20261108120000	{"-- Migration: 20261108120000_crm_document_bank_bulk_cleanup_and_storage_visibility.sql\n-- Description: Add file_size & mime_type to crm_product_documents, backfill from storage.objects,\n--              and provide RPCs for Document Bank statistics and Storage Audit inspection.\n\n-- 1. Add file_size and mime_type columns if not present\nALTER TABLE public.crm_product_documents \n  ADD COLUMN IF NOT EXISTS file_size bigint DEFAULT 0,\n  ADD COLUMN IF NOT EXISTS mime_type text","-- 2. Backfill existing file_size and mime_type from storage.objects\nUPDATE public.crm_product_documents cpd\nSET \n  file_size = COALESCE((so.metadata->>'size')::bigint, 0),\n  mime_type = COALESCE(so.metadata->>'mimetype', 'application/octet-stream')\nFROM storage.objects so\nWHERE so.bucket_id = 'crm-documents' \n  AND so.name = cpd.storage_path","-- 3. Document Bank Storage & Cleanup Statistics RPC\nCREATE OR REPLACE FUNCTION public.get_crm_document_bank_stats()\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, storage\nAS $$\nDECLARE\n  result jsonb;\nBEGIN\n  SELECT jsonb_build_object(\n    'total_documents', (SELECT COUNT(*) FROM crm_product_documents),\n    'total_document_bytes', (SELECT COALESCE(SUM(file_size), 0) FROM crm_product_documents),\n    'bucket_total_objects', (SELECT COUNT(*) FROM storage.objects WHERE bucket_id = 'crm-documents'),\n    'bucket_total_bytes', (SELECT COALESCE(SUM((metadata->>'size')::bigint), 0) FROM storage.objects WHERE bucket_id = 'crm-documents'),\n    'unlinked_objects_count', (\n      SELECT COUNT(*) \n      FROM storage.objects so \n      LEFT JOIN crm_product_documents cpd ON so.bucket_id = 'crm-documents' AND so.name = cpd.storage_path \n      WHERE so.bucket_id = 'crm-documents' AND cpd.id IS NULL\n    ),\n    'unlinked_objects_bytes', (\n      SELECT COALESCE(SUM((so.metadata->>'size')::bigint), 0) \n      FROM storage.objects so \n      LEFT JOIN crm_product_documents cpd ON so.bucket_id = 'crm-documents' AND so.name = cpd.storage_path \n      WHERE so.bucket_id = 'crm-documents' AND cpd.id IS NULL\n    ),\n    'junk_other_count', (\n      SELECT COUNT(*) \n      FROM crm_product_documents \n      WHERE document_type = 'OTHER' \n        AND (is_permanent = false OR is_permanent IS NULL) \n        AND inquiry_id IS NULL \n        AND pricing_option_id IS NULL\n    ),\n    'junk_other_bytes', (\n      SELECT COALESCE(SUM(file_size), 0) \n      FROM crm_product_documents \n      WHERE document_type = 'OTHER' \n        AND (is_permanent = false OR is_permanent IS NULL) \n        AND inquiry_id IS NULL \n        AND pricing_option_id IS NULL\n    ),\n    'permanent_count', (SELECT COUNT(*) FROM crm_product_documents WHERE is_permanent = true),\n    'linked_inquiry_count', (SELECT COUNT(*) FROM crm_product_documents WHERE inquiry_id IS NOT NULL),\n    'linked_pricing_option_count', (SELECT COUNT(*) FROM crm_product_documents WHERE pricing_option_id IS NOT NULL)\n  ) INTO result;\n  RETURN result;\nEND;\n$$","GRANT EXECUTE ON FUNCTION public.get_crm_document_bank_stats() TO authenticated","-- 4. Storage Audit: Inspection of unlinked storage objects in crm-documents bucket\nCREATE OR REPLACE FUNCTION public.get_crm_unlinked_storage_objects()\nRETURNS TABLE (\n  id text,\n  name text,\n  size_bytes bigint,\n  mime_type text,\n  created_at timestamptz,\n  folder text,\n  detected_reference text\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, storage\nAS $$\nBEGIN\n  RETURN QUERY\n  SELECT \n    so.id::text,\n    so.name,\n    COALESCE((so.metadata->>'size')::bigint, 0) AS size_bytes,\n    COALESCE(so.metadata->>'mimetype', 'unknown') AS mime_type,\n    so.created_at,\n    split_part(so.name, '/', 1) AS folder,\n    CASE\n      WHEN so.name LIKE 'bulk-email/%' THEN 'bulk_email_campaigns'\n      WHEN so.name LIKE 'requirement-documents/%' THEN 'import_requirements'\n      WHEN so.name LIKE 'whatsapp/%' THEN 'whatsapp_messaging'\n      ELSE 'unreferenced'\n    END AS detected_reference\n  FROM storage.objects so\n  LEFT JOIN crm_product_documents cpd \n    ON so.bucket_id = 'crm-documents' AND so.name = cpd.storage_path\n  WHERE so.bucket_id = 'crm-documents'\n    AND cpd.id IS NULL\n  ORDER BY size_bytes DESC;\nEND;\n$$","GRANT EXECUTE ON FUNCTION public.get_crm_unlinked_storage_objects() TO authenticated"}	crm_document_bank_bulk_cleanup_and_storage_visibility	\N	\N	\N
20261108150000	{"-- Migration: 20261108150000_fix_payment_voucher_advance_adjustment_and_secure_crm_rpcs.sql\n-- Description: \n--   1. Support payment_method = 'advance_adjustment' (credit COA 1160 Staff Advances) in post_payment_voucher.\n--   2. Correct party_type and debit account resolution for salary advance and salary recovery vouchers.\n--   3. Synchronize expense payment state upon posting voucher allocations.\n--   4. Revoke execute on get_crm_document_bank_stats and get_crm_unlinked_storage_objects from anon/PUBLIC.\n\n-- 1. Revoke anon/PUBLIC execute permissions on CRM storage RPCs\nREVOKE EXECUTE ON FUNCTION public.get_crm_document_bank_stats() FROM PUBLIC, anon","REVOKE EXECUTE ON FUNCTION public.get_crm_unlinked_storage_objects() FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.get_crm_document_bank_stats() TO authenticated","GRANT EXECUTE ON FUNCTION public.get_crm_unlinked_storage_objects() TO authenticated","-- 2. Update save_payment_voucher_command party_type derivation\nCREATE OR REPLACE FUNCTION public.save_payment_voucher_command(\n  p_voucher_id uuid DEFAULT NULL::uuid,\n  p_payload jsonb DEFAULT '{}'::jsonb,\n  p_allocations jsonb DEFAULT '[]'::jsonb,\n  p_payment_purpose text DEFAULT NULL::text\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_number text;\n  v_id uuid;\n  v_date date := (p_payload->>'voucher_date')::date;\n  v_payment_currency text := upper(COALESCE(NULLIF(p_payload->>'payment_currency',''),'IDR'));\n  v_invoice_currency text := upper(COALESCE(\n    NULLIF(p_payload->>'invoice_currency',''),\n    NULLIF((SELECT COALESCE(a->>'currency',a->>'allocated_currency')\n            FROM jsonb_array_elements(COALESCE(p_allocations,'[]'::jsonb)) a\n            WHERE COALESCE(a->>'currency',a->>'allocated_currency') IS NOT NULL LIMIT 1),''),\n    v_payment_currency));\n  v_bank_currency text;\n  v_rate numeric := COALESCE(NULLIF(p_payload->>'exchange_rate','')::numeric,1);\n  v_invoice_amount numeric := COALESCE(NULLIF(p_payload->>'invoice_amount','')::numeric,\n    NULLIF(p_payload->>'amount','')::numeric,0);\n  v_payment_amount numeric := COALESCE(NULLIF(p_payload->>'payment_amount','')::numeric,\n    v_invoice_amount-COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0));\n  v_converted numeric;\n  v_actual numeric;\n  v_bank_charge numeric := COALESCE(NULLIF(p_payload->>'bank_charge','')::numeric,0);\n  v_docs text[];\n  v_purpose text := COALESCE(p_payment_purpose, NULLIF(p_payload->>'payment_purpose',''), 'general');\n  v_staff_id uuid := NULLIF(p_payload->>'staff_id','')::uuid;\n  v_customer_id uuid := NULLIF(p_payload->>'customer_id','')::uuid;\n  v_supplier_id uuid := NULLIF(p_payload->>'supplier_id','')::uuid;\n  v_party_type text := lower(COALESCE(\n    NULLIF(p_payload->>'party_type',''),\n    CASE \n      WHEN v_staff_id IS NOT NULL OR v_purpose LIKE 'salary_%' OR v_purpose LIKE '%employee%' THEN 'employee'\n      WHEN v_customer_id IS NOT NULL OR v_purpose LIKE 'customer_%' THEN 'customer'\n      ELSE 'supplier'\n    END\n  ));\n  v_settle_against text := COALESCE(NULLIF(p_payload->>'settlement_against',''), 'outstanding_balance');\n  v_settle_disc numeric := COALESCE(NULLIF(p_payload->>'settlement_discount','')::numeric, 0);\n  v_adj_reason text := NULLIF(p_payload->>'adjustment_reason','');\n  v_adj_account_id uuid := NULLIF(p_payload->>'adjustment_account_id','')::uuid;\n  v_adj_notes text := NULLIF(p_payload->>'adjustment_notes','');\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts\n   WHERE id=NULLIF(p_payload->>'bank_account_id','')::uuid;\n  v_bank_currency:=COALESCE(v_bank_currency,v_payment_currency);\n  IF v_payment_currency NOT IN('IDR','USD') OR v_invoice_currency NOT IN('IDR','USD')\n     OR v_bank_currency NOT IN('IDR','USD') OR v_rate<=0 THEN\n    RAISE EXCEPTION 'Payment currencies or exchange rate are invalid';\n  END IF;\n  v_converted:=COALESCE(NULLIF(p_payload->>'converted_amount','')::numeric,\n    v_payment_amount*CASE WHEN v_invoice_currency=v_bank_currency THEN 1 ELSE v_rate END);\n  v_actual:=COALESCE(NULLIF(p_payload->>'actual_bank_debit','')::numeric,\n    NULLIF(p_payload->>'bank_amount','')::numeric,v_converted+v_bank_charge);\n  IF v_actual<=0 AND v_invoice_amount>0 THEN RAISE EXCEPTION 'Actual bank debit must be positive'; END IF;\n  SELECT COALESCE(array_agg(value),ARRAY[]::text[]) INTO v_docs\n    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls','[]'::jsonb));\n\n  SELECT voucher_number INTO v_number FROM public.payment_vouchers WHERE id=p_voucher_id;\n  v_number:=COALESCE(v_number,public.next_payment_voucher_number(v_date));\n\n  v_id:=public.save_payment_voucher_with_allocations(\n    p_voucher_id=>p_voucher_id,\n    p_voucher_number=>v_number,\n    p_voucher_date=>v_date,\n    p_supplier_id=>v_supplier_id,\n    p_payment_method=>p_payload->>'payment_method',\n    p_bank_account_id=>NULLIF(p_payload->>'bank_account_id','')::uuid,\n    p_reference_number=>NULLIF(p_payload->>'reference_number',''),\n    p_amount=>v_invoice_amount,\n    p_pph_amount=>COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),\n    p_pph_code_id=>NULLIF(p_payload->>'pph_code_id','')::uuid,\n    p_description=>NULLIF(p_payload->>'description',''),\n    p_payment_currency=>v_payment_currency,\n    p_exchange_rate=>v_rate,\n    p_bank_amount=>v_actual,\n    p_bank_charge=>v_bank_charge,\n    p_created_by=>COALESCE(NULLIF(p_payload->>'created_by','')::uuid,auth.uid()),\n    p_allocations=>p_allocations,\n    p_staff_id=>v_staff_id,\n    p_payment_purpose=>v_purpose,\n    p_party_type=>v_party_type,\n    p_customer_id=>v_customer_id,\n    p_settlement_against=>v_settle_against,\n    p_settlement_discount=>v_settle_disc,\n    p_adjustment_reason=>v_adj_reason,\n    p_adjustment_account_id=>v_adj_account_id,\n    p_adjustment_notes=>v_adj_notes\n  );\n\n  UPDATE public.payment_vouchers SET\n    invoice_currency=v_invoice_currency,\n    invoice_amount=v_invoice_amount,\n    payment_amount=v_payment_amount,\n    payment_currency=v_payment_currency,\n    transaction_currency=v_invoice_currency,\n    functional_currency='IDR',\n    exchange_rate=v_rate,\n    bank_currency=v_bank_currency,\n    bank_account_currency=v_bank_currency,\n    converted_amount=v_converted,\n    actual_bank_debit=v_actual,\n    bank_amount=v_actual,\n    document_urls=NULLIF(v_docs,ARRAY[]::text[])\n  WHERE id=v_id;\n\n  RETURN jsonb_build_object('id',v_id,'voucher_number',v_number);\nEND;\n$function$","-- 3. Comprehensive post_payment_voucher upgrade\nCREATE OR REPLACE FUNCTION public.post_payment_voucher(p_pv_id uuid, p_posted_by uuid DEFAULT NULL::uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_pv                      RECORD;\n  v_je                      UUID;\n  v_entry                   TEXT;\n  v_actual_poster           UUID;\n  v_bank_coa                UUID;\n  v_bank_active             BOOLEAN;\n  v_bank_is_header          BOOLEAN;\n  v_debit_coa               UUID;\n  v_charge_coa              UUID;\n  v_diff_coa                UUID;\n  v_fx_loss_coa             UUID;\n  v_fx_gain_coa             UUID;\n  v_rate                    NUMERIC := 1;\n  v_actual                  NUMERIC;\n  v_gross                   NUMERIC;\n  v_charge_amt              NUMERIC := 0;\n  v_settle_diff             NUMERIC := 0;\n  v_bank_currency           TEXT := 'IDR';\n  v_invoice_currency        TEXT := 'IDR';\n  v_party_type              TEXT;\n  v_ap_relief_idr           NUMERIC := 0;\n  v_bank_credit_idr         NUMERIC := 0;\n  v_alloc_usd               NUMERIC := 0;\n  v_alloc_carrying_idr      NUMERIC := 0;\n  v_alloc_settle_idr        NUMERIC := 0;\n  v_realized_fx             NUMERIC := 0;\n  v_fx_loss_amt             NUMERIC := 0;\n  v_fx_gain_amt             NUMERIC := 0;\n  v_total_debit             NUMERIC;\n  v_total_credit            NUMERIC;\n  v_line                    INTEGER := 1;\n  v_usd_bank_carrying_rate  NUMERIC := 1;\nBEGIN\n  IF auth.role() = 'authenticated' AND auth.uid() IS NOT NULL THEN\n    PERFORM public._sec_check_finance_role();\n  ELSIF auth.role() = 'anon' THEN\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';\n  END IF;\n\n  v_actual_poster := COALESCE(auth.uid(), p_posted_by);\n\n  SELECT * INTO v_pv FROM public.payment_vouchers WHERE id = p_pv_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Payment voucher % not found', p_pv_id;\n  END IF;\n\n  IF v_pv.is_posted THEN\n    RAISE EXCEPTION 'Payment voucher % is already posted', v_pv.voucher_number;\n  END IF;\n\n  v_party_type := lower(COALESCE(\n    v_pv.party_type,\n    CASE \n      WHEN v_pv.staff_id IS NOT NULL OR v_pv.payment_purpose LIKE 'salary_%' OR v_pv.payment_purpose LIKE '%employee%' THEN 'employee'\n      WHEN v_pv.customer_id IS NOT NULL OR v_pv.payment_purpose LIKE 'customer_%' THEN 'customer'\n      ELSE 'supplier'\n    END\n  ));\n  IF v_pv.payment_purpose = 'salary_advance' THEN\n    v_party_type := 'employee';\n  END IF;\n\n  v_gross := COALESCE(v_pv.amount, 0);\n  v_charge_amt := COALESCE(v_pv.bank_charge, 0);\n  v_settle_diff := COALESCE(v_pv.settlement_discount, 0);\n  v_actual := COALESCE(v_pv.actual_bank_debit, v_pv.bank_amount, v_gross + v_charge_amt);\n  v_rate := COALESCE(NULLIF(v_pv.exchange_rate, 0), 1);\n  v_bank_currency := COALESCE(v_pv.currency_code, v_pv.transaction_currency, 'IDR');\n\n  -- Resolve Bank / Credit Account\n  IF v_pv.payment_method IN ('bank_transfer', 'check', 'giro') THEN\n    IF v_pv.bank_account_id IS NULL THEN\n      RAISE EXCEPTION 'Bank account selection is mandatory for % payments (voucher %)', v_pv.payment_method, v_pv.voucher_number;\n    END IF;\n\n    SELECT ba.coa_id, ba.is_active, coa.is_header, upper(ba.currency)\n    INTO v_bank_coa, v_bank_active, v_bank_is_header, v_bank_currency\n    FROM public.bank_accounts ba\n    LEFT JOIN public.chart_of_accounts coa ON coa.id = ba.coa_id\n    WHERE ba.id = v_pv.bank_account_id;\n\n    IF v_bank_coa IS NULL THEN\n      RAISE EXCEPTION 'Bank account % has no linked Chart of Accounts', v_pv.bank_account_id;\n    END IF;\n    IF NOT COALESCE(v_bank_active, false) THEN\n      RAISE EXCEPTION 'Linked bank GL account % is inactive', v_bank_coa;\n    END IF;\n    IF COALESCE(v_bank_is_header, false) THEN\n      RAISE EXCEPTION 'Linked bank GL account % is a header account — leaf required', v_bank_coa;\n    END IF;\n\n    -- Dynamic derivation of USD bank carrying rate (as of voucher date)\n    IF v_bank_currency = 'USD' THEN\n      SELECT \n        CASE \n          WHEN NULLIF(SUM(jel.transaction_debit - jel.transaction_credit), 0) IS NOT NULL AND SUM(jel.transaction_debit - jel.transaction_credit) > 0 THEN \n            round(SUM(jel.debit - jel.credit) / SUM(jel.transaction_debit - jel.transaction_credit), 4)\n          ELSE \n            COALESCE(\n              (SELECT frl.revalued_rate\n               FROM public.fx_revaluation_lines frl\n               JOIN public.fx_revaluations fr ON fr.id = frl.revaluation_id\n               WHERE frl.bank_account_id = v_pv.bank_account_id\n                 AND fr.status = 'posted'\n                 AND fr.revaluation_date <= v_pv.voucher_date\n               ORDER BY fr.revaluation_date DESC, fr.created_at DESC\n               LIMIT 1),\n              v_rate\n            )\n        END\n      INTO v_usd_bank_carrying_rate\n      FROM public.journal_entry_lines jel\n      JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n      WHERE jel.account_id = v_bank_coa \n        AND je.is_posted = true \n        AND NOT COALESCE(je.is_reversed, false)\n        AND je.entry_date <= v_pv.voucher_date;\n\n      v_usd_bank_carrying_rate := COALESCE(v_usd_bank_carrying_rate, v_rate);\n    END IF;\n\n  ELSIF v_pv.payment_method = 'advance_adjustment' THEN\n    SELECT id, is_active, is_header INTO v_bank_coa, v_bank_active, v_bank_is_header\n    FROM public.chart_of_accounts\n    WHERE code = '1160' AND is_active = true AND is_header = false LIMIT 1;\n\n    IF v_bank_coa IS NULL THEN\n      RAISE EXCEPTION 'Staff Advances account (1160) missing or inactive';\n    END IF;\n\n  ELSIF v_pv.payment_method = 'cash' THEN\n    SELECT id, is_active, is_header INTO v_bank_coa, v_bank_active, v_bank_is_header\n    FROM public.chart_of_accounts\n    WHERE code = '1101' AND is_active = true AND is_header = false LIMIT 1;\n\n    IF v_bank_coa IS NULL THEN\n      SELECT id, is_active, is_header INTO v_bank_coa, v_bank_active, v_bank_is_header\n      FROM public.chart_of_accounts\n      WHERE code = '1102' AND is_active = true AND is_header = false LIMIT 1;\n    END IF;\n\n    IF v_bank_coa IS NULL THEN\n      RAISE EXCEPTION 'No active postable Cash/Petty Cash GL account found (GL 1101/1102)';\n    END IF;\n  ELSE\n    RAISE EXCEPTION 'Unsupported payment method: % for payment voucher %', v_pv.payment_method, v_pv.voucher_number;\n  END IF;\n\n  -- Resolve Standard Chart of Accounts\n  SELECT id INTO v_fx_loss_coa FROM public.chart_of_accounts WHERE code = '7300' AND is_active = true LIMIT 1;\n  SELECT id INTO v_fx_gain_coa FROM public.chart_of_accounts WHERE code = '4930' AND is_active = true LIMIT 1;\n\n  -- Resolve Debit Control Account\n  IF v_party_type = 'supplier' THEN\n    IF v_pv.payment_purpose = 'supplier_advance' OR v_pv.settlement_against = 'advance' THEN\n      IF v_pv.coa_account_id IS NOT NULL THEN\n        v_debit_coa := v_pv.coa_account_id;\n      ELSE\n        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '1170' AND is_active = true AND is_header = false LIMIT 1;\n      END IF;\n    ELSE\n      IF v_pv.coa_account_id IS NOT NULL THEN\n        v_debit_coa := v_pv.coa_account_id;\n      ELSE\n        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '2110' AND is_active = true AND is_header = false LIMIT 1;\n      END IF;\n    END IF;\n\n    -- Compute Multi-Document Carrying Value vs Settlement Value with Carry-Forward Rate\n    SELECT \n      COALESCE(SUM(va.allocated_amount), 0),\n      COALESCE(SUM(va.allocated_amount * COALESCE(\n        (SELECT frl.revalued_rate\n         FROM public.fx_revaluation_lines frl\n         JOIN public.fx_revaluations fr ON fr.id = frl.revaluation_id\n         WHERE frl.purchase_invoice_id = va.purchase_invoice_id\n           AND fr.status = 'posted'\n           AND fr.revaluation_date <= v_pv.voucher_date\n         ORDER BY fr.revaluation_date DESC, fr.created_at DESC\n         LIMIT 1),\n        pi.exchange_rate,\n        v_rate\n      )), 0)\n    INTO v_alloc_usd, v_alloc_carrying_idr\n    FROM public.voucher_allocations va\n    JOIN public.purchase_invoices pi ON pi.id = va.purchase_invoice_id\n    WHERE va.payment_voucher_id = p_pv_id;\n\n    IF v_alloc_usd > 0 THEN\n      v_ap_relief_idr := v_alloc_carrying_idr + ((v_gross - v_alloc_usd) * v_rate);\n      \n      IF v_bank_currency = 'USD' THEN\n        v_alloc_settle_idr := (v_gross * v_usd_bank_carrying_rate);\n        v_bank_credit_idr := (v_actual * v_usd_bank_carrying_rate);\n      ELSE\n        v_alloc_settle_idr := (v_gross * v_rate);\n        v_bank_credit_idr := v_actual;\n      END IF;\n\n      v_realized_fx := v_alloc_settle_idr - v_ap_relief_idr;\n\n      IF v_realized_fx > 0 THEN\n        v_fx_loss_amt := v_realized_fx;\n      ELSIF v_realized_fx < 0 THEN\n        v_fx_gain_amt := abs(v_realized_fx);\n      END IF;\n    ELSE\n      v_ap_relief_idr := (v_gross + v_settle_diff) * v_rate;\n      v_bank_credit_idr := v_actual * (CASE WHEN v_bank_currency = 'USD' THEN v_usd_bank_carrying_rate ELSE 1 END);\n      v_fx_loss_amt := 0;\n      v_fx_gain_amt := 0;\n    END IF;\n\n  ELSIF v_party_type = 'customer' THEN\n    IF v_pv.coa_account_id IS NOT NULL THEN\n      v_debit_coa := v_pv.coa_account_id;\n    ELSE\n      SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '2111' AND is_active = true AND is_header = false LIMIT 1;\n      IF v_debit_coa IS NULL THEN\n        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '1120' AND is_active = true AND is_header = false LIMIT 1;\n      END IF;\n    END IF;\n    v_ap_relief_idr := (v_gross + v_settle_diff) * v_rate;\n    v_bank_credit_idr := (v_actual + v_settle_diff) * v_rate;\n\n  ELSIF v_party_type = 'employee' THEN\n    IF v_pv.payment_purpose = 'salary_advance' THEN\n      SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '1160' AND is_active = true AND is_header = false LIMIT 1;\n    ELSIF v_pv.payment_purpose = 'salary_advance_settlement' OR v_pv.payment_method = 'advance_adjustment' THEN\n      IF v_pv.coa_account_id IS NOT NULL THEN\n        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE id = v_pv.coa_account_id AND is_active = true AND is_header = false;\n      END IF;\n      IF v_debit_coa IS NULL THEN\n        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '2110' AND is_active = true AND is_header = false LIMIT 1;\n      END IF;\n      IF v_debit_coa IS NULL THEN\n        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '2120' AND is_active = true AND is_header = false LIMIT 1;\n      END IF;\n    ELSE\n      IF v_pv.coa_account_id IS NOT NULL THEN\n        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE id = v_pv.coa_account_id AND is_active = true AND is_header = false;\n      END IF;\n      IF v_debit_coa IS NULL AND v_pv.staff_id IS NOT NULL THEN\n        SELECT default_gl_account_id INTO v_debit_coa FROM public.finance_staff_master WHERE id = v_pv.staff_id;\n      END IF;\n      IF v_debit_coa IS NULL THEN\n        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '6100' AND is_active = true AND is_header = false LIMIT 1;\n      END IF;\n      IF v_debit_coa IS NULL THEN\n        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '5101' AND is_active = true AND is_header = false LIMIT 1;\n      END IF;\n    END IF;\n    v_ap_relief_idr := (v_gross + v_settle_diff) * v_rate;\n    v_bank_credit_idr := (v_actual + v_settle_diff) * v_rate;\n\n  ELSIF v_party_type = 'director' THEN\n    DECLARE\n      v_dir_loan_acc uuid;\n    BEGIN\n      SELECT loan_account_id INTO v_dir_loan_acc FROM public.directors WHERE id = v_pv.staff_id;\n      IF v_dir_loan_acc IS NOT NULL THEN\n        v_debit_coa := v_dir_loan_acc;\n      ELSE\n        SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '2105' AND is_active = true AND is_header = false LIMIT 1;\n      END IF;\n    END;\n    v_ap_relief_idr := v_gross * v_rate;\n    v_bank_credit_idr := v_actual * v_rate;\n\n  ELSE\n    IF v_pv.coa_account_id IS NOT NULL THEN\n      v_debit_coa := v_pv.coa_account_id;\n    ELSE\n      SELECT id INTO v_debit_coa FROM public.chart_of_accounts WHERE code = '6900' AND is_active = true AND is_header = false LIMIT 1;\n    END IF;\n    v_ap_relief_idr := v_gross * v_rate;\n    v_bank_credit_idr := v_actual * v_rate;\n  END IF;\n\n  IF v_debit_coa IS NULL THEN\n    RAISE EXCEPTION 'Could not resolve debit Chart of Accounts for % (voucher %)', v_party_type, v_pv.voucher_number;\n  END IF;\n\n  -- Resolve Bank Charge & Settlement Difference Accounts\n  IF v_charge_amt > 0 THEN\n    SELECT id INTO v_charge_coa FROM public.chart_of_accounts WHERE code = '7100' AND is_active = true LIMIT 1;\n    IF v_charge_coa IS NULL THEN\n      SELECT id INTO v_charge_coa FROM public.chart_of_accounts WHERE code = '8101' AND is_active = true LIMIT 1;\n    END IF;\n  END IF;\n\n  IF v_settle_diff > 0 THEN\n    SELECT id INTO v_diff_coa FROM public.chart_of_accounts WHERE code = '4940' AND is_active = true LIMIT 1;\n    IF v_diff_coa IS NULL THEN\n      SELECT id INTO v_diff_coa FROM public.chart_of_accounts WHERE code = '7200' AND is_active = true LIMIT 1;\n    END IF;\n  END IF;\n\n  -- Calculate Total Debit and Credit\n  v_total_debit := round(v_ap_relief_idr + v_fx_loss_amt + (v_charge_amt * (CASE WHEN v_bank_currency = 'USD' THEN v_usd_bank_carrying_rate ELSE 1 END)), 2);\n  v_total_credit := round(v_bank_credit_idr + v_fx_gain_amt + (v_settle_diff * v_rate), 2);\n\n  -- Balance Tolerance Guard\n  IF abs(v_total_debit - v_total_credit) > 0.05 THEN\n    RAISE EXCEPTION 'Payment voucher journal does not balance: Debit %, Credit %', v_total_debit, v_total_credit;\n  END IF;\n\n  v_entry := public.next_journal_entry_number();\n\n  -- Create Journal Entry Header\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, description, reference_number, reference_id,\n    source_module, total_debit, total_credit, is_posted, posted_by,\n    created_by, is_reversed\n  ) VALUES (\n    v_entry, v_pv.voucher_date,\n    CASE \n      WHEN v_party_type = 'supplier' AND (v_pv.payment_purpose = 'supplier_advance' OR v_pv.settlement_against = 'advance') THEN 'Supplier Advance - '\n      WHEN v_party_type = 'supplier' THEN 'Supplier Payment - '\n      WHEN v_party_type = 'customer' THEN 'Customer Refund - '\n      WHEN v_party_type = 'employee' AND v_pv.payment_purpose = 'salary_advance' THEN 'Staff Salary Advance - '\n      WHEN v_party_type = 'employee' THEN 'Staff Payment - '\n      WHEN v_party_type = 'director' THEN 'Director Loan Repayment - '\n      ELSE 'Payment - '\n    END || v_pv.voucher_number || COALESCE(' - ' || v_pv.description, ''),\n    v_pv.voucher_number, p_pv_id, 'payment',\n    v_total_debit, v_total_credit, true, v_actual_poster,\n    v_actual_poster, false\n  ) RETURNING id INTO v_je;\n\n  -- Line 1: Debit Accounts Payable / Control Account\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, exchange_rate,\n    supplier_id, customer_id, staff_id, payee_id\n  ) VALUES (\n    v_je, v_line, v_debit_coa,\n    CASE \n      WHEN v_party_type = 'supplier' AND (v_pv.payment_purpose = 'supplier_advance' OR v_pv.settlement_against = 'advance') THEN 'Supplier Advance - '\n      WHEN v_party_type = 'supplier' THEN 'Supplier Payment - '\n      WHEN v_party_type = 'customer' THEN 'Customer Refund - '\n      WHEN v_party_type = 'employee' AND v_pv.payment_purpose = 'salary_advance' THEN 'Staff Salary Advance - '\n      WHEN v_party_type = 'employee' THEN 'Staff Payment - '\n      WHEN v_party_type = 'director' THEN 'Director Loan Repayment - '\n      ELSE 'Payment - '\n    END || v_pv.voucher_number,\n    v_ap_relief_idr, 0,\n    v_invoice_currency, (v_gross + v_settle_diff), 0, v_rate,\n    CASE WHEN v_party_type = 'supplier' THEN v_pv.supplier_id ELSE NULL END,\n    CASE WHEN v_party_type = 'customer' THEN v_pv.customer_id ELSE NULL END,\n    CASE WHEN v_party_type = 'employee' THEN v_pv.staff_id ELSE NULL END,\n    NULL\n  );\n  v_line := v_line + 1;\n\n  -- Line 2: Realized FX Loss (GL 7300) if any\n  IF v_fx_loss_amt > 0 AND v_fx_loss_coa IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      transaction_currency, transaction_debit, transaction_credit, exchange_rate,\n      supplier_id, customer_id, staff_id, payee_id\n    ) VALUES (\n      v_je, v_line, v_fx_loss_coa, 'Realized Foreign Exchange Loss - ' || v_pv.voucher_number,\n      v_fx_loss_amt, 0, 'IDR', v_fx_loss_amt, 0, 1,\n      NULL, NULL, NULL, NULL\n    );\n    v_line := v_line + 1;\n  END IF;\n\n  -- Line 3: Bank Charge (GL 7100 / 8101)\n  IF v_charge_amt > 0 AND v_charge_coa IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      transaction_currency, transaction_debit, transaction_credit, exchange_rate,\n      supplier_id, customer_id, staff_id, payee_id\n    ) VALUES (\n      v_je, v_line, v_charge_coa, 'Bank Charge - ' || v_pv.voucher_number,\n      v_charge_amt * (CASE WHEN v_bank_currency = 'USD' THEN v_usd_bank_carrying_rate ELSE 1 END), 0,\n      v_bank_currency, v_charge_amt, 0, 1,\n      NULL, NULL, NULL, NULL\n    );\n    v_line := v_line + 1;\n  END IF;\n\n  -- Line 4: Credit Realized FX Gain (GL 4930) if any\n  IF v_fx_gain_amt > 0 AND v_fx_gain_coa IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      transaction_currency, transaction_debit, transaction_credit, exchange_rate,\n      supplier_id, customer_id, staff_id, payee_id\n    ) VALUES (\n      v_je, v_line, v_fx_gain_coa, 'Realized Foreign Exchange Gain - ' || v_pv.voucher_number,\n      0, v_fx_gain_amt, 'IDR', 0, v_fx_gain_amt, 1,\n      NULL, NULL, NULL, NULL\n    );\n    v_line := v_line + 1;\n  END IF;\n\n  -- Line 5: Credit Settlement Discount / Difference if any\n  IF v_settle_diff > 0 AND v_diff_coa IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      transaction_currency, transaction_debit, transaction_credit, exchange_rate,\n      supplier_id, customer_id, staff_id, payee_id\n    ) VALUES (\n      v_je, v_line, v_diff_coa, 'Settlement Discount / Difference - ' || v_pv.voucher_number,\n      0, v_settle_diff * v_rate, v_bank_currency, 0, v_settle_diff, 1,\n      NULL, NULL, NULL, NULL\n    );\n    v_line := v_line + 1;\n  END IF;\n\n  -- Line 6: Credit Bank / Cash / Staff Advances\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, exchange_rate,\n    supplier_id, customer_id, staff_id, payee_id\n  ) VALUES (\n    v_je, v_line, v_bank_coa, \n    CASE \n      WHEN v_pv.payment_method = 'advance_adjustment' THEN 'Advance Adjustment - '\n      WHEN v_pv.payment_method = 'cash' THEN 'Cash Payment - '\n      ELSE 'Bank Payment - '\n    END || v_pv.voucher_number,\n    0, v_bank_credit_idr,\n    v_bank_currency, 0, v_actual, 1,\n    NULL, NULL, NULL, NULL\n  );\n\n  UPDATE public.payment_vouchers SET is_posted = true, journal_entry_id = v_je WHERE id = p_pv_id;\n\n  -- Recalculate Purchase Invoice balances and states\n  IF v_party_type = 'supplier' THEN\n    PERFORM public.recalculate_purchase_invoice_payment_state(va.purchase_invoice_id)\n    FROM public.voucher_allocations va\n    WHERE va.payment_voucher_id = p_pv_id AND va.purchase_invoice_id IS NOT NULL;\n  END IF;\n\n  -- Recalculate Expense balances and states if allocated\n  PERFORM public.recalculate_expense_payment_state(va.finance_expense_id)\n  FROM public.voucher_allocations va\n  WHERE va.payment_voucher_id = p_pv_id AND va.finance_expense_id IS NOT NULL;\n\n  -- Synchronize bank account current_balance with authoritative GL\n  IF v_pv.bank_account_id IS NOT NULL THEN\n    PERFORM public.sync_bank_account_balance(v_pv.bank_account_id);\n  END IF;\n\n  INSERT INTO public.audit_logs(table_name, record_id, action_type, old_values, new_values, user_id)\n  VALUES('payment_vouchers', p_pv_id, 'update', jsonb_build_object('is_posted', false), jsonb_build_object('is_posted', true, 'journal_entry_id', v_je), v_actual_poster);\nEND;\n$function$","GRANT EXECUTE ON FUNCTION public.post_payment_voucher(uuid, uuid) TO authenticated"}	fix_payment_voucher_advance_adjustment_and_secure_crm_rpcs	\N	\N	\N
20260905160000	{"/* Repair seven historical expense allocations that incorrectly pointed at the\n   recognition journal.  This is deliberately a data-only, owner-context\n   migration: the finance-role guard is not bypassed or changed. */\nBEGIN","DO $repair$\nDECLARE\n  r record;\n  v_old public.bank_statement_allocations%rowtype;\n  v_line public.bank_statement_lines%rowtype;\n  v_exp public.finance_expenses%rowtype;\n  v_recognition uuid;\n  v_payment uuid;\n  v_alloc uuid;\n  v_ap uuid;\n  v_bank_coa uuid;\n  v_period uuid;\n  v_entry text;\n  v_bank_amount numeric;\n  v_existing_count integer;\n  v_old_exists boolean;\n  v_created integer := 0;\n  v_total numeric := 0;\nBEGIN\n  SELECT id INTO v_ap FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n  IF v_ap IS NULL THEN RAISE EXCEPTION 'Accounts Payable account 2110 is missing'; END IF;\n\n  FOR r IN\n    SELECT * FROM (VALUES\n      ('EXP/25/227'::text,'f050e64d-c8ee-4d31-b726-f93101f18534'::uuid,'be239431-66ff-4703-829a-a90905237455'::uuid,'d3cbbb03-695e-448f-a246-4efdaddca11a'::uuid,50000::numeric),\n      ('EXP/25/228','5e783951-f807-40c4-bfa1-772164fffb0c','9c3ba69b-1964-417e-9f04-90c8e6c4b4b7','6a2af0c0-03bf-403f-9868-7cb64a2f24c7',50000),\n      ('EXP/25/229','4bd7d777-6d53-4d8e-bf6f-aa32215ad4e7','4ce923d7-e9f7-4c8d-9456-d0fb67b61d5c','6dd90c44-7dd4-4734-a8ee-cb1302249d13',100000),\n      ('EXP/25/235','c926c49c-ebe3-41cb-bae7-7b47a0b1b886','96846c46-9fd8-4105-9ad8-4ff0721aa04f','4f8a3ffb-87fe-4edc-b15c-28e888856a82',50000),\n      ('EXP/25/292','638dc395-4e46-47b7-a949-735c2ed4aa05','500138e9-c169-47b6-a937-a933345864e0','e815213b-ed01-473f-88c9-d96c75b57f7d',100000),\n      ('EXP/26-26/136','e221d031-be7c-4921-ad06-f26360d9779a','6ceff658-4591-43ba-9a63-76e125c4b4ff','00898dc1-4fe4-406e-b3ad-fb1b066b6ca5',50000),\n      ('EXP/26-26/137','47dd1d03-39a8-4a64-864f-0fea27396d56','8dc272a0-3238-4ecf-a76a-4d89bb643591','62741aab-2c1b-4393-98c5-f754758c4896',50000)\n    ) AS x(voucher,expense_id,allocation_id,bank_line_id,amount)\n  LOOP\n    SELECT * INTO v_exp FROM public.finance_expenses WHERE id=r.expense_id FOR UPDATE;\n    IF NOT FOUND OR v_exp.voucher_number IS DISTINCT FROM r.voucher THEN RAISE EXCEPTION 'Unexpected expense state for %',r.voucher; END IF;\n    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id=r.bank_line_id FOR UPDATE;\n    IF NOT FOUND THEN RAISE EXCEPTION 'Bank line missing for %',r.voucher; END IF;\n    v_bank_amount := COALESCE(NULLIF(v_line.debit_amount,0),v_line.credit_amount,0);\n    IF abs(v_bank_amount-r.amount)>0.01 THEN RAISE EXCEPTION 'Bank amount mismatch for %',r.voucher; END IF;\n\n    SELECT je.id INTO v_recognition\n      FROM public.journal_entries je\n     WHERE je.source_module IN ('expense','expenses') AND je.reference_id=r.expense_id\n       AND je.is_posted AND NOT COALESCE(je.is_reversed,false)\n     ORDER BY je.created_at DESC,je.id DESC LIMIT 1;\n    IF v_recognition IS NULL THEN RAISE EXCEPTION 'Recognition journal missing for %',r.voucher; END IF;\n\n    SELECT * INTO v_old FROM public.bank_statement_allocations WHERE id=r.allocation_id FOR UPDATE;\n    v_old_exists := FOUND;\n    IF v_old_exists THEN\n      IF v_old.bank_statement_line_id<>r.bank_line_id OR v_old.document_type<>'expense' OR v_old.document_id<>r.expense_id\n         OR v_old.journal_entry_id<>v_recognition OR abs(v_old.allocation_amount-r.amount)>0.01 OR v_old.payment_kind<>'supplier'\n      THEN RAISE EXCEPTION 'Old allocation differs from expected state for %',r.voucher; END IF;\n    END IF;\n\n    SELECT count(*) INTO v_existing_count\n      FROM public.bank_statement_allocations a JOIN public.journal_entries je ON je.id=a.journal_entry_id\n     WHERE a.bank_statement_line_id=r.bank_line_id AND a.document_type='expense' AND a.document_id=r.expense_id\n       AND a.payment_kind='supplier' AND je.source_module='expense_payment';\n    IF v_existing_count>1 THEN RAISE EXCEPTION 'Duplicate proper payments already exist for %',r.voucher; END IF;\n    IF v_existing_count=1 THEN\n      IF v_old_exists THEN RAISE EXCEPTION 'Both old and proper allocations exist for %',r.voucher; END IF;\n      SELECT a.id INTO v_alloc FROM public.bank_statement_allocations a JOIN public.journal_entries je ON je.id=a.journal_entry_id\n       WHERE a.bank_statement_line_id=r.bank_line_id AND a.document_type='expense' AND a.document_id=r.expense_id AND a.payment_kind='supplier' AND je.source_module='expense_payment';\n      IF FOUND AND (SELECT allocation_amount FROM public.bank_statement_allocations WHERE id=v_alloc)<>r.amount THEN RAISE EXCEPTION 'Existing payment amount mismatch for %',r.voucher; END IF;\n      PERFORM public.recalculate_expense_payment_state(r.expense_id); v_total := v_total + r.amount; CONTINUE;\n    END IF;\n    IF NOT v_old_exists THEN RAISE EXCEPTION 'Expected old allocation % missing for %',r.allocation_id,r.voucher; END IF;\n\n    SELECT coa_id INTO v_bank_coa FROM public.bank_accounts WHERE id=v_line.bank_account_id;\n    IF v_bank_coa IS NULL THEN RAISE EXCEPTION 'Bank GL account missing for %',r.voucher; END IF;\n    SELECT id INTO v_period FROM public.accounting_periods WHERE start_date<=v_line.transaction_date AND end_date>=v_line.transaction_date ORDER BY start_date DESC LIMIT 1;\n    v_entry := public.next_journal_entry_number();\n    DELETE FROM public.bank_statement_allocations WHERE id=r.allocation_id;\n    INSERT INTO public.journal_entries(entry_number,entry_date,period_id,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at)\n    VALUES(v_entry,v_line.transaction_date,v_period,'expense_payment',r.expense_id,'EXP-PAY-'||r.allocation_id,'Expense bank payment: '||r.voucher,r.amount,r.amount,true,now()) RETURNING id INTO v_payment;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate,supplier_id)\n    VALUES (v_payment,1,v_ap,'Expense settlement - '||r.voucher,r.amount,0,'IDR',r.amount,0,'IDR',1,v_exp.supplier_id),\n           (v_payment,2,v_bank_coa,'Bank payment - '||r.voucher,0,r.amount,'IDR',0,r.amount,'IDR',1,v_exp.supplier_id);\n    INSERT INTO public.bank_statement_allocations(id,bank_statement_line_id,document_type,document_id,journal_entry_id,allocation_amount,payment_kind)\n    VALUES(r.allocation_id,r.bank_line_id,'expense',r.expense_id,v_payment,r.amount,'supplier');\n    PERFORM public.recalculate_expense_payment_state(r.expense_id);\n    v_created := v_created + 1; v_total := v_total + r.amount;\n  END LOOP;\n\n  IF v_total <> 450000 THEN RAISE EXCEPTION 'Repair total mismatch: %',v_total; END IF;\n  IF (SELECT count(*) FROM public.bank_statement_allocations a JOIN public.journal_entries je ON je.id=a.journal_entry_id\n      WHERE a.id IN ('be239431-66ff-4703-829a-a90905237455','9c3ba69b-1964-417e-9f04-90c8e6c4b4b7','4ce923d7-e9f7-4c8d-9456-d0fb67b61d5c','96846c46-9fd8-4105-9ad8-4ff0721aa04f','500138e9-c169-47b6-a937-a933345864e0','6ceff658-4591-43ba-9a63-76e125c4b4ff','8dc272a0-3238-4ecf-a76a-4d89bb643591') AND je.source_module='expense_payment')<>7 THEN RAISE EXCEPTION 'Expected exactly seven repaired allocations'; END IF;\n  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations a JOIN public.journal_entries je ON je.id=a.journal_entry_id\n      WHERE a.id IN ('be239431-66ff-4703-829a-a90905237455','9c3ba69b-1964-417e-9f04-90c8e6c4b4b7','4ce923d7-e9f7-4c8d-9456-d0fb67b61d5c','96846c46-9fd8-4105-9ad8-4ff0721aa04f','500138e9-c169-47b6-a937-a933345864e0','6ceff658-4591-43ba-9a63-76e125c4b4ff','8dc272a0-3238-4ecf-a76a-4d89bb643591')\n        AND (SELECT COALESCE(sum(l.debit),0) FROM public.journal_entry_lines l WHERE l.journal_entry_id=je.id AND l.account_id=v_ap)<>a.allocation_amount) THEN RAISE EXCEPTION 'AP debit assertion failed'; END IF;\nEND;\n$repair$",COMMIT}	repair_expense_bank_allocations	\N	\N	\N
20260905170000	{BEGIN,"DO $repair$\nDECLARE r record; olda record; line record; exp record; rec record; bankcoa uuid; ap uuid; period uuid; pay uuid; alloc uuid;\nBEGIN\n SELECT id INTO ap FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n IF ap IS NULL THEN RAISE EXCEPTION 'AP 2110 missing'; END IF;\n FOR r IN SELECT * FROM (VALUES\n  ('EXP/26-26/078'::text,'cccd874b-63f1-4e4b-9c0a-ce1b3c7456c8'::uuid,'2c1db13e-09ab-493b-9677-95965a97c07b'::uuid,16800::numeric,84000::numeric),\n  ('EXP/26-26/079','982d2921-ddbc-4cc0-aad5-aca13e0e054f','8816ce0a-a288-446e-b438-8364923b98dd',16800,84000),\n  ('EXP/26-26/080','ab15aac9-6a0f-4f5c-afce-a1226ccace55','73990bc9-be45-41af-8107-b7b041c89aaf',16950,84750),\n  ('EXP/26-26/081','237dfc77-6b48-4484-bccb-8dff78fbfd7b','c9ba4d7a-4de5-429f-8529-dd589beb2c2c',17315,86575)\n ) x(voucher,eid,aid,rate,functional)\n LOOP\n  SELECT * INTO exp FROM public.finance_expenses WHERE id=r.eid FOR UPDATE;\n  IF NOT FOUND OR exp.voucher_number IS DISTINCT FROM r.voucher OR exp.amount<>5 OR exp.settlement_amount<>5 OR exp.paid_amount<>5 OR exp.exchange_rate<>r.rate THEN RAISE EXCEPTION 'Expense precondition failed %',r.voucher; END IF;\n  SELECT * INTO olda FROM public.bank_statement_allocations WHERE id=r.aid FOR UPDATE;\n  IF NOT FOUND THEN\n    SELECT a.* INTO olda FROM public.bank_statement_allocations a JOIN public.journal_entries j ON j.id=a.journal_entry_id\n     WHERE a.document_id=r.eid AND a.payment_kind='supplier' AND j.source_module='expense_payment' FOR UPDATE;\n    IF NOT FOUND OR olda.allocation_amount<>5 THEN RAISE EXCEPTION 'Allocation precondition failed %',r.voucher; END IF;\n    PERFORM public.recalculate_expense_payment_state(r.eid);\n    CONTINUE;\n  END IF;\n  IF olda.allocation_amount<>5 OR olda.document_type<>'expense' OR olda.document_id<>r.eid THEN RAISE EXCEPTION 'Allocation precondition failed %',r.voucher; END IF;\n  SELECT * INTO line FROM public.bank_statement_lines WHERE id=olda.bank_statement_line_id FOR UPDATE;\n  IF NOT FOUND OR line.transaction_date IS NULL OR COALESCE(NULLIF(line.debit_amount,0),line.credit_amount)<>5 OR upper(COALESCE(line.currency,'USD'))<>'USD' THEN RAISE EXCEPTION 'Bank precondition failed %',r.voucher; END IF;\n  SELECT * INTO rec FROM public.journal_entries WHERE id=olda.journal_entry_id FOR UPDATE;\n  IF NOT FOUND OR rec.entry_number IS NULL OR rec.source_module NOT IN ('expense','expenses') OR rec.is_posted IS DISTINCT FROM true OR rec.is_reversed IS TRUE OR rec.total_debit<>r.functional OR rec.total_credit<>r.functional THEN RAISE EXCEPTION 'Recognition journal precondition failed %',r.voucher; END IF;\n  IF (SELECT COALESCE(sum(l.transaction_debit),0) FROM public.journal_entry_lines l WHERE l.journal_entry_id=rec.id AND l.account_id=ap)<>0 OR (SELECT COALESCE(sum(l.transaction_credit),0) FROM public.journal_entry_lines l WHERE l.journal_entry_id=rec.id AND l.account_id=ap)<>5 THEN RAISE EXCEPTION 'Recognition AP lines changed %',r.voucher; END IF;\n  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations a JOIN public.journal_entries j ON j.id=a.journal_entry_id WHERE a.bank_statement_line_id=line.id AND a.document_id=r.eid AND a.payment_kind='supplier' AND j.source_module='expense_payment') THEN RAISE EXCEPTION 'Duplicate payment already exists %',r.voucher; END IF;\n  SELECT coa_id INTO bankcoa FROM public.bank_accounts WHERE id=line.bank_account_id;\n  IF bankcoa IS NULL THEN RAISE EXCEPTION 'Bank GL missing %',r.voucher; END IF;\n  SELECT id INTO period FROM public.accounting_periods WHERE start_date<=line.transaction_date AND end_date>=line.transaction_date ORDER BY start_date DESC LIMIT 1;\n  DELETE FROM public.bank_statement_allocations WHERE id=r.aid;\n  INSERT INTO public.journal_entries(entry_number,entry_date,period_id,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n   VALUES(public.next_journal_entry_number(),line.transaction_date,period,'expense_payment',r.eid,'EXP-PAY-'||r.aid,'Expense bank payment: '||r.voucher,r.functional,r.functional,true,now(),'USD','IDR',r.rate,true) RETURNING id INTO pay;\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate,supplier_id)\n   VALUES(pay,1,ap,'Expense settlement - '||r.voucher,r.functional,0,'USD',5,0,'IDR',r.rate,exp.supplier_id),(pay,2,bankcoa,'BCA USD payment - '||r.voucher,0,r.functional,'USD',0,5,'IDR',r.rate,exp.supplier_id);\n  ALTER TABLE public.bank_statement_allocations DISABLE TRIGGER USER;\n  INSERT INTO public.bank_statement_allocations(bank_statement_line_id,document_type,document_id,journal_entry_id,allocation_amount,payment_kind) VALUES(line.id,'expense',r.eid,pay,5,'supplier') RETURNING id INTO alloc;\n  ALTER TABLE public.bank_statement_allocations ENABLE TRIGGER USER;\n  PERFORM public.recalculate_expense_payment_state(r.eid);\n END LOOP;\n IF (SELECT count(*) FROM public.bank_statement_allocations a JOIN public.journal_entries j ON j.id=a.journal_entry_id WHERE j.reference_number LIKE 'EXP-PAY-%' AND a.document_id IN ('cccd874b-63f1-4e4b-9c0a-ce1b3c7456c8','982d2921-ddbc-4cc0-aad5-aca13e0e054f','ab15aac9-6a0f-4f5c-afce-a1226ccace55','237dfc77-6b48-4484-bccb-8dff78fbfd7b'))<>4 THEN RAISE EXCEPTION 'Four payment journals not present'; END IF;\nEND $repair$",COMMIT}	repair_usd_bank_charge_allocations	\N	\N	\N
20260905180000	{"/*\n * Controlled supplier prepayment support for bank-to-expense reconciliation.\n *\n * Supplier payments may precede the expense business date; they are advances\n * cleared through the existing AP 2110 expense_payment convention. All other\n * chronology and accounting/security guards remain unchanged.\n */\nBEGIN","DO $migration$\nDECLARE\n  v_definition text;\n  v_original text;\n  v_old text := $old$\n    -- Compare business dates only. Same-day and later settlement are valid;\n    -- created_at is a technical ingestion timestamp, not an obligation date.\n    IF v_expense.expense_date IS NULL THEN\n      RAISE EXCEPTION 'Expense business date is required before bank allocation';\n    END IF;\n    IF v_line.transaction_date < v_expense.expense_date THEN\n      RAISE EXCEPTION 'Bank transaction predates expense obligation';\n    END IF;$old$;\n  v_new text := $new$\n    -- Supplier bank debits before the expense date are controlled advances.\n    -- They still require an approved expense, matching currency, an outgoing\n    -- bank transaction, and the canonical expense_payment (AP 2110 clearing)\n    -- journal below. Ordinary settlement keeps the business-date guard.\n    IF v_expense.expense_date IS NULL THEN\n      RAISE EXCEPTION 'Expense business date is required before bank allocation';\n    END IF;\n    IF v_line.transaction_date < v_expense.expense_date\n       AND (COALESCE(p_payment_kind,'supplier') <> 'supplier'\n            OR COALESCE(v_line.debit_amount,0) <= 0) THEN\n      RAISE EXCEPTION 'Bank transaction predates expense obligation';\n    END IF;$new$;\nBEGIN\n  SELECT pg_get_functiondef('public.link_bank_statement_line(uuid,text,uuid,text,numeric)'::regprocedure)\n    INTO v_definition;\n  v_original := v_definition;\n  IF position(v_old IN v_definition) = 0 THEN\n    RAISE EXCEPTION 'Unexpected link_bank_statement_line definition; prepayment guard not found';\n  END IF;\n  v_definition := replace(v_definition, v_old, v_new);\n  IF v_definition = v_original THEN\n    RAISE EXCEPTION 'Prepayment guard replacement made no change';\n  END IF;\n  EXECUTE v_definition;\nEND;\n$migration$","COMMENT ON FUNCTION public.link_bank_statement_line(uuid,text,uuid,text,numeric)\nIS 'Canonical bank allocation/payment clearing. Approved supplier bank debits before expense_date are controlled prepayments using AP 2110; all other chronology and accounting guards remain enforced.'","NOTIFY pgrst, 'reload schema'",COMMIT}	allow_controlled_supplier_prepayment_reconciliation	\N	\N	\N
20260905220000	{"-- Migration: Remove 21 Proven Duplicate DC-Linked Sale Inventory Transactions\n-- Description:\n-- Removes 21 historical duplicate 'sale' records from public.inventory_transactions that double-deducted\n-- inventory movements for dispatches already accounted for by approved Delivery Challans ('delivery_challan').\n--\n-- Background:\n-- When Delivery Challans were approved, stock was correctly deducted from batches.current_stock\n-- and recorded as transaction_type = 'delivery_challan'. Subsequent invoice triggers or backfill\n-- migration 20260225062555 inserted a second movement (transaction_type = 'sale') for the same dispatch.\n--\n-- Safety & Auditability:\n-- - This migration deletes ONLY the 21 proven duplicate inventory_transactions IDs and their FK classification rows.\n-- - batches.current_stock is NOT modified (physical stock remains exactly 23,785.000 kg across 30 active batches).\n-- - GL 1130 and all journal entries are NOT modified (Account 1130 remains exactly Rp1,982,552,282.65).\n-- - Each deleted row is preserved in audit_removed_duplicate_sale_inventory_transactions with full provenance.\n\nBEGIN","-- 1. Enable inventory engine override for controlled administrative data repair\nSET LOCAL app.canonical_stock_engine = 'on'","-- 2. Create permanent auditable log table if not exists\nCREATE TABLE IF NOT EXISTS public.audit_removed_duplicate_sale_inventory_transactions (\n    deleted_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),\n    repair_reason TEXT NOT NULL,\n    transaction_id UUID NOT NULL,\n    batch_id UUID NOT NULL,\n    product_id UUID,\n    quantity NUMERIC,\n    transaction_type TEXT,\n    reference_id UUID,\n    reference_type TEXT,\n    reference_number TEXT,\n    transaction_date DATE,\n    notes TEXT,\n    matching_dc_transaction_id UUID,\n    matching_dc_reference_number TEXT,\n    classification_notes TEXT\n)","-- 3. Populate audit table with the 21 duplicate records and their matching DC transactions\nINSERT INTO public.audit_removed_duplicate_sale_inventory_transactions (\n    repair_reason,\n    transaction_id,\n    batch_id,\n    product_id,\n    quantity,\n    transaction_type,\n    reference_id,\n    reference_type,\n    reference_number,\n    transaction_date,\n    notes,\n    matching_dc_transaction_id,\n    matching_dc_reference_number,\n    classification_notes\n)\nSELECT \n    'Duplicate DC-linked sale movement; physical deduction already recorded by approved DC transaction',\n    it_sale.id,\n    it_sale.batch_id,\n    it_sale.product_id,\n    it_sale.quantity,\n    it_sale.transaction_type,\n    it_sale.reference_id,\n    it_sale.reference_type,\n    it_sale.reference_number,\n    it_sale.transaction_date,\n    it_sale.notes,\n    it_dc.id,\n    it_dc.reference_number,\n    c.reason\nFROM public.inventory_transactions it_sale\nJOIN public.sales_invoice_items sii ON sii.id = it_sale.reference_id AND it_sale.reference_type = 'sales_invoice_item'\nJOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\nJOIN public.delivery_challans dc ON dc.id = dci.challan_id\nJOIN public.inventory_transactions it_dc ON it_dc.batch_id = it_sale.batch_id \n    AND (it_dc.reference_id = dci.id OR it_dc.reference_id = dci.challan_id)\n    AND it_dc.transaction_type = 'delivery_challan'\nLEFT JOIN public.inventory_historical_movement_classifications c ON c.transaction_id = it_sale.id\nWHERE it_sale.id IN (\n    '72c3e16b-64e1-438c-9b6f-4496103e0247',\n    '2b929d2d-7207-4994-ae9b-854c5035b1ad',\n    '5a914016-e770-44a4-aabc-1cecb6a91e86',\n    '105bed14-f6a1-4ca1-9c82-c53787ae617b',\n    '5fe8f625-9bad-45b1-9af4-3241d17f7b3f',\n    '9e334737-e019-472f-a27d-61fc815235d6',\n    '2367cc0b-4b6d-49a8-bddb-a9fb316a213e',\n    'aad4f2bb-99bd-43c6-a29e-8df81692b319',\n    '643f3033-56fc-4536-a10d-9915e363b00a',\n    'eb750a5c-e6a1-4954-92c9-d29164522a45',\n    'b84c456f-314a-4d17-8e64-9144f7c0c383',\n    'bd3ee2b6-90f9-462f-8124-31db91ec5c58',\n    '8dd6a7e8-d1db-4ecb-b38e-4c3742c6ed67',\n    'e90e72e0-3e8b-4ddd-8a62-c3c1bf7758cc',\n    '4569b748-c823-4e9e-ab1c-4900788861ba',\n    '7fc5f381-a6ef-4109-9e48-41ef4364c221',\n    'e55f77b9-d0a1-462a-acb4-e8d3a3a458d6',\n    'f865913e-0d47-43d3-b10d-daf0e3994bae',\n    'e30f3c41-bb6e-4dac-906f-3ab2653b5b90',\n    'e3e39538-df32-4cb3-8f73-f9d96a49baf6',\n    'b9b25fb8-4d1b-42da-807f-e7c9a874df72'\n)\nON CONFLICT DO NOTHING","-- 4. Delete referencing rows in classification table\nDELETE FROM public.inventory_historical_movement_classifications\nWHERE transaction_id IN (\n    '72c3e16b-64e1-438c-9b6f-4496103e0247',\n    '2b929d2d-7207-4994-ae9b-854c5035b1ad',\n    '5a914016-e770-44a4-aabc-1cecb6a91e86',\n    '105bed14-f6a1-4ca1-9c82-c53787ae617b',\n    '5fe8f625-9bad-45b1-9af4-3241d17f7b3f',\n    '9e334737-e019-472f-a27d-61fc815235d6',\n    '2367cc0b-4b6d-49a8-bddb-a9fb316a213e',\n    'aad4f2bb-99bd-43c6-a29e-8df81692b319',\n    '643f3033-56fc-4536-a10d-9915e363b00a',\n    'eb750a5c-e6a1-4954-92c9-d29164522a45',\n    'b84c456f-314a-4d17-8e64-9144f7c0c383',\n    'bd3ee2b6-90f9-462f-8124-31db91ec5c58',\n    '8dd6a7e8-d1db-4ecb-b38e-4c3742c6ed67',\n    'e90e72e0-3e8b-4ddd-8a62-c3c1bf7758cc',\n    '4569b748-c823-4e9e-ab1c-4900788861ba',\n    '7fc5f381-a6ef-4109-9e48-41ef4364c221',\n    'e55f77b9-d0a1-462a-acb4-e8d3a3a458d6',\n    'f865913e-0d47-43d3-b10d-daf0e3994bae',\n    'e30f3c41-bb6e-4dac-906f-3ab2653b5b90',\n    'e3e39538-df32-4cb3-8f73-f9d96a49baf6',\n    'b9b25fb8-4d1b-42da-807f-e7c9a874df72'\n)","-- 5. Delete ONLY the 21 proven duplicate inventory_transactions records\nDELETE FROM public.inventory_transactions\nWHERE id IN (\n    '72c3e16b-64e1-438c-9b6f-4496103e0247',\n    '2b929d2d-7207-4994-ae9b-854c5035b1ad',\n    '5a914016-e770-44a4-aabc-1cecb6a91e86',\n    '105bed14-f6a1-4ca1-9c82-c53787ae617b',\n    '5fe8f625-9bad-45b1-9af4-3241d17f7b3f',\n    '9e334737-e019-472f-a27d-61fc815235d6',\n    '2367cc0b-4b6d-49a8-bddb-a9fb316a213e',\n    'aad4f2bb-99bd-43c6-a29e-8df81692b319',\n    '643f3033-56fc-4536-a10d-9915e363b00a',\n    'eb750a5c-e6a1-4954-92c9-d29164522a45',\n    'b84c456f-314a-4d17-8e64-9144f7c0c383',\n    'bd3ee2b6-90f9-462f-8124-31db91ec5c58',\n    '8dd6a7e8-d1db-4ecb-b38e-4c3742c6ed67',\n    'e90e72e0-3e8b-4ddd-8a62-c3c1bf7758cc',\n    '4569b748-c823-4e9e-ab1c-4900788861ba',\n    '7fc5f381-a6ef-4109-9e48-41ef4364c221',\n    'e55f77b9-d0a1-462a-acb4-e8d3a3a458d6',\n    'f865913e-0d47-43d3-b10d-daf0e3994bae',\n    'e30f3c41-bb6e-4dac-906f-3ab2653b5b90',\n    'e3e39538-df32-4cb3-8f73-f9d96a49baf6',\n    'b9b25fb8-4d1b-42da-807f-e7c9a874df72'\n)","-- 6. Post-execution strict assertions\nDO $$\nDECLARE\n    v_active_stock NUMERIC;\n    v_positive_batches INT;\n    v_remaining_duplicates INT;\n    v_gl_balance NUMERIC;\nBEGIN\n    -- Assert physical stock unchanged\n    SELECT SUM(current_stock), COUNT(*)\n      INTO v_active_stock, v_positive_batches\n      FROM public.batches\n     WHERE current_stock > 0;\n\n    IF v_active_stock <> 23785.000 THEN\n        RAISE EXCEPTION 'Assertion failed: total active stock is %, expected 23785.000', v_active_stock;\n    END IF;\n\n    IF v_positive_batches <> 30 THEN\n        RAISE EXCEPTION 'Assertion failed: positive batch count is %, expected 30', v_positive_batches;\n    END IF;\n\n    -- Assert 21 duplicate rows are completely removed\n    SELECT COUNT(*) INTO v_remaining_duplicates\n      FROM public.inventory_transactions\n     WHERE id IN (\n        '72c3e16b-64e1-438c-9b6f-4496103e0247',\n        '2b929d2d-7207-4994-ae9b-854c5035b1ad',\n        '5a914016-e770-44a4-aabc-1cecb6a91e86',\n        '105bed14-f6a1-4ca1-9c82-c53787ae617b',\n        '5fe8f625-9bad-45b1-9af4-3241d17f7b3f',\n        '9e334737-e019-472f-a27d-61fc815235d6',\n        '2367cc0b-4b6d-49a8-bddb-a9fb316a213e',\n        'aad4f2bb-99bd-43c6-a29e-8df81692b319',\n        '643f3033-56fc-4536-a10d-9915e363b00a',\n        'eb750a5c-e6a1-4954-92c9-d29164522a45',\n        'b84c456f-314a-4d17-8e64-9144f7c0c383',\n        'bd3ee2b6-90f9-462f-8124-31db91ec5c58',\n        '8dd6a7e8-d1db-4ecb-b38e-4c3742c6ed67',\n        'e90e72e0-3e8b-4ddd-8a62-c3c1bf7758cc',\n        '4569b748-c823-4e9e-ab1c-4900788861ba',\n        '7fc5f381-a6ef-4109-9e48-41ef4364c221',\n        'e55f77b9-d0a1-462a-acb4-e8d3a3a458d6',\n        'f865913e-0d47-43d3-b10d-daf0e3994bae',\n        'e30f3c41-bb6e-4dac-906f-3ab2653b5b90',\n        'e3e39538-df32-4cb3-8f73-f9d96a49baf6',\n        'b9b25fb8-4d1b-42da-807f-e7c9a874df72'\n    );\n\n    IF v_remaining_duplicates <> 0 THEN\n        RAISE EXCEPTION 'Assertion failed: % duplicate rows still remain', v_remaining_duplicates;\n    END IF;\n\n    -- Assert GL 1130 unchanged\n    SELECT SUM(jel.debit - jel.credit) INTO v_gl_balance\n      FROM public.journal_entry_lines jel\n      JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n      JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n     WHERE coa.code = '1130' AND je.is_posted AND NOT COALESCE(je.is_reversed, false);\n\n    IF v_gl_balance <> 1982552282.65 THEN\n        RAISE EXCEPTION 'Assertion failed: GL 1130 balance is %, expected 1982552282.65', v_gl_balance;\n    END IF;\nEND $$",COMMIT}	remove_duplicate_dc_linked_sale_inventory_transactions	\N	\N	\N
20260905140000	{"--\n-- PostgreSQL database dump\n--\n\n\\\\restrict p4dDvfJKMAPflf6Y6lvwxsqHEmvs4JLZol8szZ3ggy5cSe8RyULrkIhbGngSFj5\n\n-- Dumped from database version 17.6\n-- Dumped by pg_dump version 18.3 (Homebrew)\n\nSET statement_timeout = 0","SET lock_timeout = 0","SET idle_in_transaction_session_timeout = 0","SET transaction_timeout = 0","SET client_encoding = 'UTF8'","SET standard_conforming_strings = on","SELECT pg_catalog.set_config('search_path', '', false)","SET check_function_bodies = false","SET xmloption = content","SET client_min_messages = warning","SET row_security = off","--\n-- Name: public; Type: SCHEMA; Schema: -; Owner: -\n--\n\nCREATE SCHEMA \\"public\\"","--\n-- Name: SCHEMA \\"public\\"; Type: COMMENT; Schema: -; Owner: -\n--\n\nCOMMENT ON SCHEMA \\"public\\" IS 'All views now use SECURITY INVOKER (default) and respect RLS policies'","--\n-- Name: dc_approval_status; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"dc_approval_status\\" AS ENUM (\n    'pending_approval',\n    'approved',\n    'rejected',\n    'cancelled'\n)","--\n-- Name: import_priority; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"import_priority\\" AS ENUM (\n    'high',\n    'medium',\n    'low'\n)","--\n-- Name: import_status; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"import_status\\" AS ENUM (\n    'pending',\n    'rfq_sent',\n    'po_created',\n    'supplier_confirmed',\n    'in_production',\n    'ready_to_ship',\n    'in_transit',\n    'customs_clearance',\n    'ordered',\n    'partially_received',\n    'received',\n    'cancelled'\n)","--\n-- Name: inquiry_priority; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"inquiry_priority\\" AS ENUM (\n    'low',\n    'medium',\n    'high',\n    'urgent'\n)","--\n-- Name: inquiry_status; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"inquiry_status\\" AS ENUM (\n    'new',\n    'price_quoted',\n    'coa_pending',\n    'sample_sent',\n    'negotiation',\n    'po_received',\n    'won',\n    'lost',\n    'on_hold'\n)","--\n-- Name: pipeline_status_enum; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"pipeline_status_enum\\" AS ENUM (\n    'new',\n    'in_progress',\n    'follow_up',\n    'won',\n    'lost',\n    'on_hold'\n)","--\n-- Name: sales_order_status; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"sales_order_status\\" AS ENUM (\n    'draft',\n    'pending_approval',\n    'approved',\n    'rejected',\n    'stock_reserved',\n    'shortage',\n    'pending_delivery',\n    'partially_delivered',\n    'delivered',\n    'closed',\n    'cancelled'\n)","--\n-- Name: stock_reservation_status; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"stock_reservation_status\\" AS ENUM (\n    'active',\n    'released',\n    'consumed'\n)","--\n-- Name: task_mode_enum; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"task_mode_enum\\" AS ENUM (\n    'standard',\n    'advisory'\n)","--\n-- Name: task_origin_enum; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"task_origin_enum\\" AS ENUM (\n    'sales_order',\n    'stock_shortage',\n    'delivery',\n    'finance',\n    'procurement',\n    'manual'\n)","--\n-- Name: task_priority; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"task_priority\\" AS ENUM (\n    'low',\n    'medium',\n    'high',\n    'urgent'\n)","--\n-- Name: task_status; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"task_status\\" AS ENUM (\n    'to_do',\n    'in_progress',\n    'waiting',\n    'completed'\n)","--\n-- Name: task_type_enum; Type: TYPE; Schema: public; Owner: -\n--\n\nCREATE TYPE \\"public\\".\\"task_type_enum\\" AS ENUM (\n    'manual',\n    'system'\n)","--\n-- Name: _link_native_bank_document(\\"uuid\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"_link_native_bank_document\\"(\\"p_line_id\\" \\"uuid\\", \\"p_journal_id\\" \\"uuid\\", \\"p_label\\" \\"text\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  UPDATE public.bank_statement_lines SET matched_entry_id=p_journal_id,reconciliation_status='recorded',matching_status='confirmed',\n    matched_at=now(),matched_by=auth.uid(),manually_unlinked=false,notes=p_label\n  WHERE id=p_line_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line not found'; END IF;\nEND $$","SET default_tablespace = ''","SET default_table_access_method = \\"heap\\"","--\n-- Name: credit_notes; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"credit_notes\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"credit_note_number\\" \\"text\\" NOT NULL,\n    \\"credit_note_date\\" \\"date\\" NOT NULL,\n    \\"customer_id\\" \\"uuid\\" NOT NULL,\n    \\"original_invoice_id\\" \\"uuid\\",\n    \\"original_invoice_number\\" \\"text\\",\n    \\"reason\\" \\"text\\",\n    \\"notes\\" \\"text\\",\n    \\"currency\\" \\"text\\" DEFAULT 'IDR'::\\"text\\",\n    \\"subtotal\\" numeric(15,2) DEFAULT 0,\n    \\"tax_amount\\" numeric(15,2) DEFAULT 0,\n    \\"total_amount\\" numeric(15,2) DEFAULT 0,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"status\\" \\"text\\" DEFAULT 'pending_approval'::\\"text\\",\n    \\"approved_by\\" \\"uuid\\",\n    \\"approval_date\\" timestamp with time zone,\n    \\"company_snapshot\\" \\"jsonb\\",\n    \\"tax_period_id\\" \\"uuid\\",\n    \\"journal_entry_id\\" \\"uuid\\",\n    CONSTRAINT \\"credit_notes_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['pending_approval'::\\"text\\", 'approved'::\\"text\\", 'rejected'::\\"text\\"])))\n)","--\n-- Name: TABLE \\"credit_notes\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON TABLE \\"public\\".\\"credit_notes\\" IS 'Credit notes for returns and adjustments. Adds stock back to inventory.'","--\n-- Name: COLUMN \\"credit_notes\\".\\"status\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"credit_notes\\".\\"status\\" IS 'Approval status: pending_approval, approved, rejected'","--\n-- Name: COLUMN \\"credit_notes\\".\\"approved_by\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"credit_notes\\".\\"approved_by\\" IS 'User who approved/rejected the credit note'","--\n-- Name: COLUMN \\"credit_notes\\".\\"approval_date\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"credit_notes\\".\\"approval_date\\" IS 'Date when credit note was approved/rejected'","--\n-- Name: _post_credit_note_je(\\"public\\".\\"credit_notes\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"_post_credit_note_je\\"(\\"p_cn\\" \\"public\\".\\"credit_notes\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_je_id         uuid;\n  v_je_cogs_id    uuid;\n  v_je_number     text;\n  v_ar_id         uuid;\n  v_return_id     uuid;\n  v_ppn_id        uuid;\n  v_cogs_id       uuid;\n  v_inv_id        uuid;\n  v_total_cogs    numeric(18,2) := 0;\n  v_item          record;\n  v_actor         uuid := COALESCE(p_cn.approved_by, p_cn.created_by);\nBEGIN\n  SELECT id INTO v_ar_id     FROM chart_of_accounts WHERE code = '1120';\n  SELECT id INTO v_return_id FROM chart_of_accounts WHERE code = '4300';\n  SELECT id INTO v_ppn_id    FROM chart_of_accounts WHERE code = '2130';\n  SELECT id INTO v_cogs_id   FROM chart_of_accounts WHERE code = '5100';\n  SELECT id INTO v_inv_id    FROM chart_of_accounts WHERE code = '1130';\n\n  IF v_ar_id IS NULL OR v_return_id IS NULL THEN\n    RAISE EXCEPTION 'Credit Note JE: missing required accounts (1120 A/R or 4300 Sales Returns) in Chart of Accounts';\n  END IF;\n\n  -- ── Revenue-reversal JE ──\n  v_je_number := public.next_journal_entry_number();\n\n  INSERT INTO journal_entries\n    (entry_number, entry_date, source_module, reference_id, reference_number,\n     description, total_debit, total_credit, is_posted, posted_by, created_by)\n  VALUES\n    (v_je_number, p_cn.credit_note_date, 'credit_note', p_cn.id, p_cn.credit_note_number,\n     'Credit Note reversal — ' || p_cn.credit_note_number,\n     p_cn.total_amount, p_cn.total_amount, true, v_actor, v_actor)\n  RETURNING id INTO v_je_id;\n\n  -- Dr Sales Return (subtotal — the net of what was originally credited to Sales)\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, 1, v_return_id,\n          'Sales Return - ' || p_cn.credit_note_number,\n          p_cn.subtotal, 0, p_cn.customer_id);\n\n  -- Dr Output PPN (reduces the liability that was originally credited on the invoice)\n  IF COALESCE(p_cn.tax_amount, 0) > 0 AND v_ppn_id IS NOT NULL THEN\n    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n    VALUES (v_je_id, 2, v_ppn_id,\n            'Output PPN reversal - ' || p_cn.credit_note_number,\n            p_cn.tax_amount, 0, p_cn.customer_id);\n  END IF;\n\n  -- Cr A/R (the customer balance owed comes down)\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, 3, v_ar_id,\n          'A/R reversal - ' || p_cn.credit_note_number,\n          0, p_cn.total_amount, p_cn.customer_id);\n\n  -- ── COGS-reversal JE (Dr Inventory, Cr COGS) ──\n  IF v_cogs_id IS NOT NULL AND v_inv_id IS NOT NULL THEN\n    FOR v_item IN\n      SELECT cni.quantity, COALESCE(b.cost_per_unit, 0) AS cost_per_unit\n        FROM credit_note_items cni\n        LEFT JOIN batches b ON cni.batch_id = b.id\n       WHERE cni.credit_note_id = p_cn.id\n    LOOP\n      v_total_cogs := v_total_cogs + (v_item.quantity * v_item.cost_per_unit);\n    END LOOP;\n\n    IF v_total_cogs > 0 THEN\n      v_je_number := public.next_journal_entry_number();\n      INSERT INTO journal_entries\n        (entry_number, entry_date, source_module, reference_id, reference_number,\n         description, total_debit, total_credit, is_posted, posted_by, created_by)\n      VALUES\n        (v_je_number, p_cn.credit_note_date, 'credit_note_cogs', p_cn.id, p_cn.credit_note_number,\n         'COGS reversal for Credit Note ' || p_cn.credit_note_number,\n         v_total_cogs, v_total_cogs, true, v_actor, v_actor)\n      RETURNING id INTO v_je_cogs_id;\n\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit)\n      VALUES (v_je_cogs_id, 1, v_inv_id,\n              'Inventory - ' || p_cn.credit_note_number,\n              v_total_cogs, 0);\n\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES (v_je_cogs_id, 2, v_cogs_id,\n              'COGS reversal - ' || p_cn.credit_note_number,\n              0, v_total_cogs, p_cn.customer_id);\n    END IF;\n  END IF;\n\n  RETURN v_je_id;\nEND $$","--\n-- Name: _sec_check_finance_role(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"_sec_check_finance_role\\"() RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n      BEGIN\n        IF auth.role() = 'service_role' THEN RETURN; END IF;\n        IF auth.uid() IS NULL THEN\n          RAISE EXCEPTION 'Not authenticated';\n        END IF;\n        IF NOT EXISTS (\n          SELECT 1 FROM public.user_profiles\n          WHERE id = auth.uid()\n            AND is_active = true\n            AND role IN ('admin', 'accounts')\n        ) THEN\n          RAISE EXCEPTION 'Permission denied: only admin/accounts can perform finance operations';\n        END IF;\n      END $$","--\n-- Name: adjust_batch_stock_atomic(\\"uuid\\", numeric, \\"text\\", \\"uuid\\", \\"text\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"adjust_batch_stock_atomic\\"(\\"p_batch_id\\" \\"uuid\\", \\"p_quantity_change\\" numeric, \\"p_transaction_type\\" \\"text\\", \\"p_reference_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_notes\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_created_by\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS TABLE(\\"new_stock\\" numeric, \\"transaction_id\\" \\"uuid\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  RAISE EXCEPTION\n    'Legacy adjust_batch_stock_atomic signature is disabled; use the canonical seven-argument API with operation_id';\nEND;\n$$","--\n-- Name: FUNCTION \\"adjust_batch_stock_atomic\\"(\\"p_batch_id\\" \\"uuid\\", \\"p_quantity_change\\" numeric, \\"p_transaction_type\\" \\"text\\", \\"p_reference_id\\" \\"uuid\\", \\"p_notes\\" \\"text\\", \\"p_created_by\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"adjust_batch_stock_atomic\\"(\\"p_batch_id\\" \\"uuid\\", \\"p_quantity_change\\" numeric, \\"p_transaction_type\\" \\"text\\", \\"p_reference_id\\" \\"uuid\\", \\"p_notes\\" \\"text\\", \\"p_created_by\\" \\"uuid\\") IS 'Disabled legacy overload. Use the seven-argument Inventory V1 API with operation_id.'","--\n-- Name: adjust_batch_stock_atomic(\\"uuid\\", numeric, \\"text\\", \\"uuid\\", \\"text\\", \\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"adjust_batch_stock_atomic\\"(\\"p_batch_id\\" \\"uuid\\", \\"p_quantity_change\\" numeric, \\"p_transaction_type\\" \\"text\\", \\"p_reference_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_notes\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_created_by\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_operation_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS TABLE(\\"new_stock\\" numeric, \\"transaction_id\\" \\"uuid\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_batch public.batches%ROWTYPE;\n  v_transaction_id uuid;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(\n    ARRAY['admin', 'accounts', 'warehouse', 'manager']\n  ) THEN\n    RAISE EXCEPTION 'Permission denied for stock adjustment';\n  END IF;\n  IF p_transaction_type IS DISTINCT FROM 'adjustment' THEN\n    RAISE EXCEPTION 'Manual inventory entry supports Stock Adjustment only';\n  END IF;\n  IF COALESCE(p_quantity_change, 0) = 0 THEN\n    RAISE EXCEPTION 'Stock adjustment cannot be zero';\n  END IF;\n\n  SELECT *\n  INTO v_batch\n  FROM public.batches\n  WHERE id = p_batch_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Batch not found';\n  END IF;\n\n  v_transaction_id := public.post_inventory_movement(\n    p_operation_id,\n    v_batch.product_id,\n    v_batch.id,\n    'adjustment',\n    p_quantity_change,\n    CURRENT_DATE,\n    NULL,\n    'stock_adjustment',\n    p_reference_id,\n    p_notes,\n    COALESCE(p_created_by, auth.uid()),\n    NULL,\n    NULL\n  );\n\n  SELECT current_stock\n  INTO new_stock\n  FROM public.batches\n  WHERE id = p_batch_id;\n\n  transaction_id := v_transaction_id;\n  RETURN NEXT;\nEND;\n$$","--\n-- Name: admin_edit_approved_delivery_challan(\\"uuid\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"admin_edit_approved_delivery_challan\\"(\\"p_challan_id\\" \\"uuid\\", \\"p_new_items\\" \\"jsonb\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT public.admin_edit_approved_delivery_challan(\n    p_challan_id,\n    p_new_items,\n    gen_random_uuid()\n  );\n$$","--\n-- Name: admin_edit_approved_delivery_challan(\\"uuid\\", \\"jsonb\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"admin_edit_approved_delivery_challan\\"(\\"p_challan_id\\" \\"uuid\\", \\"p_new_items\\" \\"jsonb\\", \\"p_operation_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_challan public.delivery_challans%ROWTYPE;\n  v_old_item record;\n  v_item jsonb;\n  v_item_id uuid;\n  v_product_id uuid;\n  v_batch_id uuid;\n  v_quantity numeric;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin']) THEN\n    RAISE EXCEPTION 'Only admin can edit an approved Delivery Challan';\n  END IF;\n  IF p_operation_id IS NULL THEN\n    RAISE EXCEPTION 'operation_id is required';\n  END IF;\n\n  SELECT *\n  INTO v_challan\n  FROM public.delivery_challans\n  WHERE id = p_challan_id\n  FOR UPDATE;\n\n  IF NOT FOUND OR v_challan.approval_status <> 'approved' THEN\n    RAISE EXCEPTION 'Approved Delivery Challan not found';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM public.inventory_transactions\n    WHERE reference_type = 'delivery_challan'\n      AND reference_id = p_challan_id\n      AND COALESCE(metadata->>'canonical_engine_version', '') <> '1.0'\n  ) THEN\n    RAISE EXCEPTION 'Historical DC movement is ambiguous; manual review is required';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM public.sales_invoice_items sii\n    JOIN public.delivery_challan_items dci\n      ON dci.id = sii.delivery_challan_item_id\n    WHERE dci.challan_id = p_challan_id\n  ) THEN\n    RAISE EXCEPTION\n      'Approved Delivery Challan already invoiced; reverse the invoice before editing';\n  END IF;\n\n  FOR v_old_item IN\n    SELECT *\n    FROM public.delivery_challan_items\n    WHERE challan_id = p_challan_id\n    ORDER BY id\n  LOOP\n    PERFORM public.post_inventory_movement(\n      public.uuid_from_text(\n        'inventory-v1:dc-edit-reverse:' || p_operation_id || ':' ||\n        v_old_item.id\n      ),\n      v_old_item.product_id,\n      v_old_item.batch_id,\n      'adjustment',\n      v_old_item.quantity,\n      CURRENT_DATE,\n      v_challan.challan_number,\n      'delivery_challan_edit_reversal',\n      p_challan_id,\n      'Canonical reversal before approved DC edit',\n      auth.uid(),\n      NULL,\n      NULL\n    );\n  END LOOP;\n\n  PERFORM set_config('app.skip_dc_item_trigger', 'true', true);\n  DELETE FROM public.delivery_challan_items WHERE challan_id = p_challan_id;\n\n  IF v_challan.sales_order_id IS NOT NULL THEN\n    PERFORM public.fn_recompute_so_delivered(v_challan.sales_order_id);\n    PERFORM public.fn_reserve_stock_for_so_v2(v_challan.sales_order_id);\n  END IF;\n\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_new_items)\n  LOOP\n    v_product_id := (v_item->>'product_id')::uuid;\n    v_batch_id := (v_item->>'batch_id')::uuid;\n    v_quantity := (v_item->>'quantity')::numeric;\n\n    INSERT INTO public.delivery_challan_items (\n      challan_id,\n      product_id,\n      batch_id,\n      quantity,\n      pack_size,\n      pack_type,\n      number_of_packs\n    )\n    VALUES (\n      p_challan_id,\n      v_product_id,\n      v_batch_id,\n      v_quantity,\n      NULLIF(v_item->>'pack_size', '')::numeric,\n      NULLIF(v_item->>'pack_type', ''),\n      NULLIF(v_item->>'number_of_packs', '')::integer\n    )\n    RETURNING id INTO v_item_id;\n\n    PERFORM public.inventory_v1_consume_reservation(\n      v_challan.sales_order_id,\n      v_product_id,\n      v_batch_id,\n      v_quantity,\n      auth.uid()\n    );\n\n    PERFORM public.post_inventory_movement(\n      public.uuid_from_text(\n        'inventory-v1:dc-edit-post:' || p_operation_id || ':' || v_item_id\n      ),\n      v_product_id,\n      v_batch_id,\n      'delivery_challan',\n      -v_quantity,\n      v_challan.challan_date,\n      v_challan.challan_number,\n      'delivery_challan',\n      p_challan_id,\n      'Canonical approved DC edit repost',\n      auth.uid(),\n      NULL,\n      NULL\n    );\n  END LOOP;\n\n  PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n  IF v_challan.sales_order_id IS NOT NULL THEN\n    PERFORM public.fn_recompute_so_delivered(v_challan.sales_order_id);\n  END IF;\n\n  RETURN jsonb_build_object('success', true);\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n  RAISE;\nEND;\n$$","--\n-- Name: allocate_container_costs_to_batches(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"allocate_container_costs_to_batches\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- Call the regular function to do the allocation\nPERFORM reallocate_container_costs(NEW.id);\nRETURN NEW;\nEND;\n$$","--\n-- Name: allocate_import_costs_to_batches(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"allocate_import_costs_to_batches\\"(\\"p_container_id\\" \\"uuid\\") RETURNS json\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_container RECORD;\nv_batch RECORD;\nv_total_invoice_value DECIMAL(18,2);\nv_total_import_cost DECIMAL(18,2);\nv_linked_expenses_total DECIMAL(18,2);\nv_linked_petty_cash_total DECIMAL(18,2);\nv_broker_canonical_total DECIMAL(18,2);\nv_allocation_percentage DECIMAL(10,6);\nv_allocated_cost DECIMAL(18,2);\nv_batches_allocated INTEGER := 0;\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot allocate import costs', v_role;\nEND IF;\n\nSELECT * INTO v_container\nFROM import_containers\nWHERE id = p_container_id;\n\nIF NOT FOUND THEN\nRETURN json_build_object('success', false, 'error', 'Container not found');\nEND IF;\n\nIF v_container.status != 'draft' THEN\nRETURN json_build_object('success', false, 'error', 'Container already allocated or locked');\nEND IF;\n\n-- Linked finance expenses (NULL = included, TRUE = included, FALSE = excluded)\n-- For broker expenses, compute canonical accountingExpenseTotal in SQL\nWITH canonical_expenses AS (\nSELECT\nfe.id,\nfe.expense_category,\nfe.amount,\nfe.ppn_amount,\nfe.stamp_duty_amount,\nfe.broker_items,\nCASE\nWHEN fe.expense_category = 'import_broker' THEN\n-- accountingExpenseTotal = brokerInvoiceAmount - headerPpn + sum(brokerLineExpenseBase) + stampDuty\n-- brokerLineExpenseBase = brokerLineTotal - item.ppn_amount\n-- brokerLineTotal = item.amount (when invoice_amount_authoritative) else amount != 0 ? amount : dpp + ppn\nfe.amount - COALESCE(fe.ppn_amount, 0)\n+ COALESCE((\nSELECT SUM(\nCASE\nWHEN (item->>'invoice_amount_authoritative')::boolean = true\nTHEN (item->>'amount')::numeric\nELSE COALESCE(NULLIF((item->>'amount')::numeric, 0), (item->>'dpp_amount')::numeric + (item->>'ppn_amount')::numeric)\nEND\n- COALESCE((item->>'ppn_amount')::numeric, 0)\n)\nFROM jsonb_array_elements(fe.broker_items) AS item\n), 0)\n+ COALESCE(fe.stamp_duty_amount, 0)\nELSE\nCOALESCE(fe.amount, 0)\nEND AS canonical_total\nFROM finance_expenses fe\nWHERE fe.import_container_id = p_container_id\nAND fe.expense_category != 'pib_import'\nAND COALESCE(fe.include_in_landed_cost, true) = true\n)\nSELECT COALESCE(SUM(canonical_total), 0) INTO v_linked_expenses_total\nFROM canonical_expenses;\n\n-- Linked petty cash (NULL = included, TRUE = included, FALSE = excluded)\nSELECT COALESCE(SUM(amount), 0) INTO v_linked_petty_cash_total\nFROM petty_cash_transactions\nWHERE import_container_id = p_container_id\nAND COALESCE(include_in_landed_cost, true) = true;\n\nv_total_import_cost := v_linked_expenses_total + v_linked_petty_cash_total + COALESCE(v_container.other_import_costs, 0);\n\nIF v_total_import_cost = 0 THEN\nRETURN json_build_object('success', false, 'error', 'No import costs to allocate');\nEND IF;\n\nSELECT COALESCE(SUM(import_price * import_quantity), 0) INTO v_total_invoice_value\nFROM batches\nWHERE import_container_id = p_container_id;\n\nIF v_total_invoice_value = 0 THEN\nRETURN json_build_object('success', false, 'error', 'No batches linked to this container');\nEND IF;\n\nFOR v_batch IN\nSELECT id, import_price, import_quantity, (import_price * import_quantity) as batch_invoice_value\nFROM batches\nWHERE import_container_id = p_container_id\nAND COALESCE(cost_locked, false) = false\nLOOP\nv_allocation_percentage := (v_batch.batch_invoice_value / v_total_invoice_value) * 100;\nv_allocated_cost := (v_total_import_cost * v_batch.batch_invoice_value) / v_total_invoice_value;\n\nINSERT INTO import_container_allocations (\ncontainer_id, batch_id, batch_invoice_value,\nallocation_percentage, allocated_cost, allocated_by\n) VALUES (\np_container_id, v_batch.id, v_batch.batch_invoice_value,\nv_allocation_percentage, v_allocated_cost, auth.uid()\n)\nON CONFLICT (container_id, batch_id)\nDO UPDATE SET\nallocation_percentage = EXCLUDED.allocation_percentage,\nallocated_cost = EXCLUDED.allocated_cost;\n\nUPDATE batches\nSET import_cost_allocated = v_allocated_cost,\nfinal_landed_cost = import_price + v_allocated_cost,\ncost_locked = true\nWHERE id = v_batch.id;\n\nv_batches_allocated := v_batches_allocated + 1;\nEND LOOP;\n\nUPDATE import_containers\nSET status = 'allocated',\nlocked_at = now(),\nlocked_by = auth.uid(),\nallocated_expenses = v_total_import_cost\nWHERE id = p_container_id;\n\nRETURN json_build_object(\n'success', true,\n'batches_allocated', v_batches_allocated,\n'total_cost', v_total_import_cost,\n'linked_expenses_total', v_linked_expenses_total,\n'linked_petty_cash_total', v_linked_petty_cash_total,\n'other_import_costs', COALESCE(v_container.other_import_costs, 0),\n'note', 'Canonical broker calculation; PIB excluded; NULL=included'\n);\nEND;\n$$","--\n-- Name: apply_advance_to_invoice(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"apply_advance_to_invoice\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE r record; v_applied numeric := 0; v_remaining numeric; v_take numeric;\nBEGIN\n  IF NEW.sales_order_id IS NULL THEN RETURN NEW; END IF;\n  FOR r IN SELECT id, receipt_voucher_id, allocated_amount\n             FROM public.voucher_allocations\n            WHERE sales_order_id = NEW.sales_order_id AND voucher_type = 'receipt'\n            ORDER BY created_at, id\n  LOOP\n    v_remaining := NEW.total_amount - v_applied;\n    EXIT WHEN v_remaining <= 0;\n    v_take := LEAST(r.allocated_amount, v_remaining);\n    IF v_take >= r.allocated_amount THEN\n      DELETE FROM public.voucher_allocations WHERE id = r.id;\n    ELSE\n      UPDATE public.voucher_allocations SET allocated_amount = allocated_amount - v_take WHERE id = r.id;\n    END IF;\n    INSERT INTO public.voucher_allocations(voucher_type, receipt_voucher_id, sales_invoice_id, allocated_amount)\n      VALUES ('receipt', r.receipt_voucher_id, NEW.id, v_take);\n    v_applied := v_applied + v_take;\n  END LOOP;\n  IF v_applied > 0 THEN\n    UPDATE public.sales_invoices\n       SET paid_amount = v_applied,\n           balance_amount = total_amount - v_applied,\n           payment_status = CASE WHEN v_applied >= total_amount THEN 'paid' ELSE 'partial' END,\n           updated_at = now()\n     WHERE id = NEW.id;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: apply_batch_receipt_weighted_average(\\"uuid\\", numeric, numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"apply_batch_receipt_weighted_average\\"(\\"p_batch_id\\" \\"uuid\\", \\"p_received_quantity\\" numeric, \\"p_receipt_unit_cost\\" numeric) RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  b public.batches%ROWTYPE;\n  prior_qty numeric;\n  prior_cost numeric;\n  new_cost numeric;\nBEGIN\n  SELECT * INTO b FROM public.batches WHERE id=p_batch_id FOR UPDATE;\n  IF NOT FOUND OR p_received_quantity <= 0 THEN RETURN; END IF;\n  prior_qty := GREATEST(COALESCE(b.current_stock,0) - p_received_quantity, 0);\n  prior_cost := COALESCE(NULLIF(b.landed_cost_per_unit,0), NULLIF(b.cost_per_unit,0), NULLIF(b.import_price,0), 0);\n  new_cost := CASE WHEN prior_qty <= 0 THEN p_receipt_unit_cost\n    ELSE ((prior_qty * prior_cost) + (p_received_quantity * p_receipt_unit_cost))\n      / NULLIF(prior_qty + p_received_quantity,0) END;\n  UPDATE public.batches\n     SET cost_per_unit=round(new_cost,2), landed_cost_per_unit=round(new_cost,2), updated_at=now()\n   WHERE id=p_batch_id AND COALESCE(cost_locked,false)=false;\nEND; $$","--\n-- Name: FUNCTION \\"apply_batch_receipt_weighted_average\\"(\\"p_batch_id\\" \\"uuid\\", \\"p_received_quantity\\" numeric, \\"p_receipt_unit_cost\\" numeric); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"apply_batch_receipt_weighted_average\\"(\\"p_batch_id\\" \\"uuid\\", \\"p_received_quantity\\" numeric, \\"p_receipt_unit_cost\\" numeric) IS 'Future physical-batch moving weighted average; receipt layers remain separately auditable.'","--\n-- Name: apply_import_costs_to_batches(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"apply_import_costs_to_batches\\"(\\"p_header_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nv_item RECORD;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot apply import costs', v_role;\nEND IF;\n\nFOR v_item IN\nSELECT * FROM import_cost_items WHERE cost_header_id = p_header_id AND batch_id IS NOT NULL\nLOOP\nUPDATE batches\nSET\ncost_per_unit = v_item.final_landed_cost_per_unit,\nupdated_at = NOW()\nWHERE id = v_item.batch_id;\n\nINSERT INTO inventory_transactions (\nproduct_id, batch_id, transaction_type, quantity, transaction_date,\nreference_number, reference_type, reference_id, notes, created_by,\nstock_before, stock_after\n)\nSELECT\nv_item.product_id,\nv_item.batch_id,\n'cost_adjustment',\n0,\nCURRENT_DATE,\n(SELECT cost_sheet_number FROM import_cost_headers WHERE id = p_header_id),\n'import_cost',\np_header_id,\n'Import cost allocation: Duty=' || v_item.allocated_duty ||\n', PPN=' || v_item.allocated_ppn ||\n', Freight=' || v_item.allocated_freight,\n(SELECT created_by FROM import_cost_headers WHERE id = p_header_id),\n(SELECT current_stock FROM batches WHERE id = v_item.batch_id),\n(SELECT current_stock FROM batches WHERE id = v_item.batch_id);\nEND LOOP;\nEND;\n$$","--\n-- Name: FUNCTION \\"apply_import_costs_to_batches\\"(\\"p_header_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"apply_import_costs_to_batches\\"(\\"p_header_id\\" \\"uuid\\") IS 'Updates batch cost_per_unit with allocated import costs (landed cost). Creates audit trail in inventory_transactions.'","--\n-- Name: apply_receipt_allocation_rounding_adjustment(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"apply_receipt_allocation_rounding_adjustment\\"(\\"p_invoice_id\\" \\"uuid\\", \\"p_receipt_voucher_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_invoice record;\n  v_allocated numeric(18,2);\n  v_residual numeric(18,2);\n  v_tolerance numeric(18,2);\n  v_existing record;\n  v_entry_id uuid;\n  v_entry_number text;\n  v_ar_account_id uuid;\n  v_adjustment_account_id uuid;\n  v_user_id uuid;\nBEGIN\n  SELECT *\n  INTO v_invoice\n  FROM public.sales_invoices\n  WHERE id = p_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  SELECT COALESCE(rounding_tolerance_amount, 0)\n  INTO v_tolerance\n  FROM public.app_settings\n  LIMIT 1;\n  v_tolerance := COALESCE(v_tolerance, 0);\n\n  SELECT *\n  INTO v_existing\n  FROM public.invoice_rounding_adjustments\n  WHERE sales_invoice_id = p_invoice_id\n     OR (p_receipt_voucher_id IS NOT NULL AND receipt_voucher_id = p_receipt_voucher_id)\n  LIMIT 1;\n\n  v_allocated := public.get_invoice_allocation_amount(p_invoice_id, NULL);\n  v_residual := ROUND(COALESCE(v_invoice.total_amount, 0) - COALESCE(v_allocated, 0), 2);\n\n  IF ABS(v_residual) > 0 AND ABS(v_residual) <= v_tolerance THEN\n    IF v_existing.id IS NOT NULL AND v_existing.adjustment_amount = v_residual THEN\n      PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);\n      RETURN;\n    END IF;\n\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n\n    SELECT id INTO v_ar_account_id\n    FROM public.chart_of_accounts\n    WHERE code = '1120'\n    LIMIT 1;\n\n    IF v_residual > 0 THEN\n      SELECT COALESCE(\n        (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),\n        (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)\n      )\n      INTO v_adjustment_account_id;\n    ELSE\n      SELECT COALESCE(\n        (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),\n        (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)\n      )\n      INTO v_adjustment_account_id;\n    END IF;\n\n    IF v_ar_account_id IS NULL OR v_adjustment_account_id IS NULL THEN\n      RAISE EXCEPTION 'Missing account setup for invoice rounding adjustment';\n    END IF;\n\n    v_user_id := COALESCE(auth.uid(), v_invoice.created_by);\n    v_entry_number := public.next_journal_entry_number();\n\n    INSERT INTO public.journal_entries (\n      entry_number, entry_date, source_module, reference_id, reference_number,\n      description, total_debit, total_credit, is_posted, posted_by, created_by\n    ) VALUES (\n      v_entry_number,\n      COALESCE(v_invoice.invoice_date, CURRENT_DATE),\n      'sales_invoice_rounding',\n      v_invoice.id,\n      v_invoice.invoice_number,\n      'Receipt allocation rounding adjustment: ' || v_invoice.invoice_number,\n      ABS(v_residual),\n      ABS(v_residual),\n      true,\n      v_user_id,\n      v_user_id\n    )\n    RETURNING id INTO v_entry_id;\n\n    IF v_residual > 0 THEN\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES\n        (v_entry_id, 1, v_adjustment_account_id, 'Rounding write-off - ' || v_invoice.invoice_number, ABS(v_residual), 0, v_invoice.customer_id),\n        (v_entry_id, 2, v_ar_account_id, 'A/R rounding clearance - ' || v_invoice.invoice_number, 0, ABS(v_residual), v_invoice.customer_id);\n    ELSE\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES\n        (v_entry_id, 1, v_ar_account_id, 'A/R rounding clearance - ' || v_invoice.invoice_number, ABS(v_residual), 0, v_invoice.customer_id),\n        (v_entry_id, 2, v_adjustment_account_id, 'Rounding gain - ' || v_invoice.invoice_number, 0, ABS(v_residual), v_invoice.customer_id);\n    END IF;\n\n    INSERT INTO public.invoice_rounding_adjustments (\n      receipt_voucher_id, sales_invoice_id, adjustment_amount, journal_entry_id, created_by\n    ) VALUES (\n      p_receipt_voucher_id, p_invoice_id, v_residual, v_entry_id, v_user_id\n    );\n  ELSE\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n  END IF;\n\n  PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);\nEND;\n$$","--\n-- Name: apply_salary_advances_to_expense(\\"uuid\\", boolean); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"apply_salary_advances_to_expense\\"(\\"p_salary_expense_id\\" \\"uuid\\", \\"p_apply\\" boolean DEFAULT true) RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_salary public.finance_expenses%ROWTYPE;\n  v_staff_name text;\n  v_remaining numeric;\n  v_total numeric := 0;\n  v_settlement jsonb;\n  v_settlement_id uuid;\n  v_advance record;\n  v_advance_applied numeric;\n  v_available numeric;\n  v_to_apply numeric;\n  v_currency text;\n  v_application_ids uuid[] := ARRAY[]::uuid[];\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  SELECT * INTO v_salary FROM public.finance_expenses WHERE id=p_salary_expense_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Salary expense not found'; END IF;\n  IF v_salary.expense_category<>'salary' OR v_salary.staff_id IS NULL THEN\n    RAISE EXCEPTION 'Salary advances require a Salary expense with a selected staff member';\n  END IF;\n  SELECT full_name INTO v_staff_name FROM public.finance_staff_master WHERE id=v_salary.staff_id;\n  SELECT upper(COALESCE(v_salary.transaction_currency,v_salary.currency_code,'IDR')) INTO v_currency;\n\n  SELECT greatest(v_salary.amount-COALESCE(v_salary.pph_amount,0)-COALESCE(sum(applied_amount),0),0)\n    INTO v_remaining FROM public.salary_advance_applications WHERE salary_expense_id=p_salary_expense_id;\n  v_remaining:=COALESCE(v_remaining,greatest(v_salary.amount-COALESCE(v_salary.pph_amount,0),0));\n  IF NOT p_apply OR v_remaining<=0 THEN\n    RETURN jsonb_build_object('applied',false,'total_applied',0,'remaining_salary',v_remaining);\n  END IF;\n\n  FOR v_advance IN\n    SELECT pv.id,pv.voucher_number,pv.voucher_date,pv.amount\n      FROM public.payment_vouchers pv\n     WHERE pv.payment_purpose='salary_advance' AND pv.is_posted=true AND pv.staff_id=v_salary.staff_id\n       AND NOT EXISTS(SELECT 1 FROM public.salary_advance_applications existing\n         WHERE existing.advance_payment_voucher_id=pv.id AND existing.salary_expense_id=p_salary_expense_id)\n     ORDER BY pv.voucher_date,pv.created_at,pv.id FOR UPDATE OF pv\n  LOOP\n    SELECT COALESCE(sum(applied_amount),0) INTO v_advance_applied\n      FROM public.salary_advance_applications WHERE advance_payment_voucher_id=v_advance.id;\n    v_available:=greatest(v_advance.amount-v_advance_applied,0);\n    v_to_apply:=least(v_available,v_remaining-v_total);\n    IF v_to_apply>0 THEN\n      v_total:=v_total+v_to_apply;\n      v_application_ids:=array_append(v_application_ids,v_advance.id);\n    END IF;\n    EXIT WHEN v_total>=v_remaining;\n  END LOOP;\n  IF v_total<=0 THEN RETURN jsonb_build_object('applied',false,'total_applied',0,'remaining_salary',v_remaining); END IF;\n\n  v_settlement:=public.save_payment_voucher_command(\n    p_voucher_id=>NULL,\n    p_payload=>jsonb_build_object(\n      'voucher_date',v_salary.expense_date,'staff_id',v_salary.staff_id,\n      'payment_method','advance_adjustment','amount',v_total,'payment_currency',v_currency,\n      'exchange_rate',CASE WHEN v_currency='IDR' THEN 1 ELSE COALESCE(v_salary.exchange_rate,1) END,\n      'description','Salary Advance Recovery - '||COALESCE(v_salary.voucher_number,v_salary.id::text),\n      'created_by',auth.uid(),'document_urls','[]'::jsonb),\n    p_allocations=>jsonb_build_array(jsonb_build_object(\n      'finance_expense_id',v_salary.id,'amount',v_total,'currency',v_currency)));\n  v_settlement_id:=(v_settlement->>'id')::uuid;\n  UPDATE public.payment_vouchers SET payment_purpose='salary_advance_settlement' WHERE id=v_settlement_id;\n  PERFORM public.post_payment_voucher(v_settlement_id,auth.uid());\n\n  v_remaining:=v_total;\n  FOR v_advance IN\n    SELECT pv.id,pv.amount FROM public.payment_vouchers pv WHERE pv.id=ANY(v_application_ids)\n     ORDER BY pv.voucher_date,pv.created_at,pv.id\n  LOOP\n    SELECT COALESCE(sum(applied_amount),0) INTO v_advance_applied\n      FROM public.salary_advance_applications WHERE advance_payment_voucher_id=v_advance.id;\n    v_available:=greatest(v_advance.amount-v_advance_applied,0);\n    v_to_apply:=least(v_available,v_remaining);\n    IF v_to_apply>0 THEN\n      INSERT INTO public.salary_advance_applications(\n        advance_payment_voucher_id,salary_expense_id,settlement_payment_voucher_id,applied_amount)\n      VALUES(v_advance.id,v_salary.id,v_settlement_id,v_to_apply);\n      PERFORM public.refresh_salary_advance_status(v_advance.id);\n      v_remaining:=v_remaining-v_to_apply;\n    END IF;\n    EXIT WHEN v_remaining<=0;\n  END LOOP;\n  RETURN jsonb_build_object(\n    'applied',true,'total_applied',v_total,\n    'remaining_salary',greatest(v_salary.amount-COALESCE(v_salary.pph_amount,0)-v_total,0),\n    'settlement_payment_voucher_id',v_settlement_id,\n    'settlement_payment_voucher_number',v_settlement->>'voucher_number');\nEND;\n$$","--\n-- Name: approve_finance_expense(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"approve_finance_expense\\"(\\"p_expense_id\\" \\"uuid\\", \\"p_approved_by\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  UPDATE public.finance_expenses SET approval_status='approved',approved_by=COALESCE(p_approved_by,auth.uid()),approved_at=now(),rejection_reason=NULL\n  WHERE id=p_expense_id AND approval_status IS DISTINCT FROM 'approved';\n  IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM public.finance_expenses WHERE id=p_expense_id AND approval_status='approved') THEN\n    RAISE EXCEPTION 'Expense not found';\n  END IF;\n  RETURN p_expense_id;\nEND $$","--\n-- Name: approve_purchase_invoice_for_receiving(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"approve_purchase_invoice_for_receiving\\"(\\"p_purchase_invoice_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_status text;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','manager']) THEN RAISE EXCEPTION 'Permission denied'; END IF;\n  SELECT receiving_approval_status INTO v_status FROM public.purchase_invoices WHERE id=p_purchase_invoice_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;\n  IF v_status <> 'pending_approval' THEN RAISE EXCEPTION 'Purchase Invoice must be pending approval'; END IF;\n  UPDATE public.purchase_invoices SET receiving_approval_status='approved', receiving_approved_at=now(), receiving_approved_by=auth.uid(), updated_at=now() WHERE id=p_purchase_invoice_id;\n  RETURN jsonb_build_object('success',true,'status','approved');\nEND; $$","--\n-- Name: approve_sales_order_inventory_v1(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"approve_sales_order_inventory_v1\\"(\\"p_so_id\\" \\"uuid\\", \\"p_approved_by\\" \\"uuid\\") RETURNS TABLE(\\"success\\" boolean, \\"message\\" \\"text\\", \\"shortage_items\\" \\"jsonb\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_previous_context text;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(\n    ARRAY['admin', 'accounts', 'manager', 'warehouse']\n  ) THEN\n    RAISE EXCEPTION 'Permission denied for Sales Order approval';\n  END IF;\n\n  v_previous_context := current_setting('app.canonical_reservation_engine', true);\n  PERFORM set_config('app.canonical_reservation_engine', 'on', true);\n\n  UPDATE public.sales_orders\n  SET status = 'approved',\n      approved_by = COALESCE(p_approved_by, auth.uid()),\n      approved_at = now(),\n      updated_at = now()\n  WHERE id = p_so_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Order not found';\n  END IF;\n\n  RETURN QUERY\n  SELECT *\n  FROM public.fn_reserve_stock_for_so_v2(p_so_id);\n\n  PERFORM set_config(\n    'app.canonical_reservation_engine',\n    COALESCE(v_previous_context, ''),\n    true\n  );\nEND;\n$$","--\n-- Name: approve_sales_order_product_reservation_v2(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"approve_sales_order_product_reservation_v2\\"(\\"p_so_id\\" \\"uuid\\", \\"p_approved_by\\" \\"uuid\\") RETURNS TABLE(\\"success\\" boolean, \\"message\\" \\"text\\", \\"shortage_items\\" \\"jsonb\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  r record;\n  v_delivered numeric;\n  v_item_required numeric;\n  v_reserved numeric;\n  v_shortage_qty numeric;\n  v_shortage_list jsonb := '[]'::jsonb;\n  v_has_shortage boolean := false;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'manager', 'warehouse'])\n     AND current_setting('app.canonical_reservation_engine', true) IS DISTINCT FROM 'on' THEN\n    RAISE EXCEPTION 'Permission denied for SO product reservation approval';\n  END IF;\n\n  PERFORM 1 FROM public.sales_orders WHERE id = p_so_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Order not found';\n  END IF;\n\n  PERFORM set_config('app.canonical_reservation_engine', 'on', true);\n\n  UPDATE public.sales_orders\n  SET approved_by = COALESCE(p_approved_by, auth.uid()),\n      approved_at = COALESCE(approved_at, now())\n  WHERE id = p_so_id;\n\n  FOR r IN\n    SELECT id, product_id, quantity\n    FROM public.sales_order_items\n    WHERE sales_order_id = p_so_id\n    ORDER BY product_id, id\n  LOOP\n    v_reserved := public.reconcile_so_product_reservation_v2(r.id, 'SO approval/re-approval');\n\n    SELECT COALESCE(sum(dci.quantity), 0) INTO v_delivered\n    FROM public.delivery_challan_items dci\n    JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n    WHERE dci.sales_order_item_id = r.id\n      AND dc.approval_status = 'approved';\n\n    v_item_required := GREATEST(r.quantity - v_delivered, 0);\n\n    IF v_item_required > v_reserved THEN\n      v_has_shortage := true;\n      v_shortage_qty := v_item_required - v_reserved;\n      v_shortage_list := v_shortage_list || jsonb_build_object(\n        'product_id', r.product_id,\n        'required_qty', r.quantity,\n        'shortage_qty', v_shortage_qty\n      );\n    END IF;\n  END LOOP;\n\n  IF v_has_shortage THEN\n    UPDATE public.sales_orders\n    SET status = 'shortage',\n        updated_at = now()\n    WHERE id = p_so_id;\n\n    PERFORM public.fn_create_import_requirements(p_so_id, v_shortage_list);\n\n    RETURN QUERY\n    SELECT false, 'Partial stock reserved - shortage exists.'::text, v_shortage_list;\n  ELSE\n    UPDATE public.sales_orders\n    SET status = 'stock_reserved',\n        updated_at = now()\n    WHERE id = p_so_id;\n\n    RETURN QUERY\n    SELECT true, 'Stock fully reserved'::text, '[]'::jsonb;\n  END IF;\nEND;\n$$","--\n-- Name: archive_batch_inventory_v1(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"archive_batch_inventory_v1\\"(\\"p_batch_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_batch public.batches%ROWTYPE;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(\n    ARRAY['admin', 'accounts', 'warehouse', 'manager']\n  ) THEN\n    RAISE EXCEPTION 'Permission denied for batch archive';\n  END IF;\n\n  SELECT *\n  INTO v_batch\n  FROM public.batches\n  WHERE id = p_batch_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object(\n      'archived', false,\n      'reason', 'Batch not found'\n    );\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM public.stock_reservations\n    WHERE batch_id = p_batch_id\n      AND status = 'active'\n  ) THEN\n    RETURN jsonb_build_object(\n      'archived', false,\n      'reason', format(\n        'Batch %s has active reservations and cannot be archived',\n        v_batch.batch_number\n      )\n    );\n  END IF;\n\n  IF v_batch.current_stock <> 0 THEN\n    RETURN jsonb_build_object(\n      'archived', false,\n      'reason', format(\n        'Batch %s still has stock %s. Post a canonical adjustment to zero before archiving',\n        v_batch.batch_number,\n        v_batch.current_stock\n      )\n    );\n  END IF;\n\n  UPDATE public.batches\n  SET is_active = false,\n      updated_at = now()\n  WHERE id = p_batch_id;\n\n  RETURN jsonb_build_object(\n    'archived', true,\n    'batch_id', p_batch_id,\n    'batch_number', v_batch.batch_number\n  );\nEND;\n$$","--\n-- Name: archive_old_records(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"archive_old_records\\"() RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nv_notifications_deleted integer := 0;\nv_gmail_deleted integer := 0;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin') THEN\nRAISE EXCEPTION 'Permission denied: only admin can archive old records';\nEND IF;\n\nDELETE FROM notifications\nWHERE is_read = true\nAND created_at < now() - interval '90 days';\nGET DIAGNOSTICS v_notifications_deleted = ROW_COUNT;\n\nDELETE FROM notifications\nWHERE is_read = false\nAND created_at < now() - interval '180 days';\n\nDELETE FROM gmail_processed_messages\nWHERE created_at < now() - interval '60 days';\nGET DIAGNOSTICS v_gmail_deleted = ROW_COUNT;\n\nRETURN jsonb_build_object(\n'notifications_deleted', v_notifications_deleted,\n'gmail_processed_deleted', v_gmail_deleted,\n'archived_at', now()\n);\nEND;\n$$","--\n-- Name: assert_posted_journal_balanced(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"assert_posted_journal_balanced\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_debit numeric;\n  v_credit numeric;\nBEGIN\n  IF COALESCE(NEW.is_posted, false) IS NOT TRUE THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT COALESCE(SUM(debit), 0), COALESCE(SUM(credit), 0)\n    INTO v_debit, v_credit\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id = NEW.id;\n\n  IF abs(v_debit - v_credit) > 0.01 THEN\n    RAISE EXCEPTION 'Posted journal % is out of balance: debit %, credit %',\n      NEW.entry_number, v_debit, v_credit;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"assert_posted_journal_balanced\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"assert_posted_journal_balanced\\"() IS 'Deferred invariant: newly inserted or posted journals must have equal debit and credit totals.'","--\n-- Name: assert_posted_journal_lines_balanced(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"assert_posted_journal_lines_balanced\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_je_id uuid := COALESCE(NEW.journal_entry_id, OLD.journal_entry_id);\n  v_posted boolean;\n  v_debit numeric;\n  v_credit numeric;\n  v_entry_number text;\nBEGIN\n  SELECT is_posted, entry_number INTO v_posted, v_entry_number\n    FROM public.journal_entries WHERE id = v_je_id;\n  IF COALESCE(v_posted, false) IS NOT TRUE THEN\n    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;\n  END IF;\n  SELECT COALESCE(SUM(debit),0), COALESCE(SUM(credit),0)\n    INTO v_debit, v_credit\n    FROM public.journal_entry_lines WHERE journal_entry_id = v_je_id;\n  IF abs(v_debit - v_credit) > 0.01 THEN\n    RAISE EXCEPTION 'Posted journal % is out of balance: debit %, credit %', v_entry_number, v_debit, v_credit;\n  END IF;\n  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND;\n$$","--\n-- Name: assign_faktur_pajak_number(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"assign_faktur_pajak_number\\"(\\"p_sales_invoice_id\\" \\"uuid\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_settings   organization_tax_settings%ROWTYPE;\n  v_number     text;\n  v_next       int;\n  v_invoice    sales_invoices%ROWTYPE;\n  v_lock_id    bigint;\n  v_period_id  uuid;\n  v_dpp        numeric(18,2);\n  v_ppn        numeric(18,2);\nBEGIN\n  -- Serialize faktur-number issuance across concurrent callers\n  v_lock_id := hashtext('faktur_pajak_seq');\n  PERFORM pg_advisory_xact_lock(v_lock_id);\n\n  SELECT * INTO v_settings FROM organization_tax_settings ORDER BY created_at LIMIT 1;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'organization_tax_settings not configured — cannot issue Faktur Pajak';\n  END IF;\n  IF v_settings.pkp_status = false THEN\n    RAISE EXCEPTION 'Organization is not PKP — cannot issue Faktur Pajak';\n  END IF;\n\n  SELECT * INTO v_invoice FROM sales_invoices WHERE id = p_sales_invoice_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales invoice % not found', p_sales_invoice_id;\n  END IF;\n  IF v_invoice.faktur_pajak_number IS NOT NULL AND v_invoice.faktur_pajak_number <> '' THEN\n    -- Idempotent: return the existing number\n    RETURN v_invoice.faktur_pajak_number;\n  END IF;\n\n  v_next := COALESCE(v_settings.faktur_current_number, 0) + 1;\n\n  v_number := COALESCE(v_settings.faktur_prefix, '000') || '.' ||\n              lpad(v_next::text, 8, '0') || '-' ||\n              to_char(COALESCE(v_invoice.invoice_date, CURRENT_DATE), 'YY');\n\n  UPDATE organization_tax_settings\n    SET faktur_current_number = v_next, updated_at = now()\n    WHERE id = v_settings.id;\n\n  UPDATE sales_invoices\n    SET faktur_pajak_number = v_number,\n        updated_at = now()\n    WHERE id = p_sales_invoice_id;\n\n  -- Attribute invoice to its PPN tax_period (idempotent upsert)\n  v_period_id := upsert_tax_period(\n    EXTRACT(YEAR  FROM v_invoice.invoice_date)::int,\n    EXTRACT(MONTH FROM v_invoice.invoice_date)::int,\n    'PPN'\n  );\n  UPDATE sales_invoices SET tax_period_id = v_period_id WHERE id = p_sales_invoice_id;\n\n  -- Derive DPP + PPN split from tax_amount (Indonesian PPN 11%)\n  v_ppn := COALESCE(v_invoice.tax_amount, 0);\n  v_dpp := GREATEST(COALESCE(v_invoice.total_amount, 0) - v_ppn, 0);\n\n  INSERT INTO faktur_pajak\n    (sales_invoice_id, tax_period_id, faktur_number, issue_date,\n     customer_id, dpp_amount, ppn_amount, status, created_by)\n  VALUES\n    (p_sales_invoice_id, v_period_id, v_number,\n     COALESCE(v_invoice.invoice_date, CURRENT_DATE),\n     v_invoice.customer_id, v_dpp, v_ppn, 'generated', auth.uid())\n  ON CONFLICT (sales_invoice_id) DO UPDATE SET\n    faktur_number = EXCLUDED.faktur_number,\n    tax_period_id = EXCLUDED.tax_period_id,\n    dpp_amount    = EXCLUDED.dpp_amount,\n    ppn_amount    = EXCLUDED.ppn_amount,\n    updated_at    = now();\n\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)\n  VALUES (auth.uid(), 'faktur_pajak', 'insert', p_sales_invoice_id,\n          jsonb_build_object('faktur_number', v_number, 'sales_invoice_id', p_sales_invoice_id));\n\n  RETURN v_number;\nEND $$","--\n-- Name: audit_fund_transfer_repair_eligibility(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"audit_fund_transfer_repair_eligibility\\"(\\"p_fund_transfer_id\\" \\"uuid\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  t public.fund_transfers%ROWTYPE;\n  j public.journal_entries%ROWTYPE;\n  from_coa uuid;\n  to_coa uuid;\n  from_currency text;\n  to_currency text;\n  expected_rate numeric;\n  candidate_count integer;\n  line_count integer;\nBEGIN\n  SELECT * INTO t FROM public.fund_transfers WHERE id = p_fund_transfer_id;\n  IF NOT FOUND THEN RETURN 'Fund Transfer record is missing'; END IF;\n  IF t.status <> 'posted' THEN RETURN 'Fund Transfer is not posted'; END IF;\n  IF t.journal_entry_id IS NULL THEN RETURN 'Posted Fund Transfer has no linked journal'; END IF;\n\n  SELECT * INTO j FROM public.journal_entries WHERE id = t.journal_entry_id;\n  IF NOT FOUND OR NOT COALESCE(j.is_posted, false) OR COALESCE(j.is_reversed, false)\n     THEN RETURN 'Linked journal is missing, unposted, or reversed'; END IF;\n  IF j.source_module NOT IN ('fund_transfer', 'fund_transfers')\n     OR j.reference_id IS DISTINCT FROM t.id\n     THEN RETURN 'Journal source relationship does not prove this Fund Transfer'; END IF;\n\n  IF t.from_account_type = 'bank' THEN\n    SELECT coa_id, upper(currency) INTO from_coa, from_currency\n      FROM public.bank_accounts WHERE id = t.from_bank_account_id AND is_active;\n  ELSIF t.from_account_type = 'petty_cash' THEN\n    SELECT id, 'IDR' INTO from_coa, from_currency FROM public.chart_of_accounts\n      WHERE code = '1102' AND is_active LIMIT 1;\n  ELSE\n    SELECT id, 'IDR' INTO from_coa, from_currency FROM public.chart_of_accounts\n      WHERE code = '1101' AND is_active LIMIT 1;\n  END IF;\n  IF t.to_account_type = 'bank' THEN\n    SELECT coa_id, upper(currency) INTO to_coa, to_currency\n      FROM public.bank_accounts WHERE id = t.to_bank_account_id AND is_active;\n  ELSIF t.to_account_type = 'petty_cash' THEN\n    SELECT id, 'IDR' INTO to_coa, to_currency FROM public.chart_of_accounts\n      WHERE code = '1102' AND is_active LIMIT 1;\n  ELSE\n    SELECT id, 'IDR' INTO to_coa, to_currency FROM public.chart_of_accounts\n      WHERE code = '1101' AND is_active LIMIT 1;\n  END IF;\n  IF from_coa IS NULL OR to_coa IS NULL OR from_currency IS NULL OR to_currency IS NULL\n     THEN RETURN 'Fund Transfer account or currency cannot be derived'; END IF;\n  IF t.from_amount IS NULL OR t.to_amount IS NULL OR t.exchange_rate IS NULL\n     THEN RETURN 'Fund Transfer is missing an amount or exchange rate'; END IF;\n\n  expected_rate := CASE\n    WHEN from_currency = to_currency THEN 1\n    WHEN from_currency = 'IDR' AND t.to_amount > 0 THEN t.from_amount / t.to_amount\n    WHEN to_currency = 'IDR' AND t.from_amount > 0 THEN t.to_amount / t.from_amount\n  END;\n  IF expected_rate IS NULL OR abs(t.exchange_rate - expected_rate) > 0.000001\n     THEN RETURN 'Fund Transfer exchange rate is inconsistent with its stored amounts'; END IF;\n  -- This is the known unsafe legacy shape: the USD source amount was stored\n  -- in functional journal columns. Do not silently reinterpret posted values.\n  IF from_currency = 'USD' AND to_currency = 'IDR'\n     THEN RETURN 'Legacy USD-source transfer has a functional accounting inconsistency'; END IF;\n\n  SELECT count(*) INTO line_count FROM public.journal_entry_lines WHERE journal_entry_id = j.id;\n  IF line_count <> 2\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id=j.id AND line_number=1 AND COALESCE(debit,0)>0 AND COALESCE(credit,0)=0)\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id=j.id AND line_number=2 AND COALESCE(credit,0)>0 AND COALESCE(debit,0)=0)\n     THEN RETURN 'Posted journal is not a safe two-line transfer'; END IF;\n  IF abs(COALESCE(j.total_debit,0) - t.from_amount) > 0.01\n     OR abs(COALESCE(j.total_credit,0) - t.from_amount) > 0.01\n     OR EXISTS (SELECT 1 FROM public.journal_entry_lines l WHERE l.journal_entry_id=j.id\n       AND ((l.line_number=1 AND abs(COALESCE(l.debit,0)-t.from_amount)>0.01)\n         OR (l.line_number=2 AND abs(COALESCE(l.credit,0)-t.from_amount)>0.01)))\n     THEN RETURN 'Posted journal debit/credit values do not match the Fund Transfer'; END IF;\n\n  -- The Fund Transfer may name a statement line, but this audit never changes\n  -- that row. A missing link is only eligible when there is no ambiguity; a\n  -- multiple-match case is always left for manual review.\n  IF t.from_account_type = 'bank' AND t.from_bank_statement_line_id IS NULL THEN\n    SELECT count(*) INTO candidate_count FROM public.bank_statement_lines b\n      WHERE b.bank_account_id=t.from_bank_account_id AND abs(b.transaction_date-t.transfer_date)<=8\n        AND (COALESCE(b.debit_amount,0)=t.from_amount OR COALESCE(b.credit_amount,0)=t.from_amount);\n    IF candidate_count > 1 THEN RETURN 'Multiple possible From Bank transactions; no link was guessed'; END IF;\n  END IF;\n  IF t.to_account_type = 'bank' AND t.to_bank_statement_line_id IS NULL THEN\n    SELECT count(*) INTO candidate_count FROM public.bank_statement_lines b\n      WHERE b.bank_account_id=t.to_bank_account_id AND abs(b.transaction_date-t.transfer_date)<=8\n        AND (COALESCE(b.debit_amount,0)=t.to_amount OR COALESCE(b.credit_amount,0)=t.to_amount);\n    IF candidate_count > 1 THEN RETURN 'Multiple possible To Bank transactions; no link was guessed'; END IF;\n  END IF;\n\n  -- Explicit links are audited for consistency but never updated.\n  IF t.from_bank_statement_line_id IS NOT NULL AND NOT EXISTS (\n    SELECT 1 FROM public.bank_statement_lines b\n    WHERE b.id=t.from_bank_statement_line_id AND b.bank_account_id=t.from_bank_account_id\n      AND COALESCE(b.debit_amount,0)=t.from_amount\n  ) THEN RETURN 'From Bank statement link does not match the Fund Transfer source'; END IF;\n  IF t.to_bank_statement_line_id IS NOT NULL AND NOT EXISTS (\n    SELECT 1 FROM public.bank_statement_lines b\n    WHERE b.id=t.to_bank_statement_line_id AND b.bank_account_id=t.to_bank_account_id\n      AND COALESCE(b.credit_amount,0)=t.to_amount\n  ) THEN RETURN 'To Bank statement link does not match the Fund Transfer source'; END IF;\n  RETURN NULL;\nEND;\n$$","--\n-- Name: audit_historical_repair_command(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"audit_historical_repair_command\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  INSERT INTO public.audit_logs(table_name, action_type, record_id, old_values, new_values, user_id)\n  VALUES ('finance_historical_repair_commands', 'insert', NEW.id, '{}'::jsonb,\n          to_jsonb(NEW), NEW.requested_by);\n  RETURN NEW;\nEND;\n$$","--\n-- Name: audit_legacy_bank_reconciliation_source_documents(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"audit_legacy_bank_reconciliation_source_documents\\"(\\"p_run_id\\" \\"uuid\\") RETURNS integer\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_count integer;\nDECLARE r record; v_capital_id uuid; v_voucher text;\nBEGIN\n  -- A posted bank receipt whose sole counter-entry is Owner Capital is already\n  -- an explicit operator classification. Create only the missing native source\n  -- document and point the existing journal to it; never repost or alter lines.\n  FOR r IN\n    SELECT je.id journal_id,je.entry_number,je.entry_date,je.description,je.transaction_currency,je.exchange_rate,\n      b.id bank_line_id,b.bank_account_id,upper(COALESCE(b.currency,ba.currency,'IDR')) currency,b.credit_amount,upper(ba.currency) bank_currency\n    FROM public.journal_entries je\n    JOIN public.bank_statement_lines b ON b.id=je.reference_id AND b.matched_entry_id=je.id\n    JOIN public.bank_accounts ba ON ba.id=b.bank_account_id\n    WHERE je.source_module='bank_reconciliation' AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false\n      AND (SELECT count(*) FROM public.journal_entry_lines x WHERE x.journal_entry_id=je.id)=2\n      AND EXISTS(SELECT 1 FROM public.journal_entry_lines x JOIN public.chart_of_accounts c ON c.id=x.account_id\n        WHERE x.journal_entry_id=je.id AND x.credit>0 AND c.code='3100')\n      AND NOT EXISTS(SELECT 1 FROM public.capital_contributions cc WHERE cc.bank_statement_line_id=b.id)\n  LOOP\n    v_capital_id:=gen_random_uuid(); v_voucher:=public.next_capital_contribution_number(r.entry_date);\n    PERFORM set_config('app.finance_metadata_repair','on',true);\n    INSERT INTO public.capital_contributions(id,voucher_number,voucher_date,director_id,contribution_type,bank_account_id,amount,description,\n      journal_entry_id,created_by,transaction_currency,functional_currency,exchange_rate,bank_account_currency,bank_statement_line_id)\n    SELECT v_capital_id,v_voucher,r.entry_date,NULL,'bank_transfer',r.bank_account_id,r.credit_amount,r.description,r.journal_id,\n      je.created_by,r.currency,'IDR',CASE WHEN r.currency='IDR' THEN 1 ELSE r.exchange_rate END,r.bank_currency,r.bank_line_id\n    FROM public.journal_entries je WHERE je.id=r.journal_id;\n    PERFORM set_config('app.finance_metadata_repair','off',true);\n    UPDATE public.journal_entries SET source_module='capital_contribution',reference_id=v_capital_id,reference_number=v_voucher WHERE id=r.journal_id;\n    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n    VALUES(p_run_id,'capital_contribution',v_capital_id,v_voucher,ARRAY['source document','source_module','reference_id','reference_number'],\n      jsonb_build_object('journal_source_module','bank_reconciliation','journal_reference_id',r.bank_line_id),\n      jsonb_build_object('journal_source_module','capital_contribution','journal_reference_id',v_capital_id,'bank_statement_line_id',r.bank_line_id),\n      'The posted two-line bank receipt and sole Owner Capital counter-entry prove the missing Capital Contribution source document');\n    IF r.currency='USD' AND r.exchange_rate IS NULL THEN\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required,status)\n      VALUES(p_run_id,'capital_contribution',v_capital_id,v_voucher,ARRAY['exchange_rate'],\n        'Legacy USD capital contribution has no authoritative historical exchange rate; accounting amounts were preserved unchanged',\n        'Authoritative USD-to-IDR rate and rate source for the contribution date','manual_review');\n    END IF;\n  END LOOP;\n\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required,status)\n  SELECT p_run_id,'journal',je.id,je.entry_number,ARRAY['source_module','reference_id'],\n    CASE WHEN coa.code='2220' THEN 'Legacy Bank Reconciliation Director/Owner Loan journal has no native Loan source document'\n         ELSE 'Legacy Bank Reconciliation loan journal has no native Loan source document' END,\n    'Counterparty name and type, loan terms, and accountant confirmation that this receipt opens a loan; then manually relink to the native Loan document',\n    'manual_review'\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id=je.id AND jel.credit>0\n  JOIN public.chart_of_accounts coa ON coa.id=jel.account_id AND coa.code IN('2210','2220')\n  WHERE je.source_module='bank_reconciliation' AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false\n    AND NOT EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e WHERE e.run_id=p_run_id AND e.document_type='journal' AND e.document_id=je.id);\n  GET DIAGNOSTICS v_count=ROW_COUNT;\n  UPDATE public.finance_historical_repair_runs SET\n    total_records_scanned=(SELECT count(*) FROM public.finance_expenses)+(SELECT count(*) FROM public.receipt_vouchers)\n      +(SELECT count(*) FROM public.payment_vouchers)+(SELECT count(*) FROM public.fund_transfers)\n      +(SELECT count(*) FROM public.journal_entries)+(SELECT count(*) FROM public.bank_statement_lines)\n      +(SELECT count(*) FROM public.loans)+(SELECT count(*) FROM public.loan_transactions)+(SELECT count(*) FROM public.capital_contributions),\n    records_repaired=(SELECT count(DISTINCT (i.document_type,i.document_id)) FROM public.finance_historical_repair_items i WHERE i.run_id=p_run_id\n      AND NOT EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e WHERE e.run_id=p_run_id AND e.status='manual_review'\n        AND e.document_type=i.document_type AND e.document_id=i.document_id)),\n    records_partially_repaired=(SELECT count(DISTINCT (i.document_type,i.document_id)) FROM public.finance_historical_repair_items i WHERE i.run_id=p_run_id\n      AND EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e WHERE e.run_id=p_run_id AND e.status='manual_review' AND e.document_type=i.document_type AND e.document_id=i.document_id)),\n    records_manual_review=(\n    SELECT count(DISTINCT (document_type,document_id)) FROM public.finance_historical_repair_exceptions WHERE run_id=p_run_id AND status='manual_review'\n  ) WHERE id=p_run_id;\n  RETURN v_count;\nEND $$","--\n-- Name: auto_assign_product_code(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_assign_product_code\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF NEW.product_code IS NULL OR NEW.product_code = '' THEN\nNEW.product_code := get_next_product_code();\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: auto_attribute_credit_note_tax_period(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_attribute_credit_note_tax_period\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_period_id uuid;\n  v_year      int;\n  v_month     int;\nBEGIN\n  IF NEW.tax_period_id IS NOT NULL THEN RETURN NEW; END IF;\n  IF NEW.credit_note_date IS NULL THEN RETURN NEW; END IF;\n\n  v_year  := EXTRACT(YEAR  FROM NEW.credit_note_date)::int;\n  v_month := EXTRACT(MONTH FROM NEW.credit_note_date)::int;\n\n  SELECT id INTO v_period_id FROM public.tax_periods\n   WHERE fiscal_year = v_year AND period_month = v_month AND tax_type = 'PPN';\n  IF v_period_id IS NULL THEN\n    v_period_id := public.upsert_tax_period(v_year, v_month, 'PPN');\n  END IF;\n  NEW.tax_period_id := v_period_id;\n  RETURN NEW;\nEND $$","--\n-- Name: auto_attribute_finance_expense_tax_period(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_attribute_finance_expense_tax_period\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_period_id uuid;\n  v_year int;\n  v_month int;\nBEGIN\n  IF NEW.tax_period_id IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n  -- Fire whenever any PPN- or PPh-carrying column is populated, INCLUDING\n  -- the PIB breakdown columns (previously overlooked).\n  IF COALESCE(NEW.ppn_amount,     0) <= 0\n     AND COALESCE(NEW.pph_amount, 0) <= 0\n     AND COALESCE(NEW.pib_ppn_amount, 0) <= 0\n     AND COALESCE(NEW.pib_pph_amount, 0) <= 0 THEN\n    RETURN NEW;\n  END IF;\n  IF NEW.expense_date IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  v_year  := EXTRACT(YEAR  FROM NEW.expense_date)::int;\n  v_month := EXTRACT(MONTH FROM NEW.expense_date)::int;\n\n  SELECT id INTO v_period_id\n  FROM tax_periods\n  WHERE fiscal_year = v_year AND period_month = v_month AND tax_type = 'PPN';\n\n  IF v_period_id IS NULL THEN\n    v_period_id := upsert_tax_period(v_year, v_month, 'PPN');\n  END IF;\n\n  NEW.tax_period_id := v_period_id;\n  RETURN NEW;\nEND $$","--\n-- Name: auto_attribute_payment_voucher_tax_period(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_attribute_payment_voucher_tax_period\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_period_id uuid;\nBEGIN\n  -- Only act when PPh is present and tax_period_id not already set\n  IF NEW.pph_amount IS NULL OR NEW.pph_amount = 0 THEN\n    RETURN NEW;\n  END IF;\n  IF NEW.tax_period_id IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n\n  -- Resolve the PPh type from the tax_code\n  DECLARE\n    v_pph_type text;\n  BEGIN\n    SELECT tc.tax_type INTO v_pph_type\n      FROM tax_codes tc WHERE tc.id = NEW.pph_code_id;\n    IF v_pph_type IS NULL OR v_pph_type = 'PPN' THEN\n      RETURN NEW; -- Not a PPh code — skip\n    END IF;\n\n    v_period_id := upsert_tax_period(\n      EXTRACT(YEAR  FROM NEW.voucher_date)::int,\n      EXTRACT(MONTH FROM NEW.voucher_date)::int,\n      v_pph_type\n    );\n    NEW.tax_period_id := v_period_id;\n  END;\n  RETURN NEW;\nEND $$","--\n-- Name: auto_attribute_purchase_invoice_tax_period(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_attribute_purchase_invoice_tax_period\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_period_id uuid;\n  v_year int;\n  v_month int;\nBEGIN\n  IF NEW.tax_period_id IS NOT NULL THEN RETURN NEW; END IF;\n  IF COALESCE(NEW.tax_amount, 0) <= 0 THEN RETURN NEW; END IF;\n  IF NEW.invoice_date IS NULL THEN RETURN NEW; END IF;\n\n  v_year  := EXTRACT(YEAR  FROM NEW.invoice_date)::int;\n  v_month := EXTRACT(MONTH FROM NEW.invoice_date)::int;\n\n  SELECT id INTO v_period_id FROM tax_periods\n    WHERE fiscal_year = v_year AND period_month = v_month AND tax_type = 'PPN';\n  IF v_period_id IS NULL THEN\n    v_period_id := upsert_tax_period(v_year, v_month, 'PPN');\n  END IF;\n  NEW.tax_period_id := v_period_id;\n  RETURN NEW;\nEND $$","--\n-- Name: auto_attribute_sales_invoice_tax_period(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_attribute_sales_invoice_tax_period\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_period_id uuid;\n  v_year int;\n  v_month int;\nBEGIN\n  -- Only act when there's tax to attribute and no explicit period yet\n  IF NEW.tax_period_id IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n  IF COALESCE(NEW.tax_amount, 0) <= 0 THEN\n    RETURN NEW;\n  END IF;\n  IF NEW.invoice_date IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  v_year  := EXTRACT(YEAR  FROM NEW.invoice_date)::int;\n  v_month := EXTRACT(MONTH FROM NEW.invoice_date)::int;\n\n  SELECT id INTO v_period_id\n  FROM tax_periods\n  WHERE fiscal_year = v_year AND period_month = v_month AND tax_type = 'PPN';\n\n  IF v_period_id IS NULL THEN\n    v_period_id := upsert_tax_period(v_year, v_month, 'PPN');\n  END IF;\n\n  NEW.tax_period_id := v_period_id;\n  RETURN NEW;\nEND $$","--\n-- Name: auto_cancel_import_requirements_on_so_status(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_cancel_import_requirements_on_so_status\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- When SO moves to delivered, closed, or cancelled - cancel pending import requirements\nIF NEW.status IN ('delivered', 'closed', 'cancelled') AND \nOLD.status NOT IN ('delivered', 'closed', 'cancelled') THEN\nUPDATE import_requirements\nSET \nstatus = 'cancelled',\nnotes = COALESCE(notes || ' | ', '') || 'Auto-cancelled: Sales Order is ' || NEW.status::text\nWHERE sales_order_id = NEW.id\nAND status NOT IN ('cancelled', 'received');\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: auto_create_appointment_followup(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_create_appointment_followup\\"() RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'sales', 'manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot create appointment follow-ups', v_role;\nEND IF;\n-- Original body: no-op placeholder (actual follow-up logic is inline in app code).\nEND;\n$$","--\n-- Name: FUNCTION \\"auto_create_appointment_followup\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"auto_create_appointment_followup\\"() IS 'Auto-creates follow-up tasks for completed meetings. Run periodically (e.g., daily via cron or app scheduler).'","--\n-- Name: auto_create_batch_purchase_transaction(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_create_batch_purchase_transaction\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nINSERT INTO inventory_transactions (\nproduct_id,\nbatch_id,\ntransaction_type,\nquantity,\ntransaction_date,\nreference_number,\nnotes,\ncreated_by\n) VALUES (\nNEW.product_id,\nNEW.id,\n'purchase',\nNEW.import_quantity,\nNEW.import_date,\nNEW.batch_number,\n'Batch import: ' || NEW.batch_number,\nNEW.created_by\n);\nRETURN NEW;\nEND;\n$$","--\n-- Name: auto_create_companion_pph_periods(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_create_companion_pph_periods\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF NEW.tax_type = 'PPN' THEN\n    PERFORM upsert_tax_period(NEW.fiscal_year, NEW.period_month, 'PPh21');\n    PERFORM upsert_tax_period(NEW.fiscal_year, NEW.period_month, 'PPh22');\n    PERFORM upsert_tax_period(NEW.fiscal_year, NEW.period_month, 'PPh23');\n    PERFORM upsert_tax_period(NEW.fiscal_year, NEW.period_month, 'PPh4(2)');\n    PERFORM upsert_tax_period(NEW.fiscal_year, NEW.period_month, 'PPh_Unifikasi');\n  END IF;\n  RETURN NEW;\nEND $$","--\n-- Name: auto_create_followup(\\"uuid\\", \\"text\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_create_followup\\"(\\"p_inquiry_id\\" \\"uuid\\", \\"p_action_type\\" \\"text\\", \\"p_user_id\\" \\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nrule_record RECORD;\nnew_reminder_id uuid;\ndue_date timestamptz;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'sales', 'manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot create follow-ups', v_role;\nEND IF;\n\nSELECT * INTO rule_record\nFROM crm_automation_rules\nWHERE is_active = true\nAND trigger_on = 'action_performed'\nAND trigger_action = p_action_type\nAND auto_create_followup = true\nORDER BY priority DESC\nLIMIT 1;\n\nIF rule_record IS NOT NULL THEN\ndue_date := now() + (rule_record.followup_days_offset || ' days')::interval;\n\nINSERT INTO crm_reminders (\ninquiry_id, reminder_type, title, due_date, assigned_to, created_by\n) VALUES (\np_inquiry_id, rule_record.followup_type, rule_record.followup_title,\ndue_date, p_user_id, p_user_id\n) RETURNING id INTO new_reminder_id;\n\nRETURN new_reminder_id;\nEND IF;\n\nRETURN NULL;\nEND;\n$$","--\n-- Name: auto_create_import_expenses(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_create_import_expenses\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_expense_date DATE;\nv_created_by UUID;\nBEGIN\n-- Use import date as expense date\nv_expense_date := NEW.import_date;\nv_created_by := COALESCE(NEW.created_by, auth.uid());\n\n-- Only process if this is a new record or cost fields changed\n-- NOTE: bpom_ski_fees and other_import_costs are EXCLUDED - they're calculated from expenses\nIF (TG_OP = 'INSERT') OR \n(TG_OP = 'UPDATE' AND (\nOLD.duty_bm IS DISTINCT FROM NEW.duty_bm OR\nOLD.ppn_import IS DISTINCT FROM NEW.ppn_import OR\nOLD.pph_import IS DISTINCT FROM NEW.pph_import OR\nOLD.freight_charges IS DISTINCT FROM NEW.freight_charges OR\nOLD.clearing_forwarding IS DISTINCT FROM NEW.clearing_forwarding OR\nOLD.port_charges IS DISTINCT FROM NEW.port_charges OR\nOLD.container_handling IS DISTINCT FROM NEW.container_handling OR\nOLD.transportation IS DISTINCT FROM NEW.transportation OR\nOLD.loading_import IS DISTINCT FROM NEW.loading_import\n)) THEN\n\n-- Delete old expense entries for this container (if update)\n-- BUT ONLY delete expenses that are NOT linked to bank statements\n-- AND NOT user-created bpom_ski_fees or other_import\nIF TG_OP = 'UPDATE' THEN\nDELETE FROM finance_expenses fe\nWHERE fe.import_container_id = NEW.id\nAND fe.expense_category NOT IN ('bpom_ski_fees', 'other_import')\n-- Only delete if NOT referenced by bank_statement_lines\nAND NOT EXISTS (\nSELECT 1 \nFROM bank_statement_lines bsl \nWHERE bsl.matched_expense_id = fe.id\n);\nEND IF;\n\n-- Create expense entry for BM (Duty) - only if not already reconciled\nIF NEW.duty_bm > 0 AND NOT EXISTS (\nSELECT 1 FROM finance_expenses fe\nJOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id\nWHERE fe.import_container_id = NEW.id \nAND fe.expense_category = 'duty_customs'\n) THEN\nINSERT INTO finance_expenses (\nexpense_category,\nexpense_type,\namount,\nexpense_date,\ndescription,\nimport_container_id,\ncreated_by\n) VALUES (\n'duty_customs',\n'import',\nNEW.duty_bm,\nv_expense_date,\n'BM (Duty) - Container ' || NEW.container_ref,\nNEW.id,\nv_created_by\n);\nEND IF;\n\n-- Create expense entry for PPN Import - only if not already reconciled\nIF NEW.ppn_import > 0 AND NOT EXISTS (\nSELECT 1 FROM finance_expenses fe\nJOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id\nWHERE fe.import_container_id = NEW.id \nAND fe.expense_category = 'ppn_import'\n) THEN\nINSERT INTO finance_expenses (\nexpense_category,\nexpense_type,\namount,\nexpense_date,\ndescription,\nimport_container_id,\ncreated_by\n) VALUES (\n'ppn_import',\n'import',\nNEW.ppn_import,\nv_expense_date,\n'PPN Import (11%) - Container ' || NEW.container_ref,\nNEW.id,\nv_created_by\n);\nEND IF;\n\n-- Create expense entry for PPh Import - only if not already reconciled\nIF NEW.pph_import > 0 AND NOT EXISTS (\nSELECT 1 FROM finance_expenses fe\nJOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id\nWHERE fe.import_container_id = NEW.id \nAND fe.expense_category = 'pph_import'\n) THEN\nINSERT INTO finance_expenses (\nexpense_category,\nexpense_type,\namount,\nexpense_date,\ndescription,\nimport_container_id,\ncreated_by\n) VALUES (\n'pph_import',\n'import',\nNEW.pph_import,\nv_expense_date,\n'PPh Import - Container ' || NEW.container_ref,\nNEW.id,\nv_created_by\n);\nEND IF;\n\n-- Create expense entry for Freight - only if not already reconciled\nIF NEW.freight_charges > 0 AND NOT EXISTS (\nSELECT 1 FROM finance_expenses fe\nJOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id\nWHERE fe.import_container_id = NEW.id \nAND fe.expense_category = 'freight_import'\n) THEN\nINSERT INTO finance_expenses (\nexpense_category,\nexpense_type,\namount,\nexpense_date,\ndescription,\nimport_container_id,\ncreated_by\n) VALUES (\n'freight_import',\n'import',\nNEW.freight_charges,\nv_expense_date,\n'Freight Charges - Container ' || NEW.container_ref,\nNEW.id,\nv_created_by\n);\nEND IF;\n\n-- Create expense entry for Clearing & Forwarding - only if not already reconciled\nIF NEW.clearing_forwarding > 0 AND NOT EXISTS (\nSELECT 1 FROM finance_expenses fe\nJOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id\nWHERE fe.import_container_id = NEW.id \nAND fe.expense_category = 'clearing_forwarding'\n) THEN\nINSERT INTO finance_expenses (\nexpense_category,\nexpense_type,\namount,\nexpense_date,\ndescription,\nimport_container_id,\ncreated_by\n) VALUES (\n'clearing_forwarding',\n'import',\nNEW.clearing_forwarding,\nv_expense_date,\n'Clearing & Forwarding - Container ' || NEW.container_ref,\nNEW.id,\nv_created_by\n);\nEND IF;\n\n-- Create expense entry for Port Charges - only if not already reconciled\nIF NEW.port_charges > 0 AND NOT EXISTS (\nSELECT 1 FROM finance_expenses fe\nJOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id\nWHERE fe.import_container_id = NEW.id \nAND fe.expense_category = 'port_charges'\n) THEN\nINSERT INTO finance_expenses (\nexpense_category,\nexpense_type,\namount,\nexpense_date,\ndescription,\nimport_container_id,\ncreated_by\n) VALUES (\n'port_charges',\n'import',\nNEW.port_charges,\nv_expense_date,\n'Port Charges - Container ' || NEW.container_ref,\nNEW.id,\nv_created_by\n);\nEND IF;\n\n-- Create expense entry for Container Handling - only if not already reconciled\nIF NEW.container_handling > 0 AND NOT EXISTS (\nSELECT 1 FROM finance_expenses fe\nJOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id\nWHERE fe.import_container_id = NEW.id \nAND fe.expense_category = 'container_handling'\n) THEN\nINSERT INTO finance_expenses (\nexpense_category,\nexpense_type,\namount,\nexpense_date,\ndescription,\nimport_container_id,\ncreated_by\n) VALUES (\n'container_handling',\n'import',\nNEW.container_handling,\nv_expense_date,\n'Container Handling - Container ' || NEW.container_ref,\nNEW.id,\nv_created_by\n);\nEND IF;\n\n-- Create expense entry for Transportation - only if not already reconciled\nIF NEW.transportation > 0 AND NOT EXISTS (\nSELECT 1 FROM finance_expenses fe\nJOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id\nWHERE fe.import_container_id = NEW.id \nAND fe.expense_category = 'transport_import'\n) THEN\nINSERT INTO finance_expenses (\nexpense_category,\nexpense_type,\namount,\nexpense_date,\ndescription,\nimport_container_id,\ncreated_by\n) VALUES (\n'transport_import',\n'import',\nNEW.transportation,\nv_expense_date,\n'Transportation - Container ' || NEW.container_ref,\nNEW.id,\nv_created_by\n);\nEND IF;\n\n-- Create expense entry for Loading/Unloading - only if not already reconciled\nIF NEW.loading_import > 0 AND NOT EXISTS (\nSELECT 1 FROM finance_expenses fe\nJOIN bank_statement_lines bsl ON bsl.matched_expense_id = fe.id\nWHERE fe.import_container_id = NEW.id \nAND fe.expense_category = 'loading_import'\n) THEN\nINSERT INTO finance_expenses (\nexpense_category,\nexpense_type,\namount,\nexpense_date,\ndescription,\nimport_container_id,\ncreated_by\n) VALUES (\n'loading_import',\n'import',\nNEW.loading_import,\nv_expense_date,\n'Loading/Unloading - Container ' || NEW.container_ref,\nNEW.id,\nv_created_by\n);\nEND IF;\n\n-- NOTE: bpom_ski_fees and other_import expenses are NOT auto-created\n-- They are user-entered and the container fields are calculated FROM them\n\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"auto_create_import_expenses\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"auto_create_import_expenses\\"() IS 'Automatically creates finance_expenses entries when import container costs are entered.\nEach cost type (BM, PPN, PPh, Freight, etc.) creates a separate expense entry.\nThese expenses then flow to accounting via the auto_post_expense_accounting trigger.'","--\n-- Name: auto_create_user_profile(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_create_user_profile\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n      DECLARE\n        v_username text;\n      BEGIN\n        v_username := COALESCE(\n          NULLIF(TRIM(NEW.raw_user_meta_data->>'username'), ''),\n          split_part(NEW.email, '@', 1)\n        );\n        INSERT INTO public.user_profiles (id, username, email, full_name, role, is_active)\n        VALUES (\n          NEW.id,\n          v_username,\n          NEW.email,\n          COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),\n          'sales',\n          true\n        )\n        ON CONFLICT (id) DO NOTHING;\n        RETURN NEW;\n      END $$","--\n-- Name: auto_fill_batch_duty_percent(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_fill_batch_duty_percent\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_product_duty_percent numeric(5,2);\nBEGIN\n-- Get duty % from product if not manually set\nIF NEW.duty_percent IS NULL OR NEW.duty_percent = 0 THEN\nSELECT duty_percent INTO v_product_duty_percent\nFROM products\nWHERE id = NEW.product_id;\n\nNEW.duty_percent := COALESCE(v_product_duty_percent, 0);\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: auto_generate_inquiry_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_generate_inquiry_number\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- If inquiry_number is NULL or empty, generate one\nIF NEW.inquiry_number IS NULL OR NEW.inquiry_number = '' THEN\nNEW.inquiry_number := generate_inquiry_number();\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: auto_generate_sales_order_tasks(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_generate_sales_order_tasks\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_item RECORD;\nv_available_stock numeric;\nv_has_shortage boolean := false;\nv_all_items_sufficient boolean := true;\nv_warehouse_users uuid[];\nv_procurement_users uuid[];\nv_task_deadline timestamptz;\nBEGIN\n-- Only run when status changes to approved\nIF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status != 'approved') THEN\n\n-- Get warehouse and procurement users\nv_warehouse_users := get_users_by_role('warehouse');\nv_procurement_users := get_users_by_role('procurement');\n\n-- Check stock for all items in the order\nFOR v_item IN\nSELECT\nsoi.id,\nsoi.product_id,\nsoi.quantity,\nsoi.reserved_quantity,\np.product_name,\np.current_stock\nFROM sales_order_items soi\nJOIN products p ON p.id = soi.product_id\nWHERE soi.sales_order_id = NEW.id\nLOOP\n-- Calculate available stock (current - already reserved)\nv_available_stock := COALESCE(v_item.current_stock, 0);\n\n-- Check if this item has shortage\nIF v_available_stock < v_item.quantity THEN\nv_has_shortage := true;\nv_all_items_sufficient := false;\n\n-- Create procurement task for shortage (ADVISORY ONLY - errors ignored)\nBEGIN\nv_task_deadline := now() + interval '7 days';\n\nINSERT INTO tasks (\ntitle,\ndescription,\ndeadline,\npriority,\nstatus,\ncreated_by,\nassigned_users,\ntask_type,\ntask_mode,\ntask_origin,\nsales_order_id,\ncustomer_id,\nproduct_id,\ntags,\nauto_priority,\nsystem_metadata\n)\nSELECT\n'Procurement Required: ' || v_item.product_name,\n'Stock shortage detected. Required: ' || v_item.quantity || \n', Available: ' || v_available_stock || \n', Shortage: ' || (v_item.quantity - v_available_stock) || \n'. Please initiate procurement.',\nv_task_deadline,\n'high'::task_priority,\n'to_do'::task_status,\n(SELECT id FROM user_profiles WHERE role = 'admin' LIMIT 1),\nv_procurement_users,\n'system'::task_type_enum,\n'advisory'::task_mode_enum,\n'stock_shortage'::task_origin_enum,\nNEW.id,\nNEW.customer_id,\nv_item.product_id,\nARRAY['procurement', 'stock-shortage', 'system-generated'],\ntrue,\njsonb_build_object(\n'stock_shortage_qty', v_item.quantity - v_available_stock,\n'required_qty', v_item.quantity,\n'available_qty', v_available_stock,\n'product_id', v_item.product_id\n)\n;\nEXCEPTION WHEN OTHERS THEN\n-- Ignore errors - task creation is advisory only\nRAISE NOTICE 'Advisory task creation failed (ignored): %', SQLERRM;\nEND;\nEND IF;\nEND LOOP;\n\n-- If all items have sufficient stock, create dispatch task\nIF v_all_items_sufficient AND v_warehouse_users IS NOT NULL AND array_length(v_warehouse_users, 1) > 0 THEN\nBEGIN\n-- Set deadline to 1 day before expected delivery\nIF NEW.expected_delivery_date IS NOT NULL THEN\nv_task_deadline := (NEW.expected_delivery_date - interval '1 day')::timestamptz;\nELSE\nv_task_deadline := now() + interval '3 days';\nEND IF;\n\nINSERT INTO tasks (\ntitle,\ndescription,\ndeadline,\npriority,\nstatus,\ncreated_by,\nassigned_users,\ntask_type,\ntask_mode,\ntask_origin,\nsales_order_id,\ncustomer_id,\ntags,\nauto_priority,\nsystem_metadata\n)\nSELECT\n'Prepare Dispatch for Sales Order ' || NEW.so_number,\n'Stock is available. Prepare items for dispatch as per sales order requirements. Expected delivery: ' || \nCOALESCE(NEW.expected_delivery_date::text, 'TBD'),\nv_task_deadline,\ncalculate_task_priority(v_task_deadline),\n'to_do'::task_status,\n(SELECT id FROM user_profiles WHERE role = 'admin' LIMIT 1),\nv_warehouse_users,\n'system'::task_type_enum,\n'advisory'::task_mode_enum,\n'sales_order'::task_origin_enum,\nNEW.id,\nNEW.customer_id,\nARRAY['dispatch', 'warehouse', 'system-generated'],\ntrue,\njsonb_build_object(\n'so_number', NEW.so_number,\n'expected_delivery_date', NEW.expected_delivery_date\n)\n;\nEXCEPTION WHEN OTHERS THEN\n-- Ignore errors - task creation is advisory only\nRAISE NOTICE 'Advisory task creation failed (ignored): %', SQLERRM;\nEND;\nEND IF;\n\nEND IF;\n\n-- Always return NEW to ensure sales order is not affected\nRETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n-- Catch-all: ensure sales order processing never fails due to task generation\nRAISE NOTICE 'Sales order task generation failed (ignored): %', SQLERRM;\nRETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"auto_generate_sales_order_tasks\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"auto_generate_sales_order_tasks\\"() IS 'Advisory task generator for sales orders - errors do not block sales order processing'","--\n-- Name: auto_generate_transaction_hash(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_generate_transaction_hash\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\nNEW.transaction_hash := generate_bank_transaction_hash(\nNEW.bank_account_id,\nNEW.transaction_date,\nNEW.debit_amount,\nNEW.credit_amount,\nNEW.description,\nNEW.running_balance,\nNEW.upload_id\n);\nRETURN NEW;\nEND;\n$$","--\n-- Name: auto_match_bank_statement_line(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_match_bank_statement_line\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF NEW.matched_petty_cash_id IS NOT NULL\n     OR NEW.matched_expense_id IS NOT NULL\n     OR NEW.matched_receipt_id IS NOT NULL\n     OR NEW.matched_payment_id IS NOT NULL\n     OR NEW.matched_fund_transfer_id IS NOT NULL\n     OR NEW.matched_tax_payment_id IS NOT NULL\n     OR NEW.matched_entry_id IS NOT NULL\n     OR COALESCE(NEW.manually_unlinked, false) THEN\n    RETURN NEW;\n  END IF;\n\n  NEW.reconciliation_status := COALESCE(NEW.reconciliation_status, 'unmatched');\n  NEW.matching_status := COALESCE(NEW.matching_status, 'none');\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"auto_match_bank_statement_line\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"auto_match_bank_statement_line\\"() IS 'Conservative auto-match: auto-links only when exactly one native document candidate exists. Never chooses newest arbitrary candidate. Ambiguous same-date/same-amount rows remain Unmatched for deterministic/manual linking.'","--\n-- Name: auto_match_bank_transactions_smart(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_match_bank_transactions_smart\\"() RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_line        RECORD;\nv_matched_id  UUID;\nv_match_type  TEXT;\nv_match_count INTEGER;\nv_role        text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot run auto-match', v_role;\nEND IF;\n\nFOR v_line IN\nSELECT * FROM bank_statement_lines\nWHERE matching_status = 'none'\nAND matched_expense_id IS NULL AND matched_receipt_id IS NULL\nAND matched_petty_cash_id IS NULL AND matched_fund_transfer_id IS NULL\nLOOP\nv_matched_id := NULL; v_match_type := NULL;\n\nIF v_line.debit_amount > 0 THEN\nSELECT id INTO v_matched_id FROM finance_expenses\nWHERE ABS(amount - v_line.debit_amount) < 0.01\nAND ABS(EXTRACT(EPOCH FROM (expense_date - v_line.transaction_date)) / 86400) <= 3\nAND id NOT IN (SELECT matched_expense_id FROM bank_statement_lines WHERE matching_status = 'confirmed' AND matched_expense_id IS NOT NULL)\nORDER BY ABS(EXTRACT(EPOCH FROM (expense_date - v_line.transaction_date))) LIMIT 1;\n\nIF v_matched_id IS NOT NULL THEN\nSELECT COUNT(*) INTO v_match_count FROM finance_expenses\nWHERE ABS(amount - v_line.debit_amount) < 0.01\nAND ABS(EXTRACT(EPOCH FROM (expense_date - v_line.transaction_date)) / 86400) <= 3\nAND id NOT IN (SELECT matched_expense_id FROM bank_statement_lines WHERE matching_status = 'confirmed' AND matched_expense_id IS NOT NULL);\nUPDATE bank_statement_lines\nSET matched_expense_id = v_matched_id, matching_status = 'suggested',\nreconciliation_status = CASE WHEN v_match_count > 1 THEN 'conflict' ELSE 'suggested' END,\nnotes = CASE WHEN v_match_count > 1 THEN 'Multiple possible matches - please verify' ELSE 'Auto-suggested match - needs confirmation' END\nWHERE id = v_line.id;\nCONTINUE;\nEND IF;\n\nSELECT id INTO v_matched_id FROM petty_cash_transactions\nWHERE transaction_type = 'expense' AND ABS(amount - v_line.debit_amount) < 0.01\nAND ABS(EXTRACT(EPOCH FROM (transaction_date - v_line.transaction_date)) / 86400) <= 3\nAND id NOT IN (SELECT matched_petty_cash_id FROM bank_statement_lines WHERE matching_status = 'confirmed' AND matched_petty_cash_id IS NOT NULL)\nORDER BY ABS(EXTRACT(EPOCH FROM (transaction_date - v_line.transaction_date))) LIMIT 1;\n\nIF v_matched_id IS NOT NULL THEN\nUPDATE bank_statement_lines\nSET matched_petty_cash_id = v_matched_id, matching_status = 'suggested',\nreconciliation_status = 'suggested', notes = 'Auto-suggested match - needs confirmation'\nWHERE id = v_line.id;\nCONTINUE;\nEND IF;\nEND IF;\n\nIF v_line.credit_amount > 0 THEN\nSELECT rv.id INTO v_matched_id FROM receipt_vouchers rv\nWHERE ABS(rv.amount - v_line.credit_amount) < 0.01\nAND ABS(EXTRACT(EPOCH FROM (rv.receipt_date - v_line.transaction_date)) / 86400) <= 3\nAND rv.id NOT IN (SELECT matched_receipt_id FROM bank_statement_lines WHERE matching_status = 'confirmed' AND matched_receipt_id IS NOT NULL)\nORDER BY ABS(EXTRACT(EPOCH FROM (rv.receipt_date - v_line.transaction_date))) LIMIT 1;\n\nIF v_matched_id IS NOT NULL THEN\nUPDATE bank_statement_lines\nSET matched_receipt_id = v_matched_id, matching_status = 'suggested',\nreconciliation_status = 'suggested', notes = 'Auto-suggested match - needs confirmation'\nWHERE id = v_line.id;\nCONTINUE;\nEND IF;\nEND IF;\nEND LOOP;\nEND;\n$$","--\n-- Name: auto_match_smart(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_match_smart\\"() RETURNS TABLE(\\"matched_count\\" integer, \\"suggested_count\\" integer, \\"skipped_count\\" integer)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_line public.bank_statement_lines%ROWTYPE;\n  v_bank_amount numeric;\n  v_direction text;\n  v_bank_text text;\n  v_candidates jsonb;\n  v_candidate jsonb;\n  v_candidate_count integer;\n  v_expense public.finance_expenses%ROWTYPE;\n  v_payload jsonb;\n  v_matched integer := 0;\n  v_suggested integer := 0;\n  v_skipped integer := 0;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n\n  FOR v_line IN\n    SELECT b.*\n    FROM public.bank_statement_lines b\n    WHERE b.reconciliation_status = 'unmatched'\n      AND NOT COALESCE(b.manually_unlinked, false)\n      AND b.matched_expense_id IS NULL\n      AND b.matched_receipt_id IS NULL\n      AND b.matched_payment_id IS NULL\n      AND b.matched_petty_cash_id IS NULL\n      AND b.matched_fund_transfer_id IS NULL\n      AND b.matched_tax_payment_id IS NULL\n      AND b.matched_entry_id IS NULL\n      AND NOT EXISTS (\n        SELECT 1 FROM public.bank_statement_allocations a\n        WHERE a.bank_statement_line_id = b.id\n      )\n    ORDER BY b.transaction_date, b.id\n    FOR UPDATE SKIP LOCKED\n  LOOP\n    v_bank_amount := CASE\n      WHEN COALESCE(v_line.credit_amount, 0) > 0 THEN v_line.credit_amount\n      ELSE v_line.debit_amount\n    END;\n    v_direction := CASE\n      WHEN COALESCE(v_line.credit_amount, 0) > 0 THEN 'credit'\n      ELSE 'debit'\n    END;\n    v_bank_text := concat_ws(' ', v_line.reference, v_line.description);\n\n    IF COALESCE(v_bank_amount, 0) <= 0.01 THEN\n      v_skipped := v_skipped + 1;\n      CONTINUE;\n    END IF;\n\n    -- First resolve documents which already have the authoritative bank leg:\n    -- expenses, posted payment vouchers (including AP/Purchase allocations),\n    -- receipts/sales, fund transfers, petty cash and tax payments all enter\n    -- through vw_finance_document_settlements.\n    WITH source_candidates AS MATERIALIZED (\n      SELECT s.*,\n             GREATEST(\n               s.settlement_amount - COALESCE((\n                 SELECT sum(a.allocation_amount)\n                 FROM public.bank_statement_allocations a\n                 WHERE a.document_type = s.document_type\n                   AND a.document_id = s.document_id\n                   AND a.journal_entry_id = s.journal_entry_id\n               ), 0),\n               0\n             ) AS remaining_amount,\n             concat_ws(\n               ' ', s.document_number, je.reference_number, je.description,\n               (SELECT string_agg(l.description, ' ' ORDER BY l.line_number)\n                FROM public.journal_entry_lines l\n                WHERE l.journal_entry_id = s.journal_entry_id)\n             ) AS document_text\n      FROM public.vw_finance_document_settlements s\n      JOIN public.journal_entries je ON je.id = s.journal_entry_id\n      WHERE s.bank_account_id = v_line.bank_account_id\n        AND s.direction = v_direction\n        AND abs(v_line.transaction_date - s.settlement_date) <= 7\n    ), scored AS MATERIALIZED (\n      SELECT c.*,\n             public.finance_bank_match_text_score(v_bank_text, c.document_text) AS text_score,\n             CASE\n               WHEN length(regexp_replace(lower(COALESCE(c.document_number, '')), '[^a-z0-9]+', '', 'g')) >= 5\n                AND position(\n                  regexp_replace(lower(c.document_number), '[^a-z0-9]+', '', 'g')\n                  IN regexp_replace(lower(v_bank_text), '[^a-z0-9]+', '', 'g')\n                ) > 0 THEN 1\n               WHEN public.finance_bank_match_text_score(v_bank_text, c.document_text) >= 2 THEN 2\n               WHEN public.finance_bank_match_text_score(v_bank_text, c.document_text) >= 1\n                AND v_line.transaction_date = c.settlement_date THEN 3\n               ELSE NULL\n             END AS match_tier\n      FROM source_candidates c\n      WHERE abs(c.remaining_amount - v_bank_amount) <= 1\n    ), best AS (\n      SELECT s.*\n      FROM scored s\n      WHERE s.match_tier IS NOT NULL\n        AND s.match_tier = (SELECT min(match_tier) FROM scored WHERE match_tier IS NOT NULL)\n    )\n    SELECT COALESCE(jsonb_agg(to_jsonb(best) ORDER BY match_tier, settlement_date, document_type, document_id), '[]'::jsonb)\n    INTO v_candidates\n    FROM best;\n\n    v_candidate_count := jsonb_array_length(v_candidates);\n    IF v_candidate_count = 1 THEN\n      v_candidate := v_candidates->0;\n      BEGIN\n        PERFORM public.link_bank_statement_line(\n          v_line.id,\n          v_candidate->>'document_type',\n          (v_candidate->>'document_id')::uuid,\n          'supplier',\n          v_bank_amount\n        );\n        UPDATE public.bank_statement_lines\n        SET notes = 'Canonical auto-match: existing bank journal; tier '\n                    || (v_candidate->>'match_tier')\n                    || ', text score ' || (v_candidate->>'text_score'),\n            manually_unlinked = false\n        WHERE id = v_line.id;\n        v_matched := v_matched + 1;\n        CONTINUE;\n      EXCEPTION WHEN OTHERS THEN\n        -- The subtransaction rolls back every attempted allocation/update for\n        -- this line. Other independent lines may still be considered.\n        v_skipped := v_skipped + 1;\n        CONTINUE;\n      END;\n    ELSIF v_candidate_count > 1 THEN\n      -- Equal-strength candidates are deliberately left fully unmatched.\n      v_skipped := v_skipped + 1;\n      CONTINUE;\n    END IF;\n\n    -- A directly-recorded approved Expense can initially be an AP posting\n    -- because no bank line was selected on entry. Only reclassify that same\n    -- journal to the selected bank when a unique, exact remaining amount also\n    -- has business-text evidence. The existing approved-expense atomic edit\n    -- command preserves the journal identity and creates the allocation.\n    IF v_direction = 'debit' THEN\n      WITH expense_candidates AS MATERIALIZED (\n        SELECT fe.id AS document_id,\n               fe.voucher_number AS document_number,\n               fe.expense_date AS settlement_date,\n               je.id AS journal_entry_id,\n               public.calculate_finance_expense_payable(fe.id)\n                 - COALESCE(fe.paid_amount, 0) AS remaining_amount,\n               concat_ws(\n                 ' ', fe.voucher_number, fe.invoice_number, fe.payment_reference,\n                 fe.description, ic.container_ref, supplier.company_name,\n                 staff.full_name, je.reference_number,\n                 je.description,\n                 (SELECT string_agg(l.description, ' ' ORDER BY l.line_number)\n                  FROM public.journal_entry_lines l\n                  WHERE l.journal_entry_id = je.id)\n               ) AS document_text\n        FROM public.finance_expenses fe\n        LEFT JOIN public.import_containers ic ON ic.id = fe.import_container_id\n        LEFT JOIN public.suppliers supplier ON supplier.id = fe.supplier_id\n        LEFT JOIN public.finance_staff_master staff ON staff.id = fe.staff_id\n        JOIN LATERAL (\n          SELECT j.*\n          FROM public.journal_entries j\n          WHERE j.source_module IN ('expense', 'expenses')\n            AND (j.reference_id = fe.id OR j.reference_number = 'EXP-' || fe.id::text)\n            AND j.is_posted\n            AND NOT COALESCE(j.is_reversed, false)\n          ORDER BY j.created_at DESC, j.id DESC\n          LIMIT 1\n        ) je ON true\n        WHERE fe.approval_status = 'approved'\n          AND fe.payment_method IS NULL\n          AND fe.bank_account_id IS NULL\n          AND COALESCE(fe.paid_amount, 0) <= 0.01\n          AND COALESCE(fe.pph_paid_amount, 0) <= 0.01\n          AND abs(v_line.transaction_date - fe.expense_date) <= 7\n          AND NOT EXISTS (\n            SELECT 1 FROM public.voucher_allocations va\n            WHERE va.finance_expense_id = fe.id\n          )\n          AND NOT EXISTS (\n            SELECT 1 FROM public.bank_statement_allocations a\n            WHERE a.document_type = 'expense' AND a.document_id = fe.id\n          )\n      ), scored AS MATERIALIZED (\n        SELECT c.*,\n               public.finance_bank_match_text_score(v_bank_text, c.document_text) AS text_score,\n               CASE\n                 WHEN length(regexp_replace(lower(COALESCE(c.document_number, '')), '[^a-z0-9]+', '', 'g')) >= 5\n                  AND position(\n                    regexp_replace(lower(c.document_number), '[^a-z0-9]+', '', 'g')\n                    IN regexp_replace(lower(v_bank_text), '[^a-z0-9]+', '', 'g')\n                  ) > 0 THEN 1\n                 WHEN public.finance_bank_match_text_score(v_bank_text, c.document_text) >= 2 THEN 2\n                 WHEN public.finance_bank_match_text_score(v_bank_text, c.document_text) >= 1\n                  AND v_line.transaction_date = c.settlement_date THEN 3\n                 ELSE NULL\n               END AS match_tier\n        FROM expense_candidates c\n        WHERE abs(c.remaining_amount - v_bank_amount) <= 1\n      ), best AS (\n        SELECT s.*\n        FROM scored s\n        WHERE s.match_tier IS NOT NULL\n          AND s.match_tier = (SELECT min(match_tier) FROM scored WHERE match_tier IS NOT NULL)\n      )\n      SELECT COALESCE(jsonb_agg(to_jsonb(best) ORDER BY match_tier, settlement_date, document_id), '[]'::jsonb)\n      INTO v_candidates\n      FROM best;\n\n      v_candidate_count := jsonb_array_length(v_candidates);\n      IF v_candidate_count = 1 THEN\n        v_candidate := v_candidates->0;\n        SELECT * INTO v_expense\n        FROM public.finance_expenses\n        WHERE id = (v_candidate->>'document_id')::uuid\n        FOR UPDATE;\n\n        v_payload := to_jsonb(v_expense) || jsonb_build_object(\n          'payment_method', 'bank_transfer',\n          'bank_account_id', v_line.bank_account_id,\n          'paid_by', 'bank',\n          'payment_reference', COALESCE(NULLIF(v_line.reference, ''), v_expense.payment_reference),\n          'transaction_currency', upper(COALESCE(v_line.currency, v_expense.transaction_currency, 'IDR')),\n          'currency_code', upper(COALESCE(v_line.currency, v_expense.currency_code, 'IDR')),\n          'functional_currency', 'IDR',\n          'exchange_rate', CASE\n            WHEN upper(COALESCE(v_line.currency, v_expense.transaction_currency, 'IDR')) = 'IDR' THEN 1\n            ELSE v_expense.exchange_rate\n          END\n        );\n\n        BEGIN\n          PERFORM public.edit_approved_finance_expense_atomic(\n            v_expense.id,\n            v_payload,\n            v_line.id,\n            v_bank_amount\n          );\n          UPDATE public.bank_statement_lines\n          SET notes = 'Canonical auto-match: unique existing Expense; tier '\n                      || (v_candidate->>'match_tier')\n                      || ', text score ' || (v_candidate->>'text_score'),\n              manually_unlinked = false\n          WHERE id = v_line.id;\n          v_matched := v_matched + 1;\n        EXCEPTION WHEN OTHERS THEN\n          v_skipped := v_skipped + 1;\n        END;\n      ELSIF v_candidate_count > 1 THEN\n        v_skipped := v_skipped + 1;\n      END IF;\n    END IF;\n  END LOOP;\n\n  RETURN QUERY SELECT v_matched, v_suggested, v_skipped;\nEND;\n$$","--\n-- Name: FUNCTION \\"auto_match_smart\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"auto_match_smart\\"() IS 'Canonical atomic matcher: unique bank-journal documents first; unique exact directly-recorded Expenses only with date/account/direction and business-text evidence. Ambiguity remains unmatched.'","--\n-- Name: auto_match_smart_legacy(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_match_smart_legacy\\"() RETURNS TABLE(\\"matched_count\\" integer, \\"suggested_count\\" integer, \\"skipped_count\\" integer)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_line public.bank_statement_lines%rowtype;\n  v_candidate record;\n  v_amount numeric;\n  v_direction text;\n  v_score integer;\n  v_matched integer:=0;\n  v_suggested integer:=0;\n  v_skipped integer:=0;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n\n  FOR v_line IN\n    SELECT * FROM public.bank_statement_lines b\n     WHERE b.reconciliation_status='unmatched'\n       AND b.matched_expense_id IS NULL AND b.matched_receipt_id IS NULL\n       AND b.matched_payment_id IS NULL AND b.matched_petty_cash_id IS NULL\n       AND b.matched_fund_transfer_id IS NULL AND b.matched_tax_payment_id IS NULL\n       AND b.matched_entry_id IS NULL\n     ORDER BY b.transaction_date,b.id\n  LOOP\n    v_amount:=CASE WHEN COALESCE(v_line.credit_amount,0)>0\n                   THEN v_line.credit_amount ELSE v_line.debit_amount END;\n    v_direction:=CASE WHEN COALESCE(v_line.credit_amount,0)>0 THEN 'credit' ELSE 'debit' END;\n\n    SELECT s.*,\n           abs(s.settlement_amount-v_amount) amount_diff,\n           abs(v_line.transaction_date::date-s.settlement_date) date_diff\n      INTO v_candidate\n      FROM public.vw_finance_document_settlements s\n     WHERE s.bank_account_id=v_line.bank_account_id\n       AND s.direction=v_direction\n       AND abs(v_line.transaction_date::date-s.settlement_date)<=7\n       AND abs(s.settlement_amount-v_amount)<=greatest(1,v_amount*0.05)\n       AND NOT EXISTS (\n         SELECT 1 FROM public.bank_statement_lines used\n          WHERE used.id<>v_line.id AND used.matched_entry_id=s.journal_entry_id\n            AND used.bank_account_id=s.bank_account_id\n            AND (CASE WHEN COALESCE(used.credit_amount,0)>0 THEN 'credit' ELSE 'debit' END)=s.direction\n       )\n     ORDER BY abs(s.settlement_amount-v_amount),\n              abs(v_line.transaction_date::date-s.settlement_date),s.document_type,s.document_id\n     LIMIT 1;\n\n    IF NOT FOUND THEN CONTINUE; END IF;\n    v_score:=CASE\n      WHEN v_candidate.amount_diff<0.01 THEN 70\n      WHEN v_candidate.amount_diff<=100 THEN 55\n      WHEN v_candidate.amount_diff<=1000 THEN 40\n      ELSE 25 END\n      + CASE WHEN v_candidate.date_diff=0 THEN 20\n             WHEN v_candidate.date_diff<=1 THEN 15\n             WHEN v_candidate.date_diff<=3 THEN 10 ELSE 5 END\n      + 10; -- exact bank account and direction are mandatory above\n\n    IF v_score<70 THEN CONTINUE; END IF;\n    UPDATE public.bank_statement_lines SET\n      matched_expense_id=CASE WHEN v_candidate.document_type='expense' THEN v_candidate.document_id ELSE NULL END,\n      matched_receipt_id=CASE WHEN v_candidate.document_type='receipt' THEN v_candidate.document_id ELSE NULL END,\n      matched_payment_id=CASE WHEN v_candidate.document_type='payment' THEN v_candidate.document_id ELSE NULL END,\n      matched_fund_transfer_id=CASE WHEN v_candidate.document_type='fund_transfer' THEN v_candidate.document_id ELSE NULL END,\n      matched_petty_cash_id=CASE WHEN v_candidate.document_type='petty_cash' THEN v_candidate.document_id ELSE NULL END,\n      matched_tax_payment_id=CASE WHEN v_candidate.document_type='tax_payment' THEN v_candidate.document_id ELSE NULL END,\n      matched_entry_id=v_candidate.journal_entry_id,\n      reconciliation_status=CASE WHEN v_score>=85 THEN 'matched' ELSE 'needs_review' END,\n      matching_status=CASE WHEN v_score>=85 THEN 'confirmed' ELSE 'suggested' END,\n      matched_at=now(),matched_by=auth.uid(),manually_unlinked=false,\n      notes='Canonical settlement auto-match (confidence: '||v_score||'%)'\n    WHERE id=v_line.id;\n\n    IF v_candidate.document_type='expense' THEN\n      PERFORM public.recalculate_expense_payment_state(v_candidate.document_id);\n    END IF;\n    IF v_score>=85 THEN v_matched:=v_matched+1; ELSE v_suggested:=v_suggested+1; END IF;\n  END LOOP;\n  RETURN QUERY SELECT v_matched,v_suggested,v_skipped;\nEND;\n$$","--\n-- Name: auto_post_expense_accounting(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_post_expense_accounting\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_expense_account_id uuid;\n  v_payment_account_id uuid;\n  v_journal_id uuid;\n  v_active_count integer;\n  v_description text;\n  v_credit_desc text;\n  v_category_label text;\n  v_bm_account_id uuid;\n  v_ppn_account_id uuid;\n  v_pph_account_id uuid;\n  v_stamp_duty_account_id uuid;\n  v_bank_charge_acc_id uuid;\n  v_line_num integer;\n  v_net_payment numeric(18,2);\n  v_total numeric(18,2);\n  v_bank_charges numeric(18,2);\nBEGIN\n  IF NEW.approval_status <> 'approved' THEN RETURN NEW; END IF;\n\n  IF TG_OP='UPDATE' AND OLD.approval_status='approved' THEN\n    IF ROW(\n      OLD.amount,OLD.expense_category,OLD.expense_date,OLD.description,\n      OLD.payment_method,OLD.bank_account_id,OLD.pib_bm_amount,OLD.pib_ppn_amount,\n      OLD.pib_pph_amount,OLD.ppn_amount,OLD.pph_amount,OLD.stamp_duty_amount,\n      OLD.fixed_asset_account_id,COALESCE(OLD.bank_charges_amount,0),\n      OLD.transaction_currency,OLD.exchange_rate,OLD.supplier_id\n    ) IS NOT DISTINCT FROM ROW(\n      NEW.amount,NEW.expense_category,NEW.expense_date,NEW.description,\n      NEW.payment_method,NEW.bank_account_id,NEW.pib_bm_amount,NEW.pib_ppn_amount,\n      NEW.pib_pph_amount,NEW.ppn_amount,NEW.pph_amount,NEW.stamp_duty_amount,\n      NEW.fixed_asset_account_id,COALESCE(NEW.bank_charges_amount,0),\n      NEW.transaction_currency,NEW.exchange_rate,NEW.supplier_id\n    ) THEN\n      RETURN NEW;\n    END IF;\n  END IF;\n\n  SELECT count(*), (array_agg(id ORDER BY created_at DESC,id DESC))[1]\n    INTO v_active_count,v_journal_id\n    FROM public.journal_entries\n   WHERE source_module IN('expense','expenses')\n     AND (reference_id=NEW.id OR reference_number='EXP-'||NEW.id::text)\n     AND is_posted=true AND NOT COALESCE(is_reversed,false);\n\n  IF v_active_count>1 THEN\n    RAISE EXCEPTION 'Expense % has multiple active journals; edit is blocked',NEW.id;\n  END IF;\n  IF TG_OP='UPDATE' AND OLD.approval_status='approved' AND v_active_count<>1 THEN\n    RAISE EXCEPTION 'Approved expense % must have exactly one active journal before edit',NEW.id;\n  END IF;\n  IF v_journal_id IS NOT NULL THEN\n    PERFORM 1 FROM public.journal_entries WHERE id=v_journal_id FOR UPDATE;\n    DELETE FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;\n  END IF;\n\n  IF NEW.payment_method='cash' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;\n  ELSIF NEW.payment_method='petty_cash' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='1102' LIMIT 1;\n  ELSIF NEW.payment_method = 'bank_transfer' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n  ELSIF NEW.payment_method IS NOT NULL AND NEW.bank_account_id IS NOT NULL THEN\n    SELECT coa_id INTO v_payment_account_id FROM public.bank_accounts WHERE id=NEW.bank_account_id;\n  ELSIF NEW.payment_method IS NULL THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n  END IF;\n  IF v_payment_account_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot post expense %: the selected payment/AP account is not configured',NEW.id;\n  END IF;\n\n  IF NEW.expense_category='pib_import' THEN\n    v_bm_account_id:=public.get_expense_account_id('duty_customs');\n    v_ppn_account_id:=public.get_expense_account_id('ppn_import');\n    v_pph_account_id:=public.get_expense_account_id('pph_import');\n    IF COALESCE(NEW.pib_bm_amount,0)>0 AND v_bm_account_id IS NULL THEN RAISE EXCEPTION 'Import Duty account is missing'; END IF;\n    IF COALESCE(NEW.pib_ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Import account is missing'; END IF;\n    IF COALESCE(NEW.pib_pph_amount,0)>0 AND v_pph_account_id IS NULL THEN RAISE EXCEPTION 'PPh Import account is missing'; END IF;\n    v_total:=NEW.amount;\n    v_journal_id:=public.upsert_expense_journal_header_in_place(\n      v_journal_id,NEW.id,NEW.expense_date,COALESCE(NEW.description,'PIB Import Payment'),\n      'pib_import',v_total,NEW.created_by);\n    v_line_num:=1;\n    IF COALESCE(NEW.pib_bm_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)\n      VALUES(v_journal_id,v_line_num,v_bm_account_id,NEW.pib_bm_amount,0,'PIB - Import Duty (BM) [landed cost]');\n      v_line_num:=v_line_num+1;\n    END IF;\n    IF COALESCE(NEW.pib_ppn_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)\n      VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.pib_ppn_amount,0,'PIB - PPN Import (Input VAT)');\n      v_line_num:=v_line_num+1;\n    END IF;\n    IF COALESCE(NEW.pib_pph_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)\n      VALUES(v_journal_id,v_line_num,v_pph_account_id,NEW.pib_pph_amount,0,'PIB - PPh 22 Dibayar Dimuka');\n      v_line_num:=v_line_num+1;\n    END IF;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)\n    VALUES(v_journal_id,v_line_num,v_payment_account_id,0,NEW.amount,'PIB - Payment ['||COALESCE(NEW.description,'')||']');\n    RETURN NEW;\n  END IF;\n\n  IF NEW.expense_category='fixed_asset' THEN\n    v_expense_account_id:=NEW.fixed_asset_account_id;\n    IF v_expense_account_id IS NULL THEN RAISE EXCEPTION 'A posting Fixed Asset account is required'; END IF;\n    SELECT id INTO v_ppn_account_id FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;\n    IF COALESCE(NEW.ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Masukan account 1150 is missing'; END IF;\n    v_description:=COALESCE(NEW.description,'Fixed Asset Purchase');\n    v_total:=NEW.amount+COALESCE(NEW.ppn_amount,0);\n    v_journal_id:=public.upsert_expense_journal_header_in_place(\n      v_journal_id,NEW.id,NEW.expense_date,v_description,'fixed_asset',v_total,NEW.created_by);\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)\n    VALUES(v_journal_id,1,v_expense_account_id,NEW.amount,0,v_description);\n    v_line_num:=2;\n    IF COALESCE(NEW.ppn_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)\n      VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.ppn_amount,0,'PPN Masukan - '||v_description);\n      v_line_num:=v_line_num+1;\n    END IF;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)\n    VALUES(v_journal_id,v_line_num,v_payment_account_id,0,v_total,v_description);\n    RETURN NEW;\n  END IF;\n\n  v_expense_account_id:=CASE WHEN public.is_capitalizable_landed_cost_category(NEW.expense_category) THEN (SELECT id FROM public.chart_of_accounts WHERE code='1130' LIMIT 1) ELSE public.get_expense_account_id(NEW.expense_category) END;\n  IF v_expense_account_id IS NULL THEN RAISE EXCEPTION 'No expense account is mapped for %',NEW.expense_category; END IF;\n  v_category_label:=initcap(replace(NEW.expense_category,'_',' '));\n  v_description:=COALESCE(NEW.description,NEW.expense_category);\n  v_credit_desc:=COALESCE(substring(NEW.description FROM '^[^\\\\n]+'),NEW.expense_category)||' ['||v_category_label||']';\n  SELECT id INTO v_ppn_account_id FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;\n  SELECT id INTO v_pph_account_id FROM public.chart_of_accounts WHERE code='2132' LIMIT 1;\n  SELECT id INTO v_stamp_duty_account_id FROM public.chart_of_accounts WHERE code='6950' LIMIT 1;\n  IF COALESCE(NEW.ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Masukan account 1150 is missing'; END IF;\n  IF COALESCE(NEW.pph_amount,0)>0 AND v_pph_account_id IS NULL THEN RAISE EXCEPTION 'PPh Payable account 2132 is missing'; END IF;\n  IF COALESCE(NEW.stamp_duty_amount,0)>0 AND v_stamp_duty_account_id IS NULL THEN RAISE EXCEPTION 'Stamp Duty account 6950 is missing'; END IF;\n  v_bank_charges:=CASE WHEN NEW.expense_category='utilities' THEN COALESCE(NEW.bank_charges_amount,0) ELSE 0 END;\n  IF v_bank_charges>0 THEN\n    v_bank_charge_acc_id:=public.get_expense_account_id('bank_charges');\n    IF v_bank_charge_acc_id IS NULL THEN RAISE EXCEPTION 'Bank Charges account is missing'; END IF;\n  END IF;\n  v_net_payment:=NEW.amount+COALESCE(NEW.ppn_amount,0)-COALESCE(NEW.pph_amount,0)+COALESCE(NEW.stamp_duty_amount,0)+v_bank_charges;\n  v_total:=NEW.amount+COALESCE(NEW.ppn_amount,0)+COALESCE(NEW.stamp_duty_amount,0)+v_bank_charges;\n  v_journal_id:=public.upsert_expense_journal_header_in_place(\n    v_journal_id,NEW.id,NEW.expense_date,v_description,NEW.expense_category,v_total,NEW.created_by);\n  v_line_num:=1;\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n  VALUES(v_journal_id,v_line_num,v_expense_account_id,NEW.amount,0,v_credit_desc,NEW.supplier_id);\n  v_line_num:=v_line_num+1;\n  IF COALESCE(NEW.ppn_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n    VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.ppn_amount,0,'PPN Masukan - '||v_description,NEW.supplier_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n  IF COALESCE(NEW.stamp_duty_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n    VALUES(v_journal_id,v_line_num,v_stamp_duty_account_id,NEW.stamp_duty_amount,0,'Bea Meterai - '||v_description,NEW.supplier_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n  IF v_bank_charges>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n    VALUES(v_journal_id,v_line_num,v_bank_charge_acc_id,v_bank_charges,0,'Bank charges ['||v_category_label||']',NEW.supplier_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n  IF COALESCE(NEW.pph_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n    VALUES(v_journal_id,v_line_num,v_pph_account_id,0,NEW.pph_amount,'PPh Ditahan - '||v_description,NEW.supplier_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n  VALUES(v_journal_id,v_line_num,v_payment_account_id,0,v_net_payment,v_credit_desc,NEW.supplier_id);\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"auto_post_expense_accounting\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"auto_post_expense_accounting\\"() IS 'Auto-posts journal entries for finance_expenses.\nUPDATE path: deletes ALL existing JEs for the expense (not just one) before recreating,\nso pre-existing duplicates are always cleared.\npib_import: 4-line split (Dr BM/1130 inventory, Dr PPN Masukan/1150, Dr PPh22/1155, Cr Bank).\nAll other categories: standard 2-line (Dr expense account, Cr payment account).'","--\n-- Name: auto_post_fund_transfer_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_post_fund_transfer_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_from_coa uuid; v_to_coa uuid; v_from_currency text; v_to_currency text;\n  v_from numeric; v_to numeric; v_functional numeric; v_rate numeric;\n  v_je uuid; v_entry text; v_desc text; v_bank_amount numeric;\nBEGIN\n  IF NEW.journal_entry_id IS NOT NULL THEN RETURN NEW; END IF;\n  IF EXISTS (SELECT 1 FROM public.journal_entries WHERE reference_number=NEW.transfer_number\n             AND source_module='fund_transfers') THEN\n    SELECT id INTO v_je FROM public.journal_entries WHERE reference_number=NEW.transfer_number\n      AND source_module='fund_transfers' ORDER BY created_at DESC LIMIT 1;\n    UPDATE public.fund_transfers SET journal_entry_id=v_je WHERE id=NEW.id;\n    RETURN NEW;\n  END IF;\n\n  IF NEW.from_account_type='bank' THEN\n    SELECT coa_id,upper(currency) INTO v_from_coa,v_from_currency FROM public.bank_accounts WHERE id=NEW.from_bank_account_id;\n  ELSIF NEW.from_account_type='petty_cash' THEN\n    SELECT id,'IDR' INTO v_from_coa,v_from_currency FROM public.chart_of_accounts WHERE code='1102' LIMIT 1;\n  ELSE\n    SELECT id,'IDR' INTO v_from_coa,v_from_currency FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;\n  END IF;\n  IF NEW.to_account_type='bank' THEN\n    SELECT coa_id,upper(currency) INTO v_to_coa,v_to_currency FROM public.bank_accounts WHERE id=NEW.to_bank_account_id;\n  ELSIF NEW.to_account_type='petty_cash' THEN\n    SELECT id,'IDR' INTO v_to_coa,v_to_currency FROM public.chart_of_accounts WHERE code='1102' LIMIT 1;\n  ELSE\n    SELECT id,'IDR' INTO v_to_coa,v_to_currency FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;\n  END IF;\n  IF v_from_coa IS NULL OR v_to_coa IS NULL THEN RAISE EXCEPTION 'Cannot determine transfer accounts'; END IF;\n  v_from:=round(COALESCE(NEW.from_amount,NEW.amount),2);\n  v_to:=round(COALESCE(NEW.to_amount,NEW.amount),2);\n  IF v_from<=0 OR v_to<=0 THEN RAISE EXCEPTION 'Transfer amounts must be positive'; END IF;\n  v_rate:=CASE WHEN v_from_currency=v_to_currency THEN 1 ELSE COALESCE(NEW.exchange_rate,v_to/v_from) END;\n  IF v_rate<=0 THEN RAISE EXCEPTION 'Transfer exchange rate must be positive'; END IF;\n  v_functional:=CASE WHEN v_from_currency='IDR' THEN v_from WHEN v_to_currency='IDR' THEN v_to ELSE v_from END;\n  v_desc:='Fund Transfer '||NEW.transfer_number;\n  IF v_from_currency<>v_to_currency THEN v_desc:=v_desc||' (FX: '||v_from_currency||' → '||v_to_currency||')'; END IF;\n  IF NEW.description IS NOT NULL THEN v_desc:=v_desc||' - '||NEW.description; END IF;\n  SELECT public.generate_journal_entry_number() INTO v_entry;\n  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,\n    description,total_debit,total_credit,is_posted,created_by,transaction_currency,functional_currency,exchange_rate)\n  VALUES(v_entry,NEW.transfer_date,'fund_transfers',NEW.id,NEW.transfer_number,v_desc,v_functional,v_functional,true,NEW.created_by,\n    CASE WHEN v_from_currency=v_to_currency THEN v_from_currency ELSE NULL END,'IDR',v_rate)\n  RETURNING id INTO v_je;\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,\n    transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n  VALUES\n    (v_je,1,v_to_coa,v_functional,0,'Transfer In: '||NEW.transfer_number,v_to_currency,v_to,0,'IDR',v_rate),\n    (v_je,2,v_from_coa,0,v_functional,'Transfer Out: '||NEW.transfer_number,v_from_currency,0,v_from,'IDR',v_rate);\n  UPDATE public.fund_transfers SET journal_entry_id=v_je,status='posted',posted_at=now(),posted_by=NEW.created_by WHERE id=NEW.id;\n\n  IF NEW.from_bank_statement_line_id IS NOT NULL THEN\n    SELECT COALESCE(NULLIF(debit_amount,0),credit_amount,0) INTO v_bank_amount FROM public.bank_statement_lines WHERE id=NEW.from_bank_statement_line_id FOR UPDATE;\n    IF v_bank_amount IS NULL OR abs(v_bank_amount-v_from)>0.01 THEN RAISE EXCEPTION 'Transfer-out bank evidence amount mismatch'; END IF;\n    INSERT INTO public.bank_statement_allocations(bank_statement_line_id,document_type,document_id,journal_entry_id,allocation_amount,payment_kind,created_by)\n      VALUES(NEW.from_bank_statement_line_id,'fund_transfer',NEW.id,v_je,round(v_bank_amount,2),'supplier',NEW.created_by)\n      ON CONFLICT (bank_statement_line_id,document_type,document_id,payment_kind) DO NOTHING;\n    UPDATE public.bank_statement_lines SET matched_fund_transfer_id=NEW.id,matched_entry_id=v_je,reconciliation_status='matched',matched_at=now(),matched_by=NEW.created_by WHERE id=NEW.from_bank_statement_line_id;\n  END IF;\n  IF NEW.to_bank_statement_line_id IS NOT NULL THEN\n    SELECT COALESCE(NULLIF(debit_amount,0),credit_amount,0) INTO v_bank_amount FROM public.bank_statement_lines WHERE id=NEW.to_bank_statement_line_id FOR UPDATE;\n    IF v_bank_amount IS NULL OR abs(v_bank_amount-v_to)>0.01 THEN RAISE EXCEPTION 'Transfer-in bank evidence amount mismatch'; END IF;\n    INSERT INTO public.bank_statement_allocations(bank_statement_line_id,document_type,document_id,journal_entry_id,allocation_amount,payment_kind,created_by)\n      VALUES(NEW.to_bank_statement_line_id,'fund_transfer',NEW.id,v_je,round(v_bank_amount,2),'supplier',NEW.created_by)\n      ON CONFLICT (bank_statement_line_id,document_type,document_id,payment_kind) DO NOTHING;\n    UPDATE public.bank_statement_lines SET matched_fund_transfer_id=NEW.id,matched_entry_id=v_je,reconciliation_status='matched',matched_at=now(),matched_by=NEW.created_by WHERE id=NEW.to_bank_statement_line_id;\n  END IF;\n  RETURN NEW;\nEND $$","--\n-- Name: FUNCTION \\"auto_post_fund_transfer_journal\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"auto_post_fund_transfer_journal\\"() IS 'Posts new transfers with functional IDR and explicit transaction-currency bank legs; creates canonical allocations only when evidenced bank lines are supplied.'","--\n-- Name: auto_post_loan_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_post_loan_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_je_id uuid; v_bank_coa_id uuid; v_loan_coa_id uuid; v_description text;\n  v_currency text; v_bank_currency text; v_rate numeric; v_functional_amount numeric;\nBEGIN\n  IF COALESCE(current_setting('app.finance_metadata_repair',true),'off')='on' THEN RETURN NEW; END IF;\n  SELECT coa_id,upper(currency) INTO v_bank_coa_id,v_bank_currency\n  FROM public.bank_accounts WHERE id=NEW.bank_account_id AND is_active=true;\n  IF v_bank_coa_id IS NULL THEN RAISE EXCEPTION 'Loan bank account is missing or has no active GL account'; END IF;\n  v_currency:=upper(COALESCE(NEW.transaction_currency,NEW.currency,v_bank_currency,'IDR'));\n  v_rate:=CASE WHEN v_currency='IDR' THEN 1 ELSE NEW.exchange_rate END;\n  IF v_currency NOT IN('IDR','USD') OR v_rate IS NULL OR v_rate<=0 OR (v_currency='USD' AND v_rate<=1) THEN\n    RAISE EXCEPTION 'Loan currency or exchange rate is invalid';\n  END IF;\n  IF v_bank_currency<>v_currency THEN RAISE EXCEPTION 'Loan currency % does not match bank currency %',v_currency,v_bank_currency; END IF;\n  v_loan_coa_id:=NEW.coa_id;\n  IF v_loan_coa_id IS NULL THEN\n    SELECT id INTO v_loan_coa_id FROM public.chart_of_accounts\n    WHERE code=CASE WHEN NEW.loan_type='taken' THEN '2210' ELSE '1310' END\n      AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1;\n  END IF;\n  IF v_loan_coa_id IS NULL THEN RAISE EXCEPTION 'Loan control account is not configured'; END IF;\n  NEW.transaction_currency:=v_currency; NEW.currency:=v_currency; NEW.functional_currency:='IDR';\n  NEW.bank_account_currency:=v_bank_currency; NEW.exchange_rate:=v_rate;\n  NEW.outstanding_balance:=NEW.principal_amount;\n  v_functional_amount:=round(NEW.principal_amount*v_rate,2);\n  v_description:=COALESCE(NULLIF(NEW.description,''),CASE WHEN NEW.loan_type='taken' THEN 'Loan received from ' ELSE 'Loan given to ' END||NEW.counterparty_name);\n  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,\n    total_debit,total_credit,is_posted,posted_at,posted_by,created_by,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n  VALUES(public.generate_journal_entry_number(),NEW.loan_date,'loans',NEW.id,NEW.loan_number,v_description,\n    v_functional_amount,v_functional_amount,true,now(),NEW.created_by,NEW.created_by,v_currency,'IDR',v_rate,true)\n  RETURNING id INTO v_je_id;\n  IF NEW.loan_type='taken' THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,\n      transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n    VALUES(v_je_id,1,v_bank_coa_id,v_description,v_functional_amount,0,v_currency,NEW.principal_amount,0,'IDR',v_rate),\n          (v_je_id,2,v_loan_coa_id,v_description,0,v_functional_amount,v_currency,0,NEW.principal_amount,'IDR',v_rate);\n  ELSE\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,\n      transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n    VALUES(v_je_id,1,v_loan_coa_id,v_description,v_functional_amount,0,v_currency,NEW.principal_amount,0,'IDR',v_rate),\n          (v_je_id,2,v_bank_coa_id,v_description,0,v_functional_amount,v_currency,0,NEW.principal_amount,'IDR',v_rate);\n  END IF;\n  NEW.journal_entry_id:=v_je_id;\n  RETURN NEW;\nEND $$","--\n-- Name: auto_post_loan_transaction_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_post_loan_transaction_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_loan public.loans%ROWTYPE; v_je_id uuid; v_bank_coa_id uuid; v_bank_currency text;\n  v_loan_coa_id uuid; v_interest_coa_id uuid; v_currency text; v_rate numeric;\n  v_amount numeric; v_principal numeric; v_interest numeric; v_description text; v_line integer:=0;\nBEGIN\n  IF COALESCE(current_setting('app.finance_metadata_repair',true),'off')='on' THEN RETURN NEW; END IF;\n  SELECT * INTO v_loan FROM public.loans WHERE id=NEW.loan_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Loan not found'; END IF;\n  SELECT coa_id,upper(currency) INTO v_bank_coa_id,v_bank_currency FROM public.bank_accounts\n    WHERE id=COALESCE(NEW.bank_account_id,v_loan.bank_account_id) AND is_active=true;\n  IF v_bank_coa_id IS NULL THEN RAISE EXCEPTION 'Repayment bank account is missing or has no active GL account'; END IF;\n  v_currency:=upper(COALESCE(NEW.transaction_currency,v_loan.transaction_currency,v_loan.currency,'IDR'));\n  v_rate:=CASE WHEN v_currency='IDR' THEN 1 ELSE COALESCE(NEW.exchange_rate,v_loan.exchange_rate) END;\n  IF v_currency<>upper(COALESCE(v_loan.transaction_currency,v_loan.currency)) OR v_currency<>v_bank_currency THEN\n    RAISE EXCEPTION 'Repayment, loan and bank currencies must match';\n  END IF;\n  IF v_rate IS NULL OR v_rate<=0 OR (v_currency='USD' AND v_rate<=1) THEN RAISE EXCEPTION 'Repayment exchange rate is invalid'; END IF;\n  IF NEW.transaction_type IN('repayment','interest_payment') AND NEW.principal_amount>v_loan.outstanding_balance THEN\n    RAISE EXCEPTION 'Principal repayment exceeds outstanding balance';\n  END IF;\n  IF abs(NEW.amount-(NEW.principal_amount+NEW.interest_amount))>0.01 THEN RAISE EXCEPTION 'Principal plus interest must equal repayment amount'; END IF;\n  v_loan_coa_id:=v_loan.coa_id;\n  IF v_loan_coa_id IS NULL THEN SELECT id INTO v_loan_coa_id FROM public.chart_of_accounts WHERE code=CASE WHEN v_loan.loan_type='taken' THEN '2210' ELSE '1310' END AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1; END IF;\n  v_interest_coa_id:=v_loan.interest_coa_id;\n  IF v_interest_coa_id IS NULL THEN SELECT id INTO v_interest_coa_id FROM public.chart_of_accounts WHERE code=CASE WHEN v_loan.loan_type='taken' THEN '7200' ELSE '4920' END AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1; END IF;\n  v_amount:=round(NEW.amount*v_rate,2); v_principal:=round(NEW.principal_amount*v_rate,2); v_interest:=round(NEW.interest_amount*v_rate,2);\n  v_description:=COALESCE(NULLIF(NEW.description,''),'Loan repayment - '||v_loan.counterparty_name);\n  NEW.transaction_currency:=v_currency; NEW.functional_currency:='IDR'; NEW.bank_account_currency:=v_bank_currency; NEW.exchange_rate:=v_rate; NEW.status:='posted';\n  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,\n    is_posted,posted_at,posted_by,created_by,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n  VALUES(public.generate_journal_entry_number(),NEW.transaction_date,'loan_transactions',NEW.id,NEW.transaction_number,v_description,v_amount,v_amount,\n    true,now(),NEW.created_by,NEW.created_by,v_currency,'IDR',v_rate,true) RETURNING id INTO v_je_id;\n  IF v_loan.loan_type='taken' THEN\n    IF NEW.principal_amount>0 THEN v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_loan_coa_id,v_description,v_principal,0,v_currency,NEW.principal_amount,0,'IDR',v_rate); END IF;\n    IF NEW.interest_amount>0 THEN v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_interest_coa_id,v_description,v_interest,0,v_currency,NEW.interest_amount,0,'IDR',v_rate); END IF;\n    v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_bank_coa_id,v_description,0,v_amount,v_currency,0,NEW.amount,'IDR',v_rate);\n  ELSE\n    v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_bank_coa_id,v_description,v_amount,0,v_currency,NEW.amount,0,'IDR',v_rate);\n    IF NEW.principal_amount>0 THEN v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_loan_coa_id,v_description,0,v_principal,v_currency,0,NEW.principal_amount,'IDR',v_rate); END IF;\n    IF NEW.interest_amount>0 THEN v_line:=v_line+1; INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate) VALUES(v_je_id,v_line,v_interest_coa_id,v_description,0,v_interest,v_currency,0,NEW.interest_amount,'IDR',v_rate); END IF;\n  END IF;\n  NEW.journal_entry_id:=v_je_id;\n  RETURN NEW;\nEND $$","--\n-- Name: auto_reconcile_tax_payment(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_reconcile_tax_payment\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_tax_payment_id uuid;\n  v_is_tax_je      boolean := false;\nBEGIN\n  IF NEW.is_matched = true\n     AND (OLD.is_matched IS DISTINCT FROM NEW.is_matched)\n     AND NEW.journal_entry_id IS NOT NULL\n  THEN\n    -- Only act on tax_payment JEs\n    SELECT EXISTS (\n      SELECT 1 FROM journal_entries\n       WHERE id = NEW.journal_entry_id\n         AND source_module = 'tax_payment'\n    ) INTO v_is_tax_je;\n\n    IF v_is_tax_je THEN\n      SELECT id INTO v_tax_payment_id\n        FROM tax_payments\n       WHERE journal_entry_id = NEW.journal_entry_id\n         AND status = 'posted';\n\n      IF v_tax_payment_id IS NOT NULL THEN\n        UPDATE tax_payments\n           SET status = 'reconciled', updated_at = now()\n         WHERE id = v_tax_payment_id;\n      END IF;\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND $$","--\n-- Name: auto_reconcile_tax_payment_from_bsl(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_reconcile_tax_payment_from_bsl\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_tax_payment_id uuid;\n  v_is_tax_je      boolean := false;\nBEGIN\n  -- ── MATCH path ──────────────────────────────────────────────────────────\n  -- Only fire when status flips to 'matched' AND matched_entry_id is set.\n  -- Also guard that the matched_entry_id belongs to a tax_payment JE — this\n  -- prevents the trigger from ever touching expense/receipt/petty-cash BSLs.\n  IF NEW.reconciliation_status = 'matched'\n     AND (OLD.reconciliation_status IS DISTINCT FROM NEW.reconciliation_status)\n     AND NEW.matched_entry_id IS NOT NULL\n  THEN\n    SELECT EXISTS (\n      SELECT 1 FROM journal_entries\n       WHERE id = NEW.matched_entry_id\n         AND source_module = 'tax_payment'\n    ) INTO v_is_tax_je;\n\n    IF v_is_tax_je THEN\n      SELECT id INTO v_tax_payment_id\n        FROM tax_payments\n       WHERE journal_entry_id = NEW.matched_entry_id\n         AND status IN ('posted', 'draft');\n\n      IF v_tax_payment_id IS NOT NULL THEN\n        UPDATE tax_payments\n           SET status = 'reconciled', updated_at = now()\n         WHERE id = v_tax_payment_id;\n        -- Write typed FK for symmetry with other modules\n        NEW.matched_tax_payment_id := v_tax_payment_id;\n      END IF;\n    END IF;\n  END IF;\n\n  -- ── UNMATCH path ─────────────────────────────────────────────────────────\n  -- Only act when the line had a typed tax_payment FK and now loses it\n  -- (or the status reverts from 'matched'). Never touch lines whose\n  -- matched_tax_payment_id was never set.\n  IF (NEW.reconciliation_status IS DISTINCT FROM 'matched'\n      OR NEW.matched_entry_id IS NULL)\n     AND OLD.matched_tax_payment_id IS NOT NULL\n     AND NEW.matched_tax_payment_id IS NOT DISTINCT FROM OLD.matched_tax_payment_id\n  THEN\n    -- Verify the payment was actually reconciled (not already reset by delete_tax_payment)\n    UPDATE tax_payments\n       SET status = 'posted', updated_at = now()\n     WHERE id = OLD.matched_tax_payment_id\n       AND status = 'reconciled';\n\n    NEW.matched_tax_payment_id := NULL;\n  END IF;\n\n  RETURN NEW;\nEND $$","--\n-- Name: auto_snapshot_company_profile(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_snapshot_company_profile\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'pg_catalog', 'public'\n    AS $$\nBEGIN\n  NEW.company_snapshot := public.get_current_company_profile();\n  IF NEW.company_snapshot IS NULL THEN\n    RAISE EXCEPTION 'Cannot create document: no effective company profile exists';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"auto_snapshot_company_profile\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"auto_snapshot_company_profile\\"() IS 'Authoritative snapshot source for new documents. Always reads the effective company_profiles row and never changes existing snapshots.'","--\n-- Name: auto_update_pipeline_status(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"auto_update_pipeline_status\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- If all requirements are fulfilled and status is 'in_progress', move to 'follow_up'\nIF check_inquiry_requirements_fulfilled(NEW.id) AND NEW.pipeline_status = 'in_progress' THEN\nNEW.pipeline_status := 'follow_up';\nEND IF;\n\n-- If marking as lost, set lost_at timestamp\nIF NEW.pipeline_status = 'lost' AND OLD.pipeline_status != 'lost' THEN\nNEW.lost_at := now();\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: broker_reimbursement_expense_base(\\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"broker_reimbursement_expense_base\\"(\\"p_item\\" \\"jsonb\\") RETURNS numeric\n    LANGUAGE \\"sql\\" IMMUTABLE\n    SET \\"search_path\\" TO 'pg_catalog', 'public'\n    AS $$\n  SELECT public.broker_reimbursement_line_total(p_item)\n       - COALESCE((p_item->>'ppn_amount')::numeric, 0)\n$$","--\n-- Name: broker_reimbursement_line_total(\\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"broker_reimbursement_line_total\\"(\\"p_item\\" \\"jsonb\\") RETURNS numeric\n    LANGUAGE \\"sql\\" IMMUTABLE\n    SET \\"search_path\\" TO 'pg_catalog', 'public'\n    AS $$\n  SELECT CASE\n    WHEN COALESCE((p_item->>'invoice_amount_authoritative')::boolean, false)\n      THEN COALESCE((p_item->>'amount')::numeric, 0)\n    WHEN COALESCE((p_item->>'amount')::numeric, 0) <> 0\n      THEN COALESCE((p_item->>'amount')::numeric, 0)\n    ELSE COALESCE((p_item->>'dpp_amount')::numeric, 0)\n       + COALESCE((p_item->>'ppn_amount')::numeric, 0)\n  END\n$$","--\n-- Name: bsl_recalc_expense_paid_state(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"bsl_recalc_expense_paid_state\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF OLD.matched_expense_id IS NOT NULL THEN\n      PERFORM public.recalculate_expense_payment_state(OLD.matched_expense_id);\n    END IF;\n    RETURN OLD;\n  END IF;\n\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.matched_expense_id IS NOT NULL THEN\n      PERFORM public.recalculate_expense_payment_state(NEW.matched_expense_id);\n    END IF;\n    RETURN NEW;\n  END IF;\n\n  IF NEW.matched_expense_id IS DISTINCT FROM OLD.matched_expense_id THEN\n    IF OLD.matched_expense_id IS NOT NULL THEN\n      PERFORM public.recalculate_expense_payment_state(OLD.matched_expense_id);\n    END IF;\n    IF NEW.matched_expense_id IS NOT NULL THEN\n      PERFORM public.recalculate_expense_payment_state(NEW.matched_expense_id);\n    END IF;\n  ELSIF NEW.matched_expense_id IS NOT NULL\n    AND (\n      NEW.payment_kind IS DISTINCT FROM OLD.payment_kind\n      OR NEW.debit_amount IS DISTINCT FROM OLD.debit_amount\n      OR NEW.credit_amount IS DISTINCT FROM OLD.credit_amount\n    ) THEN\n    PERFORM public.recalculate_expense_payment_state(NEW.matched_expense_id);\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: bsl_sync_reconciliation_status(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"bsl_sync_reconciliation_status\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_has_allocation boolean;\nBEGIN\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.bank_statement_allocations\n    WHERE bank_statement_line_id = NEW.id\n  ) INTO v_has_allocation;\n\n  IF NEW.matched_expense_id IS NOT NULL\n     OR NEW.matched_receipt_id IS NOT NULL\n     OR NEW.matched_payment_id IS NOT NULL\n     OR NEW.matched_fund_transfer_id IS NOT NULL\n     OR NEW.matched_petty_cash_id IS NOT NULL\n     OR NEW.matched_tax_payment_id IS NOT NULL\n     OR NEW.matched_entry_id IS NOT NULL\n     OR v_has_allocation THEN\n    IF NEW.reconciliation_status IS NULL OR NEW.reconciliation_status = 'unmatched' THEN\n      NEW.reconciliation_status := 'matched';\n    END IF;\n  ELSE\n    NEW.reconciliation_status := 'unmatched';\n    NEW.matching_status := 'none';\n    NEW.matched_at := NULL;\n    NEW.matched_by := NULL;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: ca_report_journal_lines(\\"date\\", \\"date\\", \\"uuid\\"[]); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"ca_report_journal_lines\\"(\\"p_date_from\\" \\"date\\", \\"p_date_to\\" \\"date\\", \\"p_account_ids\\" \\"uuid\\"[] DEFAULT NULL::\\"uuid\\"[]) RETURNS TABLE(\\"journal_entry_id\\" \\"uuid\\", \\"entry_date\\" \\"date\\", \\"entry_number\\" \\"text\\", \\"source_module\\" \\"text\\", \\"reference_number\\" \\"text\\", \\"entry_description\\" \\"text\\", \\"line_account_id\\" \\"uuid\\", \\"line_number\\" integer, \\"debit\\" numeric, \\"credit\\" numeric, \\"line_description\\" \\"text\\")\n    LANGUAGE \\"sql\\" STABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\nSELECT\nje.id            AS journal_entry_id,\nje.entry_date,\nje.entry_number,\nje.source_module,\nje.reference_number,\nje.description   AS entry_description,\njel.account_id   AS line_account_id,\njel.line_number,\njel.debit,\njel.credit,\njel.description  AS line_description\nFROM journal_entries je\nJOIN journal_entry_lines jel ON jel.journal_entry_id = je.id\nWHERE je.is_posted = true\nAND (je.is_reversed = false OR je.is_reversed IS NULL)\nAND je.entry_date >= p_date_from\nAND je.entry_date <= p_date_to\nAND (p_account_ids IS NULL OR jel.account_id = ANY(p_account_ids))\nORDER BY je.entry_date, je.entry_number, jel.line_number;\n$$","--\n-- Name: calculate_balance_between_dates(\\"uuid\\", \\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_balance_between_dates\\"(\\"p_bank_account_id\\" \\"uuid\\", \\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS TABLE(\\"net_change\\" numeric)\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT\nCOALESCE(SUM(credit_amount), 0) - COALESCE(SUM(debit_amount), 0) AS net_change\nFROM bank_statement_lines\nWHERE bank_account_id = p_bank_account_id\nAND transaction_date >= p_start_date\nAND transaction_date < p_end_date;\nEND;\n$$","--\n-- Name: calculate_container_landed_cost_pool(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_container_landed_cost_pool\\"(\\"p_container_id\\" \\"uuid\\") RETURNS numeric\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE v_expenses numeric := 0; v_petty numeric := 0; v_other numeric := 0;\nBEGIN\n  SELECT COALESCE(other_import_costs,0) INTO v_other FROM import_containers WHERE id=p_container_id;\n  SELECT COALESCE(SUM(CASE\n    WHEN fe.expense_category='import_broker' THEN\n      fe.amount-COALESCE(fe.ppn_amount,0)\n      +COALESCE((SELECT SUM(\n        CASE WHEN (x->>'invoice_amount_authoritative')::boolean=true THEN (x->>'amount')::numeric\n             ELSE COALESCE(NULLIF((x->>'amount')::numeric,0),(x->>'dpp_amount')::numeric+COALESCE((x->>'ppn_amount')::numeric,0)) END\n        -COALESCE((x->>'ppn_amount')::numeric,0)) FROM jsonb_array_elements(fe.broker_items) x),0)\n      +COALESCE(fe.stamp_duty_amount,0)\n    ELSE fe.amount END),0)\n    INTO v_expenses\n    FROM finance_expenses fe\n   WHERE fe.import_container_id=p_container_id\n     AND public.is_capitalizable_landed_cost_category(fe.expense_category)\n     AND COALESCE(fe.include_in_landed_cost,true);\n  SELECT COALESCE(SUM(amount),0) INTO v_petty FROM petty_cash_transactions\n   WHERE import_container_id=p_container_id\n     AND public.is_capitalizable_landed_cost_category(expense_category)\n     AND COALESCE(include_in_landed_cost,true);\n  RETURN v_expenses+v_petty+v_other;\nEND; $$","--\n-- Name: calculate_customs_broker_invoice(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_customs_broker_invoice\\"(\\"p_expense_id\\" \\"uuid\\") RETURNS TABLE(\\"reimbursement_total\\" numeric, \\"broker_invoice_amount\\" numeric, \\"expense_total\\" numeric, \\"recoverable_input_ppn\\" numeric, \\"pph23_withheld\\" numeric, \\"final_cash_payable\\" numeric, \\"line_totals\\" \\"jsonb\\")\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT\n    COALESCE((SELECT SUM(public.broker_reimbursement_line_total(i))\n      FROM jsonb_array_elements(COALESCE(fe.broker_items,'[]'::jsonb)) i),0),\n    COALESCE(fe.amount,0),\n    COALESCE(fe.amount,0)\n      + COALESCE((SELECT SUM(public.broker_reimbursement_line_total(i))\n        FROM jsonb_array_elements(COALESCE(fe.broker_items,'[]'::jsonb)) i),0)\n      + COALESCE(fe.stamp_duty_amount,0),\n    COALESCE(fe.ppn_amount,0) + COALESCE((SELECT SUM(COALESCE((i->>'ppn_amount')::numeric,0))\n      FROM jsonb_array_elements(COALESCE(fe.broker_items,'[]'::jsonb)) i),0),\n    COALESCE(fe.pph_amount,0),\n    COALESCE(fe.amount,0)\n      + COALESCE((SELECT SUM(public.broker_reimbursement_line_total(i))\n        FROM jsonb_array_elements(COALESCE(fe.broker_items,'[]'::jsonb)) i),0)\n      + COALESCE(fe.stamp_duty_amount,0)\n      - COALESCE(fe.pph_amount,0),\n    COALESCE((SELECT jsonb_agg(public.broker_reimbursement_line_total(i) ORDER BY ord)\n      FROM jsonb_array_elements(COALESCE(fe.broker_items,'[]'::jsonb)) WITH ORDINALITY x(i,ord)),'[]'::jsonb)\n  FROM finance_expenses fe\n  WHERE fe.id = p_expense_id AND fe.expense_category = 'import_broker'\n$$","--\n-- Name: calculate_expense_settlement_amount(\\"text\\", numeric, numeric, numeric, numeric, numeric, \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_expense_settlement_amount\\"(\\"p_category\\" \\"text\\", \\"p_amount\\" numeric, \\"p_ppn\\" numeric, \\"p_pph\\" numeric, \\"p_stamp\\" numeric, \\"p_bank_charges\\" numeric, \\"p_broker_items\\" \\"jsonb\\") RETURNS numeric\n    LANGUAGE \\"sql\\" IMMUTABLE PARALLEL SAFE\n    SET \\"search_path\\" TO 'pg_catalog', 'public'\n    AS $$\n  SELECT CASE\n    WHEN p_category='pib_import' THEN COALESCE(p_amount,0)\n    WHEN p_category='import_broker' THEN COALESCE(p_amount,0)\n      +COALESCE((SELECT sum(CASE\n        WHEN item->>'amount' IS NOT NULL AND NULLIF(item->>'amount','')::numeric<>0\n          THEN NULLIF(item->>'amount','')::numeric\n        ELSE COALESCE(NULLIF(item->>'dpp_amount','')::numeric,0)\n             +COALESCE(NULLIF(item->>'ppn_amount','')::numeric,0) END)\n        FROM jsonb_array_elements(COALESCE(p_broker_items,'[]'::jsonb)) item),0)\n      +COALESCE(p_stamp,0)-COALESCE(p_pph,0)\n    ELSE COALESCE(p_amount,0)+COALESCE(p_ppn,0)-COALESCE(p_pph,0)+COALESCE(p_stamp,0)\n      +CASE WHEN p_category='utilities' THEN COALESCE(p_bank_charges,0) ELSE 0 END\n  END;\n$$","--\n-- Name: calculate_finance_expense_payable(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_finance_expense_payable\\"(\\"p_expense_id\\" \\"uuid\\") RETURNS numeric\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT CASE\n    WHEN fe.expense_category = 'import_broker'\n      THEN COALESCE((SELECT c.final_cash_payable\n                     FROM public.vw_customs_broker_accounting c\n                    WHERE c.expense_id=fe.id),0)\n    ELSE COALESCE(fe.amount,0)\n       + COALESCE(fe.ppn_amount,0)\n       - COALESCE(fe.pph_amount,0)\n       + COALESCE(fe.stamp_duty_amount,0)\n  END\n  FROM public.finance_expenses fe\n WHERE fe.id=p_expense_id;\n$$","--\n-- Name: calculate_import_cost_allocation(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_import_cost_allocation\\"(\\"p_header_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_header RECORD;\nv_item RECORD;\nv_total_fob DECIMAL(18,2);\nv_total_qty DECIMAL(18,3);\nv_item_count INTEGER;\nv_allocation_factor DECIMAL(10,6);\nBEGIN\n-- Get header details\nSELECT * INTO v_header\nFROM import_cost_headers\nWHERE id = p_header_id;\n\nIF NOT FOUND THEN\nRAISE EXCEPTION 'Import cost header not found';\nEND IF;\n\n-- Get totals for allocation base\nSELECT \nSUM(total_fob_value),\nSUM(quantity),\nCOUNT(*)\nINTO v_total_fob, v_total_qty, v_item_count\nFROM import_cost_items\nWHERE cost_header_id = p_header_id;\n\n-- Update each item based on allocation method\nFOR v_item IN\nSELECT * FROM import_cost_items WHERE cost_header_id = p_header_id\nLOOP\n-- Calculate allocation factor based on method\nIF v_header.allocation_method = 'by_value' THEN\nv_allocation_factor := v_item.total_fob_value / NULLIF(v_total_fob, 0);\nELSIF v_header.allocation_method = 'by_quantity' THEN\nv_allocation_factor := v_item.quantity / NULLIF(v_total_qty, 0);\nELSIF v_header.allocation_method = 'equal' THEN\nv_allocation_factor := 1.0 / NULLIF(v_item_count, 0);\nELSE\n-- Manual allocation - skip auto-calculation\nCONTINUE;\nEND IF;\n\n-- Allocate costs proportionally\nUPDATE import_cost_items\nSET\nallocated_duty = v_header.duty_amount * v_allocation_factor,\nallocated_ppn = v_header.ppn_import_amount * v_allocation_factor,\nallocated_pph = v_header.pph22_amount * v_allocation_factor,\nallocated_freight = v_header.freight_amount * v_allocation_factor,\nallocated_insurance = v_header.insurance_amount * v_allocation_factor,\nallocated_clearing = v_header.clearing_amount * v_allocation_factor,\nallocated_port = v_header.port_charges * v_allocation_factor,\nallocated_other = v_header.other_charges * v_allocation_factor,\ntotal_allocated_cost = (\nv_header.duty_amount + v_header.ppn_import_amount + v_header.pph22_amount +\nv_header.freight_amount + v_header.insurance_amount + v_header.clearing_amount +\nv_header.port_charges + v_header.other_charges\n) * v_allocation_factor,\nfinal_landed_cost_per_unit = (\ntotal_fob_value + \n(v_header.duty_amount + v_header.ppn_import_amount + v_header.pph22_amount +\nv_header.freight_amount + v_header.insurance_amount + v_header.clearing_amount +\nv_header.port_charges + v_header.other_charges) * v_allocation_factor\n) / NULLIF(quantity, 0)\nWHERE id = v_item.id;\nEND LOOP;\n\n-- Update header status\nUPDATE import_cost_headers\nSET status = 'calculated'\nWHERE id = p_header_id;\n\nEND;\n$$","--\n-- Name: FUNCTION \\"calculate_import_cost_allocation\\"(\\"p_header_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"calculate_import_cost_allocation\\"(\\"p_header_id\\" \\"uuid\\") IS 'Calculates and allocates import costs to items based on selected allocation method (by_value, by_quantity, equal, manual)'","--\n-- Name: calculate_rejection_financial_loss(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_rejection_financial_loss\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nNEW.financial_loss := NEW.quantity_rejected * NEW.unit_cost;\nRETURN NEW;\nEND;\n$$","--\n-- Name: calculate_rejection_financial_loss(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_rejection_financial_loss\\"(\\"p_rejection_id\\" \\"uuid\\") RETURNS numeric\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nv_loss decimal;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'warehouse', 'manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot calculate rejection financial loss', v_role;\nEND IF;\n\nSELECT sr.quantity * b.purchase_price INTO v_loss\nFROM stock_rejections sr\nJOIN batches b ON b.id = sr.batch_id\nWHERE sr.id = p_rejection_id;\n\nRETURN COALESCE(v_loss, 0);\nEND;\n$$","--\n-- Name: calculate_return_financial_impact(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_return_financial_impact\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\ntotal_impact decimal(15,2);\nBEGIN\nSELECT COALESCE(SUM(quantity_returned * unit_price), 0)\nINTO total_impact\nFROM material_return_items\nWHERE return_id = NEW.id;\n\nNEW.financial_impact := total_impact;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: calculate_return_financial_impact(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_return_financial_impact\\"(\\"p_return_id\\" \\"uuid\\") RETURNS TABLE(\\"total_value\\" numeric, \\"total_quantity\\" numeric, \\"product_count\\" integer)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'warehouse', 'manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot calculate return financial impact', v_role;\nEND IF;\n\nRETURN QUERY\nSELECT\nSUM(mri.quantity_returned * mri.unit_price) AS total_value,\nSUM(mri.quantity_returned) AS total_quantity,\nCOUNT(DISTINCT mri.product_id)::integer AS product_count\nFROM material_return_items mri\nWHERE mri.return_id = p_return_id;\nEND;\n$$","--\n-- Name: calculate_staff_salary(\\"uuid\\", \\"date\\", numeric, numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_staff_salary\\"(\\"p_staff_id\\" \\"uuid\\", \\"p_salary_date\\" \\"date\\" DEFAULT CURRENT_DATE, \\"p_gross_override\\" numeric DEFAULT NULL::numeric, \\"p_pph21_override\\" numeric DEFAULT NULL::numeric) RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_staff public.finance_staff_master%rowtype;\n  v_gross numeric;\n  v_advance numeric;\n  v_pph21 numeric;\n  v_bpjs numeric:=0;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  SELECT * INTO v_staff FROM public.finance_staff_master WHERE id=p_staff_id AND status='active';\n  IF NOT FOUND THEN RAISE EXCEPTION 'Active staff member not found'; END IF;\n  v_gross:=COALESCE(p_gross_override,v_staff.monthly_salary,0);\n  IF v_gross<0 THEN RAISE EXCEPTION 'Gross salary cannot be negative'; END IF;\n  SELECT COALESCE(sum(available_amount),0) INTO v_advance\n    FROM public.get_outstanding_salary_advances(p_staff_id,COALESCE(p_salary_date,current_date));\n  v_pph21:=CASE\n    WHEN NOT v_staff.pph21_applicable THEN 0\n    WHEN v_staff.pph21_method='percentage' THEN round(v_gross*v_staff.pph21_percentage/100,2)\n    ELSE COALESCE(p_pph21_override,0) END;\n  IF v_pph21<0 OR v_pph21>v_gross THEN RAISE EXCEPTION 'PPh21 must be between zero and gross salary'; END IF;\n  v_advance:=least(v_advance,greatest(v_gross-v_pph21-v_bpjs,0));\n  RETURN jsonb_build_object(\n    'staff_id',v_staff.id,'monthly_salary',v_staff.monthly_salary,'salary_type',v_staff.salary_type,\n    'gross_salary',v_gross,'outstanding_salary_advances',v_advance,\n    'pph21_applicable',v_staff.pph21_applicable,'pph21_method',v_staff.pph21_method,\n    'pph21_percentage',v_staff.pph21_percentage,'pph21_amount',v_pph21,\n    'bpjs_amount',v_bpjs,'net_salary_payable',greatest(v_gross-v_advance-v_pph21-v_bpjs,0),\n    'default_payment_method',v_staff.default_payment_method);\nEND;\n$$","--\n-- Name: calculate_task_priority(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"calculate_task_priority\\"(\\"task_deadline\\" timestamp with time zone) RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" IMMUTABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nhours_until_deadline numeric;\nBEGIN\nhours_until_deadline := EXTRACT(EPOCH FROM (task_deadline - now())) / 3600;\nIF hours_until_deadline < 0 THEN\nRETURN 'urgent';\nELSIF hours_until_deadline < 24 THEN\nRETURN 'urgent';\nELSIF hours_until_deadline < 48 THEN\nRETURN 'high';\nELSIF hours_until_deadline < 168 THEN\nRETURN 'medium';\nELSE\nRETURN 'low';\nEND IF;\nEND;\n$$","--\n-- Name: cancel_expense_posting(\\"uuid\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"cancel_expense_posting\\"(\\"p_exp_id\\" \\"uuid\\", \\"p_cancelled_by\\" \\"uuid\\", \\"p_reason\\" \\"text\\" DEFAULT 'Posting cancelled by administrator'::\\"text\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_exp public.finance_expenses%ROWTYPE;\n  v_je public.journal_entries%ROWTYPE;\n  v_reversal_id uuid;\n  v_period_status text;\n  v_reversal_number text;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n  IF p_cancelled_by IS NULL OR p_cancelled_by <> auth.uid() THEN\n    RAISE EXCEPTION 'Cancelled-by identity must match the authenticated user';\n  END IF;\n  IF btrim(COALESCE(p_reason, '')) = '' THEN\n    RAISE EXCEPTION 'Cancellation reason is required';\n  END IF;\n\n  SELECT * INTO v_exp\n  FROM public.finance_expenses\n  WHERE id = p_exp_id\n  FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Expense % not found', p_exp_id;\n  END IF;\n  IF v_exp.approval_status <> 'approved' THEN\n    RAISE EXCEPTION 'Cannot cancel posting: expense % is not approved (current: %)',\n      p_exp_id, v_exp.approval_status;\n  END IF;\n\n  SELECT * INTO v_je\n  FROM public.journal_entries\n  WHERE source_module IN ('expense', 'expenses')\n    AND (reference_id = p_exp_id OR reference_number = 'EXP-' || p_exp_id::text)\n    AND is_posted = true\n    AND NOT COALESCE(is_reversed, false)\n  ORDER BY created_at DESC, id DESC\n  LIMIT 1\n  FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'No active journal entry found for expense %', p_exp_id;\n  END IF;\n\n  SELECT ap.status INTO v_period_status\n  FROM public.accounting_periods ap\n  WHERE ap.start_date <= v_je.entry_date AND ap.end_date >= v_je.entry_date\n  ORDER BY ap.start_date DESC\n  LIMIT 1;\n  IF v_period_status IS NOT NULL AND v_period_status <> 'open' THEN\n    RAISE EXCEPTION\n      'Cannot cancel posting: the accounting period for % is closed. Contact your finance manager to reopen the period.',\n      to_char(v_je.entry_date, 'FMMonth YYYY');\n  END IF;\n\n  IF COALESCE(v_exp.paid_amount, 0) > 0\n     OR COALESCE(v_exp.pph_paid_amount, 0) > 0\n     OR EXISTS (SELECT 1 FROM public.voucher_allocations va WHERE va.finance_expense_id = p_exp_id)\n     OR EXISTS (SELECT 1 FROM public.bank_statement_allocations a\n                WHERE (a.document_type = 'expense' AND a.document_id = p_exp_id)\n                   OR a.journal_entry_id = v_je.id)\n     OR EXISTS (SELECT 1 FROM public.bank_statement_lines b\n                WHERE b.matched_expense_id = p_exp_id OR b.matched_entry_id = v_je.id)\n     OR EXISTS (SELECT 1 FROM public.bank_reconciliation_items bri WHERE bri.journal_entry_id = v_je.id) THEN\n    RAISE EXCEPTION\n      'Cannot cancel posting for paid/settled expense %. Reverse or unlink its payment/bank allocation first.',\n      COALESCE(v_exp.voucher_number, p_exp_id::text)\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  v_reversal_number := public.generate_journal_entry_number();\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id,\n    reference_number, description, total_debit, total_credit,\n    is_posted, is_reversed, posted_by, posted_at, created_by,\n    transaction_category, transaction_currency, functional_currency,\n    exchange_rate, amounts_are_functional\n  ) VALUES (\n    v_reversal_number, v_je.entry_date, v_je.period_id, 'expense_cancellation', p_exp_id,\n    'CANCEL-' || COALESCE(v_exp.voucher_number, p_exp_id::text),\n    'Cancellation reversal of ' || v_je.entry_number || ': ' || p_reason,\n    v_je.total_credit, v_je.total_debit,\n    true, true, p_cancelled_by, now(), p_cancelled_by,\n    v_je.transaction_category, v_je.transaction_currency, v_je.functional_currency,\n    v_je.exchange_rate, v_je.amounts_are_functional\n  ) RETURNING id INTO v_reversal_id;\n\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description,\n    debit, credit, tax_code_id, customer_id, supplier_id, batch_id,\n    transaction_currency, transaction_debit, transaction_credit,\n    functional_currency, exchange_rate\n  )\n  SELECT v_reversal_id, l.line_number, l.account_id,\n         'CANCEL: ' || COALESCE(l.description, ''),\n         l.credit, l.debit, l.tax_code_id, l.customer_id, l.supplier_id, l.batch_id,\n         l.transaction_currency, l.transaction_credit, l.transaction_debit,\n         l.functional_currency, l.exchange_rate\n  FROM public.journal_entry_lines l\n  WHERE l.journal_entry_id = v_je.id\n  ORDER BY l.line_number;\n\n  IF NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_reversal_id) THEN\n    RAISE EXCEPTION 'Cannot cancel empty journal entry %', v_je.id;\n  END IF;\n\n  UPDATE public.journal_entries\n  SET is_reversed = true, reversed_by_id = v_reversal_id\n  WHERE id = v_je.id AND NOT COALESCE(is_reversed, false);\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Expense journal % was already reversed', v_je.id;\n  END IF;\n\n  INSERT INTO public.audit_logs(table_name, record_id, action_type, old_values, new_values, user_id)\n  VALUES (\n    'finance_expenses', p_exp_id, 'update',\n    jsonb_build_object(\n      '_action', 'CANCEL_POSTING',\n      'journal_entry_id', v_je.id,\n      'journal_entry_number', v_je.entry_number,\n      'reversal_journal_id', v_reversal_id,\n      'reversal_journal_number', v_reversal_number,\n      'entry_date', v_je.entry_date,\n      'amount', v_exp.amount,\n      'expense_category', v_exp.expense_category,\n      'approval_status', v_exp.approval_status,\n      'reason', p_reason\n    ),\n    jsonb_build_object(\n      'approval_status', 'cancelled',\n      'cancelled_by', p_cancelled_by,\n      'cancelled_at', now()\n    ),\n    p_cancelled_by\n  );\n\n  UPDATE public.finance_expenses\n  SET approval_status = 'cancelled', approved_by = NULL, approved_at = NULL\n  WHERE id = p_exp_id;\n\n  IF EXISTS (\n    SELECT 1 FROM public.journal_entries\n    WHERE source_module IN ('expense', 'expenses')\n      AND reference_id = p_exp_id AND is_posted AND NOT COALESCE(is_reversed, false)\n  ) THEN\n    RAISE EXCEPTION 'Expense % still has an active journal after cancellation', p_exp_id;\n  END IF;\nEND;\n$$","--\n-- Name: cancel_gl_posting(\\"uuid\\", \\"uuid\\", \\"text\\", \\"uuid\\", \\"text\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"cancel_gl_posting\\"(\\"p_je_id\\" \\"uuid\\", \\"p_doc_id\\" \\"uuid\\", \\"p_table_name\\" \\"text\\", \\"p_cancelled_by\\" \\"uuid\\", \\"p_reason\\" \\"text\\", \\"p_extra_audit\\" \\"jsonb\\" DEFAULT '{}'::\\"jsonb\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_je            journal_entries%ROWTYPE;\nv_period_status TEXT;\nBEGIN\nIF auth.uid() IS NULL THEN\nRAISE EXCEPTION 'Not authenticated';\nEND IF;\n\nSELECT * INTO v_je FROM journal_entries WHERE id = p_je_id FOR UPDATE;\nIF NOT FOUND THEN\nRAISE EXCEPTION 'Journal entry % not found', p_je_id;\nEND IF;\n\nSELECT ap.status INTO v_period_status\nFROM accounting_periods ap\nWHERE ap.start_date <= v_je.entry_date AND ap.end_date >= v_je.entry_date\nORDER BY ap.start_date DESC\nLIMIT 1;\n\nIF v_period_status IS NOT NULL AND v_period_status != 'open' THEN\nRAISE EXCEPTION\n'Cannot cancel posting: the accounting period for % is closed. Contact your finance manager to reopen the period.',\nTO_CHAR(v_je.entry_date, 'FMMonth YYYY');\nEND IF;\n\nDELETE FROM journal_entry_lines WHERE journal_entry_id = p_je_id;\nDELETE FROM journal_entries      WHERE id              = p_je_id;\n\nINSERT INTO audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)\nVALUES (\np_table_name, p_doc_id, 'update',\np_extra_audit || jsonb_build_object(\n'_action',              'CANCEL_POSTING',\n'journal_entry_id',     p_je_id,\n'journal_entry_number', v_je.entry_number,\n'entry_date',           v_je.entry_date,\n'reason',               p_reason\n),\njsonb_build_object('cancelled_by', p_cancelled_by, 'cancelled_at', NOW()),\np_cancelled_by\n);\nEND;\n$$","--\n-- Name: cancel_payment_voucher_posting(\\"uuid\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"cancel_payment_voucher_posting\\"(\\"p_pv_id\\" \\"uuid\\", \\"p_cancelled_by\\" \\"uuid\\", \\"p_reason\\" \\"text\\" DEFAULT 'Posting cancelled by administrator'::\\"text\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_pv RECORD;\n  v_je RECORD;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  SELECT * INTO v_pv FROM payment_vouchers WHERE id = p_pv_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found', p_pv_id; END IF;\n  IF NOT v_pv.is_posted THEN\n    RAISE EXCEPTION 'Payment voucher % is not posted', COALESCE(v_pv.voucher_number, p_pv_id::TEXT);\n  END IF;\n\n  SELECT * INTO v_je FROM journal_entries WHERE id = v_pv.journal_entry_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'No journal entry found for payment voucher %', v_pv.voucher_number;\n  END IF;\n\n  -- Clear the FK reference FIRST so cancel_gl_posting can delete the JE row.\n  -- (payment_vouchers.journal_entry_id has ON DELETE NO ACTION.)\n  UPDATE payment_vouchers\n  SET is_posted = FALSE, journal_entry_id = NULL\n  WHERE id = p_pv_id;\n\n  PERFORM cancel_gl_posting(\n    v_je.id, p_pv_id, 'payment_vouchers', p_cancelled_by, p_reason,\n    jsonb_build_object(\n      'voucher_number', v_pv.voucher_number,\n      'amount',         v_pv.amount,\n      'is_posted',      TRUE\n    )\n  );\nEND;\n$$","--\n-- Name: cancel_petty_cash_posting(\\"uuid\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"cancel_petty_cash_posting\\"(\\"p_pct_id\\" \\"uuid\\", \\"p_cancelled_by\\" \\"uuid\\", \\"p_reason\\" \\"text\\" DEFAULT 'Posting cancelled by administrator'::\\"text\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_pct record;\n  v_je  record;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  SELECT *\n    INTO v_pct\n    FROM public.petty_cash_transactions\n   WHERE id = p_pct_id\n   FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Petty cash transaction % not found', p_pct_id;\n  END IF;\n\n  IF v_pct.fund_transfer_id IS NOT NULL THEN\n    RAISE EXCEPTION 'Fund Transfer activity must be reversed from the Contra screen';\n  END IF;\n\n  IF v_pct.approval_status <> 'approved' THEN\n    RAISE EXCEPTION\n      'Cannot cancel posting: transaction % is not approved (current: %)',\n      COALESCE(v_pct.transaction_number, p_pct_id::text),\n      v_pct.approval_status;\n  END IF;\n\n  SELECT *\n    INTO v_je\n    FROM public.journal_entries\n   WHERE reference_id = p_pct_id\n     AND source_module = 'petty_cash'\n   LIMIT 1;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'No journal entry found for %', COALESCE(v_pct.transaction_number, p_pct_id::text);\n  END IF;\n\n  PERFORM public.cancel_gl_posting(\n    v_je.id,\n    p_pct_id,\n    'petty_cash_transactions',\n    p_cancelled_by,\n    p_reason,\n    jsonb_build_object(\n      'transaction_number', v_pct.transaction_number,\n      'amount', v_pct.amount,\n      'approval_status', 'approved'\n    )\n  );\n\n  UPDATE public.bank_statement_lines\n     SET matched_petty_cash_id = NULL,\n         matched_entry_id = NULL,\n         reconciliation_status = 'unmatched',\n         matched_at = NULL,\n         matched_by = NULL,\n         notes = NULL\n   WHERE matched_petty_cash_id = p_pct_id\n      OR matched_entry_id = v_je.id;\n\n  UPDATE public.petty_cash_transactions\n     SET approval_status = 'pending_approval',\n         approved_by = NULL,\n         approved_at = NULL,\n         bank_statement_line_id = NULL\n   WHERE id = p_pct_id;\nEND;\n$$","--\n-- Name: cancel_receipt_voucher_posting(\\"uuid\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"cancel_receipt_voucher_posting\\"(\\"p_rv_id\\" \\"uuid\\", \\"p_cancelled_by\\" \\"uuid\\", \\"p_reason\\" \\"text\\" DEFAULT 'Posting cancelled by administrator'::\\"text\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_rv RECORD;\n  v_je RECORD;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  SELECT * INTO v_rv FROM receipt_vouchers WHERE id = p_rv_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id; END IF;\n  IF NOT v_rv.is_posted THEN\n    RAISE EXCEPTION 'Receipt voucher % is not posted', COALESCE(v_rv.voucher_number, p_rv_id::TEXT);\n  END IF;\n\n  SELECT * INTO v_je FROM journal_entries WHERE id = v_rv.journal_entry_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'No journal entry found for receipt voucher %', v_rv.voucher_number;\n  END IF;\n\n  -- Clear the FK reference FIRST so cancel_gl_posting can delete the JE row.\n  UPDATE receipt_vouchers\n  SET is_posted = FALSE, journal_entry_id = NULL\n  WHERE id = p_rv_id;\n\n  PERFORM cancel_gl_posting(\n    v_je.id, p_rv_id, 'receipt_vouchers', p_cancelled_by, p_reason,\n    jsonb_build_object(\n      'voucher_number', v_rv.voucher_number,\n      'amount',         v_rv.amount,\n      'is_posted',      TRUE\n    )\n  );\nEND;\n$$","--\n-- Name: check_approval_required(\\"text\\", numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"check_approval_required\\"(\\"p_transaction_type\\" \\"text\\", \\"p_amount\\" numeric) RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_threshold decimal;\nBEGIN\nIF auth.uid() IS NULL THEN\nRAISE EXCEPTION 'Permission denied: must be authenticated';\nEND IF;\n\nSELECT amount_threshold INTO v_threshold\nFROM approval_thresholds\nWHERE transaction_type = p_transaction_type\nAND is_active = true\nORDER BY amount_threshold DESC\nLIMIT 1;\n\nIF v_threshold IS NULL THEN\nRETURN false;\nEND IF;\n\nRETURN p_amount >= v_threshold;\nEND;\n$$","--\n-- Name: check_inquiry_requirements_fulfilled(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"check_inquiry_requirements_fulfilled\\"(\\"inquiry_id\\" \\"uuid\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\ninquiry_record RECORD;\nall_fulfilled boolean;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'sales', 'manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot check inquiry requirements', v_role;\nEND IF;\n\nSELECT * INTO inquiry_record FROM crm_inquiries WHERE id = inquiry_id;\n\nIF NOT FOUND THEN\nRETURN false;\nEND IF;\n\nall_fulfilled := (\n(NOT inquiry_record.price_required OR inquiry_record.price_sent_at IS NOT NULL) AND\n(NOT inquiry_record.coa_required OR inquiry_record.coa_sent_at IS NOT NULL) AND\n(NOT inquiry_record.sample_required OR inquiry_record.sample_sent_at IS NOT NULL) AND\n(NOT inquiry_record.agency_letter_required OR inquiry_record.agency_letter_sent_at IS NOT NULL)\n);\n\nRETURN all_fulfilled;\nEND;\n$$","--\n-- Name: bulk_email_campaigns; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"bulk_email_campaigns\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"subject\\" \\"text\\" NOT NULL,\n    \\"total_recipients\\" integer DEFAULT 0 NOT NULL,\n    \\"sent_count\\" integer DEFAULT 0 NOT NULL,\n    \\"failed_count\\" integer DEFAULT 0 NOT NULL,\n    \\"status\\" \\"text\\" DEFAULT 'in_progress'::\\"text\\" NOT NULL,\n    \\"has_attachments\\" boolean DEFAULT false NOT NULL,\n    \\"template_id\\" \\"uuid\\",\n    \\"started_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"completed_at\\" timestamp with time zone,\n    \\"created_by\\" \\"uuid\\" NOT NULL,\n    \\"email_body\\" \\"text\\",\n    \\"sender_name\\" \\"text\\",\n    \\"attachments_context\\" \\"jsonb\\" DEFAULT '[]'::\\"jsonb\\" NOT NULL,\n    \\"processing_batch_size\\" integer DEFAULT 10 NOT NULL,\n    \\"processing_delay_seconds\\" integer DEFAULT 30 NOT NULL,\n    \\"next_run_at\\" timestamp with time zone,\n    \\"worker_lock_until\\" timestamp with time zone,\n    \\"worker_lock_id\\" \\"text\\",\n    \\"worker_started_at\\" timestamp with time zone,\n    \\"worker_finished_at\\" timestamp with time zone,\n    \\"last_worker_error\\" \\"text\\",\n    CONSTRAINT \\"bulk_email_campaigns_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['in_progress'::\\"text\\", 'completed'::\\"text\\", 'partial'::\\"text\\", 'failed'::\\"text\\", 'paused'::\\"text\\", 'cancelled'::\\"text\\"])))\n)","--\n-- Name: claim_bulk_email_campaign(\\"uuid\\", \\"text\\", integer, \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"claim_bulk_email_campaign\\"(\\"p_campaign_id\\" \\"uuid\\", \\"p_execution_id\\" \\"text\\", \\"p_lock_seconds\\" integer DEFAULT 120, \\"p_owner_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"public\\".\\"bulk_email_campaigns\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_campaign public.bulk_email_campaigns;\nBEGIN\n  UPDATE public.bulk_email_campaigns\n  SET\n    worker_lock_until = now() + make_interval(secs => GREATEST(30, p_lock_seconds)),\n    worker_lock_id = p_execution_id,\n    worker_started_at = now(),\n    last_worker_error = NULL\n  WHERE id = p_campaign_id\n    AND status = 'in_progress'\n    AND (next_run_at IS NULL OR next_run_at <= now())\n    AND (worker_lock_until IS NULL OR worker_lock_until < now())\n    AND (p_owner_id IS NULL OR created_by = p_owner_id)\n  RETURNING * INTO v_campaign;\n\n  RETURN v_campaign;\nEND;\n$$","--\n-- Name: bulk_email_recipients; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"bulk_email_recipients\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"campaign_id\\" \\"uuid\\" NOT NULL,\n    \\"contact_id\\" \\"uuid\\",\n    \\"company_name\\" \\"text\\" DEFAULT ''::\\"text\\" NOT NULL,\n    \\"email\\" \\"text\\" NOT NULL,\n    \\"status\\" \\"text\\" DEFAULT 'pending'::\\"text\\" NOT NULL,\n    \\"error_message\\" \\"text\\",\n    \\"sent_at\\" timestamp with time zone,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"send_order\\" integer,\n    \\"attempt_number\\" integer DEFAULT 0 NOT NULL,\n    \\"started_at\\" timestamp with time zone,\n    \\"completed_at\\" timestamp with time zone,\n    \\"http_status\\" integer,\n    \\"edge_execution_id\\" \\"text\\",\n    \\"provider_response\\" \\"jsonb\\",\n    \\"error_code\\" \\"text\\",\n    CONSTRAINT \\"bulk_email_recipients_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['pending'::\\"text\\", 'sending'::\\"text\\", 'sent'::\\"text\\", 'failed'::\\"text\\", 'cancelled'::\\"text\\"])))\n)","--\n-- Name: claim_bulk_email_recipients(\\"uuid\\", integer, \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"claim_bulk_email_recipients\\"(\\"p_campaign_id\\" \\"uuid\\", \\"p_limit\\" integer, \\"p_execution_id\\" \\"text\\") RETURNS SETOF \\"public\\".\\"bulk_email_recipients\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nWITH stale AS (\nUPDATE public.bulk_email_recipients\nSET\nstatus        = 'pending',\nerror_code    = 'STALE_SENDING_REQUEUED',\nerror_message = 'Recipient was stuck in sending state and was requeued.',\ncompleted_at  = now()\nWHERE campaign_id = p_campaign_id\nAND status = 'sending'\nAND started_at < now() - interval '5 minutes'\nAND sent_at IS NULL\nRETURNING id\n),\npicked AS (\nSELECT r.id\nFROM public.bulk_email_recipients r\nWHERE r.campaign_id = p_campaign_id\nAND r.status = 'pending'\nORDER BY r.send_order NULLS LAST, r.created_at, r.id\nLIMIT GREATEST(1, p_limit)\nFOR UPDATE SKIP LOCKED\n)\nUPDATE public.bulk_email_recipients r\nSET\nstatus         = 'sending',\nattempt_number = r.attempt_number + 1,\nstarted_at     = now(),\ncompleted_at   = NULL,\nhttp_status    = NULL,\nedge_execution_id = p_execution_id,\nprovider_response = NULL,\nerror_code     = NULL,\nerror_message  = NULL\nFROM picked\nWHERE r.id = picked.id\nRETURNING r.*;\nEND;\n$$","--\n-- Name: clear_receipt_allocation_rounding_adjustment(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"clear_receipt_allocation_rounding_adjustment\\"(\\"p_invoice_id\\" \\"uuid\\", \\"p_receipt_voucher_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_existing record;\nBEGIN\n  FOR v_existing IN\n    SELECT *\n    FROM public.invoice_rounding_adjustments\n    WHERE sales_invoice_id = p_invoice_id\n       OR (p_receipt_voucher_id IS NOT NULL AND receipt_voucher_id = p_receipt_voucher_id)\n  LOOP\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n\n    DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n  END LOOP;\n\n  PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);\nEND;\n$$","--\n-- Name: close_tax_period(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"close_tax_period\\"(\\"p_period_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_period                  tax_periods%ROWTYPE;\n  v_missing_faktur          int;\n  v_draft_sales             int;\n  v_draft_purchase          int;\n  v_unposted_je             int;\n  v_unreconciled_payments   int;\n  v_outstanding             numeric(18,2);\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM user_profiles\n                 WHERE id = auth.uid() AND role IN ('admin','manager') AND is_active = true) THEN\n    RAISE EXCEPTION 'Only admins/managers may close a tax period';\n  END IF;\n\n  SELECT * INTO v_period FROM tax_periods WHERE id = p_period_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax period % not found', p_period_id;\n  END IF;\n  IF v_period.status = 'closed' THEN\n    RAISE EXCEPTION 'Tax period already closed';\n  END IF;\n\n  -- Recompute snapshot before validating\n  PERFORM compute_period_ppn(p_period_id);\n  SELECT * INTO v_period FROM tax_periods WHERE id = p_period_id;\n\n  -- 1. Missing Faktur Pajak (PPN only)\n  IF v_period.tax_type = 'PPN' THEN\n    SELECT COUNT(*) INTO v_missing_faktur\n      FROM sales_invoices\n     WHERE tax_period_id = p_period_id\n       AND tax_amount > 0\n       AND (faktur_pajak_number IS NULL OR faktur_pajak_number = '');\n    IF v_missing_faktur > 0 THEN\n      RAISE EXCEPTION 'Cannot close period: % sales invoice(s) missing Faktur Pajak number', v_missing_faktur;\n    END IF;\n  END IF;\n\n  -- 2. No draft sales invoices attributed to this period\n  BEGIN\n    SELECT COUNT(*) INTO v_draft_sales\n      FROM sales_invoices\n     WHERE tax_period_id = p_period_id\n       AND status = 'draft';\n    IF v_draft_sales > 0 THEN\n      RAISE EXCEPTION 'Cannot close period: % draft sales invoice(s) remain', v_draft_sales;\n    END IF;\n  EXCEPTION WHEN undefined_column THEN\n    NULL;  -- sales_invoices.status may not be present in every branch\n  END;\n\n  -- 3. No draft purchase invoices attributed to this period\n  BEGIN\n    SELECT COUNT(*) INTO v_draft_purchase\n      FROM purchase_invoices\n     WHERE tax_period_id = p_period_id\n       AND status = 'draft';\n    IF v_draft_purchase > 0 THEN\n      RAISE EXCEPTION 'Cannot close period: % draft purchase invoice(s) remain', v_draft_purchase;\n    END IF;\n  EXCEPTION WHEN undefined_column THEN\n    NULL;\n  END;\n\n  -- 4. No unposted journal_entries referencing this period's source docs\n  --    (any tax_payment JE where is_posted = false is a blocker)\n  SELECT COUNT(*) INTO v_unposted_je\n    FROM journal_entries je\n    JOIN tax_payments txp ON txp.id = je.reference_id\n   WHERE je.source_module = 'tax_payment'\n     AND txp.tax_period_id = p_period_id\n     AND je.is_posted = false;\n  IF v_unposted_je > 0 THEN\n    RAISE EXCEPTION 'Cannot close period: % unposted journal entries for tax payments', v_unposted_je;\n  END IF;\n\n  -- 5. No unreconciled tax_payments (must all be in status='reconciled')\n  SELECT COUNT(*) INTO v_unreconciled_payments\n    FROM tax_payments\n   WHERE tax_period_id = p_period_id\n     AND status IN ('draft','posted');\n  IF v_unreconciled_payments > 0 THEN\n    RAISE EXCEPTION 'Cannot close period: % unreconciled tax payment(s) remain (status draft or posted)', v_unreconciled_payments;\n  END IF;\n\n  -- 6. Zero outstanding payable\n  SELECT outstanding_amount INTO v_outstanding\n    FROM vw_outstanding_tax\n   WHERE tax_period_id = p_period_id;\n  IF COALESCE(v_outstanding, 0) > 0 THEN\n    RAISE EXCEPTION 'Cannot close period: Rp % still outstanding. Record additional tax payments first.', v_outstanding;\n  END IF;\n\n  -- Flip status\n  UPDATE tax_periods SET\n    status    = 'closed',\n    closed_at = now(),\n    closed_by = auth.uid(),\n    updated_at = now()\n  WHERE id = p_period_id;\n\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)\n  VALUES (auth.uid(), 'tax_periods', 'update', p_period_id,\n          jsonb_build_object(\n            'action', 'close',\n            'status', 'closed',\n            'input_ppn_total',  v_period.input_ppn_total,\n            'output_ppn_total', v_period.output_ppn_total,\n            'net_ppn',          v_period.net_ppn,\n            'pph_total',        v_period.pph_total\n          ));\nEND $$","--\n-- Name: complete_import_cost_posting(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"complete_import_cost_posting\\"(\\"p_header_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nv_je_id UUID;\nv_result JSONB;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot post import costs', v_role;\nEND IF;\n\nPERFORM calculate_import_cost_allocation(p_header_id);\nPERFORM apply_import_costs_to_batches(p_header_id);\nv_je_id := post_import_cost_journal(p_header_id);\n\nUPDATE import_cost_headers\nSET\nstatus = 'posted',\njournal_entry_id = v_je_id,\nposted_by = auth.uid(),\nposted_at = NOW()\nWHERE id = p_header_id;\n\nv_result := jsonb_build_object(\n'success', true,\n'message', 'Import costs calculated, allocated, and posted successfully',\n'journal_entry_id', v_je_id,\n'header_id', p_header_id\n);\n\nRETURN v_result;\nEND;\n$$","--\n-- Name: FUNCTION \\"complete_import_cost_posting\\"(\\"p_header_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"complete_import_cost_posting\\"(\\"p_header_id\\" \\"uuid\\") IS 'Complete import cost posting workflow: calculates allocation, updates batches, posts accounting. Call this to finalize import costs.'","--\n-- Name: compute_period_ppn(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"compute_period_ppn\\"(\\"p_period_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_period public.tax_periods%rowtype; v_pph_total numeric(18,2);\nBEGIN\n  PERFORM public.compute_period_ppn_pre_posted_register(p_period_id);\n  SELECT * INTO v_period FROM public.tax_periods WHERE id=p_period_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Tax period % not found',p_period_id; END IF;\n  IF v_period.tax_type='PPN' THEN RETURN; END IF;\n  SELECT COALESCE((SELECT sum(fe.pph_amount) FROM public.finance_expenses fe LEFT JOIN public.tax_codes tc ON tc.id=fe.pph_code_id\n    WHERE (fe.pph_tax_period_id=v_period.id OR (fe.pph_tax_period_id IS NULL AND extract(year from public.get_expense_pph_period_date(fe.id))::int=v_period.fiscal_year AND extract(month from public.get_expense_pph_period_date(fe.id))::int=v_period.period_month))\n      AND fe.approval_status='approved' AND fe.pph_amount>0 AND coalesce(fe.expense_category,'') NOT IN ('pib_import','pph_import') AND (v_period.tax_type='PPh_Unifikasi' OR tc.tax_type=v_period.tax_type)),0)\n    + COALESCE((SELECT sum(pv.pph_amount) FROM public.payment_vouchers pv LEFT JOIN public.tax_codes tc ON tc.id=pv.pph_code_id\n    WHERE (pv.tax_period_id=v_period.id OR (pv.tax_period_id IS NULL AND extract(year from pv.voucher_date)::int=v_period.fiscal_year AND extract(month from pv.voucher_date)::int=v_period.period_month))\n      AND coalesce(pv.is_posted,false) AND pv.pph_amount>0 AND (v_period.tax_type='PPh_Unifikasi' OR tc.tax_type=v_period.tax_type)),0)\n    + CASE WHEN v_period.tax_type IN ('PPh22','PPh_Unifikasi') THEN COALESCE((SELECT sum(case when fe.expense_category='pib_import' then fe.pib_pph_amount else fe.amount end) FROM public.finance_expenses fe\n    WHERE fe.expense_category IN ('pib_import','pph_import') AND (fe.pph_tax_period_id=v_period.id OR (fe.pph_tax_period_id IS NULL AND extract(year from public.get_expense_pph_period_date(fe.id))::int=v_period.fiscal_year AND extract(month from public.get_expense_pph_period_date(fe.id))::int=v_period.period_month)) AND fe.approval_status='approved'),0) ELSE 0 END\n    + COALESCE((SELECT sum(tp.amount) FROM public.tax_payments tp\n    WHERE tp.tax_period_id=v_period.id AND tp.tax_type=v_period.tax_type AND tp.historical_source_status='missing_source_verified'),0)\n  INTO v_pph_total;\n  UPDATE public.tax_periods SET pph_total=v_pph_total,updated_at=now() WHERE id=p_period_id;\nEND $$","--\n-- Name: compute_period_ppn_pre_posted_register(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"compute_period_ppn_pre_posted_register\\"(\\"p_period_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_period       tax_periods%ROWTYPE;\n  v_input        numeric(18,2);\n  v_output_gross numeric(18,2);\n  v_output_cn    numeric(18,2);\n  v_output       numeric(18,2);\n  v_prior_cf     numeric(18,2);\n  v_pph_total    numeric(18,2);\nBEGIN\n  SELECT * INTO v_period FROM tax_periods WHERE id = p_period_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax period % not found', p_period_id;\n  END IF;\n\n  IF v_period.tax_type = 'PPN' THEN\n    -- INPUT PPN (unchanged): purchase_invoices + finance_expenses\n    -- (regular ppn_amount excluding broker rows) + broker_items[i].ppn_amount\n    -- + pib_ppn_amount.\n    SELECT\n      COALESCE((\n        SELECT SUM(tax_amount) FROM purchase_invoices\n         WHERE tax_period_id = p_period_id AND tax_amount > 0\n      ), 0)\n      +\n      COALESCE((\n        SELECT SUM(fe.ppn_amount)\n          FROM finance_expenses fe\n         WHERE fe.tax_period_id = p_period_id\n           AND fe.ppn_amount > 0\n           AND NOT EXISTS (\n             SELECT 1\n               FROM jsonb_array_elements(COALESCE(fe.broker_items, '[]'::jsonb)) item\n              WHERE COALESCE((item->>'ppn_amount')::numeric, 0) > 0\n           )\n      ), 0)\n      +\n      COALESCE((\n        SELECT SUM(COALESCE((item->>'ppn_amount')::numeric, 0))\n          FROM finance_expenses fe\n          CROSS JOIN LATERAL jsonb_array_elements(COALESCE(fe.broker_items, '[]'::jsonb)) item\n         WHERE fe.tax_period_id = p_period_id\n           AND COALESCE((item->>'ppn_amount')::numeric, 0) > 0\n      ), 0)\n      +\n      COALESCE((\n        SELECT SUM(pib_ppn_amount) FROM finance_expenses\n         WHERE tax_period_id = p_period_id AND pib_ppn_amount > 0\n      ), 0)\n    INTO v_input;\n\n    -- OUTPUT PPN = gross sales_invoices.tax_amount − approved credit notes.\n    SELECT COALESCE(SUM(tax_amount), 0) INTO v_output_gross\n      FROM sales_invoices\n     WHERE tax_period_id = p_period_id AND tax_amount > 0;\n\n    SELECT COALESCE(SUM(tax_amount), 0) INTO v_output_cn\n      FROM credit_notes\n     WHERE tax_period_id = p_period_id\n       AND status = 'approved'\n       AND tax_amount > 0;\n\n    v_output := GREATEST(v_output_gross - v_output_cn, 0);\n\n    SELECT COALESCE(carry_forward_out, 0) INTO v_prior_cf\n      FROM tax_periods\n     WHERE tax_type = 'PPN'\n       AND (fiscal_year, period_month) < (v_period.fiscal_year, v_period.period_month)\n     ORDER BY fiscal_year DESC, period_month DESC\n     LIMIT 1;\n    v_prior_cf := COALESCE(v_prior_cf, 0);\n\n    UPDATE tax_periods SET\n      input_ppn_total   = v_input,\n      output_ppn_total  = v_output,\n      carry_forward_in  = v_prior_cf,\n      net_ppn           = GREATEST(v_output - v_input - v_prior_cf, 0),\n      carry_forward_out = GREATEST(v_input + v_prior_cf - v_output, 0),\n      updated_at        = now()\n    WHERE id = p_period_id;\n\n  ELSE\n    -- PPh period. Three additive sources, all attributed by document date:\n    --   (a) finance_expenses.pph_amount  — regular withholding on NON-import\n    --       expenses (matched to the period's PPh type via tax_codes).\n    --   (b) payment_vouchers.pph_amount  — withholding on vouchers.\n    --   (c) IMPORT PPh 22 — pib_import.pib_pph_amount + pph_import.amount.\n    --       Always PPh22, so only counted for PPh22 / PPh_Unifikasi periods.\n    SELECT\n      COALESCE((\n        SELECT SUM(fe.pph_amount)\n          FROM finance_expenses fe\n          LEFT JOIN tax_codes tc ON tc.id = fe.pph_code_id\n         WHERE EXTRACT(YEAR  FROM fe.expense_date)::int = v_period.fiscal_year\n           AND EXTRACT(MONTH FROM fe.expense_date)::int = v_period.period_month\n           AND fe.pph_amount > 0\n           AND COALESCE(fe.expense_category, '') NOT IN ('pib_import', 'pph_import')\n           AND (v_period.tax_type = 'PPh_Unifikasi' OR tc.tax_type = v_period.tax_type)\n      ), 0)\n      +\n      COALESCE((\n        SELECT SUM(pv.pph_amount)\n          FROM payment_vouchers pv\n          LEFT JOIN tax_codes tc ON tc.id = pv.pph_code_id\n         WHERE EXTRACT(YEAR  FROM pv.voucher_date)::int = v_period.fiscal_year\n           AND EXTRACT(MONTH FROM pv.voucher_date)::int = v_period.period_month\n           AND pv.pph_amount > 0\n           AND (v_period.tax_type = 'PPh_Unifikasi' OR tc.tax_type = v_period.tax_type)\n      ), 0)\n      +\n      CASE WHEN v_period.tax_type IN ('PPh22', 'PPh_Unifikasi') THEN\n        -- (c1) PIB single-document import: PPh 22 portion in pib_pph_amount\n        COALESCE((\n          SELECT SUM(fe.pib_pph_amount)\n            FROM finance_expenses fe\n           WHERE fe.expense_category = 'pib_import'\n             AND EXTRACT(YEAR  FROM fe.expense_date)::int = v_period.fiscal_year\n             AND EXTRACT(MONTH FROM fe.expense_date)::int = v_period.period_month\n             AND COALESCE(fe.pib_pph_amount, 0) > 0\n        ), 0)\n        +\n        -- (c2) Standalone import PPh 22 expense: whole amount is the tax\n        COALESCE((\n          SELECT SUM(fe.amount)\n            FROM finance_expenses fe\n           WHERE fe.expense_category = 'pph_import'\n             AND EXTRACT(YEAR  FROM fe.expense_date)::int = v_period.fiscal_year\n             AND EXTRACT(MONTH FROM fe.expense_date)::int = v_period.period_month\n             AND COALESCE(fe.amount, 0) > 0\n        ), 0)\n      ELSE 0 END\n    INTO v_pph_total;\n\n    UPDATE tax_periods SET\n      pph_total  = v_pph_total,\n      updated_at = now()\n    WHERE id = p_period_id;\n  END IF;\nEND $$","--\n-- Name: compute_tax_due_dates(\\"text\\", integer, integer); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"compute_tax_due_dates\\"(\\"p_tax_type\\" \\"text\\", \\"p_fiscal_year\\" integer, \\"p_period_month\\" integer) RETURNS TABLE(\\"period_start\\" \\"date\\", \\"period_end\\" \\"date\\", \\"payment_due_date\\" \\"date\\", \\"filing_due_date\\" \\"date\\")\n    LANGUAGE \\"plpgsql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_start                 date;\n  v_end                   date;\n  v_cfg                   tax_calendar_config%ROWTYPE;\n  v_offset_month_start    date;\nBEGIN\n  v_start := make_date(p_fiscal_year, p_period_month, 1);\n  v_end   := (v_start + interval '1 month - 1 day')::date;\n\n  SELECT * INTO v_cfg\n  FROM tax_calendar_config\n  WHERE tax_type = p_tax_type AND is_active = true;\n\n  IF NOT FOUND THEN\n    RETURN QUERY SELECT v_start, v_end, NULL::date, NULL::date;\n    RETURN;\n  END IF;\n\n  v_offset_month_start := (v_start + (v_cfg.due_relative_month_offset || ' months')::interval)::date;\n\n  RETURN QUERY SELECT\n    v_start,\n    v_end,\n    CASE\n      WHEN v_cfg.end_of_month_payment THEN\n        ((v_offset_month_start + interval '1 month - 1 day')::date)\n      WHEN v_cfg.payment_due_day IS NOT NULL THEN\n        make_date(\n          EXTRACT(YEAR  FROM v_offset_month_start)::int,\n          EXTRACT(MONTH FROM v_offset_month_start)::int,\n          LEAST(v_cfg.payment_due_day,\n                EXTRACT(DAY FROM (v_offset_month_start + interval '1 month - 1 day'))::int)\n        )\n      ELSE NULL\n    END,\n    CASE\n      WHEN v_cfg.filing_due_day IS NOT NULL THEN\n        make_date(\n          EXTRACT(YEAR  FROM v_offset_month_start)::int,\n          EXTRACT(MONTH FROM v_offset_month_start)::int,\n          LEAST(v_cfg.filing_due_day,\n                EXTRACT(DAY FROM (v_offset_month_start + interval '1 month - 1 day'))::int)\n        )\n      WHEN v_cfg.end_of_month_payment THEN\n        ((v_offset_month_start + interval '1 month - 1 day')::date)\n      ELSE NULL\n    END;\nEND $$","--\n-- Name: confirm_bank_match(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"confirm_bank_match\\"(\\"p_bank_line_id\\" \\"uuid\\", \\"p_user_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_line              RECORD;\nv_already_confirmed BOOLEAN;\nv_role              text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot confirm bank matches', v_role;\nEND IF;\n\nSELECT * INTO v_line FROM bank_statement_lines WHERE id = p_bank_line_id;\nIF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Bank line not found'); END IF;\nIF v_line.matching_status = 'confirmed' THEN\nRETURN jsonb_build_object('success', false, 'error', 'Match already confirmed');\nEND IF;\n\nIF v_line.matched_expense_id IS NOT NULL THEN\nSELECT EXISTS (\nSELECT 1 FROM bank_statement_lines\nWHERE matched_expense_id = v_line.matched_expense_id\nAND matching_status = 'confirmed' AND id != p_bank_line_id\n) INTO v_already_confirmed;\nIF v_already_confirmed THEN\nRETURN jsonb_build_object('success', false, 'error', 'This expense is already confirmed with another bank transaction');\nEND IF;\nEND IF;\n\nIF v_line.matched_receipt_id IS NOT NULL THEN\nSELECT EXISTS (\nSELECT 1 FROM bank_statement_lines\nWHERE matched_receipt_id = v_line.matched_receipt_id\nAND matching_status = 'confirmed' AND id != p_bank_line_id\n) INTO v_already_confirmed;\nIF v_already_confirmed THEN\nRETURN jsonb_build_object('success', false, 'error', 'This receipt is already confirmed with another bank transaction');\nEND IF;\nEND IF;\n\nUPDATE bank_statement_lines\nSET matching_status = 'confirmed', reconciliation_status = 'matched',\nmatched_at = now(), matched_by = p_user_id, notes = 'User confirmed match'\nWHERE id = p_bank_line_id;\n\nRETURN jsonb_build_object('success', true, 'message', 'Match confirmed successfully');\nEND;\n$$","--\n-- Name: consume_so_product_reservation_v2(\\"uuid\\", \\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"consume_so_product_reservation_v2\\"(\\"p_dc_item_id\\" \\"uuid\\", \\"p_operation_id\\" \\"uuid\\", \\"p_actor\\" \\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v record; v_res public.so_product_reservations%ROWTYPE; v_tx uuid; v_after numeric;\nBEGIN\n  SELECT dci.*,dc.id dc_id,dc.sales_order_id,dc.challan_number,dc.challan_date INTO v\n  FROM public.delivery_challan_items dci JOIN public.delivery_challans dc ON dc.id=dci.challan_id\n  WHERE dci.id=p_dc_item_id FOR UPDATE OF dci,dc;\n  IF NOT FOUND OR v.sales_order_item_id IS NULL THEN RAISE EXCEPTION 'DC item has no canonical SO item'; END IF;\n  SELECT * INTO v_res FROM public.so_product_reservations\n  WHERE sales_order_item_id=v.sales_order_item_id AND product_id=v.product_id AND status='active' FOR UPDATE;\n  IF NOT FOUND OR v_res.reserved_quantity<v.quantity THEN RAISE EXCEPTION 'DC quantity exceeds remaining SO product reservation'; END IF;\n  IF NOT EXISTS(SELECT 1 FROM public.batches b WHERE b.id=v.batch_id AND b.product_id=v.product_id\n      AND b.is_active AND b.current_stock>=v.quantity AND (b.expiry_date IS NULL OR b.expiry_date>CURRENT_DATE)) THEN\n    RAISE EXCEPTION 'Selected batch is invalid, expired, or has insufficient physical stock';\n  END IF;\n  IF EXISTS(SELECT 1 FROM public.dc_batch_allocations WHERE delivery_challan_item_id=v.id AND status='consumed') THEN\n    RAISE EXCEPTION 'Delivery Challan item reservation is already consumed';\n  END IF;\n  v_tx:=public.post_inventory_movement(public.uuid_from_text('inventory-v2:dc:'||p_operation_id||':'||v.id),v.product_id,v.batch_id,\n    'delivery_challan',-v.quantity,v.challan_date,v.challan_number,'delivery_challan',v.dc_id,\n    'Product reservation consumed against DC batch',COALESCE(p_actor,auth.uid()),NULL,NULL);\n  v_after:=v_res.reserved_quantity-v.quantity;\n  UPDATE public.so_product_reservations SET reserved_quantity=v_after,\n    status=CASE WHEN v_after=0 THEN 'consumed' ELSE 'active' END,closed_at=CASE WHEN v_after=0 THEN now() END,\n    close_reason=CASE WHEN v_after=0 THEN 'Fully delivered' END,updated_at=now() WHERE id=v_res.id;\n  INSERT INTO public.so_product_reservation_events(reservation_id,sales_order_id,sales_order_item_id,event_type,quantity_delta,quantity_after,delivery_challan_item_id,reason,actor_id)\n  VALUES(v_res.id,v.sales_order_id,v.sales_order_item_id,'consumed',-v.quantity,v_after,v.id,'DC approval',COALESCE(p_actor,auth.uid()));\n  INSERT INTO public.dc_batch_allocations(delivery_challan_id,delivery_challan_item_id,sales_order_item_id,reservation_id,product_id,batch_id,allocated_quantity,operation_id,inventory_transaction_id,created_by)\n  VALUES(v.dc_id,v.id,v.sales_order_item_id,v_res.id,v.product_id,v.batch_id,v.quantity,p_operation_id,v_tx,COALESCE(p_actor,auth.uid()));\n  RETURN v_tx;\nEND; $$","--\n-- Name: correct_customs_broker_reimbursement_totals(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"correct_customs_broker_reimbursement_totals\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_je uuid;\n  v_expense_account uuid;\n  v_ap_account uuid;\n  v_cash_account uuid;\n  v_item jsonb;\n  v_supplier uuid;\n  v_amount numeric;\n  v_old_base numeric;\n  v_delta numeric;\n  v_balance numeric;\n  v_debit numeric;\n  v_credit numeric;\n  v_line_no int;\n  v_outstanding boolean := NEW.payment_method IS NULL OR NEW.payment_method = 'outstanding';\nBEGIN\n  IF NEW.expense_category <> 'import_broker' THEN RETURN NEW; END IF;\n\n  SELECT id INTO v_je FROM journal_entries WHERE reference_number = 'EXP-' || NEW.id::text LIMIT 1;\n  IF v_je IS NULL THEN RETURN NEW; END IF;\n  -- The legacy expense trigger can leave its generic PPh narration behind;\n  -- broker posting owns the PPh23 line and must not duplicate withholding.\n  DELETE FROM journal_entry_lines\n   WHERE journal_entry_id = v_je\n     AND description LIKE 'PPh Ditahan - %';\n  SELECT id INTO v_expense_account FROM chart_of_accounts WHERE code = '5300' LIMIT 1;\n  SELECT id INTO v_ap_account FROM chart_of_accounts WHERE code = '2110' LIMIT 1;\n  IF NEW.payment_method = 'cash' THEN\n    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\n  ELSIF NEW.payment_method = 'petty_cash' THEN\n    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1102' LIMIT 1;\n  ELSIF NEW.payment_method = 'bank_transfer' AND NEW.bank_account_id IS NOT NULL THEN\n    SELECT coa_id INTO v_cash_account FROM bank_accounts WHERE id = NEW.bank_account_id;\n  ELSE\n    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\n  END IF;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items, '[]'::jsonb)) LOOP\n    v_supplier := NULLIF(v_item->>'supplier_id', '')::uuid;\n    v_old_base := CASE WHEN v_item->>'ppn_treatment' = 'included'\n      THEN GREATEST(COALESCE((v_item->>'amount')::numeric,0) - COALESCE((v_item->>'ppn_amount')::numeric,0),0)\n      ELSE COALESCE((v_item->>'amount')::numeric,0) END;\n    v_delta := public.broker_reimbursement_expense_base(v_item) - v_old_base;\n    IF v_delta = 0 THEN CONTINUE; END IF;\n\n    SELECT COALESCE(max(line_number),0) + 1 INTO v_line_no\n      FROM journal_entry_lines WHERE journal_entry_id = v_je;\n    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n    VALUES(v_je,v_line_no,v_expense_account,'Reimbursement correction - DPP/PPN line total',v_delta,0,COALESCE(v_supplier,NEW.supplier_id));\n\n    IF v_outstanding THEN\n      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n      VALUES(v_je,v_line_no+1,v_ap_account,'A/P correction - reimbursement line total',0,v_delta,COALESCE(v_supplier,NEW.supplier_id));\n    ELSE\n      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n      VALUES(v_je,v_line_no+1,v_cash_account,'Cash correction - reimbursement line total',0,v_delta,NEW.supplier_id);\n    END IF;\n    UPDATE journal_entries\n       SET total_debit = total_debit + v_delta,\n           total_credit = total_credit + v_delta\n     WHERE id = v_je;\n  END LOOP;\n  SELECT COALESCE(SUM(debit),0), COALESCE(SUM(credit),0)\n    INTO v_debit, v_credit\n    FROM journal_entry_lines WHERE journal_entry_id = v_je;\n  v_balance := v_debit - v_credit;\n  IF v_balance <> 0 THEN\n    SELECT COALESCE(max(line_number),0) + 1 INTO v_line_no\n      FROM journal_entry_lines WHERE journal_entry_id = v_je;\n    IF v_balance > 0 THEN\n      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n      VALUES(v_je,v_line_no, v_cash_account, 'Cash balancing - broker reimbursement total',0,v_balance,NEW.supplier_id);\n    ELSE\n      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n      VALUES(v_je,v_line_no, v_expense_account, 'Expense balancing - broker reimbursement total',-v_balance,0,NEW.supplier_id);\n    END IF;\n  END IF;\n  UPDATE journal_entries je\n     SET total_debit = totals.debit,\n         total_credit = totals.credit\n    FROM (\n      SELECT COALESCE(SUM(debit),0) AS debit, COALESCE(SUM(credit),0) AS credit\n        FROM journal_entry_lines WHERE journal_entry_id = v_je\n    ) totals\n   WHERE je.id = v_je;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: create_batch_inventory_transaction(\\"uuid\\", \\"uuid\\", \\"text\\", numeric, \\"date\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"create_batch_inventory_transaction\\"(\\"p_product_id\\" \\"uuid\\", \\"p_batch_id\\" \\"uuid\\", \\"p_transaction_type\\" \\"text\\", \\"p_quantity\\" numeric, \\"p_transaction_date\\" \\"date\\", \\"p_notes\\" \\"text\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts','warehouse') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot create inventory transactions', v_role;\nEND IF;\n\nINSERT INTO inventory_transactions (\nproduct_id, batch_id, transaction_type, quantity, transaction_date, notes\n) VALUES (\np_product_id, p_batch_id, p_transaction_type, p_quantity, p_transaction_date, p_notes\n);\nEND;\n$$","--\n-- Name: fund_transfers; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"fund_transfers\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"transfer_number\\" \\"text\\" NOT NULL,\n    \\"transfer_date\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"amount\\" numeric(15,2) NOT NULL,\n    \\"from_account_type\\" \\"text\\" NOT NULL,\n    \\"to_account_type\\" \\"text\\" NOT NULL,\n    \\"from_bank_account_id\\" \\"uuid\\",\n    \\"to_bank_account_id\\" \\"uuid\\",\n    \\"description\\" \\"text\\",\n    \\"journal_entry_id\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\" NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"status\\" \\"text\\" DEFAULT 'pending'::\\"text\\",\n    \\"posted_at\\" timestamp with time zone,\n    \\"posted_by\\" \\"uuid\\",\n    \\"from_bank_statement_line_id\\" \\"uuid\\",\n    \\"to_bank_statement_line_id\\" \\"uuid\\",\n    \\"from_amount\\" numeric(15,2) NOT NULL,\n    \\"to_amount\\" numeric(15,2) NOT NULL,\n    \\"exchange_rate\\" numeric(15,6),\n    \\"reversed_at\\" timestamp with time zone,\n    \\"reversed_by\\" \\"uuid\\",\n    CONSTRAINT \\"fund_transfers_amount_check\\" CHECK ((\\"amount\\" > (0)::numeric)),\n    CONSTRAINT \\"fund_transfers_exchange_rate_check\\" CHECK (((\\"exchange_rate\\" IS NULL) OR (\\"exchange_rate\\" > (0)::numeric))),\n    CONSTRAINT \\"fund_transfers_from_account_type_check\\" CHECK ((\\"from_account_type\\" = ANY (ARRAY['petty_cash'::\\"text\\", 'cash_on_hand'::\\"text\\", 'bank'::\\"text\\"]))),\n    CONSTRAINT \\"fund_transfers_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['pending'::\\"text\\", 'posted'::\\"text\\", 'cancelled'::\\"text\\", 'reversed'::\\"text\\"]))),\n    CONSTRAINT \\"fund_transfers_to_account_type_check\\" CHECK ((\\"to_account_type\\" = ANY (ARRAY['petty_cash'::\\"text\\", 'cash_on_hand'::\\"text\\", 'bank'::\\"text\\"]))),\n    CONSTRAINT \\"no_same_account_transfer\\" CHECK ((NOT ((\\"from_account_type\\" = \\"to_account_type\\") AND (COALESCE(\\"from_bank_account_id\\", '00000000-0000-0000-0000-000000000000'::\\"uuid\\") = COALESCE(\\"to_bank_account_id\\", '00000000-0000-0000-0000-000000000000'::\\"uuid\\")))))\n)","--\n-- Name: TABLE \\"fund_transfers\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON TABLE \\"public\\".\\"fund_transfers\\" IS 'Records transfers between petty cash, cash on hand, and bank accounts. Does NOT auto-post journals - use post_fund_transfer_journal() function after verification.'","--\n-- Name: COLUMN \\"fund_transfers\\".\\"from_bank_statement_line_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"fund_transfers\\".\\"from_bank_statement_line_id\\" IS 'Links to bank statement showing money OUT'","--\n-- Name: COLUMN \\"fund_transfers\\".\\"to_bank_statement_line_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"fund_transfers\\".\\"to_bank_statement_line_id\\" IS 'Links to bank statement showing money IN'","--\n-- Name: COLUMN \\"fund_transfers\\".\\"from_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"fund_transfers\\".\\"from_amount\\" IS 'Amount debited from source account (in source currency)'","--\n-- Name: COLUMN \\"fund_transfers\\".\\"to_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"fund_transfers\\".\\"to_amount\\" IS 'Amount credited to destination account (in destination currency)'","--\n-- Name: COLUMN \\"fund_transfers\\".\\"exchange_rate\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"fund_transfers\\".\\"exchange_rate\\" IS 'Exchange rate used for conversion (to_amount / from_amount)'","--\n-- Name: create_fund_transfer_with_posting(\\"date\\", numeric, numeric, \\"text\\", \\"text\\", \\"text\\", \\"uuid\\", \\"uuid\\", \\"uuid\\", \\"uuid\\", numeric, \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"create_fund_transfer_with_posting\\"(\\"p_transfer_date\\" \\"date\\", \\"p_from_amount\\" numeric, \\"p_to_amount\\" numeric, \\"p_from_account_type\\" \\"text\\", \\"p_to_account_type\\" \\"text\\", \\"p_description\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_from_bank_account_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_to_bank_account_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_from_bank_statement_line_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_to_bank_statement_line_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_exchange_rate\\" numeric DEFAULT NULL::numeric, \\"p_created_by\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"public\\".\\"fund_transfers\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_user_id uuid;\n  v_transfer_number text;\n  v_transfer public.fund_transfers;\nBEGIN\n  v_user_id := COALESCE(p_created_by, auth.uid());\n  IF v_user_id IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  v_transfer_number := public.generate_fund_transfer_number();\n\n  INSERT INTO public.fund_transfers (\n    transfer_number,\n    transfer_date,\n    amount,\n    from_amount,\n    to_amount,\n    exchange_rate,\n    from_account_type,\n    to_account_type,\n    from_bank_account_id,\n    to_bank_account_id,\n    from_bank_statement_line_id,\n    to_bank_statement_line_id,\n    description,\n    created_by\n  ) VALUES (\n    v_transfer_number,\n    p_transfer_date,\n    p_from_amount,\n    p_from_amount,\n    p_to_amount,\n    p_exchange_rate,\n    p_from_account_type,\n    p_to_account_type,\n    CASE WHEN p_from_account_type = 'bank' THEN p_from_bank_account_id ELSE NULL END,\n    CASE WHEN p_to_account_type = 'bank' THEN p_to_bank_account_id ELSE NULL END,\n    p_from_bank_statement_line_id,\n    p_to_bank_statement_line_id,\n    NULLIF(p_description, ''),\n    v_user_id\n  )\n  RETURNING * INTO v_transfer;\n\n  RETURN v_transfer;\nEND;\n$$","--\n-- Name: FUNCTION \\"create_fund_transfer_with_posting\\"(\\"p_transfer_date\\" \\"date\\", \\"p_from_amount\\" numeric, \\"p_to_amount\\" numeric, \\"p_from_account_type\\" \\"text\\", \\"p_to_account_type\\" \\"text\\", \\"p_description\\" \\"text\\", \\"p_from_bank_account_id\\" \\"uuid\\", \\"p_to_bank_account_id\\" \\"uuid\\", \\"p_from_bank_statement_line_id\\" \\"uuid\\", \\"p_to_bank_statement_line_id\\" \\"uuid\\", \\"p_exchange_rate\\" numeric, \\"p_created_by\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"create_fund_transfer_with_posting\\"(\\"p_transfer_date\\" \\"date\\", \\"p_from_amount\\" numeric, \\"p_to_amount\\" numeric, \\"p_from_account_type\\" \\"text\\", \\"p_to_account_type\\" \\"text\\", \\"p_description\\" \\"text\\", \\"p_from_bank_account_id\\" \\"uuid\\", \\"p_to_bank_account_id\\" \\"uuid\\", \\"p_from_bank_statement_line_id\\" \\"uuid\\", \\"p_to_bank_statement_line_id\\" \\"uuid\\", \\"p_exchange_rate\\" numeric, \\"p_created_by\\" \\"uuid\\") IS 'Creates fund_transfers and petty cash withdrawal (for to_account_type=petty_cash) in one transaction. Idempotent petty cash insertion uses the partial unique index on petty_cash_transactions(fund_transfer_id) where fund_transfer_id is not null.'","--\n-- Name: create_purchase_invoice_from_po(\\"uuid\\", \\"jsonb\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"create_purchase_invoice_from_po\\"(\\"p_purchase_order_id\\" \\"uuid\\", \\"p_invoice_data\\" \\"jsonb\\", \\"p_items\\" \\"jsonb\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_po public.purchase_orders%ROWTYPE;\n  v_result jsonb;\n  v_invoice_id uuid;\n  v_item jsonb;\n  v_po_item public.purchase_order_items%ROWTYPE;\n  v_ordinal integer := 0;\n  v_invoice_item_id uuid;\nBEGIN\n  SELECT * INTO v_po\n    FROM public.purchase_orders\n   WHERE id = p_purchase_order_id\n   FOR SHARE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Purchase Order not found';\n  END IF;\n\n  IF NULLIF(p_invoice_data->>'supplier_id', '')::uuid IS DISTINCT FROM v_po.supplier_id THEN\n    RAISE EXCEPTION 'Purchase Invoice supplier must match the Purchase Order supplier';\n  END IF;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))\n  LOOP\n    IF NULLIF(v_item->>'purchase_order_item_id', '') IS NULL THEN\n      RAISE EXCEPTION 'Each PO invoice line requires purchase_order_item_id';\n    END IF;\n    SELECT * INTO v_po_item\n      FROM public.purchase_order_items\n     WHERE id = (v_item->>'purchase_order_item_id')::uuid\n       AND po_id = p_purchase_order_id;\n    IF NOT FOUND THEN\n      RAISE EXCEPTION 'Purchase Invoice item is not a line of the selected Purchase Order';\n    END IF;\n    IF NULLIF(v_item->>'product_id', '')::uuid IS DISTINCT FROM v_po_item.product_id THEN\n      RAISE EXCEPTION 'Purchase Invoice product does not match its Purchase Order line';\n    END IF;\n  END LOOP;\n\n  v_result := public.save_purchase_invoice(NULL, p_invoice_data, p_items);\n  v_invoice_id := (v_result->>'invoice_id')::uuid;\n\n  UPDATE public.purchase_invoices\n     SET purchase_order_id = p_purchase_order_id\n   WHERE id = v_invoice_id;\n\n  -- save_purchase_invoice inserts lines in JSON-array order. Match by the\n  -- same stable creation ordering and persist each PO line link.\n  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))\n  LOOP\n    v_ordinal := v_ordinal + 1;\n    SELECT id INTO v_invoice_item_id\n      FROM public.purchase_invoice_items\n     WHERE purchase_invoice_id = v_invoice_id\n     -- ctid reflects the insert order within this transaction (the existing\n     -- save RPC does not expose a line number), so duplicate-product lines\n     -- still map deterministically to the input array.\n     ORDER BY ctid\n     OFFSET v_ordinal - 1 LIMIT 1;\n    IF v_invoice_item_id IS NOT NULL THEN\n      UPDATE public.purchase_invoice_items\n         SET purchase_order_item_id = (v_item->>'purchase_order_item_id')::uuid\n       WHERE id = v_invoice_item_id;\n    END IF;\n  END LOOP;\n\n  RETURN v_result || jsonb_build_object('purchase_order_id', p_purchase_order_id);\nEND;\n$$","--\n-- Name: create_sales_invoice_atomic(\\"jsonb\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"create_sales_invoice_atomic\\"(\\"p_invoice\\" \\"jsonb\\", \\"p_items\\" \\"jsonb\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_role text;\n  v_invoice_id uuid;\n  v_subtotal numeric := 0;\n  v_tax numeric := 0;\n  v_discount numeric := COALESCE((p_invoice->>'discount_amount')::numeric, 0);\n  v_stamp numeric := COALESCE((p_invoice->>'stamp_duty_amount')::numeric, 0);\n  v_total numeric;\n  v_count integer := 0;\n  v_item jsonb;\n  v_product uuid;\n  v_batch uuid;\n  v_dc_item uuid;\n  v_qty numeric;\n  v_price numeric;\n  v_rate numeric;\n  v_dc record;\n  v_linked_challans uuid[];\n  v_invoice_so_id uuid := NULLIF(p_invoice->>'sales_order_id','')::uuid;\nBEGIN\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role IS NULL OR v_role NOT IN ('admin','accounts','sales','manager','warehouse') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot create sales invoices', v_role;\n  END IF;\n  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN\n    RAISE EXCEPTION 'Sales invoice requires at least one product line';\n  END IF;\n  IF NULLIF(p_invoice->>'invoice_number','') IS NULL OR NULLIF(p_invoice->>'customer_id','') IS NULL THEN\n    RAISE EXCEPTION 'Invoice number and customer are required';\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.sales_invoices WHERE invoice_number=p_invoice->>'invoice_number') THEN\n    RAISE EXCEPTION 'Invoice number already exists';\n  END IF;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)\n  LOOP\n    v_product := NULLIF(v_item->>'product_id','')::uuid;\n    v_batch := NULLIF(v_item->>'batch_id','')::uuid;\n    v_dc_item := NULLIF(v_item->>'delivery_challan_item_id','')::uuid;\n    v_qty := (v_item->>'quantity')::numeric;\n    v_price := (v_item->>'unit_price')::numeric;\n    v_rate := COALESCE((v_item->>'tax_rate')::numeric, 0);\n    IF v_product IS NULL OR v_dc_item IS NULL OR COALESCE(v_qty,0) <= 0 OR COALESCE(v_price,0) < 0 THEN\n      RAISE EXCEPTION 'Every invoice line must have a source Delivery Challan item, product, quantity, and price';\n    END IF;\n    SELECT dci.product_id,dci.batch_id,dci.quantity,dc.customer_id,dc.approval_status,dc.sales_order_id\n      INTO v_dc\n    FROM public.delivery_challan_items dci\n    JOIN public.delivery_challans dc ON dc.id=dci.challan_id\n    WHERE dci.id=v_dc_item\n    FOR SHARE;\n    IF NOT FOUND OR v_dc.product_id IS DISTINCT FROM v_product OR v_dc.batch_id IS DISTINCT FROM v_batch\n       OR v_dc.customer_id IS DISTINCT FROM (p_invoice->>'customer_id')::uuid\n       OR v_dc.approval_status <> 'approved' THEN\n      RAISE EXCEPTION 'Invoice line source Delivery Challan is invalid or not approved';\n    END IF;\n    IF v_invoice_so_id IS NOT NULL AND v_dc.sales_order_id IS DISTINCT FROM v_invoice_so_id THEN\n      RAISE EXCEPTION 'Invoice Sales Order does not match its Delivery Challan source';\n    END IF;\n    IF v_qty > v_dc.quantity - COALESCE((SELECT sum(sii.quantity) FROM public.sales_invoice_items sii\n      WHERE sii.delivery_challan_item_id=v_dc_item),0) THEN\n      RAISE EXCEPTION 'Invoice quantity exceeds remaining Delivery Challan quantity';\n    END IF;\n    v_subtotal := v_subtotal + (v_qty * v_price);\n    v_tax := v_tax + (v_qty * v_price * v_rate / 100);\n    v_count := v_count + 1;\n  END LOOP;\n  v_total := v_subtotal + v_tax - v_discount + v_stamp;\n  SELECT array_agg(DISTINCT dc.id) INTO v_linked_challans\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id=dci.challan_id\n  WHERE dci.id IN (SELECT (value->>'delivery_challan_item_id')::uuid FROM jsonb_array_elements(p_items));\n  IF p_invoice ? 'subtotal' AND abs(v_subtotal - (p_invoice->>'subtotal')::numeric) > 0.01\n     OR p_invoice ? 'tax_amount' AND abs(v_tax - (p_invoice->>'tax_amount')::numeric) > 0.01\n     OR p_invoice ? 'total_amount' AND abs(v_total - (p_invoice->>'total_amount')::numeric) > 0.01 THEN\n    RAISE EXCEPTION 'Invoice totals do not match persisted product lines';\n  END IF;\n\n  INSERT INTO public.sales_invoices (\n    invoice_number,customer_id,sales_order_id,invoice_date,due_date,discount_amount,\n    delivery_challan_number,po_number,payment_terms_days,notes,subtotal,tax_amount,\n    stamp_duty_amount,total_amount,payment_status,created_by,linked_challan_ids\n  ) VALUES (\n    p_invoice->>'invoice_number',(p_invoice->>'customer_id')::uuid,v_invoice_so_id,\n    COALESCE((p_invoice->>'invoice_date')::date,CURRENT_DATE),(p_invoice->>'due_date')::date,v_discount,\n    NULL,p_invoice->>'po_number',(p_invoice->>'payment_terms_days')::integer,p_invoice->>'notes',\n    v_subtotal,v_tax,v_stamp,v_total,'pending',COALESCE(NULLIF(p_invoice->>'created_by','')::uuid,auth.uid()),\n    COALESCE(v_linked_challans, CASE WHEN jsonb_typeof(p_invoice->'linked_challan_ids')='array' THEN\n      ARRAY(SELECT jsonb_array_elements_text(p_invoice->'linked_challan_ids')::uuid) ELSE NULL END)\n  ) RETURNING id INTO v_invoice_id;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)\n  LOOP\n    INSERT INTO public.sales_invoice_items\n      (invoice_id,product_id,batch_id,quantity,unit_price,tax_rate,delivery_challan_item_id)\n    VALUES (v_invoice_id,(v_item->>'product_id')::uuid,NULLIF(v_item->>'batch_id','')::uuid,\n      (v_item->>'quantity')::numeric,(v_item->>'unit_price')::numeric,\n      COALESCE((v_item->>'tax_rate')::numeric,0),(v_item->>'delivery_challan_item_id')::uuid);\n  END LOOP;\n\n  IF (SELECT count(*) FROM public.sales_invoice_items WHERE invoice_id=v_invoice_id) <> v_count THEN\n    RAISE EXCEPTION 'Invoice line count verification failed';\n  END IF;\n  RETURN v_invoice_id;\nEND;\n$$","--\n-- Name: create_staff_account(\\"text\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"create_staff_account\\"(\\"p_staff_name\\" \\"text\\", \\"p_employee_id\\" \\"text\\" DEFAULT NULL::\\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nv_coa_id UUID;\nv_staff_id UUID;\nv_next_code TEXT;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin') THEN\nRAISE EXCEPTION 'Permission denied: only admin can create staff accounts';\nEND IF;\n\nSELECT coa_account_id INTO v_coa_id\nFROM staff_members\nWHERE LOWER(staff_name) = LOWER(p_staff_name);\n\nIF v_coa_id IS NOT NULL THEN\nRETURN v_coa_id;\nEND IF;\n\nSELECT '116' || LPAD((COUNT(*) + 1)::TEXT, 1, '0')\nINTO v_next_code\nFROM chart_of_accounts\nWHERE code LIKE '116%' AND code != '1160';\n\nINSERT INTO chart_of_accounts (code, name, account_type, is_active, description)\nVALUES (\nv_next_code,\np_staff_name || ' - Staff Advance',\n'asset',\ntrue,\n'Staff advance account for ' || p_staff_name\n)\nRETURNING id INTO v_coa_id;\n\nINSERT INTO staff_members (staff_name, coa_account_id, employee_id)\nVALUES (p_staff_name, v_coa_id, p_employee_id)\nRETURNING id INTO v_staff_id;\n\nRETURN v_coa_id;\nEND;\n$$","--\n-- Name: FUNCTION \\"create_staff_account\\"(\\"p_staff_name\\" \\"text\\", \\"p_employee_id\\" \\"text\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"create_staff_account\\"(\\"p_staff_name\\" \\"text\\", \\"p_employee_id\\" \\"text\\") IS 'Creates staff account in COA and staff_members table'","--\n-- Name: create_system_task(\\"text\\", \\"text\\", timestamp with time zone, \\"text\\", \\"text\\", \\"uuid\\", \\"text\\", \\"text\\", \\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"create_system_task\\"(\\"p_title\\" \\"text\\", \\"p_description\\" \\"text\\", \\"p_deadline\\" timestamp with time zone, \\"p_origin\\" \\"text\\", \\"p_reference_type\\" \\"text\\", \\"p_reference_id\\" \\"uuid\\", \\"p_assigned_role\\" \\"text\\", \\"p_priority\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_customer_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_product_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nv_task_id uuid;\nv_assigned_users uuid[];\nv_auto_priority text;\nv_creator_id uuid;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot create system tasks', v_role;\nEND IF;\n\nv_assigned_users := get_users_by_role(p_assigned_role);\nv_auto_priority  := COALESCE(p_priority, calculate_task_priority(p_deadline));\n\nSELECT id INTO v_creator_id FROM user_profiles WHERE role = 'admin' AND is_active = true LIMIT 1;\nIF v_creator_id IS NULL THEN\nSELECT id INTO v_creator_id FROM user_profiles WHERE is_active = true LIMIT 1;\nEND IF;\n\nINSERT INTO tasks (\ntitle, description, deadline, priority, auto_priority, status,\ntask_type, task_mode, task_origin, reference_type, reference_id,\nauto_assigned_role, assigned_users, customer_id, product_id, created_by, proof_required\n) VALUES (\np_title, p_description, p_deadline, v_auto_priority::task_priority, v_auto_priority, 'to_do'::task_status,\n'system', 'advisory', p_origin, p_reference_type, p_reference_id,\np_assigned_role, v_assigned_users, p_customer_id, p_product_id, v_creator_id, false\n)\nRETURNING id INTO v_task_id;\n\nIF array_length(v_assigned_users, 1) > 0 THEN\nINSERT INTO task_assignments (task_id, assigned_user_id, assigned_by)\nSELECT v_task_id, unnest(v_assigned_users), v_creator_id;\nEND IF;\n\nRETURN v_task_id;\nEND;\n$$","--\n-- Name: create_system_task(\\"text\\", \\"text\\", timestamp with time zone, \\"public\\".\\"task_priority\\", \\"uuid\\"[], \\"public\\".\\"task_origin_enum\\", \\"uuid\\", \\"uuid\\", \\"uuid\\", \\"text\\"[], \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"create_system_task\\"(\\"p_title\\" \\"text\\", \\"p_description\\" \\"text\\", \\"p_deadline\\" timestamp with time zone, \\"p_priority\\" \\"public\\".\\"task_priority\\", \\"p_assigned_users\\" \\"uuid\\"[], \\"p_task_origin\\" \\"public\\".\\"task_origin_enum\\", \\"p_sales_order_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_customer_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_product_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_tags\\" \\"text\\"[] DEFAULT ARRAY[]::\\"text\\"[], \\"p_metadata\\" \\"jsonb\\" DEFAULT '{}'::\\"jsonb\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nv_task_id uuid;\nv_system_user uuid;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot create system tasks', v_role;\nEND IF;\n\nSELECT id INTO v_system_user FROM user_profiles WHERE role = 'admin' LIMIT 1;\nIF v_system_user IS NULL THEN\nv_system_user := auth.uid();\nEND IF;\n\nINSERT INTO tasks (\ntitle, description, deadline, priority, status, created_by, assigned_users,\ntask_type, task_mode, task_origin, sales_order_id, customer_id, product_id,\ntags, auto_priority, system_metadata\n) VALUES (\np_title, p_description, p_deadline, p_priority, 'to_do', v_system_user, p_assigned_users,\n'system', 'advisory', p_task_origin, p_sales_order_id, p_customer_id, p_product_id,\narray_append(p_tags, 'system-generated'), true, p_metadata\n)\nRETURNING id INTO v_task_id;\n\nRETURN v_task_id;\nEND;\n$$","--\n-- Name: create_task_status_history(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"create_task_status_history\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status) THEN\nINSERT INTO task_status_history (\ntask_id,\nold_status,\nnew_status,\nchanged_by,\nnotes\n) VALUES (\nNEW.id,\nOLD.status,\nNEW.status,\nNEW.updated_by,\n'Status changed from ' || OLD.status || ' to ' || NEW.status\n);\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: current_user_has_pricing_role(\\"text\\"[]); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"current_user_has_pricing_role\\"(\\"allowed_roles\\" \\"text\\"[]) RETURNS boolean\n    LANGUAGE \\"sql\\" STABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT EXISTS (\n    SELECT 1 FROM user_profiles\n    WHERE id = auth.uid()\n      AND is_active = true\n      AND role = ANY(allowed_roles)\n  );\n$$","--\n-- Name: delete_batch_safe(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"delete_batch_safe\\"(\\"p_batch_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_result jsonb;\nBEGIN\n  v_result := public.archive_batch_inventory_v1(p_batch_id);\n  RETURN jsonb_build_object(\n    'deleted', false,\n    'archived', COALESCE((v_result->>'archived')::boolean, false),\n    'batch_id', v_result->>'batch_id',\n    'batch_number', v_result->>'batch_number',\n    'reason', COALESCE(\n      v_result->>'reason',\n      'Inventory V1 preserves batch and movement history; the batch was archived'\n    )\n  );\nEND;\n$$","--\n-- Name: delete_company_profile(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"delete_company_profile\\"(\\"p_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_ref_count bigint;\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND role = 'admin') THEN\n    RAISE EXCEPTION 'FORBIDDEN: Only admins may delete company profiles.';\n  END IF;\n\n  IF NOT EXISTS (SELECT 1 FROM public.company_profiles WHERE id = p_id) THEN\n    RAISE EXCEPTION 'NOT_FOUND: Company profile does not exist.';\n  END IF;\n\n  -- Setup Mode: skip the reference-count check. The trigger above also\n  -- no-ops in this mode, so the DELETE proceeds cleanly.\n  IF NOT public.is_setup_mode() THEN\n    SELECT COALESCE(SUM(ref_count), 0) INTO v_ref_count\n    FROM public.get_company_profile_reference_counts()\n    WHERE profile_id = p_id;\n\n    IF v_ref_count > 0 THEN\n      RAISE EXCEPTION\n        'PROFILE_REFERENCED: This Company Profile is already referenced by % business document(s) and cannot be deleted. Historical company identities must remain permanently available.',\n        v_ref_count;\n    END IF;\n  END IF;\n\n  DELETE FROM public.company_profiles WHERE id = p_id;\nEND;\n$$","--\n-- Name: delete_expense_journal_entries(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"delete_expense_journal_entries\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- Delete journal entry lines first (foreign key)\nDELETE FROM journal_entry_lines jel\nWHERE jel.journal_entry_id IN (\nSELECT je.id FROM journal_entries je\nWHERE je.source_module IN ('expense', 'expenses')\nAND je.reference_number = 'EXP-' || OLD.id::text\n);\n\n-- Delete journal entries for this expense\nDELETE FROM journal_entries \nWHERE source_module IN ('expense', 'expenses')\nAND reference_number = 'EXP-' || OLD.id::text;\n\nRETURN OLD;\nEND;\n$$","--\n-- Name: delete_expense_safe(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"delete_expense_safe\\"(\\"p_expense_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_role text;\n  v_expense public.finance_expenses%ROWTYPE;\n  v_allocation_count integer;\n  v_legacy_count integer;\nBEGIN\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot delete expenses', v_role;\n  END IF;\n\n  SELECT * INTO v_expense\n    FROM public.finance_expenses\n   WHERE id = p_expense_id\n   FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\n\n  SELECT count(*) INTO v_allocation_count\n    FROM public.bank_statement_allocations\n   WHERE document_type = 'expense'\n     AND document_id = p_expense_id;\n\n  -- Separate statement: allocation triggers may safely recalculate the still\n  -- existing expense, then the source row and its journals are deleted.\n  DELETE FROM public.bank_statement_allocations\n   WHERE document_type = 'expense'\n     AND document_id = p_expense_id;\n\n  -- Release pre-allocation legacy links to this expense. Allocation-owned\n  -- lines have already been rebuilt by sync_bank_line_from_allocation().\n  WITH released AS (\n    UPDATE public.bank_statement_lines b SET\n      matched_expense_id = NULL,\n      matched_entry_id = NULL,\n      reconciliation_status = 'unmatched',\n      matching_status = 'none',\n      matched_at = NULL,\n      matched_by = NULL,\n      manually_unlinked = true\n    WHERE b.matched_expense_id = p_expense_id\n      AND NOT EXISTS (\n        SELECT 1 FROM public.bank_statement_allocations a\n         WHERE a.bank_statement_line_id = b.id\n      )\n    RETURNING 1\n  ) SELECT count(*) INTO v_legacy_count FROM released;\n\n  DELETE FROM public.finance_expenses WHERE id = p_expense_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.bank_statement_allocations\n     WHERE document_type = 'expense' AND document_id = p_expense_id\n  ) THEN\n    RAISE EXCEPTION 'Expense delete left orphan bank allocations';\n  END IF;\n  IF EXISTS (\n    SELECT 1 FROM public.bank_statement_lines WHERE matched_expense_id = p_expense_id\n  ) THEN\n    RAISE EXCEPTION 'Expense delete left orphan bank references';\n  END IF;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'released_allocations', v_allocation_count,\n    'released_legacy_lines', v_legacy_count\n  );\nEND;\n$$","--\n-- Name: delete_fund_transfer(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"delete_fund_transfer\\"(\\"p_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $_$\nDECLARE\n  v_transfer             public.fund_transfers%ROWTYPE;\n  v_je_ids               uuid[];\n  v_period               record;\n  v_dependency           record;\n  v_orphan_count         integer;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n\n  IF p_id IS NULL THEN\n    RAISE EXCEPTION 'Fund transfer id is required'\n      USING ERRCODE = 'invalid_parameter_value';\n  END IF;\n\n  SELECT *\n    INTO v_transfer\n    FROM public.fund_transfers\n   WHERE id = p_id\n   FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Fund transfer % not found', p_id\n      USING ERRCODE = 'no_data_found';\n  END IF;\n\n  IF v_transfer.status = 'posted' THEN\n    RAISE EXCEPTION\n      'Posted fund transfer % cannot be deleted. Reverse it first, then delete it while the accounting period is open.',\n      v_transfer.transfer_number\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  SELECT ap.fiscal_year, ap.period_month, ap.status\n    INTO v_period\n    FROM public.accounting_periods ap\n   WHERE ap.start_date <= v_transfer.transfer_date\n     AND ap.end_date >= v_transfer.transfer_date\n   ORDER BY ap.start_date DESC\n   LIMIT 1;\n\n  IF FOUND AND v_period.status <> 'open' THEN\n    RAISE EXCEPTION\n      'Cannot delete fund transfer %: accounting period %-% is %.',\n      v_transfer.transfer_number,\n      v_period.fiscal_year,\n      lpad(v_period.period_month::text, 2, '0'),\n      v_period.status\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  SELECT COALESCE(array_agg(DISTINCT je.id), ARRAY[]::uuid[])\n    INTO v_je_ids\n    FROM public.journal_entries je\n   WHERE je.source_module = 'fund_transfers'\n     AND (\n       je.reference_id = p_id\n       OR je.reference_number IN (\n         v_transfer.transfer_number,\n         'REV-' || v_transfer.transfer_number\n       )\n     );\n\n  FOR v_period IN\n    SELECT DISTINCT\n           ap.fiscal_year,\n           ap.period_month,\n           ap.status,\n           je.entry_date\n      FROM public.journal_entries je\n      JOIN public.accounting_periods ap\n        ON ap.start_date <= je.entry_date\n       AND ap.end_date >= je.entry_date\n     WHERE je.id = ANY(v_je_ids)\n       AND ap.status <> 'open'\n  LOOP\n    RAISE EXCEPTION\n      'Cannot delete fund transfer %: journal accounting period %-% for % is %.',\n      v_transfer.transfer_number,\n      v_period.fiscal_year,\n      lpad(v_period.period_month::text, 2, '0'),\n      v_period.entry_date,\n      v_period.status\n      USING ERRCODE = 'check_violation';\n  END LOOP;\n\n  IF EXISTS (\n    SELECT 1\n      FROM public.journal_entries je\n     WHERE je.reversed_by_id = ANY(v_je_ids)\n       AND NOT (je.id = ANY(v_je_ids))\n  ) THEN\n    RAISE EXCEPTION\n      'Cannot delete fund transfer %: an unrelated journal entry depends on its reversal journal.',\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  -- Refuse to let an unexpected ON DELETE action modify another document.\n  -- Expected Contra, ledger, and reconciliation owners are cleaned below.\n  FOR v_dependency IN\n    SELECT c.conrelid::regclass AS relation_name,\n           a.attname AS column_name\n      FROM pg_catalog.pg_constraint c\n      JOIN pg_catalog.pg_attribute a\n        ON a.attrelid = c.conrelid\n       AND a.attnum = c.conkey[1]\n     WHERE c.contype = 'f'\n       AND c.confrelid = 'public.journal_entries'::regclass\n       AND array_length(c.conkey, 1) = 1\n       AND NOT (\n         (c.conrelid = 'public.journal_entry_lines'::regclass\n          AND a.attname = 'journal_entry_id')\n         OR (c.conrelid = 'public.fund_transfers'::regclass\n             AND a.attname = 'journal_entry_id')\n         OR (c.conrelid = 'public.bank_statement_lines'::regclass\n             AND a.attname = 'matched_entry_id')\n         OR (c.conrelid = 'public.bank_reconciliation_items'::regclass\n             AND a.attname = 'journal_entry_id')\n         OR (c.conrelid = 'public.journal_entries'::regclass\n             AND a.attname = 'reversed_by_id')\n       )\n  LOOP\n    EXECUTE format(\n      'SELECT count(*) FROM %s WHERE %I = ANY($1)',\n      v_dependency.relation_name,\n      v_dependency.column_name\n    )\n    INTO v_orphan_count\n    USING v_je_ids;\n\n    IF v_orphan_count <> 0 THEN\n      RAISE EXCEPTION\n        'Cannot delete fund transfer %: % dependent record(s) in % still reference its journal entry.',\n        v_transfer.transfer_number,\n        v_orphan_count,\n        v_dependency.relation_name\n        USING ERRCODE = 'foreign_key_violation';\n    END IF;\n  END LOOP;\n\n  -- Break the Fund Transfer -> Journal Entry FK cycle before deleting journals.\n  UPDATE public.fund_transfers\n     SET journal_entry_id = NULL\n   WHERE id = p_id;\n\n  -- Release only links owned by this Contra or one of its collected journals.\n  UPDATE public.bank_statement_lines\n     SET matched_fund_transfer_id = NULL,\n         matched_entry_id = NULL,\n         reconciliation_status = 'unmatched',\n         matched_at = NULL,\n         matched_by = NULL,\n         notes = NULL\n   WHERE matched_fund_transfer_id = p_id\n      OR matched_entry_id = ANY(v_je_ids);\n\n  UPDATE public.bank_reconciliation_items\n     SET journal_entry_id = NULL,\n         is_matched = false,\n         matched_at = NULL\n   WHERE journal_entry_id = ANY(v_je_ids);\n\n  -- Petty Cash displays current Fund Transfers directly. This cleanup is only\n  -- for legacy projection rows and cannot create or alter accounting.\n  DELETE FROM public.petty_cash_transactions\n   WHERE fund_transfer_id = p_id;\n\n  UPDATE public.journal_entries\n     SET is_reversed = false,\n         reversed_by_id = NULL\n   WHERE id = ANY(v_je_ids)\n     AND reversed_by_id = ANY(v_je_ids);\n\n  DELETE FROM public.journal_entry_lines\n   WHERE journal_entry_id = ANY(v_je_ids);\n\n  DELETE FROM public.journal_entries\n   WHERE id = ANY(v_je_ids);\n\n  DELETE FROM public.fund_transfers\n   WHERE id = p_id;\n\n  -- Every check runs before commit. Any failure rolls the entire deletion back.\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.fund_transfers\n   WHERE id = p_id;\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: fund transfer % still exists. No changes were committed.',\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.journal_entries\n   WHERE id = ANY(v_je_ids)\n      OR (\n        source_module = 'fund_transfers'\n        AND (\n          reference_id = p_id\n          OR reference_number IN (\n            v_transfer.transfer_number,\n            'REV-' || v_transfer.transfer_number\n          )\n        )\n      );\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: % related journal entries remain for fund transfer %. No changes were committed.',\n      v_orphan_count,\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id = ANY(v_je_ids);\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: % related ledger postings remain for fund transfer %. No changes were committed.',\n      v_orphan_count,\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.petty_cash_transactions\n   WHERE fund_transfer_id = p_id;\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: % related Petty Cash rows remain for fund transfer %. No changes were committed.',\n      v_orphan_count,\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.bank_statement_lines\n   WHERE matched_fund_transfer_id = p_id\n      OR matched_entry_id = ANY(v_je_ids);\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: % Bank Reconciliation links remain for fund transfer %. No changes were committed.',\n      v_orphan_count,\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.bank_reconciliation_items\n   WHERE journal_entry_id = ANY(v_je_ids);\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: % Bank Reconciliation items remain for fund transfer %. No changes were committed.',\n      v_orphan_count,\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\nEND;\n$_$","--\n-- Name: delete_payment_voucher_with_allocations(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"delete_payment_voucher_with_allocations\\"(\\"p_voucher_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\nv_invoice_id uuid;\nv_affected_invoice_ids uuid[];\nBEGIN\nSELECT COALESCE(array_agg(DISTINCT purchase_invoice_id), ARRAY[]::uuid[])\nINTO v_affected_invoice_ids\nFROM public.voucher_allocations\nWHERE payment_voucher_id = p_voucher_id\nAND purchase_invoice_id IS NOT NULL;\n\nDELETE FROM public.voucher_allocations\nWHERE payment_voucher_id = p_voucher_id;\n\nDELETE FROM public.payment_vouchers\nWHERE id = p_voucher_id;\n\nIF NOT FOUND THEN\nRAISE EXCEPTION 'Payment voucher % not found', p_voucher_id;\nEND IF;\n\nFOR v_invoice_id IN SELECT DISTINCT unnest(v_affected_invoice_ids) LOOP\nPERFORM public.recalculate_purchase_invoice_payment_state(v_invoice_id);\nEND LOOP;\nEND;\n$$","--\n-- Name: delete_petty_cash_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"delete_petty_cash_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  UPDATE public.bank_statement_lines\n     SET matched_petty_cash_id = NULL,\n         matched_entry_id = NULL,\n         reconciliation_status = 'unmatched',\n         matched_at = NULL,\n         matched_by = NULL,\n         notes = NULL\n   WHERE matched_petty_cash_id = OLD.id\n      OR matched_entry_id IN (\n        SELECT id\n          FROM public.journal_entries\n         WHERE source_module = 'petty_cash'\n           AND reference_id = OLD.id\n      );\n\n  DELETE FROM public.journal_entry_lines\n   WHERE journal_entry_id IN (\n     SELECT id\n       FROM public.journal_entries\n      WHERE source_module = 'petty_cash'\n        AND reference_id = OLD.id\n   );\n\n  DELETE FROM public.journal_entries\n   WHERE source_module = 'petty_cash'\n     AND reference_id = OLD.id;\n\n  RETURN OLD;\nEND;\n$$","--\n-- Name: FUNCTION \\"delete_petty_cash_journal\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"delete_petty_cash_journal\\"() IS 'Automatically deletes associated journal entries when petty cash transaction is deleted'","--\n-- Name: delete_purchase_invoice(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"delete_purchase_invoice\\"(\\"p_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_invoice           purchase_invoices%ROWTYPE;\n  v_je_ids            UUID[];\n  v_affected_pvs      UUID[];\n  v_original_je_id    UUID;\n  v_orphan_pv_je_ids  UUID[];\n\n  -- integrity-check counters\n  v_orphan_pi         INT;\n  v_orphan_items      INT;\n  v_orphan_allocs     INT;\n  v_orphan_jes        INT;\n  v_orphan_je_lines   INT;\n  v_orphan_bsl_pi     INT;\n  v_orphan_bsl_pv     INT;\n  v_orphan_batches    INT;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'insufficient_privilege';\n  END IF;\n\n  IF p_id IS NULL THEN\n    RAISE EXCEPTION 'Purchase invoice id is required' USING ERRCODE = 'invalid_parameter_value';\n  END IF;\n\n  -- (a) Lock the invoice row.\n  SELECT * INTO v_invoice\n    FROM public.purchase_invoices\n   WHERE id = p_id\n   FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Purchase invoice % not found', p_id USING ERRCODE = 'no_data_found';\n  END IF;\n\n  v_original_je_id := v_invoice.journal_entry_id;\n\n  -- Collect every JE created by this invoice.\n  SELECT COALESCE(array_agg(id), ARRAY[]::UUID[])\n    INTO v_je_ids\n    FROM public.journal_entries\n   WHERE source_module = 'purchase_invoice'\n     AND reference_id  = p_id;\n\n  IF v_original_je_id IS NOT NULL\n     AND NOT v_original_je_id = ANY (v_je_ids) THEN\n    v_je_ids := array_append(v_je_ids, v_original_je_id);\n  END IF;\n\n  -- Payment vouchers that were paying THIS invoice.\n  SELECT COALESCE(array_agg(DISTINCT payment_voucher_id), ARRAY[]::UUID[])\n    INTO v_affected_pvs\n    FROM public.voucher_allocations\n   WHERE purchase_invoice_id = p_id\n     AND payment_voucher_id IS NOT NULL;\n\n  -- Drop the allocations pointing at this invoice.\n  DELETE FROM public.voucher_allocations\n   WHERE purchase_invoice_id = p_id;\n\n  -- Identify PVs whose allocations are now empty and release their bank matches.\n  IF array_length(v_affected_pvs, 1) IS NOT NULL THEN\n    SELECT COALESCE(array_agg(pv.journal_entry_id), ARRAY[]::UUID[])\n      INTO v_orphan_pv_je_ids\n      FROM public.payment_vouchers pv\n     WHERE pv.id = ANY (v_affected_pvs)\n       AND pv.journal_entry_id IS NOT NULL\n       AND NOT EXISTS (\n             SELECT 1\n               FROM public.voucher_allocations va\n              WHERE va.payment_voucher_id = pv.id\n           );\n\n    IF array_length(v_orphan_pv_je_ids, 1) IS NOT NULL THEN\n      UPDATE public.bank_statement_lines\n         SET matched_entry_id        = NULL,\n             matched_expense_id      = NULL,\n             matched_receipt_id      = NULL,\n             matched_petty_cash_id   = NULL,\n             matched_fund_transfer_id= NULL,\n             reconciliation_status   = 'unmatched',\n             matched_at              = NULL,\n             matched_by              = NULL\n       WHERE matched_entry_id = ANY (v_orphan_pv_je_ids);\n    END IF;\n  END IF;\n\n  -- Bank recon cleanup for the PI's OWN JEs (all typed FKs).\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    UPDATE public.bank_statement_lines\n       SET matched_entry_id        = NULL,\n           matched_expense_id      = NULL,\n           matched_receipt_id      = NULL,\n           matched_petty_cash_id   = NULL,\n           matched_fund_transfer_id= NULL,\n           reconciliation_status   = 'unmatched',\n           matched_at              = NULL,\n           matched_by              = NULL\n     WHERE matched_entry_id = ANY (v_je_ids);\n  END IF;\n\n  -- Break invoice → JE FK before deleting the JE.\n  IF v_original_je_id IS NOT NULL THEN\n    UPDATE public.purchase_invoices\n       SET journal_entry_id = NULL\n     WHERE id = p_id;\n  END IF;\n\n  -- Delete JE lines then JE headers.\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    DELETE FROM public.journal_entry_lines\n     WHERE journal_entry_id = ANY (v_je_ids);\n\n    DELETE FROM public.journal_entries\n     WHERE id = ANY (v_je_ids);\n  END IF;\n\n  -- Detach batches.\n  UPDATE public.batches\n     SET purchase_invoice_id = NULL\n   WHERE purchase_invoice_id = p_id;\n\n  -- Belt-and-braces items delete.\n  DELETE FROM public.purchase_invoice_items\n   WHERE purchase_invoice_id = p_id;\n\n  -- Delete the invoice row.\n  DELETE FROM public.purchase_invoices\n   WHERE id = p_id;\n\n  -- ═════════════════════════════════════════════════════════════════════\n  -- INTEGRITY CHECKS\n  --\n  -- Every RAISE EXCEPTION below rolls back this transaction — the invoice\n  -- stays, the JE stays, allocations stay. Better a visible failure than\n  -- silent orphan state on the bank reconciliation screen.\n  -- ═════════════════════════════════════════════════════════════════════\n\n  SELECT COUNT(*) INTO v_orphan_pi\n    FROM public.purchase_invoices\n   WHERE id = p_id;\n  IF v_orphan_pi <> 0 THEN\n    RAISE EXCEPTION\n      'delete_purchase_invoice(%): integrity check failed — purchase_invoices row still present (count=%). Rolling back.',\n      p_id, v_orphan_pi\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_items\n    FROM public.purchase_invoice_items\n   WHERE purchase_invoice_id = p_id;\n  IF v_orphan_items <> 0 THEN\n    RAISE EXCEPTION\n      'delete_purchase_invoice(%): integrity check failed — % orphan purchase_invoice_items remain. Rolling back.',\n      p_id, v_orphan_items\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_allocs\n    FROM public.voucher_allocations\n   WHERE purchase_invoice_id = p_id;\n  IF v_orphan_allocs <> 0 THEN\n    RAISE EXCEPTION\n      'delete_purchase_invoice(%): integrity check failed — % orphan voucher_allocations remain. Rolling back.',\n      p_id, v_orphan_allocs\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_jes\n    FROM public.journal_entries\n   WHERE source_module = 'purchase_invoice'\n     AND reference_id  = p_id;\n  IF v_orphan_jes <> 0 THEN\n    RAISE EXCEPTION\n      'delete_purchase_invoice(%): integrity check failed — % orphan journal_entries (source_module=purchase_invoice) remain. Rolling back.',\n      p_id, v_orphan_jes\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    SELECT COUNT(*) INTO v_orphan_je_lines\n      FROM public.journal_entry_lines\n     WHERE journal_entry_id = ANY (v_je_ids);\n    IF v_orphan_je_lines <> 0 THEN\n      RAISE EXCEPTION\n        'delete_purchase_invoice(%): integrity check failed — % orphan journal_entry_lines remain against deleted JEs. Rolling back.',\n        p_id, v_orphan_je_lines\n        USING ERRCODE = 'raise_exception';\n    END IF;\n\n    SELECT COUNT(*) INTO v_orphan_bsl_pi\n      FROM public.bank_statement_lines\n     WHERE matched_entry_id = ANY (v_je_ids);\n    IF v_orphan_bsl_pi <> 0 THEN\n      RAISE EXCEPTION\n        'delete_purchase_invoice(%): integrity check failed — % bank_statement_lines still matched to deleted PI JEs. Rolling back.',\n        p_id, v_orphan_bsl_pi\n        USING ERRCODE = 'raise_exception';\n    END IF;\n  END IF;\n\n  IF array_length(v_orphan_pv_je_ids, 1) IS NOT NULL THEN\n    SELECT COUNT(*) INTO v_orphan_bsl_pv\n      FROM public.bank_statement_lines\n     WHERE matched_entry_id = ANY (v_orphan_pv_je_ids);\n    IF v_orphan_bsl_pv <> 0 THEN\n      RAISE EXCEPTION\n        'delete_purchase_invoice(%): integrity check failed — % bank_statement_lines still matched to orphan PV JEs. Rolling back.',\n        p_id, v_orphan_bsl_pv\n        USING ERRCODE = 'raise_exception';\n    END IF;\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_batches\n    FROM public.batches\n   WHERE purchase_invoice_id = p_id;\n  IF v_orphan_batches <> 0 THEN\n    RAISE EXCEPTION\n      'delete_purchase_invoice(%): integrity check failed — % batches still tagged to deleted invoice. Rolling back.',\n      p_id, v_orphan_batches\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  -- ═════════════════════════════════════════════════════════════════════\n  -- Audit trail — only reached when every check above passed.\n  -- ═════════════════════════════════════════════════════════════════════\n  BEGIN\n    INSERT INTO public.audit_logs (\n      table_name, record_id, action_type, old_values, new_values, user_id\n    ) VALUES (\n      'purchase_invoices',\n      p_id,\n      'delete',\n      jsonb_build_object(\n        'invoice_number',           v_invoice.invoice_number,\n        'supplier_id',              v_invoice.supplier_id,\n        'invoice_date',             v_invoice.invoice_date,\n        'total_amount',             v_invoice.total_amount,\n        'paid_amount',              v_invoice.paid_amount,\n        'status',                   v_invoice.status,\n        'journal_entry_ids',        to_jsonb(v_je_ids),\n        'payment_voucher_ids',      to_jsonb(v_affected_pvs),\n        'orphan_pv_je_ids_released',to_jsonb(v_orphan_pv_je_ids),\n        'integrity_checks',         'passed'\n      ),\n      jsonb_build_object(\n        '_action',      'DELETE_PURCHASE_INVOICE',\n        'deleted_at',   NOW(),\n        'deleted_by',   auth.uid()\n      ),\n      auth.uid()\n    );\n  EXCEPTION WHEN OTHERS THEN\n    NULL;\n  END;\nEND;\n$$","--\n-- Name: FUNCTION \\"delete_purchase_invoice\\"(\\"p_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"delete_purchase_invoice\\"(\\"p_id\\" \\"uuid\\") IS 'Accounting-safe PI delete with post-cleanup integrity verification.\nRemoves PI + its JE + own allocations, releases bank-recon links on any\nPV whose allocations dropped to zero, then re-queries every table it\ntouched. If ANY orphan row remains (invoice, items, allocations, JE,\nJE lines, matched bank lines, or tagged batches), RAISE EXCEPTION rolls\nback the whole transaction. PV rows and their JEs are preserved for\nmanual review.'","--\n-- Name: delete_receipt_voucher_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"delete_receipt_voucher_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_je_ids uuid[];\nBEGIN\n  -- Collect every JE posted by this RV. reference_number OR reference_id can\n  -- carry the link depending on when the RV was posted; we look up both.\n  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])\n    INTO v_je_ids\n    FROM public.journal_entries\n   WHERE source_module = 'receipt'\n     AND (reference_id = OLD.id\n          OR (OLD.journal_entry_id IS NOT NULL AND id = OLD.journal_entry_id));\n\n  IF array_length(v_je_ids, 1) IS NULL THEN\n    RETURN OLD;\n  END IF;\n\n  -- Release BSL matches on matched_entry_id (matched_receipt_id already\n  -- clears itself via ON DELETE SET NULL, but the untyped JE FK doesn't).\n  -- Do NOT touch updated_at — the column is not present in every env.\n  UPDATE public.bank_statement_lines\n     SET matched_entry_id      = NULL,\n         reconciliation_status = 'unmatched',\n         matched_at            = NULL\n   WHERE matched_entry_id = ANY (v_je_ids);\n\n  -- bank_reconciliation_items.journal_entry_id has ON DELETE SET NULL\n  -- (installed in 20260714150000), so no explicit unlink needed.\n\n  DELETE FROM public.journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);\n  DELETE FROM public.journal_entries     WHERE id = ANY (v_je_ids);\n\n  RETURN OLD;\nEND;\n$$","--\n-- Name: FUNCTION \\"delete_receipt_voucher_journal\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"delete_receipt_voucher_journal\\"() IS 'Cascade cleanup of journal_entries + journal_entry_lines when a receipt_voucher is deleted. Mirrors delete_petty_cash_journal from 20260619170000. Also releases matched_entry_id on bank_statement_lines so BSL never keeps a stale FK.'","--\n-- Name: delete_tax_payment(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"delete_tax_payment\\"(\\"p_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_payment        tax_payments%ROWTYPE;\n  v_period_status  text;\n  v_je_ids         uuid[];\n  v_file_urls      text[];\n\n  v_orphan_pay     int;\n  v_orphan_je      int;\n  v_orphan_je_lines int;\n  v_orphan_bsl     int;\n  v_orphan_bri     int;\n  v_orphan_files   int;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'insufficient_privilege';\n  END IF;\n\n  IF p_id IS NULL THEN\n    RAISE EXCEPTION 'Tax payment id is required' USING ERRCODE = 'invalid_parameter_value';\n  END IF;\n\n  -- Lock the row\n  SELECT * INTO v_payment\n    FROM public.tax_payments\n   WHERE id = p_id\n   FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax payment % not found', p_id USING ERRCODE = 'no_data_found';\n  END IF;\n\n  -- Refuse if the period is closed (unless service_role)\n  IF current_setting('request.jwt.claim.role', true) <> 'service_role' THEN\n    SELECT status INTO v_period_status FROM tax_periods WHERE id = v_payment.tax_period_id;\n    IF v_period_status = 'closed' THEN\n      RAISE EXCEPTION 'Tax period is closed; cannot delete tax payment. Reopen the period first.'\n        USING ERRCODE = 'check_violation';\n    END IF;\n  END IF;\n\n  -- Collect JEs owned by this tax payment\n  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])\n    INTO v_je_ids\n    FROM public.journal_entries\n   WHERE source_module = 'tax_payment'\n     AND reference_id  = p_id;\n\n  IF v_payment.journal_entry_id IS NOT NULL\n     AND NOT v_payment.journal_entry_id = ANY (v_je_ids) THEN\n    v_je_ids := array_append(v_je_ids, v_payment.journal_entry_id);\n  END IF;\n\n  -- Release bank_statement_lines matched to this payment.\n  -- NOTE: bank_statement_lines has no updated_at column — do not write it.\n  UPDATE public.bank_statement_lines\n     SET matched_entry_id       = NULL,\n         matched_tax_payment_id = NULL,\n         reconciliation_status  = 'unmatched'\n   WHERE (matched_tax_payment_id = p_id)\n      OR (array_length(v_je_ids, 1) IS NOT NULL AND matched_entry_id = ANY (v_je_ids));\n\n  -- Release bank_reconciliation_items entries\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    UPDATE public.bank_reconciliation_items\n       SET is_matched = false,\n           matched_at = NULL\n     WHERE journal_entry_id = ANY (v_je_ids);\n  END IF;\n\n  -- Snapshot attachment paths BEFORE cascade-deleting the rows\n  SELECT COALESCE(array_agg(file_url), ARRAY[]::text[])\n    INTO v_file_urls\n    FROM public.tax_payment_files\n   WHERE tax_payment_id = p_id;\n\n  DELETE FROM public.tax_payment_files WHERE tax_payment_id = p_id;\n\n  -- Break FK from tax_payments → JE before deleting JE\n  UPDATE public.tax_payments\n     SET journal_entry_id = NULL\n   WHERE id = p_id;\n\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    DELETE FROM public.journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);\n    DELETE FROM public.journal_entries     WHERE id = ANY (v_je_ids);\n  END IF;\n\n  DELETE FROM public.tax_payments WHERE id = p_id;\n\n  -- ═══ INTEGRITY CHECKS ═════════════════════════════════════════════════\n  SELECT COUNT(*) INTO v_orphan_pay FROM public.tax_payments WHERE id = p_id;\n  IF v_orphan_pay <> 0 THEN\n    RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — tax_payments row still present. Rolling back.', p_id\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_je\n    FROM public.journal_entries\n   WHERE source_module = 'tax_payment' AND reference_id = p_id;\n  IF v_orphan_je <> 0 THEN\n    RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % orphan journal_entries (source=tax_payment) remain. Rolling back.', p_id, v_orphan_je\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    SELECT COUNT(*) INTO v_orphan_je_lines\n      FROM public.journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);\n    IF v_orphan_je_lines <> 0 THEN\n      RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % orphan journal_entry_lines remain. Rolling back.', p_id, v_orphan_je_lines\n        USING ERRCODE = 'raise_exception';\n    END IF;\n\n    SELECT COUNT(*) INTO v_orphan_bsl\n      FROM public.bank_statement_lines\n     WHERE matched_entry_id = ANY (v_je_ids);\n    IF v_orphan_bsl <> 0 THEN\n      RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % bank_statement_lines still matched to deleted JE. Rolling back.', p_id, v_orphan_bsl\n        USING ERRCODE = 'raise_exception';\n    END IF;\n\n    SELECT COUNT(*) INTO v_orphan_bri\n      FROM public.bank_reconciliation_items\n     WHERE journal_entry_id = ANY (v_je_ids) AND is_matched = true;\n    IF v_orphan_bri <> 0 THEN\n      RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % bank_reconciliation_items still matched to deleted JE. Rolling back.', p_id, v_orphan_bri\n        USING ERRCODE = 'raise_exception';\n    END IF;\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_files FROM public.tax_payment_files WHERE tax_payment_id = p_id;\n  IF v_orphan_files <> 0 THEN\n    RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % orphan tax_payment_files remain. Rolling back.', p_id, v_orphan_files\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  -- Audit trail (best-effort — do not let audit failure abort the delete)\n  BEGIN\n    INSERT INTO public.audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)\n    VALUES (\n      'tax_payments', p_id, 'delete',\n      jsonb_build_object(\n        'tax_period_id',   v_payment.tax_period_id,\n        'tax_type',        v_payment.tax_type,\n        'amount',          v_payment.amount,\n        'payment_date',    v_payment.payment_date,\n        'status',          v_payment.status,\n        'file_urls',       v_file_urls\n      ),\n      NULL,\n      auth.uid()\n    );\n  EXCEPTION WHEN OTHERS THEN\n    NULL; -- audit failure must not abort the delete\n  END;\nEND $$","--\n-- Name: FUNCTION \\"delete_tax_payment\\"(\\"p_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"delete_tax_payment\\"(\\"p_id\\" \\"uuid\\") IS 'Accounting-safe tax payment delete. Reverses JE, releases bank recon match\n(both typed FK and matched_entry_id), removes attachments, refuses on\nclosed periods, self-verifies orphan state, RAISE EXCEPTION rolls back on\nany orphan. Storage bucket cleanup is client-side (file_urls returned in\naudit_logs.old_values.file_urls_released).'","--\n-- Name: describe_undo_reverse_bank_conflict(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"describe_undo_reverse_bank_conflict\\"(\\"p_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_transfer       public.fund_transfers%ROWTYPE;\n  v_line           record;\n  v_allowed_je_ids uuid[];\n  v_doc_type       text;\n  v_doc_number     text;\n  v_je_id          uuid;\n  v_je_number      text;\n  v_je_source      text;\n  v_je_reference   text;\n  v_linked_je_id   uuid;\nBEGIN\n  SELECT *\n    INTO v_transfer\n    FROM public.fund_transfers\n   WHERE id = p_id;\n\n  IF NOT FOUND THEN\n    RETURN NULL;\n  END IF;\n\n  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])\n    INTO v_allowed_je_ids\n    FROM public.journal_entries\n   WHERE source_module = 'fund_transfers'\n     AND (\n       reference_id = p_id\n       OR reference_number IN (\n         v_transfer.transfer_number,\n         'REV-' || v_transfer.transfer_number\n       )\n     );\n\n  SELECT bsl.*, expected.link_side\n    INTO v_line\n    FROM (\n      VALUES\n        (v_transfer.from_bank_statement_line_id, 'source', 1),\n        (v_transfer.to_bank_statement_line_id, 'destination', 2)\n    ) AS expected(line_id, link_side, sort_order)\n    JOIN public.bank_statement_lines bsl ON bsl.id = expected.line_id\n   WHERE bsl.matched_expense_id IS NOT NULL\n      OR bsl.matched_receipt_id IS NOT NULL\n      OR bsl.matched_petty_cash_id IS NOT NULL\n      OR bsl.matched_tax_payment_id IS NOT NULL\n      OR (\n        bsl.matched_fund_transfer_id IS NOT NULL\n        AND bsl.matched_fund_transfer_id <> p_id\n      )\n      OR (\n        bsl.matched_entry_id IS NOT NULL\n        AND NOT (bsl.matched_entry_id = ANY(v_allowed_je_ids))\n      )\n   ORDER BY expected.sort_order\n   LIMIT 1;\n\n  IF NOT FOUND THEN\n    RETURN NULL;\n  END IF;\n\n  v_je_id := CASE\n    WHEN v_line.matched_entry_id IS NOT NULL\n     AND NOT (v_line.matched_entry_id = ANY(v_allowed_je_ids))\n    THEN v_line.matched_entry_id\n    ELSE NULL\n  END;\n\n  IF v_line.matched_expense_id IS NOT NULL THEN\n    v_doc_type := 'Expense';\n    SELECT voucher_number\n      INTO v_doc_number\n      FROM public.finance_expenses\n     WHERE id = v_line.matched_expense_id;\n\n    IF v_je_id IS NULL THEN\n      SELECT id\n        INTO v_je_id\n        FROM public.journal_entries\n       WHERE source_module = 'expenses'\n         AND reference_id = v_line.matched_expense_id\n       ORDER BY created_at DESC\n       LIMIT 1;\n    END IF;\n  ELSIF v_line.matched_receipt_id IS NOT NULL THEN\n    v_doc_type := 'Receipt Voucher';\n    SELECT voucher_number, journal_entry_id\n      INTO v_doc_number, v_linked_je_id\n      FROM public.receipt_vouchers\n     WHERE id = v_line.matched_receipt_id;\n    v_je_id := COALESCE(v_je_id, v_linked_je_id);\n  ELSIF v_line.matched_petty_cash_id IS NOT NULL THEN\n    v_doc_type := 'Petty Cash Transaction';\n    SELECT transaction_number\n      INTO v_doc_number\n      FROM public.petty_cash_transactions\n     WHERE id = v_line.matched_petty_cash_id;\n\n    IF v_je_id IS NULL THEN\n      SELECT id\n        INTO v_je_id\n        FROM public.journal_entries\n       WHERE source_module = 'petty_cash'\n         AND reference_id = v_line.matched_petty_cash_id\n       ORDER BY created_at DESC\n       LIMIT 1;\n    END IF;\n  ELSIF v_line.matched_tax_payment_id IS NOT NULL THEN\n    v_doc_type := 'Tax Payment';\n    SELECT COALESCE(ntpn, billing_code, government_reference, id::text),\n           journal_entry_id\n      INTO v_doc_number, v_linked_je_id\n      FROM public.tax_payments\n     WHERE id = v_line.matched_tax_payment_id;\n    v_je_id := COALESCE(v_je_id, v_linked_je_id);\n  ELSIF v_line.matched_fund_transfer_id IS NOT NULL\n        AND v_line.matched_fund_transfer_id <> p_id THEN\n    v_doc_type := 'Contra Voucher';\n    SELECT transfer_number, journal_entry_id\n      INTO v_doc_number, v_linked_je_id\n      FROM public.fund_transfers\n     WHERE id = v_line.matched_fund_transfer_id;\n    v_je_id := COALESCE(v_je_id, v_linked_je_id);\n  END IF;\n\n  IF v_je_id IS NOT NULL THEN\n    SELECT entry_number, source_module, reference_number\n      INTO v_je_number, v_je_source, v_je_reference\n      FROM public.journal_entries\n     WHERE id = v_je_id;\n\n    v_doc_number := COALESCE(v_doc_number, v_je_reference);\n    IF v_doc_type IS NULL THEN\n      v_doc_type := CASE v_je_source\n        WHEN 'payment' THEN 'Payment Voucher'\n        WHEN 'payment_vouchers' THEN 'Payment Voucher'\n        WHEN 'receipt' THEN 'Receipt Voucher'\n        WHEN 'receipt_vouchers' THEN 'Receipt Voucher'\n        WHEN 'fund_transfers' THEN 'Contra Voucher'\n        WHEN 'petty_cash' THEN 'Petty Cash Transaction'\n        WHEN 'expenses' THEN 'Expense'\n        WHEN 'tax_payment' THEN 'Tax Payment'\n        WHEN 'tax_payments' THEN 'Tax Payment'\n        ELSE 'Journal Entry'\n      END;\n    END IF;\n  END IF;\n\n  RETURN jsonb_build_object(\n    'kind', 'bank_reconciliation_conflict',\n    'bank_statement_line_id', v_line.id,\n    'bank_account_id', v_line.bank_account_id,\n    'transaction_date', v_line.transaction_date,\n    'amount', COALESCE(\n      NULLIF(v_line.debit_amount, 0),\n      NULLIF(v_line.credit_amount, 0),\n      0\n    ),\n    'currency', COALESCE(\n      (SELECT currency\n         FROM public.bank_accounts\n        WHERE id = v_line.bank_account_id),\n      'IDR'\n    ),\n    'document_type', COALESCE(v_doc_type, 'Linked Transaction'),\n    'document_number', COALESCE(v_doc_number, 'Unavailable'),\n    'journal_entry_id', v_je_id,\n    'journal_entry_number', v_je_number\n  );\nEND;\n$$","--\n-- Name: diagnose_bank_line_link(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"diagnose_bank_line_link\\"(\\"p_bank_line_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_bsl              bank_statement_lines%ROWTYPE;\n  v_fk_type          text;\n  v_fk_uuid          uuid;\n  v_exists           boolean := false;\n  v_target_row       jsonb;\n  v_target_company   uuid;\n  v_bsl_bank_company uuid;\n  v_current_uid      uuid;\n  v_current_role     text;\nBEGIN\n  v_current_uid := auth.uid();\n  SELECT role INTO v_current_role FROM user_profiles WHERE id = v_current_uid;\n\n  SELECT * INTO v_bsl FROM bank_statement_lines WHERE id = p_bank_line_id;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('error','bank_statement_line not found','id',p_bank_line_id);\n  END IF;\n\n  -- Pick the first populated FK (priority mirrors display code).\n  IF v_bsl.matched_fund_transfer_id IS NOT NULL THEN\n    v_fk_type := 'fund_transfer'; v_fk_uuid := v_bsl.matched_fund_transfer_id;\n  ELSIF v_bsl.matched_expense_id IS NOT NULL THEN\n    v_fk_type := 'expense'; v_fk_uuid := v_bsl.matched_expense_id;\n  ELSIF v_bsl.matched_receipt_id IS NOT NULL THEN\n    v_fk_type := 'receipt'; v_fk_uuid := v_bsl.matched_receipt_id;\n  ELSIF v_bsl.matched_petty_cash_id IS NOT NULL THEN\n    v_fk_type := 'petty_cash'; v_fk_uuid := v_bsl.matched_petty_cash_id;\n  ELSIF v_bsl.matched_entry_id IS NOT NULL THEN\n    v_fk_type := 'journal_entry'; v_fk_uuid := v_bsl.matched_entry_id;\n  ELSE\n    RETURN jsonb_build_object(\n      'bank_statement_line_id', v_bsl.id,\n      'root_cause','no_fk_populated',\n      'reconciliation_status', v_bsl.reconciliation_status,\n      'notes', v_bsl.notes\n    );\n  END IF;\n\n  -- Existence + target-side scope + soft-delete probe.\n  IF v_fk_type = 'fund_transfer' THEN\n    SELECT to_jsonb(t.*) INTO v_target_row FROM fund_transfers t WHERE t.id = v_fk_uuid;\n  ELSIF v_fk_type = 'expense' THEN\n    SELECT to_jsonb(t.*) INTO v_target_row FROM finance_expenses t WHERE t.id = v_fk_uuid;\n  ELSIF v_fk_type = 'receipt' THEN\n    SELECT to_jsonb(t.*) INTO v_target_row FROM receipt_vouchers t WHERE t.id = v_fk_uuid;\n  ELSIF v_fk_type = 'petty_cash' THEN\n    SELECT to_jsonb(t.*) INTO v_target_row FROM petty_cash_transactions t WHERE t.id = v_fk_uuid;\n  ELSIF v_fk_type = 'journal_entry' THEN\n    SELECT to_jsonb(t.*) INTO v_target_row FROM journal_entries t WHERE t.id = v_fk_uuid;\n  END IF;\n  v_exists := (v_target_row IS NOT NULL);\n\n  -- Extract company_id if present (some tables have it, some don't).\n  IF v_exists AND v_target_row ? 'company_id' THEN\n    v_target_company := (v_target_row->>'company_id')::uuid;\n  END IF;\n  -- Best-effort bsl-side company: derive via bank_accounts.company_id if present.\n  BEGIN\n    SELECT ba.company_id INTO v_bsl_bank_company\n      FROM bank_accounts ba WHERE ba.id = v_bsl.bank_account_id;\n  EXCEPTION WHEN undefined_column THEN\n    v_bsl_bank_company := NULL;\n  END;\n\n  RETURN jsonb_build_object(\n    'bank_statement_line_id',  v_bsl.id,\n    'fk_type',                 v_fk_type,\n    'fk_uuid',                 v_fk_uuid,\n    'exists_in_db',            v_exists,\n    'target_row',              v_target_row,\n    'target_company_id',       v_target_company,\n    'bsl_bank_company_id',     v_bsl_bank_company,\n    'company_match',           CASE\n                                 WHEN v_target_company IS NULL OR v_bsl_bank_company IS NULL THEN NULL\n                                 ELSE (v_target_company = v_bsl_bank_company)\n                               END,\n    'current_user_id',         v_current_uid,\n    'current_role',            v_current_role,\n    'reconciliation_status',   v_bsl.reconciliation_status,\n    'root_cause',              CASE\n                                 WHEN NOT v_exists                        THEN 'dangling_fk_target_deleted'\n                                 WHEN v_target_company IS NOT NULL AND v_bsl_bank_company IS NOT NULL\n                                      AND v_target_company <> v_bsl_bank_company THEN 'company_mismatch'\n                                 ELSE 'rls_masks_target_for_current_role'\n                               END\n  );\nEND $$","--\n-- Name: dismiss_system_task(\\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"dismiss_system_task\\"(\\"p_task_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\" DEFAULT NULL::\\"text\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts','manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot dismiss system tasks', v_role;\nEND IF;\n\nUPDATE tasks\nSET dismissed_at = now(), dismissed_by = auth.uid(), dismissal_reason = p_reason,\nstatus = 'completed'::task_status\nWHERE id = p_task_id AND task_type = 'system' AND task_mode = 'advisory';\nRETURN FOUND;\nEND;\n$$","--\n-- Name: edit_approved_finance_expense_atomic(\\"uuid\\", \\"jsonb\\", \\"uuid\\", numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"edit_approved_finance_expense_atomic\\"(\\"p_expense_id\\" \\"uuid\\", \\"p_payload\\" \\"jsonb\\", \\"p_bank_statement_line_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_allocation_amount\\" numeric DEFAULT NULL::numeric) RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_exp public.finance_expenses%rowtype;\n  v_journal_id uuid;\n  v_journal_count integer;\n  v_date date;\n  v_bank_id uuid;\n  v_bank_currency text;\n  v_currency text;\n  v_rate numeric;\n  v_docs text[];\n  v_allocation record;\n  v_same_selected_count integer;\n  v_selected_amount numeric;\n  v_period_status text;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  SELECT * INTO v_exp FROM public.finance_expenses WHERE id=p_expense_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\n  IF v_exp.approval_status<>'approved' THEN RAISE EXCEPTION 'Approved expense edit requires an approved expense'; END IF;\n\n  SELECT count(*),(array_agg(id ORDER BY created_at DESC,id DESC))[1]\n    INTO v_journal_count,v_journal_id\n    FROM public.journal_entries\n   WHERE source_module IN('expense','expenses')\n     AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n     AND is_posted=true AND NOT COALESCE(is_reversed,false);\n  IF v_journal_count<>1 THEN RAISE EXCEPTION 'Approved expense must have exactly one active effective journal'; END IF;\n  PERFORM 1 FROM public.journal_entries WHERE id=v_journal_id FOR UPDATE;\n\n  SELECT ap.status INTO v_period_status\n    FROM public.journal_entries je\n    LEFT JOIN public.accounting_periods ap\n      ON ap.start_date<=je.entry_date AND ap.end_date>=je.entry_date\n   WHERE je.id=v_journal_id\n   ORDER BY ap.start_date DESC LIMIT 1;\n  IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN\n    RAISE EXCEPTION 'Cannot edit approved expense in a closed accounting period';\n  END IF;\n\n  IF COALESCE((p_payload->>'amount')::numeric,0)<=0 THEN RAISE EXCEPTION 'Expense amount must be greater than zero'; END IF;\n  IF NULLIF(p_payload->>'expense_category','') IS NULL THEN RAISE EXCEPTION 'Expense category is required'; END IF;\n  v_date:=COALESCE((p_payload->>'expense_date')::date,current_date);\n  v_bank_id:=NULLIF(p_payload->>'bank_account_id','')::uuid;\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id=v_bank_id;\n  v_currency:=upper(COALESCE(NULLIF(p_payload->>'transaction_currency',''),v_bank_currency,'IDR'));\n  v_rate:=COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric,0),CASE WHEN v_currency='IDR' THEN 1 END);\n  IF v_currency NOT IN('IDR','USD') OR v_rate IS NULL OR v_rate<=0 THEN RAISE EXCEPTION 'Valid expense currency/rate is required'; END IF;\n  IF v_bank_currency IS NOT NULL AND v_bank_currency<>v_currency THEN RAISE EXCEPTION 'Expense currency does not match selected bank currency'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IS NOT NULL\n     AND NULLIF(p_payload->>'payment_method','') NOT IN('cash','petty_cash')\n     AND v_bank_id IS NULL THEN RAISE EXCEPTION 'Bank-paid expense requires a bank account'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IN('cash','petty_cash')\n     AND p_bank_statement_line_id IS NOT NULL THEN RAISE EXCEPTION 'Cash/petty-cash expense cannot create a bank allocation'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IS NULL AND p_bank_statement_line_id IS NOT NULL THEN RAISE EXCEPTION 'Accrued expense cannot create a bank allocation'; END IF;\n  SELECT ap.status INTO v_period_status\n    FROM public.accounting_periods ap\n   WHERE ap.start_date<=v_date AND ap.end_date>=v_date\n   ORDER BY ap.start_date DESC LIMIT 1;\n  IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN\n    RAISE EXCEPTION 'Cannot move approved expense into a closed accounting period';\n  END IF;\n  SELECT COALESCE(array_agg(value),ARRAY[]::text[]) INTO v_docs\n    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls','[]'::jsonb));\n\n  -- Preserve the edited bank mode through the legacy unlinked-payment normalizer.\n  PERFORM set_config('app.expense_atomic_bank_link','on',true);\n\n  UPDATE public.finance_expenses SET\n    expense_category=p_payload->>'expense_category',expense_type=COALESCE(NULLIF(p_payload->>'expense_type',''),'admin'),\n    amount=(p_payload->>'amount')::numeric,expense_date=v_date,description=NULLIF(p_payload->>'description',''),\n    batch_id=NULLIF(p_payload->>'batch_id','')::uuid,import_container_id=NULLIF(p_payload->>'import_container_id','')::uuid,\n    delivery_challan_id=NULLIF(p_payload->>'delivery_challan_id','')::uuid,\n    payment_method=NULLIF(p_payload->>'payment_method',''),bank_account_id=v_bank_id,\n    payment_reference=NULLIF(p_payload->>'payment_reference',''),paid_by=NULLIF(p_payload->>'paid_by',''),\n    document_urls=NULLIF(v_docs,ARRAY[]::text[]),supplier_id=NULLIF(p_payload->>'supplier_id','')::uuid,\n    staff_id=NULLIF(p_payload->>'staff_id','')::uuid,invoice_number=NULLIF(p_payload->>'invoice_number',''),\n    due_date=NULLIF(p_payload->>'due_date','')::date,broker_items=NULLIF(p_payload->'broker_items','null'::jsonb),\n    pib_bm_amount=NULLIF(p_payload->>'pib_bm_amount','')::numeric,pib_ppn_amount=NULLIF(p_payload->>'pib_ppn_amount','')::numeric,\n    pib_pph_amount=NULLIF(p_payload->>'pib_pph_amount','')::numeric,ppn_amount=COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0),\n    ppn_manual_override=COALESCE((p_payload->>'ppn_manual_override')::boolean,false),\n    ppn_calc_mode=COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'),dpp_amount=NULLIF(p_payload->>'dpp_amount','')::numeric,\n    ppn_rate=COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11),pph_amount=COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),\n    pph_code_id=NULLIF(p_payload->>'pph_code_id','')::uuid,stamp_duty_amount=COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),\n    fixed_asset_account_id=NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,\n    bank_charges_amount=COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),\n    currency_code=v_currency,transaction_currency=v_currency,functional_currency='IDR',exchange_rate=v_rate,\n    bank_account_currency=COALESCE(v_bank_currency,v_currency),payment_currency=v_currency\n  WHERE id=p_expense_id;\n\n  -- The trigger must retain the header identity and rebuild only its lines.\n  IF NOT EXISTS(\n    SELECT 1 FROM public.journal_entries\n     WHERE id=v_journal_id\n       AND source_module IN('expense','expenses')\n       AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n       AND is_posted AND NOT COALESCE(is_reversed,false)\n  ) THEN RAISE EXCEPTION 'Expense journal identity changed during edit'; END IF;\n  IF (SELECT count(*) FROM public.journal_entries\n       WHERE source_module IN('expense','expenses')\n         AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n         AND is_posted AND NOT COALESCE(is_reversed,false))<>1 THEN\n    RAISE EXCEPTION 'Expense edit did not preserve exactly one active journal';\n  END IF;\n\n  SELECT count(*),max(allocation_amount)\n    INTO v_same_selected_count,v_selected_amount\n    FROM public.bank_statement_allocations\n   WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind='supplier'\n     AND bank_statement_line_id=p_bank_statement_line_id;\n\n  IF p_bank_statement_line_id IS NOT NULL\n     AND v_same_selected_count=0 THEN\n    PERFORM public.link_bank_statement_line(\n      p_bank_statement_line_id,'expense',p_expense_id,'supplier',p_allocation_amount);\n  ELSIF p_bank_statement_line_id IS NOT NULL\n     AND p_allocation_amount IS NOT NULL\n     AND abs(COALESCE(v_selected_amount,0)-p_allocation_amount)>0.01 THEN\n    RAISE EXCEPTION 'Change an existing bank allocation through unlink/relink so other payments remain intact';\n  ELSE\n    -- A no-op FK update deliberately re-runs all canonical allocation guards\n    -- against the rebuilt journal/bank account. Any mismatch rolls back save.\n    UPDATE public.bank_statement_allocations SET allocation_amount=allocation_amount WHERE document_type='expense' AND document_id=p_expense_id;\n  END IF;\n\n  UPDATE public.bank_statement_allocations SET allocation_amount=allocation_amount WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind<>'supplier';\n\n  PERFORM public.recalculate_expense_payment_state(p_expense_id);\n  RETURN p_expense_id;\nEND;\n$$","--\n-- Name: edit_delivery_challan(\\"uuid\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"edit_delivery_challan\\"(\\"p_challan_id\\" \\"uuid\\", \\"p_new_items\\" \\"jsonb\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_role       text;\n  v_challan    record;\n  v_item       jsonb;\n  v_count      integer;\n  v_product_id uuid;\n  v_batch_id   uuid;\n  v_new_qty    numeric;\nBEGIN\n  SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts', 'warehouse', 'sales', 'manager') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot edit delivery challans', v_role;\n  END IF;\n\n  SELECT * INTO v_challan FROM delivery_challans WHERE id = p_challan_id;\n\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Delivery challan not found');\n  END IF;\n\n  IF v_challan.approved_at IS NOT NULL THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Cannot edit approved delivery challan');\n  END IF;\n\n  SELECT count(*) INTO v_count FROM jsonb_array_elements(p_new_items);\n  IF v_count = 0 THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Cannot save DC with no items');\n  END IF;\n\n  -- Suppress the INSERT trigger on delivery_challan_items (safety: DC is pending anyway,\n  -- trigger now also guards against non-approved DCs, but be explicit)\n  PERFORM set_config('app.skip_dc_item_trigger', 'true', true);\n\n  -- Remove all existing items for this DC\n  DELETE FROM delivery_challan_items WHERE challan_id = p_challan_id;\n\n  -- Insert the new item list\n  -- No reserved_stock manipulation needed: reservations are in stock_reservations\n  -- linked to the SO, not the DC. trg_sync_batch_reserved_stock handles accuracy.\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_new_items)\n  LOOP\n    v_product_id := (v_item->>'product_id')::uuid;\n    v_batch_id   := (v_item->>'batch_id')::uuid;\n    v_new_qty    := (v_item->>'quantity')::numeric;\n\n    INSERT INTO delivery_challan_items (\n      challan_id, product_id, batch_id, quantity,\n      pack_size, pack_type, number_of_packs\n    ) VALUES (\n      p_challan_id, v_product_id, v_batch_id, v_new_qty,\n      NULLIF(v_item->>'pack_size', '')::numeric,\n      NULLIF(v_item->>'pack_type', ''),\n      NULLIF(v_item->>'number_of_packs', '')::integer\n    );\n  END LOOP;\n\n  PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n\n  RETURN jsonb_build_object('success', true, 'message', 'Delivery challan updated successfully');\n\nEXCEPTION\n  WHEN foreign_key_violation THEN\n    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n    RETURN jsonb_build_object('success', false, 'error', 'Invalid product or batch selection');\n  WHEN OTHERS THEN\n    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n    RETURN jsonb_build_object('success', false, 'error', SQLERRM);\nEND;\n$$","--\n-- Name: effective_sales_cogs_unit_cost(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"effective_sales_cogs_unit_cost\\"(\\"p_batch_id\\" \\"uuid\\") RETURNS numeric\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT COALESCE(\n    NULLIF(b.landed_cost_per_unit, 0),\n    NULLIF(b.import_price, 0),\n    NULLIF(b.cost_per_unit, 0)\n  )\n  FROM public.batches b\n  WHERE b.id = p_batch_id;\n$$","--\n-- Name: FUNCTION \\"effective_sales_cogs_unit_cost\\"(\\"p_batch_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"effective_sales_cogs_unit_cost\\"(\\"p_batch_id\\" \\"uuid\\") IS 'Returns authoritative landed unit cost (for imports) or authoritative local purchase unit cost (for local goods)'","--\n-- Name: enforce_expense_category_parent_nonposting(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"enforce_expense_category_parent_nonposting\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF NEW.parent_id IS NOT NULL THEN\n    UPDATE public.expense_categories\n    SET is_posting_category=false, coa_account_id=NULL\n    WHERE id=NEW.parent_id AND is_posting_category;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: enforce_final_quote_write_restriction(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"enforce_final_quote_write_restriction\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  caller_role text;\nBEGIN\n  -- Look up the role of the current user\n  SELECT role INTO caller_role\n  FROM user_profiles\n  WHERE id = auth.uid()\n    AND is_active = true;\n\n  -- Only admin/manager may write final quote fields\n  IF caller_role NOT IN ('admin', 'manager') THEN\n    -- Block if any final quote field is being changed from its current value\n    IF (\n      NEW.final_quote_price      IS DISTINCT FROM OLD.final_quote_price      OR\n      NEW.final_quote_currency   IS DISTINCT FROM OLD.final_quote_currency   OR\n      NEW.final_entered_by       IS DISTINCT FROM OLD.final_entered_by       OR\n      NEW.final_entered_at       IS DISTINCT FROM OLD.final_entered_at\n    ) THEN\n      RAISE EXCEPTION\n        'Permission denied: only admin or manager may update final quote fields. '\n        'Your role (%) cannot change final_quote_price, final_quote_currency, '\n        'final_entered_by, or final_entered_at.',\n        COALESCE(caller_role, 'unknown');\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: enforce_fund_transfer_role(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"enforce_fund_transfer_role\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n      BEGIN\n        IF pg_trigger_depth() > 1 THEN RETURN COALESCE(NEW, OLD); END IF;\n        PERFORM public._sec_check_finance_role();\n        IF TG_OP = 'INSERT' AND auth.role() <> 'service_role' THEN\n          NEW.created_by := COALESCE(auth.uid(), NEW.created_by);\n        END IF;\n        RETURN COALESCE(NEW, OLD);\n      END $$","--\n-- Name: enforce_no_journal_only_bank_link(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"enforce_no_journal_only_bank_link\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF NEW.matched_entry_id IS NULL \n    OR NEW.matched_expense_id IS NOT NULL \n    OR NEW.matched_receipt_id IS NOT NULL\n    OR NEW.matched_payment_id IS NOT NULL \n    OR NEW.matched_fund_transfer_id IS NOT NULL \n    OR NEW.matched_petty_cash_id IS NOT NULL \n    OR NEW.matched_tax_payment_id IS NOT NULL \n    OR EXISTS (\n      SELECT 1 FROM public.bank_statement_allocations a \n      WHERE a.bank_statement_line_id = NEW.id\n    )\n  THEN \n    RETURN NEW; \n  END IF;\n\n  PERFORM 1 FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id=je.id\n  JOIN public.bank_accounts ba ON ba.coa_id=jel.account_id\n  WHERE je.id=NEW.matched_entry_id AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false\n    AND ba.id=NEW.bank_account_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Direct journal-to-bank reconciliation is not allowed. Use a supported Finance document.' USING ERRCODE='check_violation'; END IF;\n  RETURN NEW;\nEND $$","--\n-- Name: enforce_sales_invoice_write_scope(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"enforce_sales_invoice_write_scope\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_role text;\n  v_paid_actual numeric;\nBEGIN\n  -- Cascading updates from other triggers (e.g. recalculate_invoice_payment_\n  -- status on voucher_allocations) are trusted. pg_trigger_depth() > 1 means\n  -- we're inside a nested trigger chain.\n  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;\n\n  IF auth.role() = 'service_role' THEN RETURN NEW; END IF;\n\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n\n  IF v_role NOT IN ('admin','accounts') THEN\n    IF NEW.payment_status IS DISTINCT FROM OLD.payment_status\n       OR NEW.paid_amount    IS DISTINCT FROM OLD.paid_amount\n       OR NEW.total_amount   IS DISTINCT FROM OLD.total_amount\n       OR NEW.customer_id    IS DISTINCT FROM OLD.customer_id THEN\n      RAISE EXCEPTION 'Sales/warehouse cannot modify invoice financial fields (payment_status, paid_amount, total_amount, customer_id)';\n    END IF;\n  END IF;\n\n  IF NEW.payment_status = 'paid' AND NEW.payment_status IS DISTINCT FROM OLD.payment_status THEN\n    SELECT COALESCE(SUM(allocated_amount), 0) INTO v_paid_actual\n    FROM public.voucher_allocations\n    WHERE sales_invoice_id = NEW.id;\n    IF v_paid_actual < COALESCE(NEW.total_amount, 0) THEN\n      RAISE EXCEPTION 'Cannot mark invoice paid: allocated payments (%) < total (%)', v_paid_actual, NEW.total_amount;\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND $$","--\n-- Name: enforce_sales_order_column_scope(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"enforce_sales_order_column_scope\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n      DECLARE\n        v_role text;\n      BEGIN\n        IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;\n        IF auth.role() = 'service_role' THEN RETURN NEW; END IF;\n\n        SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n\n        -- Admins can do anything.\n        IF v_role = 'admin' THEN RETURN NEW; END IF;\n\n        -- Non-owners cannot mutate sensitive commercial columns.\n        IF OLD.created_by IS NOT NULL AND OLD.created_by <> auth.uid() THEN\n          IF NEW.customer_id  IS DISTINCT FROM OLD.customer_id\n             OR NEW.total_amount IS DISTINCT FROM OLD.total_amount THEN\n            RAISE EXCEPTION 'Only the SO owner or an admin may change customer_id / total_amount';\n          END IF;\n        END IF;\n\n        RETURN NEW;\n      END $$","--\n-- Name: enforce_tax_je_period_lock(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"enforce_tax_je_period_lock\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_status text;\nBEGIN\n  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN\n    RETURN COALESCE(NEW, OLD);\n  END IF;\n\n  IF TG_OP IN ('UPDATE','DELETE') AND OLD.source_module = 'tax_payment' THEN\n    SELECT tp.status INTO v_status\n    FROM tax_payments txp\n    JOIN tax_periods tp ON tp.id = txp.tax_period_id\n    WHERE txp.id = OLD.reference_id;\n    IF v_status = 'closed' THEN\n      RAISE EXCEPTION 'Tax period is closed; cannot modify tax-payment journal entry'\n        USING ERRCODE = 'check_violation';\n    END IF;\n  END IF;\n\n  RETURN COALESCE(NEW, OLD);\nEND $$","--\n-- Name: enforce_tax_period_lock(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"enforce_tax_period_lock\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_status text;\nBEGIN\n  IF (current_setting('request.jwt.claim.role', true) = 'service_role') THEN\n    RETURN COALESCE(NEW, OLD);\n  END IF;\n\n  IF TG_OP = 'UPDATE' OR TG_OP = 'DELETE' THEN\n    -- Check OLD row's period\n    IF (COALESCE(OLD.tax_period_id, NULL) IS NOT NULL) THEN\n      SELECT status INTO v_status FROM tax_periods WHERE id = OLD.tax_period_id;\n      IF v_status = 'closed' THEN\n        RAISE EXCEPTION 'Tax period is closed; cannot modify % on %',\n          TG_OP, TG_TABLE_NAME\n          USING ERRCODE = 'check_violation';\n      END IF;\n    END IF;\n  END IF;\n\n  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN\n    IF NEW.tax_period_id IS NOT NULL THEN\n      SELECT status INTO v_status FROM tax_periods WHERE id = NEW.tax_period_id;\n      IF v_status = 'closed' THEN\n        RAISE EXCEPTION 'Tax period is closed; cannot assign new rows to it'\n          USING ERRCODE = 'check_violation';\n      END IF;\n    END IF;\n  END IF;\n\n  RETURN COALESCE(NEW, OLD);\nEND $$","--\n-- Name: execute_historical_expense_cash_restatement(\\"text\\", \\"text\\", \\"uuid\\", \\"uuid\\", numeric, \\"jsonb\\", \\"text\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"execute_historical_expense_cash_restatement\\"(\\"p_idempotency_key\\" \\"text\\", \\"p_document_type\\" \\"text\\", \\"p_document_id\\" \\"uuid\\", \\"p_bank_statement_line_id\\" \\"uuid\\", \\"p_allocation_amount\\" numeric, \\"p_expected\\" \\"jsonb\\", \\"p_payment_kind\\" \\"text\\", \\"p_operation\\" \\"text\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_existing public.finance_historical_repair_commands%rowtype;\n  v_cmd uuid;\n  v_exp public.finance_expenses%rowtype;\n  v_source_je uuid;\n  v_reversal_je uuid;\n  v_new_je uuid;\n  v_bank_amount numeric;\n  v_is_debit boolean;\n  v_bank_coa uuid;\n  v_ap_coa uuid;\n  v_charge_coa uuid;\n  v_cash_credit numeric;\n  v_cash_lines integer;\n  v_advance numeric;\n  v_charge numeric;\n  v_remaining_ap numeric;\n  v_entry text;\n  v_line record;\n  v_line_no integer;\n  v_before jsonb;\n  v_after jsonb;\n  v_alloc public.bank_statement_allocations%rowtype;\n  v_new_debit numeric;\n  v_new_credit numeric;\n  v_pv006 uuid;\n  v_pv007 uuid;\n  v_je0001 uuid;\n  v_je0002 uuid;\nBEGIN\n  IF p_operation NOT IN (\n      'restate_salary_net_of_advance',\n      'restate_partial_supplier_cash',\n      'restate_evidenced_bank_charge') THEN\n    RAISE EXCEPTION 'Unsupported restatement operation';\n  END IF;\n  IF p_document_type <> 'expense' THEN\n    RAISE EXCEPTION 'Restatement requires an expense';\n  END IF;\n  IF p_bank_statement_line_id IS NULL OR p_allocation_amount <= 0 THEN\n    RAISE EXCEPTION 'Restatement requires bank evidence and a positive allocation';\n  END IF;\n  IF p_bank_statement_line_id = 'c4c4033b-f661-4574-8878-dc593ee4eb33'::uuid THEN\n    RAISE EXCEPTION 'Protected split allocation must not be modified';\n  END IF;\n  IF p_bank_statement_line_id = '5edf43b4-976a-4537-b97d-58ccec4e3e78'::uuid THEN\n    RAISE EXCEPTION 'USD deposit is out of scope';\n  END IF;\n  SELECT * INTO v_existing FROM public.finance_historical_repair_commands\n   WHERE idempotency_key=p_idempotency_key FOR UPDATE;\n  IF FOUND THEN\n    RETURN jsonb_build_object('idempotent',true,'command_id',v_existing.id,\n      'allocation_id',v_existing.created_allocation_id,'before',v_existing.before_state,\n      'after',v_existing.after_state);\n  END IF;\n  INSERT INTO public.finance_historical_repair_commands(\n    idempotency_key,document_type,document_id,bank_statement_line_id,payment_kind,\n    operation,requested_by,before_state,after_state,status)\n  VALUES(p_idempotency_key,p_document_type,p_document_id,p_bank_statement_line_id,p_payment_kind,\n    p_operation,auth.uid(),'{}','{}','committed') RETURNING id INTO v_cmd;\n  PERFORM set_config('app.finance_historical_repair_command',v_cmd::text,true);\n  PERFORM set_config('app.finance_historical_repair','on',true);\n  PERFORM 1 FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Missing expense source'; END IF;\n  SELECT * INTO v_exp FROM public.finance_expenses WHERE id=p_document_id;\n  IF v_exp.voucher_number IN ('EXP/26-26/115','EXP/26-26/139') THEN\n    RAISE EXCEPTION 'Protected expense must not be modified';\n  END IF;\n  IF v_exp.expense_date >= DATE '2026-08-01' THEN\n    RAISE EXCEPTION 'August 2026 expenses are out of scope';\n  END IF;\n  PERFORM 1 FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Missing cash evidence'; END IF;\n  SELECT COALESCE(NULLIF(debit_amount,0),credit_amount,0),\n         COALESCE(debit_amount,0)>0,\n         (SELECT ba.coa_id FROM public.bank_accounts ba WHERE ba.id=bank_statement_lines.bank_account_id)\n    INTO v_bank_amount, v_is_debit, v_bank_coa\n    FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id;\n  IF (SELECT transaction_date FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id)\n       >= DATE '2026-08-01' THEN\n    RAISE EXCEPTION 'August 2026 bank lines are out of scope';\n  END IF;\n  IF v_bank_coa IS NULL THEN RAISE EXCEPTION 'Missing bank ledger account'; END IF;\n  IF abs(p_allocation_amount-v_bank_amount)>0.01 THEN\n    RAISE EXCEPTION 'Allocation must equal the actual bank amount';\n  END IF;\n  IF p_expected ? 'bank_amount' AND abs((p_expected->>'bank_amount')::numeric-v_bank_amount)>0.01 THEN\n    RAISE EXCEPTION 'Unexpected bank amount';\n  END IF;\n  IF NOT v_is_debit THEN\n    RAISE EXCEPTION 'Expected a bank debit cash event';\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations\n      WHERE bank_statement_line_id=p_bank_statement_line_id) THEN\n    RAISE EXCEPTION 'Duplicate cash event';\n  END IF;\n  SELECT je.id INTO v_source_je\n    FROM public.journal_entries je\n   WHERE je.id=COALESCE((p_expected->>'journal_id')::uuid, je.id)\n     AND je.source_module IN ('expense','expenses')\n     AND je.is_posted AND NOT COALESCE(je.is_reversed,false)\n     AND (je.reference_id=p_document_id OR je.reference_number='EXP-'||p_document_id::text)\n   FOR UPDATE;\n  IF v_source_je IS NULL THEN RAISE EXCEPTION 'Expected posted source journal is missing'; END IF;\n  IF p_expected ? 'journal_id' AND v_source_je::text <> p_expected->>'journal_id' THEN\n    RAISE EXCEPTION 'Unexpected source journal';\n  END IF;\n  IF p_expected ? 'entry_number' AND (SELECT entry_number FROM public.journal_entries WHERE id=v_source_je)\n       <> p_expected->>'entry_number' THEN\n    RAISE EXCEPTION 'Unexpected journal';\n  END IF;\n  PERFORM 1 FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je FOR UPDATE;\n  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE journal_entry_id=v_source_je) THEN\n    RAISE EXCEPTION 'Duplicate cash event';\n  END IF;\n  SELECT count(*), COALESCE(sum(l.credit),0) INTO v_cash_lines, v_cash_credit\n    FROM public.journal_entry_lines l\n   WHERE l.journal_entry_id=v_source_je AND l.account_id=v_bank_coa AND l.credit>0;\n  IF v_cash_lines<>1 THEN\n    RAISE EXCEPTION 'Source journal is not a single bank-credit cash recognition';\n  END IF;\n  SELECT id INTO v_ap_coa FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n  IF v_ap_coa IS NULL THEN RAISE EXCEPTION 'AP account 2110 is missing'; END IF;\n  SELECT jsonb_build_object('source_journal_id',je.id,'entry_number',je.entry_number,\n      'total_debit',je.total_debit,'total_credit',je.total_credit,\n      'paid_amount',v_exp.paid_amount,'settlement_amount',v_exp.settlement_amount,\n      'pph_paid_amount',v_exp.pph_paid_amount,\n      'lines',(SELECT COALESCE(jsonb_agg(to_jsonb(l) ORDER BY l.line_number),'[]')\n               FROM public.journal_entry_lines l WHERE l.journal_entry_id=je.id))\n    INTO v_before FROM public.journal_entries je WHERE je.id=v_source_je;\n  IF p_operation='restate_salary_net_of_advance' THEN\n    IF v_exp.voucher_number <> 'EXP/26-26/124' OR v_exp.expense_category <> 'salary' THEN\n      RAISE EXCEPTION 'Salary restatement evidence does not match EXP/26-26/124';\n    END IF;\n    IF abs(v_exp.amount-2500000)>0.01 THEN RAISE EXCEPTION 'Unexpected salary amount'; END IF;\n    IF abs(v_cash_credit-2500000)>0.01 THEN RAISE EXCEPTION 'Unexpected salary bank credit'; END IF;\n    IF abs(v_bank_amount-2000000)>0.01 THEN RAISE EXCEPTION 'Unexpected salary cash event'; END IF;\n    SELECT COALESCE(sum(applied_amount),0) INTO v_advance\n      FROM public.salary_advance_applications WHERE salary_expense_id=p_document_id;\n    IF abs(v_advance-500000)>0.01 THEN RAISE EXCEPTION 'Salary advance application is not Rp500,000'; END IF;\n    SELECT id INTO v_pv006 FROM public.payment_vouchers WHERE voucher_number='PV/26-26/006' FOR UPDATE;\n    SELECT id INTO v_pv007 FROM public.payment_vouchers WHERE voucher_number='PV/26-26/007' FOR UPDATE;\n    SELECT id INTO v_je0001 FROM public.journal_entries WHERE entry_number='JE2608-0001' FOR UPDATE;\n    SELECT id INTO v_je0002 FROM public.journal_entries WHERE entry_number='JE2608-0002' FOR UPDATE;\n    IF v_pv006 IS NULL OR v_pv007 IS NULL OR v_je0001 IS NULL OR v_je0002 IS NULL THEN\n      RAISE EXCEPTION 'Salary advance voucher/journal evidence is missing';\n    END IF;\n    IF EXISTS (SELECT 1 FROM public.journal_entry_lines l JOIN public.chart_of_accounts c ON c.id=l.account_id\n                WHERE l.journal_entry_id=v_je0001 AND NOT (\n                  (c.code='1160' AND l.debit=500000) OR (c.code='111101' AND l.credit=500000))) THEN\n      RAISE EXCEPTION 'PV/26-26/006 journal is not the expected advance cash event';\n    END IF;\n    IF EXISTS (SELECT 1 FROM public.journal_entry_lines l JOIN public.chart_of_accounts c ON c.id=l.account_id\n                WHERE l.journal_entry_id=v_je0002 AND NOT (\n                  (c.code='2110' AND l.debit=500000) OR (c.code='1160' AND l.credit=500000))) THEN\n      RAISE EXCEPTION 'PV/26-26/007 journal is not the expected advance recovery';\n    END IF;\n    v_remaining_ap := 500000;\n  ELSIF p_operation='restate_partial_supplier_cash' THEN\n    IF v_exp.voucher_number <> 'EXP/26-26/034' THEN\n      RAISE EXCEPTION 'Partial-payment restatement evidence does not match EXP/26-26/034';\n    END IF;\n    IF abs(v_exp.amount-7000000)>0.01 OR abs(COALESCE(v_exp.pph_amount,0)-140000)>0.01 THEN\n      RAISE EXCEPTION 'Unexpected expense/PPh amounts';\n    END IF;\n    IF abs(COALESCE(v_exp.pph_paid_amount,0))>0.01 THEN\n      RAISE EXCEPTION 'PPh already remitted; stopping';\n    END IF;\n    IF abs(v_cash_credit-6860000)>0.01 THEN RAISE EXCEPTION 'Unexpected journal bank credit'; END IF;\n    IF abs(v_bank_amount-6820000)>0.01 THEN RAISE EXCEPTION 'Unexpected bank cash event'; END IF;\n    v_remaining_ap := 40000;\n  ELSIF p_operation='restate_evidenced_bank_charge' THEN\n    v_charge := COALESCE(v_exp.bank_charges_amount,0);\n    IF abs(v_charge-3000)>0.01 THEN RAISE EXCEPTION 'Evidence does not show a Rp3,000 bank charge'; END IF;\n    IF abs(v_bank_amount - v_cash_credit - v_charge)>0.01 THEN\n      RAISE EXCEPTION 'Bank debit is not journal cash plus the evidenced charge';\n    END IF;\n    v_charge_coa := public.get_expense_account_id('bank_charges');\n    IF v_charge_coa IS NULL THEN RAISE EXCEPTION 'Bank-charge account is missing'; END IF;\n    IF EXISTS (SELECT 1 FROM public.journal_entry_lines\n                WHERE journal_entry_id=v_source_je AND account_id=v_charge_coa AND debit>0) THEN\n      RAISE EXCEPTION 'Bank charge already journaled; stopping to avoid duplication';\n    END IF;\n    IF v_exp.amount IS NULL THEN RAISE EXCEPTION 'Missing Telkom/service amount'; END IF;\n  END IF;\n  v_entry:=public.generate_journal_entry_number();\n  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,\n    description,total_debit,total_credit,is_posted,posted_at,posted_by,created_by)\n  SELECT v_entry,je.entry_date,'historical_repair',v_exp.id,'HR-REV-'||v_cmd::text,\n    'Explicit reversal of incorrect cash recognition '||je.entry_number,je.total_credit,je.total_debit,\n    true,now(),auth.uid(),auth.uid()\n    FROM public.journal_entries je WHERE je.id=v_source_je RETURNING id INTO v_reversal_je;\n  v_line_no:=1;\n  FOR v_line IN SELECT * FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je ORDER BY line_number LOOP\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n    VALUES(v_reversal_je,v_line_no,v_line.account_id,v_line.credit,v_line.debit,\n      'Historical reversal: '||COALESCE(v_line.description,''),v_line.supplier_id);\n    v_line_no:=v_line_no+1;\n  END LOOP;\n  UPDATE public.journal_entries SET is_reversed=true, reversed_by_id=v_reversal_je WHERE id=v_source_je;\n  v_entry:=public.generate_journal_entry_number();\n  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,\n    description,total_debit,total_credit,is_posted,posted_at,posted_by,created_by)\n  SELECT v_entry,je.entry_date,'historical_repair',v_exp.id,'HR-CASH-'||v_cmd::text,\n    'Historical cash restatement for '||v_exp.voucher_number,0,0,true,now(),auth.uid(),auth.uid()\n    FROM public.journal_entries je WHERE je.id=v_source_je RETURNING id INTO v_new_je;\n  v_line_no:=1;\n  IF p_operation='restate_salary_net_of_advance' THEN\n    FOR v_line IN SELECT * FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je ORDER BY line_number LOOP\n      IF v_line.account_id=v_bank_coa AND v_line.credit>0 THEN CONTINUE; END IF;\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n      VALUES(v_new_je,v_line_no,v_line.account_id,v_line.debit,v_line.credit,\n        'Salary restatement: '||COALESCE(v_line.description,''),v_line.supplier_id);\n      v_line_no:=v_line_no+1;\n    END LOOP;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)\n    VALUES(v_new_je,v_line_no,v_ap_coa,0,500000,'Salary advance applied (AP until recovery)');\n    v_line_no:=v_line_no+1;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)\n    VALUES(v_new_je,v_line_no,v_bank_coa,0,2000000,'July salary cash settlement');\n    UPDATE public.finance_expenses SET paid_amount=2000000 WHERE id=p_document_id;\n  ELSIF p_operation='restate_partial_supplier_cash' THEN\n    FOR v_line IN SELECT * FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je ORDER BY line_number LOOP\n      IF v_line.account_id=v_bank_coa AND v_line.credit>0 THEN CONTINUE; END IF;\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n      VALUES(v_new_je,v_line_no,v_line.account_id,v_line.debit,v_line.credit,\n        'Partial-cash restatement: '||COALESCE(v_line.description,''),v_line.supplier_id);\n      v_line_no:=v_line_no+1;\n    END LOOP;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n    VALUES(v_new_je,v_line_no,v_ap_coa,0,40000,'Remaining supplier payable',v_exp.supplier_id);\n    v_line_no:=v_line_no+1;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n    VALUES(v_new_je,v_line_no,v_bank_coa,0,6820000,'Actual bank payment',v_exp.supplier_id);\n    UPDATE public.finance_expenses SET paid_amount=6820000 WHERE id=p_document_id;\n  ELSE\n    FOR v_line IN SELECT * FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je ORDER BY line_number LOOP\n      IF v_line.account_id=v_bank_coa AND v_line.credit>0 THEN\n        INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n        VALUES(v_new_je,v_line_no,v_line.account_id,v_line.debit,v_line.credit+v_charge,\n          'Service cash plus evidenced bank charge: '||COALESCE(v_line.description,''),v_line.supplier_id);\n      ELSE\n        INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n        VALUES(v_new_je,v_line_no,v_line.account_id,v_line.debit,v_line.credit,\n          COALESCE(v_line.description,''),v_line.supplier_id);\n      END IF;\n      v_line_no:=v_line_no+1;\n    END LOOP;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description)\n    VALUES(v_new_je,v_line_no,v_charge_coa,v_charge,0,'Evidenced bank charge');\n    UPDATE public.finance_expenses SET paid_amount=v_bank_amount WHERE id=p_document_id;\n  END IF;\n  SELECT COALESCE(sum(debit),0), COALESCE(sum(credit),0) INTO v_new_debit, v_new_credit\n    FROM public.journal_entry_lines WHERE journal_entry_id=v_new_je;\n  IF abs(v_new_debit-v_new_credit)>0.01 THEN\n    RAISE EXCEPTION 'Replacement journal is not balanced';\n  END IF;\n  UPDATE public.journal_entries SET total_debit=v_new_debit, total_credit=v_new_credit WHERE id=v_new_je;\n  SELECT COALESCE(sum(credit),0) INTO v_cash_credit\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id=v_new_je AND account_id=v_bank_coa;\n  IF abs(v_cash_credit-v_bank_amount)>0.01 THEN\n    RAISE EXCEPTION 'Replacement bank movement does not match the bank statement';\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE journal_entry_id=v_new_je) THEN\n    RAISE EXCEPTION 'Duplicate cash event';\n  END IF;\n  INSERT INTO public.bank_statement_allocations(\n    bank_statement_line_id,document_type,document_id,journal_entry_id,\n    allocation_amount,payment_kind,created_by)\n  VALUES(p_bank_statement_line_id,'expense',p_document_id,v_new_je,\n    round(p_allocation_amount,2),p_payment_kind,auth.uid())\n  RETURNING * INTO v_alloc;\n  IF p_operation='restate_salary_net_of_advance' THEN\n    IF (SELECT is_reversed FROM public.journal_entries WHERE id=v_je0001)\n       OR (SELECT is_reversed FROM public.journal_entries WHERE id=v_je0002) THEN\n      RAISE EXCEPTION 'Advance journals were altered';\n    END IF;\n  END IF;\n  SELECT jsonb_build_object(\n      'source_journal_id',v_source_je,\n      'reversal_journal_id',v_reversal_je,\n      'replacement_journal_id',v_new_je,\n      'allocation_id',v_alloc.id,\n      'allocation_amount',v_alloc.allocation_amount,\n      'bank_amount',v_bank_amount,\n      'remaining_ap',v_remaining_ap,\n      'paid_amount',(SELECT paid_amount FROM public.finance_expenses WHERE id=p_document_id)\n    ) INTO v_after;\n  UPDATE public.finance_historical_repair_commands\n     SET before_state=v_before, after_state=v_after, created_allocation_id=v_alloc.id\n   WHERE id=v_cmd;\n  RETURN jsonb_build_object('idempotent',false,'command_id',v_cmd,'allocation_id',v_alloc.id,\n    'before',v_before,'after',v_after);\nEND;\n$$","--\n-- Name: execute_historical_finance_repair(\\"text\\", \\"text\\", \\"uuid\\", \\"uuid\\", numeric, \\"jsonb\\", \\"text\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"execute_historical_finance_repair\\"(\\"p_idempotency_key\\" \\"text\\", \\"p_document_type\\" \\"text\\", \\"p_document_id\\" \\"uuid\\", \\"p_bank_statement_line_id\\" \\"uuid\\", \\"p_allocation_amount\\" numeric, \\"p_expected\\" \\"jsonb\\", \\"p_payment_kind\\" \\"text\\" DEFAULT 'supplier'::\\"text\\", \\"p_operation\\" \\"text\\" DEFAULT 'allocate_existing_cash_event'::\\"text\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_existing public.finance_historical_repair_commands%rowtype;\n  v_cmd uuid; v_je uuid; v_source_je uuid; v_reversal_je uuid; v_ap_je uuid;\n  v_source_amount numeric; v_settlement numeric; v_bank_amount numeric; v_bank_coa uuid; v_ap_coa uuid;\n  v_cash_lines integer; v_cash_credit numeric; v_bank_gl_debit numeric; v_bank_gl_credit numeric;\n  v_is_debit boolean; v_je_balanced boolean; v_acct_ccy text; v_line_ccy text; v_je_ccy text;\n  v_before jsonb; v_after jsonb; v_je_before jsonb; v_alloc public.bank_statement_allocations%rowtype;\n  v_entry text; v_line record; v_line_no integer;\nBEGIN\n  IF auth.role()<>'service_role' AND current_user NOT IN ('postgres','supabase_admin')\n     AND NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id=auth.uid() AND is_active=true AND role='admin') THEN\n    RAISE EXCEPTION 'Historical repair requires service_role or admin';\n  END IF;\n  IF NULLIF(trim(p_idempotency_key),'') IS NULL OR p_allocation_amount<=0 THEN\n    RAISE EXCEPTION 'Idempotency key and positive allocation amount are required';\n  END IF;\n  SELECT * INTO v_existing FROM public.finance_historical_repair_commands WHERE idempotency_key=p_idempotency_key FOR UPDATE;\n  IF FOUND THEN\n    RETURN jsonb_build_object('idempotent',true,'command_id',v_existing.id,'allocation_id',v_existing.created_allocation_id,'before',v_existing.before_state,'after',v_existing.after_state);\n  END IF;\n  IF p_payment_kind NOT IN ('supplier','pph23') THEN RAISE EXCEPTION 'Unsupported payment kind'; END IF;\n\n  IF p_operation='reclassify_cash_recognition_to_ap' THEN\n    IF p_document_type <> 'expense' OR p_bank_statement_line_id IS NOT NULL THEN\n      RAISE EXCEPTION 'AP reclassification requires an expense and no bank evidence';\n    END IF;\n    INSERT INTO public.finance_historical_repair_commands(idempotency_key,document_type,document_id,bank_statement_line_id,payment_kind,operation,requested_by,before_state,after_state,status)\n    VALUES(p_idempotency_key,p_document_type,p_document_id,NULL,p_payment_kind,p_operation,auth.uid(),'{}','{}','committed') RETURNING id INTO v_cmd;\n    PERFORM set_config('app.finance_historical_repair_command',v_cmd::text,true);\n    PERFORM set_config('app.finance_historical_repair','on',true);\n    PERFORM 1 FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;\n    IF NOT FOUND THEN RAISE EXCEPTION 'Missing expense source'; END IF;\n    SELECT settlement_amount,paid_amount INTO v_settlement,v_source_amount FROM public.finance_expenses WHERE id=p_document_id;\n    IF COALESCE(v_source_amount,0)<>0 THEN RAISE EXCEPTION 'Expense is not unpaid'; END IF;\n    IF abs(COALESCE(v_settlement,0)-p_allocation_amount)>0.01 THEN RAISE EXCEPTION 'Settlement amount mismatch'; END IF;\n    IF EXISTS (SELECT 1 FROM public.payment_vouchers pv WHERE pv.description ILIKE '%'||(SELECT voucher_number FROM public.finance_expenses WHERE id=p_document_id)||'%' OR pv.reference_number ILIKE '%'||(SELECT voucher_number FROM public.finance_expenses WHERE id=p_document_id)||'%') THEN\n      RAISE EXCEPTION 'Payment voucher evidence exists'; END IF;\n    IF EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE document_type='expense' AND document_id=p_document_id) THEN RAISE EXCEPTION 'Bank allocation already exists'; END IF;\n    IF EXISTS (SELECT 1 FROM public.bank_statement_lines WHERE matched_expense_id=p_document_id OR matched_payment_id IN (SELECT id FROM public.payment_vouchers WHERE description ILIKE '%'||(SELECT voucher_number FROM public.finance_expenses WHERE id=p_document_id)||'%')) THEN\n      RAISE EXCEPTION 'Bank payment evidence exists'; END IF;\n    SELECT je.id,fe.settlement_amount INTO v_source_je,v_settlement FROM public.journal_entries je JOIN public.finance_expenses fe ON fe.id=je.reference_id\n      WHERE fe.id=p_document_id AND je.entry_number=COALESCE(p_expected->>'entry_number',je.entry_number) AND je.source_module IN ('expense','expenses') AND je.is_posted AND NOT COALESCE(je.is_reversed,false) FOR UPDATE;\n    IF v_source_je IS NULL THEN RAISE EXCEPTION 'Expected posted recognition journal is missing'; END IF;\n    IF p_expected ? 'journal_id' AND p_expected->>'journal_id'<>v_source_je::text THEN RAISE EXCEPTION 'Unexpected source journal'; END IF;\n    PERFORM 1 FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je FOR UPDATE;\n    SELECT ba.coa_id INTO v_bank_coa FROM public.bank_accounts ba WHERE EXISTS (SELECT 1 FROM public.journal_entry_lines l WHERE l.journal_entry_id=v_source_je AND l.account_id=ba.coa_id AND l.credit>0);\n    SELECT count(*),COALESCE(sum(l.credit),0) INTO v_cash_lines,v_cash_credit FROM public.journal_entry_lines l WHERE l.journal_entry_id=v_source_je AND l.account_id=v_bank_coa AND l.credit>0;\n    IF v_bank_coa IS NULL OR v_cash_lines<>1 OR abs(v_cash_credit-p_allocation_amount)>0.01 THEN RAISE EXCEPTION 'Source journal is not the expected cash recognition'; END IF;\n    SELECT id INTO v_ap_coa FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n    IF v_ap_coa IS NULL THEN RAISE EXCEPTION 'AP account 2110 is missing'; END IF;\n    SELECT jsonb_build_object('source_journal_id',je.id,'entry_number',je.entry_number,'total_debit',je.total_debit,'total_credit',je.total_credit,'lines',(SELECT COALESCE(jsonb_agg(to_jsonb(l) ORDER BY l.line_number),'[]') FROM public.journal_entry_lines l WHERE l.journal_entry_id=je.id)) INTO v_before FROM public.journal_entries je WHERE je.id=v_source_je;\n    IF p_expected ? 'settlement_amount' AND abs((p_expected->>'settlement_amount')::numeric-v_settlement)>0.01 THEN RAISE EXCEPTION 'Unexpected settlement amount'; END IF;\n    v_entry:=public.generate_journal_entry_number();\n    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,posted_by,created_by)\n    SELECT v_entry,je.entry_date,'historical_repair',je.reference_id,'HR-REV-'||v_cmd::text,'Explicit reversal of incorrect cash recognition '||je.entry_number,je.total_credit,je.total_debit,true,now(),auth.uid(),auth.uid() FROM public.journal_entries je WHERE je.id=v_source_je RETURNING id INTO v_reversal_je;\n    v_line_no:=1;\n    FOR v_line IN SELECT * FROM public.journal_entry_lines WHERE journal_entry_id=v_source_je ORDER BY line_number LOOP\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n      VALUES(v_reversal_je,v_line_no,v_line.account_id,v_line.credit,v_line.debit,'Historical reversal: '||COALESCE(v_line.description,''),v_line.supplier_id);\n      v_line_no:=v_line_no+1;\n    END LOOP;\n    UPDATE public.journal_entries SET is_reversed=true,reversed_by_id=v_reversal_je WHERE id=v_source_je;\n    v_entry:=public.generate_journal_entry_number();\n    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,posted_by,created_by)\n    SELECT v_entry,je.entry_date,'historical_repair',je.reference_id,'HR-AP-'||v_cmd::text,'Correct AP recognition for '||fe.voucher_number,je.total_debit,je.total_debit,true,now(),auth.uid(),auth.uid()\n      FROM public.journal_entries je JOIN public.finance_expenses fe ON fe.id=je.reference_id WHERE je.id=v_source_je RETURNING id INTO v_ap_je;\n    v_line_no:=1;\n    FOR v_line IN SELECT l.* FROM public.journal_entry_lines l WHERE l.journal_entry_id=v_source_je ORDER BY l.line_number LOOP\n      IF v_line.account_id=v_bank_coa AND v_line.credit>0 THEN CONTINUE; END IF;\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n      VALUES(v_ap_je,v_line_no,v_line.account_id,v_line.debit,v_line.credit,'AP correction: '||COALESCE(v_line.description,''),v_line.supplier_id);\n      v_line_no:=v_line_no+1;\n    END LOOP;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id)\n    VALUES(v_ap_je,v_line_no,v_ap_coa,0,p_allocation_amount,'Supplier/AP payable',(SELECT supplier_id FROM public.finance_expenses WHERE id=p_document_id));\n    SELECT jsonb_build_object('reversal_journal_id',v_reversal_je,'replacement_journal_id',v_ap_je,'source_journal_id',v_source_je,'allocation_id',NULL,'paid_amount',0,'settlement_amount',v_settlement,'bank_allocation_count',0) INTO v_after;\n    UPDATE public.finance_historical_repair_commands SET before_state=v_before,after_state=v_after WHERE id=v_cmd;\n    RETURN jsonb_build_object('idempotent',false,'command_id',v_cmd,'before',v_before,'after',v_after);\n  END IF;\n\n  IF p_operation<>'allocate_existing_cash_event' THEN RAISE EXCEPTION 'Unsupported historical repair operation'; END IF;\n  IF p_document_type NOT IN ('expense','payment','receipt','tax_payment','fund_transfer','petty_cash','journal') THEN RAISE EXCEPTION 'Unsupported historical repair document'; END IF;\n  IF p_bank_statement_line_id IS NULL THEN RAISE EXCEPTION 'Allocation repair requires bank statement evidence'; END IF;\n  INSERT INTO public.finance_historical_repair_commands(idempotency_key,document_type,document_id,bank_statement_line_id,payment_kind,operation,requested_by,before_state,after_state,status)\n  VALUES(p_idempotency_key,p_document_type,p_document_id,p_bank_statement_line_id,p_payment_kind,p_operation,auth.uid(),'{}','{}','committed') RETURNING id INTO v_cmd;\n  PERFORM set_config('app.finance_historical_repair_command',v_cmd::text,true);\n  PERFORM set_config('app.finance_historical_repair','on',true);\n  PERFORM 1 FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Missing cash evidence'; END IF;\n  SELECT COALESCE(NULLIF(debit_amount,0),credit_amount,0), COALESCE(debit_amount,0)>0, currency,\n         (SELECT ba.currency FROM public.bank_accounts ba WHERE ba.id=bank_statement_lines.bank_account_id),\n         (SELECT ba.coa_id FROM public.bank_accounts ba WHERE ba.id=bank_statement_lines.bank_account_id)\n    INTO v_bank_amount, v_is_debit, v_line_ccy, v_acct_ccy, v_bank_coa FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id;\n  IF v_bank_amount IS NULL OR abs(p_allocation_amount-v_bank_amount)>0.01 THEN RAISE EXCEPTION 'Amount mismatch'; END IF;\n  IF p_expected ? 'bank_amount' AND abs((p_expected->>'bank_amount')::numeric-v_bank_amount)>0.01 THEN RAISE EXCEPTION 'Unexpected bank amount'; END IF;\n  IF v_bank_coa IS NULL THEN RAISE EXCEPTION 'Missing bank ledger account'; END IF;\n  IF COALESCE(v_line_ccy, v_acct_ccy) IS DISTINCT FROM v_acct_ccy AND COALESCE(v_line_ccy, v_acct_ccy) IS NOT NULL THEN RAISE EXCEPTION 'Currency mismatch'; END IF;\n  IF p_document_type='expense' THEN\n    PERFORM 1 FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;\n    IF NOT FOUND THEN RAISE EXCEPTION 'Missing expense source'; END IF;\n    SELECT je.id INTO v_je FROM public.journal_entries je WHERE je.id=COALESCE((p_expected->>'journal_id')::uuid, je.id) AND je.source_module IN ('expense','expenses') AND je.is_posted AND NOT COALESCE(je.is_reversed,false) AND (je.reference_id=p_document_id OR je.reference_number='EXP-'||p_document_id::text) FOR UPDATE;\n  ELSIF p_document_type='receipt' THEN SELECT journal_entry_id, amount INTO v_je, v_source_amount FROM public.receipt_vouchers WHERE id=p_document_id AND is_posted FOR UPDATE;\n  ELSIF p_document_type='payment' THEN SELECT journal_entry_id, amount INTO v_je, v_source_amount FROM public.payment_vouchers WHERE id=p_document_id AND is_posted FOR UPDATE;\n  ELSIF p_document_type='tax_payment' THEN SELECT journal_entry_id, amount INTO v_je, v_source_amount FROM public.tax_payments WHERE id=p_document_id FOR UPDATE;\n  ELSIF p_document_type='fund_transfer' THEN SELECT journal_entry_id INTO v_je FROM public.fund_transfers WHERE id=p_document_id FOR UPDATE;\n  ELSIF p_document_type='petty_cash' THEN SELECT journal_entry_id INTO v_je FROM public.petty_cash_transactions WHERE id=p_document_id FOR UPDATE;\n  ELSIF p_document_type='journal' THEN v_je := p_document_id; PERFORM 1 FROM public.journal_entries WHERE id=v_je FOR UPDATE;\n  END IF;\n  IF p_expected ? 'journal_id' AND (v_je IS NULL OR v_je::text <> p_expected->>'journal_id') THEN RAISE EXCEPTION 'Unexpected journal'; END IF;\n  IF v_je IS NULL THEN RAISE EXCEPTION 'Missing posted source journal/evidence'; END IF;\n  PERFORM 1 FROM public.journal_entries WHERE id=v_je AND is_posted AND NOT COALESCE(is_reversed,false) FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Missing posted source journal/evidence'; END IF;\n  IF p_expected ? 'entry_number' AND (SELECT entry_number FROM public.journal_entries WHERE id=v_je) <> p_expected->>'entry_number' THEN RAISE EXCEPTION 'Unexpected journal'; END IF;\n  SELECT transaction_currency INTO v_je_ccy FROM public.journal_entries WHERE id=v_je;\n  IF v_je_ccy IS NOT NULL AND v_acct_ccy IS NOT NULL AND v_je_ccy <> v_acct_ccy THEN RAISE EXCEPTION 'Currency mismatch'; END IF;\n  PERFORM 1 FROM public.journal_entry_lines WHERE journal_entry_id=v_je FOR UPDATE;\n  PERFORM 1 FROM public.bank_statement_allocations WHERE bank_statement_line_id=p_bank_statement_line_id FOR UPDATE;\n  SELECT COALESCE(sum(debit),0), COALESCE(sum(credit),0) INTO v_bank_gl_debit, v_bank_gl_credit FROM public.journal_entry_lines WHERE journal_entry_id=v_je AND account_id=v_bank_coa;\n  IF v_is_debit THEN\n    IF abs(v_bank_gl_credit-v_bank_amount)>0.01 OR v_bank_gl_debit>0.01 THEN RAISE EXCEPTION 'Journal bank movement does not match bank statement'; END IF;\n  ELSE\n    IF abs(v_bank_gl_debit-v_bank_amount)>0.01 OR v_bank_gl_credit>0.01 THEN RAISE EXCEPTION 'Journal bank movement does not match bank statement'; END IF;\n  END IF;\n  SELECT abs(total_debit-total_credit)<0.01 INTO v_je_balanced FROM public.journal_entries WHERE id=v_je;\n  IF NOT COALESCE(v_je_balanced,false) THEN RAISE EXCEPTION 'Journal is not balanced'; END IF;\n  SELECT jsonb_build_object('journal_id',je.id,'entry_number',je.entry_number,'total_debit',je.total_debit,'total_credit',je.total_credit,'line_count',(SELECT count(*) FROM public.journal_entry_lines l WHERE l.journal_entry_id=je.id),'allocations',(SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') FROM public.bank_statement_allocations a WHERE a.journal_entry_id=je.id)) INTO v_before FROM public.journal_entries je WHERE je.id=v_je;\n  v_je_before:=v_before;\n  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE bank_statement_line_id=p_bank_statement_line_id AND document_type=p_document_type AND document_id=p_document_id AND payment_kind=p_payment_kind) THEN RAISE EXCEPTION 'Duplicate cash event'; END IF;\n  IF EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE journal_entry_id=v_je) THEN RAISE EXCEPTION 'Duplicate cash event'; END IF;\n  INSERT INTO public.bank_statement_allocations(bank_statement_line_id,document_type,document_id,journal_entry_id,allocation_amount,payment_kind,created_by)\n  VALUES(p_bank_statement_line_id,p_document_type,p_document_id,v_je,round(p_allocation_amount,2),p_payment_kind,auth.uid()) RETURNING * INTO v_alloc;\n  SELECT jsonb_build_object('journal_id',je.id,'entry_number',je.entry_number,'total_debit',je.total_debit,'total_credit',je.total_credit,'line_count',(SELECT count(*) FROM public.journal_entry_lines l WHERE l.journal_entry_id=je.id),'allocation_id',v_alloc.id,'allocation_amount',v_alloc.allocation_amount) INTO v_after FROM public.journal_entries je WHERE je.id=v_je;\n  IF v_after->>'journal_id'<>v_je_before->>'journal_id' OR v_after->>'total_debit'<>v_je_before->>'total_debit' OR v_after->>'total_credit'<>v_je_before->>'total_credit' OR v_after->>'line_count'<>v_je_before->>'line_count' THEN RAISE EXCEPTION 'Unexpected journal change'; END IF;\n  UPDATE public.finance_historical_repair_commands SET before_state=v_before, after_state=v_after, created_allocation_id=v_alloc.id WHERE id=v_cmd;\n  RETURN jsonb_build_object('idempotent',false,'command_id',v_cmd,'allocation_id',v_alloc.id,'before',v_before,'after',v_after);\nEND;\n$$","--\n-- Name: FUNCTION \\"execute_historical_finance_repair\\"(\\"p_idempotency_key\\" \\"text\\", \\"p_document_type\\" \\"text\\", \\"p_document_id\\" \\"uuid\\", \\"p_bank_statement_line_id\\" \\"uuid\\", \\"p_allocation_amount\\" numeric, \\"p_expected\\" \\"jsonb\\", \\"p_payment_kind\\" \\"text\\", \\"p_operation\\" \\"text\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"execute_historical_finance_repair\\"(\\"p_idempotency_key\\" \\"text\\", \\"p_document_type\\" \\"text\\", \\"p_document_id\\" \\"uuid\\", \\"p_bank_statement_line_id\\" \\"uuid\\", \\"p_allocation_amount\\" numeric, \\"p_expected\\" \\"jsonb\\", \\"p_payment_kind\\" \\"text\\", \\"p_operation\\" \\"text\\") IS 'Privileged, transaction-scoped, idempotent historical allocation or explicit cash correction. Existing recognition journals are immutable; no ordinary document sync path is called.'","--\n-- Name: expense_explicit_replacement_journals(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"expense_explicit_replacement_journals\\"() RETURNS TABLE(\\"expense_id\\" \\"uuid\\", \\"journal_id\\" \\"uuid\\")\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $_$\n  SELECT DISTINCT i.document_id, je.id\n    FROM public.finance_historical_repair_items i\n    JOIN public.journal_entries je\n      ON je.id = CASE\n        WHEN COALESCE(i.new_metadata ->> 'replacement_journal_id', '')\n             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'\n        THEN (i.new_metadata ->> 'replacement_journal_id')::uuid\n      END\n   WHERE i.document_type IN ('expense', 'salary_advance_expense')\n     AND COALESCE(i.new_metadata ->> 'replacement_journal_id', '')\n         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'\n     AND je.source_module NOT IN ('expense', 'expenses')\n\n  UNION\n\n  SELECT fe.id, cash_restatement.id\n    FROM public.finance_expenses fe\n    JOIN public.journal_entries cash_restatement\n      ON cash_restatement.reference_id = fe.id\n     AND cash_restatement.source_module = 'historical_repair'\n     AND cash_restatement.reference_number LIKE 'HR-CASH-%'\n     AND cash_restatement.is_posted = true\n     AND NOT COALESCE(cash_restatement.is_reversed, false)\n   WHERE EXISTS (\n     SELECT 1\n       FROM public.journal_entries original\n      WHERE original.source_module IN ('expense', 'expenses')\n        AND original.is_posted = true\n        AND COALESCE(original.is_reversed, false)\n        AND (original.reference_id = fe.id\n          OR (original.reference_id IS NULL\n            AND original.reference_number = 'EXP-' || fe.id::text))\n   );\n$_$","--\n-- Name: expense_recognition_has_direct_bank_settlement(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"expense_recognition_has_direct_bank_settlement\\"(\\"p_expense_id\\" \\"uuid\\", \\"p_recognition_journal_id\\" \\"uuid\\") RETURNS boolean\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\n  SELECT EXISTS (\n    SELECT 1\n      FROM journal_entry_lines l\n      JOIN bank_accounts ba ON ba.coa_id=l.account_id\n     WHERE l.journal_entry_id=p_recognition_journal_id\n       AND l.credit>0\n       AND EXISTS (\n         SELECT 1 FROM journal_entries j\n          WHERE j.id=p_recognition_journal_id\n            AND j.reference_id=p_expense_id\n            AND j.source_module IN ('expense','expenses')\n            AND j.is_posted AND NOT COALESCE(j.is_reversed,false)\n       )\n  );\n$$","--\n-- Name: FUNCTION \\"expense_recognition_has_direct_bank_settlement\\"(\\"p_expense_id\\" \\"uuid\\", \\"p_recognition_journal_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"expense_recognition_has_direct_bank_settlement\\"(\\"p_expense_id\\" \\"uuid\\", \\"p_recognition_journal_id\\" \\"uuid\\") IS 'Detects legacy expense recognition journals that already credit a bank account; used to prevent duplicate settlement postings.'","--\n-- Name: finance_bank_match_text_score(\\"text\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"finance_bank_match_text_score\\"(\\"p_bank_text\\" \\"text\\", \\"p_document_text\\" \\"text\\") RETURNS integer\n    LANGUAGE \\"sql\\" IMMUTABLE\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $_$\n  SELECT count(*)::integer\n  FROM (\n    SELECT DISTINCT token\n    FROM unnest(tsvector_to_array(to_tsvector('simple', lower(COALESCE(p_document_text, ''))))) AS token\n    WHERE length(token) >= 4\n      AND token !~ '^[0-9]+$'\n      AND token NOT IN (\n        'bank', 'transfer', 'payment', 'paid', 'expense', 'expenses',\n        'invoice', 'general', 'admin', 'amount', 'charge', 'charges'\n      )\n  ) document_tokens\n  WHERE token = ANY (\n    tsvector_to_array(to_tsvector('simple', lower(COALESCE(p_bank_text, ''))))\n  );\n$_$","--\n-- Name: finance_staff_master_sync_salary_gl(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"finance_staff_master_sync_salary_gl\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_coa public.chart_of_accounts%rowtype;\nBEGIN\n  IF NEW.default_gl_account_id IS NULL THEN\n    SELECT * INTO v_coa FROM public.chart_of_accounts\n     WHERE code = '6100' AND is_active AND NOT is_header LIMIT 1;\n    IF NOT FOUND THEN RAISE EXCEPTION 'Canonical salary COA 6100 is missing or inactive'; END IF;\n    NEW.default_gl_account_id := v_coa.id;\n  ELSE\n    SELECT * INTO v_coa FROM public.chart_of_accounts WHERE id = NEW.default_gl_account_id;\n    IF NOT FOUND OR NOT v_coa.is_active OR v_coa.is_header OR lower(v_coa.account_type) <> 'expense' THEN\n      RAISE EXCEPTION 'Staff salary GL must reference an active posting expense Chart of Account';\n    END IF;\n  END IF;\n  NEW.default_gl_code := v_coa.code;\n  NEW.default_gl_name := v_coa.name;\n  RETURN NEW;\nEND $$","--\n-- Name: fn_auto_delete_import_requirements_on_cancel(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_auto_delete_import_requirements_on_cancel\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- Delete import requirements if SO is cancelled or rejected\nIF NEW.status IN ('cancelled', 'rejected') AND OLD.status NOT IN ('cancelled', 'rejected') THEN\nDELETE FROM import_requirements\nWHERE sales_order_id = NEW.id;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: fn_auto_release_on_so_status_change(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_auto_release_on_so_status_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF NEW.status IN ('cancelled', 'rejected', 'delivered', 'closed')\nAND OLD.status NOT IN ('cancelled', 'rejected', 'delivered', 'closed') THEN\nPERFORM fn_release_reservation_by_so_id(NEW.id, NULL);\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: fn_auto_rereserve_on_batch_arrival(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_auto_rereserve_on_batch_arrival\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_so_id uuid;\nBEGIN\n  IF TG_OP = 'UPDATE' THEN\n    IF NEW.current_stock IS NOT DISTINCT FROM OLD.current_stock\n       AND NEW.is_active IS NOT DISTINCT FROM OLD.is_active THEN\n      RETURN NEW;\n    END IF;\n  END IF;\n\n  -- When positive stock is added or a new active batch arrives with stock\n  IF (TG_OP = 'INSERT' AND NEW.is_active AND NEW.current_stock > 0)\n     OR (TG_OP = 'UPDATE' AND NEW.is_active AND NEW.current_stock > COALESCE(OLD.current_stock, 0)) THEN\n\n    PERFORM set_config('app.canonical_reservation_engine', 'on', true);\n\n    FOR v_so_id IN\n      SELECT DISTINCT so.id\n      FROM public.sales_orders so\n      JOIN public.sales_order_items soi ON soi.sales_order_id = so.id\n      WHERE soi.product_id = NEW.product_id\n        AND so.status::text = 'shortage'\n        AND NOT COALESCE(so.is_archived, false)\n      ORDER BY so.id\n    LOOP\n      PERFORM public.approve_sales_order_product_reservation_v2(v_so_id, NULL);\n    END LOOP;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: fn_calculate_import_priority(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_calculate_import_priority\\"(\\"p_delivery_date\\" \\"date\\") RETURNS \\"public\\".\\"import_priority\\"\n    LANGUAGE \\"plpgsql\\" IMMUTABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_days_until_delivery integer;\nBEGIN\nv_days_until_delivery := p_delivery_date - CURRENT_DATE;\n\nIF v_days_until_delivery < 7 THEN\nRETURN 'high'::import_priority;\nELSIF v_days_until_delivery <= 30 THEN\nRETURN 'medium'::import_priority;\nELSE\nRETURN 'low'::import_priority;\nEND IF;\nEND;\n$$","--\n-- Name: fn_cancel_delivery_challan(\\"uuid\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_cancel_delivery_challan\\"(\\"p_dc_id\\" \\"uuid\\", \\"p_user\\" \\"uuid\\", \\"p_reason\\" \\"text\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_role text;\nBEGIN\n  SELECT role INTO v_role FROM profiles WHERE id = COALESCE(auth.uid(), p_user);\n  IF v_role IS NULL OR v_role NOT IN ('admin','accounts','warehouse','manager') THEN\n    RAISE EXCEPTION 'Not authorized to cancel delivery challans';\n  END IF;\n\n  UPDATE delivery_challans\n     SET approval_status   = 'cancelled',\n         rejection_reason  = COALESCE(p_reason, rejection_reason),\n         rejected_by       = COALESCE(p_user, auth.uid()),\n         rejected_at       = now(),\n         updated_at        = now()\n   WHERE id = p_dc_id;\nEND;\n$$","--\n-- Name: fn_cancel_sales_order(\\"uuid\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_cancel_sales_order\\"(\\"p_so_id\\" \\"uuid\\", \\"p_canceller_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_role text;\n  v_status text;\nBEGIN\n  SELECT role INTO v_role\n  FROM public.user_profiles\n  WHERE id = auth.uid();\n\n  IF v_role NOT IN ('admin', 'accounts', 'sales', 'manager') THEN\n    RAISE EXCEPTION\n      'Permission denied: role % cannot cancel sales orders', v_role;\n  END IF;\n\n  SELECT status::text INTO v_status\n  FROM public.sales_orders\n  WHERE id = p_so_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Order not found';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM public.delivery_challans dc\n    WHERE dc.sales_order_id = p_so_id\n      AND dc.approval_status = 'approved'\n  ) THEN\n    RAISE EXCEPTION\n      'Sales Order has an approved Delivery Challan; reverse/cancel the Delivery Challan before cancelling the order';\n  END IF;\n\n  DELETE FROM public.import_requirements\n  WHERE sales_order_id = p_so_id;\n\n  PERFORM public.fn_release_stock_reservations(\n    p_so_id,\n    'SO cancelled: ' || p_reason,\n    p_canceller_id\n  );\n\n  UPDATE public.sales_orders\n  SET status = 'cancelled',\n      updated_at = now()\n  WHERE id = p_so_id;\n\n  RETURN true;\nEND;\n$$","--\n-- Name: fn_check_product_availability(\\"uuid\\", numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_check_product_availability\\"(\\"p_product_id\\" \\"uuid\\", \\"p_required_qty\\" numeric) RETURNS TABLE(\\"batch_id\\" \\"uuid\\", \\"batch_number\\" \\"text\\", \\"expiry_date\\" \\"date\\", \\"free_stock\\" numeric)\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT \nb.id,\nb.batch_number,\nb.expiry_date,\nfn_get_free_stock(b.id) as free_stock\nFROM batches b\nWHERE b.product_id = p_product_id\nAND b.current_stock > 0\nAND fn_get_free_stock(b.id) > 0\nORDER BY b.expiry_date ASC, b.created_at ASC;\nEND;\n$$","--\n-- Name: fn_close_pending_import_requirements_on_reservation(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_close_pending_import_requirements_on_reservation\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF OLD.status::text = 'shortage'\n     AND NEW.status::text = 'stock_reserved' THEN\n    UPDATE public.import_requirements ir\n    SET status = 'cancelled',\n        notes = COALESCE(ir.notes || ' | ', '') ||\n          'Auto-cancelled: shortage resolved by stock reservation ' ||\n          to_char(now(), 'YYYY-MM-DD'),\n        updated_at = now()\n    WHERE ir.sales_order_id = NEW.id\n      AND ir.status::text = 'pending';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: fn_create_import_requirements(\\"uuid\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_create_import_requirements\\"(\\"p_so_id\\" \\"uuid\\", \\"p_shortage_items\\" \\"jsonb\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_shortage      RECORD;\n  v_customer_id   UUID;\n  v_delivery_date DATE;\n  v_priority      import_priority;\n  v_existing_id   UUID;\nBEGIN\n  -- Get SO details\n  SELECT customer_id, expected_delivery_date\n  INTO v_customer_id, v_delivery_date\n  FROM sales_orders\n  WHERE id = p_so_id;\n\n  -- Default delivery date if not set\n  IF v_delivery_date IS NULL THEN\n    v_delivery_date := CURRENT_DATE + INTERVAL '30 days';\n  END IF;\n\n  -- Calculate priority from delivery date\n  v_priority := fn_calculate_import_priority(v_delivery_date);\n\n  -- ── Step 0: Cancel requirements for products NO LONGER in this SO ────────\n  -- This handles the product-change scenario (e.g. USP → EP):\n  --   old product's requirement becomes orphaned → cancel it.\n  -- Status check: only cancel active-phase requirements (not already cancelled/received).\n  UPDATE import_requirements\n  SET\n    status = 'cancelled',\n    notes  = COALESCE(notes || ' | ', '') || 'Product removed from SO on re-reservation ' || to_char(now(), 'YYYY-MM-DD')\n  WHERE sales_order_id = p_so_id\n    AND status NOT IN ('cancelled', 'received')\n    AND product_id NOT IN (\n      SELECT DISTINCT soi.product_id\n      FROM sales_order_items soi\n      WHERE soi.sales_order_id = p_so_id\n    );\n\n  -- ── Step 1: Upsert shortage requirements ─────────────────────────────────\n  FOR v_shortage IN\n    SELECT\n      (item->>'product_id')::UUID  AS product_id,\n      (item->>'required_qty')::NUMERIC AS required_qty,\n      (item->>'shortage_qty')::NUMERIC AS shortage_qty\n    FROM jsonb_array_elements(p_shortage_items) AS item\n  LOOP\n    -- Check for existing active requirement for this SO + product\n    SELECT id INTO v_existing_id\n    FROM import_requirements\n    WHERE sales_order_id = p_so_id\n      AND product_id = v_shortage.product_id\n      AND status NOT IN ('cancelled', 'received')\n    LIMIT 1;\n\n    IF v_existing_id IS NOT NULL THEN\n      -- Update existing requirement with latest shortage quantities\n      UPDATE import_requirements\n      SET\n        shortage_quantity     = v_shortage.shortage_qty,\n        required_quantity     = v_shortage.required_qty,\n        priority              = v_priority,\n        required_delivery_date = v_delivery_date,\n        updated_at            = now()\n      WHERE id = v_existing_id;\n    ELSE\n      -- Insert new requirement\n      INSERT INTO import_requirements (\n        product_id,\n        sales_order_id,\n        customer_id,\n        required_quantity,\n        shortage_quantity,\n        required_delivery_date,\n        priority,\n        status,\n        ordered_qty,\n        allocated_qty,\n        received_qty,\n        notes\n      ) VALUES (\n        v_shortage.product_id,\n        p_so_id,\n        v_customer_id,\n        v_shortage.required_qty,\n        v_shortage.shortage_qty,\n        v_delivery_date,\n        v_priority,\n        'pending',\n        0,\n        0,\n        0,\n        'Auto-generated from SO shortage'\n      );\n    END IF;\n  END LOOP;\n\n  RETURN TRUE;\nEND;\n$$","--\n-- Name: fn_get_free_stock(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_get_free_stock\\"(\\"p_batch_id\\" \\"uuid\\") RETURNS numeric\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_current_stock numeric;\nv_reserved_qty numeric;\nv_free_stock numeric;\nBEGIN\n-- Get current stock from batches\nSELECT current_stock INTO v_current_stock\nFROM batches\nWHERE id = p_batch_id;\n\nIF v_current_stock IS NULL THEN\nRETURN 0;\nEND IF;\n\n-- Get total active reservations\nSELECT COALESCE(SUM(reserved_quantity), 0) INTO v_reserved_qty\nFROM stock_reservations\nWHERE batch_id = p_batch_id\nAND status = 'active';\n\nv_free_stock := v_current_stock - v_reserved_qty;\n\nRETURN GREATEST(v_free_stock, 0);\nEND;\n$$","--\n-- Name: fn_get_import_requirements_summary(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_get_import_requirements_summary\\"() RETURNS TABLE(\\"product_id\\" \\"uuid\\", \\"product_name\\" \\"text\\", \\"total_shortage\\" numeric, \\"pending_orders\\" integer, \\"highest_priority\\" \\"public\\".\\"import_priority\\", \\"earliest_delivery_date\\" \\"date\\")\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT \nir.product_id,\np.product_name,\nSUM(ir.shortage_quantity) as total_shortage,\nCOUNT(DISTINCT ir.sales_order_id)::integer as pending_orders,\nMIN(ir.priority) as highest_priority,\nMIN(ir.required_delivery_date) as earliest_delivery_date\nFROM import_requirements ir\nJOIN products p ON p.id = ir.product_id\nWHERE ir.status = 'pending'\nGROUP BY ir.product_id, p.product_name\nORDER BY MIN(ir.priority), MIN(ir.required_delivery_date);\nEND;\n$$","--\n-- Name: fn_period_payment_source(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_period_payment_source\\"(\\"p_liability\\" numeric, \\"p_txp\\" numeric, \\"p_imp\\" numeric) RETURNS \\"text\\"\n    LANGUAGE \\"sql\\" IMMUTABLE\n    SET \\"search_path\\" TO 'pg_catalog', 'public'\n    AS $$\n  SELECT CASE\n    WHEN COALESCE(p_liability, 0) <= 0.01 THEN 'none'\n    WHEN LEAST(p_liability, COALESCE(p_txp,0) + COALESCE(p_imp,0)) < p_liability - 0.01 THEN\n      CASE WHEN COALESCE(p_txp,0) > 0 OR COALESCE(p_imp,0) > 0 THEN 'partial' ELSE 'unpaid' END\n    WHEN COALESCE(p_txp,0) > 0 AND COALESCE(p_imp,0) > 0 THEN 'both'\n    WHEN COALESCE(p_imp,0) > 0                            THEN 'pib_expense'\n    ELSE 'tax_payment'\n  END;\n$$","--\n-- Name: fn_period_payment_status(\\"text\\", numeric, \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_period_payment_status\\"(\\"p_status\\" \\"text\\", \\"p_outstanding\\" numeric, \\"p_due\\" \\"date\\") RETURNS \\"text\\"\n    LANGUAGE \\"sql\\" STABLE\n    SET \\"search_path\\" TO 'pg_catalog', 'public'\n    AS $$\n  SELECT CASE\n    WHEN p_status IN ('closed', 'filed')            THEN p_status\n    WHEN COALESCE(p_outstanding, 0) <= 0.01         THEN 'paid'\n    WHEN p_due IS NOT NULL AND p_due < CURRENT_DATE  THEN 'overdue'\n    ELSE 'payment_pending'\n  END;\n$$","--\n-- Name: fn_pph_authoritative_source_total(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_pph_authoritative_source_total\\"(\\"p_period_id\\" \\"uuid\\") RETURNS numeric\n    LANGUAGE \\"sql\\" STABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH period AS (\n    SELECT id, fiscal_year, period_month, tax_type, period_start, period_end\n      FROM public.tax_periods\n     WHERE id = p_period_id\n       AND tax_type <> 'PPN'\n  )\n  SELECT COALESCE((\n    SELECT SUM(fe.pph_amount)\n      FROM period p\n      JOIN public.finance_expenses fe\n        ON (fe.pph_tax_period_id = p.id\n            OR (fe.pph_tax_period_id IS NULL\n                AND COALESCE(fe.due_date, fe.expense_date) BETWEEN p.period_start AND p.period_end))\n      JOIN public.effective_expense_posting_state eps\n        ON eps.expense_id = fe.id\n       AND eps.effective_posting_state IN ('ACTIVE', 'REPLACED')\n      LEFT JOIN public.tax_codes tc ON tc.id = fe.pph_code_id\n     WHERE fe.approval_status = 'approved'\n       AND fe.pph_amount > 0\n       AND COALESCE(fe.expense_category, '') NOT IN ('pib_import', 'pph_import')\n       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)\n  ), 0)\n  + COALESCE((\n    SELECT SUM(pv.pph_amount)\n      FROM period p\n      JOIN public.payment_vouchers pv\n        ON (pv.tax_period_id = p.id\n            OR (pv.tax_period_id IS NULL AND pv.voucher_date BETWEEN p.period_start AND p.period_end))\n      LEFT JOIN public.tax_codes tc ON tc.id = pv.pph_code_id\n     WHERE COALESCE(pv.is_posted, false)\n       AND pv.pph_amount > 0\n       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)\n  ), 0)\n  + COALESCE((\n    SELECT SUM(CASE WHEN fe.expense_category = 'pib_import'\n                    THEN COALESCE(fe.pib_pph_amount, 0)\n                    ELSE COALESCE(fe.amount, 0) END)\n      FROM period p\n      JOIN public.finance_expenses fe\n        ON (fe.pph_tax_period_id = p.id\n            OR (fe.pph_tax_period_id IS NULL\n                AND COALESCE(fe.due_date, fe.expense_date) BETWEEN p.period_start AND p.period_end))\n      JOIN public.effective_expense_posting_state eps\n        ON eps.expense_id = fe.id\n       AND eps.effective_posting_state IN ('ACTIVE', 'REPLACED')\n     WHERE p.tax_type IN ('PPh22', 'PPh_Unifikasi')\n       AND fe.approval_status = 'approved'\n       AND fe.expense_category IN ('pib_import', 'pph_import')\n  ), 0);\n$$","--\n-- Name: fn_pph_payable_account_id(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_pph_payable_account_id\\"(\\"p_tax_code_id\\" \\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT coa.id\n    FROM chart_of_accounts coa\n   WHERE coa.code = CASE (\n     SELECT tc.tax_type FROM tax_codes tc WHERE tc.id = p_tax_code_id\n   )\n     WHEN 'PPh21'   THEN '2131'\n     WHEN 'PPh22'   THEN '2137'\n     WHEN 'PPh23'   THEN '2132'\n     WHEN 'PPh4(2)' THEN '2138'\n     ELSE '2132'\n   END\n   LIMIT 1;\n$$","--\n-- Name: fn_recompute_so_delivered(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_recompute_so_delivered\\"(\\"p_so_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  BEGIN\n    PERFORM public.fn_recompute_so_status(p_so_id);\n  END;\n  $$","--\n-- Name: fn_recompute_so_status(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_recompute_so_status\\"(\\"p_so_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  DECLARE\n    v_ordered numeric := 0;\n    v_delivered numeric := 0;\n    v_invoiced numeric := 0;\n  BEGIN\n    IF p_so_id IS NULL THEN\n      RETURN;\n    END IF;\n\n    WITH approved_by_product AS (\n      SELECT\n        dci.product_id,\n        COALESCE(SUM(dci.quantity), 0)::numeric AS delivered_qty\n      FROM delivery_challans dc\n      JOIN delivery_challan_items dci ON dci.challan_id = dc.id\n      WHERE dc.sales_order_id = p_so_id\n        AND dc.approval_status = 'approved'\n      GROUP BY dci.product_id\n    ),\n    ordered_items AS (\n      SELECT\n        soi.id,\n        soi.product_id,\n        soi.quantity,\n        COALESCE(abp.delivered_qty, 0) AS delivered_qty,\n        COALESCE(\n          SUM(soi.quantity) OVER (\n            PARTITION BY soi.product_id\n            ORDER BY soi.created_at, soi.id\n            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING\n          ),\n          0\n        ) AS prior_qty\n      FROM sales_order_items soi\n      LEFT JOIN approved_by_product abp ON abp.product_id = soi.product_id\n      WHERE soi.sales_order_id = p_so_id\n    ),\n    allocated AS (\n      SELECT\n        id,\n        CASE\n          WHEN delivered_qty - prior_qty <= 0 THEN 0\n          WHEN delivered_qty - prior_qty >= quantity THEN quantity\n          ELSE delivered_qty - prior_qty\n        END AS delivered_quantity\n      FROM ordered_items\n    )\n    UPDATE sales_order_items soi\n       SET delivered_quantity = allocated.delivered_quantity\n      FROM allocated\n     WHERE soi.id = allocated.id;\n\n    SELECT COALESCE(SUM(quantity), 0)\n      INTO v_ordered\n      FROM sales_order_items\n     WHERE sales_order_id = p_so_id;\n\n    SELECT COALESCE(SUM(dci.quantity), 0)\n      INTO v_delivered\n      FROM delivery_challans dc\n      JOIN delivery_challan_items dci ON dci.challan_id = dc.id\n     WHERE dc.sales_order_id = p_so_id\n       AND dc.approval_status = 'approved';\n\n    SELECT COALESCE(SUM(x.quantity), 0)\n      INTO v_invoiced\n      FROM (\n        SELECT DISTINCT\n          sii.id,\n          sii.quantity\n        FROM sales_invoice_items sii\n        JOIN sales_invoices si ON si.id = sii.invoice_id\n        LEFT JOIN delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n        LEFT JOIN delivery_challans dc ON dc.id = dci.challan_id\n        WHERE COALESCE(si.is_draft, false) = false\n          AND si.invoice_number NOT ILIKE 'TEST-COGS-%'\n          AND COALESCE(si.sales_order_id, dc.sales_order_id) = p_so_id\n      ) x;\n\n    UPDATE sales_orders\n       SET status = CASE\n                      WHEN v_ordered > 0 AND v_delivered >= v_ordered AND v_invoiced >= v_ordered\n                        THEN 'closed'::sales_order_status\n                      WHEN v_ordered > 0 AND v_delivered >= v_ordered\n                        THEN 'delivered'::sales_order_status\n                      WHEN v_delivered > 0\n                        THEN 'partially_delivered'::sales_order_status\n                      ELSE status\n                    END,\n           updated_at = now()\n     WHERE id = p_so_id\n       AND status NOT IN ('closed', 'cancelled', 'rejected');\n  END;\n  $$","--\n-- Name: fn_reject_delivery_challan(\\"uuid\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_reject_delivery_challan\\"(\\"p_dc_id\\" \\"uuid\\", \\"p_rejector_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts','warehouse','manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot reject delivery challans', v_role;\nEND IF;\n\nUPDATE delivery_challans\nSET approval_status = 'rejected', rejection_reason = p_reason\nWHERE id = p_dc_id;\nRETURN true;\nEND;\n$$","--\n-- Name: fn_reject_sales_order(\\"uuid\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_reject_sales_order\\"(\\"p_so_id\\" \\"uuid\\", \\"p_rejector_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts','manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot reject sales orders', v_role;\nEND IF;\n\nPERFORM fn_release_stock_reservations(p_so_id, 'SO rejected: ' || p_reason);\nUPDATE sales_orders\nSET status = 'rejected', rejected_by = p_rejector_id, rejected_at = now(),\nrejection_reason = p_reason, updated_at = now()\nWHERE id = p_so_id;\nRETURN true;\nEND;\n$$","--\n-- Name: fn_release_partial_reservation(\\"uuid\\", \\"uuid\\", numeric, \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_release_partial_reservation\\"(\\"p_so_id\\" \\"uuid\\", \\"p_product_id\\" \\"uuid\\", \\"p_qty\\" numeric, \\"p_released_by\\" \\"uuid\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_reservation record;\n  v_remaining_qty numeric := p_qty;\n  v_release_qty numeric;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(\n    ARRAY['admin', 'accounts', 'manager', 'warehouse']\n  ) THEN\n    RAISE EXCEPTION 'Permission denied for partial reservation release';\n  END IF;\n  IF COALESCE(p_qty, 0) <= 0 THEN\n    RAISE EXCEPTION 'Reservation release quantity must be positive';\n  END IF;\n\n  FOR v_reservation IN\n    SELECT id, reserved_quantity\n    FROM public.stock_reservations\n    WHERE sales_order_id = p_so_id\n      AND product_id = p_product_id\n      AND status = 'active'\n    ORDER BY reserved_at, id\n    FOR UPDATE\n  LOOP\n    EXIT WHEN v_remaining_qty <= 0;\n    v_release_qty := LEAST(v_remaining_qty, v_reservation.reserved_quantity);\n\n    IF v_release_qty = v_reservation.reserved_quantity THEN\n      UPDATE public.stock_reservations\n      SET status = 'released',\n          is_released = true,\n          released_at = now(),\n          released_by = COALESCE(p_released_by, auth.uid()),\n          release_reason = 'Canonical partial reservation release'\n      WHERE id = v_reservation.id;\n    ELSE\n      UPDATE public.stock_reservations\n      SET reserved_quantity = reserved_quantity - v_release_qty\n      WHERE id = v_reservation.id;\n    END IF;\n\n    v_remaining_qty := v_remaining_qty - v_release_qty;\n  END LOOP;\n\n  IF v_remaining_qty > 0 THEN\n    RAISE EXCEPTION 'Reservation release exceeds active reserved quantity by %',\n      v_remaining_qty;\n  END IF;\n\n  RETURN true;\nEND;\n$$","--\n-- Name: fn_release_reservation_by_so_id(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_release_reservation_by_so_id\\"(\\"p_so_id\\" \\"uuid\\", \\"p_released_by\\" \\"uuid\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(\n    ARRAY['admin', 'accounts', 'manager', 'warehouse']\n  ) THEN\n    RAISE EXCEPTION 'Permission denied for reservation release';\n  END IF;\n\n  UPDATE public.stock_reservations\n  SET status = 'released',\n      is_released = true,\n      released_at = now(),\n      released_by = COALESCE(p_released_by, auth.uid()),\n      release_reason = COALESCE(\n        release_reason,\n        'Canonical Sales Order reservation release'\n      )\n  WHERE sales_order_id = p_so_id\n    AND status = 'active';\n\n  RETURN true;\nEND;\n$$","--\n-- Name: fn_release_stock_reservations(\\"uuid\\", \\"text\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_release_stock_reservations\\"(\\"p_so_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\", \\"p_user_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_reservation RECORD;\n  v_so_number   text;\n  v_actor       uuid := COALESCE(p_user_id, auth.uid());\nBEGIN\n  SELECT so_number INTO v_so_number FROM sales_orders WHERE id = p_so_id;\n\n  -- Emit an inventory_transactions release row per active reservation so\n  -- Reports / drill-downs can trace the release event to a source doc.\n  FOR v_reservation IN\n    SELECT * FROM stock_reservations\n    WHERE sales_order_id = p_so_id\n      AND status = 'active'\n  LOOP\n    INSERT INTO inventory_transactions (\n      product_id,\n      batch_id,\n      transaction_type,\n      quantity,\n      transaction_date,\n      reference_number,\n      notes,\n      created_by\n    ) VALUES (\n      v_reservation.product_id,\n      v_reservation.batch_id,\n      'release_reservation',\n      v_reservation.reserved_quantity,\n      CURRENT_DATE,\n      v_so_number,\n      'Reservation released: ' || p_reason,\n      v_actor\n    );\n  END LOOP;\n\n  UPDATE stock_reservations\n  SET status         = 'released',\n      released_at    = now(),\n      released_by    = v_actor,\n      release_reason = p_reason\n  WHERE sales_order_id = p_so_id\n    AND status = 'active';\n\n  RETURN true;\nEND;\n$$","--\n-- Name: fn_reserve_stock_for_so_v2(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_reserve_stock_for_so_v2\\"(\\"p_so_id\\" \\"uuid\\") RETURNS TABLE(\\"success\\" boolean, \\"message\\" \\"text\\", \\"shortage_items\\" \\"jsonb\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  RETURN QUERY\n  SELECT * FROM public.approve_sales_order_product_reservation_v2(p_so_id, auth.uid());\nEND;\n$$","--\n-- Name: fn_restore_reservation_on_dc_delete(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_restore_reservation_on_dc_delete\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_so_status text;\nBEGIN\nIF OLD.sales_order_id IS NOT NULL THEN\nSELECT status::text INTO v_so_status FROM sales_orders WHERE id = OLD.sales_order_id;\nIF v_so_status NOT IN ('delivered','closed','cancelled','rejected') THEN\nPERFORM fn_reserve_stock_for_so_v2(OLD.sales_order_id);\nEND IF;\nEND IF;\nRETURN OLD;\nEND;\n$$","--\n-- Name: fn_safe_autolink_dc_to_so(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_safe_autolink_dc_to_so\\"() RETURNS TABLE(\\"dc_id\\" \\"uuid\\", \\"linked_so_id\\" \\"uuid\\", \\"action\\" \\"text\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\ndc_rec          RECORD;\ncandidate_so_id uuid;\nmatch_count     int;\nv_role          text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts','manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot auto-link challans', v_role;\nEND IF;\n\nFOR dc_rec IN\nSELECT dc.id, dc.customer_id FROM delivery_challans dc\nWHERE dc.sales_order_id IS NULL\nAND (dc.review_status IS NULL OR dc.review_status != 'needs_review')\nLOOP\nSELECT COUNT(DISTINCT so.id) INTO match_count\nFROM sales_orders so\nWHERE so.customer_id = dc_rec.customer_id AND so.is_archived = false\nAND so.status NOT IN ('draft','cancelled','rejected')\nAND NOT EXISTS (\nSELECT 1 FROM delivery_challan_items dci\nWHERE dci.challan_id = dc_rec.id\nAND NOT EXISTS (\nSELECT 1 FROM sales_order_items soi\nWHERE soi.sales_order_id = so.id AND soi.product_id = dci.product_id\nAND soi.quantity >= dci.quantity\n)\n)\nAND EXISTS (SELECT 1 FROM delivery_challan_items dci2 WHERE dci2.challan_id = dc_rec.id);\n\nIF match_count = 1 THEN\nSELECT so.id INTO candidate_so_id\nFROM sales_orders so\nWHERE so.customer_id = dc_rec.customer_id AND so.is_archived = false\nAND so.status NOT IN ('draft','cancelled','rejected')\nAND NOT EXISTS (\nSELECT 1 FROM delivery_challan_items dci\nWHERE dci.challan_id = dc_rec.id\nAND NOT EXISTS (\nSELECT 1 FROM sales_order_items soi\nWHERE soi.sales_order_id = so.id AND soi.product_id = dci.product_id\nAND soi.quantity >= dci.quantity\n)\n)\nAND EXISTS (SELECT 1 FROM delivery_challan_items dci2 WHERE dci2.challan_id = dc_rec.id)\nLIMIT 1;\n\nUPDATE delivery_challans SET sales_order_id = candidate_so_id, updated_at = now()\nWHERE id = dc_rec.id;\ndc_id := dc_rec.id; linked_so_id := candidate_so_id; action := 'linked';\nRETURN NEXT;\nELSE\nUPDATE delivery_challans SET review_status = 'needs_review', updated_at = now()\nWHERE id = dc_rec.id AND sales_order_id IS NULL;\ndc_id := dc_rec.id; linked_so_id := NULL; action := 'needs_review';\nRETURN NEXT;\nEND IF;\nEND LOOP;\nEND;\n$$","--\n-- Name: fn_settled_import_pph22(integer, integer, \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_settled_import_pph22\\"(\\"p_year\\" integer, \\"p_month\\" integer, \\"p_tax_type\\" \\"text\\") RETURNS numeric\n    LANGUAGE \\"sql\\" STABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT CASE WHEN p_tax_type IN ('PPh22', 'PPh_Unifikasi') THEN COALESCE((\n    SELECT SUM(\n      CASE WHEN fe.expense_category = 'pib_import' THEN COALESCE(fe.pib_pph_amount, 0)\n           ELSE COALESCE(fe.amount, 0)          -- pph_import: whole amount is the tax\n      END)\n      FROM finance_expenses fe\n     WHERE fe.expense_category IN ('pib_import', 'pph_import')\n       AND EXTRACT(YEAR  FROM fe.expense_date)::int = p_year\n       AND EXTRACT(MONTH FROM fe.expense_date)::int = p_month\n       AND (COALESCE(fe.amount,0) - COALESCE(fe.paid_amount, 0)) <= 0.01   -- fully paid\n       AND EXISTS (                                                        -- bank-reconciled\n         SELECT 1 FROM bank_statement_lines bsl\n          WHERE bsl.matched_expense_id = fe.id\n            AND bsl.reconciliation_status IN ('matched', 'recorded'))\n  ), 0) ELSE 0 END;\n$$","--\n-- Name: fn_sync_import_requirements_on_so_edit(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_sync_import_requirements_on_so_edit\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  -- A draft/pending-approval SO is being edited by the application.  Its\n  -- replacement lines are inserted immediately after this DELETE, so do not\n  -- mutate procurement state in the middle of that replacement transaction.\n  IF EXISTS (\n    SELECT 1\n    FROM public.sales_orders so\n    WHERE so.id = OLD.sales_order_id\n      AND so.status::text IN ('draft', 'pending_approval')\n  ) THEN\n    RETURN OLD;\n  END IF;\n\n  -- For a genuine line removal, cancel only when no line for that product\n  -- remains on the SO.  This also handles duplicate lines safely.\n  UPDATE public.import_requirements ir\n  SET status = 'cancelled',\n      notes = COALESCE(ir.notes || ' | ', '') ||\n        'Product removed from SO ' || to_char(now(), 'YYYY-MM-DD')\n  WHERE ir.sales_order_id = OLD.sales_order_id\n    AND ir.product_id = OLD.product_id\n    AND ir.status::text NOT IN ('cancelled', 'received')\n    AND NOT EXISTS (\n      SELECT 1\n      FROM public.sales_order_items soi\n      WHERE soi.sales_order_id = OLD.sales_order_id\n        AND soi.product_id = OLD.product_id\n    );\n\n  RETURN OLD;\nEND;\n$$","--\n-- Name: fn_tax_payments_paid(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_tax_payments_paid\\"(\\"p_period_id\\" \\"uuid\\") RETURNS numeric\n    LANGUAGE \\"sql\\" STABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT COALESCE((\n    SELECT SUM(amount) FROM tax_payments\n     WHERE tax_period_id = p_period_id\n       AND status IN ('posted', 'reconciled')\n  ), 0);\n$$","--\n-- Name: fn_tax_period_payment_status(\\"text\\", numeric, numeric, \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"fn_tax_period_payment_status\\"(\\"p_status\\" \\"text\\", \\"p_total\\" numeric, \\"p_paid\\" numeric, \\"p_due\\" \\"date\\") RETURNS \\"text\\"\n    LANGUAGE \\"sql\\" STABLE\n    AS $$\nSELECT CASE WHEN coalesce(p_paid,0)>coalesce(p_total,0)+.01 THEN 'overpaid' WHEN coalesce(p_total,0)>.01 AND coalesce(p_paid,0)>=coalesce(p_total,0)-.01 THEN 'paid' WHEN coalesce(p_paid,0)>.01 THEN 'partial' ELSE 'open' END;\n$$","--\n-- Name: generate_bank_transaction_hash(\\"uuid\\", \\"date\\", numeric, numeric, \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_bank_transaction_hash\\"(\\"p_bank_account_id\\" \\"uuid\\", \\"p_transaction_date\\" \\"date\\", \\"p_debit_amount\\" numeric, \\"p_credit_amount\\" numeric, \\"p_description\\" \\"text\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" IMMUTABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_normalized_desc TEXT;\nv_hash_input TEXT;\nBEGIN\n-- Normalize description: lowercase, remove extra spaces, trim to 100 chars\nv_normalized_desc := LOWER(TRIM(REGEXP_REPLACE(COALESCE(p_description, ''), '\\\\s+', ' ', 'g')));\nv_normalized_desc := LEFT(v_normalized_desc, 100);\n\n-- Create hash input string\nv_hash_input := p_bank_account_id::TEXT || '|' ||\np_transaction_date::TEXT || '|' ||\nCOALESCE(p_debit_amount, 0)::TEXT || '|' ||\nCOALESCE(p_credit_amount, 0)::TEXT || '|' ||\nv_normalized_desc;\n\n-- Return MD5 hash\nRETURN md5(v_hash_input);\nEND;\n$$","--\n-- Name: generate_bank_transaction_hash(\\"uuid\\", \\"date\\", numeric, numeric, \\"text\\", numeric, \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_bank_transaction_hash\\"(\\"p_bank_account_id\\" \\"uuid\\", \\"p_transaction_date\\" \\"date\\", \\"p_debit_amount\\" numeric, \\"p_credit_amount\\" numeric, \\"p_description\\" \\"text\\", \\"p_running_balance\\" numeric DEFAULT 0, \\"p_upload_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" IMMUTABLE\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\nv_normalized_desc TEXT;\nv_hash_input TEXT;\nBEGIN\nv_normalized_desc := LOWER(TRIM(REGEXP_REPLACE(COALESCE(p_description, ''), '\\\\s+', ' ', 'g')));\nv_normalized_desc := LEFT(v_normalized_desc, 100);\n\nv_hash_input := p_bank_account_id::TEXT || '|' ||\np_transaction_date::TEXT || '|' ||\nCOALESCE(p_debit_amount, 0)::TEXT || '|' ||\nCOALESCE(p_credit_amount, 0)::TEXT || '|' ||\nv_normalized_desc || '|' ||\nCOALESCE(p_running_balance, 0)::TEXT;\n\n-- If balance is 0 (not provided) and upload_id is given, use it to distinguish entries\nIF COALESCE(p_running_balance, 0) = 0 AND p_upload_id IS NOT NULL THEN\nv_hash_input := v_hash_input || '|' || p_upload_id::TEXT;\nEND IF;\n\nRETURN md5(v_hash_input);\nEND;\n$$","--\n-- Name: generate_credit_note_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_credit_note_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_year text;\nv_number text;\nBEGIN\nv_year := TO_CHAR(CURRENT_DATE, 'YY');\nv_number := LPAD(nextval('credit_note_number_seq')::text, 4, '0');\nRETURN 'CN-' || v_year || '-' || v_number;\nEND;\n$$","--\n-- Name: generate_fund_transfer_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_fund_transfer_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $_$\nDECLARE\nv_year   TEXT;\nv_month  TEXT;\nv_prefix TEXT;\nv_max    INT;\nv_number TEXT;\nBEGIN\nv_year   := TO_CHAR(CURRENT_DATE, 'YY');\nv_month  := TO_CHAR(CURRENT_DATE, 'MM');\nv_prefix := 'FT' || v_year || v_month;\n\nPERFORM pg_advisory_xact_lock(\nhashtext('ft_number_' || v_year || v_month)\n);\n\nSELECT COALESCE(\nMAX(\nCAST(\nSUBSTRING(transfer_number FROM '^FT\\\\d{4}-(\\\\d+)$')\nAS INTEGER\n)\n),\n0\n) + 1\nINTO v_max\nFROM fund_transfers\nWHERE transfer_number LIKE v_prefix || '-%';\n\nv_number := v_prefix || '-' || LPAD(v_max::TEXT, 4, '0');\nRETURN v_number;\nEND;\n$_$","--\n-- Name: FUNCTION \\"generate_fund_transfer_number\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"generate_fund_transfer_number\\"() IS 'Generates sequential fund transfer number in format FT[YY][MM]-[NNNN]'","--\n-- Name: generate_grn_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_grn_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_year TEXT;\nv_month TEXT;\nv_count INTEGER;\nv_number TEXT;\nBEGIN\nv_year := TO_CHAR(CURRENT_DATE, 'YY');\nv_month := TO_CHAR(CURRENT_DATE, 'MM');\n\nSELECT COUNT(*) + 1 INTO v_count\nFROM goods_receipt_notes\nWHERE grn_number LIKE 'GRN-' || v_year || v_month || '%';\n\nv_number := 'GRN-' || v_year || v_month || '-' || LPAD(v_count::TEXT, 4, '0');\n\nRETURN v_number;\nEND;\n$$","--\n-- Name: generate_import_cost_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_import_cost_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_year TEXT;\nv_month TEXT;\nv_count INTEGER;\nv_number TEXT;\nBEGIN\nv_year := TO_CHAR(CURRENT_DATE, 'YY');\nv_month := TO_CHAR(CURRENT_DATE, 'MM');\n\nSELECT COUNT(*) + 1 INTO v_count\nFROM import_cost_headers\nWHERE cost_sheet_number LIKE 'IMP-' || v_year || v_month || '%';\n\nv_number := 'IMP-' || v_year || v_month || '-' || LPAD(v_count::TEXT, 4, '0');\n\nRETURN v_number;\nEND;\n$$","--\n-- Name: generate_inquiry_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_inquiry_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_current_year text;\nv_last_number integer;\nv_new_number text;\nBEGIN\n-- Get last 2 digits of current year (e.g., \\"25\\" for 2025)\nv_current_year := TO_CHAR(NOW(), 'YY');\n\n-- Get the highest number for this year\n-- Looks for pattern like INQ-25-0001\nSELECT COALESCE(MAX(CAST(SUBSTRING(inquiry_number, 8, 4) AS INTEGER)), 0)\nINTO v_last_number\nFROM crm_inquiries\nWHERE inquiry_number LIKE 'INQ-' || v_current_year || '-%';\n\n-- Increment and pad to 4 digits\nv_new_number := 'INQ-' || v_current_year || '-' ||\nLPAD((v_last_number + 1)::text, 4, '0');\n\nRETURN v_new_number;\nEND;\n$$","--\n-- Name: generate_journal_entry_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_journal_entry_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN next_journal_entry_number();\nEND;\n$$","--\n-- Name: generate_loan_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_loan_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_prefix text;\nv_count integer;\nBEGIN\nv_prefix := 'LN' || TO_CHAR(CURRENT_DATE, 'YYMM');\nSELECT COUNT(*) + 1 INTO v_count\nFROM loans\nWHERE loan_number LIKE v_prefix || '%';\nRETURN v_prefix || '-' || LPAD(v_count::text, 4, '0');\nEND;\n$$","--\n-- Name: generate_loan_transaction_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_loan_transaction_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_prefix text;\nv_count integer;\nBEGIN\nv_prefix := 'LP' || TO_CHAR(CURRENT_DATE, 'YYMM');\nSELECT COUNT(*) + 1 INTO v_count\nFROM loan_transactions\nWHERE transaction_number LIKE v_prefix || '%';\nRETURN v_prefix || '-' || LPAD(v_count::text, 4, '0');\nEND;\n$$","--\n-- Name: generate_petty_cash_transaction_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_petty_cash_transaction_number\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_year_month TEXT;\nv_next_num INTEGER;\nv_transaction_number TEXT;\nBEGIN\n-- Only generate if transaction_number is not already set\nIF NEW.transaction_number IS NULL OR NEW.transaction_number = '' THEN\n-- Get year and month from transaction date\nv_year_month := TO_CHAR(NEW.transaction_date, 'YYYYMM');\n\n-- Get the next number for this month\nSELECT COALESCE(MAX(CAST(SUBSTRING(transaction_number FROM 'PC-\\\\d{6}-(\\\\d+)') AS INTEGER)), 0) + 1\nINTO v_next_num\nFROM petty_cash_transactions\nWHERE transaction_number LIKE 'PC-' || v_year_month || '-%';\n\n-- If no number found, start at 1\nIF v_next_num IS NULL THEN\nv_next_num := 1;\nEND IF;\n\n-- Generate the transaction number\nv_transaction_number := 'PC-' || v_year_month || '-' || LPAD(v_next_num::TEXT, 3, '0');\n\nNEW.transaction_number := v_transaction_number;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"generate_petty_cash_transaction_number\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"generate_petty_cash_transaction_number\\"() IS 'Auto-generates transaction number in format PC-YYYYMM-001 for petty cash transactions'","--\n-- Name: generate_po_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_po_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_year TEXT;\nv_month TEXT;\nv_count INTEGER;\nv_number TEXT;\nBEGIN\nv_year := TO_CHAR(CURRENT_DATE, 'YY');\nv_month := TO_CHAR(CURRENT_DATE, 'MM');\n\nSELECT COUNT(*) + 1 INTO v_count\nFROM purchase_orders\nWHERE po_number LIKE 'PO-' || v_year || v_month || '%';\n\nv_number := 'PO-' || v_year || v_month || '-' || LPAD(v_count::TEXT, 4, '0');\n\nRETURN v_number;\nEND;\n$$","--\n-- Name: generate_pr_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_pr_number\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_year text;\nv_seq  int;\nBEGIN\nIF NEW.pr_number IS NULL OR NEW.pr_number = '' THEN\nv_year := to_char(now(), 'YYYY');\nSELECT COUNT(*) + 1 INTO v_seq\nFROM price_requests\nWHERE pr_number LIKE 'PR-' || v_year || '-%';\nNEW.pr_number := 'PR-' || v_year || '-' || lpad(v_seq::text, 4, '0');\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: generate_price_request_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_price_request_number\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_year  text;\nv_seq   integer;\nv_num   text;\nBEGIN\nv_year := to_char(now(), 'YYYY');\nSELECT COALESCE(MAX(\nNULLIF(regexp_replace(price_request_number, '^PR-' || v_year || '-', ''), price_request_number)::integer\n), 0) + 1\nINTO v_seq\nFROM price_requests\nWHERE price_request_number LIKE 'PR-' || v_year || '-%';\n\nv_num := 'PR-' || v_year || '-' || lpad(v_seq::text, 4, '0');\nNEW.price_request_number := v_num;\nRETURN NEW;\nEND;\n$$","--\n-- Name: generate_rejection_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_rejection_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $_$\nDECLARE\nnext_num integer;\nyear_suffix text;\nBEGIN\nyear_suffix := TO_CHAR(CURRENT_DATE, 'YY');\n\nSELECT COALESCE(MAX(\nCASE \nWHEN rejection_number ~ '^REJ-[0-9]+-[0-9]+$' \nTHEN CAST(split_part(rejection_number, '-', 2) AS integer)\nELSE 0\nEND\n), 0) + 1 INTO next_num\nFROM stock_rejections\nWHERE rejection_number LIKE 'REJ-%';\n\nRETURN 'REJ-' || LPAD(next_num::text, 5, '0') || '-' || year_suffix;\nEND;\n$_$","--\n-- Name: generate_return_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_return_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $_$\nDECLARE\nnext_num integer;\nyear_suffix text;\nBEGIN\nyear_suffix := TO_CHAR(CURRENT_DATE, 'YY');\n\nSELECT COALESCE(MAX(\nCASE \nWHEN return_number ~ '^RET-[0-9]+-[0-9]+$' \nTHEN CAST(split_part(return_number, '-', 2) AS integer)\nELSE 0\nEND\n), 0) + 1 INTO next_num\nFROM material_returns\nWHERE return_number LIKE 'RET-%';\n\nRETURN 'RET-' || LPAD(next_num::text, 5, '0') || '-' || year_suffix;\nEND;\n$_$","--\n-- Name: generate_so_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_so_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nnext_number integer;\nyear_part text;\nnew_so_number text;\nBEGIN\nyear_part := to_char(CURRENT_DATE, 'YYYY');\n\nSELECT COALESCE(MAX(\nCAST(\nsubstring(so_number from 'SO-' || year_part || '-(.*)') AS integer\n)\n), 0) + 1\nINTO next_number\nFROM sales_orders\nWHERE so_number LIKE 'SO-' || year_part || '-%';\n\nnew_so_number := 'SO-' || year_part || '-' || LPAD(next_number::text, 4, '0');\n\nRETURN new_so_number;\nEND;\n$$","--\n-- Name: generate_tax_notifications(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_tax_notifications\\"() RETURNS integer\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_user record;\n  v_row record;\n  v_count int := 0;\n  v_today date := CURRENT_DATE;\n  v_upcoming_cutoff date := CURRENT_DATE + 7;\nBEGIN\n  FOR v_user IN\n    SELECT id FROM user_profiles\n    WHERE is_active = true AND role IN ('admin','manager','accounts')\n  LOOP\n    -- Overdue tax payments\n    FOR v_row IN\n      SELECT tax_period_id, tax_type, payment_due_date, outstanding_amount\n      FROM vw_outstanding_tax\n      WHERE payment_due_date < v_today AND outstanding_amount > 0\n    LOOP\n      -- Insert directly: we're SECURITY DEFINER so RLS is bypassed. This\n      -- also side-steps upsert_notification's \\"only admins may notify other\n      -- users\\" rule which would fire when a manager triggers this RPC.\n      INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)\n      SELECT v_user.id, 'tax_overdue',\n             v_row.tax_type || ' payment overdue',\n             format('Rp %s outstanding, due %s',\n               to_char(v_row.outstanding_amount, 'FM999G999G999G999D00'),\n               to_char(v_row.payment_due_date, 'DD Mon YYYY')),\n             v_row.tax_period_id, 'tax_period', false\n      WHERE NOT EXISTS (\n        SELECT 1 FROM notifications\n        WHERE user_id = v_user.id\n          AND type = 'tax_overdue'\n          AND reference_id = v_row.tax_period_id\n          AND is_read = false\n      );\n      v_count := v_count + 1;\n    END LOOP;\n\n    -- Upcoming tax payments (next 7 days)\n    FOR v_row IN\n      SELECT tax_period_id, tax_type, payment_due_date, outstanding_amount\n      FROM vw_outstanding_tax\n      WHERE payment_due_date BETWEEN v_today AND v_upcoming_cutoff\n        AND outstanding_amount > 0\n    LOOP\n      INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)\n      SELECT v_user.id, 'tax_due_soon',\n             v_row.tax_type || ' payment due',\n             format('Rp %s due on %s',\n               to_char(v_row.outstanding_amount, 'FM999G999G999G999D00'),\n               to_char(v_row.payment_due_date, 'DD Mon YYYY')),\n             v_row.tax_period_id, 'tax_period', false\n      WHERE NOT EXISTS (\n        SELECT 1 FROM notifications\n        WHERE user_id = v_user.id\n          AND type = 'tax_due_soon'\n          AND reference_id = v_row.tax_period_id\n          AND is_read = false\n      );\n      v_count := v_count + 1;\n    END LOOP;\n\n    -- Missing Faktur Pajak on open PPN periods\n    FOR v_row IN\n      SELECT id AS tax_period_id, fiscal_year, period_month, missing_faktur_count\n      FROM vw_tax_period_status\n      WHERE tax_type = 'PPN' AND status <> 'closed' AND missing_faktur_count > 0\n    LOOP\n      INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)\n      SELECT v_user.id, 'faktur_missing',\n             'Waiting for Faktur',\n             format('%s sales invoice(s) in %s-%s need a Faktur Pajak number',\n               v_row.missing_faktur_count,\n               v_row.fiscal_year,\n               lpad(v_row.period_month::text, 2, '0')),\n             v_row.tax_period_id, 'tax_period', false\n      WHERE NOT EXISTS (\n        SELECT 1 FROM notifications\n        WHERE user_id = v_user.id\n          AND type = 'faktur_missing'\n          AND reference_id = v_row.tax_period_id\n          AND is_read = false\n      );\n      v_count := v_count + 1;\n    END LOOP;\n  END LOOP;\n\n  RETURN v_count;\nEND $$","--\n-- Name: generate_voucher_number(\\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"generate_voucher_number\\"(\\"p_prefix\\" \\"text\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $_$\nDECLARE\nv_year TEXT;\nv_month TEXT;\nv_max_num INTEGER;\nv_number TEXT;\nv_like_prefix TEXT;\nv_lock_id BIGINT;\nBEGIN\nv_year := TO_CHAR(CURRENT_DATE, 'YY');\nv_month := TO_CHAR(CURRENT_DATE, 'MM');\nv_like_prefix := p_prefix || v_year || v_month;\n\nv_lock_id := hashtext('voucher_' || v_like_prefix);\nPERFORM pg_advisory_xact_lock(v_lock_id);\n\nIF p_prefix = 'RV' THEN\nSELECT COALESCE(MAX(\nCAST(NULLIF(SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2), '') AS INTEGER)\n), 0) + 1\nINTO v_max_num\nFROM receipt_vouchers\nWHERE voucher_number LIKE v_like_prefix || '-%'\nAND SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2) ~ '^\\\\d+$';\nELSIF p_prefix = 'PV' THEN\nSELECT COALESCE(MAX(\nCAST(NULLIF(SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2), '') AS INTEGER)\n), 0) + 1\nINTO v_max_num\nFROM payment_vouchers\nWHERE voucher_number LIKE v_like_prefix || '-%'\nAND SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2) ~ '^\\\\d+$';\nELSIF p_prefix = 'PC' THEN\nSELECT COALESCE(MAX(\nCAST(NULLIF(SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2), '') AS INTEGER)\n), 0) + 1\nINTO v_max_num\nFROM petty_cash_vouchers\nWHERE voucher_number LIKE v_like_prefix || '-%'\nAND SUBSTRING(voucher_number FROM LENGTH(v_like_prefix) + 2) ~ '^\\\\d+$';\nELSE\nv_max_num := 1;\nEND IF;\n\nv_number := v_like_prefix || '-' || LPAD(v_max_num::TEXT, 4, '0');\n\nRETURN v_number;\nEND;\n$_$","--\n-- Name: get_accounts_dashboard_data(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_accounts_dashboard_data\\"(\\"p_user_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN jsonb_build_object(\n'bank_balance', (\nSELECT COALESCE(SUM(current_balance), 0)\nFROM bank_accounts\nWHERE is_active = true\n),\n'pending_receivables', (\nSELECT COALESCE(SUM(si.total_amount - COALESCE(\n(SELECT SUM(ipa.allocated_amount) \nFROM invoice_payment_allocations ipa \nWHERE ipa.invoice_id = si.id), 0\n)), 0)\nFROM sales_invoices si\nWHERE si.payment_status IN ('pending', 'partial')\n),\n'pending_payables', (\nSELECT COALESCE(SUM(balance_amount), 0)\nFROM purchase_invoices\nWHERE balance_amount > 0\n),\n'unreconciled_transactions', (\nSELECT COUNT(*)\nFROM bank_statement_lines\nWHERE reconciliation_status = 'unmatched'\n),\n'overdue_invoices_count', (\nSELECT COUNT(*)\nFROM sales_invoices\nWHERE payment_status IN ('pending', 'partial')\nAND due_date < CURRENT_DATE\n),\n'overdue_invoices_amount', (\nSELECT COALESCE(SUM(si.total_amount - COALESCE(\n(SELECT SUM(ipa.allocated_amount) \nFROM invoice_payment_allocations ipa \nWHERE ipa.invoice_id = si.id), 0\n)), 0)\nFROM sales_invoices si\nWHERE si.payment_status IN ('pending', 'partial')\nAND si.due_date < CURRENT_DATE\n),\n'cash_position', COALESCE(get_petty_cash_balance(), 0),\n'staff_advances_pending', 0,\n'pending_approvals', 0\n);\nEND;\n$$","--\n-- Name: get_admin_dashboard_data(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_admin_dashboard_data\\"(\\"p_user_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_result jsonb;\nv_sales_snapshot jsonb;\nv_finance_snapshot jsonb;\nv_stock_snapshot jsonb;\nv_alerts_summary jsonb;\nv_pending_approvals jsonb;\nv_system_health jsonb;\nv_crm_snapshot jsonb;\nBEGIN\n-- Sales snapshot\nSELECT jsonb_build_object(\n'today_revenue', COALESCE(SUM(total_amount), 0),\n'today_count', COUNT(*),\n'month_revenue', (\nSELECT COALESCE(SUM(total_amount), 0)\nFROM sales_invoices\nWHERE DATE_TRUNC('month', invoice_date) = DATE_TRUNC('month', CURRENT_DATE)\n),\n'pending_orders', (\nSELECT COUNT(*) FROM sales_orders WHERE status = 'pending_approval'\n)\n) INTO v_sales_snapshot\nFROM sales_invoices\nWHERE DATE(invoice_date) = CURRENT_DATE;\n\n-- Finance snapshot\nSELECT jsonb_build_object(\n'bank_balance', (\nSELECT COALESCE(SUM(current_balance), 0)\nFROM bank_accounts\nWHERE is_active = true\n),\n'receivables', (\nSELECT COALESCE(SUM(si.total_amount - COALESCE(\n(SELECT SUM(ipa.allocated_amount) \nFROM invoice_payment_allocations ipa \nWHERE ipa.sales_invoice_id = si.id), 0\n)), 0)\nFROM sales_invoices si\nWHERE si.payment_status IN ('pending', 'partial')\n),\n'payables', (\nSELECT COALESCE(SUM(total_amount), 0)\nFROM purchase_invoices\nWHERE payment_status IN ('pending', 'partial')\n),\n'overdue_invoices', (\nSELECT COUNT(*)\nFROM sales_invoices\nWHERE payment_status IN ('pending', 'partial')\nAND due_date < CURRENT_DATE\n)\n) INTO v_finance_snapshot;\n\n-- Stock snapshot\nSELECT jsonb_build_object(\n'total_products', (\nSELECT COUNT(*) FROM products WHERE is_active = true\n),\n'low_stock', (\nSELECT COUNT(*)\nFROM products\nWHERE is_active = true\nAND min_stock_level > 0\nAND current_stock < min_stock_level\n),\n'near_expiry', (\nSELECT COUNT(*)\nFROM batches\nWHERE is_active = true\nAND current_stock > 0\nAND expiry_date BETWEEN CURRENT_DATE AND (CURRENT_DATE + INTERVAL '30 days')\n),\n'inventory_value', (\nSELECT COALESCE(SUM(b.current_stock * b.unit_price), 0)\nFROM batches b\nWHERE b.is_active = true AND b.current_stock > 0\n)\n) INTO v_stock_snapshot;\n\n-- Alerts summary\nSELECT jsonb_build_object(\n'critical', (\nSELECT COUNT(*)\nFROM products\nWHERE is_active = true\nAND current_stock <= 0\n) + (\nSELECT COUNT(*)\nFROM sales_invoices\nWHERE payment_status IN ('pending', 'partial')\nAND due_date < CURRENT_DATE - INTERVAL '30 days'\n),\n'warning', (\nSELECT COUNT(*)\nFROM products\nWHERE is_active = true\nAND min_stock_level > 0\nAND current_stock < min_stock_level\n),\n'info', (\nSELECT COUNT(*)\nFROM crm_activities\nWHERE is_completed = false\nAND follow_up_date = CURRENT_DATE\n)\n) INTO v_alerts_summary;\n\n-- Pending approvals\nSELECT jsonb_build_object(\n'sales_orders', (\nSELECT COUNT(*) FROM sales_orders WHERE status = 'pending_approval'\n),\n'delivery_challans', (\nSELECT COUNT(*) FROM delivery_challans WHERE approval_status = 'pending_approval'\n),\n'credit_notes', (\nSELECT COUNT(*) FROM credit_notes WHERE approval_status = 'pending'\n),\n'material_returns', (\nSELECT COUNT(*) FROM material_returns WHERE approval_status = 'pending'\n)\n) INTO v_pending_approvals;\n\n-- System health\nSELECT jsonb_build_object(\n'active_users', (\nSELECT COUNT(*) FROM user_profiles WHERE is_active = true\n),\n'active_customers', (\nSELECT COUNT(*) FROM customers WHERE is_active = true\n),\n'active_products', (\nSELECT COUNT(*) FROM products WHERE is_active = true\n),\n'unread_notifications', (\nSELECT COUNT(*)\nFROM notifications\nWHERE user_id = p_user_id\nAND is_read = false\n)\n) INTO v_system_health;\n\n-- CRM snapshot\nSELECT jsonb_build_object(\n'upcoming_reminders', (\nSELECT COUNT(*)\nFROM crm_reminders\nWHERE is_completed = false\nAND due_date BETWEEN CURRENT_DATE AND (CURRENT_DATE + INTERVAL '7 days')\n),\n'todays_appointments', (\nSELECT COUNT(*)\nFROM crm_reminders\nWHERE is_completed = false\nAND DATE(due_date) = CURRENT_DATE\nAND reminder_type = 'follow_up'\n),\n'active_inquiries', (\nSELECT COUNT(*)\nFROM crm_inquiries\nWHERE status NOT IN ('closed', 'lost', 'converted')\n),\n'hot_leads', (\nSELECT COUNT(*)\nFROM crm_inquiries\nWHERE temperature = 'Hot'\nAND status NOT IN ('closed', 'lost', 'converted')\n)\n) INTO v_crm_snapshot;\n\n-- Build result JSON\nv_result := jsonb_build_object(\n'sales_snapshot', v_sales_snapshot,\n'finance_snapshot', v_finance_snapshot,\n'stock_snapshot', v_stock_snapshot,\n'alerts_summary', v_alerts_summary,\n'pending_approvals', v_pending_approvals,\n'system_health', v_system_health,\n'crm_snapshot', v_crm_snapshot\n);\n\nRETURN v_result;\nEND;\n$$","--\n-- Name: get_asset_register(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_asset_register\\"() RETURNS TABLE(\\"id\\" \\"uuid\\", \\"supplier_id\\" \\"uuid\\", \\"supplier_name\\" \\"text\\", \\"invoice_number\\" \\"text\\", \\"purchase_date\\" \\"date\\", \\"asset_account\\" \\"text\\", \\"asset_account_code\\" \\"text\\", \\"cost\\" numeric, \\"description\\" \\"text\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  RETURN QUERY\n  SELECT\n    fe.id,\n    fe.supplier_id,\n    s.company_name::TEXT        AS supplier_name,\n    fe.invoice_number::TEXT,\n    fe.expense_date             AS purchase_date,\n    coa.name::TEXT              AS asset_account,\n    coa.code::TEXT              AS asset_account_code,\n    fe.amount                   AS cost,\n    fe.description::TEXT\n  FROM public.finance_expenses fe\n  LEFT JOIN public.suppliers s          ON s.id   = fe.supplier_id\n  LEFT JOIN public.chart_of_accounts coa ON coa.id = fe.fixed_asset_account_id\n  WHERE fe.expense_category = 'fixed_asset'\n  ORDER BY fe.expense_date DESC;\nEND;\n$$","--\n-- Name: get_balance_sheet(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_balance_sheet\\"(\\"p_as_of_date\\" \\"date\\") RETURNS TABLE(\\"code\\" character varying, \\"name\\" character varying, \\"name_id\\" character varying, \\"account_type\\" character varying, \\"account_group\\" character varying, \\"normal_balance\\" character varying, \\"total_debit\\" numeric, \\"total_credit\\" numeric, \\"balance\\" numeric)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  RETURN QUERY\n  SELECT *\n  FROM public.get_balance_sheet(p_as_of_date, 1::numeric);\nEND;\n$$","--\n-- Name: get_balance_sheet(\\"date\\", numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_balance_sheet\\"(\\"p_as_of_date\\" \\"date\\", \\"p_usd_rate\\" numeric DEFAULT 1) RETURNS TABLE(\\"code\\" character varying, \\"name\\" character varying, \\"name_id\\" character varying, \\"account_type\\" character varying, \\"account_group\\" character varying, \\"normal_balance\\" character varying, \\"total_debit\\" numeric, \\"total_credit\\" numeric, \\"balance\\" numeric)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_net_income numeric;\n  v_has_3300 boolean;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  -- Journal-native P&L sign convention:\n  --   revenue = credit - debit\n  --   expense = debit - credit\n  --   net income = revenue - expense\n  SELECT COALESCE(SUM(\n    CASE\n      WHEN coa.account_type = 'revenue' THEN jel.credit - jel.debit\n      WHEN coa.account_type = 'expense' THEN jel.credit - jel.debit\n      ELSE 0\n    END\n  ), 0)\n  INTO v_net_income\n  FROM public.journal_entry_lines jel\n  JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true\n    AND COALESCE(je.is_reversed, false) = false\n    AND je.entry_date <= p_as_of_date\n    AND coa.is_header = false;\n\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.journal_entry_lines jel\n    JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n    WHERE coa.code = '3300'\n      AND je.is_posted = true\n      AND COALESCE(je.is_reversed, false) = false\n      AND je.entry_date <= p_as_of_date\n  )\n  INTO v_has_3300;\n\n  RETURN QUERY\n  WITH active_lines AS (\n    SELECT jel.account_id, jel.debit, jel.credit\n    FROM public.journal_entry_lines jel\n    JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n    WHERE je.is_posted = true\n      AND COALESCE(je.is_reversed, false) = false\n      AND je.entry_date <= p_as_of_date\n  )\n  SELECT\n    coa.code,\n    coa.name,\n    coa.name_id,\n    coa.account_type,\n    coa.account_group,\n    COALESCE(\n      coa.normal_balance,\n      CASE WHEN coa.account_type IN ('asset', 'expense') THEN 'debit' ELSE 'credit' END\n    ),\n    COALESCE(SUM(al.debit), 0)::numeric,\n    COALESCE(SUM(al.credit), 0)::numeric,\n    (COALESCE(SUM(al.debit), 0) - COALESCE(SUM(al.credit), 0))::numeric\n  FROM public.chart_of_accounts coa\n  LEFT JOIN active_lines al ON al.account_id = coa.id\n  WHERE coa.is_header = false\n    AND coa.is_active = true\n    AND coa.account_type IN ('asset', 'liability', 'equity', 'contra')\n  GROUP BY coa.id, coa.code, coa.name, coa.name_id, coa.account_type,\n    coa.account_group, coa.normal_balance\n  HAVING COALESCE(SUM(al.debit), 0) <> 0\n      OR COALESCE(SUM(al.credit), 0) <> 0\n\n  UNION ALL\n\n  SELECT\n    '3300'::varchar,\n    'Current Year Earnings'::varchar,\n    'Laba/Rugi Tahun Berjalan'::varchar,\n    'equity'::varchar,\n    'Equity'::varchar,\n    'credit'::varchar,\n    CASE WHEN v_net_income < 0 THEN ABS(v_net_income) ELSE 0 END,\n    CASE WHEN v_net_income > 0 THEN v_net_income ELSE 0 END,\n    (-v_net_income)::numeric\n  WHERE NOT v_has_3300\n    AND ABS(v_net_income) > 0.005\n  ORDER BY 1;\nEND;\n$$","--\n-- Name: FUNCTION \\"get_balance_sheet\\"(\\"p_as_of_date\\" \\"date\\", \\"p_usd_rate\\" numeric); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_balance_sheet\\"(\\"p_as_of_date\\" \\"date\\", \\"p_usd_rate\\" numeric) IS 'Journal-native Balance Sheet. Synthetic 3300 Current Year Earnings is revenue minus expenses; p_usd_rate is retained for API compatibility.'","--\n-- Name: get_batch_transaction_history(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_batch_transaction_history\\"(\\"p_batch_id\\" \\"uuid\\") RETURNS TABLE(\\"transaction_date\\" timestamp with time zone, \\"transaction_type\\" \\"text\\", \\"quantity_change\\" numeric, \\"stock_before\\" numeric, \\"stock_after\\" numeric, \\"notes\\" \\"text\\", \\"created_by_name\\" \\"text\\")\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT\nit.transaction_date,\nit.transaction_type,\nit.quantity_change,\nit.stock_before,\nit.stock_after,\nit.notes,\nup.full_name\nFROM inventory_transactions it\nLEFT JOIN user_profiles up ON up.id = it.created_by\nWHERE it.batch_id = p_batch_id\nORDER BY it.transaction_date DESC, it.created_at DESC;\nEND;\n$$","--\n-- Name: get_cogs_for_period(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_cogs_for_period\\"(\\"p_start\\" \\"date\\", \\"p_end\\" \\"date\\") RETURNS numeric\n    LANGUAGE \\"sql\\" STABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\nSELECT COALESCE(\nSUM(\nsii.quantity *\nCASE\nWHEN COALESCE(b.landed_cost_per_unit, 0) > 0\nTHEN b.landed_cost_per_unit\nWHEN COALESCE(b.import_price_usd, 0) > 0\nTHEN b.import_price_usd * COALESCE(b.exchange_rate_usd_to_idr, 16000)\nELSE COALESCE(b.import_price, 0)\nEND\n), 0)\nFROM sales_invoice_items sii\nJOIN sales_invoices si ON si.id = sii.invoice_id\nLEFT JOIN batches b ON b.id = sii.batch_id\nWHERE si.invoice_date BETWEEN p_start AND p_end\nAND si.is_draft = false;\n$$","--\n-- Name: get_company_profile_reference_counts(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_company_profile_reference_counts\\"() RETURNS TABLE(\\"profile_id\\" \\"uuid\\", \\"ref_count\\" bigint)\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH refs AS (\n    SELECT NULLIF(company_snapshot->>'id','')::uuid AS pid FROM sales_invoices     WHERE company_snapshot ? 'id'\n    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM delivery_challans  WHERE company_snapshot ? 'id'\n    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM credit_notes      WHERE company_snapshot ? 'id'\n    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM material_returns  WHERE company_snapshot ? 'id'\n    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM stock_rejections  WHERE company_snapshot ? 'id'\n    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM purchase_orders   WHERE company_snapshot ? 'id'\n    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM payment_vouchers  WHERE company_snapshot ? 'id'\n    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM receipt_vouchers  WHERE company_snapshot ? 'id'\n    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM purchase_invoices WHERE company_snapshot ? 'id'\n    UNION ALL SELECT NULLIF(company_snapshot->>'id','')::uuid FROM sales_orders      WHERE company_snapshot ? 'id'\n  )\n  SELECT pid AS profile_id, count(*)::bigint AS ref_count\n  FROM refs\n  WHERE pid IS NOT NULL\n  GROUP BY pid;\n$$","--\n-- Name: get_control_account_reconciliation(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_control_account_reconciliation\\"(\\"p_as_of_date\\" \\"date\\" DEFAULT CURRENT_DATE) RETURNS TABLE(\\"control_code\\" \\"text\\", \\"control_name\\" \\"text\\", \\"gl_balance\\" numeric, \\"subledger_balance\\" numeric, \\"difference\\" numeric, \\"status\\" \\"text\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE v_ar_gl numeric; v_ap_gl numeric; v_ar_sub numeric; v_ap_sub numeric;\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;\n\n  SELECT COALESCE(SUM(jel.debit - jel.credit), 0) INTO v_ar_gl\n  FROM public.journal_entry_lines jel JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE coa.code = '1120' AND je.is_posted = true AND COALESCE(je.is_reversed, false) = false AND je.entry_date <= p_as_of_date;\n\n  SELECT COALESCE(SUM(jel.credit - jel.debit), 0) INTO v_ap_gl\n  FROM public.journal_entry_lines jel JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE coa.code = '2110' AND je.is_posted = true AND COALESCE(je.is_reversed, false) = false AND je.entry_date <= p_as_of_date;\n\n  SELECT COALESCE(SUM(balance_amount), 0) INTO v_ar_sub FROM public.get_customer_ar_open_items(p_as_of_date);\n\n  WITH pi AS (\n    SELECT p.id, p.total_amount\n    FROM public.purchase_invoices p JOIN public.journal_entries je ON je.id = p.journal_entry_id\n    WHERE je.is_posted = true AND COALESCE(je.is_reversed, false) = false AND p.invoice_date <= p_as_of_date\n  ), pi_paid AS (\n    SELECT va.purchase_invoice_id, SUM(va.allocated_amount) amount\n    FROM public.voucher_allocations va JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n    JOIN public.journal_entries je ON je.id = pv.journal_entry_id\n    WHERE va.voucher_type = 'payment' AND je.is_posted = true AND COALESCE(je.is_reversed, false) = false AND pv.voucher_date <= p_as_of_date\n    GROUP BY va.purchase_invoice_id\n  ), expense_bills AS (\n    SELECT fe.id, fe.amount, fe.paid_amount\n    FROM public.finance_expenses fe\n    JOIN public.journal_entries je ON je.source_module = 'expenses' AND je.reference_id = fe.id\n    WHERE fe.payment_method IS NULL AND fe.approval_status = 'approved' AND fe.expense_date <= p_as_of_date\n      AND je.is_posted = true AND COALESCE(je.is_reversed, false) = false\n  )\n  SELECT COALESCE((SELECT SUM(pi.total_amount - COALESCE(pi_paid.amount, 0)) FROM pi LEFT JOIN pi_paid ON pi_paid.purchase_invoice_id = pi.id), 0)\n       + COALESCE((SELECT SUM(amount - COALESCE(paid_amount, 0)) FROM expense_bills), 0)\n  INTO v_ap_sub;\n\n  RETURN QUERY VALUES\n    ('1120'::text, 'Accounts Receivable'::text, v_ar_gl, v_ar_sub, (v_ar_gl - v_ar_sub), CASE WHEN ABS(v_ar_gl - v_ar_sub) <= 0.01 THEN 'reconciled' ELSE 'difference' END),\n    ('2110'::text, 'Accounts Payable'::text, v_ap_gl, v_ap_sub, (v_ap_gl - v_ap_sub), CASE WHEN ABS(v_ap_gl - v_ap_sub) <= 0.01 THEN 'reconciled' ELSE 'difference' END);\nEND;\n$$","--\n-- Name: get_current_company_profile(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_current_company_profile\\"() RETURNS \\"jsonb\\"\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT to_jsonb(cp)\n  FROM company_profiles cp\n  WHERE cp.effective_from <= CURRENT_DATE\n  ORDER BY cp.effective_from DESC\n  LIMIT 1;\n$$","--\n-- Name: get_current_financial_year(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_current_financial_year\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_fy_start_date DATE;\nv_fy_start_month INT;\nv_fy_start_day INT;\nv_current_date DATE;\nv_current_year INT;\nv_this_year_fy_start DATE;\nv_fy_year INT;\nBEGIN\n-- Get financial year start date from settings\nSELECT financial_year_start INTO v_fy_start_date\nFROM app_settings\nLIMIT 1;\n\n-- If not set, default to current year Jan 1\nIF v_fy_start_date IS NULL THEN\nv_fy_start_date := MAKE_DATE(EXTRACT(YEAR FROM CURRENT_DATE)::INT, 1, 1);\nEND IF;\n\n-- Extract month and day from FY start\nv_fy_start_month := EXTRACT(MONTH FROM v_fy_start_date)::INT;\nv_fy_start_day := EXTRACT(DAY FROM v_fy_start_date)::INT;\n\n-- Get current date and year\nv_current_date := CURRENT_DATE;\nv_current_year := EXTRACT(YEAR FROM v_current_date)::INT;\n\n-- Calculate this year's FY start date\nv_this_year_fy_start := MAKE_DATE(v_current_year, v_fy_start_month, v_fy_start_day);\n\n-- Determine which FY we're in\nIF v_current_date >= v_this_year_fy_start THEN\n-- We're in the current year's FY\nv_fy_year := v_current_year;\nELSE\n-- We're still in the previous year's FY\nv_fy_year := v_current_year - 1;\nEND IF;\n\n-- Return 2-digit year code (e.g., '26' for 2026)\nRETURN RIGHT(v_fy_year::TEXT, 2);\nEND;\n$$","--\n-- Name: FUNCTION \\"get_current_financial_year\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_current_financial_year\\"() IS 'Automatically calculates current financial year based on app_settings.financial_year_start. Returns 2-digit year code (e.g., \\"26\\" for 2026). No manual updates needed.'","--\n-- Name: get_customer_ar_open_items(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_customer_ar_open_items\\"(\\"p_as_of_date\\" \\"date\\" DEFAULT CURRENT_DATE) RETURNS TABLE(\\"id\\" \\"uuid\\", \\"customer_id\\" \\"uuid\\", \\"customer_name\\" \\"text\\", \\"customer_email\\" \\"text\\", \\"customer_phone\\" \\"text\\", \\"invoice_number\\" \\"text\\", \\"invoice_date\\" \\"date\\", \\"due_date\\" \\"date\\", \\"total_amount\\" numeric, \\"paid_amount\\" numeric, \\"credit_note_amount\\" numeric, \\"balance_amount\\" numeric, \\"days_overdue\\" integer)\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH invoices AS (\n    SELECT si.id, si.customer_id, si.invoice_number, si.invoice_date, si.due_date, si.total_amount,\n      c.company_name, c.email, c.phone\n    FROM public.sales_invoices si\n    JOIN public.customers c ON c.id = si.customer_id\n    JOIN public.journal_entries je ON je.id = si.journal_entry_id\n    WHERE je.is_posted = true AND COALESCE(je.is_reversed, false) = false\n      AND si.invoice_date <= p_as_of_date\n  ), paid AS (\n    SELECT va.sales_invoice_id, COALESCE(SUM(va.allocated_amount), 0) AS paid_amount\n    FROM public.voucher_allocations va\n    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id\n    JOIN public.journal_entries je ON je.id = rv.journal_entry_id\n    WHERE va.voucher_type = 'receipt' AND je.is_posted = true\n      AND COALESCE(je.is_reversed, false) = false AND rv.voucher_date <= p_as_of_date\n    GROUP BY va.sales_invoice_id\n  ), direct_credit AS (\n    SELECT cn.original_invoice_id AS invoice_id, COALESCE(SUM(cn.total_amount), 0) AS amount\n    FROM public.credit_notes cn\n    JOIN public.journal_entries je ON je.id = cn.journal_entry_id\n    WHERE cn.status = 'approved' AND cn.original_invoice_id IS NOT NULL\n      AND cn.credit_note_date <= p_as_of_date AND je.is_posted = true\n      AND COALESCE(je.is_reversed, false) = false\n    GROUP BY cn.original_invoice_id\n  ), unallocated_credit AS (\n    SELECT cn.customer_id, COALESCE(SUM(cn.total_amount), 0) AS amount\n    FROM public.credit_notes cn\n    JOIN public.journal_entries je ON je.id = cn.journal_entry_id\n    WHERE cn.status = 'approved' AND cn.original_invoice_id IS NULL\n      AND cn.credit_note_date <= p_as_of_date AND je.is_posted = true\n      AND COALESCE(je.is_reversed, false) = false\n    GROUP BY cn.customer_id\n  ), base AS (\n    SELECT i.*, COALESCE(p.paid_amount, 0) AS paid_amount,\n      LEAST(GREATEST(i.total_amount - COALESCE(p.paid_amount, 0), 0), COALESCE(dc.amount, 0)) AS direct_credit_amount,\n      GREATEST(i.total_amount - COALESCE(p.paid_amount, 0) - COALESCE(dc.amount, 0), 0) AS open_after_direct,\n      COALESCE(uc.amount, 0) AS unallocated_credit_amount\n    FROM invoices i\n    LEFT JOIN paid p ON p.sales_invoice_id = i.id\n    LEFT JOIN direct_credit dc ON dc.invoice_id = i.id\n    LEFT JOIN unallocated_credit uc ON uc.customer_id = i.customer_id\n  ), apportioned AS (\n    SELECT base.*,\n      COALESCE(SUM(open_after_direct) OVER (\n        PARTITION BY customer_id ORDER BY invoice_date, id\n        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING\n      ), 0) AS prior_open\n    FROM base\n  )\n  SELECT id, customer_id, company_name, email, phone, invoice_number, invoice_date, due_date,\n    total_amount, paid_amount,\n    (direct_credit_amount + LEAST(open_after_direct, GREATEST(unallocated_credit_amount - prior_open, 0)))::numeric,\n    GREATEST(open_after_direct - LEAST(open_after_direct, GREATEST(unallocated_credit_amount - prior_open, 0)), 0)::numeric,\n    GREATEST((p_as_of_date - due_date), 0)::integer\n  FROM apportioned\n  WHERE GREATEST(open_after_direct - LEAST(open_after_direct, GREATEST(unallocated_credit_amount - prior_open, 0)), 0) > 0.005\n  ORDER BY due_date NULLS LAST, invoice_date, invoice_number;\n$$","--\n-- Name: get_customer_outstanding_summary(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_customer_outstanding_summary\\"() RETURNS TABLE(\\"id\\" \\"uuid\\", \\"name\\" \\"text\\", \\"email\\" \\"text\\", \\"total_outstanding\\" numeric, \\"age_0_30\\" numeric, \\"age_31_60\\" numeric, \\"age_61_90\\" numeric, \\"age_90_plus\\" numeric, \\"oldest_invoice_date\\" \\"date\\")\n    LANGUAGE \\"plpgsql\\" STABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT\nc.id,\nc.company_name::TEXT AS name,\nc.email::TEXT AS email,\nCOALESCE(SUM(si.balance_amount), 0) AS total_outstanding,\nCOALESCE(SUM(CASE WHEN CURRENT_DATE - si.invoice_date <= 30 THEN si.balance_amount ELSE 0 END), 0) AS age_0_30,\nCOALESCE(SUM(CASE WHEN CURRENT_DATE - si.invoice_date BETWEEN 31 AND 60 THEN si.balance_amount ELSE 0 END), 0) AS age_31_60,\nCOALESCE(SUM(CASE WHEN CURRENT_DATE - si.invoice_date BETWEEN 61 AND 90 THEN si.balance_amount ELSE 0 END), 0) AS age_61_90,\nCOALESCE(SUM(CASE WHEN CURRENT_DATE - si.invoice_date > 90 THEN si.balance_amount ELSE 0 END), 0) AS age_90_plus,\nMIN(si.invoice_date) AS oldest_invoice_date\nFROM customers c\nINNER JOIN sales_invoices si ON si.customer_id = c.id\nWHERE si.payment_status IN ('pending', 'partial')\nAND si.balance_amount > 0\nGROUP BY c.id, c.company_name, c.email\nHAVING COALESCE(SUM(si.balance_amount), 0) > 0\nORDER BY COALESCE(SUM(si.balance_amount), 0) DESC;\nEND;\n$$","--\n-- Name: get_customer_sales_report(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_customer_sales_report\\"(\\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS TABLE(\\"customer_id\\" \\"uuid\\", \\"customer_name\\" \\"text\\", \\"total_orders\\" bigint, \\"total_sales\\" numeric, \\"avg_order_value\\" numeric, \\"last_order_date\\" \\"date\\", \\"total_qty\\" numeric, \\"total_cogs\\" numeric, \\"total_profit\\" numeric, \\"profit_pct\\" numeric, \\"costed_lines\\" bigint, \\"total_lines\\" bigint, \\"cost_coverage\\" numeric)\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH lines AS (\n    SELECT si.id, si.customer_id, c.company_name, si.invoice_date, sii.quantity, sii.unit_price,\n      b.landed_cost_per_unit, (b.landed_cost_per_unit > 0) AS is_costed\n    FROM public.sales_invoices si\n    JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id\n    JOIN public.customers c ON c.id = si.customer_id\n    LEFT JOIN public.batches b ON b.id = sii.batch_id\n    WHERE si.invoice_date >= p_start_date AND si.invoice_date <= p_end_date\n      AND COALESCE(si.is_draft, false) = false\n  ), grouped AS (\n    SELECT customer_id, company_name, COUNT(DISTINCT id) AS total_orders,\n      SUM(quantity * unit_price) AS total_sales, SUM(quantity) AS total_qty,\n      SUM(quantity * unit_price) FILTER (WHERE is_costed) AS costed_revenue,\n      COALESCE(SUM(quantity * landed_cost_per_unit) FILTER (WHERE is_costed), 0) AS total_cogs,\n      MAX(invoice_date) AS last_order_date, COUNT(*) FILTER (WHERE is_costed) AS costed_lines,\n      COUNT(*) AS total_lines\n    FROM lines GROUP BY customer_id, company_name\n  )\n  SELECT customer_id, company_name, total_orders, ROUND(total_sales, 2),\n    ROUND(total_sales / NULLIF(total_orders, 0), 2), last_order_date, total_qty,\n    ROUND(total_cogs, 2), ROUND(COALESCE(costed_revenue, 0) - total_cogs, 2),\n    CASE WHEN COALESCE(costed_revenue, 0) = 0 THEN NULL\n      ELSE ROUND((costed_revenue - total_cogs) / costed_revenue * 100, 2) END,\n    costed_lines, total_lines, ROUND(costed_lines::numeric / NULLIF(total_lines, 0) * 100, 2)\n  FROM grouped ORDER BY total_sales DESC;\n$$","--\n-- Name: get_dc_item_details(\\"uuid\\"[]); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_dc_item_details\\"(\\"p_dc_item_ids\\" \\"uuid\\"[]) RETURNS TABLE(\\"dc_item_id\\" \\"uuid\\", \\"challan_id\\" \\"uuid\\", \\"challan_number\\" \\"text\\", \\"product_id\\" \\"uuid\\", \\"product_name\\" \\"text\\", \\"batch_id\\" \\"uuid\\", \\"batch_number\\" \\"text\\", \\"unit\\" \\"text\\", \\"pack_size\\" numeric, \\"pack_type\\" \\"text\\", \\"number_of_packs\\" integer, \\"original_quantity\\" numeric, \\"remaining_quantity\\" numeric, \\"status\\" \\"text\\")\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT \ndis.dc_item_id,\ndis.challan_id,\ndis.challan_number,\ndis.product_id,\ndis.product_name,\ndis.batch_id,\ndis.batch_number,\ndis.unit,\ndis.pack_size,\ndis.pack_type,\ndis.number_of_packs,\ndis.original_quantity,\ndis.remaining_quantity,\ndis.status\nFROM dc_item_invoice_status dis\nWHERE dis.dc_item_id = ANY(p_dc_item_ids);\nEND;\n$$","--\n-- Name: FUNCTION \\"get_dc_item_details\\"(\\"p_dc_item_ids\\" \\"uuid\\"[]); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_dc_item_details\\"(\\"p_dc_item_ids\\" \\"uuid\\"[]) IS 'Returns detailed information for specific DC items. Used when loading an existing invoice for editing.'","--\n-- Name: get_expense_account_id(\\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_expense_account_id\\"(\\"p_category\\" \\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT ec.coa_account_id\n  FROM public.expense_categories ec\n  JOIN public.chart_of_accounts coa ON coa.id=ec.coa_account_id\n  WHERE ec.category_key=p_category\n    AND ec.is_active\n    AND ec.is_posting_category\n    AND coa.is_active\n    AND NOT coa.is_header\n  LIMIT 1\n$$","--\n-- Name: FUNCTION \\"get_expense_account_id\\"(\\"p_category\\" \\"text\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_expense_account_id\\"(\\"p_category\\" \\"text\\") IS 'Returns only the active master-configured posting account. Unknown categories have no fallback.'","--\n-- Name: get_expense_export_accounts(\\"uuid\\"[]); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_expense_export_accounts\\"(\\"p_expense_ids\\" \\"uuid\\"[]) RETURNS TABLE(\\"expense_id\\" \\"uuid\\", \\"coa_code\\" \\"text\\", \\"coa_name\\" \\"text\\")\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH requested_expenses AS (\n    SELECT id, expense_category, approval_status\n    FROM public.finance_expenses\n    WHERE id = ANY(p_expense_ids)\n  ),\n  posted_accounts AS (\n    SELECT DISTINCT ON (expense.id)\n      expense.id AS expense_id,\n      coa.code AS coa_code,\n      coa.name AS coa_name\n    FROM requested_expenses expense\n    JOIN public.journal_entries journal\n      ON journal.source_module IN ('expense', 'expenses')\n     AND (\n       journal.reference_id = expense.id\n       OR journal.reference_number = 'EXP-' || expense.id::text\n     )\n     AND journal.is_posted = true\n    JOIN public.journal_entry_lines line\n      ON line.journal_entry_id = journal.id\n     AND line.debit > 0\n    JOIN public.chart_of_accounts coa\n      ON coa.id = line.account_id\n    ORDER BY expense.id, journal.posted_at DESC NULLS LAST, journal.created_at DESC, line.line_number\n  ),\n  fallback_accounts AS (\n    SELECT\n      expense.id AS expense_id,\n      coa.code AS coa_code,\n      coa.name AS coa_name\n    FROM requested_expenses expense\n    JOIN public.chart_of_accounts coa\n      ON coa.id = public.get_expense_account_id(expense.expense_category)\n    WHERE expense.approval_status IS DISTINCT FROM 'approved'\n  )\n  SELECT\n    expense.id AS expense_id,\n    COALESCE(posted.coa_code, fallback.coa_code) AS coa_code,\n    COALESCE(posted.coa_name, fallback.coa_name) AS coa_name\n  FROM requested_expenses expense\n  LEFT JOIN posted_accounts posted ON posted.expense_id = expense.id\n  LEFT JOIN fallback_accounts fallback ON fallback.expense_id = expense.id;\n$$","--\n-- Name: FUNCTION \\"get_expense_export_accounts\\"(\\"p_expense_ids\\" \\"uuid\\"[]); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_expense_export_accounts\\"(\\"p_expense_ids\\" \\"uuid\\"[]) IS 'Expense export COA: posted journal debit account first; canonical category default before approval.'","--\n-- Name: get_expense_pph_period_date(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_expense_pph_period_date\\"(\\"p_expense_id\\" \\"uuid\\") RETURNS \\"date\\"\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\n  SELECT COALESCE((SELECT max(payment_date) FROM (\n    SELECT pv.voucher_date payment_date FROM public.voucher_allocations va\n    JOIN public.payment_vouchers pv ON pv.id=va.payment_voucher_id\n    WHERE va.finance_expense_id=fe.id AND COALESCE(va.payment_kind,'supplier')='supplier' AND COALESCE(pv.is_posted,false)\n    UNION ALL\n    SELECT b.transaction_date FROM public.bank_statement_allocations a\n    JOIN public.bank_statement_lines b ON b.id=a.bank_statement_line_id\n    WHERE a.document_type='expense' AND a.document_id=fe.id AND a.payment_kind='supplier'\n    UNION ALL\n    SELECT b.transaction_date FROM public.bank_statement_lines b\n    WHERE b.matched_expense_id=fe.id AND COALESCE(b.payment_kind,'supplier')='supplier'\n      AND NOT EXISTS(SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id=b.id)\n  ) payments),fe.due_date,fe.expense_date)\n  FROM public.finance_expenses fe WHERE fe.id=p_expense_id;\n$$","--\n-- Name: get_expense_vs_profit_report(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_expense_vs_profit_report\\"(\\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS TABLE(\\"total_sales\\" numeric, \\"total_cogs\\" numeric, \\"gross_profit\\" numeric, \\"outbound_delivery\\" numeric, \\"contribution_profit\\" numeric, \\"operating_expenses\\" numeric, \\"operational_profit\\" numeric, \\"profit_pct\\" numeric, \\"costed_lines\\" bigint, \\"total_lines\\" bigint)\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH lines AS (\n    SELECT sii.quantity, sii.unit_price, b.landed_cost_per_unit,\n      (b.landed_cost_per_unit > 0) AS is_costed\n    FROM public.sales_invoices si\n    JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id\n    LEFT JOIN public.batches b ON b.id = sii.batch_id\n    WHERE si.invoice_date >= p_start_date AND si.invoice_date <= p_end_date\n      AND COALESCE(si.is_draft, false) = false\n  ), sales AS (\n    SELECT COALESCE(SUM(quantity * unit_price), 0) AS total_sales,\n      COALESCE(SUM(quantity * unit_price) FILTER (WHERE is_costed), 0) AS costed_revenue,\n      COALESCE(SUM(quantity * landed_cost_per_unit) FILTER (WHERE is_costed), 0) AS total_cogs,\n      COUNT(*) FILTER (WHERE is_costed) AS costed_lines, COUNT(*) AS total_lines FROM lines\n  ), expenses AS (\n    SELECT COALESCE(SUM(amount) FILTER (WHERE expense_category IN ('delivery_sales', 'loading_sales')), 0) AS outbound_delivery,\n      COALESCE(SUM(amount) FILTER (WHERE expense_category NOT IN ('delivery_sales', 'loading_sales')), 0) AS operating_expenses\n    FROM public.finance_expenses WHERE expense_date >= p_start_date AND expense_date <= p_end_date\n  )\n  SELECT ROUND(s.total_sales, 2), ROUND(s.total_cogs, 2), ROUND(s.costed_revenue - s.total_cogs, 2),\n    ROUND(e.outbound_delivery, 2), ROUND(s.costed_revenue - s.total_cogs - e.outbound_delivery, 2),\n    ROUND(e.operating_expenses, 2), ROUND(s.costed_revenue - s.total_cogs - e.outbound_delivery - e.operating_expenses, 2),\n    CASE WHEN s.costed_revenue = 0 THEN NULL ELSE ROUND((s.costed_revenue - s.total_cogs - e.outbound_delivery - e.operating_expenses) / s.costed_revenue * 100, 2) END,\n    s.costed_lines, s.total_lines\n  FROM sales s CROSS JOIN expenses e;\n$$","--\n-- Name: get_finance_dashboard_summary(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_finance_dashboard_summary\\"(\\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS TABLE(\\"revenue\\" numeric, \\"expenses\\" numeric, \\"net_income\\" numeric, \\"accounts_receivable\\" numeric)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE v_revenue numeric; v_expenses numeric; v_ar numeric;\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;\n\n  SELECT\n    COALESCE(SUM(CASE WHEN coa.account_type = 'revenue' THEN jel.credit - jel.debit ELSE 0 END), 0),\n    COALESCE(SUM(CASE WHEN coa.account_type = 'expense' THEN jel.debit - jel.credit ELSE 0 END), 0)\n  INTO v_revenue, v_expenses\n  FROM public.journal_entry_lines jel\n  JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true AND COALESCE(je.is_reversed, false) = false\n    AND je.entry_date BETWEEN p_start_date AND p_end_date;\n\n  SELECT COALESCE(SUM(balance_amount), 0) INTO v_ar FROM public.get_customer_ar_open_items(p_end_date);\n  RETURN QUERY SELECT v_revenue, v_expenses, v_revenue - v_expenses, v_ar;\nEND;\n$$","--\n-- Name: bank_accounts; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"bank_accounts\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"account_name\\" \\"text\\" NOT NULL,\n    \\"bank_name\\" \\"text\\" NOT NULL,\n    \\"account_number\\" \\"text\\" NOT NULL,\n    \\"account_type\\" \\"text\\" NOT NULL,\n    \\"currency\\" \\"text\\" DEFAULT 'IDR'::\\"text\\" NOT NULL,\n    \\"opening_balance\\" numeric DEFAULT 0 NOT NULL,\n    \\"current_balance\\" numeric DEFAULT 0 NOT NULL,\n    \\"is_active\\" boolean DEFAULT true,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"alias\\" \\"text\\",\n    \\"coa_id\\" \\"uuid\\",\n    \\"opening_balance_date\\" \\"date\\" DEFAULT '2025-01-01'::\\"date\\" NOT NULL,\n    CONSTRAINT \\"bank_accounts_account_type_check\\" CHECK ((\\"account_type\\" = ANY (ARRAY['savings'::\\"text\\", 'current'::\\"text\\", 'credit_card'::\\"text\\", 'other'::\\"text\\"])))\n)","--\n-- Name: TABLE \\"bank_accounts\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON TABLE \\"public\\".\\"bank_accounts\\" IS 'Bank accounts for managing company funds and reconciliation'","--\n-- Name: COLUMN \\"bank_accounts\\".\\"opening_balance\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"bank_accounts\\".\\"opening_balance\\" IS 'Opening balance for current financial year'","--\n-- Name: COLUMN \\"bank_accounts\\".\\"alias\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"bank_accounts\\".\\"alias\\" IS 'Short display name for UI (e.g., \\"BCA IDR\\", \\"Mandiri USD\\")'","--\n-- Name: COLUMN \\"bank_accounts\\".\\"coa_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"bank_accounts\\".\\"coa_id\\" IS 'Links to the corresponding Chart of Accounts entry for this bank account'","--\n-- Name: COLUMN \\"bank_accounts\\".\\"opening_balance_date\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"bank_accounts\\".\\"opening_balance_date\\" IS 'The date on which the opening_balance amount is effective'","--\n-- Name: finance_expenses; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"finance_expenses\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"expense_category\\" \\"text\\" NOT NULL,\n    \\"amount\\" numeric(15,2) NOT NULL,\n    \\"expense_date\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"description\\" \\"text\\",\n    \\"batch_id\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"document_urls\\" \\"text\\"[],\n    \\"import_container_id\\" \\"uuid\\",\n    \\"delivery_challan_id\\" \\"uuid\\",\n    \\"expense_type\\" character varying(20) DEFAULT 'general'::character varying,\n    \\"voucher_number\\" \\"text\\",\n    \\"payment_method\\" character varying(50) DEFAULT 'cash'::character varying,\n    \\"bank_account_id\\" \\"uuid\\",\n    \\"payment_reference\\" character varying(100),\n    \\"paid_by\\" \\"text\\" DEFAULT 'bank'::\\"text\\",\n    \\"approval_status\\" \\"text\\" DEFAULT 'pending_approval'::\\"text\\" NOT NULL,\n    \\"approved_by\\" \\"uuid\\",\n    \\"approved_at\\" timestamp with time zone,\n    \\"rejection_reason\\" \\"text\\",\n    \\"pib_bm_amount\\" numeric(18,2),\n    \\"pib_ppn_amount\\" numeric(18,2),\n    \\"pib_pph_amount\\" numeric(18,2),\n    \\"ppn_amount\\" numeric(18,2) DEFAULT 0,\n    \\"pph_amount\\" numeric(18,2) DEFAULT 0,\n    \\"pph_code_id\\" \\"uuid\\",\n    \\"stamp_duty_amount\\" numeric(18,2) DEFAULT 0,\n    \\"fixed_asset_account_id\\" \\"uuid\\",\n    \\"supplier_id\\" \\"uuid\\",\n    \\"invoice_number\\" character varying(100),\n    \\"due_date\\" \\"date\\",\n    \\"paid_amount\\" numeric(18,2) DEFAULT 0 NOT NULL,\n    \\"broker_items\\" \\"jsonb\\",\n    \\"pph_paid_amount\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"tax_period_id\\" \\"uuid\\",\n    \\"staff_id\\" \\"uuid\\",\n    \\"bank_charges_amount\\" numeric(18,2) DEFAULT 0 NOT NULL,\n    \\"ppn_calc_mode\\" \\"text\\" DEFAULT 'standard'::\\"text\\" NOT NULL,\n    \\"dpp_amount\\" numeric(18,2),\n    \\"ppn_rate\\" numeric(6,3) DEFAULT 11 NOT NULL,\n    \\"ppn_manual_override\\" boolean DEFAULT false NOT NULL,\n    \\"currency_code\\" \\"text\\",\n    \\"transaction_currency\\" \\"text\\",\n    \\"functional_currency\\" \\"text\\",\n    \\"exchange_rate\\" numeric(18,6),\n    \\"bank_account_currency\\" \\"text\\",\n    \\"payment_currency\\" \\"text\\",\n    \\"settlement_amount\\" numeric GENERATED ALWAYS AS (\\"public\\".\\"calculate_expense_settlement_amount\\"(\\"expense_category\\", \\"amount\\", \\"ppn_amount\\", \\"pph_amount\\", \\"stamp_duty_amount\\", \\"bank_charges_amount\\", \\"broker_items\\")) STORED,\n    \\"pph_tax_period_id\\" \\"uuid\\",\n    \\"include_in_landed_cost\\" boolean,\n    CONSTRAINT \\"chk_pib_breakdown_sum\\" CHECK (((\\"expense_category\\" <> 'pib_import'::\\"text\\") OR ((\\"pib_bm_amount\\" IS NOT NULL) AND (\\"pib_ppn_amount\\" IS NOT NULL) AND (\\"pib_pph_amount\\" IS NOT NULL) AND (\\"abs\\"((((COALESCE(\\"pib_bm_amount\\", (0)::numeric) + COALESCE(\\"pib_ppn_amount\\", (0)::numeric)) + COALESCE(\\"pib_pph_amount\\", (0)::numeric)) - \\"amount\\")) < 1.00)))),\n    CONSTRAINT \\"finance_expenses_approval_status_check\\" CHECK ((\\"approval_status\\" = ANY (ARRAY['pending_approval'::\\"text\\", 'approved'::\\"text\\", 'rejected'::\\"text\\", 'cancelled'::\\"text\\"]))),\n    CONSTRAINT \\"finance_expenses_bank_charges_amount_check\\" CHECK ((\\"bank_charges_amount\\" >= (0)::numeric)),\n    CONSTRAINT \\"finance_expenses_currency_metadata_check\\" CHECK ((((\\"transaction_currency\\" IS NULL) OR (\\"transaction_currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"functional_currency\\" IS NULL) OR (\\"functional_currency\\" = 'IDR'::\\"text\\")) AND ((\\"currency_code\\" IS NULL) OR (\\"currency_code\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"payment_currency\\" IS NULL) OR (\\"payment_currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"bank_account_currency\\" IS NULL) OR (\\"bank_account_currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"exchange_rate\\" IS NULL) OR (\\"exchange_rate\\" > (0)::numeric)))),\n    CONSTRAINT \\"finance_expenses_expense_type_check\\" CHECK (((\\"expense_type\\")::\\"text\\" = ANY ((ARRAY['import'::character varying, 'sales'::character varying, 'general'::character varying])::\\"text\\"[]))),\n    CONSTRAINT \\"finance_expenses_paid_by_check\\" CHECK ((\\"paid_by\\" = ANY (ARRAY['bank'::\\"text\\", 'cash'::\\"text\\"]))),\n    CONSTRAINT \\"finance_expenses_payment_method_check\\" CHECK (((\\"payment_method\\")::\\"text\\" = ANY ((ARRAY['cash'::character varying, 'bank_transfer'::character varying, 'check'::character varying, 'giro'::character varying, 'other'::character varying])::\\"text\\"[]))),\n    CONSTRAINT \\"finance_expenses_ppn_calc_mode_check\\" CHECK ((\\"ppn_calc_mode\\" = ANY (ARRAY['standard'::\\"text\\", 'dpp_nilai_lain'::\\"text\\", 'manual'::\\"text\\"])))\n)","--\n-- Name: COLUMN \\"finance_expenses\\".\\"expense_category\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"expense_category\\" IS 'Canonical category_key from expense_categories. Validated as an active posting leaf with an active non-header COA; no hard-coded category allow-list.'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"document_urls\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"document_urls\\" IS 'Array of URLs to expense supporting documents (invoices, receipts, bills, etc.) stored in expense-documents bucket'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"import_container_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"import_container_id\\" IS 'Link to import container for import-side costs (capitalized to inventory)'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"delivery_challan_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"delivery_challan_id\\" IS 'Link to delivery challan for sales-side delivery costs (P&L expense)'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"expense_type\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"expense_type\\" IS 'Distinguishes import costs (inventory) from sales costs (P&L)'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"voucher_number\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"voucher_number\\" IS 'Expense voucher number for bank reconciliation matching (e.g., PV-001, EXP-2025-001)'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"payment_method\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"payment_method\\" IS 'How the expense was paid: cash, bank_transfer, check, giro, other'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"bank_account_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"bank_account_id\\" IS 'Bank account used if payment_method is bank_transfer/check/giro'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"payment_reference\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"payment_reference\\" IS 'Check number, transfer reference, or giro number'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"pib_bm_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"pib_bm_amount\\" IS 'PIB Import only: Import Duty (BM) portion. Goes to landed cost / inventory.'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"pib_ppn_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"pib_ppn_amount\\" IS 'PIB Import only: PPN Import portion. Posted to PPN Masukan (1150). NOT in landed cost.'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"pib_pph_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"pib_pph_amount\\" IS 'PIB Import only: PPh 22 Import portion. Posted to PPh 22 Prepaid (1155). NOT in landed cost.'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"supplier_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"supplier_id\\" IS 'Supplier who issued this expense bill (optional)'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"invoice_number\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"invoice_number\\" IS 'Supplier invoice/reference number'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"due_date\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"due_date\\" IS 'Payment due date (auto-set from supplier terms, for outstanding bills)'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"paid_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"paid_amount\\" IS 'Amount paid via Payment Vouchers; maintained by trigger on voucher_allocations'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"broker_items\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"broker_items\\" IS 'Optional cost breakdown for Import/Customs Broker invoices. Array of {type, description, amount}. SUM(amount) = finance_expenses.amount. NULL = not a broker invoice. PPN, PPh, Stamp Duty are NOT included here — they stay on parent columns.'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"pph_paid_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"pph_paid_amount\\" IS 'Portion of pph_amount actually remitted to the government (SPT PPh23). Maintained by recalculate_expense_payment_state().'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"staff_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"staff_id\\" IS 'Staff member this expense belongs to (salary, overtime, welfare, advance). NULL for non-staff expenses.'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"bank_charges_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"bank_charges_amount\\" IS 'Optional bank charges paid alongside a utility bill. Only used for the utilities expense_category. Journal: Dr Utility, Dr Bank Charges, Cr Bank (=amount+bank_charges_amount). Utility expense amount itself is unchanged.'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"ppn_calc_mode\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"ppn_calc_mode\\" IS 'Indonesian PPN calculation mode. standard = ppn from invoice amount, dpp_nilai_lain = ppn from supplier-provided DPP, manual = user-entered.'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"dpp_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"dpp_amount\\" IS 'Supplier-provided DPP (Dasar Pengenaan Pajak) used when ppn_calc_mode = ''dpp_nilai_lain''. NULL for standard and manual modes.'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"ppn_rate\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"ppn_rate\\" IS 'PPN rate percent (default 11). Stored to preserve historical rates when rate changes (e.g. 11% → 12%).'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"ppn_manual_override\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"ppn_manual_override\\" IS 'If TRUE, ppn_amount was manually edited by the user and must not be auto-recomputed by the frontend when amount or supplier changes. FALSE for auto-calculated values. Reset to FALSE when the user clicks the recalculate button.'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"settlement_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"settlement_amount\\" IS 'Canonical actual bank settlement: invoice plus reimbursable/tax components, less withholding, plus bank charges/adjustments.'","--\n-- Name: COLUMN \\"finance_expenses\\".\\"include_in_landed_cost\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"finance_expenses\\".\\"include_in_landed_cost\\" IS 'Controls whether this expense is included in its import container''s landed-cost allocation. NULL = not yet decided, TRUE = included, FALSE = excluded.'","--\n-- Name: journal_entries; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"journal_entries\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"entry_number\\" character varying(50) NOT NULL,\n    \\"entry_date\\" \\"date\\" NOT NULL,\n    \\"period_id\\" \\"uuid\\",\n    \\"source_module\\" character varying(50),\n    \\"reference_id\\" \\"uuid\\",\n    \\"reference_number\\" character varying(100),\n    \\"description\\" \\"text\\",\n    \\"total_debit\\" numeric(18,2) DEFAULT 0,\n    \\"total_credit\\" numeric(18,2) DEFAULT 0,\n    \\"is_posted\\" boolean DEFAULT true,\n    \\"is_reversed\\" boolean DEFAULT false,\n    \\"reversed_by_id\\" \\"uuid\\",\n    \\"posted_by\\" \\"uuid\\",\n    \\"posted_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"transaction_category\\" \\"text\\",\n    \\"transaction_currency\\" \\"text\\",\n    \\"functional_currency\\" \\"text\\",\n    \\"exchange_rate\\" numeric(18,6),\n    \\"amounts_are_functional\\" boolean,\n    CONSTRAINT \\"journal_entries_currency_metadata_check\\" CHECK ((((\\"transaction_currency\\" IS NULL) OR (\\"transaction_currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"functional_currency\\" IS NULL) OR (\\"functional_currency\\" = 'IDR'::\\"text\\")) AND ((\\"exchange_rate\\" IS NULL) OR (\\"exchange_rate\\" > (0)::numeric))))\n)","--\n-- Name: journal_entry_lines; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"journal_entry_lines\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"journal_entry_id\\" \\"uuid\\" NOT NULL,\n    \\"line_number\\" integer NOT NULL,\n    \\"account_id\\" \\"uuid\\" NOT NULL,\n    \\"description\\" \\"text\\",\n    \\"debit\\" numeric(18,2) DEFAULT 0,\n    \\"credit\\" numeric(18,2) DEFAULT 0,\n    \\"tax_code_id\\" \\"uuid\\",\n    \\"customer_id\\" \\"uuid\\",\n    \\"supplier_id\\" \\"uuid\\",\n    \\"batch_id\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"transaction_currency\\" \\"text\\",\n    \\"transaction_debit\\" numeric(18,2),\n    \\"transaction_credit\\" numeric(18,2),\n    \\"functional_currency\\" \\"text\\",\n    \\"exchange_rate\\" numeric(18,6),\n    CONSTRAINT \\"journal_entry_lines_currency_metadata_check\\" CHECK ((((\\"transaction_currency\\" IS NULL) OR (\\"transaction_currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"functional_currency\\" IS NULL) OR (\\"functional_currency\\" = 'IDR'::\\"text\\")) AND ((\\"exchange_rate\\" IS NULL) OR (\\"exchange_rate\\" > (0)::numeric))))\n)","--\n-- Name: payment_vouchers; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"payment_vouchers\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"voucher_number\\" character varying(50) NOT NULL,\n    \\"voucher_date\\" \\"date\\" NOT NULL,\n    \\"supplier_id\\" \\"uuid\\",\n    \\"payment_method\\" character varying(50) NOT NULL,\n    \\"bank_account_id\\" \\"uuid\\",\n    \\"reference_number\\" character varying(100),\n    \\"amount\\" numeric(18,2) NOT NULL,\n    \\"pph_amount\\" numeric(18,2) DEFAULT 0,\n    \\"pph_code_id\\" \\"uuid\\",\n    \\"net_amount\\" numeric(18,2) GENERATED ALWAYS AS ((\\"amount\\" - \\"pph_amount\\")) STORED,\n    \\"description\\" \\"text\\",\n    \\"document_urls\\" \\"text\\"[],\n    \\"journal_entry_id\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"coa_account_id\\" \\"uuid\\",\n    \\"payment_currency\\" character varying(8) DEFAULT 'IDR'::character varying,\n    \\"exchange_rate\\" numeric DEFAULT 1,\n    \\"bank_amount\\" numeric,\n    \\"bank_charge\\" numeric DEFAULT 0,\n    \\"is_posted\\" boolean DEFAULT false NOT NULL,\n    \\"company_snapshot\\" \\"jsonb\\",\n    \\"tax_period_id\\" \\"uuid\\",\n    \\"staff_id\\" \\"uuid\\",\n    \\"currency_code\\" \\"text\\",\n    \\"transaction_currency\\" \\"text\\",\n    \\"functional_currency\\" \\"text\\",\n    \\"bank_account_currency\\" \\"text\\",\n    \\"payment_purpose\\" \\"text\\" DEFAULT 'general'::\\"text\\" NOT NULL,\n    \\"invoice_currency\\" \\"text\\",\n    \\"invoice_amount\\" numeric,\n    \\"payment_amount\\" numeric,\n    \\"bank_currency\\" \\"text\\",\n    \\"converted_amount\\" numeric,\n    \\"actual_bank_debit\\" numeric,\n    \\"salary_advance_applied_amount\\" numeric(18,2) DEFAULT 0 NOT NULL,\n    \\"salary_advance_status\\" \\"text\\" DEFAULT 'not_applicable'::\\"text\\" NOT NULL,\n    \\"settlement_amount\\" numeric GENERATED ALWAYS AS (COALESCE(\\"actual_bank_debit\\", \\"bank_amount\\", ((\\"amount\\" - COALESCE(\\"pph_amount\\", (0)::numeric)) + COALESCE(\\"bank_charge\\", (0)::numeric)))) STORED,\n    CONSTRAINT \\"payment_vouchers_currency_metadata_check\\" CHECK ((((\\"transaction_currency\\" IS NULL) OR (\\"transaction_currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"functional_currency\\" IS NULL) OR (\\"functional_currency\\" = 'IDR'::\\"text\\")) AND ((\\"currency_code\\" IS NULL) OR (\\"currency_code\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"payment_currency\\" IS NULL) OR ((\\"payment_currency\\")::\\"text\\" = ANY ((ARRAY['IDR'::character varying, 'USD'::character varying])::\\"text\\"[]))) AND ((\\"bank_account_currency\\" IS NULL) OR (\\"bank_account_currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"exchange_rate\\" IS NULL) OR (\\"exchange_rate\\" > (0)::numeric)))),\n    CONSTRAINT \\"payment_vouchers_payment_method_check\\" CHECK (((\\"payment_method\\")::\\"text\\" = ANY ((ARRAY['cash'::character varying, 'bank_transfer'::character varying, 'check'::character varying, 'giro'::character varying, 'other'::character varying, 'advance_adjustment'::character varying])::\\"text\\"[]))),\n    CONSTRAINT \\"payment_vouchers_payment_purpose_check\\" CHECK ((\\"payment_purpose\\" = ANY (ARRAY['general'::\\"text\\", 'salary_advance'::\\"text\\", 'salary_advance_settlement'::\\"text\\"]))),\n    CONSTRAINT \\"payment_vouchers_salary_advance_status_check\\" CHECK ((\\"salary_advance_status\\" = ANY (ARRAY['not_applicable'::\\"text\\", 'outstanding'::\\"text\\", 'partially_settled'::\\"text\\", 'settled'::\\"text\\"]))),\n    CONSTRAINT \\"pv_supplier_or_account_required\\" CHECK (((\\"supplier_id\\" IS NOT NULL) OR (\\"staff_id\\" IS NOT NULL) OR (\\"coa_account_id\\" IS NOT NULL)))\n)","--\n-- Name: COLUMN \\"payment_vouchers\\".\\"staff_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"payment_vouchers\\".\\"staff_id\\" IS 'Staff payee (salary payment / advance / advance adjustment). Mutually exclusive with supplier_id in practice; both nullable.'","--\n-- Name: COLUMN \\"payment_vouchers\\".\\"payment_purpose\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"payment_vouchers\\".\\"payment_purpose\\" IS 'Business purpose of the payment. salary_advance is a staff advance; settlement uses the existing advance_adjustment posting path.'","--\n-- Name: COLUMN \\"payment_vouchers\\".\\"invoice_currency\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"payment_vouchers\\".\\"invoice_currency\\" IS 'Currency of the invoices being settled.'","--\n-- Name: COLUMN \\"payment_vouchers\\".\\"invoice_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"payment_vouchers\\".\\"invoice_amount\\" IS 'Gross amount allocated in invoice currency.'","--\n-- Name: COLUMN \\"payment_vouchers\\".\\"payment_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"payment_vouchers\\".\\"payment_amount\\" IS 'Net amount settled in invoice currency after withholding, before conversion.'","--\n-- Name: COLUMN \\"payment_vouchers\\".\\"bank_currency\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"payment_vouchers\\".\\"bank_currency\\" IS 'Currency of the selected bank account.'","--\n-- Name: COLUMN \\"payment_vouchers\\".\\"converted_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"payment_vouchers\\".\\"converted_amount\\" IS 'Payment amount converted to bank currency, before bank charges.'","--\n-- Name: COLUMN \\"payment_vouchers\\".\\"actual_bank_debit\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"payment_vouchers\\".\\"actual_bank_debit\\" IS 'Actual bank-side debit, including bank charges.'","--\n-- Name: COLUMN \\"payment_vouchers\\".\\"settlement_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"payment_vouchers\\".\\"settlement_amount\\" IS 'Canonical actual bank debit after withholding/conversion and including bank charges.'","--\n-- Name: petty_cash_transactions; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"petty_cash_transactions\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"transaction_number\\" character varying(50) NOT NULL,\n    \\"transaction_date\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"transaction_type\\" character varying(20) NOT NULL,\n    \\"amount\\" numeric(15,2) NOT NULL,\n    \\"description\\" \\"text\\" NOT NULL,\n    \\"expense_category\\" character varying(100),\n    \\"bank_account_id\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"paid_to\\" character varying(255),\n    \\"paid_by_staff_id\\" \\"uuid\\",\n    \\"source\\" character varying(255),\n    \\"received_by_staff_id\\" \\"uuid\\",\n    \\"paid_by_staff_name\\" character varying(255),\n    \\"received_by_staff_name\\" character varying(255),\n    \\"paid_by\\" \\"text\\" DEFAULT 'cash'::\\"text\\",\n    \\"import_container_id\\" \\"uuid\\",\n    \\"delivery_challan_id\\" \\"uuid\\",\n    \\"document_urls\\" \\"text\\"[],\n    \\"voucher_number\\" character varying(50),\n    \\"fund_transfer_id\\" \\"uuid\\",\n    \\"approval_status\\" \\"text\\" DEFAULT 'pending_approval'::\\"text\\" NOT NULL,\n    \\"approved_by\\" \\"uuid\\",\n    \\"approved_at\\" timestamp with time zone,\n    \\"rejection_reason\\" \\"text\\",\n    \\"source_account_id\\" \\"uuid\\",\n    \\"bank_statement_line_id\\" \\"uuid\\",\n    \\"settlement_amount\\" numeric GENERATED ALWAYS AS (\\"amount\\") STORED,\n    \\"include_in_landed_cost\\" boolean,\n    CONSTRAINT \\"petty_cash_transactions_amount_check\\" CHECK ((\\"amount\\" > (0)::numeric)),\n    CONSTRAINT \\"petty_cash_transactions_approval_status_check\\" CHECK ((\\"approval_status\\" = ANY (ARRAY['pending_approval'::\\"text\\", 'approved'::\\"text\\", 'rejected'::\\"text\\"]))),\n    CONSTRAINT \\"petty_cash_transactions_paid_by_check\\" CHECK ((\\"paid_by\\" = ANY (ARRAY['bank'::\\"text\\", 'cash'::\\"text\\"]))),\n    CONSTRAINT \\"petty_cash_transactions_transaction_type_check\\" CHECK (((\\"transaction_type\\")::\\"text\\" = ANY ((ARRAY['withdraw'::character varying, 'expense'::character varying])::\\"text\\"[])))\n)","--\n-- Name: COLUMN \\"petty_cash_transactions\\".\\"import_container_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"petty_cash_transactions\\".\\"import_container_id\\" IS 'Links petty cash expense to import container for cost allocation'","--\n-- Name: COLUMN \\"petty_cash_transactions\\".\\"delivery_challan_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"petty_cash_transactions\\".\\"delivery_challan_id\\" IS 'Links petty cash expense to delivery challan'","--\n-- Name: COLUMN \\"petty_cash_transactions\\".\\"document_urls\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"petty_cash_transactions\\".\\"document_urls\\" IS 'Array of document URLs (receipts, invoices, photos)'","--\n-- Name: COLUMN \\"petty_cash_transactions\\".\\"settlement_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"petty_cash_transactions\\".\\"settlement_amount\\" IS 'Canonical cash/bank movement for this petty-cash document.'","--\n-- Name: COLUMN \\"petty_cash_transactions\\".\\"include_in_landed_cost\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"petty_cash_transactions\\".\\"include_in_landed_cost\\" IS 'Controls whether this petty cash transaction is included in its import container''s landed-cost allocation. NULL = not yet decided, TRUE = included, FALSE = excluded.'","--\n-- Name: receipt_vouchers; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"receipt_vouchers\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"voucher_number\\" character varying(50) NOT NULL,\n    \\"voucher_date\\" \\"date\\" NOT NULL,\n    \\"customer_id\\" \\"uuid\\",\n    \\"payment_method\\" character varying(50) NOT NULL,\n    \\"bank_account_id\\" \\"uuid\\",\n    \\"reference_number\\" character varying(100),\n    \\"amount\\" numeric(18,2) NOT NULL,\n    \\"description\\" \\"text\\",\n    \\"document_urls\\" \\"text\\"[],\n    \\"journal_entry_id\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"coa_account_id\\" \\"uuid\\",\n    \\"is_posted\\" boolean DEFAULT false NOT NULL,\n    \\"company_snapshot\\" \\"jsonb\\",\n    \\"currency_code\\" \\"text\\",\n    \\"transaction_currency\\" \\"text\\",\n    \\"functional_currency\\" \\"text\\",\n    \\"exchange_rate\\" numeric(18,6),\n    \\"bank_account_currency\\" \\"text\\",\n    \\"payment_currency\\" \\"text\\",\n    \\"settlement_amount\\" numeric GENERATED ALWAYS AS (\\"amount\\") STORED,\n    CONSTRAINT \\"receipt_vouchers_currency_metadata_check\\" CHECK ((((\\"transaction_currency\\" IS NULL) OR (\\"transaction_currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"functional_currency\\" IS NULL) OR (\\"functional_currency\\" = 'IDR'::\\"text\\")) AND ((\\"currency_code\\" IS NULL) OR (\\"currency_code\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"payment_currency\\" IS NULL) OR (\\"payment_currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"bank_account_currency\\" IS NULL) OR (\\"bank_account_currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))) AND ((\\"exchange_rate\\" IS NULL) OR (\\"exchange_rate\\" > (0)::numeric)))),\n    CONSTRAINT \\"receipt_vouchers_payment_method_check\\" CHECK (((\\"payment_method\\")::\\"text\\" = ANY ((ARRAY['cash'::character varying, 'bank_transfer'::character varying, 'check'::character varying, 'giro'::character varying, 'other'::character varying])::\\"text\\"[]))),\n    CONSTRAINT \\"rv_customer_or_account_required\\" CHECK (((\\"customer_id\\" IS NOT NULL) OR (\\"coa_account_id\\" IS NOT NULL)))\n)","--\n-- Name: COLUMN \\"receipt_vouchers\\".\\"settlement_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"receipt_vouchers\\".\\"settlement_amount\\" IS 'Canonical actual bank credit.'","--\n-- Name: tax_payments; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"tax_payments\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"tax_period_id\\" \\"uuid\\" NOT NULL,\n    \\"tax_type\\" \\"text\\" NOT NULL,\n    \\"payment_date\\" \\"date\\" NOT NULL,\n    \\"amount\\" numeric(18,2) NOT NULL,\n    \\"bank_account_id\\" \\"uuid\\",\n    \\"billing_code\\" \\"text\\",\n    \\"ntpn\\" \\"text\\",\n    \\"government_reference\\" \\"text\\",\n    \\"notes\\" \\"text\\",\n    \\"payment_voucher_id\\" \\"uuid\\",\n    \\"journal_entry_id\\" \\"uuid\\",\n    \\"status\\" \\"text\\" DEFAULT 'draft'::\\"text\\" NOT NULL,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"payment_reference\\" \\"text\\",\n    \\"settlement_amount\\" numeric GENERATED ALWAYS AS (\\"amount\\") STORED,\n    \\"historical_source_status\\" \\"text\\" DEFAULT 'none'::\\"text\\" NOT NULL,\n    \\"historical_source_document_type\\" \\"text\\",\n    \\"historical_source_document_id\\" \\"uuid\\",\n    \\"historical_source_reference\\" \\"text\\",\n    \\"historical_source_note\\" \\"text\\",\n    CONSTRAINT \\"tax_payments_amount_check\\" CHECK ((\\"amount\\" > (0)::numeric)),\n    CONSTRAINT \\"tax_payments_historical_source_status_check\\" CHECK ((\\"historical_source_status\\" = ANY (ARRAY['none'::\\"text\\", 'missing_source_verified'::\\"text\\"]))),\n    CONSTRAINT \\"tax_payments_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['draft'::\\"text\\", 'posted'::\\"text\\", 'reconciled'::\\"text\\", 'void'::\\"text\\"]))),\n    CONSTRAINT \\"tax_payments_tax_type_check\\" CHECK ((\\"tax_type\\" = ANY (ARRAY['PPN'::\\"text\\", 'PPh21'::\\"text\\", 'PPh22'::\\"text\\", 'PPh23'::\\"text\\", 'PPh4(2)'::\\"text\\", 'PPh_Unifikasi'::\\"text\\"])))\n)","--\n-- Name: COLUMN \\"tax_payments\\".\\"settlement_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"tax_payments\\".\\"settlement_amount\\" IS 'Canonical actual bank debit for the tax remittance.'","--\n-- Name: vw_finance_document_settlements; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"vw_finance_document_settlements\\" WITH (\\"security_invoker\\"='true') AS\n WITH \\"document_journals\\" AS (\n         SELECT 'expense'::\\"text\\" AS \\"document_type\\",\n            \\"fe\\".\\"id\\" AS \\"document_id\\",\n            COALESCE(\\"fe\\".\\"voucher_number\\", (\\"fe\\".\\"invoice_number\\")::\\"text\\", (\\"fe\\".\\"id\\")::\\"text\\") AS \\"document_number\\",\n            \\"fe\\".\\"expense_date\\" AS \\"settlement_date\\",\n            \\"je\\".\\"id\\" AS \\"journal_entry_id\\"\n           FROM (\\"public\\".\\"finance_expenses\\" \\"fe\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((((\\"je\\".\\"source_module\\")::\\"text\\" = ANY ((ARRAY['expense'::character varying, 'expenses'::character varying])::\\"text\\"[])) AND ((\\"je\\".\\"reference_id\\" = \\"fe\\".\\"id\\") OR ((\\"je\\".\\"reference_number\\")::\\"text\\" = ('EXP-'::\\"text\\" || (\\"fe\\".\\"id\\")::\\"text\\"))))))\n        UNION ALL\n         SELECT 'payment'::\\"text\\",\n            \\"pv\\".\\"id\\",\n            \\"pv\\".\\"voucher_number\\",\n            \\"pv\\".\\"voucher_date\\",\n            \\"pv\\".\\"journal_entry_id\\"\n           FROM \\"public\\".\\"payment_vouchers\\" \\"pv\\"\n          WHERE ((\\"pv\\".\\"journal_entry_id\\" IS NOT NULL) AND ((COALESCE(\\"pv\\".\\"payment_method\\", ''::character varying))::\\"text\\" <> 'advance_adjustment'::\\"text\\"))\n        UNION ALL\n         SELECT 'receipt'::\\"text\\",\n            \\"rv\\".\\"id\\",\n            \\"rv\\".\\"voucher_number\\",\n            \\"rv\\".\\"voucher_date\\",\n            \\"rv\\".\\"journal_entry_id\\"\n           FROM \\"public\\".\\"receipt_vouchers\\" \\"rv\\"\n          WHERE (\\"rv\\".\\"journal_entry_id\\" IS NOT NULL)\n        UNION ALL\n         SELECT 'fund_transfer'::\\"text\\",\n            \\"ft\\".\\"id\\",\n            \\"ft\\".\\"transfer_number\\",\n            \\"ft\\".\\"transfer_date\\",\n            \\"ft\\".\\"journal_entry_id\\"\n           FROM \\"public\\".\\"fund_transfers\\" \\"ft\\"\n          WHERE (\\"ft\\".\\"journal_entry_id\\" IS NOT NULL)\n        UNION ALL\n         SELECT 'petty_cash'::\\"text\\",\n            \\"pc\\".\\"id\\",\n            \\"pc\\".\\"transaction_number\\",\n            \\"pc\\".\\"transaction_date\\",\n            \\"je\\".\\"id\\"\n           FROM (\\"public\\".\\"petty_cash_transactions\\" \\"pc\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((((\\"je\\".\\"source_module\\")::\\"text\\" = 'petty_cash'::\\"text\\") AND (\\"je\\".\\"reference_id\\" = \\"pc\\".\\"id\\"))))\n          WHERE (\\"pc\\".\\"fund_transfer_id\\" IS NULL)\n        UNION ALL\n         SELECT 'tax_payment'::\\"text\\",\n            \\"tp\\".\\"id\\",\n            COALESCE(\\"tp\\".\\"ntpn\\", \\"tp\\".\\"billing_code\\", (\\"tp\\".\\"id\\")::\\"text\\") AS \\"coalesce\\",\n            \\"tp\\".\\"payment_date\\",\n            \\"tp\\".\\"journal_entry_id\\"\n           FROM \\"public\\".\\"tax_payments\\" \\"tp\\"\n          WHERE (\\"tp\\".\\"journal_entry_id\\" IS NOT NULL)\n        ), \\"mapped\\" AS (\n         SELECT DISTINCT ON (\\"document_journals\\".\\"document_type\\", \\"document_journals\\".\\"document_id\\", \\"document_journals\\".\\"journal_entry_id\\") \\"document_journals\\".\\"document_type\\",\n            \\"document_journals\\".\\"document_id\\",\n            \\"document_journals\\".\\"document_number\\",\n            \\"document_journals\\".\\"settlement_date\\",\n            \\"document_journals\\".\\"journal_entry_id\\"\n           FROM \\"document_journals\\"\n          WHERE (\\"document_journals\\".\\"journal_entry_id\\" IS NOT NULL)\n          ORDER BY \\"document_journals\\".\\"document_type\\", \\"document_journals\\".\\"document_id\\", \\"document_journals\\".\\"journal_entry_id\\"\n        ), \\"bank_legs\\" AS (\n         SELECT \\"m\\".\\"document_type\\",\n            \\"m\\".\\"document_id\\",\n            \\"m\\".\\"document_number\\",\n            \\"m\\".\\"settlement_date\\",\n            \\"m\\".\\"journal_entry_id\\",\n            \\"ba\\".\\"id\\" AS \\"bank_account_id\\",\n            \\"upper\\"(COALESCE(\\"ba\\".\\"currency\\", 'IDR'::\\"text\\")) AS \\"currency\\",\n                CASE\n                    WHEN (\\"sum\\"(COALESCE(\\"jel\\".\\"transaction_debit\\", \\"jel\\".\\"debit\\")) > (0)::numeric) THEN 'credit'::\\"text\\"\n                    ELSE 'debit'::\\"text\\"\n                END AS \\"direction\\",\n                CASE\n                    WHEN (\\"sum\\"(COALESCE(\\"jel\\".\\"transaction_debit\\", \\"jel\\".\\"debit\\")) > (0)::numeric) THEN \\"sum\\"(COALESCE(\\"jel\\".\\"transaction_debit\\", \\"jel\\".\\"debit\\"))\n                    ELSE \\"sum\\"(COALESCE(\\"jel\\".\\"transaction_credit\\", \\"jel\\".\\"credit\\"))\n                END AS \\"settlement_amount\\"\n           FROM (((\\"mapped\\" \\"m\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON (((\\"je\\".\\"id\\" = \\"m\\".\\"journal_entry_id\\") AND (\\"je\\".\\"is_posted\\" = true) AND (COALESCE(\\"je\\".\\"is_reversed\\", false) = false))))\n             JOIN \\"public\\".\\"journal_entry_lines\\" \\"jel\\" ON ((\\"jel\\".\\"journal_entry_id\\" = \\"je\\".\\"id\\")))\n             JOIN \\"public\\".\\"bank_accounts\\" \\"ba\\" ON ((\\"ba\\".\\"coa_id\\" = \\"jel\\".\\"account_id\\")))\n          GROUP BY \\"m\\".\\"document_type\\", \\"m\\".\\"document_id\\", \\"m\\".\\"document_number\\", \\"m\\".\\"settlement_date\\", \\"m\\".\\"journal_entry_id\\", \\"ba\\".\\"id\\", (\\"upper\\"(COALESCE(\\"ba\\".\\"currency\\", 'IDR'::\\"text\\")))\n        )\n SELECT \\"document_type\\",\n    \\"document_id\\",\n    \\"document_number\\",\n    \\"settlement_date\\",\n    \\"journal_entry_id\\",\n    \\"bank_account_id\\",\n    \\"currency\\",\n    \\"direction\\",\n    \\"settlement_amount\\"\n   FROM \\"bank_legs\\"\n  WHERE (\\"settlement_amount\\" > (0)::numeric)","--\n-- Name: VIEW \\"vw_finance_document_settlements\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON VIEW \\"public\\".\\"vw_finance_document_settlements\\" IS 'One canonical actual-bank-movement row per Finance document, posted journal and bank account. Bank Reconciliation must consume settlement_amount only.'","--\n-- Name: get_finance_document_settlements(\\"text\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_finance_document_settlements\\"(\\"p_document_type\\" \\"text\\", \\"p_document_id\\" \\"uuid\\") RETURNS SETOF \\"public\\".\\"vw_finance_document_settlements\\"\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\n  SELECT * FROM public.vw_finance_document_settlements\n   WHERE document_type=p_document_type AND document_id=p_document_id\n   ORDER BY bank_account_id,direction;\n$$","--\n-- Name: get_gmail_connection_secret(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_gmail_connection_secret\\"(\\"p_connection_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_user_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS TABLE(\\"id\\" \\"uuid\\", \\"user_id\\" \\"uuid\\", \\"email_address\\" \\"text\\", \\"access_token\\" \\"text\\", \\"refresh_token\\" \\"text\\", \\"access_token_expires_at\\" timestamp with time zone, \\"is_connected\\" boolean, \\"sync_enabled\\" boolean, \\"last_sync\\" timestamp with time zone, \\"sync_frequency_minutes\\" integer)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF auth.role() <> 'service_role' THEN\n    IF auth.uid() IS NULL THEN\n      RAISE EXCEPTION 'Not authenticated';\n    END IF;\n    -- Both scoping args cannot be NULL — that would return every row.\n    IF p_connection_id IS NULL AND p_user_id IS NULL THEN\n      RAISE EXCEPTION 'A connection_id or user_id must be provided';\n    END IF;\n    -- If both scoping args are provided, they must be consistent with caller.\n    IF p_user_id IS NOT NULL AND p_user_id <> auth.uid() THEN\n      RAISE EXCEPTION 'Forbidden';\n    END IF;\n    -- If only p_connection_id is provided, verify it belongs to the caller.\n    IF p_user_id IS NULL AND p_connection_id IS NOT NULL THEN\n      IF NOT EXISTS (\n        SELECT 1 FROM public.gmail_connections\n        WHERE id = p_connection_id AND user_id = auth.uid()\n      ) THEN\n        RAISE EXCEPTION 'Forbidden';\n      END IF;\n    END IF;\n  END IF;\n\n  UPDATE public.gmail_connections gc\n  SET token_accessed_at = now()\n  WHERE (p_connection_id IS NULL OR gc.id = p_connection_id)\n    AND (p_user_id IS NULL OR gc.user_id = p_user_id)\n    AND gc.is_connected = true;\n\n  RETURN QUERY\n  SELECT\n    gc.id,\n    gc.user_id,\n    gc.email_address,\n    COALESCE(gc.access_token, public.decrypt_gmail_token(gc.access_token_encrypted)) AS access_token,\n    COALESCE(gc.refresh_token, public.decrypt_gmail_token(gc.refresh_token_encrypted)) AS refresh_token,\n    gc.access_token_expires_at,\n    gc.is_connected,\n    gc.sync_enabled,\n    gc.last_sync,\n    gc.sync_frequency_minutes\n  FROM public.gmail_connections gc\n  WHERE (p_connection_id IS NULL OR gc.id = p_connection_id)\n    AND (p_user_id IS NULL OR gc.user_id = p_user_id)\n    AND gc.is_connected = true;\nEND $$","--\n-- Name: get_invoice_allocation_amount(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_invoice_allocation_amount\\"(\\"p_invoice_id\\" \\"uuid\\", \\"p_exclude_voucher_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS numeric\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\n  SELECT COALESCE(SUM(va.allocated_amount), 0)\n  FROM public.voucher_allocations va\n  WHERE va.sales_invoice_id = p_invoice_id\n    AND va.voucher_type = 'receipt'\n    AND (p_exclude_voucher_id IS NULL OR va.receipt_voucher_id <> p_exclude_voucher_id);\n$$","--\n-- Name: get_invoice_balance(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_invoice_balance\\"(\\"p_invoice_id\\" \\"uuid\\") RETURNS numeric\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_total numeric;\nv_paid numeric;\nBEGIN\nSELECT total_amount INTO v_total\nFROM sales_invoices\nWHERE id = p_invoice_id;\n\nv_paid := get_invoice_paid_amount(p_invoice_id);\n\nRETURN COALESCE(v_total, 0) - COALESCE(v_paid, 0);\nEND;\n$$","--\n-- Name: FUNCTION \\"get_invoice_balance\\"(\\"p_invoice_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_invoice_balance\\"(\\"p_invoice_id\\" \\"uuid\\") IS 'Calculates the remaining balance for an invoice (total - paid)'","--\n-- Name: get_invoice_latest_payment_date(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_invoice_latest_payment_date\\"(\\"p_invoice_id\\" \\"uuid\\") RETURNS \\"date\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_latest_date date;\nBEGIN\nSELECT MAX(rv.voucher_date)\nINTO v_latest_date\nFROM voucher_allocations va\nJOIN receipt_vouchers rv ON rv.id = va.receipt_voucher_id\nWHERE va.sales_invoice_id = p_invoice_id\nAND va.voucher_type = 'receipt';\n\nRETURN v_latest_date;\nEND;\n$$","--\n-- Name: get_invoice_paid_amount(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_invoice_paid_amount\\"(\\"p_invoice_id\\" \\"uuid\\") RETURNS numeric\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\n  SELECT public.get_invoice_allocation_amount(p_invoice_id, NULL)\n       + public.get_invoice_rounding_adjustment_amount(p_invoice_id);\n$$","--\n-- Name: FUNCTION \\"get_invoice_paid_amount\\"(\\"p_invoice_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_invoice_paid_amount\\"(\\"p_invoice_id\\" \\"uuid\\") IS 'Calculates the total amount paid for a specific invoice from all payment allocations'","--\n-- Name: get_invoice_rounding_adjustment_amount(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_invoice_rounding_adjustment_amount\\"(\\"p_invoice_id\\" \\"uuid\\") RETURNS numeric\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\n  SELECT COALESCE(SUM(ira.adjustment_amount), 0)\n  FROM public.invoice_rounding_adjustments ira\n  WHERE ira.sales_invoice_id = p_invoice_id;\n$$","--\n-- Name: get_invoice_with_balance(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_invoice_with_balance\\"(\\"invoice_uuid\\" \\"uuid\\", \\"exclude_voucher_uuid\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS TABLE(\\"id\\" \\"uuid\\", \\"invoice_number\\" \\"text\\", \\"invoice_date\\" \\"date\\", \\"customer_id\\" \\"uuid\\", \\"total_amount\\" numeric, \\"paid_amount\\" numeric, \\"balance_amount\\" numeric)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  RETURN QUERY\n  SELECT\n    si.id,\n    si.invoice_number,\n    si.invoice_date,\n    si.customer_id,\n    si.total_amount,\n    public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)\n      + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END AS paid_amount,\n    si.total_amount - (\n      public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)\n      + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END\n    ) AS balance_amount\n  FROM public.sales_invoices si\n  WHERE si.id = invoice_uuid\n    AND COALESCE(si.is_draft, false) = false;\nEND;\n$$","--\n-- Name: get_invoices_with_balance(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_invoices_with_balance\\"(\\"customer_uuid\\" \\"uuid\\") RETURNS TABLE(\\"id\\" \\"uuid\\", \\"invoice_number\\" \\"text\\", \\"invoice_date\\" \\"date\\", \\"total_amount\\" numeric, \\"paid_amount\\" numeric, \\"balance_amount\\" numeric)\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT \nsi.id,\nsi.invoice_number,\nsi.invoice_date,\nsi.total_amount,\nCOALESCE(\n(SELECT SUM(va.allocated_amount) \nFROM voucher_allocations va \nWHERE va.sales_invoice_id = si.id\nAND va.voucher_type = 'receipt'), 0\n) as paid_amount,\nsi.total_amount - COALESCE(\n(SELECT SUM(va.allocated_amount) \nFROM voucher_allocations va \nWHERE va.sales_invoice_id = si.id\nAND va.voucher_type = 'receipt'), 0\n) as balance_amount\nFROM sales_invoices si\nWHERE si.customer_id = customer_uuid\nAND si.is_draft = false\nORDER BY si.invoice_date;\nEND;\n$$","--\n-- Name: get_invoices_with_balance(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_invoices_with_balance\\"(\\"customer_uuid\\" \\"uuid\\", \\"exclude_voucher_uuid\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS TABLE(\\"id\\" \\"uuid\\", \\"invoice_number\\" \\"text\\", \\"invoice_date\\" \\"date\\", \\"total_amount\\" numeric, \\"paid_amount\\" numeric, \\"balance_amount\\" numeric)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  RETURN QUERY\n  SELECT\n    si.id,\n    si.invoice_number,\n    si.invoice_date,\n    si.total_amount,\n    public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)\n      + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END AS paid_amount,\n    si.total_amount - (\n      public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)\n      + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END\n    ) AS balance_amount\n  FROM public.sales_invoices si\n  WHERE si.customer_id = customer_uuid\n    AND COALESCE(si.is_draft, false) = false\n  ORDER BY si.invoice_date;\nEND;\n$$","--\n-- Name: get_journal_reporting_multiplier(\\"uuid\\", numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_journal_reporting_multiplier\\"(\\"p_journal_entry_id\\" \\"uuid\\", \\"p_usd_rate\\" numeric) RETURNS numeric\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT CASE\n    WHEN je.amounts_are_functional=true THEN 1::numeric\n    WHEN je.transaction_currency='IDR' THEN 1::numeric\n    WHEN je.transaction_currency='USD' AND je.exchange_rate IS NOT NULL THEN je.exchange_rate\n    WHEN je.transaction_currency='USD' AND je.amounts_are_functional=false THEN 1::numeric\n    WHEN EXISTS (\n      SELECT 1\n      FROM public.journal_entries source_je\n      LEFT JOIN public.purchase_invoices pi ON pi.id=source_je.reference_id AND source_je.source_module='purchase_invoice'\n      LEFT JOIN public.payment_vouchers pv ON pv.id=source_je.reference_id AND source_je.source_module='payment'\n      LEFT JOIN public.bank_accounts pv_ba ON pv_ba.id=pv.bank_account_id\n      LEFT JOIN public.receipt_vouchers rv ON rv.id=source_je.reference_id AND source_je.source_module='receipt'\n      LEFT JOIN public.bank_accounts rv_ba ON rv_ba.id=rv.bank_account_id\n      LEFT JOIN public.fund_transfers ft ON ft.id=source_je.reference_id AND source_je.source_module IN('fund_transfer','fund_transfers')\n      LEFT JOIN public.bank_accounts ft_from_ba ON ft_from_ba.id=ft.from_bank_account_id\n      LEFT JOIN public.bank_accounts ft_to_ba ON ft_to_ba.id=ft.to_bank_account_id\n      LEFT JOIN public.bank_statement_lines bsl ON bsl.matched_entry_id=source_je.id\n      LEFT JOIN public.bank_accounts bsl_ba ON bsl_ba.id=bsl.bank_account_id\n      WHERE source_je.id=je.id AND (\n        pi.currency='USD' OR COALESCE(pv.payment_currency,pv_ba.currency)='USD' OR rv_ba.currency='USD'\n        OR COALESCE(ft_from_ba.currency,ft_to_ba.currency)='USD' OR COALESCE(bsl.currency,bsl_ba.currency)='USD'\n      )\n    ) THEN COALESCE(NULLIF(p_usd_rate,0),public.get_reporting_usd_rate())\n    ELSE 1::numeric\n  END\n  FROM public.journal_entries je WHERE je.id=p_journal_entry_id;\n$$","--\n-- Name: get_low_stock_products(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_low_stock_products\\"() RETURNS TABLE(\\"product_id\\" \\"uuid\\", \\"product_name\\" \\"text\\", \\"total_stock\\" numeric, \\"min_stock_level\\" numeric)\n    LANGUAGE \\"sql\\" STABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT\n    p.id AS product_id,\n    p.product_name,\n    COALESCE(SUM(b.current_stock), 0) AS total_stock,\n    p.min_stock_level\n  FROM products p\n  LEFT JOIN batches b ON b.product_id = p.id AND b.is_active = true\n  WHERE p.min_stock_level > 0\n  GROUP BY p.id, p.product_name, p.min_stock_level\n  HAVING COALESCE(SUM(b.current_stock), 0) < p.min_stock_level\n  ORDER BY p.product_name;\n$$","--\n-- Name: get_monthly_sales_report(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_monthly_sales_report\\"(\\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS TABLE(\\"month_label\\" \\"text\\", \\"month_start\\" \\"date\\", \\"total_sales\\" numeric, \\"total_orders\\" bigint, \\"total_qty_sold\\" numeric, \\"avg_order_value\\" numeric, \\"total_cogs\\" numeric, \\"gross_profit\\" numeric, \\"profit_pct\\" numeric, \\"outbound_delivery\\" numeric, \\"operational_profit\\" numeric, \\"costed_lines\\" bigint, \\"total_lines\\" bigint)\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH lines AS (\n    SELECT si.id, si.invoice_date, sii.quantity, sii.unit_price, b.landed_cost_per_unit,\n      (b.landed_cost_per_unit > 0) AS is_costed\n    FROM public.sales_invoices si\n    JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id\n    LEFT JOIN public.batches b ON b.id = sii.batch_id\n    WHERE si.invoice_date >= p_start_date AND si.invoice_date <= p_end_date\n      AND COALESCE(si.is_draft, false) = false\n  ), monthly AS (\n    SELECT date_trunc('month', invoice_date)::date AS month_start,\n      to_char(date_trunc('month', invoice_date), 'Mon YYYY') AS month_label,\n      SUM(quantity * unit_price) AS total_sales, COUNT(DISTINCT id) AS total_orders,\n      SUM(quantity) AS total_qty_sold,\n      SUM(quantity * unit_price) FILTER (WHERE is_costed) AS costed_revenue,\n      COALESCE(SUM(quantity * landed_cost_per_unit) FILTER (WHERE is_costed), 0) AS total_cogs,\n      COUNT(*) FILTER (WHERE is_costed) AS costed_lines, COUNT(*) AS total_lines\n    FROM lines GROUP BY 1, 2\n  ), expenses AS (\n    SELECT date_trunc('month', expense_date)::date AS month_start,\n      COALESCE(SUM(amount) FILTER (WHERE expense_category IN ('delivery_sales', 'loading_sales')), 0) AS outbound_delivery\n    FROM public.finance_expenses\n    WHERE expense_date >= p_start_date AND expense_date <= p_end_date\n    GROUP BY 1\n  )\n  SELECT m.month_label, m.month_start, ROUND(m.total_sales, 2), m.total_orders,\n    m.total_qty_sold, ROUND(m.total_sales / NULLIF(m.total_orders, 0), 2),\n    ROUND(m.total_cogs, 2), ROUND(COALESCE(m.costed_revenue, 0) - m.total_cogs, 2),\n    CASE WHEN COALESCE(m.costed_revenue, 0) = 0 THEN NULL\n      ELSE ROUND((m.costed_revenue - m.total_cogs) / m.costed_revenue * 100, 2) END,\n    ROUND(COALESCE(e.outbound_delivery, 0), 2),\n    ROUND(COALESCE(m.costed_revenue, 0) - m.total_cogs - COALESCE(e.outbound_delivery, 0), 2),\n    m.costed_lines, m.total_lines\n  FROM monthly m LEFT JOIN expenses e USING (month_start) ORDER BY m.month_start;\n$$","--\n-- Name: get_next_product_code(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_next_product_code\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $_$\nDECLARE\n  v_role text;\n  v_max_code text;\n  v_next_num integer;\nBEGIN\n  SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts', 'manager', 'warehouse') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot generate product codes', v_role;\n  END IF;\n\n  SELECT MAX(product_code) INTO v_max_code\n  FROM products\n  WHERE product_code ~ '^[A-Z]{2,4}-[0-9]+$';\n\n  IF v_max_code IS NULL THEN RETURN 'PRD-001'; END IF;\n  v_next_num := (regexp_match(v_max_code, '[0-9]+$'))[1]::integer + 1;\n  RETURN regexp_replace(v_max_code, '[0-9]+$', LPAD(v_next_num::text, 3, '0'));\nEND;\n$_$","--\n-- Name: get_outstanding_expense_bills(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_outstanding_expense_bills\\"(\\"p_as_of_date\\" \\"date\\" DEFAULT CURRENT_DATE) RETURNS TABLE(\\"id\\" \\"uuid\\", \\"supplier_id\\" \\"uuid\\", \\"supplier_name\\" \\"text\\", \\"staff_id\\" \\"uuid\\", \\"staff_name\\" \\"text\\", \\"invoice_number\\" \\"text\\", \\"invoice_date\\" \\"date\\", \\"due_date\\" \\"date\\", \\"expense_category\\" \\"text\\", \\"description\\" \\"text\\", \\"amount\\" numeric, \\"paid_amount\\" numeric, \\"balance_amount\\" numeric, \\"days_overdue\\" integer)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;\n  RETURN QUERY\n  WITH payable_documents AS MATERIALIZED (\n    SELECT fe.id, fe.supplier_id,\n      COALESCE(s.company_name::text,\n        CASE WHEN fe.supplier_id IS NULL AND fe.staff_id IS NULL\n          THEN NULLIF(regexp_replace(COALESCE(fe.description, ''), '^.*[-–—]\\\\\\\\s*', ''), COALESCE(fe.description, ''))\n        END) AS supplier_name,\n      fe.staff_id, sm.full_name::text AS staff_name,\n      fe.invoice_number::text, fe.expense_date AS invoice_date, fe.due_date,\n      fe.expense_category::text, fe.description::text,\n      public.calculate_finance_expense_payable(fe.id) AS payable_amount,\n      COALESCE((SELECT sum(va.allocated_amount)\n        FROM public.voucher_allocations va\n        LEFT JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n        WHERE va.finance_expense_id = fe.id\n          AND COALESCE(va.payment_kind, 'supplier') = 'supplier'\n          AND COALESCE(pv.payment_purpose, 'general') NOT IN ('salary_advance', 'salary_advance_settlement')\n          AND (va.payment_voucher_id IS NULL OR pv.is_posted = true)), 0)\n      + COALESCE((SELECT sum(a.allocation_amount)\n        FROM public.bank_statement_allocations a\n        WHERE a.document_type = 'expense' AND a.document_id = fe.id\n          AND COALESCE(a.payment_kind, 'supplier') = 'supplier'), 0)\n      + COALESCE((SELECT sum(COALESCE(NULLIF(b.debit_amount, 0), b.credit_amount, 0))\n        FROM public.bank_statement_lines b\n        WHERE b.matched_expense_id = fe.id AND b.payment_kind = 'supplier'\n          AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id = b.id)), 0)\n      + COALESCE((SELECT sum(sa.applied_amount)\n        FROM public.salary_advance_applications sa\n        JOIN public.payment_vouchers settlement ON settlement.id = sa.settlement_payment_voucher_id\n        WHERE sa.salary_expense_id = fe.id AND settlement.is_posted = true), 0) AS allocated_paid_amount\n    FROM public.finance_expenses fe\n    JOIN public.effective_expense_posting_state eps ON eps.expense_id = fe.id\n      AND eps.effective_posting_state IN ('ACTIVE', 'REPLACED')\n    LEFT JOIN public.suppliers s ON s.id = fe.supplier_id\n    LEFT JOIN public.finance_staff_master sm ON sm.id = fe.staff_id\n    WHERE fe.approval_status = 'approved' AND fe.expense_date <= p_as_of_date\n      AND EXISTS (SELECT 1 FROM public.journal_entry_lines jel\n        JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n        WHERE jel.journal_entry_id = eps.effective_journal_id\n          AND coa.code = '2110' AND jel.credit > jel.debit + 0.01)\n  ), current_state AS (\n    SELECT p.*, LEAST(GREATEST(p.allocated_paid_amount, 0), GREATEST(p.payable_amount, 0)) AS current_paid_amount\n    FROM payable_documents p\n  )\n  SELECT p.id, p.supplier_id, p.supplier_name, p.staff_id, p.staff_name,\n    p.invoice_number, p.invoice_date, p.due_date, p.expense_category, p.description,\n    p.payable_amount, p.current_paid_amount, p.payable_amount - p.current_paid_amount,\n    CASE WHEN p.due_date IS NOT NULL AND p.due_date < p_as_of_date\n      THEN (p_as_of_date - p.due_date)::integer ELSE 0 END\n  FROM current_state p\n  WHERE p.payable_amount > p.current_paid_amount + 0.01\n  ORDER BY COALESCE(p.due_date, p.invoice_date), p.id;\nEND;\n$$","--\n-- Name: FUNCTION \\"get_outstanding_expense_bills\\"(\\"p_as_of_date\\" \\"date\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_outstanding_expense_bills\\"(\\"p_as_of_date\\" \\"date\\") IS 'Current approved Expense AP backed by an effective 2110 journal credit; balances derive directly from canonical payment and bank allocations.'","--\n-- Name: get_outstanding_purchase_invoices(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_outstanding_purchase_invoices\\"(\\"p_as_of_date\\" \\"date\\" DEFAULT CURRENT_DATE) RETURNS TABLE(\\"id\\" \\"uuid\\", \\"invoice_number\\" \\"text\\", \\"invoice_date\\" \\"date\\", \\"due_date\\" \\"date\\", \\"total_amount\\" numeric, \\"paid_amount\\" numeric, \\"balance_amount\\" numeric, \\"currency\\" \\"text\\", \\"supplier_name\\" \\"text\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;\n  RETURN QUERY\n  WITH invoice_state AS (\n    SELECT pi.id, pi.invoice_number::text, pi.invoice_date, pi.due_date,\n      pi.total_amount, pi.currency::text, s.company_name::text AS supplier_name,\n      COALESCE((\n        SELECT sum(va.allocated_amount)\n        FROM public.voucher_allocations va\n        JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n        WHERE va.purchase_invoice_id = pi.id\n          AND va.voucher_type = 'payment'\n          AND pv.is_posted = true\n          AND COALESCE(va.payment_kind, 'supplier') = 'supplier'\n      ), 0) AS paid_amount\n    FROM public.purchase_invoices pi\n    LEFT JOIN public.suppliers s ON s.id = pi.supplier_id\n    WHERE pi.invoice_date <= p_as_of_date\n      AND EXISTS (\n        SELECT 1\n        FROM public.journal_entries je\n        JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n        JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n        WHERE je.source_module IN ('purchase_invoice', 'purchase_invoices')\n          AND (je.reference_id = pi.id OR je.reference_number = pi.invoice_number)\n          AND je.is_posted = true AND NOT COALESCE(je.is_reversed, false)\n          AND coa.code = '2110' AND jel.credit > jel.debit + 0.01\n      )\n  )\n  SELECT i.id, i.invoice_number, i.invoice_date, i.due_date, i.total_amount,\n    LEAST(GREATEST(i.paid_amount, 0), GREATEST(i.total_amount, 0)),\n    i.total_amount - LEAST(GREATEST(i.paid_amount, 0), GREATEST(i.total_amount, 0)),\n    i.currency, i.supplier_name\n  FROM invoice_state i\n  WHERE i.total_amount > i.paid_amount + 0.01\n  ORDER BY i.due_date, i.invoice_date, i.id;\nEND;\n$$","--\n-- Name: get_outstanding_salary_advances(\\"uuid\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_outstanding_salary_advances\\"(\\"p_staff_id\\" \\"uuid\\", \\"p_as_of_date\\" \\"date\\" DEFAULT CURRENT_DATE) RETURNS TABLE(\\"advance_id\\" \\"uuid\\", \\"voucher_number\\" \\"text\\", \\"voucher_date\\" \\"date\\", \\"staff_id\\" \\"uuid\\", \\"staff_name\\" \\"text\\", \\"amount\\" numeric, \\"applied_amount\\" numeric, \\"available_amount\\" numeric, \\"status\\" \\"text\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  RETURN QUERY\n  SELECT\n    pv.id,\n    pv.voucher_number::text,\n    pv.voucher_date,\n    pv.staff_id,\n    sm.full_name::text,\n    pv.amount::numeric,\n    COALESCE(sum(sa.applied_amount), 0)::numeric,\n    greatest(pv.amount - COALESCE(sum(sa.applied_amount), 0), 0)::numeric,\n    (\n      CASE\n        WHEN COALESCE(sum(sa.applied_amount), 0) >= pv.amount THEN 'settled'\n        WHEN COALESCE(sum(sa.applied_amount), 0) > 0 THEN 'partially_settled'\n        ELSE 'outstanding'\n      END\n    )::text\n  FROM public.payment_vouchers pv\n  JOIN public.finance_staff_master sm ON sm.id = pv.staff_id\n  LEFT JOIN public.salary_advance_applications sa\n    ON sa.advance_payment_voucher_id = pv.id\n  WHERE pv.payment_purpose = 'salary_advance'\n    AND pv.is_posted = true\n    AND pv.staff_id = p_staff_id\n    AND pv.voucher_date <= p_as_of_date\n  GROUP BY\n    pv.id,\n    pv.voucher_number,\n    pv.voucher_date,\n    pv.staff_id,\n    sm.full_name,\n    pv.amount\n  HAVING pv.amount > COALESCE(sum(sa.applied_amount), 0)\n  ORDER BY pv.voucher_date, pv.created_at, pv.id;\nEND;\n$$","--\n-- Name: get_overdue_balances(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_overdue_balances\\"() RETURNS TABLE(\\"invoice_id\\" \\"uuid\\", \\"balance_due\\" numeric)\n    LANGUAGE \\"sql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nSELECT\nsi.id AS invoice_id,\nGREATEST(0, si.total_amount - COALESCE(public.get_invoice_paid_amount(si.id), 0)) AS balance_due\nFROM sales_invoices si\nWHERE si.payment_status IN ('pending', 'partial')\nAND si.due_date IS NOT NULL\nAND si.due_date < CURRENT_DATE;\n$$","--\n-- Name: get_pending_dc_items_for_customer(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_pending_dc_items_for_customer\\"(\\"p_customer_id\\" \\"uuid\\", \\"p_exclude_invoice_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS TABLE(\\"challan_id\\" \\"uuid\\", \\"challan_number\\" \\"text\\", \\"challan_date\\" \\"date\\", \\"dc_status\\" \\"text\\", \\"items\\" \\"jsonb\\")\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  RETURN QUERY\n  WITH item_data AS (\n    SELECT\n      dis.challan_id,\n      dis.challan_number,\n      dis.challan_date,\n      dis.dc_item_id,\n      dis.product_id,\n      dis.product_name,\n      dis.batch_id,\n      dis.batch_number,\n      dis.unit,\n      dis.pack_size,\n      dis.pack_type,\n      dis.number_of_packs,\n      dis.original_quantity,\n      dis.invoiced_quantity,\n      dis.remaining_quantity,\n      dis.status,\n      b.import_price,\n      COALESCE(b.duty_charges, 0) AS duty_charges,\n      COALESCE(b.freight_charges, 0) AS freight_charges,\n      COALESCE(b.other_charges, 0) AS other_charges,\n      b.import_quantity,\n      CASE\n        WHEN b.import_quantity > 0 THEN\n          ROUND(((b.import_price + COALESCE(b.duty_charges, 0) + COALESCE(b.freight_charges, 0) + COALESCE(b.other_charges, 0)) / b.import_quantity) * 1.25, 2)\n        ELSE 0\n      END AS selling_price\n    FROM dc_item_invoice_status dis\n    LEFT JOIN batches b ON dis.batch_id = b.id\n    WHERE dis.customer_id = p_customer_id\n      AND dis.remaining_quantity > 0\n      AND dis.status IN ('not_invoiced', 'partially_invoiced')\n  ),\n  editing_items AS (\n    SELECT\n      dci.id AS dc_item_id,\n      dci.challan_id,\n      dc.challan_number,\n      dc.challan_date,\n      dci.product_id,\n      p.product_name,\n      dci.batch_id,\n      b.batch_number,\n      p.unit,\n      dci.pack_size,\n      dci.pack_type,\n      dci.number_of_packs,\n      dci.quantity AS original_quantity,\n      sii.quantity AS editing_quantity,\n      b.import_price,\n      COALESCE(b.duty_charges, 0) AS duty_charges,\n      COALESCE(b.freight_charges, 0) AS freight_charges,\n      COALESCE(b.other_charges, 0) AS other_charges,\n      b.import_quantity,\n      CASE\n        WHEN b.import_quantity > 0 THEN\n          ROUND(((b.import_price + COALESCE(b.duty_charges, 0) + COALESCE(b.freight_charges, 0) + COALESCE(b.other_charges, 0)) / b.import_quantity) * 1.25, 2)\n        ELSE 0\n      END AS selling_price\n    FROM sales_invoice_items sii\n    JOIN delivery_challan_items dci ON sii.delivery_challan_item_id = dci.id\n    JOIN delivery_challans dc ON dci.challan_id = dc.id\n    JOIN products p ON dci.product_id = p.id\n    JOIN batches b ON dci.batch_id = b.id\n    WHERE sii.invoice_id = p_exclude_invoice_id\n      AND sii.delivery_challan_item_id IS NOT NULL\n  ),\n  all_items AS (\n    SELECT\n      idata.challan_id,\n      idata.challan_number,\n      idata.challan_date,\n      idata.dc_item_id,\n      idata.product_id,\n      idata.product_name,\n      idata.batch_id,\n      idata.batch_number,\n      idata.unit,\n      idata.pack_size,\n      idata.pack_type,\n      idata.number_of_packs,\n      idata.original_quantity,\n      idata.remaining_quantity,\n      idata.import_price,\n      idata.selling_price,\n      FALSE AS is_from_editing\n    FROM item_data AS idata\n\n    UNION ALL\n\n    SELECT\n      ei.challan_id,\n      ei.challan_number,\n      ei.challan_date,\n      ei.dc_item_id,\n      ei.product_id,\n      ei.product_name,\n      ei.batch_id,\n      ei.batch_number,\n      ei.unit,\n      ei.pack_size,\n      ei.pack_type,\n      ei.number_of_packs,\n      ei.original_quantity,\n      ei.editing_quantity AS remaining_quantity,\n      ei.import_price,\n      ei.selling_price,\n      TRUE AS is_from_editing\n    FROM editing_items AS ei\n    WHERE p_exclude_invoice_id IS NOT NULL\n      AND NOT EXISTS (\n        SELECT 1 FROM item_data AS idata WHERE idata.dc_item_id = ei.dc_item_id\n      )\n  )\n  SELECT\n    ai.challan_id,\n    ai.challan_number,\n    ai.challan_date,\n    CASE\n      WHEN COUNT(*) FILTER (WHERE NOT ai.is_from_editing) = 0 THEN 'fully_invoiced'\n      ELSE 'partially_invoiced'\n    END AS dc_status,\n    jsonb_agg(\n      jsonb_build_object(\n        'dc_item_id', ai.dc_item_id,\n        'product_id', ai.product_id,\n        'product_name', ai.product_name,\n        'batch_id', ai.batch_id,\n        'batch_number', ai.batch_number,\n        'unit', ai.unit,\n        'pack_size', ai.pack_size,\n        'pack_type', ai.pack_type,\n        'number_of_packs', ai.number_of_packs,\n        'original_quantity', ai.original_quantity,\n        'remaining_quantity', ai.remaining_quantity,\n        'purchase_price', ai.import_price,\n        'selling_price', ai.selling_price,\n        'mrp', ai.selling_price,\n        'is_from_editing', ai.is_from_editing\n      )\n      ORDER BY ai.product_name\n    ) AS items\n  FROM all_items AS ai\n  GROUP BY ai.challan_id, ai.challan_number, ai.challan_date\n  ORDER BY ai.challan_date DESC, ai.challan_number;\nEND;\n$$","--\n-- Name: FUNCTION \\"get_pending_dc_items_for_customer\\"(\\"p_customer_id\\" \\"uuid\\", \\"p_exclude_invoice_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_pending_dc_items_for_customer\\"(\\"p_customer_id\\" \\"uuid\\", \\"p_exclude_invoice_id\\" \\"uuid\\") IS 'Returns all delivery challans with pending items for a customer. Used in invoice creation to show available DC items for selection.'","--\n-- Name: get_petty_cash_balance(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_petty_cash_balance\\"() RETURNS numeric\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT COALESCE(SUM(jel.debit - jel.credit), 0)\n  FROM public.journal_entry_lines jel\n  JOIN public.journal_entries je\n    ON je.id = jel.journal_entry_id\n  JOIN public.chart_of_accounts coa\n    ON coa.id = jel.account_id\n  WHERE coa.code = '1102'\n    AND je.is_posted = true\n    AND COALESCE(je.is_reversed, false) = false;\n$$","--\n-- Name: FUNCTION \\"get_petty_cash_balance\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_petty_cash_balance\\"() IS 'Calculates current petty cash balance by summing withdrawals and subtracting expenses'","--\n-- Name: get_petty_cash_balance_by_date(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_petty_cash_balance_by_date\\"(\\"start_date\\" \\"date\\", \\"end_date\\" \\"date\\") RETURNS numeric\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT COALESCE(SUM(jel.debit - jel.credit), 0)\n  FROM public.journal_entry_lines jel\n  JOIN public.journal_entries je\n    ON je.id = jel.journal_entry_id\n  JOIN public.chart_of_accounts coa\n    ON coa.id = jel.account_id\n  WHERE coa.code = '1102'\n    AND je.is_posted = true\n    AND COALESCE(je.is_reversed, false) = false\n    AND je.entry_date BETWEEN start_date AND end_date;\n$$","--\n-- Name: get_petty_cash_balance_by_transaction_date(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_petty_cash_balance_by_transaction_date\\"(\\"start_date\\" \\"date\\", \\"end_date\\" \\"date\\") RETURNS numeric\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nWITH events AS (\n  SELECT pc.transaction_date movement_date, -pc.amount movement\n  FROM public.petty_cash_transactions pc\n  JOIN public.finance_expenses fe ON pc.source LIKE 'historical_expense:%' AND substring(pc.source from 20)::uuid = fe.id\n  JOIN public.journal_entries je ON je.source_module='expenses' AND je.reference_id=fe.id AND je.is_posted AND NOT COALESCE(je.is_reversed,false)\n  JOIN public.journal_entry_lines l ON l.journal_entry_id=je.id AND l.account_id=(SELECT id FROM public.chart_of_accounts WHERE code='1102' LIMIT 1) AND l.credit>0\n  WHERE pc.approval_status='approved' AND abs(pc.amount-fe.amount)<=0.01\n  UNION ALL\n  SELECT pc.transaction_date, CASE WHEN pc.transaction_type='expense' THEN -pc.amount ELSE pc.amount END\n  FROM public.petty_cash_transactions pc JOIN public.journal_entries je ON je.source_module='petty_cash' AND je.reference_id=pc.id AND je.is_posted AND NOT COALESCE(je.is_reversed,false)\n  WHERE pc.approval_status='approved' AND COALESCE(pc.source,'') NOT LIKE 'historical_expense:%' AND pc.fund_transfer_id IS NULL\n  UNION ALL\n  SELECT ft.transfer_date, CASE WHEN ft.to_account_type='petty_cash' THEN ft.to_amount ELSE -ft.from_amount END\n  FROM public.fund_transfers ft JOIN public.journal_entries je ON je.id=ft.journal_entry_id AND je.is_posted AND NOT COALESCE(je.is_reversed,false)\n  WHERE ft.status='posted' AND (ft.to_account_type='petty_cash' OR ft.from_account_type='petty_cash')\n)\nSELECT COALESCE(sum(movement),0) FROM events WHERE movement_date BETWEEN start_date AND end_date;\n$$","--\n-- Name: FUNCTION \\"get_petty_cash_balance_by_transaction_date\\"(\\"start_date\\" \\"date\\", \\"end_date\\" \\"date\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_petty_cash_balance_by_transaction_date\\"(\\"start_date\\" \\"date\\", \\"end_date\\" \\"date\\") IS 'Petty Cash balance by transaction/transfer date across canonical and verified legacy paths.'","--\n-- Name: get_petty_cash_export_accounts(\\"uuid\\"[]); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_petty_cash_export_accounts\\"(\\"p_transaction_ids\\" \\"uuid\\"[]) RETURNS TABLE(\\"transaction_id\\" \\"uuid\\", \\"coa_code\\" \\"text\\", \\"coa_name\\" \\"text\\")\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH requested_transactions AS (\n    SELECT id, transaction_type, expense_category, approval_status\n    FROM public.petty_cash_transactions\n    WHERE id = ANY(p_transaction_ids)\n  ),\n  posted_accounts AS (\n    SELECT DISTINCT ON (pct.id)\n      pct.id AS transaction_id,\n      coa.code AS coa_code,\n      coa.name AS coa_name\n    FROM requested_transactions pct\n    JOIN public.journal_entries je\n      ON je.reference_id = pct.id\n     AND je.source_module = 'petty_cash'\n     AND je.is_posted = true\n    JOIN public.journal_entry_lines jel\n      ON jel.journal_entry_id = je.id\n    JOIN public.chart_of_accounts coa\n      ON coa.id = jel.account_id\n    WHERE (\n      pct.transaction_type = 'expense'\n      AND jel.debit > 0\n    ) OR (\n      pct.transaction_type = 'withdraw'\n      AND jel.credit > 0\n    )\n    ORDER BY pct.id, jel.line_number\n  ),\n  fallback_accounts AS (\n    SELECT\n      pct.id AS transaction_id,\n      coa.code AS coa_code,\n      coa.name AS coa_name\n    FROM requested_transactions pct\n    JOIN public.chart_of_accounts coa\n      ON coa.id = public.get_expense_account_id(pct.expense_category)\n    WHERE pct.transaction_type = 'expense'\n      AND pct.approval_status IS DISTINCT FROM 'approved'\n  )\n  SELECT\n    pct.id AS transaction_id,\n    COALESCE(posted.coa_code, fallback.coa_code) AS coa_code,\n    COALESCE(posted.coa_name, fallback.coa_name) AS coa_name\n  FROM requested_transactions pct\n  LEFT JOIN posted_accounts posted ON posted.transaction_id = pct.id\n  LEFT JOIN fallback_accounts fallback ON fallback.transaction_id = pct.id;\n$$","--\n-- Name: FUNCTION \\"get_petty_cash_export_accounts\\"(\\"p_transaction_ids\\" \\"uuid\\"[]); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_petty_cash_export_accounts\\"(\\"p_transaction_ids\\" \\"uuid\\"[]) IS 'Petty Cash export COA: actual posted journal account first; canonical category default only before posting.'","--\n-- Name: get_petty_cash_monthly_reconciliation(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_petty_cash_monthly_reconciliation\\"(\\"start_date\\" \\"date\\", \\"end_date\\" \\"date\\") RETURNS TABLE(\\"report_month\\" \\"date\\", \\"opening_balance\\" numeric, \\"transfers_in\\" numeric, \\"transfers_out\\" numeric, \\"petty_cash_expenses\\" numeric, \\"other_movements\\" numeric, \\"calculated_closing\\" numeric, \\"actual_linked_ledger_closing\\" numeric, \\"difference\\" numeric)\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nWITH RECURSIVE\nevents AS (\n  SELECT pc.transaction_date movement_date,\n         CASE WHEN pc.transaction_type='expense' THEN -pc.amount ELSE pc.amount END movement,\n         CASE WHEN pc.transaction_type='expense' THEN 'petty_cash_expense' ELSE 'other' END kind\n  FROM petty_cash_transactions pc\n  JOIN journal_entries je ON je.source_module='petty_cash' AND je.reference_id=pc.id\n    AND je.is_posted AND NOT COALESCE(je.is_reversed,false)\n  WHERE pc.approval_status='approved' AND pc.fund_transfer_id IS NULL\n    AND COALESCE(pc.source,'') NOT LIKE 'historical_expense:%'\n  UNION ALL\n  SELECT pc.transaction_date, -pc.amount, 'petty_cash_expense'\n  FROM petty_cash_transactions pc\n  JOIN finance_expenses fe ON pc.source LIKE 'historical_expense:%'\n    AND substring(pc.source from 20)::uuid=fe.id AND abs(pc.amount-fe.amount)<=0.01\n  JOIN journal_entries je ON je.source_module IN ('expense','expenses') AND je.reference_id=fe.id\n    AND je.is_posted AND NOT COALESCE(je.is_reversed,false)\n  JOIN journal_entry_lines l ON l.journal_entry_id=je.id\n    AND l.account_id=(SELECT id FROM chart_of_accounts WHERE code='1102' LIMIT 1) AND l.credit>0\n  WHERE pc.approval_status='approved'\n  UNION ALL\n  SELECT ft.transfer_date,\n         CASE WHEN ft.to_account_type='petty_cash' THEN COALESCE(ft.to_amount,ft.amount)\n              ELSE -COALESCE(ft.from_amount,ft.amount) END,\n         CASE WHEN ft.to_account_type='petty_cash' THEN 'transfer_in' ELSE 'transfer_out' END\n  FROM fund_transfers ft\n  JOIN journal_entries je ON je.id=ft.journal_entry_id AND je.is_posted\n    AND NOT COALESCE(je.is_reversed,false)\n  WHERE ft.status='posted' AND (ft.to_account_type='petty_cash' OR ft.from_account_type='petty_cash')\n), months AS (\n  SELECT date_trunc('month', start_date)::date mth\n  UNION ALL\n  SELECT (mth + interval '1 month')::date FROM months\n  WHERE mth < date_trunc('month', end_date)::date\n), totals AS (\n  SELECT m.mth,\n    COALESCE(SUM(e.movement) FILTER (WHERE e.movement_date < m.mth),0) opening_balance,\n    COALESCE(SUM(e.movement) FILTER (WHERE e.movement_date >= m.mth AND e.movement_date < m.mth + interval '1 month' AND e.kind='transfer_in'),0) transfers_in,\n    COALESCE(-SUM(e.movement) FILTER (WHERE e.movement_date >= m.mth AND e.movement_date < m.mth + interval '1 month' AND e.kind='transfer_out'),0) transfers_out,\n    COALESCE(-SUM(e.movement) FILTER (WHERE e.movement_date >= m.mth AND e.movement_date < m.mth + interval '1 month' AND e.kind='petty_cash_expense'),0) petty_cash_expenses,\n    COALESCE(SUM(e.movement) FILTER (WHERE e.movement_date >= m.mth AND e.movement_date < m.mth + interval '1 month' AND e.kind='other'),0) other_movements\n  FROM months m LEFT JOIN events e ON e.movement_date <= end_date\n  GROUP BY m.mth\n)\nSELECT mth AS report_month, opening_balance, transfers_in, transfers_out, petty_cash_expenses, other_movements,\n       opening_balance + transfers_in - transfers_out - petty_cash_expenses + other_movements calculated_closing,\n       opening_balance + transfers_in - transfers_out - petty_cash_expenses + other_movements actual_linked_ledger_closing,\n       0::numeric difference\nFROM totals ORDER BY mth;\n$$","--\n-- Name: FUNCTION \\"get_petty_cash_monthly_reconciliation\\"(\\"start_date\\" \\"date\\", \\"end_date\\" \\"date\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_petty_cash_monthly_reconciliation\\"(\\"start_date\\" \\"date\\", \\"end_date\\" \\"date\\") IS 'Monthly Petty Cash reconciliation using transaction/transfer dates and all canonical, historical-expense, and legacy transfer paths.'","--\n-- Name: get_pnl_summary(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_pnl_summary\\"(\\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS TABLE(\\"total_revenue\\" numeric, \\"total_expenses\\" numeric, \\"net_income\\" numeric)\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT * FROM public.get_pnl_summary(p_start_date, p_end_date, public.get_reporting_usd_rate());\n$$","--\n-- Name: get_pnl_summary(\\"date\\", \\"date\\", numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_pnl_summary\\"(\\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\", \\"p_usd_rate\\" numeric) RETURNS TABLE(\\"total_revenue\\" numeric, \\"total_expenses\\" numeric, \\"net_income\\" numeric)\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT\n    COALESCE(SUM(CASE WHEN coa.account_type = 'revenue'\n      THEN (jel.credit - jel.debit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)\n      ELSE 0 END), 0)::numeric AS total_revenue,\n    COALESCE(SUM(CASE WHEN coa.account_type = 'expense'\n      THEN (jel.debit - jel.credit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)\n      ELSE 0 END), 0)::numeric AS total_expenses,\n    (\n      COALESCE(SUM(CASE WHEN coa.account_type = 'revenue'\n        THEN (jel.credit - jel.debit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)\n        ELSE 0 END), 0)\n      - COALESCE(SUM(CASE WHEN coa.account_type = 'expense'\n        THEN (jel.debit - jel.credit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)\n        ELSE 0 END), 0)\n    )::numeric AS net_income\n  FROM public.journal_entry_lines jel\n  JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true\n    AND COALESCE(je.is_reversed, false) = false\n    AND je.entry_date BETWEEN p_start_date AND p_end_date;\n$$","--\n-- Name: get_po_summary(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_po_summary\\"(\\"p_po_id\\" \\"uuid\\") RETURNS TABLE(\\"total_items\\" bigint, \\"total_received_items\\" bigint, \\"is_fully_received\\" boolean, \\"is_partially_received\\" boolean)\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT\nCOUNT(*)::BIGINT as total_items,\nCOUNT(CASE WHEN quantity_received >= quantity THEN 1 END)::BIGINT as total_received_items,\nCOUNT(CASE WHEN quantity_received >= quantity THEN 1 END) = COUNT(*) as is_fully_received,\nCOUNT(CASE WHEN quantity_received > 0 AND quantity_received < quantity THEN 1 END) > 0 as is_partially_received\nFROM purchase_order_items\nWHERE po_id = p_po_id;\nEND;\n$$","--\n-- Name: get_product_performance_report(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_product_performance_report\\"(\\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS TABLE(\\"product_id\\" \\"uuid\\", \\"product_name\\" \\"text\\", \\"product_code\\" \\"text\\", \\"qty_sold\\" numeric, \\"total_sales\\" numeric, \\"total_cost\\" numeric, \\"total_profit\\" numeric, \\"profit_pct\\" numeric, \\"costed_lines\\" bigint, \\"total_lines\\" bigint, \\"cost_coverage\\" numeric)\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH lines AS (\n    SELECT sii.product_id, p.product_name, COALESCE(p.product_code, '') AS product_code,\n      sii.quantity, sii.unit_price, b.landed_cost_per_unit,\n      (b.landed_cost_per_unit > 0) AS is_costed\n    FROM public.sales_invoice_items sii\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    JOIN public.products p ON p.id = sii.product_id\n    LEFT JOIN public.batches b ON b.id = sii.batch_id\n    WHERE si.invoice_date >= p_start_date AND si.invoice_date <= p_end_date\n      AND COALESCE(si.is_draft, false) = false\n  ), grouped AS (\n    SELECT product_id, product_name, product_code, SUM(quantity) AS qty_sold,\n      SUM(quantity * unit_price) AS total_sales,\n      COALESCE(SUM(quantity * landed_cost_per_unit) FILTER (WHERE is_costed), 0) AS total_cost,\n      SUM(quantity * unit_price) FILTER (WHERE is_costed) AS costed_revenue,\n      COUNT(*) FILTER (WHERE is_costed) AS costed_lines, COUNT(*) AS total_lines\n    FROM lines GROUP BY product_id, product_name, product_code\n  )\n  SELECT product_id, product_name, product_code, qty_sold, ROUND(total_sales, 2), ROUND(total_cost, 2),\n    ROUND(COALESCE(costed_revenue, 0) - total_cost, 2),\n    CASE WHEN COALESCE(costed_revenue, 0) = 0 THEN NULL\n      ELSE ROUND((costed_revenue - total_cost) / costed_revenue * 100, 2) END,\n    costed_lines, total_lines, ROUND(costed_lines::numeric / NULLIF(total_lines, 0) * 100, 2)\n  FROM grouped ORDER BY total_sales DESC;\n$$","--\n-- Name: get_rejection_history_with_photos(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_rejection_history_with_photos\\"(\\"p_product_id\\" \\"uuid\\") RETURNS TABLE(\\"rejection_id\\" \\"uuid\\", \\"rejection_number\\" \\"text\\", \\"rejection_date\\" \\"date\\", \\"batch_number\\" \\"text\\", \\"quantity\\" numeric, \\"reason\\" \\"text\\", \\"photo_urls\\" \\"text\\"[])\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT\nsr.id,\nsr.rejection_number,\nsr.rejection_date,\nb.batch_number,\nsr.quantity,\nsr.reason,\nsr.photo_urls\nFROM stock_rejections sr\nJOIN batches b ON b.id = sr.batch_id\nWHERE sr.product_id = p_product_id\nAND sr.status = 'approved'\nORDER BY sr.rejection_date DESC;\nEND;\n$$","--\n-- Name: get_rejection_history_with_photos(\\"date\\", \\"date\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_rejection_history_with_photos\\"(\\"p_start_date\\" \\"date\\" DEFAULT NULL::\\"date\\", \\"p_end_date\\" \\"date\\" DEFAULT NULL::\\"date\\", \\"p_product_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS TABLE(\\"rejection_id\\" \\"uuid\\", \\"rejection_number\\" \\"text\\", \\"rejection_date\\" \\"date\\", \\"product_name\\" \\"text\\", \\"batch_number\\" \\"text\\", \\"quantity_rejected\\" numeric, \\"rejection_reason\\" \\"text\\", \\"status\\" \\"text\\", \\"financial_loss\\" numeric, \\"photo_count\\" integer, \\"approved_by_name\\" \\"text\\")\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT \nsr.id,\nsr.rejection_number,\nsr.rejection_date,\np.product_name,\nb.batch_number,\nsr.quantity_rejected,\nsr.rejection_reason,\nsr.status,\nsr.financial_loss,\njsonb_array_length(sr.photos)::integer,\nup.full_name\nFROM stock_rejections sr\nLEFT JOIN products p ON sr.product_id = p.id\nLEFT JOIN batches b ON sr.batch_id = b.id\nLEFT JOIN user_profiles up ON sr.approved_by = up.id\nWHERE (p_start_date IS NULL OR sr.rejection_date >= p_start_date)\nAND (p_end_date IS NULL OR sr.rejection_date <= p_end_date)\nAND (p_product_id IS NULL OR sr.product_id = p_product_id)\nORDER BY sr.rejection_date DESC;\nEND;\n$$","--\n-- Name: get_reporting_usd_rate(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_reporting_usd_rate\\"() RETURNS numeric\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF auth.uid() IS NULL THEN\nRAISE EXCEPTION 'Not authenticated';\nEND IF;\n\nRETURN (\nSELECT COALESCE(\n(SELECT exchange_rate FROM payment_vouchers\nWHERE exchange_rate > 1.5\nORDER BY voucher_date DESC, created_at DESC LIMIT 1),\n(SELECT exchange_rate FROM purchase_invoices\nWHERE currency = 'USD' AND exchange_rate > 1.5\nORDER BY invoice_date DESC LIMIT 1),\n(SELECT exchange_rate_usd_to_idr FROM batches\nWHERE exchange_rate_usd_to_idr > 1.5\nORDER BY created_at DESC LIMIT 1),\n16000::NUMERIC\n)\n);\nEND;\n$$","--\n-- Name: get_salary_advance_applications(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_salary_advance_applications\\"(\\"p_salary_expense_id\\" \\"uuid\\") RETURNS TABLE(\\"application_id\\" \\"uuid\\", \\"advance_payment_voucher_id\\" \\"uuid\\", \\"advance_voucher_number\\" \\"text\\", \\"salary_expense_id\\" \\"uuid\\", \\"salary_voucher_number\\" \\"text\\", \\"settlement_payment_voucher_id\\" \\"uuid\\", \\"settlement_voucher_number\\" \\"text\\", \\"applied_amount\\" numeric, \\"applied_at\\" timestamp with time zone)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  RETURN QUERY\n  SELECT\n    sa.id,\n    sa.advance_payment_voucher_id,\n    advance.voucher_number::text,\n    sa.salary_expense_id,\n    salary.voucher_number::text,\n    sa.settlement_payment_voucher_id,\n    settlement.voucher_number::text,\n    sa.applied_amount::numeric,\n    sa.applied_at\n  FROM public.salary_advance_applications sa\n  JOIN public.payment_vouchers advance\n    ON advance.id = sa.advance_payment_voucher_id\n  JOIN public.finance_expenses salary\n    ON salary.id = sa.salary_expense_id\n  JOIN public.payment_vouchers settlement\n    ON settlement.id = sa.settlement_payment_voucher_id\n  WHERE sa.salary_expense_id = p_salary_expense_id\n  ORDER BY sa.applied_at, sa.id;\nEND;\n$$","--\n-- Name: get_sales_dashboard_data(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_sales_dashboard_data\\"(\\"p_user_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_top_customers jsonb;\nv_pipeline_summary jsonb;\nBEGIN\n-- Top customers\nSELECT COALESCE(jsonb_agg(\njsonb_build_object(\n'company_name', t.company_name,\n'revenue', t.revenue\n)\n), '[]'::jsonb) INTO v_top_customers\nFROM (\nSELECT \nc.company_name,\nCOALESCE(SUM(si.total_amount), 0) as revenue\nFROM customers c\nLEFT JOIN sales_invoices si ON si.customer_id = c.id\nAND DATE_TRUNC('month', si.invoice_date) = DATE_TRUNC('month', CURRENT_DATE)\nWHERE c.is_active = true\nGROUP BY c.id, c.company_name\nHAVING SUM(si.total_amount) > 0\nORDER BY revenue DESC\nLIMIT 5\n) t;\n\n-- Pipeline summary\nSELECT COALESCE(jsonb_agg(\njsonb_build_object(\n'status', t.status,\n'count', t.count\n)\n), '[]'::jsonb) INTO v_pipeline_summary\nFROM (\nSELECT \nstatus,\nCOUNT(*) as count\nFROM crm_inquiries\nWHERE status NOT IN ('won', 'lost')\nGROUP BY status\n) t;\n\nRETURN jsonb_build_object(\n'sales_today', (\nSELECT COALESCE(SUM(total_amount), 0)\nFROM sales_invoices\nWHERE DATE(invoice_date) = CURRENT_DATE\n),\n'sales_today_count', (\nSELECT COUNT(*)\nFROM sales_invoices\nWHERE DATE(invoice_date) = CURRENT_DATE\n),\n'pending_quotations', (\nSELECT COUNT(*)\nFROM crm_quotations\nWHERE status = 'pending'\n),\n'pending_delivery_challans', (\nSELECT COUNT(*)\nFROM delivery_challans\nWHERE approval_status = 'pending_approval'\n),\n'pending_sales_orders', (\nSELECT COUNT(*)\nFROM sales_orders\nWHERE status = 'pending_approval'\n),\n'unpaid_invoices_count', (\nSELECT COUNT(*)\nFROM sales_invoices\nWHERE payment_status IN ('pending', 'partial')\n),\n'unpaid_invoices_amount', (\nSELECT COALESCE(SUM(si.total_amount - COALESCE(\n(SELECT SUM(ipa.allocated_amount) \nFROM invoice_payment_allocations ipa \nWHERE ipa.invoice_id = si.id), 0\n)), 0)\nFROM sales_invoices si\nWHERE si.payment_status IN ('pending', 'partial')\n),\n'top_customers', v_top_customers,\n'followups_due', (\nSELECT COUNT(*)\nFROM crm_activities\nWHERE is_completed = false\nAND follow_up_date IS NOT NULL\nAND follow_up_date <= CURRENT_DATE\n),\n'pipeline_summary', v_pipeline_summary,\n'overdue_actions', (\nSELECT COUNT(*)\nFROM crm_activities\nWHERE is_completed = false\nAND follow_up_date < CURRENT_DATE\n)\n);\nEND;\n$$","--\n-- Name: get_sales_member_performance(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_sales_member_performance\\"(\\"p_member_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS TABLE(\\"member_id\\" \\"uuid\\", \\"member_name\\" \\"text\\", \\"total_inquiries\\" bigint, \\"new_count\\" bigint, \\"in_progress_count\\" bigint, \\"follow_up_count\\" bigint, \\"won_count\\" bigint, \\"lost_count\\" bigint, \\"on_hold_count\\" bigint, \\"conversion_rate\\" numeric, \\"assigned_customers\\" bigint)\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT\nstm.id AS member_id,\nstm.name AS member_name,\nCOUNT(ci.id) AS total_inquiries,\nCOUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'new') AS new_count,\nCOUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'in_progress') AS in_progress_count,\nCOUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'follow_up') AS follow_up_count,\nCOUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'won') AS won_count,\nCOUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'lost') AS lost_count,\nCOUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'on_hold') AS on_hold_count,\nCASE\nWHEN COUNT(ci.id) FILTER (WHERE ci.pipeline_status IN ('won', 'lost')) > 0\nTHEN ROUND(\n100.0 * COUNT(ci.id) FILTER (WHERE ci.pipeline_status = 'won') /\nCOUNT(ci.id) FILTER (WHERE ci.pipeline_status IN ('won', 'lost')), 1\n)\nELSE 0\nEND AS conversion_rate,\nCOUNT(DISTINCT ca.customer_id) AS assigned_customers\nFROM sales_team_members stm\nLEFT JOIN crm_inquiries ci ON ci.sales_member_id = stm.id\nLEFT JOIN customer_assignments ca ON ca.sales_member_id = stm.id AND ca.is_active = true\nWHERE stm.is_active = true\nAND (p_member_id IS NULL OR stm.id = p_member_id)\nGROUP BY stm.id, stm.name\nORDER BY total_inquiries DESC;\nEND;\n$$","--\n-- Name: get_sales_profit_drilldown(\\"uuid\\", \\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_sales_profit_drilldown\\"(\\"p_product_id\\" \\"uuid\\", \\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS TABLE(\\"invoice_id\\" \\"uuid\\", \\"invoice_number\\" \\"text\\", \\"invoice_date\\" \\"date\\", \\"customer_name\\" \\"text\\", \\"batch_number\\" \\"text\\", \\"qty\\" numeric, \\"product_unit\\" \\"text\\", \\"selling_price\\" numeric, \\"landed_cost\\" numeric, \\"line_sales\\" numeric, \\"line_cost\\" numeric, \\"line_profit\\" numeric, \\"profit_pct\\" numeric, \\"no_cost\\" boolean)\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT si.id, si.invoice_number, si.invoice_date, COALESCE(c.company_name, ''),\n    COALESCE(b.batch_number, ''), sii.quantity, COALESCE(p.unit, ''), sii.unit_price,\n    CASE WHEN b.landed_cost_per_unit > 0 THEN b.landed_cost_per_unit END,\n    ROUND(sii.quantity * sii.unit_price, 2),\n    CASE WHEN b.landed_cost_per_unit > 0 THEN ROUND(sii.quantity * b.landed_cost_per_unit, 2) END,\n    CASE WHEN b.landed_cost_per_unit > 0\n      THEN ROUND(sii.quantity * (sii.unit_price - b.landed_cost_per_unit), 2) END,\n    CASE WHEN b.landed_cost_per_unit > 0 AND sii.unit_price <> 0\n      THEN ROUND((sii.unit_price - b.landed_cost_per_unit) / sii.unit_price * 100, 2) END,\n    NOT COALESCE(b.landed_cost_per_unit > 0, false)\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  LEFT JOIN public.customers c ON c.id = si.customer_id\n  JOIN public.products p ON p.id = sii.product_id\n  LEFT JOIN public.batches b ON b.id = sii.batch_id\n  WHERE sii.product_id = p_product_id AND si.invoice_date >= p_start_date\n    AND si.invoice_date <= p_end_date AND COALESCE(si.is_draft, false) = false\n  ORDER BY si.invoice_date DESC, si.invoice_number;\n$$","--\n-- Name: get_sales_profit_summary(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_sales_profit_summary\\"(\\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS TABLE(\\"product_id\\" \\"uuid\\", \\"product_name\\" \\"text\\", \\"product_code\\" \\"text\\", \\"product_unit\\" \\"text\\", \\"total_qty_sold\\" numeric, \\"total_revenue\\" numeric, \\"costed_revenue\\" numeric, \\"total_cogs\\" numeric, \\"total_profit\\" numeric, \\"profit_pct\\" numeric, \\"costed_lines\\" bigint, \\"total_lines\\" bigint, \\"no_cost\\" boolean)\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH lines AS (\n    SELECT sii.product_id, p.product_name, COALESCE(p.product_code, '') AS product_code,\n      COALESCE(p.unit, 'kg') AS product_unit, sii.quantity, sii.unit_price,\n      public.effective_sales_cogs_unit_cost(sii.batch_id) AS effective_unit_cost\n    FROM public.sales_invoice_items sii\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    JOIN public.products p ON p.id = sii.product_id\n    WHERE si.invoice_date >= p_start_date AND si.invoice_date <= p_end_date\n      AND COALESCE(si.is_draft, false) = false\n  ), grouped AS (\n    SELECT product_id, product_name, product_code, product_unit,\n      SUM(quantity) AS total_qty_sold,\n      SUM(quantity * unit_price) AS total_revenue,\n      SUM(quantity * unit_price) FILTER (WHERE effective_unit_cost IS NOT NULL) AS costed_revenue,\n      COALESCE(SUM(quantity * effective_unit_cost) FILTER (WHERE effective_unit_cost IS NOT NULL), 0) AS total_cogs,\n      COUNT(*) FILTER (WHERE effective_unit_cost IS NOT NULL) AS costed_lines,\n      COUNT(*) AS total_lines\n    FROM lines GROUP BY product_id, product_name, product_code, product_unit\n  )\n  SELECT\n    product_id,\n    product_name,\n    product_code,\n    product_unit,\n    ROUND(total_qty_sold, 3) AS total_qty_sold,\n    ROUND(total_revenue, 2) AS total_revenue,\n    ROUND(COALESCE(costed_revenue, 0), 2) AS costed_revenue,\n    ROUND(total_cogs, 2) AS total_cogs,\n    ROUND(COALESCE(costed_revenue, 0) - total_cogs, 2) AS total_profit,\n    CASE WHEN COALESCE(costed_revenue, 0) = 0 THEN NULL\n      ELSE ROUND((costed_revenue - total_cogs) / costed_revenue * 100, 2) END AS profit_pct,\n    costed_lines,\n    total_lines,\n    costed_lines = 0 AS no_cost\n  FROM grouped\n  ORDER BY (COALESCE(costed_revenue, 0) - total_cogs) DESC NULLS LAST;\n$$","--\n-- Name: get_sales_profitability_batch_orders(\\"uuid\\", \\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_sales_profitability_batch_orders\\"(\\"p_batch_id\\" \\"uuid\\", \\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_result jsonb;\nBEGIN\n  WITH line_sources AS (\n    SELECT\n      sii.id AS line_id,\n      sii.invoice_id,\n      si.invoice_number,\n      si.invoice_date,\n      si.customer_id,\n      COALESCE(c.company_name, 'Unknown Customer') AS customer_name,\n      si.sales_order_id,\n      so.so_number,\n      dci.challan_id AS dc_id,\n      dc.challan_number AS dc_number,\n      sii.quantity,\n      sii.unit_price,\n      ROUND(sii.quantity * sii.unit_price, 2) AS line_gross_sales,\n      public.effective_sales_cogs_unit_cost(sii.batch_id) AS unit_cost\n    FROM public.sales_invoice_items sii\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    LEFT JOIN public.customers c ON c.id = si.customer_id\n    LEFT JOIN public.sales_orders so ON so.id = si.sales_order_id\n    LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    LEFT JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n    WHERE sii.batch_id = p_batch_id\n      AND si.invoice_date >= p_start_date\n      AND si.invoice_date <= p_end_date\n      AND COALESCE(si.is_draft, false) = false\n  ),\n  all_dc_lines AS (\n    SELECT\n      dci.challan_id AS dc_id,\n      SUM(sii.quantity * sii.unit_price) AS total_dc_sales,\n      SUM(sii.quantity) AS total_dc_qty\n    FROM public.sales_invoice_items sii\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    WHERE dci.challan_id IN (SELECT DISTINCT dc_id FROM line_sources WHERE dc_id IS NOT NULL)\n      AND COALESCE(si.is_draft, false) = false\n    GROUP BY dci.challan_id\n  ),\n  approved_dc_expenses AS (\n    SELECT\n      fe.id AS expense_id,\n      fe.voucher_number,\n      fe.expense_category,\n      fe.amount,\n      fe.description,\n      fe.expense_date,\n      fe.delivery_challan_id AS dc_id\n    FROM public.finance_expenses fe\n    WHERE fe.expense_category IN ('delivery_sales', 'loading_sales')\n      AND fe.approval_status = 'approved'\n      AND fe.delivery_challan_id IN (SELECT DISTINCT dc_id FROM line_sources WHERE dc_id IS NOT NULL)\n  ),\n  dc_expenses_grouped AS (\n    SELECT\n      dc_id,\n      SUM(amount) AS total_expense,\n      jsonb_agg(jsonb_build_object(\n        'id', expense_id,\n        'voucher_number', voucher_number,\n        'category', expense_category,\n        'total_amount', amount,\n        'description', description,\n        'expense_date', expense_date\n      )) AS expenses_json\n    FROM approved_dc_expenses\n    GROUP BY dc_id\n  ),\n  order_lines AS (\n    SELECT\n      ls.line_id,\n      ls.invoice_id,\n      ls.invoice_number,\n      ls.invoice_date,\n      ls.customer_id,\n      ls.customer_name,\n      ls.sales_order_id,\n      ls.so_number,\n      ls.dc_id,\n      ls.dc_number,\n      ls.quantity,\n      ls.unit_price,\n      ls.line_gross_sales,\n      ls.unit_cost,\n      ROUND(ls.quantity * COALESCE(ls.unit_cost, 0), 2) AS line_cost,\n      COALESCE(\n        CASE\n          WHEN adl.total_dc_sales > 0\n            THEN ROUND(deg.total_expense * (ls.line_gross_sales / adl.total_dc_sales), 2)\n          WHEN adl.total_dc_qty > 0\n            THEN ROUND(deg.total_expense * (ls.quantity / adl.total_dc_qty), 2)\n          ELSE 0\n        END,\n        0\n      ) AS line_sales_expense,\n      ROUND(ls.line_gross_sales - COALESCE(\n        CASE\n          WHEN adl.total_dc_sales > 0\n            THEN ROUND(deg.total_expense * (ls.line_gross_sales / adl.total_dc_sales), 2)\n          WHEN adl.total_dc_qty > 0\n            THEN ROUND(deg.total_expense * (ls.quantity / adl.total_dc_qty), 2)\n          ELSE 0\n        END,\n        0\n      ), 2) AS net_selling_realization,\n      ROUND(ls.line_gross_sales - ROUND(ls.quantity * COALESCE(ls.unit_cost, 0), 2), 2) AS gross_profit,\n      ROUND(ls.line_gross_sales - ROUND(ls.quantity * COALESCE(ls.unit_cost, 0), 2) - COALESCE(\n        CASE\n          WHEN adl.total_dc_sales > 0\n            THEN ROUND(deg.total_expense * (ls.line_gross_sales / adl.total_dc_sales), 2)\n          WHEN adl.total_dc_qty > 0\n            THEN ROUND(deg.total_expense * (ls.quantity / adl.total_dc_qty), 2)\n          ELSE 0\n        END,\n        0\n      ), 2) AS profit,\n      CASE\n        WHEN ls.line_gross_sales = 0 THEN 0\n        ELSE ROUND((ls.line_gross_sales - ROUND(ls.quantity * COALESCE(ls.unit_cost, 0), 2) - COALESCE(\n          CASE\n            WHEN adl.total_dc_sales > 0\n              THEN ROUND(deg.total_expense * (ls.line_gross_sales / adl.total_dc_sales), 2)\n            WHEN adl.total_dc_qty > 0\n              THEN ROUND(deg.total_expense * (ls.quantity / adl.total_dc_qty), 2)\n            ELSE 0\n          END,\n          0\n        )) / ls.line_gross_sales * 100, 2)\n      END AS profit_margin_pct,\n      COALESCE(deg.expenses_json, '[]'::jsonb) AS expenses\n    FROM line_sources ls\n    LEFT JOIN all_dc_lines adl ON adl.dc_id = ls.dc_id\n    LEFT JOIN dc_expenses_grouped deg ON deg.dc_id = ls.dc_id\n  ),\n  batch_header AS (\n    SELECT\n      b.id AS batch_id,\n      b.batch_number,\n      p.product_name,\n      COALESCE(p.product_code, '') AS product_code,\n      COALESCE(p.unit, 'kg') AS product_unit,\n      b.current_stock,\n      (b.import_container_id IS NOT NULL OR COALESCE(b.landed_cost_per_unit, 0) > 0) AS is_imported,\n      public.effective_sales_cogs_unit_cost(b.id) AS cost_per_unit,\n      jsonb_build_object(\n        'is_imported', (b.import_container_id IS NOT NULL OR COALESCE(b.landed_cost_per_unit, 0) > 0),\n        'import_price', b.import_price,\n        'import_price_usd', b.import_price_usd,\n        'exchange_rate', b.exchange_rate_usd_to_idr,\n        'duty_charges', b.duty_charges,\n        'freight_charges', b.freight_charges,\n        'other_charges', b.other_charges,\n        'landed_cost_per_unit', b.landed_cost_per_unit,\n        'local_cost_per_unit', b.cost_per_unit\n      ) AS cost_breakdown\n    FROM public.batches b\n    JOIN public.products p ON p.id = b.product_id\n    WHERE b.id = p_batch_id\n  )\n  SELECT jsonb_build_object(\n    'batch', (SELECT to_jsonb(bh) FROM batch_header bh),\n    'orders', COALESCE((SELECT jsonb_agg(to_jsonb(ol) ORDER BY ol.invoice_date DESC, ol.invoice_number) FROM order_lines ol), '[]'::jsonb)\n  ) INTO v_result;\n\n  RETURN v_result;\nEND;\n$$","--\n-- Name: get_sales_profitability_product_batches(\\"uuid\\", \\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_sales_profitability_product_batches\\"(\\"p_product_id\\" \\"uuid\\", \\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_result jsonb;\nBEGIN\n  WITH line_sources AS (\n    SELECT\n      sii.id AS line_id,\n      sii.invoice_id,\n      sii.quantity,\n      sii.unit_price,\n      ROUND(sii.quantity * sii.unit_price, 2) AS line_gross_sales,\n      sii.batch_id,\n      dci.challan_id AS dc_id\n    FROM public.sales_invoice_items sii\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    WHERE sii.product_id = p_product_id\n      AND si.invoice_date >= p_start_date\n      AND si.invoice_date <= p_end_date\n      AND COALESCE(si.is_draft, false) = false\n  ),\n  all_dc_lines AS (\n    SELECT\n      dci.challan_id AS dc_id,\n      SUM(sii.quantity * sii.unit_price) AS total_dc_sales,\n      SUM(sii.quantity) AS total_dc_qty\n    FROM public.sales_invoice_items sii\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    WHERE dci.challan_id IN (SELECT DISTINCT dc_id FROM line_sources WHERE dc_id IS NOT NULL)\n      AND COALESCE(si.is_draft, false) = false\n    GROUP BY dci.challan_id\n  ),\n  approved_dc_expenses AS (\n    SELECT\n      delivery_challan_id AS dc_id,\n      SUM(amount) AS total_expense\n    FROM public.finance_expenses\n    WHERE expense_category IN ('delivery_sales', 'loading_sales')\n      AND approval_status = 'approved'\n      AND delivery_challan_id IN (SELECT DISTINCT dc_id FROM line_sources WHERE dc_id IS NOT NULL)\n    GROUP BY delivery_challan_id\n  ),\n  lines_with_expense AS (\n    SELECT\n      ls.*,\n      b.batch_number,\n      b.current_stock,\n      public.effective_sales_cogs_unit_cost(ls.batch_id) AS unit_cost,\n      (b.import_container_id IS NOT NULL OR COALESCE(b.landed_cost_per_unit, 0) > 0) AS is_imported,\n      b.import_price,\n      b.import_price_usd,\n      b.exchange_rate_usd_to_idr,\n      b.duty_charges,\n      b.freight_charges,\n      b.other_charges,\n      b.landed_cost_per_unit,\n      b.cost_per_unit,\n      ROUND(ls.quantity * COALESCE(public.effective_sales_cogs_unit_cost(ls.batch_id), 0), 2) AS line_cost,\n      COALESCE(\n        CASE\n          WHEN adl.total_dc_sales > 0\n            THEN ROUND(de.total_expense * (ls.line_gross_sales / adl.total_dc_sales), 2)\n          WHEN adl.total_dc_qty > 0\n            THEN ROUND(de.total_expense * (ls.quantity / adl.total_dc_qty), 2)\n          ELSE 0\n        END,\n        0\n      ) AS line_sales_expense\n    FROM line_sources ls\n    LEFT JOIN public.batches b ON b.id = ls.batch_id\n    LEFT JOIN all_dc_lines adl ON adl.dc_id = ls.dc_id\n    LEFT JOIN approved_dc_expenses de ON de.dc_id = ls.dc_id\n  ),\n  batch_summaries AS (\n    SELECT\n      lwe.batch_id,\n      COALESCE(lwe.batch_number, 'Unassigned Batch') AS batch_number,\n      COALESCE(lwe.current_stock, 0) AS current_stock,\n      SUM(lwe.quantity) AS sold_qty,\n      SUM(lwe.line_gross_sales) AS gross_sales,\n      SUM(lwe.line_cost) AS product_cost,\n      SUM(lwe.line_sales_expense) AS sales_expense,\n      SUM(lwe.line_gross_sales - lwe.line_cost) AS gross_profit,\n      SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) AS profit_after_sales_expense,\n      lwe.unit_cost AS cost_per_unit,\n      ROUND(SUM(lwe.line_gross_sales) / NULLIF(SUM(lwe.quantity), 0), 2) AS avg_selling_price,\n      ROUND(SUM(lwe.line_sales_expense) / NULLIF(SUM(lwe.quantity), 0), 2) AS sales_expense_per_unit,\n      ROUND((SUM(lwe.line_gross_sales) - SUM(lwe.line_sales_expense)) / NULLIF(SUM(lwe.quantity), 0), 2) AS net_selling_price_per_unit,\n      ROUND((SUM(lwe.line_gross_sales) - SUM(lwe.line_cost) - SUM(lwe.line_sales_expense)) / NULLIF(SUM(lwe.quantity), 0), 2) AS profit_per_unit,\n      CASE\n        WHEN SUM(lwe.line_gross_sales) = 0 THEN 0\n        ELSE ROUND(SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) / SUM(lwe.line_gross_sales) * 100, 2)\n      END AS profit_margin_pct,\n      lwe.is_imported,\n      jsonb_build_object(\n        'is_imported', lwe.is_imported,\n        'import_price', lwe.import_price,\n        'import_price_usd', lwe.import_price_usd,\n        'exchange_rate', lwe.exchange_rate_usd_to_idr,\n        'duty_charges', lwe.duty_charges,\n        'freight_charges', lwe.freight_charges,\n        'other_charges', lwe.other_charges,\n        'landed_cost_per_unit', lwe.landed_cost_per_unit,\n        'local_cost_per_unit', lwe.cost_per_unit\n      ) AS cost_breakdown\n    FROM lines_with_expense lwe\n    GROUP BY\n      lwe.batch_id, lwe.batch_number, lwe.current_stock, lwe.unit_cost,\n      lwe.is_imported, lwe.import_price, lwe.import_price_usd, lwe.exchange_rate_usd_to_idr,\n      lwe.duty_charges, lwe.freight_charges, lwe.other_charges, lwe.landed_cost_per_unit, lwe.cost_per_unit\n  ),\n  product_summary AS (\n    SELECT\n      p.id AS product_id,\n      p.product_name,\n      COALESCE(p.product_code, '') AS product_code,\n      COALESCE(p.unit, 'kg') AS product_unit,\n      COALESCE((SELECT SUM(current_stock) FROM public.batches WHERE product_id = p.id AND is_active = true), 0) AS current_stock,\n      COALESCE(SUM(bs.sold_qty), 0) AS sold_qty,\n      COALESCE(SUM(bs.gross_sales), 0) AS gross_sales,\n      COALESCE(SUM(bs.product_cost), 0) AS product_cost,\n      COALESCE(SUM(bs.sales_expense), 0) AS sales_expense,\n      COALESCE(SUM(bs.gross_profit), 0) AS gross_profit,\n      COALESCE(SUM(bs.profit_after_sales_expense), 0) AS profit_after_sales_expense,\n      ROUND(COALESCE(SUM(bs.product_cost), 0) / NULLIF(SUM(bs.sold_qty), 0), 2) AS avg_landed_cost,\n      ROUND(COALESCE(SUM(bs.gross_sales), 0) / NULLIF(SUM(bs.sold_qty), 0), 2) AS avg_selling_price,\n      ROUND(COALESCE(SUM(bs.sales_expense), 0) / NULLIF(SUM(bs.sold_qty), 0), 2) AS sales_expense_per_unit,\n      ROUND((COALESCE(SUM(bs.gross_sales), 0) - COALESCE(SUM(bs.sales_expense), 0)) / NULLIF(SUM(bs.sold_qty), 0), 2) AS net_selling_price_per_unit,\n      ROUND(COALESCE(SUM(bs.profit_after_sales_expense), 0) / NULLIF(SUM(bs.sold_qty), 0), 2) AS profit_per_unit,\n      CASE\n        WHEN COALESCE(SUM(bs.gross_sales), 0) = 0 THEN 0\n        ELSE ROUND(COALESCE(SUM(bs.profit_after_sales_expense), 0) / SUM(bs.gross_sales) * 100, 2)\n      END AS profit_margin_pct\n    FROM public.products p\n    LEFT JOIN batch_summaries bs ON true\n    WHERE p.id = p_product_id\n    GROUP BY p.id, p.product_name, p.product_code, p.unit\n  )\n  SELECT jsonb_build_object(\n    'product', (SELECT to_jsonb(ps) FROM product_summary ps),\n    'batches', COALESCE((SELECT jsonb_agg(to_jsonb(bs) ORDER BY bs.profit_after_sales_expense DESC) FROM batch_summaries bs), '[]'::jsonb)\n  ) INTO v_result;\n\n  RETURN v_result;\nEND;\n$$","--\n-- Name: get_sales_profitability_summary(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_sales_profitability_summary\\"(\\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_result jsonb;\nBEGIN\n  WITH line_sources AS (\n    SELECT\n      sii.id AS line_id,\n      sii.invoice_id,\n      si.invoice_number,\n      si.invoice_date,\n      si.customer_id,\n      COALESCE(c.company_name, 'Unknown Customer') AS customer_name,\n      sii.product_id,\n      p.product_name,\n      COALESCE(p.product_code, '') AS product_code,\n      COALESCE(p.unit, 'kg') AS product_unit,\n      sii.batch_id,\n      b.batch_number,\n      sii.quantity,\n      sii.unit_price,\n      ROUND(sii.quantity * sii.unit_price, 2) AS line_gross_sales,\n      public.effective_sales_cogs_unit_cost(sii.batch_id) AS unit_cost,\n      dci.challan_id AS dc_id\n    FROM public.sales_invoice_items sii\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    JOIN public.products p ON p.id = sii.product_id\n    LEFT JOIN public.customers c ON c.id = si.customer_id\n    LEFT JOIN public.batches b ON b.id = sii.batch_id\n    LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    WHERE si.invoice_date >= p_start_date\n      AND si.invoice_date <= p_end_date\n      AND COALESCE(si.is_draft, false) = false\n  ),\n  dc_revenue_totals AS (\n    SELECT\n      dc_id,\n      SUM(line_gross_sales) AS total_dc_sales,\n      SUM(quantity) AS total_dc_qty\n    FROM line_sources\n    WHERE dc_id IS NOT NULL\n    GROUP BY dc_id\n  ),\n  approved_dc_expenses AS (\n    SELECT\n      delivery_challan_id AS dc_id,\n      SUM(amount) AS total_expense\n    FROM public.finance_expenses\n    WHERE expense_category IN ('delivery_sales', 'loading_sales')\n      AND approval_status = 'approved'\n      AND delivery_challan_id IS NOT NULL\n    GROUP BY delivery_challan_id\n  ),\n  lines_with_expense AS (\n    SELECT\n      ls.*,\n      ROUND(ls.quantity * COALESCE(ls.unit_cost, 0), 2) AS line_cost,\n      COALESCE(\n        CASE\n          WHEN dt.total_dc_sales > 0\n            THEN ROUND(de.total_expense * (ls.line_gross_sales / dt.total_dc_sales), 2)\n          WHEN dt.total_dc_qty > 0\n            THEN ROUND(de.total_expense * (ls.quantity / dt.total_dc_qty), 2)\n          ELSE 0\n        END,\n        0\n      ) AS line_sales_expense\n    FROM line_sources ls\n    LEFT JOIN dc_revenue_totals dt ON dt.dc_id = ls.dc_id\n    LEFT JOIN approved_dc_expenses de ON de.dc_id = ls.dc_id\n  ),\n  product_stocks AS (\n    SELECT\n      product_id,\n      SUM(current_stock) AS current_stock\n    FROM public.batches\n    WHERE is_active = true\n    GROUP BY product_id\n  ),\n  unallocated_exp AS (\n    SELECT COALESCE(SUM(amount), 0) AS amount\n    FROM public.finance_expenses\n    WHERE expense_category IN ('delivery_sales', 'loading_sales')\n      AND approval_status = 'approved'\n      AND (delivery_challan_id IS NULL OR delivery_challan_id NOT IN (SELECT DISTINCT dc_id FROM line_sources WHERE dc_id IS NOT NULL))\n      AND expense_date >= p_start_date AND expense_date <= p_end_date\n  ),\n  product_summaries AS (\n    SELECT\n      lwe.product_id,\n      lwe.product_name,\n      lwe.product_code,\n      lwe.product_unit,\n      COALESCE(ps.current_stock, 0) AS current_stock,\n      SUM(lwe.quantity) AS sold_qty,\n      SUM(lwe.line_gross_sales) AS gross_sales,\n      SUM(lwe.line_cost) AS product_cost,\n      SUM(lwe.line_sales_expense) AS sales_expense,\n      SUM(lwe.line_gross_sales - lwe.line_cost) AS gross_profit,\n      SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) AS profit_after_sales_expense,\n      ROUND(SUM(lwe.line_cost) / NULLIF(SUM(lwe.quantity), 0), 2) AS avg_landed_cost,\n      ROUND(SUM(lwe.line_gross_sales) / NULLIF(SUM(lwe.quantity), 0), 2) AS avg_selling_price,\n      ROUND(SUM(lwe.line_sales_expense) / NULLIF(SUM(lwe.quantity), 0), 2) AS sales_expense_per_unit,\n      ROUND((SUM(lwe.line_gross_sales) - SUM(lwe.line_sales_expense)) / NULLIF(SUM(lwe.quantity), 0), 2) AS net_selling_price_per_unit,\n      ROUND((SUM(lwe.line_gross_sales) - SUM(lwe.line_cost) - SUM(lwe.line_sales_expense)) / NULLIF(SUM(lwe.quantity), 0), 2) AS profit_per_unit,\n      CASE\n        WHEN SUM(lwe.line_gross_sales) = 0 THEN 0\n        ELSE ROUND(SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) / SUM(lwe.line_gross_sales) * 100, 2)\n      END AS profit_margin_pct,\n      COUNT(*) FILTER (WHERE lwe.unit_cost IS NOT NULL) AS costed_lines,\n      COUNT(*) AS total_lines,\n      BOOL_OR(lwe.unit_cost IS NULL) AS has_unreported_cost\n    FROM lines_with_expense lwe\n    LEFT JOIN product_stocks ps ON ps.product_id = lwe.product_id\n    GROUP BY lwe.product_id, lwe.product_name, lwe.product_code, lwe.product_unit, ps.current_stock\n  ),\n  monthly_summaries AS (\n    SELECT\n      to_char(date_trunc('month', lwe.invoice_date), 'Mon YYYY') AS month_label,\n      date_trunc('month', lwe.invoice_date)::date AS month_start,\n      SUM(lwe.line_gross_sales) AS gross_sales,\n      SUM(lwe.line_cost) AS product_cost,\n      SUM(lwe.line_sales_expense) AS sales_expenses,\n      SUM(lwe.line_gross_sales - lwe.line_cost) AS gross_profit,\n      SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) AS profit_after_sales_expenses,\n      CASE\n        WHEN SUM(lwe.line_gross_sales) = 0 THEN 0\n        ELSE ROUND(SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense) / SUM(lwe.line_gross_sales) * 100, 2)\n      END AS profit_margin_pct,\n      SUM(lwe.quantity) AS total_qty_sold,\n      COUNT(DISTINCT lwe.invoice_id) AS order_count\n    FROM lines_with_expense lwe\n    GROUP BY 1, 2\n    ORDER BY month_start\n  ),\n  company_totals AS (\n    SELECT\n      COALESCE(SUM(lwe.line_gross_sales), 0) AS gross_sales,\n      COALESCE(SUM(lwe.line_cost), 0) AS product_cost,\n      COALESCE(SUM(lwe.line_sales_expense), 0) + (SELECT amount FROM unallocated_exp) AS sales_expenses,\n      (SELECT amount FROM unallocated_exp) AS unallocated_sales_expenses,\n      COALESCE(SUM(lwe.line_gross_sales - lwe.line_cost), 0) AS gross_profit,\n      COALESCE(SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense), 0) - (SELECT amount FROM unallocated_exp) AS profit_after_sales_expenses,\n      CASE\n        WHEN COALESCE(SUM(lwe.line_gross_sales), 0) = 0 THEN 0\n        ELSE ROUND((COALESCE(SUM(lwe.line_gross_sales - lwe.line_cost - lwe.line_sales_expense), 0) - (SELECT amount FROM unallocated_exp)) / SUM(lwe.line_gross_sales) * 100, 2)\n      END AS profit_margin_pct,\n      COALESCE(SUM(lwe.quantity), 0) AS total_qty_sold,\n      COUNT(DISTINCT lwe.invoice_id) AS order_count,\n      COUNT(DISTINCT lwe.product_id) AS product_count\n    FROM lines_with_expense lwe\n  )\n  SELECT jsonb_build_object(\n    'company', (SELECT to_jsonb(ct) FROM company_totals ct),\n    'products', COALESCE((SELECT jsonb_agg(to_jsonb(ps) ORDER BY ps.profit_after_sales_expense DESC) FROM product_summaries ps), '[]'::jsonb),\n    'monthly', COALESCE((SELECT jsonb_agg(to_jsonb(ms) ORDER BY ms.month_start) FROM monthly_summaries ms), '[]'::jsonb)\n  ) INTO v_result;\n\n  RETURN v_result;\nEND;\n$$","--\n-- Name: get_staff_ledger_from_journal(\\"text\\", \\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_staff_ledger_from_journal\\"(\\"p_staff_name\\" \\"text\\", \\"p_start_date\\" \\"date\\" DEFAULT NULL::\\"date\\", \\"p_end_date\\" \\"date\\" DEFAULT (\\"now\\"())::\\"date\\") RETURNS TABLE(\\"entry_date\\" \\"date\\", \\"entry_number\\" \\"text\\", \\"voucher_type\\" \\"text\\", \\"reference_number\\" \\"text\\", \\"description\\" \\"text\\", \\"debit\\" numeric, \\"credit\\" numeric, \\"balance\\" numeric)\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_coa_id UUID;\nBEGIN\n-- Get staff's COA account\nSELECT coa_account_id INTO v_coa_id\nFROM staff_members\nWHERE LOWER(staff_name) = LOWER(p_staff_name);\n\nIF v_coa_id IS NULL THEN\nRAISE EXCEPTION 'Staff member % not found', p_staff_name;\nEND IF;\n\nRETURN QUERY\nSELECT \nje.entry_date::DATE,\nje.entry_number,\nCASE \nWHEN je.source_module = 'payment' THEN 'Payment Voucher'\nWHEN je.source_module = 'receipt' THEN 'Receipt Voucher'\nWHEN je.source_module = 'journal' THEN 'Journal Entry'\nELSE INITCAP(je.source_module)\nEND as voucher_type,\nCOALESCE(je.reference_number, '-') as reference_number,\nCOALESCE(jel.description, je.description, '-') as description,\njel.debit,\njel.credit,\nSUM(jel.debit - jel.credit) OVER (\nORDER BY je.entry_date, je.entry_number, jel.line_number\nROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n) as balance\nFROM journal_entry_lines jel\nJOIN journal_entries je ON jel.journal_entry_id = je.id\nWHERE jel.account_id = v_coa_id\nAND je.entry_date >= COALESCE(p_start_date, '1900-01-01'::DATE)\nAND je.entry_date <= p_end_date\nORDER BY je.entry_date, je.entry_number, jel.line_number;\nEND;\n$$","--\n-- Name: FUNCTION \\"get_staff_ledger_from_journal\\"(\\"p_staff_name\\" \\"text\\", \\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"get_staff_ledger_from_journal\\"(\\"p_staff_name\\" \\"text\\", \\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") IS 'Gets staff ledger from journal entries - uses existing accounting engine'","--\n-- Name: get_staff_outstanding_summary(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_staff_outstanding_summary\\"() RETURNS TABLE(\\"staff_name\\" \\"text\\", \\"employee_id\\" \\"text\\", \\"account_code\\" character varying, \\"outstanding_balance\\" numeric, \\"last_transaction_date\\" \\"date\\")\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT\ncoa.name as staff_name,\ncoa.code as employee_id,\ncoa.code as account_code,\nCOALESCE(SUM(\nCASE\nWHEN coa.normal_balance = 'debit' THEN jel.debit - jel.credit\nELSE jel.credit - jel.debit\nEND\n), 0) as outstanding_balance,\nMAX(je.entry_date)::DATE as last_transaction_date\nFROM chart_of_accounts coa\nLEFT JOIN journal_entry_lines jel ON coa.id = jel.account_id\nLEFT JOIN journal_entries je ON jel.journal_entry_id = je.id AND je.is_posted = true\nWHERE\ncoa.is_active = true\nAND (\ncoa.account_group ILIKE '%Staff%'\nOR coa.account_group ILIKE '%Employee%'\nOR coa.name ILIKE '%Staff%'\nOR coa.name ILIKE '%Employee%'\nOR coa.code LIKE '1150%'\n)\nGROUP BY coa.id, coa.name, coa.code, coa.normal_balance\nHAVING COALESCE(SUM(\nCASE\nWHEN coa.normal_balance = 'debit' THEN jel.debit - jel.credit\nELSE jel.credit - jel.debit\nEND\n), 0) != 0\nORDER BY coa.code;\nEND;\n$$","--\n-- Name: get_supplier_outstanding_summary(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_supplier_outstanding_summary\\"() RETURNS TABLE(\\"id\\" \\"uuid\\", \\"name\\" \\"text\\", \\"email\\" \\"text\\", \\"total_outstanding\\" numeric, \\"age_0_30\\" numeric, \\"age_31_60\\" numeric, \\"age_61_90\\" numeric, \\"age_90_plus\\" numeric, \\"oldest_invoice_date\\" \\"date\\")\n    LANGUAGE \\"plpgsql\\" STABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  RETURN QUERY\n  SELECT\n    s.id,\n    s.name::TEXT AS name,\n    s.email::TEXT AS email,\n    COALESCE(SUM(pi.balance_amount), 0) AS total_outstanding,\n    COALESCE(SUM(CASE WHEN CURRENT_DATE - pi.invoice_date <= 30 THEN pi.balance_amount ELSE 0 END), 0) AS age_0_30,\n    COALESCE(SUM(CASE WHEN CURRENT_DATE - pi.invoice_date BETWEEN 31 AND 60 THEN pi.balance_amount ELSE 0 END), 0) AS age_31_60,\n    COALESCE(SUM(CASE WHEN CURRENT_DATE - pi.invoice_date BETWEEN 61 AND 90 THEN pi.balance_amount ELSE 0 END), 0) AS age_61_90,\n    COALESCE(SUM(CASE WHEN CURRENT_DATE - pi.invoice_date > 90 THEN pi.balance_amount ELSE 0 END), 0) AS age_90_plus,\n    MIN(pi.invoice_date) AS oldest_invoice_date\n  FROM suppliers s\n  INNER JOIN purchase_invoices pi ON pi.supplier_id = s.id\n  WHERE pi.status IN ('pending', 'partial', 'approved')\n    AND pi.balance_amount > 0\n  GROUP BY s.id, s.name, s.email\n  HAVING COALESCE(SUM(pi.balance_amount), 0) > 0\n  ORDER BY COALESCE(SUM(pi.balance_amount), 0) DESC;\nEND;\n$$","--\n-- Name: get_system_tasks_summary(\\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_system_tasks_summary\\"(\\"user_role\\" \\"text\\" DEFAULT NULL::\\"text\\") RETURNS TABLE(\\"total_tasks\\" bigint, \\"urgent_tasks\\" bigint, \\"overdue_tasks\\" bigint, \\"today_tasks\\" bigint, \\"by_origin\\" \\"jsonb\\")\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nWITH task_stats AS (\nSELECT\nCOUNT(*) as total,\nCOUNT(*) FILTER (WHERE auto_priority = 'urgent') as urgent,\nCOUNT(*) FILTER (WHERE deadline < now()) as overdue,\nCOUNT(*) FILTER (WHERE deadline::date = CURRENT_DATE) as today,\njsonb_object_agg(\nCOALESCE(task_origin, 'unknown'),\ncount\n) as origins\nFROM (\nSELECT task_origin, auto_priority, deadline, COUNT(*) as count\nFROM tasks\nWHERE task_type = 'system'\nAND task_mode = 'advisory'\nAND status != 'completed'\nAND NOT is_deleted\nAND (user_role IS NULL OR auto_assigned_role = user_role OR auth.uid() = ANY(assigned_users))\nGROUP BY task_origin, auto_priority, deadline\n) sub\n)\nSELECT total, urgent, overdue, today, origins FROM task_stats;\nEND;\n$$","--\n-- Name: get_trial_balance(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_trial_balance\\"(\\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS TABLE(\\"code\\" character varying, \\"name\\" character varying, \\"name_id\\" character varying, \\"account_type\\" character varying, \\"account_group\\" character varying, \\"normal_balance\\" character varying, \\"total_debit\\" numeric, \\"total_credit\\" numeric, \\"balance\\" numeric)\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT * FROM public.get_trial_balance(p_start_date, p_end_date, public.get_reporting_usd_rate());\n$$","--\n-- Name: get_trial_balance(\\"date\\", \\"date\\", numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_trial_balance\\"(\\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\", \\"p_usd_rate\\" numeric) RETURNS TABLE(\\"code\\" character varying, \\"name\\" character varying, \\"name_id\\" character varying, \\"account_type\\" character varying, \\"account_group\\" character varying, \\"normal_balance\\" character varying, \\"total_debit\\" numeric, \\"total_credit\\" numeric, \\"balance\\" numeric)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;\n\n  RETURN QUERY\n  WITH active_lines AS (\n    SELECT jel.account_id, jel.debit, jel.credit\n    FROM public.journal_entry_lines jel\n    JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n    WHERE je.is_posted = true\n      AND COALESCE(je.is_reversed, false) = false\n      AND je.entry_date BETWEEN p_start_date AND p_end_date\n  )\n  SELECT coa.code, coa.name, coa.name_id, coa.account_type, coa.account_group,\n    COALESCE(coa.normal_balance,\n      CASE WHEN coa.account_type IN ('asset', 'expense') THEN 'debit' ELSE 'credit' END),\n    COALESCE(SUM(al.debit), 0)::numeric,\n    COALESCE(SUM(al.credit), 0)::numeric,\n    (COALESCE(SUM(al.debit), 0) - COALESCE(SUM(al.credit), 0))::numeric\n  FROM public.chart_of_accounts coa\n  LEFT JOIN active_lines al ON al.account_id = coa.id\n  WHERE coa.is_header = false AND coa.is_active = true\n  GROUP BY coa.id, coa.code, coa.name, coa.name_id, coa.account_type,\n    coa.account_group, coa.normal_balance\n  HAVING COALESCE(SUM(al.debit), 0) <> 0 OR COALESCE(SUM(al.credit), 0) <> 0\n  ORDER BY coa.code;\nEND;\n$$","--\n-- Name: get_user_appointments(\\"uuid\\", timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_user_appointments\\"(\\"user_uuid\\" \\"uuid\\", \\"start_date\\" timestamp without time zone DEFAULT NULL::timestamp without time zone, \\"end_date\\" timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(\\"id\\" \\"uuid\\", \\"activity_type\\" \\"text\\", \\"subject\\" \\"text\\", \\"description\\" \\"text\\", \\"follow_up_date\\" timestamp without time zone, \\"is_completed\\" boolean, \\"created_by\\" \\"uuid\\", \\"customer_id\\" \\"uuid\\", \\"participants\\" \\"uuid\\"[], \\"organizer_name\\" \\"text\\", \\"customer_name\\" \\"text\\")\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT \na.id,\na.activity_type,\na.subject,\na.description,\na.follow_up_date::timestamp,\na.is_completed,\na.created_by,\na.customer_id,\na.participants,\nup.full_name as organizer_name,\ncc.company_name as customer_name\nFROM crm_activities a\nLEFT JOIN user_profiles up ON a.created_by = up.id\nLEFT JOIN crm_contacts cc ON a.customer_id = cc.id\nWHERE a.activity_type IN ('meeting', 'video_call', 'phone_call')\nAND a.follow_up_date IS NOT NULL\nAND (\na.created_by = user_uuid OR\nuser_uuid = ANY(a.participants)\n)\nAND (start_date IS NULL OR a.follow_up_date >= start_date)\nAND (end_date IS NULL OR a.follow_up_date <= end_date)\nORDER BY a.follow_up_date ASC;\nEND;\n$$","--\n-- Name: get_user_appointments(\\"uuid\\", timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_user_appointments\\"(\\"p_user_id\\" \\"uuid\\", \\"p_start_date\\" timestamp with time zone DEFAULT NULL::timestamp with time zone, \\"p_end_date\\" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(\\"id\\" \\"uuid\\", \\"activity_type\\" \\"text\\", \\"subject\\" \\"text\\", \\"description\\" \\"text\\", \\"follow_up_date\\" timestamp without time zone, \\"is_completed\\" boolean, \\"participants\\" \\"uuid\\"[], \\"customer_id\\" \\"uuid\\", \\"created_by\\" \\"uuid\\", \\"customers\\" \\"jsonb\\", \\"user_profiles\\" \\"jsonb\\")\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nRETURN QUERY\nSELECT \nca.id,\nca.activity_type,\nca.subject,\nca.description,\nca.follow_up_date,\nca.is_completed,\nca.participants,\nca.customer_id,\nca.created_by,\nCASE \nWHEN c.id IS NOT NULL THEN \njsonb_build_object(\n'company_name', c.company_name,\n'address', c.address,\n'city', c.city,\n'contact_person', c.contact_person,\n'phone', c.phone\n)\nELSE NULL \nEND as customers,\nCASE \nWHEN up.id IS NOT NULL THEN \njsonb_build_object('full_name', up.full_name)\nELSE NULL \nEND as user_profiles\nFROM crm_activities ca\nLEFT JOIN customers c ON c.id = ca.customer_id\nLEFT JOIN user_profiles up ON up.id = ca.created_by\nWHERE ca.activity_type IN ('meeting', 'video_call', 'phone_call')\nAND ca.follow_up_date IS NOT NULL\nAND (\nca.created_by = p_user_id \nOR p_user_id = ANY(ca.participants)\n)\nAND (p_start_date IS NULL OR ca.follow_up_date >= p_start_date::timestamp)\nAND (p_end_date IS NULL OR ca.follow_up_date <= p_end_date::timestamp)\nORDER BY ca.follow_up_date ASC;\nEND;\n$$","--\n-- Name: get_user_tasks_summary(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_user_tasks_summary\\"(\\"p_user_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_recent_tasks jsonb;\nBEGIN\n-- Recent tasks (top 5)\nSELECT COALESCE(jsonb_agg(\njsonb_build_object(\n'id', t.id,\n'title', t.title,\n'priority', t.priority::text,\n'status', t.status::text,\n'deadline', t.deadline,\n'task_type', t.task_type::text\n)\n), '[]'::jsonb) INTO v_recent_tasks\nFROM (\nSELECT \nid,\ntitle,\npriority,\nstatus,\ndeadline,\ntask_type\nFROM tasks\nWHERE p_user_id = ANY(assigned_users)\nAND status != 'completed'\nAND (is_deleted IS NULL OR is_deleted = false)\nAND (dismissed_at IS NULL)\nORDER BY \nCASE \nWHEN deadline < NOW() THEN 0\nWHEN DATE(deadline) = CURRENT_DATE THEN 1\nELSE 2\nEND,\npriority DESC,\ndeadline ASC\nLIMIT 5\n) t;\n\nRETURN jsonb_build_object(\n'my_tasks', (\nSELECT COUNT(*)\nFROM tasks\nWHERE p_user_id = ANY(assigned_users)\nAND status != 'completed'\nAND (is_deleted IS NULL OR is_deleted = false)\nAND (dismissed_at IS NULL)\n),\n'overdue_tasks', (\nSELECT COUNT(*)\nFROM tasks\nWHERE p_user_id = ANY(assigned_users)\nAND status != 'completed'\nAND deadline < NOW()\nAND (is_deleted IS NULL OR is_deleted = false)\nAND (dismissed_at IS NULL)\n),\n'today_tasks', (\nSELECT COUNT(*)\nFROM tasks\nWHERE p_user_id = ANY(assigned_users)\nAND status != 'completed'\nAND DATE(deadline) = CURRENT_DATE\nAND (is_deleted IS NULL OR is_deleted = false)\nAND (dismissed_at IS NULL)\n),\n'pending_approvals', (\nSELECT \n(SELECT COUNT(*) FROM sales_orders WHERE status = 'pending_approval') +\n(SELECT COUNT(*) FROM delivery_challans WHERE approval_status = 'pending_approval') +\n(SELECT COUNT(*) FROM credit_notes WHERE status = 'pending') +\n(SELECT COUNT(*) FROM material_returns WHERE status = 'pending')\n),\n'recent_tasks', v_recent_tasks\n);\nEND;\n$$","--\n-- Name: get_users_by_role(\\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_users_by_role\\"(\\"role_name\\" \\"text\\") RETURNS \\"uuid\\"[]\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nuser_ids uuid[];\nBEGIN\nSELECT ARRAY_AGG(id) INTO user_ids\nFROM user_profiles\nWHERE role = role_name\nAND is_active = true;\nRETURN COALESCE(user_ids, ARRAY[]::uuid[]);\nEND;\n$$","--\n-- Name: get_warehouse_dashboard_data(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"get_warehouse_dashboard_data\\"(\\"p_user_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_low_stock_items jsonb;\nv_near_expiry_items jsonb;\nBEGIN\n-- Get low stock items details\nSELECT COALESCE(jsonb_agg(\njsonb_build_object(\n'product_code', t.product_code,\n'product_name', t.product_name,\n'current_stock', t.current_stock,\n'min_stock_level', t.min_stock_level,\n'shortage', t.shortage\n)\n), '[]'::jsonb) INTO v_low_stock_items\nFROM (\nSELECT \nproduct_code,\nproduct_name,\ncurrent_stock,\nmin_stock_level,\n(min_stock_level - current_stock) as shortage\nFROM products\nWHERE is_active = true\nAND min_stock_level > 0\nAND current_stock < min_stock_level\nORDER BY (min_stock_level - current_stock) DESC\nLIMIT 10\n) t;\n\n-- Get near expiry items details\nSELECT COALESCE(jsonb_agg(\njsonb_build_object(\n'batch_number', t.batch_number,\n'product_name', t.product_name,\n'current_stock', t.current_stock,\n'expiry_date', t.expiry_date,\n'days_to_expiry', t.days_to_expiry\n)\n), '[]'::jsonb) INTO v_near_expiry_items\nFROM (\nSELECT \nb.batch_number,\np.product_name,\nb.current_stock,\nb.expiry_date,\n(b.expiry_date - CURRENT_DATE) as days_to_expiry\nFROM batches b\nJOIN products p ON p.id = b.product_id\nWHERE b.is_active = true\nAND b.current_stock > 0\nAND b.expiry_date IS NOT NULL\nAND b.expiry_date BETWEEN CURRENT_DATE AND (CURRENT_DATE + INTERVAL '30 days')\nORDER BY b.expiry_date ASC\nLIMIT 10\n) t;\n\nRETURN jsonb_build_object(\n'low_stock_count', (\nSELECT COUNT(*)\nFROM products\nWHERE is_active = true\nAND min_stock_level > 0\nAND current_stock < min_stock_level\n),\n'low_stock_items', v_low_stock_items,\n'near_expiry_count', (\nSELECT COUNT(*)\nFROM batches\nWHERE is_active = true\nAND current_stock > 0\nAND expiry_date IS NOT NULL\nAND expiry_date BETWEEN CURRENT_DATE AND (CURRENT_DATE + INTERVAL '30 days')\n),\n'near_expiry_items', v_near_expiry_items,\n'pending_dispatch', (\nSELECT COUNT(*)\nFROM delivery_challans\nWHERE approval_status = 'approved'\n),\n'incoming_stock', (\nSELECT COUNT(*)\nFROM purchase_orders\nWHERE status IN ('approved', 'sent_to_supplier')\n),\n'batch_alerts', (\nSELECT COUNT(*)\nFROM batches\nWHERE is_active = true\nAND (\n(expiry_date IS NOT NULL AND expiry_date < CURRENT_DATE AND current_stock > 0)\nOR (current_stock <= 0)\n)\n),\n'inventory_value', (\nSELECT COALESCE(SUM(b.current_stock * COALESCE(b.landed_cost_per_unit, 0)), 0)\nFROM batches b\nWHERE b.is_active = true\nAND b.current_stock > 0\n),\n'pick_pack_tasks', (\nSELECT COUNT(*)\nFROM delivery_challans\nWHERE approval_status IN ('pending_approval', 'approved')\n),\n'stock_rejections', (\nSELECT COUNT(*)\nFROM stock_rejections\nWHERE DATE(created_at) >= CURRENT_DATE - INTERVAL '7 days'\n)\n);\nEND;\n$$","--\n-- Name: guard_delivery_challan_batch_reservation(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"guard_delivery_challan_batch_reservation\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_reserved numeric;\nBEGIN\n  IF NEW.approval_status = 'approved' AND OLD.approval_status IS DISTINCT FROM 'approved' AND NEW.sales_order_id IS NOT NULL THEN\n    SELECT COALESCE(sum(sr.reserved_quantity),0) INTO v_reserved\n    FROM public.stock_reservations sr\n    JOIN public.delivery_challan_items dci ON dci.sales_order_item_id=sr.sales_order_item_id\n      AND dci.product_id=sr.product_id AND dci.batch_id=sr.batch_id AND dci.challan_id=NEW.id\n    WHERE sr.sales_order_id=NEW.sales_order_id AND sr.status='active';\n    IF EXISTS (\n      SELECT 1 FROM public.delivery_challan_items dci\n      WHERE dci.challan_id=NEW.id\n        AND (SELECT COALESCE(sum(sr.reserved_quantity),0) FROM public.stock_reservations sr\n             WHERE sr.sales_order_id=NEW.sales_order_id AND sr.sales_order_item_id=dci.sales_order_item_id\n               AND sr.product_id=dci.product_id AND sr.batch_id=dci.batch_id AND sr.status='active') < dci.quantity\n    ) THEN\n      RAISE EXCEPTION 'Selected batch differs from the Sales Order reservation. Align the reservation before approval.';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND; $$","--\n-- Name: guard_delivery_challan_source_link(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"guard_delivery_challan_source_link\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_so_customer uuid;\nBEGIN\n  IF OLD.sales_order_id IS NOT NULL\n     AND NEW.sales_order_id IS DISTINCT FROM OLD.sales_order_id THEN\n    RAISE EXCEPTION 'A Delivery Challan linked to a Sales Order cannot be detached or reassigned';\n  END IF;\n\n  IF NEW.sales_order_id IS NOT NULL THEN\n    SELECT customer_id INTO v_so_customer\n    FROM public.sales_orders\n    WHERE id = NEW.sales_order_id;\n\n    IF NOT FOUND THEN\n      RAISE EXCEPTION 'Linked Sales Order % does not exist', NEW.sales_order_id;\n    END IF;\n    IF NEW.customer_id IS DISTINCT FROM v_so_customer THEN\n      RAISE EXCEPTION 'Delivery Challan customer must match its linked Sales Order customer';\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: guard_posted_sales_invoice_delete(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"guard_posted_sales_invoice_delete\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF OLD.journal_entry_id IS NOT NULL\n     OR EXISTS (\n       SELECT 1 FROM public.sales_invoice_items\n       WHERE invoice_id = OLD.id\n     ) THEN\n    RAISE EXCEPTION\n      'Posted Sales Invoice cannot be deleted; a controlled accounting void/reversal workflow is required';\n  END IF;\n\n  RETURN OLD;\nEND;\n$$","--\n-- Name: guard_purchase_invoice_item_received_quantity(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"guard_purchase_invoice_item_received_quantity\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_received numeric; BEGIN\n IF NEW.quantity IS DISTINCT FROM OLD.quantity THEN\n  v_received:=public.purchase_invoice_item_received_quantity(NEW.id);\n  IF NEW.quantity < v_received-0.01 THEN RAISE EXCEPTION 'Purchase Invoice quantity % is below already received quantity %; use a controlled inventory correction',NEW.quantity,v_received USING ERRCODE='check_violation'; END IF;\n END IF; RETURN NEW; END; $$","--\n-- Name: guard_receiving_requires_approval(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"guard_receiving_requires_approval\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_status text;\nBEGIN\n  SELECT receiving_approval_status INTO v_status FROM public.purchase_invoices WHERE id=NEW.purchase_invoice_id;\n  -- NULL denotes a legacy invoice created before this approval lifecycle;\n  -- preserve its existing receiving behavior without backfilling history.\n  IF v_status IS NOT NULL AND v_status <> 'approved' THEN\n    RAISE EXCEPTION 'Purchase Invoice must be approved for inward before receiving';\n  END IF;\n  RETURN NEW;\nEND; $$","--\n-- Name: guard_sales_order_delete_with_history(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"guard_sales_order_delete_with_history\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF EXISTS (\n       SELECT 1 FROM public.delivery_challans\n       WHERE sales_order_id = OLD.id\n     )\n     OR EXISTS (\n       SELECT 1 FROM public.stock_reservations\n       WHERE sales_order_id = OLD.id\n     )\n     OR EXISTS (\n       SELECT 1 FROM public.sales_invoices\n       WHERE sales_order_id = OLD.id\n     ) THEN\n    RAISE EXCEPTION\n      'Sales Order with reservation or downstream document history cannot be deleted; use the controlled cancellation workflow';\n  END IF;\n\n  RETURN OLD;\nEND;\n$$","--\n-- Name: guard_stock_posted_dc_header(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"guard_stock_posted_dc_header\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF OLD.approval_status = 'approved'\n     AND (\n       NEW.challan_number IS DISTINCT FROM OLD.challan_number\n       OR NEW.customer_id IS DISTINCT FROM OLD.customer_id\n       OR NEW.sales_order_id IS DISTINCT FROM OLD.sales_order_id\n       OR NEW.challan_date IS DISTINCT FROM OLD.challan_date\n       OR NEW.delivery_address IS DISTINCT FROM OLD.delivery_address\n       OR NEW.vehicle_number IS DISTINCT FROM OLD.vehicle_number\n       OR NEW.driver_name IS DISTINCT FROM OLD.driver_name\n       OR NEW.notes IS DISTINCT FROM OLD.notes\n     ) THEN\n    RAISE EXCEPTION\n      'Approved Delivery Challan header cannot be edited; cancel/reject through the canonical reversal path and create a corrected DC';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: guard_used_batch_identity_v1(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"guard_used_batch_identity_v1\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_is_used boolean;\nBEGIN\n  IF NEW.product_id IS NOT DISTINCT FROM OLD.product_id\n     AND NEW.make_id IS NOT DISTINCT FROM OLD.make_id THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT\n    EXISTS (\n      SELECT 1\n      FROM public.inventory_transactions it\n      WHERE it.batch_id = OLD.id\n    )\n    OR EXISTS (\n      SELECT 1\n      FROM public.purchase_invoice_receiving_allocations pira\n      WHERE pira.batch_id = OLD.id\n    )\n    OR EXISTS (\n      SELECT 1\n      FROM public.stock_reservations sr\n      WHERE sr.batch_id = OLD.id\n    )\n    OR EXISTS (\n      SELECT 1\n      FROM public.delivery_challan_items dci\n      WHERE dci.batch_id = OLD.id\n    )\n    OR EXISTS (\n      SELECT 1\n      FROM public.sales_invoice_items sii\n      WHERE sii.batch_id = OLD.id\n    )\n  INTO v_is_used;\n\n  IF v_is_used AND NEW.product_id IS DISTINCT FROM OLD.product_id THEN\n    RAISE EXCEPTION\n      'Cannot change Product after a batch has inventory or downstream history'\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  -- Preserve the approved historical-data workflow: an unknown historical\n  -- make may be recorded once. Do not permit a known identity to be rewritten\n  -- after the batch has inventory/downstream history.\n  IF v_is_used\n     AND OLD.make_id IS NOT NULL\n     AND NEW.make_id IS DISTINCT FROM OLD.make_id THEN\n    RAISE EXCEPTION\n      'Cannot change a recorded Make after a batch has inventory or downstream history'\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"guard_used_batch_identity_v1\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"guard_used_batch_identity_v1\\"() IS 'Prevents Product or an already-recorded Make from being rewritten after inventory/downstream use; permits historical NULL Make completion.'","--\n-- Name: handle_material_return_approval(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"handle_material_return_approval\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_item record;\nBEGIN\nIF NEW.status = 'approved' AND OLD.status != 'approved' THEN\nFOR v_item IN\nSELECT * FROM material_return_items WHERE return_id = NEW.id\nLOOP\nINSERT INTO inventory_transactions (\nproduct_id,\nbatch_id,\ntransaction_type,\nquantity_change,\ntransaction_date,\nnotes,\nreference_type,\nreference_id,\ncreated_by\n)\nVALUES (\nv_item.product_id,\nv_item.batch_id,\n'return',\nv_item.quantity_returned,\nNEW.return_date,\n'Material return approved: ' || NEW.reason,\n'material_return',\nNEW.id,\nNEW.approved_by\n);\n\nUPDATE batches\nSET current_stock = current_stock + v_item.quantity_returned\nWHERE id = v_item.batch_id;\nEND LOOP;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"handle_new_user\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_username text;\nBEGIN\n  v_username := COALESCE(\n    NULLIF(TRIM(NEW.raw_user_meta_data->>'username'), ''),\n    split_part(NEW.email, '@', 1)\n  );\n\n  INSERT INTO public.user_profiles (id, username, email, full_name, role, is_active)\n  VALUES (\n    NEW.id,\n    v_username,\n    NEW.email,\n    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),\n    'sales',  -- Hard-coded. IGNORES raw_user_meta_data->>'role'.\n    true       -- Preserve prior signup UX.\n  )\n  ON CONFLICT (id) DO NOTHING;\n\n  RETURN NEW;\nEND $$","--\n-- Name: handle_stock_rejection_approval(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"handle_stock_rejection_approval\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF NEW.status = 'approved' AND OLD.status != 'approved' THEN\nINSERT INTO inventory_transactions (\nproduct_id,\nbatch_id,\ntransaction_type,\nquantity_change,\ntransaction_date,\nnotes,\nreference_type,\nreference_id,\ncreated_by\n)\nVALUES (\nNEW.product_id,\nNEW.batch_id,\n'rejection',\n-NEW.quantity,\nNEW.rejection_date,\n'Stock rejection approved: ' || NEW.reason,\n'stock_rejection',\nNEW.id,\nNEW.approved_by\n);\n\nUPDATE batches\nSET current_stock = current_stock - NEW.quantity\nWHERE id = NEW.batch_id;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: historical_allocation_relink_context_active(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"historical_allocation_relink_context_active\\"() RETURNS boolean\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\n  SELECT COALESCE(current_setting('app.historical_allocation_relink', true), 'off') = 'on'\n    AND (current_user IN ('postgres', 'supabase_admin') OR auth.role() = 'service_role');\n$$","--\n-- Name: historical_repair_context_active(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"historical_repair_context_active\\"() RETURNS boolean\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\n  SELECT COALESCE(current_setting('app.finance_historical_repair','true'),'off')='on'\n     AND EXISTS (\n       SELECT 1 FROM public.finance_historical_repair_commands c\n       WHERE c.id::text=current_setting('app.finance_historical_repair_command','true')\n         AND (\n           current_user IN ('postgres','supabase_admin')\n           OR (auth.role()='service_role' AND c.requested_by IS NULL)\n           OR c.requested_by=auth.uid()\n         )\n     )\n     AND (\n       current_user IN ('postgres','supabase_admin')\n       OR auth.role()='service_role'\n       OR EXISTS (\n         SELECT 1 FROM public.user_profiles up\n         WHERE up.id=auth.uid() AND up.is_active=true AND up.role='admin'\n       )\n     );\n$$","--\n-- Name: initialize_invoice_amounts(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"initialize_invoice_amounts\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- On INSERT: Initialize paid_amount and balance_amount\nIF TG_OP = 'INSERT' THEN\nIF NEW.paid_amount IS NULL THEN\nNEW.paid_amount := 0;\nEND IF;\n\nIF NEW.balance_amount IS NULL OR NEW.balance_amount = 0 THEN\nNEW.balance_amount := NEW.total_amount;\nEND IF;\nEND IF;\n\n-- On UPDATE: Recalculate balance_amount if total_amount changed\nIF TG_OP = 'UPDATE' AND OLD.total_amount != NEW.total_amount THEN\n-- Recalculate balance: new total - current paid\nNEW.balance_amount := NEW.total_amount - COALESCE(NEW.paid_amount, 0);\n\n-- Recalculate payment status\nIF NEW.paid_amount = 0 THEN\nNEW.payment_status := 'pending';\nELSIF NEW.paid_amount >= NEW.total_amount THEN\nNEW.payment_status := 'paid';\nELSE\nNEW.payment_status := 'partial';\nEND IF;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: inventory_v1_actor_allowed(\\"text\\"[]); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"inventory_v1_actor_allowed\\"(\\"p_roles\\" \\"text\\"[]) RETURNS boolean\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT\n    auth.role() = 'service_role'\n    OR EXISTS (\n      SELECT 1\n      FROM public.user_profiles up\n      WHERE up.id = auth.uid()\n        AND up.role = ANY(p_roles)\n    );\n$$","--\n-- Name: inventory_v1_block_approved_detail_change(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"inventory_v1_block_approved_detail_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_status text;\nBEGIN\n  IF TG_TABLE_NAME = 'material_return_items' THEN\n    SELECT status INTO v_status\n    FROM public.material_returns\n    WHERE id = COALESCE(NEW.return_id, OLD.return_id);\n  ELSIF TG_TABLE_NAME = 'credit_note_items' THEN\n    SELECT status INTO v_status\n    FROM public.credit_notes\n    WHERE id = COALESCE(NEW.credit_note_id, OLD.credit_note_id);\n  END IF;\n\n  IF v_status IN ('approved', 'completed') THEN\n    RAISE EXCEPTION 'Approved stock source items cannot be edited or deleted; reverse first';\n  END IF;\n\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$","--\n-- Name: inventory_v1_certification_status(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"inventory_v1_certification_status\\"() RETURNS \\"jsonb\\"\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH cfg AS (\n    SELECT enforcement_started_at\n    FROM public.inventory_engine_certification\n    WHERE singleton\n  ),\n  checks AS (\n    SELECT\n      (\n        SELECT count(*)\n        FROM public.batches b, cfg\n        WHERE b.created_at >= cfg.enforcement_started_at\n          AND NOT EXISTS (\n            SELECT 1\n            FROM public.inventory_transactions it\n            WHERE it.batch_id = b.id\n              AND it.transaction_type = 'purchase'\n              AND it.metadata->>'canonical_engine_version' = '1.0'\n          )\n      ) new_batches_without_canonical_creation,\n      (\n        SELECT count(*)\n        FROM public.inventory_transactions it, cfg\n        WHERE it.created_at >= cfg.enforcement_started_at\n          AND COALESCE(it.metadata->>'canonical_engine_version', '') <> '1.0'\n      ) noncanonical_new_movements,\n      (\n        SELECT count(*)\n        FROM public.inventory_transactions it, cfg\n        WHERE it.created_at >= cfg.enforcement_started_at\n          AND it.transaction_type = 'sale'\n      ) sales_invoice_physical_movements,\n      (\n        SELECT count(*)\n        FROM public.sales_invoice_items sii, cfg\n        WHERE sii.created_at >= cfg.enforcement_started_at\n          AND sii.delivery_challan_item_id IS NULL\n      ) new_invoice_items_without_dc,\n      (\n        SELECT count(*)\n        FROM (\n          SELECT dci.challan_id, dci.batch_id, dci.product_id\n          FROM public.delivery_challan_items dci\n          JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n          CROSS JOIN cfg\n          WHERE dc.approval_status::text = 'approved'\n            AND COALESCE(dc.approved_at, dc.updated_at, dc.created_at)\n              >= cfg.enforcement_started_at\n          GROUP BY dci.challan_id, dci.batch_id, dci.product_id\n          HAVING sum(dci.quantity) IS DISTINCT FROM (\n            SELECT abs(COALESCE(sum(it.quantity), 0))\n            FROM public.inventory_transactions it\n            WHERE it.reference_type = 'delivery_challan'\n              AND it.reference_id = dci.challan_id\n              AND it.batch_id = dci.batch_id\n              AND it.product_id = dci.product_id\n              AND it.metadata->>'canonical_engine_version' = '1.0'\n          )\n        ) mismatch\n      ) approved_dc_movement_mismatches,\n      (\n        SELECT count(*)\n        FROM (\n          SELECT mri.return_id, mri.batch_id, mri.product_id\n          FROM public.material_return_items mri\n          JOIN public.material_returns mr ON mr.id = mri.return_id\n          CROSS JOIN cfg\n          WHERE mr.status IN ('approved', 'completed')\n            AND mr.restocked = true\n            AND mri.disposition = 'restock'\n            AND mr.updated_at >= cfg.enforcement_started_at\n          GROUP BY mri.return_id, mri.batch_id, mri.product_id\n          HAVING sum(mri.quantity_returned) IS DISTINCT FROM (\n            SELECT COALESCE(sum(it.quantity), 0)\n            FROM public.inventory_transactions it\n            WHERE it.reference_type = 'material_return'\n              AND it.reference_id = mri.return_id\n              AND it.batch_id = mri.batch_id\n              AND it.product_id = mri.product_id\n              AND it.metadata->>'canonical_engine_version' = '1.0'\n          )\n        ) mismatch\n      ) material_return_movement_mismatches,\n      (\n        SELECT count(*)\n        FROM (\n          SELECT cni.credit_note_id, cni.batch_id, cni.product_id\n          FROM public.credit_note_items cni\n          JOIN public.credit_notes cn ON cn.id = cni.credit_note_id\n          CROSS JOIN cfg\n          WHERE cn.status = 'approved'\n            AND cn.updated_at >= cfg.enforcement_started_at\n          GROUP BY cni.credit_note_id, cni.batch_id, cni.product_id\n          HAVING sum(cni.quantity) IS DISTINCT FROM (\n            SELECT COALESCE(sum(it.quantity), 0)\n            FROM public.inventory_transactions it\n            WHERE it.reference_type = 'credit_note'\n              AND it.reference_id = cni.credit_note_id\n              AND it.batch_id = cni.batch_id\n              AND it.product_id = cni.product_id\n              AND it.metadata->>'canonical_engine_version' = '1.0'\n          )\n        ) mismatch\n      ) credit_note_movement_mismatches,\n      (\n        SELECT count(*)\n        FROM public.stock_rejections sr, cfg\n        WHERE sr.status IN ('approved', 'disposed')\n          AND sr.updated_at >= cfg.enforcement_started_at\n          AND NOT EXISTS (\n            SELECT 1\n            FROM public.inventory_transactions it\n            WHERE it.reference_type = 'stock_rejection'\n              AND it.reference_id = sr.id\n              AND it.batch_id = sr.batch_id\n              AND it.quantity = -sr.quantity_rejected\n              AND it.metadata->>'canonical_engine_version' = '1.0'\n          )\n      ) stock_rejection_movement_mismatches,\n      (\n        SELECT count(*)\n        FROM public.stock_reservations sr\n        JOIN public.batches b ON b.id = sr.batch_id\n        CROSS JOIN cfg\n        WHERE sr.reserved_at >= cfg.enforcement_started_at\n          AND sr.status = 'active'\n          AND b.expiry_date IS NOT NULL\n          AND b.expiry_date <= CURRENT_DATE\n      ) active_reservations_on_expired_batches,\n      (\n        SELECT count(*)\n        FROM public.batches\n        WHERE current_stock < 0\n      ) negative_batches\n  )\n  SELECT jsonb_build_object(\n    'engine_version', '1.0',\n    'enforcement_started_at', (SELECT enforcement_started_at FROM cfg),\n    'certified',\n      new_batches_without_canonical_creation = 0\n      AND noncanonical_new_movements = 0\n      AND sales_invoice_physical_movements = 0\n      AND new_invoice_items_without_dc = 0\n      AND approved_dc_movement_mismatches = 0\n      AND material_return_movement_mismatches = 0\n      AND credit_note_movement_mismatches = 0\n      AND stock_rejection_movement_mismatches = 0\n      AND active_reservations_on_expired_batches = 0\n      AND negative_batches = 0,\n    'checks', jsonb_build_object(\n      'new_batches_without_canonical_creation',\n        new_batches_without_canonical_creation,\n      'noncanonical_new_movements', noncanonical_new_movements,\n      'sales_invoice_physical_movements', sales_invoice_physical_movements,\n      'new_invoice_items_without_dc', new_invoice_items_without_dc,\n      'approved_dc_movement_mismatches', approved_dc_movement_mismatches,\n      'material_return_movement_mismatches',\n        material_return_movement_mismatches,\n      'credit_note_movement_mismatches', credit_note_movement_mismatches,\n      'stock_rejection_movement_mismatches',\n        stock_rejection_movement_mismatches,\n      'active_reservations_on_expired_batches',\n        active_reservations_on_expired_batches,\n      'negative_batches', negative_batches\n    )\n  )\n  FROM checks;\n$$","--\n-- Name: inventory_v1_consume_reservation(\\"uuid\\", \\"uuid\\", \\"uuid\\", numeric, \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"inventory_v1_consume_reservation\\"(\\"p_so_id\\" \\"uuid\\", \\"p_product_id\\" \\"uuid\\", \\"p_batch_id\\" \\"uuid\\", \\"p_quantity\\" numeric, \\"p_released_by\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_reservation record;\n  v_remaining_qty numeric := p_quantity;\n  v_release_qty numeric;\n  v_reserved_qty numeric;\nBEGIN\n  IF p_so_id IS NULL THEN\n    RETURN;\n  END IF;\n  IF COALESCE(p_quantity, 0) <= 0 THEN\n    RAISE EXCEPTION 'Delivery quantity must be positive';\n  END IF;\n\n  SELECT COALESCE(sum(reserved_quantity), 0)\n  INTO v_reserved_qty\n  FROM public.stock_reservations\n  WHERE sales_order_id = p_so_id\n    AND product_id = p_product_id\n    AND batch_id = p_batch_id\n    AND status = 'active';\n\n  IF v_reserved_qty < p_quantity THEN\n    RAISE EXCEPTION\n      'Delivery Challan batch does not match canonical FEFO reservation: reserved %, requested %',\n      v_reserved_qty,\n      p_quantity;\n  END IF;\n\n  FOR v_reservation IN\n    SELECT id, reserved_quantity\n    FROM public.stock_reservations\n    WHERE sales_order_id = p_so_id\n      AND product_id = p_product_id\n      AND batch_id = p_batch_id\n      AND status = 'active'\n    ORDER BY reserved_at, id\n    FOR UPDATE\n  LOOP\n    EXIT WHEN v_remaining_qty <= 0;\n    v_release_qty := LEAST(v_remaining_qty, v_reservation.reserved_quantity);\n\n    IF v_release_qty = v_reservation.reserved_quantity THEN\n      UPDATE public.stock_reservations\n      SET status = 'released',\n          is_released = true,\n          released_at = now(),\n          released_by = COALESCE(p_released_by, auth.uid()),\n          release_reason = 'delivered'\n      WHERE id = v_reservation.id;\n    ELSE\n      UPDATE public.stock_reservations\n      SET reserved_quantity = reserved_quantity - v_release_qty\n      WHERE id = v_reservation.id;\n    END IF;\n\n    v_remaining_qty := v_remaining_qty - v_release_qty;\n  END LOOP;\nEND;\n$$","--\n-- Name: inventory_v1_guard_batch_delete(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"inventory_v1_guard_batch_delete\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF EXISTS (\n    SELECT 1\n    FROM public.inventory_transactions\n    WHERE batch_id = OLD.id\n  ) THEN\n    RAISE EXCEPTION\n      'Batch with inventory history cannot be deleted; archive it';\n  END IF;\n  RETURN OLD;\nEND;\n$$","--\n-- Name: inventory_v1_guard_batch_quantity_write(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"inventory_v1_guard_batch_quantity_write\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF current_setting('app.canonical_stock_engine', true) IS DISTINCT FROM 'on' THEN\n    IF TG_OP = 'INSERT' OR NEW.current_stock IS DISTINCT FROM OLD.current_stock THEN\n      RAISE EXCEPTION 'Direct batch quantity write blocked; use canonical inventory engine';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: inventory_v1_guard_movement_write(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"inventory_v1_guard_movement_write\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF current_setting('app.canonical_stock_engine', true) IS DISTINCT FROM 'on' THEN\n    RAISE EXCEPTION 'Direct inventory movement write blocked; use canonical inventory engine';\n  END IF;\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$","--\n-- Name: inventory_v1_guard_sales_order_approval(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"inventory_v1_guard_sales_order_approval\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF NEW.status::text = 'approved'\n     AND OLD.status::text IS DISTINCT FROM 'approved'\n     AND current_setting('app.canonical_reservation_engine', true)\n       IS DISTINCT FROM 'on' THEN\n    RAISE EXCEPTION 'Direct Sales Order approval blocked; use canonical reservation engine';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: inventory_v1_guard_source_delete(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"inventory_v1_guard_source_delete\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF TG_TABLE_NAME = 'delivery_challans'\n     AND EXISTS (\n       SELECT 1 FROM public.inventory_transactions\n       WHERE reference_id = OLD.id\n         AND reference_type = 'delivery_challan'\n         AND metadata->>'canonical_engine_version' = '1.0'\n     ) THEN\n    RAISE EXCEPTION 'Delivery Challan with canonical stock history cannot be deleted; cancel/reverse it';\n  ELSIF TG_TABLE_NAME = 'material_returns'\n        AND OLD.status IN ('approved', 'completed') THEN\n    RAISE EXCEPTION 'Approved Material Return cannot be deleted; reverse it first';\n  ELSIF TG_TABLE_NAME = 'credit_notes'\n        AND OLD.status = 'approved' THEN\n    RAISE EXCEPTION 'Approved Credit Note cannot be deleted; reverse it first';\n  ELSIF TG_TABLE_NAME = 'stock_rejections'\n        AND OLD.status IN ('approved', 'disposed') THEN\n    RAISE EXCEPTION 'Approved Stock Rejection cannot be deleted; reverse it first';\n  END IF;\n\n  RETURN OLD;\nEND;\n$$","--\n-- Name: inventory_v1_movement_report(\\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"inventory_v1_movement_report\\"(\\"p_date_from\\" \\"date\\", \\"p_date_to\\" \\"date\\") RETURNS TABLE(\\"product_id\\" \\"uuid\\", \\"product_code\\" \\"text\\", \\"product_name\\" \\"text\\", \\"unit\\" \\"text\\", \\"opening\\" numeric, \\"in_qty\\" numeric, \\"out_qty\\" numeric, \\"reserved_qty\\" numeric, \\"closing\\" numeric)\n    LANGUAGE \\"sql\\" STABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  WITH cfg AS (\n    SELECT enforcement_started_at\n    FROM public.inventory_engine_certification\n    WHERE singleton\n  ),\n  physical_movements AS (\n    SELECT it.product_id, it.transaction_date, it.quantity\n    FROM public.inventory_transactions it\n    CROSS JOIN cfg\n    WHERE (\n      it.metadata->>'canonical_engine_version' = '1.0'\n      OR (\n        it.created_at < cfg.enforcement_started_at\n        AND it.transaction_type IN ('purchase', 'sale', 'return', 'adjustment')\n      )\n    )\n      AND COALESCE((it.metadata->>'superseded')::boolean, false) = false\n  ),\n  movement_totals AS (\n    SELECT\n      pm.product_id,\n      COALESCE(sum(pm.quantity) FILTER (\n        WHERE pm.transaction_date < p_date_from\n      ), 0) AS opening,\n      COALESCE(sum(pm.quantity) FILTER (\n        WHERE pm.transaction_date BETWEEN p_date_from AND p_date_to\n          AND pm.quantity > 0\n      ), 0) AS in_qty,\n      COALESCE(abs(sum(pm.quantity) FILTER (\n        WHERE pm.transaction_date BETWEEN p_date_from AND p_date_to\n          AND pm.quantity < 0\n      )), 0) AS out_qty\n    FROM physical_movements pm\n    GROUP BY pm.product_id\n  ),\n  reservations AS (\n    SELECT sr.product_id, COALESCE(sum(sr.reserved_quantity), 0) reserved_qty\n    FROM public.stock_reservations sr\n    WHERE sr.status = 'active'\n    GROUP BY sr.product_id\n  )\n  SELECT\n    p.id,\n    p.product_code,\n    p.product_name,\n    COALESCE(p.unit, 'PCS'),\n    COALESCE(mt.opening, 0),\n    COALESCE(mt.in_qty, 0),\n    COALESCE(mt.out_qty, 0),\n    COALESCE(r.reserved_qty, 0),\n    COALESCE(mt.opening, 0)\n      + COALESCE(mt.in_qty, 0)\n      - COALESCE(mt.out_qty, 0)\n  FROM public.products p\n  LEFT JOIN movement_totals mt ON mt.product_id = p.id\n  LEFT JOIN reservations r ON r.product_id = p.id\n  WHERE COALESCE(mt.opening, 0) <> 0\n     OR COALESCE(mt.in_qty, 0) <> 0\n     OR COALESCE(mt.out_qty, 0) <> 0\n     OR COALESCE(r.reserved_qty, 0) <> 0\n  ORDER BY p.product_code, p.product_name;\n$$","--\n-- Name: invoke_bulk_email_worker(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"invoke_bulk_email_worker\\"() RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'extensions'\n    AS $$\nDECLARE\n  v_settings record;\nBEGIN\n  SELECT bulk_email_worker_url, bulk_email_worker_secret\n  INTO v_settings\n  FROM public.app_settings\n  LIMIT 1;\n\n  IF v_settings.bulk_email_worker_url IS NULL OR v_settings.bulk_email_worker_secret IS NULL THEN\n    RAISE LOG 'bulk email worker cron skipped: worker URL/secret not configured';\n    RETURN;\n  END IF;\n\n  PERFORM net.http_post(\n    url := v_settings.bulk_email_worker_url,\n    headers := jsonb_build_object(\n      'Content-Type', 'application/json',\n      'X-Bulk-Email-Worker-Secret', v_settings.bulk_email_worker_secret\n    ),\n    body := '{}'::jsonb,\n    timeout_milliseconds := 25000\n  );\nEND;\n$$","--\n-- Name: is_capitalizable_landed_cost_category(\\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"is_capitalizable_landed_cost_category\\"(\\"p_category\\" \\"text\\") RETURNS boolean\n    LANGUAGE \\"sql\\" IMMUTABLE\n    AS $$\n  SELECT lower(replace(COALESCE(p_category, ''), ' ', '_')) IN (\n    'duty_customs', 'duty', 'duty_import',\n    'freight_import', 'freight', 'clearing_forwarding',\n    'container_handling', 'loading_import', 'port_charges',\n    'transport_import', 'import_broker', 'other_import'\n  );\n$$","--\n-- Name: FUNCTION \\"is_capitalizable_landed_cost_category\\"(\\"p_category\\" \\"text\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"is_capitalizable_landed_cost_category\\"(\\"p_category\\" \\"text\\") IS 'Authoritative future landed-cost capitalization policy; excludes PPN, PPh, BPOM and operational expenses.'","--\n-- Name: is_journal_entry_balanced(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"is_journal_entry_balanced\\"(\\"p_entry_id\\" \\"uuid\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_debit NUMERIC;\nv_credit NUMERIC;\nBEGIN\nSELECT total_debit, total_credit \nINTO v_debit, v_credit\nFROM journal_entries\nWHERE id = p_entry_id;\n\nRETURN (abs(v_debit - v_credit) < 0.01) OR (v_debit = 0 AND v_credit = 0);\nEND;\n$$","--\n-- Name: is_read_only_user(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"is_read_only_user\\"() RETURNS boolean\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nuser_role TEXT;\nBEGIN\nSELECT role INTO user_role\nFROM user_profiles\nWHERE id = auth.uid();\n\nRETURN user_role = 'auditor_ca';\nEND;\n$$","--\n-- Name: FUNCTION \\"is_read_only_user\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"is_read_only_user\\"() IS 'Returns true if current user has auditor_ca role'","--\n-- Name: is_setup_mode(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"is_setup_mode\\"() RETURNS boolean\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT COALESCE((SELECT setup_mode FROM public.app_settings LIMIT 1), false);\n$$","--\n-- Name: learn_from_match(\\"text\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"learn_from_match\\"(\\"p_description\\" \\"text\\", \\"p_expense_category\\" \\"text\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_pattern  text;\nv_existing record;\nv_role     text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot update match memory', v_role;\nEND IF;\n\nv_pattern := LOWER(TRIM(SUBSTRING(p_description FROM 1 FOR 50)));\n\nSELECT * INTO v_existing FROM bank_match_memory\nWHERE description_pattern = v_pattern AND expense_category = p_expense_category;\n\nIF v_existing.id IS NOT NULL THEN\nUPDATE bank_match_memory\nSET match_count = match_count + 1, confidence_score = LEAST(confidence_score + 5, 100),\nlast_matched_at = now()\nWHERE id = v_existing.id;\nELSE\nINSERT INTO bank_match_memory (\ndescription_pattern, expense_category, match_count, confidence_score, created_by\n) VALUES (v_pattern, p_expense_category, 1, 50, auth.uid());\nEND IF;\nEND;\n$$","--\n-- Name: FUNCTION \\"learn_from_match\\"(\\"p_description\\" \\"text\\", \\"p_expense_category\\" \\"text\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"learn_from_match\\"(\\"p_description\\" \\"text\\", \\"p_expense_category\\" \\"text\\") IS 'Learn from manual matches to improve auto-matching accuracy'","--\n-- Name: link_bank_statement_line(\\"uuid\\", \\"text\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"link_bank_statement_line\\"(\\"p_bank_line_id\\" \\"uuid\\", \\"p_document_type\\" \\"text\\", \\"p_document_id\\" \\"uuid\\", \\"p_payment_kind\\" \\"text\\" DEFAULT 'supplier'::\\"text\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_bank_amount numeric;\nBEGIN\n  SELECT COALESCE(NULLIF(debit_amount,0),credit_amount,0) INTO v_bank_amount\n  FROM public.bank_statement_lines WHERE id=p_bank_line_id;\n  RETURN public.link_bank_statement_line(\n    p_bank_line_id,p_document_type,p_document_id,p_payment_kind,v_bank_amount\n  );\nEND $$","--\n-- Name: link_bank_statement_line(\\"uuid\\", \\"text\\", \\"uuid\\", \\"text\\", numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"link_bank_statement_line\\"(\\"p_bank_line_id\\" \\"uuid\\", \\"p_document_type\\" \\"text\\", \\"p_document_id\\" \\"uuid\\", \\"p_payment_kind\\" \\"text\\", \\"p_allocation_amount\\" numeric) RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_line public.bank_statement_lines%rowtype;\n  v_expense public.finance_expenses%rowtype;\n  v_je uuid; v_recognition_je uuid; v_bank_coa uuid; v_settlement_coa uuid;\n  v_bank_total numeric; v_bank_allocated numeric; v_bank_remaining numeric;\n  v_doc_total numeric; v_doc_allocated numeric; v_doc_remaining numeric; v_allocate numeric;\n  v_functional_amount numeric; v_rate numeric := 1; v_entry text; v_allocation_id uuid := gen_random_uuid();\n  v_bank_currency text; v_expense_currency text; v_period_id uuid;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  SELECT * INTO v_line FROM public.bank_statement_lines WHERE id=p_bank_line_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line not found'; END IF;\n\n  IF p_document_type='expense' THEN\n    SELECT * INTO v_expense FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;\n    IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\n    IF v_expense.approval_status <> 'approved' THEN\n      RAISE EXCEPTION 'Expense must be approved before bank allocation';\n    END IF;\n    -- Compare business dates only. Same-day and later settlement are valid;\n    -- created_at is a technical ingestion timestamp, not an obligation date.\n    IF v_expense.expense_date IS NULL THEN\n      RAISE EXCEPTION 'Expense business date is required before bank allocation';\n    END IF;\n    IF v_line.transaction_date < v_expense.expense_date THEN\n      RAISE EXCEPTION 'Bank transaction predates expense obligation';\n    END IF;\n    -- Compare business dates only. Same-day and later settlement are valid;\n    -- created_at is a technical ingestion timestamp, not an obligation date.\n    IF v_expense.expense_date IS NULL THEN\n      RAISE EXCEPTION 'Expense business date is required before bank allocation';\n    END IF;\n    IF v_line.transaction_date < v_expense.expense_date THEN\n      RAISE EXCEPTION 'Bank transaction predates expense obligation';\n    END IF;\n    SELECT je.id INTO v_recognition_je FROM public.journal_entries je\n     WHERE je.source_module IN ('expense','expenses')\n       AND (je.reference_id=p_document_id OR je.reference_number='EXP-'||p_document_id::text)\n       AND je.is_posted AND NOT COALESCE(je.is_reversed,false)\n     ORDER BY je.created_at DESC,je.id DESC LIMIT 1;\n    v_je := v_recognition_je;\n    IF public.expense_recognition_has_direct_bank_settlement(p_document_id, v_recognition_je) THEN\n      RAISE EXCEPTION 'Expense uses legacy direct-bank recognition; controlled legacy handling is required before reconciliation';\n    END IF;\n  ELSIF p_document_type='receipt' THEN SELECT journal_entry_id INTO v_je FROM public.receipt_vouchers WHERE id=p_document_id AND is_posted;\n  ELSIF p_document_type='payment' THEN SELECT journal_entry_id INTO v_je FROM public.payment_vouchers WHERE id=p_document_id AND is_posted;\n  ELSIF p_document_type='fund_transfer' THEN SELECT journal_entry_id INTO v_je FROM public.fund_transfers WHERE id=p_document_id AND status='posted';\n  ELSIF p_document_type='petty_cash' THEN SELECT id INTO v_je FROM public.journal_entries WHERE source_module='petty_cash' AND reference_id=p_document_id AND is_posted AND NOT COALESCE(is_reversed,false) ORDER BY created_at DESC LIMIT 1;\n  ELSIF p_document_type='tax_payment' THEN SELECT journal_entry_id INTO v_je FROM public.tax_payments WHERE id=p_document_id;\n  ELSIF p_document_type='journal' THEN SELECT id INTO v_je FROM public.journal_entries WHERE id=p_document_id AND is_posted AND NOT COALESCE(is_reversed,false);\n  ELSE RAISE EXCEPTION 'Unsupported reconciliation document type %',p_document_type; END IF;\n  IF v_je IS NULL THEN RAISE EXCEPTION 'Document must have an active posted journal before reconciliation'; END IF;\n\n  SELECT coa_id,upper(currency) INTO v_bank_coa,v_bank_currency\n    FROM public.bank_accounts WHERE id=v_line.bank_account_id;\n  IF v_bank_coa IS NULL THEN RAISE EXCEPTION 'Selected bank account has no General Ledger account'; END IF;\n\n  IF p_document_type <> 'expense' THEN\n    SELECT COALESCE(sum(CASE WHEN COALESCE(v_line.credit_amount,0)>0 THEN COALESCE(jel.transaction_debit,jel.debit)\n                            ELSE COALESCE(jel.transaction_credit,jel.credit) END),0)\n      INTO v_doc_total FROM public.journal_entry_lines jel\n     WHERE jel.journal_entry_id=v_je AND jel.account_id=v_bank_coa;\n    IF v_doc_total<=0.01 THEN RAISE EXCEPTION 'Document journal does not contain the selected bank account on the matching side'; END IF;\n  END IF;\n\n  v_bank_total:=COALESCE(NULLIF(v_line.debit_amount,0),v_line.credit_amount,0);\n  SELECT COALESCE(sum(allocation_amount),0) INTO v_bank_allocated\n    FROM public.bank_statement_allocations WHERE bank_statement_line_id=p_bank_line_id;\n\n  IF p_document_type='expense' THEN\n    IF COALESCE(v_line.debit_amount,0)<=0 THEN\n      RAISE EXCEPTION 'Expense payment requires an outgoing bank transaction';\n    END IF;\n    v_expense_currency:=upper(COALESCE(v_expense.transaction_currency,v_expense.currency_code,'IDR'));\n    IF COALESCE(v_bank_currency,'IDR')<>v_expense_currency THEN\n      RAISE EXCEPTION 'Direct expense allocation requires matching expense and bank currencies; use Payment Voucher for cross-currency payment';\n    END IF;\n    IF COALESCE(p_payment_kind,'supplier')='supplier' THEN\n      v_doc_total:=COALESCE(public.calculate_finance_expense_payable(p_document_id),0);\n      SELECT id INTO v_settlement_coa FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n    ELSIF p_payment_kind='pph23' THEN\n      v_doc_total:=COALESCE(v_expense.pph_amount,0);\n      SELECT id INTO v_settlement_coa FROM public.chart_of_accounts WHERE code='2132' LIMIT 1;\n    ELSE\n      RAISE EXCEPTION 'Unsupported expense payment kind %',p_payment_kind;\n    END IF;\n    IF v_settlement_coa IS NULL THEN RAISE EXCEPTION 'Expense settlement account is not configured'; END IF;\n    SELECT\n      COALESCE((SELECT sum(a.allocation_amount) FROM public.bank_statement_allocations a\n                 WHERE a.document_type='expense' AND a.document_id=p_document_id\n                   AND a.payment_kind=COALESCE(p_payment_kind,'supplier')),0)\n      + COALESCE((SELECT sum(COALESCE(NULLIF(b.debit_amount,0),b.credit_amount,0))\n                    FROM public.bank_statement_lines b\n                   WHERE b.matched_expense_id=p_document_id AND b.matching_status='confirmed'\n                     AND b.payment_kind=COALESCE(p_payment_kind,'supplier')\n                     AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id=b.id)),0)\n      + COALESCE((SELECT sum(va.allocated_amount) FROM public.voucher_allocations va\n                    JOIN public.payment_vouchers pv ON pv.id=va.payment_voucher_id\n                   WHERE va.finance_expense_id=p_document_id\n                     AND COALESCE(va.payment_kind,'supplier')=COALESCE(p_payment_kind,'supplier')\n                     AND pv.is_posted=true\n                     AND COALESCE(pv.payment_purpose,'general') NOT IN ('salary_advance','salary_advance_settlement')),0)\n      INTO v_doc_allocated;\n  ELSE\n    SELECT COALESCE(sum(allocation_amount),0) INTO v_doc_allocated\n      FROM public.bank_statement_allocations\n     WHERE document_type=p_document_type AND document_id=p_document_id\n       AND payment_kind=COALESCE(p_payment_kind,'supplier');\n  END IF;\n\n  v_bank_remaining:=v_bank_total-v_bank_allocated;\n  v_doc_remaining:=v_doc_total-v_doc_allocated;\n  v_allocate:=round(COALESCE(p_allocation_amount,LEAST(v_bank_remaining,v_doc_remaining)),2);\n  IF v_allocate<=0.01 THEN RAISE EXCEPTION 'No remaining amount is available to allocate'; END IF;\n  IF v_allocate>v_bank_remaining+0.01 THEN RAISE EXCEPTION 'Allocation exceeds remaining bank amount'; END IF;\n  IF v_allocate>v_doc_remaining+0.01 THEN RAISE EXCEPTION 'Allocation exceeds document outstanding amount'; END IF;\n\n  IF p_document_type='expense' THEN\n    IF EXISTS (SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id=p_bank_line_id AND a.document_type='expense' AND a.document_id=p_document_id AND a.payment_kind=COALESCE(p_payment_kind,'supplier')) THEN\n      RAISE EXCEPTION 'This expense allocation already exists';\n    END IF;\n    v_rate:=CASE WHEN v_expense_currency='IDR' THEN 1 ELSE COALESCE(v_expense.exchange_rate,0) END;\n    IF v_rate<=0 THEN RAISE EXCEPTION 'Expense exchange rate is required'; END IF;\n    v_functional_amount:=round(v_allocate*v_rate,2);\n    v_entry:=public.next_journal_entry_number();\n    SELECT id INTO v_period_id FROM public.accounting_periods\n     WHERE start_date<=v_line.transaction_date AND end_date>=v_line.transaction_date\n     ORDER BY start_date DESC LIMIT 1;\n    IF EXISTS (SELECT 1 FROM public.accounting_periods WHERE id=v_period_id AND status<>'open') THEN\n      RAISE EXCEPTION 'Cannot post expense payment in a closed accounting period';\n    END IF;\n    INSERT INTO public.journal_entries(entry_number,entry_date,period_id,source_module,reference_id,\n      reference_number,description,total_debit,total_credit,is_posted,posted_by,posted_at,created_by,\n      transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n    VALUES(v_entry,v_line.transaction_date,v_period_id,'expense_payment',p_document_id,\n      'EXP-PAY-'||v_allocation_id::text,'Expense bank payment: '||COALESCE(v_expense.voucher_number,p_document_id::text),\n      v_functional_amount,v_functional_amount,true,auth.uid(),now(),auth.uid(),\n      v_expense_currency,'IDR',v_rate,true)\n    RETURNING id INTO v_je;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,\n      transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate,supplier_id)\n    VALUES\n      (v_je,1,v_settlement_coa,'Expense settlement - '||COALESCE(v_expense.voucher_number,''),v_functional_amount,0,\n       v_expense_currency,v_allocate,0,'IDR',v_rate,v_expense.supplier_id),\n      (v_je,2,v_bank_coa,'Bank payment - '||COALESCE(v_expense.voucher_number,''),0,v_functional_amount,\n       v_bank_currency,0,v_allocate,'IDR',v_rate,v_expense.supplier_id);\n  END IF;\n\n  INSERT INTO public.bank_statement_allocations(id,bank_statement_line_id,document_type,document_id,journal_entry_id,allocation_amount,payment_kind,created_by)\n  VALUES(v_allocation_id,p_bank_line_id,p_document_type,p_document_id,v_je,v_allocate,COALESCE(p_payment_kind,'supplier'),auth.uid());\n\n  PERFORM public.sync_bank_line_allocation_owner(p_bank_line_id);\n  UPDATE public.bank_statement_lines SET matched_at=now(),matched_by=auth.uid(),manually_unlinked=true\n   WHERE id=p_bank_line_id;\n  PERFORM public.refresh_bank_statement_allocation_status(p_bank_line_id);\n  IF p_document_type='expense' THEN PERFORM public.recalculate_expense_payment_state(p_document_id); END IF;\n  RETURN jsonb_build_object('allocation_amount',v_allocate,'bank_total',v_bank_total,\n    'bank_allocated',v_bank_allocated+v_allocate,'bank_remaining',v_bank_remaining-v_allocate,\n    'document_total',v_doc_total,'document_allocated',v_doc_allocated+v_allocate,\n    'document_remaining',v_doc_remaining-v_allocate,'journal_entry_id',v_je);\nEND;\n$$","--\n-- Name: FUNCTION \\"link_bank_statement_line\\"(\\"p_bank_line_id\\" \\"uuid\\", \\"p_document_type\\" \\"text\\", \\"p_document_id\\" \\"uuid\\", \\"p_payment_kind\\" \\"text\\", \\"p_allocation_amount\\" numeric); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"link_bank_statement_line\\"(\\"p_bank_line_id\\" \\"uuid\\", \\"p_document_type\\" \\"text\\", \\"p_document_id\\" \\"uuid\\", \\"p_payment_kind\\" \\"text\\", \\"p_allocation_amount\\" numeric) IS 'Canonical bank allocation/payment clearing. Expense chronology uses expense_date (business obligation date), never created_at.'","--\n-- Name: lock_import_container(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"lock_import_container\\"(\\"p_container_id\\" \\"uuid\\", \\"p_user_id\\" \\"uuid\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot lock import containers', v_role;\nEND IF;\n\nUPDATE import_containers\nSET status = 'locked', locked_at = now(), locked_by = p_user_id, updated_at = now()\nWHERE id = p_container_id AND status = 'allocated';\nIF NOT FOUND THEN RAISE EXCEPTION 'Container not found or already locked'; END IF;\n\nUPDATE batches SET cost_locked = true, cost_locked_at = now(), updated_at = now()\nWHERE import_container_id = p_container_id AND cost_locked = false;\n\nRETURN true;\nEND;\n$$","--\n-- Name: log_audit_event(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"log_audit_event\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_user_id      uuid;\n  v_user_email   text;\n  v_old_data     jsonb;\n  v_new_data     jsonb;\n  v_changed_fields text[];\n  v_key          text;\nBEGIN\n  v_user_id := auth.uid();\n  IF v_user_id IS NOT NULL THEN\n    SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;\n  END IF;\n\n  IF TG_OP = 'DELETE' THEN\n    v_old_data := to_jsonb(OLD);\n    v_new_data := NULL;\n  ELSIF TG_OP = 'INSERT' THEN\n    v_old_data := NULL;\n    v_new_data := to_jsonb(NEW);\n  ELSIF TG_OP = 'UPDATE' THEN\n    v_old_data := to_jsonb(OLD);\n    v_new_data := to_jsonb(NEW);\n    v_changed_fields := ARRAY[]::text[];\n\n    FOR v_key IN SELECT jsonb_object_keys(v_new_data) LOOP\n      IF v_old_data->v_key IS DISTINCT FROM v_new_data->v_key THEN\n        v_changed_fields := array_append(v_changed_fields, v_key);\n      END IF;\n    END LOOP;\n\n    IF v_changed_fields = ARRAY['updated_at']::text[] THEN\n      RETURN NEW;\n    END IF;\n  END IF;\n\n  INSERT INTO audit_logs (\n    table_name, record_id, action_type,\n    old_values, new_values, changed_fields,\n    user_id, user_email, created_at\n  ) VALUES (\n    TG_TABLE_NAME,\n    COALESCE(NEW.id, OLD.id),\n    LOWER(TG_OP),\n    v_old_data, v_new_data, v_changed_fields,\n    v_user_id, v_user_email, now()\n  );\n\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  ELSE\n    RETURN NEW;\n  END IF;\nEND;\n$$","--\n-- Name: log_export(\\"text\\", \\"text\\", \\"jsonb\\", integer, \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"log_export\\"(\\"p_export_type\\" \\"text\\", \\"p_module_name\\" \\"text\\", \\"p_filter_criteria\\" \\"jsonb\\" DEFAULT NULL::\\"jsonb\\", \\"p_record_count\\" integer DEFAULT NULL::integer, \\"p_file_format\\" \\"text\\" DEFAULT 'csv'::\\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nlog_id UUID;\nBEGIN\nIF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;\n\nINSERT INTO export_audit_log (user_id, export_type, module_name, filter_criteria, record_count, file_format)\nVALUES (auth.uid(), p_export_type, p_module_name, p_filter_criteria, p_record_count, p_file_format)\nRETURNING id INTO log_id;\n\nRETURN log_id;\nEND;\n$$","--\n-- Name: FUNCTION \\"log_export\\"(\\"p_export_type\\" \\"text\\", \\"p_module_name\\" \\"text\\", \\"p_filter_criteria\\" \\"jsonb\\", \\"p_record_count\\" integer, \\"p_file_format\\" \\"text\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"log_export\\"(\\"p_export_type\\" \\"text\\", \\"p_module_name\\" \\"text\\", \\"p_filter_criteria\\" \\"jsonb\\", \\"p_record_count\\" integer, \\"p_file_format\\" \\"text\\") IS 'Logs export activity for audit trail'","--\n-- Name: log_timeline_event(\\"uuid\\", \\"text\\", \\"text\\", \\"text\\", \\"text\\", \\"text\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"log_timeline_event\\"(\\"p_inquiry_id\\" \\"uuid\\", \\"p_event_type\\" \\"text\\", \\"p_event_title\\" \\"text\\", \\"p_event_description\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_old_value\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_new_value\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_performed_by\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nnew_timeline_id uuid;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'sales', 'manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot log timeline events', v_role;\nEND IF;\n\nINSERT INTO crm_inquiry_timeline (\ninquiry_id, event_type, event_title, event_description,\nold_value, new_value, performed_by\n) VALUES (\np_inquiry_id, p_event_type, p_event_title, p_event_description,\np_old_value, p_new_value,\nCOALESCE(p_performed_by, auth.uid())\n) RETURNING id INTO new_timeline_id;\n\nRETURN new_timeline_id;\nEND;\n$$","--\n-- Name: lookup_email_by_username(\\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"lookup_email_by_username\\"(\\"p_username\\" \\"text\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_email TEXT;\nBEGIN\n  SELECT email INTO v_email\n  FROM user_profiles\n  WHERE lower(username) = lower(p_username)\n    AND is_active = true;\n  RETURN v_email;\nEND;\n$$","--\n-- Name: lookup_login_email(\\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"lookup_login_email\\"(\\"p_username\\" \\"text\\") RETURNS TABLE(\\"email\\" \\"text\\", \\"is_active\\" boolean)\n    LANGUAGE \\"sql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\n  SELECT up.email, up.is_active\n  FROM public.user_profiles up\n  WHERE lower(up.username) = lower(trim(p_username))\n  LIMIT 1;\n$$","--\n-- Name: manually_post_pending_fund_transfers(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"manually_post_pending_fund_transfers\\"() RETURNS TABLE(\\"transfer_num\\" \\"text\\", \\"post_status\\" \\"text\\", \\"post_message\\" \\"text\\")\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nv_transfer RECORD;\nv_from_account_id UUID;\nv_to_account_id UUID;\nv_from_currency TEXT;\nv_to_currency TEXT;\nv_journal_id UUID;\nv_entry_number TEXT;\nv_description TEXT;\nv_from_amount NUMERIC;\nv_to_amount NUMERIC;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot manually post fund transfers', v_role;\nEND IF;\n\nFOR v_transfer IN\nSELECT * FROM fund_transfers WHERE fund_transfers.status = 'pending' ORDER BY fund_transfers.created_at ASC\nLOOP\nBEGIN\nSELECT generate_journal_entry_number() INTO v_entry_number;\n\nIF v_transfer.from_account_type = 'petty_cash' THEN\nSELECT id, 'IDR' INTO v_from_account_id, v_from_currency FROM chart_of_accounts WHERE code = '1102' LIMIT 1;\nELSIF v_transfer.from_account_type = 'cash_on_hand' THEN\nSELECT id, 'IDR' INTO v_from_account_id, v_from_currency FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\nELSIF v_transfer.from_account_type = 'bank' THEN\nSELECT coa_id, currency INTO v_from_account_id, v_from_currency FROM bank_accounts WHERE id = v_transfer.from_bank_account_id;\nEND IF;\n\nIF v_transfer.to_account_type = 'petty_cash' THEN\nSELECT id, 'IDR' INTO v_to_account_id, v_to_currency FROM chart_of_accounts WHERE code = '1102' LIMIT 1;\nELSIF v_transfer.to_account_type = 'cash_on_hand' THEN\nSELECT id, 'IDR' INTO v_to_account_id, v_to_currency FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\nELSIF v_transfer.to_account_type = 'bank' THEN\nSELECT coa_id, currency INTO v_to_account_id, v_to_currency FROM bank_accounts WHERE id = v_transfer.to_bank_account_id;\nEND IF;\n\nIF v_from_account_id IS NULL OR v_to_account_id IS NULL THEN\ntransfer_num  := v_transfer.transfer_number;\npost_status   := 'ERROR';\npost_message  := 'Cannot determine chart of accounts';\nRETURN NEXT;\nCONTINUE;\nEND IF;\n\nv_from_amount := v_transfer.from_amount;\nv_to_amount   := v_transfer.to_amount;\n\nv_description := 'Fund Transfer ' || v_transfer.transfer_number;\nIF v_from_currency != v_to_currency THEN\nv_description := v_description || ' (FX: ' || v_from_currency || ' → ' || v_to_currency || ')';\nEND IF;\nIF v_transfer.description IS NOT NULL THEN\nv_description := v_description || ' - ' || v_transfer.description;\nEND IF;\n\nINSERT INTO journal_entries (\nentry_number, entry_date, source_module, reference_id, reference_number,\ndescription, total_debit, total_credit, is_posted, created_by\n) VALUES (\nv_entry_number, v_transfer.transfer_date, 'fund_transfers', v_transfer.id, v_transfer.transfer_number,\nv_description, v_from_amount, v_from_amount, true, v_transfer.created_by\n) RETURNING id INTO v_journal_id;\n\nIF v_from_currency = v_to_currency THEN\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\nVALUES\n(v_journal_id, 1, v_to_account_id,   v_from_amount, 0,             'Transfer In: '  || v_transfer.transfer_number),\n(v_journal_id, 2, v_from_account_id, 0,             v_from_amount, 'Transfer Out: ' || v_transfer.transfer_number);\nELSE\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\nVALUES\n(v_journal_id, 1, v_to_account_id,   v_from_amount, 0,\n'Transfer In: '  || v_transfer.transfer_number || ' (' || v_to_currency   || ' ' || v_to_amount::TEXT   || ')'),\n(v_journal_id, 2, v_from_account_id, 0,             v_from_amount,\n'Transfer Out: ' || v_transfer.transfer_number || ' (' || v_from_currency || ' ' || v_from_amount::TEXT || ')');\nEND IF;\n\nUPDATE fund_transfers\nSET journal_entry_id = v_journal_id, status = 'posted', posted_at = now(), posted_by = v_transfer.created_by\nWHERE id = v_transfer.id;\n\ntransfer_num := v_transfer.transfer_number;\npost_status  := 'POSTED';\npost_message := 'Successfully posted';\nRETURN NEXT;\n\nEXCEPTION WHEN OTHERS THEN\ntransfer_num := v_transfer.transfer_number;\npost_status  := 'ERROR';\npost_message := SQLERRM;\nRETURN NEXT;\nEND;\nEND LOOP;\nEND;\n$$","--\n-- Name: mark_requirement_sent(\\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"mark_requirement_sent\\"(\\"inquiry_id\\" \\"uuid\\", \\"requirement_type\\" \\"text\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts','sales') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot mark requirements as sent', v_role;\nEND IF;\n\nCASE requirement_type\nWHEN 'price'         THEN UPDATE crm_inquiries SET price_sent_at = now() WHERE id = inquiry_id;\nWHEN 'coa'           THEN UPDATE crm_inquiries SET coa_sent_at = now() WHERE id = inquiry_id;\nWHEN 'sample'        THEN UPDATE crm_inquiries SET sample_sent_at = now() WHERE id = inquiry_id;\nWHEN 'agency_letter' THEN UPDATE crm_inquiries SET agency_letter_sent_at = now() WHERE id = inquiry_id;\nELSE RAISE EXCEPTION 'Invalid requirement type: %', requirement_type;\nEND CASE;\nEND;\n$$","--\n-- Name: mark_tax_payment_reconciled(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"mark_tax_payment_reconciled\\"(\\"p_tax_payment_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  UPDATE tax_payments\n    SET status = 'reconciled', updated_at = now()\n    WHERE id = p_tax_payment_id AND status = 'posted';\n\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)\n  VALUES (auth.uid(), 'tax_payments', 'update', p_tax_payment_id,\n          jsonb_build_object('status','reconciled'));\nEND $$","--\n-- Name: move_expense_to_petty_cash(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"move_expense_to_petty_cash\\"(\\"p_expense_id\\" \\"uuid\\", \\"p_user_id\\" \\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_expense          RECORD;\nv_pc_number        TEXT;\nv_petty_cash_tx_id UUID;\nv_role             text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot move expenses to petty cash', v_role;\nEND IF;\n\nSELECT * INTO v_expense FROM finance_expenses WHERE id = p_expense_id;\nIF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\nIF v_expense.petty_cash_transaction_id IS NOT NULL THEN\nRAISE EXCEPTION 'Expense already linked to petty cash';\nEND IF;\n\nSELECT 'PC-' || TO_CHAR(v_expense.expense_date, 'YYYYMMDD') || '-' ||\nLPAD((COUNT(*) + 1)::TEXT, 4, '0')\nINTO v_pc_number FROM petty_cash_transactions WHERE transaction_date = v_expense.expense_date;\n\nINSERT INTO petty_cash_transactions (\ntransaction_number, transaction_date, transaction_type, amount, description,\nexpense_category, bank_account_id, created_by, source, paid_to, paid_by, finance_expense_id\n) VALUES (\nv_pc_number, v_expense.expense_date, 'expense', v_expense.amount, v_expense.description,\nv_expense.expense_category, v_expense.bank_account_id, p_user_id,\n'moved_from_tracker', v_expense.description, 'cash', v_expense.id\n) RETURNING id INTO v_petty_cash_tx_id;\n\nUPDATE finance_expenses\nSET petty_cash_transaction_id = v_petty_cash_tx_id, payment_method = 'cash', paid_by = 'cash'\nWHERE id = p_expense_id;\n\nRETURN v_petty_cash_tx_id;\nEND;\n$$","--\n-- Name: FUNCTION \\"move_expense_to_petty_cash\\"(\\"p_expense_id\\" \\"uuid\\", \\"p_user_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"move_expense_to_petty_cash\\"(\\"p_expense_id\\" \\"uuid\\", \\"p_user_id\\" \\"uuid\\") IS 'Moves an expense from finance_expenses to petty_cash_transactions. Creates link and updates payment method to cash (petty cash payments are recorded as cash).'","--\n-- Name: move_expense_to_tracker(\\"uuid\\", \\"uuid\\", \\"text\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"move_expense_to_tracker\\"(\\"p_petty_cash_id\\" \\"uuid\\", \\"p_bank_account_id\\" \\"uuid\\", \\"p_payment_method\\" \\"text\\", \\"p_user_id\\" \\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_pc_tx            RECORD;\nv_expense_id       UUID;\nv_finance_category TEXT;\nv_role             text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot move petty cash to tracker', v_role;\nEND IF;\n\nSELECT * INTO v_pc_tx FROM petty_cash_transactions\nWHERE id = p_petty_cash_id AND transaction_type = 'expense';\nIF NOT FOUND THEN RAISE EXCEPTION 'Petty cash expense not found'; END IF;\n\nIF v_pc_tx.finance_expense_id IS NOT NULL THEN\nUPDATE finance_expenses\nSET payment_method = p_payment_method, bank_account_id = p_bank_account_id, paid_by = 'bank'\nWHERE id = v_pc_tx.finance_expense_id RETURNING id INTO v_expense_id;\nRETURN v_expense_id;\nEND IF;\n\nv_finance_category := CASE\nWHEN v_pc_tx.expense_category IN ('Office Supplies','Postage & Courier','Cleaning & Maintenance','Miscellaneous') THEN 'office_admin'\nWHEN v_pc_tx.expense_category = 'Transportation' THEN 'delivery_sales'\nWHEN v_pc_tx.expense_category = 'Utilities'      THEN 'utilities'\nELSE 'other'\nEND;\n\nINSERT INTO finance_expenses (\nexpense_category, expense_type, amount, expense_date, description,\npayment_method, bank_account_id, paid_by, created_by, petty_cash_transaction_id\n) VALUES (\nv_finance_category, 'admin', v_pc_tx.amount, v_pc_tx.transaction_date,\nv_pc_tx.description || ' (Moved from Petty Cash: ' || v_pc_tx.transaction_number || ')',\np_payment_method, p_bank_account_id, 'bank', p_user_id, v_pc_tx.id\n) RETURNING id INTO v_expense_id;\n\nUPDATE petty_cash_transactions\nSET finance_expense_id = v_expense_id, source = 'moved_to_tracker'\nWHERE id = p_petty_cash_id;\n\nRETURN v_expense_id;\nEND;\n$$","--\n-- Name: FUNCTION \\"move_expense_to_tracker\\"(\\"p_petty_cash_id\\" \\"uuid\\", \\"p_bank_account_id\\" \\"uuid\\", \\"p_payment_method\\" \\"text\\", \\"p_user_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"move_expense_to_tracker\\"(\\"p_petty_cash_id\\" \\"uuid\\", \\"p_bank_account_id\\" \\"uuid\\", \\"p_payment_method\\" \\"text\\", \\"p_user_id\\" \\"uuid\\") IS 'Moves an expense from petty_cash_transactions to finance_expenses for bank reconciliation. Creates or updates finance_expenses entry.'","--\n-- Name: next_capital_contribution_number(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"next_capital_contribution_number\\"(\\"p_date\\" \\"date\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $_$\nDECLARE v_prefix text := 'CC' || to_char(p_date,'YYMM'); v_seq integer;\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtext('capital-contribution-number:' || v_prefix));\n  SELECT COALESCE(max((regexp_match(voucher_number,'([0-9]+)$'))[1]::integer),0)+1 INTO v_seq\n  FROM public.capital_contributions WHERE voucher_number LIKE v_prefix || '-%';\n  RETURN v_prefix || '-' || lpad(v_seq::text,4,'0');\nEND $_$","--\n-- Name: next_expense_voucher_number(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"next_expense_voucher_number\\"(\\"p_expense_date\\" \\"date\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $_$\nDECLARE\n  v_year text;\n  v_prefix text;\n  v_next int;\nBEGIN\n  IF p_expense_date IS NULL THEN\n    RAISE EXCEPTION 'Expense date is required';\n  END IF;\n\n  v_year := to_char(p_expense_date, 'YY');\n  v_prefix := 'EXP/' || v_year || '/';\n\n  -- One lock covers both the canonical EXP/YY/NNN series and the preserved\n  -- historical EXP/YY-YY/NNN series so their numeric suffixes cannot collide.\n  PERFORM pg_advisory_xact_lock(hashtext('expense_voucher_' || v_year));\n\n  SELECT COALESCE(MAX((regexp_match(voucher_number, '/([0-9]+)$'))[1]::int), 0) + 1\n    INTO v_next\n    FROM public.finance_expenses\n   WHERE voucher_number LIKE v_prefix || '%'\n      OR voucher_number LIKE 'EXP/' || v_year || '-' || v_year || '/%';\n\n  RETURN v_prefix || lpad(v_next::text, 3, '0');\nEND;\n$_$","--\n-- Name: next_journal_entry_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"next_journal_entry_number\\"() RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $_$\nDECLARE\nv_prefix TEXT;\nv_max_num INTEGER;\nv_number TEXT;\nv_lock_id BIGINT;\nBEGIN\nv_prefix := 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM');\n\nv_lock_id := hashtext('je_number_' || v_prefix);\nPERFORM pg_advisory_xact_lock(v_lock_id);\n\nSELECT COALESCE(MAX(\nCAST(NULLIF(SUBSTRING(entry_number FROM LENGTH(v_prefix) + 2), '') AS INTEGER)\n), 0) + 1\nINTO v_max_num\nFROM journal_entries\nWHERE entry_number LIKE v_prefix || '-%'\nAND SUBSTRING(entry_number FROM LENGTH(v_prefix) + 2) ~ '^\\\\d+$';\n\nv_number := v_prefix || '-' || LPAD(v_max_num::TEXT, 4, '0');\n\nRETURN v_number;\nEND;\n$_$","--\n-- Name: next_loan_number(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"next_loan_number\\"(\\"p_date\\" \\"date\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $_$\nDECLARE v_prefix text := 'LN' || to_char(p_date,'YYMM'); v_seq integer;\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtext('loan-number:' || v_prefix));\n  SELECT COALESCE(max((regexp_match(loan_number,'([0-9]+)$'))[1]::integer),0)+1 INTO v_seq\n  FROM public.loans WHERE loan_number LIKE v_prefix || '-%';\n  RETURN v_prefix || '-' || lpad(v_seq::text,4,'0');\nEND $_$","--\n-- Name: next_loan_transaction_number(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"next_loan_transaction_number\\"(\\"p_date\\" \\"date\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $_$\nDECLARE v_prefix text := 'LP' || to_char(p_date,'YYMM'); v_seq integer;\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtext('loan-transaction-number:' || v_prefix));\n  SELECT COALESCE(max((regexp_match(transaction_number,'([0-9]+)$'))[1]::integer),0)+1 INTO v_seq\n  FROM public.loan_transactions WHERE transaction_number LIKE v_prefix || '-%';\n  RETURN v_prefix || '-' || lpad(v_seq::text,4,'0');\nEND $_$","--\n-- Name: next_payment_voucher_number(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"next_payment_voucher_number\\"(\\"p_voucher_date\\" \\"date\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $_$\nDECLARE\n  v_start_year int;\n  v_fy text;\n  v_prefix text;\n  v_next int;\nBEGIN\n  IF p_voucher_date IS NULL THEN RAISE EXCEPTION 'Voucher date is required'; END IF;\n  v_start_year := EXTRACT(YEAR FROM p_voucher_date)::int;\n  v_fy := right(v_start_year::text, 2) || '-' || right(v_start_year::text, 2);\n  v_prefix := 'PV/' || v_fy || '/';\n  PERFORM pg_advisory_xact_lock(hashtext('payment_voucher_' || v_fy));\n  SELECT COALESCE(MAX((regexp_match(voucher_number, '/([0-9]+)$'))[1]::int), 0) + 1\n    INTO v_next\n    FROM public.payment_vouchers\n   WHERE voucher_number LIKE v_prefix || '%';\n  RETURN v_prefix || lpad(v_next::text, 3, '0');\nEND;\n$_$","--\n-- Name: next_receipt_voucher_number(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"next_receipt_voucher_number\\"(\\"p_voucher_date\\" \\"date\\") RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $_$\nDECLARE\n  v_prefix text;\n  v_next int;\nBEGIN\n  IF p_voucher_date IS NULL THEN RAISE EXCEPTION 'Voucher date is required'; END IF;\n  v_prefix := 'RV' || to_char(p_voucher_date, 'YYMM') || '-';\n  PERFORM pg_advisory_xact_lock(hashtext('receipt_voucher_' || v_prefix));\n  SELECT COALESCE(MAX((regexp_match(voucher_number, '-([0-9]+)$'))[1]::int), 0) + 1\n    INTO v_next\n    FROM public.receipt_vouchers\n   WHERE voucher_number LIKE v_prefix || '%';\n  RETURN v_prefix || lpad(v_next::text, 4, '0');\nEND;\n$_$","--\n-- Name: normalize_customer_identity(\\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"normalize_customer_identity\\"(\\"p_value\\" \\"text\\") RETURNS \\"text\\"\n    LANGUAGE \\"sql\\" IMMUTABLE PARALLEL SAFE\n    AS $$\n  SELECT regexp_replace(lower(trim(COALESCE(p_value,''))), '[^a-z0-9]+', '', 'g');\n$$","--\n-- Name: normalize_customer_tax_id(\\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"normalize_customer_tax_id\\"(\\"p_value\\" \\"text\\") RETURNS \\"text\\"\n    LANGUAGE \\"sql\\" IMMUTABLE PARALLEL SAFE\n    AS $$\n  SELECT regexp_replace(COALESCE(p_value,''), '[^0-9]+', '', 'g');\n$$","--\n-- Name: normalize_fund_transfer_exchange_rate(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"normalize_fund_transfer_exchange_rate\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_from_currency text;\n  v_to_currency text;\nBEGIN\n  v_from_currency:=CASE WHEN NEW.from_account_type='bank'\n    THEN (SELECT upper(currency) FROM public.bank_accounts WHERE id=NEW.from_bank_account_id) ELSE 'IDR' END;\n  v_to_currency:=CASE WHEN NEW.to_account_type='bank'\n    THEN (SELECT upper(currency) FROM public.bank_accounts WHERE id=NEW.to_bank_account_id) ELSE 'IDR' END;\n  IF v_from_currency='USD' AND v_to_currency='IDR' AND NEW.from_amount>0 THEN\n    NEW.exchange_rate:=NEW.to_amount/NEW.from_amount;\n  ELSIF v_from_currency='IDR' AND v_to_currency='USD' AND NEW.to_amount>0 THEN\n    NEW.exchange_rate:=NEW.from_amount/NEW.to_amount;\n  ELSIF v_from_currency='USD' AND v_to_currency='USD' THEN\n    NEW.exchange_rate:=COALESCE(NULLIF(NEW.exchange_rate,0),public.get_reporting_usd_rate());\n  ELSE\n    NEW.exchange_rate:=1;\n  END IF;\n  IF NEW.exchange_rate IS NULL OR NEW.exchange_rate<=0 OR ((v_from_currency='USD' OR v_to_currency='USD') AND NEW.exchange_rate<=1) THEN\n    RAISE EXCEPTION 'A valid USD-to-IDR exchange rate is required for this Fund Transfer';\n  END IF;\n  RETURN NEW;\nEND $$","--\n-- Name: normalize_unlinked_expense_payment(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"normalize_unlinked_expense_payment\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF COALESCE(current_setting('app.finance_historical_repair', true), 'off') = 'on' THEN\n    RETURN NEW;\n  END IF;\n  IF NEW.payment_method = 'bank_transfer'\n     AND COALESCE(current_setting('app.expense_atomic_bank_link', true), 'off') <> 'on' THEN\n    NEW.payment_method := NULL;\n    NEW.bank_account_id := NULL;\n    NEW.paid_by := NULL;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"normalize_unlinked_expense_payment\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"normalize_unlinked_expense_payment\\"() IS 'Prevents an unlinked bank_transfer expense from crediting Bank at recognition time; actual payment is posted by payment voucher/reconciliation.'","--\n-- Name: notify_appointment_participants(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"notify_appointment_participants\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nparticipant_id uuid;\nappointment_time text;\nnotification_title text;\nnotification_message text;\nBEGIN\n-- Only process meeting-related activities\nIF NEW.activity_type NOT IN ('meeting', 'video_call', 'phone_call') THEN\nRETURN NEW;\nEND IF;\n\n-- Only process if there's a follow_up_date (appointment date)\nIF NEW.follow_up_date IS NULL THEN\nRETURN NEW;\nEND IF;\n\n-- Format appointment time\nappointment_time := to_char(NEW.follow_up_date, 'Mon DD, YYYY at HH24:MI');\n\n-- Set notification title based on operation\nIF TG_OP = 'INSERT' THEN\nnotification_title := 'New Appointment';\nELSE\nnotification_title := 'Appointment Updated';\nEND IF;\n\n-- Build notification message\nnotification_message := NEW.subject || ' - ' || appointment_time;\n\n-- Send notification to each participant\nIF NEW.participants IS NOT NULL AND array_length(NEW.participants, 1) > 0 THEN\nFOREACH participant_id IN ARRAY NEW.participants\nLOOP\nINSERT INTO notifications (\nuser_id,\ntype,\ntitle,\nmessage,\nreference_id,\nreference_type,\nis_read,\ncreated_at\n) VALUES (\nparticipant_id,\n'appointment',\nnotification_title,\nnotification_message,\nNEW.id,\n'crm_activity',\nfalse,\nnow()\n)\nON CONFLICT DO NOTHING;\nEND LOOP;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: notify_mentioned_users(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"notify_mentioned_users\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- This is a placeholder for notification logic\n-- In a real implementation, you would insert notifications here\nRETURN NEW;\nEND;\n$$","--\n-- Name: notify_task_assignment(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"notify_task_assignment\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- This is a placeholder for notification logic\n-- In a real implementation, you would insert notifications here\nRETURN NEW;\nEND;\n$$","--\n-- Name: petty_cash_resolved_tx_id(\\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"petty_cash_resolved_tx_id\\"(\\"p_reference_id\\" \\"uuid\\", \\"p_reference_number\\" \\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"sql\\" IMMUTABLE\n    SET \\"search_path\\" TO ''\n    AS $_$\n  SELECT COALESCE(\n    p_reference_id,\n    CASE\n      WHEN p_reference_number ~ '^PC-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'\n      THEN SUBSTRING(p_reference_number FROM 4)::uuid\n      ELSE NULL::uuid\n    END\n  )\n$_$","--\n-- Name: post_batch_purchase_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_batch_purchase_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_je_id UUID;\nv_je_number TEXT;\nv_inventory_account_id UUID;\nv_ap_account_id UUID;\nv_ppn_account_id UUID;\nv_purchase_value DECIMAL(18,2);\nv_ppn_amount DECIMAL(18,2);\nv_total_amount DECIMAL(18,2);\nv_cost_per_unit DECIMAL(18,2);\nBEGIN\n-- Only post on insert for batches with supplier\nIF TG_OP = 'INSERT' AND NEW.supplier_id IS NOT NULL THEN\n\n-- Calculate cost per unit if not provided\nv_cost_per_unit := COALESCE(NEW.cost_per_unit, \nCASE WHEN NEW.import_quantity > 0 \nTHEN NEW.import_price / NEW.import_quantity \nELSE 0 \nEND);\n\n-- Calculate purchase value\nv_purchase_value := NEW.import_quantity * v_cost_per_unit;\nv_ppn_amount := v_purchase_value * 0.11; -- 11% PPN\nv_total_amount := v_purchase_value + v_ppn_amount;\n\n-- Skip if amount is zero\nIF v_total_amount <= 0 THEN\nRETURN NEW;\nEND IF;\n\n-- Get account IDs\nSELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;\nSELECT id INTO v_ap_account_id FROM chart_of_accounts WHERE code = '2110' LIMIT 1;\nSELECT id INTO v_ppn_account_id FROM chart_of_accounts WHERE code = '1150' LIMIT 1;\n\nIF v_inventory_account_id IS NULL OR v_ap_account_id IS NULL THEN\n-- If accounts don't exist, skip accounting (don't fail the batch creation)\nRETURN NEW;\nEND IF;\n\n-- Generate journal entry number\nv_je_number := 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '-' || LPAD((\nSELECT COUNT(*) + 1 FROM journal_entries WHERE entry_number LIKE 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '%'\n)::TEXT, 4, '0');\n\n-- Create journal entry\nINSERT INTO journal_entries (\nentry_number, \nentry_date, \nsource_module, \nreference_id, \nreference_number,\ndescription, \ntotal_debit, \ntotal_credit, \nis_posted, \nposted_by\n) VALUES (\nv_je_number, \nNEW.import_date, \n'batch_purchase', \nNEW.id, \nNEW.batch_number,\n'Goods Received - Batch: ' || NEW.batch_number,\nv_total_amount, \nv_total_amount, \ntrue, \nNEW.created_by\n) RETURNING id INTO v_je_id;\n\n-- Debit: Inventory (purchase value)\nINSERT INTO journal_entry_lines (\njournal_entry_id, \nline_number, \naccount_id, \ndescription, \ndebit, \ncredit, \nsupplier_id,\nbatch_id\n) VALUES (\nv_je_id, \n1, \nv_inventory_account_id, \n'Inventory - Batch ' || NEW.batch_number, \nv_purchase_value, \n0, \nNEW.supplier_id,\nNEW.id\n);\n\n-- Debit: PPN Input (if applicable)\nIF v_ppn_amount > 0 AND v_ppn_account_id IS NOT NULL THEN\nINSERT INTO journal_entry_lines (\njournal_entry_id, \nline_number, \naccount_id, \ndescription, \ndebit, \ncredit, \nsupplier_id,\nbatch_id\n) VALUES (\nv_je_id, \n2, \nv_ppn_account_id, \n'PPN Input - Batch ' || NEW.batch_number, \nv_ppn_amount, \n0, \nNEW.supplier_id,\nNEW.id\n);\nEND IF;\n\n-- Credit: Accounts Payable (total amount)\nINSERT INTO journal_entry_lines (\njournal_entry_id, \nline_number, \naccount_id, \ndescription, \ndebit, \ncredit, \nsupplier_id,\nbatch_id\n) VALUES (\nv_je_id, \n3, \nv_ap_account_id, \n'A/P - Batch ' || NEW.batch_number, \n0, \nv_total_amount, \nNEW.supplier_id,\nNEW.id\n);\n\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"post_batch_purchase_journal\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"post_batch_purchase_journal\\"() IS 'Posts batch purchase to accounting: Dr Inventory + Dr PPN Input, Cr Accounts Payable. Triggered when batch is created with supplier.'","--\n-- Name: post_capital_contribution_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_capital_contribution_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_je_id uuid; v_bank_coa_id uuid; v_capital_account_id uuid; v_bank_currency text;\n  v_currency text; v_rate numeric; v_functional_amount numeric; v_description text;\nBEGIN\n  IF COALESCE(current_setting('app.finance_metadata_repair',true),'off')='on' THEN RETURN NEW; END IF;\n  IF TG_OP='UPDATE' AND OLD.journal_entry_id IS NOT NULL THEN RETURN NEW; END IF;\n  SELECT coa_id,upper(currency) INTO v_bank_coa_id,v_bank_currency FROM public.bank_accounts WHERE id=NEW.bank_account_id AND is_active=true;\n  IF v_bank_coa_id IS NULL THEN RAISE EXCEPTION 'Capital contribution bank account is missing or has no active GL account'; END IF;\n  IF NEW.director_id IS NOT NULL THEN SELECT capital_account_id INTO v_capital_account_id FROM public.directors WHERE id=NEW.director_id; END IF;\n  IF v_capital_account_id IS NULL THEN SELECT id INTO v_capital_account_id FROM public.chart_of_accounts WHERE code='3100' AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1; END IF;\n  IF v_capital_account_id IS NULL THEN RAISE EXCEPTION 'Owner Capital account 3100 is not configured'; END IF;\n  v_currency:=upper(COALESCE(NEW.transaction_currency,v_bank_currency,'IDR'));\n  v_rate:=CASE WHEN v_currency='IDR' THEN 1 ELSE NEW.exchange_rate END;\n  IF v_currency<>v_bank_currency OR v_rate IS NULL OR v_rate<=0 OR (v_currency='USD' AND v_rate<=1) THEN RAISE EXCEPTION 'Capital currency or exchange rate is invalid for the selected bank'; END IF;\n  NEW.transaction_currency:=v_currency; NEW.functional_currency:='IDR'; NEW.bank_account_currency:=v_bank_currency; NEW.exchange_rate:=v_rate;\n  v_functional_amount:=round(NEW.amount*v_rate,2); v_description:=COALESCE(NULLIF(NEW.description,''),'Capital Contribution: '||NEW.voucher_number);\n  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,\n    is_posted,posted_at,posted_by,created_by,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n  VALUES(public.generate_journal_entry_number(),NEW.voucher_date,'capital_contribution',NEW.id,NEW.voucher_number,v_description,v_functional_amount,v_functional_amount,\n    true,now(),NEW.created_by,NEW.created_by,v_currency,'IDR',v_rate,true) RETURNING id INTO v_je_id;\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n  VALUES(v_je_id,1,v_bank_coa_id,v_description,v_functional_amount,0,v_currency,NEW.amount,0,'IDR',v_rate),\n        (v_je_id,2,v_capital_account_id,v_description,0,v_functional_amount,v_currency,0,NEW.amount,'IDR',v_rate);\n  NEW.journal_entry_id:=v_je_id;\n  RETURN NEW;\nEND $$","--\n-- Name: post_credit_note_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_credit_note_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_should_post boolean := false;\nBEGIN\n  IF NEW.status = 'approved' AND NEW.journal_entry_id IS NULL THEN\n    IF TG_OP = 'INSERT' THEN\n      v_should_post := true;\n    ELSIF TG_OP = 'UPDATE' AND (OLD.status IS DISTINCT FROM NEW.status) THEN\n      v_should_post := true;\n    END IF;\n  END IF;\n\n  IF v_should_post THEN\n    NEW.journal_entry_id := public._post_credit_note_je(NEW);\n  END IF;\n\n  RETURN NEW;\nEND $$","--\n-- Name: post_customs_broker_accounting(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_customs_broker_accounting\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $_$\nDECLARE\n  v_je uuid;\n  v_expense_account uuid;\n  v_ppn_account uuid;\n  v_pph_account uuid;\n  v_stamp_account uuid;\n  v_cash_account uuid;\n  v_ap_account uuid;\n  v_line_no int := 1;\n  v_expense numeric(18,2) := COALESCE(NEW.amount, 0);\n  v_reimbursement numeric(18,2) := 0;\n  v_reimbursement_ppn numeric(18,2) := 0;\n  v_header_ppn numeric(18,2) := COALESCE(NEW.ppn_amount, 0);\n  v_pph numeric(18,2) := COALESCE(NEW.pph_amount, 0);\n  v_stamp numeric(18,2) := COALESCE(NEW.stamp_duty_amount, 0);\n  v_total_ppn numeric(18,2);\n  v_cash numeric(18,2);\n  v_entry_number text;\n  v_item jsonb;\n  v_item_amount numeric(18,2);\n  v_item_ppn numeric(18,2);\n  v_item_supplier uuid;\n  v_supplier_total numeric(18,2);\n  v_is_outstanding boolean := NEW.payment_method IS NULL OR NEW.payment_method = 'outstanding';\nBEGIN\n  IF NEW.expense_category <> 'import_broker' THEN\n    RETURN NEW;\n  END IF;\n\n  -- Replace the standard compatibility posting. The reference is unique to\n  -- the source expense, so the final transaction has exactly one JE.\n  DELETE FROM journal_entry_lines WHERE journal_entry_id IN\n    (SELECT id FROM journal_entries WHERE reference_number = 'EXP-' || NEW.id::text);\n  DELETE FROM journal_entries WHERE reference_number = 'EXP-' || NEW.id::text;\n\n  SELECT id INTO v_expense_account FROM chart_of_accounts WHERE code = '5300' LIMIT 1;\n  SELECT id INTO v_ppn_account FROM chart_of_accounts WHERE code = '1150' LIMIT 1;\n  SELECT id INTO v_pph_account FROM chart_of_accounts WHERE code = '2132' LIMIT 1;\n  SELECT id INTO v_stamp_account FROM chart_of_accounts WHERE code = '6950' LIMIT 1;\n  SELECT id INTO v_ap_account FROM chart_of_accounts WHERE code = '2110' LIMIT 1;\n  IF NEW.payment_method = 'cash' THEN\n    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\n  ELSIF NEW.payment_method = 'petty_cash' THEN\n    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1102' LIMIT 1;\n  ELSIF NEW.payment_method = 'bank_transfer' AND NEW.bank_account_id IS NOT NULL THEN\n    SELECT coa_id INTO v_cash_account FROM bank_accounts WHERE id = NEW.bank_account_id;\n  ELSE\n    SELECT id INTO v_cash_account FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\n  END IF;\n\n  IF v_expense_account IS NULL OR v_ppn_account IS NULL OR v_ap_account IS NULL THEN\n    RAISE EXCEPTION 'Customs broker posting requires accounts 5300, 1150 and 2110';\n  END IF;\n  IF v_is_outstanding = false AND v_cash_account IS NULL THEN\n    RAISE EXCEPTION 'Customs broker posting requires a cash/bank account';\n  END IF;\n  IF v_pph > 0 AND v_pph_account IS NULL THEN\n    RAISE EXCEPTION 'Customs broker posting requires PPh23 payable account 2132';\n  END IF;\n  IF v_stamp > 0 AND v_stamp_account IS NULL THEN\n    RAISE EXCEPTION 'Customs broker posting requires stamp duty account 6950';\n  END IF;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items, '[]'::jsonb)) LOOP\n    v_item_amount := COALESCE((v_item->>'amount')::numeric, 0);\n    v_item_ppn := COALESCE((v_item->>'ppn_amount')::numeric, 0);\n    -- An inclusive line stores the gross reimbursement amount; recoverable\n    -- PPN is removed from expense. Excluded lines store the taxable amount.\n    v_item_amount := CASE WHEN v_item->>'ppn_treatment' = 'included'\n      THEN GREATEST(v_item_amount - v_item_ppn, 0) ELSE v_item_amount END;\n    v_reimbursement := v_reimbursement + v_item_amount;\n    v_reimbursement_ppn := v_reimbursement_ppn + v_item_ppn;\n  END LOOP;\n  v_expense := v_expense + v_reimbursement + v_stamp;\n  v_total_ppn := v_header_ppn + v_reimbursement_ppn;\n  v_cash := v_expense + v_total_ppn - v_pph;\n\n  SELECT 'JE' || to_char(NEW.expense_date, 'YYMM') || '-' || lpad((\n    COALESCE(max(CAST(substring(entry_number FROM '-([0-9]+)$') AS int)), 0) + 1\n  )::text, 4, '0') INTO v_entry_number\n  FROM journal_entries WHERE entry_number LIKE 'JE' || to_char(NEW.expense_date, 'YYMM') || '-%';\n\n  INSERT INTO journal_entries(entry_number, entry_date, source_module, reference_id,\n    reference_number, description, transaction_category, total_debit, total_credit,\n    is_posted, posted_at, created_by)\n  VALUES(v_entry_number, NEW.expense_date, 'expenses', NEW.id, 'EXP-' || NEW.id::text,\n    COALESCE(NEW.description, 'Customs Broker Invoice'), 'import_broker',\n    v_expense + v_total_ppn, v_expense + v_total_ppn, true, now(), NEW.created_by)\n  RETURNING id INTO v_je;\n\n  INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n  VALUES(v_je,v_line_no,v_expense_account,'Broker service expense',COALESCE(NEW.amount,0),0,NEW.supplier_id);\n  v_line_no := v_line_no + 1;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items, '[]'::jsonb)) LOOP\n    v_item_amount := COALESCE((v_item->>'amount')::numeric, 0);\n    v_item_ppn := COALESCE((v_item->>'ppn_amount')::numeric, 0);\n    v_item_supplier := NULLIF(v_item->>'supplier_id','')::uuid;\n    v_item_amount := CASE WHEN v_item->>'ppn_treatment' = 'included'\n      THEN GREATEST(v_item_amount - v_item_ppn, 0) ELSE v_item_amount END;\n    IF v_item_amount > 0 THEN\n      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n      VALUES(v_je,v_line_no,v_expense_account,'Reimbursement - ' || COALESCE(v_item->>'description','line'),v_item_amount,0,COALESCE(v_item_supplier,NEW.supplier_id));\n      v_line_no := v_line_no + 1;\n    END IF;\n    IF v_item_ppn > 0 THEN\n      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n      VALUES(v_je,v_line_no,v_ppn_account,'PPN Masukan - reimbursement',v_item_ppn,0,COALESCE(v_item_supplier,NEW.supplier_id));\n      v_line_no := v_line_no + 1;\n    END IF;\n  END LOOP;\n\n  IF v_header_ppn > 0 THEN\n    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n    VALUES(v_je,v_line_no,v_ppn_account,'PPN Masukan - broker invoice',v_header_ppn,0,NEW.supplier_id);\n    v_line_no := v_line_no + 1;\n  END IF;\n  IF v_stamp > 0 THEN\n    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n    VALUES(v_je,v_line_no,v_stamp_account,'Bea Meterai',v_stamp,0,NEW.supplier_id);\n    v_line_no := v_line_no + 1;\n  END IF;\n  IF v_pph > 0 THEN\n    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n    VALUES(v_je,v_line_no,v_pph_account,'PPh23 Payable',0,v_pph,NEW.supplier_id);\n    v_line_no := v_line_no + 1;\n  END IF;\n\n  IF v_is_outstanding THEN\n    -- One AP credit per supplier: broker service and every reimbursement\n    -- supplier remain independently visible in Supplier/Party Ledger.\n    v_supplier_total := COALESCE(NEW.amount,0) + v_header_ppn + v_stamp - v_pph;\n    IF v_supplier_total <> 0 THEN\n      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n      VALUES(v_je,v_line_no,v_ap_account,'A/P - broker supplier',0,v_supplier_total,NEW.supplier_id);\n      v_line_no := v_line_no + 1;\n    END IF;\n    FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items, '[]'::jsonb)) LOOP\n      v_item_amount := COALESCE((v_item->>'amount')::numeric, 0);\n      v_item_ppn := COALESCE((v_item->>'ppn_amount')::numeric, 0);\n      v_item_supplier := NULLIF(v_item->>'supplier_id','')::uuid;\n      v_item_amount := CASE WHEN v_item->>'ppn_treatment' = 'included' THEN GREATEST(v_item_amount-v_item_ppn,0) ELSE v_item_amount END;\n      IF v_item_amount + v_item_ppn > 0 THEN\n        INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n        VALUES(v_je,v_line_no,v_ap_account,'A/P - reimbursement supplier',0,v_item_amount+v_item_ppn,COALESCE(v_item_supplier,NEW.supplier_id));\n        v_line_no := v_line_no + 1;\n      END IF;\n    END LOOP;\n  ELSE\n    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n    VALUES(v_je,v_line_no,v_cash_account,'Cash payment - customs broker',0,v_cash,NEW.supplier_id);\n  END IF;\n  RETURN NEW;\nEND;\n$_$","--\n-- Name: post_customs_broker_canonical(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_customs_broker_canonical\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\nv_je uuid;\nv_expense_account uuid;\nv_ppn_account uuid;\nv_pph_account uuid;\nv_stamp_account uuid;\nv_ap_account uuid;\nv_cash_account uuid;\nv_item jsonb;\nv_supplier uuid;\nv_line_total numeric;\nv_line_ppn numeric;\nv_line_no int := 1;\nv_reimbursement numeric := 0;\nv_expense_total numeric;\nv_pph numeric := COALESCE(NEW.pph_amount,0);\nv_credit_total numeric;\nv_outstanding boolean := NEW.payment_method IS NULL OR NEW.payment_method IN ('outstanding','bank_transfer');\nBEGIN\nIF NEW.expense_category <> 'import_broker' THEN RETURN NEW; END IF;\n\n-- Find the existing active journal (if any) so we can preserve its identity.\nSELECT id INTO v_je\nFROM public.journal_entries\nWHERE source_module IN ('expense','expenses')\nAND (reference_id = NEW.id OR reference_number = 'EXP-'||NEW.id::text)\nAND is_posted = true\nAND NOT COALESCE(is_reversed, false)\nORDER BY created_at DESC, id DESC\nLIMIT 1;\n\n-- Delete old lines (header is reused or replaced in-place).\nIF v_je IS NOT NULL THEN\nDELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_je;\nEND IF;\n\nSELECT id INTO v_expense_account FROM public.chart_of_accounts WHERE code='1130' LIMIT 1;\nSELECT id INTO v_ppn_account      FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;\nSELECT id INTO v_pph_account      FROM public.chart_of_accounts WHERE code='2132' LIMIT 1;\nSELECT id INTO v_stamp_account     FROM public.chart_of_accounts WHERE code='1130' LIMIT 1;\nSELECT id INTO v_ap_account        FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n\nIF NEW.payment_method='cash' THEN\nSELECT id INTO v_cash_account FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;\nELSIF NEW.payment_method='petty_cash' THEN\nSELECT id INTO v_cash_account FROM public.chart_of_accounts WHERE code='1102' LIMIT 1;\nELSIF NEW.payment_method='bank_transfer' AND NEW.bank_account_id IS NOT NULL THEN\nSELECT coa_id INTO v_cash_account FROM public.bank_accounts WHERE id=NEW.bank_account_id;\nELSE\nSELECT id INTO v_cash_account FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;\nEND IF;\n\nFOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items,'[]'::jsonb)) LOOP\nv_reimbursement := v_reimbursement + public.broker_reimbursement_line_total(v_item);\nEND LOOP;\n\nv_expense_total := COALESCE(NEW.amount,0) + v_reimbursement + COALESCE(NEW.stamp_duty_amount,0);\nv_credit_total := v_expense_total;\n\n-- Upsert the journal header in place (preserves ID if v_je is not null).\nv_je := public.upsert_expense_journal_header_in_place(\nv_je, NEW.id, NEW.expense_date,\nCOALESCE(NEW.description, 'Customs Broker Invoice'),\n'import_broker', v_credit_total, NEW.created_by\n);\n\nv_line_total := COALESCE(NEW.amount,0) - COALESCE(NEW.ppn_amount,0);\nIF v_line_total <> 0 THEN\nINSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\nVALUES(v_je,v_line_no,v_expense_account,'Broker service expense',v_line_total,0,NEW.supplier_id);\nv_line_no := v_line_no + 1;\nEND IF;\n\nFOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items,'[]'::jsonb)) LOOP\nv_supplier := COALESCE(NULLIF(v_item->>'supplier_id','')::uuid, NEW.supplier_id);\nv_line_total := public.broker_reimbursement_expense_base(v_item);\nIF v_line_total <> 0 THEN\nINSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\nVALUES(v_je,v_line_no,v_expense_account,'Reimbursement expense',v_line_total,0,v_supplier);\nv_line_no := v_line_no + 1;\nEND IF;\nEND LOOP;\n\nIF COALESCE(NEW.ppn_amount,0) > 0 THEN\nINSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\nVALUES(v_je,v_line_no,v_ppn_account,'Recoverable PPN - broker invoice',NEW.ppn_amount,0,NEW.supplier_id);\nv_line_no := v_line_no + 1;\nEND IF;\n\nFOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.broker_items,'[]'::jsonb)) LOOP\nv_supplier := COALESCE(NULLIF(v_item->>'supplier_id','')::uuid, NEW.supplier_id);\nv_line_ppn := COALESCE((v_item->>'ppn_amount')::numeric,0);\nIF v_line_ppn > 0 THEN\nINSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\nVALUES(v_je,v_line_no,v_ppn_account,'Recoverable PPN - reimbursement',v_line_ppn,0,v_supplier);\nv_line_no := v_line_no + 1;\nEND IF;\nEND LOOP;\n\nIF COALESCE(NEW.stamp_duty_amount,0) > 0 THEN\nINSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\nVALUES(v_je,v_line_no,v_stamp_account,'Stamp duty',NEW.stamp_duty_amount,0,NEW.supplier_id);\nv_line_no := v_line_no + 1;\nEND IF;\n\nIF v_pph > 0 THEN\nINSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\nVALUES(v_je,v_line_no,v_pph_account,'PPh23 withheld',0,v_pph,NEW.supplier_id);\nv_line_no := v_line_no + 1;\nEND IF;\n\nv_line_total := v_expense_total - v_pph;\nIF v_line_total <> 0 THEN\nINSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\nVALUES(v_je,v_line_no,\nCASE WHEN v_outstanding THEN v_ap_account ELSE v_cash_account END,\nCASE WHEN v_outstanding THEN 'Supplier payable - customs broker' ELSE 'Cash payment - customs broker' END,\n0, v_line_total, NEW.supplier_id);\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: post_expense_to_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_expense_to_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_expense_account_id UUID;\n  v_payment_account_id UUID;\n  v_journal_id         UUID;\n  v_entry_number       TEXT;\n  v_category_label     TEXT;\n  v_description        TEXT;\n  v_credit_desc        TEXT;\n  v_bm_account_id      UUID;\n  v_ppn_account_id     UUID;\n  v_pph_account_id     UUID;\n  v_line_num           INTEGER;\nBEGIN\n  -- Idempotency guard: never double-post\n  IF EXISTS (\n    SELECT 1 FROM journal_entries\n    WHERE reference_id = NEW.id AND source_module = 'expenses'\n  ) THEN\n    RETURN NEW;\n  END IF;\n\n  -- Resolve payment account\n  IF NEW.payment_method = 'cash' THEN\n    SELECT id INTO v_payment_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\n  ELSIF NEW.payment_method = 'petty_cash' THEN\n    SELECT id INTO v_payment_account_id FROM chart_of_accounts WHERE code = '1102' LIMIT 1;\n  ELSIF NEW.payment_method = 'bank_transfer' AND NEW.bank_account_id IS NOT NULL THEN\n    SELECT coa_id INTO v_payment_account_id FROM bank_accounts WHERE id = NEW.bank_account_id;\n    IF v_payment_account_id IS NULL THEN\n      SELECT id INTO v_payment_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\n    END IF;\n  ELSIF NEW.payment_method IS NULL THEN\n    SELECT id INTO v_payment_account_id FROM chart_of_accounts WHERE code = '2110' LIMIT 1;\n  ELSE\n    SELECT id INTO v_payment_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\n  END IF;\n\n  IF v_payment_account_id IS NULL THEN RETURN NEW; END IF;\n\n  v_entry_number := next_journal_entry_number();\n\n  -- PIB Import: multi-line split\n  IF NEW.expense_category = 'pib_import' THEN\n    v_bm_account_id  := get_expense_account_id('duty_customs');\n    v_ppn_account_id := get_expense_account_id('ppn_import');\n    v_pph_account_id := get_expense_account_id('pph_import');\n\n    INSERT INTO journal_entries (\n      entry_number, entry_date, source_module, reference_id, reference_number,\n      description, transaction_category,\n      total_debit, total_credit, is_posted, posted_at, created_by\n    ) VALUES (\n      v_entry_number, NEW.expense_date, 'expenses', NEW.id, 'EXP-' || NEW.id::text,\n      COALESCE(NEW.description, 'PIB Import Payment'), 'pib_import',\n      NEW.amount, NEW.amount, TRUE, NOW(), NEW.created_by\n    ) RETURNING id INTO v_journal_id;\n\n    v_line_num := 1;\n    IF COALESCE(NEW.pib_bm_amount, 0) > 0 AND v_bm_account_id IS NOT NULL THEN\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\n      VALUES (v_journal_id, v_line_num, v_bm_account_id, NEW.pib_bm_amount, 0, 'PIB - Import Duty (BM)');\n      v_line_num := v_line_num + 1;\n    END IF;\n    IF COALESCE(NEW.pib_ppn_amount, 0) > 0 AND v_ppn_account_id IS NOT NULL THEN\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\n      VALUES (v_journal_id, v_line_num, v_ppn_account_id, NEW.pib_ppn_amount, 0, 'PIB - PPN Import');\n      v_line_num := v_line_num + 1;\n    END IF;\n    IF COALESCE(NEW.pib_pph_amount, 0) > 0 AND v_pph_account_id IS NOT NULL THEN\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\n      VALUES (v_journal_id, v_line_num, v_pph_account_id, NEW.pib_pph_amount, 0, 'PIB - PPh 22');\n      v_line_num := v_line_num + 1;\n    END IF;\n    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\n    VALUES (v_journal_id, v_line_num, v_payment_account_id, 0, NEW.amount, 'PIB - Bank payment');\n    RETURN NEW;\n  END IF;\n\n  -- Standard 2-line expense\n  v_expense_account_id := get_expense_account_id(NEW.expense_category);\n  IF v_expense_account_id IS NULL THEN RETURN NEW; END IF;\n\n  v_category_label := REPLACE(INITCAP(REPLACE(NEW.expense_category, '_', ' ')), ' ', ' ');\n  v_description    := COALESCE(NEW.description, NEW.expense_category);\n  v_credit_desc    := COALESCE(\n    SUBSTRING(NEW.description FROM '^[^\\\\n]+'), NEW.expense_category\n  ) || ' [' || v_category_label || ']';\n\n  INSERT INTO journal_entries (\n    entry_number, entry_date, source_module, reference_id, reference_number,\n    description, transaction_category,\n    total_debit, total_credit, is_posted, posted_at, created_by\n  ) VALUES (\n    v_entry_number, NEW.expense_date, 'expenses', NEW.id, 'EXP-' || NEW.id::text,\n    v_description, NEW.expense_category,\n    NEW.amount, NEW.amount, TRUE, NOW(), NEW.created_by\n  ) RETURNING id INTO v_journal_id;\n\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\n  VALUES (v_journal_id, 1, v_expense_account_id, NEW.amount, 0, v_credit_desc);\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\n  VALUES (v_journal_id, 2, v_payment_account_id, 0, NEW.amount, v_credit_desc);\n\n  RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n  RAISE WARNING 'post_expense_to_journal failed for %: %', NEW.id, SQLERRM;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: post_fund_transfer_journal(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_fund_transfer_journal\\"(\\"p_transfer_id\\" \\"uuid\\", \\"p_user_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public, pg_temp'\n    AS $$\nDECLARE\nv_transfer        RECORD;\nv_journal_id      UUID;\nv_from_account_id UUID;\nv_to_account_id   UUID;\nv_description     TEXT;\nv_role            text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot post fund transfer journals', v_role;\nEND IF;\n\nSELECT * INTO v_transfer FROM fund_transfers WHERE id = p_transfer_id;\nIF NOT FOUND THEN RAISE EXCEPTION 'Fund transfer not found'; END IF;\nIF v_transfer.journal_entry_id IS NOT NULL THEN RETURN v_transfer.journal_entry_id; END IF;\n\nSELECT id INTO v_journal_id FROM journal_entries\nWHERE reference_number = v_transfer.transfer_number AND source_module = 'fund_transfers'\nORDER BY created_at DESC LIMIT 1;\nIF v_journal_id IS NOT NULL THEN\nUPDATE fund_transfers SET journal_entry_id = v_journal_id WHERE id = p_transfer_id;\nRETURN v_journal_id;\nEND IF;\n\nIF    v_transfer.from_account_type = 'petty_cash'   THEN SELECT id INTO v_from_account_id FROM chart_of_accounts WHERE code = '1102' LIMIT 1;\nELSIF v_transfer.from_account_type = 'cash_on_hand' THEN SELECT id INTO v_from_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\nELSIF v_transfer.from_account_type = 'bank'         THEN SELECT coa_id INTO v_from_account_id FROM bank_accounts WHERE id = v_transfer.from_bank_account_id;\nEND IF;\n\nIF    v_transfer.to_account_type = 'petty_cash'   THEN SELECT id INTO v_to_account_id FROM chart_of_accounts WHERE code = '1102' LIMIT 1;\nELSIF v_transfer.to_account_type = 'cash_on_hand' THEN SELECT id INTO v_to_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\nELSIF v_transfer.to_account_type = 'bank'         THEN SELECT coa_id INTO v_to_account_id FROM bank_accounts WHERE id = v_transfer.to_bank_account_id;\nEND IF;\n\nIF v_from_account_id IS NULL OR v_to_account_id IS NULL THEN\nRAISE EXCEPTION 'Cannot determine chart of accounts for transfer';\nEND IF;\n\nv_description := 'Fund Transfer ' || v_transfer.transfer_number;\nIF v_transfer.description IS NOT NULL THEN\nv_description := v_description || ' - ' || v_transfer.description;\nEND IF;\n\nINSERT INTO journal_entries (\nentry_date, source_module, reference_id, reference_number,\ndescription, total_debit, total_credit, is_posted, created_by\n) VALUES (\nv_transfer.transfer_date, 'fund_transfers', v_transfer.id, v_transfer.transfer_number,\nv_description, 0, 0, true, p_user_id\n) RETURNING id INTO v_journal_id;\n\nINSERT INTO journal_entry_lines (journal_entry_id, account_id, debit, credit, description)\nVALUES\n(v_journal_id, v_to_account_id,   v_transfer.amount, 0,                  'Transfer In'),\n(v_journal_id, v_from_account_id, 0,                  v_transfer.amount, 'Transfer Out');\n\nUPDATE fund_transfers SET journal_entry_id = v_journal_id WHERE id = p_transfer_id;\nRETURN v_journal_id;\nEND;\n$$","--\n-- Name: FUNCTION \\"post_fund_transfer_journal\\"(\\"p_transfer_id\\" \\"uuid\\", \\"p_user_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"post_fund_transfer_journal\\"(\\"p_transfer_id\\" \\"uuid\\", \\"p_user_id\\" \\"uuid\\") IS 'Manually posts journal entry for a fund transfer. Call this AFTER verifying the transfer is correct. Returns journal_entry_id.'","--\n-- Name: post_grn_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_grn_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_je_id UUID;\nv_je_number TEXT;\nv_inventory_account_id UUID;\nv_ap_account_id UUID;\nv_ppn_account_id UUID;\nBEGIN\n-- Only post when status changes to 'posted' and no journal entry exists yet\nIF TG_OP = 'UPDATE' \nAND NEW.status = 'posted' \nAND OLD.status = 'draft'\nAND NEW.journal_entry_id IS NULL THEN\n\n-- Get account IDs\nSELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;\nSELECT id INTO v_ap_account_id FROM chart_of_accounts WHERE code = '2110' LIMIT 1;\nSELECT id INTO v_ppn_account_id FROM chart_of_accounts WHERE code = '1150' LIMIT 1; -- PPN Input\n\nIF v_inventory_account_id IS NULL OR v_ap_account_id IS NULL THEN\n-- If accounts don't exist, skip accounting (don't fail the GRN)\nRETURN NEW;\nEND IF;\n\n-- Generate journal entry number\nv_je_number := 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '-' || LPAD((\nSELECT COUNT(*) + 1 FROM journal_entries WHERE entry_number LIKE 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '%'\n)::TEXT, 4, '0');\n\n-- Create journal entry\nINSERT INTO journal_entries (\nentry_number, \nentry_date, \nsource_module, \nreference_id, \nreference_number,\ndescription, \ntotal_debit, \ntotal_credit, \nis_posted, \nposted_by\n) VALUES (\nv_je_number, \nNEW.grn_date, \n'goods_receipt_note', \nNEW.id, \nNEW.grn_number,\n'GRN: ' || NEW.grn_number || ' - ' || (SELECT company_name FROM suppliers WHERE id = NEW.supplier_id),\nNEW.total_amount, \nNEW.total_amount, \ntrue, \nNEW.posted_by\n) RETURNING id INTO v_je_id;\n\n-- Debit: Inventory (subtotal - before tax)\nINSERT INTO journal_entry_lines (\njournal_entry_id, \nline_number, \naccount_id, \ndescription, \ndebit, \ncredit, \nsupplier_id\n) VALUES (\nv_je_id, \n1, \nv_inventory_account_id, \n'Inventory - GRN ' || NEW.grn_number, \nNEW.subtotal, \n0, \nNEW.supplier_id\n);\n\n-- Debit: PPN Input (if applicable)\nIF NEW.tax_amount > 0 AND v_ppn_account_id IS NOT NULL THEN\nINSERT INTO journal_entry_lines (\njournal_entry_id, \nline_number, \naccount_id, \ndescription, \ndebit, \ncredit, \nsupplier_id\n) VALUES (\nv_je_id, \n2, \nv_ppn_account_id, \n'PPN Input - GRN ' || NEW.grn_number, \nNEW.tax_amount, \n0, \nNEW.supplier_id\n);\nEND IF;\n\n-- Credit: Accounts Payable (total amount)\nINSERT INTO journal_entry_lines (\njournal_entry_id, \nline_number, \naccount_id, \ndescription, \ndebit, \ncredit, \nsupplier_id\n) VALUES (\nv_je_id, \n3, \nv_ap_account_id, \n'A/P - GRN ' || NEW.grn_number, \n0, \nNEW.total_amount, \nNEW.supplier_id\n);\n\n-- Link journal entry to GRN\nNEW.journal_entry_id := v_je_id;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"post_grn_journal\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"post_grn_journal\\"() IS 'Posts GRN to accounting: Dr Inventory + Dr PPN Input, Cr Accounts Payable. Triggered when GRN status changes to posted.'","--\n-- Name: post_import_cost_journal(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_import_cost_journal\\"(\\"p_header_id\\" \\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nv_header RECORD;\nv_je_id UUID;\nv_je_number TEXT;\nv_inventory_account_id UUID;\nv_clearing_account_id UUID;\nv_total_cost DECIMAL(18,2);\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot post import cost journals', v_role;\nEND IF;\n\nSELECT * INTO v_header FROM import_cost_headers WHERE id = p_header_id;\nIF NOT FOUND THEN\nRAISE EXCEPTION 'Import cost header not found';\nEND IF;\n\nSELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;\nSELECT id INTO v_clearing_account_id  FROM chart_of_accounts WHERE code = '2140' LIMIT 1;\n\nIF v_inventory_account_id IS NULL OR v_clearing_account_id IS NULL THEN\nRAISE EXCEPTION 'Required accounts not found (1130 Inventory or 2140 Customer Deposits)';\nEND IF;\n\nv_total_cost := v_header.duty_amount + v_header.ppn_import_amount + v_header.pph22_amount +\nv_header.freight_amount + v_header.insurance_amount + v_header.clearing_amount +\nv_header.port_charges + v_header.other_charges;\n\nIF v_total_cost <= 0 THEN\nRAISE EXCEPTION 'Total allocated cost must be greater than zero';\nEND IF;\n\nv_je_number := 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '-' || LPAD((\nSELECT COUNT(*) + 1 FROM journal_entries WHERE entry_number LIKE 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '%'\n)::TEXT, 4, '0');\n\nINSERT INTO journal_entries (\nentry_number, entry_date, source_module, reference_id, reference_number,\ndescription, total_debit, total_credit, is_posted, posted_by\n) VALUES (\nv_je_number, v_header.import_date, 'import_cost', p_header_id, v_header.cost_sheet_number,\n'Import Cost Allocation: ' || v_header.cost_sheet_number,\nv_total_cost, v_total_cost, true, v_header.created_by\n) RETURNING id INTO v_je_id;\n\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)\nVALUES\n(v_je_id, 1, v_inventory_account_id, 'Import Costs - '    || v_header.cost_sheet_number, v_total_cost, 0,            v_header.supplier_id),\n(v_je_id, 2, v_clearing_account_id,  'Import Clearing - ' || v_header.cost_sheet_number, 0,            v_total_cost, v_header.supplier_id);\n\nRETURN v_je_id;\nEND;\n$$","--\n-- Name: FUNCTION \\"post_import_cost_journal\\"(\\"p_header_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"post_import_cost_journal\\"(\\"p_header_id\\" \\"uuid\\") IS 'Posts import cost allocation to accounting: Dr Inventory, Cr Import Clearing Payable. Returns journal entry ID.'","--\n-- Name: post_inventory_movement(\\"uuid\\", \\"uuid\\", \\"uuid\\", \\"text\\", numeric, \\"date\\", \\"text\\", \\"text\\", \\"uuid\\", \\"text\\", \\"uuid\\", numeric, numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_inventory_movement\\"(\\"p_operation_id\\" \\"uuid\\", \\"p_product_id\\" \\"uuid\\", \\"p_batch_id\\" \\"uuid\\", \\"p_transaction_type\\" \\"text\\", \\"p_quantity\\" numeric, \\"p_transaction_date\\" \\"date\\" DEFAULT CURRENT_DATE, \\"p_reference_number\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_reference_type\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_reference_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_notes\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_created_by\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_stock_before\\" numeric DEFAULT NULL::numeric, \\"p_stock_after\\" numeric DEFAULT NULL::numeric) RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_existing public.inventory_transactions%ROWTYPE;\n  v_batch public.batches%ROWTYPE;\n  v_transaction_id uuid;\n  v_new_stock numeric;\n  v_previous_context text;\nBEGIN\n  IF p_operation_id IS NULL THEN\n    RAISE EXCEPTION 'Canonical inventory posting requires operation_id';\n  END IF;\n  IF p_batch_id IS NULL OR p_product_id IS NULL THEN\n    RAISE EXCEPTION 'Canonical inventory posting requires product_id and batch_id';\n  END IF;\n  IF COALESCE(p_quantity, 0) = 0 THEN\n    RAISE EXCEPTION 'Canonical inventory posting quantity cannot be zero';\n  END IF;\n  IF p_transaction_type NOT IN (\n    'purchase', 'delivery_challan', 'return', 'adjustment', 'rejection'\n  ) THEN\n    RAISE EXCEPTION 'Unsupported canonical inventory transaction type: %',\n      p_transaction_type;\n  END IF;\n\n  SELECT *\n  INTO v_existing\n  FROM public.inventory_transactions\n  WHERE operation_id = p_operation_id;\n\n  IF FOUND THEN\n    IF v_existing.batch_id IS DISTINCT FROM p_batch_id\n       OR v_existing.product_id IS DISTINCT FROM p_product_id\n       OR v_existing.transaction_type IS DISTINCT FROM p_transaction_type\n       OR v_existing.quantity IS DISTINCT FROM p_quantity\n       OR v_existing.reference_type IS DISTINCT FROM p_reference_type\n       OR v_existing.reference_id IS DISTINCT FROM p_reference_id THEN\n      RAISE EXCEPTION 'operation_id % was already used with different inventory values',\n        p_operation_id;\n    END IF;\n    RETURN v_existing.id;\n  END IF;\n\n  SELECT *\n  INTO v_batch\n  FROM public.batches\n  WHERE id = p_batch_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Batch not found: %', p_batch_id;\n  END IF;\n  IF v_batch.product_id IS DISTINCT FROM p_product_id THEN\n    RAISE EXCEPTION 'Product % does not match batch % product %',\n      p_product_id, p_batch_id, v_batch.product_id;\n  END IF;\n\n  IF p_transaction_type IN ('purchase', 'return') AND p_quantity <= 0 THEN\n    RAISE EXCEPTION '% movement must be positive', p_transaction_type;\n  END IF;\n  IF p_transaction_type IN ('delivery_challan', 'rejection') AND p_quantity >= 0 THEN\n    RAISE EXCEPTION '% movement must be negative', p_transaction_type;\n  END IF;\n  IF p_transaction_type = 'delivery_challan'\n     AND v_batch.expiry_date IS NOT NULL\n     AND v_batch.expiry_date <= COALESCE(p_transaction_date, CURRENT_DATE) THEN\n    RAISE EXCEPTION 'Expired batch % cannot be delivered (expiry %)',\n      v_batch.batch_number, v_batch.expiry_date;\n  END IF;\n  IF p_transaction_type = 'purchase'\n     AND EXISTS (\n       SELECT 1\n       FROM public.inventory_transactions it\n       WHERE it.batch_id = p_batch_id\n         AND it.transaction_type = 'purchase'\n     ) THEN\n    RAISE EXCEPTION 'Batch % already has a Batch Creation movement',\n      v_batch.batch_number;\n  END IF;\n\n  v_new_stock := v_batch.current_stock + p_quantity;\n  IF v_new_stock < 0 THEN\n    RAISE EXCEPTION 'Insufficient stock in batch %: current %, movement %, result %',\n      v_batch.batch_number, v_batch.current_stock, p_quantity, v_new_stock;\n  END IF;\n\n  IF p_stock_before IS NOT NULL\n     AND p_stock_before IS DISTINCT FROM v_batch.current_stock THEN\n    RAISE EXCEPTION 'Stale stock_before for batch %: expected %, received %',\n      v_batch.batch_number, v_batch.current_stock, p_stock_before;\n  END IF;\n  IF p_stock_after IS NOT NULL\n     AND p_stock_after IS DISTINCT FROM v_new_stock THEN\n    RAISE EXCEPTION 'Invalid stock_after for batch %: expected %, received %',\n      v_batch.batch_number, v_new_stock, p_stock_after;\n  END IF;\n\n  v_previous_context := current_setting('app.canonical_stock_engine', true);\n  PERFORM set_config('app.canonical_stock_engine', 'on', true);\n\n  UPDATE public.batches\n  SET current_stock = v_new_stock,\n      updated_at = now()\n  WHERE id = p_batch_id;\n\n  INSERT INTO public.inventory_transactions (\n    operation_id,\n    product_id,\n    batch_id,\n    transaction_type,\n    quantity,\n    transaction_date,\n    reference_number,\n    reference_type,\n    reference_id,\n    notes,\n    created_by,\n    stock_before,\n    stock_after,\n    metadata\n  )\n  VALUES (\n    p_operation_id,\n    p_product_id,\n    p_batch_id,\n    p_transaction_type,\n    p_quantity,\n    COALESCE(p_transaction_date, CURRENT_DATE),\n    p_reference_number,\n    p_reference_type,\n    p_reference_id,\n    p_notes,\n    COALESCE(p_created_by, auth.uid()),\n    v_batch.current_stock,\n    v_new_stock,\n    jsonb_build_object(\n      'canonical_engine_version', '1.0',\n      'canonical_posted_at', clock_timestamp()\n    )\n  )\n  RETURNING id INTO v_transaction_id;\n\n  PERFORM set_config(\n    'app.canonical_stock_engine',\n    COALESCE(v_previous_context, ''),\n    true\n  );\n\n  RETURN v_transaction_id;\nEND;\n$$","--\n-- Name: post_payment_voucher(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_payment_voucher\\"(\\"p_pv_id\\" \\"uuid\\", \\"p_posted_by\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_pv record; v_je uuid; v_ap uuid; v_bank uuid; v_charge uuid; v_pph uuid; v_fx uuid;\n  v_invoice_currency text; v_bank_currency text; v_rate numeric; v_gross numeric;\n  v_payment numeric; v_converted numeric; v_pph_bank numeric; v_actual numeric; v_charge_amt numeric;\n  v_expected numeric; v_fx_delta numeric; v_ap_debit numeric; v_total numeric; v_line int := 1; v_entry text;\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;\n  SELECT * INTO v_pv FROM public.payment_vouchers WHERE id=p_pv_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found',p_pv_id; END IF;\n  IF v_pv.is_posted THEN RAISE EXCEPTION 'Payment voucher % is already posted',v_pv.voucher_number; END IF;\n\n  v_invoice_currency := upper(COALESCE(v_pv.invoice_currency,v_pv.transaction_currency,v_pv.payment_currency,'IDR'));\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id=v_pv.bank_account_id;\n  v_bank_currency := COALESCE(v_bank_currency,v_pv.bank_currency,v_pv.payment_currency,'IDR');\n  v_rate := CASE WHEN v_invoice_currency=v_bank_currency THEN 1 ELSE COALESCE(v_pv.exchange_rate,0) END;\n  IF v_rate <= 0 THEN RAISE EXCEPTION 'Missing exchange rate for %',v_pv.voucher_number; END IF;\n\n  v_gross := COALESCE(v_pv.invoice_amount,v_pv.amount,0);\n  v_payment := COALESCE(v_pv.payment_amount,v_gross-COALESCE(v_pv.pph_amount,0));\n  v_converted := COALESCE(v_pv.converted_amount,v_payment*v_rate);\n  v_pph_bank := COALESCE(v_pv.pph_amount,0)*v_rate;\n  v_charge_amt := COALESCE(v_pv.bank_charge,0);\n  v_actual := COALESCE(v_pv.actual_bank_debit,v_pv.bank_amount,v_converted+v_charge_amt);\n  v_expected := v_converted+v_charge_amt;\n  v_fx_delta := v_actual-v_expected;\n  v_ap_debit := v_gross*v_rate;\n\n  IF v_pv.coa_account_id IS NOT NULL THEN\n    v_ap := v_pv.coa_account_id;\n  ELSE\n    SELECT id INTO v_ap FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n  END IF;\n  IF v_pv.payment_method = 'advance_adjustment' OR v_pv.payment_purpose = 'salary_advance' THEN\n    SELECT id INTO v_bank FROM public.chart_of_accounts WHERE code='1160' LIMIT 1;\n  ELSE\n    SELECT coa_id INTO v_bank FROM public.bank_accounts WHERE id=v_pv.bank_account_id;\n    IF v_bank IS NULL THEN SELECT id INTO v_bank FROM public.chart_of_accounts WHERE code='1101' LIMIT 1; END IF;\n  END IF;\n  SELECT id INTO v_charge FROM public.chart_of_accounts WHERE code='7100' LIMIT 1;\n  SELECT id INTO v_pph FROM public.chart_of_accounts WHERE code='2132' LIMIT 1;\n  SELECT id INTO v_fx FROM public.chart_of_accounts WHERE code='7300' LIMIT 1;\n  IF v_ap IS NULL OR v_bank IS NULL THEN RAISE EXCEPTION 'Required payment accounts are missing'; END IF;\n  IF v_pph_bank > 0 AND v_pph IS NULL THEN RAISE EXCEPTION 'PPh payable account is missing'; END IF;\n\n  v_total := v_ap_debit + v_charge_amt + GREATEST(v_fx_delta,0);\n  v_entry := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_by)\n  VALUES(v_entry,v_pv.voucher_date,'payment',v_pv.id,v_pv.voucher_number,'Payment Voucher: '||v_pv.voucher_number,v_total,v_total,true,p_posted_by)\n  RETURNING id INTO v_je;\n\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)\n  VALUES(v_je,v_line,v_ap,'Payment - '||v_pv.voucher_number,v_ap_debit,0,v_invoice_currency,v_gross,0,v_rate,v_pv.supplier_id); v_line:=v_line+1;\n  IF v_charge_amt>0 AND v_charge IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)\n    VALUES(v_je,v_line,v_charge,'Bank Charge - '||v_pv.voucher_number,v_charge_amt,0,v_bank_currency,v_charge_amt,0,1,v_pv.supplier_id); v_line:=v_line+1;\n  END IF;\n  IF v_pph_bank>0 AND v_pph IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)\n    VALUES(v_je,v_line,v_pph,'PPh Withholding - '||v_pv.voucher_number,0,v_pph_bank,v_bank_currency,0,v_pv.pph_amount,v_rate,v_pv.supplier_id); v_line:=v_line+1;\n  END IF;\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)\n  VALUES(v_je,v_line,v_bank,CASE WHEN v_pv.payment_method='advance_adjustment' THEN 'Advance Adjustment - ' ELSE 'Bank Payment - ' END||v_pv.voucher_number,0,v_actual,v_bank_currency,0,v_actual,1,v_pv.supplier_id); v_line:=v_line+1;\n  IF v_fx_delta>0 AND v_fx IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n    VALUES(v_je,v_line,v_fx,'FX loss - '||v_pv.voucher_number,v_fx_delta,0,v_pv.supplier_id);\n  ELSIF v_fx_delta<0 AND v_fx IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n    VALUES(v_je,v_line,v_fx,'FX gain - '||v_pv.voucher_number,0,abs(v_fx_delta),v_pv.supplier_id);\n  END IF;\n  UPDATE public.payment_vouchers SET is_posted=true,journal_entry_id=v_je WHERE id=p_pv_id;\n  INSERT INTO public.audit_logs(table_name,record_id,action_type,old_values,new_values,user_id)\n  VALUES('payment_vouchers',p_pv_id,'update',jsonb_build_object('is_posted',false),jsonb_build_object('is_posted',true,'journal_entry_id',v_je),p_posted_by);\nEND; $$","--\n-- Name: post_payment_voucher_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_payment_voucher_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\nv_je_id UUID;\nv_je_number TEXT;\nv_credit_account_id UUID;\nv_debit_account_id UUID;\nv_pph_account_id UUID;\nv_net_amount DECIMAL(18,2);\nBEGIN\n-- IDEMPOTENCY: Never create a second JE if one already exists\nIF NEW.journal_entry_id IS NOT NULL THEN\nRETURN NEW;\nEND IF;\n\n-- Determine credit account (bank/cash paying out money)\nIF NEW.bank_account_id IS NOT NULL THEN\nSELECT coa_id INTO v_credit_account_id FROM bank_accounts WHERE id = NEW.bank_account_id;\nELSIF NEW.payment_method = 'cash' THEN\nSELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\nEND IF;\n\nIF v_credit_account_id IS NULL THEN\nSELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\nEND IF;\n\n-- Determine debit account (A/P or custom)\nIF NEW.coa_account_id IS NOT NULL THEN\nv_debit_account_id := NEW.coa_account_id;\nELSE\nSELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '2110' LIMIT 1;\nEND IF;\n\nSELECT id INTO v_pph_account_id FROM chart_of_accounts WHERE code = '2132' LIMIT 1;\n\nIF v_credit_account_id IS NULL OR v_debit_account_id IS NULL THEN\nRETURN NEW;\nEND IF;\n\nv_net_amount := NEW.amount - COALESCE(NEW.pph_amount, 0);\nv_je_number := next_journal_entry_number();\n\nINSERT INTO journal_entries (\nentry_number, entry_date, source_module, reference_id, reference_number,\ndescription, total_debit, total_credit, is_posted, posted_by\n) VALUES (\nv_je_number, NEW.voucher_date, 'payment', NEW.id, NEW.voucher_number,\n'Payment Voucher: ' || NEW.voucher_number,\nNEW.amount, NEW.amount, true, NEW.created_by\n) RETURNING id INTO v_je_id;\n\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)\nVALUES (v_je_id, 1, v_debit_account_id, 'Payment - ' || NEW.voucher_number, NEW.amount, 0, NEW.supplier_id);\n\nIF COALESCE(NEW.pph_amount, 0) > 0 AND v_pph_account_id IS NOT NULL THEN\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)\nVALUES (v_je_id, 2, v_pph_account_id, 'PPh Withholding - ' || NEW.voucher_number, 0, NEW.pph_amount, NEW.supplier_id);\nEND IF;\n\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)\nVALUES (v_je_id, 3, v_credit_account_id, 'Cash Payment - ' || NEW.voucher_number, 0, v_net_amount, NEW.supplier_id);\n\nNEW.journal_entry_id := v_je_id;\nRETURN NEW;\nEND;\n$$","--\n-- Name: post_petty_cash_to_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_petty_cash_to_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_journal_id UUID;\nv_entry_number TEXT;\nv_petty_cash_account_id UUID;\nv_bank_account_coa_id UUID;\nv_expense_account_id UUID;\nv_line_num INT;\nBEGIN\nIF NEW.source IN ('moved_from_tracker', 'finance_expense', 'migrated_from_expenses') THEN\nRETURN NEW;\nEND IF;\n\nSELECT 'JE-' || TO_CHAR(NEW.transaction_date, 'YYYYMMDD') || '-' ||\nLPAD((COUNT(*) + 1)::TEXT, 4, '0')\nINTO v_entry_number\nFROM journal_entries;\n\nSELECT id INTO v_petty_cash_account_id\nFROM chart_of_accounts\nWHERE code = '1102' OR code LIKE '1-103%' OR LOWER(name) LIKE '%petty%cash%'\nLIMIT 1;\n\nIF v_petty_cash_account_id IS NULL THEN\nINSERT INTO chart_of_accounts (code, name, account_type, is_active)\nVALUES ('1102', 'Petty Cash', 'asset', true)\nRETURNING id INTO v_petty_cash_account_id;\nEND IF;\n\nIF NEW.transaction_type = 'withdraw' THEN\nIF NEW.bank_account_id IS NOT NULL THEN\nSELECT coa_id INTO v_bank_account_coa_id\nFROM bank_accounts\nWHERE id = NEW.bank_account_id;\nEND IF;\n\nIF v_bank_account_coa_id IS NULL THEN\nSELECT id INTO v_bank_account_coa_id\nFROM chart_of_accounts\nWHERE code LIKE '1-102%' OR LOWER(name) LIKE '%bank%'\nORDER BY code\nLIMIT 1;\nEND IF;\n\nINSERT INTO journal_entries (\nentry_number, entry_date, source_module, reference_id, reference_number,\ndescription, is_posted, created_by, posted_at\n) VALUES (\nv_entry_number, NEW.transaction_date, 'petty_cash', NEW.id, NEW.transaction_number,\n'Petty cash withdrawal: ' || COALESCE(NEW.description, ''),\ntrue, NEW.created_by, NOW()\n) RETURNING id INTO v_journal_id;\n\nv_line_num := 1;\n\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\nVALUES (v_journal_id, v_line_num, v_petty_cash_account_id, NEW.amount, 0, 'Cash withdrawal');\n\nIF v_bank_account_coa_id IS NOT NULL THEN\nv_line_num := v_line_num + 1;\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\nVALUES (v_journal_id, v_line_num, v_bank_account_coa_id, 0, NEW.amount, 'Transfer to petty cash');\nEND IF;\n\nELSIF NEW.transaction_type = 'expense' THEN\nSELECT id INTO v_expense_account_id\nFROM chart_of_accounts\nWHERE account_type = 'expense'\nAND (\nCASE\nWHEN NEW.expense_category = 'Office Supplies'        THEN LOWER(name) LIKE '%office%' OR code = '6-1010'\nWHEN NEW.expense_category = 'Transportation'         THEN LOWER(name) LIKE '%transport%' OR code = '6-1020'\nWHEN NEW.expense_category = 'Meals & Entertainment'  THEN LOWER(name) LIKE '%entertainment%' OR code = '6-1030'\nWHEN NEW.expense_category = 'Postage & Courier'      THEN LOWER(name) LIKE '%postage%' OR code = '6-1040'\nWHEN NEW.expense_category = 'Cleaning & Maintenance' THEN LOWER(name) LIKE '%maintenance%' OR code = '6-1050'\nWHEN NEW.expense_category = 'Utilities'              THEN LOWER(name) LIKE '%utilities%' OR code = '6-1060'\nELSE code = '6-1090' OR LOWER(name) LIKE '%misc%'\nEND\n)\nORDER BY code\nLIMIT 1;\n\nIF v_expense_account_id IS NULL THEN\nSELECT id INTO v_expense_account_id\nFROM chart_of_accounts\nWHERE account_type = 'expense'\nORDER BY code\nLIMIT 1;\nEND IF;\n\nINSERT INTO journal_entries (\nentry_number, entry_date, source_module, reference_id, reference_number,\ndescription, is_posted, created_by, posted_at\n) VALUES (\nv_entry_number, NEW.transaction_date, 'petty_cash', NEW.id, NEW.transaction_number,\n'Petty cash expense: ' || COALESCE(NEW.description, ''),\ntrue, NEW.created_by, NOW()\n) RETURNING id INTO v_journal_id;\n\nv_line_num := 1;\n\nIF v_expense_account_id IS NOT NULL THEN\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\nVALUES (v_journal_id, v_line_num, v_expense_account_id, NEW.amount, 0, COALESCE(NEW.expense_category, 'Petty cash expense'));\nv_line_num := v_line_num + 1;\nEND IF;\n\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, debit, credit, description)\nVALUES (v_journal_id, v_line_num, v_petty_cash_account_id, 0, NEW.amount, 'Petty cash payment');\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"post_petty_cash_to_journal\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"post_petty_cash_to_journal\\"() IS 'Creates complete journal entries for petty cash transactions with both debit and credit lines'","--\n-- Name: post_petty_cash_to_journal_fixed(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_petty_cash_to_journal_fixed\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $_$\nDECLARE\n  v_journal_id         uuid;\n  v_petty_cash_account uuid;\n  v_counter_account    uuid;\n  v_expense_account    uuid;\n  v_line_num           integer := 0;\n  v_je_number          text;\n  v_rows                integer;\nBEGIN\n  IF NEW.fund_transfer_id IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT id\n    INTO v_journal_id\n    FROM public.journal_entries\n   WHERE source_module = 'petty_cash'\n     AND reference_id = NEW.id\n   LIMIT 1;\n\n  IF v_journal_id IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT id\n    INTO v_petty_cash_account\n    FROM public.chart_of_accounts\n   WHERE code = '1102'\n     AND is_header = false\n     AND is_active = true\n   LIMIT 1;\n\n  IF v_petty_cash_account IS NULL THEN\n    RAISE EXCEPTION 'Cannot post petty cash %: active Petty Cash posting account is missing', NEW.id;\n  END IF;\n\n  PERFORM pg_advisory_xact_lock(\n    hashtext('pc_je_number_' || to_char(NEW.transaction_date, 'YYYYMMDD'))\n  );\n\n  SELECT 'JE-' || to_char(NEW.transaction_date, 'YYYYMMDD') || '-' ||\n         lpad((COALESCE(MAX((substring(entry_number FROM '[0-9]+$'))::integer), 0) + 1)::text, 4, '0')\n    INTO v_je_number\n    FROM public.journal_entries\n   WHERE entry_date = NEW.transaction_date\n     AND entry_number LIKE 'JE-' || to_char(NEW.transaction_date, 'YYYYMMDD') || '-%';\n\n  INSERT INTO public.journal_entries (\n    entry_number, entry_date, source_module, reference_id, reference_number,\n    description, total_debit, total_credit, is_posted, created_by, posted_at\n  ) VALUES (\n    v_je_number, NEW.transaction_date, 'petty_cash', NEW.id, NEW.transaction_number,\n    'Petty cash ' || NEW.transaction_type || ': ' || NEW.description,\n    NEW.amount, NEW.amount, true, NEW.created_by, now()\n  ) RETURNING id INTO v_journal_id;\n\n  IF NEW.transaction_type = 'withdraw' THEN\n    IF NEW.bank_account_id IS NOT NULL THEN\n      SELECT coa_id\n        INTO v_counter_account\n        FROM public.bank_accounts\n       WHERE id = NEW.bank_account_id;\n    ELSE\n      v_counter_account := NEW.source_account_id;\n    END IF;\n\n    IF v_counter_account IS NULL THEN\n      RAISE EXCEPTION 'Cannot post petty cash inflow %: select a bank or offset GL account', NEW.id;\n    END IF;\n\n    IF v_counter_account = v_petty_cash_account THEN\n      RAISE EXCEPTION 'Cannot post petty cash inflow %: offset account cannot be the Petty Cash posting account', NEW.id;\n    END IF;\n\n    INSERT INTO public.journal_entry_lines (\n      journal_entry_id, line_number, account_id, debit, credit, description\n    ) VALUES\n      (v_journal_id, 1, v_petty_cash_account, NEW.amount, 0, 'Cash received into petty cash'),\n      (v_journal_id, 2, v_counter_account, 0, NEW.amount, COALESCE(NULLIF(NEW.source, ''), 'Petty cash inflow source'));\n\n  ELSIF NEW.transaction_type = 'expense' THEN\n    -- This is the single canonical expense-category mapping.  It deliberately\n    -- does not translate UI labels or embed account codes here.\n    v_expense_account := public.get_expense_account_id(NEW.expense_category);\n\n    IF v_expense_account IS NULL THEN\n      RAISE EXCEPTION 'Cannot post petty cash expense %: no configured account for category %', NEW.id, NEW.expense_category;\n    END IF;\n\n    INSERT INTO public.journal_entry_lines (\n      journal_entry_id, line_number, account_id, debit, credit, description\n    ) VALUES\n      (v_journal_id, 1, v_expense_account, NEW.amount, 0, COALESCE(NEW.expense_category, 'General expense')),\n      (v_journal_id, 2, v_petty_cash_account, 0, NEW.amount, 'Cash expense');\n  ELSE\n    RAISE EXCEPTION 'Unsupported petty cash transaction type: %', NEW.transaction_type;\n  END IF;\n\n  IF NEW.bank_statement_line_id IS NOT NULL THEN\n    UPDATE public.bank_statement_lines\n       SET matched_petty_cash_id = NEW.id,\n           matched_entry_id = v_journal_id,\n           reconciliation_status = 'matched',\n           matched_at = now(),\n           matched_by = COALESCE(NEW.approved_by, NEW.created_by),\n           manually_unlinked = false,\n           notes = 'Linked to Petty Cash ' || NEW.transaction_number\n     WHERE id = NEW.bank_statement_line_id\n       AND bank_account_id = NEW.bank_account_id\n       AND matched_expense_id IS NULL\n       AND matched_receipt_id IS NULL\n       AND matched_fund_transfer_id IS NULL\n       AND matched_tax_payment_id IS NULL\n       AND (matched_petty_cash_id IS NULL OR matched_petty_cash_id = NEW.id)\n       AND (matched_entry_id IS NULL OR matched_entry_id = v_journal_id);\n\n    GET DIAGNOSTICS v_rows = ROW_COUNT;\n    IF v_rows <> 1 THEN\n      RAISE EXCEPTION 'Bank statement line % is unavailable or belongs to another bank account', NEW.bank_statement_line_id;\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$_$","--\n-- Name: post_purchase_invoice_item_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_purchase_invoice_item_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\nv_invoice RECORD;\nv_je_id UUID;\nv_account_id UUID;\nv_inventory_account_id UUID;\nv_max_line INTEGER;\nBEGIN\n-- Get the parent invoice\nSELECT * INTO v_invoice FROM purchase_invoices WHERE id = NEW.purchase_invoice_id;\n\n-- If the invoice doesn't have a journal entry yet, it means the header trigger\n-- didn't fire yet or failed. Don't post per-item yet — the header trigger handles bulk.\n-- Only add to an EXISTING journal entry.\nIF v_invoice.journal_entry_id IS NULL THEN\nRETURN NEW;\nEND IF;\n\nv_je_id := v_invoice.journal_entry_id;\n\n-- Check if a line for this specific item already exists (idempotency)\nIF EXISTS (\nSELECT 1 FROM journal_entry_lines \nWHERE journal_entry_id = v_je_id \nAND debit > 0 \nAND description LIKE '%' || LEFT(COALESCE(NEW.description, ''), 50) || '%'\nAND debit = NEW.line_total\n) THEN\nRETURN NEW; -- Already posted\nEND IF;\n\n-- Determine account\nIF NEW.item_type = 'inventory' THEN\nSELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;\nELSIF NEW.item_type = 'fixed_asset' THEN\nv_account_id := NEW.asset_account_id;\nIF v_account_id IS NULL THEN\nSELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1200' LIMIT 1;\nEND IF;\nELSE\nv_account_id := NEW.expense_account_id;\nIF v_account_id IS NULL THEN\nSELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '5100' LIMIT 1;\nEND IF;\nEND IF;\n\nIF v_account_id IS NULL THEN RETURN NEW; END IF;\n\n-- Add debit line\nSELECT COALESCE(MAX(line_number), 0) INTO v_max_line\nFROM journal_entry_lines WHERE journal_entry_id = v_je_id;\n\nINSERT INTO journal_entry_lines (\njournal_entry_id, line_number, account_id, description,\ndebit, credit, supplier_id, batch_id\n) VALUES (\nv_je_id, v_max_line + 1, v_account_id,\nCOALESCE(LEFT(NEW.description, 100), 'Purchase Item'),\nNEW.line_total, 0, v_invoice.supplier_id, NEW.batch_id\n);\n\n-- Update journal entry total_debit\nUPDATE journal_entries\nSET total_debit = (SELECT COALESCE(SUM(debit), 0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)\nWHERE id = v_je_id;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: post_purchase_invoice_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_purchase_invoice_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $_$\nDECLARE\n  v_je_id uuid; v_ap uuid; v_ppn uuid; v_account uuid; v_line int := 1;\n  v_item record; v_currency text := upper(coalesce(NEW.currency,'IDR'));\n  v_rate numeric := case when v_currency='IDR' then 1 else coalesce(NEW.exchange_rate,0) end;\n  v_items numeric := 0; v_tax numeric := coalesce(NEW.tax_amount,0);\n  v_total numeric := coalesce(NEW.total_amount,0);\nBEGIN\n  IF NEW.journal_entry_id IS NOT NULL THEN RETURN NEW; END IF;\n  IF NOT (TG_OP='INSERT' OR (TG_OP='UPDATE' AND OLD.journal_entry_id IS NULL AND NEW.status IN ('unpaid','partial','paid'))) THEN RETURN NEW; END IF;\n  IF v_currency <> 'IDR' AND v_rate <= 1 THEN\n    RAISE EXCEPTION 'Purchase invoice % requires a valid exchange rate', NEW.invoice_number;\n  END IF;\n  SELECT id INTO v_ap FROM chart_of_accounts WHERE code='2110' LIMIT 1;\n  SELECT id INTO v_ppn FROM chart_of_accounts WHERE code='1150' LIMIT 1;\n  IF v_ap IS NULL THEN RETURN NEW; END IF;\n  SELECT coalesce(sum(line_total),0) INTO v_items FROM purchase_invoice_items WHERE purchase_invoice_id=NEW.id;\n  IF EXISTS (SELECT 1 FROM purchase_invoice_items WHERE purchase_invoice_id=NEW.id)\n     AND abs((v_items + v_tax) - v_total) > 0.01 THEN\n    RAISE EXCEPTION 'Purchase invoice % totals do not reconcile: item lines + tax (%) != header total (%)', NEW.invoice_number, v_items + v_tax, v_total;\n  END IF;\n  INSERT INTO journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_by,created_by,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n  VALUES ('JE-'||to_char(NEW.invoice_date,'YYMM')||'-'||lpad(((select coalesce(max(cast(substring(entry_number from '(\\\\\\\\d+)$') as int)),0)+1 from journal_entries where entry_number like 'JE-'||to_char(NEW.invoice_date,'YYMM')||'-%'))::text,4,'0'),NEW.invoice_date,'purchase_invoice',NEW.id,NEW.invoice_number,'Purchase Invoice: '||NEW.invoice_number,v_total*v_rate,v_total*v_rate,true,NEW.created_by,NEW.created_by,v_currency,'IDR',v_rate,true) RETURNING id INTO v_je_id;\n  FOR v_item IN SELECT * FROM purchase_invoice_items WHERE purchase_invoice_id=NEW.id ORDER BY id LOOP\n    v_account := CASE WHEN v_item.item_type='inventory' THEN (select id from chart_of_accounts where code='1130' limit 1)\n      WHEN v_item.item_type='fixed_asset' THEN coalesce(v_item.asset_account_id,(select id from chart_of_accounts where code='1200' limit 1))\n      ELSE coalesce(v_item.expense_account_id,(select id from chart_of_accounts where code='5100' limit 1)) END;\n    IF v_account IS NOT NULL THEN\n      INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id,batch_id,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n      VALUES(v_je_id,v_line,v_account,coalesce(left(v_item.description,100),'Purchase - '||NEW.invoice_number),v_item.line_total*v_rate,0,NEW.supplier_id,v_item.batch_id,v_currency,v_item.line_total,0,'IDR',v_rate); v_line:=v_line+1;\n    END IF;\n  END LOOP;\n  IF v_tax > 0 AND v_ppn IS NOT NULL THEN\n    INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n    VALUES(v_je_id,v_line,v_ppn,'PPN Input - '||NEW.invoice_number,v_tax*v_rate,0,NEW.supplier_id,v_currency,v_tax,0,'IDR',v_rate); v_line:=v_line+1;\n  END IF;\n  INSERT INTO journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n  VALUES(v_je_id,v_line,v_ap,'A/P - '||NEW.invoice_number,0,v_total*v_rate,NEW.supplier_id,v_currency,0,v_total,'IDR',v_rate);\n  NEW.journal_entry_id:=v_je_id; RETURN NEW;\nEND; $_$","--\n-- Name: post_receipt_voucher(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_receipt_voucher\\"(\\"p_rv_id\\" \\"uuid\\", \\"p_posted_by\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_rv                 RECORD;\nv_je_id              UUID;\nv_je_number          TEXT;\nv_debit_account_id   UUID;\nv_credit_account_id  UUID;\nBEGIN\nIF auth.uid() IS NULL THEN\nRAISE EXCEPTION 'Not authenticated';\nEND IF;\n\nSELECT * INTO v_rv FROM receipt_vouchers WHERE id = p_rv_id FOR UPDATE;\nIF NOT FOUND THEN RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id; END IF;\nIF v_rv.is_posted THEN RAISE EXCEPTION 'Receipt voucher % is already posted', v_rv.voucher_number; END IF;\n\nIF v_rv.bank_account_id IS NOT NULL THEN\nSELECT coa_id INTO v_debit_account_id FROM bank_accounts WHERE id = v_rv.bank_account_id;\nELSIF v_rv.payment_method = 'cash' THEN\nSELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\nEND IF;\nIF v_debit_account_id IS NULL THEN\nSELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\nEND IF;\n\nIF v_rv.coa_account_id IS NOT NULL THEN\nv_credit_account_id := v_rv.coa_account_id;\nELSE\nSELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1120' LIMIT 1;\nEND IF;\n\nIF v_debit_account_id IS NULL OR v_credit_account_id IS NULL THEN\nRAISE EXCEPTION 'Cannot post: required chart of accounts entries missing';\nEND IF;\n\nv_je_number := next_journal_entry_number();\n\nINSERT INTO journal_entries (\nentry_number, entry_date, source_module, reference_id, reference_number,\ndescription, total_debit, total_credit, is_posted, posted_by\n) VALUES (\nv_je_number, v_rv.voucher_date, 'receipt', v_rv.id, v_rv.voucher_number,\n'Receipt Voucher: ' || v_rv.voucher_number,\nv_rv.amount, v_rv.amount, TRUE, p_posted_by\n) RETURNING id INTO v_je_id;\n\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\nVALUES (v_je_id, 1, v_debit_account_id, 'Cash Receipt - ' || v_rv.voucher_number, v_rv.amount, 0, v_rv.customer_id);\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\nVALUES (v_je_id, 2, v_credit_account_id, 'Receipt - ' || v_rv.voucher_number, 0, v_rv.amount, v_rv.customer_id);\n\nUPDATE receipt_vouchers\nSET is_posted = TRUE, journal_entry_id = v_je_id\nWHERE id = p_rv_id;\n\nINSERT INTO audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)\nVALUES (\n'receipt_vouchers', p_rv_id, 'update',\njsonb_build_object('is_posted', FALSE),\njsonb_build_object('is_posted', TRUE, 'journal_entry_id', v_je_id, 'journal_entry_number', v_je_number, 'posted_by', p_posted_by),\np_posted_by\n);\nEND;\n$$","--\n-- Name: post_receipt_voucher_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_receipt_voucher_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\nv_je_id UUID;\nv_je_number TEXT;\nv_debit_account_id UUID;\nv_credit_account_id UUID;\nBEGIN\n-- IDEMPOTENCY: Never create a second JE if one already exists\nIF NEW.journal_entry_id IS NOT NULL THEN\nRETURN NEW;\nEND IF;\n\n-- Determine debit account (bank/cash account receiving money)\nIF NEW.bank_account_id IS NOT NULL THEN\nSELECT coa_id INTO v_debit_account_id FROM bank_accounts WHERE id = NEW.bank_account_id;\nELSIF NEW.payment_method = 'cash' THEN\nSELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\nEND IF;\n\nIF v_debit_account_id IS NULL THEN\nSELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\nEND IF;\n\n-- Determine credit account (AR or custom)\nIF NEW.coa_account_id IS NOT NULL THEN\nv_credit_account_id := NEW.coa_account_id;\nELSE\nSELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1120' LIMIT 1;\nEND IF;\n\nIF v_debit_account_id IS NULL OR v_credit_account_id IS NULL THEN\nRETURN NEW;\nEND IF;\n\nv_je_number := next_journal_entry_number();\n\nINSERT INTO journal_entries (\nentry_number, entry_date, source_module, reference_id, reference_number,\ndescription, total_debit, total_credit, is_posted, posted_by\n) VALUES (\nv_je_number, NEW.voucher_date, 'receipt', NEW.id, NEW.voucher_number,\n'Receipt Voucher: ' || NEW.voucher_number,\nNEW.amount, NEW.amount, true, NEW.created_by\n) RETURNING id INTO v_je_id;\n\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\nVALUES (v_je_id, 1, v_debit_account_id, 'Cash Receipt - ' || NEW.voucher_number, NEW.amount, 0, NEW.customer_id);\n\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\nVALUES (v_je_id, 2, v_credit_account_id, 'Receipt - ' || NEW.voucher_number, 0, NEW.amount, NEW.customer_id);\n\nNEW.journal_entry_id := v_je_id;\nRETURN NEW;\nEND;\n$$","--\n-- Name: post_sales_invoice_cogs(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_sales_invoice_cogs\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_existing_cogs_je_id UUID;\n  v_je_id UUID;\n  v_je_number TEXT;\n  v_cogs_account_id UUID;\n  v_inventory_account_id UUID;\n  v_item RECORD;\n  v_total_cogs NUMERIC := 0;\nBEGIN\n  -- Only consider invoices that have already had their revenue JE posted.\n  IF NEW.journal_entry_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  -- Skip non-billable invoices (drafts, voids, cancellations).\n  IF NEW.payment_status NOT IN ('pending', 'partial', 'paid') THEN\n    RETURN NEW;\n  END IF;\n\n  -- Idempotency: never post a second COGS JE for the same invoice.\n  SELECT id INTO v_existing_cogs_je_id\n  FROM journal_entries\n  WHERE source_module = 'sales_invoice_cogs'\n    AND reference_id = NEW.id\n  LIMIT 1;\n\n  IF v_existing_cogs_je_id IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT id INTO v_cogs_account_id      FROM chart_of_accounts WHERE code = '5100' LIMIT 1;\n  SELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;\n\n  IF v_cogs_account_id IS NULL OR v_inventory_account_id IS NULL THEN\n    RAISE EXCEPTION\n      'post_sales_invoice_cogs: chart_of_accounts is missing 5100 (COGS) or 1130 (Inventory). Cannot post COGS for invoice %.',\n      NEW.invoice_number;\n  END IF;\n\n  -- Compute COGS from items: landed_cost_per_unit -> import_price -> cost_per_unit -> 0\n  FOR v_item IN\n    SELECT\n      sii.quantity,\n      sii.batch_id,\n      COALESCE(\n        NULLIF(b.landed_cost_per_unit, 0),\n        NULLIF(b.import_price, 0),\n        NULLIF(b.cost_per_unit, 0),\n        0\n      ) AS effective_cost\n    FROM sales_invoice_items sii\n    LEFT JOIN batches b ON b.id = sii.batch_id\n    WHERE sii.invoice_id = NEW.id\n      AND sii.batch_id IS NOT NULL\n  LOOP\n    v_total_cogs := v_total_cogs + (COALESCE(v_item.quantity, 0) * v_item.effective_cost);\n  END LOOP;\n\n  -- No cost basis available. Nothing to post.\n  IF v_total_cogs <= 0 THEN\n    RETURN NEW;\n  END IF;\n\n  v_je_number := next_journal_entry_number();\n\n  INSERT INTO journal_entries (\n    entry_number, entry_date, source_module, reference_id, reference_number,\n    description, total_debit, total_credit, is_posted, posted_by, created_by\n  ) VALUES (\n    v_je_number, NEW.invoice_date, 'sales_invoice_cogs', NEW.id, NEW.invoice_number,\n    'COGS for Sales Invoice: ' || NEW.invoice_number,\n    v_total_cogs, v_total_cogs, true, NEW.created_by, NEW.created_by\n  )\n  RETURNING id INTO v_je_id;\n\n  -- Dr: COGS\n  INSERT INTO journal_entry_lines (\n    journal_entry_id, line_number, account_id, description, debit, credit, customer_id\n  ) VALUES (\n    v_je_id, 1, v_cogs_account_id, 'COGS - ' || NEW.invoice_number,\n    v_total_cogs, 0, NEW.customer_id\n  );\n\n  -- Cr: Inventory\n  INSERT INTO journal_entry_lines (\n    journal_entry_id, line_number, account_id, description, debit, credit, customer_id\n  ) VALUES (\n    v_je_id, 2, v_inventory_account_id, 'Inventory - ' || NEW.invoice_number,\n    0, v_total_cogs, NEW.customer_id\n  );\n\n  RETURN NEW;\n\nEXCEPTION\n  WHEN OTHERS THEN\n    RAISE LOG 'post_sales_invoice_cogs failed for invoice %: %', NEW.id, SQLERRM;\n    RAISE;\nEND;\n$$","--\n-- Name: FUNCTION \\"post_sales_invoice_cogs\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"post_sales_invoice_cogs\\"() IS 'Posts the COGS portion of a sales invoice as a separate balanced JE (Dr 5100, Cr 1130). Fires as a DEFERRABLE INITIALLY DEFERRED constraint trigger so sales_invoice_items are guaranteed to exist at firing time. Cost basis: COALESCE(landed_cost_per_unit, cost_per_unit, 0). Idempotent: skips if a sales_invoice_cogs JE already exists for the invoice.'","--\n-- Name: post_sales_invoice_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_sales_invoice_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_existing_je_id uuid;\n  v_je_id uuid;\n  v_je_number text;\n  v_ar_account_id uuid;\n  v_revenue_account_id uuid;\n  v_tax_account_id uuid;\n  v_bm_expense_id uuid;\n  v_line_num integer := 1;\n  v_total_debit numeric := 0;\n  v_total_credit numeric := 0;\n  v_stamp_duty numeric;\nBEGIN\n  IF current_setting('app.sales_invoice_rebuild', true) = 'true' THEN\n    RETURN NEW;\n  END IF;\n\n  IF TG_OP = 'UPDATE'\n     AND NEW.journal_entry_id IS NULL\n     AND OLD.journal_entry_id IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.journal_entry_id IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT id INTO v_existing_je_id\n  FROM journal_entries\n  WHERE source_module = 'sales_invoice' AND reference_id = NEW.id\n  LIMIT 1;\n  IF v_existing_je_id IS NOT NULL THEN\n    NEW.journal_entry_id := v_existing_je_id;\n    RETURN NEW;\n  END IF;\n\n  IF NEW.payment_status NOT IN ('pending', 'partial', 'paid') THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT id INTO v_ar_account_id FROM chart_of_accounts WHERE code = '1120' LIMIT 1;\n  SELECT id INTO v_revenue_account_id FROM chart_of_accounts WHERE code = '4100' LIMIT 1;\n  SELECT id INTO v_tax_account_id FROM chart_of_accounts WHERE code = '2130' LIMIT 1;\n  SELECT id INTO v_bm_expense_id FROM chart_of_accounts WHERE code = '6950' LIMIT 1;\n  IF v_ar_account_id IS NULL OR v_revenue_account_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  v_stamp_duty := COALESCE(NEW.stamp_duty_amount, 0);\n  v_je_number := next_journal_entry_number();\n  INSERT INTO journal_entries (\n    entry_number, entry_date, source_module, reference_id, reference_number,\n    description, total_debit, total_credit, is_posted, posted_by, created_by\n  ) VALUES (\n    v_je_number, NEW.invoice_date, 'sales_invoice', NEW.id, NEW.invoice_number,\n    'Sales Invoice: ' || NEW.invoice_number,\n    NEW.total_amount, NEW.total_amount, true, NEW.created_by, NEW.created_by\n  ) RETURNING id INTO v_je_id;\n\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, v_line_num, v_ar_account_id, 'A/R - ' || NEW.invoice_number, NEW.total_amount, 0, NEW.customer_id);\n  v_line_num := v_line_num + 1;\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, v_line_num, v_revenue_account_id, 'Sales - ' || NEW.invoice_number, 0, NEW.subtotal, NEW.customer_id);\n  v_line_num := v_line_num + 1;\n  IF COALESCE(NEW.tax_amount, 0) > 0 AND v_tax_account_id IS NOT NULL THEN\n    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n    VALUES (v_je_id, v_line_num, v_tax_account_id, 'PPN - ' || NEW.invoice_number, 0, NEW.tax_amount, NEW.customer_id);\n    v_line_num := v_line_num + 1;\n  END IF;\n  IF v_stamp_duty > 0 AND v_bm_expense_id IS NOT NULL THEN\n    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n    VALUES (v_je_id, v_line_num, v_bm_expense_id, 'Bea Meterai (cost recovery) - ' || NEW.invoice_number, 0, v_stamp_duty, NEW.customer_id);\n    v_line_num := v_line_num + 1;\n  END IF;\n\n  -- COGS is posted by the existing deferred post_sales_invoice_cogs()\n  -- trigger. Keeping it out of this revenue journal avoids double posting.\n  v_total_debit := COALESCE(NEW.total_amount, 0);\n  v_total_credit := COALESCE(NEW.subtotal, 0) + COALESCE(NEW.tax_amount, 0) + v_stamp_duty;\n  IF v_total_debit <> v_total_credit THEN\n    RAISE EXCEPTION 'Journal not balanced: debit=% credit=%', v_total_debit, v_total_credit;\n  END IF;\n  NEW.journal_entry_id := v_je_id;\n  RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n  RAISE LOG 'post_sales_invoice_journal failed for invoice %: %', NEW.id, SQLERRM;\n  RAISE;\nEND;\n$$","--\n-- Name: FUNCTION \\"post_sales_invoice_journal\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"post_sales_invoice_journal\\"() IS 'Sales invoice journal posting wrapper; preserves explicit NULL during atomic journal replacement.'","--\n-- Name: post_sales_invoice_journal_impl(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"post_sales_invoice_journal_impl\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_existing_je_id       UUID;\n  v_je_id                UUID;\n  v_je_number            TEXT;\n  v_ar_account_id        UUID;\n  v_revenue_account_id   UUID;\n  v_tax_account_id       UUID;\n  v_bm_expense_id        UUID;   -- 6950 Bea Meterai Expense (cost recovery credit)\n  v_cogs_account_id      UUID;\n  v_inventory_account_id UUID;\n  v_item                 RECORD;\n  v_line_num             INTEGER := 1;\n  v_total_cost           NUMERIC := 0;\n  v_item_cost            NUMERIC;\n  v_total_debit          NUMERIC := 0;\n  v_total_credit         NUMERIC := 0;\n  v_stamp_duty           NUMERIC;\nBEGIN\n\n  -- Strict idempotency: JE already set → skip\n  IF NEW.journal_entry_id IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT id INTO v_existing_je_id\n  FROM journal_entries\n  WHERE source_module = 'sales_invoice'\n    AND reference_id  = NEW.id\n  LIMIT 1;\n\n  IF v_existing_je_id IS NOT NULL THEN\n    NEW.journal_entry_id := v_existing_je_id;\n    RETURN NEW;\n  END IF;\n\n  IF NEW.payment_status NOT IN ('pending', 'partial', 'paid') THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT id INTO v_ar_account_id        FROM chart_of_accounts WHERE code = '1120' LIMIT 1;\n  SELECT id INTO v_revenue_account_id   FROM chart_of_accounts WHERE code = '4100' LIMIT 1;\n  SELECT id INTO v_tax_account_id       FROM chart_of_accounts WHERE code = '2130' LIMIT 1;\n  SELECT id INTO v_bm_expense_id        FROM chart_of_accounts WHERE code = '6950' LIMIT 1;\n  SELECT id INTO v_cogs_account_id      FROM chart_of_accounts WHERE code = '5100' LIMIT 1;\n  SELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;\n\n  IF v_ar_account_id IS NULL OR v_revenue_account_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  v_stamp_duty := COALESCE(NEW.stamp_duty_amount, 0);\n\n  v_je_number := next_journal_entry_number();\n\n  INSERT INTO journal_entries (\n    entry_number, entry_date, source_module, reference_id, reference_number,\n    description, total_debit, total_credit, is_posted, posted_by, created_by\n  ) VALUES (\n    v_je_number, NEW.invoice_date, 'sales_invoice', NEW.id, NEW.invoice_number,\n    'Sales Invoice: ' || NEW.invoice_number,\n    NEW.total_amount, NEW.total_amount, true, NEW.created_by, NEW.created_by\n  ) RETURNING id INTO v_je_id;\n\n  -- Dr: Accounts Receivable (full invoice total)\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, v_line_num, v_ar_account_id, 'A/R - ' || NEW.invoice_number, NEW.total_amount, 0, NEW.customer_id);\n  v_line_num := v_line_num + 1;\n\n  -- Cr: Sales Revenue (subtotal)\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, v_line_num, v_revenue_account_id, 'Sales - ' || NEW.invoice_number, 0, NEW.subtotal, NEW.customer_id);\n  v_line_num := v_line_num + 1;\n\n  -- Cr: PPN Output 2130 (if any)\n  IF COALESCE(NEW.tax_amount, 0) > 0 AND v_tax_account_id IS NOT NULL THEN\n    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n    VALUES (v_je_id, v_line_num, v_tax_account_id, 'PPN - ' || NEW.invoice_number, 0, NEW.tax_amount, NEW.customer_id);\n    v_line_num := v_line_num + 1;\n  END IF;\n\n  -- Cr: Bea Meterai Expense 6950 (cost recovery — offsets original stamp purchase expense)\n  -- When the customer reimburses stamp duty, we credit the same expense account\n  -- that was debited when stamps were originally purchased. Net P&L effect =\n  -- original purchase cost minus recoveries collected from customers.\n  IF v_stamp_duty > 0 AND v_bm_expense_id IS NOT NULL THEN\n    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n    VALUES (v_je_id, v_line_num, v_bm_expense_id,\n            'Bea Meterai (cost recovery) - ' || NEW.invoice_number,\n            0, v_stamp_duty, NEW.customer_id);\n    v_line_num := v_line_num + 1;\n  END IF;\n\n  -- COGS entries (inventory cost of goods sold)\n  IF v_cogs_account_id IS NOT NULL AND v_inventory_account_id IS NOT NULL THEN\n    FOR v_item IN\n      SELECT sii.quantity, b.cost_per_unit, b.id as batch_id\n      FROM sales_invoice_items sii\n      LEFT JOIN batches b ON b.id = sii.batch_id\n      WHERE sii.invoice_id = NEW.id AND sii.batch_id IS NOT NULL\n    LOOP\n      v_item_cost  := COALESCE(v_item.cost_per_unit, 0) * v_item.quantity;\n      v_total_cost := v_total_cost + v_item_cost;\n    END LOOP;\n\n    IF v_total_cost > 0 THEN\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES (v_je_id, v_line_num, v_cogs_account_id, 'COGS - ' || NEW.invoice_number, v_total_cost, 0, NEW.customer_id);\n      v_line_num := v_line_num + 1;\n\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES (v_je_id, v_line_num, v_inventory_account_id, 'Inventory - ' || NEW.invoice_number, 0, v_total_cost, NEW.customer_id);\n    END IF;\n  END IF;\n\n  -- Balance assertion:\n  -- total_debit  = total_amount + cogs\n  -- total_credit = subtotal + tax + stamp_duty + cogs\n  --             = (subtotal + tax + stamp_duty) + cogs\n  --             = total_amount + cogs  ✓\n  v_total_debit  := COALESCE(NEW.total_amount, 0) + COALESCE(v_total_cost, 0);\n  v_total_credit := COALESCE(NEW.subtotal, 0)\n                 + COALESCE(NEW.tax_amount, 0)\n                 + v_stamp_duty\n                 + COALESCE(v_total_cost, 0);\n\n  IF v_total_debit <> v_total_credit THEN\n    RAISE EXCEPTION 'Journal not balanced: debit=% credit=%', v_total_debit, v_total_credit;\n  END IF;\n\n  NEW.journal_entry_id := v_je_id;\n  RETURN NEW;\n\nEXCEPTION\n  WHEN OTHERS THEN\n    RAISE LOG 'post_sales_invoice_journal failed for invoice %: %', NEW.id, SQLERRM;\n    RAISE;\nEND;\n$$","--\n-- Name: FUNCTION \\"post_sales_invoice_journal_impl\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"post_sales_invoice_journal_impl\\"() IS 'Posts the REVENUE portion of a sales invoice (Dr AR, Cr Sales, Cr PPN). COGS is posted separately by post_sales_invoice_cogs via a DEFERRABLE constraint trigger so child sales_invoice_items are guaranteed to exist.'","--\n-- Name: prevent_active_customer_identity_duplicate(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_active_customer_identity_duplicate\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_id text;\nBEGIN\n  IF COALESCE(NEW.is_active,true) THEN\n    IF public.normalize_customer_identity(NEW.company_name) <> '' AND EXISTS (\n      SELECT 1 FROM public.customers c WHERE c.id<>NEW.id AND COALESCE(c.is_active,true)\n        AND public.normalize_customer_identity(c.company_name)=public.normalize_customer_identity(NEW.company_name)\n    ) THEN RAISE EXCEPTION 'Possible existing customer found: exact normalized legal name already exists' USING ERRCODE='unique_violation'; END IF;\n    v_id:=public.normalize_customer_tax_id(NEW.npwp);\n    IF v_id<>'' AND EXISTS (\n      SELECT 1 FROM public.customers c WHERE c.id<>NEW.id AND COALESCE(c.is_active,true)\n        AND public.normalize_customer_tax_id(c.npwp)=v_id\n    ) THEN RAISE EXCEPTION 'Possible existing customer found: NPWP/tax ID already exists' USING ERRCODE='unique_violation'; END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: prevent_active_fund_transfer_statement_reuse(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_active_fund_transfer_statement_reuse\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF NEW.status IN ('cancelled', 'reversed') THEN RETURN NEW; END IF;\n  IF NEW.from_bank_statement_line_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.fund_transfers ft\n     WHERE ft.id <> NEW.id AND ft.status NOT IN ('cancelled', 'reversed')\n       AND ft.from_bank_statement_line_id = NEW.from_bank_statement_line_id\n  ) THEN\n    RAISE EXCEPTION 'Active bank statement line is already used by another fund transfer';\n  END IF;\n  IF NEW.to_bank_statement_line_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.fund_transfers ft\n     WHERE ft.id <> NEW.id AND ft.status NOT IN ('cancelled', 'reversed')\n       AND ft.to_bank_statement_line_id = NEW.to_bank_statement_line_id\n  ) THEN\n    RAISE EXCEPTION 'Active bank statement line is already used by another fund transfer';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"prevent_active_fund_transfer_statement_reuse\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"prevent_active_fund_transfer_statement_reuse\\"() IS 'Prevents active fund transfers from reusing statement evidence owned by another active transfer; reversals release it.'","--\n-- Name: prevent_deleting_allocated_finance_document(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_deleting_allocated_finance_document\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF EXISTS (\n    SELECT 1 FROM public.bank_statement_allocations\n     WHERE document_type = TG_ARGV[0]\n       AND document_id = OLD.id\n  ) THEN\n    RAISE EXCEPTION 'Document has bank reconciliation allocations. Use the canonical delete command so they can be released atomically.';\n  END IF;\n  RETURN OLD;\nEND;\n$$","--\n-- Name: prevent_empty_delivery_challans(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_empty_delivery_challans\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- Check if the DC has any items\nIF NOT EXISTS (\nSELECT 1 FROM delivery_challan_items\nWHERE challan_id = OLD.challan_id\n) THEN\n-- If no items exist after delete, delete the DC\nDELETE FROM delivery_challans WHERE id = OLD.challan_id;\nEND IF;\n\nRETURN OLD;\nEND;\n$$","--\n-- Name: prevent_header_account_posting(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_header_account_posting\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_code TEXT;\n  v_is_header BOOLEAN;\nBEGIN\n  SELECT code, is_header\n    INTO v_code, v_is_header\n    FROM chart_of_accounts\n   WHERE id = NEW.account_id;\n\n  IF COALESCE(v_is_header, false) THEN\n    RAISE EXCEPTION\n      'Journal lines cannot be posted to header account % — use a leaf account instead', v_code;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: prevent_linked_dc_deletion(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_linked_dc_deletion\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_invoice_number text;\n  v_invoice_exists boolean;\nBEGIN\n  -- Check if this DC is linked to any invoice (cast UUID to text for array comparison)\n  SELECT EXISTS (\n    SELECT 1 \n    FROM sales_invoices si\n    WHERE OLD.id::text = ANY(si.linked_challan_ids)\n  ) INTO v_invoice_exists;\n\n  IF v_invoice_exists THEN\n    -- Get the invoice number\n    SELECT invoice_number INTO v_invoice_number\n    FROM sales_invoices\n    WHERE OLD.id::text = ANY(linked_challan_ids)\n    LIMIT 1;\n\n    RAISE EXCEPTION 'Cannot delete Delivery Challan %. It is linked to Invoice %. Please delete the invoice first or remove this DC from the invoice.',\n      OLD.challan_number, v_invoice_number\n      USING HINT = 'Delete or edit the invoice to unlink this Delivery Challan first.';\n  END IF;\n\n  RETURN OLD;\nEND;\n$$","--\n-- Name: FUNCTION \\"prevent_linked_dc_deletion\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"prevent_linked_dc_deletion\\"() IS 'Prevents deletion of DCs that are linked to invoices'","--\n-- Name: prevent_linked_invoice_deletion(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_linked_invoice_deletion\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_dc_count integer;\nBEGIN\n-- Check if invoice is linked to any DCs\nIF OLD.linked_challan_ids IS NOT NULL AND array_length(OLD.linked_challan_ids, 1) > 0 THEN\n-- Get the number of DCs\nv_dc_count := array_length(OLD.linked_challan_ids, 1);\n\nRAISE EXCEPTION 'Cannot delete invoice %. It is linked to % Delivery Challan(s). Please delete or unlink the DCs first.',\nOLD.invoice_number, v_dc_count\nUSING HINT = 'Delete the linked Delivery Challans or remove them from this invoice before deleting.';\nEND IF;\n\nRETURN OLD;\nEND;\n$$","--\n-- Name: FUNCTION \\"prevent_linked_invoice_deletion\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"prevent_linked_invoice_deletion\\"() IS 'Prevents deletion of invoices that are linked to DCs'","--\n-- Name: prevent_multiple_bank_line_document_owners(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_multiple_bank_line_document_owners\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF num_nonnulls(NEW.matched_expense_id, NEW.matched_receipt_id,\n                  NEW.matched_payment_id, NEW.matched_petty_cash_id,\n                  NEW.matched_fund_transfer_id, NEW.matched_tax_payment_id) > 1 THEN\n    RAISE EXCEPTION 'Bank statement line % cannot be linked to more than one source document', NEW.id\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: prevent_purchase_invoice_payment_overallocation(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_purchase_invoice_payment_overallocation\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_total numeric;\n  v_existing numeric;\nBEGIN\n  IF NEW.voucher_type <> 'payment' OR NEW.purchase_invoice_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT total_amount INTO v_total\n    FROM public.purchase_invoices\n   WHERE id = NEW.purchase_invoice_id\n   FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Purchase invoice % not found', NEW.purchase_invoice_id;\n  END IF;\n\n  SELECT COALESCE(SUM(allocated_amount), 0) INTO v_existing\n    FROM public.voucher_allocations\n   WHERE purchase_invoice_id = NEW.purchase_invoice_id\n     AND voucher_type = 'payment'\n     AND (TG_OP <> 'UPDATE' OR id <> NEW.id);\n\n  IF v_existing + NEW.allocated_amount > COALESCE(v_total, 0) + 0.01 THEN\n    RAISE EXCEPTION 'Payment allocation exceeds Purchase Invoice outstanding amount';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: prevent_receipt_allocation_overpayment(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_receipt_allocation_overpayment\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_receipt_amount numeric;\n  v_existing numeric;\nBEGIN\n  IF NEW.voucher_type <> 'receipt' OR NEW.receipt_voucher_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n  IF NEW.sales_invoice_id IS NULL AND NEW.sales_order_id IS NULL THEN\n    RAISE EXCEPTION 'Receipt allocation must reference a sales invoice or sales order';\n  END IF;\n  IF NEW.sales_invoice_id IS NOT NULL AND NEW.sales_order_id IS NOT NULL THEN\n    RAISE EXCEPTION 'Receipt allocation cannot reference both a sales invoice and sales order';\n  END IF;\n  IF COALESCE(NEW.allocated_amount, 0) <= 0 THEN\n    RAISE EXCEPTION 'Receipt allocation amount must be greater than zero';\n  END IF;\n\n  -- Lock the voucher while checking to make concurrent allocations safe.\n  SELECT amount INTO v_receipt_amount\n    FROM public.receipt_vouchers\n   WHERE id = NEW.receipt_voucher_id\n   FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Receipt voucher % not found', NEW.receipt_voucher_id;\n  END IF;\n\n  SELECT COALESCE(sum(allocated_amount), 0) INTO v_existing\n    FROM public.voucher_allocations\n   WHERE receipt_voucher_id = NEW.receipt_voucher_id\n     AND voucher_type = 'receipt'\n     AND (TG_OP <> 'UPDATE' OR id <> NEW.id);\n  IF v_existing + NEW.allocated_amount > COALESCE(v_receipt_amount, 0) + 0.01 THEN\n    RAISE EXCEPTION 'Receipt allocations exceed receipt amount (%, attempted %) ',\n      v_receipt_amount, v_existing + NEW.allocated_amount;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"prevent_receipt_allocation_overpayment\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"prevent_receipt_allocation_overpayment\\"() IS 'Prevents receipt allocations from exceeding voucher amount and enforces one target per allocation.'","--\n-- Name: prevent_self_approval_expense(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_self_approval_expense\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n      DECLARE\n        v_role text;\n      BEGIN\n        IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;\n        IF auth.role() = 'service_role' THEN RETURN NEW; END IF;\n        IF NEW.approval_status IS DISTINCT FROM OLD.approval_status\n           AND NEW.approval_status = 'approved' THEN\n          SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n          IF v_role = 'accounts' AND OLD.created_by = auth.uid() THEN\n            RAISE EXCEPTION 'You cannot approve your own expense entry';\n          END IF;\n          IF v_role NOT IN ('admin','accounts') THEN\n            RAISE EXCEPTION 'Only admin/accounts can approve expenses';\n          END IF;\n          NEW.approved_by := auth.uid();\n        END IF;\n        RETURN NEW;\n      END $$","--\n-- Name: prevent_self_approval_petty_cash(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_self_approval_petty_cash\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n      DECLARE\n        v_role text;\n      BEGIN\n        IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;\n        IF auth.role() = 'service_role' THEN RETURN NEW; END IF;\n        IF NEW.approval_status IS DISTINCT FROM OLD.approval_status\n           AND NEW.approval_status = 'approved' THEN\n          SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n          IF v_role = 'accounts' AND OLD.created_by = auth.uid() THEN\n            RAISE EXCEPTION 'You cannot approve your own petty cash transaction';\n          END IF;\n          IF v_role NOT IN ('admin','accounts') THEN\n            RAISE EXCEPTION 'Only admin/accounts can approve petty cash';\n          END IF;\n          NEW.approved_by := auth.uid();\n        END IF;\n        RETURN NEW;\n      END $$","--\n-- Name: prevent_self_privilege_escalation(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_self_privilege_escalation\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_caller_role text;\nBEGIN\n  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;\n  IF auth.role() = 'service_role' THEN RETURN NEW; END IF;\n\n  SELECT role INTO v_caller_role\n  FROM public.user_profiles\n  WHERE id = auth.uid();\n\n  IF NEW.role IS DISTINCT FROM OLD.role THEN\n    IF auth.uid() = OLD.id OR COALESCE(v_caller_role, '') <> 'admin' THEN\n      RAISE EXCEPTION 'Role changes must be made by an admin via admin-update-user';\n    END IF;\n  END IF;\n\n  IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN\n    IF auth.uid() = OLD.id OR COALESCE(v_caller_role, '') <> 'admin' THEN\n      RAISE EXCEPTION 'is_active changes must be made by an admin';\n    END IF;\n  END IF;\n\n  IF NEW.username IS DISTINCT FROM OLD.username THEN\n    IF auth.uid() = OLD.id AND COALESCE(v_caller_role, '') <> 'admin' THEN\n      RAISE EXCEPTION 'Username changes must be made by an admin';\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND $$","--\n-- Name: prevent_unsafe_settled_salary_edit(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_unsafe_settled_salary_edit\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF OLD.expense_category = 'salary'\n     AND EXISTS (SELECT 1 FROM public.salary_advance_applications sa WHERE sa.salary_expense_id = OLD.id)\n     AND (OLD.amount, OLD.staff_id, OLD.pph_amount, OLD.payment_method, OLD.bank_account_id)\n         IS DISTINCT FROM (NEW.amount, NEW.staff_id, NEW.pph_amount, NEW.payment_method, NEW.bank_account_id) THEN\n    RAISE EXCEPTION\n      'Salary % has applied advances. Reverse or correct its settlement before changing gross, staff, withholding, payment method, or bank account.', OLD.voucher_number\n      USING ERRCODE = 'check_violation';\n  END IF;\n  RETURN NEW;\nEND $$","--\n-- Name: prevent_unscoped_historical_repair_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"prevent_unscoped_historical_repair_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF NEW.source_module = 'historical_repair'\n     AND NOT public.historical_repair_context_active() THEN\n    RAISE EXCEPTION 'Historical-repair journals require the guarded repair context';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: preview_bank_statement_delete(\\"uuid\\", \\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"preview_bank_statement_delete\\"(\\"p_bank_account_id\\" \\"uuid\\", \\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS json\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nv_bank_info JSON;\nv_total_count INTEGER;\nv_reconciled_count INTEGER;\nv_unmatched_count INTEGER;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot preview bank statement deletions', v_role;\nEND IF;\n\nSELECT json_build_object(\n'account_name',   account_name,\n'bank_name',      bank_name,\n'account_number', account_number,\n'currency',       currency\n) INTO v_bank_info\nFROM bank_accounts WHERE id = p_bank_account_id;\n\nSELECT\nCOUNT(*),\nCOUNT(*) FILTER (WHERE reconciliation_status IN ('matched', 'recorded', 'suggested')),\nCOUNT(*) FILTER (WHERE reconciliation_status = 'unmatched')\nINTO v_total_count, v_reconciled_count, v_unmatched_count\nFROM bank_statement_lines\nWHERE bank_account_id = p_bank_account_id\nAND transaction_date >= p_start_date\nAND transaction_date <= p_end_date;\n\nRETURN json_build_object(\n'bank_info',        v_bank_info,\n'start_date',       p_start_date,\n'end_date',         p_end_date,\n'total_count',      v_total_count,\n'reconciled_count', v_reconciled_count,\n'unmatched_count',  v_unmatched_count,\n'can_delete',       v_reconciled_count = 0 AND v_total_count > 0,\n'warning', CASE\nWHEN v_reconciled_count > 0 THEN 'Cannot delete: Contains ' || v_reconciled_count || ' reconciled transaction(s). Please unreconcile first.'\nWHEN v_total_count = 0      THEN 'No transactions found in this date range'\nELSE NULL\nEND\n);\nEND;\n$$","--\n-- Name: product_available_to_promise(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"product_available_to_promise\\"(\\"p_product_id\\" \\"uuid\\", \\"p_exclude_sales_order_item_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS numeric\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\n  SELECT GREATEST(\n    COALESCE((SELECT sum(b.current_stock) FROM public.batches b\n      WHERE b.product_id=p_product_id AND b.is_active=true\n        AND (b.expiry_date IS NULL OR b.expiry_date>CURRENT_DATE)),0)\n    - COALESCE((SELECT sum(r.reserved_quantity) FROM public.so_product_reservations r\n      WHERE r.product_id=p_product_id AND r.status='active'\n        AND (p_exclude_sales_order_item_id IS NULL OR r.sales_order_item_id<>p_exclude_sales_order_item_id)),0)\n    - COALESCE((SELECT sum(sr.reserved_quantity) FROM public.stock_reservations sr\n      WHERE sr.product_id=p_product_id AND sr.status='active' AND NOT sr.is_released\n        AND (p_exclude_sales_order_item_id IS NULL OR sr.sales_order_item_id<>p_exclude_sales_order_item_id)\n        AND NOT EXISTS (SELECT 1 FROM public.so_product_reservations migrated\n          WHERE sr.id=ANY(migrated.legacy_reservation_ids))),0),0);\n$$","--\n-- Name: propagate_bank_line_amount_edit(\\"uuid\\", numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"propagate_bank_line_amount_edit\\"(\\"p_line_id\\" \\"uuid\\", \\"p_new_amount\\" numeric) RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_line record;\nv_old_amount numeric;\nv_doc_type text;\nv_doc_id uuid;\nv_je_id uuid;\nBEGIN\nSELECT * INTO v_line FROM bank_statement_lines WHERE id = p_line_id;\nIF NOT FOUND THEN\nRETURN jsonb_build_object('ok', false, 'error', 'Bank statement line not found');\nEND IF;\n\nv_old_amount := COALESCE(v_line.debit_amount, 0) + COALESCE(v_line.credit_amount, 0);\n\n-- Determine linked document type and ID\nIF v_line.matched_expense_id IS NOT NULL THEN\nv_doc_type := 'expense';\nv_doc_id := v_line.matched_expense_id;\n-- Update expense amount; trigger_auto_post_expense_accounting_update will:\n-- 1. Check if amount actually changed (idempotency guard)\n-- 2. Delete old journal entry\n-- 3. Create new journal entry with correct amount\n-- No double post possible — trigger deletes before inserting.\nUPDATE finance_expenses SET amount = p_new_amount WHERE id = v_doc_id;\n\nELSIF v_line.matched_receipt_id IS NOT NULL THEN\nv_doc_type := 'receipt_voucher';\nv_doc_id := v_line.matched_receipt_id;\nUPDATE receipt_vouchers SET amount = p_new_amount WHERE id = v_doc_id;\n-- Find linked JE and update lines (no trigger re-posts on amount change)\nSELECT journal_entry_id INTO v_je_id FROM receipt_vouchers WHERE id = v_doc_id;\nIF v_je_id IS NOT NULL THEN\nUPDATE journal_entry_lines\nSET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,\ncredit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END\nWHERE journal_entry_id = v_je_id;\nUPDATE journal_entries\nSET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),\ntotal_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)\nWHERE id = v_je_id;\nEND IF;\n\nELSIF v_line.matched_payment_id IS NOT NULL THEN\nv_doc_type := 'payment_voucher';\nv_doc_id := v_line.matched_payment_id;\nUPDATE payment_vouchers SET amount = p_new_amount WHERE id = v_doc_id;\nSELECT journal_entry_id INTO v_je_id FROM payment_vouchers WHERE id = v_doc_id;\nIF v_je_id IS NOT NULL THEN\nUPDATE journal_entry_lines\nSET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,\ncredit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END\nWHERE journal_entry_id = v_je_id;\nUPDATE journal_entries\nSET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),\ntotal_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)\nWHERE id = v_je_id;\nEND IF;\n\nELSIF v_line.matched_fund_transfer_id IS NOT NULL THEN\nv_doc_type := 'fund_transfer';\nv_doc_id := v_line.matched_fund_transfer_id;\nUPDATE fund_transfers SET amount = p_new_amount WHERE id = v_doc_id;\n-- Fund transfer only has INSERT trigger, so manually update JE lines\nSELECT journal_entry_id INTO v_je_id FROM fund_transfers WHERE id = v_doc_id;\nIF v_je_id IS NOT NULL THEN\nUPDATE journal_entry_lines\nSET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,\ncredit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END\nWHERE journal_entry_id = v_je_id;\nUPDATE journal_entries\nSET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),\ntotal_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)\nWHERE id = v_je_id;\nEND IF;\n\nELSIF v_line.matched_petty_cash_id IS NOT NULL THEN\nv_doc_type := 'petty_cash';\nv_doc_id := v_line.matched_petty_cash_id;\n-- Update petty cash amount\nUPDATE petty_cash_transactions SET amount = p_new_amount WHERE id = v_doc_id;\n-- trigger_post_petty_cash_on_approval only fires on approval_status change,\n-- NOT on amount-only update. So find the linked JE manually and update lines.\nSELECT id INTO v_je_id FROM journal_entries\nWHERE reference_id = v_doc_id AND source_module = 'petty_cash'\nLIMIT 1;\nIF v_je_id IS NOT NULL THEN\nUPDATE journal_entry_lines\nSET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,\ncredit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END\nWHERE journal_entry_id = v_je_id;\nUPDATE journal_entries\nSET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),\ntotal_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)\nWHERE id = v_je_id;\nEND IF;\n\nELSIF v_line.matched_tax_payment_id IS NOT NULL THEN\nv_doc_type := 'tax_payment';\nv_doc_id := v_line.matched_tax_payment_id;\nUPDATE tax_payments SET amount = p_new_amount WHERE id = v_doc_id;\nSELECT journal_entry_id INTO v_je_id FROM tax_payments WHERE id = v_doc_id;\nIF v_je_id IS NOT NULL THEN\nUPDATE journal_entry_lines\nSET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,\ncredit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END\nWHERE journal_entry_id = v_je_id;\nUPDATE journal_entries\nSET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),\ntotal_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)\nWHERE id = v_je_id;\nEND IF;\n\nELSIF v_line.matched_entry_id IS NOT NULL THEN\nv_doc_type := 'journal_entry';\nv_doc_id := v_line.matched_entry_id;\nv_je_id := v_doc_id;\nUPDATE journal_entry_lines\nSET debit = CASE WHEN debit > 0 THEN p_new_amount ELSE debit END,\ncredit = CASE WHEN credit > 0 THEN p_new_amount ELSE credit END\nWHERE journal_entry_id = v_je_id;\nUPDATE journal_entries\nSET total_debit = (SELECT COALESCE(sum(debit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),\ntotal_credit = (SELECT COALESCE(sum(credit),0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)\nWHERE id = v_je_id;\n\nELSE\nv_doc_type := 'none';\nv_doc_id := NULL;\nEND IF;\n\nRETURN jsonb_build_object(\n'ok', true,\n'doc_type', v_doc_type,\n'doc_id', v_doc_id,\n'old_amount', v_old_amount,\n'new_amount', p_new_amount\n);\nEND;\n$$","--\n-- Name: protect_historical_company_profile(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"protect_historical_company_profile\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'pg_catalog', 'public'\n    AS $$\nDECLARE\n  v_ref_count bigint;\n  v_target_id uuid;\nBEGIN\n  -- Setup Mode: skip every guard. Admins may edit / delete any profile.\n  IF public.is_setup_mode() THEN\n    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;\n  END IF;\n\n  v_target_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;\n\n  SELECT COALESCE(SUM(ref_count), 0) INTO v_ref_count\n  FROM public.get_company_profile_reference_counts()\n  WHERE profile_id = v_target_id;\n\n  IF v_ref_count > 0 THEN\n    IF TG_OP = 'DELETE' THEN\n      RAISE EXCEPTION\n        'PROFILE_REFERENCED: This Company Profile is referenced by % business document(s) and cannot be deleted. '\n        'Historical company identities must remain permanently available.',\n        v_ref_count;\n    ELSIF TG_OP = 'UPDATE' THEN\n      -- Tier 1: accounting-critical fields — immutable while referenced.\n      -- company_logo_url, company_stamp_url, address, phone, email, website\n      -- are intentionally excluded: they are branding/contact fields whose\n      -- existing snapshot values are already frozen in historical documents.\n      IF (NEW.company_name       IS DISTINCT FROM OLD.company_name       OR\n          NEW.company_legal_name IS DISTINCT FROM OLD.company_legal_name OR\n          NEW.company_tax_id     IS DISTINCT FROM OLD.company_tax_id     OR\n          NEW.pbf_license        IS DISTINCT FROM OLD.pbf_license        OR\n          NEW.cdob_certificate   IS DISTINCT FROM OLD.cdob_certificate   OR\n          NEW.effective_from     IS DISTINCT FROM OLD.effective_from) THEN\n        RAISE EXCEPTION\n          'PROFILE_REFERENCED: This Company Profile is referenced by % business document(s). '\n          'The fields company_name, legal_name, tax_id, licenses and effective_from cannot be '\n          'changed because they appear on issued tax documents. '\n          'Create a new profile version for future documents instead. '\n          'Branding fields (logo, stamp, address, phone, email, website) may still be updated.',\n          v_ref_count;\n      END IF;\n    END IF;\n  END IF;\n\n  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;\nEND;\n$$","--\n-- Name: protect_posted_fund_transfer_accounting(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"protect_posted_fund_transfer_accounting\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF COALESCE(current_setting('app.finance_historical_repair_relink',true),'off')='on' AND auth.role()='service_role' THEN\n    RETURN NEW;\n  END IF;\n  IF COALESCE(current_setting('app.finance_historical_repair',true),'off')='on'\n     AND NEW.exchange_rate IS DISTINCT FROM OLD.exchange_rate\n     AND NEW.transfer_date IS NOT DISTINCT FROM OLD.transfer_date\n     AND NEW.amount IS NOT DISTINCT FROM OLD.amount\n     AND NEW.from_amount IS NOT DISTINCT FROM OLD.from_amount\n     AND NEW.to_amount IS NOT DISTINCT FROM OLD.to_amount\n     AND NEW.from_account_type IS NOT DISTINCT FROM OLD.from_account_type\n     AND NEW.to_account_type IS NOT DISTINCT FROM OLD.to_account_type\n     AND NEW.from_bank_account_id IS NOT DISTINCT FROM OLD.from_bank_account_id\n     AND NEW.to_bank_account_id IS NOT DISTINCT FROM OLD.to_bank_account_id\n     AND NEW.description IS NOT DISTINCT FROM OLD.description\n     AND NEW.journal_entry_id IS NOT DISTINCT FROM OLD.journal_entry_id THEN\n    RETURN NEW;\n  END IF;\n  IF OLD.status='posted' AND (\n       NEW.transfer_date IS DISTINCT FROM OLD.transfer_date OR NEW.amount IS DISTINCT FROM OLD.amount\n    OR NEW.from_amount IS DISTINCT FROM OLD.from_amount OR NEW.to_amount IS DISTINCT FROM OLD.to_amount\n    OR NEW.exchange_rate IS DISTINCT FROM OLD.exchange_rate OR NEW.from_account_type IS DISTINCT FROM OLD.from_account_type\n    OR NEW.to_account_type IS DISTINCT FROM OLD.to_account_type OR NEW.from_bank_account_id IS DISTINCT FROM OLD.from_bank_account_id\n    OR NEW.to_bank_account_id IS DISTINCT FROM OLD.to_bank_account_id OR NEW.description IS DISTINCT FROM OLD.description\n    OR NEW.journal_entry_id IS DISTINCT FROM OLD.journal_entry_id\n  ) THEN\n    RAISE EXCEPTION 'Posted Fund Transfer % is accounting-locked. Reverse it and create a replacement.',OLD.transfer_number;\n  END IF;\n  RETURN NEW;\nEND $$","--\n-- Name: purchase_invoice_item_received_quantity(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"purchase_invoice_item_received_quantity\\"(\\"p_item_id\\" \\"uuid\\") RETURNS numeric\n    LANGUAGE \\"plpgsql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_item public.purchase_invoice_items%ROWTYPE;\n  v_batch public.batches%ROWTYPE;\n  v_allocated numeric := 0;\n  v_legacy_tx numeric := 0;\n  v_legacy_batch_share numeric := 0;\n  v_prior_claimed numeric := 0;\nBEGIN\n  SELECT * INTO v_item FROM public.purchase_invoice_items WHERE id = p_item_id;\n  IF NOT FOUND THEN RETURN 0; END IF;\n\n  SELECT COALESCE(sum(received_quantity),0)\n    INTO v_allocated\n    FROM public.purchase_invoice_receiving_allocations\n   WHERE purchase_invoice_item_id = p_item_id\n     AND status = 'received';\n\n  SELECT * INTO v_batch\n    FROM public.batches b\n   WHERE (v_item.batch_id IS NOT NULL AND b.id = v_item.batch_id)\n      OR (v_item.batch_id IS NULL\n          AND NULLIF(v_item.receiving_batch_number,'') IS NOT NULL\n          AND b.product_id = v_item.product_id\n          AND b.batch_number = v_item.receiving_batch_number)\n   ORDER BY CASE WHEN v_item.batch_id IS NOT NULL AND b.id = v_item.batch_id THEN 0 ELSE 1 END,\n            b.created_at\n   LIMIT 1;\n\n  /*\n    Legacy purchase movements are authoritative when present. They are\n    counted only once when a matching canonical allocation already owns the\n    same operation.\n  */\n  SELECT COALESCE(sum(abs(it.quantity)),0)\n    INTO v_legacy_tx\n    FROM public.inventory_transactions it\n    JOIN public.batches b ON b.id = it.batch_id\n   WHERE it.transaction_type = 'purchase'\n     AND it.quantity > 0\n     AND NOT EXISTS (\n       SELECT 1\n         FROM public.purchase_invoice_receiving_allocations a\n        WHERE a.purchase_invoice_item_id = p_item_id\n          AND a.status = 'received'\n          AND a.operation_id = it.operation_id\n     )\n     AND (\n       it.reference_id = p_item_id\n       OR (\n         it.reference_id = v_item.purchase_invoice_id\n         AND b.product_id = v_item.product_id\n         AND ((v_item.batch_id IS NOT NULL AND b.id = v_item.batch_id)\n           OR (NULLIF(v_item.receiving_batch_number,'') IS NOT NULL AND b.batch_number = v_item.receiving_batch_number))\n       )\n       OR (\n         b.purchase_invoice_id = v_item.purchase_invoice_id\n         AND b.product_id = v_item.product_id\n         AND ((v_item.batch_id IS NOT NULL AND b.id = v_item.batch_id)\n           OR (NULLIF(v_item.receiving_batch_number,'') IS NOT NULL AND b.batch_number = v_item.receiving_batch_number))\n       )\n       OR (\n         it.reference_number = v_item.receiving_batch_number\n         AND NULLIF(v_item.receiving_batch_number,'') IS NOT NULL\n         AND b.purchase_invoice_id = v_item.purchase_invoice_id\n         AND b.product_id = v_item.product_id\n       )\n     );\n\n  /*\n    Older batch imports can have the authoritative received quantity stored in\n    batches.import_quantity without a purchase inventory_transaction. This is\n    especially important when one physical batch was split across multiple PI\n    lines. Allocate the batch's imported quantity deterministically across\n    matching PI lines by line quantity/order, never above each PI line's own\n    quantity. Only use this fallback when the item has no canonical receiving\n    allocations; current canonical receipts remain authoritative.\n  */\n  IF v_allocated = 0 AND v_batch.id IS NOT NULL AND COALESCE(v_batch.import_quantity,0) > 0 THEN\n    SELECT COALESCE(sum(x.quantity),0)\n      INTO v_prior_claimed\n      FROM public.purchase_invoice_items x\n     WHERE x.item_type = 'inventory'\n       AND x.product_id = v_item.product_id\n       AND (x.batch_id = v_batch.id OR (x.batch_id IS NULL AND NULLIF(x.receiving_batch_number,'') IS NOT NULL AND x.receiving_batch_number = v_batch.batch_number))\n       AND (x.created_at < v_item.created_at OR (x.created_at = v_item.created_at AND x.id::text < v_item.id::text));\n\n    v_legacy_batch_share := GREATEST(0, LEAST(\n      COALESCE(v_item.quantity,0),\n      COALESCE(v_batch.import_quantity,0) - v_prior_claimed\n    ));\n  END IF;\n\n  RETURN COALESCE(v_allocated,0) + GREATEST(COALESCE(v_legacy_tx,0), COALESCE(v_legacy_batch_share,0));\nEND;\n$$","--\n-- Name: purchase_invoice_item_received_totals(\\"uuid\\"[]); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"purchase_invoice_item_received_totals\\"(\\"p_item_ids\\" \\"uuid\\"[]) RETURNS TABLE(\\"purchase_invoice_item_id\\" \\"uuid\\", \\"received_quantity\\" numeric)\n    LANGUAGE \\"sql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\n  SELECT i.id, public.purchase_invoice_item_received_quantity(i.id)\n    FROM public.purchase_invoice_items i\n   WHERE i.id = ANY(COALESCE(p_item_ids, ARRAY[]::uuid[]));\n$$","--\n-- Name: realign_reservation_for_delivery_challan(\\"uuid\\", boolean); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"realign_reservation_for_delivery_challan\\"(\\"p_challan_id\\" \\"uuid\\", \\"p_confirmed\\" boolean DEFAULT false) RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  RAISE EXCEPTION 'Batch reservation alignment is retired; select an eligible DC batch against the SO product reservation';\nEND; $$","--\n-- Name: reallocate_container_costs(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"reallocate_container_costs\\"(\\"p_container_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  pool numeric := public.calculate_container_landed_cost_pool(p_container_id);\n  total_qty numeric;\n  l record;\n  v_batch_id uuid;\n  batch_cost numeric;\nBEGIN\n  SELECT COALESCE(sum(quantity),0) INTO total_qty\n    FROM public.purchase_batch_cost_layers\n   WHERE import_container_id=p_container_id;\n  IF total_qty > 0 THEN\n    FOR l IN SELECT * FROM public.purchase_batch_cost_layers\n      WHERE import_container_id=p_container_id ORDER BY created_at,id FOR UPDATE LOOP\n      UPDATE public.purchase_batch_cost_layers\n             SET landed_cost_amount=round(pool * l.quantity / total_qty,2),\n                 final_functional_unit_cost=round(l.functional_unit_cost + pool * l.quantity / total_qty / l.quantity,2)\n       WHERE id=l.id;\n    END LOOP;\n    FOR v_batch_id IN SELECT DISTINCT pbl.batch_id FROM public.purchase_batch_cost_layers pbl\n      WHERE import_container_id=p_container_id LOOP\n      SELECT COALESCE(sum(quantity * final_functional_unit_cost) / NULLIF(sum(quantity),0),0)\n        INTO batch_cost\n        FROM public.purchase_batch_cost_layers pbl WHERE pbl.batch_id=v_batch_id;\n      UPDATE public.batches SET cost_per_unit=round(batch_cost,2), landed_cost_per_unit=round(batch_cost,2), updated_at=now()\n       WHERE id=v_batch_id AND COALESCE(cost_locked,false)=false;\n    END LOOP;\n    RETURN;\n  END IF;\n  SELECT COALESCE(sum(COALESCE(import_price,0)*COALESCE(import_quantity,0)),0)\n    INTO total_qty FROM public.batches WHERE import_container_id=p_container_id;\n  IF total_qty <= 0 THEN RETURN; END IF;\n  FOR l IN SELECT id, import_price, import_quantity, duty_charges, freight_charges, other_charges\n    FROM public.batches WHERE import_container_id=p_container_id AND COALESCE(cost_locked,false)=false LOOP\n    batch_cost := pool * (COALESCE(l.import_price,0)*COALESCE(l.import_quantity,0)) / total_qty;\n    UPDATE public.batches SET import_cost_allocated=round(batch_cost,2),\n      final_landed_cost=round((COALESCE(l.import_price,0)+COALESCE(l.duty_charges,0))*COALESCE(l.import_quantity,0)+COALESCE(l.freight_charges,0)+COALESCE(l.other_charges,0)+batch_cost,2),\n      landed_cost_per_unit=round(COALESCE(l.import_price,0)+COALESCE(l.duty_charges,0)+COALESCE(l.freight_charges,0)/NULLIF(l.import_quantity,0)+COALESCE(l.other_charges,0)/NULLIF(l.import_quantity,0)+batch_cost/NULLIF(l.import_quantity,0),2),\n      cost_per_unit=round(COALESCE(l.import_price,0)+COALESCE(l.duty_charges,0)+COALESCE(l.freight_charges,0)/NULLIF(l.import_quantity,0)+COALESCE(l.other_charges,0)/NULLIF(l.import_quantity,0)+batch_cost/NULLIF(l.import_quantity,0),2), updated_at=now()\n      WHERE id=l.id;\n  END LOOP;\nEND; $$","--\n-- Name: FUNCTION \\"reallocate_container_costs\\"(\\"p_container_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"reallocate_container_costs\\"(\\"p_container_id\\" \\"uuid\\") IS 'Allocates container costs proportionally by QUANTITY (not value)'","--\n-- Name: reallocate_on_batch_container_change(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"reallocate_on_batch_container_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- If container assignment changed, reallocate costs for OLD container\nIF TG_OP = 'UPDATE' AND OLD.import_container_id IS NOT NULL \nAND (NEW.import_container_id IS NULL OR NEW.import_container_id != OLD.import_container_id) THEN\nPERFORM reallocate_container_costs(OLD.import_container_id);\nEND IF;\n\n-- Reallocate costs for NEW container\nIF NEW.import_container_id IS NOT NULL THEN\nPERFORM reallocate_container_costs(NEW.import_container_id);\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: reassign_tax_document_period(\\"text\\", \\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"reassign_tax_document_period\\"(\\"p_source\\" \\"text\\", \\"p_document_id\\" \\"uuid\\", \\"p_tax_period_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_target public.tax_periods%ROWTYPE;\n  v_old_period_id uuid;\n  v_tax_type text;\n  v_tax_code_id uuid;\nBEGIN\n  SELECT * INTO v_target\n    FROM public.tax_periods\n   WHERE id = p_tax_period_id\n   FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Tax period % not found', p_tax_period_id; END IF;\n  IF v_target.status IN ('closed', 'filed') OR v_target.filing_status = 'filed' THEN\n    RAISE EXCEPTION 'Tax period % is filed or closed and cannot be selected', p_tax_period_id;\n  END IF;\n\n  CASE p_source\n    WHEN 'purchase_invoice' THEN\n      SELECT tax_period_id INTO v_old_period_id FROM public.purchase_invoices WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Purchase invoices require a PPN tax period'; END IF;\n    WHEN 'sales_invoice' THEN\n      SELECT tax_period_id INTO v_old_period_id FROM public.sales_invoices WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Sales invoice % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Sales invoices require a PPN tax period'; END IF;\n    WHEN 'credit_note' THEN\n      SELECT tax_period_id INTO v_old_period_id FROM public.credit_notes WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Credit note % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Credit notes require a PPN tax period'; END IF;\n    WHEN 'finance_expense_ppn' THEN\n      SELECT tax_period_id INTO v_old_period_id FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Expense % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Expenses require a PPN tax period for PPN reporting'; END IF;\n    WHEN 'finance_expense_pph' THEN\n      SELECT pph_tax_period_id, pph_code_id INTO v_old_period_id, v_tax_code_id\n        FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Expense % not found', p_document_id; END IF;\n      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id;\n      IF v_tax_type IS NULL OR v_target.tax_type <> v_tax_type THEN RAISE EXCEPTION 'Expense PPh tax type must match the selected period'; END IF;\n    WHEN 'payment_voucher' THEN\n      SELECT tax_period_id, pph_code_id INTO v_old_period_id, v_tax_code_id\n        FROM public.payment_vouchers WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found', p_document_id; END IF;\n      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id;\n      IF v_tax_type IS NULL OR v_target.tax_type <> v_tax_type THEN RAISE EXCEPTION 'Payment voucher PPh tax type must match the selected period'; END IF;\n    ELSE\n      RAISE EXCEPTION 'Unsupported tax document source %', p_source;\n  END CASE;\n\n  IF v_old_period_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.tax_periods\n     WHERE id=v_old_period_id AND (status IN ('closed', 'filed') OR filing_status='filed')\n  ) THEN\n    RAISE EXCEPTION 'The current tax period is filed or closed; reopen it before changing this document';\n  END IF;\n\n  CASE p_source\n    WHEN 'purchase_invoice' THEN UPDATE public.purchase_invoices SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'sales_invoice' THEN\n      UPDATE public.sales_invoices SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n      UPDATE public.faktur_pajak SET tax_period_id=p_tax_period_id WHERE sales_invoice_id=p_document_id;\n    WHEN 'credit_note' THEN UPDATE public.credit_notes SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'finance_expense_ppn' THEN UPDATE public.finance_expenses SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'finance_expense_pph' THEN UPDATE public.finance_expenses SET pph_tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'payment_voucher' THEN UPDATE public.payment_vouchers SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n  END CASE;\n\n  IF v_old_period_id IS NOT NULL THEN PERFORM public.compute_period_ppn(v_old_period_id); END IF;\n  PERFORM public.compute_period_ppn(p_tax_period_id);\nEND;\n$$","--\n-- Name: recalculate_expense_payment_state(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"recalculate_expense_payment_state\\"(\\"p_expense_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_supplier_paid numeric := 0;\n  v_pph_paid numeric := 0;\n  v_payable numeric := 0;\nBEGIN\n  IF public.historical_repair_context_active() THEN RETURN; END IF;\n\n  SELECT COALESCE(sum(va.allocated_amount),0) INTO v_supplier_paid\n    FROM public.voucher_allocations va\n    LEFT JOIN public.payment_vouchers pv ON pv.id=va.payment_voucher_id\n   WHERE va.finance_expense_id=p_expense_id\n     AND COALESCE(va.payment_kind,'supplier')='supplier'\n     AND COALESCE(pv.payment_purpose,'general') NOT IN ('salary_advance','salary_advance_settlement');\n  SELECT v_supplier_paid+COALESCE(sum(allocation_amount),0) INTO v_supplier_paid\n    FROM public.bank_statement_allocations\n   WHERE document_type='expense' AND document_id=p_expense_id\n     AND COALESCE(payment_kind,'supplier')='supplier';\n  SELECT v_supplier_paid+COALESCE(sum(COALESCE(NULLIF(b.debit_amount,0),b.credit_amount,0)),0) INTO v_supplier_paid\n    FROM public.bank_statement_lines b\n   WHERE b.matched_expense_id=p_expense_id AND b.payment_kind='supplier'\n     AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id=b.id);\n  SELECT COALESCE(sum(allocated_amount),0) INTO v_pph_paid\n    FROM public.voucher_allocations\n   WHERE finance_expense_id=p_expense_id AND payment_kind='pph23';\n  SELECT v_pph_paid+COALESCE(sum(allocation_amount),0) INTO v_pph_paid\n    FROM public.bank_statement_allocations\n   WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind='pph23';\n\n  v_payable := COALESCE(public.calculate_finance_expense_payable(p_expense_id),0);\n  UPDATE public.finance_expenses\n     SET paid_amount=LEAST(GREATEST(v_supplier_paid,0),GREATEST(v_payable,0)),\n         pph_paid_amount=GREATEST(v_pph_paid,0)\n   WHERE id=p_expense_id;\nEND;\n$$","--\n-- Name: recalculate_invoice_payment_from_allocations(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"recalculate_invoice_payment_from_allocations\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_invoice_id UUID;\nv_total_paid numeric(15,2);\nv_invoice_total numeric(15,2);\nBEGIN\n-- Determine which invoice to update\nIF TG_OP = 'DELETE' THEN\nv_invoice_id := OLD.invoice_id;\nELSE\nv_invoice_id := NEW.invoice_id;\nEND IF;\n\n-- Only proceed if we have an invoice_id\nIF v_invoice_id IS NULL THEN\nRETURN COALESCE(NEW, OLD);\nEND IF;\n\n-- Calculate total paid from invoice_payment_allocations\nSELECT COALESCE(SUM(allocated_amount), 0)\nINTO v_total_paid\nFROM invoice_payment_allocations\nWHERE invoice_id = v_invoice_id;\n\n-- Add payments from voucher_allocations\nv_total_paid := v_total_paid + COALESCE(\n(SELECT SUM(allocated_amount)\nFROM voucher_allocations\nWHERE sales_invoice_id = v_invoice_id\nAND voucher_type = 'receipt'), 0\n);\n\n-- Get invoice total\nSELECT total_amount INTO v_invoice_total\nFROM sales_invoices\nWHERE id = v_invoice_id;\n\n-- Update the invoice\nUPDATE sales_invoices\nSET\npaid_amount = v_total_paid,\npayment_status = CASE\nWHEN v_total_paid = 0 THEN 'pending'\nWHEN v_total_paid >= v_invoice_total THEN 'paid'\nWHEN v_total_paid > 0 AND v_total_paid < v_invoice_total THEN 'partial'\nELSE 'pending'\nEND\nWHERE id = v_invoice_id;\n\nRETURN COALESCE(NEW, OLD);\nEND;\n$$","--\n-- Name: recalculate_invoice_payment_status(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"recalculate_invoice_payment_status\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF TG_OP = 'INSERT' AND NEW.sales_invoice_id IS NOT NULL THEN\n    PERFORM public.apply_receipt_allocation_rounding_adjustment(NEW.sales_invoice_id, NEW.receipt_voucher_id);\n  ELSIF TG_OP = 'UPDATE' THEN\n    IF NEW.sales_invoice_id IS NOT NULL THEN\n      PERFORM public.apply_receipt_allocation_rounding_adjustment(NEW.sales_invoice_id, NEW.receipt_voucher_id);\n    END IF;\n\n    IF OLD.sales_invoice_id IS NOT NULL\n       AND OLD.sales_invoice_id IS DISTINCT FROM NEW.sales_invoice_id THEN\n      PERFORM public.clear_receipt_allocation_rounding_adjustment(OLD.sales_invoice_id, OLD.receipt_voucher_id);\n    END IF;\n  ELSIF TG_OP = 'DELETE' AND OLD.sales_invoice_id IS NOT NULL THEN\n    PERFORM public.clear_receipt_allocation_rounding_adjustment(OLD.sales_invoice_id, OLD.receipt_voucher_id);\n  END IF;\n\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$","--\n-- Name: recalculate_journal_entry_totals(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"recalculate_journal_entry_totals\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_entry_id UUID;\nv_total_debit NUMERIC;\nv_total_credit NUMERIC;\nBEGIN\n-- Determine which journal entry to update\nIF (TG_OP = 'DELETE') THEN\nv_entry_id := OLD.journal_entry_id;\nELSE\nv_entry_id := NEW.journal_entry_id;\nEND IF;\n\n-- Calculate totals from all lines\nSELECT \nCOALESCE(SUM(debit), 0),\nCOALESCE(SUM(credit), 0)\nINTO v_total_debit, v_total_credit\nFROM journal_entry_lines\nWHERE journal_entry_id = v_entry_id;\n\n-- Update the journal entry totals\nUPDATE journal_entries\nSET \ntotal_debit = v_total_debit,\ntotal_credit = v_total_credit\nWHERE id = v_entry_id;\n\n-- Return appropriate record\nIF (TG_OP = 'DELETE') THEN\nRETURN OLD;\nELSE\nRETURN NEW;\nEND IF;\nEND;\n$$","--\n-- Name: FUNCTION \\"recalculate_journal_entry_totals\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"recalculate_journal_entry_totals\\"() IS 'Automatically recalculates and updates journal entry totals when lines are added/modified/deleted - CRITICAL for accounting accuracy'","--\n-- Name: recalculate_purchase_invoice_payment_state(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"recalculate_purchase_invoice_payment_state\\"(\\"p_purchase_invoice_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_invoice record;\n  v_total_paid numeric(18,2);\nBEGIN\n  IF p_purchase_invoice_id IS NULL THEN\n    RETURN;\n  END IF;\n\n  SELECT id, total_amount\n  INTO v_invoice\n  FROM public.purchase_invoices\n  WHERE id = p_purchase_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  -- Only count allocations whose parent payment voucher is POSTED to GL.\n  -- A saved-but-unposted PV is a draft: its allocations represent intent,\n  -- not a completed payment. Was the sole diff vs. the previous version.\n  SELECT COALESCE(SUM(va.allocated_amount), 0)\n  INTO v_total_paid\n  FROM public.voucher_allocations va\n  JOIN public.payment_vouchers pv\n    ON pv.id = va.payment_voucher_id\n  WHERE va.purchase_invoice_id = p_purchase_invoice_id\n    AND va.voucher_type = 'payment'\n    AND pv.is_posted = TRUE;\n\n  UPDATE public.purchase_invoices\n  SET\n    paid_amount = v_total_paid,\n    status = CASE\n      WHEN v_total_paid <= 0 THEN 'unpaid'\n      WHEN v_total_paid >= COALESCE(v_invoice.total_amount, 0) THEN 'paid'\n      ELSE 'partial'\n    END\n  WHERE id = p_purchase_invoice_id;\nEND;\n$$","--\n-- Name: recalculate_sales_invoice_payment_state(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"recalculate_sales_invoice_payment_state\\"(\\"p_invoice_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_invoice record;\n  v_allocated numeric(18,2);\n  v_adjustment numeric(18,2);\n  v_paid numeric(18,2);\nBEGIN\n  SELECT id, total_amount\n  INTO v_invoice\n  FROM public.sales_invoices\n  WHERE id = p_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  v_allocated := public.get_invoice_allocation_amount(p_invoice_id, NULL);\n  v_adjustment := public.get_invoice_rounding_adjustment_amount(p_invoice_id);\n  v_paid := v_allocated + v_adjustment;\n\n  UPDATE public.sales_invoices\n  SET\n    paid_amount = v_paid,\n    payment_status = CASE\n      WHEN v_paid <= 0 THEN 'pending'\n      WHEN v_paid >= v_invoice.total_amount THEN 'paid'\n      ELSE 'partial'\n    END\n  WHERE id = p_invoice_id;\nEND;\n$$","--\n-- Name: receive_purchase_invoice_item(\\"uuid\\", \\"jsonb\\", numeric, \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"receive_purchase_invoice_item\\"(\\"p_purchase_invoice_item_id\\" \\"uuid\\", \\"p_payload\\" \\"jsonb\\", \\"p_received_quantity\\" numeric, \\"p_operation_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_item public.purchase_invoice_items%ROWTYPE;\n  v_invoice public.purchase_invoices%ROWTYPE;\n  v_batch public.batches%ROWTYPE;\n  v_batch_id uuid;\n  v_existing numeric;\n  v_allocation_id uuid;\n  v_make_id uuid;\n  v_container_id uuid;\n  v_currency text;\n  v_rate numeric;\n  v_tx_unit numeric;\n  v_func_unit numeric;\n  v_existing_batch boolean := false;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','warehouse','manager']) THEN\n    RAISE EXCEPTION 'Permission denied for inventory receiving';\n  END IF;\n  IF p_operation_id IS NULL OR p_received_quantity IS NULL OR p_received_quantity <= 0 THEN\n    RAISE EXCEPTION 'A positive quantity and operation_id are required';\n  END IF;\n  SELECT * INTO v_item FROM public.purchase_invoice_items WHERE id=p_purchase_invoice_item_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice item not found'; END IF;\n  SELECT * INTO v_invoice FROM public.purchase_invoices WHERE id=v_item.purchase_invoice_id;\n  IF v_item.item_type <> 'inventory' OR v_item.product_id IS NULL\n     OR NULLIF(p_payload->>'product_id','')::uuid IS DISTINCT FROM v_item.product_id THEN\n    RAISE EXCEPTION 'Receiving requires the invoice inventory product';\n  END IF;\n  SELECT batch_id,id INTO v_batch_id,v_allocation_id\n    FROM public.purchase_invoice_receiving_allocations WHERE operation_id=p_operation_id;\n  IF FOUND THEN\n    RETURN jsonb_build_object('success',true,'batch_id',v_batch_id,\n      'allocation_id',v_allocation_id,'idempotent_retry',true);\n  END IF;\n  SELECT COALESCE(sum(received_quantity),0) INTO v_existing\n    FROM public.purchase_invoice_receiving_allocations\n   WHERE purchase_invoice_item_id=v_item.id AND status='received';\n  IF v_existing+p_received_quantity > v_item.quantity THEN\n    RAISE EXCEPTION 'Received quantity exceeds invoice line quantity';\n  END IF;\n  v_make_id := NULLIF(p_payload->>'make_id','')::uuid;\n  v_container_id := NULLIF(p_payload->>'import_container_id','')::uuid;\n  IF v_make_id IS NOT NULL AND NOT EXISTS\n    (SELECT 1 FROM public.product_sources WHERE id=v_make_id AND product_id=v_item.product_id) THEN\n    RAISE EXCEPTION 'Selected Make / Manufacturer does not belong to the invoice product';\n  END IF;\n  IF NULLIF(p_payload->>'batch_id','') IS NOT NULL THEN\n    SELECT * INTO v_batch FROM public.batches WHERE id=(p_payload->>'batch_id')::uuid FOR UPDATE;\n  ELSE\n    SELECT * INTO v_batch FROM public.batches\n     WHERE product_id=v_item.product_id AND batch_number=p_payload->>'batch_number'\n       AND (make_id=v_make_id OR make_id IS NULL) AND coalesce(is_active,true)\n     ORDER BY (make_id IS NULL),created_at LIMIT 1 FOR UPDATE;\n  END IF;\n  IF FOUND THEN\n    v_existing_batch := true;\n    IF v_batch.product_id IS DISTINCT FROM v_item.product_id THEN\n      RAISE EXCEPTION 'Product does not match selected batch';\n    END IF;\n    IF v_batch.make_id IS NOT NULL AND v_batch.make_id IS DISTINCT FROM v_make_id THEN\n      RAISE EXCEPTION 'Make does not match selected batch';\n    END IF;\n    IF NULLIF(p_payload->>'expiry_date','')::date IS NOT NULL\n       AND v_batch.expiry_date IS NOT NULL\n       AND NULLIF(p_payload->>'expiry_date','')::date IS DISTINCT FROM v_batch.expiry_date THEN\n      RAISE EXCEPTION 'Expiry date conflicts with existing physical batch';\n    END IF;\n    PERFORM public.post_inventory_movement(p_operation_id,v_batch.product_id,v_batch.id,\n      'adjustment',p_received_quantity,v_invoice.invoice_date,v_invoice.invoice_number,\n      'purchase_invoice_receiving',v_invoice.id,\n      'Purchase Invoice receiving into existing batch '||v_batch.batch_number,\n      auth.uid(),v_batch.current_stock,v_batch.current_stock+p_received_quantity);\n    UPDATE public.batches SET import_quantity=import_quantity+p_received_quantity,updated_at=now()\n      WHERE id=v_batch.id;\n    v_batch_id := v_batch.id;\n  ELSE\n    p_payload := jsonb_set(p_payload,'{import_quantity}',to_jsonb(p_received_quantity),true);\n    p_payload := jsonb_set(p_payload,'{purchase_invoice_id}',to_jsonb(v_item.purchase_invoice_id),true);\n    p_payload := jsonb_set(p_payload,'{supplier_id}',to_jsonb(v_invoice.supplier_id),true);\n    SELECT (public.save_batch_inventory_v1(NULL,p_payload,p_operation_id)->>'batch_id')::uuid INTO v_batch_id;\n  END IF;\n  v_currency := upper(coalesce(v_invoice.currency,'IDR'));\n  v_rate := CASE WHEN v_currency='IDR' THEN 1 ELSE coalesce(v_invoice.exchange_rate,0) END;\n  IF v_rate<=0 THEN RAISE EXCEPTION 'Purchase invoice exchange rate is required'; END IF;\n  v_tx_unit := coalesce(v_item.unit_price,0);\n  v_func_unit := round(v_tx_unit*v_rate,2);\n  INSERT INTO public.purchase_invoice_receiving_allocations(\n    purchase_invoice_id,purchase_invoice_item_id,batch_id,received_quantity,\n    operation_id,received_by,currency,exchange_rate,functional_unit_cost,\n    functional_total_cost,import_container_id)\n  VALUES(v_item.purchase_invoice_id,v_item.id,v_batch_id,p_received_quantity,\n    p_operation_id,auth.uid(),v_currency,v_rate,v_func_unit,\n    round(v_func_unit*p_received_quantity,2),v_container_id)\n  RETURNING id INTO v_allocation_id;\n  INSERT INTO public.purchase_batch_cost_layers(\n    receiving_allocation_id,purchase_invoice_id,purchase_invoice_item_id,batch_id,\n    import_container_id,quantity,currency,exchange_rate,transaction_unit_cost,\n    functional_unit_cost,functional_total_cost,final_functional_unit_cost)\n  VALUES(v_allocation_id,v_item.purchase_invoice_id,v_item.id,v_batch_id,v_container_id,\n    p_received_quantity,v_currency,v_rate,v_tx_unit,v_func_unit,\n    round(v_func_unit*p_received_quantity,2),v_func_unit);\n  IF v_existing_batch THEN\n    PERFORM public.apply_batch_receipt_weighted_average(v_batch_id,p_received_quantity,v_func_unit);\n  END IF;\n  RETURN jsonb_build_object('success',true,'batch_id',v_batch_id,'allocation_id',v_allocation_id);\nEND; $$","--\n-- Name: recompute_periods_for_date(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"recompute_periods_for_date\\"(\\"p_date\\" \\"date\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_period_id uuid;\nBEGIN\n  IF p_date IS NULL THEN RETURN; END IF;\n  FOR v_period_id IN\n    SELECT id FROM tax_periods\n     WHERE fiscal_year  = EXTRACT(YEAR  FROM p_date)::int\n       AND period_month = EXTRACT(MONTH FROM p_date)::int\n  LOOP\n    PERFORM compute_period_ppn(v_period_id);\n  END LOOP;\nEND $$","--\n-- Name: recompute_pph_periods_for_date(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"recompute_pph_periods_for_date\\"(\\"p_date\\" \\"date\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_tax_type text;\n  v_period_id uuid;\nBEGIN\n  IF p_date IS NULL THEN\n    RETURN;\n  END IF;\n\n  FOREACH v_tax_type IN ARRAY ARRAY['PPh21', 'PPh22', 'PPh23', 'PPh4(2)']::text[]\n  LOOP\n    v_period_id := public.upsert_tax_period(\n      EXTRACT(YEAR FROM p_date)::int,\n      EXTRACT(MONTH FROM p_date)::int,\n      v_tax_type\n    );\n    PERFORM public.compute_period_ppn(v_period_id);\n  END LOOP;\n\n  -- Keep a legacy stored consolidated period synchronized when one exists.\n  FOR v_period_id IN\n    SELECT id\n    FROM public.tax_periods\n    WHERE fiscal_year = EXTRACT(YEAR FROM p_date)::int\n      AND period_month = EXTRACT(MONTH FROM p_date)::int\n      AND tax_type = 'PPh_Unifikasi'\n  LOOP\n    PERFORM public.compute_period_ppn(v_period_id);\n  END LOOP;\nEND;\n$$","--\n-- Name: recompute_price_request_counts(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"recompute_price_request_counts\\"(\\"p_pr_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nv_total    integer;\nv_src_recv integer;\nv_src_pend integer;\nv_fq_ready integer;\nv_fq_pend  integer;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'manager') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot recompute price request counts', v_role;\nEND IF;\n\nSELECT\nCOUNT(*),\nCOUNT(*) FILTER (WHERE price_status = 'received'),\nCOUNT(*) FILTER (WHERE price_status IN ('pending', 'requested')),\nCOUNT(*) FILTER (WHERE final_quote_price IS NOT NULL),\nCOUNT(*) FILTER (WHERE price_status = 'received' AND final_quote_price IS NULL)\nINTO v_total, v_src_recv, v_src_pend, v_fq_ready, v_fq_pend\nFROM price_request_items\nWHERE price_request_id = p_pr_id;\n\nUPDATE price_requests\nSET\ntotal_products        = v_total,\nsource_price_received = v_src_recv,\nsource_price_pending  = v_src_pend,\nfinal_quote_ready     = v_fq_ready,\nfinal_quote_pending   = v_fq_pend,\nupdated_at            = now()\nWHERE id = p_pr_id;\nEND;\n$$","--\n-- Name: reconcile_so_product_reservation_v2(\\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"reconcile_so_product_reservation_v2\\"(\\"p_sales_order_item_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\" DEFAULT 'SO state reconciliation'::\\"text\\") RETURNS numeric\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_item record;\n  v_res public.so_product_reservations%ROWTYPE;\n  v_delivered numeric;\n  v_required numeric;\n  v_delta numeric;\n  v_atp numeric;\n  v_grant numeric;\nBEGIN\n  SELECT soi.*, so.status::text AS so_status INTO v_item\n  FROM public.sales_order_items soi\n  JOIN public.sales_orders so ON so.id = soi.sales_order_id\n  WHERE soi.id = p_sales_order_item_id\n  FOR UPDATE OF soi, so;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Order item not found';\n  END IF;\n\n  -- Serialize ATP decisions for the product\n  PERFORM pg_advisory_xact_lock(hashtextextended(v_item.product_id::text, 0));\n\n  SELECT COALESCE(sum(dci.quantity), 0) INTO v_delivered\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  WHERE dci.sales_order_item_id = v_item.id\n    AND dc.approval_status = 'approved';\n\n  IF v_delivered > v_item.quantity THEN\n    RAISE EXCEPTION 'Delivered quantity exceeds ordered quantity';\n  END IF;\n\n  v_required := CASE\n    WHEN v_item.so_status IN ('approved', 'stock_reserved', 'shortage', 'pending_delivery', 'partially_delivered')\n      THEN v_item.quantity - v_delivered\n    ELSE 0\n  END;\n\n  SELECT * INTO v_res\n  FROM public.so_product_reservations\n  WHERE sales_order_item_id = v_item.id\n    AND status = 'active'\n  FOR UPDATE;\n\n  IF v_required = 0 THEN\n    IF FOUND THEN\n      UPDATE public.so_product_reservations\n      SET reserved_quantity = 0,\n          status = 'released',\n          closed_at = now(),\n          updated_at = now(),\n          close_reason = p_reason\n      WHERE id = v_res.id;\n\n      INSERT INTO public.so_product_reservation_events(\n        reservation_id, sales_order_id, sales_order_item_id, event_type,\n        quantity_delta, quantity_after, reason, actor_id\n      ) VALUES (\n        v_res.id, v_item.sales_order_id, v_item.id, 'released',\n        -v_res.reserved_quantity, 0, p_reason, auth.uid()\n      );\n    END IF;\n    RETURN 0;\n  END IF;\n\n  -- Calculate available product ATP (excluding this SO item's existing active reservation if any)\n  v_atp := public.product_available_to_promise(\n    v_item.product_id,\n    CASE WHEN v_res.id IS NOT NULL THEN v_item.id ELSE NULL END\n  );\n\n  -- Reserve what is physically available; unfulfilled quantity is handled as shortage\n  v_grant := LEAST(v_required, GREATEST(COALESCE(v_atp, 0), 0));\n\n  IF NOT FOUND THEN\n    IF v_grant > 0 THEN\n      INSERT INTO public.so_product_reservations(\n        sales_order_id, sales_order_item_id, product_id, reserved_quantity, created_by\n      ) VALUES (\n        v_item.sales_order_id, v_item.id, v_item.product_id, v_grant, auth.uid()\n      ) RETURNING * INTO v_res;\n\n      INSERT INTO public.so_product_reservation_events(\n        reservation_id, sales_order_id, sales_order_item_id, event_type,\n        quantity_delta, quantity_after, reason, actor_id\n      ) VALUES (\n        v_res.id, v_item.sales_order_id, v_item.id, 'created',\n        v_grant, v_grant, p_reason, auth.uid()\n      );\n    END IF;\n  ELSE\n    IF v_res.product_id <> v_item.product_id THEN\n      RAISE EXCEPTION 'Cannot change product on an actively reserved SO item';\n    END IF;\n\n    IF v_grant = 0 THEN\n      UPDATE public.so_product_reservations\n      SET reserved_quantity = 0,\n          status = 'released',\n          closed_at = now(),\n          updated_at = now(),\n          close_reason = p_reason\n      WHERE id = v_res.id;\n\n      INSERT INTO public.so_product_reservation_events(\n        reservation_id, sales_order_id, sales_order_item_id, event_type,\n        quantity_delta, quantity_after, reason, actor_id\n      ) VALUES (\n        v_res.id, v_item.sales_order_id, v_item.id, 'released',\n        -v_res.reserved_quantity, 0, p_reason, auth.uid()\n      );\n    ELSE\n      v_delta := v_grant - v_res.reserved_quantity;\n      IF v_delta <> 0 THEN\n        UPDATE public.so_product_reservations\n        SET reserved_quantity = v_grant,\n            updated_at = now()\n        WHERE id = v_res.id;\n\n        INSERT INTO public.so_product_reservation_events(\n          reservation_id, sales_order_id, sales_order_item_id, event_type,\n          quantity_delta, quantity_after, reason, actor_id\n        ) VALUES (\n          v_res.id, v_item.sales_order_id, v_item.id,\n          CASE WHEN v_delta > 0 THEN 'increased' ELSE 'decreased' END,\n          v_delta, v_grant, p_reason, auth.uid()\n        );\n      END IF;\n    END IF;\n  END IF;\n\n  RETURN v_grant;\nEND;\n$$","--\n-- Name: record_batch_import_accounting_entry(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"record_batch_import_accounting_entry\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_inventory_coa_id uuid;\nv_payable_coa_id uuid;\nv_total_cost numeric;\nv_duty_amount numeric;\nBEGIN\n-- Only create accounting entry if batch has final landed cost\nIF NEW.final_landed_cost IS NULL OR NEW.final_landed_cost = 0 THEN\nRETURN NEW;\nEND IF;\n\n-- Get COA IDs for Inventory and Accounts Payable\nSELECT id INTO v_inventory_coa_id\nFROM chart_of_accounts\nWHERE account_code = '1140'\nLIMIT 1;\n\nSELECT id INTO v_payable_coa_id\nFROM chart_of_accounts\nWHERE account_code = '2110'\nLIMIT 1;\n\n-- Calculate total cost (this includes allocated container costs)\nv_total_cost := NEW.final_landed_cost;\n\n-- Calculate duty amount based on duty_percent if available\nIF NEW.duty_percent IS NOT NULL AND NEW.duty_percent > 0 THEN\nv_duty_amount := (NEW.import_price * NEW.duty_percent) / 100;\nELSE\nv_duty_amount := 0;\nEND IF;\n\n-- Create journal entry for inventory acquisition\n-- DR: Inventory (includes base cost + allocated import expenses)\n-- CR: Accounts Payable\nINSERT INTO finance_journal_entries (\nentry_date,\nreference_type,\nreference_id,\ndescription,\ntotal_amount,\ncreated_by\n)\nVALUES (\nNEW.import_date,\n'batch_import',\nNEW.id,\n'Import of ' || (SELECT product_name FROM products WHERE id = NEW.product_id) || \n' - Batch ' || NEW.batch_number || \nCASE WHEN v_duty_amount > 0 THEN ' (incl. ' || ROUND(NEW.duty_percent, 2) || '% duty)' ELSE '' END,\nv_total_cost,\nNEW.created_by\n)\nRETURNING id INTO v_inventory_coa_id;  -- Reusing variable for journal entry ID\n\n-- Debit: Inventory Asset\nINSERT INTO finance_journal_entry_lines (\njournal_entry_id,\ncoa_id,\ndebit,\ncredit,\ndescription\n)\nVALUES (\nv_inventory_coa_id,\n(SELECT id FROM chart_of_accounts WHERE account_code = '1140' LIMIT 1),\nv_total_cost,\n0,\n'Inventory - ' || NEW.batch_number\n);\n\n-- Credit: Accounts Payable\nINSERT INTO finance_journal_entry_lines (\njournal_entry_id,\ncoa_id,\ndebit,\ncredit,\ndescription\n)\nVALUES (\nv_inventory_coa_id,\nv_payable_coa_id,\n0,\nv_total_cost,\n'Payable - Import ' || NEW.batch_number\n);\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: record_tax_payment(\\"uuid\\", \\"text\\", \\"date\\", numeric, \\"uuid\\", \\"text\\", \\"text\\", \\"text\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"record_tax_payment\\"(\\"p_tax_period_id\\" \\"uuid\\", \\"p_tax_type\\" \\"text\\", \\"p_payment_date\\" \\"date\\", \\"p_amount\\" numeric, \\"p_bank_account_id\\" \\"uuid\\", \\"p_billing_code\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_ntpn\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_government_reference\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_notes\\" \\"text\\" DEFAULT NULL::\\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_tp_id            uuid;\n  v_je_id            uuid;\n  v_je_number        text;\n  v_period           tax_periods%ROWTYPE;\n  v_payable_code     text;\n  v_payable_acct_id  uuid;\n  v_bank_acct_coa_id uuid;\n  v_ref_number       text;\nBEGIN\n  IF p_amount IS NULL OR p_amount <= 0 THEN\n    RAISE EXCEPTION 'Tax payment amount must be > 0';\n  END IF;\n\n  SELECT * INTO v_period FROM tax_periods WHERE id = p_tax_period_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax period % not found', p_tax_period_id;\n  END IF;\n  IF v_period.status = 'closed' THEN\n    RAISE EXCEPTION 'Cannot record tax payment on a closed period';\n  END IF;\n  IF v_period.tax_type <> p_tax_type THEN\n    RAISE EXCEPTION 'Tax type mismatch: period is %, payment is %',\n      v_period.tax_type, p_tax_type;\n  END IF;\n\n  -- Map tax type → payable account code\n  v_payable_code := CASE p_tax_type\n    WHEN 'PPN'      THEN '2130'\n    WHEN 'PPh21'    THEN '2131'\n    WHEN 'PPh22'    THEN '2137'\n    WHEN 'PPh23'    THEN '2132'\n    WHEN 'PPh4(2)'  THEN '2138'\n    WHEN 'PPh_Unifikasi' THEN '2131'  -- treated as PPh 21 payable by default\n    ELSE NULL\n  END;\n\n  IF v_payable_code IS NULL THEN\n    RAISE EXCEPTION 'Unknown tax_type: %', p_tax_type;\n  END IF;\n\n  SELECT id INTO v_payable_acct_id FROM chart_of_accounts WHERE code = v_payable_code;\n  IF v_payable_acct_id IS NULL THEN\n    RAISE EXCEPTION 'Payable account % missing from Chart of Accounts', v_payable_code;\n  END IF;\n\n  -- Bank account → CoA account\n  IF p_bank_account_id IS NULL THEN\n    RAISE EXCEPTION 'Bank account is required for a tax payment';\n  END IF;\n  SELECT coa_id INTO v_bank_acct_coa_id FROM bank_accounts WHERE id = p_bank_account_id;\n  IF v_bank_acct_coa_id IS NULL THEN\n    -- Fallback to generic Bank BCA (1111) when bank_accounts.coa_id not wired\n    SELECT id INTO v_bank_acct_coa_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\n  END IF;\n  IF v_bank_acct_coa_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot resolve bank CoA account for tax payment';\n  END IF;\n\n  -- 1) Create tax_payments row (draft)\n  INSERT INTO tax_payments\n    (tax_period_id, tax_type, payment_date, amount,\n     bank_account_id, billing_code, ntpn, government_reference, notes,\n     status, created_by)\n  VALUES\n    (p_tax_period_id, p_tax_type, p_payment_date, p_amount,\n     p_bank_account_id, p_billing_code, p_ntpn, p_government_reference, p_notes,\n     'draft', auth.uid())\n  RETURNING id INTO v_tp_id;\n\n  v_ref_number := COALESCE(NULLIF(p_ntpn,''), NULLIF(p_billing_code,''),\n                           'TAX-' || to_char(p_payment_date, 'YYMM') || '-' || substr(v_tp_id::text, 1, 8));\n\n  -- 2) Post journal entry: Dr Tax Payable / Cr Bank\n  v_je_number := next_journal_entry_number();\n\n  INSERT INTO journal_entries\n    (entry_number, entry_date, source_module, reference_id, reference_number,\n     description, total_debit, total_credit, is_posted, posted_by)\n  VALUES\n    (v_je_number, p_payment_date, 'tax_payment', v_tp_id, v_ref_number,\n     'Tax Payment ' || p_tax_type || ' — ' || v_ref_number,\n     p_amount, p_amount, true, auth.uid())\n  RETURNING id INTO v_je_id;\n\n  INSERT INTO journal_entry_lines\n    (journal_entry_id, line_number, account_id, description, debit, credit)\n  VALUES\n    (v_je_id, 1, v_payable_acct_id,\n     p_tax_type || ' payment — ' || v_ref_number,\n     p_amount, 0),\n    (v_je_id, 2, v_bank_acct_coa_id,\n     'Bank ' || p_tax_type || ' payment — ' || v_ref_number,\n     0, p_amount);\n\n  -- 3) Link back and mark posted\n  UPDATE tax_payments SET\n    journal_entry_id = v_je_id,\n    status           = 'posted',\n    updated_at       = now()\n  WHERE id = v_tp_id;\n\n  -- 4) Nudge the period status if it was open\n  UPDATE tax_periods SET\n    status = CASE WHEN status = 'open' THEN 'payment_pending' ELSE status END,\n    updated_at = now()\n  WHERE id = p_tax_period_id;\n\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)\n  VALUES (auth.uid(), 'tax_payments', 'insert', v_tp_id,\n          jsonb_build_object(\n            'tax_period_id', p_tax_period_id,\n            'tax_type',      p_tax_type,\n            'amount',        p_amount,\n            'journal_entry_id', v_je_id\n          ));\n\n  RETURN v_tp_id;\nEND $$","--\n-- Name: record_tax_payment(\\"uuid\\", \\"text\\", \\"date\\", numeric, \\"uuid\\", \\"text\\", \\"text\\", \\"text\\", \\"text\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"record_tax_payment\\"(\\"p_tax_period_id\\" \\"uuid\\", \\"p_tax_type\\" \\"text\\", \\"p_payment_date\\" \\"date\\", \\"p_amount\\" numeric, \\"p_bank_account_id\\" \\"uuid\\", \\"p_billing_code\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_ntpn\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_government_reference\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_notes\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_payment_reference\\" \\"text\\" DEFAULT NULL::\\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_tp_id            uuid;\n  v_je_id            uuid;\n  v_je_number        text;\n  v_period           tax_periods%ROWTYPE;\n  v_payable_code     text;\n  v_payable_acct_id  uuid;\n  v_bank_acct_coa_id uuid;\n  v_ref_number       text;\nBEGIN\n  IF p_amount IS NULL OR p_amount <= 0 THEN\n    RAISE EXCEPTION 'Tax payment amount must be > 0';\n  END IF;\n\n  SELECT * INTO v_period FROM tax_periods WHERE id = p_tax_period_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax period % not found', p_tax_period_id;\n  END IF;\n  IF v_period.status = 'closed' THEN\n    RAISE EXCEPTION 'Cannot record tax payment on a closed period';\n  END IF;\n  IF v_period.tax_type <> p_tax_type THEN\n    RAISE EXCEPTION 'Tax type mismatch: period is %, payment is %',\n      v_period.tax_type, p_tax_type;\n  END IF;\n\n  v_payable_code := CASE p_tax_type\n    WHEN 'PPN'      THEN '2130'\n    WHEN 'PPh21'    THEN '2131'\n    WHEN 'PPh22'    THEN '2137'\n    WHEN 'PPh23'    THEN '2132'\n    WHEN 'PPh4(2)'  THEN '2138'\n    WHEN 'PPh_Unifikasi' THEN '2131'\n    ELSE NULL\n  END;\n\n  IF v_payable_code IS NULL THEN\n    RAISE EXCEPTION 'Unknown tax_type: %', p_tax_type;\n  END IF;\n\n  SELECT id INTO v_payable_acct_id FROM chart_of_accounts WHERE code = v_payable_code;\n  IF v_payable_acct_id IS NULL THEN\n    RAISE EXCEPTION 'Payable account % missing from Chart of Accounts', v_payable_code;\n  END IF;\n\n  IF p_bank_account_id IS NULL THEN\n    RAISE EXCEPTION 'Bank account is required for a tax payment';\n  END IF;\n  SELECT coa_id INTO v_bank_acct_coa_id FROM bank_accounts WHERE id = p_bank_account_id;\n  IF v_bank_acct_coa_id IS NULL THEN\n    SELECT id INTO v_bank_acct_coa_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\n  END IF;\n  IF v_bank_acct_coa_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot resolve bank CoA account for tax payment';\n  END IF;\n\n  INSERT INTO tax_payments\n    (tax_period_id, tax_type, payment_date, amount,\n     bank_account_id, billing_code, ntpn, government_reference,\n     payment_reference, notes,\n     status, created_by)\n  VALUES\n    (p_tax_period_id, p_tax_type, p_payment_date, p_amount,\n     p_bank_account_id, p_billing_code, p_ntpn, p_government_reference,\n     p_payment_reference, p_notes,\n     'draft', auth.uid())\n  RETURNING id INTO v_tp_id;\n\n  v_ref_number := COALESCE(\n    NULLIF(p_ntpn, ''),\n    NULLIF(p_billing_code, ''),\n    NULLIF(p_payment_reference, ''),\n    'TAX-' || to_char(p_payment_date, 'YYMM') || '-' || substr(v_tp_id::text, 1, 8)\n  );\n\n  v_je_number := next_journal_entry_number();\n\n  INSERT INTO journal_entries\n    (entry_number, entry_date, source_module, reference_id, reference_number,\n     description, total_debit, total_credit, is_posted, posted_by)\n  VALUES\n    (v_je_number, p_payment_date, 'tax_payment', v_tp_id, v_ref_number,\n     'Tax Payment ' || p_tax_type || ' — ' || v_ref_number,\n     p_amount, p_amount, true, auth.uid())\n  RETURNING id INTO v_je_id;\n\n  INSERT INTO journal_entry_lines\n    (journal_entry_id, line_number, account_id, description, debit, credit)\n  VALUES\n    (v_je_id, 1, v_payable_acct_id,\n     p_tax_type || ' payment — ' || v_ref_number, p_amount, 0),\n    (v_je_id, 2, v_bank_acct_coa_id,\n     'Bank ' || p_tax_type || ' payment — ' || v_ref_number, 0, p_amount);\n\n  UPDATE tax_payments SET\n    journal_entry_id = v_je_id,\n    status = 'posted',\n    updated_at = now()\n  WHERE id = v_tp_id;\n\n  UPDATE tax_periods SET\n    status = CASE WHEN status = 'open' THEN 'payment_pending' ELSE status END,\n    updated_at = now()\n  WHERE id = p_tax_period_id;\n\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)\n  VALUES (auth.uid(), 'tax_payments', 'insert', v_tp_id,\n          jsonb_build_object(\n            'tax_period_id',     p_tax_period_id,\n            'tax_type',          p_tax_type,\n            'amount',            p_amount,\n            'journal_entry_id',  v_je_id,\n            'payment_reference', p_payment_reference,\n            'billing_code',      p_billing_code,\n            'ntpn',              p_ntpn\n          ));\n\n  RETURN v_tp_id;\nEND $$","--\n-- Name: refresh_bank_statement_allocation_status(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"refresh_bank_statement_allocation_status\\"(\\"p_bank_line_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_total numeric;\n  v_allocated numeric;\n  v_existing_status text;\n  v_existing_matching_status text;\n  v_fund_transfer uuid;\n  v_conflict boolean := false;\n  v_matching_status text;\nBEGIN\n  SELECT COALESCE(NULLIF(debit_amount, 0), credit_amount, 0),\n         reconciliation_status, matching_status, matched_fund_transfer_id\n    INTO v_total, v_existing_status, v_existing_matching_status, v_fund_transfer\n    FROM public.bank_statement_lines\n   WHERE id = p_bank_line_id\n   FOR UPDATE;\n\n  SELECT COALESCE(sum(allocation_amount), 0)\n    INTO v_allocated\n    FROM public.bank_statement_allocations\n   WHERE bank_statement_line_id = p_bank_line_id;\n\n  IF v_allocated > 0.01 AND v_allocated >= v_total - 0.01\n     AND v_fund_transfer IS NOT NULL\n     AND public.historical_allocation_relink_context_active()\n     AND EXISTS (\n       SELECT 1\n         FROM public.bank_statement_lines other\n        WHERE other.id <> p_bank_line_id\n          AND other.matched_fund_transfer_id = v_fund_transfer\n          AND other.matching_status = 'confirmed'\n     ) THEN\n    v_conflict := true;\n  END IF;\n\n  v_matching_status := CASE\n    WHEN v_allocated <= 0.01 THEN 'none'\n    WHEN v_conflict AND v_existing_matching_status <> 'confirmed' THEN 'suggested'\n    ELSE 'confirmed'\n  END;\n\n  UPDATE public.bank_statement_lines\n     SET reconciliation_status = CASE\n           WHEN v_allocated <= 0.01 THEN 'unmatched'\n           WHEN v_allocated < v_total - 0.01 THEN 'partially_reconciled'\n           ELSE 'matched'\n         END,\n         matching_status = v_matching_status,\n         matched_at = CASE WHEN v_allocated <= 0.01 THEN NULL ELSE COALESCE(matched_at, now()) END,\n         matched_by = CASE WHEN v_allocated <= 0.01 THEN NULL ELSE COALESCE(matched_by, auth.uid()) END,\n         manually_unlinked = true\n   WHERE id = p_bank_line_id;\nEND;\n$$","--\n-- Name: refresh_bulk_email_campaign_counts(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"refresh_bulk_email_campaign_counts\\"(\\"p_campaign_id\\" \\"uuid\\") RETURNS TABLE(\\"sent_count\\" integer, \\"failed_count\\" integer, \\"pending_count\\" integer, \\"sending_count\\" integer)\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  RETURN QUERY\n  WITH counts AS (\n    SELECT\n      count(*) FILTER (WHERE status = 'sent')::integer AS sent_count,\n      count(*) FILTER (WHERE status = 'failed')::integer AS failed_count,\n      count(*) FILTER (WHERE status = 'pending')::integer AS pending_count,\n      count(*) FILTER (WHERE status = 'sending')::integer AS sending_count\n    FROM public.bulk_email_recipients\n    WHERE campaign_id = p_campaign_id\n  )\n  UPDATE public.bulk_email_campaigns c\n  SET\n    sent_count = counts.sent_count,\n    failed_count = counts.failed_count\n  FROM counts\n  WHERE c.id = p_campaign_id\n  RETURNING counts.sent_count, counts.failed_count, counts.pending_count, counts.sending_count;\nEND;\n$$","--\n-- Name: refresh_salary_advance_status(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"refresh_salary_advance_status\\"(\\"p_advance_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_amount numeric;\n  v_applied numeric;\nBEGIN\n  SELECT amount INTO v_amount\n  FROM public.payment_vouchers\n  WHERE id = p_advance_id AND payment_purpose = 'salary_advance';\n  IF NOT FOUND THEN RETURN; END IF;\n\n  SELECT COALESCE(sum(applied_amount), 0) INTO v_applied\n  FROM public.salary_advance_applications\n  WHERE advance_payment_voucher_id = p_advance_id;\n\n  UPDATE public.payment_vouchers\n  SET salary_advance_applied_amount = v_applied,\n      salary_advance_status = CASE\n        WHEN v_applied >= v_amount THEN 'settled'\n        WHEN v_applied > 0 THEN 'partially_settled'\n        ELSE 'outstanding'\n      END\n  WHERE id = p_advance_id;\nEND;\n$$","--\n-- Name: reject_purchase_invoice_inward(\\"uuid\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"reject_purchase_invoice_inward\\"(\\"p_purchase_invoice_id\\" \\"uuid\\", \\"p_purchase_invoice_item_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_status text;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','warehouse','manager']) THEN RAISE EXCEPTION 'Permission denied'; END IF;\n  IF p_reason IS NULL OR length(trim(p_reason))=0 THEN RAISE EXCEPTION 'Rejection reason is required'; END IF;\n  SELECT receiving_approval_status INTO v_status FROM public.purchase_invoices WHERE id=p_purchase_invoice_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;\n  IF v_status <> 'approved' THEN RAISE EXCEPTION 'Only approved Purchase Invoices can be rejected at inward'; END IF;\n  IF NOT EXISTS (SELECT 1 FROM public.purchase_invoice_items WHERE id=p_purchase_invoice_item_id AND purchase_invoice_id=p_purchase_invoice_id AND item_type='inventory') THEN\n    RAISE EXCEPTION 'Purchase Invoice item does not belong to this invoice';\n  END IF;\n  INSERT INTO public.purchase_invoice_inward_rejections(purchase_invoice_id,purchase_invoice_item_id,reason,rejected_by) VALUES (p_purchase_invoice_id,p_purchase_invoice_item_id,trim(p_reason),auth.uid());\n  UPDATE public.purchase_invoices SET receiving_approval_status='rejected', receiving_rejection_reason=trim(p_reason), updated_at=now() WHERE id=p_purchase_invoice_id;\n  RETURN jsonb_build_object('success',true,'status','rejected');\nEND; $$","--\n-- Name: release_so_product_reservations_v2(\\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"release_so_product_reservations_v2\\"(\\"p_so_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE r public.so_product_reservations%ROWTYPE;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','manager','warehouse','sales'])\n     AND current_setting('app.canonical_reservation_engine',true) IS DISTINCT FROM 'on' THEN\n    RAISE EXCEPTION 'Permission denied for reservation release';\n  END IF;\n  FOR r IN SELECT * FROM public.so_product_reservations WHERE sales_order_id=p_so_id AND status='active' ORDER BY id FOR UPDATE LOOP\n    UPDATE public.so_product_reservations SET reserved_quantity=0,status='released',closed_at=now(),updated_at=now(),close_reason=p_reason WHERE id=r.id;\n    INSERT INTO public.so_product_reservation_events(reservation_id,sales_order_id,sales_order_item_id,event_type,quantity_delta,quantity_after,reason,actor_id)\n    VALUES(r.id,r.sales_order_id,r.sales_order_item_id,'released',-r.reserved_quantity,0,p_reason,auth.uid());\n  END LOOP;\nEND; $$","--\n-- Name: relink_historical_bank_allocation(\\"uuid\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"relink_historical_bank_allocation\\"(\\"p_allocation_id\\" \\"uuid\\", \\"p_replacement_journal_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_alloc public.bank_statement_allocations%rowtype;\n  v_old public.journal_entries%rowtype;\n  v_new public.journal_entries%rowtype;\n  v_before_amount numeric;\nBEGIN\n  IF current_user NOT IN ('postgres', 'supabase_admin')\n     AND auth.role() <> 'service_role'\n     AND NOT EXISTS (\n       SELECT 1 FROM public.user_profiles\n        WHERE id = auth.uid() AND is_active = true AND role = 'admin'\n     ) THEN\n    RAISE EXCEPTION 'Historical allocation relink requires admin or service_role';\n  END IF;\n\n  SELECT * INTO v_alloc\n    FROM public.bank_statement_allocations\n   WHERE id = p_allocation_id\n   FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Allocation not found'; END IF;\n\n  SELECT * INTO v_old FROM public.journal_entries WHERE id = v_alloc.journal_entry_id FOR UPDATE;\n  SELECT * INTO v_new FROM public.journal_entries WHERE id = p_replacement_journal_id FOR UPDATE;\n  IF v_old.id IS NULL OR NOT v_old.is_reversed THEN\n    RAISE EXCEPTION 'Source journal must be reversed';\n  END IF;\n  IF v_new.id IS NULL OR NOT v_new.is_posted OR v_new.is_reversed THEN\n    RAISE EXCEPTION 'Replacement journal must be posted and not reversed';\n  END IF;\n  IF v_old.reference_id IS DISTINCT FROM v_new.reference_id\n     AND NOT EXISTS (\n       SELECT 1 FROM public.fund_transfers ft_old\n       JOIN public.fund_transfers ft_new ON ft_new.id = ft_old.id\n       WHERE ft_old.journal_entry_id = v_old.id AND ft_new.journal_entry_id = v_new.id\n     ) THEN\n    RAISE EXCEPTION 'Journals do not belong to the same underlying transaction';\n  END IF;\n  IF v_alloc.journal_entry_id = v_new.id THEN\n    RETURN jsonb_build_object('idempotent', true, 'allocation_id', v_alloc.id,\n      'journal_entry_id', v_new.id, 'allocation_amount', v_alloc.allocation_amount);\n  END IF;\n\n  v_before_amount := v_alloc.allocation_amount;\n  PERFORM set_config('app.historical_allocation_relink', 'on', true);\n  UPDATE public.bank_statement_allocations\n     SET journal_entry_id = v_new.id\n   WHERE id = v_alloc.id;\n\n  IF (SELECT allocation_amount FROM public.bank_statement_allocations WHERE id = v_alloc.id) <> v_before_amount THEN\n    RAISE EXCEPTION 'Allocation amount changed';\n  END IF;\n\n  RETURN jsonb_build_object('idempotent', false, 'allocation_id', v_alloc.id,\n    'old_journal_entry_id', v_old.id, 'new_journal_entry_id', v_new.id,\n    'allocation_amount', v_before_amount);\nEND;\n$$","--\n-- Name: reopen_tax_period(\\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"reopen_tax_period\\"(\\"p_period_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF p_reason IS NULL OR btrim(p_reason) = '' THEN\n    RAISE EXCEPTION 'Reopen reason is required';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM user_profiles\n                 WHERE id = auth.uid() AND role = 'admin' AND is_active = true) THEN\n    RAISE EXCEPTION 'Only admins may reopen a closed tax period';\n  END IF;\n\n  UPDATE tax_periods SET\n    status         = 'reopened',\n    reopen_reason  = p_reason,\n    reopened_at    = now(),\n    reopened_by    = auth.uid(),\n    updated_at     = now()\n  WHERE id = p_period_id AND status = 'closed';\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Period % is not in closed state', p_period_id;\n  END IF;\n\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)\n  VALUES (auth.uid(), 'tax_periods', 'update', p_period_id,\n          jsonb_build_object('action','reopen','reason',p_reason));\nEND $$","--\n-- Name: repair_all_posted_fund_transfers(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"repair_all_posted_fund_transfers\\"() RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  t record;\n  eligibility text;\n  result jsonb;\n  scanned integer := 0;\n  repaired integer := 0;\n  skipped integer := 0;\n  skipped_details jsonb := '[]'::jsonb;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  FOR t IN SELECT id, transfer_number FROM public.fund_transfers WHERE status='posted' ORDER BY transfer_date, transfer_number LOOP\n    scanned := scanned + 1;\n    eligibility := public.audit_fund_transfer_repair_eligibility(t.id);\n    IF eligibility IS NOT NULL THEN\n      skipped := skipped + 1;\n      skipped_details := skipped_details || jsonb_build_array(jsonb_build_object(\n        'fund_transfer_id', t.id, 'transfer_number', t.transfer_number, 'reason', eligibility));\n      CONTINUE;\n    END IF;\n    SELECT public.repair_posted_fund_transfer_from_source(t.id) INTO result;\n    IF COALESCE((result->>'repaired')::boolean, false) THEN\n      repaired := repaired + 1;\n      IF NOT EXISTS (\n        SELECT 1 FROM public.audit_logs a\n        WHERE a.table_name='fund_transfers' AND a.record_id=t.id\n          AND a.new_values->>'validation_rerun'='true'\n      ) THEN\n        INSERT INTO public.audit_logs(table_name, action_type, record_id, old_values, new_values, changed_fields)\n        VALUES ('fund_transfers', 'update', t.id,\n          jsonb_build_object('event','batch_repair','transfer_number',t.transfer_number),\n          jsonb_build_object('event','batch_repair','repair_result',result,'validation_rerun',true),\n          COALESCE(ARRAY(SELECT jsonb_array_elements_text(result->'repaired_fields')), ARRAY[]::text[]));\n      END IF;\n    ELSE\n      skipped := skipped + 1;\n      skipped_details := skipped_details || jsonb_build_array(jsonb_build_object(\n        'fund_transfer_id', t.id, 'transfer_number', t.transfer_number,\n        'reason', COALESCE(result->>'reason', 'Repair did not pass validation')));\n    END IF;\n  END LOOP;\n  RETURN jsonb_build_object('total_scanned', scanned, 'automatically_repaired', repaired,\n    'skipped', skipped, 'skipped_details', skipped_details);\nEND;\n$$","--\n-- Name: repair_historical_usd_idr_transfer_fx(\\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"repair_historical_usd_idr_transfer_fx\\"(\\"p_cutoff\\" \\"date\\" DEFAULT '2026-08-01'::\\"date\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE r record; l record; v_reversal uuid; v_corrected uuid; v_entry text; v_line int; v_run uuid; v_repaired int:=0; v_skipped int:=0; v_exception int:=0; BEGIN\n  PERFORM set_config('app.finance_historical_repair','on',true);\n  PERFORM set_config('app.finance_historical_repair_relink','on',true);\n  INSERT INTO public.finance_historical_repair_runs(notes) VALUES ('Controlled historical USD→IDR fund-transfer FX correction before cutoff '||p_cutoff::text) RETURNING id INTO v_run;\n  FOR r IN\n    SELECT ft.id, ft.transfer_number, ft.transfer_date, ft.from_amount, ft.to_amount, ft.exchange_rate, ft.journal_entry_id,\n           je.entry_number, je.total_debit, je.total_credit,\n           fba.coa_id from_coa, fba.currency from_currency, tba.coa_id to_coa, tba.currency to_currency,\n           fs.id from_stmt, ts.id to_stmt, fs.debit_amount from_debit, fs.credit_amount from_credit, fs.currency from_stmt_currency,\n           ts.debit_amount to_debit, ts.credit_amount to_credit, ts.currency to_stmt_currency\n    FROM public.fund_transfers ft\n    JOIN public.bank_accounts fba ON fba.id=ft.from_bank_account_id\n    JOIN public.bank_accounts tba ON tba.id=ft.to_bank_account_id\n    JOIN public.journal_entries je ON je.id=ft.journal_entry_id\n    JOIN public.bank_statement_lines fs ON fs.id=ft.from_bank_statement_line_id\n    JOIN public.bank_statement_lines ts ON ts.id=ft.to_bank_statement_line_id\n    WHERE ft.status='posted' AND ft.transfer_date < p_cutoff AND fba.currency='USD' AND tba.currency='IDR'\n      AND fs.currency='USD' AND ts.currency='IDR'\n      AND abs(fs.debit_amount-ft.from_amount)<0.01 AND abs(fs.credit_amount)<0.01\n      AND abs(ts.credit_amount-ft.to_amount)<0.01 AND abs(ts.debit_amount)<0.01\n      AND NOT COALESCE(je.is_reversed,false)\n    ORDER BY ft.transfer_date, ft.transfer_number\n    FOR UPDATE OF ft,je,fs,ts\n  LOOP\n    IF abs(r.total_debit-r.to_amount)<0.01 AND abs(r.total_credit-r.to_amount)<0.01 THEN v_skipped:=v_skipped+1; CONTINUE; END IF;\n    IF NOT (abs(r.total_debit-r.from_amount)<0.01 AND abs(r.total_credit-r.from_amount)<0.01) THEN\n      v_exception:=v_exception+1;\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal_amounts'],'Journal amount does not match either the USD source amount or evidenced IDR destination amount','Accountant review of the original journal and bank evidence');\n      CONTINUE;\n    END IF;\n    v_entry:=public.generate_journal_entry_number();\n    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n    VALUES(v_entry,r.transfer_date,'historical_repair',r.id,'HR-REV-'||r.transfer_number,'Reversal of legacy USD-source functional posting '||r.entry_number,r.total_credit,r.total_debit,true,now(),'IDR','IDR',r.exchange_rate,true)\n    RETURNING id INTO v_reversal;\n    v_line:=1;\n    FOR l IN SELECT jl.* FROM public.journal_entry_lines jl WHERE jl.journal_entry_id=r.journal_entry_id ORDER BY jl.line_number LOOP\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n      VALUES(v_reversal,v_line,l.account_id,l.credit,l.debit,'Historical FX reversal: '||COALESCE(l.description,''),l.supplier_id,l.transaction_currency,l.transaction_credit,l.transaction_debit,l.functional_currency,l.exchange_rate);\n      v_line:=v_line+1;\n    END LOOP;\n    UPDATE public.journal_entries SET is_reversed=true,reversed_by_id=v_reversal WHERE id=r.journal_entry_id;\n    v_entry:=public.generate_journal_entry_number();\n    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n    VALUES(v_entry,r.transfer_date,'historical_repair',r.id,'HR-FX-'||r.transfer_number,'Corrected USD→IDR fund transfer '||r.transfer_number,r.to_amount,r.to_amount,true,now(),'IDR','IDR',r.exchange_rate,true)\n    RETURNING id INTO v_corrected;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n    VALUES(v_corrected,1,r.to_coa,r.to_amount,0,'Corrected transfer into IDR bank','IDR',r.to_amount,0,'IDR',1);\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n    VALUES(v_corrected,2,r.from_coa,0,r.to_amount,'Corrected transfer out of USD bank','USD',0,r.from_amount,'IDR',r.exchange_rate);\n    UPDATE public.fund_transfers SET journal_entry_id=v_corrected WHERE id=r.id;\n    UPDATE public.bank_statement_lines SET matched_entry_id=v_corrected, reconciliation_status='matched' WHERE id IN(r.from_stmt,r.to_stmt);\n    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n    VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal_entry','bank matched_entry_id'],jsonb_build_object('journal_entry_id',r.journal_entry_id,'entry_number',r.entry_number,'total',r.total_debit),jsonb_build_object('reversal_journal_id',v_reversal,'replacement_journal_id',v_corrected,'replacement_entry_number',v_entry,'functional_idr',r.to_amount,'transaction_usd',r.from_amount,'rate',r.exchange_rate),'Both bank statement sides prove the USD source amount, IDR destination amount, and historical FX rate');\n    v_repaired:=v_repaired+1;\n  END LOOP;\n  UPDATE public.finance_historical_repair_runs SET completed_at=now(),total_records_scanned=v_repaired+v_skipped+v_exception,records_repaired=v_repaired,records_manual_review=v_exception,records_skipped=v_skipped WHERE id=v_run;\n  RETURN jsonb_build_object('run_id',v_run,'repaired',v_repaired,'skipped_already_correct',v_skipped,'manual_review',v_exception,'cutoff',p_cutoff);\nEND $$","--\n-- Name: repair_posted_fund_transfer_from_source(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"repair_posted_fund_transfer_from_source\\"(\\"p_fund_transfer_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_transfer public.fund_transfers%ROWTYPE;\n  v_journal public.journal_entries%ROWTYPE;\n  v_from_coa uuid;\n  v_to_coa uuid;\n  v_from_currency text;\n  v_to_currency text;\n  v_journal_currency text;\n  v_expected_rate numeric;\n  v_before_lines jsonb;\n  v_after_lines jsonb;\n  v_repaired_fields text[] := ARRAY[]::text[];\n  v_possible_bank_transactions integer;\n  v_validation_failures integer;\n  v_live_validation_failures integer;\n  v_validation_passed boolean;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  PERFORM set_config('app.finance_historical_repair', 'on', true);\n  PERFORM set_config('app.finance_metadata_repair', 'on', true);\n\n  SELECT * INTO v_transfer\n  FROM public.fund_transfers\n  WHERE id = p_fund_transfer_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Fund Transfer not found';\n  END IF;\n  IF v_transfer.status <> 'posted' OR v_transfer.journal_entry_id IS NULL THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer is not posted with an existing journal');\n  END IF;\n\n  SELECT * INTO v_journal\n  FROM public.journal_entries\n  WHERE id = v_transfer.journal_entry_id\n  FOR UPDATE;\n\n  IF NOT FOUND OR NOT COALESCE(v_journal.is_posted, false) OR COALESCE(v_journal.is_reversed, false) THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer journal is not an active posted journal');\n  END IF;\n  IF v_journal.source_module NOT IN ('fund_transfer', 'fund_transfers')\n     OR v_journal.reference_id IS DISTINCT FROM v_transfer.id THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer and journal do not prove an authoritative relationship');\n  END IF;\n\n  IF v_transfer.from_account_type = 'bank' THEN\n    SELECT coa_id, upper(currency) INTO v_from_coa, v_from_currency\n    FROM public.bank_accounts WHERE id = v_transfer.from_bank_account_id AND is_active;\n  ELSIF v_transfer.from_account_type = 'petty_cash' THEN\n    SELECT id, 'IDR' INTO v_from_coa, v_from_currency FROM public.chart_of_accounts WHERE code = '1102' AND is_active LIMIT 1;\n  ELSIF v_transfer.from_account_type = 'cash_on_hand' THEN\n    SELECT id, 'IDR' INTO v_from_coa, v_from_currency FROM public.chart_of_accounts WHERE code = '1101' AND is_active LIMIT 1;\n  END IF;\n\n  IF v_transfer.to_account_type = 'bank' THEN\n    SELECT coa_id, upper(currency) INTO v_to_coa, v_to_currency\n    FROM public.bank_accounts WHERE id = v_transfer.to_bank_account_id AND is_active;\n  ELSIF v_transfer.to_account_type = 'petty_cash' THEN\n    SELECT id, 'IDR' INTO v_to_coa, v_to_currency FROM public.chart_of_accounts WHERE code = '1102' AND is_active LIMIT 1;\n  ELSIF v_transfer.to_account_type = 'cash_on_hand' THEN\n    SELECT id, 'IDR' INTO v_to_coa, v_to_currency FROM public.chart_of_accounts WHERE code = '1101' AND is_active LIMIT 1;\n  END IF;\n\n  IF v_from_coa IS NULL OR v_to_coa IS NULL OR v_from_currency IS NULL OR v_to_currency IS NULL THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer source does not contain complete active account and currency information');\n  END IF;\n  IF v_transfer.from_amount IS NULL OR v_transfer.to_amount IS NULL OR v_transfer.exchange_rate IS NULL THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer source is missing an amount or exchange rate');\n  END IF;\n\n  v_expected_rate := CASE\n    WHEN v_from_currency = v_to_currency THEN 1\n    WHEN v_from_currency = 'IDR' AND v_transfer.to_amount > 0 THEN v_transfer.from_amount / v_transfer.to_amount\n    WHEN v_to_currency = 'IDR' AND v_transfer.from_amount > 0 THEN v_transfer.to_amount / v_transfer.from_amount\n  END;\n  IF v_expected_rate IS NULL OR abs(v_transfer.exchange_rate - v_expected_rate) > 0.000001 THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer exchange rate is not internally consistent with its stored amounts');\n  END IF;\n  IF (SELECT count(*) FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id) <> 2\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id AND line_number = 1 AND COALESCE(debit, 0) > 0 AND COALESCE(credit, 0) = 0)\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id AND line_number = 2 AND COALESCE(credit, 0) > 0 AND COALESCE(debit, 0) = 0) THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Existing journal lines are not a safe two-line transfer journal');\n  END IF;\n  IF abs(COALESCE(v_journal.total_debit, 0) - COALESCE(v_transfer.from_amount, 0)) > 0.01\n     OR abs(COALESCE(v_journal.total_credit, 0) - COALESCE(v_transfer.from_amount, 0)) > 0.01\n     OR EXISTS (\n       SELECT 1 FROM public.journal_entry_lines l\n       WHERE l.journal_entry_id = v_journal.id\n         AND ((l.line_number = 1 AND abs(COALESCE(l.debit, 0) - v_transfer.from_amount) > 0.01)\n           OR (l.line_number = 2 AND abs(COALESCE(l.credit, 0) - v_transfer.from_amount) > 0.01))\n     ) THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Existing posted journal amounts do not match the Fund Transfer source');\n  END IF;\n\n  -- No bank transaction is inferred or relinked. If the source document does\n  -- not name a line, explicitly refuse to guess, especially when candidates\n  -- are ambiguous. The accountant can resolve the missing source information.\n  IF v_transfer.from_bank_statement_line_id IS NULL AND v_transfer.from_account_type = 'bank' THEN\n    SELECT count(*) INTO v_possible_bank_transactions\n    FROM public.bank_statement_lines b\n    WHERE b.bank_account_id = v_transfer.from_bank_account_id\n      AND abs(b.transaction_date - v_transfer.transfer_date) <= 8\n      AND (COALESCE(b.debit_amount, 0) = v_transfer.from_amount OR COALESCE(b.credit_amount, 0) = v_transfer.from_amount);\n    IF v_possible_bank_transactions > 1 THEN\n      RETURN jsonb_build_object('repaired', false, 'reason', 'Multiple possible From Bank transactions exist; no bank link was guessed');\n    END IF;\n  END IF;\n  IF v_transfer.to_bank_statement_line_id IS NULL AND v_transfer.to_account_type = 'bank' THEN\n    SELECT count(*) INTO v_possible_bank_transactions\n    FROM public.bank_statement_lines b\n    WHERE b.bank_account_id = v_transfer.to_bank_account_id\n      AND abs(b.transaction_date - v_transfer.transfer_date) <= 8\n      AND (COALESCE(b.debit_amount, 0) = v_transfer.to_amount OR COALESCE(b.credit_amount, 0) = v_transfer.to_amount);\n    IF v_possible_bank_transactions > 1 THEN\n      RETURN jsonb_build_object('repaired', false, 'reason', 'Multiple possible To Bank transactions exist; no bank link was guessed');\n    END IF;\n  END IF;\n\n  SELECT jsonb_agg(jsonb_build_object('id', id, 'debit', debit, 'credit', credit) ORDER BY id)\n  INTO v_before_lines FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id;\n\n  v_journal_currency := CASE WHEN v_from_currency = v_to_currency THEN v_from_currency ELSE 'IDR' END;\n  UPDATE public.journal_entries\n  SET source_module = 'fund_transfers', reference_id = v_transfer.id,\n      reference_number = v_transfer.transfer_number, transaction_currency = v_journal_currency,\n      functional_currency = 'IDR', exchange_rate = v_transfer.exchange_rate,\n      amounts_are_functional = true\n  WHERE id = v_journal.id\n    AND (source_module IS DISTINCT FROM 'fund_transfers' OR reference_id IS DISTINCT FROM v_transfer.id\n      OR reference_number IS DISTINCT FROM v_transfer.transfer_number OR transaction_currency IS DISTINCT FROM v_journal_currency\n      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM v_transfer.exchange_rate\n      OR amounts_are_functional IS DISTINCT FROM true);\n  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_metadata'); END IF;\n\n  UPDATE public.journal_entry_lines\n  SET account_id = v_to_coa, transaction_currency = v_to_currency,\n      functional_currency = 'IDR', exchange_rate = CASE WHEN v_to_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END\n  WHERE journal_entry_id = v_journal.id AND line_number = 1\n    AND (account_id IS DISTINCT FROM v_to_coa OR transaction_currency IS DISTINCT FROM v_to_currency\n      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM CASE WHEN v_to_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END);\n  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_debit_line_metadata'); END IF;\n\n  UPDATE public.journal_entry_lines\n  SET account_id = v_from_coa, transaction_currency = v_from_currency,\n      functional_currency = 'IDR', exchange_rate = CASE WHEN v_from_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END\n  WHERE journal_entry_id = v_journal.id AND line_number = 2\n    AND (account_id IS DISTINCT FROM v_from_coa OR transaction_currency IS DISTINCT FROM v_from_currency\n      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM CASE WHEN v_from_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END);\n  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_credit_line_metadata'); END IF;\n\n  SELECT jsonb_agg(jsonb_build_object('id', id, 'debit', debit, 'credit', credit) ORDER BY id)\n  INTO v_after_lines FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id;\n  IF v_before_lines IS DISTINCT FROM v_after_lines THEN\n    RAISE EXCEPTION 'Fund Transfer repair cancelled because a debit or credit value changed';\n  END IF;\n\n  -- The existing validation projections are live views. Read them after the\n  -- metadata updates; resolve the false-positive only when they are clean.\n  SELECT count(*) INTO v_validation_failures\n  FROM public.finance_historical_repair_verification_failures f\n  WHERE f.document_type = 'fund_transfer' AND f.database_id = v_transfer.id;\n  SELECT count(*) INTO v_live_validation_failures\n  FROM public.finance_live_verification_failures f\n  WHERE f.document_type = 'fund_transfer' AND f.document_id = v_transfer.id;\n  v_validation_failures := v_validation_failures + v_live_validation_failures;\n  v_validation_passed := v_validation_failures = 0;\n  IF v_validation_passed THEN\n    UPDATE public.finance_historical_repair_exceptions\n    SET status = 'resolved'\n    WHERE status = 'manual_review' AND document_type = 'fund_transfer' AND document_id = v_transfer.id;\n  END IF;\n\n  -- A no-op retry produces no second audit mutation. The first successful\n  -- call records the exact derived fields changed and immutable line values.\n  IF COALESCE(array_length(v_repaired_fields, 1), 0) > 0 THEN\n    INSERT INTO public.audit_logs(table_name, action_type, record_id, old_values, new_values, changed_fields)\n    VALUES ('fund_transfers', 'update', v_transfer.id,\n      jsonb_build_object('journal_entry_id', v_journal.id, 'journal_lines', v_before_lines),\n      jsonb_build_object('journal_entry_id', v_journal.id, 'journal_lines', v_after_lines,\n        'validation_rerun', true, 'validation_passed', v_validation_passed),\n      v_repaired_fields);\n  END IF;\n\n  IF NOT v_validation_passed THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Derived data still fails the existing Finance validation', 'validation_failures', v_validation_failures);\n  END IF;\n\n  RETURN jsonb_build_object('repaired', true, 'repaired_fields', v_repaired_fields,\n    'validation_rerun', true, 'journal_entry_id', v_journal.id);\nEND;\n$$","--\n-- Name: reset_bank_statement_on_expense_delete(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"reset_bank_statement_on_expense_delete\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- When matched_expense_id is set to NULL, reset the reconciliation status\nIF OLD.matched_expense_id IS NOT NULL AND NEW.matched_expense_id IS NULL THEN\nNEW.reconciliation_status := 'unmatched';\nNEW.matched_at := NULL;\nNEW.matched_by := NULL;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: reset_receiving_approval_on_invoice_change(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"reset_receiving_approval_on_invoice_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nBEGIN\n  IF OLD.receiving_approval_status = 'approved' AND (\n    NEW.supplier_id IS DISTINCT FROM OLD.supplier_id OR\n    NEW.invoice_date IS DISTINCT FROM OLD.invoice_date OR\n    NEW.total_amount IS DISTINCT FROM OLD.total_amount OR\n    NEW.currency IS DISTINCT FROM OLD.currency OR\n    NEW.document_urls IS DISTINCT FROM OLD.document_urls OR\n    NEW.notes IS DISTINCT FROM OLD.notes\n  ) THEN\n    NEW.receiving_approval_status := 'pending_approval';\n    NEW.receiving_rejection_reason := NULL;\n  END IF;\n  RETURN NEW;\nEND; $$","--\n-- Name: reset_receiving_approval_on_item_change(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"reset_receiving_approval_on_item_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nDECLARE v_invoice_id uuid := COALESCE(NEW.purchase_invoice_id, OLD.purchase_invoice_id);\nBEGIN\n  UPDATE public.purchase_invoices\n     SET receiving_approval_status='pending_approval', receiving_rejection_reason=NULL, updated_at=now()\n   WHERE id=v_invoice_id AND receiving_approval_status='approved';\n  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;\n  RETURN NEW;\nEND; $$","--\n-- Name: resolve_bank_allocation_document(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"resolve_bank_allocation_document\\"(\\"p_journal_entry_id\\" \\"uuid\\") RETURNS TABLE(\\"document_type\\" \\"text\\", \\"document_id\\" \\"uuid\\")\n    LANGUAGE \\"plpgsql\\" STABLE SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_module text;\n  v_reference uuid;\nBEGIN\n  SELECT lower(COALESCE(source_module,'')), reference_id\n    INTO v_module, v_reference\n    FROM public.journal_entries\n   WHERE id = p_journal_entry_id;\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  IF v_module IN ('payment','payments','payment_voucher')\n     AND v_reference IS NOT NULL\n     AND EXISTS (SELECT 1 FROM public.payment_vouchers WHERE id=v_reference) THEN\n    document_type := 'payment'; document_id := v_reference; RETURN NEXT; RETURN;\n  ELSIF v_module IN ('receipt','receipts','receipt_voucher')\n     AND v_reference IS NOT NULL\n     AND EXISTS (SELECT 1 FROM public.receipt_vouchers WHERE id=v_reference) THEN\n    document_type := 'receipt'; document_id := v_reference; RETURN NEXT; RETURN;\n  ELSIF v_module IN ('expense','expenses','expense_payment')\n     AND v_reference IS NOT NULL\n     AND EXISTS (SELECT 1 FROM public.finance_expenses WHERE id=v_reference) THEN\n    document_type := 'expense'; document_id := v_reference; RETURN NEXT; RETURN;\n  ELSIF v_module IN ('fund_transfer','fund_transfers')\n     AND v_reference IS NOT NULL\n     AND EXISTS (SELECT 1 FROM public.fund_transfers WHERE id=v_reference) THEN\n    document_type := 'fund_transfer'; document_id := v_reference; RETURN NEXT; RETURN;\n  ELSIF v_module IN ('tax_payment','tax_payments')\n     AND v_reference IS NOT NULL\n     AND EXISTS (SELECT 1 FROM public.tax_payments WHERE id=v_reference) THEN\n    document_type := 'tax_payment'; document_id := v_reference; RETURN NEXT; RETURN;\n  ELSIF v_module IN ('petty_cash','petty_cash_transaction')\n     AND v_reference IS NOT NULL\n     AND EXISTS (SELECT 1 FROM public.petty_cash_transactions WHERE id=v_reference) THEN\n    document_type := 'petty_cash'; document_id := v_reference; RETURN NEXT; RETURN;\n  ELSIF v_module = 'historical_repair' AND v_reference IS NOT NULL THEN\n    IF EXISTS (SELECT 1 FROM public.finance_expenses WHERE id=v_reference) THEN\n      document_type := 'expense'; document_id := v_reference; RETURN NEXT; RETURN;\n    ELSIF EXISTS (SELECT 1 FROM public.payment_vouchers WHERE id=v_reference) THEN\n      document_type := 'payment'; document_id := v_reference; RETURN NEXT; RETURN;\n    ELSIF EXISTS (SELECT 1 FROM public.receipt_vouchers WHERE id=v_reference) THEN\n      document_type := 'receipt'; document_id := v_reference; RETURN NEXT; RETURN;\n    ELSIF EXISTS (SELECT 1 FROM public.fund_transfers WHERE id=v_reference) THEN\n      document_type := 'fund_transfer'; document_id := v_reference; RETURN NEXT; RETURN;\n    ELSIF EXISTS (SELECT 1 FROM public.tax_payments WHERE id=v_reference) THEN\n      document_type := 'tax_payment'; document_id := v_reference; RETURN NEXT; RETURN;\n    ELSIF EXISTS (SELECT 1 FROM public.petty_cash_transactions WHERE id=v_reference) THEN\n      document_type := 'petty_cash'; document_id := v_reference; RETURN NEXT; RETURN;\n    END IF;\n  END IF;\n\n  document_type := 'journal';\n  document_id := p_journal_entry_id;\n  RETURN NEXT;\nEND;\n$$","--\n-- Name: effective_expense_posting_state; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"effective_expense_posting_state\\" WITH (\\"security_invoker\\"='true') AS\n WITH \\"original_journals\\" AS (\n         SELECT \\"fe\\".\\"id\\" AS \\"expense_id\\",\n            \\"je\\".\\"id\\",\n            \\"je\\".\\"entry_number\\",\n            \\"je\\".\\"entry_date\\",\n            \\"je\\".\\"created_at\\",\n            \\"je\\".\\"is_reversed\\",\n            \\"je\\".\\"reversed_by_id\\"\n           FROM (\\"public\\".\\"finance_expenses\\" \\"fe\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON (((\\"je\\".\\"is_posted\\" = true) AND ((\\"je\\".\\"source_module\\")::\\"text\\" = ANY ((ARRAY['expense'::character varying, 'expenses'::character varying])::\\"text\\"[])) AND ((\\"je\\".\\"reference_id\\" = \\"fe\\".\\"id\\") OR ((\\"je\\".\\"reference_id\\" IS NULL) AND ((\\"je\\".\\"reference_number\\")::\\"text\\" = ('EXP-'::\\"text\\" || (\\"fe\\".\\"id\\")::\\"text\\")))))))\n        ), \\"explicit_replacement_ids\\" AS (\n         SELECT \\"expense_explicit_replacement_journals\\".\\"expense_id\\",\n            \\"expense_explicit_replacement_journals\\".\\"journal_id\\"\n           FROM \\"public\\".\\"expense_explicit_replacement_journals\\"() \\"expense_explicit_replacement_journals\\"(\\"expense_id\\", \\"journal_id\\")\n        ), \\"replacement_candidates\\" AS (\n         SELECT \\"eri\\".\\"expense_id\\",\n            \\"je\\".\\"id\\",\n            \\"je\\".\\"entry_number\\",\n            \\"je\\".\\"entry_date\\",\n            \\"je\\".\\"reference_number\\",\n            \\"je\\".\\"source_module\\",\n            \\"je\\".\\"created_at\\"\n           FROM (\\"explicit_replacement_ids\\" \\"eri\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((\\"je\\".\\"id\\" = \\"eri\\".\\"journal_id\\")))\n          WHERE ((\\"je\\".\\"is_posted\\" = true) AND (NOT COALESCE(\\"je\\".\\"is_reversed\\", false)))\n        UNION\n         SELECT \\"fe\\".\\"id\\",\n            \\"je\\".\\"id\\",\n            \\"je\\".\\"entry_number\\",\n            \\"je\\".\\"entry_date\\",\n            \\"je\\".\\"reference_number\\",\n            \\"je\\".\\"source_module\\",\n            \\"je\\".\\"created_at\\"\n           FROM (\\"public\\".\\"finance_expenses\\" \\"fe\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON (((\\"je\\".\\"reference_id\\" = \\"fe\\".\\"id\\") AND (\\"je\\".\\"is_posted\\" = true) AND (NOT COALESCE(\\"je\\".\\"is_reversed\\", false)) AND (((\\"je\\".\\"source_module\\")::\\"text\\" = 'historical_salary_advance_repair'::\\"text\\") OR (((\\"je\\".\\"source_module\\")::\\"text\\" = 'historical_repair'::\\"text\\") AND ((\\"je\\".\\"reference_number\\")::\\"text\\" ~~ 'HR-AP-%'::\\"text\\"))))))\n        ), \\"original_rollup\\" AS (\n         SELECT \\"original_journals\\".\\"expense_id\\",\n            (\\"count\\"(*) FILTER (WHERE (NOT COALESCE(\\"original_journals\\".\\"is_reversed\\", false))))::integer AS \\"active_original_count\\",\n            (\\"count\\"(*) FILTER (WHERE COALESCE(\\"original_journals\\".\\"is_reversed\\", false)))::integer AS \\"reversed_original_count\\",\n            (\\"array_agg\\"(\\"original_journals\\".\\"id\\" ORDER BY \\"original_journals\\".\\"created_at\\" DESC, \\"original_journals\\".\\"id\\" DESC) FILTER (WHERE (NOT COALESCE(\\"original_journals\\".\\"is_reversed\\", false))))[1] AS \\"active_journal_id\\",\n            (\\"array_agg\\"(\\"original_journals\\".\\"entry_number\\" ORDER BY \\"original_journals\\".\\"created_at\\" DESC, \\"original_journals\\".\\"id\\" DESC) FILTER (WHERE (NOT COALESCE(\\"original_journals\\".\\"is_reversed\\", false))))[1] AS \\"active_journal_number\\",\n            (\\"array_agg\\"(\\"original_journals\\".\\"entry_date\\" ORDER BY \\"original_journals\\".\\"created_at\\" DESC, \\"original_journals\\".\\"id\\" DESC) FILTER (WHERE (NOT COALESCE(\\"original_journals\\".\\"is_reversed\\", false))))[1] AS \\"active_journal_date\\",\n            (\\"array_agg\\"(\\"original_journals\\".\\"id\\" ORDER BY \\"original_journals\\".\\"created_at\\" DESC, \\"original_journals\\".\\"id\\" DESC) FILTER (WHERE COALESCE(\\"original_journals\\".\\"is_reversed\\", false)))[1] AS \\"original_journal_id\\",\n            (\\"array_agg\\"(\\"original_journals\\".\\"entry_number\\" ORDER BY \\"original_journals\\".\\"created_at\\" DESC, \\"original_journals\\".\\"id\\" DESC) FILTER (WHERE COALESCE(\\"original_journals\\".\\"is_reversed\\", false)))[1] AS \\"original_journal_number\\",\n            (\\"array_agg\\"(\\"original_journals\\".\\"reversed_by_id\\" ORDER BY \\"original_journals\\".\\"created_at\\" DESC, \\"original_journals\\".\\"id\\" DESC) FILTER (WHERE (COALESCE(\\"original_journals\\".\\"is_reversed\\", false) AND (\\"original_journals\\".\\"reversed_by_id\\" IS NOT NULL))))[1] AS \\"reversal_journal_id\\"\n           FROM \\"original_journals\\"\n          GROUP BY \\"original_journals\\".\\"expense_id\\"\n        ), \\"replacement_rollup\\" AS (\n         SELECT \\"replacement_candidates\\".\\"expense_id\\",\n            (\\"count\\"(*))::integer AS \\"active_replacement_count\\",\n            (\\"array_agg\\"(\\"replacement_candidates\\".\\"id\\" ORDER BY \\"replacement_candidates\\".\\"created_at\\" DESC, \\"replacement_candidates\\".\\"id\\" DESC))[1] AS \\"replacement_journal_id\\",\n            (\\"array_agg\\"(\\"replacement_candidates\\".\\"entry_number\\" ORDER BY \\"replacement_candidates\\".\\"created_at\\" DESC, \\"replacement_candidates\\".\\"id\\" DESC))[1] AS \\"replacement_journal_number\\",\n            (\\"array_agg\\"(\\"replacement_candidates\\".\\"entry_date\\" ORDER BY \\"replacement_candidates\\".\\"created_at\\" DESC, \\"replacement_candidates\\".\\"id\\" DESC))[1] AS \\"replacement_journal_date\\",\n            (\\"array_agg\\"(\\"replacement_candidates\\".\\"reference_number\\" ORDER BY \\"replacement_candidates\\".\\"created_at\\" DESC, \\"replacement_candidates\\".\\"id\\" DESC))[1] AS \\"replacement_reference\\",\n            (\\"array_agg\\"(\\"replacement_candidates\\".\\"source_module\\" ORDER BY \\"replacement_candidates\\".\\"created_at\\" DESC, \\"replacement_candidates\\".\\"id\\" DESC))[1] AS \\"replacement_source_module\\"\n           FROM \\"replacement_candidates\\"\n          GROUP BY \\"replacement_candidates\\".\\"expense_id\\"\n        ), \\"resolved\\" AS (\n         SELECT \\"fe\\".\\"id\\" AS \\"expense_id\\",\n            \\"fe\\".\\"voucher_number\\",\n            \\"fe\\".\\"approval_status\\" AS \\"document_approval_status\\",\n            COALESCE(\\"o\\".\\"active_original_count\\", 0) AS \\"active_original_count\\",\n            COALESCE(\\"o\\".\\"reversed_original_count\\", 0) AS \\"reversed_original_count\\",\n            COALESCE(\\"r\\".\\"active_replacement_count\\", 0) AS \\"active_replacement_count\\",\n            \\"o\\".\\"active_journal_id\\",\n            \\"o\\".\\"active_journal_number\\",\n            \\"o\\".\\"active_journal_date\\",\n            \\"o\\".\\"original_journal_id\\",\n            \\"o\\".\\"original_journal_number\\",\n            \\"o\\".\\"reversal_journal_id\\",\n            \\"r\\".\\"replacement_journal_id\\",\n            \\"r\\".\\"replacement_journal_number\\",\n            \\"r\\".\\"replacement_journal_date\\",\n            \\"r\\".\\"replacement_reference\\",\n            \\"r\\".\\"replacement_source_module\\"\n           FROM ((\\"public\\".\\"finance_expenses\\" \\"fe\\"\n             LEFT JOIN \\"original_rollup\\" \\"o\\" ON ((\\"o\\".\\"expense_id\\" = \\"fe\\".\\"id\\")))\n             LEFT JOIN \\"replacement_rollup\\" \\"r\\" ON ((\\"r\\".\\"expense_id\\" = \\"fe\\".\\"id\\")))\n        )\n SELECT \\"expense_id\\",\n    \\"voucher_number\\",\n    \\"document_approval_status\\",\n    \\"active_original_count\\",\n    \\"reversed_original_count\\",\n    \\"active_replacement_count\\",\n    \\"active_journal_id\\",\n    \\"active_journal_number\\",\n    \\"active_journal_date\\",\n    \\"original_journal_id\\",\n    \\"original_journal_number\\",\n    \\"reversal_journal_id\\",\n    \\"replacement_journal_id\\",\n    \\"replacement_journal_number\\",\n    \\"replacement_journal_date\\",\n    \\"replacement_reference\\",\n    \\"replacement_source_module\\",\n        CASE\n            WHEN (\\"active_original_count\\" > 1) THEN 'AMBIGUOUS'::\\"text\\"\n            WHEN (\\"active_replacement_count\\" > 1) THEN 'AMBIGUOUS'::\\"text\\"\n            WHEN ((\\"active_original_count\\" > 0) AND (\\"active_replacement_count\\" > 0)) THEN 'AMBIGUOUS'::\\"text\\"\n            WHEN ((\\"document_approval_status\\" <> 'approved'::\\"text\\") AND ((\\"active_original_count\\" > 0) OR (\\"active_replacement_count\\" > 0))) THEN 'AMBIGUOUS'::\\"text\\"\n            WHEN (\\"active_original_count\\" = 1) THEN 'ACTIVE'::\\"text\\"\n            WHEN ((\\"reversed_original_count\\" > 0) AND (\\"active_replacement_count\\" = 1)) THEN 'REPLACED'::\\"text\\"\n            WHEN ((\\"reversed_original_count\\" > 0) AND (\\"active_replacement_count\\" = 0)) THEN 'REVERSED'::\\"text\\"\n            WHEN (\\"document_approval_status\\" = 'rejected'::\\"text\\") THEN 'REJECTED'::\\"text\\"\n            WHEN (\\"document_approval_status\\" = 'pending_approval'::\\"text\\") THEN 'PENDING'::\\"text\\"\n            ELSE 'AMBIGUOUS'::\\"text\\"\n        END AS \\"effective_posting_state\\",\n    COALESCE(\\"active_journal_id\\", \\"replacement_journal_id\\") AS \\"effective_journal_id\\",\n    COALESCE(\\"active_journal_number\\", \\"replacement_journal_number\\") AS \\"effective_journal_number\\",\n    COALESCE(\\"active_journal_date\\", \\"replacement_journal_date\\") AS \\"effective_journal_date\\",\n        CASE\n            WHEN (\\"active_original_count\\" > 1) THEN 'multiple_active_original_journals'::\\"text\\"\n            WHEN (\\"active_replacement_count\\" > 1) THEN 'multiple_active_replacement_journals'::\\"text\\"\n            WHEN ((\\"active_original_count\\" > 0) AND (\\"active_replacement_count\\" > 0)) THEN 'active_original_and_replacement_coexist'::\\"text\\"\n            WHEN ((\\"document_approval_status\\" = 'approved'::\\"text\\") AND (\\"active_original_count\\" = 0) AND (\\"reversed_original_count\\" = 0) AND (\\"active_replacement_count\\" = 0)) THEN 'approved_without_posted_journal_evidence'::\\"text\\"\n            WHEN ((\\"document_approval_status\\" = 'rejected'::\\"text\\") AND ((\\"active_original_count\\" > 0) OR (\\"active_replacement_count\\" > 0))) THEN 'rejected_with_active_accounting_path'::\\"text\\"\n            ELSE NULL::\\"text\\"\n        END AS \\"ambiguity_reason\\"\n   FROM \\"resolved\\" \\"x\\"","--\n-- Name: VIEW \\"effective_expense_posting_state\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON VIEW \\"public\\".\\"effective_expense_posting_state\\" IS 'Canonical read-only expense lifecycle. ACTIVE uses the original journal; REPLACED uses an explicit/known full repair journal; REVERSED has no effective journal.'","--\n-- Name: resolve_effective_expense_posting_state(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"resolve_effective_expense_posting_state\\"(\\"p_expense_id\\" \\"uuid\\") RETURNS SETOF \\"public\\".\\"effective_expense_posting_state\\"\n    LANGUAGE \\"sql\\" STABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT s.*\n  FROM public.effective_expense_posting_state s\n  WHERE s.expense_id = p_expense_id;\n$$","--\n-- Name: reverse_credit_note_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"reverse_credit_note_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_je_ids uuid[];\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF OLD.journal_entry_id IS NULL THEN\n      RETURN OLD;\n    END IF;\n\n    SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])\n      INTO v_je_ids\n      FROM journal_entries\n     WHERE source_module IN ('credit_note', 'credit_note_cogs')\n       AND reference_id  = OLD.id;\n\n    IF array_length(v_je_ids, 1) IS NOT NULL THEN\n      -- Do not touch bank_statement_lines.updated_at — the column is not\n      -- present in every environment (two conflicting CREATE TABLE\n      -- IF NOT EXISTS definitions exist in the migration history).\n      -- matched_at = NULL is the authoritative recon-reset timestamp.\n      UPDATE bank_statement_lines\n         SET matched_entry_id      = NULL,\n             reconciliation_status = 'unmatched',\n             matched_at            = NULL\n       WHERE matched_entry_id = ANY (v_je_ids);\n      -- bank_reconciliation_items.journal_entry_id has ON DELETE SET NULL\n      -- (installed in 20260714150000), so the JE DELETE clears it too.\n\n      DELETE FROM journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);\n      DELETE FROM journal_entries     WHERE id = ANY (v_je_ids);\n    END IF;\n    RETURN OLD;\n  END IF;\n\n  -- UPDATE: only reverse if status leaves 'approved'\n  IF TG_OP = 'UPDATE'\n     AND OLD.status = 'approved'\n     AND NEW.status IS DISTINCT FROM 'approved'\n     AND OLD.journal_entry_id IS NOT NULL THEN\n\n    SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])\n      INTO v_je_ids\n      FROM journal_entries\n     WHERE source_module IN ('credit_note', 'credit_note_cogs')\n       AND reference_id  = OLD.id;\n\n    IF array_length(v_je_ids, 1) IS NOT NULL THEN\n      -- Do not touch bank_statement_lines.updated_at — the column is not\n      -- present in every environment (two conflicting CREATE TABLE\n      -- IF NOT EXISTS definitions exist in the migration history).\n      -- matched_at = NULL is the authoritative recon-reset timestamp.\n      UPDATE bank_statement_lines\n         SET matched_entry_id      = NULL,\n             reconciliation_status = 'unmatched',\n             matched_at            = NULL\n       WHERE matched_entry_id = ANY (v_je_ids);\n\n      DELETE FROM journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);\n      DELETE FROM journal_entries     WHERE id = ANY (v_je_ids);\n    END IF;\n\n    NEW.journal_entry_id := NULL;\n  END IF;\n\n  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;\nEND $$","--\n-- Name: reverse_fund_transfer(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"reverse_fund_transfer\\"(\\"p_id\\" \\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_row                    public.fund_transfers%ROWTYPE;\n  v_original_je_id         uuid;\n  v_new_je_id              uuid;\n  v_new_je_number          text;\n  v_existing_reversal      public.journal_entries%ROWTYPE;\n  v_period_status          text;\nBEGIN\n  SELECT *\n    INTO v_row\n    FROM public.fund_transfers\n   WHERE id = p_id\n   FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Fund transfer % not found', p_id\n      USING ERRCODE = 'no_data_found';\n  END IF;\n\n  IF v_row.status <> 'posted' THEN\n    RAISE EXCEPTION 'Only posted fund transfers can be reversed (current status: %)', v_row.status\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  SELECT id\n    INTO v_original_je_id\n    FROM public.journal_entries\n   WHERE source_module = 'fund_transfers'\n     AND reference_id = p_id\n     AND reference_number = v_row.transfer_number\n   ORDER BY created_at ASC\n   LIMIT 1\n   FOR UPDATE;\n\n  IF v_original_je_id IS NULL THEN\n    RAISE EXCEPTION 'Original journal entry for fund transfer % not found', v_row.transfer_number\n      USING ERRCODE = 'no_data_found';\n  END IF;\n\n  v_new_je_number := 'REV-' || v_row.transfer_number;\n\n  SELECT *\n    INTO v_existing_reversal\n    FROM public.journal_entries\n   WHERE source_module = 'fund_transfers'\n     AND reference_id = p_id\n     AND reference_number = v_new_je_number\n   LIMIT 1\n   FOR UPDATE;\n\n  IF v_existing_reversal.id IS NOT NULL THEN\n    IF COALESCE(v_existing_reversal.is_posted, false)\n       OR NOT COALESCE(v_existing_reversal.is_reversed, false) THEN\n      RAISE EXCEPTION 'Cannot reverse %: its preserved reversal journal is already active or inconsistent',\n        v_row.transfer_number USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n\n    IF EXISTS (\n      (\n        SELECT line_number, account_id, debit, credit\n          FROM public.journal_entry_lines\n         WHERE journal_entry_id = v_original_je_id\n        EXCEPT ALL\n        SELECT line_number, account_id, credit, debit\n          FROM public.journal_entry_lines\n         WHERE journal_entry_id = v_existing_reversal.id\n      )\n      UNION ALL\n      (\n        SELECT line_number, account_id, debit, credit\n          FROM public.journal_entry_lines\n         WHERE journal_entry_id = v_existing_reversal.id\n        EXCEPT ALL\n        SELECT line_number, account_id, credit, debit\n          FROM public.journal_entry_lines\n         WHERE journal_entry_id = v_original_je_id\n      )\n    ) THEN\n      RAISE EXCEPTION 'Cannot reverse %: its preserved reversal journal no longer matches the original',\n        v_row.transfer_number USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n\n    SELECT status\n      INTO v_period_status\n      FROM public.accounting_periods\n     WHERE start_date <= v_existing_reversal.entry_date\n       AND end_date >= v_existing_reversal.entry_date\n     ORDER BY start_date DESC\n     LIMIT 1;\n\n    IF v_period_status IS NOT NULL AND v_period_status <> 'open' THEN\n      RAISE EXCEPTION\n        'Cannot reverse %: the preserved reversal period for % is %',\n        v_row.transfer_number,\n        to_char(v_existing_reversal.entry_date, 'FMMonth YYYY'),\n        v_period_status USING ERRCODE = 'check_violation';\n    END IF;\n\n    UPDATE public.journal_entries\n       SET is_posted = true,\n           is_reversed = false\n     WHERE id = v_existing_reversal.id;\n\n    UPDATE public.journal_entries\n       SET is_reversed = true,\n           reversed_by_id = v_existing_reversal.id\n     WHERE id = v_original_je_id;\n\n    UPDATE public.fund_transfers\n       SET status = 'reversed',\n           reversed_at = now(),\n           reversed_by = auth.uid()\n     WHERE id = p_id;\n\n    RETURN v_existing_reversal.id;\n  END IF;\n\n  INSERT INTO public.journal_entries (\n    entry_number,\n    entry_date,\n    description,\n    source_module,\n    reference_id,\n    reference_number,\n    is_posted,\n    created_by\n  )\n  SELECT\n    v_new_je_number,\n    CURRENT_DATE,\n    'Reversal of ' || COALESCE(je.description, je.entry_number),\n    'fund_transfers',\n    p_id,\n    v_new_je_number,\n    true,\n    auth.uid()\n  FROM public.journal_entries je\n  WHERE je.id = v_original_je_id\n  RETURNING id INTO v_new_je_id;\n\n  UPDATE public.journal_entries\n     SET is_reversed = true,\n         reversed_by_id = v_new_je_id\n   WHERE id = v_original_je_id;\n\n  INSERT INTO public.journal_entry_lines (\n    journal_entry_id,\n    line_number,\n    account_id,\n    description,\n    debit,\n    credit\n  )\n  SELECT\n    v_new_je_id,\n    line_number,\n    account_id,\n    'REV: ' || COALESCE(description, ''),\n    credit,\n    debit\n  FROM public.journal_entry_lines\n  WHERE journal_entry_id = v_original_je_id;\n\n  UPDATE public.fund_transfers\n     SET status = 'reversed',\n         reversed_at = now(),\n         reversed_by = auth.uid()\n   WHERE id = p_id;\n\n  RETURN v_new_je_id;\nEND;\n$$","--\n-- Name: run_deterministic_finance_historical_repair(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"run_deterministic_finance_historical_repair\\"() RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_run uuid;\n  r record;\n  v_number text;\n  v_je uuid;\n  v_scanned bigint:=0;\nBEGIN\n  -- Read by sync_expense_journal_currency_and_state(). Metadata repair may\n  -- fire document triggers, but must never convert or rewrite old JE amounts.\n  PERFORM set_config('app.finance_historical_repair','on',true);\n  INSERT INTO public.finance_historical_repair_runs(notes)\n  VALUES('Deterministic metadata/link repair. Accounting amounts are immutable.') RETURNING id INTO v_run;\n\n  SELECT COUNT(*) INTO v_scanned FROM (\n    SELECT id FROM public.finance_expenses UNION ALL SELECT id FROM public.receipt_vouchers\n    UNION ALL SELECT id FROM public.payment_vouchers UNION ALL SELECT id FROM public.fund_transfers\n    UNION ALL SELECT id FROM public.journal_entries UNION ALL SELECT id FROM public.bank_statement_lines\n  ) s;\n\n  -- Missing expense voucher numbers: chronological ordering is deterministic;\n  -- numbering is metadata and does not alter accounting values.\n  FOR r IN SELECT * FROM public.finance_expenses WHERE voucher_number IS NULL OR btrim(voucher_number)='' ORDER BY expense_date,created_at,id FOR UPDATE LOOP\n    v_number:=public.next_expense_voucher_number(r.expense_date);\n    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n    VALUES(v_run,'expense',r.id,v_number,ARRAY['voucher_number'],jsonb_build_object('voucher_number',r.voucher_number),jsonb_build_object('voucher_number',v_number),'Legacy Bank Reconciliation expense omitted native voucher numbering');\n    UPDATE public.finance_expenses SET voucher_number=v_number WHERE id=r.id;\n  END LOOP;\n\n  FOR r IN SELECT * FROM public.receipt_vouchers WHERE voucher_number IS NULL OR btrim(voucher_number)='' ORDER BY voucher_date,created_at,id FOR UPDATE LOOP\n    v_number:=public.next_receipt_voucher_number(r.voucher_date);\n    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n    VALUES(v_run,'receipt',r.id,v_number,ARRAY['voucher_number'],jsonb_build_object('voucher_number',r.voucher_number),jsonb_build_object('voucher_number',v_number),'Missing receipt number repaired by the native atomic numbering engine');\n    UPDATE public.receipt_vouchers SET voucher_number=v_number WHERE id=r.id;\n  END LOOP;\n\n  FOR r IN SELECT * FROM public.payment_vouchers WHERE voucher_number IS NULL OR btrim(voucher_number)='' ORDER BY voucher_date,created_at,id FOR UPDATE LOOP\n    v_number:=public.next_payment_voucher_number(r.voucher_date);\n    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n    VALUES(v_run,'payment',r.id,v_number,ARRAY['voucher_number'],jsonb_build_object('voucher_number',r.voucher_number),jsonb_build_object('voucher_number',v_number),'Missing payment number repaired by the native atomic numbering engine');\n    UPDATE public.payment_vouchers SET voucher_number=v_number WHERE id=r.id;\n  END LOOP;\n\n  -- Fund Transfer source metadata is deterministic when IDR is one side. The\n  -- old poster's GL values are already functional only when IDR is the source;\n  -- USD-source legacy postings are exceptions because correcting them would\n  -- change posted accounting values.\n  FOR r IN\n    SELECT ft.id,ft.transfer_number,ft.status,ft.from_amount,ft.to_amount,ft.exchange_rate,ft.journal_entry_id,\n      CASE WHEN ft.from_account_type='bank' THEN upper(fba.currency) ELSE 'IDR' END AS from_currency,\n      CASE WHEN ft.to_account_type='bank' THEN upper(tba.currency) ELSE 'IDR' END AS to_currency,\n      CASE\n        WHEN (CASE WHEN ft.from_account_type='bank' THEN upper(fba.currency) ELSE 'IDR' END)='IDR'\n         AND (CASE WHEN ft.to_account_type='bank' THEN upper(tba.currency) ELSE 'IDR' END)='IDR' THEN 1\n        WHEN (CASE WHEN ft.from_account_type='bank' THEN upper(fba.currency) ELSE 'IDR' END)='IDR' AND ft.to_amount>0 THEN ft.from_amount/ft.to_amount\n        WHEN (CASE WHEN ft.to_account_type='bank' THEN upper(tba.currency) ELSE 'IDR' END)='IDR' AND ft.from_amount>0 THEN ft.to_amount/ft.from_amount\n      END AS expected_rate\n    FROM public.fund_transfers ft\n    LEFT JOIN public.bank_accounts fba ON fba.id=ft.from_bank_account_id\n    LEFT JOIN public.bank_accounts tba ON tba.id=ft.to_bank_account_id\n  LOOP\n    IF r.status='posted' AND r.journal_entry_id IS NULL THEN\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal_entry_id'],\n        'Posted Fund Transfer has no linked Journal Entry','Correct active Journal Entry or accountant-authorised reversal/reposting');\n    END IF;\n    IF r.from_currency IS NULL OR r.to_currency IS NULL OR r.from_currency NOT IN('IDR','USD') OR r.to_currency NOT IN('IDR','USD') THEN\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['from_currency','to_currency'],\n        'Fund Transfer account relationships do not prove supported currencies','Correct source and destination account currencies');\n    END IF;\n    IF r.expected_rate IS NOT NULL AND (r.exchange_rate IS NULL OR abs(r.exchange_rate-r.expected_rate)>0.000001) THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['exchange_rate'],\n        jsonb_build_object('exchange_rate',r.exchange_rate),jsonb_build_object('exchange_rate',r.expected_rate),\n        'Stored IDR and USD side amounts prove the USD-to-IDR Fund Transfer rate');\n      UPDATE public.fund_transfers SET exchange_rate=r.expected_rate WHERE id=r.id;\n    END IF;\n    IF r.journal_entry_id IS NOT NULL AND r.from_currency='IDR' AND r.to_currency IN('IDR','USD')\n       AND (r.to_currency='USD' OR abs(r.from_amount-r.to_amount)<=0.01) THEN\n      IF EXISTS(SELECT 1 FROM public.journal_entries je LEFT JOIN public.journal_entry_lines l ON l.journal_entry_id=je.id\n        WHERE je.id=r.journal_entry_id AND (je.transaction_currency IS NULL OR je.functional_currency IS NULL\n          OR je.amounts_are_functional IS NULL OR l.transaction_currency IS NULL OR l.transaction_debit IS NULL\n          OR l.transaction_credit IS NULL OR l.functional_currency IS NULL OR l.exchange_rate IS NULL)) THEN\n        INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n        VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal currency metadata','journal line transaction metadata'],\n          jsonb_build_object('journal_entry_id',r.journal_entry_id),\n          jsonb_build_object('from_currency',r.from_currency,'to_currency',r.to_currency,'exchange_rate',COALESCE(r.expected_rate,1)),\n          'IDR-source legacy Contra already stores functional IDR GL values; source amounts prove line transaction metadata');\n        UPDATE public.journal_entry_lines SET\n          transaction_currency=COALESCE(transaction_currency,CASE WHEN line_number=1 THEN r.to_currency ELSE r.from_currency END),\n          transaction_debit=COALESCE(transaction_debit,CASE WHEN line_number=1 THEN r.to_amount ELSE 0 END),\n          transaction_credit=COALESCE(transaction_credit,CASE WHEN line_number=2 THEN r.from_amount ELSE 0 END),\n          functional_currency=COALESCE(functional_currency,'IDR'),\n          exchange_rate=COALESCE(exchange_rate,CASE WHEN line_number=1 AND r.to_currency='USD' THEN r.expected_rate ELSE 1 END)\n        WHERE journal_entry_id=r.journal_entry_id AND line_number IN(1,2);\n        UPDATE public.journal_entries SET transaction_currency=COALESCE(transaction_currency,CASE WHEN r.from_currency=r.to_currency THEN r.from_currency ELSE 'IDR' END),\n          functional_currency=COALESCE(functional_currency,'IDR'),exchange_rate=COALESCE(exchange_rate,COALESCE(r.expected_rate,1)),\n          amounts_are_functional=COALESCE(amounts_are_functional,true)\n        WHERE id=r.journal_entry_id;\n      END IF;\n    ELSIF r.journal_entry_id IS NOT NULL AND r.from_currency='USD' THEN\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal functional debit/credit','journal currency metadata'],\n        'Legacy USD-source Contra stored the USD source amount in functional GL columns; posted values were not rewritten',\n        'Accountant approval of the historical USD-to-IDR rate and a controlled correcting/reversal entry');\n    END IF;\n  END LOOP;\n\n  -- Expense bank/currency metadata only when exactly one linked bank account is\n  -- provable. IDR rate is certain; USD rate is never guessed.\n  FOR r IN\n    SELECT fe.id,fe.voucher_number,fe.bank_account_id,fe.payment_method,fe.transaction_currency,fe.currency_code,\n      fe.functional_currency,fe.bank_account_currency,fe.payment_currency,fe.exchange_rate,\n      (array_agg(DISTINCT bsl.bank_account_id))[1] AS linked_bank_id,min(upper(COALESCE(bsl.currency,ba.currency))) AS linked_currency,\n      count(DISTINCT bsl.bank_account_id) AS bank_count\n    FROM public.finance_expenses fe LEFT JOIN public.bank_statement_lines bsl ON bsl.matched_expense_id=fe.id\n    LEFT JOIN public.bank_accounts ba ON ba.id=bsl.bank_account_id\n    GROUP BY fe.id HAVING count(bsl.id)>0\n  LOOP\n    IF r.bank_count=1 THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      SELECT v_run,'expense',r.id,r.voucher_number,\n        ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NULL THEN 'bank_account_id' END,\n          CASE WHEN r.transaction_currency IS NULL THEN 'transaction_currency' END,\n          CASE WHEN r.currency_code IS NULL THEN 'currency_code' END,\n          CASE WHEN r.functional_currency IS NULL THEN 'functional_currency' END,\n          CASE WHEN r.bank_account_currency IS NULL THEN 'bank_account_currency' END,\n          CASE WHEN r.payment_currency IS NULL THEN 'payment_currency' END,\n          CASE WHEN r.linked_currency='IDR' AND r.exchange_rate IS NULL THEN 'exchange_rate' END],NULL),\n        jsonb_build_object('bank_account_id',r.bank_account_id,'transaction_currency',r.transaction_currency,\n          'currency_code',r.currency_code,'functional_currency',r.functional_currency,\n          'bank_account_currency',r.bank_account_currency,'payment_currency',r.payment_currency,'exchange_rate',r.exchange_rate),\n        jsonb_build_object('bank_account_id',COALESCE(r.bank_account_id,r.linked_bank_id),\n          'transaction_currency',COALESCE(r.transaction_currency,r.linked_currency),\n          'currency_code',COALESCE(r.currency_code,r.linked_currency),'functional_currency',COALESCE(r.functional_currency,'IDR'),\n          'bank_account_currency',COALESCE(r.bank_account_currency,r.linked_currency),\n          'payment_currency',COALESCE(r.payment_currency,r.linked_currency),\n          'exchange_rate',COALESCE(r.exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)),\n        'Unique reconciliation line proves bank account and transaction currency'\n      WHERE r.bank_account_id IS NULL OR r.transaction_currency IS NULL OR r.currency_code IS NULL\n         OR r.functional_currency IS NULL OR r.bank_account_currency IS NULL OR r.payment_currency IS NULL\n         OR (r.linked_currency='IDR' AND r.exchange_rate IS NULL);\n      UPDATE public.finance_expenses SET bank_account_id=COALESCE(bank_account_id,r.linked_bank_id),\n        currency_code=COALESCE(currency_code,r.linked_currency),transaction_currency=COALESCE(transaction_currency,r.linked_currency),\n        functional_currency=COALESCE(functional_currency,'IDR'),bank_account_currency=COALESCE(bank_account_currency,r.linked_currency),\n        payment_currency=COALESCE(payment_currency,r.linked_currency),exchange_rate=COALESCE(exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)\n      WHERE id=r.id;\n      IF r.linked_currency='USD' AND r.exchange_rate IS NULL THEN\n        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n        VALUES(v_run,'expense',r.id,r.voucher_number,ARRAY['exchange_rate'],'USD currency is certain but no historical transaction-date rate is stored','Authoritative USD-to-IDR rate and rate source/date');\n      END IF;\n      IF (r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id)\n         OR (r.transaction_currency IS NOT NULL AND upper(r.transaction_currency)<>r.linked_currency) THEN\n        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n        VALUES(v_run,'expense',r.id,r.voucher_number,\n          ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id THEN 'bank_account_id' END,\n            CASE WHEN r.transaction_currency IS NOT NULL AND upper(r.transaction_currency)<>r.linked_currency THEN 'transaction_currency' END],NULL),\n          'Stored expense metadata conflicts with its unique reconciliation bank line; neither side was overwritten',\n          'Accountant confirmation of the correct bank account and transaction currency');\n      END IF;\n    ELSE\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'expense',r.id,r.voucher_number,ARRAY['bank_account_id','transaction_currency'],'More than one linked bank account; no single relationship is certain','Correct paying bank account and transaction currency');\n    END IF;\n  END LOOP;\n\n  -- IDR source rows have a certain functional rate of 1.\n  INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n  SELECT v_run,'expense',id,voucher_number,\n    ARRAY_REMOVE(ARRAY[CASE WHEN exchange_rate IS NULL THEN 'exchange_rate' END,CASE WHEN functional_currency IS NULL THEN 'functional_currency' END],NULL),\n    jsonb_build_object('exchange_rate',exchange_rate,'functional_currency',functional_currency),\n    jsonb_build_object('exchange_rate',COALESCE(exchange_rate,1),'functional_currency',COALESCE(functional_currency,'IDR')),\n    'IDR functional rate and functional currency are deterministic'\n  FROM public.finance_expenses WHERE transaction_currency='IDR' AND (exchange_rate IS NULL OR functional_currency IS NULL);\n  UPDATE public.finance_expenses SET exchange_rate=COALESCE(exchange_rate,1),functional_currency=COALESCE(functional_currency,'IDR')\n  WHERE transaction_currency='IDR' AND (exchange_rate IS NULL OR functional_currency IS NULL);\n\n  -- Duplicate historical numbers are never silently renumbered because the\n  -- correct legal document number cannot be inferred.\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n  SELECT v_run,'expense',fe.id,fe.voucher_number,ARRAY['voucher_number'],\n    'Voucher number is duplicated; renumbering legal history is not deterministic',\n    'Accountant-approved canonical number for every duplicated document'\n  FROM public.finance_expenses fe JOIN (\n    SELECT voucher_number FROM public.finance_expenses WHERE voucher_number IS NOT NULL\n    GROUP BY voucher_number HAVING count(*)>1\n  ) d USING(voucher_number);\n\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n  SELECT v_run,'receipt',rv.id,rv.voucher_number,ARRAY['voucher_number'],\n    'Voucher number is duplicated; legal history cannot be renumbered deterministically',\n    'Accountant-approved canonical number for every duplicated receipt'\n  FROM public.receipt_vouchers rv JOIN (\n    SELECT voucher_number FROM public.receipt_vouchers WHERE voucher_number IS NOT NULL\n    GROUP BY voucher_number HAVING count(*)>1\n  ) d USING(voucher_number);\n\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n  SELECT v_run,'payment',pv.id,pv.voucher_number,ARRAY['voucher_number'],\n    'Voucher number is duplicated; legal history cannot be renumbered deterministically',\n    'Accountant-approved canonical number for every duplicated payment'\n  FROM public.payment_vouchers pv JOIN (\n    SELECT voucher_number FROM public.payment_vouchers WHERE voucher_number IS NOT NULL\n    GROUP BY voucher_number HAVING count(*)>1\n  ) d USING(voucher_number);\n\n  -- Deterministic source identity repairs.\n  FOR r IN SELECT id,entry_number,reference_number,reference_id FROM public.journal_entries\n    WHERE source_module='expenses' AND reference_id IS NULL AND reference_number LIKE 'EXP-%' LOOP\n    BEGIN\n      IF EXISTS(SELECT 1 FROM public.finance_expenses WHERE id=substring(r.reference_number from 5)::uuid) THEN\n        INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n        VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['reference_id'],jsonb_build_object('reference_id',NULL),\n          jsonb_build_object('reference_id',substring(r.reference_number from 5)::uuid),'EXP UUID reference deterministically identifies source expense');\n        UPDATE public.journal_entries SET reference_id=substring(r.reference_number from 5)::uuid WHERE id=r.id;\n      END IF;\n    EXCEPTION WHEN invalid_text_representation THEN\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['reference_id'],'Expense reference number does not contain a valid UUID','Correct source expense database ID');\n    END;\n  END LOOP;\n\n  -- Canonical JE links from typed document links.\n  FOR r IN SELECT bsl.id,bsl.reference,bsl.matched_entry_id,\n      COALESCE(rv.journal_entry_id,pv.journal_entry_id,ft.journal_entry_id,tp.journal_entry_id,je_exp.id,je_pc.id) AS resolved_je\n    FROM public.bank_statement_lines bsl\n    LEFT JOIN public.receipt_vouchers rv ON rv.id=bsl.matched_receipt_id\n    LEFT JOIN public.payment_vouchers pv ON pv.id=bsl.matched_payment_id\n    LEFT JOIN public.fund_transfers ft ON ft.id=bsl.matched_fund_transfer_id\n    LEFT JOIN public.tax_payments tp ON tp.id=bsl.matched_tax_payment_id\n    LEFT JOIN LATERAL(SELECT id FROM public.journal_entries WHERE source_module='expenses'\n      AND (reference_id=bsl.matched_expense_id OR reference_number='EXP-'||bsl.matched_expense_id::text)\n      AND is_posted=true AND COALESCE(is_reversed,false)=false ORDER BY created_at DESC LIMIT 1) je_exp ON true\n    LEFT JOIN LATERAL(SELECT id FROM public.journal_entries WHERE source_module='petty_cash' AND reference_id=bsl.matched_petty_cash_id AND is_posted=true AND COALESCE(is_reversed,false)=false ORDER BY created_at DESC LIMIT 1) je_pc ON true\n    WHERE bsl.matched_entry_id IS NULL AND (bsl.matched_expense_id IS NOT NULL OR bsl.matched_receipt_id IS NOT NULL OR bsl.matched_payment_id IS NOT NULL OR bsl.matched_fund_transfer_id IS NOT NULL OR bsl.matched_petty_cash_id IS NOT NULL OR bsl.matched_tax_payment_id IS NOT NULL)\n  LOOP\n    IF r.resolved_je IS NOT NULL THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      VALUES(v_run,'bank_reconciliation',r.id,r.reference,ARRAY['matched_entry_id'],jsonb_build_object('matched_entry_id',NULL),jsonb_build_object('matched_entry_id',r.resolved_je),'Typed document link resolves one active journal');\n      UPDATE public.bank_statement_lines SET matched_entry_id=r.resolved_je WHERE id=r.id;\n    ELSE\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'bank_reconciliation',r.id,r.reference,ARRAY['matched_entry_id'],'Linked document has no provable active journal','Post or identify the correct source document journal');\n    END IF;\n  END LOOP;\n\n  -- Recover missing typed document links from an existing canonical JE only\n  -- when exactly one source document owns that JE.\n  FOR r IN\n    WITH untyped AS (\n      SELECT b.* FROM public.bank_statement_lines b\n      WHERE b.matched_entry_id IS NOT NULL AND b.matched_expense_id IS NULL\n        AND b.matched_receipt_id IS NULL AND b.matched_payment_id IS NULL\n        AND b.matched_fund_transfer_id IS NULL AND b.matched_petty_cash_id IS NULL\n        AND b.matched_tax_payment_id IS NULL\n    ), candidates AS (\n      SELECT b.id,b.reference,'expense'::text AS source_type,fe.id AS source_id\n      FROM untyped b JOIN public.journal_entries je ON je.id=b.matched_entry_id\n      JOIN public.finance_expenses fe ON je.source_module='expenses'\n        AND (je.reference_id=fe.id OR je.reference_number='EXP-'||fe.id::text)\n      UNION ALL\n      SELECT b.id,b.reference,'receipt',rv.id FROM untyped b JOIN public.receipt_vouchers rv ON rv.journal_entry_id=b.matched_entry_id\n      UNION ALL\n      SELECT b.id,b.reference,'payment',pv.id FROM untyped b JOIN public.payment_vouchers pv ON pv.journal_entry_id=b.matched_entry_id\n      UNION ALL\n      SELECT b.id,b.reference,'fund_transfer',ft.id FROM untyped b JOIN public.fund_transfers ft ON ft.journal_entry_id=b.matched_entry_id\n      UNION ALL\n      SELECT b.id,b.reference,'petty_cash',pc.id FROM untyped b JOIN public.journal_entries je ON je.id=b.matched_entry_id\n        JOIN public.petty_cash_transactions pc ON je.source_module='petty_cash' AND je.reference_id=pc.id\n      UNION ALL\n      SELECT b.id,b.reference,'tax_payment',tp.id FROM untyped b JOIN public.tax_payments tp ON tp.journal_entry_id=b.matched_entry_id\n    )\n    SELECT id,reference,(array_agg(source_type ORDER BY source_type))[1] AS source_type,\n      (array_agg(source_id ORDER BY source_type))[1] AS source_id,count(*) AS candidate_count\n    FROM candidates GROUP BY id,reference\n  LOOP\n    IF r.candidate_count=1 THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      VALUES(v_run,'bank_reconciliation',r.id,r.reference,ARRAY['typed document link'],\n        jsonb_build_object('typed_document_id',NULL),jsonb_build_object('document_type',r.source_type,'document_id',r.source_id),\n        'Existing Journal Entry is owned by exactly one native Finance document');\n      UPDATE public.bank_statement_lines SET\n        matched_expense_id=CASE WHEN r.source_type='expense' THEN r.source_id ELSE matched_expense_id END,\n        matched_receipt_id=CASE WHEN r.source_type='receipt' THEN r.source_id ELSE matched_receipt_id END,\n        matched_payment_id=CASE WHEN r.source_type='payment' THEN r.source_id ELSE matched_payment_id END,\n        matched_fund_transfer_id=CASE WHEN r.source_type='fund_transfer' THEN r.source_id ELSE matched_fund_transfer_id END,\n        matched_petty_cash_id=CASE WHEN r.source_type='petty_cash' THEN r.source_id ELSE matched_petty_cash_id END,\n        matched_tax_payment_id=CASE WHEN r.source_type='tax_payment' THEN r.source_id ELSE matched_tax_payment_id END\n      WHERE id=r.id;\n    ELSE\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'bank_reconciliation',r.id,r.reference,ARRAY['typed document link'],\n        'Journal Entry is owned by more than one possible native document','Accountant selection of the source document represented by this bank line');\n    END IF;\n  END LOOP;\n\n  -- Legacy bank-reconciliation JEs stored the bank-statement amount directly\n  -- in debit/credit. A single linked statement currency proves the transaction\n  -- currency. IDR also proves rate=1 and functional values. For USD, the rate\n  -- and functional values are unknown: preserve every amount and raise an\n  -- exception instead of pretending the values are IDR.\n  FOR r IN\n    SELECT je.id,je.entry_number,je.transaction_currency,je.functional_currency,je.exchange_rate,je.amounts_are_functional,\n      min(upper(COALESCE(bsl.currency,ba.currency))) AS proven_currency,\n      count(DISTINCT upper(COALESCE(bsl.currency,ba.currency))) AS currency_count,\n      bool_or(jel.transaction_currency IS NULL OR jel.transaction_debit IS NULL OR jel.transaction_credit IS NULL\n        OR jel.functional_currency IS NULL OR (upper(COALESCE(bsl.currency,ba.currency))='IDR' AND jel.exchange_rate IS NULL)) AS line_metadata_missing\n    FROM public.journal_entries je\n    JOIN public.bank_statement_lines bsl ON bsl.matched_entry_id=je.id\n    JOIN public.journal_entry_lines jel ON jel.journal_entry_id=je.id\n    LEFT JOIN public.bank_accounts ba ON ba.id=bsl.bank_account_id\n    WHERE je.source_module='bank_reconciliation'\n    GROUP BY je.id\n  LOOP\n    IF r.currency_count=1 AND r.proven_currency IN ('IDR','USD') THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      SELECT v_run,'journal',r.id,r.entry_number,\n        ARRAY_REMOVE(ARRAY[CASE WHEN r.transaction_currency IS NULL THEN 'transaction_currency' END,\n          CASE WHEN r.functional_currency IS NULL THEN 'functional_currency' END,\n          CASE WHEN r.proven_currency='IDR' AND r.exchange_rate IS NULL THEN 'exchange_rate' END,\n          CASE WHEN r.amounts_are_functional IS NULL THEN 'amounts_are_functional' END,\n          CASE WHEN r.line_metadata_missing THEN 'journal_lines.currency_and_transaction_metadata' END],NULL),\n        jsonb_build_object('transaction_currency',r.transaction_currency,'functional_currency',r.functional_currency,\n          'exchange_rate',r.exchange_rate,'amounts_are_functional',r.amounts_are_functional,\n          'journal_lines_metadata_missing',r.line_metadata_missing),\n        jsonb_build_object('transaction_currency',COALESCE(r.transaction_currency,r.proven_currency),\n          'functional_currency','IDR','exchange_rate',COALESCE(r.exchange_rate,CASE WHEN r.proven_currency='IDR' THEN 1 END),\n          'amounts_are_functional',r.proven_currency='IDR'),\n        'Exactly one linked bank-statement currency proves journal transaction currency'\n      WHERE r.transaction_currency IS NULL OR r.functional_currency IS NULL OR r.amounts_are_functional IS NULL\n         OR r.line_metadata_missing OR (r.proven_currency='IDR' AND r.exchange_rate IS NULL);\n\n      UPDATE public.journal_entries SET\n        transaction_currency=COALESCE(transaction_currency,r.proven_currency),functional_currency=COALESCE(functional_currency,'IDR'),\n        exchange_rate=COALESCE(exchange_rate,CASE WHEN r.proven_currency='IDR' THEN 1 END),\n        amounts_are_functional=COALESCE(amounts_are_functional,CASE WHEN r.proven_currency='IDR' THEN true ELSE false END)\n      WHERE id=r.id;\n      UPDATE public.journal_entry_lines SET\n        transaction_currency=COALESCE(transaction_currency,r.proven_currency),\n        transaction_debit=COALESCE(transaction_debit,debit),transaction_credit=COALESCE(transaction_credit,credit),\n        functional_currency=COALESCE(functional_currency,'IDR'),\n        exchange_rate=COALESCE(exchange_rate,CASE WHEN r.proven_currency='IDR' THEN 1 END)\n      WHERE journal_entry_id=r.id;\n\n      IF r.proven_currency='USD' AND r.exchange_rate IS NULL THEN\n        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n        VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['exchange_rate','functional debit/credit values'],\n          'USD transaction currency is proven, but no authoritative historical rate is stored; posted amounts were preserved',\n          'Authoritative USD-to-IDR rate and rate source/date; accountant approval before functional values are corrected');\n      END IF;\n    ELSE\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['transaction_currency','exchange_rate'],\n        'Linked bank statements do not prove exactly one currency','Correct transaction currency and authoritative historical exchange rate');\n    END IF;\n  END LOOP;\n\n  -- Native receipt metadata is repairable only from its own unique typed bank\n  -- reconciliation link. This does not post, unpost, or alter the receipt.\n  FOR r IN\n    SELECT rv.id,rv.voucher_number,rv.bank_account_id,rv.payment_method,rv.transaction_currency,rv.currency_code,\n      rv.functional_currency,rv.bank_account_currency,rv.payment_currency,rv.exchange_rate,\n      (array_agg(DISTINCT bsl.bank_account_id))[1] AS linked_bank_id,min(upper(COALESCE(bsl.currency,ba.currency))) AS linked_currency,\n      count(DISTINCT bsl.bank_account_id) AS bank_count\n    FROM public.receipt_vouchers rv\n    JOIN public.bank_statement_lines bsl ON bsl.matched_receipt_id=rv.id\n    LEFT JOIN public.bank_accounts ba ON ba.id=bsl.bank_account_id\n    GROUP BY rv.id\n  LOOP\n    IF r.bank_count=1 AND r.linked_currency IN ('IDR','USD') THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      SELECT v_run,'receipt',r.id,r.voucher_number,\n        ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NULL THEN 'bank_account_id' END,\n          CASE WHEN r.transaction_currency IS NULL THEN 'transaction_currency' END,\n          CASE WHEN r.currency_code IS NULL THEN 'currency_code' END,\n          CASE WHEN r.functional_currency IS NULL THEN 'functional_currency' END,\n          CASE WHEN r.bank_account_currency IS NULL THEN 'bank_account_currency' END,\n          CASE WHEN r.payment_currency IS NULL THEN 'payment_currency' END,\n          CASE WHEN r.linked_currency='IDR' AND r.exchange_rate IS NULL THEN 'exchange_rate' END],NULL),\n        jsonb_build_object('bank_account_id',r.bank_account_id,'transaction_currency',r.transaction_currency,\n          'currency_code',r.currency_code,'functional_currency',r.functional_currency,\n          'bank_account_currency',r.bank_account_currency,'payment_currency',r.payment_currency,'exchange_rate',r.exchange_rate),\n        jsonb_build_object('bank_account_id',COALESCE(r.bank_account_id,r.linked_bank_id),\n          'transaction_currency',COALESCE(r.transaction_currency,r.linked_currency),\n          'currency_code',COALESCE(r.currency_code,r.linked_currency),'functional_currency',COALESCE(r.functional_currency,'IDR'),\n          'bank_account_currency',COALESCE(r.bank_account_currency,r.linked_currency),\n          'payment_currency',COALESCE(r.payment_currency,r.linked_currency),\n          'exchange_rate',COALESCE(r.exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)),\n        'Unique typed reconciliation link proves receipt bank and currency'\n      WHERE r.bank_account_id IS NULL OR r.transaction_currency IS NULL OR r.currency_code IS NULL\n         OR r.functional_currency IS NULL OR r.bank_account_currency IS NULL OR r.payment_currency IS NULL\n         OR (r.linked_currency='IDR' AND r.exchange_rate IS NULL);\n      UPDATE public.receipt_vouchers SET bank_account_id=COALESCE(bank_account_id,r.linked_bank_id),\n        currency_code=COALESCE(currency_code,r.linked_currency),\n        transaction_currency=COALESCE(transaction_currency,r.linked_currency),functional_currency=COALESCE(functional_currency,'IDR'),\n        bank_account_currency=COALESCE(bank_account_currency,r.linked_currency),payment_currency=COALESCE(payment_currency,r.linked_currency),\n        exchange_rate=COALESCE(exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)\n      WHERE id=r.id;\n      IF r.linked_currency='USD' AND r.exchange_rate IS NULL THEN\n        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n        VALUES(v_run,'receipt',r.id,r.voucher_number,ARRAY['exchange_rate'],'USD receipt has no stored historical rate','Authoritative USD-to-IDR rate and rate source/date');\n      END IF;\n      IF (r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id)\n         OR (r.transaction_currency IS NOT NULL AND upper(r.transaction_currency)<>r.linked_currency) THEN\n        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n        VALUES(v_run,'receipt',r.id,r.voucher_number,\n          ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id THEN 'bank_account_id' END,\n            CASE WHEN r.transaction_currency IS NOT NULL AND upper(r.transaction_currency)<>r.linked_currency THEN 'transaction_currency' END],NULL),\n          'Stored receipt metadata conflicts with its unique reconciliation bank line; neither side was overwritten',\n          'Accountant confirmation of the correct receiving bank and transaction currency');\n      END IF;\n    ELSE\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'receipt',r.id,r.voucher_number,ARRAY['bank_account_id','transaction_currency'],'Typed links do not prove one bank account','Correct receiving bank account and transaction currency');\n    END IF;\n  END LOOP;\n\n  -- Payment voucher links now use the same typed-FK contract as every other\n  -- Finance document. Existing payment amounts and rates are retained.\n  FOR r IN\n    SELECT pv.id,pv.voucher_number,pv.bank_account_id,pv.payment_method,pv.payment_currency,pv.transaction_currency,\n      pv.currency_code,pv.functional_currency,pv.bank_account_currency,pv.exchange_rate,\n      (array_agg(DISTINCT bsl.bank_account_id))[1] AS linked_bank_id,\n      min(upper(COALESCE(bsl.currency,ba.currency))) AS linked_currency,\n      count(DISTINCT bsl.bank_account_id) AS bank_count\n    FROM public.payment_vouchers pv\n    JOIN public.bank_statement_lines bsl ON bsl.matched_payment_id=pv.id\n    LEFT JOIN public.bank_accounts ba ON ba.id=bsl.bank_account_id\n    GROUP BY pv.id\n  LOOP\n    IF r.bank_count=1 AND r.linked_currency IN ('IDR','USD') THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      SELECT v_run,'payment',r.id,r.voucher_number,\n        ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NULL THEN 'bank_account_id' END,\n          CASE WHEN r.payment_currency IS NULL THEN 'payment_currency' END,\n          CASE WHEN r.transaction_currency IS NULL THEN 'transaction_currency' END,\n          CASE WHEN r.currency_code IS NULL THEN 'currency_code' END,\n          CASE WHEN r.functional_currency IS NULL THEN 'functional_currency' END,\n          CASE WHEN r.bank_account_currency IS NULL THEN 'bank_account_currency' END,\n          CASE WHEN r.linked_currency='IDR' AND r.exchange_rate IS NULL THEN 'exchange_rate' END],NULL),\n        jsonb_build_object('bank_account_id',r.bank_account_id,'payment_currency',r.payment_currency,\n          'transaction_currency',r.transaction_currency,'currency_code',r.currency_code,\n          'functional_currency',r.functional_currency,'bank_account_currency',r.bank_account_currency,'exchange_rate',r.exchange_rate),\n        jsonb_build_object('bank_account_id',COALESCE(r.bank_account_id,r.linked_bank_id),\n          'payment_currency',COALESCE(r.payment_currency,r.linked_currency),\n          'transaction_currency',COALESCE(r.transaction_currency,r.linked_currency),\n          'currency_code',COALESCE(r.currency_code,r.linked_currency),'functional_currency',COALESCE(r.functional_currency,'IDR'),\n          'bank_account_currency',COALESCE(r.bank_account_currency,r.linked_currency),\n          'exchange_rate',COALESCE(r.exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)),\n        'Unique typed reconciliation link proves payment bank and currency'\n      WHERE r.bank_account_id IS NULL OR r.payment_currency IS NULL OR r.transaction_currency IS NULL\n         OR r.currency_code IS NULL OR r.functional_currency IS NULL OR r.bank_account_currency IS NULL\n         OR (r.linked_currency='IDR' AND r.exchange_rate IS NULL);\n      UPDATE public.payment_vouchers SET bank_account_id=COALESCE(bank_account_id,r.linked_bank_id),\n        payment_currency=COALESCE(payment_currency,r.linked_currency),currency_code=COALESCE(currency_code,r.linked_currency),\n        transaction_currency=COALESCE(transaction_currency,r.linked_currency),functional_currency=COALESCE(functional_currency,'IDR'),\n        bank_account_currency=COALESCE(bank_account_currency,r.linked_currency),\n        exchange_rate=COALESCE(exchange_rate,CASE WHEN r.linked_currency='IDR' THEN 1 END)\n      WHERE id=r.id;\n      IF r.linked_currency='USD' AND r.exchange_rate IS NULL THEN\n        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n        VALUES(v_run,'payment',r.id,r.voucher_number,ARRAY['exchange_rate'],'USD payment has no stored historical rate','Authoritative USD-to-IDR rate and rate source/date');\n      END IF;\n      IF (r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id)\n         OR (r.payment_currency IS NOT NULL AND upper(r.payment_currency)<>r.linked_currency) THEN\n        INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n        VALUES(v_run,'payment',r.id,r.voucher_number,\n          ARRAY_REMOVE(ARRAY[CASE WHEN r.bank_account_id IS NOT NULL AND r.bank_account_id<>r.linked_bank_id THEN 'bank_account_id' END,\n            CASE WHEN r.payment_currency IS NOT NULL AND upper(r.payment_currency)<>r.linked_currency THEN 'payment_currency' END],NULL),\n          'Stored payment metadata conflicts with its unique reconciliation bank line; neither side was overwritten',\n          'Accountant confirmation of the correct paying bank and payment currency');\n      END IF;\n    ELSE\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'payment',r.id,r.voucher_number,ARRAY['bank_account_id','transaction_currency'],'Journal links do not prove one bank account','Correct paying bank account and transaction currency');\n    END IF;\n  END LOOP;\n\n  -- Restore missing native document-to-journal links only when exactly one\n  -- active JE identifies the document by source_module + reference_id.\n  FOR r IN\n    SELECT rv.id,rv.voucher_number,(array_agg(je.id ORDER BY je.created_at))[1] AS resolved_je,count(je.id) AS je_count\n    FROM public.receipt_vouchers rv JOIN public.journal_entries je\n      ON je.source_module='receipt' AND je.reference_id=rv.id AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false\n    WHERE rv.journal_entry_id IS NULL GROUP BY rv.id\n  LOOP\n    IF r.je_count=1 THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      VALUES(v_run,'receipt',r.id,r.voucher_number,ARRAY['journal_entry_id'],jsonb_build_object('journal_entry_id',NULL),jsonb_build_object('journal_entry_id',r.resolved_je),'One active native receipt journal proves the missing link');\n      UPDATE public.receipt_vouchers SET journal_entry_id=r.resolved_je WHERE id=r.id;\n    ELSE\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'receipt',r.id,r.voucher_number,ARRAY['journal_entry_id'],'More than one active receipt journal identifies this document','Accountant selection of the canonical active journal');\n    END IF;\n  END LOOP;\n\n  FOR r IN\n    SELECT pv.id,pv.voucher_number,(array_agg(je.id ORDER BY je.created_at))[1] AS resolved_je,count(je.id) AS je_count\n    FROM public.payment_vouchers pv JOIN public.journal_entries je\n      ON je.source_module='payment' AND je.reference_id=pv.id AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false\n    WHERE pv.journal_entry_id IS NULL GROUP BY pv.id\n  LOOP\n    IF r.je_count=1 THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      VALUES(v_run,'payment',r.id,r.voucher_number,ARRAY['journal_entry_id'],jsonb_build_object('journal_entry_id',NULL),jsonb_build_object('journal_entry_id',r.resolved_je),'One active native payment journal proves the missing link');\n      UPDATE public.payment_vouchers SET journal_entry_id=r.resolved_je WHERE id=r.id;\n    ELSE\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'payment',r.id,r.voucher_number,ARRAY['journal_entry_id'],'More than one active payment journal identifies this document','Accountant selection of the canonical active journal');\n    END IF;\n  END LOOP;\n\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n  SELECT v_run,'receipt',rv.id,rv.voucher_number,ARRAY['journal_entry_id'],\n    'Posted receipt has no uniquely identifiable active journal','Correct active Journal Entry or accountant-authorised reposting'\n  FROM public.receipt_vouchers rv\n  WHERE rv.is_posted=true AND rv.journal_entry_id IS NULL\n    AND NOT EXISTS(SELECT 1 FROM public.journal_entries je WHERE je.source_module='receipt' AND je.reference_id=rv.id\n      AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false);\n\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n  SELECT v_run,'payment',pv.id,pv.voucher_number,ARRAY['journal_entry_id'],\n    'Posted payment has no uniquely identifiable active journal','Correct active Journal Entry or accountant-authorised reposting'\n  FROM public.payment_vouchers pv\n  WHERE pv.is_posted=true AND pv.journal_entry_id IS NULL\n    AND NOT EXISTS(SELECT 1 FROM public.journal_entries je WHERE je.source_module='payment' AND je.reference_id=pv.id\n      AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false);\n\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n  SELECT v_run,'expense',fe.id,fe.voucher_number,ARRAY['active journal'],\n    CASE WHEN count(je.id)=0 THEN 'Approved expense has no active journal' ELSE 'Approved expense has more than one active journal' END,\n    CASE WHEN count(je.id)=0 THEN 'Accountant-authorised posting through the native Expense workflow' ELSE 'Accountant selection/reversal of duplicate active journals' END\n  FROM public.finance_expenses fe\n  LEFT JOIN public.journal_entries je ON je.source_module='expenses'\n    AND (je.reference_id=fe.id OR je.reference_number='EXP-'||fe.id::text)\n    AND je.is_posted=true AND COALESCE(je.is_reversed,false)=false\n  WHERE fe.approval_status='approved'\n  GROUP BY fe.id HAVING count(je.id)<>1;\n\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n  SELECT v_run,'bank_reconciliation',b.id,b.reference,ARRAY['document link','journal link'],\n    'Bank line is marked matched/recorded but has no document or Journal Entry link',\n    'Correct source document or reset the line to Unmatched'\n  FROM public.bank_statement_lines b\n  WHERE b.reconciliation_status IN('matched','recorded') AND b.matched_entry_id IS NULL\n    AND b.matched_expense_id IS NULL AND b.matched_receipt_id IS NULL AND b.matched_payment_id IS NULL\n    AND b.matched_fund_transfer_id IS NULL AND b.matched_petty_cash_id IS NULL AND b.matched_tax_payment_id IS NULL;\n\n  -- If a document already owns a journal but the reverse source ID is absent,\n  -- the FK itself proves reference_id. Mismatches are exceptions, never fixed.\n  FOR r IN\n    SELECT je.id,je.entry_number,je.source_module,je.reference_id,rv.id AS source_id\n    FROM public.receipt_vouchers rv JOIN public.journal_entries je ON je.id=rv.journal_entry_id\n    WHERE (je.source_module IS NULL OR je.source_module='receipt')\n      AND (je.source_module IS NULL OR je.reference_id IS NULL OR je.reference_id<>rv.id)\n  LOOP\n    IF (r.reference_id IS NULL OR r.reference_id=r.source_id) AND (r.source_module IS NULL OR r.source_module='receipt') THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      VALUES(v_run,'journal',r.id,r.entry_number,\n        ARRAY_REMOVE(ARRAY[CASE WHEN r.source_module IS NULL THEN 'source_module' END,\n          CASE WHEN r.reference_id IS NULL THEN 'reference_id' END],NULL),\n        jsonb_build_object('source_module',r.source_module,'reference_id',r.reference_id),\n        jsonb_build_object('source_module','receipt','reference_id',r.source_id),'Receipt journal_entry_id proves reverse source identity');\n      UPDATE public.journal_entries SET source_module=COALESCE(source_module,'receipt'),reference_id=r.source_id WHERE id=r.id;\n    ELSE\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['reference_id'],'Journal source ID conflicts with owning receipt','Accountant confirmation of the correct source document');\n    END IF;\n  END LOOP;\n\n  FOR r IN\n    SELECT je.id,je.entry_number,je.source_module,je.reference_id,pv.id AS source_id\n    FROM public.payment_vouchers pv JOIN public.journal_entries je ON je.id=pv.journal_entry_id\n    WHERE (je.source_module IS NULL OR je.source_module='payment')\n      AND (je.source_module IS NULL OR je.reference_id IS NULL OR je.reference_id<>pv.id)\n  LOOP\n    IF (r.reference_id IS NULL OR r.reference_id=r.source_id) AND (r.source_module IS NULL OR r.source_module='payment') THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      VALUES(v_run,'journal',r.id,r.entry_number,\n        ARRAY_REMOVE(ARRAY[CASE WHEN r.source_module IS NULL THEN 'source_module' END,\n          CASE WHEN r.reference_id IS NULL THEN 'reference_id' END],NULL),\n        jsonb_build_object('source_module',r.source_module,'reference_id',r.reference_id),\n        jsonb_build_object('source_module','payment','reference_id',r.source_id),'Payment journal_entry_id proves reverse source identity');\n      UPDATE public.journal_entries SET source_module=COALESCE(source_module,'payment'),reference_id=r.source_id WHERE id=r.id;\n    ELSE\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['reference_id'],'Journal source ID conflicts with owning payment','Accountant confirmation of the correct source document');\n    END IF;\n  END LOOP;\n\n  -- Director Loan correction is safe only when narration explicitly proves it.\n  FOR r IN SELECT je.id,je.entry_number,jel.id AS line_id,jel.account_id\n    FROM public.journal_entries je JOIN public.journal_entry_lines jel ON jel.journal_entry_id=je.id\n    JOIN public.chart_of_accounts coa ON coa.id=jel.account_id\n    WHERE je.source_module='bank_reconciliation' AND coa.code='2210' AND jel.credit>0\n      AND lower(COALESCE(je.description,'')) ~ '(director|owner) loan' LOOP\n    IF EXISTS(SELECT 1 FROM public.chart_of_accounts WHERE code='2220' AND is_active=true AND COALESCE(is_header,false)=false) THEN\n      INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n      SELECT v_run,'journal',r.id,r.entry_number,ARRAY['credit_account_id'],jsonb_build_object('account_id',r.account_id),jsonb_build_object('account_id',id),'Narration explicitly identifies Director/Owner Loan; native mapping is 2220'\n      FROM public.chart_of_accounts WHERE code='2220' AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1;\n      UPDATE public.journal_entry_lines SET account_id=(SELECT id FROM public.chart_of_accounts WHERE code='2220' AND is_active=true AND COALESCE(is_header,false)=false LIMIT 1) WHERE id=r.line_id;\n    ELSE\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'journal',r.id,r.entry_number,ARRAY['credit_account_id'],'Director/Owner Loan is certain but account 2220 is unavailable','Activate/create the approved posting account 2220');\n    END IF;\n  END LOOP;\n\n  -- Explicit exceptions for unresolved metadata; never guess.\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n  SELECT v_run,'expense',id,voucher_number,\n    ARRAY_REMOVE(ARRAY[CASE WHEN transaction_currency IS NULL THEN 'transaction_currency' END,\n      CASE WHEN functional_currency IS NULL THEN 'functional_currency' END,CASE WHEN currency_code IS NULL THEN 'currency_code' END,\n      CASE WHEN exchange_rate IS NULL THEN 'exchange_rate' END,CASE WHEN payment_method IS NULL THEN 'payment_method' END,\n      CASE WHEN bank_account_id IS NULL AND payment_method='bank_transfer' THEN 'bank_account_id' END],NULL),\n    'No unique authoritative relationship exists in stored data','Transaction currency, historical exchange rate with source/date, exact payment method, and/or paying bank account'\n  FROM public.finance_expenses\n  WHERE transaction_currency IS NULL OR functional_currency IS NULL OR currency_code IS NULL OR exchange_rate IS NULL\n     OR payment_method IS NULL OR (bank_account_id IS NULL AND payment_method='bank_transfer');\n\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n  SELECT v_run,'receipt',id,voucher_number,\n    ARRAY_REMOVE(ARRAY[CASE WHEN transaction_currency IS NULL THEN 'transaction_currency' END,\n      CASE WHEN functional_currency IS NULL THEN 'functional_currency' END,CASE WHEN currency_code IS NULL THEN 'currency_code' END,\n      CASE WHEN exchange_rate IS NULL THEN 'exchange_rate' END,\n      CASE WHEN payment_method IS NULL THEN 'payment_method' END,\n      CASE WHEN bank_account_id IS NULL AND payment_method='bank_transfer' THEN 'bank_account_id' END],NULL),\n    'No unique authoritative relationship exists in stored receipt data',\n    'Transaction currency, historical rate with source/date, exact payment method, and/or receiving bank account'\n  FROM public.receipt_vouchers\n  WHERE transaction_currency IS NULL OR functional_currency IS NULL OR currency_code IS NULL OR exchange_rate IS NULL\n     OR payment_method IS NULL OR (bank_account_id IS NULL AND payment_method='bank_transfer');\n\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n  SELECT v_run,'payment',id,voucher_number,\n    ARRAY_REMOVE(ARRAY[CASE WHEN transaction_currency IS NULL THEN 'transaction_currency' END,\n      CASE WHEN functional_currency IS NULL THEN 'functional_currency' END,CASE WHEN currency_code IS NULL THEN 'currency_code' END,\n      CASE WHEN exchange_rate IS NULL THEN 'exchange_rate' END,\n      CASE WHEN payment_method IS NULL THEN 'payment_method' END,\n      CASE WHEN bank_account_id IS NULL AND payment_method='bank_transfer' THEN 'bank_account_id' END],NULL),\n    'No unique authoritative relationship exists in stored payment data',\n    'Transaction currency, historical rate with source/date, exact payment method, and/or paying bank account'\n  FROM public.payment_vouchers\n  WHERE transaction_currency IS NULL OR functional_currency IS NULL OR currency_code IS NULL OR exchange_rate IS NULL\n     OR payment_method IS NULL OR (bank_account_id IS NULL AND payment_method='bank_transfer');\n\n  INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n  SELECT v_run,'journal',id,entry_number,\n    ARRAY_REMOVE(ARRAY[CASE WHEN source_module IS NULL THEN 'source_module' END,\n      CASE WHEN source_module='bank_reconciliation' AND transaction_currency IS NULL THEN 'transaction_currency' END,\n      CASE WHEN source_module='bank_reconciliation' AND transaction_currency='USD' AND exchange_rate IS NULL THEN 'exchange_rate' END],NULL),\n    'Journal metadata cannot be derived from a unique stored source relationship',\n    'Correct source module/document and/or authoritative historical currency rate'\n  FROM public.journal_entries\n  WHERE source_module IS NULL OR (source_module='bank_reconciliation' AND (transaction_currency IS NULL OR (transaction_currency='USD' AND exchange_rate IS NULL)));\n\n  -- Classify every remaining scanned row as an explicit, reasoned skip so the\n  -- run totals reconcile exactly to the scan population.\n  INSERT INTO public.finance_historical_repair_exceptions(\n    run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required,status)\n  SELECT v_run,c.document_type,c.document_id,c.document_number,ARRAY[]::text[],\n    'No missing or inconsistent deterministic metadata was found','None','skipped'\n  FROM (\n    SELECT 'expense'::text document_type,id document_id,voucher_number::text document_number FROM public.finance_expenses\n    UNION ALL SELECT 'receipt',id,voucher_number::text FROM public.receipt_vouchers\n    UNION ALL SELECT 'payment',id,voucher_number::text FROM public.payment_vouchers\n    UNION ALL SELECT 'fund_transfer',id,transfer_number::text FROM public.fund_transfers\n    UNION ALL SELECT 'journal',id,entry_number::text FROM public.journal_entries\n    UNION ALL SELECT 'bank_reconciliation',id,reference::text FROM public.bank_statement_lines\n  ) c\n  WHERE NOT EXISTS(SELECT 1 FROM public.finance_historical_repair_items i\n    WHERE i.run_id=v_run AND i.document_type=c.document_type AND i.document_id=c.document_id)\n    AND NOT EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e\n    WHERE e.run_id=v_run AND e.document_type=c.document_type AND e.document_id=c.document_id);\n\n  UPDATE public.finance_historical_repair_runs SET completed_at=now(),total_records_scanned=v_scanned,\n    records_repaired=(SELECT count(DISTINCT (i.document_type,i.document_id))\n      FROM public.finance_historical_repair_items i WHERE i.run_id=v_run\n        AND NOT EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e\n          WHERE e.run_id=v_run AND e.status='manual_review' AND e.document_type=i.document_type AND e.document_id=i.document_id)),\n    records_partially_repaired=(SELECT count(DISTINCT (i.document_type,i.document_id))\n      FROM public.finance_historical_repair_items i WHERE i.run_id=v_run\n        AND EXISTS(SELECT 1 FROM public.finance_historical_repair_exceptions e\n          WHERE e.run_id=v_run AND e.status='manual_review' AND e.document_type=i.document_type AND e.document_id=i.document_id)),\n    records_manual_review=(SELECT count(DISTINCT (document_type,document_id)) FROM public.finance_historical_repair_exceptions WHERE run_id=v_run AND status='manual_review'),\n    records_skipped=(SELECT count(DISTINCT (document_type,document_id)) FROM public.finance_historical_repair_exceptions WHERE run_id=v_run AND status='skipped')\n  WHERE id=v_run;\n  RETURN v_run;\nEND;\n$$","--\n-- Name: safe_delete_bank_statement_lines(\\"uuid\\", \\"date\\", \\"date\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"safe_delete_bank_statement_lines\\"(\\"p_bank_account_id\\" \\"uuid\\", \\"p_start_date\\" \\"date\\", \\"p_end_date\\" \\"date\\") RETURNS json\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_total_count      INTEGER;\nv_reconciled_count INTEGER;\nv_deletable_count  INTEGER;\nv_deleted_count    INTEGER;\nv_role             text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot delete bank statement lines', v_role;\nEND IF;\n\nSELECT COUNT(*) INTO v_total_count FROM bank_statement_lines\nWHERE bank_account_id = p_bank_account_id\nAND transaction_date BETWEEN p_start_date AND p_end_date;\n\nSELECT COUNT(*) INTO v_reconciled_count FROM bank_statement_lines\nWHERE bank_account_id = p_bank_account_id\nAND transaction_date BETWEEN p_start_date AND p_end_date\nAND reconciliation_status IN ('matched','recorded','suggested');\n\nv_deletable_count := v_total_count - v_reconciled_count;\n\nIF v_reconciled_count > 0 THEN\nRETURN json_build_object(\n'success', false,\n'error', 'Cannot delete: ' || v_reconciled_count || ' transaction(s) are reconciled',\n'total_count', v_total_count, 'reconciled_count', v_reconciled_count,\n'deletable_count', v_deletable_count, 'deleted_count', 0\n);\nEND IF;\n\nDELETE FROM bank_statement_lines\nWHERE bank_account_id = p_bank_account_id\nAND transaction_date BETWEEN p_start_date AND p_end_date\nAND reconciliation_status = 'unmatched';\nGET DIAGNOSTICS v_deleted_count = ROW_COUNT;\n\nRETURN json_build_object(\n'success', true, 'total_count', v_total_count, 'reconciled_count', v_reconciled_count,\n'deletable_count', v_deletable_count, 'deleted_count', v_deleted_count\n);\nEND;\n$$","--\n-- Name: save_and_link_finance_expense_atomic(\\"uuid\\", \\"jsonb\\", \\"uuid\\", numeric, \\"uuid\\", boolean); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_and_link_finance_expense_atomic\\"(\\"p_expense_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_payload\\" \\"jsonb\\" DEFAULT '{}'::\\"jsonb\\", \\"p_bank_statement_line_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_allocation_amount\\" numeric DEFAULT NULL::numeric, \\"p_approved_by\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_apply_salary_advances\\" boolean DEFAULT false) RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_expense_id uuid;\n  v_journal_id uuid;\n  v_journal_count integer;\n  v_allocation_count integer;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n\n  IF p_bank_statement_line_id IS NULL THEN\n    RAISE EXCEPTION 'A bank statement line is required for atomic expense linking';\n  END IF;\n\n  -- Serialize concurrent attempts against both the source document and bank\n  -- line before any document or accounting write is made.\n  PERFORM 1\n    FROM public.bank_statement_lines\n   WHERE id = p_bank_statement_line_id\n   FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line not found'; END IF;\n\n  IF p_expense_id IS NOT NULL THEN\n    PERFORM 1 FROM public.finance_expenses WHERE id = p_expense_id FOR UPDATE;\n    IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\n    IF EXISTS (\n      SELECT 1 FROM public.finance_expenses\n       WHERE id = p_expense_id AND approval_status = 'approved'\n    ) THEN\n      RAISE EXCEPTION 'Approved expenses must use the canonical approved-edit command';\n    END IF;\n  END IF;\n\n  -- Existing document command: a new/unlinked expense remains pending until\n  -- the approval call below. Any later failure rolls this insert/update back.\n  -- The selected statement makes this a controlled bank-linked save.\n  PERFORM set_config('app.expense_atomic_bank_link','on',true);\n  v_expense_id := public.save_finance_expense(p_expense_id, p_payload);\n\n  IF p_apply_salary_advances THEN\n    PERFORM public.apply_salary_advances_to_expense(v_expense_id, true);\n  END IF;\n\n  -- Existing approval command invokes the one canonical expense journal\n  -- builder through trigger_auto_post_expense_accounting.\n  PERFORM public.approve_finance_expense(\n    v_expense_id,\n    COALESCE(p_approved_by, auth.uid())\n  );\n\n  SELECT count(*), (array_agg(id ORDER BY created_at DESC, id DESC))[1]\n    INTO v_journal_count, v_journal_id\n    FROM public.journal_entries\n   WHERE source_module IN ('expense', 'expenses')\n     AND (\n       reference_id = v_expense_id\n       OR reference_number = 'EXP-' || v_expense_id::text\n     )\n     AND is_posted = true\n     AND NOT COALESCE(is_reversed, false);\n  IF v_journal_count <> 1 THEN\n    RAISE EXCEPTION 'Expense bank link requires exactly one active effective journal';\n  END IF;\n\n  -- Existing canonical link command validates bank account, currency, amount,\n  -- journal bank side, split-allocation capacity, and duplicate allocation.\n  PERFORM public.link_bank_statement_line(\n    p_bank_statement_line_id,\n    'expense',\n    v_expense_id,\n    'supplier',\n    p_allocation_amount\n  );\n\n  SELECT count(*) INTO v_allocation_count\n    FROM public.bank_statement_allocations\n   WHERE bank_statement_line_id = p_bank_statement_line_id\n     AND document_type = 'expense'\n     AND document_id = v_expense_id\n     AND payment_kind = 'supplier'\n     AND journal_entry_id = v_journal_id;\n  IF v_allocation_count <> 1 THEN\n    RAISE EXCEPTION 'Expense bank link did not preserve exactly one canonical allocation';\n  END IF;\n\n  PERFORM public.recalculate_expense_payment_state(v_expense_id);\n  RETURN v_expense_id;\nEND;\n$$","--\n-- Name: save_bank_linked_finance_journal(\\"uuid\\", \\"text\\", \\"text\\", \\"text\\", \\"text\\", numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_bank_linked_finance_journal\\"(\\"p_bank_line_id\\" \\"uuid\\", \\"p_description\\" \\"text\\", \\"p_counter_account_code\\" \\"text\\", \\"p_bank_side\\" \\"text\\", \\"p_transaction_currency\\" \\"text\\", \\"p_exchange_rate\\" numeric) RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_line public.bank_statement_lines%ROWTYPE; v_bank_coa uuid; v_counter_coa uuid;\n  v_amount numeric; v_journal uuid; v_lines jsonb; v_result jsonb;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  SELECT * INTO v_line FROM public.bank_statement_lines WHERE id=p_bank_line_id FOR UPDATE;\n  IF NOT FOUND OR v_line.matched_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Bank statement line is missing or already linked'; END IF;\n  SELECT coa_id INTO v_bank_coa FROM public.bank_accounts WHERE id=v_line.bank_account_id AND is_active=true AND upper(currency)=upper(p_transaction_currency);\n  SELECT id INTO v_counter_coa FROM public.chart_of_accounts WHERE code=p_counter_account_code AND is_active=true AND COALESCE(is_header,false)=false;\n  IF v_bank_coa IS NULL OR v_counter_coa IS NULL THEN RAISE EXCEPTION 'Bank or counter account is not configured'; END IF;\n  IF p_bank_side='debit' THEN v_amount:=COALESCE(v_line.credit_amount,0);\n  ELSIF p_bank_side='credit' THEN v_amount:=COALESCE(v_line.debit_amount,0);\n  ELSE RAISE EXCEPTION 'Bank side must be debit or credit'; END IF;\n  IF v_amount<=0 THEN RAISE EXCEPTION 'Bank statement direction does not match this journal action'; END IF;\n  v_lines:=CASE WHEN p_bank_side='debit' THEN jsonb_build_array(\n      jsonb_build_object('account_id',v_bank_coa,'description',p_description,'debit',v_amount,'credit',0),\n      jsonb_build_object('account_id',v_counter_coa,'description',p_description,'debit',0,'credit',v_amount))\n    ELSE jsonb_build_array(\n      jsonb_build_object('account_id',v_counter_coa,'description',p_description,'debit',v_amount,'credit',0),\n      jsonb_build_object('account_id',v_bank_coa,'description',p_description,'debit',0,'credit',v_amount)) END;\n  v_journal:=public.save_finance_journal(NULL,v_line.transaction_date,p_description,v_lines,upper(p_transaction_currency),p_exchange_rate);\n  v_result:=public.link_bank_statement_line(p_bank_line_id,'journal',v_journal,'supplier');\n  RETURN jsonb_build_object('document_id',v_journal,'journal_entry_id',v_journal,'link',v_result);\nEND $$","--\n-- Name: save_batch_inventory_v1(\\"uuid\\", \\"jsonb\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_batch_inventory_v1\\"(\\"p_batch_id\\" \\"uuid\\", \\"p_payload\\" \\"jsonb\\", \\"p_operation_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_batch public.batches%ROWTYPE;\n  v_existing_batch_id uuid;\n  v_actor uuid := auth.uid();\n  v_delta numeric;\n  v_previous_context text;\n  v_unit_price numeric;\n  v_is_local boolean;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'warehouse', 'manager']) THEN\n    RAISE EXCEPTION 'Permission denied for canonical batch save';\n  END IF;\n  IF p_operation_id IS NULL THEN\n    RAISE EXCEPTION 'operation_id is required';\n  END IF;\n  IF p_batch_id IS NULL AND NULLIF(p_payload->>'make_id', '') IS NULL THEN\n    RAISE EXCEPTION 'Make / Manufacturer is required for new inventory batches';\n  END IF;\n  IF NULLIF(p_payload->>'make_id', '') IS NOT NULL\n     AND NOT EXISTS (\n       SELECT 1 FROM public.product_sources\n        WHERE id = (p_payload->>'make_id')::uuid\n          AND product_id = (p_payload->>'product_id')::uuid\n     ) THEN\n    RAISE EXCEPTION 'Selected Make / Manufacturer does not belong to the selected product';\n  END IF;\n\n  v_unit_price := COALESCE((p_payload->>'import_price')::numeric, 0);\n  v_is_local := NULLIF(p_payload->>'import_container_id', '') IS NULL;\n\n  IF p_batch_id IS NULL THEN\n    SELECT batch_id INTO v_existing_batch_id\n      FROM public.inventory_transactions\n     WHERE operation_id = p_operation_id AND transaction_type = 'purchase';\n    IF FOUND THEN\n      RETURN jsonb_build_object('success', true, 'batch_id', v_existing_batch_id, 'idempotent_retry', true);\n    END IF;\n\n    v_previous_context := current_setting('app.canonical_stock_engine', true);\n    PERFORM set_config('app.canonical_stock_engine', 'on', true);\n    INSERT INTO public.batches (\n      batch_number, product_id, make_id, import_container_id, import_date,\n      import_quantity, current_stock, packaging_details, import_price,\n      import_price_usd, exchange_rate_usd_to_idr, duty_percent, duty_charges,\n      duty_charge_type, freight_charges, freight_charge_type, other_charges,\n      other_charge_type, expiry_date, is_active, created_by,\n      cost_per_unit, landed_cost_per_unit, final_landed_cost, import_price_per_unit\n    ) VALUES (\n      p_payload->>'batch_number', (p_payload->>'product_id')::uuid,\n      NULLIF(p_payload->>'make_id', '')::uuid,\n      NULLIF(p_payload->>'import_container_id', '')::uuid,\n      (p_payload->>'import_date')::date, (p_payload->>'import_quantity')::numeric,\n      0, NULLIF(p_payload->>'packaging_details', ''),\n      v_unit_price,\n      NULLIF(p_payload->>'import_price_usd', '')::numeric,\n      NULLIF(p_payload->>'exchange_rate_usd_to_idr', '')::numeric,\n      COALESCE(NULLIF(p_payload->>'duty_percent', '')::numeric, 0),\n      COALESCE(NULLIF(p_payload->>'duty_charges', '')::numeric, 0),\n      COALESCE(NULLIF(p_payload->>'duty_charge_type', ''), 'fixed'),\n      COALESCE(NULLIF(p_payload->>'freight_charges', '')::numeric, 0),\n      COALESCE(NULLIF(p_payload->>'freight_charge_type', ''), 'fixed'),\n      COALESCE(NULLIF(p_payload->>'other_charges', '')::numeric, 0),\n      COALESCE(NULLIF(p_payload->>'other_charge_type', ''), 'fixed'),\n      NULLIF(p_payload->>'expiry_date', '')::date, true, v_actor,\n      v_unit_price,\n      CASE WHEN v_is_local THEN v_unit_price ELSE 0 END,\n      CASE WHEN v_is_local THEN v_unit_price * (p_payload->>'import_quantity')::numeric ELSE 0 END,\n      v_unit_price\n    ) RETURNING * INTO v_batch;\n    PERFORM set_config('app.canonical_stock_engine', COALESCE(v_previous_context, ''), true);\n    PERFORM public.post_inventory_movement(\n      p_operation_id, v_batch.product_id, v_batch.id, 'purchase',\n      v_batch.import_quantity, v_batch.import_date, v_batch.batch_number,\n      'batch_creation', v_batch.id, 'Canonical Batch Creation: ' || v_batch.batch_number,\n      v_actor, 0, v_batch.import_quantity\n    );\n    RETURN jsonb_build_object('success', true, 'batch_id', v_batch.id);\n  END IF;\n\n  SELECT * INTO v_batch FROM public.batches WHERE id = p_batch_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Batch not found'; END IF;\n  IF (p_payload->>'product_id')::uuid IS DISTINCT FROM v_batch.product_id\n     AND EXISTS (SELECT 1 FROM public.inventory_transactions WHERE batch_id = p_batch_id AND transaction_type <> 'purchase') THEN\n    RAISE EXCEPTION 'Cannot change product after batch stock movement exists';\n  END IF;\n\n  v_delta := (p_payload->>'import_quantity')::numeric - v_batch.import_quantity;\n  UPDATE public.batches SET\n    batch_number = p_payload->>'batch_number', product_id = (p_payload->>'product_id')::uuid,\n    make_id = NULLIF(p_payload->>'make_id', '')::uuid,\n    import_container_id = NULLIF(p_payload->>'import_container_id', '')::uuid,\n    import_date = (p_payload->>'import_date')::date, import_quantity = (p_payload->>'import_quantity')::numeric,\n    packaging_details = NULLIF(p_payload->>'packaging_details', ''),\n    import_price = COALESCE((p_payload->>'import_price')::numeric, import_price),\n    import_price_usd = NULLIF(p_payload->>'import_price_usd', '')::numeric,\n    exchange_rate_usd_to_idr = NULLIF(p_payload->>'exchange_rate_usd_to_idr', '')::numeric,\n    duty_percent = COALESCE(NULLIF(p_payload->>'duty_percent', '')::numeric, 0),\n    duty_charges = COALESCE(NULLIF(p_payload->>'duty_charges', '')::numeric, 0),\n    duty_charge_type = COALESCE(NULLIF(p_payload->>'duty_charge_type', ''), duty_charge_type),\n    freight_charges = COALESCE(NULLIF(p_payload->>'freight_charges', '')::numeric, 0),\n    freight_charge_type = COALESCE(NULLIF(p_payload->>'freight_charge_type', ''), freight_charge_type),\n    other_charges = COALESCE(NULLIF(p_payload->>'other_charges', '')::numeric, 0),\n    other_charge_type = COALESCE(NULLIF(p_payload->>'other_charge_type', ''), other_charge_type),\n    expiry_date = NULLIF(p_payload->>'expiry_date', '')::date,\n    cost_per_unit = CASE\n      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL\n        THEN COALESCE((p_payload->>'import_price')::numeric, import_price)\n      ELSE cost_per_unit\n    END,\n    landed_cost_per_unit = CASE\n      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL\n        THEN COALESCE((p_payload->>'import_price')::numeric, import_price)\n      ELSE landed_cost_per_unit\n    END,\n    final_landed_cost = CASE\n      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL\n        THEN COALESCE((p_payload->>'import_price')::numeric, import_price) * (p_payload->>'import_quantity')::numeric\n      ELSE final_landed_cost\n    END,\n    import_price_per_unit = COALESCE((p_payload->>'import_price')::numeric, import_price),\n    updated_at = now()\n  WHERE id = p_batch_id;\n\n  IF v_delta <> 0 THEN\n    PERFORM public.post_inventory_movement(\n      p_operation_id, (p_payload->>'product_id')::uuid, p_batch_id, 'adjustment',\n      v_delta, CURRENT_DATE, p_payload->>'batch_number', 'batch_edit', p_batch_id,\n      format('Canonical Batch Edit quantity correction: %s to %s', v_batch.import_quantity, (p_payload->>'import_quantity')::numeric),\n      v_actor, v_batch.current_stock, v_batch.current_stock + v_delta\n    );\n  END IF;\n  RETURN jsonb_build_object('success', true, 'batch_id', p_batch_id);\nEND;\n$$","--\n-- Name: save_finance_capital_contribution(\\"jsonb\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_finance_capital_contribution\\"(\\"p_payload\\" \\"jsonb\\", \\"p_bank_statement_line_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_id uuid:=gen_random_uuid(); v_number text; v_je uuid; v_line public.bank_statement_lines%ROWTYPE; v_amount numeric; v_date date;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_date:=(p_payload->>'voucher_date')::date; v_amount:=(p_payload->>'amount')::numeric;\n  IF v_amount<=0 THEN RAISE EXCEPTION 'Capital contribution amount must be positive'; END IF;\n  IF p_bank_statement_line_id IS NOT NULL THEN\n    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id FOR UPDATE;\n    IF NOT FOUND OR COALESCE(v_line.credit_amount,0)<>v_amount OR v_line.bank_account_id<>(p_payload->>'bank_account_id')::uuid THEN RAISE EXCEPTION 'Bank statement line does not exactly match this capital contribution'; END IF;\n    IF v_line.matched_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Bank statement line is already linked'; END IF;\n  END IF;\n  v_number:=public.next_capital_contribution_number(v_date);\n  INSERT INTO public.capital_contributions(id,voucher_number,voucher_date,director_id,contribution_type,bank_account_id,amount,description,created_by,\n    transaction_currency,functional_currency,exchange_rate,bank_account_currency,bank_statement_line_id)\n  VALUES(v_id,v_number,v_date,NULL,'bank_transfer',(p_payload->>'bank_account_id')::uuid,v_amount,COALESCE(p_payload->>'description',''),\n    COALESCE(NULLIF(p_payload->>'created_by','')::uuid,auth.uid()),upper(p_payload->>'transaction_currency'),'IDR',(p_payload->>'exchange_rate')::numeric,\n    upper(p_payload->>'transaction_currency'),p_bank_statement_line_id) RETURNING journal_entry_id INTO v_je;\n  IF p_bank_statement_line_id IS NOT NULL THEN PERFORM public._link_native_bank_document(p_bank_statement_line_id,v_je,'Capital Contribution - '||v_number); END IF;\n  RETURN jsonb_build_object('id',v_id,'voucher_number',v_number,'journal_entry_id',v_je);\nEND $$","--\n-- Name: save_finance_exception_corrections(\\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_finance_exception_corrections\\"(\\"p_corrections\\" \\"jsonb\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  c jsonb;\n  v_document_type text;\n  v_document_id uuid;\n  v_exception_id bigint;\n  v_reason text;\n  v_journal_id uuid;\n  v_line_id uuid;\n  v_account_id uuid;\n  v_bank_id uuid;\n  v_bank_coa_id uuid;\n  v_bank_currency text;\n  v_tax_code_id uuid;\n  v_tax_type text;\n  v_exchange_rate numeric;\n  v_before_lines jsonb;\n  v_after_lines jsonb;\n  v_resolved boolean := false;\n  v_saved integer := 0;\n  v_resolved_count integer := 0;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  IF jsonb_typeof(p_corrections) <> 'array' OR jsonb_array_length(p_corrections)=0 THEN\n    RAISE EXCEPTION 'Select at least one correction before saving';\n  END IF;\n\n  -- Existing source triggers read these flags. Metadata corrections must never\n  -- regenerate journals or recalculate historical debit/credit values.\n  PERFORM set_config('app.finance_historical_repair','on',true);\n  PERFORM set_config('app.finance_metadata_repair','on',true);\n\n  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections)\n  LOOP\n    v_document_type := c->>'document_type';\n    v_document_id := (c->>'document_id')::uuid;\n    v_exception_id := NULLIF(c->>'exception_id','')::bigint;\n    v_line_id := NULLIF(c->>'journal_line_id','')::uuid;\n    v_bank_id := NULLIF(c->>'bank_account_id','')::uuid;\n    v_tax_code_id := NULLIF(c->>'tax_code_id','')::uuid;\n    v_exchange_rate := NULLIF(c->>'exchange_rate','')::numeric;\n    v_resolved := false;\n\n    IF v_exception_id IS NOT NULL THEN\n      SELECT reason INTO v_reason\n      FROM public.finance_historical_repair_exceptions\n      WHERE id=v_exception_id AND document_type=v_document_type\n        AND document_id=v_document_id AND status='manual_review'\n      FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'This exception is no longer open'; END IF;\n    ELSE\n      v_reason := 'Live Finance verification failure';\n      IF NOT EXISTS (\n        SELECT 1 FROM public.finance_exception_correction_dashboard d\n        WHERE d.document_type=v_document_type AND d.document_id=v_document_id\n          AND d.status='Verification failed'\n      ) THEN RAISE EXCEPTION 'This verification failure is no longer open'; END IF;\n    END IF;\n\n    SELECT CASE v_document_type\n      WHEN 'journal' THEN v_document_id\n      WHEN 'receipt' THEN (SELECT journal_entry_id FROM public.receipt_vouchers WHERE id=v_document_id)\n      WHEN 'payment' THEN (SELECT journal_entry_id FROM public.payment_vouchers WHERE id=v_document_id)\n      WHEN 'fund_transfer' THEN (SELECT journal_entry_id FROM public.fund_transfers WHERE id=v_document_id)\n      WHEN 'loan' THEN (SELECT journal_entry_id FROM public.loans WHERE id=v_document_id)\n      WHEN 'loan_transaction' THEN (SELECT journal_entry_id FROM public.loan_transactions WHERE id=v_document_id)\n      WHEN 'loan_repayment' THEN (SELECT journal_entry_id FROM public.loan_transactions WHERE id=v_document_id)\n      WHEN 'capital_contribution' THEN (SELECT journal_entry_id FROM public.capital_contributions WHERE id=v_document_id)\n      WHEN 'tax_payment' THEN (SELECT journal_entry_id FROM public.tax_payments WHERE id=v_document_id)\n      WHEN 'sales_invoice' THEN (SELECT journal_entry_id FROM public.sales_invoices WHERE id=v_document_id)\n      WHEN 'purchase_invoice' THEN (SELECT journal_entry_id FROM public.purchase_invoices WHERE id=v_document_id)\n      WHEN 'bank_reconciliation' THEN (SELECT matched_entry_id FROM public.bank_statement_lines WHERE id=v_document_id)\n      WHEN 'expense' THEN (SELECT id FROM public.journal_entries j WHERE j.source_module IN('expense','expenses')\n        AND (j.reference_id=v_document_id OR j.reference_number='EXP-'||v_document_id::text)\n        AND COALESCE(j.is_reversed,false)=false ORDER BY j.is_posted DESC,j.created_at DESC LIMIT 1)\n      WHEN 'petty_cash' THEN (SELECT id FROM public.journal_entries j WHERE j.source_module='petty_cash'\n        AND j.reference_id=v_document_id AND COALESCE(j.is_reversed,false)=false ORDER BY j.is_posted DESC,j.created_at DESC LIMIT 1)\n    END INTO v_journal_id;\n\n    IF v_journal_id IS NOT NULL THEN\n      SELECT jsonb_agg(jsonb_build_object('id',id,'debit',debit,'credit',credit) ORDER BY id)\n      INTO v_before_lines FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;\n    END IF;\n\n    IF v_bank_id IS NOT NULL THEN\n      SELECT ba.coa_id,upper(ba.currency) INTO v_bank_coa_id,v_bank_currency\n      FROM public.bank_accounts ba JOIN public.chart_of_accounts coa ON coa.id=ba.coa_id\n      WHERE ba.id=v_bank_id AND ba.is_active=true AND coa.is_active=true AND COALESCE(coa.is_header,false)=false;\n      IF v_bank_coa_id IS NULL THEN RAISE EXCEPTION 'Selected bank has no active posting account'; END IF;\n    END IF;\n\n    v_account_id := COALESCE(NULLIF(c->>'account_id','')::uuid,\n      NULLIF(c->>'loan_account_id','')::uuid,\n      NULLIF(c->>'capital_account_id','')::uuid,\n      CASE WHEN v_bank_id IS NOT NULL THEN v_bank_coa_id END);\n    IF v_account_id IS NOT NULL AND NOT EXISTS (\n      SELECT 1 FROM public.chart_of_accounts WHERE id=v_account_id AND is_active=true AND COALESCE(is_header,false)=false\n    ) THEN RAISE EXCEPTION 'Selected account is not an active posting account'; END IF;\n\n    IF v_tax_code_id IS NOT NULL THEN\n      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id AND is_active=true;\n      IF v_tax_type IS NULL THEN RAISE EXCEPTION 'Selected tax category is not active'; END IF;\n    END IF;\n\n    -- Source metadata. Every assignment is to an existing row; no insert,\n    -- delete, posting, numbering, date, narration, or amount field is allowed.\n    IF v_document_type='expense' THEN\n      UPDATE public.finance_expenses SET\n        expense_category=COALESCE(NULLIF(c->>'expense_category',''),expense_category),\n        payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),\n        bank_account_id=COALESCE(v_bank_id,bank_account_id),\n        pph_code_id=COALESCE(v_tax_code_id,pph_code_id),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),\n        currency_code=COALESCE(v_bank_currency,currency_code),\n        payment_currency=COALESCE(v_bank_currency,payment_currency),\n        bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),\n        functional_currency=COALESCE(functional_currency,'IDR')\n      WHERE id=v_document_id;\n    ELSIF v_document_type='receipt' THEN\n      UPDATE public.receipt_vouchers SET payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),\n        bank_account_id=COALESCE(v_bank_id,bank_account_id),exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency_code=COALESCE(v_bank_currency,currency_code),\n        payment_currency=COALESCE(v_bank_currency,payment_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),\n        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;\n    ELSIF v_document_type='payment' THEN\n      UPDATE public.payment_vouchers SET payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),\n        bank_account_id=COALESCE(v_bank_id,bank_account_id),pph_code_id=COALESCE(v_tax_code_id,pph_code_id),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency_code=COALESCE(v_bank_currency,currency_code),\n        payment_currency=COALESCE(v_bank_currency,payment_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),\n        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;\n    ELSIF v_document_type='loan' THEN\n      UPDATE public.loans SET bank_account_id=COALESCE(v_bank_id,bank_account_id),\n        coa_id=COALESCE(NULLIF(c->>'loan_account_id','')::uuid,coa_id),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency=COALESCE(v_bank_currency,currency),\n        bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),functional_currency=COALESCE(functional_currency,'IDR')\n      WHERE id=v_document_id;\n    ELSIF v_document_type IN ('loan_transaction','loan_repayment') THEN\n      UPDATE public.loan_transactions SET bank_account_id=COALESCE(v_bank_id,bank_account_id),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),\n        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;\n    ELSIF v_document_type='capital_contribution' THEN\n      UPDATE public.capital_contributions SET bank_account_id=COALESCE(v_bank_id,bank_account_id),\n        contribution_type=COALESCE(NULLIF(c->>'expense_category',''),contribution_type),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),\n        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;\n    ELSIF v_document_type='petty_cash' THEN\n      UPDATE public.petty_cash_transactions SET expense_category=COALESCE(NULLIF(c->>'expense_category',''),expense_category),\n        bank_account_id=COALESCE(v_bank_id,bank_account_id) WHERE id=v_document_id;\n    ELSIF v_document_type='tax_payment' THEN\n      UPDATE public.tax_payments SET bank_account_id=COALESCE(v_bank_id,bank_account_id),\n        tax_type=COALESCE(v_tax_type,tax_type) WHERE id=v_document_id;\n    ELSIF v_document_type='sales_invoice' AND NULLIF(c->>'faktur_pajak_number','') IS NOT NULL THEN\n      UPDATE public.sales_invoices SET faktur_pajak_number=c->>'faktur_pajak_number' WHERE id=v_document_id;\n    ELSIF v_document_type='purchase_invoice' AND NULLIF(c->>'faktur_pajak_number','') IS NOT NULL THEN\n      UPDATE public.purchase_invoices SET faktur_pajak_number=c->>'faktur_pajak_number' WHERE id=v_document_id;\n    ELSIF v_document_type='bank_reconciliation' AND NULLIF(c->>'payment_type','') IS NOT NULL THEN\n      UPDATE public.bank_statement_lines SET payment_kind=c->>'payment_type' WHERE id=v_document_id;\n    END IF;\n\n    IF v_journal_id IS NOT NULL THEN\n      UPDATE public.journal_entries SET\n        source_module=COALESCE(NULLIF(c->>'document_classification',''),source_module),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),\n        functional_currency=COALESCE(functional_currency,'IDR'),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        amounts_are_functional=COALESCE(amounts_are_functional,true)\n      WHERE id=v_journal_id;\n    END IF;\n\n    IF v_account_id IS NOT NULL THEN\n      IF v_line_id IS NULL OR NOT EXISTS (\n        SELECT 1 FROM public.journal_entry_lines WHERE id=v_line_id AND journal_entry_id=v_journal_id\n      ) THEN RAISE EXCEPTION 'The account line can no longer be identified safely'; END IF;\n      UPDATE public.journal_entry_lines SET account_id=v_account_id WHERE id=v_line_id;\n    END IF;\n\n    IF v_journal_id IS NOT NULL THEN\n      SELECT jsonb_agg(jsonb_build_object('id',id,'debit',debit,'credit',credit) ORDER BY id)\n      INTO v_after_lines FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;\n      IF v_before_lines IS DISTINCT FROM v_after_lines THEN\n        RAISE EXCEPTION 'Correction cancelled because a debit or credit value changed';\n      END IF;\n    END IF;\n\n    -- Resolve only when the specific historical problem is now disproved.\n    IF v_reason ILIKE '%missing Faktur Pajak%' THEN\n      v_resolved := EXISTS(SELECT 1 FROM public.sales_invoices WHERE id=v_document_id AND NULLIF(btrim(faktur_pajak_number),'') IS NOT NULL)\n        OR EXISTS(SELECT 1 FROM public.purchase_invoices WHERE id=v_document_id AND NULLIF(btrim(faktur_pajak_number),'') IS NOT NULL);\n    ELSIF v_reason ILIKE '%no historical transaction-date rate%' OR v_reason ILIKE '%no authoritative historical rate%' THEN\n      v_resolved := v_exchange_rate IS NOT NULL AND v_exchange_rate>0;\n    ELSIF v_reason ILIKE '%does not use the Expense bank account%' OR v_reason ILIKE '%does not post to this bank account%' THEN\n      v_resolved := EXISTS(SELECT 1 FROM public.journal_entry_lines jl JOIN public.bank_accounts ba ON ba.coa_id=jl.account_id\n        WHERE jl.journal_entry_id=v_journal_id AND ba.id=COALESCE(v_bank_id,(SELECT bank_account_id FROM public.bank_statement_lines WHERE id=v_document_id)));\n    ELSIF v_reason ILIKE 'No unique authoritative relationship%' THEN\n      IF v_document_type='expense' THEN v_resolved := EXISTS(SELECT 1 FROM public.finance_expenses x WHERE x.id=v_document_id\n        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL\n        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL));\n      ELSIF v_document_type='receipt' THEN v_resolved := EXISTS(SELECT 1 FROM public.receipt_vouchers x WHERE x.id=v_document_id\n        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL\n        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL));\n      ELSIF v_document_type='payment' THEN v_resolved := EXISTS(SELECT 1 FROM public.payment_vouchers x WHERE x.id=v_document_id\n        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL\n        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL)); END IF;\n    ELSIF v_reason ILIKE '%metadata conflicts%' THEN\n      v_resolved := v_bank_id IS NOT NULL;\n    ELSIF v_reason ILIKE '%Journal metadata cannot be derived%' THEN\n      v_resolved := EXISTS(SELECT 1 FROM public.journal_entries WHERE id=v_journal_id AND source_module IS NOT NULL\n        AND transaction_currency IS NOT NULL AND functional_currency IS NOT NULL\n        AND (transaction_currency='IDR' OR exchange_rate IS NOT NULL));\n    END IF;\n\n    IF v_exception_id IS NOT NULL AND v_resolved THEN\n      UPDATE public.finance_historical_repair_exceptions SET status='resolved' WHERE id=v_exception_id;\n      v_resolved_count := v_resolved_count + 1;\n    END IF;\n\n    INSERT INTO public.audit_logs(table_name,action_type,record_id,old_values,new_values,changed_fields)\n    VALUES('finance_exception_correction_dashboard','update',v_document_id,\n      jsonb_build_object('exception_id',v_exception_id,'journal_lines',v_before_lines),\n      jsonb_build_object('correction',c,'journal_lines',v_after_lines,'resolved',v_resolved),\n      ARRAY['finance_metadata','account_classification','exception_status']);\n    v_saved := v_saved + 1;\n  END LOOP;\n\n  RETURN jsonb_build_object('saved',v_saved,'resolved',v_resolved_count,'refresh_required',true);\nEND;\n$$","--\n-- Name: save_finance_exception_corrections_v2(\\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_finance_exception_corrections_v2\\"(\\"p_corrections\\" \\"jsonb\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  c jsonb;\n  v_type text;\n  v_id uuid;\n  v_exception bigint;\n  v_journal uuid;\n  v_line uuid;\n  v_supplier uuid;\n  v_customer uuid;\n  v_from_bank uuid;\n  v_to_bank uuid;\n  v_from_old uuid;\n  v_to_old uuid;\n  v_from_old_coa uuid;\n  v_to_old_coa uuid;\n  v_from_new_coa uuid;\n  v_to_new_coa uuid;\n  v_from_alias text;\n  v_to_alias text;\n  v_from_currency text;\n  v_to_currency text;\n  v_link_type text;\n  v_link_id uuid;\n  v_result jsonb;\n  v_resolved_ids jsonb := '[]'::jsonb;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  IF jsonb_typeof(p_corrections)<>'array' OR jsonb_array_length(p_corrections)=0 THEN\n    RAISE EXCEPTION 'Select at least one correction before saving';\n  END IF;\n  PERFORM set_config('app.finance_historical_repair','on',true);\n  PERFORM set_config('app.finance_metadata_repair','on',true);\n\n  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections) LOOP\n    v_type:=c->>'document_type';\n    v_id:=(c->>'document_id')::uuid;\n    v_exception:=NULLIF(c->>'exception_id','')::bigint;\n    v_journal:=NULLIF(c->>'journal_entry_id','')::uuid;\n    v_line:=NULLIF(c->>'journal_line_id','')::uuid;\n    v_supplier:=NULLIF(c->>'supplier_id','')::uuid;\n    v_customer:=NULLIF(c->>'customer_id','')::uuid;\n    v_from_bank:=NULLIF(c->>'from_bank_account_id','')::uuid;\n    v_to_bank:=NULLIF(c->>'to_bank_account_id','')::uuid;\n    v_link_type:=NULLIF(c->>'linked_document_type','');\n    v_link_id:=NULLIF(c->>'linked_document_id','')::uuid;\n\n    IF NOT EXISTS (SELECT 1 FROM public.finance_exception_correction_dashboard x WHERE x.document_type=v_type AND x.document_id=v_id) THEN\n      RAISE EXCEPTION 'This exception is no longer open';\n    END IF;\n    IF v_supplier IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.suppliers WHERE id=v_supplier AND COALESCE(is_active,true)) THEN\n      RAISE EXCEPTION 'Selected supplier is not active';\n    END IF;\n    IF v_customer IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customers WHERE id=v_customer) THEN\n      RAISE EXCEPTION 'Selected customer does not exist';\n    END IF;\n\n    IF v_type='expense' THEN\n      UPDATE public.finance_expenses SET\n        expense_type=COALESCE(NULLIF(c->>'expense_subcategory',''),expense_type),\n        supplier_id=COALESCE(v_supplier,supplier_id),\n        payment_reference=COALESCE(NULLIF(c->>'reference',''),payment_reference)\n      WHERE id=v_id;\n    ELSIF v_type='receipt' THEN\n      UPDATE public.receipt_vouchers SET customer_id=COALESCE(v_customer,customer_id),\n        reference_number=COALESCE(NULLIF(c->>'reference',''),reference_number) WHERE id=v_id;\n    ELSIF v_type='payment' THEN\n      UPDATE public.payment_vouchers SET supplier_id=COALESCE(v_supplier,supplier_id),\n        reference_number=COALESCE(NULLIF(c->>'reference',''),reference_number) WHERE id=v_id;\n    ELSIF v_type='loan' THEN\n      UPDATE public.loans SET loan_type=COALESCE(NULLIF(c->>'finance_classification',''),loan_type) WHERE id=v_id;\n    ELSIF v_type='capital_contribution' THEN\n      UPDATE public.capital_contributions SET contribution_type=COALESCE(NULLIF(c->>'finance_classification',''),contribution_type) WHERE id=v_id;\n    END IF;\n\n    IF v_line IS NOT NULL THEN\n      UPDATE public.journal_entry_lines SET\n        supplier_id=COALESCE(v_supplier,supplier_id),customer_id=COALESCE(v_customer,customer_id)\n      WHERE id=v_line AND journal_entry_id=v_journal;\n    END IF;\n\n    IF v_type='fund_transfer' AND (v_from_bank IS NOT NULL OR v_to_bank IS NOT NULL) THEN\n      SELECT from_bank_account_id,to_bank_account_id,journal_entry_id INTO v_from_old,v_to_old,v_journal\n      FROM public.fund_transfers WHERE id=v_id FOR UPDATE;\n      v_from_bank:=COALESCE(v_from_bank,v_from_old);\n      v_to_bank:=COALESCE(v_to_bank,v_to_old);\n      IF v_from_bank=v_to_bank THEN RAISE EXCEPTION 'From Bank and To Bank must be different'; END IF;\n      SELECT coa_id,COALESCE(alias,account_name,bank_name),upper(currency) INTO v_from_new_coa,v_from_alias,v_from_currency\n        FROM public.bank_accounts WHERE id=v_from_bank AND is_active;\n      SELECT coa_id,COALESCE(alias,account_name,bank_name),upper(currency) INTO v_to_new_coa,v_to_alias,v_to_currency\n        FROM public.bank_accounts WHERE id=v_to_bank AND is_active;\n      SELECT coa_id INTO v_from_old_coa FROM public.bank_accounts WHERE id=v_from_old;\n      SELECT coa_id INTO v_to_old_coa FROM public.bank_accounts WHERE id=v_to_old;\n      IF v_from_new_coa IS NULL OR v_to_new_coa IS NULL THEN RAISE EXCEPTION 'Both transfer banks need active Bank Master posting accounts'; END IF;\n      UPDATE public.journal_entry_lines SET account_id=v_from_new_coa\n        WHERE journal_entry_id=v_journal AND account_id=v_from_old_coa AND COALESCE(credit,0)>0;\n      UPDATE public.journal_entry_lines SET account_id=v_to_new_coa\n        WHERE journal_entry_id=v_journal AND account_id=v_to_old_coa AND COALESCE(debit,0)>0;\n      UPDATE public.fund_transfers SET from_bank_account_id=v_from_bank,to_bank_account_id=v_to_bank WHERE id=v_id;\n    END IF;\n\n    IF v_type='bank_reconciliation' AND v_link_id IS NOT NULL THEN\n      IF v_link_type IS NULL THEN RAISE EXCEPTION 'Select the linked document type'; END IF;\n      PERFORM public.link_bank_statement_line(v_id,v_link_type,v_link_id,COALESCE(NULLIF(c->>'payment_type',''),'supplier'));\n    END IF;\n  END LOOP;\n\n  -- Existing RPC owns GL classification, bank master mapping, tax/currency\n  -- metadata, balance protection, audit logging and reason-specific verification.\n  v_result:=public.save_finance_exception_corrections(p_corrections);\n\n  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections) LOOP\n    v_exception:=NULLIF(c->>'exception_id','')::bigint;\n    IF v_exception IS NOT NULL AND COALESCE((c->>'confirm_resolved')::boolean,false)\n       AND EXISTS (\n         SELECT 1 FROM jsonb_each_text(c) x\n         WHERE x.key IN ('expense_category','expense_subcategory','account_id','bank_account_id','from_bank_account_id',\n           'to_bank_account_id','loan_account_id','capital_account_id','tax_code_id','payment_type','document_classification',\n           'exchange_rate','faktur_pajak_number','supplier_id','customer_id','reference','finance_classification','linked_document_id')\n           AND NULLIF(x.value,'') IS NOT NULL\n       ) THEN\n      UPDATE public.finance_historical_repair_exceptions SET status='resolved'\n      WHERE id=v_exception AND status='manual_review';\n    END IF;\n    IF NOT EXISTS (\n      SELECT 1 FROM public.finance_exception_correction_dashboard x\n      WHERE x.document_type=c->>'document_type' AND x.document_id=(c->>'document_id')::uuid\n    ) THEN v_resolved_ids:=v_resolved_ids || jsonb_build_array(c->>'row_id'); END IF;\n  END LOOP;\n\n  RETURN v_result || jsonb_build_object('resolved_row_ids',v_resolved_ids,'verification_refreshed',true);\nEND;\n$$","--\n-- Name: save_finance_expense(\\"uuid\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_finance_expense\\"(\\"p_expense_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_payload\\" \\"jsonb\\" DEFAULT '{}'::\\"jsonb\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_id uuid;\n  v_date date := COALESCE((p_payload->>'expense_date')::date, current_date);\n  v_bank_id uuid := NULLIF(p_payload->>'bank_account_id', '')::uuid;\n  v_bank_currency text;\n  v_currency text;\n  v_rate numeric;\n  v_docs text[];\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  IF COALESCE((p_payload->>'amount')::numeric, 0) <= 0 THEN\n    RAISE EXCEPTION 'Expense amount must be greater than zero';\n  END IF;\n  IF NULLIF(p_payload->>'expense_category', '') IS NULL THEN\n    RAISE EXCEPTION 'Expense category is required';\n  END IF;\n\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id = v_bank_id;\n  v_currency := upper(COALESCE(NULLIF(p_payload->>'transaction_currency',''), v_bank_currency, 'IDR'));\n  IF v_currency NOT IN ('IDR','USD') THEN RAISE EXCEPTION 'Unsupported expense currency %', v_currency; END IF;\n  v_rate := COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric, 0), CASE WHEN v_currency = 'IDR' THEN 1 ELSE NULL END);\n  IF v_rate IS NULL OR v_rate <= 0 THEN\n    RAISE EXCEPTION 'A positive exchange rate is required for % expenses', v_currency;\n  END IF;\n  IF v_bank_currency IS NOT NULL AND v_bank_currency <> v_currency THEN\n    RAISE EXCEPTION 'Expense currency % does not match selected bank currency %', v_currency, v_bank_currency;\n  END IF;\n\n  SELECT COALESCE(array_agg(value), ARRAY[]::text[]) INTO v_docs\n    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls', '[]'::jsonb));\n\n  IF p_expense_id IS NULL THEN\n    INSERT INTO public.finance_expenses (\n      voucher_number, expense_category, expense_type, amount, expense_date, description,\n      batch_id, import_container_id, delivery_challan_id, payment_method, bank_account_id,\n      payment_reference, paid_by, document_urls, supplier_id, staff_id, invoice_number,\n      due_date, broker_items, pib_bm_amount, pib_ppn_amount, pib_pph_amount, ppn_amount,\n      ppn_manual_override, ppn_calc_mode, dpp_amount, ppn_rate, pph_amount, pph_code_id,\n      stamp_duty_amount, fixed_asset_account_id, bank_charges_amount, approval_status,\n      created_by, currency_code, transaction_currency, functional_currency, exchange_rate,\n      bank_account_currency, payment_currency\n    ) VALUES (\n      public.next_expense_voucher_number(v_date), p_payload->>'expense_category',\n      COALESCE(NULLIF(p_payload->>'expense_type',''), 'admin'), (p_payload->>'amount')::numeric,\n      v_date, NULLIF(p_payload->>'description',''), NULLIF(p_payload->>'batch_id','')::uuid,\n      NULLIF(p_payload->>'import_container_id','')::uuid, NULLIF(p_payload->>'delivery_challan_id','')::uuid,\n      NULLIF(p_payload->>'payment_method',''), v_bank_id, NULLIF(p_payload->>'payment_reference',''),\n      NULLIF(p_payload->>'paid_by',''), NULLIF(v_docs, ARRAY[]::text[]),\n      NULLIF(p_payload->>'supplier_id','')::uuid, NULLIF(p_payload->>'staff_id','')::uuid,\n      NULLIF(p_payload->>'invoice_number',''), NULLIF(p_payload->>'due_date','')::date,\n      NULLIF(p_payload->'broker_items','null'::jsonb), NULLIF(p_payload->>'pib_bm_amount','')::numeric,\n      NULLIF(p_payload->>'pib_ppn_amount','')::numeric, NULLIF(p_payload->>'pib_pph_amount','')::numeric,\n      COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0), COALESCE((p_payload->>'ppn_manual_override')::boolean,false),\n      COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'), NULLIF(p_payload->>'dpp_amount','')::numeric,\n      COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11), COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),\n      NULLIF(p_payload->>'pph_code_id','')::uuid, COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),\n      NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,\n      COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),\n      COALESCE(NULLIF(p_payload->>'approval_status',''),'pending_approval'),\n      COALESCE(NULLIF(p_payload->>'created_by','')::uuid, auth.uid()),\n      v_currency, v_currency, 'IDR', v_rate, COALESCE(v_bank_currency,v_currency), v_currency\n    ) RETURNING id INTO v_id;\n  ELSE\n    IF EXISTS (SELECT 1 FROM public.finance_expenses WHERE id=p_expense_id AND approval_status='approved') THEN\n      RAISE EXCEPTION 'This expense is posted. Cancel Posting first to make changes.';\n    END IF;\n    UPDATE public.finance_expenses SET\n      expense_category=p_payload->>'expense_category', expense_type=COALESCE(NULLIF(p_payload->>'expense_type',''),'admin'),\n      amount=(p_payload->>'amount')::numeric, expense_date=v_date, description=NULLIF(p_payload->>'description',''),\n      batch_id=NULLIF(p_payload->>'batch_id','')::uuid, import_container_id=NULLIF(p_payload->>'import_container_id','')::uuid,\n      delivery_challan_id=NULLIF(p_payload->>'delivery_challan_id','')::uuid,\n      payment_method=NULLIF(p_payload->>'payment_method',''), bank_account_id=v_bank_id,\n      payment_reference=NULLIF(p_payload->>'payment_reference',''), paid_by=NULLIF(p_payload->>'paid_by',''),\n      document_urls=NULLIF(v_docs,ARRAY[]::text[]), supplier_id=NULLIF(p_payload->>'supplier_id','')::uuid,\n      staff_id=NULLIF(p_payload->>'staff_id','')::uuid, invoice_number=NULLIF(p_payload->>'invoice_number',''),\n      due_date=NULLIF(p_payload->>'due_date','')::date, broker_items=NULLIF(p_payload->'broker_items','null'::jsonb),\n      pib_bm_amount=NULLIF(p_payload->>'pib_bm_amount','')::numeric,\n      pib_ppn_amount=NULLIF(p_payload->>'pib_ppn_amount','')::numeric,\n      pib_pph_amount=NULLIF(p_payload->>'pib_pph_amount','')::numeric,\n      ppn_amount=COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0),\n      ppn_manual_override=COALESCE((p_payload->>'ppn_manual_override')::boolean,false),\n      ppn_calc_mode=COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'),\n      dpp_amount=NULLIF(p_payload->>'dpp_amount','')::numeric, ppn_rate=COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11),\n      pph_amount=COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0), pph_code_id=NULLIF(p_payload->>'pph_code_id','')::uuid,\n      stamp_duty_amount=COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),\n      fixed_asset_account_id=NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,\n      bank_charges_amount=COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),\n      currency_code=v_currency, transaction_currency=v_currency, functional_currency='IDR', exchange_rate=v_rate,\n      bank_account_currency=COALESCE(v_bank_currency,v_currency), payment_currency=v_currency\n    WHERE id=p_expense_id RETURNING id INTO v_id;\n  END IF;\n  RETURN v_id;\nEND;\n$$","--\n-- Name: save_finance_journal(\\"uuid\\", \\"date\\", \\"text\\", \\"jsonb\\", \\"text\\", numeric); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_finance_journal\\"(\\"p_entry_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_entry_date\\" \\"date\\" DEFAULT CURRENT_DATE, \\"p_description\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_lines\\" \\"jsonb\\" DEFAULT '[]'::\\"jsonb\\", \\"p_transaction_currency\\" \\"text\\" DEFAULT 'IDR'::\\"text\\", \\"p_exchange_rate\\" numeric DEFAULT 1) RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_id uuid;\n  v_line jsonb;\n  v_dr numeric:=0;\n  v_cr numeric:=0;\n  v_factor numeric;\n  v_num text;\n  v_i int:=0;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  p_transaction_currency:=upper(COALESCE(p_transaction_currency,'IDR'));\n  IF p_transaction_currency NOT IN ('IDR','USD') THEN RAISE EXCEPTION 'Unsupported journal currency'; END IF;\n  IF p_exchange_rate IS NULL OR p_exchange_rate<=0 OR (p_transaction_currency='USD' AND p_exchange_rate<=1) THEN\n    RAISE EXCEPTION 'A valid exchange rate is required';\n  END IF;\n  v_factor:=CASE WHEN p_transaction_currency='IDR' THEN 1 ELSE p_exchange_rate END;\n  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP\n    v_dr:=v_dr+COALESCE((v_line->>'debit')::numeric,0);\n    v_cr:=v_cr+COALESCE((v_line->>'credit')::numeric,0);\n  END LOOP;\n  IF v_dr<=0 OR abs(v_dr-v_cr)>0.01 THEN RAISE EXCEPTION 'Journal must be balanced and greater than zero'; END IF;\n\n  IF p_entry_id IS NULL THEN\n    v_num:=public.generate_journal_entry_number();\n    INSERT INTO public.journal_entries(entry_number,entry_date,description,source_module,total_debit,total_credit,\n      is_posted,posted_by,created_by,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n    VALUES(v_num,p_entry_date,NULLIF(p_description,''),'manual',round(v_dr*v_factor,2),round(v_cr*v_factor,2),\n      true,auth.uid(),auth.uid(),p_transaction_currency,'IDR',v_factor,true)\n    RETURNING id INTO v_id;\n  ELSE\n    IF NOT EXISTS(SELECT 1 FROM public.journal_entries WHERE id=p_entry_id AND source_module='manual') THEN\n      RAISE EXCEPTION 'Only manual journals can be edited';\n    END IF;\n    v_id:=p_entry_id;\n    UPDATE public.journal_entries SET entry_date=p_entry_date,description=NULLIF(p_description,''),\n      total_debit=round(v_dr*v_factor,2),total_credit=round(v_cr*v_factor,2),transaction_currency=p_transaction_currency,\n      functional_currency='IDR',exchange_rate=v_factor,amounts_are_functional=true WHERE id=v_id;\n    DELETE FROM public.journal_entry_lines WHERE journal_entry_id=v_id;\n  END IF;\n  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP\n    IF COALESCE((v_line->>'debit')::numeric,0)>0 OR COALESCE((v_line->>'credit')::numeric,0)>0 THEN\n      v_i:=v_i+1;\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,\n        transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n      VALUES(v_id,v_i,(v_line->>'account_id')::uuid,NULLIF(v_line->>'description',''),\n        round(COALESCE((v_line->>'debit')::numeric,0)*v_factor,2),\n        round(COALESCE((v_line->>'credit')::numeric,0)*v_factor,2),p_transaction_currency,\n        COALESCE((v_line->>'debit')::numeric,0),COALESCE((v_line->>'credit')::numeric,0),'IDR',v_factor);\n    END IF;\n  END LOOP;\n  RETURN v_id;\nEND;\n$$","--\n-- Name: save_finance_loan(\\"jsonb\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_finance_loan\\"(\\"p_payload\\" \\"jsonb\\", \\"p_bank_statement_line_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_id uuid := gen_random_uuid();\n  v_number text;\n  v_je uuid;\n  v_coa uuid;\n  v_line public.bank_statement_lines%ROWTYPE;\n  v_amount numeric;\n  v_date date;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_date := (p_payload->>'loan_date')::date;\n  v_amount := (p_payload->>'principal_amount')::numeric;\n\n  IF NULLIF(trim(p_payload->>'counterparty_name'), '') IS NULL OR v_amount <= 0 THEN\n    RAISE EXCEPTION 'Loan counterparty and positive principal are required';\n  END IF;\n\n  IF p_payload->>'liability_kind' = 'director_owner' THEN\n    -- The UI supplies the existing liability ledger ID selected from the COA.\n    -- Do not resolve a code or manufacture a Director/Owner account here.\n    SELECT id INTO v_coa\n    FROM public.chart_of_accounts\n    WHERE id = NULLIF(p_payload->>'liability_account_id', '')::uuid\n      AND is_active = true\n      AND COALESCE(is_header, false) = false\n      AND lower(account_type) = 'liability';\n    IF v_coa IS NULL THEN\n      RAISE EXCEPTION 'Select an existing active Director/Owner liability ledger';\n    END IF;\n    -- When the installation has an existing Director master, ensure its\n    -- configured loan ledger is exactly the selected COA. Older ledgers with\n    -- no master record remain supported without creating one.\n    IF NULLIF(p_payload->>'director_id', '') IS NOT NULL AND NOT EXISTS (\n      SELECT 1\n      FROM public.directors d\n      WHERE d.id = (p_payload->>'director_id')::uuid\n        AND d.is_active = true\n        AND COALESCE(d.is_deprecated, false) = false\n        AND d.loan_account_id = v_coa\n    ) THEN\n      RAISE EXCEPTION 'Selected Director/Owner is not configured for this loan ledger';\n    END IF;\n  ELSE\n    -- Existing ordinary-loan behaviour is intentionally unchanged.\n    SELECT id INTO v_coa\n    FROM public.chart_of_accounts\n    WHERE code = '2210' AND is_active = true AND COALESCE(is_header, false) = false\n    LIMIT 1;\n    IF v_coa IS NULL THEN\n      RAISE EXCEPTION 'Required loan liability account is not configured';\n    END IF;\n  END IF;\n\n  IF p_bank_statement_line_id IS NOT NULL THEN\n    SELECT * INTO v_line\n    FROM public.bank_statement_lines\n    WHERE id = p_bank_statement_line_id\n    FOR UPDATE;\n\n    IF NOT FOUND\n      OR COALESCE(v_line.credit_amount, 0) <> v_amount\n      OR v_line.bank_account_id <> (p_payload->>'bank_account_id')::uuid THEN\n      RAISE EXCEPTION 'Bank statement line does not exactly match this loan';\n    END IF;\n    IF v_line.matched_entry_id IS NOT NULL THEN\n      RAISE EXCEPTION 'Bank statement line is already linked';\n    END IF;\n  END IF;\n\n  v_number := public.next_loan_number(v_date);\n  INSERT INTO public.loans(\n    id, loan_number, loan_type, counterparty_name, counterparty_type,\n    principal_amount, interest_rate, loan_date, bank_account_id, coa_id,\n    currency, transaction_currency, functional_currency, exchange_rate,\n    bank_account_currency, description, created_by, bank_statement_line_id\n  )\n  VALUES (\n    v_id, v_number, 'taken', trim(p_payload->>'counterparty_name'),\n    COALESCE(NULLIF(p_payload->>'counterparty_type', ''), 'person'),\n    v_amount, 0, v_date, (p_payload->>'bank_account_id')::uuid, v_coa,\n    upper(p_payload->>'transaction_currency'), upper(p_payload->>'transaction_currency'),\n    'IDR', (p_payload->>'exchange_rate')::numeric,\n    upper(p_payload->>'transaction_currency'), COALESCE(p_payload->>'description', ''),\n    COALESCE(NULLIF(p_payload->>'created_by', '')::uuid, auth.uid()),\n    p_bank_statement_line_id\n  )\n  RETURNING journal_entry_id INTO v_je;\n\n  IF p_bank_statement_line_id IS NOT NULL THEN\n    PERFORM public._link_native_bank_document(\n      p_bank_statement_line_id,\n      v_je,\n      'Loan - ' || v_number\n    );\n  END IF;\n\n  RETURN jsonb_build_object('id', v_id, 'loan_number', v_number, 'journal_entry_id', v_je);\nEND;\n$$","--\n-- Name: save_finance_loan_repayment(\\"jsonb\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_finance_loan_repayment\\"(\\"p_payload\\" \\"jsonb\\", \\"p_bank_statement_line_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_id uuid:=gen_random_uuid(); v_number text; v_je uuid; v_line public.bank_statement_lines%ROWTYPE; v_amount numeric; v_date date;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_date:=(p_payload->>'transaction_date')::date; v_amount:=COALESCE((p_payload->>'principal_amount')::numeric,0)+COALESCE((p_payload->>'interest_amount')::numeric,0);\n  IF p_bank_statement_line_id IS NOT NULL THEN\n    SELECT * INTO v_line FROM public.bank_statement_lines WHERE id=p_bank_statement_line_id FOR UPDATE;\n    IF NOT FOUND OR COALESCE(v_line.debit_amount,0)<>v_amount OR v_line.bank_account_id<>(p_payload->>'bank_account_id')::uuid THEN RAISE EXCEPTION 'Bank statement line does not exactly match this repayment'; END IF;\n    IF v_line.matched_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Bank statement line is already linked'; END IF;\n  END IF;\n  v_number:=public.next_loan_transaction_number(v_date);\n  INSERT INTO public.loan_transactions(id,transaction_number,loan_id,transaction_type,transaction_date,amount,principal_amount,interest_amount,\n    bank_account_id,bank_statement_line_id,description,created_by,transaction_currency,functional_currency,exchange_rate,bank_account_currency)\n  VALUES(v_id,v_number,(p_payload->>'loan_id')::uuid,'repayment',v_date,v_amount,(p_payload->>'principal_amount')::numeric,\n    COALESCE((p_payload->>'interest_amount')::numeric,0),(p_payload->>'bank_account_id')::uuid,p_bank_statement_line_id,\n    COALESCE(p_payload->>'description',''),COALESCE(NULLIF(p_payload->>'created_by','')::uuid,auth.uid()),upper(p_payload->>'transaction_currency'),'IDR',\n    (p_payload->>'exchange_rate')::numeric,upper(p_payload->>'transaction_currency')) RETURNING journal_entry_id INTO v_je;\n  IF p_bank_statement_line_id IS NOT NULL THEN PERFORM public._link_native_bank_document(p_bank_statement_line_id,v_je,'Loan Repayment - '||v_number); END IF;\n  RETURN jsonb_build_object('id',v_id,'transaction_number',v_number,'journal_entry_id',v_je);\nEND $$","--\n-- Name: save_payment_voucher(\\"date\\", \\"uuid\\", \\"text\\", \\"uuid\\", \\"text\\", numeric, numeric, \\"uuid\\", \\"text\\", \\"uuid\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_payment_voucher\\"(\\"p_voucher_date\\" \\"date\\", \\"p_supplier_id\\" \\"uuid\\", \\"p_payment_method\\" \\"text\\", \\"p_bank_account_id\\" \\"uuid\\", \\"p_reference_number\\" \\"text\\", \\"p_amount\\" numeric, \\"p_pph_amount\\" numeric, \\"p_pph_code_id\\" \\"uuid\\", \\"p_description\\" \\"text\\", \\"p_created_by\\" \\"uuid\\", \\"p_allocations\\" \\"jsonb\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\nv_voucher_number text;\nBEGIN\nv_voucher_number := public.generate_voucher_number('PV');\n\nRETURN public.save_payment_voucher_with_allocations(\nNULL,\nv_voucher_number,\np_voucher_date,\np_supplier_id,\np_payment_method,\np_bank_account_id,\np_reference_number,\np_amount,\np_pph_amount,\np_pph_code_id,\np_description,\n'IDR',\n1,\nNULL,\n0,\np_created_by,\np_allocations\n);\nEND;\n$$","--\n-- Name: save_payment_voucher_command(\\"uuid\\", \\"jsonb\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_payment_voucher_command\\"(\\"p_voucher_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_payload\\" \\"jsonb\\" DEFAULT '{}'::\\"jsonb\\", \\"p_allocations\\" \\"jsonb\\" DEFAULT '[]'::\\"jsonb\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_number text;\n  v_id uuid;\n  v_date date := (p_payload->>'voucher_date')::date;\n  v_payment_currency text := upper(COALESCE(NULLIF(p_payload->>'payment_currency',''),'IDR'));\n  v_invoice_currency text := upper(COALESCE(\n    NULLIF(p_payload->>'invoice_currency',''),\n    NULLIF((SELECT COALESCE(a->>'currency',a->>'allocated_currency')\n            FROM jsonb_array_elements(COALESCE(p_allocations,'[]'::jsonb)) a\n            WHERE COALESCE(a->>'currency',a->>'allocated_currency') IS NOT NULL LIMIT 1),''),\n    v_payment_currency));\n  v_bank_currency text;\n  v_rate numeric := COALESCE(NULLIF(p_payload->>'exchange_rate','')::numeric,1);\n  v_invoice_amount numeric := COALESCE(NULLIF(p_payload->>'invoice_amount','')::numeric,\n    NULLIF(p_payload->>'amount','')::numeric,0);\n  v_payment_amount numeric := COALESCE(NULLIF(p_payload->>'payment_amount','')::numeric,\n    v_invoice_amount-COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0));\n  v_converted numeric;\n  v_actual numeric;\n  v_bank_charge numeric := COALESCE(NULLIF(p_payload->>'bank_charge','')::numeric,0);\n  v_docs text[];\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts\n   WHERE id=NULLIF(p_payload->>'bank_account_id','')::uuid;\n  v_bank_currency:=COALESCE(v_bank_currency,v_payment_currency);\n  IF v_payment_currency NOT IN('IDR','USD') OR v_invoice_currency NOT IN('IDR','USD')\n     OR v_bank_currency NOT IN('IDR','USD') OR v_rate<=0 THEN\n    RAISE EXCEPTION 'Payment currencies or exchange rate are invalid';\n  END IF;\n  v_converted:=COALESCE(NULLIF(p_payload->>'converted_amount','')::numeric,\n    v_payment_amount*CASE WHEN v_invoice_currency=v_bank_currency THEN 1 ELSE v_rate END);\n  v_actual:=COALESCE(NULLIF(p_payload->>'actual_bank_debit','')::numeric,\n    NULLIF(p_payload->>'bank_amount','')::numeric,v_converted+v_bank_charge);\n  IF v_actual<=0 AND v_invoice_amount>0 THEN RAISE EXCEPTION 'Actual bank debit must be positive'; END IF;\n  SELECT COALESCE(array_agg(value),ARRAY[]::text[]) INTO v_docs\n    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls','[]'::jsonb));\n\n  SELECT voucher_number INTO v_number FROM public.payment_vouchers WHERE id=p_voucher_id;\n  v_number:=COALESCE(v_number,public.next_payment_voucher_number(v_date));\n  v_id:=public.save_payment_voucher_with_allocations(\n    p_voucher_id=>p_voucher_id,p_voucher_number=>v_number,p_voucher_date=>v_date,\n    p_supplier_id=>NULLIF(p_payload->>'supplier_id','')::uuid,\n    p_payment_method=>p_payload->>'payment_method',\n    p_bank_account_id=>NULLIF(p_payload->>'bank_account_id','')::uuid,\n    p_reference_number=>NULLIF(p_payload->>'reference_number',''),p_amount=>v_invoice_amount,\n    p_pph_amount=>COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),\n    p_pph_code_id=>NULLIF(p_payload->>'pph_code_id','')::uuid,\n    p_description=>NULLIF(p_payload->>'description',''),\n    p_payment_currency=>v_payment_currency,p_exchange_rate=>v_rate,\n    p_bank_amount=>v_actual,p_bank_charge=>v_bank_charge,\n    p_created_by=>COALESCE(NULLIF(p_payload->>'created_by','')::uuid,auth.uid()),\n    p_allocations=>p_allocations,p_staff_id=>NULLIF(p_payload->>'staff_id','')::uuid);\n  UPDATE public.payment_vouchers SET\n    invoice_currency=v_invoice_currency,invoice_amount=v_invoice_amount,\n    payment_amount=v_payment_amount,payment_currency=v_payment_currency,\n    transaction_currency=v_invoice_currency,functional_currency='IDR',\n    exchange_rate=v_rate,bank_currency=v_bank_currency,\n    bank_account_currency=v_bank_currency,converted_amount=v_converted,\n    actual_bank_debit=v_actual,bank_amount=v_actual,\n    document_urls=NULLIF(v_docs,ARRAY[]::text[])\n  WHERE id=v_id;\n  RETURN jsonb_build_object('id',v_id,'voucher_number',v_number);\nEND;\n$$","--\n-- Name: save_payment_voucher_with_allocations(\\"uuid\\", \\"text\\", \\"date\\", \\"uuid\\", \\"text\\", \\"uuid\\", \\"text\\", numeric, numeric, \\"uuid\\", \\"text\\", \\"text\\", numeric, numeric, numeric, \\"uuid\\", \\"jsonb\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_payment_voucher_with_allocations\\"(\\"p_voucher_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_voucher_number\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_voucher_date\\" \\"date\\" DEFAULT NULL::\\"date\\", \\"p_supplier_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_payment_method\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_bank_account_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_reference_number\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_amount\\" numeric DEFAULT 0, \\"p_pph_amount\\" numeric DEFAULT 0, \\"p_pph_code_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_description\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_payment_currency\\" \\"text\\" DEFAULT 'IDR'::\\"text\\", \\"p_exchange_rate\\" numeric DEFAULT 1, \\"p_bank_amount\\" numeric DEFAULT NULL::numeric, \\"p_bank_charge\\" numeric DEFAULT 0, \\"p_created_by\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_allocations\\" \\"jsonb\\" DEFAULT '[]'::\\"jsonb\\", \\"p_staff_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_voucher_id    UUID;\n  v_alloc         JSONB;\n  v_invoice_id    UUID;\n  v_expense_id    UUID;\n  v_alloc_amount  NUMERIC;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  IF p_supplier_id IS NULL AND p_staff_id IS NULL THEN\n    RAISE EXCEPTION 'Payment voucher needs a payee: supplier or staff';\n  END IF;\n\n  -- ── Create or update the voucher header ──\n  IF p_voucher_id IS NULL THEN\n    INSERT INTO payment_vouchers (\n      voucher_number, voucher_date, supplier_id, staff_id, payment_method,\n      bank_account_id, reference_number, amount, pph_amount, pph_code_id,\n      description, payment_currency, exchange_rate,\n      bank_amount, bank_charge, created_by\n    ) VALUES (\n      p_voucher_number, p_voucher_date, p_supplier_id, p_staff_id, p_payment_method,\n      p_bank_account_id, p_reference_number, p_amount, p_pph_amount, p_pph_code_id,\n      p_description, p_payment_currency, p_exchange_rate,\n      p_bank_amount, p_bank_charge, p_created_by\n    ) RETURNING id INTO v_voucher_id;\n  ELSE\n    v_voucher_id := p_voucher_id;\n\n    IF EXISTS (SELECT 1 FROM payment_vouchers WHERE id = v_voucher_id AND is_posted = TRUE) THEN\n      RAISE EXCEPTION 'Cannot edit: % is posted. Cancel Posting first to make changes.', p_voucher_number;\n    END IF;\n\n    UPDATE payment_vouchers SET\n      voucher_date      = p_voucher_date,\n      supplier_id       = p_supplier_id,\n      staff_id          = p_staff_id,\n      payment_method    = p_payment_method,\n      bank_account_id   = p_bank_account_id,\n      reference_number  = p_reference_number,\n      amount            = p_amount,\n      pph_amount        = p_pph_amount,\n      pph_code_id       = p_pph_code_id,\n      description       = p_description,\n      payment_currency  = p_payment_currency,\n      exchange_rate     = p_exchange_rate,\n      bank_amount       = p_bank_amount,\n      bank_charge       = p_bank_charge,\n      updated_at        = NOW()\n    WHERE id = v_voucher_id;\n  END IF;\n\n  -- ── Replace all allocations ──\n  DELETE FROM voucher_allocations WHERE payment_voucher_id = v_voucher_id;\n\n  FOR v_alloc IN SELECT value FROM jsonb_array_elements(p_allocations) AS value\n  LOOP\n    v_alloc_amount := COALESCE((v_alloc->>'amount')::NUMERIC, 0);\n    IF v_alloc_amount <= 0 THEN\n      CONTINUE;\n    END IF;\n\n    v_invoice_id := NULLIF(v_alloc->>'invoice_id', '')::UUID;\n    v_expense_id := NULLIF(v_alloc->>'finance_expense_id', '')::UUID;\n\n    IF v_invoice_id IS NOT NULL THEN\n      INSERT INTO voucher_allocations (\n        payment_voucher_id, purchase_invoice_id,\n        allocated_amount, allocated_currency, voucher_type\n      ) VALUES (\n        v_voucher_id, v_invoice_id, v_alloc_amount,\n        COALESCE(v_alloc->>'currency', 'IDR'), 'payment'\n      );\n    ELSIF v_expense_id IS NOT NULL THEN\n      INSERT INTO voucher_allocations (\n        payment_voucher_id, finance_expense_id,\n        allocated_amount, allocated_currency, voucher_type\n      ) VALUES (\n        v_voucher_id, v_expense_id, v_alloc_amount,\n        COALESCE(v_alloc->>'currency', 'IDR'), 'payment'\n      );\n      -- paid_amount on finance_expenses updated by trg_sync_expense_payment_state\n    END IF;\n  END LOOP;\n\n  RETURN v_voucher_id;\nEND;\n$$","--\n-- Name: save_payment_voucher_with_purpose(\\"uuid\\", \\"jsonb\\", \\"jsonb\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_payment_voucher_with_purpose\\"(\\"p_voucher_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_payload\\" \\"jsonb\\" DEFAULT '{}'::\\"jsonb\\", \\"p_allocations\\" \\"jsonb\\" DEFAULT '[]'::\\"jsonb\\", \\"p_payment_purpose\\" \\"text\\" DEFAULT 'general'::\\"text\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_result jsonb;\n  v_id uuid;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n\n  IF p_payment_purpose NOT IN (\n    'general',\n    'salary_advance',\n    'salary_advance_settlement'\n  ) THEN\n    RAISE EXCEPTION 'Unsupported payment purpose %', p_payment_purpose;\n  END IF;\n\n  v_result := public.save_payment_voucher_command(\n    p_voucher_id,\n    p_payload,\n    p_allocations\n  );\n  v_id := (v_result->>'id')::uuid;\n\n  UPDATE public.payment_vouchers\n     SET payment_purpose = p_payment_purpose,\n         salary_advance_status = CASE p_payment_purpose\n           WHEN 'salary_advance' THEN 'outstanding'\n           ELSE 'not_applicable'\n         END\n   WHERE id = v_id;\n\n  RETURN v_result;\nEND;\n$$","--\n-- Name: save_purchase_invoice(\\"uuid\\", \\"jsonb\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_purchase_invoice\\"(\\"p_invoice_id\\" \\"uuid\\", \\"p_invoice_data\\" \\"jsonb\\", \\"p_items\\" \\"jsonb\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $_$\n  DECLARE\n    v_invoice_id        UUID;\n    v_je_id             UUID;\n    v_je_number         TEXT;\n    v_ap_account_id     UUID;\n    v_ppn_account_id    UUID;\n    v_bm_account_id     UUID;\n    v_account_id        UUID;\n    v_item              JSONB;\n    v_line_number       INTEGER;\n    v_invoice_date      DATE;\n    v_invoice_number    TEXT;\n    v_supplier_id       UUID;\n    v_total_amount      NUMERIC(15,2);\n    v_tax_amount        NUMERIC(15,2);\n    v_stamp_duty_amount NUMERIC(15,2);\n    v_created_by        UUID;\n    v_item_type         TEXT;\n    v_line_total        NUMERIC(15,2);\n    v_item_id           UUID;\n    v_po_id             UUID;\n    v_currency          TEXT;\n    v_rate              NUMERIC;\n  BEGIN\n    v_created_by        := auth.uid();\n    v_invoice_date      := (p_invoice_data->>'invoice_date')::DATE;\n    v_invoice_number    := p_invoice_data->>'invoice_number';\n    v_total_amount      := (p_invoice_data->>'total_amount')::NUMERIC(15,2);\n    v_tax_amount        := COALESCE((p_invoice_data->>'tax_amount')::NUMERIC(15,2), 0);\n    v_stamp_duty_amount := COALESCE((p_invoice_data->>'stamp_duty_amount')::NUMERIC(15,2), 0);\n    v_supplier_id       := (p_invoice_data->>'supplier_id')::UUID;\n    v_po_id             := NULLIF(p_invoice_data->>'purchase_order_id', '')::UUID;\n    v_currency := upper(coalesce(p_invoice_data->>'currency', 'IDR'));\n    v_rate := CASE WHEN v_currency = 'IDR' THEN 1 ELSE NULLIF((p_invoice_data->>'exchange_rate')::NUMERIC, 0) END;\n    IF v_currency <> 'IDR' AND (v_rate IS NULL OR v_rate <= 1) THEN\n      RAISE EXCEPTION 'Purchase invoice % requires a valid exchange rate greater than 1', v_invoice_number;\n    END IF;\n\n    SELECT id INTO v_ap_account_id  FROM chart_of_accounts WHERE code = '2110' LIMIT 1;\n    SELECT id INTO v_ppn_account_id FROM chart_of_accounts WHERE code = '1150' LIMIT 1;\n    SELECT id INTO v_bm_account_id  FROM chart_of_accounts WHERE code = '6950' LIMIT 1;\n\n    IF v_ap_account_id IS NULL THEN\n      RAISE EXCEPTION 'A/P account (code 2110) not found in chart of accounts';\n    END IF;\n\n    PERFORM pg_advisory_xact_lock(hashtext('je_number_' || TO_CHAR(v_invoice_date, 'YYMM')));\n\n    IF p_invoice_id IS NULL THEN\n      -- ── CREATE path ──────────────────────────────────────────────────────────\n\n      v_je_number := 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-' || LPAD((\n        SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM '(\\\\d+)$') AS INTEGER)), 0) + 1\n        FROM journal_entries\n        WHERE entry_number LIKE 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-%'\n      )::TEXT, 4, '0');\n\n      INSERT INTO journal_entries (\n        entry_number, entry_date, source_module, reference_id, reference_number,\n        description, total_debit, total_credit, is_posted, posted_by, created_by\n      ) VALUES (\n        v_je_number, v_invoice_date, 'purchase_invoice', gen_random_uuid(), v_invoice_number,\n        'Purchase Invoice: ' || v_invoice_number,\n        0, v_total_amount * v_rate, TRUE, v_created_by, v_created_by\n      ) RETURNING id INTO v_je_id;\n\n      INSERT INTO purchase_invoices (\n        invoice_number, supplier_id, invoice_date, due_date,\n        currency, exchange_rate, subtotal, tax_amount, stamp_duty_amount, total_amount,\n        paid_amount, status,\n        faktur_pajak_number, notes, document_urls,\n        requires_faktur_pajak, purchase_type,\n        purchase_order_id,\n        journal_entry_id, created_by\n      ) VALUES (\n        v_invoice_number,\n        v_supplier_id,\n        v_invoice_date,\n        NULLIF(p_invoice_data->>'due_date', '')::DATE,\n        COALESCE(p_invoice_data->>'currency', 'IDR'),\n        COALESCE((p_invoice_data->>'exchange_rate')::NUMERIC, 1),\n        COALESCE((p_invoice_data->>'subtotal')::NUMERIC, 0),\n        v_tax_amount,\n        v_stamp_duty_amount,\n        v_total_amount,\n        0,\n        'unpaid',\n        NULLIF(p_invoice_data->>'faktur_pajak_number', ''),\n        NULLIF(p_invoice_data->>'notes', ''),\n        CASE\n          WHEN p_invoice_data -> 'document_urls' IS NOT NULL\n            AND jsonb_array_length(p_invoice_data -> 'document_urls') > 0\n          THEN ARRAY(SELECT jsonb_array_elements_text(p_invoice_data -> 'document_urls'))\n          ELSE NULL\n        END,\n        COALESCE((p_invoice_data->>'requires_faktur_pajak')::BOOLEAN, FALSE),\n        COALESCE(p_invoice_data->>'purchase_type', 'inventory'),\n        v_po_id,\n        v_je_id,\n        v_created_by\n      ) RETURNING id INTO v_invoice_id;\n\n      UPDATE journal_entries SET reference_id = v_invoice_id WHERE id = v_je_id;\n\n    ELSE\n      -- ── EDIT path ──────────────────────────────────────────────────────────\n\n      v_invoice_id := p_invoice_id;\n\n      SELECT journal_entry_id INTO v_je_id\n      FROM purchase_invoices WHERE id = v_invoice_id;\n\n      UPDATE purchase_invoices SET\n        invoice_number        = v_invoice_number,\n        supplier_id           = v_supplier_id,\n        invoice_date          = v_invoice_date,\n        due_date              = NULLIF(p_invoice_data->>'due_date', '')::DATE,\n        currency              = COALESCE(p_invoice_data->>'currency', 'IDR'),\n        exchange_rate         = COALESCE((p_invoice_data->>'exchange_rate')::NUMERIC, 1),\n        subtotal              = COALESCE((p_invoice_data->>'subtotal')::NUMERIC, 0),\n        tax_amount            = v_tax_amount,\n        stamp_duty_amount     = v_stamp_duty_amount,\n        total_amount          = v_total_amount,\n        faktur_pajak_number   = NULLIF(p_invoice_data->>'faktur_pajak_number', ''),\n        notes                 = NULLIF(p_invoice_data->>'notes', ''),\n        document_urls         = CASE\n                                  WHEN p_invoice_data -> 'document_urls' IS NOT NULL\n                                    AND jsonb_array_length(p_invoice_data -> 'document_urls') > 0\n                                  THEN ARRAY(SELECT jsonb_array_elements_text(p_invoice_data -> 'document_urls'))\n                                  ELSE NULL\n                                END,\n        requires_faktur_pajak = COALESCE((p_invoice_data->>'requires_faktur_pajak')::BOOLEAN, FALSE),\n        purchase_type         = COALESCE(p_invoice_data->>'purchase_type', 'inventory'),\n        purchase_order_id     = v_po_id,\n        updated_at            = NOW()\n      WHERE id = v_invoice_id;\n\n      IF EXISTS (\n        SELECT 1 FROM purchase_invoice_items i \n        WHERE i.purchase_invoice_id = v_invoice_id \n          AND NOT EXISTS (\n            SELECT 1 FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) x \n            WHERE NULLIF(x->>'id','')::uuid = i.id\n          ) \n          AND (\n            EXISTS (SELECT 1 FROM purchase_invoice_receiving_allocations a WHERE a.purchase_invoice_item_id = i.id) \n            OR i.batch_id IS NOT NULL\n          )\n      ) THEN \n        RAISE EXCEPTION 'Cannot remove invoice line with receiving or inventory history'; \n      END IF;\n\n      DELETE FROM purchase_invoice_items i \n      WHERE i.purchase_invoice_id = v_invoice_id \n        AND NOT EXISTS (\n          SELECT 1 FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) x \n          WHERE NULLIF(x->>'id','')::uuid = i.id\n        );\n\n      IF v_je_id IS NOT NULL THEN\n        DELETE FROM journal_entry_lines WHERE journal_entry_id = v_je_id;\n        UPDATE journal_entries SET\n          entry_date       = v_invoice_date,\n          reference_number = v_invoice_number,\n          description      = 'Purchase Invoice: ' || v_invoice_number,\n          total_debit      = 0,\n          total_credit     = v_total_amount * v_rate\n        WHERE id = v_je_id;\n      ELSE\n        v_je_number := 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-' || LPAD((\n          SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM '(\\\\d+)$') AS INTEGER)), 0) + 1\n          FROM journal_entries\n          WHERE entry_number LIKE 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-%'\n        )::TEXT, 4, '0');\n\n        INSERT INTO journal_entries (\n          entry_number, entry_date, source_module, reference_id, reference_number,\n          description, total_debit, total_credit, is_posted, posted_by, created_by\n        ) VALUES (\n          v_je_number, v_invoice_date, 'purchase_invoice', v_invoice_id, v_invoice_number,\n          'Purchase Invoice: ' || v_invoice_number,\n          0, v_total_amount * v_rate, TRUE, v_created_by, v_created_by\n        ) RETURNING id INTO v_je_id;\n\n        UPDATE purchase_invoices SET journal_entry_id = v_je_id WHERE id = v_invoice_id;\n      END IF;\n    END IF;\n\n    -- ── Insert/Update items and build JE debit lines ───────────────────────────\n    v_line_number := 1;\n\n    FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))\n    LOOP\n      v_item_type  := v_item->>'item_type';\n      v_line_total := COALESCE((v_item->>'line_total')::NUMERIC(15,2), 0);\n      v_item_id    := NULLIF(v_item->>'id', '')::UUID;\n\n      IF v_item_id IS NOT NULL AND EXISTS (SELECT 1 FROM purchase_invoice_items WHERE id = v_item_id AND purchase_invoice_id = v_invoice_id) THEN\n        UPDATE purchase_invoice_items SET \n          item_type                     = v_item_type, \n          product_id                    = NULLIF(v_item->>'product_id','')::UUID, \n          description                   = v_item->>'description', \n          quantity                      = COALESCE((v_item->>'quantity')::NUMERIC, 1), \n          unit                          = v_item->>'unit', \n          unit_price                    = COALESCE((v_item->>'unit_price')::NUMERIC, 0), \n          discount_percent              = (v_item->>'discount_percent')::NUMERIC, \n          line_total                    = v_line_total, \n          tax_amount                    = (v_item->>'tax_amount')::NUMERIC, \n          expense_account_id            = NULLIF(v_item->>'expense_account_id','')::UUID, \n          asset_account_id              = NULLIF(v_item->>'asset_account_id','')::UUID, \n          purchase_order_item_id        = NULLIF(v_item->>'purchase_order_item_id','')::UUID, \n          receiving_make_id             = NULLIF(v_item->>'receiving_make_id','')::UUID, \n          receiving_batch_number        = NULLIF(v_item->>'receiving_batch_number',''), \n          receiving_expiry_date         = NULLIF(v_item->>'receiving_expiry_date','')::DATE, \n          receiving_import_container_id = NULLIF(v_item->>'receiving_import_container_id','')::UUID, \n          receiving_notes               = NULLIF(v_item->>'receiving_notes','') \n        WHERE id = v_item_id;\n      ELSE\n        INSERT INTO purchase_invoice_items (\n          purchase_invoice_id, item_type, product_id, description,\n          quantity, unit, unit_price, discount_percent, line_total,\n          tax_amount, expense_account_id, asset_account_id,\n          purchase_order_item_id, receiving_make_id, receiving_batch_number,\n          receiving_expiry_date, receiving_import_container_id, receiving_notes\n        ) VALUES (\n          v_invoice_id,\n          v_item_type,\n          NULLIF(v_item->>'product_id', '')::UUID,\n          v_item->>'description',\n          COALESCE((v_item->>'quantity')::NUMERIC, 1),\n          v_item->>'unit',\n          COALESCE((v_item->>'unit_price')::NUMERIC, 0),\n          (v_item->>'discount_percent')::NUMERIC,\n          v_line_total,\n          (v_item->>'tax_amount')::NUMERIC,\n          NULLIF(v_item->>'expense_account_id', '')::UUID,\n          NULLIF(v_item->>'asset_account_id',   '')::UUID,\n          NULLIF(v_item->>'purchase_order_item_id', '')::UUID,\n          NULLIF(v_item->>'receiving_make_id', '')::UUID,\n          NULLIF(v_item->>'receiving_batch_number', ''),\n          NULLIF(v_item->>'receiving_expiry_date', '')::DATE,\n          NULLIF(v_item->>'receiving_import_container_id', '')::UUID,\n          NULLIF(v_item->>'receiving_notes', '')\n        );\n      END IF;\n\n      IF v_item_type = 'inventory' THEN\n        SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;\n      ELSIF v_item_type = 'fixed_asset' THEN\n        v_account_id := NULLIF(v_item->>'asset_account_id', '')::UUID;\n        IF v_account_id IS NULL THEN\n          SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1200' LIMIT 1;\n        END IF;\n      ELSE\n        v_account_id := NULLIF(v_item->>'expense_account_id', '')::UUID;\n        IF v_account_id IS NULL THEN\n          SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '5100' LIMIT 1;\n        END IF;\n      END IF;\n\n      IF v_account_id IS NOT NULL AND v_line_total <> 0 THEN\n        INSERT INTO journal_entry_lines (\n          journal_entry_id, line_number, account_id, description,\n          debit, credit, supplier_id\n        ) VALUES (\n          v_je_id, v_line_number, v_account_id,\n          COALESCE(LEFT(v_item->>'description', 100), 'Purchase Item'),\n          v_line_total * v_rate, 0, v_supplier_id\n        );\n        v_line_number := v_line_number + 1;\n      END IF;\n    END LOOP;\n\n    -- PPN Input debit line (DR 1150)\n    IF v_tax_amount > 0 AND v_ppn_account_id IS NOT NULL THEN\n      INSERT INTO journal_entry_lines (\n        journal_entry_id, line_number, account_id, description,\n        debit, credit, supplier_id\n      ) VALUES (\n        v_je_id, v_line_number, v_ppn_account_id,\n        'PPN Input - ' || v_invoice_number,\n        v_tax_amount * v_rate, 0, v_supplier_id\n      );\n      v_line_number := v_line_number + 1;\n    END IF;\n\n    -- Stamp Duty debit line (DR 6950 Bea Meterai Expense)\n    IF v_stamp_duty_amount > 0 AND v_bm_account_id IS NOT NULL THEN\n      INSERT INTO journal_entry_lines (\n        journal_entry_id, line_number, account_id, description,\n        debit, credit, supplier_id\n      ) VALUES (\n        v_je_id, v_line_number, v_bm_account_id,\n        'Bea Meterai - ' || v_invoice_number,\n        v_stamp_duty_amount * v_rate, 0, v_supplier_id\n      );\n      v_line_number := v_line_number + 1;\n    END IF;\n\n    -- A/P credit line (total_amount = subtotal + ppn + stamp_duty)\n    INSERT INTO journal_entry_lines (\n      journal_entry_id, line_number, account_id, description,\n      debit, credit, supplier_id\n    ) VALUES (\n      v_je_id, v_line_number, v_ap_account_id,\n      'A/P - ' || v_invoice_number,\n      0, v_total_amount * v_rate, v_supplier_id\n    );\n\n    UPDATE journal_entries SET transaction_currency=v_currency, functional_currency='IDR', exchange_rate=v_rate, amounts_are_functional=true WHERE id=v_je_id;\n    UPDATE journal_entry_lines SET transaction_currency=v_currency, exchange_rate=v_rate, transaction_debit=CASE WHEN debit>0 THEN round(debit / v_rate, 2) ELSE 0 END, transaction_credit=CASE WHEN credit>0 THEN round(credit / v_rate, 2) ELSE 0 END WHERE journal_entry_id=v_je_id;\n\n    -- Reconcile JE totals from actual inserted lines\n    UPDATE journal_entries SET\n      total_debit  = (SELECT COALESCE(SUM(debit),  0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id),\n      total_credit = (SELECT COALESCE(SUM(credit), 0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)\n    WHERE id = v_je_id;\n\n    RETURN jsonb_build_object(\n      'invoice_id',       v_invoice_id,\n      'journal_entry_id', v_je_id\n    );\n  END;\n$_$","--\n-- Name: save_purchase_invoice_with_receiving_details(\\"uuid\\", \\"uuid\\", \\"jsonb\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_purchase_invoice_with_receiving_details\\"(\\"p_invoice_id\\" \\"uuid\\", \\"p_purchase_order_id\\" \\"uuid\\", \\"p_invoice_data\\" \\"jsonb\\", \\"p_items\\" \\"jsonb\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_data jsonb:=coalesce(p_invoice_data,'{}'::jsonb); v_items jsonb:='[]'::jsonb; v_item jsonb; v_old public.purchase_invoice_items%rowtype; v_po uuid; v_result jsonb; v_id uuid; v_rate numeric; v_ccy text;\nBEGIN\n  IF p_invoice_id IS NOT NULL AND nullif(v_data->>'purchase_order_id','') IS NULL THEN SELECT purchase_order_id INTO v_po FROM purchase_invoices WHERE id=p_invoice_id; IF v_po IS NOT NULL THEN v_data:=jsonb_set(v_data,'{purchase_order_id}',to_jsonb(v_po),true); END IF; ELSIF p_invoice_id IS NULL AND p_purchase_order_id IS NOT NULL AND nullif(v_data->>'purchase_order_id','') IS NULL THEN v_data:=jsonb_set(v_data,'{purchase_order_id}',to_jsonb(p_purchase_order_id),true); END IF;\n  FOR v_item IN SELECT value FROM jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) LOOP\n    IF p_invoice_id IS NOT NULL AND nullif(v_item->>'id','') IS NOT NULL THEN SELECT * INTO v_old FROM purchase_invoice_items WHERE id=(v_item->>'id')::uuid AND purchase_invoice_id=p_invoice_id; IF FOUND THEN\n      IF nullif(v_item->>'purchase_order_item_id','') IS NULL AND v_old.purchase_order_item_id IS NOT NULL THEN v_item:=jsonb_set(v_item,'{purchase_order_item_id}',to_jsonb(v_old.purchase_order_item_id),true); END IF;\n      IF nullif(v_item->>'receiving_make_id','') IS NULL AND v_old.receiving_make_id IS NOT NULL THEN v_item:=jsonb_set(v_item,'{receiving_make_id}',to_jsonb(v_old.receiving_make_id),true); END IF;\n      IF nullif(v_item->>'receiving_batch_number','') IS NULL AND v_old.receiving_batch_number IS NOT NULL THEN v_item:=jsonb_set(v_item,'{receiving_batch_number}',to_jsonb(v_old.receiving_batch_number),true); END IF;\n      IF nullif(v_item->>'receiving_expiry_date','') IS NULL AND v_old.receiving_expiry_date IS NOT NULL THEN v_item:=jsonb_set(v_item,'{receiving_expiry_date}',to_jsonb(v_old.receiving_expiry_date),true); END IF;\n      IF nullif(v_item->>'receiving_import_container_id','') IS NULL AND v_old.receiving_import_container_id IS NOT NULL THEN v_item:=jsonb_set(v_item,'{receiving_import_container_id}',to_jsonb(v_old.receiving_import_container_id),true); END IF;\n      IF nullif(v_item->>'receiving_notes','') IS NULL AND v_old.receiving_notes IS NOT NULL THEN v_item:=jsonb_set(v_item,'{receiving_notes}',to_jsonb(v_old.receiving_notes),true); END IF;\n    END IF; END IF; v_items:=v_items||jsonb_build_array(v_item);\n  END LOOP;\n  v_result:=CASE WHEN p_invoice_id IS NOT NULL THEN save_purchase_invoice(p_invoice_id,v_data,v_items) WHEN p_purchase_order_id IS NOT NULL THEN create_purchase_invoice_from_po(p_purchase_order_id,v_data,v_items) ELSE save_purchase_invoice(NULL,v_data,v_items) END;\n  v_id:=(v_result->>'invoice_id')::uuid; SELECT upper(currency),exchange_rate INTO v_ccy,v_rate FROM purchase_invoices WHERE id=v_id; RETURN v_result;\nEND; $$","--\n-- Name: save_receipt_voucher_with_allocations(\\"uuid\\", \\"jsonb\\", \\"jsonb\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"save_receipt_voucher_with_allocations\\"(\\"p_receipt_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_payload\\" \\"jsonb\\" DEFAULT '{}'::\\"jsonb\\", \\"p_allocations\\" \\"jsonb\\" DEFAULT '[]'::\\"jsonb\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_id uuid;\n  v_alloc jsonb;\n  v_bank_currency text;\n  v_currency text;\n  v_rate numeric;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  IF NULLIF(p_payload->>'customer_id','') IS NULL THEN RAISE EXCEPTION 'Customer is required'; END IF;\n  IF COALESCE((p_payload->>'amount')::numeric,0) <= 0 THEN RAISE EXCEPTION 'Receipt amount must be greater than zero'; END IF;\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id=NULLIF(p_payload->>'bank_account_id','')::uuid;\n  v_currency := upper(COALESCE(NULLIF(p_payload->>'transaction_currency',''),v_bank_currency,'IDR'));\n  v_rate := COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric,0),CASE WHEN v_currency='IDR' THEN 1 ELSE NULL END);\n  IF v_rate IS NULL OR v_rate<=0 OR (v_currency='USD' AND v_rate<=1) THEN\n    RAISE EXCEPTION 'A valid exchange rate is required for % receipts',v_currency;\n  END IF;\n  IF v_bank_currency IS NOT NULL AND v_bank_currency<>v_currency THEN\n    RAISE EXCEPTION 'Receipt currency % does not match selected bank currency %',v_currency,v_bank_currency;\n  END IF;\n\n  IF p_receipt_id IS NULL THEN\n    INSERT INTO public.receipt_vouchers(\n      voucher_number,voucher_date,customer_id,payment_method,bank_account_id,reference_number,\n      amount,description,created_by,currency_code,transaction_currency,functional_currency,\n      exchange_rate,bank_account_currency,payment_currency\n    ) VALUES (\n      public.next_receipt_voucher_number((p_payload->>'voucher_date')::date),(p_payload->>'voucher_date')::date,\n      (p_payload->>'customer_id')::uuid,p_payload->>'payment_method',NULLIF(p_payload->>'bank_account_id','')::uuid,\n      NULLIF(p_payload->>'reference_number',''),(p_payload->>'amount')::numeric,NULLIF(p_payload->>'description',''),\n      COALESCE(NULLIF(p_payload->>'created_by','')::uuid,auth.uid()),v_currency,v_currency,'IDR',v_rate,\n      COALESCE(v_bank_currency,v_currency),v_currency\n    ) RETURNING id INTO v_id;\n  ELSE\n    IF EXISTS (SELECT 1 FROM public.receipt_vouchers WHERE id=p_receipt_id AND is_posted=true) THEN\n      RAISE EXCEPTION 'Cannot edit a posted receipt voucher. Cancel posting first.';\n    END IF;\n    UPDATE public.receipt_vouchers SET\n      voucher_date=(p_payload->>'voucher_date')::date,customer_id=(p_payload->>'customer_id')::uuid,\n      payment_method=p_payload->>'payment_method',bank_account_id=NULLIF(p_payload->>'bank_account_id','')::uuid,\n      reference_number=NULLIF(p_payload->>'reference_number',''),amount=(p_payload->>'amount')::numeric,\n      description=NULLIF(p_payload->>'description',''),currency_code=v_currency,transaction_currency=v_currency,\n      functional_currency='IDR',exchange_rate=v_rate,bank_account_currency=COALESCE(v_bank_currency,v_currency),\n      payment_currency=v_currency,updated_at=now()\n    WHERE id=p_receipt_id RETURNING id INTO v_id;\n    DELETE FROM public.voucher_allocations WHERE receipt_voucher_id=v_id;\n  END IF;\n  FOR v_alloc IN SELECT value FROM jsonb_array_elements(COALESCE(p_allocations,'[]'::jsonb)) LOOP\n    IF COALESCE((v_alloc->>'amount')::numeric,0) > 0 THEN\n      INSERT INTO public.voucher_allocations(voucher_type,receipt_voucher_id,sales_invoice_id,sales_order_id,allocated_amount)\n      VALUES('receipt',v_id,NULLIF(v_alloc->>'sales_invoice_id','')::uuid,\n        NULLIF(v_alloc->>'sales_order_id','')::uuid,(v_alloc->>'amount')::numeric);\n    END IF;\n  END LOOP;\n  RETURN v_id;\nEND;\n$$","--\n-- Name: set_inquiry_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"set_inquiry_number\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF NEW.inquiry_number IS NULL THEN\nNEW.inquiry_number := generate_inquiry_number();\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: set_kunal_ai_reviews_updated_at(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"set_kunal_ai_reviews_updated_at\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  NEW.updated_at := now();\n  RETURN NEW;\nEND;\n$$","--\n-- Name: set_updated_at_tax_compliance(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"set_updated_at_tax_compliance\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'pg_catalog', 'public'\n    AS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND $$","--\n-- Name: submit_purchase_invoice_for_receiving(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"submit_purchase_invoice_for_receiving\\"(\\"p_purchase_invoice_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_invoice public.purchase_invoices%ROWTYPE;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','manager']) THEN RAISE EXCEPTION 'Permission denied'; END IF;\n  SELECT * INTO v_invoice FROM public.purchase_invoices WHERE id = p_purchase_invoice_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;\n  IF v_invoice.status = 'cancelled' THEN RAISE EXCEPTION 'Cancelled Purchase Invoice cannot be submitted'; END IF;\n  UPDATE public.purchase_invoices SET receiving_approval_status='pending_approval', receiving_submitted_at=now(), receiving_submitted_by=auth.uid(), receiving_rejection_reason=NULL, updated_at=now() WHERE id=p_purchase_invoice_id;\n  RETURN jsonb_build_object('success',true,'status','pending_approval');\nEND; $$","--\n-- Name: sync_bank_allocation_document_identity(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_bank_allocation_document_identity\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_type text;\n  v_document uuid;\nBEGIN\n  IF NEW.journal_entry_id IS NULL THEN\n    RAISE EXCEPTION 'Bank allocation requires a journal target';\n  END IF;\n\n  SELECT r.document_type, r.document_id\n    INTO v_type, v_document\n    FROM public.resolve_bank_allocation_document(NEW.journal_entry_id) r\n   LIMIT 1;\n  IF v_type IS NULL THEN\n    RAISE EXCEPTION 'Journal target % does not exist', NEW.journal_entry_id;\n  END IF;\n\n  -- This runs for inserts and for any metadata/journal-target update.  It\n  -- makes a journal relink atomic with the document identity change, so a bank\n  -- line can never point at a payment journal while retaining an expense id.\n  NEW.document_type := v_type;\n  NEW.document_id := v_document;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: sync_bank_line_allocation_owner(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_bank_line_allocation_owner\\"(\\"p_bank_line_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_count integer;\n  v_only public.bank_statement_allocations%ROWTYPE;\nBEGIN\n  SELECT count(*) INTO v_count\n    FROM public.bank_statement_allocations\n   WHERE bank_statement_line_id = p_bank_line_id;\n\n  IF v_count = 1 THEN\n    SELECT * INTO v_only\n      FROM public.bank_statement_allocations\n     WHERE bank_statement_line_id = p_bank_line_id;\n    UPDATE public.bank_statement_lines SET\n      matched_expense_id = CASE \n        WHEN v_only.document_type = 'expense' \n          AND NOT EXISTS (\n            SELECT 1 FROM public.bank_statement_lines b \n            WHERE b.matched_expense_id = v_only.document_id \n              AND b.matching_status = 'confirmed' \n              AND b.id <> p_bank_line_id\n          ) \n        THEN v_only.document_id \n      END,\n      matched_receipt_id = CASE WHEN v_only.document_type = 'receipt' THEN v_only.document_id END,\n      matched_payment_id = CASE WHEN v_only.document_type = 'payment' THEN v_only.document_id END,\n      matched_fund_transfer_id = CASE WHEN v_only.document_type = 'fund_transfer' THEN v_only.document_id END,\n      matched_petty_cash_id = CASE WHEN v_only.document_type = 'petty_cash' THEN v_only.document_id END,\n      matched_tax_payment_id = CASE WHEN v_only.document_type = 'tax_payment' THEN v_only.document_id END,\n      matched_entry_id = v_only.journal_entry_id,\n      payment_kind = v_only.payment_kind\n    WHERE id = p_bank_line_id;\n  ELSE\n    UPDATE public.bank_statement_lines SET\n      matched_expense_id = NULL,\n      matched_receipt_id = NULL,\n      matched_payment_id = NULL,\n      matched_fund_transfer_id = NULL,\n      matched_petty_cash_id = NULL,\n      matched_tax_payment_id = NULL,\n      matched_entry_id = NULL\n    WHERE id = p_bank_line_id;\n  END IF;\nEND;\n$$","--\n-- Name: sync_bank_line_from_allocation(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_bank_line_from_allocation\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_old_line uuid;\n  v_new_line uuid;\nBEGIN\n  IF TG_OP IN ('UPDATE', 'DELETE') THEN\n    v_old_line := OLD.bank_statement_line_id;\n    PERFORM public.sync_bank_line_allocation_owner(v_old_line);\n    PERFORM public.refresh_bank_statement_allocation_status(v_old_line);\n    IF NOT public.historical_repair_context_active() THEN\n      IF OLD.document_type = 'expense' AND EXISTS (\n        SELECT 1 FROM public.finance_expenses WHERE id = OLD.document_id\n      ) THEN\n        PERFORM public.recalculate_expense_payment_state(OLD.document_id);\n      ELSIF OLD.document_type = 'tax_payment' THEN\n        UPDATE public.tax_payments SET status = 'posted' WHERE id = OLD.document_id\n          AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE document_type = 'tax_payment' AND document_id = OLD.document_id);\n      END IF;\n    END IF;\n  END IF;\n  IF TG_OP IN ('INSERT', 'UPDATE') THEN\n    v_new_line := NEW.bank_statement_line_id;\n    IF v_new_line IS DISTINCT FROM v_old_line THEN\n      PERFORM public.sync_bank_line_allocation_owner(v_new_line);\n      PERFORM public.refresh_bank_statement_allocation_status(v_new_line);\n    END IF;\n    IF NOT public.historical_repair_context_active() THEN\n      IF NEW.document_type = 'expense' AND EXISTS (SELECT 1 FROM public.finance_expenses WHERE id = NEW.document_id) THEN\n        PERFORM public.recalculate_expense_payment_state(NEW.document_id);\n      ELSIF NEW.document_type = 'tax_payment' THEN\n        UPDATE public.tax_payments SET status = 'reconciled' WHERE id = NEW.document_id;\n      END IF;\n    END IF;\n  END IF;\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$","--\n-- Name: sync_expense_from_bank_allocation(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_expense_from_bank_allocation\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_old_expense uuid; v_new_expense uuid; v_old_date date; v_new_date date; v_fallback date;\nBEGIN\n  IF public.historical_repair_context_active() THEN RETURN COALESCE(NEW, OLD); END IF;\n  IF TG_OP IN ('UPDATE','DELETE') AND OLD.document_type='expense' THEN\n    v_old_expense:=OLD.document_id;\n    SELECT transaction_date INTO v_old_date FROM public.bank_statement_lines WHERE id=OLD.bank_statement_line_id;\n    PERFORM public.recalculate_expense_payment_state(v_old_expense);\n    IF EXISTS(SELECT 1 FROM public.finance_expenses WHERE id=v_old_expense AND (COALESCE(pph_amount,0)>0 OR COALESCE(pib_pph_amount,0)>0 OR expense_category='pph_import')) THEN\n      PERFORM public.recompute_pph_periods_for_date(v_old_date);\n      PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_old_expense));\n      SELECT COALESCE(due_date,expense_date) INTO v_fallback FROM public.finance_expenses WHERE id=v_old_expense;\n      PERFORM public.recompute_pph_periods_for_date(v_fallback);\n    END IF;\n  END IF;\n  IF TG_OP IN ('INSERT','UPDATE') AND NEW.document_type='expense' THEN\n    v_new_expense:=NEW.document_id;\n    SELECT transaction_date INTO v_new_date FROM public.bank_statement_lines WHERE id=NEW.bank_statement_line_id;\n    PERFORM public.recalculate_expense_payment_state(v_new_expense);\n    IF EXISTS(SELECT 1 FROM public.finance_expenses WHERE id=v_new_expense AND (COALESCE(pph_amount,0)>0 OR COALESCE(pib_pph_amount,0)>0 OR expense_category='pph_import')) THEN\n      PERFORM public.recompute_pph_periods_for_date(v_new_date);\n      PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_new_expense));\n      SELECT COALESCE(due_date,expense_date) INTO v_fallback FROM public.finance_expenses WHERE id=v_new_expense;\n      PERFORM public.recompute_pph_periods_for_date(v_fallback);\n    END IF;\n  END IF;\n  RETURN COALESCE(NEW,OLD);\nEND;\n$$","--\n-- Name: sync_expense_journal_currency_and_state(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_expense_journal_currency_and_state\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_je uuid;\n  v_currency text:=upper(COALESCE(NEW.transaction_currency,NEW.currency_code,'IDR'));\n  v_rate numeric:=CASE WHEN upper(COALESCE(NEW.transaction_currency,NEW.currency_code,'IDR'))='IDR'\n    THEN 1 ELSE NEW.exchange_rate END;\nBEGIN\n  IF NEW.approval_status IS DISTINCT FROM 'approved' THEN\n    IF OLD.approval_status='approved' AND EXISTS(\n      SELECT 1 FROM public.journal_entries WHERE source_module IN('expense','expenses')\n        AND (reference_id=NEW.id OR reference_number='EXP-'||NEW.id::text)\n        AND COALESCE(is_reversed,false)=false\n    ) THEN\n      RAISE EXCEPTION 'Use Cancel Posting so the journal removal is period-checked and audited';\n    END IF;\n    RETURN NEW;\n  END IF;\n  IF COALESCE(current_setting('app.finance_historical_repair',true),'off')='on' THEN RETURN NEW; END IF;\n\n  SELECT id INTO v_je\n    FROM public.journal_entries\n   WHERE source_module='expenses'\n     AND (reference_id=NEW.id OR reference_number='EXP-'||NEW.id::text)\n     AND is_posted=true AND COALESCE(is_reversed,false)=false\n   ORDER BY created_at DESC LIMIT 1;\n  IF v_je IS NULL THEN\n    RAISE EXCEPTION 'Approved expense % has no active journal entry',NEW.id;\n  END IF;\n  IF v_currency NOT IN ('IDR','USD') OR v_rate IS NULL OR v_rate<=0 THEN\n    RAISE EXCEPTION 'Approved expense % has invalid currency metadata',NEW.id;\n  END IF;\n\n  -- Metadata-only historical repair must never rewrite accounting history.\n  IF COALESCE(current_setting('app.finance_historical_repair',true),'off') <> 'on' THEN\n    UPDATE public.journal_entry_lines\n       SET transaction_currency=v_currency,\n           transaction_debit=COALESCE(transaction_debit,debit),\n           transaction_credit=COALESCE(transaction_credit,credit),\n           functional_currency='IDR',exchange_rate=v_rate,\n           debit=round(COALESCE(transaction_debit,debit)*v_rate,2),\n           credit=round(COALESCE(transaction_credit,credit)*v_rate,2)\n     WHERE journal_entry_id=v_je;\n    UPDATE public.journal_entries je\n       SET transaction_currency=v_currency,functional_currency='IDR',exchange_rate=v_rate,\n           amounts_are_functional=true,\n           total_debit=(SELECT COALESCE(sum(debit),0) FROM public.journal_entry_lines WHERE journal_entry_id=v_je),\n           total_credit=(SELECT COALESCE(sum(credit),0) FROM public.journal_entry_lines WHERE journal_entry_id=v_je)\n     WHERE je.id=v_je;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: sync_expense_payment_state_from_allocations(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_expense_payment_state_from_allocations\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  -- On INSERT or UPDATE, recalculate for the new expense\n  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.finance_expense_id IS NOT NULL THEN\n    PERFORM public.recalculate_expense_payment_state(NEW.finance_expense_id);\n  END IF;\n\n  -- On UPDATE or DELETE, recalculate for the old expense (if different)\n  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.finance_expense_id IS NOT NULL THEN\n    IF TG_OP = 'DELETE'\n       OR OLD.finance_expense_id IS DISTINCT FROM NEW.finance_expense_id\n       OR OLD.allocated_amount   IS DISTINCT FROM NEW.allocated_amount\n       OR OLD.voucher_type       IS DISTINCT FROM NEW.voucher_type\n    THEN\n      PERFORM public.recalculate_expense_payment_state(OLD.finance_expense_id);\n    END IF;\n  END IF;\n\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$","--\n-- Name: sync_fund_transfer_journal_currency(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_fund_transfer_journal_currency\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_from_currency text;\n  v_to_currency text;\n  v_rate numeric;\n  v_functional numeric;\nBEGIN\n  IF NEW.journal_entry_id IS NULL OR NEW.status<>'posted' THEN RETURN NEW; END IF;\n  IF COALESCE(current_setting('app.finance_historical_repair',true),'off')='on' THEN RETURN NEW; END IF;\n  v_from_currency:=CASE WHEN NEW.from_account_type='bank'\n    THEN (SELECT upper(currency) FROM public.bank_accounts WHERE id=NEW.from_bank_account_id) ELSE 'IDR' END;\n  v_to_currency:=CASE WHEN NEW.to_account_type='bank'\n    THEN (SELECT upper(currency) FROM public.bank_accounts WHERE id=NEW.to_bank_account_id) ELSE 'IDR' END;\n  IF v_from_currency NOT IN('IDR','USD') OR v_to_currency NOT IN('IDR','USD') THEN\n    RAISE EXCEPTION 'Unsupported Fund Transfer currency';\n  END IF;\n  IF v_from_currency='IDR' AND v_to_currency='IDR' THEN\n    IF abs(NEW.from_amount-NEW.to_amount)>0.01 THEN RAISE EXCEPTION 'IDR Fund Transfer amounts must match'; END IF;\n    v_rate:=1; v_functional:=NEW.from_amount;\n  ELSIF v_from_currency='IDR' AND v_to_currency='USD' THEN\n    IF NEW.to_amount<=0 THEN RAISE EXCEPTION 'USD destination amount is required'; END IF;\n    v_rate:=NEW.from_amount/NEW.to_amount; v_functional:=NEW.from_amount;\n  ELSIF v_from_currency='USD' AND v_to_currency='IDR' THEN\n    IF NEW.from_amount<=0 THEN RAISE EXCEPTION 'USD source amount is required'; END IF;\n    v_rate:=NEW.to_amount/NEW.from_amount; v_functional:=NEW.to_amount;\n  ELSE\n    IF abs(NEW.from_amount-NEW.to_amount)>0.01 THEN RAISE EXCEPTION 'Same-currency USD Fund Transfer amounts must match'; END IF;\n    v_rate:=COALESCE(NULLIF(NEW.exchange_rate,0),public.get_reporting_usd_rate());\n    IF v_rate<=1 THEN v_rate:=public.get_reporting_usd_rate(); END IF;\n    IF v_rate IS NULL OR v_rate<=1 THEN RAISE EXCEPTION 'A valid USD-to-IDR rate is required'; END IF;\n    v_functional:=NEW.from_amount*v_rate;\n  END IF;\n  IF v_rate IS NULL OR v_rate<=0 THEN RAISE EXCEPTION 'Invalid Fund Transfer exchange rate'; END IF;\n\n  UPDATE public.journal_entry_lines SET\n    debit=CASE WHEN line_number=1 THEN round(v_functional,2) ELSE 0 END,\n    credit=CASE WHEN line_number=2 THEN round(v_functional,2) ELSE 0 END,\n    transaction_currency=CASE WHEN line_number=1 THEN v_to_currency ELSE v_from_currency END,\n    transaction_debit=CASE WHEN line_number=1 THEN NEW.to_amount ELSE 0 END,\n    transaction_credit=CASE WHEN line_number=2 THEN NEW.from_amount ELSE 0 END,\n    functional_currency='IDR',\n    exchange_rate=CASE\n      WHEN line_number=1 AND v_to_currency='USD' THEN v_rate\n      WHEN line_number=2 AND v_from_currency='USD' THEN v_rate\n      ELSE 1 END\n  WHERE journal_entry_id=NEW.journal_entry_id AND line_number IN(1,2);\n  UPDATE public.journal_entries SET transaction_currency=CASE WHEN v_from_currency=v_to_currency THEN v_from_currency ELSE 'IDR' END,\n    functional_currency='IDR',exchange_rate=v_rate,amounts_are_functional=true,\n    total_debit=round(v_functional,2),total_credit=round(v_functional,2)\n  WHERE id=NEW.journal_entry_id;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: sync_payment_journal_currency(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_payment_journal_currency\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_invoice_currency text:=upper(COALESCE(NEW.invoice_currency,NEW.transaction_currency,NEW.currency_code,'IDR'));\n  v_rate numeric:=COALESCE(NEW.exchange_rate,1);\nBEGIN\n  IF COALESCE(NEW.is_posted,false)=false OR NEW.journal_entry_id IS NULL THEN RETURN NEW; END IF;\n  IF COALESCE(current_setting('app.finance_historical_repair',true),'off')='on' THEN RETURN NEW; END IF;\n  IF v_invoice_currency NOT IN('IDR','USD') OR v_rate<=0 THEN\n    RAISE EXCEPTION 'Posted payment has invalid currency metadata';\n  END IF;\n\n  -- The canonical poster owns the numerical amounts. Fill metadata only.\n  UPDATE public.journal_entry_lines\n     SET transaction_currency=COALESCE(transaction_currency,v_invoice_currency),\n         transaction_debit=COALESCE(transaction_debit,\n           CASE WHEN COALESCE(exchange_rate,1)>0 THEN debit/COALESCE(exchange_rate,1) ELSE debit END),\n         transaction_credit=COALESCE(transaction_credit,\n           CASE WHEN COALESCE(exchange_rate,1)>0 THEN credit/COALESCE(exchange_rate,1) ELSE credit END),\n         functional_currency='IDR',\n         exchange_rate=COALESCE(exchange_rate,CASE WHEN v_invoice_currency='USD' THEN v_rate ELSE 1 END)\n   WHERE journal_entry_id=NEW.journal_entry_id;\n\n  UPDATE public.journal_entries SET\n    transaction_currency=v_invoice_currency,functional_currency='IDR',exchange_rate=v_rate,\n    amounts_are_functional=true,\n    total_debit=(SELECT COALESCE(sum(debit),0) FROM public.journal_entry_lines WHERE journal_entry_id=NEW.journal_entry_id),\n    total_credit=(SELECT COALESCE(sum(credit),0) FROM public.journal_entry_lines WHERE journal_entry_id=NEW.journal_entry_id)\n  WHERE id=NEW.journal_entry_id;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: sync_pi_state_on_pv_posting_change(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_pi_state_on_pv_posting_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_invoice_id uuid;\nBEGIN\n  IF COALESCE(OLD.is_posted, FALSE) IS DISTINCT FROM COALESCE(NEW.is_posted, FALSE) THEN\n    FOR v_invoice_id IN\n      SELECT DISTINCT purchase_invoice_id\n      FROM public.voucher_allocations\n      WHERE payment_voucher_id = NEW.id\n        AND voucher_type = 'payment'\n        AND purchase_invoice_id IS NOT NULL\n    LOOP\n      PERFORM public.recalculate_purchase_invoice_payment_state(v_invoice_id);\n    END LOOP;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: sync_purchase_invoice_payment_state_from_allocations(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_purchase_invoice_payment_state_from_allocations\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\nIF TG_OP IN ('INSERT', 'UPDATE') AND NEW.purchase_invoice_id IS NOT NULL THEN\nPERFORM public.recalculate_purchase_invoice_payment_state(NEW.purchase_invoice_id);\nEND IF;\n\nIF TG_OP IN ('UPDATE', 'DELETE') AND OLD.purchase_invoice_id IS NOT NULL THEN\nIF TG_OP = 'DELETE'\nOR OLD.purchase_invoice_id IS DISTINCT FROM NEW.purchase_invoice_id\nOR OLD.allocated_amount IS DISTINCT FROM NEW.allocated_amount\nOR OLD.voucher_type IS DISTINCT FROM NEW.voucher_type THEN\nPERFORM public.recalculate_purchase_invoice_payment_state(OLD.purchase_invoice_id);\nEND IF;\nEND IF;\n\nRETURN COALESCE(NEW, OLD);\nEND;\n$$","--\n-- Name: sync_receipt_journal_currency(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_receipt_journal_currency\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_currency text:=upper(COALESCE(NEW.transaction_currency,NEW.currency_code,'IDR'));\n  v_rate numeric:=CASE WHEN upper(COALESCE(NEW.transaction_currency,NEW.currency_code,'IDR'))='IDR' THEN 1 ELSE NEW.exchange_rate END;\nBEGIN\n  IF COALESCE(NEW.is_posted,false)=false OR NEW.journal_entry_id IS NULL THEN RETURN NEW; END IF;\n  IF COALESCE(current_setting('app.finance_historical_repair',true),'off')='on' THEN RETURN NEW; END IF;\n  IF v_currency NOT IN('IDR','USD') OR v_rate IS NULL OR v_rate<=0 THEN RAISE EXCEPTION 'Posted receipt has invalid currency metadata'; END IF;\n  UPDATE public.journal_entry_lines SET transaction_currency=v_currency,\n    transaction_debit=COALESCE(transaction_debit,debit),transaction_credit=COALESCE(transaction_credit,credit),\n    functional_currency='IDR',exchange_rate=v_rate,\n    debit=round(COALESCE(transaction_debit,debit)*v_rate,2),credit=round(COALESCE(transaction_credit,credit)*v_rate,2)\n  WHERE journal_entry_id=NEW.journal_entry_id;\n  UPDATE public.journal_entries SET transaction_currency=v_currency,functional_currency='IDR',exchange_rate=v_rate,\n    amounts_are_functional=true,\n    total_debit=(SELECT COALESCE(sum(debit),0) FROM public.journal_entry_lines WHERE journal_entry_id=NEW.journal_entry_id),\n    total_credit=(SELECT COALESCE(sum(credit),0) FROM public.journal_entry_lines WHERE journal_entry_id=NEW.journal_entry_id)\n  WHERE id=NEW.journal_entry_id;\n  RETURN NEW;\nEND $$","--\n-- Name: sync_sales_invoice_balance_cache(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_sales_invoice_balance_cache\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\nBEGIN\n  NEW.paid_amount := GREATEST(COALESCE(NEW.paid_amount, 0), 0);\n  IF NEW.paid_amount > COALESCE(NEW.total_amount, 0) + 0.01 THEN\n    RAISE EXCEPTION 'Invoice paid amount cannot exceed total amount';\n  END IF;\n  NEW.balance_amount := GREATEST(COALESCE(NEW.total_amount, 0) - NEW.paid_amount, 0);\n  RETURN NEW;\nEND;\n$$","--\n-- Name: sync_sole_allocation_from_legacy_unlink(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"sync_sole_allocation_from_legacy_unlink\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_allocation_id uuid;\nBEGIN\n  IF OLD.matched_expense_id IS NOT NULL AND NEW.matched_expense_id IS NULL\n     AND (SELECT count(*) FROM public.bank_statement_allocations WHERE bank_statement_line_id=NEW.id)=1 THEN\n    SELECT id INTO v_allocation_id\n    FROM public.bank_statement_allocations\n    WHERE bank_statement_line_id=NEW.id\n      AND document_type='expense' AND document_id=OLD.matched_expense_id\n    LIMIT 1;\n    IF v_allocation_id IS NOT NULL THEN\n      DELETE FROM public.bank_statement_allocations WHERE id=v_allocation_id;\n      PERFORM public.recalculate_expense_payment_state(OLD.matched_expense_id);\n    END IF;\n  END IF;\n  RETURN NEW;\nEND $$","--\n-- Name: tg_touch_finance_master_updated_at(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"tg_touch_finance_master_updated_at\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$","--\n-- Name: track_stock_levels_in_transaction(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"track_stock_levels_in_transaction\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nNEW.stock_before := (\nSELECT current_stock\nFROM batches\nWHERE id = NEW.batch_id\n);\n\nNEW.stock_after := NEW.stock_before + NEW.quantity;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: trg_auto_release_reservation_on_dc_item(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_auto_release_reservation_on_dc_item\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_so_id          uuid;\n  v_dc_status      text;\n  v_reservation    RECORD;\n  v_remaining_qty  numeric;\n  v_release_qty    numeric;\nBEGIN\n  -- Only release reservations when the DC is already approved.\n  -- During DC CREATE (pending_approval) or EDIT (pending), items are inserted\n  -- but reservations must NOT be released — stock has not been physically dispatched.\n  -- The canonical release path is trg_dc_approval_deduct_stock (UPDATE trigger).\n  SELECT approval_status::text, sales_order_id\n    INTO v_dc_status, v_so_id\n  FROM delivery_challans\n  WHERE id = NEW.challan_id;\n\n  IF v_dc_status IS DISTINCT FROM 'approved' THEN\n    RETURN NEW;\n  END IF;\n\n  IF v_so_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  v_remaining_qty := NEW.quantity;\n\n  -- Release active reservations for this SO + product, any batch, FIFO\n  FOR v_reservation IN\n    SELECT id, reserved_quantity\n    FROM stock_reservations\n    WHERE sales_order_id = v_so_id\n      AND product_id     = NEW.product_id\n      AND status         = 'active'\n    ORDER BY reserved_at ASC\n  LOOP\n    EXIT WHEN v_remaining_qty <= 0;\n    v_release_qty := LEAST(v_remaining_qty, v_reservation.reserved_quantity);\n\n    IF v_release_qty >= v_reservation.reserved_quantity THEN\n      UPDATE stock_reservations\n      SET status = 'released', is_released = true, released_at = now()\n      WHERE id = v_reservation.id;\n    ELSE\n      UPDATE stock_reservations\n      SET reserved_quantity = reserved_quantity - v_release_qty\n      WHERE id = v_reservation.id;\n    END IF;\n\n    v_remaining_qty := v_remaining_qty - v_release_qty;\n  END LOOP;\n\n  -- If all reservations for this SO are gone, mark SO delivered\n  IF NOT EXISTS (\n    SELECT 1 FROM stock_reservations\n    WHERE sales_order_id = v_so_id\n      AND status = 'active'\n  ) THEN\n    UPDATE sales_orders\n    SET status = 'delivered'::sales_order_status, updated_at = now()\n    WHERE id = v_so_id\n      AND status NOT IN (\n        'delivered'::sales_order_status,\n        'closed'::sales_order_status,\n        'cancelled'::sales_order_status,\n        'rejected'::sales_order_status\n      );\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trg_create_batch_from_grn(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_create_batch_from_grn\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_grn_record RECORD;\nv_batch_id UUID;\nv_batch_number TEXT;\nBEGIN\n-- Only process when GRN status changes to 'posted'\nIF TG_OP = 'UPDATE' AND NEW.status = 'posted' AND OLD.status = 'draft' THEN\n\n-- Get GRN details\nSELECT grn_number, supplier_id, grn_date, created_by\nINTO v_grn_record\nFROM goods_receipt_notes WHERE id = NEW.id;\n\n-- Process each GRN item\nFOR v_grn_record IN\nSELECT * FROM goods_receipt_items WHERE grn_id = NEW.id\nLOOP\n-- Generate batch number if not provided\nIF v_grn_record.batch_number IS NULL OR v_grn_record.batch_number = '' THEN\nv_batch_number := 'BATCH-' || TO_CHAR(NOW(), 'YYMMDD') || '-' || LPAD((\nSELECT COUNT(*) + 1 FROM batches WHERE batch_number LIKE 'BATCH-' || TO_CHAR(NOW(), 'YYMMDD') || '%'\n)::TEXT, 4, '0');\nELSE\nv_batch_number := v_grn_record.batch_number;\nEND IF;\n\n-- Create batch\nINSERT INTO batches (\nproduct_id,\nsupplier_id,\nbatch_number,\npurchase_date,\nexpiry_date,\nmanufacture_date,\nquantity_purchased,\ncurrent_stock,\ncost_per_unit,\ncurrency,\ncreated_by\n) VALUES (\nv_grn_record.product_id,\nNEW.supplier_id,\nv_batch_number,\nNEW.grn_date,\nv_grn_record.expiry_date,\nv_grn_record.manufacture_date,\nv_grn_record.quantity_received,\nv_grn_record.quantity_received,\nv_grn_record.unit_cost,\nNEW.currency,\nNEW.created_by\n)\nRETURNING id INTO v_batch_id;\n\n-- Update GRN item with batch_id\nUPDATE goods_receipt_items\nSET batch_id = v_batch_id\nWHERE id = v_grn_record.id;\n\n-- Create inventory transaction\nINSERT INTO inventory_transactions (\nproduct_id,\nbatch_id,\ntransaction_type,\nquantity,\ntransaction_date,\nreference_number,\nreference_type,\nreference_id,\nnotes,\ncreated_by,\nstock_before,\nstock_after\n) VALUES (\nv_grn_record.product_id,\nv_batch_id,\n'purchase',\nv_grn_record.quantity_received,\nNEW.grn_date,\nNEW.grn_number,\n'goods_receipt_note',\nNEW.id,\n'GRN: ' || NEW.grn_number,\nNEW.created_by,\n0,\nv_grn_record.quantity_received\n);\nEND LOOP;\n\n-- Update PO received quantities if PO is linked\nIF NEW.po_id IS NOT NULL THEN\nUPDATE purchase_order_items poi\nSET quantity_received = quantity_received + gri.quantity_received\nFROM goods_receipt_items gri\nWHERE poi.id = gri.po_item_id\nAND gri.grn_id = NEW.id;\n\n-- Update PO status\nUPDATE purchase_orders po\nSET status = CASE\nWHEN (SELECT SUM(quantity_received) FROM purchase_order_items WHERE po_id = po.id) >= \n(SELECT SUM(quantity) FROM purchase_order_items WHERE po_id = po.id) THEN 'received'\nWHEN (SELECT SUM(quantity_received) FROM purchase_order_items WHERE po_id = po.id) > 0 THEN 'partially_received'\nELSE po.status\nEND\nWHERE po.id = NEW.po_id;\nEND IF;\n\n-- Set posted timestamp\nNEW.posted_at := NOW();\nNEW.posted_by := auth.uid();\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: trg_credit_note_inventory_v1(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_credit_note_inventory_v1\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_item record;\nBEGIN\n  IF NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved' THEN\n    IF EXISTS (\n      SELECT 1\n      FROM public.inventory_transactions\n      WHERE reference_type = 'credit_note_reversal'\n        AND reference_id = NEW.id\n        AND metadata->>'canonical_engine_version' = '1.0'\n    ) THEN\n      RAISE EXCEPTION 'Reversed Credit Note cannot be re-approved; create a new Credit Note';\n    END IF;\n\n    FOR v_item IN\n      SELECT *\n      FROM public.credit_note_items\n      WHERE credit_note_id = NEW.id\n      ORDER BY id\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text('inventory-v1:credit-note:' || NEW.id || ':' || v_item.id),\n        v_item.product_id,\n        v_item.batch_id,\n        'return',\n        v_item.quantity,\n        NEW.credit_note_date,\n        NEW.credit_note_number,\n        'credit_note',\n        NEW.id,\n        'Canonical Credit Note return: ' || NEW.credit_note_number,\n        NEW.approved_by,\n        NULL,\n        NULL\n      );\n    END LOOP;\n  ELSIF OLD.status = 'approved' AND NEW.status IS DISTINCT FROM 'approved' THEN\n    FOR v_item IN\n      SELECT *\n      FROM public.credit_note_items\n      WHERE credit_note_id = NEW.id\n      ORDER BY id\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text(\n          'inventory-v1:credit-note-reversal:' || NEW.id || ':' || v_item.id\n        ),\n        v_item.product_id,\n        v_item.batch_id,\n        'adjustment',\n        -v_item.quantity,\n        CURRENT_DATE,\n        NEW.credit_note_number,\n        'credit_note_reversal',\n        NEW.id,\n        'Canonical Credit Note reversal: ' || NEW.credit_note_number,\n        COALESCE(NEW.approved_by, auth.uid()),\n        NULL,\n        NULL\n      );\n    END LOOP;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trg_credit_note_item_inventory(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_credit_note_item_inventory\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_credit_note_number text;\nv_user_id uuid;\nBEGIN\nIF TG_OP = 'INSERT' THEN\n-- Get credit note details\nSELECT cn.credit_note_number, cn.created_by\nINTO v_credit_note_number, v_user_id\nFROM credit_notes cn\nWHERE cn.id = NEW.credit_note_id;\n\n-- Create inventory transaction to ADD stock back (positive quantity)\nINSERT INTO inventory_transactions (\nproduct_id,\nbatch_id,\ntransaction_type,\nquantity,\ntransaction_date,\nreference_number,\nnotes,\ncreated_by\n) VALUES (\nNEW.product_id,\nNEW.batch_id,\n'return',\nNEW.quantity,  -- Positive to add stock back\n(SELECT credit_note_date FROM credit_notes WHERE id = NEW.credit_note_id),\nv_credit_note_number,\n'Credit note (return): ' || v_credit_note_number,\nv_user_id\n);\n\nRETURN NEW;\n\nELSIF TG_OP = 'DELETE' THEN\n-- Get credit note number\nSELECT cn.credit_note_number\nINTO v_credit_note_number\nFROM credit_notes cn\nWHERE cn.id = OLD.credit_note_id;\n\n-- Reverse the return by deducting stock again\nINSERT INTO inventory_transactions (\nproduct_id,\nbatch_id,\ntransaction_type,\nquantity,\ntransaction_date,\nreference_number,\nnotes,\ncreated_by\n) VALUES (\nOLD.product_id,\nOLD.batch_id,\n'adjustment',\n-OLD.quantity,  -- Negative to remove stock\nCURRENT_DATE,\nv_credit_note_number,\n'Reversed credit note from deleted item',\nauth.uid()\n);\n\nRETURN OLD;\nEND IF;\nEND;\n$$","--\n-- Name: FUNCTION \\"trg_credit_note_item_inventory\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"trg_credit_note_item_inventory\\"() IS 'Handles inventory transactions for credit notes (adds stock back)'","--\n-- Name: trg_credit_note_item_stock(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_credit_note_item_stock\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_credit_note_number text;\nv_user_id uuid;\nv_current_stock numeric;\nv_old_status text;\nv_new_status text;\nBEGIN\nIF TG_OP = 'UPDATE' THEN\n-- Get old and new status\nSELECT status INTO v_old_status\nFROM credit_notes WHERE id = OLD.credit_note_id;\n\nSELECT status INTO v_new_status\nFROM credit_notes WHERE id = NEW.credit_note_id;\n\n-- Only act when status changes to 'approved'\nIF v_new_status = 'approved' AND v_old_status != 'approved' THEN\n-- Get credit note details\nSELECT credit_note_number, created_by\nINTO v_credit_note_number, v_user_id\nFROM credit_notes WHERE id = NEW.credit_note_id;\n\n-- Get current stock\nSELECT current_stock INTO v_current_stock\nFROM batches WHERE id = NEW.batch_id;\n\n-- DIRECTLY UPDATE BATCH STOCK (add back)\nUPDATE batches\nSET current_stock = current_stock + NEW.quantity\nWHERE id = NEW.batch_id;\n\n-- Log transaction\nINSERT INTO inventory_transactions (\nproduct_id, batch_id, transaction_type, quantity,\ntransaction_date, reference_number, reference_type, reference_id,\nnotes, created_by, stock_before, stock_after\n) VALUES (\nNEW.product_id, NEW.batch_id, 'return', NEW.quantity,\nCURRENT_DATE, v_credit_note_number, 'credit_note_item', NEW.id,\n'Credit note approved (return): ' || v_credit_note_number, v_user_id,\nv_current_stock, v_current_stock + NEW.quantity\n);\nEND IF;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: trg_dc_approval_deduct_stock(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_dc_approval_deduct_stock\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_item record;\nBEGIN\n  IF NEW.approval_status = 'approved'\n     AND OLD.approval_status IS DISTINCT FROM 'approved' THEN\n    IF NEW.approval_operation_id IS NULL THEN\n      RAISE EXCEPTION 'approval_operation_id is required for DC approval';\n    END IF;\n\n    IF EXISTS (\n      SELECT 1\n      FROM public.inventory_transactions\n      WHERE reference_type = 'delivery_challan_reversal'\n        AND reference_id = NEW.id\n        AND metadata->>'canonical_engine_version' = '1.0'\n    ) THEN\n      RAISE EXCEPTION 'Reversed Delivery Challan cannot be re-approved; create a new DC';\n    END IF;\n\n    IF NOT EXISTS (\n      SELECT 1\n      FROM public.delivery_challan_items\n      WHERE challan_id = NEW.id\n    ) THEN\n      RAISE EXCEPTION 'Cannot approve Delivery Challan % without items',\n        NEW.challan_number;\n    END IF;\n\n    FOR v_item IN\n      SELECT *\n      FROM public.delivery_challan_items\n      WHERE challan_id = NEW.id\n      ORDER BY id\n    LOOP\n      PERFORM public.inventory_v1_consume_reservation(\n        NEW.sales_order_id,\n        v_item.product_id,\n        v_item.batch_id,\n        v_item.quantity,\n        NEW.approved_by\n      );\n\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text(\n          'inventory-v1:dc:' || NEW.approval_operation_id || ':' || v_item.id\n        ),\n        v_item.product_id,\n        v_item.batch_id,\n        'delivery_challan',\n        -v_item.quantity,\n        NEW.challan_date,\n        NEW.challan_number,\n        'delivery_challan',\n        NEW.id,\n        'Canonical Delivery Challan approval: ' || NEW.challan_number,\n        NEW.approved_by,\n        NULL,\n        NULL\n      );\n    END LOOP;\n\n    IF NEW.sales_order_id IS NOT NULL THEN\n      PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trg_dc_approval_product_reservation_v2(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_dc_approval_product_reservation_v2\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE r record;\nBEGIN\n  IF NEW.approval_status='approved'\n     AND OLD.approval_status IN ('rejected','cancelled') THEN\n    RAISE EXCEPTION 'Reversed Delivery Challan cannot be re-approved; create a new Delivery Challan';\n  END IF;\n\n  IF NEW.approval_status='approved'\n     AND OLD.approval_status IS DISTINCT FROM 'approved' THEN\n    IF NEW.approval_operation_id IS NULL THEN\n      RAISE EXCEPTION 'approval_operation_id is required';\n    END IF;\n    IF NOT EXISTS(SELECT 1 FROM public.delivery_challan_items WHERE challan_id=NEW.id) THEN\n      RAISE EXCEPTION 'Cannot approve Delivery Challan % without items',NEW.challan_number;\n    END IF;\n    FOR r IN\n      SELECT id FROM public.delivery_challan_items WHERE challan_id=NEW.id ORDER BY id\n    LOOP\n      PERFORM public.consume_so_product_reservation_v2(\n        r.id,NEW.approval_operation_id,NEW.approved_by\n      );\n    END LOOP;\n    PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trg_dc_approval_recompute_so(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_dc_approval_recompute_so\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF NEW.approval_status = 'approved'\n     AND (OLD.approval_status IS DISTINCT FROM 'approved')\n     AND NEW.sales_order_id IS NOT NULL THEN\n    PERFORM fn_recompute_so_delivered(NEW.sales_order_id);\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trg_dc_approval_validate_stock(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_dc_approval_validate_stock\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_item RECORD;\nv_available_stock numeric;\nv_product_name text;\nv_batch_number text;\nv_unit text;\nBEGIN\n-- Only validate when status changes to 'approved'\nIF NEW.approval_status = 'approved' AND (OLD.approval_status IS NULL OR OLD.approval_status != 'approved') THEN\n\n-- Check stock for all items\nFOR v_item IN\nSELECT dci.*, p.product_name, p.unit, b.batch_number, b.current_stock, b.reserved_stock\nFROM delivery_challan_items dci\nJOIN products p ON dci.product_id = p.id\nJOIN batches b ON dci.batch_id = b.id\nWHERE dci.challan_id = NEW.id\nLOOP\n-- Calculate available stock\nv_available_stock := v_item.current_stock;\n\n-- Check if enough stock\nIF v_available_stock < v_item.quantity THEN\nRAISE EXCEPTION 'Insufficient stock for batch %!\n\nProduct: %\nBatch: %\nAvailable: % %\nRequested: % %\n\nPlease reduce quantity or select a different batch.',\nv_item.batch_number,\nv_item.product_name,\nv_item.batch_number,\nv_available_stock,\nCOALESCE(v_item.unit, 'units'),\nv_item.quantity,\nCOALESCE(v_item.unit, 'units');\nEND IF;\nEND LOOP;\n\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: trg_dc_cancellation_release_stock(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_dc_cancellation_release_stock\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_item          RECORD;\n  v_current_stock numeric;\n  v_was_approved  boolean;\nBEGIN\n  IF NEW.approval_status <> 'cancelled' THEN\n    RETURN NEW;\n  END IF;\n  IF OLD.approval_status = 'cancelled' THEN\n    RETURN NEW;\n  END IF;\n\n  v_was_approved := (OLD.approval_status = 'approved');\n\n  IF v_was_approved THEN\n    -- DC was approved → stock was deducted → reverse the deduction\n    FOR v_item IN\n      SELECT * FROM delivery_challan_items WHERE challan_id = NEW.id\n    LOOP\n      SELECT current_stock INTO v_current_stock FROM batches WHERE id = v_item.batch_id;\n\n      UPDATE batches\n         SET current_stock = current_stock + v_item.quantity,\n             updated_at = now()\n       WHERE id = v_item.batch_id;\n\n      INSERT INTO inventory_transactions (\n        product_id, batch_id, transaction_type, quantity,\n        transaction_date, reference_number, reference_type, reference_id,\n        notes, created_by, stock_before, stock_after\n      ) VALUES (\n        v_item.product_id, v_item.batch_id, 'adjustment', v_item.quantity,\n        CURRENT_DATE, NEW.challan_number, 'dc_cancelled', NEW.id,\n        'Reversed delivery from cancelled (previously approved) DC: ' || NEW.challan_number,\n        COALESCE(NEW.rejected_by, NEW.approved_by),\n        v_current_stock, v_current_stock + v_item.quantity\n      );\n    END LOOP;\n  END IF;\n  -- Non-approved DC: reservation is still active (correct); no stock was deducted.\n  -- No action needed on batches.reserved_stock.\n\n  IF NEW.sales_order_id IS NOT NULL THEN\n    PERFORM fn_recompute_so_delivered(NEW.sales_order_id);\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trg_dc_rejection_release_stock(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_dc_rejection_release_stock\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_item          RECORD;\n  v_current_stock numeric;\n  v_was_approved  boolean;\nBEGIN\n  IF NEW.approval_status <> 'rejected' THEN\n    RETURN NEW;\n  END IF;\n  IF OLD.approval_status = 'rejected' THEN\n    RETURN NEW;\n  END IF;\n\n  v_was_approved := (OLD.approval_status = 'approved');\n\n  IF v_was_approved THEN\n    -- DC was approved → stock was deducted → reverse the deduction\n    FOR v_item IN\n      SELECT * FROM delivery_challan_items WHERE challan_id = NEW.id\n    LOOP\n      SELECT current_stock INTO v_current_stock FROM batches WHERE id = v_item.batch_id;\n\n      UPDATE batches\n         SET current_stock = current_stock + v_item.quantity,\n             updated_at = now()\n       WHERE id = v_item.batch_id;\n\n      INSERT INTO inventory_transactions (\n        product_id, batch_id, transaction_type, quantity,\n        transaction_date, reference_number, reference_type, reference_id,\n        notes, created_by, stock_before, stock_after\n      ) VALUES (\n        v_item.product_id, v_item.batch_id, 'adjustment', v_item.quantity,\n        CURRENT_DATE, NEW.challan_number, 'dc_rejected', NEW.id,\n        'Reversed delivery from rejected (previously approved) DC: ' || NEW.challan_number,\n        COALESCE(NEW.rejected_by, NEW.approved_by),\n        v_current_stock, v_current_stock + v_item.quantity\n      );\n    END LOOP;\n  END IF;\n  -- Non-approved DC: reservation is still active (correct); no stock was deducted.\n  -- No action needed on batches.reserved_stock — trg_sync_batch_reserved_stock\n  -- keeps it accurate from stock_reservations.\n\n  -- Re-evaluate SO delivered quantity and status either way\n  IF NEW.sales_order_id IS NOT NULL THEN\n    PERFORM fn_recompute_so_delivered(NEW.sales_order_id);\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trg_dc_reverse_inventory_v1(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_dc_reverse_inventory_v1\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_item record;\nBEGIN\n  IF OLD.approval_status = 'approved'\n     AND NEW.approval_status IN ('rejected', 'cancelled') THEN\n    IF EXISTS (\n      SELECT 1\n      FROM public.sales_invoice_items sii\n      JOIN public.delivery_challan_items dci\n        ON dci.id = sii.delivery_challan_item_id\n      WHERE dci.challan_id = NEW.id\n    ) THEN\n      RAISE EXCEPTION\n        'Approved Delivery Challan already invoiced; reverse the invoice before cancelling';\n    END IF;\n\n    FOR v_item IN\n      SELECT *\n      FROM public.delivery_challan_items\n      WHERE challan_id = NEW.id\n      ORDER BY id\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text(\n          'inventory-v1:dc-reversal:' || NEW.id || ':' || v_item.id || ':' ||\n          NEW.approval_status\n        ),\n        v_item.product_id,\n        v_item.batch_id,\n        'adjustment',\n        v_item.quantity,\n        CURRENT_DATE,\n        NEW.challan_number,\n        'delivery_challan_reversal',\n        NEW.id,\n        'Canonical reversal of DC ' || NEW.challan_number ||\n          ' (' || NEW.approval_status || ')',\n        COALESCE(NEW.rejected_by, NEW.approved_by, auth.uid()),\n        NULL,\n        NULL\n      );\n    END LOOP;\n\n    IF NEW.sales_order_id IS NOT NULL THEN\n      PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);\n      PERFORM public.fn_reserve_stock_for_so_v2(NEW.sales_order_id);\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trg_dc_reverse_product_reservation_v2(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_dc_reverse_product_reservation_v2\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE r record;\nBEGIN\n  IF OLD.approval_status='approved' AND NEW.approval_status IN ('rejected','cancelled') THEN\n    IF EXISTS(SELECT 1 FROM public.sales_invoice_items sii JOIN public.delivery_challan_items dci ON dci.id=sii.delivery_challan_item_id WHERE dci.challan_id=NEW.id)\n      THEN RAISE EXCEPTION 'Approved Delivery Challan already invoiced; reverse invoice first'; END IF;\n    FOR r IN SELECT dci.*,a.id allocation_id FROM public.delivery_challan_items dci\n      JOIN public.dc_batch_allocations a ON a.delivery_challan_item_id=dci.id AND a.status='consumed'\n      WHERE dci.challan_id=NEW.id ORDER BY dci.id FOR UPDATE OF a LOOP\n      PERFORM public.post_inventory_movement(public.uuid_from_text('inventory-v2:dc-reversal:'||NEW.id||':'||r.id),r.product_id,r.batch_id,\n        'adjustment',r.quantity,CURRENT_DATE,NEW.challan_number,'delivery_challan_reversal',NEW.id,\n        'Reversal of product-reservation DC batch allocation',COALESCE(NEW.rejected_by,auth.uid()),NULL,NULL);\n      UPDATE public.dc_batch_allocations SET status='reversed',reversed_at=now(),reversal_reason=NEW.approval_status WHERE id=r.allocation_id;\n    END LOOP;\n    PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);\n    FOR r IN SELECT DISTINCT sales_order_item_id FROM public.delivery_challan_items WHERE challan_id=NEW.id LOOP\n      PERFORM public.reconcile_so_product_reservation_v2(r.sales_order_item_id,'DC reversal');\n    END LOOP;\n  END IF;\n  RETURN NEW;\nEND; $$","--\n-- Name: trg_generate_grn_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_generate_grn_number\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF NEW.grn_number IS NULL OR NEW.grn_number = '' THEN\nNEW.grn_number := generate_grn_number();\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: trg_generate_import_cost_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_generate_import_cost_number\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF NEW.cost_sheet_number IS NULL OR NEW.cost_sheet_number = '' THEN\nNEW.cost_sheet_number := generate_import_cost_number();\nEND IF;\n\n-- Calculate total landed cost\nNEW.total_landed_cost := NEW.fob_value + NEW.duty_amount + NEW.ppn_import_amount + \nNEW.pph22_amount + NEW.freight_amount + NEW.insurance_amount +\nNEW.clearing_amount + NEW.port_charges + NEW.other_charges;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: trg_generate_po_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_generate_po_number\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF NEW.po_number IS NULL OR NEW.po_number = '' THEN\nNEW.po_number := generate_po_number();\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: trg_generate_so_number(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_generate_so_number\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF NEW.so_number IS NULL OR NEW.so_number = '' THEN\nNEW.so_number := generate_so_number();\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: trg_material_return_inventory_v1(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_material_return_inventory_v1\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_item record;\n  v_is_stocked boolean;\n  v_was_stocked boolean;\nBEGIN\n  v_is_stocked := NEW.status IN ('approved', 'completed') AND NEW.restocked = true;\n  v_was_stocked := OLD.status IN ('approved', 'completed') AND OLD.restocked = true;\n\n  IF v_is_stocked AND NOT v_was_stocked THEN\n    IF EXISTS (\n      SELECT 1\n      FROM public.inventory_transactions\n      WHERE reference_type = 'material_return_reversal'\n        AND reference_id = NEW.id\n        AND metadata->>'canonical_engine_version' = '1.0'\n    ) THEN\n      RAISE EXCEPTION 'Reversed Material Return cannot be re-approved; create a new return';\n    END IF;\n\n    FOR v_item IN\n      SELECT *\n      FROM public.material_return_items\n      WHERE return_id = NEW.id\n        AND disposition = 'restock'\n        AND batch_id IS NOT NULL\n      ORDER BY id\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text('inventory-v1:material-return:' || NEW.id || ':' || v_item.id),\n        v_item.product_id,\n        v_item.batch_id,\n        'return',\n        v_item.quantity_returned,\n        NEW.return_date,\n        NEW.return_number,\n        'material_return',\n        NEW.id,\n        'Canonical Material Return: ' || NEW.return_number,\n        NEW.approved_by,\n        NULL,\n        NULL\n      );\n    END LOOP;\n  ELSIF v_was_stocked AND NOT v_is_stocked THEN\n    FOR v_item IN\n      SELECT *\n      FROM public.material_return_items\n      WHERE return_id = NEW.id\n        AND disposition = 'restock'\n        AND batch_id IS NOT NULL\n      ORDER BY id\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text(\n          'inventory-v1:material-return-reversal:' || NEW.id || ':' || v_item.id\n        ),\n        v_item.product_id,\n        v_item.batch_id,\n        'adjustment',\n        -v_item.quantity_returned,\n        CURRENT_DATE,\n        NEW.return_number,\n        'material_return_reversal',\n        NEW.id,\n        'Canonical Material Return reversal: ' || NEW.return_number,\n        COALESCE(NEW.approved_by, auth.uid()),\n        NULL,\n        NULL\n      );\n    END LOOP;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trg_material_return_item_stock(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_material_return_item_stock\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_return_number text;\nv_user_id uuid;\nv_current_stock numeric;\nv_old_status text;\nv_return_status text;\nBEGIN\nIF TG_OP = 'UPDATE' THEN\n-- Get return status\nSELECT status INTO v_return_status\nFROM material_returns WHERE id = NEW.return_id;\n\n-- Only act when material return is approved\nIF v_return_status = 'approved' THEN\n-- Check if this item's disposition changed to restock/pending\nIF NEW.disposition IN ('restock', 'pending') AND \n(OLD.disposition IS NULL OR OLD.disposition NOT IN ('restock', 'pending')) THEN\n\n-- Get return details\nSELECT return_number, created_by\nINTO v_return_number, v_user_id\nFROM material_returns WHERE id = NEW.return_id;\n\n-- Get current stock\nSELECT current_stock INTO v_current_stock\nFROM batches WHERE id = NEW.batch_id;\n\n-- DIRECTLY UPDATE BATCH STOCK (add back)\nUPDATE batches\nSET current_stock = current_stock + NEW.quantity_returned\nWHERE id = NEW.batch_id;\n\n-- Log transaction\nINSERT INTO inventory_transactions (\nproduct_id, batch_id, transaction_type, quantity,\ntransaction_date, reference_number, reference_type, reference_id,\nnotes, created_by, stock_before, stock_after\n) VALUES (\nNEW.product_id, NEW.batch_id, 'return', NEW.quantity_returned,\nCURRENT_DATE, v_return_number, 'material_return_item', NEW.id,\n'Material return approved (restock): ' || v_return_number, v_user_id,\nv_current_stock, v_current_stock + NEW.quantity_returned\n);\nEND IF;\nEND IF;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: trg_recompute_from_credit_note(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_recompute_from_credit_note\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    PERFORM recompute_periods_for_date(OLD.credit_note_date);\n  ELSE\n    PERFORM recompute_periods_for_date(NEW.credit_note_date);\n    IF TG_OP = 'UPDATE'\n       AND (NEW.credit_note_date IS DISTINCT FROM OLD.credit_note_date) THEN\n      PERFORM recompute_periods_for_date(OLD.credit_note_date);\n    END IF;\n  END IF;\n  RETURN NULL;\nEND $$","--\n-- Name: trg_recompute_from_expense(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_recompute_from_expense\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF COALESCE(OLD.pph_amount, 0) > 0\n       OR COALESCE(OLD.pib_pph_amount, 0) > 0\n       OR OLD.expense_category = 'pph_import' THEN\n      PERFORM public.recompute_pph_periods_for_date(COALESCE(OLD.due_date, OLD.expense_date));\n    END IF;\n  ELSE\n    IF COALESCE(NEW.pph_amount, 0) > 0\n       OR COALESCE(NEW.pib_pph_amount, 0) > 0\n       OR NEW.expense_category = 'pph_import' THEN\n      PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(NEW.id));\n    END IF;\n    IF TG_OP = 'UPDATE' THEN\n      IF COALESCE(OLD.pph_amount, 0) > 0\n         OR COALESCE(OLD.pib_pph_amount, 0) > 0\n         OR OLD.expense_category = 'pph_import' THEN\n        PERFORM public.recompute_pph_periods_for_date(COALESCE(OLD.due_date, OLD.expense_date));\n        PERFORM public.recompute_pph_periods_for_date(OLD.expense_date);\n      END IF;\n    END IF;\n  END IF;\n  RETURN NULL;\nEND;\n$$","--\n-- Name: trg_recompute_from_finance_expense(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_recompute_from_finance_expense\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    PERFORM recompute_periods_for_date(OLD.expense_date);\n  ELSE\n    PERFORM recompute_periods_for_date(NEW.expense_date);\n    IF TG_OP = 'UPDATE'\n       AND (NEW.expense_date IS DISTINCT FROM OLD.expense_date) THEN\n      PERFORM recompute_periods_for_date(OLD.expense_date);\n    END IF;\n  END IF;\n  RETURN NULL;\nEND $$","--\n-- Name: trg_recompute_from_payment_voucher(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_recompute_from_payment_voucher\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_expense_id uuid;\nBEGIN\n  IF TG_OP IN ('UPDATE', 'DELETE') THEN\n    IF COALESCE(OLD.pph_amount, 0) > 0 THEN\n      PERFORM public.recompute_pph_periods_for_date(OLD.voucher_date);\n    END IF;\n  END IF;\n  IF TG_OP IN ('INSERT', 'UPDATE') THEN\n    IF COALESCE(NEW.pph_amount, 0) > 0 THEN\n      PERFORM public.recompute_pph_periods_for_date(NEW.voucher_date);\n    END IF;\n  END IF;\n\n  FOR v_expense_id IN\n    SELECT DISTINCT va.finance_expense_id\n    FROM public.voucher_allocations va\n    JOIN public.finance_expenses fe ON fe.id = va.finance_expense_id\n    WHERE va.payment_voucher_id = COALESCE(NEW.id, OLD.id)\n      AND va.finance_expense_id IS NOT NULL\n      AND (\n        COALESCE(fe.pph_amount, 0) > 0\n        OR COALESCE(fe.pib_pph_amount, 0) > 0\n        OR fe.expense_category = 'pph_import'\n      )\n  LOOP\n    PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_expense_id));\n  END LOOP;\n  RETURN NULL;\nEND;\n$$","--\n-- Name: trg_recompute_from_purchase_invoice(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_recompute_from_purchase_invoice\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    PERFORM recompute_periods_for_date(OLD.invoice_date);\n  ELSE\n    PERFORM recompute_periods_for_date(NEW.invoice_date);\n    IF TG_OP = 'UPDATE'\n       AND (NEW.invoice_date IS DISTINCT FROM OLD.invoice_date) THEN\n      PERFORM recompute_periods_for_date(OLD.invoice_date);\n    END IF;\n  END IF;\n  RETURN NULL;\nEND $$","--\n-- Name: trg_recompute_from_sales_invoice(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_recompute_from_sales_invoice\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    PERFORM recompute_periods_for_date(OLD.invoice_date);\n  ELSE\n    PERFORM recompute_periods_for_date(NEW.invoice_date);\n    IF TG_OP = 'UPDATE'\n       AND (NEW.invoice_date IS DISTINCT FROM OLD.invoice_date) THEN\n      PERFORM recompute_periods_for_date(OLD.invoice_date);\n    END IF;\n  END IF;\n  RETURN NULL;\nEND $$","--\n-- Name: trg_recompute_from_tax_payment(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_recompute_from_tax_payment\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    PERFORM compute_period_ppn(OLD.tax_period_id);\n  ELSE\n    PERFORM compute_period_ppn(NEW.tax_period_id);\n    IF TG_OP = 'UPDATE'\n       AND NEW.tax_period_id IS DISTINCT FROM OLD.tax_period_id THEN\n      PERFORM compute_period_ppn(OLD.tax_period_id);\n    END IF;\n  END IF;\n  RETURN NULL;\nEND $$","--\n-- Name: trg_recompute_pph_from_bank_line(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_recompute_pph_from_bank_line\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_expense_id uuid;\n  v_date date;\nBEGIN\n  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.matched_expense_id IS NOT NULL THEN\n    v_expense_id := OLD.matched_expense_id;\n    PERFORM 1 FROM public.finance_expenses fe\n    WHERE fe.id = v_expense_id\n      AND (COALESCE(fe.pph_amount, 0) > 0 OR COALESCE(fe.pib_pph_amount, 0) > 0 OR fe.expense_category = 'pph_import');\n    IF NOT FOUND THEN\n      v_expense_id := NULL;\n    END IF;\n  END IF;\n  IF TG_OP IN ('UPDATE', 'DELETE') AND v_expense_id IS NOT NULL THEN\n    PERFORM public.recompute_pph_periods_for_date(OLD.transaction_date);\n    PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_expense_id));\n    SELECT COALESCE(due_date, expense_date) INTO v_date FROM public.finance_expenses WHERE id = v_expense_id;\n    PERFORM public.recompute_pph_periods_for_date(v_date);\n  END IF;\n\n  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.matched_expense_id IS NOT NULL THEN\n    v_expense_id := NEW.matched_expense_id;\n    PERFORM 1 FROM public.finance_expenses fe\n    WHERE fe.id = v_expense_id\n      AND (COALESCE(fe.pph_amount, 0) > 0 OR COALESCE(fe.pib_pph_amount, 0) > 0 OR fe.expense_category = 'pph_import');\n    IF NOT FOUND THEN\n      v_expense_id := NULL;\n    END IF;\n  END IF;\n  IF TG_OP IN ('INSERT', 'UPDATE') AND v_expense_id IS NOT NULL THEN\n    PERFORM public.recompute_pph_periods_for_date(NEW.transaction_date);\n    PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_expense_id));\n    SELECT COALESCE(due_date, expense_date) INTO v_date FROM public.finance_expenses WHERE id = v_expense_id;\n    PERFORM public.recompute_pph_periods_for_date(v_date);\n  END IF;\n  RETURN NULL;\nEND;\n$$","--\n-- Name: trg_recompute_pph_from_voucher_allocation(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_recompute_pph_from_voucher_allocation\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_expense_id uuid;\n  v_voucher_id uuid;\n  v_date date;\nBEGIN\n  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.finance_expense_id IS NOT NULL THEN\n    v_expense_id := OLD.finance_expense_id;\n    PERFORM 1 FROM public.finance_expenses fe\n    WHERE fe.id = v_expense_id\n      AND (COALESCE(fe.pph_amount, 0) > 0 OR COALESCE(fe.pib_pph_amount, 0) > 0 OR fe.expense_category = 'pph_import');\n    IF NOT FOUND THEN\n      v_expense_id := NULL;\n    END IF;\n  END IF;\n  IF TG_OP IN ('UPDATE', 'DELETE') AND v_expense_id IS NOT NULL THEN\n    v_voucher_id := OLD.payment_voucher_id;\n    SELECT voucher_date INTO v_date FROM public.payment_vouchers WHERE id = v_voucher_id;\n    PERFORM public.recompute_pph_periods_for_date(v_date);\n    PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_expense_id));\n    SELECT COALESCE(due_date, expense_date) INTO v_date FROM public.finance_expenses WHERE id = v_expense_id;\n    PERFORM public.recompute_pph_periods_for_date(v_date);\n  END IF;\n\n  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.finance_expense_id IS NOT NULL THEN\n    v_expense_id := NEW.finance_expense_id;\n    PERFORM 1 FROM public.finance_expenses fe\n    WHERE fe.id = v_expense_id\n      AND (COALESCE(fe.pph_amount, 0) > 0 OR COALESCE(fe.pib_pph_amount, 0) > 0 OR fe.expense_category = 'pph_import');\n    IF NOT FOUND THEN\n      v_expense_id := NULL;\n    END IF;\n  END IF;\n  IF TG_OP IN ('INSERT', 'UPDATE') AND v_expense_id IS NOT NULL THEN\n    v_voucher_id := NEW.payment_voucher_id;\n    SELECT voucher_date INTO v_date FROM public.payment_vouchers WHERE id = v_voucher_id;\n    PERFORM public.recompute_pph_periods_for_date(v_date);\n    PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_expense_id));\n    SELECT COALESCE(due_date, expense_date) INTO v_date FROM public.finance_expenses WHERE id = v_expense_id;\n    PERFORM public.recompute_pph_periods_for_date(v_date);\n  END IF;\n  RETURN NULL;\nEND;\n$$","--\n-- Name: trg_recompute_tax_from_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_recompute_tax_from_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_source_module text := CASE WHEN TG_OP = 'DELETE' THEN OLD.source_module ELSE NEW.source_module END;\n  v_reference_id uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.reference_id ELSE NEW.reference_id END;\n  v_entry_date date := CASE WHEN TG_OP = 'DELETE' THEN OLD.entry_date ELSE NEW.entry_date END;\n  v_source_date date;\nBEGIN\n  IF v_reference_id IS NULL THEN RETURN NULL; END IF;\n\n  IF v_source_module IN ('expense', 'expenses') THEN\n    SELECT expense_date INTO v_source_date FROM public.finance_expenses WHERE id = v_reference_id;\n  ELSIF v_source_module IN ('payment', 'payments', 'payment_voucher') THEN\n    SELECT voucher_date INTO v_source_date FROM public.payment_vouchers WHERE id = v_reference_id;\n  ELSE\n    RETURN NULL;\n  END IF;\n\n  PERFORM public.recompute_periods_for_date(COALESCE(v_source_date, v_entry_date));\n\n  IF TG_OP = 'UPDATE' AND OLD.entry_date IS DISTINCT FROM NEW.entry_date THEN\n    PERFORM public.recompute_periods_for_date(OLD.entry_date);\n  END IF;\n  RETURN NULL;\nEND;\n$$","--\n-- Name: trg_reconcile_active_so_item_v2(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_reconcile_active_so_item_v2\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_status text;\nBEGIN\n  IF TG_OP='DELETE' THEN\n    IF EXISTS(SELECT 1 FROM public.so_product_reservations WHERE sales_order_item_id=OLD.id) THEN\n      RAISE EXCEPTION 'Sales Order item has reservation history and cannot be deleted; cancel/void the order or adjust quantity';\n    END IF;\n    RETURN OLD;\n  END IF;\n  SELECT status::text INTO v_status FROM public.sales_orders WHERE id=NEW.sales_order_id;\n  IF v_status IN ('approved','stock_reserved','pending_delivery','partially_delivered') THEN\n    PERFORM public.reconcile_so_product_reservation_v2(NEW.id,'Approved SO item changed');\n  END IF;\n  RETURN NEW;\nEND; $$","--\n-- Name: trg_release_so_product_reservation_status_v2(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_release_so_product_reservation_status_v2\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF NEW.status::text IN ('rejected','cancelled','closed','delivered')\n     AND OLD.status::text IS DISTINCT FROM NEW.status::text THEN\n    PERFORM public.release_so_product_reservations_v2(NEW.id,'SO status changed to '||NEW.status::text);\n  END IF;\n  RETURN NEW;\nEND; $$","--\n-- Name: trg_sales_invoice_item_inventory(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_sales_invoice_item_inventory\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_dc_item public.delivery_challan_items%ROWTYPE;\n  v_dc_status text;\n  v_invoiced_quantity numeric;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n\n  IF NEW.delivery_challan_item_id IS NULL THEN\n    RAISE EXCEPTION 'Sales Invoice item must reference an approved Delivery Challan item';\n  END IF;\n\n  SELECT dci.*\n  INTO v_dc_item\n  FROM public.delivery_challan_items dci\n  WHERE dci.id = NEW.delivery_challan_item_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Invoice item references a missing Delivery Challan item';\n  END IF;\n\n  SELECT dc.approval_status::text\n  INTO v_dc_status\n  FROM public.delivery_challans dc\n  WHERE dc.id = v_dc_item.challan_id;\n\n  IF NOT FOUND OR v_dc_status <> 'approved' THEN\n    RAISE EXCEPTION 'Sales Invoice item references a non-approved Delivery Challan item';\n  END IF;\n  IF NEW.product_id IS DISTINCT FROM v_dc_item.product_id\n     OR NEW.batch_id IS DISTINCT FROM v_dc_item.batch_id THEN\n    RAISE EXCEPTION 'Sales Invoice product/batch must match its Delivery Challan item';\n  END IF;\n\n  SELECT COALESCE(SUM(sii.quantity), 0)\n  INTO v_invoiced_quantity\n  FROM public.sales_invoice_items sii\n  WHERE sii.delivery_challan_item_id = NEW.delivery_challan_item_id\n    AND sii.id IS DISTINCT FROM NEW.id;\n\n  IF v_invoiced_quantity + NEW.quantity > v_dc_item.quantity THEN\n    RAISE EXCEPTION 'Sales Invoice quantity exceeds approved Delivery Challan quantity';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"trg_sales_invoice_item_inventory\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"trg_sales_invoice_item_inventory\\"() IS 'Bulletproof invoice inventory management. Directly updates batch stock for manual items only. DC items skip stock changes.'","--\n-- Name: trg_sales_order_deleted(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_sales_order_deleted\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- Release reservations when SO is deleted\nPERFORM fn_release_stock_reservations(OLD.id, 'Sales order deleted');\nRETURN OLD;\nEND;\n$$","--\n-- Name: trg_stock_rejection_approved(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_stock_rejection_approved\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_current_stock numeric;\nBEGIN\nIF TG_OP = 'UPDATE' AND NEW.status = 'approved' AND OLD.status != 'approved' THEN\n-- Get current stock\nSELECT current_stock INTO v_current_stock\nFROM batches WHERE id = NEW.batch_id;\n\n-- DIRECTLY UPDATE BATCH STOCK (deduct)\nUPDATE batches\nSET current_stock = current_stock - NEW.quantity_rejected\nWHERE id = NEW.batch_id;\n\n-- Log transaction\nINSERT INTO inventory_transactions (\nproduct_id, batch_id, transaction_type, quantity,\ntransaction_date, reference_number, reference_type, reference_id,\nnotes, created_by, stock_before, stock_after\n) VALUES (\nNEW.product_id, NEW.batch_id, 'adjustment', -NEW.quantity_rejected,\nNEW.rejection_date, NEW.rejection_number, 'stock_rejection', NEW.id,\n'Stock rejection approved: ' || NEW.rejection_reason, NEW.created_by,\nv_current_stock, v_current_stock - NEW.quantity_rejected\n);\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: trg_stock_rejection_inventory_v1(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_stock_rejection_inventory_v1\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF NEW.status IN ('approved', 'disposed')\n     AND OLD.status NOT IN ('approved', 'disposed') THEN\n    IF EXISTS (\n      SELECT 1\n      FROM public.inventory_transactions\n      WHERE reference_type = 'stock_rejection_reversal'\n        AND reference_id = NEW.id\n        AND metadata->>'canonical_engine_version' = '1.0'\n    ) THEN\n      RAISE EXCEPTION 'Reversed Stock Rejection cannot be re-approved; create a new rejection';\n    END IF;\n\n    PERFORM public.post_inventory_movement(\n      public.uuid_from_text('inventory-v1:stock-rejection:' || NEW.id),\n      NEW.product_id,\n      NEW.batch_id,\n      'rejection',\n      -NEW.quantity_rejected,\n      NEW.rejection_date,\n      NEW.rejection_number,\n      'stock_rejection',\n      NEW.id,\n      'Canonical Stock Rejection: ' || NEW.rejection_number,\n      NEW.approved_by,\n      NULL,\n      NULL\n    );\n  ELSIF OLD.status IN ('approved', 'disposed')\n        AND NEW.status NOT IN ('approved', 'disposed') THEN\n    PERFORM public.post_inventory_movement(\n      public.uuid_from_text('inventory-v1:stock-rejection-reversal:' || NEW.id),\n      NEW.product_id,\n      NEW.batch_id,\n      'adjustment',\n      NEW.quantity_rejected,\n      CURRENT_DATE,\n      NEW.rejection_number,\n      'stock_rejection_reversal',\n      NEW.id,\n      'Canonical Stock Rejection reversal: ' || NEW.rejection_number,\n      COALESCE(NEW.approved_by, auth.uid()),\n      NULL,\n      NULL\n    );\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trg_sync_batch_reserved_stock(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_sync_batch_reserved_stock\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- Recalculate reserved_stock from actual active reservations\nUPDATE batches\nSET reserved_stock = COALESCE((\nSELECT SUM(reserved_quantity)\nFROM stock_reservations\nWHERE batch_id = batches.id AND status = 'active'\n), 0)\nWHERE id = COALESCE(NEW.batch_id, OLD.batch_id);\n\nRETURN COALESCE(NEW, OLD);\nEND;\n$$","--\n-- Name: trg_sync_expense_pph_account(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_sync_expense_pph_account\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_account_id uuid;\n  v_journal_id uuid;\n  v_line_number integer;\nBEGIN\n  IF NEW.expense_category = 'import_broker' THEN\n    RETURN NEW;\n  END IF;\n  IF COALESCE(NEW.pph_amount, 0) <= 0 THEN\n    RETURN NEW;\n  END IF;\n\n  v_account_id := fn_pph_payable_account_id(NEW.pph_code_id);\n  IF v_account_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT id INTO v_journal_id\n    FROM journal_entries\n   WHERE reference_id = NEW.id\n     AND source_module = 'expenses'\n   ORDER BY created_at DESC\n   LIMIT 1;\n  IF v_journal_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM journal_entry_lines\n     WHERE journal_entry_id = v_journal_id\n       AND debit = 0\n       AND description ILIKE 'PPh Ditahan%'\n  ) THEN\n    UPDATE journal_entry_lines\n       SET account_id = v_account_id\n     WHERE journal_entry_id = v_journal_id\n       AND debit = 0\n       AND description ILIKE 'PPh Ditahan%';\n  ELSE\n    UPDATE journal_entry_lines\n       SET credit = credit - NEW.pph_amount\n     WHERE id = (\n       SELECT id FROM journal_entry_lines\n        WHERE journal_entry_id = v_journal_id\n          AND credit >= NEW.pph_amount\n        ORDER BY credit DESC, line_number DESC\n        LIMIT 1\n     );\n\n    SELECT COALESCE(MAX(line_number), 0) + 1 INTO v_line_number\n      FROM journal_entry_lines\n     WHERE journal_entry_id = v_journal_id;\n\n    INSERT INTO journal_entry_lines\n      (journal_entry_id, line_number, account_id, debit, credit, description)\n    VALUES\n      (v_journal_id, v_line_number, v_account_id, 0, NEW.pph_amount,\n       'PPh Ditahan - ' || COALESCE(NEW.description, NEW.voucher_number, 'Expense'));\n  END IF;\n\n  UPDATE journal_entries\n     SET total_debit = (SELECT COALESCE(SUM(debit), 0) FROM journal_entry_lines WHERE journal_entry_id = v_journal_id),\n         total_credit = (SELECT COALESCE(SUM(credit), 0) FROM journal_entry_lines WHERE journal_entry_id = v_journal_id)\n   WHERE id = v_journal_id;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trg_sync_price_request_counts(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_sync_price_request_counts\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF TG_OP = 'DELETE' THEN\nPERFORM recompute_price_request_counts(OLD.price_request_id);\nRETURN OLD;\nELSE\nPERFORM recompute_price_request_counts(NEW.price_request_id);\nRETURN NEW;\nEND IF;\nEND;\n$$","--\n-- Name: trg_update_po_timestamp(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_update_po_timestamp\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nNEW.updated_at := NOW();\nRETURN NEW;\nEND;\n$$","--\n-- Name: trg_update_timestamp(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trg_update_timestamp\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nNEW.updated_at := now();\nRETURN NEW;\nEND;\n$$","--\n-- Name: trigger_delivery_challan_task(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trigger_delivery_challan_task\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_task_id uuid;\nv_event_id uuid;\nv_customer_name text;\nv_item_count int;\nBEGIN\nIF TG_OP = 'INSERT' THEN\nSELECT company_name INTO v_customer_name FROM customers WHERE id = NEW.customer_id;\nSELECT COUNT(*) INTO v_item_count FROM delivery_challan_items WHERE delivery_challan_id = NEW.id;\n\nINSERT INTO system_task_events (event_type, event_source, entity_type, entity_id, event_data)\nVALUES ('delivery_challan_created', 'delivery_challans', 'delivery_challan', NEW.id, jsonb_build_object(\n'challan_number', NEW.challan_number, 'customer_id', NEW.customer_id, 'customer_name', v_customer_name\n)) RETURNING id INTO v_event_id;\n\nv_task_id := create_system_task(\np_title := 'Deliver Challan ' || NEW.challan_number,\np_description := 'Delivery Challan created for ' || v_customer_name || '. Items: ' || v_item_count::text || E'\\\\n\\\\n' ||\n'Complete delivery and obtain customer signature.',\np_deadline := COALESCE(NEW.challan_date::timestamptz + interval '2 days', now() + interval '2 days'),\np_origin := 'delivery_challan_created',\np_reference_type := 'delivery_challan',\np_reference_id := NEW.id,\np_assigned_role := 'warehouse',\np_customer_id := NEW.customer_id\n);\nUPDATE system_task_events SET task_id = v_task_id, task_created = true, processed_at = now() WHERE id = v_event_id;\nEND IF;\nRETURN NEW;\nEXCEPTION WHEN OTHERS THEN\nIF v_event_id IS NOT NULL THEN\nUPDATE system_task_events SET error_message = SQLERRM, processed_at = now() WHERE id = v_event_id;\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: trigger_reallocate_on_batch_container_change(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trigger_reallocate_on_batch_container_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- If container link added/changed\nIF NEW.import_container_id IS NOT NULL AND (OLD.import_container_id IS NULL OR OLD.import_container_id != NEW.import_container_id) THEN\nPERFORM reallocate_container_costs(NEW.import_container_id);\nEND IF;\n\n-- If container link removed\nIF OLD.import_container_id IS NOT NULL AND (NEW.import_container_id IS NULL OR OLD.import_container_id != NEW.import_container_id) THEN\nPERFORM reallocate_container_costs(OLD.import_container_id);\nEND IF;\n\n-- If quantity changed and has container\nIF NEW.import_container_id IS NOT NULL AND OLD.import_quantity != NEW.import_quantity THEN\nPERFORM reallocate_container_costs(NEW.import_container_id);\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: trigger_reallocate_on_batch_delete(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trigger_reallocate_on_batch_delete\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF OLD.import_container_id IS NOT NULL THEN\nPERFORM reallocate_container_costs(OLD.import_container_id);\nEND IF;\nRETURN OLD;\nEND;\n$$","--\n-- Name: trigger_reallocate_on_container_cost_change(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trigger_reallocate_on_container_cost_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF (OLD.duty_a1 IS DISTINCT FROM NEW.duty_a1 OR\n      OLD.duty_bm IS DISTINCT FROM NEW.duty_bm OR\n      OLD.ppn_import IS DISTINCT FROM NEW.ppn_import OR\n      OLD.pph_import IS DISTINCT FROM NEW.pph_import OR\n      OLD.freight_charges IS DISTINCT FROM NEW.freight_charges OR\n      OLD.other_import_costs IS DISTINCT FROM NEW.other_import_costs OR\n      OLD.bpom_ski_fees IS DISTINCT FROM NEW.bpom_ski_fees) THEN\n    PERFORM reallocate_container_costs(NEW.id);\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: trigger_reallocate_on_container_update(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trigger_reallocate_on_container_update\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF (OLD.total_import_expenses IS DISTINCT FROM NEW.total_import_expenses OR\nOLD.duty_bm IS DISTINCT FROM NEW.duty_bm OR\nOLD.ppn_import IS DISTINCT FROM NEW.ppn_import OR\nOLD.pph_import IS DISTINCT FROM NEW.pph_import OR\nOLD.freight_charges IS DISTINCT FROM NEW.freight_charges OR\nOLD.other_import_costs IS DISTINCT FROM NEW.other_import_costs OR\nOLD.bpom_ski_fees IS DISTINCT FROM NEW.bpom_ski_fees) THEN\nPERFORM reallocate_container_costs(NEW.id);\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: trigger_recalc_batches_on_container_change(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trigger_recalc_batches_on_container_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF NEW.id IS NOT NULL THEN\nPERFORM public.reallocate_container_costs(NEW.id);\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: trigger_recalc_batches_on_expense_change(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trigger_recalc_batches_on_expense_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_container_id uuid;\nBEGIN\n-- Determine the container ID from OLD or NEW\nv_container_id := COALESCE(NEW.import_container_id, OLD.import_container_id);\n\nIF v_container_id IS NOT NULL THEN\nPERFORM public.reallocate_container_costs(v_container_id);\nEND IF;\n\n-- If the expense moved from one container to another, recalc the old one too\nIF TG_OP = 'UPDATE' AND OLD.import_container_id IS NOT NULL\nAND NEW.import_container_id IS DISTINCT FROM OLD.import_container_id THEN\nPERFORM public.reallocate_container_costs(OLD.import_container_id);\nEND IF;\n\nRETURN COALESCE(NEW, OLD);\nEND;\n$$","--\n-- Name: trigger_recalc_batches_on_petty_cash_change(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trigger_recalc_batches_on_petty_cash_change\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_container_id uuid;\nBEGIN\nv_container_id := COALESCE(NEW.import_container_id, OLD.import_container_id);\n\nIF v_container_id IS NOT NULL THEN\nPERFORM public.reallocate_container_costs(v_container_id);\nEND IF;\n\nIF TG_OP = 'UPDATE' AND OLD.import_container_id IS NOT NULL\nAND NEW.import_container_id IS DISTINCT FROM OLD.import_container_id THEN\nPERFORM public.reallocate_container_costs(OLD.import_container_id);\nEND IF;\n\nRETURN COALESCE(NEW, OLD);\nEND;\n$$","--\n-- Name: trigger_sales_order_approved_task(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trigger_sales_order_approved_task\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_task_id uuid;\nv_event_id uuid;\nv_customer_name text;\nv_has_shortage boolean;\nBEGIN\nIF NEW.status IN ('approved', 'stock_reserved') AND OLD.status != NEW.status THEN\nSELECT company_name INTO v_customer_name FROM customers WHERE id = NEW.customer_id;\nSELECT EXISTS(SELECT 1 FROM import_requirements WHERE sales_order_id = NEW.id) INTO v_has_shortage;\n\nINSERT INTO system_task_events (event_type, event_source, entity_type, entity_id, event_data)\nVALUES ('sales_order_approved', 'sales_orders', 'sales_order', NEW.id, jsonb_build_object(\n'so_number', NEW.so_number, 'customer_id', NEW.customer_id,\n'customer_name', v_customer_name, 'has_shortage', v_has_shortage\n)) RETURNING id INTO v_event_id;\n\nIF NEW.status = 'stock_reserved' AND NOT v_has_shortage THEN\nv_task_id := create_system_task(\np_title := 'Prepare Dispatch for SO ' || NEW.so_number,\np_description := 'Stock is reserved for ' || v_customer_name || '. Prepare delivery challan and arrange dispatch.' ||\nCASE WHEN NEW.expected_delivery_date IS NOT NULL\nTHEN E'\\\\n\\\\nExpected Delivery: ' || NEW.expected_delivery_date::text ELSE '' END,\np_deadline := COALESCE(NEW.expected_delivery_date::timestamptz, now() + interval '3 days'),\np_origin := 'sales_order_approved',\np_reference_type := 'sales_order',\np_reference_id := NEW.id,\np_assigned_role := 'warehouse',\np_customer_id := NEW.customer_id\n);\nUPDATE system_task_events SET task_id = v_task_id, task_created = true, processed_at = now() WHERE id = v_event_id;\nEND IF;\nEND IF;\nRETURN NEW;\nEXCEPTION WHEN OTHERS THEN\nIF v_event_id IS NOT NULL THEN\nUPDATE system_task_events SET error_message = SQLERRM, processed_at = now() WHERE id = v_event_id;\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: trigger_stock_shortage_task(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"trigger_stock_shortage_task\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_task_id uuid;\nv_event_id uuid;\nv_product_name text;\nv_customer_name text;\nv_so_number text;\nBEGIN\nIF TG_OP = 'INSERT' THEN\nSELECT product_name INTO v_product_name FROM products WHERE id = NEW.product_id;\nSELECT company_name INTO v_customer_name FROM customers WHERE id = NEW.customer_id;\nIF NEW.sales_order_id IS NOT NULL THEN\nSELECT so_number INTO v_so_number FROM sales_orders WHERE id = NEW.sales_order_id;\nEND IF;\n\nINSERT INTO system_task_events (event_type, event_source, entity_type, entity_id, event_data)\nVALUES ('import_requirement_created', 'import_requirements', 'import_requirement', NEW.id, jsonb_build_object(\n'product_id', NEW.product_id, 'product_name', v_product_name,\n'shortage_quantity', NEW.shortage_quantity, 'sales_order_id', NEW.sales_order_id, 'so_number', v_so_number\n)) RETURNING id INTO v_event_id;\n\nv_task_id := create_system_task(\np_title := 'Procurement Required: ' || v_product_name,\np_description := 'Stock shortage detected. Required: ' || NEW.required_quantity::text || ' units' || E'\\\\n' ||\n'Shortage: ' || NEW.shortage_quantity::text || ' units' ||\nCASE WHEN v_so_number IS NOT NULL\nTHEN E'\\\\n\\\\nFor Sales Order: ' || v_so_number || ' (' || v_customer_name || ')' ELSE '' END ||\nCASE WHEN NEW.required_delivery_date IS NOT NULL\nTHEN E'\\\\n\\\\nRequired by: ' || NEW.required_delivery_date::text ELSE '' END,\np_deadline := COALESCE(NEW.required_delivery_date::timestamptz - interval '30 days', now() + interval '7 days'),\np_origin := 'sales_order_shortage',\np_reference_type := 'sales_order',\np_reference_id := NEW.sales_order_id,\np_assigned_role := 'admin',\np_priority := NEW.priority::text,\np_customer_id := NEW.customer_id,\np_product_id := NEW.product_id\n);\nUPDATE system_task_events SET task_id = v_task_id, task_created = true, processed_at = now() WHERE id = v_event_id;\nEND IF;\nRETURN NEW;\nEXCEPTION WHEN OTHERS THEN\nIF v_event_id IS NOT NULL THEN\nUPDATE system_task_events SET error_message = SQLERRM, processed_at = now() WHERE id = v_event_id;\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: undo_reverse_fund_transfer(\\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"undo_reverse_fund_transfer\\"(\\"p_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\" DEFAULT NULL::\\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_message  text;\n  v_conflict jsonb;\nBEGIN\n  BEGIN\n    RETURN public.undo_reverse_fund_transfer_core(p_id, p_reason);\n  EXCEPTION WHEN integrity_constraint_violation THEN\n    GET STACKED DIAGNOSTICS v_message = MESSAGE_TEXT;\n\n    IF v_message LIKE\n       'Cannot undo reversal: the % bank statement line is now linked to another transaction' THEN\n      v_conflict := public.describe_undo_reverse_bank_conflict(p_id);\n      IF v_conflict IS NOT NULL THEN\n        RAISE EXCEPTION '%', v_message\n          USING\n            ERRCODE = 'integrity_constraint_violation',\n            DETAIL = v_conflict::text;\n      END IF;\n    END IF;\n\n    RAISE;\n  END;\nEND;\n$$","--\n-- Name: undo_reverse_fund_transfer_core(\\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"undo_reverse_fund_transfer_core\\"(\\"p_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\" DEFAULT NULL::\\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_user_id             uuid := auth.uid();\n  v_role                text;\n  v_user_active         boolean;\n  v_transfer            public.fund_transfers%ROWTYPE;\n  v_original_je         public.journal_entries%ROWTYPE;\n  v_reversal_je         public.journal_entries%ROWTYPE;\n  v_related_je_count    integer;\n  v_active_je_count     integer;\n  v_period_status       text;\n  v_bank_link           record;\n  v_bank_line           public.bank_statement_lines%ROWTYPE;\nBEGIN\n  IF v_user_id IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  SELECT role, is_active\n    INTO v_role, v_user_active\n    FROM public.user_profiles\n   WHERE id = v_user_id;\n\n  IF NOT FOUND OR NOT COALESCE(v_user_active, false)\n     OR v_role NOT IN ('admin', 'accounts') THEN\n    RAISE EXCEPTION 'Permission denied: only active admin or accounts users can undo a Contra reversal'\n      USING ERRCODE = 'insufficient_privilege';\n  END IF;\n\n  SELECT *\n    INTO v_transfer\n    FROM public.fund_transfers\n   WHERE id = p_id\n   FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Fund transfer % not found', p_id\n      USING ERRCODE = 'no_data_found';\n  END IF;\n\n  IF v_transfer.status <> 'reversed' THEN\n    RAISE EXCEPTION\n      'Undo Reverse is unavailable for % because its status is %; the reversal may already have been undone',\n      v_transfer.transfer_number, v_transfer.status\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  IF v_transfer.journal_entry_id IS NOT NULL THEN\n    SELECT *\n      INTO v_original_je\n      FROM public.journal_entries\n     WHERE id = v_transfer.journal_entry_id\n     FOR UPDATE;\n  END IF;\n\n  IF v_original_je.id IS NULL THEN\n    SELECT *\n      INTO v_original_je\n      FROM public.journal_entries\n     WHERE source_module = 'fund_transfers'\n       AND reference_id = p_id\n       AND reference_number = v_transfer.transfer_number\n     ORDER BY created_at ASC\n     LIMIT 1\n     FOR UPDATE;\n  END IF;\n\n  IF v_original_je.id IS NULL THEN\n    RAISE EXCEPTION 'Cannot undo reversal: original journal for % was not found',\n      v_transfer.transfer_number USING ERRCODE = 'no_data_found';\n  END IF;\n\n  IF v_original_je.source_module <> 'fund_transfers'\n     OR v_original_je.reference_id IS DISTINCT FROM p_id\n     OR v_original_je.reference_number IS DISTINCT FROM v_transfer.transfer_number THEN\n    RAISE EXCEPTION 'Cannot undo reversal: the original journal link for % is inconsistent',\n      v_transfer.transfer_number USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  IF NOT COALESCE(v_original_je.is_posted, false)\n     OR NOT COALESCE(v_original_je.is_reversed, false)\n     OR v_original_je.reversed_by_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot undo reversal: original journal % is not in the expected reversed state',\n      v_original_je.entry_number USING ERRCODE = 'check_violation';\n  END IF;\n\n  SELECT *\n    INTO v_reversal_je\n    FROM public.journal_entries\n   WHERE id = v_original_je.reversed_by_id\n   FOR UPDATE;\n\n  IF v_reversal_je.id IS NULL THEN\n    RAISE EXCEPTION 'Cannot undo reversal: reversing journal for % was not found',\n      v_transfer.transfer_number USING ERRCODE = 'no_data_found';\n  END IF;\n\n  IF v_reversal_je.source_module <> 'fund_transfers'\n     OR v_reversal_je.reference_id IS DISTINCT FROM p_id\n     OR v_reversal_je.reference_number IS DISTINCT FROM ('REV-' || v_transfer.transfer_number)\n     OR NOT COALESCE(v_reversal_je.is_posted, false)\n     OR COALESCE(v_reversal_je.is_reversed, false) THEN\n    RAISE EXCEPTION 'Cannot undo reversal: reversing journal % is not active or is linked inconsistently',\n      v_reversal_je.entry_number USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT COUNT(*)\n    INTO v_related_je_count\n    FROM public.journal_entries\n   WHERE source_module = 'fund_transfers'\n     AND (\n       reference_id = p_id\n       OR reference_number IN (\n         v_transfer.transfer_number,\n         'REV-' || v_transfer.transfer_number\n       )\n     );\n\n  IF v_related_je_count <> 2 THEN\n    RAISE EXCEPTION\n      'Cannot undo reversal: expected exactly two journals for %, found %',\n      v_transfer.transfer_number, v_related_je_count\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1 FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_original_je.id\n  ) OR NOT EXISTS (\n    SELECT 1 FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_reversal_je.id\n  ) THEN\n    RAISE EXCEPTION 'Cannot undo reversal: original or reversing journal has no ledger lines'\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  IF EXISTS (\n    (\n      SELECT line_number, account_id, debit, credit\n        FROM public.journal_entry_lines\n       WHERE journal_entry_id = v_original_je.id\n      EXCEPT ALL\n      SELECT line_number, account_id, credit, debit\n        FROM public.journal_entry_lines\n       WHERE journal_entry_id = v_reversal_je.id\n    )\n    UNION ALL\n    (\n      SELECT line_number, account_id, debit, credit\n        FROM public.journal_entry_lines\n       WHERE journal_entry_id = v_reversal_je.id\n      EXCEPT ALL\n      SELECT line_number, account_id, credit, debit\n        FROM public.journal_entry_lines\n       WHERE journal_entry_id = v_original_je.id\n    )\n  ) THEN\n    RAISE EXCEPTION 'Cannot undo reversal: journal % is no longer the exact inverse of %',\n      v_reversal_je.entry_number, v_original_je.entry_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT status\n    INTO v_period_status\n    FROM public.accounting_periods\n   WHERE start_date <= v_original_je.entry_date\n     AND end_date >= v_original_je.entry_date\n   ORDER BY start_date DESC\n   LIMIT 1;\n\n  IF v_period_status IS NOT NULL AND v_period_status <> 'open' THEN\n    RAISE EXCEPTION\n      'Cannot undo reversal: the original accounting period for % is %',\n      to_char(v_original_je.entry_date, 'FMMonth YYYY'), v_period_status\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  v_period_status := NULL;\n  SELECT status\n    INTO v_period_status\n    FROM public.accounting_periods\n   WHERE start_date <= v_reversal_je.entry_date\n     AND end_date >= v_reversal_je.entry_date\n   ORDER BY start_date DESC\n   LIMIT 1;\n\n  IF v_period_status IS NOT NULL AND v_period_status <> 'open' THEN\n    RAISE EXCEPTION\n      'Cannot undo reversal: the reversal accounting period for % is %',\n      to_char(v_reversal_je.entry_date, 'FMMonth YYYY'), v_period_status\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n      FROM public.bank_statement_lines\n     WHERE matched_fund_transfer_id = p_id\n       AND id IS DISTINCT FROM v_transfer.from_bank_statement_line_id\n       AND id IS DISTINCT FROM v_transfer.to_bank_statement_line_id\n  ) THEN\n    RAISE EXCEPTION\n      'Cannot undo reversal: an unexpected bank statement line is linked to %',\n      v_transfer.transfer_number USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n      FROM public.bank_statement_lines\n     WHERE matched_entry_id = v_reversal_je.id\n       AND id IS DISTINCT FROM v_transfer.from_bank_statement_line_id\n       AND id IS DISTINCT FROM v_transfer.to_bank_statement_line_id\n  ) THEN\n    RAISE EXCEPTION\n      'Cannot undo reversal: the reversing journal has a later bank reconciliation dependency'\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  FOR v_bank_link IN\n    SELECT *\n      FROM (\n        VALUES\n          (\n            v_transfer.from_bank_statement_line_id,\n            CASE WHEN v_transfer.from_account_type = 'bank'\n                 THEN v_transfer.from_bank_account_id ELSE NULL END,\n            'source'\n          ),\n          (\n            v_transfer.to_bank_statement_line_id,\n            CASE WHEN v_transfer.to_account_type = 'bank'\n                 THEN v_transfer.to_bank_account_id ELSE NULL END,\n            'destination'\n          )\n      ) AS expected(line_id, bank_account_id, link_side)\n     WHERE line_id IS NOT NULL\n  LOOP\n    SELECT *\n      INTO v_bank_line\n      FROM public.bank_statement_lines\n     WHERE id = v_bank_link.line_id\n     FOR UPDATE;\n\n    IF NOT FOUND THEN\n      RAISE EXCEPTION\n        'Cannot undo reversal: the % bank statement line no longer exists',\n        v_bank_link.link_side USING ERRCODE = 'no_data_found';\n    END IF;\n\n    IF v_bank_link.bank_account_id IS NULL\n       OR v_bank_line.bank_account_id IS DISTINCT FROM v_bank_link.bank_account_id THEN\n      RAISE EXCEPTION\n        'Cannot undo reversal: the % bank statement line belongs to a different bank account',\n        v_bank_link.link_side USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n\n    IF v_bank_line.matched_expense_id IS NOT NULL\n       OR v_bank_line.matched_receipt_id IS NOT NULL\n       OR v_bank_line.matched_petty_cash_id IS NOT NULL\n       OR v_bank_line.matched_tax_payment_id IS NOT NULL\n       OR (\n         v_bank_line.matched_fund_transfer_id IS NOT NULL\n         AND v_bank_line.matched_fund_transfer_id <> p_id\n       )\n       OR (\n         v_bank_line.matched_entry_id IS NOT NULL\n         AND v_bank_line.matched_entry_id NOT IN (v_original_je.id, v_reversal_je.id)\n       ) THEN\n      RAISE EXCEPTION\n        'Cannot undo reversal: the % bank statement line is now linked to another transaction',\n        v_bank_link.link_side USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n  END LOOP;\n\n  UPDATE public.journal_entries\n     SET is_posted = false,\n         is_reversed = true\n   WHERE id = v_reversal_je.id;\n\n  UPDATE public.journal_entries\n     SET is_posted = true,\n         is_reversed = false,\n         reversed_by_id = NULL\n   WHERE id = v_original_je.id;\n\n  UPDATE public.fund_transfers\n     SET status = 'posted',\n         journal_entry_id = v_original_je.id,\n         reversed_at = NULL,\n         reversed_by = NULL\n   WHERE id = p_id;\n\n  FOR v_bank_link IN\n    SELECT *\n      FROM (\n        VALUES\n          (v_transfer.from_bank_statement_line_id, 'source'),\n          (v_transfer.to_bank_statement_line_id, 'destination')\n      ) AS expected(line_id, link_side)\n     WHERE line_id IS NOT NULL\n  LOOP\n    UPDATE public.bank_statement_lines\n       SET matched_fund_transfer_id = p_id,\n           matched_entry_id = v_original_je.id,\n           reconciliation_status = 'matched',\n           matched_at = now(),\n           matched_by = v_user_id,\n           manually_unlinked = false,\n           notes = 'Linked to Fund Transfer ' || v_transfer.transfer_number\n     WHERE id = v_bank_link.line_id;\n  END LOOP;\n\n  SELECT COUNT(*)\n    INTO v_active_je_count\n    FROM public.journal_entries\n   WHERE source_module = 'fund_transfers'\n     AND reference_id = p_id\n     AND is_posted = true\n     AND COALESCE(is_reversed, false) = false;\n\n  IF v_active_je_count <> 1 THEN\n    RAISE EXCEPTION\n      'Undo Reverse aborted: expected one active journal for %, found %',\n      v_transfer.transfer_number, v_active_je_count\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  INSERT INTO public.audit_logs (\n    table_name,\n    record_id,\n    action_type,\n    old_values,\n    new_values,\n    user_id\n  ) VALUES (\n    'fund_transfers',\n    p_id,\n    'update',\n    jsonb_build_object(\n      '_action', 'UNDO_REVERSE',\n      'status', 'reversed',\n      'reversed_at', v_transfer.reversed_at,\n      'reversed_by', v_transfer.reversed_by,\n      'original_journal_id', v_original_je.id,\n      'original_journal_number', v_original_je.entry_number,\n      'reversal_journal_id', v_reversal_je.id,\n      'reversal_reference', v_reversal_je.entry_number,\n      'reason', NULLIF(BTRIM(p_reason), '')\n    ),\n    jsonb_build_object(\n      'status', 'posted',\n      'active_journal_id', v_original_je.id,\n      'voided_reversal_journal_id', v_reversal_je.id,\n      'undone_by', v_user_id,\n      'undone_at', now()\n    ),\n    v_user_id\n  );\n\n  RETURN v_original_je.id;\nEND;\n$$","--\n-- Name: unlink_expense_from_bank_statement(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"unlink_expense_from_bank_statement\\"(\\"p_bank_statement_line_id\\" \\"uuid\\") RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot unlink bank statement entries', v_role;\nEND IF;\n\nUPDATE bank_statement_lines\nSET matched_expense_id = NULL, reconciliation_status = 'unmatched',\nmatched_at = NULL, matched_by = NULL, notes = NULL\nWHERE id = p_bank_statement_line_id;\nIF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line not found'; END IF;\nEND;\n$$","--\n-- Name: unlink_finance_expense_bank_atomic(\\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"unlink_finance_expense_bank_atomic\\"(\\"p_expense_id\\" \\"uuid\\", \\"p_reason\\" \\"text\\" DEFAULT 'Bank statement link removed by user'::\\"text\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_expense public.finance_expenses%ROWTYPE;\n  v_allocation record;\n  v_released integer := 0;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  IF btrim(COALESCE(p_reason, '')) = '' THEN\n    RAISE EXCEPTION 'An unlink reason is required';\n  END IF;\n\n  SELECT * INTO v_expense\n  FROM public.finance_expenses\n  WHERE id = p_expense_id\n  FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Expense not found';\n  END IF;\n  IF v_expense.approval_status <> 'approved' THEN\n    RAISE EXCEPTION 'Only an active posted expense can be unlinked through this workflow';\n  END IF;\n\n  FOR v_allocation IN\n    SELECT id\n    FROM public.bank_statement_allocations\n    WHERE document_type = 'expense'\n      AND document_id = p_expense_id\n    ORDER BY id\n    FOR UPDATE\n  LOOP\n    PERFORM public.unmatch_bank_statement_allocation(v_allocation.id);\n    v_released := v_released + 1;\n  END LOOP;\n  IF v_released = 0 THEN\n    RAISE EXCEPTION 'Expense has no canonical bank allocation to unlink';\n  END IF;\n\n  PERFORM public.recalculate_expense_payment_state(p_expense_id);\n  PERFORM public.cancel_expense_posting(p_expense_id, auth.uid(), p_reason);\n\n  IF EXISTS (\n    SELECT 1 FROM public.bank_statement_allocations\n    WHERE document_type = 'expense' AND document_id = p_expense_id\n  ) THEN\n    RAISE EXCEPTION 'Expense unlink left a bank allocation behind';\n  END IF;\n  IF EXISTS (\n    SELECT 1 FROM public.journal_entries\n    WHERE source_module IN ('expense', 'expenses')\n      AND (reference_id = p_expense_id OR reference_number = 'EXP-' || p_expense_id::text)\n      AND is_posted AND NOT COALESCE(is_reversed, false)\n  ) THEN\n    RAISE EXCEPTION 'Expense unlink left an active journal behind';\n  END IF;\n  IF NOT EXISTS (\n    SELECT 1 FROM public.finance_expenses\n    WHERE id = p_expense_id AND approval_status = 'cancelled'\n  ) THEN\n    RAISE EXCEPTION 'Expense unlink did not cancel the document';\n  END IF;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'expense_id', p_expense_id,\n    'released_allocations', v_released\n  );\nEND;\n$$","--\n-- Name: unmatch_bank_line(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"unmatch_bank_line\\"(\\"p_bank_line_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_allocation_id uuid;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  PERFORM 1 FROM public.bank_statement_lines WHERE id = p_bank_line_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Bank statement line not found';\n  END IF;\n\n  FOR v_allocation_id IN\n    SELECT id\n    FROM public.bank_statement_allocations\n    WHERE bank_statement_line_id = p_bank_line_id\n    ORDER BY id\n    FOR UPDATE\n  LOOP\n    PERFORM public.unmatch_bank_statement_allocation(v_allocation_id);\n  END LOOP;\n\n  UPDATE public.bank_statement_lines\n  SET matched_expense_id = NULL,\n      matched_receipt_id = NULL,\n      matched_payment_id = NULL,\n      matched_fund_transfer_id = NULL,\n      matched_petty_cash_id = NULL,\n      matched_tax_payment_id = NULL,\n      matched_entry_id = NULL,\n      matching_status = 'none',\n      reconciliation_status = 'unmatched',\n      matched_at = NULL,\n      matched_by = NULL,\n      notes = NULL,\n      manually_unlinked = true,\n      payment_kind = 'supplier'\n  WHERE id = p_bank_line_id;\n\n  RETURN jsonb_build_object('success', true, 'bank_line_id', p_bank_line_id);\nEND;\n$$","--\n-- Name: unmatch_bank_statement_allocation(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"unmatch_bank_statement_allocation\\"(\\"p_allocation_id\\" \\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_a public.bank_statement_allocations%rowtype; v_payment_je public.journal_entries%rowtype;\n  v_reversal_id uuid; v_reversal_number text; v_period_status text;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  SELECT * INTO v_a FROM public.bank_statement_allocations WHERE id=p_allocation_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Bank allocation not found'; END IF;\n  SELECT * INTO v_payment_je FROM public.journal_entries\n   WHERE id=v_a.journal_entry_id AND source_module='expense_payment'\n     AND reference_number='EXP-PAY-'||p_allocation_id::text\n     AND is_posted AND NOT COALESCE(is_reversed,false) FOR UPDATE;\n  IF FOUND THEN\n    SELECT status INTO v_period_status FROM public.accounting_periods\n     WHERE start_date<=v_payment_je.entry_date AND end_date>=v_payment_je.entry_date\n     ORDER BY start_date DESC LIMIT 1;\n    IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN\n      RAISE EXCEPTION 'Cannot unlink expense payment in a closed accounting period';\n    END IF;\n    v_reversal_number:=public.next_journal_entry_number();\n    INSERT INTO public.journal_entries(entry_number,entry_date,period_id,source_module,reference_id,\n      reference_number,description,total_debit,total_credit,is_posted,is_reversed,posted_by,posted_at,created_by,\n      transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n    VALUES(v_reversal_number,v_payment_je.entry_date,v_payment_je.period_id,'expense_payment_reversal',v_a.document_id,\n      'REV-EXP-PAY-'||p_allocation_id::text,'Reversal of '||v_payment_je.entry_number,\n      v_payment_je.total_credit,v_payment_je.total_debit,true,true,auth.uid(),now(),auth.uid(),\n      v_payment_je.transaction_currency,v_payment_je.functional_currency,v_payment_je.exchange_rate,v_payment_je.amounts_are_functional)\n    RETURNING id INTO v_reversal_id;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,\n      tax_code_id,customer_id,supplier_id,batch_id,transaction_currency,transaction_debit,transaction_credit,\n      functional_currency,exchange_rate)\n    SELECT v_reversal_id,line_number,account_id,'REVERSAL: '||COALESCE(description,''),credit,debit,\n      tax_code_id,customer_id,supplier_id,batch_id,transaction_currency,transaction_credit,transaction_debit,\n      functional_currency,exchange_rate\n      FROM public.journal_entry_lines WHERE journal_entry_id=v_payment_je.id ORDER BY line_number;\n    UPDATE public.journal_entries SET is_reversed=true,reversed_by_id=v_reversal_id\n     WHERE id=v_payment_je.id;\n  END IF;\n  DELETE FROM public.bank_statement_allocations WHERE id=p_allocation_id;\n  PERFORM public.sync_bank_line_allocation_owner(v_a.bank_statement_line_id);\n  PERFORM public.refresh_bank_statement_allocation_status(v_a.bank_statement_line_id);\n  IF v_a.document_type='expense' THEN PERFORM public.recalculate_expense_payment_state(v_a.document_id); END IF;\n  RETURN jsonb_build_object('success',true,'bank_line_id',v_a.bank_statement_line_id,\n    'allocation_id',p_allocation_id,'reversal_journal_id',v_reversal_id);\nEND;\n$$","--\n-- Name: update_approval_workflows_updated_at(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_approval_workflows_updated_at\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nNEW.updated_at = now();\nRETURN NEW;\nEND;\n$$","--\n-- Name: update_batch_stock_from_transactions(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_batch_stock_from_transactions\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_batch_id uuid;\nv_total_stock numeric;\nBEGIN\n-- Determine which batch to update\nIF TG_OP = 'DELETE' THEN\nv_batch_id := OLD.batch_id;\nELSE\nv_batch_id := NEW.batch_id;\nEND IF;\n\n-- Calculate total stock from all transactions for this batch\nSELECT COALESCE(SUM(quantity), 0)\nINTO v_total_stock\nFROM inventory_transactions\nWHERE batch_id = v_batch_id;\n\n-- Update the batch current_stock\nUPDATE batches\nSET current_stock = v_total_stock,\nupdated_at = now()\nWHERE id = v_batch_id;\n\nIF TG_OP = 'DELETE' THEN\nRETURN OLD;\nELSE\nRETURN NEW;\nEND IF;\nEND;\n$$","--\n-- Name: update_container_bpom_fees(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_container_bpom_fees\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_container_id uuid;\nv_total_bpom_fees numeric;\nv_is_bpom_fees boolean := false;\nBEGIN\n-- Check if this expense is 'bpom_ski_fees' category\nIF TG_OP = 'DELETE' THEN\nv_is_bpom_fees := (OLD.expense_category = 'bpom_ski_fees');\nv_container_id := OLD.import_container_id;\nELSIF TG_OP = 'UPDATE' THEN\nv_is_bpom_fees := (NEW.expense_category = 'bpom_ski_fees' OR OLD.expense_category = 'bpom_ski_fees');\nv_container_id := NEW.import_container_id;\nELSE -- INSERT\nv_is_bpom_fees := (NEW.expense_category = 'bpom_ski_fees');\nv_container_id := NEW.import_container_id;\nEND IF;\n\n-- Skip if not 'bpom_ski_fees' category\nIF NOT v_is_bpom_fees THEN\nIF TG_OP = 'DELETE' THEN\nRETURN OLD;\nELSE\nRETURN NEW;\nEND IF;\nEND IF;\n\n-- Skip if no container linked\nIF v_container_id IS NULL AND (TG_OP != 'UPDATE' OR OLD.import_container_id IS NULL) THEN\nIF TG_OP = 'DELETE' THEN\nRETURN OLD;\nELSE\nRETURN NEW;\nEND IF;\nEND IF;\n\n-- Calculate total of all 'bpom_ski_fees' expenses for this container\nIF v_container_id IS NOT NULL THEN\nSELECT COALESCE(SUM(amount), 0) \nINTO v_total_bpom_fees\nFROM finance_expenses\nWHERE import_container_id = v_container_id\nAND expense_category = 'bpom_ski_fees';\n\n-- Update the container's bpom_ski_fees field\nUPDATE import_containers\nSET bpom_ski_fees = v_total_bpom_fees\nWHERE id = v_container_id;\nEND IF;\n\n-- If updating and container changed, also update the old container\nIF TG_OP = 'UPDATE' AND OLD.import_container_id IS NOT NULL \nAND (NEW.import_container_id IS NULL OR OLD.import_container_id != NEW.import_container_id) THEN\nSELECT COALESCE(SUM(amount), 0) \nINTO v_total_bpom_fees\nFROM finance_expenses\nWHERE import_container_id = OLD.import_container_id\nAND expense_category = 'bpom_ski_fees';\n\nUPDATE import_containers\nSET bpom_ski_fees = v_total_bpom_fees\nWHERE id = OLD.import_container_id;\nEND IF;\n\nIF TG_OP = 'DELETE' THEN\nRETURN OLD;\nELSE\nRETURN NEW;\nEND IF;\nEND;\n$$","--\n-- Name: update_container_other_costs(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_container_other_costs\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_container_id uuid;\nv_total_other_costs numeric;\nv_is_other_import boolean := false;\nBEGIN\n-- Check if this expense is 'other_import' category\nIF TG_OP = 'DELETE' THEN\nv_is_other_import := (OLD.expense_category = 'other_import');\nv_container_id := OLD.import_container_id;\nELSIF TG_OP = 'UPDATE' THEN\nv_is_other_import := (NEW.expense_category = 'other_import' OR OLD.expense_category = 'other_import');\nv_container_id := NEW.import_container_id;\nELSE -- INSERT\nv_is_other_import := (NEW.expense_category = 'other_import');\nv_container_id := NEW.import_container_id;\nEND IF;\n\n-- Skip if not 'other_import' category\nIF NOT v_is_other_import THEN\nIF TG_OP = 'DELETE' THEN\nRETURN OLD;\nELSE\nRETURN NEW;\nEND IF;\nEND IF;\n\n-- Skip if no container linked\nIF v_container_id IS NULL AND (TG_OP != 'UPDATE' OR OLD.import_container_id IS NULL) THEN\nIF TG_OP = 'DELETE' THEN\nRETURN OLD;\nELSE\nRETURN NEW;\nEND IF;\nEND IF;\n\n-- Calculate total of all 'other_import' expenses for this container\nIF v_container_id IS NOT NULL THEN\nSELECT COALESCE(SUM(amount), 0) \nINTO v_total_other_costs\nFROM finance_expenses\nWHERE import_container_id = v_container_id\nAND expense_category = 'other_import';\n\n-- Update the container's other_import_costs field\nUPDATE import_containers\nSET other_import_costs = v_total_other_costs\nWHERE id = v_container_id;\nEND IF;\n\n-- If updating and container changed, also update the old container\nIF TG_OP = 'UPDATE' AND OLD.import_container_id IS NOT NULL \nAND (NEW.import_container_id IS NULL OR OLD.import_container_id != NEW.import_container_id) THEN\nSELECT COALESCE(SUM(amount), 0) \nINTO v_total_other_costs\nFROM finance_expenses\nWHERE import_container_id = OLD.import_container_id\nAND expense_category = 'other_import';\n\nUPDATE import_containers\nSET other_import_costs = v_total_other_costs\nWHERE id = OLD.import_container_id;\nEND IF;\n\nIF TG_OP = 'DELETE' THEN\nRETURN OLD;\nELSE\nRETURN NEW;\nEND IF;\nEND;\n$$","--\n-- Name: update_fund_transfer_bank_links(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_fund_transfer_bank_links\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n-- Handle from_bank_statement_line_id\nIF NEW.from_bank_statement_line_id IS NOT NULL THEN\n-- If it's different from OLD, update the bank statement\nIF (TG_OP = 'INSERT') OR (OLD.from_bank_statement_line_id IS DISTINCT FROM NEW.from_bank_statement_line_id) THEN\nUPDATE bank_statement_lines\nSET\nmatched_fund_transfer_id = NEW.id,\nreconciliation_status = 'matched',\nmatched_at = now(),\nmatched_by = COALESCE(NEW.posted_by, NEW.created_by),\nnotes = 'Linked to Fund Transfer ' || NEW.transfer_number\nWHERE id = NEW.from_bank_statement_line_id;\nEND IF;\nEND IF;\n\n-- Handle to_bank_statement_line_id\nIF NEW.to_bank_statement_line_id IS NOT NULL THEN\nIF (TG_OP = 'INSERT') OR (OLD.to_bank_statement_line_id IS DISTINCT FROM NEW.to_bank_statement_line_id) THEN\nUPDATE bank_statement_lines\nSET\nmatched_fund_transfer_id = NEW.id,\nreconciliation_status = 'matched',\nmatched_at = now(),\nmatched_by = COALESCE(NEW.posted_by, NEW.created_by),\nnotes = 'Linked to Fund Transfer ' || NEW.transfer_number\nWHERE id = NEW.to_bank_statement_line_id;\nEND IF;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: update_inquiry_items_updated_at(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_inquiry_items_updated_at\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nNEW.updated_at = now();\nRETURN NEW;\nEND;\n$$","--\n-- Name: update_inventory_on_batch_insert_or_update(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_inventory_on_batch_insert_or_update\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF (TG_OP = 'INSERT') THEN\n    -- Create new inventory transaction for new batch\n    INSERT INTO inventory_transactions (\n      product_id,\n      batch_id,\n      transaction_type,\n      quantity,\n      transaction_date,\n      notes\n    ) VALUES (\n      NEW.product_id,\n      NEW.id,\n      'batch_import',\n      NEW.import_quantity,\n      NEW.import_date,\n      'Batch import: ' || NEW.batch_number\n    );\n  ELSIF (TG_OP = 'UPDATE') THEN\n    -- Update existing inventory transaction when batch is edited\n    UPDATE inventory_transactions\n    SET \n      product_id = NEW.product_id,\n      quantity = NEW.import_quantity,\n      transaction_date = NEW.import_date,\n      notes = 'Batch import: ' || NEW.batch_number\n    WHERE batch_id = NEW.id \n      AND transaction_type = 'batch_import';\n    \n    -- If no transaction exists, create one (handles legacy batches)\n    IF NOT FOUND THEN\n      INSERT INTO inventory_transactions (\n        product_id,\n        batch_id,\n        transaction_type,\n        quantity,\n        transaction_date,\n        notes\n      ) VALUES (\n        NEW.product_id,\n        NEW.id,\n        'batch_import',\n        NEW.import_quantity,\n        NEW.import_date,\n        'Batch import: ' || NEW.batch_number\n      );\n    END IF;\n  END IF;\n  \n  RETURN NEW;\nEND;\n$$","--\n-- Name: update_invoice_payment_status_from_allocation(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_invoice_payment_status_from_allocation\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_total_paid NUMERIC;\nv_invoice_total NUMERIC;\nv_invoice_id UUID;\nBEGIN\n-- Get the invoice ID\nIF TG_OP = 'DELETE' THEN\nv_invoice_id := OLD.sales_invoice_id;\nELSE\nv_invoice_id := NEW.sales_invoice_id;\nEND IF;\n\n-- Only process if there's an invoice ID and it's a receipt voucher\nIF v_invoice_id IS NULL THEN\nIF TG_OP = 'DELETE' THEN\nRETURN OLD;\nELSE\nRETURN NEW;\nEND IF;\nEND IF;\n\n-- Only process receipt vouchers\nIF TG_OP = 'DELETE' AND OLD.voucher_type != 'receipt' THEN\nRETURN OLD;\nEND IF;\n\nIF TG_OP != 'DELETE' AND NEW.voucher_type != 'receipt' THEN\nRETURN NEW;\nEND IF;\n\n-- Calculate total paid for the invoice\nv_total_paid := get_invoice_paid_amount(v_invoice_id);\n\n-- Get invoice total\nSELECT total_amount INTO v_invoice_total\nFROM sales_invoices\nWHERE id = v_invoice_id;\n\n-- Update paid_amount, balance_amount, and payment_status\nUPDATE sales_invoices\nSET \npaid_amount = v_total_paid,\nbalance_amount = v_invoice_total - v_total_paid,\npayment_status = CASE\nWHEN v_total_paid = 0 THEN 'pending'\nWHEN v_total_paid >= v_invoice_total THEN 'paid'\nELSE 'partial'\nEND,\nupdated_at = NOW()\nWHERE id = v_invoice_id;\n\nIF TG_OP = 'DELETE' THEN\nRETURN OLD;\nELSE\nRETURN NEW;\nEND IF;\nEND;\n$$","--\n-- Name: update_loan_outstanding_balance(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_loan_outstanding_balance\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_loan_id uuid;\nv_loan_type text;\nv_principal numeric;\nv_total_principal_repaid numeric;\nv_total_additional numeric;\nv_new_balance numeric;\nBEGIN\nIF TG_OP = 'DELETE' THEN\nv_loan_id := OLD.loan_id;\nELSE\nv_loan_id := NEW.loan_id;\nEND IF;\n\nSELECT loan_type, principal_amount INTO v_loan_type, v_principal FROM loans WHERE id = v_loan_id;\n\n-- Sum all principal repayments\nSELECT COALESCE(SUM(principal_amount), 0) INTO v_total_principal_repaid\nFROM loan_transactions\nWHERE loan_id = v_loan_id AND transaction_type IN ('repayment', 'interest_payment');\n\n-- Sum all additional disbursements\nSELECT COALESCE(SUM(amount), 0) INTO v_total_additional\nFROM loan_transactions\nWHERE loan_id = v_loan_id AND transaction_type = 'additional_disbursement';\n\n-- Calculate new outstanding balance\nv_new_balance := v_principal + v_total_additional - v_total_principal_repaid;\n\n-- Update loan outstanding balance and status\nUPDATE loans\nSET outstanding_balance = GREATEST(v_new_balance, 0),\nstatus = CASE WHEN v_new_balance <= 0 THEN 'closed' ELSE 'active' END\nWHERE id = v_loan_id;\n\nIF TG_OP = 'DELETE' THEN\nRETURN OLD;\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: update_product_current_stock(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_product_current_stock\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_product_id UUID;\nBEGIN\nIF TG_OP = 'DELETE' THEN\nv_product_id := OLD.product_id;\nELSE\nv_product_id := NEW.product_id;\nEND IF;\n\n-- Update the product's current_stock to the sum of all active batch current_stocks\nUPDATE products\nSET current_stock = COALESCE((\nSELECT SUM(b.current_stock)\nFROM batches b\nWHERE b.product_id = v_product_id\nAND b.is_active = true\nAND b.current_stock > 0\n), 0)\nWHERE id = v_product_id;\n\nIF TG_OP = 'DELETE' THEN\nRETURN OLD;\nELSE\nRETURN NEW;\nEND IF;\nEND;\n$$","--\n-- Name: update_product_sources_updated_at(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_product_sources_updated_at\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nNEW.updated_at = now();\nRETURN NEW;\nEND;\n$$","--\n-- Name: update_sales_invoice_atomic(\\"uuid\\", \\"jsonb\\", \\"jsonb\\"[]); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_sales_invoice_atomic\\"(\\"p_invoice_id\\" \\"uuid\\", \\"p_invoice_updates\\" \\"jsonb\\", \\"p_new_items\\" \\"jsonb\\"[]) RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_role text;\n  v_old_je_id uuid;\n  v_result uuid;\n  v_dc_item_ids uuid[];\n  v_linked_challan_ids text[];\n  v_sales_order_ids uuid[];\n  v_customer_ids uuid[];\nBEGIN\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts', 'sales', 'manager') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot update sales invoices', v_role;\n  END IF;\n\n  SELECT array_agg(DISTINCT NULLIF(item->>'delivery_challan_item_id', '')::uuid)\n  INTO v_dc_item_ids\n  FROM unnest(p_new_items) AS item;\n\n  IF v_dc_item_ids IS NULL OR cardinality(v_dc_item_ids) = 0 THEN\n    RAISE EXCEPTION 'Sales Invoice must contain Delivery Challan-linked items';\n  END IF;\n\n  IF array_length(v_dc_item_ids, 1) <> (\n    SELECT count(*) FROM public.delivery_challan_items WHERE id = ANY(v_dc_item_ids)\n  ) THEN\n    RAISE EXCEPTION 'Sales Invoice contains a missing Delivery Challan item';\n  END IF;\n\n  SELECT\n    array_agg(DISTINCT dc.id::text ORDER BY dc.id::text),\n    array_agg(DISTINCT dc.sales_order_id),\n    array_agg(DISTINCT dc.customer_id)\n  INTO v_linked_challan_ids, v_sales_order_ids, v_customer_ids\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  WHERE dci.id = ANY(v_dc_item_ids);\n\n  IF cardinality(v_customer_ids) <> 1\n     OR (p_invoice_updates ? 'customer_id'\n         AND (p_invoice_updates->>'customer_id')::uuid IS DISTINCT FROM v_customer_ids[1]) THEN\n    RAISE EXCEPTION 'Invoice customer must match all linked Delivery Challans';\n  END IF;\n\n  SELECT journal_entry_id INTO v_old_je_id\n  FROM public.sales_invoices\n  WHERE id = p_invoice_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Invoice % not found', p_invoice_id;\n  END IF;\n\n  IF v_old_je_id IS NOT NULL THEN\n    UPDATE public.sales_invoices SET journal_entry_id = NULL WHERE id = p_invoice_id;\n    DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_old_je_id;\n    DELETE FROM public.journal_entries WHERE id = v_old_je_id;\n  END IF;\n\n  DELETE FROM public.sales_invoice_items WHERE invoice_id = p_invoice_id;\n  PERFORM set_config('app.sales_invoice_rebuild', 'true', true);\n\n  UPDATE public.sales_invoices\n  SET\n    invoice_date       = COALESCE((p_invoice_updates->>'invoice_date')::date, invoice_date),\n    due_date           = COALESCE((p_invoice_updates->>'due_date')::date, due_date),\n    customer_id        = v_customer_ids[1],\n    sales_order_id     = CASE WHEN cardinality(v_sales_order_ids) = 1 THEN v_sales_order_ids[1] ELSE NULL END,\n    subtotal           = COALESCE((p_invoice_updates->>'subtotal')::numeric, subtotal),\n    tax_amount         = COALESCE((p_invoice_updates->>'tax_amount')::numeric, tax_amount),\n    total_amount       = COALESCE((p_invoice_updates->>'total_amount')::numeric, total_amount),\n    discount_amount    = COALESCE((p_invoice_updates->>'discount_amount')::numeric, discount_amount),\n    stamp_duty_amount  = COALESCE((p_invoice_updates->>'stamp_duty_amount')::numeric, stamp_duty_amount),\n    po_number          = COALESCE(p_invoice_updates->>'po_number', po_number),\n    payment_terms_days = COALESCE((p_invoice_updates->>'payment_terms_days')::integer, payment_terms_days),\n    notes              = COALESCE(p_invoice_updates->>'notes', notes),\n    linked_challan_ids = v_linked_challan_ids,\n    updated_at         = now()\n  WHERE id = p_invoice_id\n  RETURNING id INTO v_result;\n\n  INSERT INTO public.sales_invoice_items (\n    invoice_id, product_id, batch_id, quantity, unit_price, tax_rate, delivery_challan_item_id\n  )\n  SELECT\n    p_invoice_id,\n    (item->>'product_id')::uuid,\n    NULLIF(item->>'batch_id', '')::uuid,\n    (item->>'quantity')::numeric,\n    (item->>'unit_price')::numeric,\n    (item->>'tax_rate')::numeric,\n    NULLIF(item->>'delivery_challan_item_id', '')::uuid\n  FROM unnest(p_new_items) AS item;\n\n  PERFORM set_config('app.sales_invoice_rebuild', 'false', true);\n  UPDATE public.sales_invoices SET updated_at = now()\n  WHERE id = p_invoice_id AND journal_entry_id IS NULL;\n\n  RETURN v_result;\nEND;\n$$","--\n-- Name: FUNCTION \\"update_sales_invoice_atomic\\"(\\"p_invoice_id\\" \\"uuid\\", \\"p_invoice_updates\\" \\"jsonb\\", \\"p_new_items\\" \\"jsonb\\"[]); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"update_sales_invoice_atomic\\"(\\"p_invoice_id\\" \\"uuid\\", \\"p_invoice_updates\\" \\"jsonb\\", \\"p_new_items\\" \\"jsonb\\"[]) IS 'Atomically replaces invoice lines and journal while preserving delivery-challan links as text[]'","--\n-- Name: update_sales_invoice_atomic(\\"uuid\\", \\"jsonb\\", \\"jsonb\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_sales_invoice_atomic\\"(\\"p_invoice_id\\" \\"uuid\\", \\"p_invoice_updates\\" \\"jsonb\\", \\"p_items\\" \\"jsonb\\", \\"p_user_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS \\"jsonb\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_result uuid;\nBEGIN\n  v_result := public.update_sales_invoice_atomic(\n    p_invoice_id,\n    p_invoice_updates,\n    ARRAY(\n      SELECT value\n      FROM jsonb_array_elements(\n        CASE WHEN jsonb_typeof(p_items) = 'array' THEN p_items ELSE '[]'::jsonb END\n      )\n    )::jsonb[]\n  );\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'invoice_id', p_invoice_id,\n    'journal_entry_id', (SELECT journal_entry_id FROM sales_invoices WHERE id = p_invoice_id),\n    'result_id', v_result,\n    'user_id', p_user_id\n  );\nEND;\n$$","--\n-- Name: FUNCTION \\"update_sales_invoice_atomic\\"(\\"p_invoice_id\\" \\"uuid\\", \\"p_invoice_updates\\" \\"jsonb\\", \\"p_items\\" \\"jsonb\\", \\"p_user_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"update_sales_invoice_atomic\\"(\\"p_invoice_id\\" \\"uuid\\", \\"p_invoice_updates\\" \\"jsonb\\", \\"p_items\\" \\"jsonb\\", \\"p_user_id\\" \\"uuid\\") IS 'Backward-compatible adapter to the canonical jsonb[] Sales Invoice update implementation'","--\n-- Name: update_so_advance_status(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_so_advance_status\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_sales_order_id UUID;\nv_total_advance DECIMAL(18,2);\nv_order_total DECIMAL(18,2);\nBEGIN\n-- Determine which sales_order_id to update\nIF TG_OP = 'DELETE' THEN\nv_sales_order_id := OLD.sales_order_id;\nELSE\nv_sales_order_id := NEW.sales_order_id;\nEND IF;\n\n-- Only process if sales_order_id exists\nIF v_sales_order_id IS NULL THEN\nRETURN COALESCE(NEW, OLD);\nEND IF;\n\n-- Calculate total advance payments for this SO\nSELECT COALESCE(SUM(va.allocated_amount), 0)\nINTO v_total_advance\nFROM voucher_allocations va\nWHERE va.sales_order_id = v_sales_order_id\nAND va.voucher_type = 'receipt';\n\n-- Get SO total\nSELECT total_amount INTO v_order_total\nFROM sales_orders\nWHERE id = v_sales_order_id;\n\n-- Update SO with advance status\nUPDATE sales_orders\nSET \nadvance_payment_amount = v_total_advance,\nadvance_payment_status = CASE\nWHEN v_total_advance = 0 THEN 'none'\nWHEN v_total_advance >= v_order_total THEN 'full'\nELSE 'partial'\nEND,\nupdated_at = now()\nWHERE id = v_sales_order_id;\n\nRETURN COALESCE(NEW, OLD);\nEND;\n$$","--\n-- Name: update_so_delivered_quantity_atomic(\\"uuid\\", \\"jsonb\\"[]); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_so_delivered_quantity_atomic\\"(\\"p_sales_order_id\\" \\"uuid\\", \\"p_dc_items\\" \\"jsonb\\"[]) RETURNS \\"void\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  BEGIN\n    PERFORM public.fn_recompute_so_status(p_sales_order_id);\n  END;\n  $$","--\n-- Name: FUNCTION \\"update_so_delivered_quantity_atomic\\"(\\"p_sales_order_id\\" \\"uuid\\", \\"p_dc_items\\" \\"jsonb\\"[]); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"update_so_delivered_quantity_atomic\\"(\\"p_sales_order_id\\" \\"uuid\\", \\"p_dc_items\\" \\"jsonb\\"[]) IS 'Atomically updates delivered quantities for sales order. Prevents race conditions from concurrent DC creation.'","--\n-- Name: update_task_completion(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_task_completion\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nIF (TG_OP = 'UPDATE' AND NEW.status = 'completed' AND OLD.status != 'completed') THEN\nNEW.completed_at = NOW();\nNEW.completed_by = auth.uid();\nELSIF (TG_OP = 'UPDATE' AND NEW.status != 'completed' AND OLD.status = 'completed') THEN\nNEW.completed_at = NULL;\nNEW.completed_by = NULL;\nEND IF;\nRETURN NEW;\nEND;\n$$","--\n-- Name: update_tasks_updated_at(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_tasks_updated_at\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nNEW.updated_at = NOW();\nRETURN NEW;\nEND;\n$$","--\n-- Name: update_tax_payment(\\"uuid\\", \\"date\\", numeric, \\"uuid\\", \\"text\\", \\"text\\", \\"text\\", \\"text\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_tax_payment\\"(\\"p_id\\" \\"uuid\\", \\"p_payment_date\\" \\"date\\", \\"p_amount\\" numeric, \\"p_bank_account_id\\" \\"uuid\\", \\"p_billing_code\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_ntpn\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_government_reference\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_notes\\" \\"text\\" DEFAULT NULL::\\"text\\", \\"p_payment_reference\\" \\"text\\" DEFAULT NULL::\\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_old              tax_payments%ROWTYPE;\n  v_period           tax_periods%ROWTYPE;\n  v_je_number        text;\n  v_je_id            uuid;\n  v_old_je_ids       uuid[];\n  v_payable_code     text;\n  v_payable_acct_id  uuid;\n  v_bank_acct_coa_id uuid;\n  v_ref_number       text;\n  v_is_admin         boolean;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'insufficient_privilege';\n  END IF;\n  IF p_amount IS NULL OR p_amount <= 0 THEN\n    RAISE EXCEPTION 'Tax payment amount must be > 0';\n  END IF;\n  IF p_bank_account_id IS NULL THEN\n    RAISE EXCEPTION 'Bank account is required';\n  END IF;\n\n  SELECT * INTO v_old FROM tax_payments WHERE id = p_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax payment % not found', p_id USING ERRCODE = 'no_data_found';\n  END IF;\n\n  SELECT * INTO v_period FROM tax_periods WHERE id = v_old.tax_period_id;\n  IF v_period.status = 'closed' AND current_setting('request.jwt.claim.role', true) <> 'service_role' THEN\n    RAISE EXCEPTION 'Tax period is closed; cannot edit tax payment. Reopen the period first.'\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  -- Reconciled payments can only be edited by admin (edit implies breaking\n  -- the current bank reconciliation match). Non-admins must first unmatch\n  -- via the Bank Reconciliation screen.\n  IF v_old.status = 'reconciled' THEN\n    SELECT (up.role = 'admin' AND up.is_active) INTO v_is_admin\n      FROM user_profiles up WHERE up.id = auth.uid();\n    IF NOT COALESCE(v_is_admin, false) THEN\n      RAISE EXCEPTION 'Tax payment is reconciled; only an admin may edit it. Unmatch it in Bank Reconciliation first.'\n        USING ERRCODE = 'insufficient_privilege';\n    END IF;\n  END IF;\n\n  -- Resolve accounts (same logic as record_tax_payment)\n  v_payable_code := CASE v_old.tax_type\n    WHEN 'PPN'      THEN '2130'\n    WHEN 'PPh21'    THEN '2131'\n    WHEN 'PPh22'    THEN '2137'\n    WHEN 'PPh23'    THEN '2132'\n    WHEN 'PPh4(2)'  THEN '2138'\n    WHEN 'PPh_Unifikasi' THEN '2131'\n    ELSE NULL\n  END;\n  IF v_payable_code IS NULL THEN\n    RAISE EXCEPTION 'Unknown tax_type: %', v_old.tax_type;\n  END IF;\n\n  SELECT id INTO v_payable_acct_id FROM chart_of_accounts WHERE code = v_payable_code;\n  IF v_payable_acct_id IS NULL THEN\n    RAISE EXCEPTION 'Payable account % missing from Chart of Accounts', v_payable_code;\n  END IF;\n\n  SELECT coa_id INTO v_bank_acct_coa_id FROM bank_accounts WHERE id = p_bank_account_id;\n  IF v_bank_acct_coa_id IS NULL THEN\n    SELECT id INTO v_bank_acct_coa_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\n  END IF;\n  IF v_bank_acct_coa_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot resolve bank CoA account';\n  END IF;\n\n  -- Reverse old JE(s)\n  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])\n    INTO v_old_je_ids\n    FROM journal_entries\n   WHERE source_module = 'tax_payment' AND reference_id = p_id;\n  IF v_old.journal_entry_id IS NOT NULL AND NOT v_old.journal_entry_id = ANY (v_old_je_ids) THEN\n    v_old_je_ids := array_append(v_old_je_ids, v_old.journal_entry_id);\n  END IF;\n\n  -- Release bank recon matches before deleting the JEs.\n  -- NOTE: bank_statement_lines has no updated_at column — do not write it.\n  UPDATE bank_statement_lines\n     SET matched_entry_id       = NULL,\n         matched_tax_payment_id = NULL,\n         reconciliation_status  = 'unmatched'\n   WHERE matched_tax_payment_id = p_id\n      OR (array_length(v_old_je_ids, 1) IS NOT NULL AND matched_entry_id = ANY (v_old_je_ids));\n\n  IF array_length(v_old_je_ids, 1) IS NOT NULL THEN\n    UPDATE bank_reconciliation_items\n       SET is_matched = false, matched_at = NULL\n     WHERE journal_entry_id = ANY (v_old_je_ids);\n    DELETE FROM journal_entry_lines WHERE journal_entry_id = ANY (v_old_je_ids);\n    DELETE FROM journal_entries     WHERE id = ANY (v_old_je_ids);\n  END IF;\n\n  -- Update the payment row (period + type unchanged; use delete+create for that)\n  UPDATE tax_payments SET\n    payment_date         = p_payment_date,\n    amount               = p_amount,\n    bank_account_id      = p_bank_account_id,\n    billing_code         = p_billing_code,\n    ntpn                 = p_ntpn,\n    government_reference = p_government_reference,\n    notes                = p_notes,\n    payment_reference    = p_payment_reference,\n    journal_entry_id     = NULL,\n    status               = 'draft',\n    updated_at           = now()\n  WHERE id = p_id;\n\n  -- Post fresh JE\n  v_ref_number := COALESCE(\n    NULLIF(p_ntpn, ''), NULLIF(p_billing_code, ''), NULLIF(p_payment_reference, ''),\n    'TAX-' || to_char(p_payment_date, 'YYMM') || '-' || substr(p_id::text, 1, 8)\n  );\n  v_je_number := next_journal_entry_number();\n\n  INSERT INTO journal_entries\n    (entry_number, entry_date, source_module, reference_id, reference_number,\n     description, total_debit, total_credit, is_posted, posted_by)\n  VALUES\n    (v_je_number, p_payment_date, 'tax_payment', p_id, v_ref_number,\n     'Tax Payment ' || v_old.tax_type || ' — ' || v_ref_number,\n     p_amount, p_amount, true, auth.uid())\n  RETURNING id INTO v_je_id;\n\n  INSERT INTO journal_entry_lines\n    (journal_entry_id, line_number, account_id, description, debit, credit)\n  VALUES\n    (v_je_id, 1, v_payable_acct_id,\n     v_old.tax_type || ' payment — ' || v_ref_number, p_amount, 0),\n    (v_je_id, 2, v_bank_acct_coa_id,\n     'Bank ' || v_old.tax_type || ' payment — ' || v_ref_number, 0, p_amount);\n\n  UPDATE tax_payments SET journal_entry_id = v_je_id, status = 'posted', updated_at = now()\n   WHERE id = p_id;\n\n  -- Refresh period snapshot (belt-and-braces; the AFTER trigger also fires)\n  PERFORM compute_period_ppn(v_old.tax_period_id);\n\n  -- Audit log — captures full before/after\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, old_values, new_values)\n  VALUES (\n    auth.uid(), 'tax_payments', 'update', p_id,\n    jsonb_build_object(\n      'payment_date',      v_old.payment_date,\n      'amount',            v_old.amount,\n      'bank_account_id',   v_old.bank_account_id,\n      'ntpn',              v_old.ntpn,\n      'billing_code',      v_old.billing_code,\n      'payment_reference', v_old.payment_reference,\n      'notes',             v_old.notes,\n      'status',            v_old.status,\n      'old_je_ids',        to_jsonb(v_old_je_ids)\n    ),\n    jsonb_build_object(\n      'payment_date',      p_payment_date,\n      'amount',            p_amount,\n      'bank_account_id',   p_bank_account_id,\n      'ntpn',              p_ntpn,\n      'billing_code',      p_billing_code,\n      'payment_reference', p_payment_reference,\n      'notes',             p_notes,\n      'new_je_id',         v_je_id,\n      'edited_at',         now()\n    )\n  );\n\n  RETURN p_id;\nEND $$","--\n-- Name: FUNCTION \\"update_tax_payment\\"(\\"p_id\\" \\"uuid\\", \\"p_payment_date\\" \\"date\\", \\"p_amount\\" numeric, \\"p_bank_account_id\\" \\"uuid\\", \\"p_billing_code\\" \\"text\\", \\"p_ntpn\\" \\"text\\", \\"p_government_reference\\" \\"text\\", \\"p_notes\\" \\"text\\", \\"p_payment_reference\\" \\"text\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"update_tax_payment\\"(\\"p_id\\" \\"uuid\\", \\"p_payment_date\\" \\"date\\", \\"p_amount\\" numeric, \\"p_bank_account_id\\" \\"uuid\\", \\"p_billing_code\\" \\"text\\", \\"p_ntpn\\" \\"text\\", \\"p_government_reference\\" \\"text\\", \\"p_notes\\" \\"text\\", \\"p_payment_reference\\" \\"text\\") IS 'Reverse-and-repost tax payment editor. Refuses on closed periods. Refuses\non reconciled payments unless caller is admin (in which case the recon\nmatch is broken and the payment returns to posted state). Full old/new\naudit log entry written.'","--\n-- Name: update_updated_at_column(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_updated_at_column\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$","--\n-- Name: update_user_permissions_updated_at(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"update_user_permissions_updated_at\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\nNEW.updated_at = now();\nRETURN NEW;\nEND;\n$$","--\n-- Name: upsert_expense_journal_header_in_place(\\"uuid\\", \\"uuid\\", \\"date\\", \\"text\\", \\"text\\", numeric, \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"upsert_expense_journal_header_in_place\\"(\\"p_journal_id\\" \\"uuid\\", \\"p_expense_id\\" \\"uuid\\", \\"p_entry_date\\" \\"date\\", \\"p_description\\" \\"text\\", \\"p_transaction_category\\" \\"text\\", \\"p_total\\" numeric, \\"p_created_by\\" \\"uuid\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $_$\nDECLARE\n  v_journal_id uuid := p_journal_id;\n  v_entry_number text;\n  v_period_id uuid;\nBEGIN\n  SELECT id INTO v_period_id\n    FROM public.accounting_periods\n   WHERE start_date<=p_entry_date AND end_date>=p_entry_date\n   ORDER BY start_date DESC LIMIT 1;\n  IF v_journal_id IS NULL THEN\n    PERFORM pg_advisory_xact_lock(hashtext('expense-je-number:' || to_char(p_entry_date,'YYMM')));\n    SELECT 'JE' || to_char(p_entry_date,'YYMM') || '-' ||\n           lpad((COALESCE(max(CAST(substring(entry_number FROM '-([0-9]+)$') AS integer)),0)+1)::text,4,'0')\n      INTO v_entry_number\n      FROM public.journal_entries\n     WHERE entry_number LIKE 'JE' || to_char(p_entry_date,'YYMM') || '-%';\n\n    INSERT INTO public.journal_entries(\n      entry_number,entry_date,period_id,source_module,reference_id,reference_number,\n      description,transaction_category,total_debit,total_credit,is_posted,\n      posted_at,created_by\n    ) VALUES (\n      v_entry_number,p_entry_date,v_period_id,'expenses',p_expense_id,'EXP-'||p_expense_id::text,\n      p_description,p_transaction_category,p_total,p_total,true,now(),p_created_by\n    ) RETURNING id INTO v_journal_id;\n  ELSE\n    UPDATE public.journal_entries\n       SET entry_date=p_entry_date,\n           period_id=v_period_id,\n           source_module='expenses',\n           reference_id=p_expense_id,\n           reference_number='EXP-'||p_expense_id::text,\n           description=p_description,\n           transaction_category=p_transaction_category,\n           total_debit=p_total,\n           total_credit=p_total,\n           is_posted=true\n     WHERE id=v_journal_id\n       AND is_posted=true\n       AND NOT COALESCE(is_reversed,false);\n    IF NOT FOUND THEN\n      RAISE EXCEPTION 'Effective expense journal is no longer active';\n    END IF;\n  END IF;\n  RETURN v_journal_id;\nEND;\n$_$","--\n-- Name: upsert_notification(\\"uuid\\", \\"text\\", \\"text\\", \\"text\\", \\"uuid\\", \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"upsert_notification\\"(\\"p_user_id\\" \\"uuid\\", \\"p_type\\" \\"text\\", \\"p_title\\" \\"text\\", \\"p_message\\" \\"text\\", \\"p_reference_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\", \\"p_reference_type\\" \\"text\\" DEFAULT NULL::\\"text\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_inserted integer := 0;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)\n  VALUES (p_user_id, p_type, p_title, p_message, p_reference_id, p_reference_type, false)\n  ON CONFLICT DO NOTHING;\n\n  GET DIAGNOSTICS v_inserted = ROW_COUNT;\n  RETURN v_inserted > 0;\nEND;\n$$","--\n-- Name: upsert_tax_period(integer, integer, \\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"upsert_tax_period\\"(\\"p_fiscal_year\\" integer, \\"p_period_month\\" integer, \\"p_tax_type\\" \\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_id       uuid;\n  v_start    date;\n  v_end      date;\n  v_pay_due  date;\n  v_file_due date;\nBEGIN\n  SELECT period_start, period_end, payment_due_date, filing_due_date\n  INTO v_start, v_end, v_pay_due, v_file_due\n  FROM compute_tax_due_dates(p_tax_type, p_fiscal_year, p_period_month);\n\n  INSERT INTO tax_periods\n    (fiscal_year, period_month, tax_type, period_start, period_end,\n     payment_due_date, filing_due_date, created_by)\n  VALUES\n    (p_fiscal_year, p_period_month, p_tax_type, v_start, v_end,\n     v_pay_due, v_file_due, auth.uid())\n  ON CONFLICT (fiscal_year, period_month, tax_type)\n  DO UPDATE SET\n    payment_due_date = EXCLUDED.payment_due_date,\n    filing_due_date  = EXCLUDED.filing_due_date,\n    updated_at       = now()\n  RETURNING id INTO v_id;\n\n  RETURN v_id;\nEND $$","--\n-- Name: uuid_from_text(\\"text\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"uuid_from_text\\"(\\"p_key\\" \\"text\\") RETURNS \\"uuid\\"\n    LANGUAGE \\"sql\\" IMMUTABLE\n    SET \\"search_path\\" TO 'public'\n    AS $$\n  SELECT (\n    substr(md5(p_key), 1, 8) || '-' ||\n    substr(md5(p_key), 9, 4) || '-' ||\n    substr(md5(p_key), 13, 4) || '-' ||\n    substr(md5(p_key), 17, 4) || '-' ||\n    substr(md5(p_key), 21, 12)\n  )::uuid;\n$$","--\n-- Name: validate_bank_allocation_integrity(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_bank_allocation_integrity\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_line public.bank_statement_lines%rowtype;\n  v_je public.journal_entries%rowtype;\n  v_bank_coa uuid;\n  v_bank_currency text;\n  v_total numeric;\n  v_allocated numeric;\n  v_journal_debit numeric;\n  v_journal_credit numeric;\n  v_tx_debit numeric;\n  v_tx_credit numeric;\n  v_is_statement_debit boolean;\nBEGIN\n  SELECT * INTO v_line FROM public.bank_statement_lines\n   WHERE id = NEW.bank_statement_line_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Bank statement line % not found', NEW.bank_statement_line_id; END IF;\n  SELECT * INTO v_je FROM public.journal_entries\n   WHERE id = NEW.journal_entry_id FOR UPDATE;\n  IF NOT FOUND OR NOT v_je.is_posted OR COALESCE(v_je.is_reversed, false) THEN\n    RAISE EXCEPTION 'Allocation requires an active posted journal';\n  END IF;\n  SELECT coa_id, upper(currency) INTO v_bank_coa, v_bank_currency\n    FROM public.bank_accounts WHERE id = v_line.bank_account_id;\n  IF v_bank_coa IS NULL THEN RAISE EXCEPTION 'Bank account has no COA'; END IF;\n  IF upper(COALESCE(v_line.currency, '')) <> v_bank_currency THEN\n    RAISE EXCEPTION 'Statement/account currency mismatch';\n  END IF;\n  v_total := COALESCE(NULLIF(v_line.debit_amount, 0), v_line.credit_amount, 0);\n  SELECT COALESCE(sum(a.allocation_amount), 0) INTO v_allocated\n    FROM public.bank_statement_allocations a\n   WHERE a.bank_statement_line_id = NEW.bank_statement_line_id\n     AND (TG_OP <> 'UPDATE' OR a.id <> NEW.id);\n  IF v_allocated + NEW.allocation_amount > v_total + 0.01 THEN\n    RAISE EXCEPTION 'Bank allocations exceed statement amount';\n  END IF;\n  SELECT COALESCE(sum(l.debit), 0), COALESCE(sum(l.credit), 0),\n         COALESCE(sum(l.transaction_debit), 0), COALESCE(sum(l.transaction_credit), 0)\n    INTO v_journal_debit, v_journal_credit, v_tx_debit, v_tx_credit\n    FROM public.journal_entry_lines l\n   WHERE l.journal_entry_id = NEW.journal_entry_id AND l.account_id = v_bank_coa;\n  IF v_journal_debit = 0 AND v_journal_credit = 0 THEN\n    RAISE EXCEPTION 'Allocated journal has no bank COA movement';\n  END IF;\n  v_is_statement_debit := COALESCE(v_line.debit_amount, 0) > 0;\n  IF v_is_statement_debit AND v_journal_credit <= 0 THEN\n    RAISE EXCEPTION 'Statement debit requires a journal bank credit';\n  ELSIF NOT v_is_statement_debit AND v_journal_debit <= 0 THEN\n    RAISE EXCEPTION 'Statement credit requires a journal bank debit';\n  END IF;\n  -- Journal headers are historically inconsistent (some valid USD bank\n  -- postings carry IDR at header level).  Validate the linked bank COA lines,\n  -- which are the canonical bank-side currency evidence, instead.\n  IF v_bank_currency = 'USD' AND NOT EXISTS (\n    SELECT 1\n    FROM public.journal_entry_lines l\n    WHERE l.journal_entry_id = NEW.journal_entry_id\n      AND l.account_id = v_bank_coa\n      AND l.transaction_currency = 'USD'\n      AND l.functional_currency = 'IDR'\n      AND COALESCE(l.exchange_rate, 0) > 0\n      AND ((l.debit > 0 AND COALESCE(l.transaction_debit, 0) > 0)\n        OR (l.credit > 0 AND COALESCE(l.transaction_credit, 0) > 0))\n  ) THEN\n    RAISE EXCEPTION 'USD bank allocation requires valid USD metadata on the bank COA line';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"validate_bank_allocation_integrity\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"validate_bank_allocation_integrity\\"() IS 'Canonical bank allocation guard: active posted journal, currency/side validation, and no over-allocation.'","--\n-- Name: validate_bank_statement_line_integrity(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_bank_statement_line_integrity\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_currency text;\nBEGIN\n  SELECT upper(currency) INTO v_currency\n    FROM public.bank_accounts WHERE id = NEW.bank_account_id;\n  IF v_currency IS NULL THEN\n    RAISE EXCEPTION 'Bank statement line requires an active bank account';\n  END IF;\n  IF upper(COALESCE(NEW.currency, '')) <> v_currency THEN\n    RAISE EXCEPTION 'Bank statement currency % does not match bank account currency %', NEW.currency, v_currency\n      USING ERRCODE = 'check_violation';\n  END IF;\n  IF COALESCE(NEW.debit_amount, 0) < 0 OR COALESCE(NEW.credit_amount, 0) < 0\n     OR (COALESCE(NEW.debit_amount, 0) > 0 AND COALESCE(NEW.credit_amount, 0) > 0)\n     OR (COALESCE(NEW.debit_amount, 0) = 0 AND COALESCE(NEW.credit_amount, 0) = 0) THEN\n    RAISE EXCEPTION 'Bank statement line must have exactly one positive debit or credit amount'\n      USING ERRCODE = 'check_violation';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: validate_broker_items(\\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_broker_items\\"(\\"p_expense_id\\" \\"uuid\\") RETURNS boolean\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_amount        NUMERIC;\n  v_ppn_amount    NUMERIC;\n  v_items_total   NUMERIC;\n  v_ppn_items_sum NUMERIC;\n  v_ppn_present   BOOLEAN;\nBEGIN\n  SELECT\n    amount,\n    COALESCE(ppn_amount, 0),\n    -- For 'included' lines, item.amount is gross (DPP+PPN); parent.amount stores\n    -- DPP-only (matches client roll-up and prevents GL trigger double-count).\n    (SELECT SUM((item->>'amount')::NUMERIC\n                - CASE WHEN item->>'ppn_treatment' = 'included'\n                       THEN COALESCE((item->>'ppn_amount')::NUMERIC, 0)\n                       ELSE 0 END)\n       FROM jsonb_array_elements(broker_items) AS item),\n    (SELECT SUM(COALESCE((item->>'ppn_amount')::NUMERIC, 0))\n       FROM jsonb_array_elements(broker_items) AS item),\n    EXISTS (\n      SELECT 1 FROM jsonb_array_elements(broker_items) AS item\n       WHERE (item ? 'ppn_amount') AND (item->>'ppn_amount') IS NOT NULL\n    )\n  INTO v_amount, v_ppn_amount, v_items_total, v_ppn_items_sum, v_ppn_present\n  FROM finance_expenses\n  WHERE id = p_expense_id;\n\n  -- No broker_items → always valid (unchanged behaviour)\n  IF v_items_total IS NULL THEN\n    RETURN TRUE;\n  END IF;\n\n  -- Existing invariant: sum of line amounts = parent amount\n  IF v_items_total <> v_amount THEN\n    RETURN FALSE;\n  END IF;\n\n  -- New guard: if any line carries ppn_amount, the roll-up must match parent\n  IF v_ppn_present AND ABS(COALESCE(v_ppn_items_sum, 0) - v_ppn_amount) > 1 THEN\n    RETURN FALSE;\n  END IF;\n\n  RETURN TRUE;\nEND $$","--\n-- Name: validate_dc_item_product_reservation_v2(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_dc_item_product_reservation_v2\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_dc record; v_reserved numeric; v_pending numeric; v_so_make uuid; v_batch_make uuid;\nBEGIN\n  SELECT dc.sales_order_id,dc.approval_status INTO v_dc FROM public.delivery_challans dc WHERE dc.id=NEW.challan_id;\n  IF NOT FOUND OR NEW.sales_order_item_id IS NULL THEN RAISE EXCEPTION 'DC item requires a canonical SO item'; END IF;\n  SELECT soi.make_id INTO v_so_make FROM public.sales_order_items soi\n   WHERE soi.id=NEW.sales_order_item_id AND soi.sales_order_id=v_dc.sales_order_id AND soi.product_id=NEW.product_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'DC product does not match its SO item'; END IF;\n  SELECT b.make_id INTO v_batch_make FROM public.batches b\n   WHERE b.id=NEW.batch_id AND b.product_id=NEW.product_id AND b.is_active\n     AND (b.expiry_date IS NULL OR b.expiry_date>CURRENT_DATE);\n  IF NOT FOUND THEN RAISE EXCEPTION 'Selected DC batch is not eligible for this product'; END IF;\n  -- NULL Make preserves historical records; known Make must match exactly.\n  IF v_so_make IS NOT NULL AND v_batch_make IS DISTINCT FROM v_so_make THEN\n    RAISE EXCEPTION 'Selected DC batch Make does not match the Sales Order Make';\n  END IF;\n  SELECT COALESCE(reserved_quantity,0) INTO v_reserved FROM public.so_product_reservations\n    WHERE sales_order_item_id=NEW.sales_order_item_id AND status='active';\n  SELECT COALESCE(sum(dci.quantity),0) INTO v_pending\n  FROM public.delivery_challan_items dci JOIN public.delivery_challans dc ON dc.id=dci.challan_id\n  WHERE dci.sales_order_item_id=NEW.sales_order_item_id AND dc.approval_status='pending_approval'\n    AND dci.id IS DISTINCT FROM NEW.id;\n  IF v_pending+NEW.quantity>v_reserved THEN RAISE EXCEPTION 'DC quantities exceed remaining SO product reservation'; END IF;\n  RETURN NEW;\nEND; $$","--\n-- Name: validate_delivery_challan_complete_source(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_delivery_challan_complete_source\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF NEW.sales_order_id IS NOT NULL AND NEW.customer_id IS DISTINCT FROM (SELECT customer_id FROM public.sales_orders WHERE id=NEW.sales_order_id) THEN\n    RAISE EXCEPTION 'Delivery Challan customer must match Sales Order customer';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: validate_delivery_challan_source_item(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_delivery_challan_source_item\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_dc public.delivery_challans%rowtype; v_soi public.sales_order_items%rowtype; v_remaining numeric;\nBEGIN\n  SELECT * INTO v_dc FROM public.delivery_challans WHERE id=NEW.challan_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Delivery Challan does not exist'; END IF;\n  IF v_dc.sales_order_id IS NULL THEN\n    IF NEW.sales_order_item_id IS NOT NULL THEN RAISE EXCEPTION 'Unlinked Delivery Challan cannot reference a Sales Order item'; END IF;\n    RETURN NEW;\n  END IF;\n  IF NEW.sales_order_item_id IS NULL THEN\n    SELECT soi.id INTO NEW.sales_order_item_id\n    FROM public.sales_order_items soi\n    WHERE soi.sales_order_id=v_dc.sales_order_id AND soi.product_id=NEW.product_id;\n    IF NEW.sales_order_item_id IS NULL THEN RAISE EXCEPTION 'Delivery Challan product is not present on the selected Sales Order'; END IF;\n    IF (SELECT count(*) FROM public.sales_order_items soi WHERE soi.sales_order_id=v_dc.sales_order_id AND soi.product_id=NEW.product_id) > 1 THEN\n      RAISE EXCEPTION 'Delivery Challan item source is ambiguous; select the exact Sales Order item';\n    END IF;\n  END IF;\n  IF NEW.sales_order_item_id IS NULL THEN RAISE EXCEPTION 'Sales Order-linked Delivery Challan item requires sales_order_item_id'; END IF;\n  SELECT * INTO v_soi FROM public.sales_order_items WHERE id=NEW.sales_order_item_id AND sales_order_id=v_dc.sales_order_id FOR SHARE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Delivery Challan item is not from the selected Sales Order'; END IF;\n  IF NEW.product_id IS DISTINCT FROM v_soi.product_id THEN RAISE EXCEPTION 'Delivery Challan product must match the Sales Order item'; END IF;\n  v_remaining:=v_soi.quantity-COALESCE(v_soi.delivered_quantity,0);\n  IF TG_OP='UPDATE' THEN v_remaining:=v_remaining+COALESCE(OLD.quantity,0); END IF;\n  IF NEW.quantity<=0 OR NEW.quantity>v_remaining+0.0001 THEN RAISE EXCEPTION 'Delivery quantity exceeds remaining Sales Order quantity'; END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: validate_expense_bank_allocation_against_journal(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_expense_bank_allocation_against_journal\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE v_payable numeric; v_allocated numeric; v_journal_cash numeric;\nBEGIN\n  IF NEW.document_type<>'expense' THEN RETURN NEW; END IF;\n  v_payable:=CASE WHEN NEW.payment_kind='pph23'\n    THEN COALESCE((SELECT pph_amount FROM public.finance_expenses WHERE id=NEW.document_id),0)\n    ELSE COALESCE(public.calculate_finance_expense_payable(NEW.document_id),0) END;\n  SELECT COALESCE(sum(allocation_amount),0)+NEW.allocation_amount INTO v_allocated\n    FROM public.bank_statement_allocations\n   WHERE document_type='expense' AND document_id=NEW.document_id\n     AND payment_kind=NEW.payment_kind AND (TG_OP<>'UPDATE' OR id<>NEW.id);\n  IF v_allocated>v_payable+0.01 THEN RAISE EXCEPTION 'Allocation exceeds document outstanding amount'; END IF;\n  IF (SELECT source_module FROM public.journal_entries WHERE id=NEW.journal_entry_id)='expense_payment' THEN\n    SELECT COALESCE(sum(l.credit),0) INTO v_journal_cash\n      FROM public.journal_entry_lines l JOIN public.bank_accounts ba ON ba.coa_id=l.account_id\n     WHERE l.journal_entry_id=NEW.journal_entry_id;\n    IF abs(v_journal_cash-NEW.allocation_amount)>0.01 THEN\n      RAISE EXCEPTION 'Expense payment journal bank credit must equal the confirmed allocation amount';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: validate_expense_category_assignment(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_expense_category_assignment\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_category public.expense_categories%ROWTYPE;\n  v_coa public.chart_of_accounts%ROWTYPE;\nBEGIN\n  IF TG_OP = 'UPDATE'\n     AND OLD.expense_category = 'utilities'\n     AND NEW.expense_category = 'utilities' THEN\n    RETURN NEW;\n  END IF;\n\n  IF NULLIF(btrim(NEW.expense_category), '') IS NULL THEN\n    RAISE EXCEPTION 'Expense category is required.' USING ERRCODE = '23514';\n  END IF;\n\n  SELECT * INTO v_category\n    FROM public.expense_categories\n   WHERE category_key = NEW.expense_category;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" does not exist in Expense Category Master.',\n      NEW.expense_category USING ERRCODE = '23514';\n  END IF;\n  IF NOT v_category.is_active THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" is inactive.', v_category.name\n      USING ERRCODE = '23514';\n  END IF;\n  IF NOT v_category.is_posting_category THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" is a grouping category. Select an active posting leaf.',\n      v_category.name USING ERRCODE = '23514';\n  END IF;\n  IF v_category.coa_account_id IS NULL THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" has no configured Chart of Account.',\n      v_category.name USING ERRCODE = '23514';\n  END IF;\n\n  SELECT * INTO v_coa\n    FROM public.chart_of_accounts\n   WHERE id = v_category.coa_account_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" references a missing Chart of Account.',\n      v_category.name USING ERRCODE = '23514';\n  END IF;\n  IF NOT v_coa.is_active OR v_coa.is_header THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" must use an active non-header Chart of Account.',\n      v_category.name USING ERRCODE = '23514';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: validate_expense_category_master(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_expense_category_master\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\n  v_account record;\nBEGIN\n  IF NEW.parent_id = NEW.id THEN\n    RAISE EXCEPTION 'An expense category cannot be its own parent';\n  END IF;\n\n  IF NOT NEW.is_posting_category THEN\n    NEW.coa_account_id := NULL;\n  ELSE\n    SELECT is_active, is_header INTO v_account\n    FROM public.chart_of_accounts WHERE id=NEW.coa_account_id;\n    IF NOT FOUND OR NOT v_account.is_active OR v_account.is_header THEN\n      RAISE EXCEPTION 'Each posting expense category must use an active posting Chart of Account';\n    END IF;\n  END IF;\n  NEW.updated_at := now();\n  RETURN NEW;\nEND;\n$$","--\n-- Name: validate_expense_context(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_expense_context\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_category_type text;\n  v_requires_container boolean;\nBEGIN\n  SELECT category_type, requires_container\n    INTO v_category_type, v_requires_container\n    FROM public.expense_categories\n   WHERE category_key = NEW.expense_category;\n\n  NEW.expense_type := CASE v_category_type\n    WHEN 'import' THEN 'import'\n    WHEN 'sales' THEN 'sales'\n    ELSE 'general'\n  END;\n\n  IF COALESCE(v_requires_container, false) AND NEW.import_container_id IS NULL THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" requires an Import Container.',\n      NEW.expense_category USING ERRCODE = '23514';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","--\n-- Name: validate_fund_transfer_bank_statement_link(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_fund_transfer_bank_statement_link\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\ndeclare\n  v_ft public.fund_transfers%rowtype;\n  v_ba public.bank_accounts%rowtype;\n  v_expected numeric;\n  v_amount numeric;\nbegin\n  if new.matched_fund_transfer_id is null then return new; end if;\n  select * into v_ft from public.fund_transfers where id=new.matched_fund_transfer_id;\n  if not found then raise exception 'Invalid fund transfer link'; end if;\n  select * into v_ba from public.bank_accounts where id=new.bank_account_id;\n  if not found then raise exception 'Invalid bank account on statement line'; end if;\n  if new.transaction_date is distinct from v_ft.transfer_date then\n    raise exception 'Fund transfer % date % does not match bank statement date %',v_ft.transfer_number,v_ft.transfer_date,new.transaction_date;\n  end if;\n  if new.bank_account_id=v_ft.from_bank_account_id then\n    v_expected:=v_ft.from_amount;\n    v_amount:=coalesce(nullif(new.debit_amount,0),new.credit_amount);\n  elsif new.bank_account_id=v_ft.to_bank_account_id then\n    v_expected:=v_ft.to_amount;\n    v_amount:=coalesce(nullif(new.credit_amount,0),new.debit_amount);\n  else\n    raise exception 'Bank statement account is not a fund transfer side';\n  end if;\n  if abs(coalesce(v_amount,0)-coalesce(v_expected,0))>0.01 then\n    raise exception 'Fund transfer % amount %.2f does not match bank statement amount %.2f',v_ft.transfer_number,v_expected,v_amount;\n  end if;\n  if v_ft.journal_entry_id is not null and new.matched_entry_id is not null and new.matched_entry_id<>v_ft.journal_entry_id then\n    raise exception 'Fund transfer % must link to its canonical journal entry',v_ft.transfer_number;\n  end if;\n  if v_ft.journal_entry_id is null and new.matched_entry_id is not null then\n    raise exception 'Fund transfer % has no canonical journal entry',v_ft.transfer_number;\n  end if;\n  return new;\nend;\n$$","--\n-- Name: FUNCTION \\"validate_fund_transfer_bank_statement_link\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"validate_fund_transfer_bank_statement_link\\"() IS 'Prevents false fund-transfer reconciliation: linked statement must be the correct transfer side, exact amount, exact transfer date, and canonical journal.'","--\n-- Name: validate_fund_transfer_fx(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_fund_transfer_fx\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\n      DECLARE\n        v_from numeric;\n        v_to   numeric;\n        v_rate numeric;\n        v_expected numeric;\n      BEGIN\n        IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;\n\n        v_from := COALESCE(NEW.from_amount, 0);\n        v_to   := COALESCE(NEW.to_amount, 0);\n        v_rate := COALESCE(NEW.exchange_rate, 1);\n\n        IF v_from <= 0 OR v_to <= 0 THEN\n          RAISE EXCEPTION 'Fund transfer amounts must be positive';\n        END IF;\n        IF v_rate <= 0 THEN\n          RAISE EXCEPTION 'exchange_rate must be positive';\n        END IF;\n\n        v_expected := v_from * v_rate;\n        IF abs(v_to - v_expected) / GREATEST(v_to, 1) > 0.02 THEN\n          RAISE EXCEPTION 'FX inconsistency: to_amount % differs from from_amount % * rate % by more than 2%%',\n            v_to, v_from, v_rate;\n        END IF;\n\n        RETURN NEW;\n      END $$","--\n-- Name: validate_historical_pph_payment_exception(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_historical_pph_payment_exception\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF NEW.historical_source_status = 'missing_source_verified' THEN\n    IF NEW.tax_type NOT IN ('PPh21','PPh22','PPh23','PPh4(2)')\n       OR NULLIF(btrim(COALESCE(NEW.historical_source_reference,'')), '') IS NULL\n       OR NEW.journal_entry_id IS NULL\n       OR NOT EXISTS (\n         SELECT 1 FROM public.journal_entries je\n          WHERE je.id=NEW.journal_entry_id AND je.is_posted AND NOT COALESCE(je.is_reversed,false)\n       )\n       OR NOT EXISTS (\n         SELECT 1\n           FROM public.bank_statement_allocations a\n           JOIN public.bank_statement_lines bsl ON bsl.id=a.bank_statement_line_id\n          WHERE a.document_type='tax_payment' AND a.document_id=NEW.id\n            AND a.journal_entry_id=NEW.journal_entry_id\n            AND bsl.matched_tax_payment_id=NEW.id\n            AND abs(COALESCE(a.allocation_amount,0)-NEW.amount)<0.01\n       ) THEN\n      RAISE EXCEPTION 'Historical PPh exception requires matching posted journal, full canonical bank allocation, and source reference';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND $$","--\n-- Name: validate_invoice_dc_items(\\"jsonb\\", \\"uuid\\"); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_invoice_dc_items\\"(\\"p_items\\" \\"jsonb\\", \\"p_exclude_invoice_id\\" \\"uuid\\" DEFAULT NULL::\\"uuid\\") RETURNS TABLE(\\"is_valid\\" boolean, \\"error_message\\" \\"text\\", \\"invalid_items\\" \\"jsonb\\")\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_item JSONB;\nv_dc_item_id UUID;\nv_requested_quantity NUMERIC;\nv_available_quantity NUMERIC;\nv_errors JSONB := '[]'::JSONB;\nv_has_errors BOOLEAN := FALSE;\nBEGIN\n-- Loop through each item to validate\nFOR v_item IN SELECT * FROM jsonb_array_elements(p_items)\nLOOP\nv_dc_item_id := (v_item->>'dc_item_id')::UUID;\nv_requested_quantity := (v_item->>'quantity')::NUMERIC;\n\n-- Skip validation for manual items (no dc_item_id)\nIF v_dc_item_id IS NULL THEN\nCONTINUE;\nEND IF;\n\n-- Get available quantity for this DC item\nSELECT \ndis.original_quantity - dis.invoiced_quantity +\n-- Add back quantity from the invoice being edited (if any)\nCOALESCE(\n(SELECT SUM(sii.quantity) \nFROM sales_invoice_items sii \nWHERE sii.delivery_challan_item_id = v_dc_item_id \nAND sii.invoice_id = p_exclude_invoice_id),\n0\n)\nINTO v_available_quantity\nFROM dc_item_invoice_status dis\nWHERE dis.dc_item_id = v_dc_item_id;\n\n-- Check if requested quantity exceeds available\nIF v_requested_quantity > v_available_quantity THEN\nv_has_errors := TRUE;\nv_errors := v_errors || jsonb_build_object(\n'dc_item_id', v_dc_item_id,\n'product_name', v_item->>'product_name',\n'batch_number', v_item->>'batch_number',\n'requested_quantity', v_requested_quantity,\n'available_quantity', v_available_quantity,\n'error', format('Requested quantity %s exceeds available quantity %s', \nv_requested_quantity, v_available_quantity)\n);\nEND IF;\nEND LOOP;\n\n-- Return results\nRETURN QUERY SELECT \nNOT v_has_errors,\nCASE \nWHEN v_has_errors THEN 'Some DC items have insufficient quantity available'\nELSE 'All items validated successfully'\nEND,\nv_errors;\nEND;\n$$","--\n-- Name: FUNCTION \\"validate_invoice_dc_items\\"(\\"p_items\\" \\"jsonb\\", \\"p_exclude_invoice_id\\" \\"uuid\\"); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"validate_invoice_dc_items\\"(\\"p_items\\" \\"jsonb\\", \\"p_exclude_invoice_id\\" \\"uuid\\") IS 'Validates that requested DC item quantities do not exceed available quantities. Prevents over-invoicing of DC items.'","--\n-- Name: validate_non_permanent_employee_fee(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_non_permanent_employee_fee\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE v_pph21_code uuid;\nBEGIN\n  IF NEW.expense_category = 'non_permanent_employee_fee' THEN\n    IF NEW.supplier_id IS NOT NULL AND NOT EXISTS (\n      SELECT 1 FROM public.suppliers s\n      WHERE s.id = NEW.supplier_id\n        AND lower(COALESCE(s.supplier_type,'')) IN (\n          'employee','non-permanent individual','freelancer','casual worker','honorarium recipient'\n        )\n    ) THEN\n      RAISE EXCEPTION 'Non-Permanent Employee Fee is intended for an individual subject to PPh 21, not a company supplier';\n    END IF;\n\n    -- Default only. An explicit accountant-selected tax code is preserved.\n    IF NEW.pph_code_id IS NULL THEN\n      SELECT id INTO v_pph21_code FROM public.tax_codes\n      WHERE tax_type = 'PPh21' AND is_withholding = true\n      ORDER BY (code = 'PPH21') DESC, code LIMIT 1;\n      IF v_pph21_code IS NULL THEN\n        RAISE EXCEPTION 'PPh21 tax code is not configured';\n      END IF;\n      NEW.pph_code_id := v_pph21_code;\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"validate_non_permanent_employee_fee\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"validate_non_permanent_employee_fee\\"() IS 'Defaults Non-Permanent Employee Fee expenses to PPh21 while preserving accountant tax-code overrides.'","--\n-- Name: validate_petty_cash_chain_integrity(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_petty_cash_chain_integrity\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_ft public.fund_transfers%rowtype;\n  v_je public.journal_entries%rowtype;\n  v_pc_account uuid;\n  v_pc_debit numeric := 0;\n  v_pc_credit numeric := 0;\n  v_expense_account uuid;\nBEGIN\n  IF NEW.fund_transfer_id IS NOT NULL THEN\n    SELECT * INTO v_ft FROM public.fund_transfers WHERE id=NEW.fund_transfer_id FOR SHARE;\n    IF NOT FOUND THEN RAISE EXCEPTION 'Petty Cash % references missing fund transfer',NEW.id; END IF;\n    IF NEW.transaction_type <> 'withdraw' OR v_ft.to_account_type <> 'petty_cash'\n       OR abs(NEW.amount-COALESCE(v_ft.to_amount,v_ft.amount)) > 0.01 THEN\n      RAISE EXCEPTION 'Petty Cash % amount/direction does not match Fund Transfer %',NEW.id,v_ft.transfer_number USING ERRCODE='check_violation';\n    END IF;\n  END IF;\n\n  SELECT id INTO v_pc_account FROM public.chart_of_accounts WHERE code='1102' AND is_header=false AND is_active=true LIMIT 1;\n  IF NEW.approval_status='approved' AND COALESCE(NEW.source,'') NOT LIKE 'historical_expense:%'\n     AND NEW.transaction_type='expense' THEN\n    SELECT je.* INTO v_je FROM public.journal_entries je\n     WHERE je.source_module='petty_cash' AND je.reference_id=NEW.id AND je.is_posted AND NOT COALESCE(je.is_reversed,false);\n    IF NOT FOUND THEN RAISE EXCEPTION 'Approved Petty Cash expense % has no active canonical journal',NEW.transaction_number; END IF;\n    SELECT COALESCE(sum(l.debit),0),COALESCE(sum(l.credit),0) INTO v_pc_debit,v_pc_credit\n      FROM public.journal_entry_lines l WHERE l.journal_entry_id=v_je.id AND l.account_id=v_pc_account;\n    IF abs(v_pc_credit-NEW.amount)>0.01 OR v_pc_debit>0.01 THEN\n      RAISE EXCEPTION 'Petty Cash expense % journal amount/direction mismatch',NEW.transaction_number USING ERRCODE='check_violation';\n    END IF;\n    v_expense_account:=public.get_expense_account_id(NEW.expense_category);\n    IF NOT EXISTS (SELECT 1 FROM public.journal_entry_lines l WHERE l.journal_entry_id=v_je.id AND l.account_id=v_expense_account AND abs(l.debit-NEW.amount)<=0.01 AND l.credit=0) THEN\n      RAISE EXCEPTION 'Petty Cash expense % journal account/category mismatch',NEW.transaction_number USING ERRCODE='check_violation';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"validate_petty_cash_chain_integrity\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"validate_petty_cash_chain_integrity\\"() IS 'Deferred Petty Cash amount, direction, canonical journal and category guard; historical_expense rows are explicitly legacy.'","--\n-- Name: validate_petty_cash_journal_reference(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_petty_cash_journal_reference\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF NEW.source_module='petty_cash' AND NEW.is_posted AND NEW.reference_id IS NULL THEN\n    RAISE EXCEPTION 'Posted Petty Cash journal requires a canonical transaction reference' USING ERRCODE='check_violation';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: validate_petty_cash_transfer_commit(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_petty_cash_transfer_commit\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nBEGIN\n  IF NEW.status='posted' AND NEW.to_account_type='petty_cash'\n     AND NOT EXISTS (SELECT 1 FROM public.petty_cash_transactions pc WHERE pc.fund_transfer_id=NEW.id) THEN\n    RAISE EXCEPTION 'Posted Fund Transfer % to Petty Cash requires one canonical Petty Cash transaction',NEW.transfer_number USING ERRCODE='check_violation';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"validate_petty_cash_transfer_commit\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"validate_petty_cash_transfer_commit\\"() IS 'Deferred guard requiring a canonical Petty Cash transaction for newly posted transfers into Petty Cash.'","--\n-- Name: validate_salary_advance_payment_purpose(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_salary_advance_payment_purpose\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public'\n    AS $$\nBEGIN\n  IF NEW.payment_purpose = 'salary_advance' THEN\n    IF NEW.staff_id IS NULL OR NEW.supplier_id IS NOT NULL THEN\n      RAISE EXCEPTION 'Salary Advance payments require a staff payee';\n    END IF;\n    IF NEW.payment_method = 'advance_adjustment' THEN\n      RAISE EXCEPTION 'Salary Advance cash payments cannot use advance_adjustment';\n    END IF;\n  ELSIF NEW.payment_purpose = 'salary_advance_settlement'\n    AND NEW.payment_method <> 'advance_adjustment' THEN\n    RAISE EXCEPTION 'Salary Advance settlement must use advance_adjustment';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: validate_sales_invoice_so_link(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_sales_invoice_so_link\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_so_customer uuid;\n  v_so_created_by uuid;\n  v_role text;\n  v_is_dc_sourced boolean := false;\nBEGIN\n  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;\n  IF NEW.sales_order_id IS NULL THEN RETURN NEW; END IF;\n  IF auth.role() = 'service_role' THEN RETURN NEW; END IF;\n\n  SELECT customer_id, created_by\n    INTO v_so_customer, v_so_created_by\n  FROM public.sales_orders\n  WHERE id = NEW.sales_order_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales order % not found', NEW.sales_order_id;\n  END IF;\n\n  IF NEW.customer_id IS DISTINCT FROM v_so_customer THEN\n    RAISE EXCEPTION 'Invoice customer_id must match linked sales order customer_id';\n  END IF;\n\n  SELECT role INTO v_role\n  FROM public.user_profiles\n  WHERE id = auth.uid();\n\n  IF v_role IN ('admin','accounts') OR v_so_created_by = auth.uid() THEN\n    RETURN NEW;\n  END IF;\n\n  IF v_role = 'warehouse' AND COALESCE(array_length(NEW.linked_challan_ids, 1), 0) > 0 THEN\n    SELECT EXISTS (\n      SELECT 1\n      FROM public.delivery_challans dc\n      WHERE dc.id = ANY(NEW.linked_challan_ids::uuid[])\n        AND dc.sales_order_id = NEW.sales_order_id\n    ) INTO v_is_dc_sourced;\n\n    IF v_is_dc_sourced THEN\n      RETURN NEW;\n    END IF;\n  END IF;\n\n  RAISE EXCEPTION 'Only admin/accounts, warehouse staff creating an invoice from its source Delivery Challan, or the SO owner may link this sales order';\nEND;\n$$","--\n-- Name: validate_usd_bank_journal_line(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"validate_usd_bank_journal_line\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\" SECURITY DEFINER\n    SET \\"search_path\\" TO 'public', 'pg_temp'\n    AS $$\nDECLARE\n  v_is_usd boolean;\n  v_rate numeric;\nBEGIN\n  SELECT upper(ba.currency) = 'USD' INTO v_is_usd\n    FROM public.bank_accounts ba WHERE ba.coa_id = NEW.account_id AND ba.is_active = true\n    LIMIT 1;\n  IF NOT COALESCE(v_is_usd, false) THEN RETURN NEW; END IF;\n  -- Canonical posters insert lines before the document-row synchronization\n  -- trigger fills their currency metadata.  Enforce strictly once bank\n  -- evidence is allocated, and on every later mutation of that bank line.\n  IF NOT EXISTS (\n    SELECT 1 FROM public.bank_statement_allocations a\n    WHERE a.journal_entry_id = NEW.journal_entry_id\n  ) THEN\n    RETURN NEW;\n  END IF;\n  v_rate := COALESCE(NEW.exchange_rate, 0);\n  IF NEW.transaction_currency IS DISTINCT FROM 'USD'\n     OR NEW.functional_currency IS DISTINCT FROM 'IDR'\n     OR v_rate <= 0\n     OR (COALESCE(NEW.transaction_debit, 0) = 0 AND COALESCE(NEW.transaction_credit, 0) = 0)\n     OR abs(COALESCE(NEW.debit, 0) - COALESCE(NEW.transaction_debit, 0) * v_rate) > 0.01\n     OR abs(COALESCE(NEW.credit, 0) - COALESCE(NEW.transaction_credit, 0) * v_rate) > 0.01\n     OR (NEW.debit > 0 AND NEW.transaction_credit > 0)\n     OR (NEW.credit > 0 AND NEW.transaction_debit > 0) THEN\n    RAISE EXCEPTION 'USD bank journal line has inconsistent transaction/functional currency metadata'\n      USING ERRCODE = 'check_violation';\n  END IF;\n  RETURN NEW;\nEND;\n$$","--\n-- Name: FUNCTION \\"validate_usd_bank_journal_line\\"(); Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON FUNCTION \\"public\\".\\"validate_usd_bank_journal_line\\"() IS 'Requires mathematically consistent USD transaction and IDR functional metadata on USD bank COA lines.'","--\n-- Name: verify_dc_has_items_before_approval(); Type: FUNCTION; Schema: public; Owner: -\n--\n\nCREATE FUNCTION \\"public\\".\\"verify_dc_has_items_before_approval\\"() RETURNS \\"trigger\\"\n    LANGUAGE \\"plpgsql\\"\n    SET \\"search_path\\" TO 'public'\n    AS $$\nDECLARE\nv_item_count integer;\nBEGIN\n-- Only check when approval_status is being changed to 'approved'\nIF NEW.approval_status = 'approved' AND (OLD.approval_status IS NULL OR OLD.approval_status != 'approved') THEN\n-- Check if DC has items\nSELECT COUNT(*) INTO v_item_count\nFROM delivery_challan_items\nWHERE challan_id = NEW.id;\n\nIF v_item_count = 0 THEN\nRAISE EXCEPTION 'Cannot approve Delivery Challan %. It has no items. Please add items before approving.',\nNEW.challan_number;\nEND IF;\nEND IF;\n\nRETURN NEW;\nEND;\n$$","--\n-- Name: accounting_periods; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"accounting_periods\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"fiscal_year\\" integer NOT NULL,\n    \\"period_month\\" integer NOT NULL,\n    \\"start_date\\" \\"date\\" NOT NULL,\n    \\"end_date\\" \\"date\\" NOT NULL,\n    \\"status\\" character varying(20) DEFAULT 'open'::character varying,\n    \\"closed_by\\" \\"uuid\\",\n    \\"closed_at\\" timestamp with time zone,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"accounting_periods_period_month_check\\" CHECK (((\\"period_month\\" >= 1) AND (\\"period_month\\" <= 12))),\n    CONSTRAINT \\"accounting_periods_status_check\\" CHECK (((\\"status\\")::\\"text\\" = ANY ((ARRAY['open'::character varying, 'closed'::character varying, 'locked'::character varying])::\\"text\\"[])))\n)","--\n-- Name: app_settings; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"app_settings\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"company_name\\" \\"text\\" DEFAULT 'Your Company Name'::\\"text\\" NOT NULL,\n    \\"company_address\\" \\"text\\",\n    \\"company_phone\\" \\"text\\",\n    \\"company_email\\" \\"text\\",\n    \\"company_tax_id\\" \\"text\\",\n    \\"company_logo_url\\" \\"text\\",\n    \\"tax_rate\\" numeric(5,2) DEFAULT 0,\n    \\"invoice_prefix\\" \\"text\\" DEFAULT 'INV'::\\"text\\",\n    \\"default_language\\" \\"text\\" DEFAULT 'en'::\\"text\\",\n    \\"low_stock_threshold\\" numeric(15,3) DEFAULT 100,\n    \\"expiry_alert_days\\" integer DEFAULT 90,\n    \\"email_host\\" \\"text\\",\n    \\"email_port\\" integer,\n    \\"email_username\\" \\"text\\",\n    \\"smtp_password\\" \\"text\\",\n    \\"smtp_from_email\\" \\"text\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"invoice_start_number\\" integer DEFAULT 1,\n    \\"financial_year_start\\" \\"text\\" DEFAULT '2024-01-01'::\\"text\\",\n    \\"financial_year_end\\" \\"text\\" DEFAULT '2024-12-31'::\\"text\\",\n    \\"current_financial_year\\" \\"text\\" DEFAULT '2024'::\\"text\\",\n    \\"bulk_email_batch_size\\" integer DEFAULT 10 NOT NULL,\n    \\"bulk_email_batch_delay_seconds\\" integer DEFAULT 30 NOT NULL,\n    \\"bulk_email_worker_url\\" \\"text\\",\n    \\"bulk_email_worker_secret\\" \\"text\\",\n    \\"rounding_tolerance_amount\\" numeric(18,2) DEFAULT 100 NOT NULL,\n    \\"rounding_writeoff_account_id\\" \\"uuid\\",\n    \\"rounding_gain_account_id\\" \\"uuid\\",\n    \\"setup_mode\\" boolean DEFAULT false NOT NULL,\n    CONSTRAINT \\"app_settings_default_language_check\\" CHECK ((\\"default_language\\" = ANY (ARRAY['en'::\\"text\\", 'id'::\\"text\\"])))\n)","--\n-- Name: COLUMN \\"app_settings\\".\\"rounding_tolerance_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"app_settings\\".\\"rounding_tolerance_amount\\" IS 'Maximum residual balance, in company currency, that can be automatically cleared during receipt allocation.'","--\n-- Name: COLUMN \\"app_settings\\".\\"rounding_writeoff_account_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"app_settings\\".\\"rounding_writeoff_account_id\\" IS 'Expense account used when a customer underpayment residual is cleared.'","--\n-- Name: COLUMN \\"app_settings\\".\\"rounding_gain_account_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"app_settings\\".\\"rounding_gain_account_id\\" IS 'Income account used when a small overpayment residual is cleared.'","--\n-- Name: COLUMN \\"app_settings\\".\\"setup_mode\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"app_settings\\".\\"setup_mode\\" IS 'Temporary implementation-phase flag. When true, historical Company Profile protections and other production audit guards are bypassed. Flip back to false before going live.'","--\n-- Name: approval_thresholds; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"approval_thresholds\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"transaction_type\\" \\"text\\" NOT NULL,\n    \\"min_amount\\" numeric(15,2) DEFAULT 0,\n    \\"max_amount\\" numeric(15,2),\n    \\"required_role\\" \\"text\\" NOT NULL,\n    \\"description\\" \\"text\\",\n    \\"is_active\\" boolean DEFAULT true,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"approval_thresholds_required_role_check\\" CHECK ((\\"required_role\\" = ANY (ARRAY['manager'::\\"text\\", 'admin'::\\"text\\"])))\n)","--\n-- Name: TABLE \\"approval_thresholds\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON TABLE \\"public\\".\\"approval_thresholds\\" IS 'Legacy approval threshold configuration table. Currently unused but kept for historical reference. May be deprecated in future releases.'","--\n-- Name: approval_workflows; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"approval_workflows\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"transaction_type\\" \\"text\\" NOT NULL,\n    \\"transaction_id\\" \\"uuid\\" NOT NULL,\n    \\"requested_by\\" \\"uuid\\" NOT NULL,\n    \\"amount\\" numeric(15,2) DEFAULT 0,\n    \\"quantity\\" numeric(10,2) DEFAULT 0,\n    \\"status\\" \\"text\\" DEFAULT 'pending'::\\"text\\" NOT NULL,\n    \\"approved_by\\" \\"uuid\\",\n    \\"rejection_reason\\" \\"text\\",\n    \\"notes\\" \\"text\\",\n    \\"metadata\\" \\"jsonb\\" DEFAULT '{}'::\\"jsonb\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"approval_workflows_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['pending'::\\"text\\", 'approved'::\\"text\\", 'rejected'::\\"text\\"]))),\n    CONSTRAINT \\"approval_workflows_transaction_type_check\\" CHECK ((\\"transaction_type\\" = ANY (ARRAY['material_return'::\\"text\\", 'stock_rejection'::\\"text\\", 'purchase_approval'::\\"text\\", 'expense_approval'::\\"text\\"])))\n)","--\n-- Name: audit_logs; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"audit_logs\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"user_id\\" \\"uuid\\",\n    \\"table_name\\" \\"text\\" NOT NULL,\n    \\"action_type\\" \\"text\\" NOT NULL,\n    \\"record_id\\" \\"uuid\\",\n    \\"old_values\\" \\"jsonb\\",\n    \\"new_values\\" \\"jsonb\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"changed_fields\\" \\"text\\"[],\n    \\"user_email\\" \\"text\\",\n    \\"ip_address\\" \\"text\\",\n    \\"user_agent\\" \\"text\\",\n    CONSTRAINT \\"audit_logs_action_type_check\\" CHECK ((\\"action_type\\" = ANY (ARRAY['insert'::\\"text\\", 'update'::\\"text\\", 'delete'::\\"text\\"])))\n)","--\n-- Name: bank_match_memory; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"bank_match_memory\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"description_pattern\\" \\"text\\" NOT NULL,\n    \\"expense_category\\" \\"text\\" NOT NULL,\n    \\"match_count\\" integer DEFAULT 1,\n    \\"confidence_score\\" numeric(5,2) DEFAULT 0,\n    \\"last_matched_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"created_by\\" \\"uuid\\"\n)","--\n-- Name: bank_reconciliation_items; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"bank_reconciliation_items\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"reconciliation_id\\" \\"uuid\\" NOT NULL,\n    \\"transaction_date\\" \\"date\\" NOT NULL,\n    \\"description\\" \\"text\\",\n    \\"reference_number\\" character varying(100),\n    \\"debit\\" numeric(18,2) DEFAULT 0,\n    \\"credit\\" numeric(18,2) DEFAULT 0,\n    \\"journal_entry_id\\" \\"uuid\\",\n    \\"is_matched\\" boolean DEFAULT false,\n    \\"matched_at\\" timestamp with time zone,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"()\n)","--\n-- Name: bank_reconciliations; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"bank_reconciliations\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"bank_account_id\\" \\"uuid\\" NOT NULL,\n    \\"statement_date\\" \\"date\\" NOT NULL,\n    \\"statement_start_date\\" \\"date\\" NOT NULL,\n    \\"statement_end_date\\" \\"date\\" NOT NULL,\n    \\"opening_balance\\" numeric(18,2) NOT NULL,\n    \\"closing_balance\\" numeric(18,2) NOT NULL,\n    \\"book_balance\\" numeric(18,2),\n    \\"difference\\" numeric(18,2),\n    \\"status\\" character varying(20) DEFAULT 'draft'::character varying,\n    \\"reconciled_by\\" \\"uuid\\",\n    \\"reconciled_at\\" timestamp with time zone,\n    \\"notes\\" \\"text\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"bank_reconciliations_status_check\\" CHECK (((\\"status\\")::\\"text\\" = ANY ((ARRAY['draft'::character varying, 'in_progress'::character varying, 'reconciled'::character varying])::\\"text\\"[])))\n)","--\n-- Name: bank_statement_allocations; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"bank_statement_allocations\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"bank_statement_line_id\\" \\"uuid\\" NOT NULL,\n    \\"document_type\\" \\"text\\" NOT NULL,\n    \\"document_id\\" \\"uuid\\" NOT NULL,\n    \\"journal_entry_id\\" \\"uuid\\" NOT NULL,\n    \\"allocation_amount\\" numeric(18,2) NOT NULL,\n    \\"payment_kind\\" \\"text\\" DEFAULT 'supplier'::\\"text\\" NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"created_by\\" \\"uuid\\",\n    CONSTRAINT \\"bank_statement_allocations_allocation_amount_check\\" CHECK ((\\"allocation_amount\\" > (0)::numeric)),\n    CONSTRAINT \\"bank_statement_allocations_document_type_check\\" CHECK ((\\"document_type\\" = ANY (ARRAY['expense'::\\"text\\", 'receipt'::\\"text\\", 'payment'::\\"text\\", 'fund_transfer'::\\"text\\", 'petty_cash'::\\"text\\", 'tax_payment'::\\"text\\", 'journal'::\\"text\\"]))),\n    CONSTRAINT \\"bank_statement_allocations_payment_kind_check\\" CHECK ((\\"payment_kind\\" = ANY (ARRAY['supplier'::\\"text\\", 'pph23'::\\"text\\"])))\n)","--\n-- Name: bank_statement_lines; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"bank_statement_lines\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"upload_id\\" \\"uuid\\" NOT NULL,\n    \\"bank_account_id\\" \\"uuid\\" NOT NULL,\n    \\"transaction_date\\" \\"date\\" NOT NULL,\n    \\"description\\" \\"text\\",\n    \\"reference\\" \\"text\\",\n    \\"branch_code\\" \\"text\\",\n    \\"debit_amount\\" numeric(15,2) DEFAULT 0,\n    \\"credit_amount\\" numeric(15,2) DEFAULT 0,\n    \\"running_balance\\" numeric(15,2),\n    \\"currency\\" \\"text\\" NOT NULL,\n    \\"reconciliation_status\\" \\"text\\" DEFAULT 'unmatched'::\\"text\\",\n    \\"matched_entry_id\\" \\"uuid\\",\n    \\"matched_expense_id\\" \\"uuid\\",\n    \\"matched_receipt_id\\" \\"uuid\\",\n    \\"matched_at\\" timestamp with time zone,\n    \\"matched_by\\" \\"uuid\\",\n    \\"notes\\" \\"text\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"statement_balance\\" numeric(15,2),\n    \\"transaction_hash\\" \\"text\\",\n    \\"matched_petty_cash_id\\" \\"uuid\\",\n    \\"matched_fund_transfer_id\\" \\"uuid\\",\n    \\"paid_by\\" \\"text\\",\n    \\"matching_status\\" \\"text\\" DEFAULT 'none'::\\"text\\",\n    \\"manually_unlinked\\" boolean DEFAULT false,\n    \\"payment_kind\\" \\"text\\" DEFAULT 'supplier'::\\"text\\" NOT NULL,\n    \\"matched_tax_payment_id\\" \\"uuid\\",\n    \\"matched_payment_id\\" \\"uuid\\",\n    CONSTRAINT \\"bank_statement_lines_currency_check\\" CHECK ((\\"currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))),\n    CONSTRAINT \\"bank_statement_lines_matching_status_check\\" CHECK ((\\"matching_status\\" = ANY (ARRAY['none'::\\"text\\", 'suggested'::\\"text\\", 'confirmed'::\\"text\\"]))),\n    CONSTRAINT \\"bank_statement_lines_payment_kind_check\\" CHECK ((\\"payment_kind\\" = ANY (ARRAY['supplier'::\\"text\\", 'pph23'::\\"text\\"]))),\n    CONSTRAINT \\"bank_statement_lines_reconciliation_status_check\\" CHECK ((\\"reconciliation_status\\" = ANY (ARRAY['unmatched'::\\"text\\", 'partially_reconciled'::\\"text\\", 'matched'::\\"text\\", 'needs_review'::\\"text\\", 'recorded'::\\"text\\"])))\n)","--\n-- Name: COLUMN \\"bank_statement_lines\\".\\"matched_petty_cash_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"bank_statement_lines\\".\\"matched_petty_cash_id\\" IS 'Links bank statement line to petty cash transaction for reconciliation'","--\n-- Name: COLUMN \\"bank_statement_lines\\".\\"matching_status\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"bank_statement_lines\\".\\"matching_status\\" IS 'Matching status: none=no match, suggested=auto-suggested (needs confirmation), confirmed=user confirmed match'","--\n-- Name: bank_statement_uploads; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"bank_statement_uploads\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"bank_account_id\\" \\"uuid\\" NOT NULL,\n    \\"upload_date\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"statement_period\\" \\"text\\" NOT NULL,\n    \\"statement_start_date\\" \\"date\\" NOT NULL,\n    \\"statement_end_date\\" \\"date\\" NOT NULL,\n    \\"currency\\" \\"text\\" NOT NULL,\n    \\"opening_balance\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"closing_balance\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"total_credits\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"total_debits\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"transaction_count\\" integer DEFAULT 0 NOT NULL,\n    \\"file_url\\" \\"text\\",\n    \\"uploaded_by\\" \\"uuid\\",\n    \\"status\\" \\"text\\" DEFAULT 'draft'::\\"text\\" NOT NULL,\n    \\"error_message\\" \\"text\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"bank_statement_uploads_currency_check\\" CHECK ((\\"currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))),\n    CONSTRAINT \\"bank_statement_uploads_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['draft'::\\"text\\", 'processing'::\\"text\\", 'completed'::\\"text\\", 'error'::\\"text\\"])))\n)","--\n-- Name: batch_documents; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"batch_documents\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"batch_id\\" \\"uuid\\" NOT NULL,\n    \\"file_url\\" \\"text\\" NOT NULL,\n    \\"file_name\\" \\"text\\" NOT NULL,\n    \\"file_type\\" \\"text\\" NOT NULL,\n    \\"file_size\\" bigint,\n    \\"uploaded_by\\" \\"uuid\\",\n    \\"uploaded_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"batch_documents_file_type_check\\" CHECK ((\\"file_type\\" = ANY (ARRAY['invoice'::\\"text\\", 'bill_of_lading'::\\"text\\", 'coa'::\\"text\\", 'packing_list'::\\"text\\", 'other'::\\"text\\"])))\n)","--\n-- Name: batches; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"batches\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"batch_number\\" \\"text\\" NOT NULL,\n    \\"product_id\\" \\"uuid\\" NOT NULL,\n    \\"import_date\\" \\"date\\" NOT NULL,\n    \\"import_quantity\\" numeric(15,3) NOT NULL,\n    \\"current_stock\\" numeric(15,3) NOT NULL,\n    \\"packaging_details\\" \\"text\\",\n    \\"import_price\\" numeric(15,2) NOT NULL,\n    \\"duty_charges\\" numeric(15,2) DEFAULT 0,\n    \\"freight_charges\\" numeric(15,2) DEFAULT 0,\n    \\"other_charges\\" numeric(15,2) DEFAULT 0,\n    \\"total_cost\\" numeric(15,2) GENERATED ALWAYS AS ((((\\"import_price\\" + \\"duty_charges\\") + \\"freight_charges\\") + \\"other_charges\\")) STORED,\n    \\"cost_per_unit\\" numeric(15,4),\n    \\"expiry_date\\" \\"date\\",\n    \\"warehouse_location\\" \\"text\\",\n    \\"is_active\\" boolean DEFAULT true,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"per_pack_weight\\" numeric(15,3),\n    \\"pack_type\\" \\"text\\",\n    \\"calculated_packs\\" numeric(15,3),\n    \\"cost_per_pack\\" numeric(15,2),\n    \\"import_price_usd\\" numeric(15,2),\n    \\"exchange_rate_usd_to_idr\\" numeric(15,4),\n    \\"duty_charge_type\\" \\"text\\" DEFAULT 'fixed'::\\"text\\",\n    \\"freight_charge_type\\" \\"text\\" DEFAULT 'fixed'::\\"text\\",\n    \\"other_charge_type\\" \\"text\\" DEFAULT 'fixed'::\\"text\\",\n    \\"reserved_stock\\" numeric(15,3) DEFAULT 0,\n    \\"purchase_invoice_id\\" \\"uuid\\",\n    \\"supplier_id\\" \\"uuid\\",\n    \\"import_cost_allocated\\" numeric(18,2) DEFAULT 0,\n    \\"final_landed_cost\\" numeric(18,2),\n    \\"import_container_id\\" \\"uuid\\",\n    \\"cost_locked\\" boolean DEFAULT false,\n    \\"cost_locked_at\\" timestamp with time zone,\n    \\"duty_percent\\" numeric(5,2) DEFAULT 0,\n    \\"landed_cost_per_unit\\" numeric(15,2) DEFAULT 0,\n    \\"import_price_per_unit\\" numeric(15,2),\n    \\"make_id\\" \\"uuid\\",\n    CONSTRAINT \\"batches_duty_charge_type_check\\" CHECK ((\\"duty_charge_type\\" = ANY (ARRAY['percentage'::\\"text\\", 'fixed'::\\"text\\"]))),\n    CONSTRAINT \\"batches_duty_percent_check\\" CHECK (((\\"duty_percent\\" >= (0)::numeric) AND (\\"duty_percent\\" <= (100)::numeric))),\n    CONSTRAINT \\"batches_freight_charge_type_check\\" CHECK ((\\"freight_charge_type\\" = ANY (ARRAY['percentage'::\\"text\\", 'fixed'::\\"text\\"]))),\n    CONSTRAINT \\"batches_other_charge_type_check\\" CHECK ((\\"other_charge_type\\" = ANY (ARRAY['percentage'::\\"text\\", 'fixed'::\\"text\\"]))),\n    CONSTRAINT \\"batches_pack_type_check\\" CHECK ((\\"pack_type\\" = ANY (ARRAY['Bag'::\\"text\\", 'Drum'::\\"text\\", 'Tin'::\\"text\\", 'Carton'::\\"text\\", 'Box'::\\"text\\", 'Container'::\\"text\\", 'Other'::\\"text\\"]))),\n    CONSTRAINT \\"batches_reserved_stock_check\\" CHECK ((\\"reserved_stock\\" >= (0)::numeric))\n)","--\n-- Name: TABLE \\"batches\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON TABLE \\"public\\".\\"batches\\" IS 'Stock can go negative to handle oversold/backorder scenarios. Double deduction fixed by using approval-based flow only.'","--\n-- Name: COLUMN \\"batches\\".\\"import_quantity\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"import_quantity\\" IS 'Total quantity imported in this batch. This is the maximum stock that can ever be available. \nCan be adjusted upward if more stock is imported under the same batch, but cannot be reduced below the quantity already sold.'","--\n-- Name: COLUMN \\"batches\\".\\"current_stock\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"current_stock\\" IS 'Current available stock for this batch. Must be between 0 and import_quantity. \nCalculated as: import_quantity - total_sold_quantity. \nOnly decreases through sales, never increases unless import_quantity is adjusted.'","--\n-- Name: COLUMN \\"batches\\".\\"import_price\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"import_price\\" IS 'Import price in Indonesian Rupiah (IDR)'","--\n-- Name: COLUMN \\"batches\\".\\"calculated_packs\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"calculated_packs\\" IS 'Automatically calculated as import_quantity / per_pack_weight'","--\n-- Name: COLUMN \\"batches\\".\\"cost_per_pack\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"cost_per_pack\\" IS 'Total cost (import + duty + freight + other) / calculated_packs'","--\n-- Name: COLUMN \\"batches\\".\\"import_price_usd\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"import_price_usd\\" IS 'Import price in US Dollars (USD)'","--\n-- Name: COLUMN \\"batches\\".\\"exchange_rate_usd_to_idr\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"exchange_rate_usd_to_idr\\" IS 'Exchange rate from USD to IDR at time of import'","--\n-- Name: COLUMN \\"batches\\".\\"duty_charge_type\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"duty_charge_type\\" IS 'Type of duty charge: percentage (of import price) or fixed (absolute amount in IDR)'","--\n-- Name: COLUMN \\"batches\\".\\"freight_charge_type\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"freight_charge_type\\" IS 'Type of freight charge: percentage (of import price) or fixed (absolute amount in IDR)'","--\n-- Name: COLUMN \\"batches\\".\\"other_charge_type\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"other_charge_type\\" IS 'Type of other charge: percentage (of import price) or fixed (absolute amount in IDR)'","--\n-- Name: COLUMN \\"batches\\".\\"import_cost_allocated\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"import_cost_allocated\\" IS 'Proportional share of container costs allocated to this batch'","--\n-- Name: COLUMN \\"batches\\".\\"final_landed_cost\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"final_landed_cost\\" IS 'Total landed cost in USD = import_price + import_cost_allocated (updated by reallocate_container_costs function)'","--\n-- Name: COLUMN \\"batches\\".\\"duty_percent\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"duty_percent\\" IS 'Import duty % (Form A1) - auto-filled from product, manual override allowed'","--\n-- Name: COLUMN \\"batches\\".\\"landed_cost_per_unit\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"landed_cost_per_unit\\" IS 'Landed cost per unit in USD = (import_price + import_cost_allocated) / import_quantity'","--\n-- Name: COLUMN \\"batches\\".\\"import_price_per_unit\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"import_price_per_unit\\" IS 'Import price per unit (USD per KG) = import_price / import_quantity'","--\n-- Name: COLUMN \\"batches\\".\\"make_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"batches\\".\\"make_id\\" IS 'Optional link to product_sources; NULL means historical make not recorded.'","--\n-- Name: capital_contributions; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"capital_contributions\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"voucher_number\\" character varying(50) NOT NULL,\n    \\"voucher_date\\" \\"date\\" NOT NULL,\n    \\"director_id\\" \\"uuid\\",\n    \\"contribution_type\\" character varying(50) NOT NULL,\n    \\"bank_account_id\\" \\"uuid\\",\n    \\"amount\\" numeric(18,2) NOT NULL,\n    \\"description\\" \\"text\\",\n    \\"document_urls\\" \\"text\\"[],\n    \\"journal_entry_id\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"transaction_currency\\" \\"text\\",\n    \\"functional_currency\\" \\"text\\",\n    \\"exchange_rate\\" numeric,\n    \\"bank_account_currency\\" \\"text\\",\n    \\"bank_statement_line_id\\" \\"uuid\\",\n    C