 DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"price_request_id\\" \\"uuid\\" NOT NULL,\n    \\"event_type\\" \\"text\\" NOT NULL,\n    \\"item_id\\" \\"uuid\\",\n    \\"actor_id\\" \\"uuid\\",\n    \\"actor_name\\" \\"text\\",\n    \\"description\\" \\"text\\" NOT NULL,\n    \\"metadata\\" \\"jsonb\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"communication_timeline_event_type_check\\" CHECK ((\\"event_type\\" = ANY (ARRAY['sourcing_request_sent'::\\"text\\", 'reply_received'::\\"text\\", 'price_updated'::\\"text\\", 'document_pending'::\\"text\\", 'document_received'::\\"text\\", 'reminder_sent'::\\"text\\", 'final_price_entered'::\\"text\\", 'customer_quote_sent'::\\"text\\", 'status_changed'::\\"text\\", 'note_added'::\\"text\\"])))\n)","--\n-- Name: company_profiles; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"company_profiles\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"effective_from\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"company_name\\" \\"text\\" NOT NULL,\n    \\"company_address\\" \\"text\\",\n    \\"company_phone\\" \\"text\\",\n    \\"company_email\\" \\"text\\",\n    \\"company_tax_id\\" \\"text\\",\n    \\"company_logo_url\\" \\"text\\",\n    \\"pbf_license\\" \\"text\\",\n    \\"cdob_certificate\\" \\"text\\",\n    \\"notes\\" \\"text\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"company_legal_name\\" \\"text\\",\n    \\"company_website\\" \\"text\\",\n    \\"company_stamp_url\\" \\"text\\"\n)","--\n-- Name: credit_note_items; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"credit_note_items\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"credit_note_id\\" \\"uuid\\" NOT NULL,\n    \\"product_id\\" \\"uuid\\" NOT NULL,\n    \\"batch_id\\" \\"uuid\\" NOT NULL,\n    \\"quantity\\" numeric(10,3) NOT NULL