erson\\" \\"text\\",\n    \\"contact_email\\" \\"text\\",\n    \\"contact_phone\\" \\"text\\",\n    \\"company_name\\" \\"text\\" NOT NULL,\n    \\"email_subject\\" \\"text\\",\n    \\"email_body\\" \\"text\\",\n    \\"status\\" \\"public\\".\\"inquiry_status\\" DEFAULT 'new'::\\"public\\".\\"inquiry_status\\",\n    \\"priority\\" \\"public\\".\\"inquiry_priority\\" DEFAULT 'medium'::\\"public\\".\\"inquiry_priority\\",\n    \\"next_follow_up\\" timestamp with time zone,\n    \\"last_contact_date\\" timestamp with time zone,\n    \\"quoted_price\\" numeric,\n    \\"quoted_currency\\" \\"text\\" DEFAULT 'IDR'::\\"text\\",\n    \\"target_price\\" numeric,\n    \\"estimated_value\\" numeric,\n    \\"coa_sent\\" boolean DEFAULT false,\n    \\"coa_sent_date\\" \\"date\\",\n    \\"msds_sent\\" boolean DEFAULT false,\n    \\"msds_sent_date\\" \\"date\\",\n    \\"sample_sent\\" boolean DEFAULT false,\n    \\"sample_sent_date\\" \\"date\\",\n    \\"price_quoted\\" boolean DEFAULT false,\n    \\"price_quoted_date\\" \\"date\\",\n    \\"remarks\\" \\"text\\",\n    \\"internal_notes\\" \\"text\\",\n    \\"tags\\" \\"text\\"[],\n    \\"assigned_to\\" \\"uuid\\",\n    \\"source\\" \\"text\\" DEFAULT 'email'::\\"text\\",\n    \\"source_email_id\\" \\"uuid\\",\n    \\"converted_to_quotation\\" \\"uuid\\",\n    \\"converted_to_order\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"closed_at\\" timestamp with time zone,\n    \\"purpose_icons\\" \\"text\\"[] DEFAULT '{}'::\\"text\\"[],\n    \\"delivery_date_expected\\" \\"date\\",\n    \\"ai_confidence_score\\" numeric DEFAULT 0.0,\n    \\"auto_detected_company\\" boolean DEFAULT false,\n    \\"auto_detected_contact\\" boolean DEFAULT false,\n    \\"inquiry_source\\" \\"text\\" DEFAULT 'other'::\\"text\\",\n    \\"specification\\" \\"text\\",\n    \\"customer_id\\" \\"uuid\\",\n    \\"pipeline_status\\" \\"public\\".\\"pipeline_status_enum\\" DEFAULT 'new'::\\"public\\".\\"pipeline_status_enum\\",\n    \\"price_required\\" boolean DEFAULT true,\n    \\"coa_required\\" boolean DEFAULT true,\n    \\"sample_required\\" boolean DEFAULT false,\n    \\"agency_letter_required\\" boolean DEFAULT false,\n    \\"price_sent_at\\" timestamp with time zone,\n    \\"coa_sent_at\\" timestamp with time zone,\n    \\"sample_sent_at\\" timestamp with time zone,\n    \\"agency_letter_sent_at\\" timestamp with time zone,\n    \\"mail_subject\\" \\"text\\",\n    \\"aceerp_no\\" \\"text\\",\n    \\"purchase_price\\" numeric,\n    \\"purchase_price_currency\\" \\"text\\" DEFAULT 'USD'::\\"text\\",\n    \\"offered_price\\" numeric,\n    \\"offered_price_currency\\" \\"text\\" DEFAULT 'USD'::\\"text\\",\n    \\"delivery_date\\" \\"date\\",\n    \\"delivery_terms\\" \\"text\\",\n    \\"lost_reason\\" \\"text\\",\n    \\"lost_at\\" timestamp with time zone,\n    \\"competitor_name\\" \\"text\\",\n    \\"competitor_price\\" numeric,\n    \\"others_required\\" boolean DEFAULT false,\n    \\"others_sent_at\\" timestamp with time zone,\n    \\"is_multi_product\\" boolean DEFAULT false,\n    \\"has_items\\" boolean DEFAULT false,\n    \\"sales_member_id\\" \\"uuid\\",\n    \\"price_ready\\" boolean DEFAULT false NOT NULL,\n    \\"source_status\\" \\"text\\" DEFAULT 'not_sent'::\\"text\\" NOT NULL,\n    \\"document_status\\" \\"text\\" DEFAULT 'not_required'::\\"text\\" NOT NULL,\n    \\"kunal_price_status\\" \\"text\\" DEFAULT 'pending'::\\"text\\" NOT NULL,\n    \\"quote_status\\" \\"text\\" DEFAULT 'not_sent'::\\"text\\" NOT NULL,\n    \\"reminder_count\\" integer DEFAULT 0 NOT NULL,\n    \\"last_sourcing_sent_at\\" timestamp with time zone,\n    \\"last_reminder_sent_at\\" timestamp with time zone,\n    \\"quote_sent_at\\" timestamp with time zone,\n    \\"source_type\\" \\"text\\",\n    \\"kunal_pricing_requested_at\\" timestamp with time zone,\n    \\"kunal_pricing_requested_by\\" \\"uuid\\",\n    \\"kunal_pricing_note\\" \\"text\\",\n    \\"import_data_reference\\" \\"text\\",\n    \\"sent_to_india\\" boolean DEFAULT false NOT NULL,\n    \\"sent_to_india_at\\" timestamp with time zone,\n    \\"sent_to_india_by\\" \\"uuid\\",\n    \\"crm_contact_id\\" \\"uuid\\",\n    CONSTRAINT \\"crm_inquiries_document_status_chk\\" CHECK ((\\"document_status\\" = ANY (ARRAY['not_required'::\\"text\\", 'pending'::\\"text\\", 'partial'::\\"text\\", 'received'::\\"text\\"]))),\n    CONSTRAINT \\"crm_inquiries_inquiry_source_check\\" CHECK ((\\"inquiry_source\\" = ANY (ARRAY['email'::\\"text\\", 'whatsapp'::\\"text\\", 'phone_call'::\\"text\\", 'walk_in'::\\"text\\", 'other'::\\"text\\"]))),\n    CONSTRAINT \\"crm_inquiries_kunal_price_status_chk\\" CHECK ((\\"kunal_price_status\\" = ANY (ARRAY['pending'::\\"text\\", 'entered'::\\"text\\"]))),\n    CONSTRAINT \\"crm_inquiries_quote_status_chk\\" CHECK ((\\"quote_status\\" = ANY (ARRAY['not_sent'::\\"text\\", 'sent'::\\"text\\", 'follow_up_due'::\\"text\\", 'won'::\\"text\\", 'lost'::\\"text\\"]))),\n    CONSTRAINT \\"crm_inquiries_source_status_chk\\" CHECK ((\\"source_status\\" = ANY (ARRAY['not_sent'::\\"text\\", 'sent'::\\"text\\", 'waiting_reply'::\\"text\\", 'partial_received'::\\"text\\", 'received'::\\"text\\", 'unavailable'::\\"text\\"])))\n)","--\n-- Name: COLUMN \\"crm_inquiries\\".\\"customer_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"crm_inquiries\\".\\"customer_id\\" IS 'FK to customers (ERP master). Only set when the CRM prospect has been promoted to an ERP trading customer. May be NULL for pure prospects.'","--\n-- Name: COLUMN \\"crm_inquiries\\".\\"crm_contact_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"crm_inquiries\\".\\"crm_contact_id\\" IS 'FK to crm_contacts — the CRM prospect this inquiry is about. Populated by the CRM Add/Select Customer flow. Independent of customer_id.'","--\n-- Name: crm_inquiry_items; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_inquiry_items\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"parent_inquiry_id\\" \\"uuid\\" NOT NULL,\n    \\"inquiry_number\\" \\"text\\" NOT NULL,\n    \\"product_name\\" \\"text\\" NOT NULL,\n    \\"specification\\" \\"text\\",\n    \\"quantity\\" \\"text\\",\n    \\"target_price\\" \\"text\\",\n    \\"status\\" \\"text\\" DEFAULT 'open'::\\"text\\",\n    \\"pipeline_stage\\" \\"text\\" DEFAULT 'new'::\\"text\\",\n    \\"document_sent\\" boolean DEFAULT false,\n    \\"document_sent_at\\" timestamp with time zone,\n    \\"notes\\" \\"text\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"supplier_name\\" \\"text\\",\n    \\"supplier_country\\" \\"text\\",\n    \\"delivery_date\\" \\"date\\",\n    \\"delivery_terms\\" \\"text\\",\n    \\"aceerp_no\\" \\"text\\",\n    \\"purchase_price\\" numeric(15,2),\n    \\"purchase_price_currency\\" \\"text\\" DEFAULT 'USD'::\\"text\\",\n    \\"offered_price\\" numeric(15,2),\n    \\"offered_price_currency\\" \\"text\\" DEFAULT 'USD'::\\"text\\",\n    \\"our_side_status\\" \\"text\\"[] DEFAULT '{}'::\\"text\\"[],\n    \\"price_sent_at\\" timestamp with time zone,\n    \\"coa_sent_at\\" timestamp with time zone,\n    \\"sample_sent_at\\" timestamp with time zone,\n    \\"agency_letter_sent_at\\" timestamp with time zone,\n    \\"remarks\\" \\"text\\",\n    \\"make\\" \\"text\\"\n)","--\n-- Name: crm_inquiry_pricing_options; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_inquiry_pricing_options\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"inquiry_id\\" \\"uuid\\" NOT NULL,\n    \\"source_type\\" \\"text\\" DEFAULT 'india'::\\"text\\" NOT NULL,\n    \\"offered_make\\" \\"text\\",\n    \\"source_price\\" numeric,\n    \\"source_currency\\" \\"text\\" DEFAULT 'USD'::\\"text\\" NOT NULL,\n    \\"availability\\" \\"text\\" DEFAULT 'available'::\\"text\\" NOT NULL,\n    \\"document_status\\" \\"text\\" DEFAULT 'pending'::\\"text\\" NOT NULL,\n    \\"remark\\" \\"text\\",\n    \\"is_selected\\" boolean DEFAULT false NOT NULL,\n    \\"confidence\\" numeric,\n    \\"parser_result_id\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"moq\\" \\"text\\",\n    \\"packing\\" \\"text\\",\n    \\"lead_time\\" \\"text\\",\n    \\"origin\\" \\"text\\",\n    \\"supplier\\" \\"text\\",\n    \\"specification\\" \\"text\\",\n    \\"margin_pct\\" numeric,\n    \\"selling_price\\" numeric,\n    \\"selling_currency\\" \\"text\\"\n)","--\n-- Name: crm_inquiry_timeline; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_inquiry_timeline\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"inquiry_id\\" \\"uuid\\" NOT NULL,\n    \\"event_type\\" \\"text\\" NOT NULL,\n    \\"event_title\\" \\"text\\" NOT NULL,\n    \\"event_description\\" \\"text\\",\n    \\"old_value\\" \\"text\\",\n    \\"new_value\\" \\"text\\",\n    \\"related_action_id\\" \\"uuid\\",\n    \\"related_activity_id\\" \\"uuid\\",\n    \\"related_email_id\\" \\"uuid\\",\n    \\"performed_by\\" \\"uuid\\",\n    \\"event_timestamp\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"crm_inquiry_timeline_event_type_check\\" CHECK ((\\"event_type\\" = ANY (ARRAY['created'::\\"text\\", 'status_changed'::\\"text\\", 'email_sent'::\\"text\\", 'email_received'::\\"text\\", 'action_performed'::\\"text\\", 'activity_logged'::\\"text\\", 'document_sent'::\\"text\\", 'follow_up_created'::\\"text\\", 'follow_up_completed'::\\"text\\", 'assigned'::\\"text\\", 'note_added'::\\"text\\"])))\n)","--\n-- Name: crm_leads; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_leads\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"company_name\\" \\"text\\" NOT NULL,\n    \\"contact_person\\" \\"text\\" NOT NULL,\n    \\"email\\" \\"text\\",\n    \\"phone\\" \\"text\\",\n    \\"product_interest\\" \\"text\\",\n    \\"quantity_interest\\" \\"text\\",\n    \\"lead_source\\" \\"text\\",\n    \\"status\\" \\"text\\" DEFAULT 'inquiry'::\\"text\\" NOT NULL,\n    \\"assigned_to\\" \\"uuid\\",\n    \\"expected_close_date\\" \\"date\\",\n    \\"estimated_value\\" numeric(15,2),\n    \\"notes\\" \\"text\\",\n    \\"converted_to_customer\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"priority\\" \\"text\\" DEFAULT 'medium'::\\"text\\",\n    \\"next_follow_up\\" timestamp with time zone,\n    \\"lead_score\\" integer DEFAULT 50,\n    \\"tags\\" \\"text\\"[],\n    \\"deal_value\\" numeric DEFAULT 0,\n    CONSTRAINT \\"crm_leads_lead_score_check\\" CHECK (((\\"lead_score\\" >= 0) AND (\\"lead_score\\" <= 100))),\n    CONSTRAINT \\"crm_leads_lead_source_check\\" CHECK ((\\"lead_source\\" = ANY (ARRAY['website'::\\"text\\", 'referral'::\\"text\\", 'trade_show'::\\"text\\", 'cold_call'::\\"text\\", 'email'::\\"text\\", 'other'::\\"text\\"]))),\n    CONSTRAINT \\"crm_leads_priority_check\\" CHECK ((\\"priority\\" = ANY (ARRAY['low'::\\"text\\", 'medium'::\\"text\\", 'high'::\\"text\\", 'urgent'::\\"text\\"]))),\n    CONSTRAINT \\"crm_leads_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['inquiry'::\\"text\\", 'quotation'::\\"text\\", 'negotiation'::\\"text\\", 'won'::\\"text\\", 'lost'::\\"text\\"])))\n)","--\n-- Name: crm_pipeline_stages; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_pipeline_stages\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"stage_name\\" \\"text\\" NOT NULL,\n    \\"stage_order\\" integer NOT NULL,\n    \\"color\\" \\"text\\" DEFAULT '#3B82F6'::\\"text\\",\n    \\"is_active\\" boolean DEFAULT true,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"()\n)","--\n-- Name: crm_product_documents; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_product_documents\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"inquiry_id\\" \\"uuid\\",\n    \\"product_name\\" \\"text\\",\n    \\"make\\" \\"text\\",\n    \\"document_type\\" \\"text\\",\n    \\"original_file_name\\" \\"text\\",\n    \\"display_file_name\\" \\"text\\",\n    \\"storage_bucket\\" \\"text\\" DEFAULT 'crm-documents'::\\"text\\",\n    \\"storage_path\\" \\"text\\" NOT NULL,\n    \\"source_gmail_message_id\\" \\"text\\",\n    \\"source_gmail_thread_id\\" \\"text\\",\n    \\"source_email_subject\\" \\"text\\",\n    \\"uploaded_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"crm_product_documents_document_type_check\\" CHECK ((\\"document_type\\" = ANY (ARRAY['COA'::\\"text\\", 'MSDS'::\\"text\\", 'MHD'::\\"text\\", 'TDS'::\\"text\\", 'SPEC'::\\"text\\", 'COC'::\\"text\\", 'GMP'::\\"text\\", 'ISO'::\\"text\\", 'DMF'::\\"text\\", 'OTHER'::\\"text\\"])))\n)","--\n-- Name: crm_quick_actions_log; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_quick_actions_log\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"inquiry_id\\" \\"uuid\\" NOT NULL,\n    \\"contact_id\\" \\"uuid\\",\n    \\"action_type\\" \\"text\\" NOT NULL,\n    \\"action_label\\" \\"text\\" NOT NULL,\n    \\"email_sent\\" boolean DEFAULT false,\n    \\"email_to\\" \\"text\\",\n    \\"email_subject\\" \\"text\\",\n    \\"email_body\\" \\"text\\",\n    \\"template_used\\" \\"uuid\\",\n    \\"documents_attached\\" \\"text\\"[],\n    \\"old_status\\" \\"text\\",\n    \\"new_status\\" \\"text\\",\n    \\"status_updated\\" boolean DEFAULT false,\n    \\"follow_up_created\\" boolean DEFAULT false,\n    \\"follow_up_date\\" timestamp with time zone,\n    \\"follow_up_reminder_id\\" \\"uuid\\",\n    \\"call_outcome\\" \\"text\\",\n    \\"meeting_outcome\\" \\"text\\",\n    \\"notes\\" \\"text\\",\n    \\"performed_by\\" \\"uuid\\" NOT NULL,\n    \\"performed_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"duration_seconds\\" integer,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"crm_quick_actions_log_action_type_check\\" CHECK ((\\"action_type\\" = ANY (ARRAY['send_price'::\\"text\\", 'send_coa'::\\"text\\", 'send_msds'::\\"text\\", 'send_sample'::\\"text\\", 'follow_up'::\\"text\\", 'send_agency_letter'::\\"text\\", 'send_delivery_update'::\\"text\\", 'log_call'::\\"text\\", 'log_meeting'::\\"text\\", 'log_whatsapp'::\\"text\\", 'add_note'::\\"text\\"])))\n)","--\n-- Name: crm_quotation_items; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_quotation_items\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"quotation_id\\" \\"uuid\\" NOT NULL,\n    \\"product_id\\" \\"uuid\\",\n    \\"product_name\\" \\"text\\" NOT NULL,\n    \\"quantity\\" numeric NOT NULL,\n    \\"unit_price\\" numeric NOT NULL,\n    \\"tax_rate\\" numeric DEFAULT 0,\n    \\"discount_percent\\" numeric DEFAULT 0,\n    \\"line_total\\" numeric GENERATED ALWAYS AS ((((\\"quantity\\" * \\"unit_price\\") * ((1)::numeric - (\\"discount_percent\\" / (100)::numeric))) * ((1)::numeric + (\\"tax_rate\\" / (100)::numeric)))) STORED,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"crm_quotation_items_discount_percent_check\\" CHECK (((\\"discount_percent\\" >= (0)::numeric) AND (\\"discount_percent\\" <= (100)::numeric))),\n    CONSTRAINT \\"crm_quotation_items_quantity_check\\" CHECK ((\\"quantity\\" > (0)::numeric)),\n    CONSTRAINT \\"crm_quotation_items_tax_rate_check\\" CHECK ((\\"tax_rate\\" >= (0)::numeric)),\n    CONSTRAINT \\"crm_quotation_items_unit_price_check\\" CHECK ((\\"unit_price\\" >= (0)::numeric))\n)","--\n-- Name: crm_quotations; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_quotations\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"quotation_number\\" \\"text\\" NOT NULL,\n    \\"lead_id\\" \\"uuid\\",\n    \\"customer_id\\" \\"uuid\\",\n    \\"quotation_date\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"valid_until\\" \\"date\\" NOT NULL,\n    \\"subtotal\\" numeric DEFAULT 0 NOT NULL,\n    \\"tax_amount\\" numeric DEFAULT 0 NOT NULL,\n    \\"discount_amount\\" numeric DEFAULT 0,\n    \\"total_amount\\" numeric DEFAULT 0 NOT NULL,\n    \\"status\\" \\"text\\" DEFAULT 'draft'::\\"text\\" NOT NULL,\n    \\"notes\\" \\"text\\",\n    \\"terms_conditions\\" \\"text\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"at_least_one_entity\\" CHECK (((\\"lead_id\\" IS NOT NULL) OR (\\"customer_id\\" IS NOT NULL))),\n    CONSTRAINT \\"crm_quotations_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['draft'::\\"text\\", 'sent'::\\"text\\", 'accepted'::\\"text\\", 'rejected'::\\"text\\", 'expired'::\\"text\\"])))\n)","--\n-- Name: crm_reminders; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"crm_reminders\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"inquiry_id\\" \\"uuid\\",\n    \\"reminder_type\\" \\"text\\" NOT NULL,\n    \\"title\\" \\"text\\" NOT NULL,\n    \\"description\\" \\"text\\",\n    \\"due_date\\" timestamp with time zone NOT NULL,\n    \\"reminder_date\\" timestamp with time zone,\n    \\"is_completed\\" boolean DEFAULT false,\n    \\"completed_at\\" timestamp with time zone,\n    \\"completed_by\\" \\"uuid\\",\n    \\"assigned_to\\" \\"uuid\\" NOT NULL,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"crm_reminders_reminder_type_check\\" CHECK ((\\"reminder_type\\" = ANY (ARRAY['follow_up'::\\"text\\", 'send_coa'::\\"text\\", 'send_sample'::\\"text\\", 'send_price'::\\"text\\", 'custom'::\\"text\\"])))\n)","--\n-- Name: customers; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"customers\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"company_name\\" \\"text\\" NOT NULL,\n    \\"npwp\\" \\"text\\",\n    \\"address\\" \\"text\\",\n    \\"city\\" \\"text\\",\n    \\"country\\" \\"text\\" DEFAULT 'Indonesia'::\\"text\\",\n    \\"contact_person\\" \\"text\\",\n    \\"email\\" \\"text\\",\n    \\"phone\\" \\"text\\",\n    \\"gst_vat_type\\" \\"text\\",\n    \\"payment_terms\\" \\"text\\",\n    \\"is_active\\" boolean DEFAULT true,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"pharmacy_license\\" \\"text\\",\n    \\"pbf_license\\" \\"text\\",\n    \\"pkp_status\\" boolean DEFAULT false\n)","--\n-- Name: COLUMN \\"customers\\".\\"company_name\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"customers\\".\\"company_name\\" IS 'Primary company/customer name identifier'","--\n-- Name: sales_orders; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"sales_orders\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"so_number\\" \\"text\\" NOT NULL,\n    \\"customer_id\\" \\"uuid\\" NOT NULL,\n    \\"customer_po_number\\" \\"text\\" NOT NULL,\n    \\"customer_po_date\\" \\"date\\" NOT NULL,\n    \\"customer_po_file_url\\" \\"text\\",\n    \\"so_date\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"expected_delivery_date\\" \\"date\\",\n    \\"notes\\" \\"text\\",\n    \\"status\\" \\"public\\".\\"sales_order_status\\" DEFAULT 'draft'::\\"public\\".\\"sales_order_status\\" NOT NULL,\n    \\"subtotal_amount\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"tax_amount\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"total_amount\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"created_by\\" \\"uuid\\" NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"approved_by\\" \\"uuid\\",\n    \\"approved_at\\" timestamp with time zone,\n    \\"rejected_by\\" \\"uuid\\",\n    \\"rejected_at\\" timestamp with time zone,\n    \\"rejection_reason\\" \\"text\\",\n    \\"is_archived\\" boolean DEFAULT false,\n    \\"archived_at\\" timestamp with time zone,\n    \\"archived_by\\" \\"uuid\\",\n    \\"archive_reason\\" \\"text\\",\n    \\"currency\\" \\"text\\" DEFAULT 'IDR'::\\"text\\",\n    \\"advance_payment_amount\\" numeric(18,2) DEFAULT 0,\n    \\"advance_payment_status\\" character varying(20) DEFAULT 'none'::character varying,\n    \\"company_snapshot\\" \\"jsonb\\",\n    \\"commercial_usd_to_idr_rate\\" numeric(18,6),\n    \\"inquiry_id\\" \\"uuid\\",\n    CONSTRAINT \\"sales_orders_advance_payment_status_check\\" CHECK (((\\"advance_payment_status\\")::\\"text\\" = ANY ((ARRAY['none'::character varying, 'partial'::character varying, 'full'::character varying])::\\"text\\"[]))),\n    CONSTRAINT \\"sales_orders_commercial_usd_to_idr_rate_check\\" CHECK (((\\"commercial_usd_to_idr_rate\\" IS NULL) OR (\\"commercial_usd_to_idr_rate\\" > (0)::numeric))),\n    CONSTRAINT \\"sales_orders_currency_check\\" CHECK ((\\"currency\\" = ANY (ARRAY['USD'::\\"text\\", 'IDR'::\\"text\\"]))),\n    CONSTRAINT \\"valid_amounts\\" CHECK (((\\"subtotal_amount\\" >= (0)::numeric) AND (\\"tax_amount\\" >= (0)::numeric) AND (\\"total_amount\\" >= (0)::numeric))),\n    CONSTRAINT \\"valid_customer_po_number\\" CHECK ((\\"length\\"(TRIM(BOTH FROM \\"customer_po_number\\")) > 0))\n)","--\n-- Name: COLUMN \\"sales_orders\\".\\"currency\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"sales_orders\\".\\"currency\\" IS 'Currency for the sales order: USD or IDR'","--\n-- Name: COLUMN \\"sales_orders\\".\\"commercial_usd_to_idr_rate\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"sales_orders\\".\\"commercial_usd_to_idr_rate\\" IS 'Historical USD to IDR rate used for this order commercial agreement; never recalculated.'","--\n-- Name: COLUMN \\"sales_orders\\".\\"inquiry_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"sales_orders\\".\\"inquiry_id\\" IS 'Optional CRM source inquiry; populated only for an explicit future CRM-to-SO creation.'","--\n-- Name: voucher_allocations; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"voucher_allocations\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"voucher_type\\" character varying(20) NOT NULL,\n    \\"receipt_voucher_id\\" \\"uuid\\",\n    \\"payment_voucher_id\\" \\"uuid\\",\n    \\"sales_invoice_id\\" \\"uuid\\",\n    \\"purchase_invoice_id\\" \\"uuid\\",\n    \\"allocated_amount\\" numeric(18,2) NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"sales_order_id\\" \\"uuid\\",\n    \\"allocated_currency\\" character varying(8) DEFAULT 'IDR'::character varying,\n    \\"finance_expense_id\\" \\"uuid\\",\n    \\"payment_kind\\" \\"text\\" DEFAULT 'supplier'::\\"text\\" NOT NULL,\n    CONSTRAINT \\"voucher_allocations_check\\" CHECK (((((\\"voucher_type\\")::\\"text\\" = 'receipt'::\\"text\\") AND (\\"receipt_voucher_id\\" IS NOT NULL) AND (\\"sales_invoice_id\\" IS NOT NULL)) OR (((\\"voucher_type\\")::\\"text\\" = 'payment'::\\"text\\") AND (\\"payment_voucher_id\\" IS NOT NULL) AND (\\"purchase_invoice_id\\" IS NOT NULL)) OR (((\\"voucher_type\\")::\\"text\\" = 'payment'::\\"text\\") AND (\\"payment_voucher_id\\" IS NOT NULL) AND (\\"finance_expense_id\\" IS NOT NULL)))),\n    CONSTRAINT \\"voucher_allocations_payment_kind_check\\" CHECK ((\\"payment_kind\\" = ANY (ARRAY['supplier'::\\"text\\", 'pph23'::\\"text\\"]))),\n    CONSTRAINT \\"voucher_allocations_voucher_type_check\\" CHECK (((\\"voucher_type\\")::\\"text\\" = ANY ((ARRAY['receipt'::character varying, 'payment'::character varying])::\\"text\\"[])))\n)","--\n-- Name: customer_advance_balances; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"customer_advance_balances\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"c\\".\\"id\\" AS \\"customer_id\\",\n    \\"c\\".\\"company_name\\",\n    COALESCE(\\"sum\\"(\\"va\\".\\"allocated_amount\\"), (0)::numeric) AS \\"total_advances\\",\n    \\"count\\"(DISTINCT \\"va\\".\\"sales_order_id\\") AS \\"orders_with_advance\\"\n   FROM ((\\"public\\".\\"customers\\" \\"c\\"\n     LEFT JOIN \\"public\\".\\"sales_orders\\" \\"so\\" ON ((\\"so\\".\\"customer_id\\" = \\"c\\".\\"id\\")))\n     LEFT JOIN \\"public\\".\\"voucher_allocations\\" \\"va\\" ON (((\\"va\\".\\"sales_order_id\\" = \\"so\\".\\"id\\") AND ((\\"va\\".\\"voucher_type\\")::\\"text\\" = 'receipt'::\\"text\\"))))\n  WHERE (\\"va\\".\\"sales_order_id\\" IS NOT NULL)\n  GROUP BY \\"c\\".\\"id\\", \\"c\\".\\"company_name\\"","--\n-- Name: VIEW \\"customer_advance_balances\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON VIEW \\"public\\".\\"customer_advance_balances\\" IS 'Security: Converted to SECURITY INVOKER - executes with caller permissions'","--\n-- Name: customer_assignments; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"customer_assignments\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"customer_id\\" \\"uuid\\" NOT NULL,\n    \\"sales_member_id\\" \\"uuid\\" NOT NULL,\n    \\"assigned_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"assigned_by\\" \\"uuid\\",\n    \\"notes\\" \\"text\\",\n    \\"is_active\\" boolean DEFAULT true,\n    \\"crm_contact_id\\" \\"uuid\\"\n)","--\n-- Name: customer_documents; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"customer_documents\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"customer_id\\" \\"uuid\\" NOT NULL,\n    \\"file_url\\" \\"text\\" NOT NULL,\n    \\"file_name\\" \\"text\\" NOT NULL,\n    \\"file_type\\" \\"text\\" DEFAULT 'other'::\\"text\\",\n    \\"file_size\\" bigint,\n    \\"uploaded_by\\" \\"uuid\\",\n    \\"uploaded_at\\" timestamp with time zone DEFAULT \\"now\\"()\n)","--\n-- Name: customer_payments; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"customer_payments\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"payment_number\\" \\"text\\" NOT NULL,\n    \\"customer_id\\" \\"uuid\\" NOT NULL,\n    \\"invoice_id\\" \\"uuid\\",\n    \\"payment_date\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"amount\\" numeric NOT NULL,\n    \\"payment_method\\" \\"text\\" NOT NULL,\n    \\"bank_account_id\\" \\"uuid\\",\n    \\"reference_number\\" \\"text\\",\n    \\"notes\\" \\"text\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    CONSTRAINT \\"customer_payments_amount_check\\" CHECK ((\\"amount\\" > (0)::numeric)),\n    CONSTRAINT \\"customer_payments_payment_method_check\\" CHECK ((\\"payment_method\\" = ANY (ARRAY['cash'::\\"text\\", 'bank_transfer'::\\"text\\", 'cheque'::\\"text\\", 'credit_card'::\\"text\\", 'other'::\\"text\\"])))\n)","--\n-- Name: TABLE \\"customer_payments\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON TABLE \\"public\\".\\"customer_payments\\" IS 'Payments received from customers against sales invoices'","--\n-- Name: customer_receivables_view; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"customer_receivables_view\\" AS\n SELECT \\"c\\".\\"id\\" AS \\"customer_id\\",\n    \\"c\\".\\"company_name\\",\n    COALESCE(\\"sum\\"(\n        CASE\n            WHEN ((\\"coa\\".\\"code\\")::\\"text\\" = '1120'::\\"text\\") THEN (\\"jel\\".\\"debit\\" - \\"jel\\".\\"credit\\")\n            ELSE (0)::numeric\n        END), (0)::numeric) AS \\"receivable_balance\\"\n   FROM (((\\"public\\".\\"customers\\" \\"c\\"\n     LEFT JOIN \\"public\\".\\"journal_entry_lines\\" \\"jel\\" ON ((\\"jel\\".\\"customer_id\\" = \\"c\\".\\"id\\")))\n     LEFT JOIN \\"public\\".\\"chart_of_accounts\\" \\"coa\\" ON ((\\"coa\\".\\"id\\" = \\"jel\\".\\"account_id\\")))\n     LEFT JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((\\"je\\".\\"id\\" = \\"jel\\".\\"journal_entry_id\\")))\n  WHERE (COALESCE(\\"je\\".\\"is_posted\\", false) AND (NOT COALESCE(\\"je\\".\\"is_reversed\\", false)))\n  GROUP BY \\"c\\".\\"id\\", \\"c\\".\\"company_name\\"\n HAVING (COALESCE(\\"sum\\"(\n        CASE\n            WHEN ((\\"coa\\".\\"code\\")::\\"text\\" = '1120'::\\"text\\") THEN (\\"jel\\".\\"debit\\" - \\"jel\\".\\"credit\\")\n            ELSE (0)::numeric\n        END), (0)::numeric) <> (0)::numeric)","--\n-- Name: VIEW \\"customer_receivables_view\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON VIEW \\"public\\".\\"customer_receivables_view\\" IS 'Security: Converted to SECURITY INVOKER - executes with caller permissions'","--\n-- Name: dc_batch_allocations; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"dc_batch_allocations\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"delivery_challan_id\\" \\"uuid\\" NOT NULL,\n    \\"delivery_challan_item_id\\" \\"uuid\\" NOT NULL,\n    \\"sales_order_item_id\\" \\"uuid\\" NOT NULL,\n    \\"reservation_id\\" \\"uuid\\" NOT NULL,\n    \\"product_id\\" \\"uuid\\" NOT NULL,\n    \\"batch_id\\" \\"uuid\\" NOT NULL,\n    \\"allocated_quantity\\" numeric NOT NULL,\n    \\"status\\" \\"text\\" DEFAULT 'consumed'::\\"text\\" NOT NULL,\n    \\"operation_id\\" \\"uuid\\" NOT NULL,\n    \\"inventory_transaction_id\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"created_by\\" \\"uuid\\",\n    \\"reversed_at\\" timestamp with time zone,\n    \\"reversal_reason\\" \\"text\\",\n    CONSTRAINT \\"dc_batch_allocations_allocated_quantity_check\\" CHECK ((\\"allocated_quantity\\" > (0)::numeric)),\n    CONSTRAINT \\"dc_batch_allocations_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['consumed'::\\"text\\", 'reversed'::\\"text\\"])))\n)","--\n-- Name: delivery_challan_items; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"delivery_challan_items\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"challan_id\\" \\"uuid\\" NOT NULL,\n    \\"product_id\\" \\"uuid\\" NOT NULL,\n    \\"batch_id\\" \\"uuid\\" NOT NULL,\n    \\"quantity\\" numeric NOT NULL,\n    \\"pack_size\\" numeric,\n    \\"pack_type\\" \\"text\\",\n    \\"number_of_packs\\" integer,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"sales_order_item_id\\" \\"uuid\\",\n    CONSTRAINT \\"delivery_challan_items_quantity_check\\" CHECK ((\\"quantity\\" > (0)::numeric))\n)","--\n-- Name: COLUMN \\"delivery_challan_items\\".\\"sales_order_item_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"delivery_challan_items\\".\\"sales_order_item_id\\" IS 'Authoritative Sales Order source item for SO-created Delivery Challans; null only for retained legacy unlinked rows.'","--\n-- Name: delivery_challans; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"delivery_challans\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"challan_number\\" \\"text\\" NOT NULL,\n    \\"customer_id\\" \\"uuid\\" NOT NULL,\n    \\"challan_date\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"delivery_address\\" \\"text\\" NOT NULL,\n    \\"vehicle_number\\" \\"text\\",\n    \\"driver_name\\" \\"text\\",\n    \\"notes\\" \\"text\\",\n    \\"created_by\\" \\"uuid\\" NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"sales_order_id\\" \\"uuid\\",\n    \\"approval_status\\" \\"public\\".\\"dc_approval_status\\" DEFAULT 'pending_approval'::\\"public\\".\\"dc_approval_status\\" NOT NULL,\n    \\"approved_by\\" \\"uuid\\",\n    \\"approved_at\\" timestamp with time zone,\n    \\"rejection_reason\\" \\"text\\",\n    \\"rejected_by\\" \\"uuid\\",\n    \\"rejected_at\\" timestamp with time zone,\n    \\"review_status\\" \\"text\\",\n    \\"approval_operation_id\\" \\"uuid\\",\n    \\"company_snapshot\\" \\"jsonb\\"\n)","--\n-- Name: COLUMN \\"delivery_challans\\".\\"rejection_reason\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"delivery_challans\\".\\"rejection_reason\\" IS 'Reason provided for rejecting the challan'","--\n-- Name: COLUMN \\"delivery_challans\\".\\"rejected_by\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"delivery_challans\\".\\"rejected_by\\" IS 'User who rejected the delivery challan'","--\n-- Name: COLUMN \\"delivery_challans\\".\\"rejected_at\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"delivery_challans\\".\\"rejected_at\\" IS 'Timestamp when the challan was rejected'","--\n-- Name: sales_invoice_items; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"sales_invoice_items\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"invoice_id\\" \\"uuid\\" NOT NULL,\n    \\"product_id\\" \\"uuid\\" NOT NULL,\n    \\"batch_id\\" \\"uuid\\",\n    \\"quantity\\" numeric(15,3) NOT NULL,\n    \\"unit_price\\" numeric(15,2) NOT NULL,\n    \\"tax_rate\\" numeric(5,2) DEFAULT 0,\n    \\"tax_amount\\" numeric(15,2) GENERATED ALWAYS AS ((((\\"quantity\\" * \\"unit_price\\") * \\"tax_rate\\") / (100)::numeric)) STORED,\n    \\"line_total\\" numeric(15,2) GENERATED ALWAYS AS (((\\"quantity\\" * \\"unit_price\\") + (((\\"quantity\\" * \\"unit_price\\") * \\"tax_rate\\") / (100)::numeric))) STORED,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"delivery_challan_item_id\\" \\"uuid\\" NOT NULL\n)","--\n-- Name: COLUMN \\"sales_invoice_items\\".\\"delivery_challan_item_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"sales_invoice_items\\".\\"delivery_challan_item_id\\" IS 'Links to source delivery challan item. NULL = manual item (deduct stock), NOT NULL = from DC (stock already deducted)'","--\n-- Name: sales_invoices; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"sales_invoices\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"invoice_number\\" \\"text\\" NOT NULL,\n    \\"customer_id\\" \\"uuid\\" NOT NULL,\n    \\"invoice_date\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"due_date\\" \\"date\\",\n    \\"subtotal\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"tax_amount\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"discount_amount\\" numeric(15,2) DEFAULT 0,\n    \\"total_amount\\" numeric(15,2) DEFAULT 0 NOT NULL,\n    \\"payment_status\\" \\"text\\" DEFAULT 'pending'::\\"text\\" NOT NULL,\n    \\"delivery_challan_number\\" \\"text\\",\n    \\"notes\\" \\"text\\",\n    \\"is_draft\\" boolean DEFAULT false,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"po_number\\" \\"text\\",\n    \\"payment_terms_days\\" integer DEFAULT 30,\n    \\"linked_challan_ids\\" \\"text\\"[],\n    \\"customer_po_file_url\\" \\"text\\",\n    \\"journal_entry_id\\" \\"uuid\\",\n    \\"faktur_pajak_number\\" character varying(50),\n    \\"paid_amount\\" numeric(18,2) DEFAULT 0,\n    \\"balance_amount\\" numeric(18,2) DEFAULT 0,\n    \\"sales_order_id\\" \\"uuid\\",\n    \\"stamp_duty_amount\\" numeric(18,2) DEFAULT 0,\n    \\"tax_period_id\\" \\"uuid\\",\n    \\"company_snapshot\\" \\"jsonb\\",\n    CONSTRAINT \\"sales_invoices_balance_nonnegative\\" CHECK ((COALESCE(\\"balance_amount\\", (0)::numeric) >= '-0.01'::numeric)),\n    CONSTRAINT \\"sales_invoices_paid_not_over_total\\" CHECK ((COALESCE(\\"paid_amount\\", (0)::numeric) <= (COALESCE(\\"total_amount\\", (0)::numeric) + 0.01))),\n    CONSTRAINT \\"sales_invoices_payment_status_check\\" CHECK ((\\"payment_status\\" = ANY (ARRAY['pending'::\\"text\\", 'partial'::\\"text\\", 'paid'::\\"text\\"])))\n)","--\n-- Name: COLUMN \\"sales_invoices\\".\\"paid_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"sales_invoices\\".\\"paid_amount\\" IS 'Total amount paid towards this invoice from all payment sources'","--\n-- Name: COLUMN \\"sales_invoices\\".\\"balance_amount\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"sales_invoices\\".\\"balance_amount\\" IS 'Remaining balance (computed as total_amount - paid_amount)'","--\n-- Name: dc_invoicing_summary; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"dc_invoicing_summary\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"dc\\".\\"id\\" AS \\"challan_id\\",\n    \\"dc\\".\\"challan_number\\",\n    \\"dc\\".\\"customer_id\\",\n    \\"dc\\".\\"challan_date\\",\n    \\"dc\\".\\"approval_status\\",\n    \\"count\\"(DISTINCT \\"dci\\".\\"id\\") AS \\"total_items\\",\n    \\"count\\"(DISTINCT\n        CASE\n            WHEN (\\"sii\\".\\"id\\" IS NULL) THEN \\"dci\\".\\"id\\"\n            ELSE NULL::\\"uuid\\"\n        END) AS \\"not_invoiced_items\\",\n    \\"count\\"(DISTINCT\n        CASE\n            WHEN (\\"sii\\".\\"id\\" IS NOT NULL) THEN \\"dci\\".\\"id\\"\n            ELSE NULL::\\"uuid\\"\n        END) AS \\"invoiced_items\\",\n    COALESCE(\\"sum\\"(\\"dci\\".\\"quantity\\"), (0)::numeric) AS \\"total_quantity\\",\n    COALESCE(\\"sum\\"(\n        CASE\n            WHEN (\\"sii\\".\\"id\\" IS NULL) THEN \\"dci\\".\\"quantity\\"\n            ELSE (0)::numeric\n        END), (0)::numeric) AS \\"total_remaining_quantity\\",\n        CASE\n            WHEN (\\"count\\"(DISTINCT \\"sii\\".\\"id\\") = 0) THEN 'not_invoiced'::\\"text\\"\n            WHEN (\\"count\\"(DISTINCT \\"sii\\".\\"id\\") < \\"count\\"(DISTINCT \\"dci\\".\\"id\\")) THEN 'partially_invoiced'::\\"text\\"\n            ELSE 'fully_invoiced'::\\"text\\"\n        END AS \\"dc_status\\",\n    COALESCE(\\"array_agg\\"(DISTINCT \\"si\\".\\"invoice_number\\") FILTER (WHERE (\\"si\\".\\"invoice_number\\" IS NOT NULL)), ARRAY[]::\\"text\\"[]) AS \\"linked_invoices\\"\n   FROM (((\\"public\\".\\"delivery_challans\\" \\"dc\\"\n     LEFT JOIN \\"public\\".\\"delivery_challan_items\\" \\"dci\\" ON ((\\"dc\\".\\"id\\" = \\"dci\\".\\"challan_id\\")))\n     LEFT JOIN \\"public\\".\\"sales_invoice_items\\" \\"sii\\" ON ((\\"sii\\".\\"delivery_challan_item_id\\" = \\"dci\\".\\"id\\")))\n     LEFT JOIN \\"public\\".\\"sales_invoices\\" \\"si\\" ON ((\\"sii\\".\\"invoice_id\\" = \\"si\\".\\"id\\")))\n  WHERE (\\"dc\\".\\"approval_status\\" = 'approved'::\\"public\\".\\"dc_approval_status\\")\n  GROUP BY \\"dc\\".\\"id\\", \\"dc\\".\\"challan_number\\", \\"dc\\".\\"customer_id\\", \\"dc\\".\\"challan_date\\", \\"dc\\".\\"approval_status\\"","--\n-- Name: VIEW \\"dc_invoicing_summary\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON VIEW \\"public\\".\\"dc_invoicing_summary\\" IS 'Summary of delivery challans with invoicing status and remaining quantities for approved DCs only'","--\n-- Name: products; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"products\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"product_name\\" \\"text\\" NOT NULL,\n    \\"product_code\\" \\"text\\",\n    \\"hsn_code\\" \\"text\\",\n    \\"category\\" \\"text\\" NOT NULL,\n    \\"unit\\" \\"text\\" NOT NULL,\n    \\"packaging_type\\" \\"text\\",\n    \\"default_supplier\\" \\"text\\",\n    \\"description\\" \\"text\\",\n    \\"is_active\\" boolean DEFAULT true,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"total_quantity\\" numeric(15,3),\n    \\"per_pack_weight\\" numeric(15,3),\n    \\"pack_type\\" \\"text\\",\n    \\"calculated_packs\\" numeric(15,3),\n    \\"min_stock_level\\" numeric(15,3),\n    \\"duty_a1\\" \\"text\\",\n    \\"duty_percent\\" numeric(5,2) DEFAULT 0,\n    \\"current_stock\\" numeric(18,2) DEFAULT 0,\n    CONSTRAINT \\"products_category_check\\" CHECK ((\\"category\\" = ANY (ARRAY['api'::\\"text\\", 'excipient'::\\"text\\", 'solvent'::\\"text\\", 'other'::\\"text\\"]))),\n    CONSTRAINT \\"products_pack_type_check\\" CHECK ((\\"pack_type\\" = ANY (ARRAY['Bag'::\\"text\\", 'Drum'::\\"text\\", 'Tin'::\\"text\\", 'Carton'::\\"text\\", 'Box'::\\"text\\", 'Container'::\\"text\\", 'Other'::\\"text\\"]))),\n    CONSTRAINT \\"products_unit_check\\" CHECK ((\\"unit\\" = ANY (ARRAY['kg'::\\"text\\", 'g'::\\"text\\", 'mg'::\\"text\\", 'ton'::\\"text\\", 'litre'::\\"text\\", 'ml'::\\"text\\", 'piece'::\\"text\\", 'box'::\\"text\\", 'bottle'::\\"text\\", 'pack'::\\"text\\"])))\n)","--\n-- Name: COLUMN \\"products\\".\\"unit\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"products\\".\\"unit\\" IS 'Unit of measurement: kg (Kilogram), g (Gram), mg (Milligram), ton (Ton), litre (Litre), ml (Millilitre), piece (Piece), box (Box), bottle (Bottle), pack (Pack)'","--\n-- Name: COLUMN \\"products\\".\\"calculated_packs\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"products\\".\\"calculated_packs\\" IS 'Automatically calculated as total_quantity / per_pack_weight'","--\n-- Name: COLUMN \\"products\\".\\"min_stock_level\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"products\\".\\"min_stock_level\\" IS 'Minimum stock threshold for this product, in the product unit. When stock falls below this level, low stock alerts are triggered.'","--\n-- Name: COLUMN \\"products\\".\\"duty_a1\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"products\\".\\"duty_a1\\" IS 'Import duty information/rate for the product (A1 category)'","--\n-- Name: COLUMN \\"products\\".\\"duty_percent\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"products\\".\\"duty_percent\\" IS 'Import duty percentage - auto-synced with duty_a1 field'","--\n-- Name: COLUMN \\"products\\".\\"current_stock\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"products\\".\\"current_stock\\" IS 'Total of all active batch stocks for this product. Auto-updated by trigger.'","--\n-- Name: dc_item_invoice_status; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"dc_item_invoice_status\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"dci\\".\\"id\\" AS \\"dc_item_id\\",\n    \\"dci\\".\\"challan_id\\",\n    \\"dc\\".\\"challan_number\\",\n    \\"dc\\".\\"challan_date\\",\n    \\"dc\\".\\"customer_id\\",\n    \\"c\\".\\"company_name\\" AS \\"customer_name\\",\n    \\"dci\\".\\"product_id\\",\n    \\"p\\".\\"product_name\\",\n    \\"dci\\".\\"batch_id\\",\n    \\"b\\".\\"batch_number\\",\n    \\"dci\\".\\"quantity\\" AS \\"original_quantity\\",\n    \\"p\\".\\"unit\\",\n    \\"dci\\".\\"pack_size\\",\n    \\"dci\\".\\"pack_type\\",\n    \\"dci\\".\\"number_of_packs\\",\n    COALESCE(\\"sum\\"(\\"sii\\".\\"quantity\\"), (0)::numeric) AS \\"invoiced_quantity\\",\n    (\\"dci\\".\\"quantity\\" - COALESCE(\\"sum\\"(\\"sii\\".\\"quantity\\"), (0)::numeric)) AS \\"remaining_quantity\\",\n        CASE\n            WHEN (COALESCE(\\"sum\\"(\\"sii\\".\\"quantity\\"), (0)::numeric) = (0)::numeric) THEN 'not_invoiced'::\\"text\\"\n            WHEN (COALESCE(\\"sum\\"(\\"sii\\".\\"quantity\\"), (0)::numeric) >= \\"dci\\".\\"quantity\\") THEN 'fully_invoiced'::\\"text\\"\n            ELSE 'partially_invoiced'::\\"text\\"\n        END AS \\"status\\",\n    \\"array_agg\\"(DISTINCT \\"si\\".\\"invoice_number\\" ORDER BY \\"si\\".\\"invoice_number\\") FILTER (WHERE (\\"si\\".\\"invoice_number\\" IS NOT NULL)) AS \\"invoice_numbers\\",\n    \\"count\\"(DISTINCT \\"sii\\".\\"invoice_id\\") AS \\"invoice_count\\"\n   FROM ((((((\\"public\\".\\"delivery_challan_items\\" \\"dci\\"\n     JOIN \\"public\\".\\"delivery_challans\\" \\"dc\\" ON ((\\"dci\\".\\"challan_id\\" = \\"dc\\".\\"id\\")))\n     LEFT JOIN \\"public\\".\\"customers\\" \\"c\\" ON ((\\"dc\\".\\"customer_id\\" = \\"c\\".\\"id\\")))\n     LEFT JOIN \\"public\\".\\"products\\" \\"p\\" ON ((\\"dci\\".\\"product_id\\" = \\"p\\".\\"id\\")))\n     LEFT JOIN \\"public\\".\\"batches\\" \\"b\\" ON ((\\"dci\\".\\"batch_id\\" = \\"b\\".\\"id\\")))\n     LEFT JOIN \\"public\\".\\"sales_invoice_items\\" \\"sii\\" ON ((\\"dci\\".\\"id\\" = \\"sii\\".\\"delivery_challan_item_id\\")))\n     LEFT JOIN \\"public\\".\\"sales_invoices\\" \\"si\\" ON ((\\"sii\\".\\"invoice_id\\" = \\"si\\".\\"id\\")))\n  GROUP BY \\"dci\\".\\"id\\", \\"dci\\".\\"challan_id\\", \\"dc\\".\\"challan_number\\", \\"dc\\".\\"challan_date\\", \\"dc\\".\\"customer_id\\", \\"c\\".\\"company_name\\", \\"dci\\".\\"product_id\\", \\"p\\".\\"product_name\\", \\"p\\".\\"unit\\", \\"dci\\".\\"batch_id\\", \\"b\\".\\"batch_number\\", \\"dci\\".\\"quantity\\", \\"dci\\".\\"pack_size\\", \\"dci\\".\\"pack_type\\", \\"dci\\".\\"number_of_packs\\"","--\n-- Name: directors; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"directors\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"director_code\\" character varying(50),\n    \\"full_name\\" character varying(255) NOT NULL,\n    \\"designation\\" character varying(100),\n    \\"email\\" character varying(255),\n    \\"phone\\" character varying(50),\n    \\"address\\" \\"text\\",\n    \\"capital_account_id\\" \\"uuid\\",\n    \\"is_active\\" boolean DEFAULT true,\n    \\"notes\\" \\"text\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"loan_account_id\\" \\"uuid\\",\n    \\"drawings_account_id\\" \\"uuid\\",\n    \\"is_deprecated\\" boolean DEFAULT false\n)","--\n-- Name: TABLE \\"directors\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON TABLE \\"public\\".\\"directors\\" IS 'DEPRECATED: Directors master table kept for historical reference. New entries should use proper Chart of Accounts ledgers directly (Capital/Loan/Drawings accounts).'","--\n-- Name: COLUMN \\"directors\\".\\"capital_account_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"directors\\".\\"capital_account_id\\" IS 'Dedicated capital ledger account (Equity section)'","--\n-- Name: COLUMN \\"directors\\".\\"loan_account_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"directors\\".\\"loan_account_id\\" IS 'Loan from Owner account (Liability section) - for money lent to company'","--\n-- Name: COLUMN \\"directors\\".\\"drawings_account_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"directors\\".\\"drawings_account_id\\" IS 'Drawings account (Equity contra) - for money withdrawn by owner'","--\n-- Name: COLUMN \\"directors\\".\\"is_deprecated\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"directors\\".\\"is_deprecated\\" IS 'TRUE means this record has been migrated to proper Chart of Accounts ledgers. Table kept for historical reference only.'","--\n-- Name: director_account_balances; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"director_account_balances\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"d\\".\\"id\\" AS \\"director_id\\",\n    \\"d\\".\\"full_name\\" AS \\"director_name\\",\n    \\"d\\".\\"designation\\",\n    \\"ca\\".\\"id\\" AS \\"capital_account_id\\",\n    \\"ca\\".\\"code\\" AS \\"capital_account_code\\",\n    \\"ca\\".\\"name\\" AS \\"capital_account_name\\",\n    COALESCE(( SELECT \\"sum\\"((\\"jel\\".\\"credit\\" - \\"jel\\".\\"debit\\")) AS \\"sum\\"\n           FROM (\\"public\\".\\"journal_entry_lines\\" \\"jel\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((\\"je\\".\\"id\\" = \\"jel\\".\\"journal_entry_id\\")))\n          WHERE (\\"jel\\".\\"account_id\\" = \\"ca\\".\\"id\\")), (0)::numeric) AS \\"capital_balance\\",\n    \\"la\\".\\"id\\" AS \\"loan_account_id\\",\n    \\"la\\".\\"code\\" AS \\"loan_account_code\\",\n    \\"la\\".\\"name\\" AS \\"loan_account_name\\",\n    COALESCE(( SELECT \\"sum\\"((\\"jel\\".\\"credit\\" - \\"jel\\".\\"debit\\")) AS \\"sum\\"\n           FROM (\\"public\\".\\"journal_entry_lines\\" \\"jel\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((\\"je\\".\\"id\\" = \\"jel\\".\\"journal_entry_id\\")))\n          WHERE (\\"jel\\".\\"account_id\\" = \\"la\\".\\"id\\")), (0)::numeric) AS \\"loan_balance\\",\n    \\"da\\".\\"id\\" AS \\"drawings_account_id\\",\n    \\"da\\".\\"code\\" AS \\"drawings_account_code\\",\n    \\"da\\".\\"name\\" AS \\"drawings_account_name\\",\n    COALESCE(( SELECT \\"sum\\"((\\"jel\\".\\"debit\\" - \\"jel\\".\\"credit\\")) AS \\"sum\\"\n           FROM (\\"public\\".\\"journal_entry_lines\\" \\"jel\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((\\"je\\".\\"id\\" = \\"jel\\".\\"journal_entry_id\\")))\n          WHERE (\\"jel\\".\\"account_id\\" = \\"da\\".\\"id\\")), (0)::numeric) AS \\"drawings_balance\\",\n    (COALESCE(( SELECT \\"sum\\"((\\"jel\\".\\"credit\\" - \\"jel\\".\\"debit\\")) AS \\"sum\\"\n           FROM (\\"public\\".\\"journal_entry_lines\\" \\"jel\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((\\"je\\".\\"id\\" = \\"jel\\".\\"journal_entry_id\\")))\n          WHERE (\\"jel\\".\\"account_id\\" = \\"ca\\".\\"id\\")), (0)::numeric) - COALESCE(( SELECT \\"sum\\"((\\"jel\\".\\"debit\\" - \\"jel\\".\\"credit\\")) AS \\"sum\\"\n           FROM (\\"public\\".\\"journal_entry_lines\\" \\"jel\\"\n             JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((\\"je\\".\\"id\\" = \\"jel\\".\\"journal_entry_id\\")))\n          WHERE (\\"jel\\".\\"account_id\\" = \\"da\\".\\"id\\")), (0)::numeric)) AS \\"net_capital\\"\n   FROM (((\\"public\\".\\"directors\\" \\"d\\"\n     LEFT JOIN \\"public\\".\\"chart_of_accounts\\" \\"ca\\" ON ((\\"d\\".\\"capital_account_id\\" = \\"ca\\".\\"id\\")))\n     LEFT JOIN \\"public\\".\\"chart_of_accounts\\" \\"la\\" ON ((\\"d\\".\\"loan_account_id\\" = \\"la\\".\\"id\\")))\n     LEFT JOIN \\"public\\".\\"chart_of_accounts\\" \\"da\\" ON ((\\"d\\".\\"drawings_account_id\\" = \\"da\\".\\"id\\")))\n  WHERE (\\"d\\".\\"is_active\\" = true)","--\n-- Name: VIEW \\"director_account_balances\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON VIEW \\"public\\".\\"director_account_balances\\" IS 'Helper view showing all director-related account balances. Capital and Loan balances should appear in Balance Sheet. Drawings reduce net capital.'","--\n-- Name: duplicate_postings; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"duplicate_postings\\" WITH (\\"security_invoker\\"='true') AS\n WITH \\"duplicate_keys\\" AS (\n         SELECT \\"journal_entries\\".\\"source_module\\",\n            \\"journal_entries\\".\\"reference_id\\",\n            \\"count\\"(*) AS \\"duplicate_count\\"\n           FROM \\"public\\".\\"journal_entries\\"\n          WHERE ((\\"journal_entries\\".\\"reference_id\\" IS NOT NULL) AND (\\"journal_entries\\".\\"is_posted\\" = true) AND (COALESCE(\\"journal_entries\\".\\"is_reversed\\", false) = false))\n          GROUP BY \\"journal_entries\\".\\"source_module\\", \\"journal_entries\\".\\"reference_id\\"\n         HAVING (\\"count\\"(*) > 1)\n        )\n SELECT \\"je\\".\\"id\\" AS \\"journal_entry_id\\",\n    \\"je\\".\\"entry_number\\",\n    \\"je\\".\\"entry_date\\",\n    \\"je\\".\\"source_module\\",\n    \\"je\\".\\"reference_id\\",\n    \\"je\\".\\"reference_number\\",\n    \\"je\\".\\"description\\",\n    \\"dk\\".\\"duplicate_count\\"\n   FROM (\\"public\\".\\"journal_entries\\" \\"je\\"\n     JOIN \\"duplicate_keys\\" \\"dk\\" ON (((NOT ((\\"dk\\".\\"source_module\\")::\\"text\\" IS DISTINCT FROM (\\"je\\".\\"source_module\\")::\\"text\\")) AND (\\"dk\\".\\"reference_id\\" = \\"je\\".\\"reference_id\\"))))\n  WHERE ((\\"je\\".\\"is_posted\\" = true) AND (COALESCE(\\"je\\".\\"is_reversed\\", false) = false))","--\n-- Name: email_inquiry_links; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"email_inquiry_links\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"gmail_message_id\\" \\"text\\",\n    \\"gmail_thread_id\\" \\"text\\",\n    \\"inquiry_id\\" \\"uuid\\" NOT NULL,\n    \\"link_type\\" \\"text\\" NOT NULL,\n    \\"source_reply_parser_run_at\\" timestamp with time zone,\n    \\"parser_confidence\\" numeric,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    CONSTRAINT \\"email_inquiry_links_type_chk\\" CHECK ((\\"link_type\\" = ANY (ARRAY['customer_inquiry'::\\"text\\", 'source_reply'::\\"text\\", 'customer_quote'::\\"text\\", 'reminder'::\\"text\\", 'generic'::\\"text\\"])))\n)","--\n-- Name: email_thread_map; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"email_thread_map\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"price_request_id\\" \\"uuid\\",\n    \\"item_ids\\" \\"uuid\\"[],\n    \\"gmail_thread_id\\" \\"text\\",\n    \\"gmail_message_id\\" \\"text\\",\n    \\"source_type\\" \\"text\\",\n    \\"direction\\" \\"text\\" DEFAULT 'outbound'::\\"text\\",\n    \\"subject\\" \\"text\\",\n    \\"sent_at\\" timestamp with time zone,\n    \\"reply_received_at\\" timestamp with time zone,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL\n)","--\n-- Name: expense_categories; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"expense_categories\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"category_key\\" \\"text\\" NOT NULL,\n    \\"name\\" \\"text\\" NOT NULL,\n    \\"parent_id\\" \\"uuid\\",\n    \\"category_type\\" \\"text\\" DEFAULT 'operations'::\\"text\\" NOT NULL,\n    \\"tax_behavior\\" \\"text\\" DEFAULT 'standard'::\\"text\\" NOT NULL,\n    \\"description\\" \\"text\\",\n    \\"coa_account_id\\" \\"uuid\\",\n    \\"requires_container\\" boolean DEFAULT false NOT NULL,\n    \\"allows_account_override\\" boolean DEFAULT false NOT NULL,\n    \\"is_active\\" boolean DEFAULT true NOT NULL,\n    \\"sort_order\\" integer DEFAULT 0 NOT NULL,\n    \\"icon\\" \\"text\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"is_posting_category\\" boolean DEFAULT true NOT NULL,\n    CONSTRAINT \\"expense_categories_key_format\\" CHECK ((\\"category_key\\" ~ '^[a-z][a-z0-9_]*$'::\\"text\\")),\n    CONSTRAINT \\"expense_categories_type\\" CHECK ((\\"category_type\\" = ANY (ARRAY['import'::\\"text\\", 'sales'::\\"text\\", 'staff'::\\"text\\", 'operations'::\\"text\\", 'admin'::\\"text\\", 'assets'::\\"text\\"])))\n)","--\n-- Name: TABLE \\"expense_categories\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON TABLE \\"public\\".\\"expense_categories\\" IS 'Single canonical category master for Expenses, Petty Cash and future expense modules.'","--\n-- Name: COLUMN \\"expense_categories\\".\\"is_posting_category\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"expense_categories\\".\\"is_posting_category\\" IS 'True only for leaf categories. Parent rows organise UI and reporting and cannot post.'","--\n-- Name: expense_posting_lifecycle_audit; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"expense_posting_lifecycle_audit\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"expense_id\\",\n    \\"voucher_number\\",\n    \\"document_approval_status\\",\n    \\"active_original_count\\",\n    \\"reversed_original_count\\",\n    \\"active_replacement_count\\",\n    \\"active_journal_id\\",\n    \\"active_journal_number\\",\n    \\"active_journal_date\\",\n    \\"original_journal_id\\",\n    \\"original_journal_number\\",\n    \\"reversal_journal_id\\",\n    \\"replacement_journal_id\\",\n    \\"replacement_journal_number\\",\n    \\"replacement_journal_date\\",\n    \\"replacement_reference\\",\n    \\"replacement_source_module\\",\n    \\"effective_posting_state\\",\n    \\"effective_journal_id\\",\n    \\"effective_journal_number\\",\n    \\"effective_journal_date\\",\n    \\"ambiguity_reason\\"\n   FROM \\"public\\".\\"effective_expense_posting_state\\"\n  WHERE ((\\"document_approval_status\\" = 'approved'::\\"text\\") AND (\\"effective_posting_state\\" <> 'ACTIVE'::\\"text\\"))","--\n-- Name: VIEW \\"expense_posting_lifecycle_audit\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON VIEW \\"public\\".\\"expense_posting_lifecycle_audit\\" IS 'Read-only audit population of approved expense documents whose effective posting is reversed, replaced or ambiguous.'","--\n-- Name: export_audit_log; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"export_audit_log\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"user_id\\" \\"uuid\\" NOT NULL,\n    \\"export_type\\" \\"text\\" NOT NULL,\n    \\"module_name\\" \\"text\\" NOT NULL,\n    \\"filter_criteria\\" \\"jsonb\\",\n    \\"record_count\\" integer,\n    \\"file_format\\" \\"text\\" NOT NULL,\n    \\"exported_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"ip_address\\" \\"text\\",\n    \\"user_agent\\" \\"text\\",\n    CONSTRAINT \\"export_audit_log_file_format_check\\" CHECK ((\\"file_format\\" = ANY (ARRAY['csv'::\\"text\\", 'excel'::\\"text\\", 'pdf'::\\"text\\"])))\n)","--\n-- Name: TABLE \\"export_audit_log\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON TABLE \\"public\\".\\"export_audit_log\\" IS 'Audit trail for all data exports by users, especially auditors'","--\n-- Name: extracted_contacts; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"extracted_contacts\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"user_id\\" \\"uuid\\" NOT NULL,\n    \\"company_name\\" \\"text\\" DEFAULT ''::\\"text\\",\n    \\"customer_name\\" \\"text\\" DEFAULT ''::\\"text\\",\n    \\"email_ids\\" \\"text\\" NOT NULL,\n    \\"phone\\" \\"text\\" DEFAULT ''::\\"text\\",\n    \\"mobile\\" \\"text\\" DEFAULT ''::\\"text\\",\n    \\"website\\" \\"text\\" DEFAULT ''::\\"text\\",\n    \\"address\\" \\"text\\" DEFAULT ''::\\"text\\",\n    \\"source\\" \\"text\\" DEFAULT 'Gmail'::\\"text\\",\n    \\"confidence\\" numeric(3,2) DEFAULT 0.5,\n    \\"extracted_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"()\n)","--\n-- Name: faktur_pajak; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"faktur_pajak\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"sales_invoice_id\\" \\"uuid\\" NOT NULL,\n    \\"tax_period_id\\" \\"uuid\\",\n    \\"faktur_number\\" character varying(50) NOT NULL,\n    \\"issue_date\\" \\"date\\" NOT NULL,\n    \\"customer_id\\" \\"uuid\\",\n    \\"dpp_amount\\" numeric(18,2) DEFAULT 0 NOT NULL,\n    \\"ppn_amount\\" numeric(18,2) DEFAULT 0 NOT NULL,\n    \\"status\\" \\"text\\" DEFAULT 'generated'::\\"text\\" NOT NULL,\n    \\"reported_at\\" timestamp with time zone,\n    \\"notes\\" \\"text\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"official_djp_number\\" character varying(50),\n    \\"linked_invoice_id\\" \\"uuid\\",\n    \\"invoice_amount\\" numeric(18,2),\n    \\"uploaded_by\\" \\"uuid\\",\n    \\"uploaded_at\\" timestamp with time zone,\n    CONSTRAINT \\"faktur_pajak_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['waiting'::\\"text\\", 'recorded'::\\"text\\", 'reported'::\\"text\\", 'cancelled'::\\"text\\", 'generated'::\\"text\\", 'uploaded'::\\"text\\"])))\n)","--\n-- Name: COLUMN \\"faktur_pajak\\".\\"official_djp_number\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"faktur_pajak\\".\\"official_djp_number\\" IS 'Official DJP number received from the external CA; never generated by the ERP.'","--\n-- Name: COLUMN \\"faktur_pajak\\".\\"linked_invoice_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"faktur_pajak\\".\\"linked_invoice_id\\" IS 'Explicit audit link to the originating Sales Invoice.'","--\n-- Name: faktur_pajak_files; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"faktur_pajak_files\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"faktur_pajak_id\\" \\"uuid\\" NOT NULL,\n    \\"file_url\\" \\"text\\" NOT NULL,\n    \\"file_name\\" character varying(255),\n    \\"file_type\\" character varying(50),\n    \\"file_size\\" integer,\n    \\"kind\\" \\"text\\",\n    \\"uploaded_by\\" \\"uuid\\",\n    \\"uploaded_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    CONSTRAINT \\"faktur_pajak_files_kind_check\\" CHECK ((\\"kind\\" = ANY (ARRAY['pdf'::\\"text\\", 'xml'::\\"text\\", 'csv'::\\"text\\", 'other'::\\"text\\"])))\n)","--\n-- Name: finance_historical_repair_exceptions; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"finance_historical_repair_exceptions\\" (\n    \\"id\\" bigint NOT NULL,\n    \\"run_id\\" \\"uuid\\" NOT NULL,\n    \\"document_type\\" \\"text\\" NOT NULL,\n    \\"document_id\\" \\"uuid\\" NOT NULL,\n    \\"document_number\\" \\"text\\",\n    \\"inconsistent_fields\\" \\"text\\"[] NOT NULL,\n    \\"reason\\" \\"text\\" NOT NULL,\n    \\"manual_information_required\\" \\"text\\" NOT NULL,\n    \\"status\\" \\"text\\" DEFAULT 'manual_review'::\\"text\\" NOT NULL,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    CONSTRAINT \\"finance_historical_repair_exceptions_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['manual_review'::\\"text\\", 'resolved'::\\"text\\", 'skipped'::\\"text\\"])))\n)","--\n-- Name: loan_transactions; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"loan_transactions\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"transaction_number\\" \\"text\\" NOT NULL,\n    \\"loan_id\\" \\"uuid\\" NOT NULL,\n    \\"transaction_type\\" \\"text\\" NOT NULL,\n    \\"transaction_date\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"amount\\" numeric(18,2) NOT NULL,\n    \\"principal_amount\\" numeric(18,2) DEFAULT 0 NOT NULL,\n    \\"interest_amount\\" numeric(18,2) DEFAULT 0 NOT NULL,\n    \\"bank_account_id\\" \\"uuid\\",\n    \\"bank_statement_line_id\\" \\"uuid\\",\n    \\"description\\" \\"text\\" DEFAULT ''::\\"text\\",\n    \\"journal_entry_id\\" \\"uuid\\",\n    \\"status\\" \\"text\\" DEFAULT 'pending'::\\"text\\" NOT NULL,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"transaction_currency\\" \\"text\\",\n    \\"functional_currency\\" \\"text\\",\n    \\"exchange_rate\\" numeric,\n    \\"bank_account_currency\\" \\"text\\",\n    CONSTRAINT \\"loan_transactions_amount_check\\" CHECK ((\\"amount\\" > (0)::numeric)),\n    CONSTRAINT \\"loan_transactions_interest_amount_check\\" CHECK ((\\"interest_amount\\" >= (0)::numeric)),\n    CONSTRAINT \\"loan_transactions_principal_amount_check\\" CHECK ((\\"principal_amount\\" >= (0)::numeric)),\n    CONSTRAINT \\"loan_transactions_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['posted'::\\"text\\", 'pending'::\\"text\\"]))),\n    CONSTRAINT \\"loan_transactions_transaction_type_check\\" CHECK ((\\"transaction_type\\" = ANY (ARRAY['repayment'::\\"text\\", 'interest_payment'::\\"text\\", 'additional_disbursement'::\\"text\\"])))\n)","--\n-- Name: loans; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"loans\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"loan_number\\" \\"text\\" NOT NULL,\n    \\"loan_type\\" \\"text\\" NOT NULL,\n    \\"counterparty_name\\" \\"text\\" NOT NULL,\n    \\"counterparty_type\\" \\"text\\" DEFAULT 'person'::\\"text\\" NOT NULL,\n    \\"principal_amount\\" numeric(18,2) NOT NULL,\n    \\"interest_rate\\" numeric(5,2) DEFAULT 0 NOT NULL,\n    \\"loan_date\\" \\"date\\" DEFAULT CURRENT_DATE NOT NULL,\n    \\"maturity_date\\" \\"date\\",\n    \\"bank_account_id\\" \\"uuid\\",\n    \\"coa_id\\" \\"uuid\\",\n    \\"interest_coa_id\\" \\"uuid\\",\n    \\"currency\\" \\"text\\" DEFAULT 'IDR'::\\"text\\" NOT NULL,\n    \\"description\\" \\"text\\" DEFAULT ''::\\"text\\",\n    \\"notes\\" \\"text\\" DEFAULT ''::\\"text\\",\n    \\"status\\" \\"text\\" DEFAULT 'active'::\\"text\\" NOT NULL,\n    \\"outstanding_balance\\" numeric(18,2) DEFAULT 0 NOT NULL,\n    \\"journal_entry_id\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"transaction_currency\\" \\"text\\",\n    \\"functional_currency\\" \\"text\\",\n    \\"exchange_rate\\" numeric,\n    \\"bank_account_currency\\" \\"text\\",\n    \\"bank_statement_line_id\\" \\"uuid\\",\n    CONSTRAINT \\"loans_counterparty_type_check\\" CHECK ((\\"counterparty_type\\" = ANY (ARRAY['bank'::\\"text\\", 'person'::\\"text\\", 'staff'::\\"text\\", 'company'::\\"text\\"]))),\n    CONSTRAINT \\"loans_currency_check\\" CHECK ((\\"currency\\" = ANY (ARRAY['IDR'::\\"text\\", 'USD'::\\"text\\"]))),\n    CONSTRAINT \\"loans_interest_rate_check\\" CHECK ((\\"interest_rate\\" >= (0)::numeric)),\n    CONSTRAINT \\"loans_loan_type_check\\" CHECK ((\\"loan_type\\" = ANY (ARRAY['taken'::\\"text\\", 'given'::\\"text\\"]))),\n    CONSTRAINT \\"loans_principal_amount_check\\" CHECK ((\\"principal_amount\\" > (0)::numeric)),\n    CONSTRAINT \\"loans_status_check\\" CHECK ((\\"status\\" = ANY (ARRAY['active'::\\"text\\", 'closed'::\\"text\\"])))\n)","--\n-- Name: purchase_invoices; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"purchase_invoices\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"invoice_number\\" character varying(100) NOT NULL,\n    \\"supplier_id\\" \\"uuid\\" NOT NULL,\n    \\"invoice_date\\" \\"date\\" NOT NULL,\n    \\"due_date\\" \\"date\\",\n    \\"currency\\" character varying(10) DEFAULT 'IDR'::character varying,\n    \\"exchange_rate\\" numeric(18,6) DEFAULT 1,\n    \\"subtotal\\" numeric(18,2) DEFAULT 0,\n    \\"tax_amount\\" numeric(18,2) DEFAULT 0,\n    \\"total_amount\\" numeric(18,2) DEFAULT 0,\n    \\"paid_amount\\" numeric(18,2) DEFAULT 0,\n    \\"balance_amount\\" numeric(18,2) GENERATED ALWAYS AS ((\\"total_amount\\" - \\"paid_amount\\")) STORED,\n    \\"status\\" character varying(20) DEFAULT 'unpaid'::character varying,\n    \\"faktur_pajak_number\\" character varying(50),\n    \\"notes\\" \\"text\\",\n    \\"document_urls\\" \\"text\\"[],\n    \\"journal_entry_id\\" \\"uuid\\",\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"purchase_type\\" character varying(50) DEFAULT 'inventory'::character varying,\n    \\"requires_faktur_pajak\\" boolean DEFAULT false,\n    \\"stamp_duty_amount\\" numeric(18,2) DEFAULT 0,\n    \\"tax_period_id\\" \\"uuid\\",\n    \\"company_snapshot\\" \\"jsonb\\",\n    \\"purchase_order_id\\" \\"uuid\\",\n    \\"receiving_approval_status\\" \\"text\\",\n    \\"receiving_submitted_at\\" timestamp with time zone,\n    \\"receiving_submitted_by\\" \\"uuid\\",\n    \\"receiving_approved_at\\" timestamp with time zone,\n    \\"receiving_approved_by\\" \\"uuid\\",\n    \\"receiving_rejection_reason\\" \\"text\\",\n    CONSTRAINT \\"purchase_invoices_purchase_type_check\\" CHECK (((\\"purchase_type\\")::\\"text\\" = ANY ((ARRAY['inventory'::character varying, 'fixed_asset'::character varying, 'expense'::character varying, 'import'::character varying])::\\"text\\"[]))),\n    CONSTRAINT \\"purchase_invoices_receiving_approval_status_check\\" CHECK ((\\"receiving_approval_status\\" = ANY (ARRAY['draft'::\\"text\\", 'pending_approval'::\\"text\\", 'approved'::\\"text\\", 'rejected'::\\"text\\"]))),\n    CONSTRAINT \\"purchase_invoices_status_check\\" CHECK (((\\"status\\")::\\"text\\" = ANY ((ARRAY['draft'::character varying, 'unpaid'::character varying, 'partial'::character varying, 'paid'::character varying, 'cancelled'::character varying])::\\"text\\"[])))\n)","--\n-- Name: TABLE \\"purchase_invoices\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON TABLE \\"public\\".\\"purchase_invoices\\" IS 'Enhanced purchase invoice system supporting inventory, assets, expenses, and imports with proper journal posting'","--\n-- Name: COLUMN \\"purchase_invoices\\".\\"purchase_type\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"purchase_invoices\\".\\"purchase_type\\" IS 'Type of purchase: inventory (stock), fixed_asset, expense, or import'","--\n-- Name: COLUMN \\"purchase_invoices\\".\\"requires_faktur_pajak\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"purchase_invoices\\".\\"requires_faktur_pajak\\" IS 'True if supplier is PKP and Faktur Pajak is required'","--\n-- Name: suppliers; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"suppliers\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"supplier_code\\" character varying(50),\n    \\"company_name\\" character varying(255) NOT NULL,\n    \\"contact_person\\" character varying(255),\n    \\"email\\" character varying(255),\n    \\"phone\\" character varying(50),\n    \\"address\\" \\"text\\",\n    \\"city\\" character varying(100),\n    \\"country\\" character varying(100) DEFAULT 'Indonesia'::character varying,\n    \\"npwp\\" character varying(30),\n    \\"pkp_status\\" boolean DEFAULT false,\n    \\"payment_terms_days\\" integer DEFAULT 30,\n    \\"bank_name\\" character varying(100),\n    \\"bank_account_number\\" character varying(50),\n    \\"bank_account_name\\" character varying(255),\n    \\"notes\\" \\"text\\",\n    \\"is_active\\" boolean DEFAULT true,\n    \\"created_by\\" \\"uuid\\",\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"postal_code\\" character varying(20),\n    \\"default_expense_category\\" character varying(100),\n    \\"default_pph_code_id\\" \\"uuid\\",\n    \\"tax_preference\\" character varying(20) DEFAULT 'none'::character varying,\n    \\"supplier_type\\" character varying(50),\n    CONSTRAINT \\"suppliers_tax_preference_check\\" CHECK (((\\"tax_preference\\")::\\"text\\" = ANY ((ARRAY['none'::character varying, 'ppn_only'::character varying, 'ppn_pph'::character varying, 'pph_only'::character varying])::\\"text\\"[])))\n)","--\n-- Name: COLUMN \\"suppliers\\".\\"default_expense_category\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"suppliers\\".\\"default_expense_category\\" IS 'Auto-fill expense category when this supplier is selected in Expense entry'","--\n-- Name: COLUMN \\"suppliers\\".\\"default_pph_code_id\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"suppliers\\".\\"default_pph_code_id\\" IS 'Default PPh withholding tax code for this supplier'","--\n-- Name: COLUMN \\"suppliers\\".\\"tax_preference\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"suppliers\\".\\"tax_preference\\" IS 'Which tax fields to show by default: none | ppn_only | ppn_pph | pph_only'","--\n-- Name: COLUMN \\"suppliers\\".\\"supplier_type\\"; Type: COMMENT; Schema: public; Owner: -\n--\n\nCOMMENT ON COLUMN \\"public\\".\\"suppliers\\".\\"supplier_type\\" IS 'Import Broker | Utility | Transport | Employee | Government | Professional Services | General'","--\n-- Name: finance_historical_repair_exception_details; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"finance_historical_repair_exception_details\\" WITH (\\"security_invoker\\"='true') AS\n WITH \\"exceptions\\" AS (\n         SELECT \\"e\\".\\"id\\",\n            \\"e\\".\\"run_id\\",\n            \\"e\\".\\"document_type\\",\n            \\"e\\".\\"document_id\\",\n            \\"e\\".\\"document_number\\",\n            \\"e\\".\\"inconsistent_fields\\",\n            \\"e\\".\\"reason\\",\n            \\"e\\".\\"manual_information_required\\",\n            \\"e\\".\\"status\\",\n            \\"e\\".\\"created_at\\",\n                CASE\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%USD%rate%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%USD-source Contra%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%does not use the Expense bank account%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%does not post to this bank account%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%without an accrued payable%'::\\"text\\")) THEN 'Historical accounting decision required'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%multiple typed%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%no provable active journal%'::\\"text\\")) THEN 'Manual relink required'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%Approved expense has no active journal%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%Journal metadata cannot be derived%'::\\"text\\")) THEN 'Missing source document'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%No unique authoritative relationship%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%metadata conflicts%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%missing Faktur Pajak%'::\\"text\\")) THEN 'Manual edit required'::\\"text\\"\n                    ELSE 'Investigate further'::\\"text\\"\n                END AS \\"classification\\"\n           FROM \\"public\\".\\"finance_historical_repair_exceptions\\" \\"e\\"\n          WHERE (\\"e\\".\\"status\\" = 'manual_review'::\\"text\\")\n        ), \\"details\\" AS (\n         SELECT \\"e\\".\\"run_id\\",\n            \\"e\\".\\"document_type\\",\n            COALESCE(\\"e\\".\\"document_number\\", NULLIF(\\"bsl\\".\\"reference\\", ''::\\"text\\")) AS \\"document_number\\",\n            \\"e\\".\\"document_id\\" AS \\"database_id\\",\n            COALESCE(\\"fe\\".\\"expense_date\\", \\"rv\\".\\"voucher_date\\", \\"pv\\".\\"voucher_date\\", \\"ft\\".\\"transfer_date\\", \\"l\\".\\"loan_date\\", \\"lt\\".\\"transaction_date\\", \\"cc\\".\\"voucher_date\\", \\"pc\\".\\"transaction_date\\", \\"tp\\".\\"payment_date\\", \\"si\\".\\"invoice_date\\", \\"pi\\".\\"invoice_date\\", \\"je\\".\\"entry_date\\", \\"bsl\\".\\"transaction_date\\") AS \\"document_date\\",\n            COALESCE(\\"fe\\".\\"amount\\", \\"rv\\".\\"amount\\", \\"pv\\".\\"amount\\", \\"ft\\".\\"amount\\", \\"l\\".\\"principal_amount\\", \\"lt\\".\\"amount\\", \\"cc\\".\\"amount\\", \\"pc\\".\\"amount\\", \\"tp\\".\\"amount\\", \\"si\\".\\"total_amount\\", \\"pi\\".\\"total_amount\\", \\"je\\".\\"total_debit\\", NULLIF(\\"bsl\\".\\"debit_amount\\", (0)::numeric), \\"bsl\\".\\"credit_amount\\") AS \\"amount\\",\n            COALESCE(\\"fe\\".\\"transaction_currency\\", \\"fe\\".\\"currency_code\\", \\"fe\\".\\"payment_currency\\", \\"fe\\".\\"bank_account_currency\\", \\"rv\\".\\"transaction_currency\\", \\"rv\\".\\"currency_code\\", \\"rv\\".\\"payment_currency\\", \\"rv\\".\\"bank_account_currency\\", \\"pv\\".\\"transaction_currency\\", \\"pv\\".\\"currency_code\\", (\\"pv\\".\\"payment_currency\\")::\\"text\\", \\"pv\\".\\"bank_account_currency\\", \\"l\\".\\"transaction_currency\\", \\"l\\".\\"currency\\", \\"l\\".\\"bank_account_currency\\", \\"lt\\".\\"transaction_currency\\", \\"lt\\".\\"bank_account_currency\\", \\"cc\\".\\"transaction_currency\\", \\"cc\\".\\"bank_account_currency\\", (\\"pi\\".\\"currency\\")::\\"text\\", \\"je\\".\\"transaction_currency\\", \\"je\\".\\"functional_currency\\", \\"bsl\\".\\"currency\\", \\"ba\\".\\"currency\\",\n                CASE\n                    WHEN ((\\"ft\\".\\"id\\" IS NOT NULL) AND (\\"fba\\".\\"currency\\" = \\"tba\\".\\"currency\\")) THEN \\"fba\\".\\"currency\\"\n                    ELSE NULL::\\"text\\"\n                END, 'IDR'::\\"text\\") AS \\"currency\\",\n            COALESCE(\\"expense_supplier\\".\\"company_name\\", (\\"receipt_customer\\".\\"company_name\\")::character varying, \\"payment_supplier\\".\\"company_name\\", (\\"sales_customer\\".\\"company_name\\")::character varying, \\"purchase_supplier\\".\\"company_name\\", (\\"l\\".\\"counterparty_name\\")::character varying, (\\"parent_loan\\".\\"counterparty_name\\")::character varying, (NULLIF((\\"pc\\".\\"paid_to\\")::\\"text\\", ''::\\"text\\"))::character varying) AS \\"customer_supplier\\",\n                CASE\n                    WHEN (\\"ft\\".\\"id\\" IS NOT NULL) THEN \\"con