y\\", (\\"pc\\".\\"expense_category\\")::\\"text\\", \\"je\\".\\"transaction_category\\", \\"l\\".\\"loan_type\\", (\\"cc\\".\\"contribution_type\\")::\\"text\\", \\"tp\\".\\"tax_type\\", (\\"pi\\".\\"purchase_type\\")::\\"text\\", \\"bsl\\".\\"payment_kind\\") AS \\"current_category\\",\n            COALESCE(\\"fe\\".\\"bank_account_id\\", \\"rv\\".\\"bank_account_id\\", \\"pv\\".\\"bank_account_id\\", \\"l\\".\\"bank_account_id\\", \\"lt\\".\\"bank_account_id\\", \\"cc\\".\\"bank_account_id\\", \\"pc\\".\\"bank_account_id\\", \\"tp\\".\\"bank_account_id\\", \\"bsl\\".\\"bank_account_id\\") AS \\"current_bank_account_id\\",\n            \\"source_je\\".\\"id\\" AS \\"journal_entry_id\\",\n            \\"current_line\\".\\"id\\" AS \\"journal_line_id\\",\n            \\"current_line\\".\\"account_id\\" AS \\"current_account_id\\",\n            \\"concat_ws\\"(' · '::\\"text\\", \\"coa\\".\\"code\\", \\"coa\\".\\"name\\") AS \\"current_gl_account\\",\n            \\"fe\\".\\"exchange_rate\\" AS \\"expense_exchange_rate\\",\n            COALESCE(\\"fe\\".\\"pph_code_id\\", \\"pv\\".\\"pph_code_id\\") AS \\"current_tax_code_id\\",\n            COALESCE(\\"fe\\".\\"payment_method\\", \\"rv\\".\\"payment_method\\", \\"pv\\".\\"payment_method\\", (\\"bsl\\".\\"payment_kind\\")::character varying) AS \\"current_payment_type\\",\n            \\"source_je\\".\\"source_module\\" AS \\"current_document_classification\\",\n            COALESCE(\\"si\\".\\"faktur_pajak_number\\", \\"pi\\".\\"faktur_pajak_number\\") AS \\"current_faktur_pajak_number\\"\n           FROM ((((((((((((((((\\"unresolved\\" \\"u\\"\n             LEFT JOIN \\"public\\".\\"finance_expenses\\" \\"fe\\" ON (((\\"u\\".\\"document_type\\" = 'expense'::\\"text\\") AND (\\"fe\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n             LEFT JOIN \\"public\\".\\"receipt_vouchers\\" \\"rv\\" ON (((\\"u\\".\\"document_type\\" = 'receipt'::\\"text\\") AND (\\"rv\\".\\"id\\" = \\"u\\".\\"document_id\\"))))\n          