.\\"created_at\\",\n                    \\"jl\\".\\"transaction_currency\\",\n                    \\"jl\\".\\"transaction_debit\\",\n                    \\"jl\\".\\"transaction_credit\\",\n                    \\"jl\\".\\"functional_currency\\",\n                    \\"jl\\".\\"exchange_rate\\"\n                   FROM \\"public\\".\\"journal_entry_lines\\" \\"jl\\"\n                  WHERE (\\"jl\\".\\"journal_entry_id\\" = \\"source_je\\".\\"id\\")\n                  ORDER BY\n                        CASE\n                            WHEN ((\\"u\\".\\"document_type\\" = 'bank_reconciliation'::\\"text\\") AND (((COALESCE(\\"bsl\\".\\"credit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF(\\"jl\\".\\"transaction_debit\\", (0)::numeric), \\"jl\\".\\"debit\\") = \\"bsl\\".\\"credit_amount\\")) OR ((COALESCE(\\"bsl\\".\\"debit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF(\\"jl\\".\\"transaction_credit\\", (0)::numeric), \\"jl\\".\\"credit\\") = \\"bsl\\".\\"debit_amount\\")))) THEN 0\n                            WHEN (\\"jl\\".\\"account_id\\" = COALESCE(\\"l\\".\\"coa_id\\", \\"rv\\".\\"coa_account_id\\", \\"pv\\".\\"coa_account_id\\", \\"fe\\".\\"fixed_asset_account_id\\")) THEN 0\n                            ELSE 1\n                        END, \\"jl\\".\\"line_number\\"\n                 LIMIT 1) \\"current_line\\" ON (true))\n             LEFT JOIN \\"public\\".\\"chart_of_accounts\\" \\"coa\\" ON ((\\"coa\\".\\"id\\" = \\"current_line\\".\\"account_id\\")))\n        ), \\"business_rows\\" AS (\n         SELECT \\"e\\".\\"row_id\\",\n            \\"e\\".\\"exception_id\\",\n            \\"e\\".\\"run_id\\",\n            \\"e\\".\\"document_type\\",\n            \\"e\\".\\"document_id\\",\n            \\"e\\".\\"date\\",\n            \\"e\\".\\"voucher_number\\",\n            \\"e\\".\\"journal_number\\",\n            \\"e\\".\\"amount\\",\n            \\"e\\".\\"currency\\",\n            \\"e\\".\\"bank\\",\n            \\"e\\".\\"customer_supplier\\",\n            \\"e\\".\\"classification\\",\n            \\"e\\".\\"reason\\",\n            \\"e\\".\\"manual_information_required\\",\n            \\"e\\".\\"recommended_action\\",\n            \\"e\\".\\"inconsistent_fields\\",\n            \\"e\\".\\"current_category\\",\n            \\"e\\".\\"current_bank_account_id\\",\n            \\"e\\".\\"journal_entry_id\\",\n            \\"e\\".\\"journal_line_id\\",\n            \\"e\\".\\"current_account_id\\",\n            \\"e\\".\\"current_gl_account\\",\n            \\"e\\".\\"expense_exchange_rate\\",\n            \\"e\\".\\"current_tax_code_id\\",\n            \\"e\\".\\"current_payment_type\\",\n            \\"e\\".\\"current_document_classification\\",\n            \\"e\\".\\"current_faktur_pajak_number\\",\n                CASE\n                    WHEN (\\"e\\".\\"reason\\" ~~* 'No unique authoritative relationship%'::\\"text\\") THEN 'The historical record is missing a confirmed payment method, bank, currency, or exchange rate.'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%no historical transaction-date rate%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%no authoritative historical rate%'::\\"text\\")) THEN 'The transaction is confirmed as foreign currency, but its original exchange rate is missing.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%USD-source Contra%'::\\"text\\") THEN 'The transfer used an older foreign-currency treatment that cannot be corrected without an accountant decision.'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%does not post to this bank account%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%does not use the Expense bank account%'::\\"text\\")) THEN 'The voucher and bank transaction are linked, but the journal uses a different account.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%amount or direction does not match%'::\\"text\\") THEN 'The amount or money-in/money-out direction differs between the bank transaction and journal.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%missing Faktur Pajak%'::\\"text\\") THEN 'A taxed invoice is missing its Faktur Pajak number.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%without an accrued payable%'::\\"text\\") THEN 'A tax payment exists without the earlier tax amount being recorded as payable.'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%no active journal%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%no provable active journal%'::\\"text\\")) THEN 'The document does not have a confirmed active journal.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%metadata conflicts%'::\\"text\\") THEN 'The voucher details conflict with the linked bank transaction.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%Journal metadata cannot be derived%'::\\"text\\") THEN 'The journal source or classification cannot be confirmed from the historical record.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%no native Loan source document%'::\\"text\\") THEN 'The journal is loan-related, but its original loan document is missing.'::\\"text\\"\n                    ELSE 'The historical record needs an accountant to confirm its correct classification.'::\\"text\\"\n                END AS \\"problem\\",\n                CASE\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%no historical transaction-date rate%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%no authoritative historical rate%'::\\"text\\")) THEN 'The application must not guess a historical exchange rate.'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%USD-source Contra%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%amount or direction does not match%'::\\"text\\")) THEN 'Correcting it automatically could change the meaning of posted accounting amounts.'::\\"text\\"\n                    WHEN ((\\"e\\".\\"reason\\" ~~* '%no active journal%'::\\"text\\") OR (\\"e\\".\\"reason\\" ~~* '%no native Loan source document%'::\\"text\\")) THEN 'No existing source-to-journal relationship proves a safe automatic correction.'::\\"text\\"\n                    WHEN (\\"e\\".\\"reason\\" ~~* '%without an accrued payable%'::\\"text\\") THEN 'Only an accountant can confirm whether an accrual or reclassification is appropriate.'::\\"text\\"\n                    ELSE 'More than one correction is possible from the available historical information.'::\\"text\\"\n                END AS \\"why_not_automatic\\"\n           FROM \\"enriched\\" \\"e\\"\n        )\n SELECT \\"business_rows\\".\\"row_id\\",\n    \\"business_rows\\".\\"exception_id\\",\n    \\"business_rows\\".\\"run_id\\",\n    \\"business_rows\\".\\"document_type\\",\n    \\"business_rows\\".\\"document_id\\",\n    \\"business_rows\\".\\"date\\",\n    \\"business_rows\\".\\"voucher_number\\",\n    \\"business_rows\\".\\"journal_number\\",\n    \\"business_rows\\".\\"amount\\",\n    \\"business_rows\\".\\"currency\\",\n    \\"business_rows\\".\\"bank\\",\n    \\"business_rows\\".\\"customer_supplier\\",\n    \\"business_rows\\".\\"current_category\\",\n    \\"business_rows\\".\\"current_gl_account\\",\n    'Needs accountant review'::\\"text\\" AS \\"status\\",\n    \\"business_rows\\".\\"problem\\",\n    \\"business_rows\\".\\"why_not_automatic\\",\n    \\"business_rows\\".\\"recommended_action\\",\n    \\"business_rows\\".\\"current_bank_account_id\\",\n    \\"business_rows\\".\\"journal_entry_id\\",\n    \\"business_rows\\".\\"journal_line_id\\",\n    \\"business_rows\\".\\"current_account_id\\",\n    \\"business_rows\\".\\"current_tax_code_id\\",\n    \\"business_rows\\".\\"current_payment_type\\",\n    \\"business_rows\\".\\"current_document_classification\\",\n    \\"business_rows\\".\\"current_faktur_pajak_number\\",\n    \\"business_rows\\".\\"expense_exchange_rate\\"\n   FROM \\"business_rows\\"\nUNION ALL\n SELECT ((('verification:'::\\"text\\" || \\"vf\\".\\"document_type\\") || ':'::\\"text\\") || (\\"vf\\".\\"database_id\\")::\\"text\\") AS \\"row_id\\",\n    NULL::bigint AS \\"exception_id\\",\n    \\"vf\\".\\"run_id\\",\n    \\"vf\\".\\"document_type\\",\n    \\"vf\\".\\"database_id\\" AS \\"document_id\\",\n    NULL::\\"date\\" AS \\"date\\",\n    COALESCE(\\"vf\\".\\"document_number\\", '(none)'::\\"text\\") AS \\"voucher_number\\",\n    NULL::\\"text\\" AS \\"journal_number\\",\n    NULL::numeric AS \\"amount\\",\n    'Unknown'::\\"text\\" AS \\"currency\\",\n    NULL::\\"text\\" AS \\"bank\\",\n    NULL::\\"text\\" AS \\"customer_supplier\\",\n    NULL::\\"text\\" AS \\"current_category\\",\n    NULL::\\"text\\" AS \\"current_gl_account\\",\n    'Verification failed'::\\"text\\" AS \\"status\\",\n    'A Finance verification check still fails for this record.'::\\"text\\" AS \\"problem\\",\n    'The current Finance data does not yet satisfy every report check.'::\\"text\\" AS \\"why_not_automatic\\",\n    'Review the source document, journal and linked bank transaction, then save the confirmed classifications.'::\\"text\\" AS \\"recommended_action\\",\n    NULL::\\"uuid\\" AS \\"current_bank_account_id\\",\n    NULL::\\"uuid\\" AS \\"journal_entry_id\\",\n    NULL::\\"uuid\\" AS \\"journal_line_id\\",\n    NULL::\\"uuid\\" AS \\"current_account_id\\",\n    NULL::\\"uuid\\" AS \\"current_tax_code_id\\",\n    NULL::\\"text\\" AS \\"current_payment_type\\",\n    NULL::\\"text\\" AS \\"current_document_classification\\",\n    NULL::\\"text\\" AS \\"current_faktur_pajak_number\\",\n    NULL::numeric AS \\"expense_exchange_rate\\"\n   FROM \\"public\\".\\"finance_historical_repair_verification_failures\\" \\"vf\\"\n  WHERE (NOT (EXISTS ( SELECT 1\n           FROM \\"unresolved\\" \\"u\\"\n          WHERE ((\\"u\\".\\"run_id\\" = \\"vf\\".\\"run_id\\") AND (\\"u\\".\\"document_type\\" = \\"vf\\".\\"document_type\\") AND (\\"u\\".\\"document_id\\" = \\"vf\\".\\"database_id\\")))))","--\n-- Name: finance_historical_repair_runs; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"finance_historical_repair_runs\\" (\n    \\"id\\" \\"uuid\\" DEFAULT \\"gen_random_uuid\\"() NOT NULL,\n    \\"started_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    \\"completed_at\\" timestamp with time zone,\n    \\"total_records_scanned\\" bigint DEFAULT 0 NOT NULL,\n    \\"records_repaired\\" bigint DEFAULT 0 NOT NULL,\n    \\"records_partially_repaired\\" bigint DEFAULT 0 NOT NULL,\n    \\"records_manual_review\\" bigint DEFAULT 0 NOT NULL,\n    \\"records_skipped\\" bigint DEFAULT 0 NOT NULL,\n    \\"notes\\" \\"text\\"\n)","--\n-- Name: finance_historical_repair_summary; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"finance_historical_repair_summary\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"id\\" AS \\"run_id\\",\n    \\"started_at\\",\n    \\"completed_at\\",\n    \\"total_records_scanned\\",\n    \\"records_repaired\\",\n    \\"records_partially_repaired\\",\n    \\"records_manual_review\\",\n    \\"records_skipped\\",\n    \\"notes\\"\n   FROM \\"public\\".\\"finance_historical_repair_runs\\"","--\n-- Name: finance_legacy_accepted_documents; Type: TABLE; Schema: public; Owner: -\n--\n\nCREATE TABLE \\"public\\".\\"finance_legacy_accepted_documents\\" (\n    \\"document_type\\" \\"text\\" NOT NULL,\n    \\"document_id\\" \\"uuid\\" NOT NULL,\n    \\"classification\\" \\"text\\" NOT NULL,\n    \\"acceptance_reason\\" \\"text\\" NOT NULL,\n    \\"accepted_at\\" timestamp with time zone DEFAULT \\"now\\"() NOT NULL,\n    CONSTRAINT \\"finance_legacy_accepted_documents_classification_check\\" CHECK ((\\"classification\\" = 'legacy_accepted'::\\"text\\")),\n    CONSTRAINT \\"finance_legacy_accepted_documents_document_type_check\\" CHECK ((\\"document_type\\" = 'fund_transfer'::\\"text\\"))\n)","--\n-- Name: unbalanced_journal_entries; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"unbalanced_journal_entries\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"id\\",\n    \\"entry_number\\",\n    \\"entry_date\\",\n    \\"total_debit\\",\n    \\"total_credit\\",\n    (\\"total_debit\\" - \\"total_credit\\") AS \\"difference\\",\n    \\"description\\",\n    \\"created_at\\"\n   FROM \\"public\\".\\"journal_entries\\"\n  WHERE ((\\"abs\\"((\\"total_debit\\" - \\"total_credit\\")) >= 0.01) AND (NOT ((\\"total_debit\\" = (0)::numeric) AND (\\"total_credit\\" = (0)::numeric))))\n  ORDER BY \\"created_at\\" DESC","--\n-- Name: finance_live_verification_failures; Type: VIEW; Schema: public; Owner: -\n--\n\nCREATE VIEW \\"public\\".\\"finance_live_verification_failures\\" WITH (\\"security_invoker\\"='true') AS\n WITH \\"bank_failures\\" AS (\n         SELECT \\"b\\".\\"id\\",\n            \\"b\\".\\"upload_id\\",\n            \\"b\\".\\"bank_account_id\\",\n            \\"b\\".\\"transaction_date\\",\n            \\"b\\".\\"description\\",\n            \\"b\\".\\"reference\\",\n            \\"b\\".\\"branch_code\\",\n            \\"b\\".\\"debit_amount\\",\n            \\"b\\".\\"credit_amount\\",\n            \\"b\\".\\"running_balance\\",\n            \\"b\\".\\"currency\\",\n            \\"b\\".\\"reconciliation_status\\",\n            \\"b\\".\\"matched_entry_id\\",\n            \\"b\\".\\"matched_expense_id\\",\n            \\"b\\".\\"matched_receipt_id\\",\n            \\"b\\".\\"matched_at\\",\n            \\"b\\".\\"matched_by\\",\n            \\"b\\".\\"notes\\",\n            \\"b\\".\\"created_by\\",\n            \\"b\\".\\"created_at\\",\n            \\"b\\".\\"statement_balance\\",\n            \\"b\\".\\"transaction_hash\\",\n            \\"b\\".\\"matched_petty_cash_id\\",\n            \\"b\\".\\"matched_fund_transfer_id\\",\n            \\"b\\".\\"paid_by\\",\n            \\"b\\".\\"matching_status\\",\n            \\"b\\".\\"manually_unlinked\\",\n            \\"b\\".\\"payment_kind\\",\n            \\"b\\".\\"matched_tax_payment_id\\",\n            \\"b\\".\\"matched_payment_id\\",\n            \\"ba\\".\\"coa_id\\" AS \\"bank_coa_id\\",\n            \\"ba\\".\\"bank_name\\",\n            \\"ba\\".\\"account_name\\",\n            \\"ba\\".\\"account_number\\",\n            \\"ba\\".\\"currency\\" AS \\"bank_currency\\",\n            \\"je\\".\\"id\\" AS \\"active_journal_id\\",\n            \\"je\\".\\"entry_number\\",\n                CASE\n                    WHEN (\\"ba\\".\\"coa_id\\" IS NULL) THEN 'The selected bank is missing its posting account.'::\\"text\\"\n                    WHEN (\\"je\\".\\"id\\" IS NULL) THEN 'The linked bank transaction has no active journal.'::\\"text\\"\n                    WHEN (NOT (EXISTS ( SELECT 1\n                       FROM \\"public\\".\\"journal_entry_lines\\" \\"x\\"\n                      WHERE ((\\"x\\".\\"journal_entry_id\\" = \\"je\\".\\"id\\") AND (\\"x\\".\\"account_id\\" = \\"ba\\".\\"coa_id\\"))))) THEN 'The linked journal uses a different account from the Bank Master.'::\\"text\\"\n                    ELSE 'The amount or money-in/money-out direction differs between the bank transaction and journal.'::\\"text\\"\n                END AS \\"problem\\"\n           FROM ((\\"public\\".\\"bank_statement_lines\\" \\"b\\"\n             LEFT JOIN \\"public\\".\\"bank_accounts\\" \\"ba\\" ON ((\\"ba\\".\\"id\\" = \\"b\\".\\"bank_account_id\\")))\n             LEFT JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON (((\\"je\\".\\"id\\" = \\"b\\".\\"matched_entry_id\\") AND (\\"je\\".\\"is_posted\\" = true) AND (COALESCE(\\"je\\".\\"is_reversed\\", false) = false))))\n          WHERE (((\\"b\\".\\"reconciliation_status\\" = ANY (ARRAY['matched'::\\"text\\", 'recorded'::\\"text\\"])) OR (\\"b\\".\\"matched_entry_id\\" IS NOT NULL)) AND ((\\"ba\\".\\"coa_id\\" IS NULL) OR (\\"je\\".\\"id\\" IS NULL) OR (NOT (EXISTS ( SELECT 1\n                   FROM \\"public\\".\\"journal_entry_lines\\" \\"x\\"\n                  WHERE ((\\"x\\".\\"journal_entry_id\\" = \\"je\\".\\"id\\") AND (\\"x\\".\\"account_id\\" = \\"ba\\".\\"coa_id\\") AND (((COALESCE(\\"b\\".\\"credit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(\\"b\\".\\"debit_amount\\", (0)::numeric) = (0)::numeric) AND (COALESCE(NULLIF(\\"x\\".\\"transaction_debit\\", (0)::numeric), \\"x\\".\\"debit\\") = \\"b\\".\\"credit_amount\\")) OR ((COALESCE(\\"b\\".\\"debit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(\\"b\\".\\"credit_amount\\", (0)::numeric) = (0)::numeric) AND (COALESCE(NULLIF(\\"x\\".\\"transaction_credit\\", (0)::numeric), \\"x\\".\\"credit\\") = \\"b\\".\\"debit_amount\\")))))))))\n        ), \\"bank_rows\\" AS (\n         SELECT ('live:bank_reconciliation:'::\\"text\\" || (\\"b\\".\\"id\\")::\\"text\\") AS \\"row_id\\",\n            NULL::bigint AS \\"exception_id\\",\n            ( SELECT \\"finance_historical_repair_summary\\".\\"run_id\\"\n                   FROM \\"public\\".\\"finance_historical_repair_summary\\"\n                  ORDER BY \\"finance_historical_repair_summary\\".\\"started_at\\" DESC\n                 LIMIT 1) AS \\"run_id\\",\n            'bank_reconciliation'::\\"text\\" AS \\"document_type\\",\n            \\"b\\".\\"id\\" AS \\"document_id\\",\n            \\"b\\".\\"transaction_date\\" AS \\"date\\",\n            COALESCE(NULLIF(\\"b\\".\\"reference\\", ''::\\"text\\"), 'Bank transaction'::\\"text\\") AS \\"voucher_number\\",\n            (\\"b\\".\\"entry_number\\")::\\"text\\" AS \\"journal_number\\",\n            (COALESCE(NULLIF(\\"b\\".\\"debit_amount\\", (0)::numeric), \\"b\\".\\"credit_amount\\"))::numeric AS \\"amount\\",\n            COALESCE(\\"b\\".\\"currency\\", \\"b\\".\\"bank_currency\\", 'Unknown'::\\"text\\") AS \\"currency\\",\n            \\"concat_ws\\"(' · '::\\"text\\", \\"b\\".\\"bank_name\\", \\"b\\".\\"account_name\\", \\"b\\".\\"account_number\\", \\"b\\".\\"bank_currency\\") AS \\"bank\\",\n            COALESCE(\\"c\\".\\"company_name\\", (\\"s\\".\\"company_name\\")::\\"text\\") AS \\"customer_supplier\\",\n            \\"b\\".\\"payment_kind\\" AS \\"current_category\\",\n            \\"concat_ws\\"(' · '::\\"text\\", \\"coa\\".\\"code\\", \\"coa\\".\\"name\\") AS \\"current_gl_account\\",\n            'Verification failed'::\\"text\\" AS \\"status\\",\n            \\"b\\".\\"problem\\",\n            'The current bank link does not satisfy the Bank Master, amount and direction checks.'::\\"text\\" AS \\"why_not_automatic\\",\n            'Review the original bank transaction and source document, then select the confirmed bank and account. If the amounts differ, ask the accountant whether a formal correction is required.'::\\"text\\" AS \\"recommended_action\\",\n            \\"b\\".\\"bank_account_id\\" AS \\"current_bank_account_id\\",\n            \\"b\\".\\"active_journal_id\\" AS \\"journal_entry_id\\",\n            \\"current_line\\".\\"id\\" AS \\"journal_line_id\\",\n            \\"current_line\\".\\"account_id\\" AS \\"current_account_id\\",\n            NULL::\\"uuid\\" AS \\"current_tax_code_id\\",\n            \\"b\\".\\"payment_kind\\" AS \\"current_payment_type\\",\n            (\\"je\\".\\"source_module\\")::\\"text\\" AS \\"current_document_classification\\",\n            NULL::\\"text\\" AS \\"current_faktur_pajak_number\\",\n            NULL::numeric AS \\"expense_exchange_rate\\"\n           FROM ((((((((\\"bank_failures\\" \\"b\\"\n             LEFT JOIN \\"public\\".\\"journal_entries\\" \\"je\\" ON ((\\"je\\".\\"id\\" = \\"b\\".\\"active_journal_id\\")))\n             LEFT JOIN \\"public\\".\\"receipt_vouchers\\" \\"rv\\" ON ((\\"rv\\".\\"id\\" = \\"b\\".\\"matched_receipt_id\\")))\n             LEFT JOIN \\"public\\".\\"payment_vouchers\\" \\"pv\\" ON ((\\"pv\\".\\"id\\" = \\"b\\".\\"matched_payment_id\\")))\n             LEFT JOIN \\"public\\".\\"finance_expenses\\" \\"fe\\" ON ((\\"fe\\".\\"id\\" = \\"b\\".\\"matched_expense_id\\")))\n             LEFT JOIN \\"public\\".\\"customers\\" \\"c\\" ON ((\\"c\\".\\"id\\" = \\"rv\\".\\"customer_id\\")))\n             LEFT JOIN \\"public\\".\\"suppliers\\" \\"s\\" ON ((\\"s\\".\\"id\\" = COALESCE(\\"pv\\".\\"supplier_id\\", \\"fe\\".\\"supplier_id\\"))))\n             LEFT JOIN LATERAL ( SELECT \\"x\\".\\"id\\",\n                    \\"x\\".\\"account_id\\"\n                   FROM \\"public\\".\\"journal_entry_lines\\" \\"x\\"\n                  WHERE (\\"x\\".\\"journal_entry_id\\" = \\"b\\".\\"active_journal_id\\")\n                  ORDER BY\n                        CASE\n                            WHEN (((COALESCE(\\"b\\".\\"credit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF(\\"x\\".\\"transaction_debit\\", (0)::numeric), \\"x\\".\\"debit\\") = \\"b\\".\\"credit_amount\\")) OR ((COALESCE(\\"b\\".\\"debit_amount\\", (0)::numeric) > (0)::numeric) AND (COALESCE(NULLIF(\\"x\\".\\"transaction_credit\\", (0)::numeric), \\"x\\".\\"credit\\") = \\"b\\".\\"debit_amount\\"))) THEN 0\n                            ELSE 1\n                        END, \\"x\\".\\"line_number\\"\n                 LIMIT 1) \\"current_line\\" ON (true))\n             LEFT JOIN \\"public\\".\\"chart_of_accounts\\" \\"coa\\" ON ((\\"coa\\".\\"id\\" = \\"current_line\\".\\"account_id\\")))\n        ), \\"journal_rows\\" AS (\n         SELECT ('live:journal:'::\\"text\\" || (\\"u\\".\\"id\\")::\\"text\\") AS \\"?column?\\",\n            NULL::bigint AS \\"int8\\",\n            ( SELECT \\"finance_historical_repair_summary\\".\\"run_id\\"\n                   FROM \\"public\\".\\"finance_historical_repair_summary\\"\n                  ORDER BY \\"finance_historical_repair_summary\\".\\"started_at\\" DESC\n                 LIMIT 1) AS \\"run_id\\",\n            'journal'::\\"text\\" AS \\"text\\",\n            \\"u\\".\\"id\\",\n            \\"u\\".\\"entry_date\\",\n            (\\"u\\".\\"entry_number\\")::\\"text\\" AS \\"entry_number\\",\n            (\\"u\\".\\"entry_number\\")::\\"text\\" AS \\"entry_number\\",\n            (\\"u\\".\\"total_deb