\\" USING \\"btree\\" (\\"source_module\\", \\"reference_id\\") WHERE (((\\"source_module\\")::\\"text\\" = 'petty_cash'::\\"text\\") AND (\\"reference_id\\" IS NOT NULL))","--\n-- Name: uniq_journal_entries_source_ref_number; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uniq_journal_entries_source_ref_number\\" ON \\"public\\".\\"journal_entries\\" USING \\"btree\\" (\\"source_module\\", \\"reference_number\\") WHERE ((\\"reference_number\\" IS NOT NULL) AND (\\"source_module\\" IS NOT NULL) AND (NOT COALESCE(\\"is_reversed\\", false)))","--\n-- Name: uniq_petty_cash_resolved_tx_id; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uniq_petty_cash_resolved_tx_id\\" ON \\"public\\".\\"journal_entries\\" USING \\"btree\\" (\\"source_module\\", \\"public\\".\\"petty_cash_resolved_tx_id\\"(\\"reference_id\\", (\\"reference_number\\")::\\"text\\")) WHERE (((\\"source_module\\")::\\"text\\" = 'petty_cash'::\\"text\\") AND (\\"public\\".\\"petty_cash_resolved_tx_id\\"(\\"reference_id\\", (\\"reference_number\\")::\\"text\\") IS NOT NULL))","--\n-- Name: uq_active_bank_document_journal; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_active_bank_document_journal\\" ON \\"public\\".\\"journal_entries\\" USING \\"btree\\" (\\"source_module\\", \\"reference_id\\") WHERE ((\\"reference_id\\" IS NOT NULL) AND (\\"is_posted\\" = true) AND (COALESCE(\\"is_reversed\\", false) = false) AND ((\\"reference_number\\")::\\"text\\" IS DISTINCT FROM (\\"entry_number\\")::\\"text\\") AND ((\\"source_module\\")::\\"text\\" = ANY ((ARRAY['expenses'::character varying, 'payment'::character varying, 'receipt'::character varying, 'petty_cash'::character varying, 'fund_transfers'::character varying, 'tax_payment'::character varying])::\\"text\\"[])))","--\n-- Name: uq_active_customer_normalized_name; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_active_customer_normalized_name\\" ON \\"public\\".\\"customers\\" USING \\"btree\\" (\\"public\\".\\"normalize_customer_identity\\"(\\"company_name\\")) WHERE (COALESCE(\\"is_active\\", true) AND (\\"public\\".\\"normalize_customer_identity\\"(\\"company_name\\") <> ''::\\"text\\"))","--\n-- Name: uq_active_customer_normalized_npwp; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_active_customer_normalized_npwp\\" ON \\"public\\".\\"customers\\" USING \\"btree\\" (\\"public\\".\\"normalize_customer_tax_id\\"(\\"npwp\\")) WHERE (COALESCE(\\"is_active\\", true) AND (\\"public\\".\\"normalize_customer_tax_id\\"(\\"npwp\\") <> ''::\\"text\\"))","--\n-- Name: uq_active_fund_transfer_from_statement; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_active_fund_transfer_from_statement\\" ON \\"public\\".\\"fund_transfers\\" USING \\"btree\\" (\\"from_bank_statement_line_id\\") WHERE ((\\"from_bank_statement_line_id\\" IS NOT NULL) AND (\\"status\\" <> ALL (ARRAY['cancelled'::\\"text\\", 'reversed'::\\"text\\"])))","--\n-- Name: uq_active_fund_transfer_to_statement; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_active_fund_transfer_to_statement\\" ON \\"public\\".\\"fund_transfers\\" USING \\"btree\\" (\\"to_bank_statement_line_id\\") WHERE ((\\"to_bank_statement_line_id\\" IS NOT NULL) AND (\\"status\\" <> ALL (ARRAY['cancelled'::\\"text\\", 'reversed'::\\"text\\"])))","--\n-- Name: uq_dc_batch_allocation_active_item; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_dc_batch_allocation_active_item\\" ON \\"public\\".\\"dc_batch_allocations\\" USING \\"btree\\" (\\"delivery_challan_item_id\\") WHERE (\\"status\\" = 'consumed'::\\"text\\")","--\n-- Name: uq_dc_batch_allocation_operation; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_dc_batch_allocation_operation\\" ON \\"public\\".\\"dc_batch_allocations\\" USING \\"btree\\" (\\"operation_id\\", \\"delivery_challan_item_id\\")","--\n-- Name: uq_finance_expenses_voucher_number; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_finance_expenses_voucher_number\\" ON \\"public\\".\\"finance_expenses\\" USING \\"btree\\" (\\"voucher_number\\") WHERE (\\"voucher_number\\" IS NOT NULL)","--\n-- Name: uq_import_req_so_product_active; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_import_req_so_product_active\\" ON \\"public\\".\\"import_requirements\\" USING \\"btree\\" (\\"sales_order_id\\", \\"product_id\\") WHERE (\\"status\\" = ANY (ARRAY['pending'::\\"public\\".\\"import_status\\", 'ordered'::\\"public\\".\\"import_status\\", 'rfq_sent'::\\"public\\".\\"import_status\\", 'po_created'::\\"public\\".\\"import_status\\", 'supplier_confirmed'::\\"public\\".\\"import_status\\", 'in_production'::\\"public\\".\\"import_status\\", 'ready_to_ship'::\\"public\\".\\"import_status\\", 'in_transit'::\\"public\\".\\"import_status\\", 'customs_clearance'::\\"public\\".\\"import_status\\"]))","--\n-- Name: uq_sales_invoice_items_invoice_dc_item; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_sales_invoice_items_invoice_dc_item\\" ON \\"public\\".\\"sales_invoice_items\\" USING \\"btree\\" (\\"invoice_id\\", \\"delivery_challan_item_id\\")","--\n-- Name: uq_so_product_reservation_active_item; Type: INDEX; Schema: public; Owner: -\n--\n\nCREATE UNIQUE INDEX \\"uq_so_product_reservation_active_item\\" ON \\"public\\".\\"so_product_reservations\\" USING \\"btree\\" (\\"sales_order_item_id\\") WHERE (\\"status\\" = 'active'::\\"text\\")","--\n-- Name: inventory_v1_conservation_reconciliation _RETURN; Type: RULE; Schema: public; Owner: -\n--\n\nCREATE OR REPLACE VIEW \\"public\\".\\"inventory_v1_conservation_reconciliation\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"b\\".\\"id\\" AS \\"batch_id\\",\n    \\"b\\".\\"batch_number\\",\n    \\"b\\".\\"import_quantity\\",\n    \\"b\\".\\"current_stock\\",\n    \\"b\\".\\"reserved_stock\\",\n    \\"sum\\"(\\"l\\".\\"effective_quantity\\") AS \\"effective_ledger_quantity\\",\n    (\\"sum\\"(\\"l\\".\\"effective_quantity\\") - \\"b\\".\\"current_stock\\") AS \\"conservation_error\\",\n    (COALESCE(\\"b\\".\\"current_stock\\", (0)::numeric) < (0)::numeric) AS \\"negative_stock\\",\n    (COALESCE(\\"b\\".\\"reserved_stock\\", (0)::numeric) > COALESCE(\\"b\\".\\"current_stock\\", (0)::numeric)) AS \\"reserved_exceeds_current\\"\n   FROM (\\"public\\".\\"batches\\" \\"b\\"\n     JOIN \\"public\\".\\"inventory_v1_effective_ledger\\" \\"l\\" ON (((\\"l\\".\\"batch_id\\" = \\"b\\".\\"id\\") AND \\"l\\".\\"is_effective\\")))\n  GROUP BY \\"b\\".\\"id\\"","--\n-- Name: product_sources_with_stats _RETURN; Type: RULE; Schema: public; Owner: -\n--\n\nCREATE OR REPLACE VIEW \\"public\\".\\"product_sources_with_stats\\" WITH (\\"security_invoker\\"='true') AS\n SELECT \\"ps\\".\\"id\\",\n    \\"ps\\".\\"product_id\\",\n    \\"ps\\".\\"supplier_id\\",\n    \\"ps\\".\\"supplier_name\\",\n    \\"ps\\".\\"grade\\",\n    \\"ps\\".\\"country\\",\n    \\"ps\\".\\"remarks\\",\n    \\"ps\\".\\"created_by\\",\n    \\"ps\\".\\"created_at\\",\n    \\"ps\\".\\"updated_at\\",\n    \\"s\\".\\"company_name\\" AS \\"supplier_company_name\\",\n    \\"count\\"(DISTINCT \\"psd\\".\\"id\\") AS \\"document_count\\",\n    \\"array_agg\\"(DISTINCT \\"psd\\".\\"doc_type\\") FILTER (WHERE (\\"psd\\".\\"doc_type\\" IS NOT NULL)) AS \\"available_doc_types\\"\n   FROM ((\\"public\\".\\"product_sources\\" \\"ps\\"\n     LEFT JOIN \\"public\\".\\"suppliers\\" \\"s\\" ON ((\\"ps\\".\\"supplier_id\\" = \\"s\\".\\"id\\")))\n     LEFT JOIN \\"public\\".\\"product_source_documents\\" \\"psd\\" ON ((\\"ps\\".\\"id\\" = \\"psd\\".\\"source_id\\")))\n  GROUP BY \\"ps\\".\\"id\\", \\"s\\".\\"company_name\\"","--\n-- Name: vw_input_ppn_report _RETURN; Type: RULE; Schema: public; Owner: -\n--\n\nCREATE OR REPLACE VIEW \\"public\\".\\"vw_input_ppn_report\\" WITH (\\"security_invoker\\"='true') AS\n WITH \\"tax_lines\\" AS (\n         SELECT \\"je\\".\\"id\\" AS \\"journal_id\\",\n            \\"je\\".\\"entry_date\\",\n            \\"je\\".\\"source_module\\",\n            \\"je\\".\\"reference_id\\",\n            \\"je\\".\\"reference_number\\",\n            \\"je\\".\\"description\\",\n            \\"je\\".\\"created_at\\",\n            \\"je\\".\\"total_debit\\",\n            \\"sum\\"((\\"jel\\".\\"debit\\" - \\"jel\\".\\"credit\\")) AS \\"ppn_amount\\"\n           FROM ((\\"public\\".\\"journal_entries\\" \\"je\\"\n             JOIN \\"public\\".\\"journal_entry_lines\\" \\"jel\\" ON ((\\"jel\\".\\"journal_entry_id\\" = \\"je\\".\\"id\\")))\n             JOIN \\"public\\".\\"chart_of_accounts\\" \\"coa\\" ON ((\\"coa\\".\\"id\\" = \\"jel\\".\\"account_id\\")))\n          WHERE ((\\"je\\".\\"is_posted\\" = true) AND (COALESCE(\\"je\\".\\"is_reversed\\", false) = false) AND ((\\"coa\\".\\"code\\")::\\"text\\" = '1150'::\\"text\\"))\n          GROUP BY \\"je\\".\\"id\\"\n         HAVING (\\"sum\\"((\\"jel\\".\\"debit\\" - \\"jel\\".\\"credit\\")) > (0)::numeric)\n        )\n SELECT \\"date_trunc\\"('month'::\\"text\\", (\\"t\\".\\"entry_date\\")::timestamp with time zone) AS \\"month\\",\n    \\"t\\".\\"entry_date\\" AS \\"expense_date\\",\n        CASE\n            WHEN ((\\"t\\".\\"source_module\\")::\\"text\\" = 'purchase_invoice'::\\"text\\") THEN 'Purchase Invoice'::\\"text\\"\n            WHEN (\\"fe\\".\\"expense_category\\" = 'pib_import'::\\"text\\") THEN 'PIB Import'::\\"text\\"\n            WHEN (\\"fe\\".\\"expense_category\\" = 'ppn_import'::\\"text\\") THEN 'PPN Import (Legacy)'::\\"text\\"\n            ELSE 'Supplier Invoice'::\\"text\\"\n        END AS \\"document_type\\",\n    COALESCE(\\"pi\\".\\"invoice_number\\", \\"fe\\".\\"invoice_number\\", (\\"fe\\".\\"voucher_number\\")::character varying, \\"t\\".\\"reference_number\\", ((\\"t\\".\\"journal_id\\")::\\"text\\")::character varying) AS \\"reference\\",\n    COALESCE(\\"s\\".\\"company_name\\", '-'::character varying) AS \\"supplier\\",\n    COALESCE(\\"s\\".\\"npwp\\", '-'::character varying) AS \\"supplier_npwp\\",\n        CASE\n            WHEN (\\"fe\\".\\"expense_category\\" = 'import_broker'::\\"text\\") THEN (COALESCE(\\"fe\\".\\"dpp_amount\\", (0)::numeric) + COALESCE(( SELECT \\"sum\\"(COALESCE((NULLIF((\\"item\\".\\"value\\" ->> 'dpp_amount'::\\"text\\"), ''::\\"text\\"))::numeric, (0)::numeric)) AS \\"sum\\"\n               FROM \\"jsonb_array_elements\\"(COALESCE(\\"fe\\".\\"broker_items\\", '[]'::\\"jsonb\\")) \\"item\\"(\\"value\\")), (0)::numeric))\n            ELSE GREATEST((\\"t\\".\\"total_debit\\" - \\"t\\".\\"ppn_amount\\"), (0)::numeric)\n        END AS \\"dpp_amount\\",\n    \\"t\\".\\"ppn_amount\\",\n    COALESCE(\\"fe\\".\\"description\\", \\"pi\\".\\"notes\\", \\"t\\".\\"description\\") AS \\"description\\",\n    \\"t\\".\\"created_at\\",\n    COALESCE(\\"fe\\".\\"tax_period_id\\", \\"pi\\".\\"tax_period_id\\", \\"date_period\\".\\"id\\") AS \\"tax_period_id\\"\n   FROM ((((\\"tax_lines\\" \\"t\\"\n     LEFT JOIN \\"public\\".\\"finance_expenses\\" \\"fe\\" ON ((((\\"t\\".\\"source_module\\")::\\"text\\" = ANY ((ARRAY['expense'::character varying, 'expenses'::character varying])::\\"text\\"[])) AND (\\"fe\\".\\"id\\" = \\"t\\".\\"reference_id\\"))))\n     LEFT JOIN \\"public\\".\\"purchase_invoices\\" \\"pi\\" ON ((((\\"t\\".\\"source_module\\")::\\"text\\" = 'purchase_invoice'::\\"text\\") AND (\\"pi\\".\\"id\\" = \\"t\\".\\"reference_id\\"))))\n     LEFT JOIN \\"public\\".\\"suppliers\\" \\"s\\" ON ((\\"s\\".\\"id\\" = COALESCE(\\"fe\\".\\"supplier_id\\", \\"pi\\".\\"supplier_id\\"))))\n     LEFT JOIN \\"public\\".\\"tax_periods\\" \\"date_period\\" ON (((\\"date_period\\".\\"tax_type\\" = 'PPN'::\\"text\\") AND ((\\"t\\".\\"entry_date\\" >= \\"date_period\\".\\"period_start\\") AND (\\"t\\".\\"entry_date\\" <= \\"date_period\\".\\"period_end\\")))))\n  ORDER BY \\"t\\".\\"entry_date\\" DESC","--\n-- Name: vw_output_ppn_report _RETURN; Type: RULE; Schema: public; Owner: -\