ds tax_periods_select; Type: POLICY; Schema: public; Owner: -\n--\n\nCREATE POLICY \\"tax_periods_select\\" ON \\"public\\".\\"tax_periods\\" FOR SELECT TO \\"authenticated\\" USING (true)","--\n-- Name: tax_periods tax_periods_write; Type: POLICY; Schema: public; Owner: -\n--\n\nCREATE POLICY \\"tax_periods_write\\" ON \\"public\\".\\"tax_periods\\" TO \\"authenticated\\" USING ((EXISTS ( SELECT 1\n   FROM \\"public\\".\\"user_profiles\\" \\"up\\"\n  WHERE ((\\"up\\".\\"id\\" = ( SELECT \\"auth\\".\\"uid\\"() AS \\"uid\\")) AND (\\"up\\".\\"role\\" = ANY (ARRAY['admin'::\\"text\\", 'manager'::\\"text\\"])) AND (\\"up\\".\\"is_active\\" = true))))) WITH CHECK ((EXISTS ( SELECT 1\n   FROM \\"public\\".\\"user_profiles\\" \\"up\\"\n  WHERE ((\\"up\\".\\"id\\" = ( SELECT \\"auth\\".\\"uid\\"() AS \\"uid\\")) AND (\\"up\\".\\"role\\" = ANY (ARRAY['admin'::\\"text\\", 'manager'::\\"text\\"])) AND (\\"up\\".\\"is_active\\" = true)))))","--\n-- Name: user_permissions; Type: ROW SECURITY; Schema: public; Owner: -\n--\n\nALTER TABLE \\"public\\".\\"user_permissions\\" ENABLE ROW LEVEL SECURITY","--\n-- Name: user_profiles; Type: ROW SECURITY; Schema: public; Owner: -\n--\n\nALTER TABLE \\"public\\".\\"user_profiles\\" ENABLE ROW LEVEL SECURITY","--\n-- Name: finance_utility_master utility_master_read; Type: POLICY; Schema: public; Owner: -\n--\n\nCREATE POLICY \\"utility_master_read\\" ON \\"public\\".\\"finance_utility_master\\" FOR SELECT TO \\"authenticated\\" USING (true)","--\n-- Name: finance_utility_master utility_master_write; Type: POLICY; Schema: public; Owner: -\n--\n\nCREATE POLICY \\"utility_master_write\\" ON \\"public\\".\\"finance_utility_master\\" TO \\"authenticated\\" USING ((EXISTS ( SELECT 1\n   FROM \\"public\\".\\"user_profiles\\" \\"up\\"\n  WHERE ((\\"up\\".\\"id\\" = ( SELECT \\"auth\\".\\"uid\\"() AS \\"uid\\")) AND (\\"up\\".\\"role\\" = ANY (ARRAY['admin'::\\"text\\", 'accounts'::\\"text\\"])))))) WITH CHECK ((EXISTS ( SELECT 1\n   FROM \\"public\\".\\"user_profiles\\" \\"up\\"\n  WHERE ((\\"up\\".\\"id\\" = ( SELECT \\"auth\\".\\"uid\\"() AS \\"uid\\")) AND (\\"up\\".\\"role\\" = ANY (ARRAY['admin'::\\"text\\", 'accounts'::\\"text\\"]))))))","--\n-- Name: vendor_bills; Type: ROW SECURITY; Schema: public; Owner: -\n--\n\nALTER TABLE \\"public\\".\\"vendor_bills\\" ENABLE ROW LEVEL SECURITY","--\n-- Name: vendor_payments; Type: ROW SECURITY; Schema: public; Owner: -\n--\n\nALTER TABLE \\"public\\".\\"vendor_payments\\" ENABLE ROW LEVEL SECURITY","--\n-- Name: voucher_allocations; Type: ROW SECURITY; Schema: public; Owner: -\n--\n\nALTER TABLE \\"public\\".\\"voucher_allocations\\" ENABLE ROW LEVEL SECURITY","--\n-- PostgreSQL database dump complete\n--\n\n\\\\unrestrict p4dDvfJKMAPflf6Y6lvwxsqHEmvs4JLZol8szZ3ggy5cSe8RyULrkIhbGngSFj5"}	canonical_baseline	\N	\N	\N
20260905190000	{"-- PPh withholding periods are determined by the expense/document date unless\n-- an explicit pph_tax_period_id was selected.  Due dates are payment terms,\n-- not the withholding month; using them moved August PPh23 into September.\n-- This migration changes reporting/recomputation only and posts no journals.\nBEGIN","-- Central date resolver used by PPh recomputation triggers.  An explicit\n-- pph_tax_period_id remains the manual override; otherwise the source\n-- document's expense date is the established PPh period basis.\nCREATE OR REPLACE FUNCTION public.get_expense_pph_period_date(p_expense_id uuid)\nRETURNS date\nLANGUAGE sql STABLE SECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\n  SELECT fe.expense_date\n  FROM public.finance_expenses fe\n  WHERE fe.id = p_expense_id;\n$$","CREATE OR REPLACE FUNCTION public.fn_pph_authoritative_source_total(p_period_id uuid)\nRETURNS numeric LANGUAGE sql STABLE SET search_path = public AS $$\n  WITH period AS (\n    SELECT id, fiscal_year, period_month, tax_type, period_start, period_end\n      FROM public.tax_periods WHERE id = p_period_id AND tax_type <> 'PPN'\n  )\n  SELECT COALESCE((\n    SELECT SUM(fe.pph_amount)\n      FROM period p\n      JOIN public.finance_expenses fe\n        ON (fe.pph_tax_period_id = p.id\n            OR (fe.pph_tax_period_id IS NULL AND fe.expense_date BETWEEN p.period_start AND p.period_end))\n      JOIN public.effective_expense_posting_state eps ON eps.expense_id = fe.id\n       AND eps.effective_posting_state IN ('ACTIVE','REPLACED')\n      LEFT JOIN public.tax_codes tc ON tc.id = fe.pph_code_id\n     WHERE fe.approval_status = 'approved' AND fe.pph_amount > 0\n       AND COALESCE(fe.expense_category,'') NOT IN ('pib_import','pph_import')\n       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)\n  ),0) + COALESCE((\n    SELECT SUM(pv.pph_amount) FROM period p\n      JOIN public.payment_vouchers pv ON (pv.tax_period_id = p.id\n        OR (pv.tax_period_id IS NULL AND pv.voucher_date BETWEEN p.period_start AND p.period_end))\n      LEFT JOIN public.tax_codes tc ON tc.id = pv.pph_code_id\n     WHERE COALESCE(pv.is_posted,false) AND pv.pph_amount > 0\n       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)\n  ),0) + COALESCE((\n    SELECT SUM(CASE WHEN fe.expense_category='pib_import' THEN COALESCE(fe.pib_pph_amount,0) ELSE COALESCE(fe.amount,0) END)\n      FROM period p JOIN public.finance_expenses fe ON (fe.pph_tax_period_id = p.id\n        OR (fe.pph_tax_period_id IS NULL AND fe.expense_date BETWEEN p.period_start AND p.period_end))\n      JOIN public.effective_expense_posting_state eps ON eps.expense_id = fe.id\n       AND eps.effective_posting_state IN ('ACTIVE','REPLACED')\n     WHERE p.tax_type IN ('PPh22','PPh_Unifikasi') AND fe.approval_status='approved'\n       AND fe.expense_category IN ('pib_import','pph_import')\n  ),0);\n$$","-- Keep the stored-total recomputation on the same authoritative basis.\nCREATE OR REPLACE FUNCTION public.compute_period_ppn(p_period_id uuid)\nRETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$\nDECLARE v_period public.tax_periods%rowtype; v_pph_total numeric(18,2);\nBEGIN\n  PERFORM public.compute_period_ppn_pre_posted_register(p_period_id);\n  SELECT * INTO v_period FROM public.tax_periods WHERE id=p_period_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Tax period % not found',p_period_id; END IF;\n  IF v_period.tax_type='PPN' THEN RETURN; END IF;\n  SELECT COALESCE(public.fn_pph_authoritative_source_total(p_period_id),0)\n    + COALESCE((SELECT sum(tp.amount) FROM public.tax_payments tp\n      WHERE tp.tax_period_id=p_period_id AND tp.tax_type=v_period.tax_type\n        AND tp.historical_source_status='missing_source_verified'),0)\n    INTO v_pph_total;\n  UPDATE public.tax_periods SET pph_total=v_pph_total,updated_at=now() WHERE id=p_period_id;\nEND; $$","CREATE OR REPLACE VIEW public.vw_canonical_tax_period_amounts AS\nWITH amounts AS (\n SELECT tp.*, public.fn_tax_payments_paid(tp.id) actual_paid,\n   CASE WHEN public.fn_tax_payments_paid(tp.id)>0.01\n          OR tp.status IN ('paid','filed','closed') THEN tp.pph_total\n        ELSE public.fn_pph_authoritative_source_total(tp.id) END::numeric(18,2) resolved_pph_total\n FROM public.tax_periods tp\n)\nSELECT id tax_period_id,fiscal_year,period_month,tax_type,status,filing_status,\n payment_due_date,filing_due_date,input_ppn_total,output_ppn_total,net_ppn,\n CASE WHEN tax_type='PPN' THEN 0::numeric(18,2) ELSE resolved_pph_total END pph_total,\n CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END::numeric(18,2) total_tax,\n actual_paid paid_amount,\n GREATEST((CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END)-actual_paid,0) outstanding_amount,\n GREATEST(actual_paid-(CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END),0) overpaid_amount,\n (CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END)-actual_paid net_position,\n public.fn_tax_period_payment_status(status,CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END,actual_paid,payment_due_date) payment_status,\n public.fn_period_payment_source(CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END,actual_paid,0) payment_source,\n (SELECT count(*) FROM public.tax_payments p WHERE p.tax_period_id=amounts.id AND p.status='reconciled') reconciled_payments_count,\n (SELECT count(*) FROM public.tax_payments p WHERE p.tax_period_id=amounts.id AND p.status IN ('draft','posted')) unreconciled_payments_count,\n (SELECT count(*) FROM public.sales_invoices si WHERE si.tax_period_id=amounts.id AND COALESCE(si.faktur_pajak_number,'')='' AND si.tax_amount>0) missing_faktur_count\nFROM amounts","CREATE OR REPLACE VIEW public.vw_pph_by_period_type AS\nSELECT tax_period_id,fiscal_year,period_month,tax_type,pph_total,paid_amount pph_paid_total,\n outstanding_amount pph_outstanding,status,payment_due_date,filing_due_date,payment_status,\n payment_source,net_position pph_net_position,overpaid_amount pph_overpaid\nFROM public.vw_canonical_tax_period_amounts WHERE tax_type <> 'PPN'","CREATE OR REPLACE VIEW public.vw_tax_period_status AS\nSELECT c.tax_period_id id,c.fiscal_year,c.period_month,c.tax_type,c.status,c.filing_status,\n c.payment_due_date,c.filing_due_date,c.net_ppn,c.pph_total,\n c.reconciled_payments_count,c.unreconciled_payments_count,c.missing_faktur_count,\n c.paid_amount,c.outstanding_amount,c.payment_status,c.payment_source,c.net_position,c.overpaid_amount\nFROM public.vw_canonical_tax_period_amounts c","GRANT SELECT ON public.vw_canonical_tax_period_amounts, public.vw_pph_by_period_type, public.vw_tax_period_status TO authenticated","NOTIFY pgrst, 'reload schema'",COMMIT}	fix_pph23_tax_period_basis	\N	\N	\N
20260905200000	{"-- Forward-only COGS cost snapshots for newly posted sales invoices.\n-- Historical sales_invoice_items remain NULL; no journals are backfilled.\nBEGIN","ALTER TABLE public.sales_invoice_items\n  ADD COLUMN IF NOT EXISTS cogs_unit_cost numeric(15,2),\n  ADD COLUMN IF NOT EXISTS cogs_total_cost numeric(15,2)","CREATE OR REPLACE FUNCTION public.post_sales_invoice_cogs()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_existing_cogs_je_id UUID;\n  v_je_id UUID;\n  v_je_number TEXT;\n  v_cogs_account_id UUID;\n  v_inventory_account_id UUID;\n  v_item RECORD;\n  v_total_cogs NUMERIC := 0;\n  v_snapshot_item_ids uuid[] := ARRAY[]::uuid[];\n  v_snapshot_unit_costs numeric[] := ARRAY[]::numeric[];\n  v_snapshot_total_costs numeric[] := ARRAY[]::numeric[];\nBEGIN\n  IF NEW.journal_entry_id IS NULL THEN RETURN NEW; END IF;\n  IF NEW.payment_status NOT IN ('pending', 'partial', 'paid') THEN RETURN NEW; END IF;\n\n  SELECT id INTO v_existing_cogs_je_id\n    FROM public.journal_entries\n   WHERE source_module = 'sales_invoice_cogs' AND reference_id = NEW.id\n   LIMIT 1;\n  IF v_existing_cogs_je_id IS NOT NULL THEN RETURN NEW; END IF;\n\n  SELECT id INTO v_cogs_account_id FROM public.chart_of_accounts WHERE code = '5100' LIMIT 1;\n  SELECT id INTO v_inventory_account_id FROM public.chart_of_accounts WHERE code = '1130' LIMIT 1;\n  IF v_cogs_account_id IS NULL OR v_inventory_account_id IS NULL THEN\n    RAISE EXCEPTION\n      'post_sales_invoice_cogs: chart_of_accounts is missing 5100 (COGS) or 1130 (Inventory). Cannot post COGS for invoice %.',\n      NEW.invoice_number;\n  END IF;\n\n  -- Preserve the existing batch-cost calculation exactly.\n  FOR v_item IN\n    SELECT sii.id, sii.quantity, sii.batch_id,\n           COALESCE(NULLIF(b.landed_cost_per_unit, 0),\n                    NULLIF(b.import_price, 0),\n                    NULLIF(b.cost_per_unit, 0), 0) AS effective_cost\n      FROM public.sales_invoice_items sii\n      LEFT JOIN public.batches b ON b.id = sii.batch_id\n     WHERE sii.invoice_id = NEW.id AND sii.batch_id IS NOT NULL\n  LOOP\n    -- Stage the exact effective cost used by the existing calculation.  The\n    -- rows are written only after a positive COGS posting is guaranteed.\n    v_snapshot_item_ids := array_append(v_snapshot_item_ids, v_item.id);\n    v_snapshot_unit_costs := array_append(v_snapshot_unit_costs, v_item.effective_cost);\n    v_snapshot_total_costs := array_append(v_snapshot_total_costs,\n      ROUND(COALESCE(v_item.quantity, 0) * v_item.effective_cost, 2));\n    v_total_cogs := v_total_cogs + (COALESCE(v_item.quantity, 0) * v_item.effective_cost);\n  END LOOP;\n\n  IF v_total_cogs <= 0 THEN RETURN NEW; END IF;\n\n  -- Snapshot only as part of a successful COGS posting.  The idempotency\n  -- guard above leaves every already-posted (including historical) line as-is.\n  UPDATE public.sales_invoice_items sii\n     SET cogs_unit_cost = s.unit_cost,\n         cogs_total_cost = s.total_cost\n    FROM unnest(v_snapshot_item_ids, v_snapshot_unit_costs, v_snapshot_total_costs)\n      AS s(item_id, unit_cost, total_cost)\n   WHERE sii.id = s.item_id;\n\n  v_je_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries (\n    entry_number, entry_date, source_module, reference_id, reference_number,\n    description, total_debit, total_credit, is_posted, posted_by, created_by\n  ) VALUES (\n    v_je_number, NEW.invoice_date, 'sales_invoice_cogs', NEW.id, NEW.invoice_number,\n    'COGS for Sales Invoice: ' || NEW.invoice_number,\n    v_total_cogs, v_total_cogs, true, NEW.created_by, NEW.created_by\n  ) RETURNING id INTO v_je_id;\n\n  INSERT INTO public.journal_entry_lines\n    (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, 1, v_cogs_account_id, 'COGS - ' || NEW.invoice_number,\n          v_total_cogs, 0, NEW.customer_id);\n  INSERT INTO public.journal_entry_lines\n    (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, 2, v_inventory_account_id, 'Inventory - ' || NEW.invoice_number,\n          0, v_total_cogs, NEW.customer_id);\n\n  RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n  RAISE LOG 'post_sales_invoice_cogs failed for invoice %: %', NEW.id, SQLERRM;\n  RAISE;\nEND;\n$$","COMMENT ON FUNCTION public.post_sales_invoice_cogs() IS\n  'Posts unchanged COGS JE and snapshots effective batch cost on newly posted sales_invoice_items; historical rows are not backfilled.'",COMMIT}	add_future_cogs_snapshots	\N	\N	\N
20260905210000	{"-- Use posted sales COGS journals and forward line snapshots for profitability.\n-- This changes reporting only; no accounting or historical data is written.\nBEGIN","CREATE OR REPLACE FUNCTION public.get_monthly_sales_report(p_start_date date, p_end_date date)\nRETURNS TABLE(month_label text, month_start date, total_sales numeric, total_orders bigint,\n  total_qty_sold numeric, avg_order_value numeric, total_cogs numeric, gross_profit numeric,\n  profit_pct numeric, outbound_delivery numeric, operational_profit numeric, costed_lines bigint, total_lines bigint)\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$\nWITH inv AS (\n SELECT si.id,si.invoice_date,si.invoice_number,\n   sum(sii.quantity*sii.unit_price) sales,sum(sii.quantity) qty,count(*) lines,\n   coalesce(sum(sii.cogs_total_cost),0) snap_cost,\n   coalesce((SELECT sum(jel.debit-jel.credit) FROM journal_entry_lines jel JOIN chart_of_accounts coa ON coa.id=jel.account_id\n      JOIN journal_entries je ON je.id=jel.journal_entry_id WHERE je.source_module='sales_invoice_cogs' AND je.reference_id=si.id\n      AND je.is_posted AND NOT coalesce(je.is_reversed,false) AND coa.code='5100'),0) je_cost,\n   count(*) FILTER (WHERE sii.cogs_total_cost IS NOT NULL) costed\n FROM sales_invoices si JOIN sales_invoice_items sii ON sii.invoice_id=si.id\n WHERE si.invoice_date BETWEEN p_start_date AND p_end_date AND NOT coalesce(si.is_draft,false)\n GROUP BY si.id,si.invoice_date,si.invoice_number\n), lines AS (\n SELECT *,CASE WHEN costed=lines AND costed>0 THEN snap_cost WHEN lines=1 AND je_cost>0 THEN je_cost ELSE NULL END authoritative_cost\n FROM inv\n), monthly AS (\n SELECT date_trunc('month',invoice_date)::date month_start,to_char(date_trunc('month',invoice_date),'Mon YYYY') month_label,\n   sum(sales) total_sales,count(*) total_orders,sum(qty) total_qty_sold,sum(je_cost) total_cogs,\n   sum(authoritative_cost) FILTER (WHERE authoritative_cost IS NOT NULL) costed_cogs\n FROM lines GROUP BY 1,2\n), expenses AS (\n SELECT date_trunc('month',expense_date)::date month_start,coalesce(sum(amount),0) outbound_delivery\n FROM finance_expenses WHERE expense_category IN ('delivery_sales','loading_sales') AND approval_status='approved'\n   AND expense_date BETWEEN p_start_date AND p_end_date GROUP BY 1\n)\nSELECT m.month_label,m.month_start,round(m.total_sales,2),m.total_orders,m.total_qty_sold,\n round(m.total_sales/nullif(m.total_orders,0),2),round(coalesce(m.total_cogs,0),2),\n round(coalesce(m.total_sales,0)-coalesce(m.total_cogs,0),2),\n CASE WHEN m.total_sales=0 THEN NULL ELSE round((m.total_sales-coalesce(m.total_cogs,0))/m.total_sales*100,2) END,\n round(coalesce(e.outbound_delivery,0),2),round(m.total_sales-coalesce(m.total_cogs,0)-coalesce(e.outbound_delivery,0),2),\n (SELECT coalesce(sum(costed),0) FROM lines x WHERE date_trunc('month',x.invoice_date)::date=m.month_start),\n (SELECT coalesce(sum(lines),0) FROM lines x WHERE date_trunc('month',x.invoice_date)::date=m.month_start)\nFROM monthly m LEFT JOIN expenses e USING(month_start) ORDER BY m.month_start;\n$$","CREATE OR REPLACE FUNCTION public.get_sales_profitability_summary(p_start_date date,p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$\nWITH inv AS (\n SELECT si.id,si.invoice_date,sii.product_id,sii.batch_id,sii.quantity,sii.unit_price,\n   round(sii.quantity*sii.unit_price,2) sales,sii.cogs_total_cost,sii.cogs_unit_cost,\n   (SELECT sum(jel.debit-jel.credit) FROM journal_entry_lines jel JOIN chart_of_accounts coa ON coa.id=jel.account_id JOIN journal_entries je ON je.id=jel.journal_entry_id\n    WHERE je.source_module='sales_invoice_cogs' AND je.reference_id=si.id AND je.is_posted AND NOT coalesce(je.is_reversed,false) AND coa.code='5100') je_cost\n FROM sales_invoices si JOIN sales_invoice_items sii ON sii.invoice_id=si.id\n WHERE si.invoice_date BETWEEN p_start_date AND p_end_date AND NOT coalesce(si.is_draft,false)\n), invoice_cost AS (\n SELECT id,coalesce(max(je_cost),0) je_cost,count(*) lines,count(*) FILTER(WHERE cogs_total_cost IS NOT NULL) costed,\n   coalesce(sum(cogs_total_cost),0) snap_cost,max(invoice_date) invoice_date,sum(sales) sales,sum(quantity) quantity\n FROM inv GROUP BY id\n), resolved AS (\n SELECT i.*,CASE WHEN c.costed=c.lines AND c.costed>0 THEN i.cogs_total_cost WHEN c.lines=1 AND c.je_cost>0 THEN c.je_cost ELSE NULL END line_cost,\n   c.je_cost invoice_cogs FROM inv i JOIN invoice_cost c ON c.id=i.id\n), products AS (\n SELECT p.id product_id,p.product_name,coalesce(p.product_code,'') product_code,coalesce(p.unit,'kg') product_unit,\n   coalesce((SELECT sum(current_stock) FROM batches b0 WHERE b0.product_id=p.id AND b0.is_active),0) current_stock,\n   sum(r.quantity) sold_qty,sum(r.sales) gross_sales,sum(r.line_cost) product_cost,\n   count(*) FILTER(WHERE r.line_cost IS NOT NULL) costed_lines,count(*) total_lines\n FROM products p JOIN resolved r ON r.product_id=p.id GROUP BY p.id,p.product_name,p.product_code,p.unit\n), company AS (\n SELECT coalesce(sum(c.sales),0) gross_sales,coalesce(sum(c.je_cost),0) product_cost,\n   coalesce(sum(c.quantity),0) total_qty_sold,count(*) order_count,(SELECT count(distinct product_id) FROM resolved) product_count\n FROM invoice_cost c\n), monthly AS (\n SELECT to_char(date_trunc('month',invoice_date),'Mon YYYY') month_label,date_trunc('month',invoice_date)::date month_start,\n   sum(sales) gross_sales,sum(je_cost) product_cost,sum(quantity) total_qty_sold,count(*) order_count\n FROM invoice_cost GROUP BY 1,2\n)\nSELECT jsonb_build_object(\n 'company',jsonb_build_object('gross_sales',c.gross_sales,'product_cost',c.product_cost,'sales_expenses',0,'unallocated_sales_expenses',0,\n   'gross_profit',c.gross_sales-c.product_cost,'profit_after_sales_expenses',c.gross_sales-c.product_cost,\n   'profit_margin_pct',case when c.gross_sales=0 then null else round((c.gross_sales-c.product_cost)/c.gross_sales*100,2) end,\n   'total_qty_sold',c.total_qty_sold,'order_count',c.order_count,'product_count',c.product_count),\n 'products',coalesce((select jsonb_agg(to_jsonb(p)) from products p),'[]'::jsonb),\n 'monthly',coalesce((select jsonb_agg(jsonb_build_object('month_label',m.month_label,'month_start',m.month_start,'gross_sales',m.gross_sales,'product_cost',m.product_cost,'sales_expenses',0,'gross_profit',m.gross_sales-m.product_cost,'profit_after_sales_expenses',m.gross_sales-m.product_cost,'profit_margin_pct',case when m.gross_sales=0 then null else round((m.gross_sales-m.product_cost)/m.gross_sales*100,2) end,'total_qty_sold',m.total_qty_sold,'order_count',m.order_count) order by m.month_start) from monthly m),'[]'::jsonb))\nFROM company c;\n$$","-- Drill-down functions retain their established response shape but source line\n-- costs exclusively from snapshots, with the documented single-line fallback.\nCREATE OR REPLACE FUNCTION public.get_sales_profitability_batch_orders(p_batch_id uuid,p_start_date date,p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$\nWITH x AS (\n SELECT sii.id line_id,si.id invoice_id,si.invoice_number,si.invoice_date,si.customer_id,coalesce(c.company_name,'Unknown Customer') customer_name,\n   si.sales_order_id,so.so_number,sii.quantity,sii.unit_price,round(sii.quantity*sii.unit_price,2) line_gross_sales,sii.cogs_unit_cost,\n   CASE WHEN sii.cogs_total_cost IS NOT NULL THEN sii.cogs_total_cost WHEN (SELECT count(*) FROM sales_invoice_items z WHERE z.invoice_id=si.id)=1 THEN\n      (SELECT sum(jel.debit-jel.credit) FROM journal_entry_lines jel JOIN chart_of_accounts coa ON coa.id=jel.account_id JOIN journal_entries je ON je.id=jel.journal_entry_id WHERE je.source_module='sales_invoice_cogs' AND je.reference_id=si.id AND je.is_posted AND NOT coalesce(je.is_reversed,false) AND coa.code='5100') ELSE NULL END line_cost\n FROM sales_invoice_items sii JOIN sales_invoices si ON si.id=sii.invoice_id LEFT JOIN customers c ON c.id=si.customer_id LEFT JOIN sales_orders so ON so.id=si.sales_order_id\n WHERE sii.batch_id=p_batch_id AND si.invoice_date BETWEEN p_start_date AND p_end_date AND NOT coalesce(si.is_draft,false)\n)\nSELECT jsonb_build_object('batch',(SELECT to_jsonb(b) FROM (SELECT b.id batch_id,b.batch_number,p.product_name,b.current_stock FROM batches b JOIN products p ON p.id=b.product_id WHERE b.id=p_batch_id) b),\n 'orders',coalesce((SELECT jsonb_agg(jsonb_build_object('line_id',line_id,'invoice_id',invoice_id,'invoice_number',invoice_number,'invoice_date',invoice_date,'customer_id',customer_id,'customer_name',customer_name,'sales_order_id',sales_order_id,'so_number',so_number,'quantity',quantity,'unit_price',unit_price,'selling_price',unit_price,'gross_sales',line_gross_sales,'unit_cost',cogs_unit_cost,'line_cost',line_cost,'gross_profit',case when line_cost is null then null else line_gross_sales-line_cost end) order by invoice_date desc) FROM x),'[]'::jsonb));\n$$","CREATE OR REPLACE FUNCTION public.get_sales_profitability_product_batches(p_product_id uuid,p_start_date date,p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$\nWITH x0 AS (SELECT sii.batch_id,sii.quantity,round(sii.quantity*sii.unit_price,2) sales,sii.cogs_total_cost,sii.cogs_unit_cost,si.id invoice_id,\n (SELECT count(*) FROM sales_invoice_items z WHERE z.invoice_id=si.id) invoice_lines,\n (SELECT sum(jel.debit-jel.credit) FROM journal_entry_lines jel JOIN chart_of_accounts coa ON coa.id=jel.account_id JOIN journal_entries je ON je.id=jel.journal_entry_id\n  WHERE je.source_module='sales_invoice_cogs' AND je.reference_id=si.id AND je.is_posted AND NOT coalesce(je.is_reversed,false) AND coa.code='5100') je_cost\n FROM sales_invoice_items sii JOIN sales_invoices si ON si.id=sii.invoice_id WHERE sii.product_id=p_product_id AND si.invoice_date BETWEEN p_start_date AND p_end_date AND NOT coalesce(si.is_draft,false)),\n x AS (SELECT *,CASE WHEN cogs_total_cost IS NOT NULL THEN cogs_total_cost WHEN invoice_lines=1 AND je_cost IS NOT NULL THEN je_cost ELSE NULL END line_cost FROM x0),\n s AS (SELECT batch_id,sum(quantity) sold_qty,sum(sales) gross_sales,sum(line_cost) product_cost,count(*) total_lines,count(*) FILTER(WHERE line_cost IS NOT NULL) costed_lines,\n   CASE WHEN count(*) FILTER(WHERE line_cost IS NOT NULL)=count(*) THEN sum(sales)-sum(line_cost) ELSE NULL END gross_profit,\n   CASE WHEN count(*) FILTER(WHERE line_cost IS NOT NULL)=count(*) AND sum(sales)<>0 THEN round((sum(sales)-sum(line_cost))/sum(sales)*100,2) ELSE NULL END profit_margin_pct,\n   CASE WHEN count(*) FILTER(WHERE line_cost IS NOT NULL)=0 THEN 'unavailable' WHEN count(*) FILTER(WHERE line_cost IS NOT NULL)<count(*) THEN 'partial' ELSE 'complete' END cost_coverage\n FROM x GROUP BY batch_id)\nSELECT jsonb_build_object('product',(SELECT jsonb_build_object('product_id',p.id,'product_name',p.product_name,'product_code',coalesce(p.product_code,''),'product_unit',coalesce(p.unit,'kg'),'sold_qty',coalesce(sum(s.sold_qty),0),'gross_sales',coalesce(sum(s.gross_sales),0),'product_cost',coalesce(sum(s.product_cost),0),'costed_lines',coalesce(sum(s.costed_lines),0),'total_lines',coalesce(sum(s.total_lines),0)) FROM products p LEFT JOIN s ON true WHERE p.id=p_product_id GROUP BY p.id,p.product_name,p.product_code,p.unit),'batches',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM s),'[]'::jsonb));\n$$",COMMIT}	authoritative_sales_profitability_cogs	\N	\N	\N
20260905230000	{"-- Reconstruct report-only historical line COGS when posted accounting and\n-- batch evidence prove the allocation. This migration writes no business data.\n--\n-- Rp1.00 is the maximum permitted reconciliation difference. It accommodates\n-- whole-rupiah/document rounding only; percentage or material tolerances are\n-- deliberately prohibited.\nBEGIN","CREATE OR REPLACE FUNCTION public.get_authoritative_sales_line_cogs(\n  p_start_date date,\n  p_end_date date\n)\nRETURNS TABLE (\n  line_id uuid,\n  invoice_id uuid,\n  product_id uuid,\n  batch_id uuid,\n  quantity numeric,\n  authoritative_cogs numeric,\n  authoritative_unit_cogs numeric,\n  resolution_tier text,\n  invoice_line_count bigint,\n  invoice_product_count bigint,\n  posted_invoice_cogs numeric,\n  base_line_cost numeric,\n  reconciliation_difference numeric\n)\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nWITH posted_cogs AS (\n  SELECT\n    je.reference_id AS invoice_id,\n    SUM(jel.debit - jel.credit) AS posted_invoice_cogs\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.source_module = 'sales_invoice_cogs'\n    AND je.is_posted = true\n    AND NOT COALESCE(je.is_reversed, false)\n    AND coa.code = '5100'\n  GROUP BY je.reference_id\n), line_basis AS (\n  SELECT\n    sii.id AS line_id,\n    sii.invoice_id,\n    sii.product_id,\n    sii.batch_id,\n    sii.quantity,\n    sii.cogs_total_cost AS snapshot_cogs,\n    CASE\n      WHEN COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0)) IS NULL\n        THEN NULL\n      ELSE sii.quantity * COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0))\n    END AS base_line_cost,\n    pc.posted_invoice_cogs\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  LEFT JOIN public.batches b ON b.id = sii.batch_id\n  LEFT JOIN posted_cogs pc ON pc.invoice_id = sii.invoice_id\n  WHERE si.invoice_date BETWEEN p_start_date AND p_end_date\n    AND NOT COALESCE(si.is_draft, false)\n), invoice_evidence AS (\n  SELECT\n    invoice_id,\n    COUNT(*) AS invoice_line_count,\n    COUNT(DISTINCT product_id) AS invoice_product_count,\n    COUNT(*) FILTER (WHERE snapshot_cogs IS NULL) AS unresolved_line_count,\n    COUNT(*) FILTER (WHERE snapshot_cogs IS NULL AND base_line_cost IS NOT NULL) AS unresolved_base_line_count,\n    COALESCE(SUM(snapshot_cogs), 0) AS snapshot_cogs_total,\n    SUM(base_line_cost) FILTER (WHERE snapshot_cogs IS NULL) AS unresolved_base_cost_total,\n    MAX(posted_invoice_cogs) AS posted_invoice_cogs\n  FROM line_basis\n  GROUP BY invoice_id\n), resolved AS (\n  SELECT\n    lb.*,\n    ie.invoice_line_count,\n    ie.invoice_product_count,\n    ie.unresolved_line_count,\n    ie.unresolved_base_line_count,\n    ie.snapshot_cogs_total,\n    ie.unresolved_base_cost_total,\n    ie.posted_invoice_cogs AS invoice_posted_cogs,\n    ie.posted_invoice_cogs - ie.snapshot_cogs_total AS residual_posted_cogs,\n    ABS(ie.unresolved_base_cost_total - (ie.posted_invoice_cogs - ie.snapshot_cogs_total)) AS reconciliation_difference\n  FROM line_basis lb\n  JOIN invoice_evidence ie ON ie.invoice_id = lb.invoice_id\n)\nSELECT\n  r.line_id,\n  r.invoice_id,\n  r.product_id,\n  r.batch_id,\n  r.quantity,\n  CASE\n    -- Tier 1: immutable posting-time snapshot.\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs\n    -- Tier 2: the only invoice line owns all posted invoice COGS.\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN r.invoice_posted_cogs\n    -- Tiers 3/4: allocate only when every unresolved line has usable batch\n    -- evidence and its total agrees with residual posted COGS within Rp1.00.\n    WHEN r.invoice_line_count > 1\n      AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)\n    ELSE NULL\n  END AS authoritative_cogs,\n  CASE\n    WHEN r.quantity = 0 THEN NULL\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs / r.quantity\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN r.invoice_posted_cogs / r.quantity\n    WHEN r.invoice_line_count > 1\n      AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN (r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)) / r.quantity\n    ELSE NULL\n  END AS authoritative_unit_cogs,\n  CASE\n    WHEN r.snapshot_cogs IS NOT NULL THEN 'snapshot'\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN 'single_line_posted_cogs'\n    WHEN r.invoice_line_count > 1\n      AND r.invoice_product_count = 1\n      AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN 'single_product_proven_allocation'\n    WHEN r.invoice_line_count > 1\n      AND r.invoice_product_count > 1\n      AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN 'multi_product_proven_allocation'\n    ELSE 'unresolved'\n  END AS resolution_tier,\n  r.invoice_line_count,\n  r.invoice_product_count,\n  r.invoice_posted_cogs,\n  r.base_line_cost,\n  r.reconciliation_difference\nFROM resolved r;\n$$","COMMENT ON FUNCTION public.get_authoritative_sales_line_cogs(date, date) IS\n  'Read-only historical COGS waterfall: snapshot, single-line posted COGS, then batch-evidence allocation only when it reconciles to active posted GL 5100 within Rp1.00; otherwise NULL.'","CREATE OR REPLACE FUNCTION public.get_sales_profitability_summary(p_start_date date, p_end_date date)\nRETURNS jsonb\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$\nWITH resolved AS (\n  SELECT\n    ar.*,\n    si.invoice_date,\n    ROUND(sii.quantity * sii.unit_price, 2) AS sales,\n    p.product_name,\n    COALESCE(p.product_code, '') AS product_code,\n    COALESCE(p.unit, 'kg') AS product_unit\n  FROM public.get_authoritative_sales_line_cogs(p_start_date, p_end_date) ar\n  JOIN public.sales_invoice_items sii ON sii.id = ar.line_id\n  JOIN public.sales_invoices si ON si.id = ar.invoice_id\n  JOIN public.products p ON p.id = ar.product_id\n), products_report AS (\n  SELECT\n    r.product_id,\n    r.product_name,\n    r.product_code,\n    r.product_unit,\n    COALESCE((SELECT SUM(b.current_stock) FROM public.batches b WHERE b.product_id = r.product_id AND b.is_active), 0) AS current_stock,\n    SUM(r.quantity) AS sold_qty,\n    SUM(r.sales) AS gross_sales,\n    SUM(r.authoritative_cogs) AS product_cost,\n    0::numeric AS sales_expense,\n    CASE WHEN COUNT(r.authoritative_cogs) = COUNT(*) THEN SUM(r.sales) - SUM(r.authoritative_cogs) ELSE NULL END AS gross_profit,\n    CASE WHEN COUNT(r.authoritative_cogs) = COUNT(*) THEN SUM(r.sales) - SUM(r.authoritative_cogs) ELSE NULL END AS profit_after_sales_expense,\n    CASE WHEN COUNT(r.authoritative_cogs) = COUNT(*) THEN ROUND(SUM(r.authoritative_cogs) / NULLIF(SUM(r.quantity), 0), 2) ELSE NULL END AS avg_landed_cost,\n    ROUND(SUM(r.sales) / NULLIF(SUM(r.quantity), 0), 2) AS avg_selling_price,\n    0::numeric AS sales_expense_per_unit,\n    ROUND(SUM(r.sales) / NULLIF(SUM(r.quantity), 0), 2) AS net_selling_price_per_unit,\n    CASE WHEN COUNT(r.authoritative_cogs) = COUNT(*) THEN ROUND((SUM(r.sales) - SUM(r.authoritative_cogs)) / NULLIF(SUM(r.quantity), 0), 2) ELSE NULL END AS profit_per_unit,\n    CASE WHEN COUNT(r.authoritative_cogs) = COUNT(*) AND SUM(r.sales) <> 0\n      THEN ROUND((SUM(r.sales) - SUM(r.authoritative_cogs)) / SUM(r.sales) * 100, 2) ELSE NULL END AS profit_margin_pct,\n    COUNT(r.authoritative_cogs) AS costed_lines,\n    COUNT(*) AS total_lines,\n    COUNT(r.authoritative_cogs) < COUNT(*) AS has_unreported_cost\n  FROM resolved r\n  GROUP BY r.product_id, r.product_name, r.product_code, r.product_unit\n), invoice_scope AS (\n  SELECT invoice_id, MAX(invoice_date) AS invoice_date, MAX(posted_invoice_cogs) AS posted_invoice_cogs,\n    SUM(sales) AS invoice_sales, SUM(quantity) AS invoice_qty\n  FROM resolved GROUP BY invoice_id\n), company AS (\n  SELECT\n    COALESCE(SUM(invoice_sales), 0) AS gross_sales,\n    COALESCE(SUM(posted_invoice_cogs), 0) AS product_cost,\n    COALESCE(SUM(invoice_qty), 0) AS total_qty_sold,\n    COUNT(*) AS order_count,\n    (SELECT COUNT(DISTINCT product_id) FROM resolved) AS product_count\n  FROM invoice_scope\n), monthly AS (\n  SELECT\n    TO_CHAR(DATE_TRUNC('month', i.invoice_date), 'Mon YYYY') AS month_label,\n    DATE_TRUNC('month', i.invoice_date)::date AS month_start,\n    SUM(i.invoice_sales) AS gross_sales,\n    COALESCE(SUM(i.posted_invoice_cogs), 0) AS product_cost,\n    SUM(i.invoice_qty) AS total_qty_sold,\n    COUNT(*) AS order_count\n  FROM invoice_scope i\n  GROUP BY 1, 2\n)\nSELECT jsonb_build_object(\n  'company', jsonb_build_object(\n    'gross_sales', c.gross_sales, 'product_cost', c.product_cost,\n    'sales_expenses', 0, 'unallocated_sales_expenses', 0,\n    'gross_profit', c.gross_sales - c.product_cost,\n    'profit_after_sales_expenses', c.gross_sales - c.product_cost,\n    'profit_margin_pct', CASE WHEN c.gross_sales = 0 THEN NULL ELSE ROUND((c.gross_sales-c.product_cost)/c.gross_sales*100,2) END,\n    'total_qty_sold', c.total_qty_sold, 'order_count', c.order_count, 'product_count', c.product_count\n  ),\n  'products', COALESCE((SELECT jsonb_agg(to_jsonb(p)) FROM (SELECT * FROM products_report ORDER BY product_name) p), '[]'::jsonb),\n  'monthly', COALESCE((SELECT jsonb_agg(jsonb_build_object(\n    'month_label', m.month_label, 'month_start', m.month_start,\n    'gross_sales', m.gross_sales, 'product_cost', m.product_cost, 'sales_expenses', 0,\n    'gross_profit', m.gross_sales-m.product_cost,\n    'profit_after_sales_expenses', m.gross_sales-m.product_cost,\n    'profit_margin_pct', CASE WHEN m.gross_sales=0 THEN NULL ELSE ROUND((m.gross_sales-m.product_cost)/m.gross_sales*100,2) END,\n    'total_qty_sold', m.total_qty_sold, 'order_count', m.order_count\n  )) FROM (SELECT * FROM monthly ORDER BY month_start) m), '[]'::jsonb)\n)\nFROM company c;\n$$","CREATE OR REPLACE FUNCTION public.get_sales_profitability_product_batches(p_product_id uuid, p_start_date date, p_end_date date)\nRETURNS jsonb\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$\nWITH x AS (\n  SELECT\n    ar.*,\n    ROUND(sii.quantity * sii.unit_price, 2) AS sales,\n    b.batch_number,\n    b.current_stock,\n    (b.import_container_id IS NOT NULL OR COALESCE(b.landed_cost_per_unit, 0) > 0) AS is_imported,\n    b.import_price, b.import_price_usd, b.exchange_rate_usd_to_idr,\n    b.duty_charges, b.freight_charges, b.other_charges,\n    b.landed_cost_per_unit, b.cost_per_unit\n  FROM public.get_authoritative_sales_line_cogs(p_start_date, p_end_date) ar\n  JOIN public.sales_invoice_items sii ON sii.id = ar.line_id\n  LEFT JOIN public.batches b ON b.id = ar.batch_id\n  WHERE ar.product_id = p_product_id\n), s AS (\n  SELECT\n    batch_id,\n    COALESCE(batch_number, 'Unassigned Batch') AS batch_number,\n    COALESCE(current_stock, 0) AS current_stock,\n    SUM(quantity) AS sold_qty,\n    SUM(sales) AS gross_sales,\n    SUM(authoritative_cogs) AS product_cost,\n    0::numeric AS sales_expense,\n    CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN SUM(sales)-SUM(authoritative_cogs) ELSE NULL END AS gross_profit,\n    CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN SUM(sales)-SUM(authoritative_cogs) ELSE NULL END AS profit_after_sales_expense,\n    CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN ROUND(SUM(authoritative_cogs)/NULLIF(SUM(quantity),0),2) ELSE NULL END AS cost_per_unit,\n    ROUND(SUM(sales)/NULLIF(SUM(quantity),0),2) AS avg_selling_price,\n    0::numeric AS sales_expense_per_unit,\n    ROUND(SUM(sales)/NULLIF(SUM(quantity),0),2) AS net_selling_price_per_unit,\n    CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN ROUND((SUM(sales)-SUM(authoritative_cogs))/NULLIF(SUM(quantity),0),2) ELSE NULL END AS profit_per_unit,\n    CASE WHEN COUNT(authoritative_cogs)=COUNT(*) AND SUM(sales)<>0 THEN ROUND((SUM(sales)-SUM(authoritative_cogs))/SUM(sales)*100,2) ELSE NULL END AS profit_margin_pct,\n    COUNT(authoritative_cogs) AS costed_lines,\n    COUNT(*) AS total_lines,\n    CASE WHEN COUNT(authoritative_cogs)=0 THEN 'unavailable' WHEN COUNT(authoritative_cogs)<COUNT(*) THEN 'partial' ELSE 'complete' END AS cost_coverage,\n    BOOL_OR(is_imported) AS is_imported,\n    jsonb_build_object(\n      'is_imported', BOOL_OR(is_imported), 'import_price', MAX(import_price),\n      'import_price_usd', MAX(import_price_usd), 'exchange_rate', MAX(exchange_rate_usd_to_idr),\n      'duty_charges', MAX(duty_charges), 'freight_charges', MAX(freight_charges),\n      'other_charges', MAX(other_charges), 'landed_cost_per_unit', MAX(landed_cost_per_unit),\n      'local_cost_per_unit', MAX(cost_per_unit)\n    ) AS cost_breakdown\n  FROM x\n  GROUP BY batch_id, batch_number, current_stock\n), product_report AS (\n  SELECT\n    p.id AS product_id, p.product_name, COALESCE(p.product_code,'') AS product_code,\n    COALESCE(p.unit,'kg') AS product_unit,\n    COALESCE((SELECT SUM(b.current_stock) FROM public.batches b WHERE b.product_id=p.id AND b.is_active),0) AS current_stock,\n    COALESCE(SUM(s.sold_qty),0) AS sold_qty, COALESCE(SUM(s.gross_sales),0) AS gross_sales,\n    SUM(s.product_cost) AS product_cost, 0::numeric AS sales_expense,\n    CASE WHEN COALESCE(SUM(s.costed_lines),0)=COALESCE(SUM(s.total_lines),0) THEN SUM(s.gross_profit) ELSE NULL END AS gross_profit,\n    CASE WHEN COALESCE(SUM(s.costed_lines),0)=COALESCE(SUM(s.total_lines),0) THEN SUM(s.profit_after_sales_expense) ELSE NULL END AS profit_after_sales_expense,\n    CASE WHEN COALESCE(SUM(s.costed_lines),0)=COALESCE(SUM(s.total_lines),0) THEN ROUND(SUM(s.product_cost)/NULLIF(SUM(s.sold_qty),0),2) ELSE NULL END AS avg_landed_cost,\n    ROUND(SUM(s.gross_sales)/NULLIF(SUM(s.sold_qty),0),2) AS avg_selling_price,\n    0::numeric AS sales_expense_per_unit,\n    ROUND(SUM(s.gross_sales)/NULLIF(SUM(s.sold_qty),0),2) AS net_selling_price_per_unit,\n    CASE WHEN COALESCE(SUM(s.costed_lines),0)=COALESCE(SUM(s.total_lines),0) THEN ROUND((SUM(s.gross_sales)-SUM(s.product_cost))/NULLIF(SUM(s.sold_qty),0),2) ELSE NULL END AS profit_per_unit,\n    CASE WHEN COALESCE(SUM(s.costed_lines),0)=COALESCE(SUM(s.total_lines),0) AND SUM(s.gross_sales)<>0 THEN ROUND((SUM(s.gross_sales)-SUM(s.product_cost))/SUM(s.gross_sales)*100,2) ELSE NULL END AS profit_margin_pct,\n    COALESCE(SUM(s.costed_lines),0) AS costed_lines, COALESCE(SUM(s.total_lines),0) AS total_lines\n  FROM public.products p LEFT JOIN s ON true WHERE p.id=p_product_id\n  GROUP BY p.id,p.product_name,p.product_code,p.unit\n)\nSELECT jsonb_build_object(\n  'product', (SELECT to_jsonb(p) FROM product_report p),\n  'batches', COALESCE((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.profit_after_sales_expense DESC NULLS LAST) FROM s), '[]'::jsonb)\n);\n$$","CREATE OR REPLACE FUNCTION public.get_sales_profitability_batch_orders(p_batch_id uuid, p_start_date date, p_end_date date)\nRETURNS jsonb\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$\nWITH x AS (\n  SELECT\n    ar.line_id, ar.invoice_id, si.invoice_number, si.invoice_date, si.customer_id,\n    COALESCE(c.company_name,'Unknown Customer') AS customer_name,\n    si.sales_order_id, so.so_number, dci.challan_id AS dc_id, dc.challan_number AS dc_number,\n    ar.quantity, sii.unit_price AS selling_price,\n    ROUND(ar.quantity*sii.unit_price,2) AS gross_sales,\n    ar.authoritative_unit_cogs AS unit_cost, ar.authoritative_cogs AS line_cost,\n    0::numeric AS line_sales_expense,\n    ROUND(ar.quantity*sii.unit_price,2) AS net_selling_realization,\n    CASE WHEN ar.authoritative_cogs IS NULL THEN NULL ELSE ROUND(ar.quantity*sii.unit_price,2)-ar.authoritative_cogs END AS gross_profit,\n    CASE WHEN ar.authoritative_cogs IS NULL THEN NULL ELSE ROUND(ar.quantity*sii.unit_price,2)-ar.authoritative_cogs END AS profit,\n    CASE WHEN ar.authoritative_cogs IS NULL OR ar.quantity*sii.unit_price=0 THEN NULL\n      ELSE ROUND((ar.quantity*sii.unit_price-ar.authoritative_cogs)/(ar.quantity*sii.unit_price)*100,2) END AS profit_margin_pct,\n    ar.resolution_tier AS cogs_resolution,\n    '[]'::jsonb AS expenses\n  FROM public.get_authoritative_sales_line_cogs(p_start_date,p_end_date) ar\n  JOIN public.sales_invoice_items sii ON sii.id=ar.line_id\n  JOIN public.sales_invoices si ON si.id=ar.invoice_id\n  LEFT JOIN public.customers c ON c.id=si.customer_id\n  LEFT JOIN public.sales_orders so ON so.id=si.sales_order_id\n  LEFT JOIN public.delivery_challan_items dci ON dci.id=sii.delivery_challan_item_id\n  LEFT JOIN public.delivery_challans dc ON dc.id=dci.challan_id\n  WHERE ar.batch_id=p_batch_id\n)\nSELECT jsonb_build_object(\n  'batch', (SELECT jsonb_build_object(\n    'batch_id',b.id,'batch_number',b.batch_number,'product_name',p.product_name,\n    'product_code',COALESCE(p.product_code,''),'product_unit',COALESCE(p.unit,'kg'),\n    'current_stock',b.current_stock\n  ) FROM public.batches b JOIN public.products p ON p.id=b.product_id WHERE b.id=p_batch_id),\n  'orders', COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.invoice_date DESC,x.invoice_number) FROM x),'[]'::jsonb)\n);\n$$","GRANT EXECUTE ON FUNCTION public.get_authoritative_sales_line_cogs(date,date) TO authenticated","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_summary(date,date) TO authenticated","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_product_batches(uuid,date,date) TO authenticated","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_batch_orders(uuid,date,date) TO authenticated",COMMIT}	authoritative_historical_sales_cogs_reconstruction	\N	\N	\N
20260905240000	{"-- Tier 3 product reporting: a multi-line invoice containing exactly one\n-- product proves that product's total COGS from the posted GL 5100 amount even\n-- when current batch fields cannot prove a finer line/batch allocation.\n-- This replaces a read-only report function and writes no business data.\nBEGIN","CREATE OR REPLACE FUNCTION public.get_sales_profitability_summary(p_start_date date, p_end_date date)\nRETURNS jsonb\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$\nWITH resolved AS (\n  SELECT\n    ar.*,\n    si.invoice_date,\n    ROUND(sii.quantity * sii.unit_price, 2) AS sales,\n    p.product_name,\n    COALESCE(p.product_code, '') AS product_code,\n    COALESCE(p.unit, 'kg') AS product_unit\n  FROM public.get_authoritative_sales_line_cogs(p_start_date, p_end_date) ar\n  JOIN public.sales_invoice_items sii ON sii.id = ar.line_id\n  JOIN public.sales_invoices si ON si.id = ar.invoice_id\n  JOIN public.products p ON p.id = ar.product_id\n), invoice_product_evidence AS (\n  SELECT\n    invoice_id,\n    product_id,\n    COUNT(*) AS line_count,\n    COUNT(authoritative_cogs) AS resolved_line_count,\n    MAX(invoice_product_count) AS invoice_product_count,\n    MAX(posted_invoice_cogs) AS posted_invoice_cogs,\n    CASE\n      WHEN COUNT(authoritative_cogs) = COUNT(*) THEN SUM(authoritative_cogs)\n      WHEN MAX(invoice_product_count) = 1 AND MAX(posted_invoice_cogs) IS NOT NULL\n        THEN MAX(posted_invoice_cogs)\n      ELSE NULL\n    END AS authoritative_product_cogs\n  FROM resolved\n  GROUP BY invoice_id, product_id\n), product_costs AS (\n  SELECT\n    product_id,\n    SUM(authoritative_product_cogs) AS product_cost,\n    SUM(line_count) FILTER (WHERE authoritative_product_cogs IS NOT NULL) AS costed_lines,\n    SUM(line_count) AS total_lines\n  FROM invoice_product_evidence\n  GROUP BY product_id\n), product_activity AS (\n  SELECT\n    product_id,\n    MAX(product_name) AS product_name,\n    MAX(product_code) AS product_code,\n    MAX(product_unit) AS product_unit,\n    SUM(quantity) AS sold_qty,\n    SUM(sales) AS gross_sales\n  FROM resolved\n  GROUP BY product_id\n), products_report AS (\n  SELECT\n    a.product_id,\n    a.product_name,\n    a.product_code,\n    a.product_unit,\n    COALESCE((SELECT SUM(b.current_stock) FROM public.batches b WHERE b.product_id=a.product_id AND b.is_active),0) AS current_stock,\n    a.sold_qty,\n    a.gross_sales,\n    pc.product_cost,\n    0::numeric AS sales_expense,\n    CASE WHEN pc.costed_lines=pc.total_lines THEN a.gross_sales-pc.product_cost ELSE NULL END AS gross_profit,\n    CASE WHEN pc.costed_lines=pc.total_lines THEN a.gross_sales-pc.product_cost ELSE NULL END AS profit_after_sales_expense,\n    CASE WHEN pc.costed_lines=pc.total_lines THEN ROUND(pc.product_cost/NULLIF(a.sold_qty,0),2) ELSE NULL END AS avg_landed_cost,\n    ROUND(a.gross_sales/NULLIF(a.sold_qty,0),2) AS avg_selling_price,\n    0::numeric AS sales_expense_per_unit,\n    ROUND(a.gross_sales/NULLIF(a.sold_qty,0),2) AS net_selling_price_per_unit,\n    CASE WHEN pc.costed_lines=pc.total_lines THEN ROUND((a.gross_sales-pc.product_cost)/NULLIF(a.sold_qty,0),2) ELSE NULL END AS profit_per_unit,\n    CASE WHEN pc.costed_lines=pc.total_lines AND a.gross_sales<>0 THEN ROUND((a.gross_sales-pc.product_cost)/a.gross_sales*100,2) ELSE NULL END AS profit_margin_pct,\n    COALESCE(pc.costed_lines,0) AS costed_lines,\n    pc.total_lines,\n    COALESCE(pc.costed_lines,0)<pc.total_lines AS has_unreported_cost\n  FROM product_activity a\n  JOIN product_costs pc ON pc.product_id=a.product_id\n), invoice_scope AS (\n  SELECT invoice_id, MAX(invoice_date) AS invoice_date, MAX(posted_invoice_cogs) AS posted_invoice_cogs,\n    SUM(sales) AS invoice_sales, SUM(quantity) AS invoice_qty\n  FROM resolved GROUP BY invoice_id\n), company AS (\n  SELECT COALESCE(SUM(invoice_sales),0) AS gross_sales,\n    COALESCE(SUM(posted_invoice_cogs),0) AS product_cost,\n    COALESCE(SUM(invoice_qty),0) AS total_qty_sold,\n    COUNT(*) AS order_count,\n    (SELECT COUNT(DISTINCT product_id) FROM resolved) AS product_count\n  FROM invoice_scope\n), monthly AS (\n  SELECT TO_CHAR(DATE_TRUNC('month',invoice_date),'Mon YYYY') AS month_label,\n    DATE_TRUNC('month',invoice_date)::date AS month_start,\n    SUM(invoice_sales) AS gross_sales,\n    COALESCE(SUM(posted_invoice_cogs),0) AS product_cost,\n    SUM(invoice_qty) AS total_qty_sold,\n    COUNT(*) AS order_count\n  FROM invoice_scope GROUP BY 1,2\n)\nSELECT jsonb_build_object(\n  'company',jsonb_build_object(\n    'gross_sales',c.gross_sales,'product_cost',c.product_cost,\n    'sales_expenses',0,'unallocated_sales_expenses',0,\n    'gross_profit',c.gross_sales-c.product_cost,\n    'profit_after_sales_expenses',c.gross_sales-c.product_cost,\n    'profit_margin_pct',CASE WHEN c.gross_sales=0 THEN NULL ELSE ROUND((c.gross_sales-c.product_cost)/c.gross_sales*100,2) END,\n    'total_qty_sold',c.total_qty_sold,'order_count',c.order_count,'product_count',c.product_count\n  ),\n  'products',COALESCE((SELECT jsonb_agg(to_jsonb(p)) FROM (SELECT * FROM products_report ORDER BY product_name) p),'[]'::jsonb),\n  'monthly',COALESCE((SELECT jsonb_agg(jsonb_build_object(\n    'month_label',m.month_label,'month_start',m.month_start,\n    'gross_sales',m.gross_sales,'product_cost',m.product_cost,'sales_expenses',0,\n    'gross_profit',m.gross_sales-m.product_cost,\n    'profit_after_sales_expenses',m.gross_sales-m.product_cost,\n    'profit_margin_pct',CASE WHEN m.gross_sales=0 THEN NULL ELSE ROUND((m.gross_sales-m.product_cost)/m.gross_sales*100,2) END,\n    'total_qty_sold',m.total_qty_sold,'order_count',m.order_count\n  )) FROM (SELECT * FROM monthly ORDER BY month_start) m),'[]'::jsonb)\n)\nFROM company c;\n$$","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_summary(date,date) TO authenticated",COMMIT}	single_product_invoice_cogs_attribution	\N	\N	\N
20260905250000	{"-- Preserve sales-invoice-item and batch attribution for future COGS postings.\n-- Existing journal lines and sales invoices are intentionally untouched.\nBEGIN","ALTER TABLE public.journal_entry_lines\n  ADD COLUMN IF NOT EXISTS sales_invoice_item_id uuid\n    REFERENCES public.sales_invoice_items(id) ON DELETE RESTRICT","CREATE INDEX IF NOT EXISTS idx_journal_entry_lines_sales_invoice_item_id\n  ON public.journal_entry_lines(sales_invoice_item_id)\n  WHERE sales_invoice_item_id IS NOT NULL","CREATE OR REPLACE FUNCTION public.post_sales_invoice_cogs()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_existing_cogs_je_id uuid;\n  v_je_id uuid;\n  v_je_number text;\n  v_cogs_account_id uuid;\n  v_inventory_account_id uuid;\n  v_item record;\n  v_total_cogs numeric := 0;\n  v_line_number integer := 1;\n  v_snapshot_item_ids uuid[] := ARRAY[]::uuid[];\n  v_snapshot_batch_ids uuid[] := ARRAY[]::uuid[];\n  v_snapshot_unit_costs numeric[] := ARRAY[]::numeric[];\n  v_snapshot_total_costs numeric[] := ARRAY[]::numeric[];\nBEGIN\n  -- Keep existing posting eligibility and idempotency rules unchanged.\n  IF NEW.journal_entry_id IS NULL THEN RETURN NEW; END IF;\n  IF NEW.payment_status NOT IN ('pending', 'partial', 'paid') THEN RETURN NEW; END IF;\n\n  -- Serialize posting attempts for this invoice.  The existing journal lookup\n  -- remains the idempotency authority, while this lock closes the concurrent\n  -- retry race without imposing a historical-data uniqueness constraint.\n  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.id::text, 0));\n\n  SELECT id INTO v_existing_cogs_je_id\n    FROM public.journal_entries\n   WHERE source_module = 'sales_invoice_cogs'\n     AND reference_id = NEW.id\n   LIMIT 1;\n  IF v_existing_cogs_je_id IS NOT NULL THEN RETURN NEW; END IF;\n\n  SELECT id INTO v_cogs_account_id FROM public.chart_of_accounts WHERE code = '5100' LIMIT 1;\n  SELECT id INTO v_inventory_account_id FROM public.chart_of_accounts WHERE code = '1130' LIMIT 1;\n  IF v_cogs_account_id IS NULL OR v_inventory_account_id IS NULL THEN\n    RAISE EXCEPTION\n      'post_sales_invoice_cogs: chart_of_accounts is missing 5100 (COGS) or 1130 (Inventory). Cannot post COGS for invoice %.',\n      NEW.invoice_number;\n  END IF;\n\n  -- Preserve the established cost source. Each item is rounded at the amount\n  -- actually posted, so item debit/credit totals equal the journal total.\n  FOR v_item IN\n    SELECT sii.id, sii.quantity, sii.batch_id,\n           COALESCE(NULLIF(b.landed_cost_per_unit, 0),\n                    NULLIF(b.import_price, 0),\n                    NULLIF(b.cost_per_unit, 0), 0) AS effective_cost\n      FROM public.sales_invoice_items sii\n      LEFT JOIN public.batches b ON b.id = sii.batch_id\n     WHERE sii.invoice_id = NEW.id\n       AND sii.batch_id IS NOT NULL\n     ORDER BY sii.id\n  LOOP\n    v_snapshot_item_ids := array_append(v_snapshot_item_ids, v_item.id);\n    v_snapshot_batch_ids := array_append(v_snapshot_batch_ids, v_item.batch_id);\n    v_snapshot_unit_costs := array_append(v_snapshot_unit_costs, v_item.effective_cost);\n    v_snapshot_total_costs := array_append(\n      v_snapshot_total_costs,\n      ROUND(COALESCE(v_item.quantity, 0) * v_item.effective_cost, 2)\n    );\n    v_total_cogs := v_total_cogs + ROUND(COALESCE(v_item.quantity, 0) * v_item.effective_cost, 2);\n  END LOOP;\n\n  IF v_total_cogs <= 0 THEN RETURN NEW; END IF;\n\n  -- The snapshots and item-level journal lines are created in this trigger's\n  -- single transaction; an error rolls back both.\n  UPDATE public.sales_invoice_items sii\n     SET cogs_unit_cost = s.unit_cost,\n         cogs_total_cost = s.total_cost\n    FROM unnest(\n      v_snapshot_item_ids,\n      v_snapshot_unit_costs,\n      v_snapshot_total_costs\n    ) AS s(item_id, unit_cost, total_cost)\n   WHERE sii.id = s.item_id;\n\n  v_je_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries (\n    entry_number, entry_date, source_module, reference_id, reference_number,\n    description, total_debit, total_credit, is_posted, posted_by, created_by\n  ) VALUES (\n    v_je_number, NEW.invoice_date, 'sales_invoice_cogs', NEW.id, NEW.invoice_number,\n    'COGS for Sales Invoice: ' || NEW.invoice_number,\n    v_total_cogs, v_total_cogs, true, NEW.created_by, NEW.created_by\n  ) RETURNING id INTO v_je_id;\n\n  FOR v_item IN\n    SELECT item_id, batch_id, total_cost\n      FROM unnest(v_snapshot_item_ids, v_snapshot_batch_ids, v_snapshot_total_costs)\n        AS s(item_id, batch_id, total_cost)\n     WHERE total_cost <> 0\n     ORDER BY item_id\n  LOOP\n    INSERT INTO public.journal_entry_lines (\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      customer_id, batch_id, sales_invoice_item_id\n    ) VALUES (\n      v_je_id, v_line_number, v_cogs_account_id,\n      'COGS - ' || NEW.invoice_number, v_item.total_cost, 0,\n      NEW.customer_id, v_item.batch_id, v_item.item_id\n    );\n    v_line_number := v_line_number + 1;\n\n    INSERT INTO public.journal_entry_lines (\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      customer_id, batch_id, sales_invoice_item_id\n    ) VALUES (\n      v_je_id, v_line_number, v_inventory_account_id,\n      'Inventory - ' || NEW.invoice_number, 0, v_item.total_cost,\n      NEW.customer_id, v_item.batch_id, v_item.item_id\n    );\n    v_line_number := v_line_number + 1;\n  END LOOP;\n\n  RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n  RAISE LOG 'post_sales_invoice_cogs failed for invoice %: %', NEW.id, SQLERRM;\n  RAISE;\nEND;\n$$","COMMENT ON FUNCTION public.post_sales_invoice_cogs() IS\n  'Posts future COGS with unchanged cost basis and immutable item/batch journal attribution; existing COGS journals are never modified.'","-- Prefer directly attributed, active posted 5100 lines for future report\n-- drilldown. Historical lines continue through the existing evidence waterfall.\nCREATE OR REPLACE FUNCTION public.get_authoritative_sales_line_cogs(\n  p_start_date date,\n  p_end_date date\n)\nRETURNS TABLE (\n  line_id uuid,\n  invoice_id uuid,\n  product_id uuid,\n  batch_id uuid,\n  quantity numeric,\n  authoritative_cogs numeric,\n  authoritative_unit_cogs numeric,\n  resolution_tier text,\n  invoice_line_count bigint,\n  invoice_product_count bigint,\n  posted_invoice_cogs numeric,\n  base_line_cost numeric,\n  reconciliation_difference numeric\n)\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nWITH posted_cogs AS (\n  SELECT\n    je.reference_id AS invoice_id,\n    SUM(jel.debit - jel.credit) AS posted_invoice_cogs\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.source_module = 'sales_invoice_cogs'\n    AND je.is_posted = true\n    AND NOT COALESCE(je.is_reversed, false)\n    AND coa.code = '5100'\n  GROUP BY je.reference_id\n), posted_item_cogs AS (\n  SELECT\n    jel.sales_invoice_item_id AS line_id,\n    SUM(jel.debit - jel.credit) AS posted_item_cogs\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.source_module = 'sales_invoice_cogs'\n    AND je.is_posted = true\n    AND NOT COALESCE(je.is_reversed, false)\n    AND coa.code = '5100'\n    AND jel.sales_invoice_item_id IS NOT NULL\n  GROUP BY jel.sales_invoice_item_id\n), line_basis AS (\n  SELECT\n    sii.id AS line_id,\n    sii.invoice_id,\n    sii.product_id,\n    sii.batch_id,\n    sii.quantity,\n    pic.posted_item_cogs,\n    sii.cogs_total_cost AS snapshot_cogs,\n    CASE\n      WHEN COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0)) IS NULL\n        THEN NULL\n      ELSE sii.quantity * COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0))\n    END AS base_line_cost,\n    pc.posted_invoice_cogs\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  LEFT JOIN public.batches b ON b.id = sii.batch_id\n  LEFT JOIN posted_cogs pc ON pc.invoice_id = sii.invoice_id\n  LEFT JOIN posted_item_cogs pic ON pic.line_id = sii.id\n  WHERE si.invoice_date BETWEEN p_start_date AND p_end_date\n    AND NOT COALESCE(si.is_draft, false)\n), invoice_evidence AS (\n  SELECT\n    invoice_id,\n    COUNT(*) AS invoice_line_count,\n    COUNT(DISTINCT product_id) AS invoice_product_count,\n    COUNT(*) FILTER (WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL) AS unresolved_line_count,\n    COUNT(*) FILTER (\n      WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL AND base_line_cost IS NOT NULL\n    ) AS unresolved_base_line_count,\n    COALESCE(SUM(COALESCE(posted_item_cogs, snapshot_cogs)), 0) AS resolved_cogs_total,\n    SUM(base_line_cost) FILTER (\n      WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL\n    ) AS unresolved_base_cost_total,\n    MAX(posted_invoice_cogs) AS posted_invoice_cogs\n  FROM line_basis\n  GROUP BY invoice_id\n), resolved AS (\n  SELECT\n    lb.*,\n    ie.invoice_line_count,\n    ie.invoice_product_count,\n    ie.unresolved_line_count,\n    ie.unresolved_base_line_count,\n    ie.resolved_cogs_total,\n    ie.unresolved_base_cost_total,\n    ie.posted_invoice_cogs AS invoice_posted_cogs,\n    ie.posted_invoice_cogs - ie.resolved_cogs_total AS residual_posted_cogs,\n    ABS(ie.unresolved_base_cost_total - (ie.posted_invoice_cogs - ie.resolved_cogs_total)) AS reconciliation_difference\n  FROM line_basis lb\n  JOIN invoice_evidence ie ON ie.invoice_id = lb.invoice_id\n)\nSELECT\n  r.line_id,\n  r.invoice_id,\n  r.product_id,\n  r.batch_id,\n  r.quantity,\n  CASE\n    WHEN r.posted_item_cogs IS NOT NULL THEN r.posted_item_cogs\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN r.invoice_posted_cogs\n    WHEN r.invoice_line_count > 1\n      AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)\n    ELSE NULL\n  END AS authoritative_cogs,\n  CASE\n    WHEN r.quantity = 0 THEN NULL\n    WHEN r.posted_item_cogs IS NOT NULL THEN r.posted_item_cogs / r.quantity\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs / r.quantity\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN r.invoice_posted_cogs / r.quantity\n    WHEN r.invoice_line_count > 1\n      AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN (r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)) / r.quantity\n    ELSE NULL\n  END AS authoritative_unit_cogs,\n  CASE\n    WHEN r.posted_item_cogs IS NOT NULL THEN 'posted_item_cogs'\n    WHEN r.snapshot_cogs IS NOT NULL THEN 'snapshot'\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN 'single_line_posted_cogs'\n    WHEN r.invoice_line_count > 1\n      AND r.invoice_product_count = 1\n      AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN 'single_product_proven_allocation'\n    WHEN r.invoice_line_count > 1\n      AND r.invoice_product_count > 1\n      AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN 'multi_product_proven_allocation'\n    ELSE 'unresolved'\n  END AS resolution_tier,\n  r.invoice_line_count,\n  r.invoice_product_count,\n  r.invoice_posted_cogs,\n  r.base_line_cost,\n  r.reconciliation_difference\nFROM resolved r;\n$$","COMMENT ON FUNCTION public.get_authoritative_sales_line_cogs(date, date) IS\n  'Read-only COGS waterfall that prefers active posted item-attributed GL 5100 lines for future invoices, then uses existing historical evidence rules.'","GRANT EXECUTE ON FUNCTION public.get_authoritative_sales_line_cogs(date, date) TO authenticated",COMMIT}	attribute_future_sales_invoice_cogs_lines	\N	\N	\N
20260905260000	{"-- Report-only correction: include all active posted COGS evidence for an\n-- invoice, including historical correction/final-correction journals.\n-- No accounting or business rows are modified. Rp1.00 remains the sole\n-- reconciliation tolerance for reconstructed multi-line allocations.\nBEGIN","CREATE OR REPLACE FUNCTION public.get_authoritative_sales_line_cogs(\n  p_start_date date, p_end_date date\n)\nRETURNS TABLE (\n  line_id uuid, invoice_id uuid, product_id uuid, batch_id uuid, quantity numeric,\n  authoritative_cogs numeric, authoritative_unit_cogs numeric, resolution_tier text,\n  invoice_line_count bigint, invoice_product_count bigint, posted_invoice_cogs numeric,\n  base_line_cost numeric, reconciliation_difference numeric\n)\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp\nAS $$\nWITH active_cogs AS (\n  SELECT je.reference_id AS invoice_id, je.id AS journal_id,\n         SUM(jel.debit - jel.credit) AS cogs_amount\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true\n    AND NOT COALESCE(je.is_reversed, false)\n    AND coa.code = '5100'\n    AND je.reference_id IS NOT NULL\n    AND (\n      je.source_module = 'sales_invoice_cogs'\n      OR je.source_module IN ('historical_cogs_correction', 'historical_cogs_final_correction')\n      OR je.source_module LIKE 'historical_cogs%'\n    )\n  GROUP BY je.reference_id, je.id\n), posted_cogs AS (\n  SELECT invoice_id, SUM(cogs_amount) AS posted_invoice_cogs\n  FROM active_cogs GROUP BY invoice_id\n), posted_item_cogs AS (\n  SELECT jel.sales_invoice_item_id AS line_id,\n         SUM(jel.debit - jel.credit) AS posted_item_cogs\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true AND NOT COALESCE(je.is_reversed, false)\n    AND coa.code = '5100' AND jel.sales_invoice_item_id IS NOT NULL\n    AND (\n      je.source_module = 'sales_invoice_cogs'\n      OR je.source_module IN ('historical_cogs_correction', 'historical_cogs_final_correction')\n      OR je.source_module LIKE 'historical_cogs%'\n    )\n  GROUP BY jel.sales_invoice_item_id\n), line_basis AS (\n  SELECT sii.id AS line_id, sii.invoice_id, sii.product_id, sii.batch_id,\n         sii.quantity, pic.posted_item_cogs, sii.cogs_total_cost AS snapshot_cogs,\n         CASE WHEN COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0)) IS NULL\n              THEN NULL ELSE sii.quantity * COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0)) END AS base_line_cost,\n         pc.posted_invoice_cogs\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  LEFT JOIN public.batches b ON b.id = sii.batch_id\n  LEFT JOIN posted_cogs pc ON pc.invoice_id = sii.invoice_id\n  LEFT JOIN posted_item_cogs pic ON pic.line_id = sii.id\n  WHERE si.invoice_date BETWEEN p_start_date AND p_end_date\n    AND NOT COALESCE(si.is_draft, false)\n), invoice_evidence AS (\n  SELECT invoice_id, COUNT(*) AS invoice_line_count,\n         COUNT(DISTINCT product_id) AS invoice_product_count,\n         COUNT(*) FILTER (WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL) AS unresolved_line_count,\n         COUNT(*) FILTER (WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL AND base_line_cost IS NOT NULL) AS unresolved_base_line_count,\n         COALESCE(SUM(COALESCE(posted_item_cogs, snapshot_cogs)), 0) AS resolved_cogs_total,\n         SUM(base_line_cost) FILTER (WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL) AS unresolved_base_cost_total,\n         MAX(posted_invoice_cogs) AS posted_invoice_cogs\n  FROM line_basis GROUP BY invoice_id\n), resolved AS (\n  SELECT lb.*, ie.invoice_line_count, ie.invoice_product_count,\n         ie.unresolved_line_count, ie.unresolved_base_line_count,\n         ie.resolved_cogs_total, ie.unresolved_base_cost_total,\n         ie.posted_invoice_cogs AS invoice_posted_cogs,\n         ie.posted_invoice_cogs - ie.resolved_cogs_total AS residual_posted_cogs,\n         ABS(ie.unresolved_base_cost_total - (ie.posted_invoice_cogs - ie.resolved_cogs_total)) AS reconciliation_difference\n  FROM line_basis lb JOIN invoice_evidence ie ON ie.invoice_id = lb.invoice_id\n)\nSELECT r.line_id, r.invoice_id, r.product_id, r.batch_id, r.quantity,\n  CASE\n    WHEN r.posted_item_cogs IS NOT NULL THEN r.posted_item_cogs\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN r.invoice_posted_cogs\n    WHEN r.invoice_line_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)\n    ELSE NULL END AS authoritative_cogs,\n  CASE\n    WHEN r.quantity = 0 THEN NULL\n    WHEN r.posted_item_cogs IS NOT NULL THEN r.posted_item_cogs / r.quantity\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs / r.quantity\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN r.invoice_posted_cogs / r.quantity\n    WHEN r.invoice_line_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN (r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)) / r.quantity\n    ELSE NULL END AS authoritative_unit_cogs,\n  CASE\n    WHEN r.posted_item_cogs IS NOT NULL THEN 'posted_item_cogs'\n    WHEN r.snapshot_cogs IS NOT NULL THEN 'snapshot'\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN 'single_line_posted_cogs'\n    WHEN r.invoice_line_count > 1 AND r.invoice_product_count = 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00 THEN 'single_product_proven_allocation'\n    WHEN r.invoice_line_count > 1 AND r.invoice_product_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00 THEN 'multi_product_proven_allocation'\n    ELSE 'unresolved' END AS resolution_tier,\n  r.invoice_line_count, r.invoice_product_count, r.invoice_posted_cogs,\n  r.base_line_cost, r.reconciliation_difference\nFROM resolved r;\n$$","COMMENT ON FUNCTION public.get_authoritative_sales_line_cogs(date, date) IS\n  'Read-only COGS waterfall including active posted sales COGS and historical correction/final-correction 5100 evidence; Rp1.00 reconciliation tolerance.'",COMMIT}	include_active_historical_cogs_corrections	\N	\N	\N
20260905270000	{"-- Restore report-only sales-expense attribution. No accounting/business data is written.\nBEGIN","CREATE OR REPLACE FUNCTION public.get_sales_profitability_line_expenses(\n  p_start_date date,\n  p_end_date date\n)\nRETURNS TABLE(line_id uuid, sales_expense numeric)\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$\nWITH scoped AS (\n  SELECT sii.id AS line_id, dci.challan_id AS dc_id,\n         ROUND(sii.quantity * sii.unit_price, 2) AS line_sales,\n         sii.quantity\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n  WHERE si.invoice_date BETWEEN p_start_date AND p_end_date\n    AND NOT COALESCE(si.is_draft, false)\n), dc_totals AS (\n  SELECT dci.challan_id AS dc_id,\n         SUM(ROUND(sii.quantity * sii.unit_price, 2)) AS total_sales,\n         SUM(sii.quantity) AS total_qty\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n  WHERE NOT COALESCE(si.is_draft, false)\n    AND dci.challan_id IN (SELECT DISTINCT dc_id FROM scoped WHERE dc_id IS NOT NULL)\n  GROUP BY dci.challan_id\n), dc_expenses AS (\n  SELECT delivery_challan_id AS dc_id, SUM(amount) AS total_expense\n  FROM public.finance_expenses\n  WHERE expense_category IN ('delivery_sales', 'loading_sales')\n    AND approval_status = 'approved'\n    AND delivery_challan_id IN (SELECT DISTINCT dc_id FROM scoped WHERE dc_id IS NOT NULL)\n  GROUP BY delivery_challan_id\n)\nSELECT s.line_id,\n       COALESCE(CASE\n         WHEN d.total_sales > 0 THEN ROUND(e.total_expense * s.line_sales / d.total_sales, 2)\n         WHEN d.total_qty > 0 THEN ROUND(e.total_expense * s.quantity / d.total_qty, 2)\n         ELSE 0\n       END, 0)::numeric AS sales_expense\nFROM scoped s\nLEFT JOIN dc_totals d ON d.dc_id = s.dc_id\nLEFT JOIN dc_expenses e ON e.dc_id = s.dc_id;\n$$","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_line_expenses(date,date) TO authenticated","CREATE OR REPLACE FUNCTION public.get_sales_profitability_summary(p_start_date date, p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$\nWITH resolved AS (\n  SELECT ar.*, si.invoice_date, ROUND(sii.quantity*sii.unit_price,2) AS sales,\n         p.product_name, COALESCE(p.product_code,'') AS product_code, COALESCE(p.unit,'kg') AS product_unit,\n         COALESCE(le.sales_expense,0) AS sales_expense\n  FROM public.get_authoritative_sales_line_cogs(p_start_date,p_end_date) ar\n  JOIN public.sales_invoice_items sii ON sii.id=ar.line_id\n  JOIN public.sales_invoices si ON si.id=ar.invoice_id\n  JOIN public.products p ON p.id=ar.product_id\n  LEFT JOIN public.get_sales_profitability_line_expenses(p_start_date,p_end_date) le ON le.line_id=ar.line_id\n), unallocated AS (\n  SELECT COALESCE(SUM(fe.amount),0) AS amount\n  FROM public.finance_expenses fe\n  WHERE fe.expense_category IN ('delivery_sales','loading_sales')\n    AND fe.approval_status='approved'\n    AND fe.expense_date BETWEEN p_start_date AND p_end_date\n    AND (fe.delivery_challan_id IS NULL OR NOT EXISTS (\n      SELECT 1 FROM resolved r WHERE r.line_id IS NOT NULL\n        AND EXISTS (SELECT 1 FROM public.sales_invoice_items sii2\n                   JOIN public.delivery_challan_items dci2 ON dci2.id=sii2.delivery_challan_item_id\n                   WHERE sii2.id=r.line_id AND dci2.challan_id=fe.delivery_challan_id)\n    ))\n), products_report AS (\n  SELECT r.product_id,MAX(r.product_name) product_name,MAX(r.product_code) product_code,MAX(r.product_unit) product_unit,\n    COALESCE((SELECT SUM(b.current_stock) FROM public.batches b WHERE b.product_id=r.product_id AND b.is_active),0) current_stock,\n    SUM(r.quantity) sold_qty,SUM(r.sales) gross_sales,SUM(r.authoritative_cogs) product_cost,SUM(r.sales_expense) sales_expense,\n    CASE WHEN COUNT(r.authoritative_cogs)=COUNT(*) THEN SUM(r.sales)-SUM(r.authoritative_cogs) ELSE NULL END gross_profit,\n    CASE WHEN COUNT(r.authoritative_cogs)=COUNT(*) THEN SUM(r.sales)-SUM(r.authoritative_cogs)-SUM(r.sales_expense) ELSE NULL END profit_after_sales_expenses,\n    COUNT(r.authoritative_cogs) costed_lines,COUNT(*) total_lines,COUNT(r.authoritative_cogs)<COUNT(*) has_unreported_cost\n  FROM resolved r GROUP BY r.product_id\n), invoice_scope AS (\n  SELECT invoice_id,MAX(invoice_date) invoice_date,MAX(posted_invoice_cogs) posted_invoice_cogs,SUM(sales) invoice_sales,SUM(quantity) invoice_qty,SUM(sales_expense) sales_expense\n  FROM resolved GROUP BY invoice_id\n), company AS (\n  SELECT COALESCE(SUM(invoice_sales),0) gross_sales,COALESCE(SUM(posted_invoice_cogs),0) product_cost,\n    COALESCE(SUM(sales_expense),0)+(SELECT amount FROM unallocated) sales_expenses,(SELECT amount FROM unallocated) unallocated_sales_expenses,\n    COALESCE(SUM(invoice_qty),0) total_qty_sold,COUNT(*) order_count,(SELECT COUNT(DISTINCT product_id) FROM resolved) product_count\n  FROM invoice_scope\n), unallocated_by_month AS (\n  SELECT DATE_TRUNC('month',fe.expense_date)::date month_start,SUM(fe.amount) amount\n  FROM public.finance_expenses fe\n  WHERE fe.expense_category IN ('delivery_sales','loading_sales') AND fe.approval_status='approved'\n    AND fe.expense_date BETWEEN p_start_date AND p_end_date\n    AND (fe.delivery_challan_id IS NULL OR NOT EXISTS (\n      SELECT 1 FROM resolved r JOIN public.sales_invoice_items sii2 ON sii2.id=r.line_id\n      JOIN public.delivery_challan_items dci2 ON dci2.id=sii2.delivery_challan_item_id\n      WHERE dci2.challan_id=fe.delivery_challan_id\n    )) GROUP BY 1\n), monthly_base AS (\n  SELECT TO_CHAR(DATE_TRUNC('month',invoice_date),'Mon YYYY') month_label,DATE_TRUNC('month',invoice_date)::date month_start,\n    SUM(invoice_sales) gross_sales,COALESCE(SUM(posted_invoice_cogs),0) product_cost,\n    SUM(sales_expense) sales_expenses,\n    SUM(invoice_qty) total_qty_sold,COUNT(*) order_count\n  FROM invoice_scope GROUP BY 1,2\n), monthly AS (\n  SELECT mb.*, mb.sales_expenses + COALESCE(u.amount,0) AS sales_expenses_total\n  FROM monthly_base mb LEFT JOIN unallocated_by_month u USING (month_start)\n)\nSELECT jsonb_build_object(\n 'company',jsonb_build_object('gross_sales',c.gross_sales,'product_cost',c.product_cost,'sales_expenses',c.sales_expenses,'unallocated_sales_expenses',c.unallocated_sales_expenses,\n   'gross_profit',c.gross_sales-c.product_cost,'profit_after_sales_expenses',c.gross_sales-c.product_cost-c.sales_expenses,\n   'profit_margin_pct',CASE WHEN c.gross_sales=0 THEN NULL ELSE ROUND((c.gross_sales-c.product_cost-c.sales_expenses)/c.gross_sales*100,2) END,\n   'total_qty_sold',c.total_qty_sold,'order_count',c.order_count,'product_count',c.product_count),\n 'products',COALESCE((SELECT jsonb_agg(to_jsonb(p)) FROM products_report p),'[]'::jsonb),\n 'monthly',COALESCE((SELECT jsonb_agg(jsonb_build_object('month_label',m.month_label,'month_start',m.month_start,'gross_sales',m.gross_sales,'product_cost',m.product_cost,'sales_expenses',m.sales_expenses_total,\n   'gross_profit',m.gross_sales-m.product_cost,'profit_after_sales_expenses',m.gross_sales-m.product_cost-m.sales_expenses_total,\n   'profit_margin_pct',CASE WHEN m.gross_sales=0 THEN NULL ELSE ROUND((m.gross_sales-m.product_cost-m.sales_expenses_total)/m.gross_sales*100,2) END,'total_qty_sold',m.total_qty_sold,'order_count',m.order_count) ORDER BY m.month_start) FROM monthly m),'[]'::jsonb)\n) FROM company c;\n$$","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_summary(date,date) TO authenticated","-- Keep drilldowns on the same line-level expense source as the company report.\nCREATE OR REPLACE FUNCTION public.get_sales_profitability_batch_orders(p_batch_id uuid,p_start_date date,p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$\nWITH x AS (\n SELECT ar.*,sii.unit_price,si.invoice_number,si.invoice_date,si.customer_id,COALESCE(c.company_name,'Unknown Customer') customer_name,si.sales_order_id,so.so_number,\n   ROUND(ar.quantity*sii.unit_price,2) gross_sales,COALESCE(le.sales_expense,0) line_sales_expense\n FROM public.get_authoritative_sales_line_cogs(p_start_date,p_end_date) ar JOIN public.sales_invoice_items sii ON sii.id=ar.line_id JOIN public.sales_invoices si ON si.id=ar.invoice_id\n LEFT JOIN public.customers c ON c.id=si.customer_id LEFT JOIN public.sales_orders so ON so.id=si.sales_order_id\n LEFT JOIN public.get_sales_profitability_line_expenses(p_start_date,p_end_date) le ON le.line_id=ar.line_id WHERE ar.batch_id=p_batch_id\n)\nSELECT jsonb_build_object('batch',(SELECT jsonb_build_object('batch_id',b.id,'batch_number',b.batch_number,'product_name',p.product_name,'product_code',COALESCE(p.product_code,''),'product_unit',COALESCE(p.unit,'kg'),'current_stock',b.current_stock) FROM public.batches b JOIN public.products p ON p.id=b.product_id WHERE b.id=p_batch_id),\n 'orders',COALESCE((SELECT jsonb_agg(jsonb_build_object('line_id',line_id,'invoice_id',invoice_id,'invoice_number',invoice_number,'invoice_date',invoice_date,'customer_id',customer_id,'customer_name',customer_name,'sales_order_id',sales_order_id,'so_number',so_number,'quantity',quantity,'unit_price',unit_price,'selling_price',unit_price,'gross_sales',gross_sales,'unit_cost',authoritative_unit_cogs,'line_cost',authoritative_cogs,'line_sales_expense',line_sales_expense,'gross_profit',CASE WHEN authoritative_cogs IS NULL THEN NULL ELSE gross_sales-authoritative_cogs END,'profit',CASE WHEN authoritative_cogs IS NULL THEN NULL ELSE gross_sales-authoritative_cogs-line_sales_expense END) ORDER BY invoice_date DESC,invoice_number) FROM x),'[]'::jsonb));\n$$","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_batch_orders(uuid,date,date) TO authenticated","CREATE OR REPLACE FUNCTION public.get_sales_profitability_product_batches(p_product_id uuid,p_start_date date,p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$\nWITH x AS (\n SELECT ar.*,sii.unit_price,ROUND(ar.quantity*sii.unit_price,2) gross_sales,b.batch_number,b.current_stock,\n   COALESCE(le.sales_expense,0) sales_expense\n FROM public.get_authoritative_sales_line_cogs(p_start_date,p_end_date) ar\n JOIN public.sales_invoice_items sii ON sii.id=ar.line_id\n LEFT JOIN public.batches b ON b.id=ar.batch_id\n LEFT JOIN public.get_sales_profitability_line_expenses(p_start_date,p_end_date) le ON le.line_id=ar.line_id\n WHERE ar.product_id=p_product_id\n), batches_report AS (\n SELECT batch_id,COALESCE(batch_number,'Unassigned Batch') batch_number,COALESCE(current_stock,0) current_stock,\n   SUM(quantity) sold_qty,SUM(gross_sales) gross_sales,SUM(authoritative_cogs) product_cost,SUM(sales_expense) sales_expense,\n   COUNT(authoritative_cogs) costed_lines,COUNT(*) total_lines,\n   CASE WHEN COUNT(authoritative_cogs)=0 THEN 'unavailable' WHEN COUNT(authoritative_cogs)<COUNT(*) THEN 'partial' ELSE 'complete' END cost_coverage,\n   CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN SUM(gross_sales)-SUM(authoritative_cogs) ELSE NULL END gross_profit,\n   CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN SUM(gross_sales)-SUM(authoritative_cogs)-SUM(sales_expense) ELSE NULL END profit_after_sales_expense\n FROM x GROUP BY batch_id,batch_number,current_stock\n), product_report AS (\n SELECT p.id product_id,p.product_name,COALESCE(p.product_code,'') product_code,COALESCE(p.unit,'kg') product_unit,\n   COALESCE(SUM(b.sold_qty),0) sold_qty,COALESCE(SUM(b.gross_sales),0) gross_sales,COALESCE(SUM(b.product_cost),0) product_cost,COALESCE(SUM(b.sales_expense),0) sales_expense,\n   COALESCE(SUM(b.costed_lines),0) costed_lines,COALESCE(SUM(b.total_lines),0) total_lines,\n   CASE WHEN COALESCE(SUM(b.costed_lines),0)=COALESCE(SUM(b.total_lines),0) THEN SUM(b.gross_profit) ELSE NULL END gross_profit,\n   CASE WHEN COALESCE(SUM(b.costed_lines),0)=COALESCE(SUM(b.total_lines),0) THEN SUM(b.gross_profit)-SUM(b.sales_expense) ELSE NULL END profit_after_sales_expense\n FROM public.products p LEFT JOIN batches_report b ON true WHERE p.id=p_product_id GROUP BY p.id,p.product_name,p.product_code,p.unit\n)\nSELECT jsonb_build_object('product',(SELECT to_jsonb(pr) FROM product_report pr),'batches',COALESCE((SELECT jsonb_agg(to_jsonb(br) ORDER BY br.batch_number) FROM batches_report br),'[]'::jsonb));\n$$","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_product_batches(uuid,date,date) TO authenticated",COMMIT}	restore_sales_expense_profitability	\N	\N	\N
20260905271000	{"-- Restore canonical profitability response/calculations while retaining the\n-- authoritative report-only COGS and sales-expense resolvers.\nBEGIN","CREATE OR REPLACE FUNCTION public.get_sales_profitability_summary(p_start_date date,p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$\nWITH lines AS (\n SELECT ar.*,si.invoice_date,si.invoice_number,si.customer_id,COALESCE(c.company_name,'Unknown Customer') customer_name,\n   si.sales_order_id,so.so_number,sii.unit_price,ROUND(sii.quantity*sii.unit_price,2) line_gross_sales,\n   p.product_name,COALESCE(p.product_code,'') product_code,COALESCE(p.unit,'kg') product_unit,\n   b.batch_number,COALESCE(le.sales_expense,0) line_sales_expense,\n   dci.challan_id dc_id,dc.challan_number dc_number\n FROM public.get_authoritative_sales_line_cogs(p_start_date,p_end_date) ar\n JOIN public.sales_invoice_items sii ON sii.id=ar.line_id JOIN public.sales_invoices si ON si.id=ar.invoice_id\n JOIN public.products p ON p.id=ar.product_id LEFT JOIN public.customers c ON c.id=si.customer_id\n LEFT JOIN public.sales_orders so ON so.id=si.sales_order_id LEFT JOIN public.batches b ON b.id=ar.batch_id\n LEFT JOIN public.delivery_challan_items dci ON dci.id=sii.delivery_challan_item_id LEFT JOIN public.delivery_challans dc ON dc.id=dci.challan_id\n LEFT JOIN public.get_sales_profitability_line_expenses(p_start_date,p_end_date) le ON le.line_id=ar.line_id\n), unallocated AS (\n SELECT COALESCE(SUM(fe.amount),0) amount FROM public.finance_expenses fe\n WHERE fe.expense_category IN ('delivery_sales','loading_sales') AND fe.approval_status='approved'\n   AND fe.expense_date BETWEEN p_start_date AND p_end_date AND (fe.delivery_challan_id IS NULL OR NOT EXISTS (SELECT 1 FROM lines l WHERE l.dc_id=fe.delivery_challan_id))\n), prod AS (\n SELECT product_id,MAX(product_name) product_name,MAX(product_code) product_code,MAX(product_unit) product_unit,\n   COALESCE((SELECT SUM(b.current_stock) FROM public.batches b WHERE b.product_id=l.product_id AND b.is_active),0) current_stock,\n   SUM(quantity) sold_qty,SUM(line_gross_sales) gross_sales,SUM(authoritative_cogs) product_cost,SUM(line_sales_expense) sales_expense,\n   ROUND(SUM(line_gross_sales)/NULLIF(SUM(quantity),0),2) avg_selling_price,\n   ROUND(SUM(line_sales_expense)/NULLIF(SUM(quantity),0),2) sales_expense_per_unit,\n   ROUND((SUM(line_gross_sales)-SUM(line_sales_expense))/NULLIF(SUM(quantity),0),2) net_selling_price_per_unit,\n   CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN ROUND(SUM(authoritative_cogs)/NULLIF(SUM(quantity),0),2) END avg_landed_cost,\n   CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN SUM(line_gross_sales)-SUM(authoritative_cogs) END gross_profit,\n   CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN SUM(line_gross_sales)-SUM(authoritative_cogs)-SUM(line_sales_expense) END profit_after_sales_expense,\n   CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN ROUND((SUM(line_gross_sales)-SUM(authoritative_cogs)-SUM(line_sales_expense))/NULLIF(SUM(quantity),0),2) END profit_per_unit,\n   CASE WHEN COUNT(authoritative_cogs)=COUNT(*) AND SUM(line_gross_sales)<>0 THEN ROUND((SUM(line_gross_sales)-SUM(authoritative_cogs)-SUM(line_sales_expense))/SUM(line_gross_sales)*100,2) END profit_margin_pct,\n   COUNT(authoritative_cogs) costed_lines,COUNT(*) total_lines,COUNT(authoritative_cogs)<COUNT(*) has_unreported_cost\n FROM lines l GROUP BY product_id\n), inv AS (\n SELECT invoice_id,MAX(invoice_date) invoice_date,MAX(posted_invoice_cogs) product_cost,SUM(line_gross_sales) gross_sales,SUM(quantity) total_qty_sold,SUM(line_sales_expense) sales_expenses\n FROM lines GROUP BY invoice_id\n), months AS (\n SELECT DATE_TRUNC('month',invoice_date)::date month_start,TO_CHAR(DATE_TRUNC('month',invoice_date),'Mon YYYY') month_label,\n   SUM(gross_sales) gross_sales,SUM(product_cost) product_cost,SUM(sales_expenses) sales_expenses,SUM(total_qty_sold) total_qty_sold,COUNT(*) order_count\n FROM inv GROUP BY 1,2\n), company AS (\n SELECT COALESCE(SUM(gross_sales),0) gross_sales,COALESCE(SUM(product_cost),0) product_cost,\n   COALESCE(SUM(sales_expenses),0)+(SELECT amount FROM unallocated) sales_expenses,(SELECT amount FROM unallocated) unallocated_sales_expenses,\n   COALESCE(SUM(total_qty_sold),0) total_qty_sold,COUNT(*) order_count,(SELECT COUNT(DISTINCT product_id) FROM lines) product_count\n FROM inv\n)\nSELECT jsonb_build_object('company',jsonb_build_object('gross_sales',c.gross_sales,'product_cost',c.product_cost,'sales_expenses',c.sales_expenses,'unallocated_sales_expenses',c.unallocated_sales_expenses,'gross_profit',c.gross_sales-c.product_cost,'profit_after_sales_expenses',c.gross_sales-c.product_cost-c.sales_expenses,'profit_margin_pct',CASE WHEN c.gross_sales=0 THEN NULL ELSE ROUND((c.gross_sales-c.product_cost-c.sales_expenses)/c.gross_sales*100,2) END,'total_qty_sold',c.total_qty_sold,'order_count',c.order_count,'product_count',c.product_count),\n 'products',COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.product_name) FROM prod p),'[]'::jsonb),\n 'monthly',COALESCE((SELECT jsonb_agg(jsonb_build_object('month_label',m.month_label,'month_start',m.month_start,'gross_sales',m.gross_sales,'product_cost',m.product_cost,'sales_expenses',m.sales_expenses,'gross_profit',m.gross_sales-m.product_cost,'profit_after_sales_expenses',m.gross_sales-m.product_cost-m.sales_expenses,'profit_margin_pct',CASE WHEN m.gross_sales=0 THEN NULL ELSE ROUND((m.gross_sales-m.product_cost-m.sales_expenses)/m.gross_sales*100,2) END,'total_qty_sold',m.total_qty_sold,'order_count',m.order_count) ORDER BY m.month_start) FROM months m),'[]'::jsonb))\nFROM company c;\n$$","CREATE OR REPLACE FUNCTION public.get_sales_profitability_product_batches(p_product_id uuid,p_start_date date,p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$\nWITH l AS (\n SELECT ar.*,sii.unit_price,ROUND(ar.quantity*sii.unit_price,2) gross_sales,b.batch_number,b.current_stock,\n   COALESCE(le.sales_expense,0) sales_expense,b.import_price,b.import_price_usd,b.exchange_rate_usd_to_idr,b.duty_charges,b.freight_charges,b.other_charges,b.landed_cost_per_unit,b.cost_per_unit\n FROM public.get_authoritative_sales_line_cogs(p_start_date,p_end_date) ar JOIN public.sales_invoice_items sii ON sii.id=ar.line_id LEFT JOIN public.batches b ON b.id=ar.batch_id\n LEFT JOIN public.get_sales_profitability_line_expenses(p_start_date,p_end_date) le ON le.line_id=ar.line_id WHERE ar.product_id=p_product_id\n), b AS (\n SELECT batch_id,COALESCE(batch_number,'Unassigned Batch') batch_number,COALESCE(current_stock,0) current_stock,SUM(quantity) sold_qty,SUM(gross_sales) gross_sales,SUM(authoritative_cogs) product_cost,SUM(sales_expense) sales_expense,\n   CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN SUM(gross_sales)-SUM(authoritative_cogs) END gross_profit,CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN SUM(gross_sales)-SUM(authoritative_cogs)-SUM(sales_expense) END profit_after_sales_expense,\n   CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN ROUND(SUM(authoritative_cogs)/NULLIF(SUM(quantity),0),2) END cost_per_unit,ROUND(SUM(gross_sales)/NULLIF(SUM(quantity),0),2) avg_selling_price,ROUND(SUM(sales_expense)/NULLIF(SUM(quantity),0),2) sales_expense_per_unit,\n   ROUND((SUM(gross_sales)-SUM(sales_expense))/NULLIF(SUM(quantity),0),2) net_selling_price_per_unit,CASE WHEN COUNT(authoritative_cogs)=COUNT(*) THEN ROUND((SUM(gross_sales)-SUM(authoritative_cogs)-SUM(sales_expense))/NULLIF(SUM(quantity),0),2) END profit_per_unit,\n   CASE WHEN COUNT(authoritative_cogs)=COUNT(*) AND SUM(gross_sales)<>0 THEN ROUND((SUM(gross_sales)-SUM(authoritative_cogs)-SUM(sales_expense))/SUM(gross_sales)*100,2) END profit_margin_pct,COUNT(authoritative_cogs) costed_lines,COUNT(*) total_lines,CASE WHEN COUNT(authoritative_cogs)=0 THEN 'unavailable' WHEN COUNT(authoritative_cogs)<COUNT(*) THEN 'partial' ELSE 'complete' END cost_coverage,\n   BOOL_OR(import_price IS NOT NULL OR landed_cost_per_unit IS NOT NULL) is_imported,jsonb_build_object('import_price',MAX(import_price),'import_price_usd',MAX(import_price_usd),'exchange_rate',MAX(exchange_rate_usd_to_idr),'duty_charges',MAX(duty_charges),'freight_charges',MAX(freight_charges),'other_charges',MAX(other_charges),'landed_cost_per_unit',MAX(landed_cost_per_unit),'local_cost_per_unit',MAX(cost_per_unit)) cost_breakdown\n FROM l GROUP BY batch_id,batch_number,current_stock\n), p AS (SELECT pr.id product_id,pr.product_name,COALESCE(pr.product_code,'') product_code,COALESCE(pr.unit,'kg') product_unit,COALESCE(SUM(b.sold_qty),0) sold_qty,COALESCE(SUM(b.gross_sales),0) gross_sales,COALESCE(SUM(b.product_cost),0) product_cost,COALESCE(SUM(b.sales_expense),0) sales_expense,COALESCE(SUM(b.costed_lines),0) costed_lines,COALESCE(SUM(b.total_lines),0) total_lines,CASE WHEN SUM(b.costed_lines)=SUM(b.total_lines) THEN SUM(b.gross_profit) END gross_profit,CASE WHEN SUM(b.costed_lines)=SUM(b.total_lines) THEN SUM(b.profit_after_sales_expense) END profit_after_sales_expense FROM public.products pr LEFT JOIN b ON true WHERE pr.id=p_product_id GROUP BY pr.id,pr.product_name,pr.product_code,pr.unit)\nSELECT jsonb_build_object('product',(SELECT to_jsonb(p) FROM p),'batches',COALESCE((SELECT jsonb_agg(to_jsonb(b) ORDER BY b.profit_after_sales_expense DESC NULLS LAST) FROM b),'[]'::jsonb));\n$$","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_summary(date,date) TO authenticated","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_product_batches(uuid,date,date) TO authenticated",COMMIT}	hybrid_sales_profitability_structure	\N	\N	\N
20260905272000	{"-- Complete the canonical batch/order response shape; report-only.\nBEGIN","CREATE OR REPLACE FUNCTION public.get_sales_profitability_batch_orders(p_batch_id uuid,p_start_date date,p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$\nWITH x AS (\n SELECT ar.line_id,ar.invoice_id,si.invoice_number,si.invoice_date,si.customer_id,COALESCE(c.company_name,'Unknown Customer') customer_name,si.sales_order_id,so.so_number,dci.challan_id dc_id,dc.challan_number dc_number,ar.quantity,sii.unit_price selling_price,ROUND(ar.quantity*sii.unit_price,2) gross_sales,ar.authoritative_unit_cogs unit_cost,ar.authoritative_cogs line_cost,COALESCE(le.sales_expense,0) line_sales_expense,ar.resolution_tier cogs_resolution\n FROM public.get_authoritative_sales_line_cogs(p_start_date,p_end_date) ar JOIN public.sales_invoice_items sii ON sii.id=ar.line_id JOIN public.sales_invoices si ON si.id=ar.invoice_id LEFT JOIN public.customers c ON c.id=si.customer_id LEFT JOIN public.sales_orders so ON so.id=si.sales_order_id LEFT JOIN public.delivery_challan_items dci ON dci.id=sii.delivery_challan_item_id LEFT JOIN public.delivery_challans dc ON dc.id=dci.challan_id LEFT JOIN public.get_sales_profitability_line_expenses(p_start_date,p_end_date) le ON le.line_id=ar.line_id WHERE ar.batch_id=p_batch_id\n), ex AS (SELECT fe.delivery_challan_id dc_id,jsonb_agg(jsonb_build_object('id',fe.id,'voucher_number',fe.voucher_number,'category',fe.expense_category,'total_amount',fe.amount,'description',fe.description,'expense_date',fe.expense_date)) expenses FROM public.finance_expenses fe WHERE fe.expense_category IN ('delivery_sales','loading_sales') AND fe.approval_status='approved' AND fe.delivery_challan_id IN (SELECT DISTINCT dc_id FROM x WHERE dc_id IS NOT NULL) GROUP BY fe.delivery_challan_id)\nSELECT jsonb_build_object('batch',(SELECT jsonb_build_object('batch_id',b.id,'batch_number',b.batch_number,'product_name',p.product_name,'product_code',COALESCE(p.product_code,''),'product_unit',COALESCE(p.unit,'kg'),'current_stock',b.current_stock) FROM public.batches b JOIN public.products p ON p.id=b.product_id WHERE b.id=p_batch_id),'orders',COALESCE((SELECT jsonb_agg(jsonb_build_object('line_id',x.line_id,'invoice_id',x.invoice_id,'invoice_number',x.invoice_number,'invoice_date',x.invoice_date,'customer_id',x.customer_id,'customer_name',x.customer_name,'sales_order_id',x.sales_order_id,'so_number',x.so_number,'dc_id',x.dc_id,'dc_number',x.dc_number,'quantity',x.quantity,'selling_price',x.selling_price,'unit_price',x.selling_price,'gross_sales',x.gross_sales,'unit_cost',x.unit_cost,'line_cost',x.line_cost,'line_sales_expense',x.line_sales_expense,'net_selling_realization',x.gross_sales-x.line_sales_expense,'gross_profit',CASE WHEN x.line_cost IS NULL THEN NULL ELSE x.gross_sales-x.line_cost END,'profit',CASE WHEN x.line_cost IS NULL THEN NULL ELSE x.gross_sales-x.line_cost-x.line_sales_expense END,'profit_margin_pct',CASE WHEN x.line_cost IS NULL OR x.gross_sales=0 THEN NULL ELSE ROUND((x.gross_sales-x.line_cost-x.line_sales_expense)/x.gross_sales*100,2) END,'cogs_resolution',x.cogs_resolution,'expenses',COALESCE(ex.expenses,'[]'::jsonb)) ORDER BY x.invoice_date DESC,x.invoice_number) FROM x LEFT JOIN ex USING(dc_id)),'[]'::jsonb));\n$$","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_batch_orders(uuid,date,date) TO authenticated",COMMIT}	restore_sales_profitability_batch_orders_shape	\N	\N	\N
20260906045533	{"BEGIN;\n\nCREATE OR REPLACE FUNCTION public.get_sales_profitability_product_batches(\n  p_product_id uuid,\n  p_start_date date,\n  p_end_date date\n)\nRETURNS jsonb\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nWITH l AS (\n  SELECT ar.*, sii.unit_price,\n    ROUND(ar.quantity * sii.unit_price, 2) AS gross_sales,\n    b.batch_number,\n    b.current_stock,\n    COALESCE(le.sales_expense, 0) AS sales_expense,\n    b.import_price,\n    b.import_price_usd,\n    b.exchange_rate_usd_to_idr,\n    b.duty_charges,\n    b.freight_charges,\n    b.other_charges,\n    b.landed_cost_per_unit,\n    b.cost_per_unit AS batch_cost_per_unit\n  FROM public.get_authoritative_sales_line_cogs(p_start_date, p_end_date) ar\n  JOIN public.sales_invoice_items sii ON sii.id = ar.line_id\n  LEFT JOIN public.batches b ON b.id = ar.batch_id\n  LEFT JOIN public.get_sales_profitability_line_expenses(p_start_date, p_end_date) le ON le.line_id = ar.line_id\n  WHERE ar.product_id = p_product_id\n), b AS (\n  SELECT\n    batch_id,\n    COALESCE(batch_number, 'Unassigned Batch') AS batch_number,\n    COALESCE(current_stock, 0) AS current_stock,\n    SUM(quantity) AS sold_qty,\n    SUM(gross_sales) AS gross_sales,\n    SUM(authoritative_cogs) AS product_cost,\n    SUM(sales_expense) AS sales_expense,\n    CASE WHEN COUNT(authoritative_cogs) = COUNT(*) THEN SUM(gross_sales) - SUM(authoritative_cogs) END AS gross_profit,\n    CASE WHEN COUNT(authoritative_cogs) = COUNT(*) THEN SUM(gross_sales) - SUM(authoritative_cogs) - SUM(sales_expense) END AS profit_after_sales_expense,\n    CASE\n      WHEN COUNT(authoritative_cogs) = COUNT(*) THEN ROUND(SUM(authoritative_cogs) / NULLIF(SUM(quantity), 0), 2)\n      WHEN MAX(COALESCE(NULLIF(landed_cost_per_unit, 0), NULLIF(batch_cost_per_unit, 0), NULLIF(import_price, 0))) IS NOT NULL\n        THEN MAX(COALESCE(NULLIF(landed_cost_per_unit, 0), NULLIF(batch_cost_per_unit, 0), NULLIF(import_price, 0)))\n      ELSE NULL\n    END AS cost_per_unit,\n    ROUND(SUM(gross_sales) / NULLIF(SUM(quantity), 0), 2) AS avg_selling_price,\n    ROUND(SUM(sales_expense) / NULLIF(SUM(quantity), 0), 2) AS sales_expense_per_unit,\n    ROUND((SUM(gross_sales) - SUM(sales_expense)) / NULLIF(SUM(quantity), 0), 2) AS net_selling_price_per_unit,\n    CASE WHEN COUNT(authoritative_cogs) = COUNT(*) THEN ROUND((SUM(gross_sales) - SUM(authoritative_cogs) - SUM(sales_expense)) / NULLIF(SUM(quantity), 0), 2) END AS profit_per_unit,\n    CASE WHEN COUNT(authoritative_cogs) = COUNT(*) AND SUM(gross_sales) <> 0 THEN ROUND((SUM(gross_sales) - SUM(authoritative_cogs) - SUM(sales_expense)) / SUM(gross_sales) * 100, 2) END AS profit_margin_pct,\n    COUNT(authoritative_cogs) AS costed_lines,\n    COUNT(*) AS total_lines,\n    CASE WHEN COUNT(authoritative_cogs) = 0 THEN 'unavailable' WHEN COUNT(authoritative_cogs) < COUNT(*) THEN 'partial' ELSE 'complete' END AS cost_coverage,\n    BOOL_OR(import_price IS NOT NULL OR landed_cost_per_unit IS NOT NULL) AS is_imported,\n    jsonb_build_object(\n      'import_price', MAX(import_price),\n      'import_price_usd', MAX(import_price_usd),\n      'exchange_rate', MAX(exchange_rate_usd_to_idr),\n      'duty_charges', MAX(duty_charges),\n      'freight_charges', MAX(freight_charges),\n      'other_charges', MAX(other_charges),\n      'landed_cost_per_unit', MAX(landed_cost_per_unit),\n      'local_cost_per_unit', MAX(batch_cost_per_unit)\n    ) AS cost_breakdown\n  FROM l\n  GROUP BY batch_id, batch_number, current_stock\n), p AS (\n  SELECT\n    pr.id AS product_id,\n    pr.product_name,\n    COALESCE(pr.product_code, '') AS product_code,\n    COALESCE(pr.unit, 'kg') AS product_unit,\n    COALESCE(SUM(b.sold_qty), 0) AS sold_qty,\n    COALESCE(SUM(b.gross_sales), 0) AS gross_sales,\n    COALESCE(SUM(b.product_cost), 0) AS product_cost,\n    COALESCE(SUM(b.sales_expense), 0) AS sales_expense,\n    COALESCE(SUM(b.costed_lines), 0) AS costed_lines,\n    COALESCE(SUM(b.total_lines), 0) AS total_lines,\n    CASE WHEN SUM(b.costed_lines) = SUM(b.total_lines) THEN SUM(b.gross_profit) END AS gross_profit,\n    CASE WHEN SUM(b.costed_lines) = SUM(b.total_lines) THEN SUM(b.profit_after_sales_expense) END AS profit_after_sales_expense\n  FROM public.products pr\n  LEFT JOIN b ON true\n  WHERE pr.id = p_product_id\n  GROUP BY pr.id, pr.product_name, pr.product_code, pr.unit\n)\nSELECT jsonb_build_object(\n  'product', (SELECT to_jsonb(p) FROM p),\n  'batches', COALESCE((SELECT jsonb_agg(to_jsonb(b) ORDER BY b.profit_after_sales_expense DESC NULLS LAST, b.batch_number) FROM b), '[]'::jsonb)\n);\n$function$;\n\nGRANT EXECUTE ON FUNCTION public.get_sales_profitability_product_batches(uuid,date,date) TO authenticated;\nCOMMIT;"}	restore_historical_batch_cost_display	simplykool@gmail.com	\N	\N
20260906130000	{"-- Restore canonical profitability calculations, metrics, and reconciliation\n-- while preserving authoritative accounting COGS and sales expense resolvers.\nBEGIN","-- 1. Summary function: preserve authoritative COGS and sales expenses,\n--    compute canonical metrics for all products, and clearly report partial coverage.\nCREATE OR REPLACE FUNCTION public.get_sales_profitability_summary(p_start_date date, p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$\nWITH lines AS (\n  SELECT\n    ar.*,\n    si.invoice_date,\n    si.invoice_number,\n    si.customer_id,\n    COALESCE(c.company_name, 'Unknown Customer') AS customer_name,\n    si.sales_order_id,\n    so.so_number,\n    sii.unit_price,\n    ROUND(sii.quantity * sii.unit_price, 2) AS line_gross_sales,\n    p.product_name,\n    COALESCE(p.product_code, '') AS product_code,\n    COALESCE(p.unit, 'kg') AS product_unit,\n    b.batch_number,\n    COALESCE(b.landed_cost_per_unit, b.cost_per_unit) AS batch_unit_cost,\n    COALESCE(le.sales_expense, 0) AS line_sales_expense,\n    dci.challan_id AS dc_id,\n    dc.challan_number AS dc_number\n  FROM public.get_authoritative_sales_line_cogs(p_start_date, p_end_date) ar\n  JOIN public.sales_invoice_items sii ON sii.id = ar.line_id\n  JOIN public.sales_invoices si ON si.id = ar.invoice_id\n  JOIN public.products p ON p.id = ar.product_id\n  LEFT JOIN public.customers c ON c.id = si.customer_id\n  LEFT JOIN public.sales_orders so ON so.id = si.sales_order_id\n  LEFT JOIN public.batches b ON b.id = ar.batch_id\n  LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n  LEFT JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  LEFT JOIN public.get_sales_profitability_line_expenses(p_start_date, p_end_date) le ON le.line_id = ar.line_id\n),\nunallocated AS (\n  SELECT COALESCE(SUM(fe.amount), 0) AS amount\n  FROM public.finance_expenses fe\n  WHERE fe.expense_category IN ('delivery_sales', 'loading_sales')\n    AND fe.approval_status = 'approved'\n    AND fe.expense_date BETWEEN p_start_date AND p_end_date\n    AND (fe.delivery_challan_id IS NULL OR NOT EXISTS (SELECT 1 FROM lines l WHERE l.dc_id = fe.delivery_challan_id))\n),\nprod AS (\n  SELECT\n    product_id,\n    MAX(product_name) AS product_name,\n    MAX(product_code) AS product_code,\n    MAX(product_unit) AS product_unit,\n    COALESCE((SELECT SUM(b.current_stock) FROM public.batches b WHERE b.product_id = l.product_id AND b.is_active), 0) AS current_stock,\n    SUM(quantity) AS sold_qty,\n    SUM(line_gross_sales) AS gross_sales,\n    SUM(authoritative_cogs) AS product_cost,\n    SUM(line_sales_expense) AS sales_expense,\n    ROUND(SUM(line_gross_sales) / NULLIF(SUM(quantity), 0), 2) AS avg_selling_price,\n    ROUND(SUM(line_sales_expense) / NULLIF(SUM(quantity), 0), 2) AS sales_expense_per_unit,\n    ROUND((SUM(line_gross_sales) - SUM(line_sales_expense)) / NULLIF(SUM(quantity), 0), 2) AS net_selling_price_per_unit,\n    -- Landed cost: weighted average of known authoritative COGS per unit, fallback to weighted average of batch unit cost if costed lines exist\n    COALESCE(\n      ROUND(SUM(authoritative_cogs) / NULLIF(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN quantity ELSE 0 END), 0), 2),\n      ROUND(SUM(quantity * batch_unit_cost) / NULLIF(SUM(quantity), 0), 2)\n    ) AS avg_landed_cost,\n    -- Gross profit: realized gross profit on known COGS lines\n    ROUND(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales - authoritative_cogs ELSE 0 END), 2) AS gross_profit,\n    -- Profit after sales expense: gross profit on costed lines minus sales expense on costed lines\n    ROUND(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales - authoritative_cogs - line_sales_expense ELSE 0 END), 2) AS profit_after_sales_expense,\n    -- Profit per unit: on costed volume\n    ROUND(\n      SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales - authoritative_cogs - line_sales_expense ELSE 0 END)\n      / NULLIF(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN quantity ELSE 0 END), 0),\n      2\n    ) AS profit_per_unit,\n    -- Profit margin %: on costed sales volume\n    CASE\n      WHEN SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales ELSE 0 END) = 0 THEN NULL\n      ELSE ROUND(\n        SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales - authoritative_cogs - line_sales_expense ELSE 0 END)\n        / SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales ELSE 0 END) * 100,\n        2\n      )\n    END AS profit_margin_pct,\n    COUNT(authoritative_cogs) AS costed_lines,\n    COUNT(*) AS total_lines,\n    COUNT(authoritative_cogs) < COUNT(*) AS has_unreported_cost\n  FROM lines l\n  GROUP BY product_id\n),\ninv AS (\n  SELECT\n    invoice_id,\n    MAX(invoice_date) AS invoice_date,\n    MAX(posted_invoice_cogs) AS product_cost,\n    SUM(line_gross_sales) AS gross_sales,\n    SUM(quantity) AS total_qty_sold,\n    SUM(line_sales_expense) AS sales_expenses\n  FROM lines\n  GROUP BY invoice_id\n),\nmonths AS (\n  SELECT\n    DATE_TRUNC('month', invoice_date)::date AS month_start,\n    TO_CHAR(DATE_TRUNC('month', invoice_date), 'Mon YYYY') AS month_label,\n    SUM(gross_sales) AS gross_sales,\n    SUM(product_cost) AS product_cost,\n    SUM(sales_expenses) AS sales_expenses,\n    SUM(total_qty_sold) AS total_qty_sold,\n    COUNT(*) AS order_count\n  FROM inv\n  GROUP BY 1, 2\n),\ncompany AS (\n  SELECT\n    COALESCE(SUM(gross_sales), 0) AS gross_sales,\n    COALESCE(SUM(product_cost), 0) AS product_cost,\n    COALESCE(SUM(sales_expenses), 0) + (SELECT amount FROM unallocated) AS sales_expenses,\n    (SELECT amount FROM unallocated) AS unallocated_sales_expenses,\n    COALESCE(SUM(total_qty_sold), 0) AS total_qty_sold,\n    COUNT(*) AS order_count,\n    (SELECT COUNT(DISTINCT product_id) FROM lines) AS product_count\n  FROM inv\n)\nSELECT jsonb_build_object(\n  'company', jsonb_build_object(\n    'gross_sales', c.gross_sales,\n    'product_cost', c.product_cost,\n    'sales_expenses', c.sales_expenses,\n    'unallocated_sales_expenses', c.unallocated_sales_expenses,\n    'gross_profit', c.gross_sales - c.product_cost,\n    'profit_after_sales_expenses', c.gross_sales - c.product_cost - c.sales_expenses,\n    'profit_margin_pct', CASE WHEN c.gross_sales = 0 THEN NULL ELSE ROUND((c.gross_sales - c.product_cost - c.sales_expenses) / c.gross_sales * 100, 2) END,\n    'total_qty_sold', c.total_qty_sold,\n    'order_count', c.order_count,\n    'product_count', c.product_count\n  ),\n  'products', COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.product_name) FROM prod p), '[]'::jsonb),\n  'monthly', COALESCE((\n    SELECT jsonb_agg(\n      jsonb_build_object(\n        'month_label', m.month_label,\n        'month_start', m.month_start,\n        'gross_sales', m.gross_sales,\n        'product_cost', m.product_cost,\n        'sales_expenses', m.sales_expenses,\n        'gross_profit', m.gross_sales - m.product_cost,\n        'profit_after_sales_expenses', m.gross_sales - m.product_cost - m.sales_expenses,\n        'profit_margin_pct', CASE WHEN m.gross_sales = 0 THEN NULL ELSE ROUND((m.gross_sales - m.product_cost - m.sales_expenses) / m.gross_sales * 100, 2) END,\n        'total_qty_sold', m.total_qty_sold,\n        'order_count', m.order_count\n      ) ORDER BY m.month_start\n    ) FROM months m\n  ), '[]'::jsonb)\n)\nFROM company c;\n$$","-- 2. Product batches drilldown: return complete canonical product summary and batch rows\nCREATE OR REPLACE FUNCTION public.get_sales_profitability_product_batches(p_product_id uuid, p_start_date date, p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$\nWITH l AS (\n  SELECT\n    ar.*,\n    sii.unit_price,\n    ROUND(ar.quantity * sii.unit_price, 2) AS gross_sales,\n    b.batch_number,\n    b.current_stock,\n    COALESCE(le.sales_expense, 0) AS sales_expense,\n    b.import_price,\n    b.import_price_usd,\n    b.exchange_rate_usd_to_idr,\n    b.duty_charges,\n    b.freight_charges,\n    b.other_charges,\n    b.landed_cost_per_unit,\n    b.cost_per_unit\n  FROM public.get_authoritative_sales_line_cogs(p_start_date, p_end_date) ar\n  JOIN public.sales_invoice_items sii ON sii.id = ar.line_id\n  LEFT JOIN public.batches b ON b.id = ar.batch_id\n  LEFT JOIN public.get_sales_profitability_line_expenses(p_start_date, p_end_date) le ON le.line_id = ar.line_id\n  WHERE ar.product_id = p_product_id\n),\nb AS (\n  SELECT\n    batch_id,\n    COALESCE(batch_number, 'Unassigned Batch') AS batch_number,\n    COALESCE(current_stock, 0) AS current_stock,\n    SUM(quantity) AS sold_qty,\n    SUM(gross_sales) AS gross_sales,\n    SUM(authoritative_cogs) AS product_cost,\n    SUM(sales_expense) AS sales_expense,\n    ROUND(SUM(gross_sales) / NULLIF(SUM(quantity), 0), 2) AS avg_selling_price,\n    ROUND(SUM(sales_expense) / NULLIF(SUM(quantity), 0), 2) AS sales_expense_per_unit,\n    ROUND((SUM(gross_sales) - SUM(sales_expense)) / NULLIF(SUM(quantity), 0), 2) AS net_selling_price_per_unit,\n    -- Cost per unit: authoritative cost per unit if costed, otherwise batch landed/local cost\n    COALESCE(\n      ROUND(SUM(authoritative_cogs) / NULLIF(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN quantity ELSE 0 END), 0), 2),\n      MAX(COALESCE(landed_cost_per_unit, cost_per_unit))\n    ) AS cost_per_unit,\n    -- Gross profit & Profit after sales expense on costed lines\n    ROUND(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN gross_sales - authoritative_cogs ELSE 0 END), 2) AS gross_profit,\n    ROUND(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN gross_sales - authoritative_cogs - sales_expense ELSE 0 END), 2) AS profit_after_sales_expense,\n    ROUND(\n      SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN gross_sales - authoritative_cogs - sales_expense ELSE 0 END)\n      / NULLIF(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN quantity ELSE 0 END), 0),\n      2\n    ) AS profit_per_unit,\n    CASE\n      WHEN SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN gross_sales ELSE 0 END) = 0 THEN NULL\n      ELSE ROUND(\n        SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN gross_sales - authoritative_cogs - sales_expense ELSE 0 END)\n        / SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN gross_sales ELSE 0 END) * 100,\n        2\n      )\n    END AS profit_margin_pct,\n    COUNT(authoritative_cogs) AS costed_lines,\n    COUNT(*) AS total_lines,\n    CASE\n      WHEN COUNT(authoritative_cogs) = 0 THEN 'unavailable'\n      WHEN COUNT(authoritative_cogs) < COUNT(*) THEN 'partial'\n      ELSE 'complete'\n    END AS cost_coverage,\n    BOOL_OR(import_price IS NOT NULL OR landed_cost_per_unit IS NOT NULL) AS is_imported,\n    jsonb_build_object(\n      'import_price', MAX(import_price),\n      'import_price_usd', MAX(import_price_usd),\n      'exchange_rate', MAX(exchange_rate_usd_to_idr),\n      'duty_charges', MAX(duty_charges),\n      'freight_charges', MAX(freight_charges),\n      'other_charges', MAX(other_charges),\n      'landed_cost_per_unit', MAX(landed_cost_per_unit),\n      'local_cost_per_unit', MAX(cost_per_unit)\n    ) AS cost_breakdown\n  FROM l\n  GROUP BY batch_id, batch_number, current_stock\n),\np AS (\n  SELECT\n    pr.id AS product_id,\n    pr.product_name,\n    COALESCE(pr.product_code, '') AS product_code,\n    COALESCE(pr.unit, 'kg') AS product_unit,\n    COALESCE((SELECT SUM(cur_b.current_stock) FROM public.batches cur_b WHERE cur_b.product_id = pr.id AND cur_b.is_active), 0) AS current_stock,\n    COALESCE(SUM(b.sold_qty), 0) AS sold_qty,\n    COALESCE(SUM(b.gross_sales), 0) AS gross_sales,\n    COALESCE(SUM(b.product_cost), 0) AS product_cost,\n    COALESCE(SUM(b.sales_expense), 0) AS sales_expense,\n    COALESCE(SUM(b.costed_lines), 0) AS costed_lines,\n    COALESCE(SUM(b.total_lines), 0) AS total_lines,\n    ROUND(COALESCE(SUM(b.gross_sales), 0) / NULLIF(SUM(b.sold_qty), 0), 2) AS avg_selling_price,\n    ROUND(COALESCE(SUM(b.sales_expense), 0) / NULLIF(SUM(b.sold_qty), 0), 2) AS sales_expense_per_unit,\n    ROUND((COALESCE(SUM(b.gross_sales), 0) - COALESCE(SUM(b.sales_expense), 0)) / NULLIF(SUM(b.sold_qty), 0), 2) AS net_selling_price_per_unit,\n    ROUND(COALESCE(SUM(b.product_cost), 0) / NULLIF(SUM(CASE WHEN b.costed_lines > 0 THEN b.sold_qty ELSE 0 END), 0), 2) AS avg_landed_cost,\n    ROUND(SUM(b.gross_profit), 2) AS gross_profit,\n    ROUND(SUM(b.profit_after_sales_expense), 2) AS profit_after_sales_expense,\n    ROUND(SUM(b.profit_after_sales_expense) / NULLIF(SUM(CASE WHEN b.costed_lines > 0 THEN b.sold_qty ELSE 0 END), 0), 2) AS profit_per_unit,\n    CASE\n      WHEN SUM(CASE WHEN b.costed_lines > 0 THEN b.gross_sales ELSE 0 END) = 0 THEN NULL\n      ELSE ROUND(SUM(b.profit_after_sales_expense) / SUM(CASE WHEN b.costed_lines > 0 THEN b.gross_sales ELSE 0 END) * 100, 2)\n    END AS profit_margin_pct\n  FROM public.products pr\n  LEFT JOIN b ON true\n  WHERE pr.id = p_product_id\n  GROUP BY pr.id, pr.product_name, pr.product_code, pr.unit\n)\nSELECT jsonb_build_object(\n  'product', (SELECT to_jsonb(p) FROM p),\n  'batches', COALESCE((SELECT jsonb_agg(to_jsonb(b) ORDER BY b.profit_after_sales_expense DESC NULLS LAST) FROM b), '[]'::jsonb)\n);\n$$","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_summary(date, date) TO authenticated","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_product_batches(uuid, date, date) TO authenticated",COMMIT}	restore_canonical_sales_profitability_metrics	\N	\N	\N
20260906230000	{"-- Migration: 20260906230000_canonicalize_historical_repair_expense_journals.sql\n-- Description: Canonicalize active replacement journals for EXP/26-26/139 and EXP/26/177\n--              so that edit_approved_finance_expense_atomic recognizes them as canonical active journals.\n--\n-- Target 1: EXP/26-26/139 (id: 3b56b2ee-c157-4da8-8bdc-c0bea9b3316d)\n--           Active replacement journal: JE2609-0018 (id: 2cde9efd-9b22-4ba6-acbe-f712d6bb0497)\n--\n-- Target 2: EXP/26/177 (id: e95a4775-cca4-4f38-830b-fcfd7ed5a1f3)\n--           Active replacement journal: JE2609-0022 (id: 4d89886c-eab1-4d39-8a46-f499319e1b69)\n\nDO $$\nDECLARE\n  v_count integer;\n  v_exp1_state text;\n  v_exp2_state text;\nBEGIN\n  -- 1. Canonicalize JE2609-0018 for EXP/26-26/139\n  UPDATE public.journal_entries\n  SET source_module = 'expenses',\n      reference_number = 'EXP-3b56b2ee-c157-4da8-8bdc-c0bea9b3316d'\n  WHERE id = '2cde9efd-9b22-4ba6-acbe-f712d6bb0497'\n    AND entry_number = 'JE2609-0018'\n    AND reference_id = '3b56b2ee-c157-4da8-8bdc-c0bea9b3316d'\n    AND is_posted = true\n    AND NOT COALESCE(is_reversed, false);\n\n  GET DIAGNOSTICS v_count = ROW_COUNT;\n  IF v_count <> 1 THEN\n    RAISE EXCEPTION 'Failed to update JE2609-0018: expected 1 row, got %', v_count;\n  END IF;\n\n  -- 2. Canonicalize JE2609-0022 for EXP/26/177\n  UPDATE public.journal_entries\n  SET source_module = 'expenses',\n      reference_number = 'EXP-e95a4775-cca4-4f38-830b-fcfd7ed5a1f3'\n  WHERE id = '4d89886c-eab1-4d39-8a46-f499319e1b69'\n    AND entry_number = 'JE2609-0022'\n    AND reference_id = 'e95a4775-cca4-4f38-830b-fcfd7ed5a1f3'\n    AND is_posted = true\n    AND NOT COALESCE(is_reversed, false);\n\n  GET DIAGNOSTICS v_count = ROW_COUNT;\n  IF v_count <> 1 THEN\n    RAISE EXCEPTION 'Failed to update JE2609-0022: expected 1 row, got %', v_count;\n  END IF;\n\n  -- 3. Verify effective_expense_posting_state invariants\n  SELECT effective_posting_state INTO v_exp1_state\n  FROM public.effective_expense_posting_state\n  WHERE expense_id = '3b56b2ee-c157-4da8-8bdc-c0bea9b3316d';\n\n  IF v_exp1_state <> 'ACTIVE' THEN\n    RAISE EXCEPTION 'EXP/26-26/139 effective_posting_state expected ACTIVE, got %', v_exp1_state;\n  END IF;\n\n  SELECT effective_posting_state INTO v_exp2_state\n  FROM public.effective_expense_posting_state\n  WHERE expense_id = 'e95a4775-cca4-4f38-830b-fcfd7ed5a1f3';\n\n  IF v_exp2_state <> 'ACTIVE' THEN\n    RAISE EXCEPTION 'EXP/26/177 effective_posting_state expected ACTIVE, got %', v_exp2_state;\n  END IF;\nEND $$"}	canonicalize_historical_repair_expense_journals	\N	\N	\N
20260907140000	{"-- ============================================================================\n-- Fix Sales Order Approval Product Reservation Pending Approval Bug\n-- ============================================================================\n-- Problem:\n-- When a sales order in 'pending_approval' was approved,\n-- reconcile_so_product_reservation_v2 checked:\n--   WHEN v_item.so_status IN ('approved', 'stock_reserved', 'shortage', 'pending_delivery', 'partially_delivered')\n-- Because 'pending_approval' was omitted from this list, v_required evaluated to 0.\n-- The function returned 0 without reserving available stock.\n-- approve_sales_order_product_reservation_v2 then assumed a shortage existed,\n-- set status = 'shortage', and generated a bogus pending import requirement,\n-- causing the Stock summary to display a false shortage even with sufficient stock.\n--\n-- Fix:\n-- 1. Add 'pending_approval' to reconcile_so_product_reservation_v2 status list.\n-- 2. In approve_sales_order_product_reservation_v2, ensure pending import\n--    requirements are cancelled when an order achieves full stock reservation.\n-- 3. Re-reconcile SO-2026-0075 to reserve its 500 kg from Batch 250816w2,\n--    transition it to 'stock_reserved', and cancel its false import requirement.\n-- ============================================================================\n\nBEGIN","-- 1. Update reconcile_so_product_reservation_v2\nCREATE OR REPLACE FUNCTION public.reconcile_so_product_reservation_v2(\n  p_sales_order_item_id uuid,\n  p_reason text DEFAULT 'SO state reconciliation'::text\n)\nRETURNS numeric\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_item record;\n  v_res public.so_product_reservations%ROWTYPE;\n  v_delivered numeric;\n  v_required numeric;\n  v_delta numeric;\n  v_atp numeric;\n  v_grant numeric;\nBEGIN\n  SELECT soi.*, so.status::text AS so_status INTO v_item\n  FROM public.sales_order_items soi\n  JOIN public.sales_orders so ON so.id = soi.sales_order_id\n  WHERE soi.id = p_sales_order_item_id\n  FOR UPDATE OF soi, so;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Order item not found';\n  END IF;\n\n  -- Serialize ATP decisions for the product\n  PERFORM pg_advisory_xact_lock(hashtextextended(v_item.product_id::text, 0));\n\n  SELECT COALESCE(sum(dci.quantity), 0) INTO v_delivered\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  WHERE dci.sales_order_item_id = v_item.id\n    AND dc.approval_status = 'approved';\n\n  IF v_delivered > v_item.quantity THEN\n    RAISE EXCEPTION 'Delivered quantity exceeds ordered quantity';\n  END IF;\n\n  v_required := CASE\n    WHEN v_item.so_status IN ('pending_approval', 'approved', 'stock_reserved', 'shortage', 'pending_delivery', 'partially_delivered')\n      THEN v_item.quantity - v_delivered\n    ELSE 0\n  END;\n\n  SELECT * INTO v_res\n  FROM public.so_product_reservations\n  WHERE sales_order_item_id = v_item.id\n    AND status = 'active'\n  FOR UPDATE;\n\n  IF v_required = 0 THEN\n    IF FOUND THEN\n      UPDATE public.so_product_reservations\n      SET reserved_quantity = 0,\n          status = 'released',\n          closed_at = now(),\n          updated_at = now(),\n          close_reason = p_reason\n      WHERE id = v_res.id;\n\n      INSERT INTO public.so_product_reservation_events(\n        reservation_id, sales_order_id, sales_order_item_id, event_type,\n        quantity_delta, quantity_after, reason, actor_id\n      ) VALUES (\n        v_res.id, v_item.sales_order_id, v_item.id, 'released',\n        -v_res.reserved_quantity, 0, p_reason, auth.uid()\n      );\n    END IF;\n    RETURN 0;\n  END IF;\n\n  -- Calculate available product ATP (excluding this SO item's existing active reservation if any)\n  v_atp := public.product_available_to_promise(\n    v_item.product_id,\n    CASE WHEN v_res.id IS NOT NULL THEN v_item.id ELSE NULL END\n  );\n\n  -- Reserve what is physically available; unfulfilled quantity is handled as shortage\n  v_grant := LEAST(v_required, GREATEST(COALESCE(v_atp, 0), 0));\n\n  IF NOT FOUND THEN\n    IF v_grant > 0 THEN\n      INSERT INTO public.so_product_reservations(\n        sales_order_id, sales_order_item_id, product_id, reserved_quantity, created_by\n      ) VALUES (\n        v_item.sales_order_id, v_item.id, v_item.product_id, v_grant, auth.uid()\n      ) RETURNING * INTO v_res;\n\n      INSERT INTO public.so_product_reservation_events(\n        reservation_id, sales_order_id, sales_order_item_id, event_type,\n        quantity_delta, quantity_after, reason, actor_id\n      ) VALUES (\n        v_res.id, v_item.sales_order_id, v_item.id, 'created',\n        v_grant, v_grant, p_reason, auth.uid()\n      );\n    END IF;\n  ELSE\n    IF v_res.product_id <> v_item.product_id THEN\n      RAISE EXCEPTION 'Cannot change product on an actively reserved SO item';\n    END IF;\n\n    IF v_grant = 0 THEN\n      UPDATE public.so_product_reservations\n      SET reserved_quantity = 0,\n          status = 'released',\n          closed_at = now(),\n          updated_at = now(),\n          close_reason = p_reason\n      WHERE id = v_res.id;\n\n      INSERT INTO public.so_product_reservation_events(\n        reservation_id, sales_order_id, sales_order_item_id, event_type,\n        quantity_delta, quantity_after, reason, actor_id\n      ) VALUES (\n        v_res.id, v_item.sales_order_id, v_item.id, 'released',\n        -v_res.reserved_quantity, 0, p_reason, auth.uid()\n      );\n    ELSE\n      v_delta := v_grant - v_res.reserved_quantity;\n      IF v_delta <> 0 THEN\n        UPDATE public.so_product_reservations\n        SET reserved_quantity = v_grant,\n            updated_at = now()\n        WHERE id = v_res.id;\n\n        INSERT INTO public.so_product_reservation_events(\n          reservation_id, sales_order_id, sales_order_item_id, event_type,\n          quantity_delta, quantity_after, reason, actor_id\n        ) VALUES (\n          v_res.id, v_item.sales_order_id, v_item.id,\n          CASE WHEN v_delta > 0 THEN 'increased' ELSE 'decreased' END,\n          v_delta, v_grant, p_reason, auth.uid()\n        );\n      END IF;\n    END IF;\n  END IF;\n\n  RETURN v_grant;\nEND;\n$$","-- 2. Update approve_sales_order_product_reservation_v2\nCREATE OR REPLACE FUNCTION public.approve_sales_order_product_reservation_v2(\n  p_so_id uuid,\n  p_approved_by uuid\n)\nRETURNS TABLE(success boolean, message text, shortage_items jsonb)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  r record;\n  v_delivered numeric;\n  v_item_required numeric;\n  v_reserved numeric;\n  v_shortage_qty numeric;\n  v_shortage_list jsonb := '[]'::jsonb;\n  v_has_shortage boolean := false;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'manager', 'warehouse'])\n     AND current_setting('app.canonical_reservation_engine', true) IS DISTINCT FROM 'on' THEN\n    RAISE EXCEPTION 'Permission denied for SO product reservation approval';\n  END IF;\n\n  PERFORM 1 FROM public.sales_orders WHERE id = p_so_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Order not found';\n  END IF;\n\n  PERFORM set_config('app.canonical_reservation_engine', 'on', true);\n\n  UPDATE public.sales_orders\n  SET approved_by = COALESCE(p_approved_by, auth.uid()),\n      approved_at = COALESCE(approved_at, now())\n  WHERE id = p_so_id;\n\n  FOR r IN\n    SELECT id, product_id, quantity\n    FROM public.sales_order_items\n    WHERE sales_order_id = p_so_id\n    ORDER BY product_id, id\n  LOOP\n    v_reserved := public.reconcile_so_product_reservation_v2(r.id, 'SO approval/re-approval');\n\n    SELECT COALESCE(sum(dci.quantity), 0) INTO v_delivered\n    FROM public.delivery_challan_items dci\n    JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n    WHERE dci.sales_order_item_id = r.id\n      AND dc.approval_status = 'approved';\n\n    v_item_required := GREATEST(r.quantity - v_delivered, 0);\n\n    IF v_item_required > v_reserved THEN\n      v_has_shortage := true;\n      v_shortage_qty := v_item_required - v_reserved;\n      v_shortage_list := v_shortage_list || jsonb_build_object(\n        'product_id', r.product_id,\n        'required_qty', r.quantity,\n        'shortage_qty', v_shortage_qty\n      );\n    END IF;\n  END LOOP;\n\n  IF v_has_shortage THEN\n    UPDATE public.sales_orders\n    SET status = 'shortage',\n        updated_at = now()\n    WHERE id = p_so_id;\n\n    PERFORM public.fn_create_import_requirements(p_so_id, v_shortage_list);\n\n    RETURN QUERY\n    SELECT false, 'Partial stock reserved - shortage exists.'::text, v_shortage_list;\n  ELSE\n    UPDATE public.sales_orders\n    SET status = 'stock_reserved',\n        updated_at = now()\n    WHERE id = p_so_id;\n\n    -- Cancel any pending import requirements for this SO\n    UPDATE public.import_requirements\n    SET status = 'cancelled',\n        notes = COALESCE(notes || ' | ', '') ||\n          'Auto-cancelled: shortage resolved by stock reservation ' ||\n          to_char(now(), 'YYYY-MM-DD'),\n        updated_at = now()\n    WHERE sales_order_id = p_so_id\n      AND status = 'pending';\n\n    RETURN QUERY\n    SELECT true, 'Stock fully reserved'::text, '[]'::jsonb;\n  END IF;\nEND;\n$$","-- 3. Permissions\nREVOKE ALL ON FUNCTION public.reconcile_so_product_reservation_v2(uuid, text) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.reconcile_so_product_reservation_v2(uuid, text) TO authenticated, service_role","REVOKE ALL ON FUNCTION public.approve_sales_order_product_reservation_v2(uuid, uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.approve_sales_order_product_reservation_v2(uuid, uuid) TO authenticated, service_role","-- 4. Re-reconcile SO-2026-0075\nDO $$\nDECLARE\n  v_so_id uuid := '3e40aaec-9f4f-4c21-8354-444b9a705a5d';\n  v_admin_id uuid;\nBEGIN\n  IF EXISTS (SELECT 1 FROM public.sales_orders WHERE id = v_so_id AND status = 'shortage') THEN\n    SELECT approved_by INTO v_admin_id FROM public.sales_orders WHERE id = v_so_id;\n    PERFORM set_config('app.canonical_reservation_engine', 'on', true);\n    PERFORM public.approve_sales_order_product_reservation_v2(v_so_id, v_admin_id);\n  END IF;\nEND $$",COMMIT}	fix_so_approval_reservation_shortage_bug	\N	\N	\N
20260907143000	{"-- Migration: Fix finance views performance, missing indexes, and missing anon view grants\n-- 1. Index idx_bank_statement_lines_matched_payment to optimize LATERAL join in finance_exception_correction_dashboard\n-- 2. Fast set-based view for vw_canonical_tax_period_amounts (reduces query from 13-30s timeout to ~150ms)\n-- 3. Missing SELECT grants on missing_petty_cash_links, effective_expense_posting_state, and finance_historical_repair_exceptions\nBEGIN","-- 1. Index on bank_statement_lines for matched_payment_id\nCREATE INDEX IF NOT EXISTS idx_bank_statement_lines_matched_payment \n  ON public.bank_statement_lines (matched_payment_id) \n  WHERE matched_payment_id IS NOT NULL","-- 2. Fast set-based view for vw_canonical_tax_period_amounts\nCREATE OR REPLACE VIEW public.vw_canonical_tax_period_amounts AS\nWITH periods AS MATERIALIZED (SELECT * FROM public.tax_periods),\nactive_expenses AS MATERIALIZED (\n  SELECT fe.id,fe.pph_tax_period_id,fe.expense_date,fe.due_date,fe.pph_amount,fe.pph_code_id,fe.expense_category,fe.pib_pph_amount\n  FROM public.finance_expenses fe JOIN public.effective_expense_posting_state eps ON eps.expense_id=fe.id AND eps.effective_posting_state IN ('ACTIVE','REPLACED')\n  WHERE fe.approval_status='approved'\n), expense_pph AS (\n  SELECT p.id tax_period_id,\n    coalesce(sum(a.pph_amount) FILTER (WHERE a.expense_category NOT IN ('pib_import','pph_import') AND (p.tax_type='PPh_Unifikasi' OR tc.tax_type=p.tax_type)),0)\n    + coalesce(sum(CASE WHEN p.tax_type IN ('PPh22','PPh_Unifikasi') AND a.expense_category IN ('pib_import','pph_import') THEN CASE WHEN a.expense_category='pib_import' THEN coalesce(a.pib_pph_amount,0) ELSE coalesce(a.pph_amount,0) END ELSE 0 END),0) amount\n  FROM periods p LEFT JOIN active_expenses a ON a.pph_tax_period_id=p.id OR (a.pph_tax_period_id IS NULL AND a.expense_date BETWEEN p.period_start AND p.period_end)\n  LEFT JOIN public.tax_codes tc ON tc.id=a.pph_code_id WHERE p.tax_type<>'PPN' GROUP BY p.id\n), voucher_pph AS (\n  SELECT p.id tax_period_id,coalesce(sum(pv.pph_amount),0) amount\n  FROM periods p LEFT JOIN public.payment_vouchers pv ON pv.tax_period_id=p.id OR (pv.tax_period_id IS NULL AND pv.voucher_date BETWEEN p.period_start AND p.period_end)\n  LEFT JOIN public.tax_codes tc ON tc.id=pv.pph_code_id WHERE p.tax_type<>'PPN' AND coalesce(pv.is_posted,false) AND pv.pph_amount>0 AND (p.tax_type='PPh_Unifikasi' OR tc.tax_type=p.tax_type) GROUP BY p.id\n), paid AS (\n  SELECT p.id tax_period_id,coalesce(sum(t.amount) FILTER (WHERE t.status IN ('posted','reconciled')),0) amount,count(*) FILTER (WHERE t.status='reconciled') reconciled_count,count(*) FILTER (WHERE t.status IN ('draft','posted')) unreconciled_count\n  FROM periods p LEFT JOIN public.tax_payments t ON t.tax_period_id=p.id GROUP BY p.id\n), missing_faktur AS (\n  SELECT tax_period_id,count(*) amount FROM public.sales_invoices WHERE coalesce(faktur_pajak_number,'')='' AND tax_amount>0 GROUP BY tax_period_id\n), resolved AS (\n  SELECT p.*,\n    CASE WHEN coalesce(pay.amount,0)>.01 OR p.status IN ('paid','filed','closed') THEN coalesce(p.pph_total,0)\n         ELSE coalesce(e.amount,0)+coalesce(v.amount,0) END source_pph,\n    coalesce(pay.amount,0) actual_paid,coalesce(pay.reconciled_count,0) reconciled_count,coalesce(pay.unreconciled_count,0) unreconciled_count,coalesce(m.amount,0) missing_faktur\n  FROM periods p LEFT JOIN expense_pph e ON e.tax_period_id=p.id LEFT JOIN voucher_pph v ON v.tax_period_id=p.id LEFT JOIN paid pay ON pay.tax_period_id=p.id LEFT JOIN missing_faktur m ON m.tax_period_id=p.id\n)\nSELECT id tax_period_id,fiscal_year,period_month,tax_type,status,filing_status,payment_due_date,filing_due_date,input_ppn_total,output_ppn_total,net_ppn,\n  (CASE WHEN tax_type='PPN' THEN 0 ELSE source_pph END)::numeric(18,2) pph_total,\n  (CASE WHEN tax_type='PPN' THEN coalesce(net_ppn,0) ELSE source_pph END)::numeric(18,2) total_tax,\n  actual_paid paid_amount,\n  greatest((CASE WHEN tax_type='PPN' THEN coalesce(net_ppn,0) ELSE source_pph END)-actual_paid,0) outstanding_amount,\n  greatest(actual_paid-(CASE WHEN tax_type='PPN' THEN coalesce(net_ppn,0) ELSE source_pph END),0) overpaid_amount,\n  (CASE WHEN tax_type='PPN' THEN coalesce(net_ppn,0) ELSE source_pph END)-actual_paid net_position,\n  public.fn_tax_period_payment_status(status,CASE WHEN tax_type='PPN' THEN coalesce(net_ppn,0) ELSE source_pph END,actual_paid,payment_due_date) payment_status,\n  public.fn_period_payment_source(CASE WHEN tax_type='PPN' THEN coalesce(net_ppn,0) ELSE source_pph END,actual_paid,0) payment_source,\n  reconciled_count reconciled_payments_count,\n  unreconciled_count unreconciled_payments_count,\n  missing_faktur missing_faktur_count\nFROM resolved","ALTER VIEW public.vw_canonical_tax_period_amounts SET (security_invoker=true)","CREATE OR REPLACE VIEW public.vw_tax_period_status AS \nSELECT c.tax_period_id id,c.fiscal_year,c.period_month,c.tax_type,c.status,c.filing_status,\n  c.payment_due_date,c.filing_due_date,c.net_ppn,c.pph_total,\n  c.reconciled_payments_count,c.unreconciled_payments_count,c.missing_faktur_count,\n  c.paid_amount,c.outstanding_amount,c.payment_status,c.payment_source,c.net_position,c.overpaid_amount\nFROM public.vw_canonical_tax_period_amounts c","ALTER VIEW public.vw_tax_period_status SET (security_invoker=true)","CREATE OR REPLACE VIEW public.vw_pph_by_period_type AS\nSELECT tax_period_id,fiscal_year,period_month,tax_type,pph_total,paid_amount pph_paid_total,\n  outstanding_amount pph_outstanding,status,payment_due_date,filing_due_date,payment_status,\n  payment_source,net_position pph_net_position,overpaid_amount pph_overpaid\nFROM public.vw_canonical_tax_period_amounts WHERE tax_type <> 'PPN'","ALTER VIEW public.vw_pph_by_period_type SET (security_invoker=true)","CREATE OR REPLACE VIEW public.vw_outstanding_tax AS \nSELECT tax_period_id,fiscal_year,period_month,tax_type,status,payment_due_date,outstanding_amount,paid_amount actual_payment_amount,overpaid_amount \nFROM public.vw_canonical_tax_period_amounts WHERE outstanding_amount>.01 OR overpaid_amount>.01","ALTER VIEW public.vw_outstanding_tax SET (security_invoker=true)","-- 3. Grants for views to ensure anon/authenticated/service_role can read\nGRANT SELECT ON public.missing_petty_cash_links TO anon, authenticated, service_role","GRANT SELECT ON public.effective_expense_posting_state TO anon, authenticated, service_role","GRANT SELECT ON public.finance_historical_repair_exceptions TO anon, authenticated, service_role","GRANT SELECT ON public.vw_canonical_tax_period_amounts TO anon, authenticated, service_role","GRANT SELECT ON public.vw_tax_period_status TO anon, authenticated, service_role","GRANT SELECT ON public.vw_pph_by_period_type TO anon, authenticated, service_role","GRANT SELECT ON public.vw_outstanding_tax TO anon, authenticated, service_role","NOTIFY pgrst, 'reload schema'",COMMIT}	fix_finance_views_performance_and_grants	\N	\N	\N
20260907143500	{"-- Grant SELECT on remaining finance historical repair and bank allocation tables to anon, authenticated, service_role\nBEGIN","GRANT SELECT ON public.bank_statement_allocations TO anon, authenticated, service_role","GRANT SELECT ON public.finance_historical_repair_items TO anon, authenticated, service_role","GRANT SELECT ON public.finance_historical_repair_runs TO anon, authenticated, service_role","GRANT SELECT ON public.finance_historical_repair_commands TO anon, authenticated, service_role","NOTIFY pgrst, 'reload schema'",COMMIT}	grant_remaining_finance_repair_tables	\N	\N	\N
20260907150000	{"-- Migration: 20260907150000_normalize_cancelled_expenses_approval_status.sql\n-- Ensure cancelled expenses have approval_status = 'cancelled' and are not left in 'pending_approval'\n\n-- 1. Correct any existing expenses that were cancelled/reversed but retained 'pending_approval'\nUPDATE public.finance_expenses\nSET approval_status = 'cancelled',\n    approved_by = NULL,\n    approved_at = NULL\nWHERE approval_status = 'pending_approval'\n  AND id IN (\n    SELECT expense_id\n    FROM public.effective_expense_posting_state\n    WHERE effective_posting_state = 'REVERSED'\n  )","-- 2. Explicitly ensure target expense EXP/26-26/052 is marked cancelled\nUPDATE public.finance_expenses\nSET approval_status = 'cancelled',\n    approved_by = NULL,\n    approved_at = NULL\nWHERE voucher_number = 'EXP/26-26/052'\n  AND approval_status <> 'cancelled'"}	normalize_cancelled_expenses_approval_status	\N	\N	\N
20260908153000	{"-- Migration: 20260908153000_repair_august_september_sales_cogs_snapshots.sql\n-- Description: Backfill authoritative historical COGS snapshots for August and September 2026 sales invoices\n--              and correct SAPJ-26-045 to its forensically proven historical posting allocation.\n-- Zero GL change, zero inventory change, zero batch cost change, zero revenue change.\n\nBEGIN","-- ============================================================================\n-- 1. PART 1: Correct SAPJ-26-045 to forensically proven historical values\n--    Diclofenac Potassium = Rp141,296.94/unit * 150 = Rp21,194,541.00\n--    Corn Starch BP       = Rp10,008.60/unit * 1000 = Rp10,008,600.00\n--    Total = Rp31,203,141.00 (reconciles 100% to JE2609-0007)\n-- ============================================================================\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 141296.94,\n    cogs_total_cost = 21194541.00\nWHERE id = '2886ee2a-c6f6-4073-8dbe-45da3c6ff63a'\n  AND invoice_id = '47b60acf-e3b7-44da-91ea-15c6e716bfe7'","UPDATE public.sales_invoice_items\nSET cogs_unit_cost = 10008.60,\n    cogs_total_cost = 10008600.00\nWHERE id = '47da953f-cfe3-4239-ac4a-33f69e0a156f'\n  AND invoice_id = '47b60acf-e3b7-44da-91ea-15c6e716bfe7'","-- ============================================================================\n-- 2. Multi-line Invoice SAPJ-26-044\n--    MCC PH-102 (Qty 25)  @ Rp42,348.49 = Rp1,058,712.25\n--    MCC PH-101 (Qty 100) @ Rp40,282.71 = Rp4,028,271.00\n--    Total = Rp5,086,983.25 (reconciles 100% to JE2609-0049)\n-- ============================================================================\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 42348.49,\n    cogs_total_cost = 1058712.25\nWHERE id = '5b6dd348-4b2d-4a0f-9461-1d97bf665e5a'\n  AND invoice_id = 'e3b01ec5-ec9e-4454-ad48-665852259d5d'","UPDATE public.sales_invoice_items\nSET cogs_unit_cost = 40282.71,\n    cogs_total_cost = 4028271.00\nWHERE id = 'ee70d8a3-c42c-4f42-8d77-babafb2b906b'\n  AND invoice_id = 'e3b01ec5-ec9e-4454-ad48-665852259d5d'","-- ============================================================================\n-- 3. Single-line Invoices (SAPJ-26-035 through SAPJ-26-053)\n--    Each single-line invoice has 100% of posted COGS uniquely attributable\n-- ============================================================================\n\n-- SAPJ-26-035 (Pregabalin, Qty 100, JE2609-0006 = Rp101,716,562.00)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 1017165.62,\n    cogs_total_cost = 101716562.00\nWHERE id = '1c1a4883-4fb3-4969-8c52-a1be1e8c9a67'","-- SAPJ-26-036 (Diclofenac Potassium, Qty 75, Net Posted COGS = Rp10,597,270.50 across JE2608-0067, HFR-260904-FCOGS-036, HFR-260904-FCOGS-FIX-16)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 141296.94,\n    cogs_total_cost = 10597270.50\nWHERE id = 'dfcc4439-dcfe-4c6a-b05a-a429cc12381e'","-- SAPJ-26-037 (Cetirizine HCl EP, Qty 25, Net Posted COGS = Rp14,700,479.50 across JE2608-0066, HFR-260904-FCOGS-037)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 588019.18,\n    cogs_total_cost = 14700479.50\nWHERE id = '4c7393a2-3d51-4abd-8e79-8efdb20c022d'","-- SAPJ-26-038 (Piperazine Phosphate, Qty 600, JE2609-0005 = Rp91,608,738.00)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 152681.23,\n    cogs_total_cost = 91608738.00\nWHERE id = 'f31d5bd0-1083-4ce3-9855-2f7294e985d1'","-- SAPJ-26-039 (Corn Starch BP, Qty 300, JE2609-0009 = Rp2,964,498.00)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 9881.66,\n    cogs_total_cost = 2964498.00\nWHERE id = '1e1869cf-2cb4-4c48-a3da-e6128531c934'","-- SAPJ-26-040 (Corn Starch BP, Qty 4525, JE2609-0008 = Rp44,714,511.50)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 9881.66,\n    cogs_total_cost = 44714511.50\nWHERE id = '4f651d4a-8af5-4a8d-9680-f2acd6f87dea'","-- SAPJ-26-041 (MCC PH-102, Qty 125, Net Posted COGS = Rp5,293,561.25 across JE2608-0051, HFR-260904-FCOGS-038, HFR-260904-FCOGS-FIX-17)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 42348.49,\n    cogs_total_cost = 5293561.25\nWHERE id = 'ec7d4d89-624e-4f41-8970-85cb724ffcc8'","-- SAPJ-26-042 (Diclofenac Sodium, Qty 200, JE2609-0047 = Rp36,000,000.00)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 180000.00,\n    cogs_total_cost = 36000000.00\nWHERE id = '04c9b531-689f-4291-8e5f-723b01290e18'","-- SAPJ-26-043 (Diclofenac Sodium, Qty 300, JE2609-0048 = Rp54,000,000.00)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 180000.00,\n    cogs_total_cost = 54000000.00\nWHERE id = 'bd57805a-d15e-4b8a-a118-21c71245f0b9'","-- SAPJ-26-046 (Corn Starch BP, Qty 500, JE2609-0025 = Rp5,004,300.00)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 10008.60,\n    cogs_total_cost = 5004300.00\nWHERE id = '85c2f253-6cc8-4f87-81fb-1775990d9a2e'","-- SAPJ-26-047 (Corn Starch BP, Qty 500, JE2609-0028 = Rp5,004,300.00)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 10008.60,\n    cogs_total_cost = 5004300.00\nWHERE id = '99c1f69b-5afb-4af1-bd68-d6142b474772'","-- SAPJ-26-048 (Cefixime USP, Qty 125, JE2609-0031 = Rp284,488,486.25)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 2275907.89,\n    cogs_total_cost = 284488486.25\nWHERE id = 'ab322cf1-225a-4d77-9898-b1452a178b2f'","-- SAPJ-26-049 (Corn Starch BP, Qty 4175, JE2609-0033 = Rp41,255,930.50)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 9881.66,\n    cogs_total_cost = 41255930.50\nWHERE id = '805bd9e9-6f4b-4faa-8a78-2830691ef8f8'","-- SAPJ-26-050 (Corn Starch BP, Qty 1000, JE2609-0035 = Rp10,008,600.00)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 10008.60,\n    cogs_total_cost = 10008600.00\nWHERE id = '3ec1e936-2e75-474b-a565-aac43d4ae824'","-- SAPJ-26-051 (MCC PH-101, Qty 500, JE2609-0037 = Rp20,141,355.00)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 40282.71,\n    cogs_total_cost = 20141355.00\nWHERE id = '53a41550-1b47-49a9-82f6-910c0ed12098'","-- SAPJ-26-052 (Corn Starch BP, Qty 7000, JE2609-0039 = Rp70,060,200.00)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 10008.60,\n    cogs_total_cost = 70060200.00\nWHERE id = '35974d7e-e595-4e96-a4a2-f1a699430648'","-- SAPJ-26-053 (MCC PH-101, Qty 125, JE2609-0041 = Rp5,035,338.75)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 40282.71,\n    cogs_total_cost = 5035338.75\nWHERE id = 'd2aa55c2-0df8-4ac8-ab78-1ed277b37350'","-- ============================================================================\n-- 4. Attribution on single-line COGS journal lines (links journal line to item)\n--    Preserves GL amounts and accounts while enabling direct item reconciliation\n-- ============================================================================\nUPDATE public.journal_entry_lines jel\nSET sales_invoice_item_id = sii.id,\n    batch_id = sii.batch_id\nFROM public.journal_entries je\nJOIN public.sales_invoices si ON si.id = je.reference_id\nJOIN public.sales_invoice_items sii ON sii.invoice_id = si.id\nWHERE jel.journal_entry_id = je.id\n  AND (je.source_module = 'sales_invoice_cogs' OR je.source_module LIKE 'historical_cogs%')\n  AND je.is_posted = true\n  AND NOT COALESCE(je.is_reversed, false)\n  AND jel.sales_invoice_item_id IS NULL\n  AND si.invoice_number IN (\n    'SAPJ-26-035', 'SAPJ-26-036', 'SAPJ-26-037', 'SAPJ-26-038', 'SAPJ-26-039',\n    'SAPJ-26-040', 'SAPJ-26-041', 'SAPJ-26-042', 'SAPJ-26-043', 'SAPJ-26-046',\n    'SAPJ-26-047', 'SAPJ-26-048', 'SAPJ-26-049', 'SAPJ-26-050', 'SAPJ-26-051',\n    'SAPJ-26-052', 'SAPJ-26-053'\n  )",COMMIT}	repair_august_september_sales_cogs_snapshots	\N	\N	\N
20260908160000	{"-- Migration: 20260908160000_include_sales_commission_and_marketing_expenses_in_profitability.sql\n-- Description: Expand Sales Profitability expense filters to include all approved sales-category expenses\n--              (including marketing/sales commissions and other sales expenses) linked to Delivery Challans,\n--              while preventing unrelated administrative, staff, tax, and operating expenses from being included.\n-- Zero GL change, zero transaction changes, report-only logic fix.\n\nBEGIN","-- 1. Line Expenses Resolver: allocate all approved sales-type expenses linked to Delivery Challans\nCREATE OR REPLACE FUNCTION public.get_sales_profitability_line_expenses(\n  p_start_date date,\n  p_end_date date\n)\nRETURNS TABLE(line_id uuid, sales_expense numeric)\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$\nWITH scoped AS (\n  SELECT sii.id AS line_id, dci.challan_id AS dc_id,\n         ROUND(sii.quantity * sii.unit_price, 2) AS line_sales,\n         sii.quantity\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n  WHERE si.invoice_date BETWEEN p_start_date AND p_end_date\n    AND NOT COALESCE(si.is_draft, false)\n), dc_totals AS (\n  SELECT dci.challan_id AS dc_id,\n         SUM(ROUND(sii.quantity * sii.unit_price, 2)) AS total_sales,\n         SUM(sii.quantity) AS total_qty\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n  WHERE NOT COALESCE(si.is_draft, false)\n    AND dci.challan_id IN (SELECT DISTINCT dc_id FROM scoped WHERE dc_id IS NOT NULL)\n  GROUP BY dci.challan_id\n), dc_expenses AS (\n  SELECT fe.delivery_challan_id AS dc_id, SUM(fe.amount) AS total_expense\n  FROM public.finance_expenses fe\n  WHERE (\n      fe.expense_category IN ('delivery_sales', 'loading_sales', 'marketing_advertising', 'other_sales')\n      OR EXISTS (\n        SELECT 1 FROM public.expense_categories ec\n        WHERE ec.category_key = fe.expense_category\n          AND ec.category_type = 'sales'\n      )\n    )\n    AND fe.approval_status = 'approved'\n    AND fe.delivery_challan_id IN (SELECT DISTINCT dc_id FROM scoped WHERE dc_id IS NOT NULL)\n  GROUP BY fe.delivery_challan_id\n)\nSELECT s.line_id,\n       COALESCE(CASE\n         WHEN d.total_sales > 0 THEN ROUND(e.total_expense * s.line_sales / d.total_sales, 2)\n         WHEN d.total_qty > 0 THEN ROUND(e.total_expense * s.quantity / d.total_qty, 2)\n         ELSE 0\n       END, 0)::numeric AS sales_expense\nFROM scoped s\nLEFT JOIN dc_totals d ON d.dc_id = s.dc_id\nLEFT JOIN dc_expenses e ON e.dc_id = s.dc_id;\n$$","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_line_expenses(date, date) TO authenticated","-- 2. Summary Function: include all sales-type expenses in unallocated company calculations\nCREATE OR REPLACE FUNCTION public.get_sales_profitability_summary(p_start_date date, p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$\nWITH lines AS (\n  SELECT\n    ar.*,\n    si.invoice_date,\n    si.invoice_number,\n    si.customer_id,\n    COALESCE(c.company_name, 'Unknown Customer') AS customer_name,\n    si.sales_order_id,\n    so.so_number,\n    sii.unit_price,\n    ROUND(sii.quantity * sii.unit_price, 2) AS line_gross_sales,\n    p.product_name,\n    COALESCE(p.product_code, '') AS product_code,\n    COALESCE(p.unit, 'kg') AS product_unit,\n    b.batch_number,\n    COALESCE(b.landed_cost_per_unit, b.cost_per_unit) AS batch_unit_cost,\n    COALESCE(le.sales_expense, 0) AS line_sales_expense,\n    dci.challan_id AS dc_id,\n    dc.challan_number AS dc_number\n  FROM public.get_authoritative_sales_line_cogs(p_start_date, p_end_date) ar\n  JOIN public.sales_invoice_items sii ON sii.id = ar.line_id\n  JOIN public.sales_invoices si ON si.id = ar.invoice_id\n  JOIN public.products p ON p.id = ar.product_id\n  LEFT JOIN public.customers c ON c.id = si.customer_id\n  LEFT JOIN public.sales_orders so ON so.id = si.sales_order_id\n  LEFT JOIN public.batches b ON b.id = ar.batch_id\n  LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n  LEFT JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  LEFT JOIN public.get_sales_profitability_line_expenses(p_start_date, p_end_date) le ON le.line_id = ar.line_id\n),\nunallocated AS (\n  SELECT COALESCE(SUM(fe.amount), 0) AS amount\n  FROM public.finance_expenses fe\n  WHERE (\n      fe.expense_category IN ('delivery_sales', 'loading_sales', 'marketing_advertising', 'other_sales')\n      OR EXISTS (\n        SELECT 1 FROM public.expense_categories ec\n        WHERE ec.category_key = fe.expense_category\n          AND ec.category_type = 'sales'\n      )\n    )\n    AND fe.approval_status = 'approved'\n    AND fe.expense_date BETWEEN p_start_date AND p_end_date\n    AND (fe.delivery_challan_id IS NULL OR NOT EXISTS (SELECT 1 FROM lines l WHERE l.dc_id = fe.delivery_challan_id))\n),\nprod AS (\n  SELECT\n    product_id,\n    MAX(product_name) AS product_name,\n    MAX(product_code) AS product_code,\n    MAX(product_unit) AS product_unit,\n    COALESCE((SELECT SUM(b.current_stock) FROM public.batches b WHERE b.product_id = l.product_id AND b.is_active), 0) AS current_stock,\n    SUM(quantity) AS sold_qty,\n    SUM(line_gross_sales) AS gross_sales,\n    SUM(authoritative_cogs) AS product_cost,\n    SUM(line_sales_expense) AS sales_expense,\n    ROUND(SUM(line_gross_sales) / NULLIF(SUM(quantity), 0), 2) AS avg_selling_price,\n    ROUND(SUM(line_sales_expense) / NULLIF(SUM(quantity), 0), 2) AS sales_expense_per_unit,\n    ROUND((SUM(line_gross_sales) - SUM(line_sales_expense)) / NULLIF(SUM(quantity), 0), 2) AS net_selling_price_per_unit,\n    COALESCE(\n      ROUND(SUM(authoritative_cogs) / NULLIF(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN quantity ELSE 0 END), 0), 2),\n      ROUND(SUM(quantity * batch_unit_cost) / NULLIF(SUM(quantity), 0), 2)\n    ) AS avg_landed_cost,\n    ROUND(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales - authoritative_cogs ELSE 0 END), 2) AS gross_profit,\n    ROUND(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales - authoritative_cogs - line_sales_expense ELSE 0 END), 2) AS profit_after_sales_expense,\n    ROUND(\n      SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales - authoritative_cogs - line_sales_expense ELSE 0 END)\n      / NULLIF(SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN quantity ELSE 0 END), 0),\n      2\n    ) AS profit_per_unit,\n    CASE\n      WHEN SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales ELSE 0 END) = 0 THEN NULL\n      ELSE ROUND(\n        SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales - authoritative_cogs - line_sales_expense ELSE 0 END)\n        / SUM(CASE WHEN authoritative_cogs IS NOT NULL THEN line_gross_sales ELSE 0 END) * 100,\n        2\n      )\n    END AS profit_margin_pct,\n    COUNT(authoritative_cogs) AS costed_lines,\n    COUNT(*) AS total_lines,\n    COUNT(authoritative_cogs) < COUNT(*) AS has_unreported_cost\n  FROM lines l\n  GROUP BY product_id\n),\ninv AS (\n  SELECT\n    invoice_id,\n    MAX(invoice_date) AS invoice_date,\n    MAX(posted_invoice_cogs) AS product_cost,\n    SUM(line_gross_sales) AS gross_sales,\n    SUM(quantity) AS total_qty_sold,\n    SUM(line_sales_expense) AS sales_expenses\n  FROM lines\n  GROUP BY invoice_id\n),\nmonths AS (\n  SELECT\n    DATE_TRUNC('month', invoice_date)::date AS month_start,\n    TO_CHAR(DATE_TRUNC('month', invoice_date), 'Mon YYYY') AS month_label,\n    SUM(gross_sales) AS gross_sales,\n    SUM(product_cost) AS product_cost,\n    SUM(sales_expenses) AS sales_expenses,\n    SUM(total_qty_sold) AS total_qty_sold,\n    COUNT(*) AS order_count\n  FROM inv\n  GROUP BY 1, 2\n),\ncompany AS (\n  SELECT\n    COALESCE(SUM(gross_sales), 0) AS gross_sales,\n    COALESCE(SUM(product_cost), 0) AS product_cost,\n    COALESCE(SUM(sales_expenses), 0) + (SELECT amount FROM unallocated) AS sales_expenses,\n    (SELECT amount FROM unallocated) AS unallocated_sales_expenses,\n    COALESCE(SUM(total_qty_sold), 0) AS total_qty_sold,\n    COUNT(*) AS order_count,\n    (SELECT COUNT(DISTINCT product_id) FROM lines) AS product_count\n  FROM inv\n)\nSELECT jsonb_build_object(\n  'company', jsonb_build_object(\n    'gross_sales', c.gross_sales,\n    'product_cost', c.product_cost,\n    'sales_expenses', c.sales_expenses,\n    'unallocated_sales_expenses', c.unallocated_sales_expenses,\n    'gross_profit', c.gross_sales - c.product_cost,\n    'profit_after_sales_expenses', c.gross_sales - c.product_cost - c.sales_expenses,\n    'profit_margin_pct', CASE WHEN c.gross_sales = 0 THEN NULL ELSE ROUND((c.gross_sales - c.product_cost - c.sales_expenses) / c.gross_sales * 100, 2) END,\n    'total_qty_sold', c.total_qty_sold,\n    'order_count', c.order_count,\n    'product_count', c.product_count\n  ),\n  'products', COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.product_name) FROM prod p), '[]'::jsonb),\n  'monthly', COALESCE((\n    SELECT jsonb_agg(\n      jsonb_build_object(\n        'month_label', m.month_label,\n        'month_start', m.month_start,\n        'gross_sales', m.gross_sales,\n        'product_cost', m.product_cost,\n        'sales_expenses', m.sales_expenses,\n        'gross_profit', m.gross_sales - m.product_cost,\n        'profit_after_sales_expenses', m.gross_sales - m.product_cost - m.sales_expenses,\n        'profit_margin_pct', CASE WHEN m.gross_sales = 0 THEN NULL ELSE ROUND((m.gross_sales - m.product_cost - m.sales_expenses) / m.gross_sales * 100, 2) END,\n        'total_qty_sold', m.total_qty_sold,\n        'order_count', m.order_count\n      ) ORDER BY m.month_start\n    ) FROM months m\n  ), '[]'::jsonb)\n)\nFROM company c;\n$$","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_summary(date, date) TO authenticated","-- 3. Batch Orders Drilldown: include all sales-type expenses in DC expenses JSON\nCREATE OR REPLACE FUNCTION public.get_sales_profitability_batch_orders(p_batch_id uuid, p_start_date date, p_end_date date)\nRETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$\nWITH x AS (\n  SELECT\n    ar.line_id, ar.invoice_id, si.invoice_number, si.invoice_date, si.customer_id,\n    COALESCE(c.company_name, 'Unknown Customer') AS customer_name,\n    si.sales_order_id, so.so_number, dci.challan_id AS dc_id, dc.challan_number AS dc_number,\n    ar.quantity, sii.unit_price AS selling_price,\n    ROUND(ar.quantity * sii.unit_price, 2) AS gross_sales,\n    ar.authoritative_unit_cogs AS unit_cost,\n    ar.authoritative_cogs AS line_cost,\n    COALESCE(le.sales_expense, 0) AS line_sales_expense,\n    ar.resolution_tier AS cogs_resolution\n  FROM public.get_authoritative_sales_line_cogs(p_start_date, p_end_date) ar\n  JOIN public.sales_invoice_items sii ON sii.id = ar.line_id\n  JOIN public.sales_invoices si ON si.id = ar.invoice_id\n  LEFT JOIN public.customers c ON c.id = si.customer_id\n  LEFT JOIN public.sales_orders so ON so.id = si.sales_order_id\n  LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n  LEFT JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  LEFT JOIN public.get_sales_profitability_line_expenses(p_start_date, p_end_date) le ON le.line_id = ar.line_id\n  WHERE ar.batch_id = p_batch_id\n),\nex AS (\n  SELECT\n    fe.delivery_challan_id AS dc_id,\n    jsonb_agg(jsonb_build_object(\n      'id', fe.id,\n      'voucher_number', fe.voucher_number,\n      'category', fe.expense_category,\n      'total_amount', fe.amount,\n      'description', fe.description,\n      'expense_date', fe.expense_date\n    )) AS expenses\n  FROM public.finance_expenses fe\n  WHERE (\n      fe.expense_category IN ('delivery_sales', 'loading_sales', 'marketing_advertising', 'other_sales')\n      OR EXISTS (\n        SELECT 1 FROM public.expense_categories ec\n        WHERE ec.category_key = fe.expense_category\n          AND ec.category_type = 'sales'\n      )\n    )\n    AND fe.approval_status = 'approved'\n    AND fe.delivery_challan_id IN (SELECT DISTINCT dc_id FROM x WHERE dc_id IS NOT NULL)\n  GROUP BY fe.delivery_challan_id\n)\nSELECT jsonb_build_object(\n  'batch', (\n    SELECT jsonb_build_object(\n      'batch_id', b.id,\n      'batch_number', b.batch_number,\n      'product_name', p.product_name,\n      'product_code', COALESCE(p.product_code, ''),\n      'product_unit', COALESCE(p.unit, 'kg'),\n      'current_stock', b.current_stock\n    )\n    FROM public.batches b\n    JOIN public.products p ON p.id = b.product_id\n    WHERE b.id = p_batch_id\n  ),\n  'orders', COALESCE((\n    SELECT jsonb_agg(\n      jsonb_build_object(\n        'line_id', x.line_id,\n        'invoice_id', x.invoice_id,\n        'invoice_number', x.invoice_number,\n        'invoice_date', x.invoice_date,\n        'customer_id', x.customer_id,\n        'customer_name', x.customer_name,\n        'sales_order_id', x.sales_order_id,\n        'so_number', x.so_number,\n        'dc_id', x.dc_id,\n        'dc_number', x.dc_number,\n        'quantity', x.quantity,\n        'selling_price', x.selling_price,\n        'unit_price', x.selling_price,\n        'gross_sales', x.gross_sales,\n        'unit_cost', x.unit_cost,\n        'line_cost', x.line_cost,\n        'line_sales_expense', x.line_sales_expense,\n        'net_selling_realization', x.gross_sales - x.line_sales_expense,\n        'gross_profit', CASE WHEN x.line_cost IS NULL THEN NULL ELSE x.gross_sales - x.line_cost END,\n        'profit', CASE WHEN x.line_cost IS NULL THEN NULL ELSE x.gross_sales - x.line_cost - x.line_sales_expense END,\n        'profit_margin_pct', CASE WHEN x.line_cost IS NULL OR x.gross_sales = 0 THEN NULL ELSE ROUND((x.gross_sales - x.line_cost - x.line_sales_expense) / x.gross_sales * 100, 2) END,\n        'cogs_resolution', x.cogs_resolution,\n        'expenses', COALESCE(ex.expenses, '[]'::jsonb)\n      ) ORDER BY x.invoice_date DESC, x.invoice_number\n    )\n    FROM x\n    LEFT JOIN ex USING (dc_id)\n  ), '[]'::jsonb)\n);\n$$","GRANT EXECUTE ON FUNCTION public.get_sales_profitability_batch_orders(uuid, date, date) TO authenticated",COMMIT}	include_sales_commission_and_marketing_expenses_in_profitability	\N	\N	\N
20260908163000	{"-- Migration: 20260908163000_repair_historical_cogs_snapshots_sapj_26_017_and_032.sql\n-- Description: Backfill forensically proven historical line-level COGS snapshots for SAPJ-26-017 and SAPJ-26-032.\n--              Proven from immutable audit_logs of batch landed cost at the exact COGS posting timestamps.\n-- Zero GL change, zero inventory change, zero current batch cost change.\n\nBEGIN","-- ============================================================================\n-- 1. Invoice SAPJ-26-017 (2026-05-05) — Ibuprofen BP\n--    Total Posted COGS = Rp73,597,342.50 across JE2607-0001 and HFR-260904-FCOGS-024\n--    Proven batch landed cost at posting time (2026-09-03 17:52:38 UTC) was Rp163,549.65/kg\n--    Total qty = 450 kg (150 kg + 250 kg + 50 kg)\n--    450 * 163,549.65 = Rp73,597,342.50 (100% exact match to posted COGS, Rp0.00 diff)\n-- ============================================================================\n\n-- Line 1: Batch 4001/1101/25/A-3147 (Qty 150 kg)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 163549.65,\n    cogs_total_cost = 24532447.50\nWHERE id = '3286a2c5-461f-4571-bf71-6ca050e72f29'\n  AND invoice_id = '662a7c07-df0a-463a-ba0c-2cff6381907f'","-- Line 2: Batch 4001/1101/25/A-3145 (Qty 250 kg)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 163549.65,\n    cogs_total_cost = 40887412.50\nWHERE id = '57d9c923-0a8f-4d61-99eb-e7bb1f351f63'\n  AND invoice_id = '662a7c07-df0a-463a-ba0c-2cff6381907f'","-- Line 3: Batch 4001/1101/25/A-3146 (Qty 50 kg)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 163549.65,\n    cogs_total_cost = 8177482.50\nWHERE id = 'f185574f-3b80-48c0-be90-dd9278934e27'\n  AND invoice_id = '662a7c07-df0a-463a-ba0c-2cff6381907f'","-- ============================================================================\n-- 2. Invoice SAPJ-26-032 (2026-07-24) — Diclofenac Sodium\n--    Total Posted COGS = Rp112,782,600.00 from JE2609-0044\n--    Proven batch landed cost at posting time (2026-09-03 17:15:18 UTC) was Rp187,971.00/kg\n--    Total qty = 600 kg (50 kg + 550 kg)\n--    600 * 187,971.00 = Rp112,782,600.00 (100% exact match to posted COGS, Rp0.00 diff)\n-- ============================================================================\n\n-- Line 1: Batch DFS/126010052 (Qty 50 kg)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 187971.00,\n    cogs_total_cost = 9398550.00\nWHERE id = '387b8c44-cd87-4b2d-9fc2-b9ed819c8d07'\n  AND invoice_id = '3300fde7-f257-4c5c-8f5e-f2780ca6600f'","-- Line 2: Batch DFS/125120557 (Qty 550 kg)\nUPDATE public.sales_invoice_items\nSET cogs_unit_cost = 187971.00,\n    cogs_total_cost = 103384050.00\nWHERE id = '54368b9e-33e0-439f-be71-4b1b88417dd4'\n  AND invoice_id = '3300fde7-f257-4c5c-8f5e-f2780ca6600f'",COMMIT}	repair_historical_cogs_snapshots_sapj_26_017_and_032	\N	\N	\N
20260908235000	{"-- Migration: 20260908235000_phase1_payee_master_and_tax_foundation.sql\n-- Description: Phase 1 database foundation for Payee Master and PPh 21 tax architecture.\n--              Introduces public.finance_payees, canonical PPh 21 calculation regimes in tax_codes,\n--              snapshot columns in finance_expenses, payee attribution on journal_entry_lines,\n--              and hardens auto_post_expense_accounting() to eliminate silent fallbacks to PPh 23.\n-- Zero retrospective accounting changes; preserves all closed periods and reconciliations.\n\nBEGIN","-- 1. Create Enums for Business Role and DJP Tax Classification\nDO $$ BEGIN\n    CREATE TYPE public.payee_business_role AS ENUM (\n        'sales_commission_recipient',\n        'tax_consultant',\n        'legal_counsel',\n        'notary',\n        'warehouse_labor',\n        'property_owner',\n        'freelance_specialist'\n    );\nEXCEPTION WHEN duplicate_object THEN null; END $$","DO $$ BEGIN\n    CREATE TYPE public.payee_tax_classification AS ENUM (\n        'bukan_pegawai_imbalan',\n        'tenaga_ahli',\n        'pegawai_tidak_tetap',\n        'pemilik_sewa_op'\n    );\nEXCEPTION WHEN duplicate_object THEN null; END $$","-- 2. Create Table: finance_payees\nCREATE TABLE IF NOT EXISTS public.finance_payees (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    payee_code TEXT UNIQUE NOT NULL,\n    full_name TEXT NOT NULL,\n    business_role public.payee_business_role NOT NULL,\n    tax_classification public.payee_tax_classification NOT NULL,\n    nik VARCHAR(16) NULL,\n    npwp VARCHAR(20) NULL,\n    ptkp_status VARCHAR(10) NOT NULL DEFAULT 'TK/0',\n    default_pph_code_id UUID NULL REFERENCES public.tax_codes(id),\n    bank_name TEXT NULL,\n    bank_account_number TEXT NULL,\n    bank_account_holder TEXT NULL,\n    phone TEXT NULL,\n    email TEXT NULL,\n    address TEXT NULL,\n    notes TEXT NULL,\n    is_active BOOLEAN NOT NULL DEFAULT true,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n)","CREATE INDEX IF NOT EXISTS idx_finance_payees_role ON public.finance_payees(business_role)","CREATE INDEX IF NOT EXISTS idx_finance_payees_classification ON public.finance_payees(tax_classification)","CREATE INDEX IF NOT EXISTS idx_finance_payees_active ON public.finance_payees(is_active)","-- Enable RLS on finance_payees\nALTER TABLE public.finance_payees ENABLE ROW LEVEL SECURITY","DO $$ BEGIN\n    CREATE POLICY \\"Allow authenticated read on finance_payees\\"\n        ON public.finance_payees FOR SELECT\n        TO authenticated\n        USING (true);\nEXCEPTION WHEN duplicate_object THEN null; END $$","DO $$ BEGIN\n    CREATE POLICY \\"Allow authenticated insert/update on finance_payees\\"\n        ON public.finance_payees FOR ALL\n        TO authenticated\n        USING (true)\n        WITH CHECK (true);\nEXCEPTION WHEN duplicate_object THEN null; END $$","-- 3. Insert Canonical PPh 21 Calculation Regimes into tax_codes\n-- Account 2131 PPh 21 Payable is 5f1dc2bc-c988-40ce-a827-ae6bd5aa6ca2\nINSERT INTO public.tax_codes (\n    code, name, tax_type, rate, is_withholding, payment_account_id, is_active\n) VALUES (\n    'PPH21-NE',\n    'PPh 21 - Bukan Pegawai & Tenaga Ahli (DPP 50% / Pasal 17)',\n    'PPh21',\n    0.00,\n    true,\n    '5f1dc2bc-c988-40ce-a827-ae6bd5aa6ca2',\n    true\n) ON CONFLICT (code) DO UPDATE SET\n    payment_account_id = EXCLUDED.payment_account_id,\n    name = EXCLUDED.name,\n    tax_type = EXCLUDED.tax_type,\n    is_withholding = true,\n    is_active = true","INSERT INTO public.tax_codes (\n    code, name, tax_type, rate, is_withholding, payment_account_id, is_active\n) VALUES (\n    'PPH21-TT',\n    'PPh 21 - Pegawai Tidak Tetap (TER Harian / Bebas Pajak)',\n    'PPh21',\n    0.00,\n    true,\n    '5f1dc2bc-c988-40ce-a827-ae6bd5aa6ca2',\n    true\n) ON CONFLICT (code) DO UPDATE SET\n    payment_account_id = EXCLUDED.payment_account_id,\n    name = EXCLUDED.name,\n    tax_type = EXCLUDED.tax_type,\n    is_withholding = true,\n    is_active = true","-- 4. Extend finance_expenses with Snapshot & Attribution Columns\nALTER TABLE public.finance_expenses\n    ADD COLUMN IF NOT EXISTS payee_id UUID NULL REFERENCES public.finance_payees(id),\n    ADD COLUMN IF NOT EXISTS pph_calculation_regime TEXT NULL,\n    ADD COLUMN IF NOT EXISTS pph_dpp_ratio NUMERIC(5,4) NULL,\n    ADD COLUMN IF NOT EXISTS pph_dpp_amount NUMERIC(15,2) NULL,\n    ADD COLUMN IF NOT EXISTS pph_rate NUMERIC(5,2) NULL,\n    ADD COLUMN IF NOT EXISTS is_tax_manual_override BOOLEAN NOT NULL DEFAULT false,\n    ADD COLUMN IF NOT EXISTS linked_sales_invoice_id UUID NULL REFERENCES public.sales_invoices(id)","CREATE INDEX IF NOT EXISTS idx_finance_expenses_payee ON public.finance_expenses(payee_id)","CREATE INDEX IF NOT EXISTS idx_finance_expenses_linked_si ON public.finance_expenses(linked_sales_invoice_id)","-- 5. Extend journal_entry_lines with payee_id\nALTER TABLE public.journal_entry_lines\n    ADD COLUMN IF NOT EXISTS payee_id UUID NULL REFERENCES public.finance_payees(id)","CREATE INDEX IF NOT EXISTS idx_journal_entry_lines_payee ON public.journal_entry_lines(payee_id)","-- 6. Harden fn_pph_payable_account_id: Strict Resolution, ZERO Silent Fallback\nCREATE OR REPLACE FUNCTION public.fn_pph_payable_account_id(p_tax_code_id uuid)\nRETURNS uuid\nLANGUAGE plpgsql\nSTABLE SECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_account_id uuid;\n  v_tax_type text;\nBEGIN\n  IF p_tax_code_id IS NULL THEN\n    RETURN NULL;\n  END IF;\n\n  -- 1. Direct resolution from tax_codes.payment_account_id\n  SELECT payment_account_id, tax_type INTO v_account_id, v_tax_type\n    FROM public.tax_codes\n   WHERE id = p_tax_code_id;\n\n  IF v_account_id IS NOT NULL THEN\n    RETURN v_account_id;\n  END IF;\n\n  -- 2. Fallback to tax_type mapped COA code if payment_account_id was not populated\n  IF v_tax_type = 'PPh21' THEN\n    SELECT id INTO v_account_id FROM public.chart_of_accounts WHERE code = '2131' LIMIT 1;\n  ELSIF v_tax_type = 'PPh22' THEN\n    SELECT id INTO v_account_id FROM public.chart_of_accounts WHERE code = '2137' LIMIT 1;\n  ELSIF v_tax_type = 'PPh23' THEN\n    SELECT id INTO v_account_id FROM public.chart_of_accounts WHERE code = '2132' LIMIT 1;\n  ELSIF v_tax_type = 'PPh4(2)' THEN\n    SELECT id INTO v_account_id FROM public.chart_of_accounts WHERE code = '2138' LIMIT 1;\n  ELSE\n    v_account_id := NULL; -- Strict: unknown tax type returns NULL, NO silent fallback to 2132!\n  END IF;\n\n  RETURN v_account_id;\nEND;\n$$","-- 7. Harden auto_post_expense_accounting: Abort on Missing/Invalid Withholding Tax Code\nCREATE OR REPLACE FUNCTION public.auto_post_expense_accounting()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_expense_account_id uuid;\n  v_payment_account_id uuid;\n  v_journal_id uuid;\n  v_active_count integer;\n  v_description text;\n  v_credit_desc text;\n  v_category_label text;\n  v_bm_account_id uuid;\n  v_ppn_account_id uuid;\n  v_pph_account_id uuid;\n  v_stamp_duty_account_id uuid;\n  v_bank_charge_acc_id uuid;\n  v_line_num integer;\n  v_net_payment numeric(18,2);\n  v_total numeric(18,2);\n  v_bank_charges numeric(18,2);\nBEGIN\n  IF NEW.approval_status <> 'approved' THEN RETURN NEW; END IF;\n\n  IF TG_OP='UPDATE' AND OLD.approval_status='approved' THEN\n    IF ROW(\n      OLD.amount,OLD.expense_category,OLD.expense_date,OLD.description,\n      OLD.payment_method,OLD.bank_account_id,OLD.pib_bm_amount,OLD.pib_ppn_amount,\n      OLD.pib_pph_amount,OLD.ppn_amount,OLD.pph_amount,OLD.pph_code_id,OLD.stamp_duty_amount,\n      OLD.fixed_asset_account_id,COALESCE(OLD.bank_charges_amount,0),\n      OLD.transaction_currency,OLD.exchange_rate,OLD.supplier_id,OLD.payee_id\n    ) IS NOT DISTINCT FROM ROW(\n      NEW.amount,NEW.expense_category,NEW.expense_date,NEW.description,\n      NEW.payment_method,NEW.bank_account_id,NEW.pib_bm_amount,NEW.pib_ppn_amount,\n      NEW.pib_pph_amount,NEW.ppn_amount,NEW.pph_amount,NEW.pph_code_id,NEW.stamp_duty_amount,\n      NEW.fixed_asset_account_id,COALESCE(NEW.bank_charges_amount,0),\n      NEW.transaction_currency,NEW.exchange_rate,NEW.supplier_id,NEW.payee_id\n    ) THEN\n      RETURN NEW;\n    END IF;\n  END IF;\n\n  SELECT count(*), (array_agg(id ORDER BY created_at DESC,id DESC))[1]\n    INTO v_active_count,v_journal_id\n    FROM public.journal_entries\n   WHERE source_module IN('expense','expenses')\n     AND (reference_id=NEW.id OR reference_number='EXP-'||NEW.id::text)\n     AND is_posted=true AND NOT COALESCE(is_reversed,false);\n\n  IF v_active_count>1 THEN\n    RAISE EXCEPTION 'Expense % has multiple active journals; edit is blocked',NEW.id;\n  END IF;\n  IF TG_OP='UPDATE' AND OLD.approval_status='approved' AND v_active_count<>1 THEN\n    RAISE EXCEPTION 'Approved expense % must have exactly one active journal before edit',NEW.id;\n  END IF;\n  IF v_journal_id IS NOT NULL THEN\n    PERFORM 1 FROM public.journal_entries WHERE id=v_journal_id FOR UPDATE;\n    DELETE FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;\n  END IF;\n\n  IF NEW.payment_method='cash' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;\n  ELSIF NEW.payment_method='petty_cash' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='1102' LIMIT 1;\n  ELSIF NEW.payment_method = 'bank_transfer' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n  ELSIF NEW.payment_method IS NOT NULL AND NEW.bank_account_id IS NOT NULL THEN\n    SELECT coa_id INTO v_payment_account_id FROM public.bank_accounts WHERE id=NEW.bank_account_id;\n  ELSIF NEW.payment_method IS NULL THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n  END IF;\n  IF v_payment_account_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot post expense %: the selected payment/AP account is not configured',NEW.id;\n  END IF;\n\n  IF NEW.expense_category='pib_import' THEN\n    v_bm_account_id:=public.get_expense_account_id('duty_customs');\n    v_ppn_account_id:=public.get_expense_account_id('ppn_import');\n    v_pph_account_id:=public.get_expense_account_id('pph_import');\n    IF COALESCE(NEW.pib_bm_amount,0)>0 AND v_bm_account_id IS NULL THEN RAISE EXCEPTION 'Import Duty account is missing'; END IF;\n    IF COALESCE(NEW.pib_ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Import account is missing'; END IF;\n    IF COALESCE(NEW.pib_pph_amount,0)>0 AND v_pph_account_id IS NULL THEN RAISE EXCEPTION 'PPh Import account is missing'; END IF;\n    v_total:=NEW.amount;\n    v_journal_id:=public.upsert_expense_journal_header_in_place(\n      v_journal_id,NEW.id,NEW.expense_date,COALESCE(NEW.description,'PIB Import Payment'),\n      'pib_import',v_total,NEW.created_by);\n    v_line_num:=1;\n    IF COALESCE(NEW.pib_bm_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_bm_account_id,NEW.pib_bm_amount,0,'PIB - Import Duty (BM) [landed cost]',NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    IF COALESCE(NEW.pib_ppn_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.pib_ppn_amount,0,'PIB - PPN Import (Input VAT)',NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    IF COALESCE(NEW.pib_pph_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_pph_account_id,NEW.pib_pph_amount,0,'PIB - PPh 22 Dibayar Dimuka',NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_payment_account_id,0,NEW.amount,'PIB - Payment ['||COALESCE(NEW.description,'')||']',NEW.supplier_id,NEW.payee_id);\n    RETURN NEW;\n  END IF;\n\n  IF NEW.expense_category='fixed_asset' THEN\n    v_expense_account_id:=NEW.fixed_asset_account_id;\n    IF v_expense_account_id IS NULL THEN RAISE EXCEPTION 'A posting Fixed Asset account is required'; END IF;\n    SELECT id INTO v_ppn_account_id FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;\n    IF COALESCE(NEW.ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Masukan account 1150 is missing'; END IF;\n    v_description:=COALESCE(NEW.description,'Fixed Asset Purchase');\n    v_total:=NEW.amount+COALESCE(NEW.ppn_amount,0);\n    v_journal_id:=public.upsert_expense_journal_header_in_place(\n      v_journal_id,NEW.id,NEW.expense_date,v_description,'fixed_asset',v_total,NEW.created_by);\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,1,v_expense_account_id,NEW.amount,0,v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=2;\n    IF COALESCE(NEW.ppn_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.ppn_amount,0,'PPN Masukan - '||v_description,NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_payment_account_id,0,v_total,v_description,NEW.supplier_id,NEW.payee_id);\n    RETURN NEW;\n  END IF;\n\n  v_expense_account_id:=CASE WHEN public.is_capitalizable_landed_cost_category(NEW.expense_category) THEN (SELECT id FROM public.chart_of_accounts WHERE code='1130' LIMIT 1) ELSE public.get_expense_account_id(NEW.expense_category) END;\n  IF v_expense_account_id IS NULL THEN RAISE EXCEPTION 'No expense account is mapped for %',NEW.expense_category; END IF;\n  v_category_label:=initcap(replace(NEW.expense_category,'_',' '));\n  v_description:=COALESCE(NEW.description,NEW.expense_category);\n  v_credit_desc:=COALESCE(substring(NEW.description FROM '^[^\\\\n]+'),NEW.expense_category)||' ['||v_category_label||']';\n  \n  SELECT id INTO v_ppn_account_id FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;\n  SELECT id INTO v_stamp_duty_account_id FROM public.chart_of_accounts WHERE code='6950' LIMIT 1;\n  IF COALESCE(NEW.ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Masukan account 1150 is missing'; END IF;\n  IF COALESCE(NEW.stamp_duty_amount,0)>0 AND v_stamp_duty_account_id IS NULL THEN RAISE EXCEPTION 'Stamp Duty account 6950 is missing'; END IF;\n\n  -- STRICT ZERO-FALLBACK RESOLUTION FOR WITHHOLDING TAX\n  IF COALESCE(NEW.pph_amount, 0) > 0 THEN\n    IF NEW.pph_code_id IS NULL THEN\n      RAISE EXCEPTION 'Cannot post expense %: Withholding tax amount % exists but pph_code_id is NULL', \n        NEW.id, NEW.pph_amount;\n    END IF;\n\n    v_pph_account_id := public.fn_pph_payable_account_id(NEW.pph_code_id);\n\n    IF v_pph_account_id IS NULL THEN\n      RAISE EXCEPTION 'Cannot post expense %: Tax code % has no valid GL liability account configured', \n        NEW.id, NEW.pph_code_id;\n    END IF;\n  END IF;\n\n  v_bank_charges:=CASE WHEN NEW.expense_category='utilities' THEN COALESCE(NEW.bank_charges_amount,0) ELSE 0 END;\n  IF v_bank_charges>0 THEN\n    v_bank_charge_acc_id:=public.get_expense_account_id('bank_charges');\n    IF v_bank_charge_acc_id IS NULL THEN RAISE EXCEPTION 'Bank Charges account is missing'; END IF;\n  END IF;\n\n  v_net_payment:=NEW.amount+COALESCE(NEW.ppn_amount,0)-COALESCE(NEW.pph_amount,0)+COALESCE(NEW.stamp_duty_amount,0)+v_bank_charges;\n  v_total:=NEW.amount+COALESCE(NEW.ppn_amount,0)+COALESCE(NEW.stamp_duty_amount,0)+v_bank_charges;\n\n  v_journal_id:=public.upsert_expense_journal_header_in_place(\n    v_journal_id,NEW.id,NEW.expense_date,v_description,NEW.expense_category,v_total,NEW.created_by);\n  v_line_num:=1;\n\n  -- 1. Debit Expense\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n  VALUES(v_journal_id,v_line_num,v_expense_account_id,NEW.amount,0,v_credit_desc,NEW.supplier_id,NEW.payee_id);\n  v_line_num:=v_line_num+1;\n\n  -- 2. Debit PPN Masukan\n  IF COALESCE(NEW.ppn_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.ppn_amount,0,'PPN Masukan - '||v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  -- 3. Debit Stamp Duty\n  IF COALESCE(NEW.stamp_duty_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_stamp_duty_account_id,NEW.stamp_duty_amount,0,'Bea Meterai - '||v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  -- 4. Debit Bank Charges\n  IF v_bank_charges>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_bank_charge_acc_id,v_bank_charges,0,'Bank charges ['||v_category_label||']',NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  -- 5. Credit PPh Ditahan\n  IF COALESCE(NEW.pph_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_pph_account_id,0,NEW.pph_amount,'PPh Ditahan - '||v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  -- 6. Credit Payment / AP Account\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n  VALUES(v_journal_id,v_line_num,v_payment_account_id,0,v_net_payment,v_credit_desc,NEW.supplier_id,NEW.payee_id);\n\n  RETURN NEW;\nEND;\n$function$","-- 8. Harden trg_sync_expense_pph_account to prevent fallback and copy payee_id\nCREATE OR REPLACE FUNCTION public.trg_sync_expense_pph_account()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_account_id uuid;\n  v_journal_id uuid;\n  v_line_number integer;\nBEGIN\n  IF NEW.expense_category = 'import_broker' THEN\n    RETURN NEW;\n  END IF;\n  IF COALESCE(NEW.pph_amount, 0) <= 0 THEN\n    RETURN NEW;\n  END IF;\n\n  v_account_id := public.fn_pph_payable_account_id(NEW.pph_code_id);\n  IF v_account_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT id INTO v_journal_id\n    FROM public.journal_entries\n   WHERE reference_id = NEW.id\n     AND source_module IN ('expense', 'expenses')\n   ORDER BY created_at DESC\n   LIMIT 1;\n\n  IF v_journal_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_journal_id\n       AND debit = 0\n       AND description ILIKE 'PPh Ditahan%'\n  ) THEN\n    UPDATE public.journal_entry_lines\n       SET account_id = v_account_id,\n           payee_id = NEW.payee_id\n     WHERE journal_entry_id = v_journal_id\n       AND debit = 0\n       AND description ILIKE 'PPh Ditahan%';\n  ELSE\n    UPDATE public.journal_entry_lines\n       SET credit = credit - NEW.pph_amount\n     WHERE id = (\n       SELECT id FROM public.journal_entry_lines\n        WHERE journal_entry_id = v_journal_id\n          AND credit >= NEW.pph_amount\n        ORDER BY credit DESC, line_number DESC\n        LIMIT 1\n     );\n\n    SELECT COALESCE(MAX(line_number), 0) + 1 INTO v_line_number\n      FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_journal_id;\n\n    INSERT INTO public.journal_entry_lines\n      (journal_entry_id, line_number, account_id, debit, credit, description, supplier_id, payee_id)\n    VALUES\n      (v_journal_id, v_line_number, v_account_id, 0, NEW.pph_amount,\n       'PPh Ditahan - ' || COALESCE(NEW.description, NEW.voucher_number, 'Expense'),\n       NEW.supplier_id, NEW.payee_id);\n  END IF;\n\n  UPDATE public.journal_entries\n     SET total_debit = (SELECT COALESCE(SUM(debit), 0) FROM public.journal_entry_lines WHERE journal_entry_id = v_journal_id),\n         total_credit = (SELECT COALESCE(SUM(credit), 0) FROM public.journal_entry_lines WHERE journal_entry_id = v_journal_id)\n   WHERE id = v_journal_id;\n\n  RETURN NEW;\nEND;\n$function$","-- 9. Update validate_non_permanent_employee_fee to support Payee Master\nCREATE OR REPLACE FUNCTION public.validate_non_permanent_employee_fee()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE v_pph21_code uuid;\nBEGIN\n  IF NEW.expense_category = 'non_permanent_employee_fee' THEN\n    -- If supplier_id is provided instead of payee_id, ensure it is an individual supplier\n    IF NEW.supplier_id IS NOT NULL AND NEW.payee_id IS NULL AND NOT EXISTS (\n      SELECT 1 FROM public.suppliers s\n      WHERE s.id = NEW.supplier_id\n        AND lower(COALESCE(s.supplier_type,'')) IN (\n          'employee','non-permanent individual','freelancer','casual worker','honorarium recipient'\n        )\n    ) THEN\n      RAISE EXCEPTION 'Non-Permanent Employee Fee is intended for an individual subject to PPh 21, not a company supplier';\n    END IF;\n\n    -- Default only. An explicit accountant-selected tax code is preserved.\n    IF NEW.pph_code_id IS NULL THEN\n      SELECT id INTO v_pph21_code FROM public.tax_codes\n      WHERE tax_type = 'PPh21' AND is_withholding = true\n      ORDER BY (code = 'PPH21-NE') DESC, (code = 'PPH21') DESC, code LIMIT 1;\n      IF v_pph21_code IS NULL THEN\n        RAISE EXCEPTION 'PPh21 tax code is not configured';\n      END IF;\n      NEW.pph_code_id := v_pph21_code;\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$function$",COMMIT}	phase1_payee_master_and_tax_foundation	\N	\N	\N
20260909000000	{"-- Migration: 20260909000000_phase3_save_expense_payee_fields.sql\n-- Description: Extend save_finance_expense and edit_approved_finance_expense_atomic\n--              to persist payee_id, linked_sales_invoice_id, and PPh snapshot columns.\n\nBEGIN","CREATE OR REPLACE FUNCTION public.save_finance_expense(\n  p_expense_id uuid DEFAULT NULL::uuid,\n  p_payload jsonb DEFAULT '{}'::jsonb\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_id uuid;\n  v_date date := COALESCE((p_payload->>'expense_date')::date, current_date);\n  v_bank_id uuid := NULLIF(p_payload->>'bank_account_id', '')::uuid;\n  v_bank_currency text;\n  v_currency text;\n  v_rate numeric;\n  v_docs text[];\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  IF COALESCE((p_payload->>'amount')::numeric, 0) <= 0 THEN\n    RAISE EXCEPTION 'Expense amount must be greater than zero';\n  END IF;\n  IF NULLIF(p_payload->>'expense_category', '') IS NULL THEN\n    RAISE EXCEPTION 'Expense category is required';\n  END IF;\n\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id = v_bank_id;\n  v_currency := upper(COALESCE(NULLIF(p_payload->>'transaction_currency',''), v_bank_currency, 'IDR'));\n  IF v_currency NOT IN ('IDR','USD') THEN RAISE EXCEPTION 'Unsupported expense currency %', v_currency; END IF;\n  v_rate := COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric, 0), CASE WHEN v_currency = 'IDR' THEN 1 ELSE NULL END);\n  IF v_rate IS NULL OR v_rate <= 0 THEN\n    RAISE EXCEPTION 'A positive exchange rate is required for % expenses', v_currency;\n  END IF;\n  IF v_bank_currency IS NOT NULL AND v_bank_currency <> v_currency THEN\n    RAISE EXCEPTION 'Expense currency % does not match selected bank currency %', v_currency, v_bank_currency;\n  END IF;\n\n  SELECT COALESCE(array_agg(value), ARRAY[]::text[]) INTO v_docs\n    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls', '[]'::jsonb));\n\n  IF p_expense_id IS NULL THEN\n    INSERT INTO public.finance_expenses (\n      voucher_number, expense_category, expense_type, amount, expense_date, description,\n      batch_id, import_container_id, delivery_challan_id, payment_method, bank_account_id,\n      payment_reference, paid_by, document_urls, supplier_id, staff_id, invoice_number,\n      due_date, broker_items, pib_bm_amount, pib_ppn_amount, pib_pph_amount, ppn_amount,\n      ppn_manual_override, ppn_calc_mode, dpp_amount, ppn_rate, pph_amount, pph_code_id,\n      stamp_duty_amount, fixed_asset_account_id, bank_charges_amount, approval_status,\n      created_by, currency_code, transaction_currency, functional_currency, exchange_rate,\n      bank_account_currency, payment_currency,\n      payee_id, linked_sales_invoice_id, pph_calculation_regime, pph_dpp_ratio,\n      pph_dpp_amount, pph_rate, is_tax_manual_override\n    ) VALUES (\n      public.next_expense_voucher_number(v_date), p_payload->>'expense_category',\n      COALESCE(NULLIF(p_payload->>'expense_type',''), 'admin'), (p_payload->>'amount')::numeric,\n      v_date, NULLIF(p_payload->>'description',''), NULLIF(p_payload->>'batch_id','')::uuid,\n      NULLIF(p_payload->>'import_container_id','')::uuid, NULLIF(p_payload->>'delivery_challan_id','')::uuid,\n      NULLIF(p_payload->>'payment_method',''), v_bank_id, NULLIF(p_payload->>'payment_reference',''),\n      NULLIF(p_payload->>'paid_by',''), NULLIF(v_docs, ARRAY[]::text[]),\n      NULLIF(p_payload->>'supplier_id','')::uuid, NULLIF(p_payload->>'staff_id','')::uuid,\n      NULLIF(p_payload->>'invoice_number',''), NULLIF(p_payload->>'due_date','')::date,\n      NULLIF(p_payload->'broker_items','null'::jsonb), NULLIF(p_payload->>'pib_bm_amount','')::numeric,\n      NULLIF(p_payload->>'pib_ppn_amount','')::numeric, NULLIF(p_payload->>'pib_pph_amount','')::numeric,\n      COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0), COALESCE((p_payload->>'ppn_manual_override')::boolean,false),\n      COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'), NULLIF(p_payload->>'dpp_amount','')::numeric,\n      COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11), COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),\n      NULLIF(p_payload->>'pph_code_id','')::uuid, COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),\n      NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,\n      COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),\n      COALESCE(NULLIF(p_payload->>'approval_status',''),'pending_approval'),\n      COALESCE(NULLIF(p_payload->>'created_by','')::uuid, auth.uid()),\n      v_currency, v_currency, 'IDR', v_rate, COALESCE(v_bank_currency,v_currency), v_currency,\n      NULLIF(p_payload->>'payee_id','')::uuid,\n      NULLIF(p_payload->>'linked_sales_invoice_id','')::uuid,\n      NULLIF(p_payload->>'pph_calculation_regime',''),\n      NULLIF(p_payload->>'pph_dpp_ratio','')::numeric,\n      NULLIF(p_payload->>'pph_dpp_amount','')::numeric,\n      NULLIF(p_payload->>'pph_rate','')::numeric,\n      COALESCE((p_payload->>'is_tax_manual_override')::boolean, false)\n    ) RETURNING id INTO v_id;\n  ELSE\n    IF EXISTS (SELECT 1 FROM public.finance_expenses WHERE id=p_expense_id AND approval_status='approved') THEN\n      RAISE EXCEPTION 'This expense is posted. Cancel Posting first to make changes.';\n    END IF;\n    UPDATE public.finance_expenses SET\n      expense_category=p_payload->>'expense_category', expense_type=COALESCE(NULLIF(p_payload->>'expense_type',''),'admin'),\n      amount=(p_payload->>'amount')::numeric, expense_date=v_date, description=NULLIF(p_payload->>'description',''),\n      batch_id=NULLIF(p_payload->>'batch_id','')::uuid, import_container_id=NULLIF(p_payload->>'import_container_id','')::uuid,\n      delivery_challan_id=NULLIF(p_payload->>'delivery_challan_id','')::uuid,\n      payment_method=NULLIF(p_payload->>'payment_method',''), bank_account_id=v_bank_id,\n      payment_reference=NULLIF(p_payload->>'payment_reference',''), paid_by=NULLIF(p_payload->>'paid_by',''),\n      document_urls=NULLIF(v_docs,ARRAY[]::text[]), supplier_id=NULLIF(p_payload->>'supplier_id','')::uuid,\n      staff_id=NULLIF(p_payload->>'staff_id','')::uuid, invoice_number=NULLIF(p_payload->>'invoice_number',''),\n      due_date=NULLIF(p_payload->>'due_date','')::date, broker_items=NULLIF(p_payload->'broker_items','null'::jsonb),\n      pib_bm_amount=NULLIF(p_payload->>'pib_bm_amount','')::numeric,\n      pib_ppn_amount=NULLIF(p_payload->>'pib_ppn_amount','')::numeric,\n      pib_pph_amount=NULLIF(p_payload->>'pib_pph_amount','')::numeric,\n      ppn_amount=COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0),\n      ppn_manual_override=COALESCE((p_payload->>'ppn_manual_override')::boolean,false),\n      ppn_calc_mode=COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'),\n      dpp_amount=NULLIF(p_payload->>'dpp_amount','')::numeric, ppn_rate=COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11),\n      pph_amount=COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0), pph_code_id=NULLIF(p_payload->>'pph_code_id','')::uuid,\n      stamp_duty_amount=COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),\n      fixed_asset_account_id=NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,\n      bank_charges_amount=COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),\n      currency_code=v_currency, transaction_currency=v_currency, functional_currency='IDR', exchange_rate=v_rate,\n      bank_account_currency=COALESCE(v_bank_currency,v_currency), payment_currency=v_currency,\n      payee_id=NULLIF(p_payload->>'payee_id','')::uuid,\n      linked_sales_invoice_id=NULLIF(p_payload->>'linked_sales_invoice_id','')::uuid,\n      pph_calculation_regime=NULLIF(p_payload->>'pph_calculation_regime',''),\n      pph_dpp_ratio=NULLIF(p_payload->>'pph_dpp_ratio','')::numeric,\n      pph_dpp_amount=NULLIF(p_payload->>'pph_dpp_amount','')::numeric,\n      pph_rate=NULLIF(p_payload->>'pph_rate','')::numeric,\n      is_tax_manual_override=COALESCE((p_payload->>'is_tax_manual_override')::boolean, false)\n    WHERE id=p_expense_id RETURNING id INTO v_id;\n  END IF;\n  RETURN v_id;\nEND;\n$function$","CREATE OR REPLACE FUNCTION public.edit_approved_finance_expense_atomic(\n  p_expense_id uuid,\n  p_payload jsonb,\n  p_bank_statement_line_id uuid DEFAULT NULL::uuid,\n  p_allocation_amount numeric DEFAULT NULL::numeric\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_exp public.finance_expenses%rowtype;\n  v_journal_id uuid;\n  v_journal_count integer;\n  v_date date;\n  v_bank_id uuid;\n  v_bank_currency text;\n  v_currency text;\n  v_rate numeric;\n  v_docs text[];\n  v_allocation record;\n  v_same_selected_count integer;\n  v_selected_amount numeric;\n  v_period_status text;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  SELECT * INTO v_exp FROM public.finance_expenses WHERE id=p_expense_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\n  IF v_exp.approval_status<>'approved' THEN RAISE EXCEPTION 'Approved expense edit requires an approved expense'; END IF;\n\n  SELECT count(*),(array_agg(id ORDER BY created_at DESC,id DESC))[1]\n    INTO v_journal_count,v_journal_id\n    FROM public.journal_entries\n   WHERE source_module IN('expense','expenses')\n     AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n     AND is_posted=true AND NOT COALESCE(is_reversed,false);\n  IF v_journal_count<>1 THEN RAISE EXCEPTION 'Approved expense must have exactly one active effective journal'; END IF;\n  PERFORM 1 FROM public.journal_entries WHERE id=v_journal_id FOR UPDATE;\n\n  SELECT ap.status INTO v_period_status\n    FROM public.journal_entries je\n    LEFT JOIN public.accounting_periods ap\n      ON ap.start_date<=je.entry_date AND ap.end_date>=je.entry_date\n   WHERE je.id=v_journal_id\n   ORDER BY ap.start_date DESC LIMIT 1;\n  IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN\n    RAISE EXCEPTION 'Cannot edit approved expense in a closed accounting period';\n  END IF;\n\n  IF COALESCE((p_payload->>'amount')::numeric,0)<=0 THEN RAISE EXCEPTION 'Expense amount must be greater than zero'; END IF;\n  IF NULLIF(p_payload->>'expense_category','') IS NULL THEN RAISE EXCEPTION 'Expense category is required'; END IF;\n  v_date:=COALESCE((p_payload->>'expense_date')::date,current_date);\n  v_bank_id:=NULLIF(p_payload->>'bank_account_id','')::uuid;\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id=v_bank_id;\n  v_currency:=upper(COALESCE(NULLIF(p_payload->>'transaction_currency',''),v_bank_currency,'IDR'));\n  v_rate:=COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric,0),CASE WHEN v_currency='IDR' THEN 1 END);\n  IF v_currency NOT IN('IDR','USD') OR v_rate IS NULL OR v_rate<=0 THEN RAISE EXCEPTION 'Valid expense currency/rate is required'; END IF;\n  IF v_bank_currency IS NOT NULL AND v_bank_currency<>v_currency THEN RAISE EXCEPTION 'Expense currency does not match selected bank currency'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IS NOT NULL\n     AND NULLIF(p_payload->>'payment_method','') NOT IN('cash','petty_cash')\n     AND v_bank_id IS NULL THEN RAISE EXCEPTION 'Bank-paid expense requires a bank account'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IN('cash','petty_cash')\n     AND p_bank_statement_line_id IS NOT NULL THEN RAISE EXCEPTION 'Cash/petty-cash expense cannot create a bank allocation'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IS NULL AND p_bank_statement_line_id IS NOT NULL THEN RAISE EXCEPTION 'Accrued expense cannot create a bank allocation'; END IF;\n  SELECT ap.status INTO v_period_status\n    FROM public.accounting_periods ap\n   WHERE ap.start_date<=v_date AND ap.end_date>=v_date\n   ORDER BY ap.start_date DESC LIMIT 1;\n  IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN\n    RAISE EXCEPTION 'Cannot move approved expense into a closed accounting period';\n  END IF;\n  SELECT COALESCE(array_agg(value),ARRAY[]::text[]) INTO v_docs\n    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls','[]'::jsonb));\n\n  -- Preserve the edited bank mode through the legacy unlinked-payment normalizer.\n  PERFORM set_config('app.expense_atomic_bank_link','on',true);\n\n  UPDATE public.finance_expenses SET\n    expense_category=p_payload->>'expense_category',expense_type=COALESCE(NULLIF(p_payload->>'expense_type',''),'admin'),\n    amount=(p_payload->>'amount')::numeric,expense_date=v_date,description=NULLIF(p_payload->>'description',''),\n    batch_id=NULLIF(p_payload->>'batch_id','')::uuid,import_container_id=NULLIF(p_payload->>'import_container_id','')::uuid,\n    delivery_challan_id=NULLIF(p_payload->>'delivery_challan_id','')::uuid,\n    payment_method=NULLIF(p_payload->>'payment_method',''),bank_account_id=v_bank_id,\n    payment_reference=NULLIF(p_payload->>'payment_reference',''),paid_by=NULLIF(p_payload->>'paid_by',''),\n    document_urls=NULLIF(v_docs,ARRAY[]::text[]),supplier_id=NULLIF(p_payload->>'supplier_id','')::uuid,\n    staff_id=NULLIF(p_payload->>'staff_id','')::uuid,invoice_number=NULLIF(p_payload->>'invoice_number',''),\n    due_date=NULLIF(p_payload->>'due_date','')::date,broker_items=NULLIF(p_payload->'broker_items','null'::jsonb),\n    pib_bm_amount=NULLIF(p_payload->>'pib_bm_amount','')::numeric,pib_ppn_amount=NULLIF(p_payload->>'pib_ppn_amount','')::numeric,\n    pib_pph_amount=NULLIF(p_payload->>'pib_pph_amount','')::numeric,ppn_amount=COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0),\n    ppn_manual_override=COALESCE((p_payload->>'ppn_manual_override')::boolean,false),\n    ppn_calc_mode=COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'),dpp_amount=NULLIF(p_payload->>'dpp_amount','')::numeric,\n    ppn_rate=COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11),pph_amount=COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),\n    pph_code_id=NULLIF(p_payload->>'pph_code_id','')::uuid,stamp_duty_amount=COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),\n    fixed_asset_account_id=NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,\n    bank_charges_amount=COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),\n    currency_code=v_currency,transaction_currency=v_currency,functional_currency='IDR',exchange_rate=v_rate,\n    bank_account_currency=COALESCE(v_bank_currency,v_currency),payment_currency=v_currency,\n    payee_id=NULLIF(p_payload->>'payee_id','')::uuid,\n    linked_sales_invoice_id=NULLIF(p_payload->>'linked_sales_invoice_id','')::uuid,\n    pph_calculation_regime=NULLIF(p_payload->>'pph_calculation_regime',''),\n    pph_dpp_ratio=NULLIF(p_payload->>'pph_dpp_ratio','')::numeric,\n    pph_dpp_amount=NULLIF(p_payload->>'pph_dpp_amount','')::numeric,\n    pph_rate=NULLIF(p_payload->>'pph_rate','')::numeric,\n    is_tax_manual_override=COALESCE((p_payload->>'is_tax_manual_override')::boolean, false)\n  WHERE id=p_expense_id;\n\n  -- The trigger must retain the header identity and rebuild only its lines.\n  IF NOT EXISTS(\n    SELECT 1 FROM public.journal_entries\n     WHERE id=v_journal_id\n       AND source_module IN('expense','expenses')\n       AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n       AND is_posted AND NOT COALESCE(is_reversed,false)\n  ) THEN RAISE EXCEPTION 'Expense journal identity changed during edit'; END IF;\n  IF (SELECT count(*) FROM public.journal_entries\n       WHERE source_module IN('expense','expenses')\n         AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n         AND is_posted AND NOT COALESCE(is_reversed,false))<>1 THEN\n    RAISE EXCEPTION 'Expense edit did not preserve exactly one active journal';\n  END IF;\n\n  SELECT count(*),max(allocation_amount)\n    INTO v_same_selected_count,v_selected_amount\n    FROM public.bank_statement_allocations\n   WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind='supplier'\n     AND bank_statement_line_id=p_bank_statement_line_id;\n\n  IF p_bank_statement_line_id IS NOT NULL\n     AND v_same_selected_count=0 THEN\n    PERFORM public.link_bank_statement_line(\n      p_bank_statement_line_id,'expense',p_expense_id,'supplier',p_allocation_amount);\n  ELSIF p_bank_statement_line_id IS NOT NULL\n     AND p_allocation_amount IS NOT NULL\n     AND abs(COALESCE(v_selected_amount,0)-p_allocation_amount)>0.01 THEN\n    RAISE EXCEPTION 'Change an existing bank allocation through unlink/relink so other payments remain intact';\n  ELSE\n    UPDATE public.bank_statement_allocations SET allocation_amount=allocation_amount WHERE document_type='expense' AND document_id=p_expense_id;\n  END IF;\n\n  UPDATE public.bank_statement_allocations SET allocation_amount=allocation_amount WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind<>'supplier';\n\n  PERFORM public.recalculate_expense_payment_state(p_expense_id);\n  RETURN p_expense_id;\nEND;\n$function$",COMMIT}	phase3_save_expense_payee_fields	\N	\N	\N
20260909001000	{"-- Migration: 20260909001000_phase4_historical_payee_backfill.sql\n-- Description: Phase 4 Historical Payee Master creation, metadata-only backfill of 12 posted historical expenses,\n--              correction of 5 unposted Faizah expenses to PPh 21 non-employee regime, and trigger safeguards.\n--              Zero changes to historical posted debits/credits, bank reconciliations, petty cash, or loan balances.\n\nBEGIN","-- 1. Ensure trigger functions respect the 'app.finance_metadata_repair' bypass flag\nCREATE OR REPLACE FUNCTION public.enforce_tax_period_lock()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nDECLARE\n  v_status text;\nBEGIN\n  IF (current_setting('app.finance_metadata_repair', true) = 'on') THEN\n    RETURN COALESCE(NEW, OLD);\n  END IF;\n\n  IF (current_setting('request.jwt.claim.role', true) = 'service_role') THEN\n    RETURN COALESCE(NEW, OLD);\n  END IF;\n\n  IF TG_OP = 'UPDATE' OR TG_OP = 'DELETE' THEN\n    IF (COALESCE(OLD.tax_period_id, NULL) IS NOT NULL) THEN\n      SELECT status INTO v_status FROM tax_periods WHERE id = OLD.tax_period_id;\n      IF v_status = 'closed' THEN\n        RAISE EXCEPTION 'Tax period is closed; cannot modify % on %',\n          TG_OP, TG_TABLE_NAME\n          USING ERRCODE = 'check_violation';\n      END IF;\n    END IF;\n  END IF;\n\n  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN\n    IF NEW.tax_period_id IS NOT NULL THEN\n      SELECT status INTO v_status FROM tax_periods WHERE id = NEW.tax_period_id;\n      IF v_status = 'closed' THEN\n        RAISE EXCEPTION 'Tax period is closed; cannot assign new rows to it'\n          USING ERRCODE = 'check_violation';\n      END IF;\n    END IF;\n  END IF;\n\n  RETURN COALESCE(NEW, OLD);\nEND $function$","-- Update auto_post_expense_accounting to respect app.finance_metadata_repair\nCREATE OR REPLACE FUNCTION public.auto_post_expense_accounting()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_expense_account_id uuid;\n  v_payment_account_id uuid;\n  v_journal_id uuid;\n  v_active_count integer;\n  v_description text;\n  v_credit_desc text;\n  v_category_label text;\n  v_bm_account_id uuid;\n  v_ppn_account_id uuid;\n  v_pph_account_id uuid;\n  v_stamp_duty_account_id uuid;\n  v_bank_charge_acc_id uuid;\n  v_line_num integer;\n  v_net_payment numeric(18,2);\n  v_total numeric(18,2);\n  v_bank_charges numeric(18,2);\nBEGIN\n  -- Bypass completely during historical metadata repair\n  IF current_setting('app.finance_metadata_repair', true) = 'on' THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.approval_status <> 'approved' THEN RETURN NEW; END IF;\n\n  IF TG_OP='UPDATE' AND OLD.approval_status='approved' THEN\n    IF ROW(\n      OLD.amount,OLD.expense_category,OLD.expense_date,OLD.description,\n      OLD.payment_method,OLD.bank_account_id,OLD.pib_bm_amount,OLD.pib_ppn_amount,\n      OLD.pib_pph_amount,OLD.ppn_amount,OLD.pph_amount,OLD.pph_code_id,OLD.stamp_duty_amount,\n      OLD.fixed_asset_account_id,COALESCE(OLD.bank_charges_amount,0),\n      OLD.transaction_currency,OLD.exchange_rate,OLD.supplier_id,OLD.payee_id\n    ) IS NOT DISTINCT FROM ROW(\n      NEW.amount,NEW.expense_category,NEW.expense_date,NEW.description,\n      NEW.payment_method,NEW.bank_account_id,NEW.pib_bm_amount,NEW.pib_ppn_amount,\n      NEW.pib_pph_amount,NEW.ppn_amount,NEW.pph_amount,NEW.pph_code_id,NEW.stamp_duty_amount,\n      NEW.fixed_asset_account_id,COALESCE(NEW.bank_charges_amount,0),\n      NEW.transaction_currency,NEW.exchange_rate,NEW.supplier_id,NEW.payee_id\n    ) THEN\n      RETURN NEW;\n    END IF;\n  END IF;\n\n  SELECT count(*), (array_agg(id ORDER BY created_at DESC,id DESC))[1]\n    INTO v_active_count,v_journal_id\n    FROM public.journal_entries\n   WHERE source_module IN('expense','expenses')\n     AND (reference_id=NEW.id OR reference_number='EXP-'||NEW.id::text)\n     AND is_posted=true AND NOT COALESCE(is_reversed,false);\n\n  IF v_active_count>1 THEN\n    RAISE EXCEPTION 'Expense % has multiple active journals; edit is blocked',NEW.id;\n  END IF;\n  IF TG_OP='UPDATE' AND OLD.approval_status='approved' AND v_active_count<>1 THEN\n    RAISE EXCEPTION 'Approved expense % must have exactly one active journal before edit',NEW.id;\n  END IF;\n  IF v_journal_id IS NOT NULL THEN\n    PERFORM 1 FROM public.journal_entries WHERE id=v_journal_id FOR UPDATE;\n    DELETE FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;\n  END IF;\n\n  IF NEW.payment_method='cash' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;\n  ELSIF NEW.payment_method='petty_cash' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='1102' LIMIT 1;\n  ELSIF NEW.payment_method = 'bank_transfer' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n  ELSIF NEW.payment_method IS NOT NULL AND NEW.bank_account_id IS NOT NULL THEN\n    SELECT coa_id INTO v_payment_account_id FROM public.bank_accounts WHERE id=NEW.bank_account_id;\n  ELSIF NEW.payment_method IS NULL OR NEW.payment_method = 'outstanding' THEN\n    IF NEW.expense_category='salary' THEN\n      SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2120' LIMIT 1;\n    ELSE\n      SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n    END IF;\n  END IF;\n  IF v_payment_account_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot post expense %: the selected payment/AP account is not configured',NEW.id;\n  END IF;\n\n  IF NEW.expense_category='pib_import' THEN\n    SELECT id INTO v_bm_account_id FROM public.chart_of_accounts WHERE code='1130' LIMIT 1;\n    SELECT id INTO v_ppn_account_id FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;\n    SELECT id INTO v_pph_account_id FROM public.chart_of_accounts WHERE code='1160' LIMIT 1;\n    IF COALESCE(NEW.pib_bm_amount,0)>0 AND v_bm_account_id IS NULL THEN RAISE EXCEPTION 'BM account 1130 is missing'; END IF;\n    IF COALESCE(NEW.pib_ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN account 1150 is missing'; END IF;\n    IF COALESCE(NEW.pib_pph_amount,0)>0 AND v_pph_account_id IS NULL THEN RAISE EXCEPTION 'PPh 22 account 1160 is missing'; END IF;\n    v_total:=COALESCE(NEW.pib_bm_amount,0)+COALESCE(NEW.pib_ppn_amount,0)+COALESCE(NEW.pib_pph_amount,0);\n    IF v_total<>NEW.amount THEN\n      RAISE EXCEPTION 'PIB components sum (%) must equal total expense amount (%)',v_total,NEW.amount;\n    END IF;\n    v_journal_id:=public.upsert_expense_journal_header_in_place(\n      v_journal_id,NEW.id,NEW.expense_date,COALESCE(NEW.description,'PIB Import Payment'),\n      'pib_import',v_total,NEW.created_by);\n    v_line_num:=1;\n    IF COALESCE(NEW.pib_bm_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_bm_account_id,NEW.pib_bm_amount,0,'PIB - Import Duty (BM) [landed cost]',NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    IF COALESCE(NEW.pib_ppn_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.pib_ppn_amount,0,'PIB - PPN Import (Input VAT)',NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    IF COALESCE(NEW.pib_pph_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_pph_account_id,NEW.pib_pph_amount,0,'PIB - PPh 22 Dibayar Dimuka',NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_payment_account_id,0,NEW.amount,'PIB - Payment ['||COALESCE(NEW.description,'')||']',NEW.supplier_id,NEW.payee_id);\n    RETURN NEW;\n  END IF;\n\n  IF NEW.expense_category='fixed_asset' THEN\n    v_expense_account_id:=NEW.fixed_asset_account_id;\n    IF v_expense_account_id IS NULL THEN RAISE EXCEPTION 'A posting Fixed Asset account is required'; END IF;\n    SELECT id INTO v_ppn_account_id FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;\n    IF COALESCE(NEW.ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Masukan account 1150 is missing'; END IF;\n    v_description:=COALESCE(NEW.description,'Fixed Asset Purchase');\n    v_total:=NEW.amount+COALESCE(NEW.ppn_amount,0);\n    v_journal_id:=public.upsert_expense_journal_header_in_place(\n      v_journal_id,NEW.id,NEW.expense_date,v_description,'fixed_asset',v_total,NEW.created_by);\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,1,v_expense_account_id,NEW.amount,0,v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=2;\n    IF COALESCE(NEW.ppn_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.ppn_amount,0,'PPN Masukan - '||v_description,NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_payment_account_id,0,v_total,v_description,NEW.supplier_id,NEW.payee_id);\n    RETURN NEW;\n  END IF;\n\n  v_expense_account_id:=CASE WHEN public.is_capitalizable_landed_cost_category(NEW.expense_category) THEN (SELECT id FROM public.chart_of_accounts WHERE code='1130' LIMIT 1) ELSE public.get_expense_account_id(NEW.expense_category) END;\n  IF v_expense_account_id IS NULL THEN RAISE EXCEPTION 'No expense account is mapped for %',NEW.expense_category; END IF;\n  v_category_label:=initcap(replace(NEW.expense_category,'_',' '));\n  v_description:=COALESCE(NEW.description,NEW.expense_category);\n  v_credit_desc:=COALESCE(substring(NEW.description FROM '^[^\\\\n]+'),NEW.expense_category)||' ['||v_category_label||']';\n  \n  SELECT id INTO v_ppn_account_id FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;\n  SELECT id INTO v_stamp_duty_account_id FROM public.chart_of_accounts WHERE code='6950' LIMIT 1;\n  IF COALESCE(NEW.ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Masukan account 1150 is missing'; END IF;\n  IF COALESCE(NEW.stamp_duty_amount,0)>0 AND v_stamp_duty_account_id IS NULL THEN RAISE EXCEPTION 'Stamp Duty account 6950 is missing'; END IF;\n\n  -- STRICT ZERO-FALLBACK RESOLUTION FOR WITHHOLDING TAX\n  IF COALESCE(NEW.pph_amount, 0) > 0 THEN\n    IF NEW.pph_code_id IS NULL THEN\n      RAISE EXCEPTION 'Cannot post expense %: Withholding tax amount % exists but pph_code_id is NULL', \n        NEW.id, NEW.pph_amount;\n    END IF;\n\n    v_pph_account_id := public.fn_pph_payable_account_id(NEW.pph_code_id);\n\n    IF v_pph_account_id IS NULL THEN\n      RAISE EXCEPTION 'Cannot post expense %: Tax code % has no valid GL liability account configured', \n        NEW.id, NEW.pph_code_id;\n    END IF;\n  END IF;\n\n  v_bank_charges:=COALESCE(NEW.bank_charges_amount,0);\n  IF v_bank_charges>0 THEN\n    SELECT id INTO v_bank_charge_acc_id FROM public.chart_of_accounts WHERE code='6900' LIMIT 1;\n    IF v_bank_charge_acc_id IS NULL THEN RAISE EXCEPTION 'Bank charges account 6900 is missing'; END IF;\n  END IF;\n\n  v_net_payment:=(NEW.amount+COALESCE(NEW.ppn_amount,0)+COALESCE(NEW.stamp_duty_amount,0))-COALESCE(NEW.pph_amount,0);\n  v_total:=NEW.amount+COALESCE(NEW.ppn_amount,0)+COALESCE(NEW.stamp_duty_amount,0)+v_bank_charges;\n\n  v_journal_id:=public.upsert_expense_journal_header_in_place(\n    v_journal_id,NEW.id,NEW.expense_date,v_description,NEW.expense_category,v_total,NEW.created_by);\n\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n  VALUES(v_journal_id,1,v_expense_account_id,NEW.amount,0,v_description,NEW.supplier_id,NEW.payee_id);\n  v_line_num:=2;\n\n  IF COALESCE(NEW.ppn_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.ppn_amount,0,'PPN Masukan - '||v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  IF COALESCE(NEW.stamp_duty_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_stamp_duty_account_id,NEW.stamp_duty_amount,0,'Bea Meterai - '||v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  IF v_bank_charges>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_bank_charge_acc_id,v_bank_charges,0,'Biaya Transfer / Bank Charges - '||v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  IF COALESCE(NEW.pph_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_pph_account_id,0,NEW.pph_amount,'PPh Ditahan - '||v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n  VALUES(v_journal_id,v_line_num,v_payment_account_id,0,v_net_payment+v_bank_charges,v_credit_desc,NEW.supplier_id,NEW.payee_id);\n\n  RETURN NEW;\nEND;\n$function$","-- Update trg_sync_expense_pph_account to respect app.finance_metadata_repair\nCREATE OR REPLACE FUNCTION public.trg_sync_expense_pph_account()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_account_id uuid;\n  v_journal_id uuid;\n  v_line_number integer;\nBEGIN\n  IF current_setting('app.finance_metadata_repair', true) = 'on' THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.expense_category = 'import_broker' THEN\n    RETURN NEW;\n  END IF;\n  IF COALESCE(NEW.pph_amount, 0) <= 0 THEN\n    RETURN NEW;\n  END IF;\n\n  v_account_id := public.fn_pph_payable_account_id(NEW.pph_code_id);\n  IF v_account_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT id INTO v_journal_id\n    FROM public.journal_entries\n   WHERE reference_id = NEW.id\n     AND source_module IN ('expense', 'expenses')\n   ORDER BY created_at DESC\n   LIMIT 1;\n\n  IF v_journal_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_journal_id\n       AND debit = 0\n       AND description ILIKE 'PPh Ditahan%'\n  ) THEN\n    UPDATE public.journal_entry_lines\n       SET account_id = v_account_id,\n           payee_id = NEW.payee_id\n     WHERE journal_entry_id = v_journal_id\n       AND debit = 0\n       AND description ILIKE 'PPh Ditahan%';\n  ELSE\n    UPDATE public.journal_entry_lines\n       SET credit = credit - NEW.pph_amount\n     WHERE id = (\n       SELECT id FROM public.journal_entry_lines\n        WHERE journal_entry_id = v_journal_id\n          AND credit >= NEW.pph_amount\n        ORDER BY credit DESC, line_number DESC\n        LIMIT 1\n     );\n\n    SELECT COALESCE(MAX(line_number), 0) + 1 INTO v_line_number\n      FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_journal_id;\n\n    INSERT INTO public.journal_entry_lines\n      (journal_entry_id, line_number, account_id, debit, credit, description, supplier_id, payee_id)\n    VALUES\n      (v_journal_id, v_line_number, v_account_id, 0, NEW.pph_amount,\n       'PPh Ditahan - ' || COALESCE(NEW.description, NEW.voucher_number, 'Expense'),\n       NEW.supplier_id, NEW.payee_id);\n  END IF;\n\n  UPDATE public.journal_entries\n     SET total_debit = (SELECT COALESCE(SUM(debit), 0) FROM public.journal_entry_lines WHERE journal_entry_id = v_journal_id),\n         total_credit = (SELECT COALESCE(SUM(credit), 0) FROM public.journal_entry_lines WHERE journal_entry_id = v_journal_id)\n   WHERE id = v_journal_id;\n\n  RETURN NEW;\nEND;\n$function$","-- 2. Execute Data Migration within Protected Metadata-Repair Context\nDO $$\nDECLARE\n  v_pph21_ne_id uuid := '82c88cd1-a57e-4fa0-a94e-b0bb1863c190'::uuid;\n  v_sheila_id uuid;\n  v_ricardo_id uuid;\n  v_rudi_id uuid;\n  v_notaris_id uuid;\n  v_roslina_id uuid;\n  v_faizah_id uuid;\nBEGIN\n  -- Activate metadata-repair mode to suppress journal triggers and period lock exceptions\n  PERFORM set_config('app.finance_metadata_repair', 'on', true);\n\n  -- A. Create Payee Master Records\n  -- 1. Sheila (Tax Consultant)\n  INSERT INTO public.finance_payees (\n    payee_code, full_name, business_role, tax_classification, default_pph_code_id, notes, is_active\n  ) VALUES (\n    'PAY-0001', 'Sheila', 'tax_consultant', 'tenaga_ahli', v_pph21_ne_id, 'Historical tax consultant', true\n  )\n  ON CONFLICT (payee_code) DO UPDATE \n    SET full_name = EXCLUDED.full_name,\n        business_role = EXCLUDED.business_role,\n        tax_classification = EXCLUDED.tax_classification,\n        default_pph_code_id = EXCLUDED.default_pph_code_id\n  RETURNING id INTO v_sheila_id;\n\n  -- 2. Ricardo Suhendra W (Tax Consultant / Financial Statement Review)\n  INSERT INTO public.finance_payees (\n    payee_code, full_name, business_role, tax_classification, default_pph_code_id, notes, is_active\n  ) VALUES (\n    'PAY-0002', 'Ricardo Suhendra W', 'tax_consultant', 'tenaga_ahli', v_pph21_ne_id, 'Financial statements review consultant', true\n  )\n  ON CONFLICT (payee_code) DO UPDATE \n    SET full_name = EXCLUDED.full_name,\n        business_role = EXCLUDED.business_role,\n        tax_classification = EXCLUDED.tax_classification,\n        default_pph_code_id = EXCLUDED.default_pph_code_id\n  RETURNING id INTO v_ricardo_id;\n\n  -- 3. Rudi Kartono (Sales Commission Recipient)\n  INSERT INTO public.finance_payees (\n    payee_code, full_name, business_role, tax_classification, default_pph_code_id, notes, is_active\n  ) VALUES (\n    'PAY-0003', 'Rudi Kartono', 'sales_commission_recipient', 'bukan_pegawai_imbalan', v_pph21_ne_id, 'Sales commission recipient', true\n  )\n  ON CONFLICT (payee_code) DO UPDATE \n    SET full_name = EXCLUDED.full_name,\n        business_role = EXCLUDED.business_role,\n        tax_classification = EXCLUDED.tax_classification,\n        default_pph_code_id = EXCLUDED.default_pph_code_id\n  RETURNING id INTO v_rudi_id;\n\n  -- 4. Notaris (Notary)\n  INSERT INTO public.finance_payees (\n    payee_code, full_name, business_role, tax_classification, default_pph_code_id, notes, is_active\n  ) VALUES (\n    'PAY-0004', 'Notaris', 'notary', 'tenaga_ahli', v_pph21_ne_id, 'Notary professional legal services', true\n  )\n  ON CONFLICT (payee_code) DO UPDATE \n    SET full_name = EXCLUDED.full_name,\n        business_role = EXCLUDED.business_role,\n        tax_classification = EXCLUDED.tax_classification,\n        default_pph_code_id = EXCLUDED.default_pph_code_id\n  RETURNING id INTO v_notaris_id;\n\n  -- 5. Roslina (Sales Commission Recipient)\n  INSERT INTO public.finance_payees (\n    payee_code, full_name, business_role, tax_classification, default_pph_code_id, notes, is_active\n  ) VALUES (\n    'PAY-0005', 'Roslina', 'sales_commission_recipient', 'bukan_pegawai_imbalan', v_pph21_ne_id, 'Marketing / sales commission recipient', true\n  )\n  ON CONFLICT (payee_code) DO UPDATE \n    SET full_name = EXCLUDED.full_name,\n        business_role = EXCLUDED.business_role,\n        tax_classification = EXCLUDED.tax_classification,\n        default_pph_code_id = EXCLUDED.default_pph_code_id\n  RETURNING id INTO v_roslina_id;\n\n  -- 6. Faizah (Sales Commission Recipient)\n  INSERT INTO public.finance_payees (\n    payee_code, full_name, business_role, tax_classification, default_pph_code_id, notes, is_active\n  ) VALUES (\n    'PAY-0006', 'Faizah', 'sales_commission_recipient', 'bukan_pegawai_imbalan', v_pph21_ne_id, 'Sales commission recipient - PT RANIA', true\n  )\n  ON CONFLICT (payee_code) DO UPDATE \n    SET full_name = EXCLUDED.full_name,\n        business_role = EXCLUDED.business_role,\n        tax_classification = EXCLUDED.tax_classification,\n        default_pph_code_id = EXCLUDED.default_pph_code_id\n  RETURNING id INTO v_faizah_id;\n\n  -- B. Backfill 12 Posted Historical Expenses (Metadata Only, Preserving Posted Accounting)\n  -- 1. EXP/26/127 -> Sheila (Amount 2.700.000, DPP 1.350.000, PPh 67.500)\n  UPDATE public.finance_expenses\n     SET payee_id = v_sheila_id,\n         pph_calculation_regime = 'pasal17_dpp50',\n         pph_dpp_ratio = 0.50,\n         pph_dpp_amount = 1350000.00,\n         pph_rate = 2.50\n   WHERE voucher_number = 'EXP/26/127';\n\n  -- 2. Ricardo Suhendra W (8 Records, Amount 2.000.000 each, DPP 1.000.000, PPh 50.000)\n  UPDATE public.finance_expenses\n     SET payee_id = v_ricardo_id,\n         pph_calculation_regime = 'pasal17_dpp50',\n         pph_dpp_ratio = 0.50,\n         pph_dpp_amount = 1000000.00,\n         pph_rate = 2.50\n   WHERE voucher_number IN (\n     'EXP/26/203', 'EXP/26/204', 'EXP/26/200', 'EXP/26/199', 'EXP/26/201',\n     'EXP/26-26/138', 'EXP/26/179', 'EXP/26/180'\n   );\n\n  -- 3. EXP/26/226 -> Rudi Kartono (Amount 17.880.000, DPP 8.940.000, PPh 447.000, SAPJ-26-035)\n  UPDATE public.finance_expenses\n     SET payee_id = v_rudi_id,\n         linked_sales_invoice_id = '3e2652e2-ac33-4413-842e-37b6189736a4'::uuid,\n         pph_calculation_regime = 'pasal17_dpp50',\n         pph_dpp_ratio = 0.50,\n         pph_dpp_amount = 8940000.00,\n         pph_rate = 2.50\n   WHERE voucher_number = 'EXP/26/226';\n\n  -- 4. EXP/26/224 -> Notaris (Amount 15.000.000, DPP 7.500.000, PPh 375.000)\n  UPDATE public.finance_expenses\n     SET payee_id = v_notaris_id,\n         pph_calculation_regime = 'pasal17_dpp50',\n         pph_dpp_ratio = 0.50,\n         pph_dpp_amount = 7500000.00,\n         pph_rate = 2.50\n   WHERE voucher_number = 'EXP/26/224';\n\n  -- 5. EXP/26/223 -> Roslina (Amount 2.000.000, no tax withheld)\n  UPDATE public.finance_expenses\n     SET payee_id = v_roslina_id\n   WHERE voucher_number = 'EXP/26/223';\n\n  -- Attribute payee_id to journal_entry_lines for these 12 historical expenses\n  -- Preserves line amounts, accounts, debits, credits, and journal checksums completely\n  UPDATE public.journal_entry_lines jel\n     SET payee_id = fe.payee_id\n    FROM public.finance_expenses fe\n    JOIN public.journal_entries je ON je.reference_id = fe.id\n   WHERE jel.journal_entry_id = je.id\n     AND fe.voucher_number IN (\n       'EXP/26/127', 'EXP/26/203', 'EXP/26/204', 'EXP/26/200', 'EXP/26/199', 'EXP/26/201',\n       'EXP/26-26/138', 'EXP/26/179', 'EXP/26/180', 'EXP/26/226', 'EXP/26/224', 'EXP/26/223'\n     )\n     AND jel.payee_id IS NULL;\n\n  -- C. Correct 5 Unposted Faizah Expenses (Pending Approval, Currently Carrying PPH22)\n  -- 1. EXP/26/236 (SAPJ 26-025, Amount 2.957.625, DPP 1.478.813, PPh 73.941)\n  UPDATE public.finance_expenses\n     SET payee_id = v_faizah_id,\n         pph_code_id = v_pph21_ne_id,\n         pph_calculation_regime = 'pasal17_dpp50',\n         pph_dpp_ratio = 0.50,\n         pph_dpp_amount = 1478813.00,\n         pph_rate = 2.50,\n         pph_amount = 73941.00,\n         is_tax_manual_override = false,\n         linked_sales_invoice_id = 'bb5ed19a-66d9-4cb7-90b6-8694bc848052'::uuid,\n         delivery_challan_id = '33bd7fbe-c9ec-4994-b335-7660eaaf63a8'::uuid\n   WHERE voucher_number = 'EXP/26/236' AND approval_status = 'pending_approval';\n\n  -- 2. EXP/26/237 (SAPJ 26-030, Amount 2.700.000, DPP 1.350.000, PPh 67.500)\n  UPDATE public.finance_expenses\n     SET payee_id = v_faizah_id,\n         pph_code_id = v_pph21_ne_id,\n         pph_calculation_regime = 'pasal17_dpp50',\n         pph_dpp_ratio = 0.50,\n         pph_dpp_amount = 1350000.00,\n         pph_rate = 2.50,\n         pph_amount = 67500.00,\n         is_tax_manual_override = false,\n         linked_sales_invoice_id = '17a0aea3-5398-4733-8b52-068422a53290'::uuid,\n         delivery_challan_id = '21953713-1c04-4fe4-9ff4-c6e6197044b9'::uuid\n   WHERE voucher_number = 'EXP/26/237' AND approval_status = 'pending_approval';\n\n  -- 3. EXP/26/238 (SAPJ 26-032, Amount 3.240.000, DPP 1.620.000, PPh 81.000)\n  UPDATE public.finance_expenses\n     SET payee_id = v_faizah_id,\n         pph_code_id = v_pph21_ne_id,\n         pph_calculation_regime = 'pasal17_dpp50',\n         pph_dpp_ratio = 0.50,\n         pph_dpp_amount = 1620000.00,\n         pph_rate = 2.50,\n         pph_amount = 81000.00,\n         is_tax_manual_override = false,\n         linked_sales_invoice_id = '3300fde7-f257-4c5c-8f5e-f2780ca6600f'::uuid,\n         delivery_challan_id = '4a82330e-68d8-4d0a-80b1-882ccfde7baf'::uuid\n   WHERE voucher_number = 'EXP/26/238' AND approval_status = 'pending_approval';\n\n  -- 4. EXP/26/239 (SAPJ 26-033, Amount 1.350.000, DPP 675.000, PPh 33.750)\n  UPDATE public.finance_expenses\n     SET payee_id = v_faizah_id,\n         pph_code_id = v_pph21_ne_id,\n         pph_calculation_regime = 'pasal17_dpp50',\n         pph_dpp_ratio = 0.50,\n         pph_dpp_amount = 675000.00,\n         pph_rate = 2.50,\n         pph_amount = 33750.00,\n         is_tax_manual_override = false,\n         linked_sales_invoice_id = '1d6196ce-6e41-4ac3-8c2b-71260a77a214'::uuid,\n         delivery_challan_id = '6f923dfe-1ced-4dd4-bb97-44a91808f355'::uuid\n   WHERE voucher_number = 'EXP/26/239' AND approval_status = 'pending_approval';\n\n  -- 5. EXP/26/240 (SAPJ 26-034, Amount 675.000, DPP 337.500, PPh 16.875)\n  UPDATE public.finance_expenses\n     SET payee_id = v_faizah_id,\n         pph_code_id = v_pph21_ne_id,\n         pph_calculation_regime = 'pasal17_dpp50',\n         pph_dpp_ratio = 0.50,\n         pph_dpp_amount = 337500.00,\n         pph_rate = 2.50,\n         pph_amount = 16875.00,\n         is_tax_manual_override = false,\n         linked_sales_invoice_id = '68017ca2-250d-494f-b9ee-cf4245cf367c'::uuid,\n         delivery_challan_id = '64c2248d-b97c-43cf-8864-e1b95f3ae5d8'::uuid\n   WHERE voucher_number = 'EXP/26/240' AND approval_status = 'pending_approval';\n\n  -- Reset metadata-repair mode\n  PERFORM set_config('app.finance_metadata_repair', 'off', true);\nEND $$",COMMIT}	phase4_historical_payee_backfill	\N	\N	\N
20260909110000	{"-- Migration: 20260909110000_repair_auto_post_expense_payment_resolution.sql\n-- Description: Repair auto_post_expense_accounting() payment/AP account resolution.\n--              Restores canonical accounting rules:\n--                - cash -> 1101\n--                - petty_cash -> 1102\n--                - bank_transfer -> 2110 (or direct bank coa_id if bank_account_id is attached)\n--                - outstanding / null -> 2120 (salary) or 2110 (AP)\n--              Removes erroneous \\"A paid expense requires bank_account_id\\" blocker that prevented\n--              approving, creating, and editing normal unlinked or cash/petty expenses.\n--              Maintains all payee attribution and zero-silent-fallback withholding tax rules.\n\nBEGIN","CREATE OR REPLACE FUNCTION public.auto_post_expense_accounting()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_expense_account_id uuid;\n  v_payment_account_id uuid;\n  v_journal_id uuid;\n  v_active_count integer;\n  v_description text;\n  v_credit_desc text;\n  v_category_label text;\n  v_bm_account_id uuid;\n  v_ppn_account_id uuid;\n  v_pph_account_id uuid;\n  v_stamp_duty_account_id uuid;\n  v_bank_charge_acc_id uuid;\n  v_line_num integer;\n  v_net_payment numeric(18,2);\n  v_total numeric(18,2);\n  v_bank_charges numeric(18,2);\nBEGIN\n  -- Bypass completely during historical metadata repair\n  IF current_setting('app.finance_metadata_repair', true) = 'on' THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.approval_status <> 'approved' THEN RETURN NEW; END IF;\n\n  IF TG_OP='UPDATE' AND OLD.approval_status='approved' THEN\n    IF ROW(\n      OLD.amount,OLD.expense_category,OLD.expense_date,OLD.description,\n      OLD.payment_method,OLD.bank_account_id,OLD.pib_bm_amount,OLD.pib_ppn_amount,\n      OLD.pib_pph_amount,OLD.ppn_amount,OLD.pph_amount,OLD.pph_code_id,OLD.stamp_duty_amount,\n      OLD.fixed_asset_account_id,COALESCE(OLD.bank_charges_amount,0),\n      OLD.transaction_currency,OLD.exchange_rate,OLD.supplier_id,OLD.payee_id\n    ) IS NOT DISTINCT FROM ROW(\n      NEW.amount,NEW.expense_category,NEW.expense_date,NEW.description,\n      NEW.payment_method,NEW.bank_account_id,NEW.pib_bm_amount,NEW.pib_ppn_amount,\n      NEW.pib_pph_amount,NEW.ppn_amount,NEW.pph_amount,NEW.pph_code_id,NEW.stamp_duty_amount,\n      NEW.fixed_asset_account_id,COALESCE(NEW.bank_charges_amount,0),\n      NEW.transaction_currency,NEW.exchange_rate,NEW.supplier_id,NEW.payee_id\n    ) THEN\n      RETURN NEW;\n    END IF;\n  END IF;\n\n  SELECT count(*), (array_agg(id ORDER BY created_at DESC,id DESC))[1]\n    INTO v_active_count,v_journal_id\n    FROM public.journal_entries\n   WHERE source_module IN('expense','expenses')\n     AND (reference_id=NEW.id OR reference_number='EXP-'||NEW.id::text)\n     AND is_posted=true AND NOT COALESCE(is_reversed,false);\n\n  IF v_active_count>1 THEN\n    RAISE EXCEPTION 'Expense % has multiple active journals; edit is blocked',NEW.id;\n  END IF;\n  IF TG_OP='UPDATE' AND OLD.approval_status='approved' AND v_active_count<>1 THEN\n    RAISE EXCEPTION 'Approved expense % must have exactly one active journal before edit',NEW.id;\n  END IF;\n  IF v_journal_id IS NOT NULL THEN\n    PERFORM 1 FROM public.journal_entries WHERE id=v_journal_id FOR UPDATE;\n    DELETE FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;\n  END IF;\n\n  IF NEW.payment_method='cash' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='1101' LIMIT 1;\n  ELSIF NEW.payment_method='petty_cash' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='1102' LIMIT 1;\n  ELSIF NEW.payment_method = 'bank_transfer' THEN\n    SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n  ELSIF NEW.payment_method IS NOT NULL AND NEW.bank_account_id IS NOT NULL THEN\n    SELECT coa_id INTO v_payment_account_id FROM public.bank_accounts WHERE id=NEW.bank_account_id;\n  ELSIF NEW.payment_method IS NULL OR NEW.payment_method = 'outstanding' THEN\n    IF NEW.expense_category='salary' THEN\n      SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2120' LIMIT 1;\n    ELSE\n      SELECT id INTO v_payment_account_id FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n    END IF;\n  END IF;\n  IF v_payment_account_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot post expense %: the selected payment/AP account is not configured',NEW.id;\n  END IF;\n\n  IF NEW.expense_category='pib_import' THEN\n    v_bm_account_id:=public.get_expense_account_id('duty_customs');\n    v_ppn_account_id:=public.get_expense_account_id('ppn_import');\n    v_pph_account_id:=public.get_expense_account_id('pph_import');\n    IF COALESCE(NEW.pib_bm_amount,0)>0 AND v_bm_account_id IS NULL THEN RAISE EXCEPTION 'Import Duty account is missing'; END IF;\n    IF COALESCE(NEW.pib_ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Import account is missing'; END IF;\n    IF COALESCE(NEW.pib_pph_amount,0)>0 AND v_pph_account_id IS NULL THEN RAISE EXCEPTION 'PPh Import account is missing'; END IF;\n    v_total:=NEW.amount;\n    v_journal_id:=public.upsert_expense_journal_header_in_place(\n      v_journal_id,NEW.id,NEW.expense_date,COALESCE(NEW.description,'PIB Import Payment'),\n      'pib_import',v_total,NEW.created_by);\n    v_line_num:=1;\n    IF COALESCE(NEW.pib_bm_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_bm_account_id,NEW.pib_bm_amount,0,'PIB - Import Duty (BM) [landed cost]',NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    IF COALESCE(NEW.pib_ppn_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.pib_ppn_amount,0,'PIB - PPN Import (Input VAT)',NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    IF COALESCE(NEW.pib_pph_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_pph_account_id,NEW.pib_pph_amount,0,'PIB - PPh 22 Dibayar Dimuka',NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_payment_account_id,0,NEW.amount,'PIB - Payment ['||COALESCE(NEW.description,'')||']',NEW.supplier_id,NEW.payee_id);\n    RETURN NEW;\n  END IF;\n\n  IF NEW.expense_category='fixed_asset' THEN\n    v_expense_account_id:=NEW.fixed_asset_account_id;\n    IF v_expense_account_id IS NULL THEN RAISE EXCEPTION 'A posting Fixed Asset account is required'; END IF;\n    SELECT id INTO v_ppn_account_id FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;\n    IF COALESCE(NEW.ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Masukan account 1150 is missing'; END IF;\n    v_description:=COALESCE(NEW.description,'Fixed Asset Purchase');\n    v_total:=NEW.amount+COALESCE(NEW.ppn_amount,0);\n    v_journal_id:=public.upsert_expense_journal_header_in_place(\n      v_journal_id,NEW.id,NEW.expense_date,v_description,'fixed_asset',v_total,NEW.created_by);\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,1,v_expense_account_id,NEW.amount,0,v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=2;\n    IF COALESCE(NEW.ppn_amount,0)>0 THEN\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n      VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.ppn_amount,0,'PPN Masukan - '||v_description,NEW.supplier_id,NEW.payee_id);\n      v_line_num:=v_line_num+1;\n    END IF;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_payment_account_id,0,v_total,v_description,NEW.supplier_id,NEW.payee_id);\n    RETURN NEW;\n  END IF;\n\n  v_expense_account_id:=CASE WHEN public.is_capitalizable_landed_cost_category(NEW.expense_category) THEN (SELECT id FROM public.chart_of_accounts WHERE code='1130' LIMIT 1) ELSE public.get_expense_account_id(NEW.expense_category) END;\n  IF v_expense_account_id IS NULL THEN RAISE EXCEPTION 'No expense account is mapped for %',NEW.expense_category; END IF;\n  v_category_label:=initcap(replace(NEW.expense_category,'_',' '));\n  v_description:=COALESCE(NEW.description,NEW.expense_category);\n  v_credit_desc:=COALESCE(substring(NEW.description FROM '^[^\\\\n]+'),NEW.expense_category)||' ['||v_category_label||']';\n  \n  SELECT id INTO v_ppn_account_id FROM public.chart_of_accounts WHERE code='1150' LIMIT 1;\n  SELECT id INTO v_stamp_duty_account_id FROM public.chart_of_accounts WHERE code='6950' LIMIT 1;\n  IF COALESCE(NEW.ppn_amount,0)>0 AND v_ppn_account_id IS NULL THEN RAISE EXCEPTION 'PPN Masukan account 1150 is missing'; END IF;\n  IF COALESCE(NEW.stamp_duty_amount,0)>0 AND v_stamp_duty_account_id IS NULL THEN RAISE EXCEPTION 'Stamp Duty account 6950 is missing'; END IF;\n\n  -- STRICT ZERO-FALLBACK RESOLUTION FOR WITHHOLDING TAX\n  IF COALESCE(NEW.pph_amount, 0) > 0 THEN\n    IF NEW.pph_code_id IS NULL THEN\n      RAISE EXCEPTION 'Cannot post expense %: Withholding tax amount % exists but pph_code_id is NULL', \n        NEW.id, NEW.pph_amount;\n    END IF;\n\n    v_pph_account_id := public.fn_pph_payable_account_id(NEW.pph_code_id);\n\n    IF v_pph_account_id IS NULL THEN\n      RAISE EXCEPTION 'Cannot post expense %: Tax code % has no valid GL liability account configured', \n        NEW.id, NEW.pph_code_id;\n    END IF;\n  END IF;\n\n  v_bank_charges:=CASE WHEN NEW.expense_category='utilities' THEN COALESCE(NEW.bank_charges_amount,0) ELSE 0 END;\n  IF v_bank_charges>0 THEN\n    v_bank_charge_acc_id:=public.get_expense_account_id('bank_charges');\n    IF v_bank_charge_acc_id IS NULL THEN RAISE EXCEPTION 'Bank Charges account is missing'; END IF;\n  END IF;\n\n  v_net_payment:=NEW.amount+COALESCE(NEW.ppn_amount,0)-COALESCE(NEW.pph_amount,0)+COALESCE(NEW.stamp_duty_amount,0)+v_bank_charges;\n  v_total:=NEW.amount+COALESCE(NEW.ppn_amount,0)+COALESCE(NEW.stamp_duty_amount,0)+v_bank_charges;\n\n  v_journal_id:=public.upsert_expense_journal_header_in_place(\n    v_journal_id,NEW.id,NEW.expense_date,v_description,NEW.expense_category,v_total,NEW.created_by);\n  v_line_num:=1;\n\n  -- 1. Debit Expense\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n  VALUES(v_journal_id,v_line_num,v_expense_account_id,NEW.amount,0,v_credit_desc,NEW.supplier_id,NEW.payee_id);\n  v_line_num:=v_line_num+1;\n\n  -- 2. Debit PPN Masukan\n  IF COALESCE(NEW.ppn_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_ppn_account_id,NEW.ppn_amount,0,'PPN Masukan - '||v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  -- 3. Debit Stamp Duty\n  IF COALESCE(NEW.stamp_duty_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_stamp_duty_account_id,NEW.stamp_duty_amount,0,'Bea Meterai - '||v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  -- 4. Debit Bank Charges\n  IF v_bank_charges>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_bank_charge_acc_id,v_bank_charges,0,'Bank charges ['||v_category_label||']',NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  -- 5. Credit PPh Ditahan\n  IF COALESCE(NEW.pph_amount,0)>0 THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n    VALUES(v_journal_id,v_line_num,v_pph_account_id,0,NEW.pph_amount,'PPh Ditahan - '||v_description,NEW.supplier_id,NEW.payee_id);\n    v_line_num:=v_line_num+1;\n  END IF;\n\n  -- 6. Credit Payment / AP Account\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,payee_id)\n  VALUES(v_journal_id,v_line_num,v_payment_account_id,0,v_net_payment,v_credit_desc,NEW.supplier_id,NEW.payee_id);\n\n  RETURN NEW;\nEND;\n$function$",COMMIT}	repair_auto_post_expense_payment_resolution	\N	\N	\N
20260909111500	{"-- Migration: 20260909111500_add_document_urls_to_finance_payees.sql\n-- Description: Add document_urls TEXT[] column to public.finance_payees for KTP, NPWP, and KYC document uploads.\n\nBEGIN","ALTER TABLE public.finance_payees\n  ADD COLUMN IF NOT EXISTS document_urls TEXT[] NOT NULL DEFAULT '{}'::text[]",COMMIT}	add_document_urls_to_finance_payees	\N	\N	\N
20260909112500	{"-- Migration: 20260909112500_fix_sales_invoice_update_cogs_fk_conflict.sql\n-- Description: Fix foreign key conflict when updating sales invoices.\n--              1. Alter journal_entry_lines_sales_invoice_item_id_fkey to ON DELETE SET NULL\n--                 so item deletion is never blocked.\n--              2. Update update_sales_invoice_atomic() to also delete the old COGS journal entry\n--                 along with the revenue journal entry, so COGS is cleanly regenerated for new items.\n\nBEGIN","-- 1. Relax foreign key constraint to ON DELETE SET NULL\nALTER TABLE public.journal_entry_lines\n  DROP CONSTRAINT IF EXISTS journal_entry_lines_sales_invoice_item_id_fkey,\n  ADD CONSTRAINT journal_entry_lines_sales_invoice_item_id_fkey\n    FOREIGN KEY (sales_invoice_item_id)\n    REFERENCES public.sales_invoice_items(id)\n    ON DELETE SET NULL","-- 2. Update update_sales_invoice_atomic to clean up COGS journal before deleting items\nCREATE OR REPLACE FUNCTION public.update_sales_invoice_atomic(\n  p_invoice_id uuid,\n  p_invoice_updates jsonb,\n  p_new_items jsonb[]\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_role text;\n  v_old_je_id uuid;\n  v_result uuid;\n  v_dc_item_ids uuid[];\n  v_linked_challan_ids text[];\n  v_sales_order_ids uuid[];\n  v_customer_ids uuid[];\nBEGIN\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts', 'sales', 'manager') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot update sales invoices', v_role;\n  END IF;\n\n  SELECT array_agg(DISTINCT NULLIF(item->>'delivery_challan_item_id', '')::uuid)\n  INTO v_dc_item_ids\n  FROM unnest(p_new_items) AS item;\n\n  IF v_dc_item_ids IS NULL OR cardinality(v_dc_item_ids) = 0 THEN\n    RAISE EXCEPTION 'Sales Invoice must contain Delivery Challan-linked items';\n  END IF;\n\n  IF array_length(v_dc_item_ids, 1) <> (\n    SELECT count(*) FROM public.delivery_challan_items WHERE id = ANY(v_dc_item_ids)\n  ) THEN\n    RAISE EXCEPTION 'Sales Invoice contains a missing Delivery Challan item';\n  END IF;\n\n  SELECT\n    array_agg(DISTINCT dc.id::text ORDER BY dc.id::text),\n    array_agg(DISTINCT dc.sales_order_id),\n    array_agg(DISTINCT dc.customer_id)\n  INTO v_linked_challan_ids, v_sales_order_ids, v_customer_ids\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  WHERE dci.id = ANY(v_dc_item_ids);\n\n  IF cardinality(v_customer_ids) <> 1\n     OR (p_invoice_updates ? 'customer_id'\n         AND (p_invoice_updates->>'customer_id')::uuid IS DISTINCT FROM v_customer_ids[1]) THEN\n    RAISE EXCEPTION 'Invoice customer must match all linked Delivery Challans';\n  END IF;\n\n  SELECT journal_entry_id INTO v_old_je_id\n  FROM public.sales_invoices\n  WHERE id = p_invoice_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Invoice % not found', p_invoice_id;\n  END IF;\n\n  -- Remove old revenue journal entry\n  IF v_old_je_id IS NOT NULL THEN\n    UPDATE public.sales_invoices SET journal_entry_id = NULL WHERE id = p_invoice_id;\n    DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_old_je_id;\n    DELETE FROM public.journal_entries WHERE id = v_old_je_id;\n  END IF;\n\n  -- Remove old COGS journal entry so COGS is cleanly regenerated for updated items\n  DELETE FROM public.journal_entry_lines\n   WHERE journal_entry_id IN (\n     SELECT id FROM public.journal_entries\n      WHERE source_module = 'sales_invoice_cogs' AND reference_id = p_invoice_id\n   );\n  DELETE FROM public.journal_entries\n   WHERE source_module = 'sales_invoice_cogs' AND reference_id = p_invoice_id;\n\n  -- Delete old sales invoice items\n  DELETE FROM public.sales_invoice_items WHERE invoice_id = p_invoice_id;\n  PERFORM set_config('app.sales_invoice_rebuild', 'true', true);\n\n  UPDATE public.sales_invoices\n  SET\n    invoice_date       = COALESCE((p_invoice_updates->>'invoice_date')::date, invoice_date),\n    due_date           = COALESCE((p_invoice_updates->>'due_date')::date, due_date),\n    customer_id        = v_customer_ids[1],\n    sales_order_id     = CASE WHEN cardinality(v_sales_order_ids) = 1 THEN v_sales_order_ids[1] ELSE NULL END,\n    subtotal           = COALESCE((p_invoice_updates->>'subtotal')::numeric, subtotal),\n    tax_amount         = COALESCE((p_invoice_updates->>'tax_amount')::numeric, tax_amount),\n    total_amount       = COALESCE((p_invoice_updates->>'total_amount')::numeric, total_amount),\n    discount_amount    = COALESCE((p_invoice_updates->>'discount_amount')::numeric, discount_amount),\n    stamp_duty_amount  = COALESCE((p_invoice_updates->>'stamp_duty_amount')::numeric, stamp_duty_amount),\n    po_number          = COALESCE(p_invoice_updates->>'po_number', po_number),\n    payment_terms_days = COALESCE((p_invoice_updates->>'payment_terms_days')::integer, payment_terms_days),\n    notes              = COALESCE(p_invoice_updates->>'notes', notes),\n    linked_challan_ids = v_linked_challan_ids,\n    updated_at         = now()\n  WHERE id = p_invoice_id\n  RETURNING id INTO v_result;\n\n  INSERT INTO public.sales_invoice_items (\n    invoice_id, product_id, batch_id, quantity, unit_price, tax_rate, delivery_challan_item_id\n  )\n  SELECT\n    p_invoice_id,\n    (item->>'product_id')::uuid,\n    NULLIF(item->>'batch_id', '')::uuid,\n    (item->>'quantity')::numeric,\n    (item->>'unit_price')::numeric,\n    (item->>'tax_rate')::numeric,\n    NULLIF(item->>'delivery_challan_item_id', '')::uuid\n  FROM unnest(p_new_items) AS item;\n\n  PERFORM set_config('app.sales_invoice_rebuild', 'false', true);\n  UPDATE public.sales_invoices SET updated_at = now()\n  WHERE id = p_invoice_id AND journal_entry_id IS NULL;\n\n  RETURN v_result;\nEND;\n$function$",COMMIT}	fix_sales_invoice_update_cogs_fk_conflict	\N	\N	\N
20260909113500	{"-- Migration: 20260909113500_add_document_urls_to_finance_staff_master.sql\n-- Description: Add document_urls TEXT[] column to public.finance_staff_master for KTP, NPWP, contracts, and HR/KYC document uploads.\n\nBEGIN","ALTER TABLE public.finance_staff_master\n  ADD COLUMN IF NOT EXISTS document_urls TEXT[] NOT NULL DEFAULT '{}'::text[]",COMMIT}	add_document_urls_to_finance_staff_master	\N	\N	\N
20260909114500	{"-- Migration: 20260909114500_add_nik_to_finance_staff_master.sql\n-- Description: Add nik (Nomor Induk Kependudukan / Citizen ID) to public.finance_staff_master for PPh 21 tax withholding and e-Bupot reporting.\n\nBEGIN","ALTER TABLE public.finance_staff_master\n  ADD COLUMN IF NOT EXISTS nik TEXT","COMMENT ON COLUMN public.finance_staff_master.nik IS 'Indonesian 16-digit Citizen ID (NIK / KTP) for PPh 21 tax withholding returns'",COMMIT}	add_nik_to_finance_staff_master	\N	\N	\N
20260909121500	{"-- ============================================================================\n-- Fix Fund Transfer to Petty Cash Withdrawal & Category Assignment Bug\n-- ============================================================================\n-- Problem:\n-- 1. When creating a Fund Transfer with to_account_type = 'petty_cash',\n--    the deferred constraint trigger `trg_validate_petty_cash_transfer_commit`\n--    checks that a matching row exists in `petty_cash_transactions(fund_transfer_id)`.\n-- 2. However, `create_fund_transfer_with_posting` was missing the INSERT into\n--    `petty_cash_transactions`.\n-- 3. Furthermore, the trigger `trg_validate_petty_cash_category_assignment`\n--    enforced that `expense_category` must not be null on all rows in\n--    `petty_cash_transactions`, failing on `transaction_type = 'withdraw'`\n--    (since a cash replenishment/withdrawal into the petty cash box is not an expense).\n--\n-- Solution:\n-- 1. Exempt `transaction_type = 'withdraw'` in `validate_expense_category_assignment()`.\n-- 2. Restore the canonical `INSERT INTO public.petty_cash_transactions` in\n--    `create_fund_transfer_with_posting()`.\n-- ============================================================================\n\nBEGIN","-- 1. Update validate_expense_category_assignment to skip 'withdraw' transactions\nCREATE OR REPLACE FUNCTION public.validate_expense_category_assignment()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_category public.expense_categories%ROWTYPE;\n  v_coa public.chart_of_accounts%ROWTYPE;\nBEGIN\n  -- A petty cash withdrawal is a cash replenishment/transfer, not an expense\n  IF TG_TABLE_NAME = 'petty_cash_transactions' AND (to_jsonb(NEW) ->> 'transaction_type') = 'withdraw' THEN\n    RETURN NEW;\n  END IF;\n\n  IF TG_OP = 'UPDATE'\n     AND OLD.expense_category = 'utilities'\n     AND NEW.expense_category = 'utilities' THEN\n    RETURN NEW;\n  END IF;\n\n  IF NULLIF(btrim(NEW.expense_category), '') IS NULL THEN\n    RAISE EXCEPTION 'Expense category is required.' USING ERRCODE = '23514';\n  END IF;\n\n  SELECT * INTO v_category\n    FROM public.expense_categories\n   WHERE category_key = NEW.expense_category;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" does not exist in Expense Category Master.',\n      NEW.expense_category USING ERRCODE = '23514';\n  END IF;\n  IF NOT v_category.is_active THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" is inactive.', v_category.name\n      USING ERRCODE = '23514';\n  END IF;\n  IF NOT v_category.is_posting_category THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" is a grouping category. Select an active posting leaf.',\n      v_category.name USING ERRCODE = '23514';\n  END IF;\n  IF v_category.coa_account_id IS NULL THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" has no configured Chart of Account.',\n      v_category.name USING ERRCODE = '23514';\n  END IF;\n\n  SELECT * INTO v_coa\n    FROM public.chart_of_accounts\n   WHERE id = v_category.coa_account_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" references a missing Chart of Account.',\n      v_category.name USING ERRCODE = '23514';\n  END IF;\n  IF NOT v_coa.is_active OR v_coa.is_header THEN\n    RAISE EXCEPTION 'Expense category \\"%\\" must use an active non-header Chart of Account.',\n      v_category.name USING ERRCODE = '23514';\n  END IF;\n\n  RETURN NEW;\nEND;\n$function$","-- 2. Update create_fund_transfer_with_posting to create the canonical petty cash withdrawal\nCREATE OR REPLACE FUNCTION public.create_fund_transfer_with_posting(\n  p_transfer_date date,\n  p_from_amount numeric,\n  p_to_amount numeric,\n  p_from_account_type text,\n  p_to_account_type text,\n  p_description text DEFAULT NULL::text,\n  p_from_bank_account_id uuid DEFAULT NULL::uuid,\n  p_to_bank_account_id uuid DEFAULT NULL::uuid,\n  p_from_bank_statement_line_id uuid DEFAULT NULL::uuid,\n  p_to_bank_statement_line_id uuid DEFAULT NULL::uuid,\n  p_exchange_rate numeric DEFAULT NULL::numeric,\n  p_created_by uuid DEFAULT NULL::uuid\n) RETURNS fund_transfers\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  v_user_id uuid;\n  v_transfer_number text;\n  v_transfer public.fund_transfers;\n  v_source_account_name text;\nBEGIN\n  v_user_id := COALESCE(p_created_by, auth.uid());\n  IF v_user_id IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  v_transfer_number := public.generate_fund_transfer_number();\n\n  INSERT INTO public.fund_transfers (\n    transfer_number,\n    transfer_date,\n    amount,\n    from_amount,\n    to_amount,\n    exchange_rate,\n    from_account_type,\n    to_account_type,\n    from_bank_account_id,\n    to_bank_account_id,\n    from_bank_statement_line_id,\n    to_bank_statement_line_id,\n    description,\n    created_by\n  ) VALUES (\n    v_transfer_number,\n    p_transfer_date,\n    p_from_amount,\n    p_from_amount,\n    p_to_amount,\n    p_exchange_rate,\n    p_from_account_type,\n    p_to_account_type,\n    CASE WHEN p_from_account_type = 'bank' THEN p_from_bank_account_id ELSE NULL END,\n    CASE WHEN p_to_account_type = 'bank' THEN p_to_bank_account_id ELSE NULL END,\n    p_from_bank_statement_line_id,\n    p_to_bank_statement_line_id,\n    NULLIF(p_description, ''),\n    v_user_id\n  )\n  RETURNING * INTO v_transfer;\n\n  IF v_transfer.to_account_type = 'petty_cash' THEN\n    IF v_transfer.from_account_type = 'bank' THEN\n      SELECT COALESCE(ba.alias, ba.bank_name, 'Bank')\n        INTO v_source_account_name\n      FROM public.bank_accounts ba\n      WHERE ba.id = v_transfer.from_bank_account_id;\n    ELSE\n      v_source_account_name := 'Cash on Hand';\n    END IF;\n\n    INSERT INTO public.petty_cash_transactions (\n      transaction_date,\n      transaction_type,\n      amount,\n      description,\n      bank_account_id,\n      bank_statement_line_id,\n      source,\n      fund_transfer_id,\n      approval_status,\n      created_by\n    ) VALUES (\n      v_transfer.transfer_date,\n      'withdraw',\n      v_transfer.to_amount,\n      COALESCE(v_transfer.description, 'Fund transfer from ' || COALESCE(v_source_account_name, 'Bank')),\n      v_transfer.from_bank_account_id,\n      v_transfer.from_bank_statement_line_id,\n      'Fund Transfer ' || v_transfer.transfer_number,\n      v_transfer.id,\n      'approved',\n      v_user_id\n    )\n    ON CONFLICT (fund_transfer_id) WHERE fund_transfer_id IS NOT NULL DO NOTHING;\n  END IF;\n\n  RETURN v_transfer;\nEND;\n$$","NOTIFY pgrst, 'reload schema'",COMMIT}	fix_fund_transfer_petty_cash_withdrawal	\N	\N	\N
20260909153000	{"-- Migration: 20260909153000_optimize_expense_bank_allocation_triggers.sql\n-- Description: Optimize expense and bank allocation triggers to eliminate recursive ping-pong cascading\n--              and redundant full-register tax recalculations that caused statement timeouts.\n\nBEGIN","-- 1. Guard recalculate_expense_payment_state: only write to finance_expenses when values actually change\nCREATE OR REPLACE FUNCTION public.recalculate_expense_payment_state(p_expense_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_supplier_paid numeric := 0;\n  v_pph_paid numeric := 0;\n  v_payable numeric := 0;\n  v_target_paid numeric;\n  v_target_pph_paid numeric;\nBEGIN\n  IF public.historical_repair_context_active() THEN RETURN; END IF;\n\n  SELECT COALESCE(sum(va.allocated_amount),0) INTO v_supplier_paid\n    FROM public.voucher_allocations va\n    LEFT JOIN public.payment_vouchers pv ON pv.id=va.payment_voucher_id\n   WHERE va.finance_expense_id=p_expense_id\n     AND COALESCE(va.payment_kind,'supplier')='supplier'\n     AND COALESCE(pv.payment_purpose,'general') NOT IN ('salary_advance','salary_advance_settlement');\n  SELECT v_supplier_paid+COALESCE(sum(allocation_amount),0) INTO v_supplier_paid\n    FROM public.bank_statement_allocations\n   WHERE document_type='expense' AND document_id=p_expense_id\n     AND COALESCE(payment_kind,'supplier')='supplier';\n  SELECT v_supplier_paid+COALESCE(sum(COALESCE(NULLIF(b.debit_amount,0),b.credit_amount,0)),0) INTO v_supplier_paid\n    FROM public.bank_statement_lines b\n   WHERE b.matched_expense_id=p_expense_id AND b.payment_kind='supplier'\n     AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id=b.id);\n  SELECT COALESCE(sum(allocated_amount),0) INTO v_pph_paid\n    FROM public.voucher_allocations\n   WHERE finance_expense_id=p_expense_id AND payment_kind='pph23';\n  SELECT v_pph_paid+COALESCE(sum(allocation_amount),0) INTO v_pph_paid\n    FROM public.bank_statement_allocations\n   WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind='pph23';\n\n  v_payable := COALESCE(public.calculate_finance_expense_payable(p_expense_id),0);\n  v_target_paid := LEAST(GREATEST(v_supplier_paid,0),GREATEST(v_payable,0));\n  v_target_pph_paid := GREATEST(v_pph_paid,0);\n\n  UPDATE public.finance_expenses\n     SET paid_amount=v_target_paid,\n         pph_paid_amount=v_target_pph_paid\n   WHERE id=p_expense_id\n     AND (paid_amount IS DISTINCT FROM v_target_paid OR pph_paid_amount IS DISTINCT FROM v_target_pph_paid);\nEND;\n$function$","-- 2. Guard trg_recompute_from_expense: only recompute tax periods when tax-relevant fields change\nCREATE OR REPLACE FUNCTION public.trg_recompute_from_expense()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF COALESCE(OLD.pph_amount, 0) > 0\n       OR COALESCE(OLD.pib_pph_amount, 0) > 0\n       OR OLD.expense_category = 'pph_import' THEN\n      PERFORM public.recompute_pph_periods_for_date(COALESCE(OLD.due_date, OLD.expense_date));\n    END IF;\n  ELSIF TG_OP = 'INSERT' THEN\n    IF COALESCE(NEW.pph_amount, 0) > 0\n       OR COALESCE(NEW.pib_pph_amount, 0) > 0\n       OR NEW.expense_category = 'pph_import' THEN\n      PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(NEW.id));\n    END IF;\n  ELSIF TG_OP = 'UPDATE' THEN\n    IF (\n      NEW.pph_amount IS DISTINCT FROM OLD.pph_amount OR\n      NEW.pib_pph_amount IS DISTINCT FROM OLD.pib_pph_amount OR\n      NEW.ppn_amount IS DISTINCT FROM OLD.ppn_amount OR\n      NEW.pib_ppn_amount IS DISTINCT FROM OLD.pib_ppn_amount OR\n      NEW.expense_date IS DISTINCT FROM OLD.expense_date OR\n      NEW.due_date IS DISTINCT FROM OLD.due_date OR\n      NEW.expense_category IS DISTINCT FROM OLD.expense_category OR\n      NEW.approval_status IS DISTINCT FROM OLD.approval_status OR\n      NEW.pph_code_id IS DISTINCT FROM OLD.pph_code_id\n    ) THEN\n      IF COALESCE(NEW.pph_amount, 0) > 0\n         OR COALESCE(NEW.pib_pph_amount, 0) > 0\n         OR NEW.expense_category = 'pph_import' THEN\n        PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(NEW.id));\n      END IF;\n      IF COALESCE(OLD.pph_amount, 0) > 0\n         OR COALESCE(OLD.pib_pph_amount, 0) > 0\n         OR OLD.expense_category = 'pph_import' THEN\n        PERFORM public.recompute_pph_periods_for_date(COALESCE(OLD.due_date, OLD.expense_date));\n        IF OLD.expense_date IS DISTINCT FROM NEW.expense_date THEN\n          PERFORM public.recompute_pph_periods_for_date(OLD.expense_date);\n        END IF;\n      END IF;\n    END IF;\n  END IF;\n  RETURN NULL;\nEND;\n$function$","-- 3. Guard trg_recompute_pph_from_bank_line: avoid recomputing if line owner/date didn't change\nCREATE OR REPLACE FUNCTION public.trg_recompute_pph_from_bank_line()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_expense_id uuid;\n  v_date date;\nBEGIN\n  IF TG_OP = 'UPDATE' THEN\n    IF OLD.matched_expense_id IS NOT DISTINCT FROM NEW.matched_expense_id\n       AND OLD.transaction_date IS NOT DISTINCT FROM NEW.transaction_date\n       AND OLD.payment_kind IS NOT DISTINCT FROM NEW.payment_kind THEN\n      RETURN NULL;\n    END IF;\n  END IF;\n\n  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.matched_expense_id IS NOT NULL THEN\n    v_expense_id := OLD.matched_expense_id;\n    PERFORM 1 FROM public.finance_expenses fe\n    WHERE fe.id = v_expense_id\n      AND (COALESCE(fe.pph_amount, 0) > 0 OR COALESCE(fe.pib_pph_amount, 0) > 0 OR fe.expense_category = 'pph_import');\n    IF NOT FOUND THEN\n      v_expense_id := NULL;\n    END IF;\n  END IF;\n  IF TG_OP IN ('UPDATE', 'DELETE') AND v_expense_id IS NOT NULL THEN\n    PERFORM public.recompute_pph_periods_for_date(OLD.transaction_date);\n    PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_expense_id));\n    SELECT COALESCE(due_date, expense_date) INTO v_date FROM public.finance_expenses WHERE id = v_expense_id;\n    PERFORM public.recompute_pph_periods_for_date(v_date);\n  END IF;\n\n  v_expense_id := NULL;\n  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.matched_expense_id IS NOT NULL THEN\n    v_expense_id := NEW.matched_expense_id;\n    PERFORM 1 FROM public.finance_expenses fe\n    WHERE fe.id = v_expense_id\n      AND (COALESCE(fe.pph_amount, 0) > 0 OR COALESCE(fe.pib_pph_amount, 0) > 0 OR fe.expense_category = 'pph_import');\n    IF NOT FOUND THEN\n      v_expense_id := NULL;\n    END IF;\n  END IF;\n  IF TG_OP IN ('INSERT', 'UPDATE') AND v_expense_id IS NOT NULL THEN\n    PERFORM public.recompute_pph_periods_for_date(NEW.transaction_date);\n    PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(v_expense_id));\n    SELECT COALESCE(due_date, expense_date) INTO v_date FROM public.finance_expenses WHERE id = v_expense_id;\n    PERFORM public.recompute_pph_periods_for_date(v_date);\n  END IF;\n  RETURN NULL;\nEND;\n$function$","-- 4. Guard sync_bank_line_allocation_owner: avoid writing to bank_statement_lines when fields match\nCREATE OR REPLACE FUNCTION public.sync_bank_line_allocation_owner(p_bank_line_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_count integer;\n  v_only public.bank_statement_allocations%ROWTYPE;\n  v_target_expense_id uuid;\n  v_target_receipt_id uuid;\n  v_target_payment_id uuid;\n  v_target_ft_id uuid;\n  v_target_pc_id uuid;\n  v_target_tax_id uuid;\n  v_target_entry_id uuid;\n  v_target_kind text;\nBEGIN\n  SELECT count(*) INTO v_count\n    FROM public.bank_statement_allocations\n   WHERE bank_statement_line_id = p_bank_line_id;\n\n  IF v_count = 1 THEN\n    SELECT * INTO v_only\n      FROM public.bank_statement_allocations\n     WHERE bank_statement_line_id = p_bank_line_id;\n\n    v_target_expense_id := CASE \n        WHEN v_only.document_type = 'expense' \n          AND NOT EXISTS (\n            SELECT 1 FROM public.bank_statement_lines b \n            WHERE b.matched_expense_id = v_only.document_id \n              AND b.matching_status = 'confirmed' \n              AND b.id <> p_bank_line_id\n          ) \n        THEN v_only.document_id \n      END;\n    v_target_receipt_id := CASE WHEN v_only.document_type = 'receipt' THEN v_only.document_id END;\n    v_target_payment_id := CASE WHEN v_only.document_type = 'payment' THEN v_only.document_id END;\n    v_target_ft_id := CASE WHEN v_only.document_type = 'fund_transfer' THEN v_only.document_id END;\n    v_target_pc_id := CASE WHEN v_only.document_type = 'petty_cash' THEN v_only.document_id END;\n    v_target_tax_id := CASE WHEN v_only.document_type = 'tax_payment' THEN v_only.document_id END;\n    v_target_entry_id := v_only.journal_entry_id;\n    v_target_kind := COALESCE(v_only.payment_kind, 'supplier');\n\n    UPDATE public.bank_statement_lines SET\n      matched_expense_id = v_target_expense_id,\n      matched_receipt_id = v_target_receipt_id,\n      matched_payment_id = v_target_payment_id,\n      matched_fund_transfer_id = v_target_ft_id,\n      matched_petty_cash_id = v_target_pc_id,\n      matched_tax_payment_id = v_target_tax_id,\n      matched_entry_id = v_target_entry_id,\n      payment_kind = v_target_kind\n    WHERE id = p_bank_line_id\n      AND (\n        matched_expense_id IS DISTINCT FROM v_target_expense_id OR\n        matched_receipt_id IS DISTINCT FROM v_target_receipt_id OR\n        matched_payment_id IS DISTINCT FROM v_target_payment_id OR\n        matched_fund_transfer_id IS DISTINCT FROM v_target_ft_id OR\n        matched_petty_cash_id IS DISTINCT FROM v_target_pc_id OR\n        matched_tax_payment_id IS DISTINCT FROM v_target_tax_id OR\n        matched_entry_id IS DISTINCT FROM v_target_entry_id OR\n        payment_kind IS DISTINCT FROM v_target_kind\n      );\n  ELSE\n    UPDATE public.bank_statement_lines SET\n      matched_expense_id = NULL,\n      matched_receipt_id = NULL,\n      matched_payment_id = NULL,\n      matched_fund_transfer_id = NULL,\n      matched_petty_cash_id = NULL,\n      matched_tax_payment_id = NULL,\n      matched_entry_id = NULL\n    WHERE id = p_bank_line_id\n      AND (\n        matched_expense_id IS NOT NULL OR\n        matched_receipt_id IS NOT NULL OR\n        matched_payment_id IS NOT NULL OR\n        matched_fund_transfer_id IS NOT NULL OR\n        matched_petty_cash_id IS NOT NULL OR\n        matched_tax_payment_id IS NOT NULL OR\n        matched_entry_id IS NOT NULL\n      );\n  END IF;\nEND;\n$function$","-- 5. Optimize sync_bank_line_from_allocation: eliminate duplicate recalculate_expense_payment_state\nCREATE OR REPLACE FUNCTION public.sync_bank_line_from_allocation()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_old_line uuid;\n  v_new_line uuid;\nBEGIN\n  IF TG_OP IN ('UPDATE', 'DELETE') THEN\n    v_old_line := OLD.bank_statement_line_id;\n    PERFORM public.sync_bank_line_allocation_owner(v_old_line);\n    PERFORM public.refresh_bank_statement_allocation_status(v_old_line);\n    IF NOT public.historical_repair_context_active() THEN\n      IF OLD.document_type = 'tax_payment' THEN\n        UPDATE public.tax_payments SET status = 'posted' WHERE id = OLD.document_id\n          AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations WHERE document_type = 'tax_payment' AND document_id = OLD.document_id);\n      END IF;\n    END IF;\n  END IF;\n  IF TG_OP IN ('INSERT', 'UPDATE') THEN\n    v_new_line := NEW.bank_statement_line_id;\n    IF v_new_line IS DISTINCT FROM v_old_line THEN\n      PERFORM public.sync_bank_line_allocation_owner(v_new_line);\n      PERFORM public.refresh_bank_statement_allocation_status(v_new_line);\n    END IF;\n    IF NOT public.historical_repair_context_active() THEN\n      IF NEW.document_type = 'tax_payment' THEN\n        UPDATE public.tax_payments SET status = 'reconciled' WHERE id = NEW.document_id;\n      END IF;\n    END IF;\n  END IF;\n  RETURN COALESCE(NEW, OLD);\nEND;\n$function$","-- 6. Optimize sync_expense_from_bank_allocation: avoid redundant recomputations of identical dates\nCREATE OR REPLACE FUNCTION public.sync_expense_from_bank_allocation()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_old_expense uuid;\n  v_new_expense uuid;\n  v_old_date date;\n  v_new_date date;\n  v_fallback date;\n  v_exp_date date;\nBEGIN\n  IF public.historical_repair_context_active() THEN RETURN COALESCE(NEW, OLD); END IF;\n  IF TG_OP IN ('UPDATE','DELETE') AND OLD.document_type='expense' THEN\n    v_old_expense:=OLD.document_id;\n    SELECT transaction_date INTO v_old_date FROM public.bank_statement_lines WHERE id=OLD.bank_statement_line_id;\n    PERFORM public.recalculate_expense_payment_state(v_old_expense);\n    IF EXISTS(SELECT 1 FROM public.finance_expenses WHERE id=v_old_expense AND (COALESCE(pph_amount,0)>0 OR COALESCE(pib_pph_amount,0)>0 OR expense_category='pph_import')) THEN\n      IF v_old_date IS NOT NULL THEN\n        PERFORM public.recompute_pph_periods_for_date(v_old_date);\n      END IF;\n      v_exp_date := public.get_expense_pph_period_date(v_old_expense);\n      IF v_exp_date IS NOT NULL AND v_exp_date IS DISTINCT FROM v_old_date THEN\n        PERFORM public.recompute_pph_periods_for_date(v_exp_date);\n      END IF;\n      SELECT COALESCE(due_date,expense_date) INTO v_fallback FROM public.finance_expenses WHERE id=v_old_expense;\n      IF v_fallback IS NOT NULL AND v_fallback IS DISTINCT FROM v_old_date AND v_fallback IS DISTINCT FROM v_exp_date THEN\n        PERFORM public.recompute_pph_periods_for_date(v_fallback);\n      END IF;\n    END IF;\n  END IF;\n  IF TG_OP IN ('INSERT','UPDATE') AND NEW.document_type='expense' THEN\n    v_new_expense:=NEW.document_id;\n    SELECT transaction_date INTO v_new_date FROM public.bank_statement_lines WHERE id=NEW.bank_statement_line_id;\n    PERFORM public.recalculate_expense_payment_state(v_new_expense);\n    IF EXISTS(SELECT 1 FROM public.finance_expenses WHERE id=v_new_expense AND (COALESCE(pph_amount,0)>0 OR COALESCE(pib_pph_amount,0)>0 OR expense_category='pph_import')) THEN\n      IF v_new_date IS NOT NULL THEN\n        PERFORM public.recompute_pph_periods_for_date(v_new_date);\n      END IF;\n      v_exp_date := public.get_expense_pph_period_date(v_new_expense);\n      IF v_exp_date IS NOT NULL AND v_exp_date IS DISTINCT FROM v_new_date THEN\n        PERFORM public.recompute_pph_periods_for_date(v_exp_date);\n      END IF;\n      SELECT COALESCE(due_date,expense_date) INTO v_fallback FROM public.finance_expenses WHERE id=v_new_expense;\n      IF v_fallback IS NOT NULL AND v_fallback IS DISTINCT FROM v_new_date AND v_fallback IS DISTINCT FROM v_exp_date THEN\n        PERFORM public.recompute_pph_periods_for_date(v_fallback);\n      END IF;\n    END IF;\n  END IF;\n  RETURN COALESCE(NEW,OLD);\nEND;\n$function$","-- 7. Optimize edit_approved_finance_expense_atomic: remove no-op bank allocation touch\nCREATE OR REPLACE FUNCTION public.edit_approved_finance_expense_atomic(\n  p_expense_id uuid,\n  p_payload jsonb,\n  p_bank_statement_line_id uuid DEFAULT NULL::uuid,\n  p_allocation_amount numeric DEFAULT NULL::numeric\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_exp public.finance_expenses%rowtype;\n  v_journal_id uuid;\n  v_journal_count integer;\n  v_date date;\n  v_bank_id uuid;\n  v_bank_currency text;\n  v_currency text;\n  v_rate numeric;\n  v_docs text[];\n  v_same_selected_count integer;\n  v_selected_amount numeric;\n  v_period_status text;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  SELECT * INTO v_exp FROM public.finance_expenses WHERE id=p_expense_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\n  IF v_exp.approval_status<>'approved' THEN RAISE EXCEPTION 'Approved expense edit requires an approved expense'; END IF;\n\n  SELECT count(*),(array_agg(id ORDER BY created_at DESC,id DESC))[1]\n    INTO v_journal_count,v_journal_id\n    FROM public.journal_entries\n   WHERE source_module IN('expense','expenses')\n     AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n     AND is_posted=true AND NOT COALESCE(is_reversed,false);\n  IF v_journal_count<>1 THEN RAISE EXCEPTION 'Approved expense must have exactly one active effective journal'; END IF;\n  PERFORM 1 FROM public.journal_entries WHERE id=v_journal_id FOR UPDATE;\n\n  SELECT ap.status INTO v_period_status\n    FROM public.journal_entries je\n    LEFT JOIN public.accounting_periods ap\n      ON ap.start_date<=je.entry_date AND ap.end_date>=je.entry_date\n   WHERE je.id=v_journal_id\n   ORDER BY ap.start_date DESC LIMIT 1;\n  IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN\n    RAISE EXCEPTION 'Cannot edit approved expense in a closed accounting period';\n  END IF;\n\n  IF COALESCE((p_payload->>'amount')::numeric,0)<=0 THEN RAISE EXCEPTION 'Expense amount must be greater than zero'; END IF;\n  IF NULLIF(p_payload->>'expense_category','') IS NULL THEN RAISE EXCEPTION 'Expense category is required'; END IF;\n  v_date:=COALESCE((p_payload->>'expense_date')::date,current_date);\n  v_bank_id:=NULLIF(p_payload->>'bank_account_id','')::uuid;\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id=v_bank_id;\n  v_currency:=upper(COALESCE(NULLIF(p_payload->>'transaction_currency',''),v_bank_currency,'IDR'));\n  v_rate:=COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric,0),CASE WHEN v_currency='IDR' THEN 1 END);\n  IF v_currency NOT IN('IDR','USD') OR v_rate IS NULL OR v_rate<=0 THEN RAISE EXCEPTION 'Valid expense currency/rate is required'; END IF;\n  IF v_bank_currency IS NOT NULL AND v_bank_currency<>v_currency THEN RAISE EXCEPTION 'Expense currency does not match selected bank currency'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IS NOT NULL\n     AND NULLIF(p_payload->>'payment_method','') NOT IN('cash','petty_cash')\n     AND v_bank_id IS NULL THEN RAISE EXCEPTION 'Bank-paid expense requires a bank account'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IN('cash','petty_cash')\n     AND p_bank_statement_line_id IS NOT NULL THEN RAISE EXCEPTION 'Cash/petty-cash expense cannot create a bank allocation'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IS NULL AND p_bank_statement_line_id IS NOT NULL THEN RAISE EXCEPTION 'Accrued expense cannot create a bank allocation'; END IF;\n  SELECT ap.status INTO v_period_status\n    FROM public.accounting_periods ap\n   WHERE ap.start_date<=v_date AND ap.end_date>=v_date\n   ORDER BY ap.start_date DESC LIMIT 1;\n  IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN\n    RAISE EXCEPTION 'Cannot move approved expense into a closed accounting period';\n  END IF;\n  SELECT COALESCE(array_agg(value),ARRAY[]::text[]) INTO v_docs\n    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls','[]'::jsonb));\n\n  PERFORM set_config('app.expense_atomic_bank_link','on',true);\n\n  UPDATE public.finance_expenses SET\n    expense_category=p_payload->>'expense_category',expense_type=COALESCE(NULLIF(p_payload->>'expense_type',''),'admin'),\n    amount=(p_payload->>'amount')::numeric,expense_date=v_date,description=NULLIF(p_payload->>'description',''),\n    batch_id=NULLIF(p_payload->>'batch_id','')::uuid,import_container_id=NULLIF(p_payload->>'import_container_id','')::uuid,\n    delivery_challan_id=NULLIF(p_payload->>'delivery_challan_id','')::uuid,\n    payment_method=NULLIF(p_payload->>'payment_method',''),bank_account_id=v_bank_id,\n    payment_reference=NULLIF(p_payload->>'payment_reference',''),paid_by=NULLIF(p_payload->>'paid_by',''),\n    document_urls=NULLIF(v_docs,ARRAY[]::text[]),supplier_id=NULLIF(p_payload->>'supplier_id','')::uuid,\n    staff_id=NULLIF(p_payload->>'staff_id','')::uuid,invoice_number=NULLIF(p_payload->>'invoice_number',''),\n    due_date=NULLIF(p_payload->>'due_date','')::date,broker_items=NULLIF(p_payload->'broker_items','null'::jsonb),\n    pib_bm_amount=NULLIF(p_payload->>'pib_bm_amount','')::numeric,pib_ppn_amount=NULLIF(p_payload->>'pib_ppn_amount','')::numeric,\n    pib_pph_amount=NULLIF(p_payload->>'pib_pph_amount','')::numeric,ppn_amount=COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0),\n    ppn_manual_override=COALESCE((p_payload->>'ppn_manual_override')::boolean,false),\n    ppn_calc_mode=COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'),dpp_amount=NULLIF(p_payload->>'dpp_amount','')::numeric,\n    ppn_rate=COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11),pph_amount=COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),\n    pph_code_id=NULLIF(p_payload->>'pph_code_id','')::uuid,stamp_duty_amount=COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),\n    fixed_asset_account_id=NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,\n    bank_charges_amount=COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),\n    currency_code=v_currency,transaction_currency=v_currency,functional_currency='IDR',exchange_rate=v_rate,\n    bank_account_currency=COALESCE(v_bank_currency,v_currency),payment_currency=v_currency,\n    payee_id=NULLIF(p_payload->>'payee_id','')::uuid,\n    linked_sales_invoice_id=NULLIF(p_payload->>'linked_sales_invoice_id','')::uuid,\n    pph_calculation_regime=NULLIF(p_payload->>'pph_calculation_regime',''),\n    pph_dpp_ratio=NULLIF(p_payload->>'pph_dpp_ratio','')::numeric,\n    pph_dpp_amount=NULLIF(p_payload->>'pph_dpp_amount','')::numeric,\n    pph_rate=NULLIF(p_payload->>'pph_rate','')::numeric,\n    is_tax_manual_override=COALESCE((p_payload->>'is_tax_manual_override')::boolean, false)\n  WHERE id=p_expense_id;\n\n  IF NOT EXISTS(\n    SELECT 1 FROM public.journal_entries\n     WHERE id=v_journal_id\n       AND source_module IN('expense','expenses')\n       AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n       AND is_posted AND NOT COALESCE(is_reversed,false)\n  ) THEN RAISE EXCEPTION 'Expense journal identity changed during edit'; END IF;\n  IF (SELECT count(*) FROM public.journal_entries\n       WHERE source_module IN('expense','expenses')\n         AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n         AND is_posted AND NOT COALESCE(is_reversed,false))<>1 THEN\n    RAISE EXCEPTION 'Expense edit did not preserve exactly one active journal';\n  END IF;\n\n  SELECT count(*),max(allocation_amount)\n    INTO v_same_selected_count,v_selected_amount\n    FROM public.bank_statement_allocations\n   WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind='supplier'\n     AND bank_statement_line_id=p_bank_statement_line_id;\n\n  IF p_bank_statement_line_id IS NOT NULL\n     AND v_same_selected_count=0 THEN\n    PERFORM public.link_bank_statement_line(\n      p_bank_statement_line_id,'expense',p_expense_id,'supplier',p_allocation_amount);\n  ELSIF p_bank_statement_line_id IS NOT NULL\n     AND p_allocation_amount IS NOT NULL\n     AND abs(COALESCE(v_selected_amount,0)-p_allocation_amount)>0.01 THEN\n    RAISE EXCEPTION 'Change an existing bank allocation through unlink/relink so other payments remain intact';\n  END IF;\n\n  PERFORM public.recalculate_expense_payment_state(p_expense_id);\n  RETURN p_expense_id;\nEND;\n$function$",COMMIT}	optimize_expense_bank_allocation_triggers	\N	\N	\N
20260909163000	{"-- Migration: 20260909163000_propagate_batch_cost_to_sales_cogs.sql\n-- Description: Automated propagation of batch authoritative cost changes to sales COGS,\n--              creating controlled revaluation true-up journals and updating snapshots.\n\nBEGIN","-- 1. Helper to resolve the authoritative unit cost of a batch\nCREATE OR REPLACE FUNCTION public.calculate_batch_authoritative_cost(p_batch public.batches)\nRETURNS numeric\nLANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$\n  SELECT COALESCE(\n    NULLIF(p_batch.landed_cost_per_unit, 0),\n    NULLIF(p_batch.cost_per_unit, 0),\n    NULLIF(p_batch.import_price, 0),\n    0\n  );\n$$","CREATE OR REPLACE FUNCTION public.get_batch_authoritative_unit_cost(p_batch_id uuid)\nRETURNS numeric\nLANGUAGE sql STABLE PARALLEL SAFE AS $$\n  SELECT COALESCE(\n    NULLIF(b.landed_cost_per_unit, 0),\n    NULLIF(b.cost_per_unit, 0),\n    NULLIF(b.import_price, 0),\n    0\n  )\n  FROM public.batches b\n  WHERE b.id = p_batch_id;\n$$","-- 2. Core procedure to revalue sales COGS when a batch cost changes\nCREATE OR REPLACE FUNCTION public.propagate_batch_cost_change(p_batch_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_batch public.batches%ROWTYPE;\n  v_new_unit_cost numeric;\n  v_cogs_account_id uuid;\n  v_inventory_account_id uuid;\n  v_inv record;\n  v_item record;\n  v_already_posted_item_cogs numeric;\n  v_target_item_cogs numeric;\n  v_item_delta numeric;\n  v_invoice_total_delta numeric;\n  v_entry_date date;\n  v_period_status text;\n  v_period_id uuid;\n  v_je_id uuid;\n  v_je_number text;\n  v_source_module text;\n  v_description text;\n  v_line_number integer;\n  v_adjusted_invoices_count integer := 0;\n  v_adjusted_items_count integer := 0;\n  v_total_delta_posted numeric := 0;\nBEGIN\n  SELECT * INTO v_batch FROM public.batches WHERE id = p_batch_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Batch not found');\n  END IF;\n\n  v_new_unit_cost := public.calculate_batch_authoritative_cost(v_batch);\n  IF v_new_unit_cost <= 0 THEN\n    RETURN jsonb_build_object('success', true, 'message', 'Batch has zero or uncosted basis; skipping propagation');\n  END IF;\n\n  SELECT id INTO v_cogs_account_id FROM public.chart_of_accounts WHERE code = '5100' LIMIT 1;\n  SELECT id INTO v_inventory_account_id FROM public.chart_of_accounts WHERE code = '1130' LIMIT 1;\n  IF v_cogs_account_id IS NULL OR v_inventory_account_id IS NULL THEN\n    RAISE EXCEPTION 'Missing COGS (5100) or Inventory (1130) account in chart_of_accounts';\n  END IF;\n\n  -- Iterate through each posted sales invoice containing items from this batch\n  FOR v_inv IN\n    SELECT DISTINCT si.id, si.invoice_number, si.invoice_date, si.customer_id, si.created_by\n      FROM public.sales_invoices si\n      JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id\n     WHERE sii.batch_id = p_batch_id\n       AND NOT COALESCE(si.is_draft, false)\n       AND si.journal_entry_id IS NOT NULL\n     ORDER BY si.invoice_date ASC, si.id ASC\n  LOOP\n    v_invoice_total_delta := 0;\n\n    -- First pass: calculate total delta for items of this batch on this invoice\n    FOR v_item IN\n      SELECT sii.id, sii.quantity, sii.cogs_total_cost\n        FROM public.sales_invoice_items sii\n       WHERE sii.invoice_id = v_inv.id\n         AND sii.batch_id = p_batch_id\n       ORDER BY sii.id\n    LOOP\n      v_target_item_cogs := ROUND(COALESCE(v_item.quantity, 0) * v_new_unit_cost, 2);\n\n      -- Check cumulative posted 5100 GL lines for this specific line item\n      SELECT COALESCE(SUM(jel.debit - jel.credit), 0)\n        INTO v_already_posted_item_cogs\n        FROM public.journal_entries je\n        JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n        JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n       WHERE jel.sales_invoice_item_id = v_item.id\n         AND coa.code = '5100'\n         AND je.is_posted = true\n         AND NOT COALESCE(je.is_reversed, false);\n\n      -- Fallback to item snapshot if no attributed GL lines exist yet\n      IF v_already_posted_item_cogs = 0 AND COALESCE(v_item.cogs_total_cost, 0) > 0 THEN\n        v_already_posted_item_cogs := v_item.cogs_total_cost;\n      END IF;\n\n      v_item_delta := v_target_item_cogs - v_already_posted_item_cogs;\n      IF ABS(v_item_delta) >= 0.01 THEN\n        v_invoice_total_delta := v_invoice_total_delta + v_item_delta;\n      END IF;\n    END LOOP;\n\n    -- If this invoice needs a COGS adjustment, post the controlled revaluation entry\n    IF ABS(v_invoice_total_delta) >= 0.01 THEN\n      -- Respect accounting period lock:\n      SELECT ap.status INTO v_period_status\n        FROM public.accounting_periods ap\n       WHERE ap.start_date <= v_inv.invoice_date AND ap.end_date >= v_inv.invoice_date\n       ORDER BY ap.start_date DESC LIMIT 1;\n\n      IF v_period_status = 'open' THEN\n        v_entry_date := v_inv.invoice_date;\n      ELSE\n        v_entry_date := CURRENT_DATE;\n      END IF;\n\n      SELECT id INTO v_period_id\n        FROM public.accounting_periods\n       WHERE start_date <= v_entry_date AND end_date >= v_entry_date\n       ORDER BY start_date DESC LIMIT 1;\n\n      -- Check if an initial COGS entry already exists\n      IF EXISTS (\n        SELECT 1 FROM public.journal_entries\n         WHERE source_module = 'sales_invoice_cogs'\n           AND reference_id = v_inv.id\n           AND is_posted = true\n           AND NOT COALESCE(is_reversed, false)\n      ) THEN\n        v_source_module := 'sales_invoice_cogs_adjustment';\n        v_description := 'COGS True-Up: ' || v_inv.invoice_number || ' (Batch ' || v_batch.batch_number || ' cost update)';\n      ELSE\n        v_source_module := 'sales_invoice_cogs';\n        v_description := 'COGS for Sales Invoice: ' || v_inv.invoice_number;\n      END IF;\n\n      v_je_number := public.next_journal_entry_number();\n\n      INSERT INTO public.journal_entries (\n        entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n        description, total_debit, total_credit, is_posted, posted_by, created_by\n      ) VALUES (\n        v_je_number, v_entry_date, v_period_id, v_source_module, v_inv.id, v_inv.invoice_number,\n        v_description, ABS(v_invoice_total_delta), ABS(v_invoice_total_delta),\n        true, COALESCE(auth.uid(), v_inv.created_by), COALESCE(auth.uid(), v_inv.created_by)\n      ) RETURNING id INTO v_je_id;\n\n      v_line_number := 1;\n\n      -- Second pass: insert balanced attributed journal lines and update item snapshots\n      FOR v_item IN\n        SELECT sii.id, sii.quantity, sii.cogs_total_cost\n          FROM public.sales_invoice_items sii\n         WHERE sii.invoice_id = v_inv.id\n           AND sii.batch_id = p_batch_id\n         ORDER BY sii.id\n      LOOP\n        v_target_item_cogs := ROUND(COALESCE(v_item.quantity, 0) * v_new_unit_cost, 2);\n\n        SELECT COALESCE(SUM(jel.debit - jel.credit), 0)\n          INTO v_already_posted_item_cogs\n          FROM public.journal_entries je\n          JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n          JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n         WHERE jel.sales_invoice_item_id = v_item.id\n           AND coa.code = '5100'\n           AND je.is_posted = true\n           AND NOT COALESCE(je.is_reversed, false);\n\n        IF v_already_posted_item_cogs = 0 AND COALESCE(v_item.cogs_total_cost, 0) > 0 THEN\n          v_already_posted_item_cogs := v_item.cogs_total_cost;\n        END IF;\n\n        v_item_delta := v_target_item_cogs - v_already_posted_item_cogs;\n\n        IF ABS(v_item_delta) >= 0.01 THEN\n          -- Update item snapshot to authoritative cost\n          UPDATE public.sales_invoice_items\n             SET cogs_unit_cost = v_new_unit_cost,\n                 cogs_total_cost = v_target_item_cogs\n           WHERE id = v_item.id;\n\n          IF v_item_delta > 0 THEN\n            -- Debit 5100 COGS, Credit 1130 Inventory\n            INSERT INTO public.journal_entry_lines (\n              journal_entry_id, line_number, account_id, description, debit, credit,\n              customer_id, batch_id, sales_invoice_item_id\n            ) VALUES (\n              v_je_id, v_line_number, v_cogs_account_id,\n              'COGS adjustment - ' || v_inv.invoice_number, v_item_delta, 0,\n              v_inv.customer_id, p_batch_id, v_item.id\n            );\n            v_line_number := v_line_number + 1;\n\n            INSERT INTO public.journal_entry_lines (\n              journal_entry_id, line_number, account_id, description, debit, credit,\n              customer_id, batch_id, sales_invoice_item_id\n            ) VALUES (\n              v_je_id, v_line_number, v_inventory_account_id,\n              'Inventory revaluation - ' || v_inv.invoice_number, 0, v_item_delta,\n              v_inv.customer_id, p_batch_id, v_item.id\n            );\n            v_line_number := v_line_number + 1;\n          ELSE\n            -- Reverse for negative delta: Debit 1130 Inventory, Credit 5100 COGS\n            INSERT INTO public.journal_entry_lines (\n              journal_entry_id, line_number, account_id, description, debit, credit,\n              customer_id, batch_id, sales_invoice_item_id\n            ) VALUES (\n              v_je_id, v_line_number, v_inventory_account_id,\n              'Inventory revaluation (downward) - ' || v_inv.invoice_number, ABS(v_item_delta), 0,\n              v_inv.customer_id, p_batch_id, v_item.id\n            );\n            v_line_number := v_line_number + 1;\n\n            INSERT INTO public.journal_entry_lines (\n              journal_entry_id, line_number, account_id, description, debit, credit,\n              customer_id, batch_id, sales_invoice_item_id\n            ) VALUES (\n              v_je_id, v_line_number, v_cogs_account_id,\n              'COGS adjustment (downward) - ' || v_inv.invoice_number, 0, ABS(v_item_delta),\n              v_inv.customer_id, p_batch_id, v_item.id\n            );\n            v_line_number := v_line_number + 1;\n          END IF;\n\n          v_adjusted_items_count := v_adjusted_items_count + 1;\n        END IF;\n      END LOOP;\n\n      v_adjusted_invoices_count := v_adjusted_invoices_count + 1;\n      v_total_delta_posted := v_total_delta_posted + v_invoice_total_delta;\n    END IF;\n  END LOOP;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'batch_id', p_batch_id,\n    'batch_number', v_batch.batch_number,\n    'new_unit_cost', v_new_unit_cost,\n    'adjusted_invoices_count', v_adjusted_invoices_count,\n    'adjusted_items_count', v_adjusted_items_count,\n    'total_delta_posted', v_total_delta_posted\n  );\nEND;\n$$","-- 3. Trigger on public.batches to automatically propagate cost changes\nCREATE OR REPLACE FUNCTION public.trg_batches_propagate_cost_change()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_old_cost numeric;\n  v_new_cost numeric;\nBEGIN\n  IF pg_trigger_depth() > 1 THEN\n    RETURN NEW;\n  END IF;\n\n  IF current_setting('app.finance_metadata_repair', true) = 'on' THEN\n    RETURN NEW;\n  END IF;\n\n  v_old_cost := public.calculate_batch_authoritative_cost(OLD);\n  v_new_cost := public.calculate_batch_authoritative_cost(NEW);\n\n  IF v_old_cost IS DISTINCT FROM v_new_cost AND v_new_cost > 0 THEN\n    PERFORM public.propagate_batch_cost_change(NEW.id);\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","DROP TRIGGER IF EXISTS trg_batches_propagate_cost_change ON public.batches","CREATE TRIGGER trg_batches_propagate_cost_change\nAFTER UPDATE OF landed_cost_per_unit, cost_per_unit, import_price, final_landed_cost\nON public.batches\nFOR EACH ROW\nEXECUTE FUNCTION public.trg_batches_propagate_cost_change()","-- 4. Update get_authoritative_sales_line_cogs to recognize sales_invoice_cogs_adjustment\nCREATE OR REPLACE FUNCTION public.get_authoritative_sales_line_cogs(\n  p_start_date date, p_end_date date\n)\nRETURNS TABLE (\n  line_id uuid, invoice_id uuid, product_id uuid, batch_id uuid, quantity numeric,\n  authoritative_cogs numeric, authoritative_unit_cogs numeric, resolution_tier text,\n  invoice_line_count bigint, invoice_product_count bigint, posted_invoice_cogs numeric,\n  base_line_cost numeric, reconciliation_difference numeric\n)\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp\nAS $$\nWITH active_cogs AS (\n  SELECT je.reference_id AS invoice_id, je.id AS journal_id,\n         SUM(jel.debit - jel.credit) AS cogs_amount\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true\n    AND NOT COALESCE(je.is_reversed, false)\n    AND coa.code = '5100'\n    AND je.reference_id IS NOT NULL\n    AND (\n      je.source_module IN ('sales_invoice_cogs', 'sales_invoice_cogs_adjustment')\n      OR je.source_module IN ('historical_cogs_correction', 'historical_cogs_final_correction')\n      OR je.source_module LIKE 'historical_cogs%'\n      OR je.source_module LIKE '%cogs%'\n    )\n  GROUP BY je.reference_id, je.id\n), posted_cogs AS (\n  SELECT invoice_id, SUM(cogs_amount) AS posted_invoice_cogs\n  FROM active_cogs GROUP BY invoice_id\n), posted_item_cogs AS (\n  SELECT jel.sales_invoice_item_id AS line_id,\n         SUM(jel.debit - jel.credit) AS posted_item_cogs\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true AND NOT COALESCE(je.is_reversed, false)\n    AND coa.code = '5100' AND jel.sales_invoice_item_id IS NOT NULL\n    AND (\n      je.source_module IN ('sales_invoice_cogs', 'sales_invoice_cogs_adjustment')\n      OR je.source_module IN ('historical_cogs_correction', 'historical_cogs_final_correction')\n      OR je.source_module LIKE 'historical_cogs%'\n      OR je.source_module LIKE '%cogs%'\n    )\n  GROUP BY jel.sales_invoice_item_id\n), line_basis AS (\n  SELECT sii.id AS line_id, sii.invoice_id, sii.product_id, sii.batch_id,\n         sii.quantity, pic.posted_item_cogs, sii.cogs_total_cost AS snapshot_cogs,\n         CASE WHEN COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0)) IS NULL\n              THEN NULL ELSE sii.quantity * COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0)) END AS base_line_cost,\n         pc.posted_invoice_cogs\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  LEFT JOIN public.batches b ON b.id = sii.batch_id\n  LEFT JOIN posted_cogs pc ON pc.invoice_id = sii.invoice_id\n  LEFT JOIN posted_item_cogs pic ON pic.line_id = sii.id\n  WHERE si.invoice_date BETWEEN p_start_date AND p_end_date\n    AND NOT COALESCE(si.is_draft, false)\n), invoice_evidence AS (\n  SELECT invoice_id, COUNT(*) AS invoice_line_count,\n         COUNT(DISTINCT product_id) AS invoice_product_count,\n         COUNT(*) FILTER (WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL) AS unresolved_line_count,\n         COUNT(*) FILTER (WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL AND base_line_cost IS NOT NULL) AS unresolved_base_line_count,\n         COALESCE(SUM(COALESCE(posted_item_cogs, snapshot_cogs)), 0) AS resolved_cogs_total,\n         SUM(base_line_cost) FILTER (WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL) AS unresolved_base_cost_total,\n         MAX(posted_invoice_cogs) AS posted_invoice_cogs\n  FROM line_basis GROUP BY invoice_id\n), resolved AS (\n  SELECT lb.*, ie.invoice_line_count, ie.invoice_product_count,\n         ie.unresolved_line_count, ie.unresolved_base_line_count,\n         ie.resolved_cogs_total, ie.unresolved_base_cost_total,\n         ie.posted_invoice_cogs AS invoice_posted_cogs,\n         ie.posted_invoice_cogs - ie.resolved_cogs_total AS residual_posted_cogs,\n         ABS(ie.unresolved_base_cost_total - (ie.posted_invoice_cogs - ie.resolved_cogs_total)) AS reconciliation_difference\n  FROM line_basis lb JOIN invoice_evidence ie ON ie.invoice_id = lb.invoice_id\n)\nSELECT r.line_id, r.invoice_id, r.product_id, r.batch_id, r.quantity,\n  CASE\n    WHEN r.posted_item_cogs IS NOT NULL THEN r.posted_item_cogs\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN r.invoice_posted_cogs\n    WHEN r.invoice_line_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)\n    ELSE NULL END AS authoritative_cogs,\n  CASE\n    WHEN r.quantity = 0 THEN NULL\n    WHEN r.posted_item_cogs IS NOT NULL THEN r.posted_item_cogs / r.quantity\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs / r.quantity\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN r.invoice_posted_cogs / r.quantity\n    WHEN r.invoice_line_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00\n      THEN (r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)) / r.quantity\n    ELSE NULL END AS authoritative_unit_cogs,\n  CASE\n    WHEN r.posted_item_cogs IS NOT NULL THEN 'posted_item_cogs'\n    WHEN r.snapshot_cogs IS NOT NULL THEN 'snapshot'\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN 'single_line_posted_cogs'\n    WHEN r.invoice_line_count > 1 AND r.invoice_product_count = 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00 THEN 'single_product_proven_allocation'\n    WHEN r.invoice_line_count > 1 AND r.invoice_product_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count AND r.unresolved_base_cost_total > 0\n      AND ABS(r.unresolved_base_cost_total - r.residual_posted_cogs) <= 1.00 THEN 'multi_product_proven_allocation'\n    ELSE 'unresolved' END AS resolution_tier,\n  r.invoice_line_count, r.invoice_product_count, r.invoice_posted_cogs,\n  r.base_line_cost, r.reconciliation_difference\nFROM resolved r;\n$$","GRANT EXECUTE ON FUNCTION public.calculate_batch_authoritative_cost(public.batches) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.get_batch_authoritative_unit_cost(uuid) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.propagate_batch_cost_change(uuid) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.get_authoritative_sales_line_cogs(date, date) TO authenticated, service_role",COMMIT}	propagate_batch_cost_to_sales_cogs	\N	\N	\N
20260911153000	{"-- Fix dynamic PPh period reassignment, trigger synchronization, and canonical amounts\nBEGIN","-- 1. Central authoritative source resolver that handles reassigned expenses in PPh_Unifikasi\n--    and includes missing_source_verified historical tax payments.\nCREATE OR REPLACE FUNCTION public.fn_pph_authoritative_source_total(p_period_id uuid)\nRETURNS numeric LANGUAGE sql STABLE SET search_path = public AS $$\n  WITH period AS (\n    SELECT id, fiscal_year, period_month, tax_type, period_start, period_end\n      FROM public.tax_periods WHERE id = p_period_id AND tax_type <> 'PPN'\n  )\n  SELECT COALESCE((\n    SELECT SUM(fe.pph_amount)\n      FROM period p\n      JOIN public.finance_expenses fe\n        ON (fe.pph_tax_period_id = p.id\n            OR (p.tax_type = 'PPh_Unifikasi' AND EXISTS (\n                SELECT 1 FROM public.tax_periods p_sub\n                 WHERE p_sub.id = fe.pph_tax_period_id\n                   AND p_sub.fiscal_year = p.fiscal_year\n                   AND p_sub.period_month = p.period_month\n            ))\n            OR (fe.pph_tax_period_id IS NULL AND fe.expense_date BETWEEN p.period_start AND p.period_end))\n      JOIN public.effective_expense_posting_state eps ON eps.expense_id = fe.id\n       AND eps.effective_posting_state IN ('ACTIVE','REPLACED')\n      LEFT JOIN public.tax_codes tc ON tc.id = fe.pph_code_id\n     WHERE fe.approval_status = 'approved' AND fe.pph_amount > 0\n       AND COALESCE(fe.expense_category,'') NOT IN ('pib_import','pph_import')\n       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)\n  ),0) + COALESCE((\n    SELECT SUM(pv.pph_amount) FROM period p\n      JOIN public.payment_vouchers pv ON (pv.tax_period_id = p.id\n        OR (p.tax_type = 'PPh_Unifikasi' AND EXISTS (\n            SELECT 1 FROM public.tax_periods p_sub\n             WHERE p_sub.id = pv.tax_period_id\n               AND p_sub.fiscal_year = p.fiscal_year\n               AND p_sub.period_month = p.period_month\n        ))\n        OR (pv.tax_period_id IS NULL AND pv.voucher_date BETWEEN p.period_start AND p.period_end))\n      LEFT JOIN public.tax_codes tc ON tc.id = pv.pph_code_id\n     WHERE COALESCE(pv.is_posted,false) AND pv.pph_amount > 0\n       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)\n  ),0) + COALESCE((\n    SELECT SUM(CASE WHEN fe.expense_category='pib_import' THEN COALESCE(fe.pib_pph_amount,0) ELSE COALESCE(fe.amount,0) END)\n      FROM period p JOIN public.finance_expenses fe ON (fe.pph_tax_period_id = p.id\n        OR (p.tax_type = 'PPh_Unifikasi' AND EXISTS (\n            SELECT 1 FROM public.tax_periods p_sub\n             WHERE p_sub.id = fe.pph_tax_period_id\n               AND p_sub.fiscal_year = p.fiscal_year\n               AND p_sub.period_month = p.period_month\n        ))\n        OR (fe.pph_tax_period_id IS NULL AND fe.expense_date BETWEEN p.period_start AND p.period_end))\n      JOIN public.effective_expense_posting_state eps ON eps.expense_id = fe.id\n       AND eps.effective_posting_state IN ('ACTIVE','REPLACED')\n     WHERE p.tax_type IN ('PPh22','PPh_Unifikasi') AND fe.approval_status='approved'\n       AND fe.expense_category IN ('pib_import','pph_import')\n  ),0) + COALESCE((\n    SELECT SUM(tp.amount) FROM period p\n      JOIN public.tax_payments tp ON tp.tax_period_id = p.id\n     WHERE (p.tax_type = 'PPh_Unifikasi' OR tp.tax_type = p.tax_type)\n       AND tp.historical_source_status = 'missing_source_verified'\n  ),0);\n$$","-- 2. Make canonical PPh total dynamic for all unfiled/open/partial periods\nCREATE OR REPLACE VIEW public.vw_canonical_tax_period_amounts AS\nWITH amounts AS (\n SELECT tp.*, public.fn_tax_payments_paid(tp.id) actual_paid,\n   CASE WHEN tp.status IN ('filed','closed') OR tp.filing_status = 'filed' THEN tp.pph_total\n        ELSE public.fn_pph_authoritative_source_total(tp.id) END::numeric(18,2) resolved_pph_total\n FROM public.tax_periods tp\n)\nSELECT id tax_period_id,fiscal_year,period_month,tax_type,status,filing_status,\n payment_due_date,filing_due_date,input_ppn_total,output_ppn_total,net_ppn,\n CASE WHEN tax_type='PPN' THEN 0::numeric(18,2) ELSE resolved_pph_total END pph_total,\n CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END::numeric(18,2) total_tax,\n actual_paid paid_amount,\n GREATEST((CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END)-actual_paid,0) outstanding_amount,\n GREATEST(actual_paid-(CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END),0) overpaid_amount,\n (CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END)-actual_paid net_position,\n public.fn_tax_period_payment_status(status,CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END,actual_paid,payment_due_date) payment_status,\n public.fn_period_payment_source(CASE WHEN tax_type='PPN' THEN net_ppn ELSE resolved_pph_total END,actual_paid,0) payment_source,\n (SELECT count(*) FROM public.tax_payments p WHERE p.tax_period_id=amounts.id AND p.status='reconciled') reconciled_payments_count,\n (SELECT count(*) FROM public.tax_payments p WHERE p.tax_period_id=amounts.id AND p.status IN ('draft','posted')) unreconciled_payments_count,\n (SELECT count(*) FROM public.sales_invoices si WHERE si.tax_period_id=amounts.id AND COALESCE(si.faktur_pajak_number,'')='' AND si.tax_amount>0) missing_faktur_count\nFROM amounts","ALTER VIEW public.vw_canonical_tax_period_amounts SET (security_invoker = true)","GRANT SELECT ON public.vw_canonical_tax_period_amounts TO anon, authenticated, service_role","-- 3. Update reassign_tax_document_period to resolve default/implicit periods and recompute both periods\nCREATE OR REPLACE FUNCTION public.reassign_tax_document_period(\n  p_source text,\n  p_document_id uuid,\n  p_tax_period_id uuid\n) RETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_target public.tax_periods%ROWTYPE;\n  v_old_period_id uuid;\n  v_tax_type text;\n  v_tax_code_id uuid;\n  v_doc_date date;\nBEGIN\n  SELECT * INTO v_target\n    FROM public.tax_periods\n   WHERE id = p_tax_period_id\n   FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Tax period % not found', p_tax_period_id; END IF;\n  IF v_target.status IN ('closed', 'filed') OR v_target.filing_status = 'filed' THEN\n    RAISE EXCEPTION 'Tax period % is filed or closed and cannot be selected', p_tax_period_id;\n  END IF;\n\n  CASE p_source\n    WHEN 'purchase_invoice' THEN\n      SELECT tax_period_id, invoice_date INTO v_old_period_id, v_doc_date FROM public.purchase_invoices WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Purchase invoices require a PPN tax period'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    WHEN 'sales_invoice' THEN\n      SELECT tax_period_id, invoice_date INTO v_old_period_id, v_doc_date FROM public.sales_invoices WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Sales invoice % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Sales invoices require a PPN tax period'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    WHEN 'credit_note' THEN\n      SELECT tax_period_id, issue_date INTO v_old_period_id, v_doc_date FROM public.credit_notes WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Credit note % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Credit notes require a PPN tax period'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    WHEN 'finance_expense_ppn' THEN\n      SELECT tax_period_id, expense_date INTO v_old_period_id, v_doc_date FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Expense % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Expenses require a PPN tax period for PPN reporting'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    WHEN 'finance_expense_pph' THEN\n      SELECT pph_tax_period_id, pph_code_id, expense_date INTO v_old_period_id, v_tax_code_id, v_doc_date\n        FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Expense % not found', p_document_id; END IF;\n      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id;\n      IF v_tax_type IS NULL OR v_target.tax_type <> v_tax_type THEN RAISE EXCEPTION 'Expense PPh tax type must match the selected period'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = v_tax_type AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    WHEN 'payment_voucher' THEN\n      SELECT tax_period_id, pph_code_id, voucher_date INTO v_old_period_id, v_tax_code_id, v_doc_date\n        FROM public.payment_vouchers WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found', p_document_id; END IF;\n      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id;\n      IF v_tax_type IS NULL OR v_target.tax_type <> v_tax_type THEN RAISE EXCEPTION 'Payment voucher PPh tax type must match the selected period'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = v_tax_type AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    ELSE\n      RAISE EXCEPTION 'Unsupported tax document source %', p_source;\n  END CASE;\n\n  IF v_old_period_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.tax_periods\n     WHERE id=v_old_period_id AND (status IN ('closed', 'filed') OR filing_status='filed')\n  ) THEN\n    RAISE EXCEPTION 'The current tax period is filed or closed; reopen it before changing this document';\n  END IF;\n\n  CASE p_source\n    WHEN 'purchase_invoice' THEN UPDATE public.purchase_invoices SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'sales_invoice' THEN\n      UPDATE public.sales_invoices SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n      UPDATE public.faktur_pajak SET tax_period_id=p_tax_period_id WHERE sales_invoice_id=p_document_id;\n    WHEN 'credit_note' THEN UPDATE public.credit_notes SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'finance_expense_ppn' THEN UPDATE public.finance_expenses SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'finance_expense_pph' THEN UPDATE public.finance_expenses SET pph_tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'payment_voucher' THEN UPDATE public.payment_vouchers SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n  END CASE;\n\n  IF v_old_period_id IS NOT NULL AND v_old_period_id <> p_tax_period_id THEN\n    PERFORM public.compute_period_ppn(v_old_period_id);\n  END IF;\n  PERFORM public.compute_period_ppn(p_tax_period_id);\nEND;\n$$","-- 4. Update trigger function to listen to pph_tax_period_id and tax_period_id\nCREATE OR REPLACE FUNCTION public.trg_recompute_from_expense()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF COALESCE(OLD.pph_amount, 0) > 0\n       OR COALESCE(OLD.pib_pph_amount, 0) > 0\n       OR OLD.expense_category = 'pph_import' THEN\n      IF OLD.pph_tax_period_id IS NOT NULL THEN\n        PERFORM public.compute_period_ppn(OLD.pph_tax_period_id);\n      END IF;\n      PERFORM public.recompute_pph_periods_for_date(COALESCE(OLD.due_date, OLD.expense_date));\n      IF OLD.expense_date IS NOT NULL THEN\n        PERFORM public.recompute_pph_periods_for_date(OLD.expense_date);\n      END IF;\n    END IF;\n    IF OLD.tax_period_id IS NOT NULL THEN\n      PERFORM public.compute_period_ppn(OLD.tax_period_id);\n    END IF;\n\n  ELSIF TG_OP = 'INSERT' THEN\n    IF COALESCE(NEW.pph_amount, 0) > 0\n       OR COALESCE(NEW.pib_pph_amount, 0) > 0\n       OR NEW.expense_category = 'pph_import' THEN\n      IF NEW.pph_tax_period_id IS NOT NULL THEN\n        PERFORM public.compute_period_ppn(NEW.pph_tax_period_id);\n      END IF;\n      PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(NEW.id));\n    END IF;\n    IF NEW.tax_period_id IS NOT NULL THEN\n      PERFORM public.compute_period_ppn(NEW.tax_period_id);\n    END IF;\n\n  ELSIF TG_OP = 'UPDATE' THEN\n    IF (\n      NEW.pph_amount IS DISTINCT FROM OLD.pph_amount OR\n      NEW.pib_pph_amount IS DISTINCT FROM OLD.pib_pph_amount OR\n      NEW.ppn_amount IS DISTINCT FROM OLD.ppn_amount OR\n      NEW.pib_ppn_amount IS DISTINCT FROM OLD.pib_ppn_amount OR\n      NEW.expense_date IS DISTINCT FROM OLD.expense_date OR\n      NEW.due_date IS DISTINCT FROM OLD.due_date OR\n      NEW.expense_category IS DISTINCT FROM OLD.expense_category OR\n      NEW.approval_status IS DISTINCT FROM OLD.approval_status OR\n      NEW.pph_code_id IS DISTINCT FROM OLD.pph_code_id OR\n      NEW.pph_tax_period_id IS DISTINCT FROM OLD.pph_tax_period_id OR\n      NEW.tax_period_id IS DISTINCT FROM OLD.tax_period_id\n    ) THEN\n      IF NEW.pph_tax_period_id IS NOT NULL THEN\n        PERFORM public.compute_period_ppn(NEW.pph_tax_period_id);\n      END IF;\n      IF OLD.pph_tax_period_id IS NOT NULL AND OLD.pph_tax_period_id IS DISTINCT FROM NEW.pph_tax_period_id THEN\n        PERFORM public.compute_period_ppn(OLD.pph_tax_period_id);\n      END IF;\n      IF NEW.tax_period_id IS NOT NULL THEN\n        PERFORM public.compute_period_ppn(NEW.tax_period_id);\n      END IF;\n      IF OLD.tax_period_id IS NOT NULL AND OLD.tax_period_id IS DISTINCT FROM NEW.tax_period_id THEN\n        PERFORM public.compute_period_ppn(OLD.tax_period_id);\n      END IF;\n\n      IF COALESCE(NEW.pph_amount, 0) > 0\n         OR COALESCE(NEW.pib_pph_amount, 0) > 0\n         OR NEW.expense_category = 'pph_import' THEN\n        PERFORM public.recompute_pph_periods_for_date(public.get_expense_pph_period_date(NEW.id));\n      END IF;\n      IF COALESCE(OLD.pph_amount, 0) > 0\n         OR COALESCE(OLD.pib_pph_amount, 0) > 0\n         OR OLD.expense_category = 'pph_import' THEN\n        PERFORM public.recompute_pph_periods_for_date(COALESCE(OLD.due_date, OLD.expense_date));\n        IF OLD.expense_date IS DISTINCT FROM NEW.expense_date THEN\n          PERFORM public.recompute_pph_periods_for_date(OLD.expense_date);\n        END IF;\n      END IF;\n    END IF;\n  END IF;\n  RETURN NULL;\nEND;\n$function$","-- 5. Recompute current stored totals for June and July 2026 periods\nSELECT public.compute_period_ppn(id)\n  FROM public.tax_periods\n WHERE fiscal_year = 2026 AND period_month IN (6, 7) AND tax_type <> 'PPN'","NOTIFY pgrst, 'reload schema'",COMMIT}	fix_dynamic_pph23_period_reassignment	\N	\N	\N
20260914140000	{"-- ============================================================================\n-- Migration: Fix Import PPh 22 Classification in Tax Compliance Engine\n-- ============================================================================\n-- Root Cause:\n--   Import PPh 22 (paid under PIB customs clearance) was previously aggregated\n--   into monthly tax_periods.pph_total as if it were a monthly withholding tax\n--   liability. Because Import PPh 22 is paid directly at customs via bank transfer\n--   to the State Treasury (Kas Negara/DJBC) and debited to 1155 PPh 22 Dibayar\n--   Dimuka (Advance Income Tax Asset), it is NOT a monthly withholding liability\n--   and is never remitted via monthly DJP billing (tax_payments).\n--\n-- Fix:\n--   1. Exclude pib_import and pph_import from fn_pph_authoritative_source_total()\n--      and compute_period_ppn_pre_posted_register().\n--   2. Maintain vw_pph22_advance_tax_report as the authoritative register for\n--      Annual Corporate Tax Return (SPT Tahunan PPh Badan / Form 1771 Lampiran III).\n--   3. Recalculate tax_periods for PPh22 and PPh_Unifikasi so that phantom\n--      liabilities are cleared from vw_outstanding_tax.\n--   4. Genuine withholdings (PPh 21, PPh 23, PPh 4(2)) and COA 1155/2137 balances\n--      remain 100% unaffected.\n-- ============================================================================\n\nBEGIN","-- 1. Central authoritative source resolver: exclude import advance taxes\nCREATE OR REPLACE FUNCTION public.fn_pph_authoritative_source_total(p_period_id uuid)\nRETURNS numeric LANGUAGE sql STABLE SET search_path = public AS $$\n  WITH period AS (\n    SELECT id, fiscal_year, period_month, tax_type, period_start, period_end\n      FROM public.tax_periods WHERE id = p_period_id AND tax_type <> 'PPN'\n  )\n  -- (a) Genuine withholding on expenses (where pph_amount > 0).\n  -- Note: pib_import and pph_import are excluded because import PPh 22 is an\n  -- advance tax (prepaid tax asset / COA 1155) paid at customs clearance under PIB,\n  -- NOT a monthly withholding liability payable to DJP.\n  SELECT COALESCE((\n    SELECT SUM(fe.pph_amount)\n      FROM period p\n      JOIN public.finance_expenses fe\n        ON (fe.pph_tax_period_id = p.id\n            OR (p.tax_type = 'PPh_Unifikasi' AND EXISTS (\n                SELECT 1 FROM public.tax_periods p_sub\n                 WHERE p_sub.id = fe.pph_tax_period_id\n                   AND p_sub.fiscal_year = p.fiscal_year\n                   AND p_sub.period_month = p.period_month\n            ))\n            OR (fe.pph_tax_period_id IS NULL AND fe.expense_date BETWEEN p.period_start AND p.period_end))\n      JOIN public.effective_expense_posting_state eps ON eps.expense_id = fe.id\n       AND eps.effective_posting_state IN ('ACTIVE','REPLACED')\n      LEFT JOIN public.tax_codes tc ON tc.id = fe.pph_code_id\n     WHERE fe.approval_status = 'approved' AND fe.pph_amount > 0\n       AND COALESCE(fe.expense_category,'') NOT IN ('pib_import','pph_import')\n       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)\n  ),0)\n  -- (b) Genuine withholding on payment vouchers\n  + COALESCE((\n    SELECT SUM(pv.pph_amount) FROM period p\n      JOIN public.payment_vouchers pv ON (pv.tax_period_id = p.id\n        OR (p.tax_type = 'PPh_Unifikasi' AND EXISTS (\n            SELECT 1 FROM public.tax_periods p_sub\n             WHERE p_sub.id = pv.tax_period_id\n               AND p_sub.fiscal_year = p.fiscal_year\n               AND p_sub.period_month = p.period_month\n        ))\n        OR (pv.tax_period_id IS NULL AND pv.voucher_date BETWEEN p.period_start AND p.period_end))\n      LEFT JOIN public.tax_codes tc ON tc.id = pv.pph_code_id\n     WHERE COALESCE(pv.is_posted,false) AND pv.pph_amount > 0\n       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)\n  ),0)\n  -- (c) Historical verified tax payments with missing source\n  + COALESCE((\n    SELECT SUM(tp.amount) FROM period p\n      JOIN public.tax_payments tp ON tp.tax_period_id = p.id\n     WHERE (p.tax_type = 'PPh_Unifikasi' OR tp.tax_type = p.tax_type)\n       AND tp.historical_source_status = 'missing_source_verified'\n  ),0);\n$$","-- 2. Legacy pre-posted register calculation: align with authoritative resolver\nCREATE OR REPLACE FUNCTION public.compute_period_ppn_pre_posted_register(p_period_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  v_period       tax_periods%ROWTYPE;\n  v_input        numeric(18,2);\n  v_output_gross numeric(18,2);\n  v_output_cn    numeric(18,2);\n  v_output       numeric(18,2);\n  v_prior_cf     numeric(18,2);\n  v_pph_total    numeric(18,2);\nBEGIN\n  SELECT * INTO v_period FROM tax_periods WHERE id = p_period_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax period % not found', p_period_id;\n  END IF;\n\n  IF v_period.tax_type = 'PPN' THEN\n    SELECT\n      COALESCE((\n        SELECT SUM(tax_amount) FROM purchase_invoices\n         WHERE tax_period_id = p_period_id AND tax_amount > 0\n      ), 0)\n      +\n      COALESCE((\n        SELECT SUM(fe.ppn_amount)\n          FROM finance_expenses fe\n         WHERE fe.tax_period_id = p_period_id\n           AND fe.ppn_amount > 0\n           AND NOT EXISTS (\n             SELECT 1\n               FROM jsonb_array_elements(COALESCE(fe.broker_items, '[]'::jsonb)) item\n              WHERE COALESCE((item->>'ppn_amount')::numeric, 0) > 0\n           )\n      ), 0)\n      +\n      COALESCE((\n        SELECT SUM(COALESCE((item->>'ppn_amount')::numeric, 0))\n          FROM finance_expenses fe\n          CROSS JOIN LATERAL jsonb_array_elements(COALESCE(fe.broker_items, '[]'::jsonb)) item\n         WHERE fe.tax_period_id = p_period_id\n           AND COALESCE((item->>'ppn_amount')::numeric, 0) > 0\n      ), 0)\n      +\n      COALESCE((\n        SELECT SUM(pib_ppn_amount) FROM finance_expenses\n         WHERE tax_period_id = p_period_id AND pib_ppn_amount > 0\n      ), 0)\n    INTO v_input;\n\n    SELECT COALESCE(SUM(tax_amount), 0) INTO v_output_gross\n      FROM sales_invoices\n     WHERE tax_period_id = p_period_id AND tax_amount > 0;\n\n    SELECT COALESCE(SUM(tax_amount), 0) INTO v_output_cn\n      FROM credit_notes\n     WHERE tax_period_id = p_period_id\n       AND status = 'approved'\n       AND tax_amount > 0;\n\n    v_output := GREATEST(v_output_gross - v_output_cn, 0);\n\n    SELECT COALESCE(carry_forward_out, 0) INTO v_prior_cf\n      FROM tax_periods\n     WHERE tax_type = 'PPN'\n       AND (fiscal_year, period_month) < (v_period.fiscal_year, v_period.period_month)\n     ORDER BY fiscal_year DESC, period_month DESC\n     LIMIT 1;\n    v_prior_cf := COALESCE(v_prior_cf, 0);\n\n    UPDATE tax_periods SET\n      input_ppn_total   = v_input,\n      output_ppn_total  = v_output,\n      carry_forward_in  = v_prior_cf,\n      net_ppn           = GREATEST(v_output - v_input - v_prior_cf, 0),\n      carry_forward_out = GREATEST(v_input + v_prior_cf - v_output, 0),\n      updated_at        = now()\n    WHERE id = p_period_id;\n\n  ELSE\n    -- PPh period: only sum genuine withholdings (never import advance taxes)\n    SELECT\n      COALESCE((\n        SELECT SUM(fe.pph_amount)\n          FROM finance_expenses fe\n          LEFT JOIN tax_codes tc ON tc.id = fe.pph_code_id\n         WHERE EXTRACT(YEAR  FROM fe.expense_date)::int = v_period.fiscal_year\n           AND EXTRACT(MONTH FROM fe.expense_date)::int = v_period.period_month\n           AND fe.pph_amount > 0\n           AND COALESCE(fe.expense_category, '') NOT IN ('pib_import', 'pph_import')\n           AND (v_period.tax_type = 'PPh_Unifikasi' OR tc.tax_type = v_period.tax_type)\n      ), 0)\n      +\n      COALESCE((\n        SELECT SUM(pv.pph_amount)\n          FROM payment_vouchers pv\n          LEFT JOIN tax_codes tc ON tc.id = pv.pph_code_id\n         WHERE EXTRACT(YEAR  FROM pv.voucher_date)::int = v_period.fiscal_year\n           AND EXTRACT(MONTH FROM pv.voucher_date)::int = v_period.period_month\n           AND pv.pph_amount > 0\n           AND (v_period.tax_type = 'PPh_Unifikasi' OR tc.tax_type = v_period.tax_type)\n      ), 0)\n    INTO v_pph_total;\n\n    UPDATE tax_periods SET\n      pph_total  = v_pph_total,\n      updated_at = now()\n    WHERE id = p_period_id;\n  END IF;\nEND;\n$$","-- 3. Recalculate/refresh all open/unfiled PPh22 and PPh_Unifikasi tax periods\nDO $$\nDECLARE\n  r record;\nBEGIN\n  FOR r IN\n    SELECT id FROM public.tax_periods\n     WHERE tax_type IN ('PPh22', 'PPh_Unifikasi')\n       AND status NOT IN ('closed', 'filed')\n       AND COALESCE(filing_status, '') <> 'filed'\n     ORDER BY fiscal_year, period_month\n  LOOP\n    PERFORM public.compute_period_ppn(r.id);\n  END LOOP;\nEND $$","NOTIFY pgrst, 'reload schema'",COMMIT}	fix_import_pph22_classification	\N	\N	\N
20260914150000	{"-- ============================================================================\n-- Migration: 20260914150000_enquiry_control_center_foundation.sql\n-- Description: Phase 4 Enquiry Control Center Database Foundation\n-- \n-- Exactly SIX new tables:\n--   1. public.enquiry_conversations\n--   2. public.enquiry_conversation_links\n--   3. public.enquiry_conversation_messages\n--   4. public.enquiry_requests\n--   5. public.enquiry_request_events\n--   6. public.enquiry_request_messages\n--\n-- Exactly ONE existing table modification:\n--   public.crm_product_documents (adds nullable enquiry_request_id FK + index)\n--\n-- Zero changes to crm_inquiries, crm_inquiry_items, tasks, or pricing tables.\n-- Zero business logic, triggers, or backfill.\n-- ============================================================================\n\nBEGIN","-- ============================================================================\n-- 1. enquiry_conversations\n-- ============================================================================\nCREATE TABLE public.enquiry_conversations (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  customer_id UUID REFERENCES public.customers(id) ON DELETE SET NULL,\n  crm_contact_id UUID REFERENCES public.crm_contacts(id) ON DELETE SET NULL,\n  channel TEXT NOT NULL CHECK (channel IN ('email', 'whatsapp', 'internal')),\n  external_thread_id TEXT,\n  title TEXT NOT NULL,\n  participant_identifiers TEXT[] NOT NULL DEFAULT '{}',\n  last_message_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived', 'spam')),\n  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n)","-- Channel-scoped conversation identity uniqueness\nCREATE UNIQUE INDEX uq_enq_conv_channel_external_thread\n  ON public.enquiry_conversations(channel, external_thread_id)\n  WHERE external_thread_id IS NOT NULL","-- Operational indexes\nCREATE INDEX idx_enq_conv_customer_id ON public.enquiry_conversations(customer_id)","CREATE INDEX idx_enq_conv_last_message ON public.enquiry_conversations(last_message_at DESC)","-- ============================================================================\n-- 2. enquiry_conversation_links\n-- ============================================================================\nCREATE TABLE public.enquiry_conversation_links (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  conversation_id UUID NOT NULL REFERENCES public.enquiry_conversations(id) ON DELETE CASCADE,\n  inquiry_id UUID NOT NULL REFERENCES public.crm_inquiries(id) ON DELETE CASCADE,\n  link_type TEXT NOT NULL DEFAULT 'related' CHECK (link_type IN ('primary', 'related', 'reference')),\n  is_active BOOLEAN NOT NULL DEFAULT true,\n  created_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  CONSTRAINT uq_conversation_inquiry UNIQUE (conversation_id, inquiry_id)\n)","-- Single active primary conversation per enquiry\nCREATE UNIQUE INDEX uq_enquiry_single_active_primary_conv\n  ON public.enquiry_conversation_links(inquiry_id)\n  WHERE link_type = 'primary' AND is_active = true","-- Operational indexes\nCREATE INDEX idx_enq_conv_links_inq_id ON public.enquiry_conversation_links(inquiry_id)","CREATE INDEX idx_enq_conv_links_conv_id ON public.enquiry_conversation_links(conversation_id)","-- ============================================================================\n-- 3. enquiry_conversation_messages\n-- ============================================================================\nCREATE TABLE public.enquiry_conversation_messages (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  conversation_id UUID NOT NULL REFERENCES public.enquiry_conversations(id) ON DELETE RESTRICT,\n  channel TEXT NOT NULL CHECK (channel IN ('email', 'whatsapp', 'internal')),\n  direction TEXT NOT NULL CHECK (direction IN ('inbound', 'outbound', 'internal')),\n  external_message_id TEXT,\n  sender_address TEXT NOT NULL,\n  sender_name TEXT,\n  recipient_addresses TEXT[] NOT NULL DEFAULT '{}',\n  subject TEXT,\n  body_text TEXT,\n  body_html TEXT,\n  attachments JSONB NOT NULL DEFAULT '[]'::jsonb,\n  raw_payload JSONB,\n  received_or_sent_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  actor_type TEXT NOT NULL DEFAULT 'user' CHECK (actor_type IN ('user', 'system', 'ai')),\n  actor_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,\n  ai_processed BOOLEAN NOT NULL DEFAULT false,\n  ai_summary TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n)","-- Message-level idempotency uniqueness\nCREATE UNIQUE INDEX uq_enq_msg_channel_external_id\n  ON public.enquiry_conversation_messages(channel, external_message_id)\n  WHERE external_message_id IS NOT NULL","-- Operational index\nCREATE INDEX idx_enq_msg_conv_received ON public.enquiry_conversation_messages(conversation_id, received_or_sent_at DESC)","-- ============================================================================\n-- 4. enquiry_requests\n-- ============================================================================\nCREATE TABLE public.enquiry_requests (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  inquiry_id UUID NOT NULL REFERENCES public.crm_inquiries(id) ON DELETE RESTRICT,\n  inquiry_item_id UUID REFERENCES public.crm_inquiry_items(id) ON DELETE SET NULL,\n  product_id UUID REFERENCES public.products(id) ON DELETE SET NULL,\n  product_name_raw TEXT,\n  \n  category TEXT NOT NULL CHECK (category IN (\n    'commercial',\n    'technical',\n    'document',\n    'sample',\n    'logistics',\n    'custom'\n  )),\n  request_code TEXT NOT NULL,\n  title TEXT NOT NULL,\n  customer_requirement TEXT NOT NULL,\n  parameters JSONB NOT NULL DEFAULT '{}'::jsonb,\n\n  status TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN (\n    'OPEN',\n    'IN_PROGRESS',\n    'BLOCKED',\n    'RESOLVED',\n    'NOT_POSSIBLE',\n    'NOT_REQUIRED',\n    'CANCELLED'\n  )),\n  waiting_for TEXT NOT NULL DEFAULT 'INTERNAL' CHECK (waiting_for IN (\n    'INTERNAL',\n    'INDIA',\n    'MANUFACTURER',\n    'CUSTOMER',\n    'NONE'\n  )),\n  current_issue TEXT,\n  next_action TEXT,\n\n  assigned_to UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,\n  assigned_team TEXT CHECK (assigned_team IN (\n    'sales', 'pricing_india', 'regulatory', 'warehouse', 'sourcing', 'management'\n  )),\n\n  due_at TIMESTAMPTZ,\n  reminder_level INT NOT NULL DEFAULT 0 CHECK (reminder_level BETWEEN 0 AND 4),\n  last_reminded_at TIMESTAMPTZ,\n  escalated_at TIMESTAMPTZ,\n\n  source_message_id UUID REFERENCES public.enquiry_conversation_messages(id) ON DELETE SET NULL,\n  ai_status TEXT NOT NULL DEFAULT 'manual' CHECK (ai_status IN ('manual', 'suggested', 'confirmed', 'rejected', 'edited')),\n  ai_confidence NUMERIC(4,3),\n  ai_extracted_text TEXT,\n  confirmed_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,\n  confirmed_at TIMESTAMPTZ,\n\n  response_text TEXT,\n  response_value JSONB,\n  resolved_at TIMESTAMPTZ,\n  resolved_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,\n\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n)","-- Operational indexes\nCREATE INDEX idx_enq_req_inquiry_id ON public.enquiry_requests(inquiry_id)","CREATE INDEX idx_enq_req_item_id ON public.enquiry_requests(inquiry_item_id) WHERE inquiry_item_id IS NOT NULL","CREATE INDEX idx_enq_req_product_id ON public.enquiry_requests(product_id) WHERE product_id IS NOT NULL","CREATE INDEX idx_enq_req_status_waiting ON public.enquiry_requests(status, waiting_for)","CREATE INDEX idx_enq_req_assigned ON public.enquiry_requests(assigned_to, assigned_team) WHERE status IN ('OPEN', 'IN_PROGRESS', 'BLOCKED')","CREATE INDEX idx_enq_req_due_at ON public.enquiry_requests(due_at) WHERE status IN ('OPEN', 'IN_PROGRESS', 'BLOCKED')","CREATE INDEX idx_enq_req_ai_status ON public.enquiry_requests(ai_status) WHERE ai_status = 'suggested'","CREATE INDEX idx_enq_req_source_msg ON public.enquiry_requests(source_message_id) WHERE source_message_id IS NOT NULL","-- ============================================================================\n-- 5. enquiry_request_events\n-- ============================================================================\nCREATE TABLE public.enquiry_request_events (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  request_id UUID NOT NULL REFERENCES public.enquiry_requests(id) ON DELETE CASCADE,\n  inquiry_id UUID NOT NULL REFERENCES public.crm_inquiries(id) ON DELETE CASCADE,\n  event_type TEXT NOT NULL CHECK (event_type IN (\n    'created',\n    'requirement_changed',\n    'supplier_response',\n    'customer_decision',\n    'status_changed',\n    'waiting_for_changed',\n    'owner_reassigned',\n    'escalated',\n    'resolved',\n    'cancelled'\n  )),\n  summary TEXT NOT NULL,\n  old_status TEXT,\n  new_status TEXT,\n  old_waiting_for TEXT,\n  new_waiting_for TEXT,\n  details JSONB NOT NULL DEFAULT '{}'::jsonb,\n  source_message_id UUID REFERENCES public.enquiry_conversation_messages(id) ON DELETE SET NULL,\n  actor_type TEXT NOT NULL DEFAULT 'user' CHECK (actor_type IN ('user', 'system', 'ai')),\n  actor_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n)","-- Operational indexes\nCREATE INDEX idx_enq_req_events_req_created ON public.enquiry_request_events(request_id, created_at DESC)","CREATE INDEX idx_enq_req_events_inq_created ON public.enquiry_request_events(inquiry_id, created_at DESC)","-- ============================================================================\n-- 6. enquiry_request_messages\n-- ============================================================================\nCREATE TABLE public.enquiry_request_messages (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  request_id UUID NOT NULL REFERENCES public.enquiry_requests(id) ON DELETE CASCADE,\n  message_id UUID NOT NULL REFERENCES public.enquiry_conversation_messages(id) ON DELETE CASCADE,\n  relationship TEXT NOT NULL CHECK (relationship IN (\n    'originated',\n    'clarified',\n    'blocked',\n    'resolved',\n    'referenced'\n  )),\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  CONSTRAINT uq_request_message UNIQUE (request_id, message_id, relationship)\n)","CREATE INDEX idx_enq_req_msg_lookup ON public.enquiry_request_messages(request_id, message_id)","-- ============================================================================\n-- 7. Modify Existing Table: crm_product_documents\n-- ============================================================================\nALTER TABLE public.crm_product_documents\n  ADD COLUMN IF NOT EXISTS enquiry_request_id UUID REFERENCES public.enquiry_requests(id) ON DELETE SET NULL","CREATE INDEX IF NOT EXISTS idx_crm_prod_docs_req_id\n  ON public.crm_product_documents(enquiry_request_id)\n  WHERE enquiry_request_id IS NOT NULL","-- ============================================================================\n-- 8. Updated_At Triggers (Using Existing ERP Helper)\n-- ============================================================================\nCREATE TRIGGER trg_enquiry_conversations_updated_at\n  BEFORE UPDATE ON public.enquiry_conversations\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","CREATE TRIGGER trg_enquiry_requests_updated_at\n  BEFORE UPDATE ON public.enquiry_requests\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()","-- ============================================================================\n-- 9. Row Level Security (RLS)\n-- ============================================================================\nALTER TABLE public.enquiry_conversations ENABLE ROW LEVEL SECURITY","ALTER TABLE public.enquiry_conversation_links ENABLE ROW LEVEL SECURITY","ALTER TABLE public.enquiry_conversation_messages ENABLE ROW LEVEL SECURITY","ALTER TABLE public.enquiry_requests ENABLE ROW LEVEL SECURITY","ALTER TABLE public.enquiry_request_events ENABLE ROW LEVEL SECURITY","ALTER TABLE public.enquiry_request_messages ENABLE ROW LEVEL SECURITY","-- enquiry_conversations\nCREATE POLICY \\"enquiry_conversations_select\\"\n  ON public.enquiry_conversations FOR SELECT TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true))","CREATE POLICY \\"enquiry_conversations_insert\\"\n  ON public.enquiry_conversations FOR INSERT TO authenticated\n  WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","CREATE POLICY \\"enquiry_conversations_update\\"\n  ON public.enquiry_conversations FOR UPDATE TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))\n  WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","CREATE POLICY \\"enquiry_conversations_delete\\"\n  ON public.enquiry_conversations FOR DELETE TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role = 'admin'))","-- enquiry_conversation_links\nCREATE POLICY \\"enquiry_conversation_links_select\\"\n  ON public.enquiry_conversation_links FOR SELECT TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true))","CREATE POLICY \\"enquiry_conversation_links_insert\\"\n  ON public.enquiry_conversation_links FOR INSERT TO authenticated\n  WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","CREATE POLICY \\"enquiry_conversation_links_update\\"\n  ON public.enquiry_conversation_links FOR UPDATE TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))\n  WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","CREATE POLICY \\"enquiry_conversation_links_delete\\"\n  ON public.enquiry_conversation_links FOR DELETE TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","-- enquiry_conversation_messages\nCREATE POLICY \\"enquiry_conversation_messages_select\\"\n  ON public.enquiry_conversation_messages FOR SELECT TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true))","CREATE POLICY \\"enquiry_conversation_messages_insert\\"\n  ON public.enquiry_conversation_messages FOR INSERT TO authenticated\n  WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","CREATE POLICY \\"enquiry_conversation_messages_update\\"\n  ON public.enquiry_conversation_messages FOR UPDATE TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))\n  WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","CREATE POLICY \\"enquiry_conversation_messages_delete\\"\n  ON public.enquiry_conversation_messages FOR DELETE TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role = 'admin'))","-- enquiry_requests\nCREATE POLICY \\"enquiry_requests_select\\"\n  ON public.enquiry_requests FOR SELECT TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true))","CREATE POLICY \\"enquiry_requests_insert\\"\n  ON public.enquiry_requests FOR INSERT TO authenticated\n  WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","CREATE POLICY \\"enquiry_requests_update\\"\n  ON public.enquiry_requests FOR UPDATE TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))\n  WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","CREATE POLICY \\"enquiry_requests_delete\\"\n  ON public.enquiry_requests FOR DELETE TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role = 'admin'))","-- enquiry_request_events (APPEND-ONLY: ZERO UPDATE AND ZERO DELETE POLICIES)\nCREATE POLICY \\"enquiry_request_events_select\\"\n  ON public.enquiry_request_events FOR SELECT TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true))","CREATE POLICY \\"enquiry_request_events_insert\\"\n  ON public.enquiry_request_events FOR INSERT TO authenticated\n  WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","-- enquiry_request_messages\nCREATE POLICY \\"enquiry_request_messages_select\\"\n  ON public.enquiry_request_messages FOR SELECT TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true))","CREATE POLICY \\"enquiry_request_messages_insert\\"\n  ON public.enquiry_request_messages FOR INSERT TO authenticated\n  WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","CREATE POLICY \\"enquiry_request_messages_update\\"\n  ON public.enquiry_request_messages FOR UPDATE TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))\n  WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","CREATE POLICY \\"enquiry_request_messages_delete\\"\n  ON public.enquiry_request_messages FOR DELETE TO authenticated\n  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_active = true AND role IN ('admin', 'sales')))","NOTIFY pgrst, 'reload schema'",COMMIT}	enquiry_control_center_foundation	\N	\N	\N
20260914160000	{"-- ============================================================================\n-- Migration: 20260914160000_enquiry_service_atomic_rpc.sql\n-- Description: Phase 5 Enquiry Service Atomic RPCs and Immutability Protection\n--\n-- Objects:\n--   1. Trigger fn_protect_enquiry_message_content & trg_protect_enquiry_message_content\n--   2. Tightened RLS on enquiry_request_messages (remove sales DELETE/UPDATE)\n--   3. RPC create_enquiry_request_atomic\n--   4. RPC transition_enquiry_request_atomic\n--\n-- Security:\n--   - Strict actor enforcement (browser callers forced to actor_type='user', actor_id=auth.uid())\n--   - Role checks: active admin/sales users only, auditor_ca blocked from write\n--   - Explicit EXECUTE grants (REVOKE FROM PUBLIC, GRANT TO authenticated, service_role)\n-- ============================================================================\n\nBEGIN","-- ============================================================================\n-- 1. Message Communication Content Immutability Protection\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.fn_protect_enquiry_message_content()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  IF NEW.channel IS DISTINCT FROM OLD.channel\n     OR NEW.direction IS DISTINCT FROM OLD.direction\n     OR NEW.external_message_id IS DISTINCT FROM OLD.external_message_id\n     OR NEW.sender_address IS DISTINCT FROM OLD.sender_address\n     OR NEW.recipient_addresses IS DISTINCT FROM OLD.recipient_addresses\n     OR NEW.subject IS DISTINCT FROM OLD.subject\n     OR NEW.body_text IS DISTINCT FROM OLD.body_text\n     OR NEW.body_html IS DISTINCT FROM OLD.body_html\n     OR NEW.attachments IS DISTINCT FROM OLD.attachments\n     OR NEW.received_or_sent_at IS DISTINCT FROM OLD.received_or_sent_at\n     OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id\n  THEN\n    RAISE EXCEPTION 'Communication content in enquiry_conversation_messages is immutable';\n  END IF;\n  RETURN NEW;\nEND;\n$$","DROP TRIGGER IF EXISTS trg_protect_enquiry_message_content ON public.enquiry_conversation_messages","CREATE TRIGGER trg_protect_enquiry_message_content\n  BEFORE UPDATE ON public.enquiry_conversation_messages\n  FOR EACH ROW\n  EXECUTE FUNCTION public.fn_protect_enquiry_message_content()","-- ============================================================================\n-- 2. Tighten Provenance Policies on enquiry_request_messages\n-- ============================================================================\n-- Drop existing update and delete policies\nDROP POLICY IF EXISTS \\"enquiry_request_messages_update\\" ON public.enquiry_request_messages","DROP POLICY IF EXISTS \\"enquiry_request_messages_delete\\" ON public.enquiry_request_messages","-- Provenance is strictly append-only (SELECT + INSERT) for normal sales users.\n-- DELETE is restricted solely to admin. UPDATE is removed completely.\nCREATE POLICY \\"enquiry_request_messages_delete\\"\n  ON public.enquiry_request_messages FOR DELETE TO authenticated\n  USING (EXISTS (\n    SELECT 1 FROM public.user_profiles\n    WHERE id = auth.uid() AND is_active = true AND role = 'admin'\n  ))","-- ============================================================================\n-- 3. Atomic Request Creation RPC\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.create_enquiry_request_atomic(\n  p_inquiry_id UUID,\n  p_category TEXT,\n  p_request_code TEXT,\n  p_title TEXT,\n  p_customer_requirement TEXT,\n  p_parameters JSONB DEFAULT '{}'::jsonb,\n  p_assigned_to UUID DEFAULT NULL,\n  p_assigned_team TEXT DEFAULT NULL,\n  p_due_at TIMESTAMPTZ DEFAULT NULL,\n  p_waiting_for TEXT DEFAULT 'INTERNAL',\n  p_source_message_id UUID DEFAULT NULL,\n  p_ai_status TEXT DEFAULT 'manual',\n  p_ai_confidence NUMERIC DEFAULT NULL,\n  p_ai_extracted_text TEXT DEFAULT NULL,\n  p_actor_type TEXT DEFAULT 'user',\n  p_actor_id UUID DEFAULT NULL\n)\nRETURNS UUID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_caller_role TEXT;\n  v_caller_auth_uid UUID;\n  v_effective_actor_type TEXT;\n  v_effective_actor_id UUID;\n  v_new_req_id UUID;\n  v_user_role TEXT;\nBEGIN\n  v_caller_role := auth.role();\n  v_caller_auth_uid := auth.uid();\n\n  IF v_caller_role = 'authenticated' THEN\n    SELECT role INTO v_user_role\n    FROM public.user_profiles\n    WHERE id = v_caller_auth_uid AND is_active = true;\n\n    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'sales') THEN\n      RAISE EXCEPTION 'Unauthorized: only active admin or sales users can create enquiry requests';\n    END IF;\n\n    -- Anti-spoofing guards\n    IF p_actor_type IS NOT NULL AND p_actor_type <> 'user' THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate AI or system';\n    END IF;\n\n    IF p_actor_id IS NOT NULL AND p_actor_id <> v_caller_auth_uid THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate other users';\n    END IF;\n\n    v_effective_actor_type := 'user';\n    v_effective_actor_id := v_caller_auth_uid;\n\n  ELSIF v_caller_role = 'service_role' THEN\n    IF p_actor_type NOT IN ('user', 'system', 'ai') THEN\n      RAISE EXCEPTION 'Invalid actor_type: must be user, system, or ai';\n    END IF;\n    v_effective_actor_type := p_actor_type;\n    v_effective_actor_id := p_actor_id;\n\n  ELSE\n    RAISE EXCEPTION 'Unauthorized: unauthenticated access rejected';\n  END IF;\n\n  -- Validate inquiry exists\n  IF NOT EXISTS (SELECT 1 FROM public.crm_inquiries WHERE id = p_inquiry_id) THEN\n    RAISE EXCEPTION 'Inquiry not found: %', p_inquiry_id;\n  END IF;\n\n  -- Insert into enquiry_requests\n  INSERT INTO public.enquiry_requests (\n    inquiry_id,\n    category,\n    request_code,\n    title,\n    customer_requirement,\n    parameters,\n    assigned_to,\n    assigned_team,\n    due_at,\n    status,\n    waiting_for,\n    source_message_id,\n    ai_status,\n    ai_confidence,\n    ai_extracted_text\n  ) VALUES (\n    p_inquiry_id,\n    p_category,\n    p_request_code,\n    p_title,\n    p_customer_requirement,\n    COALESCE(p_parameters, '{}'::jsonb),\n    p_assigned_to,\n    p_assigned_team,\n    p_due_at,\n    'OPEN',\n    COALESCE(p_waiting_for, 'INTERNAL'),\n    p_source_message_id,\n    COALESCE(p_ai_status, 'manual'),\n    p_ai_confidence,\n    p_ai_extracted_text\n  )\n  RETURNING id INTO v_new_req_id;\n\n  -- Insert initial 'created' event\n  INSERT INTO public.enquiry_request_events (\n    request_id,\n    inquiry_id,\n    event_type,\n    summary,\n    old_status,\n    new_status,\n    old_waiting_for,\n    new_waiting_for,\n    details,\n    source_message_id,\n    actor_type,\n    actor_id\n  ) VALUES (\n    v_new_req_id,\n    p_inquiry_id,\n    'created',\n    'Request created: ' || p_title,\n    NULL,\n    'OPEN',\n    NULL,\n    COALESCE(p_waiting_for, 'INTERNAL'),\n    jsonb_build_object(\n      'initial_requirement', p_customer_requirement,\n      'parameters', COALESCE(p_parameters, '{}'::jsonb)\n    ),\n    p_source_message_id,\n    v_effective_actor_type,\n    v_effective_actor_id\n  );\n\n  -- Insert provenance if source message provided\n  IF p_source_message_id IS NOT NULL THEN\n    INSERT INTO public.enquiry_request_messages (\n      request_id,\n      message_id,\n      relationship\n    ) VALUES (\n      v_new_req_id,\n      p_source_message_id,\n      'originated'\n    )\n    ON CONFLICT (request_id, message_id, relationship) DO NOTHING;\n  END IF;\n\n  RETURN v_new_req_id;\nEND;\n$$","-- ============================================================================\n-- 4. Atomic Request State Transition RPC\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.transition_enquiry_request_atomic(\n  p_request_id UUID,\n  p_event_type TEXT,\n  p_summary TEXT,\n  p_new_status TEXT DEFAULT NULL,\n  p_new_waiting_for TEXT DEFAULT NULL,\n  p_new_requirement TEXT DEFAULT NULL,\n  p_new_parameters JSONB DEFAULT NULL,\n  p_current_issue TEXT DEFAULT NULL,\n  p_next_action TEXT DEFAULT NULL,\n  p_new_assigned_to UUID DEFAULT NULL,\n  p_new_assigned_team TEXT DEFAULT NULL,\n  p_response_text TEXT DEFAULT NULL,\n  p_response_value JSONB DEFAULT NULL,\n  p_details JSONB DEFAULT '{}'::jsonb,\n  p_source_message_id UUID DEFAULT NULL,\n  p_actor_type TEXT DEFAULT 'user',\n  p_actor_id UUID DEFAULT NULL\n)\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_caller_role TEXT;\n  v_caller_auth_uid UUID;\n  v_effective_actor_type TEXT;\n  v_effective_actor_id UUID;\n  v_user_role TEXT;\n\n  v_req public.enquiry_requests%ROWTYPE;\n  v_effective_status TEXT;\n  v_effective_waiting_for TEXT;\n  v_effective_requirement TEXT;\n  v_effective_parameters JSONB;\n  v_effective_assigned_to UUID;\n  v_effective_assigned_team TEXT;\n  v_effective_current_issue TEXT;\n  v_effective_next_action TEXT;\n  v_effective_response_text TEXT;\n  v_effective_response_value JSONB;\n  v_resolved_at TIMESTAMPTZ;\n  v_resolved_by UUID;\n  v_event_details JSONB;\nBEGIN\n  v_caller_role := auth.role();\n  v_caller_auth_uid := auth.uid();\n\n  IF v_caller_role = 'authenticated' THEN\n    SELECT role INTO v_user_role\n    FROM public.user_profiles\n    WHERE id = v_caller_auth_uid AND is_active = true;\n\n    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'sales') THEN\n      RAISE EXCEPTION 'Unauthorized: only active admin or sales users can update enquiry requests';\n    END IF;\n\n    -- Anti-spoofing guards\n    IF p_actor_type IS NOT NULL AND p_actor_type <> 'user' THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate AI or system';\n    END IF;\n\n    IF p_actor_id IS NOT NULL AND p_actor_id <> v_caller_auth_uid THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate other users';\n    END IF;\n\n    v_effective_actor_type := 'user';\n    v_effective_actor_id := v_caller_auth_uid;\n\n  ELSIF v_caller_role = 'service_role' THEN\n    IF p_actor_type NOT IN ('user', 'system', 'ai') THEN\n      RAISE EXCEPTION 'Invalid actor_type: must be user, system, or ai';\n    END IF;\n    v_effective_actor_type := p_actor_type;\n    v_effective_actor_id := p_actor_id;\n\n  ELSE\n    RAISE EXCEPTION 'Unauthorized: unauthenticated access rejected';\n  END IF;\n\n  -- Validate event_type check constraint\n  IF p_event_type NOT IN (\n    'created',\n    'requirement_changed',\n    'supplier_response',\n    'customer_decision',\n    'status_changed',\n    'waiting_for_changed',\n    'owner_reassigned',\n    'escalated',\n    'resolved',\n    'cancelled'\n  ) THEN\n    RAISE EXCEPTION 'Invalid event_type: %', p_event_type;\n  END IF;\n\n  -- Row lock target enquiry_requests record\n  SELECT * INTO v_req\n  FROM public.enquiry_requests\n  WHERE id = p_request_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Enquiry request not found: %', p_request_id;\n  END IF;\n\n  -- Resolve effective state values\n  v_effective_status := COALESCE(p_new_status, v_req.status);\n  v_effective_waiting_for := COALESCE(p_new_waiting_for, v_req.waiting_for);\n  v_effective_requirement := COALESCE(p_new_requirement, v_req.customer_requirement);\n  v_effective_parameters := COALESCE(p_new_parameters, v_req.parameters);\n  v_effective_assigned_to := CASE WHEN p_new_assigned_to IS NOT NULL THEN p_new_assigned_to ELSE v_req.assigned_to END;\n  v_effective_assigned_team := CASE WHEN p_new_assigned_team IS NOT NULL THEN p_new_assigned_team ELSE v_req.assigned_team END;\n  v_effective_current_issue := CASE WHEN p_current_issue IS NOT NULL THEN p_current_issue ELSE v_req.current_issue END;\n  v_effective_next_action := CASE WHEN p_next_action IS NOT NULL THEN p_next_action ELSE v_req.next_action END;\n  v_effective_response_text := CASE WHEN p_response_text IS NOT NULL THEN p_response_text ELSE v_req.response_text END;\n  v_effective_response_value := CASE WHEN p_response_value IS NOT NULL THEN p_response_value ELSE v_req.response_value END;\n  v_resolved_at := v_req.resolved_at;\n  v_resolved_by := v_req.resolved_by;\n\n  -- State-specific validations\n  IF v_effective_status = 'RESOLVED' THEN\n    IF (v_effective_response_text IS NULL OR trim(v_effective_response_text) = '')\n       AND (v_effective_response_value IS NULL OR v_effective_response_value = '{}'::jsonb) THEN\n      RAISE EXCEPTION 'RESOLVED requests require response_text or response_value';\n    END IF;\n    v_effective_waiting_for := 'NONE';\n    v_resolved_at := now();\n    v_resolved_by := v_effective_actor_id;\n  END IF;\n\n  IF v_effective_status = 'BLOCKED' THEN\n    IF v_effective_waiting_for = 'NONE' THEN\n      RAISE EXCEPTION 'BLOCKED requests must specify waiting_for dependency (INTERNAL, INDIA, MANUFACTURER, CUSTOMER)';\n    END IF;\n    IF v_effective_current_issue IS NULL OR trim(v_effective_current_issue) = '' THEN\n      RAISE EXCEPTION 'BLOCKED requests must have a current_issue describing the impediment';\n    END IF;\n  END IF;\n\n  IF v_effective_status = 'CANCELLED' THEN\n    IF (v_effective_current_issue IS NULL OR trim(v_effective_current_issue) = '')\n       AND (p_details->>'cancellation_reason' IS NULL OR trim(p_details->>'cancellation_reason') = '') THEN\n      RAISE EXCEPTION 'CANCELLED requests must have a cancellation reason in current_issue or details.cancellation_reason';\n    END IF;\n  END IF;\n\n  IF v_effective_status = 'NOT_POSSIBLE' THEN\n    IF (v_effective_current_issue IS NULL OR trim(v_effective_current_issue) = '')\n       AND (p_details->>'reason' IS NULL OR trim(p_details->>'reason') = '') THEN\n      RAISE EXCEPTION 'NOT_POSSIBLE requests must have an explanation in current_issue or details.reason';\n    END IF;\n  END IF;\n\n  -- Build details diff\n  v_event_details := COALESCE(p_details, '{}'::jsonb);\n  IF p_new_requirement IS NOT NULL AND p_new_requirement <> v_req.customer_requirement THEN\n    v_event_details := v_event_details || jsonb_build_object(\n      'requirement_diff', jsonb_build_object('old', v_req.customer_requirement, 'new', p_new_requirement)\n    );\n  END IF;\n\n  -- Apply updates to enquiry_requests\n  UPDATE public.enquiry_requests\n  SET\n    status = v_effective_status,\n    waiting_for = v_effective_waiting_for,\n    customer_requirement = v_effective_requirement,\n    parameters = v_effective_parameters,\n    assigned_to = v_effective_assigned_to,\n    assigned_team = v_effective_assigned_team,\n    current_issue = v_effective_current_issue,\n    next_action = v_effective_next_action,\n    response_text = v_effective_response_text,\n    response_value = v_effective_response_value,\n    resolved_at = v_resolved_at,\n    resolved_by = v_resolved_by,\n    updated_at = now()\n  WHERE id = p_request_id;\n\n  -- Append event to enquiry_request_events\n  INSERT INTO public.enquiry_request_events (\n    request_id,\n    inquiry_id,\n    event_type,\n    summary,\n    old_status,\n    new_status,\n    old_waiting_for,\n    new_waiting_for,\n    details,\n    source_message_id,\n    actor_type,\n    actor_id\n  ) VALUES (\n    p_request_id,\n    v_req.inquiry_id,\n    p_event_type,\n    p_summary,\n    v_req.status,\n    v_effective_status,\n    v_req.waiting_for,\n    v_effective_waiting_for,\n    v_event_details,\n    p_source_message_id,\n    v_effective_actor_type,\n    v_effective_actor_id\n  );\n\n  -- Link provenance if source message provided\n  IF p_source_message_id IS NOT NULL THEN\n    INSERT INTO public.enquiry_request_messages (\n      request_id,\n      message_id,\n      relationship\n    ) VALUES (\n      p_request_id,\n      p_source_message_id,\n      CASE\n        WHEN v_effective_status = 'RESOLVED' THEN 'resolved'\n        WHEN v_effective_status = 'BLOCKED' THEN 'blocked'\n        ELSE 'clarified'\n      END\n    )\n    ON CONFLICT (request_id, message_id, relationship) DO NOTHING;\n  END IF;\n\nEND;\n$$","-- ============================================================================\n-- 5. RPC Security Grants (Explicit Permissions)\n-- ============================================================================\nREVOKE ALL ON FUNCTION public.create_enquiry_request_atomic FROM PUBLIC","REVOKE ALL ON FUNCTION public.transition_enquiry_request_atomic FROM PUBLIC","REVOKE EXECUTE ON FUNCTION public.create_enquiry_request_atomic FROM anon","REVOKE EXECUTE ON FUNCTION public.transition_enquiry_request_atomic FROM anon","GRANT EXECUTE ON FUNCTION public.create_enquiry_request_atomic TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.transition_enquiry_request_atomic TO authenticated, service_role",COMMIT}	enquiry_service_atomic_rpc	\N	\N	\N
20260914170000	{"-- Migration: 20260914170000_add_gmail_ids_to_crm_email_activities.sql\n-- Add nullable gmail_message_id and gmail_thread_id to public.crm_email_activities\n-- with partial unique index and transparent deduplication protection.\n\nALTER TABLE public.crm_email_activities \n  ADD COLUMN IF NOT EXISTS gmail_message_id text,\n  ADD COLUMN IF NOT EXISTS gmail_thread_id text","CREATE UNIQUE INDEX IF NOT EXISTS idx_crm_email_activities_gmail_msg_id \n  ON public.crm_email_activities(gmail_message_id) \n  WHERE gmail_message_id IS NOT NULL","-- Deduplication function: prevents duplicate activity records if a caller subsequently\n-- attempts to insert the same outbound email that send-bulk-email already recorded.\nCREATE OR REPLACE FUNCTION public.fn_crm_email_activities_dedup()\nRETURNS TRIGGER AS $$\nDECLARE\n  v_existing_id UUID;\nBEGIN\n  -- If the incoming record already has gmail_message_id, let normal unique index handle it\n  IF NEW.gmail_message_id IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n\n  -- If incoming record has NO gmail_message_id, check if a matching record with gmail_message_id\n  -- was already created for this send (same inquiry, subject, creator, within 2-minute window)\n  SELECT id INTO v_existing_id\n  FROM public.crm_email_activities\n  WHERE gmail_message_id IS NOT NULL\n    AND created_by IS NOT DISTINCT FROM NEW.created_by\n    AND subject = NEW.subject\n    AND inquiry_id IS NOT DISTINCT FROM NEW.inquiry_id\n    AND sent_date >= (COALESCE(NEW.sent_date, now()) - INTERVAL '2 minutes')\n    AND sent_date <= (COALESCE(NEW.sent_date, now()) + INTERVAL '2 minutes')\n  ORDER BY sent_date DESC\n  LIMIT 1;\n\n  IF v_existing_id IS NOT NULL THEN\n    -- Update existing activity with any supplementary fields and suppress duplicate insert\n    UPDATE public.crm_email_activities\n    SET\n      contact_id = COALESCE(crm_email_activities.contact_id, NEW.contact_id),\n      template_id = COALESCE(crm_email_activities.template_id, NEW.template_id),\n      attachment_urls = COALESCE(crm_email_activities.attachment_urls, NEW.attachment_urls)\n    WHERE id = v_existing_id;\n\n    RETURN NULL; -- Suppresses the duplicate insert\n  END IF;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql","DROP TRIGGER IF EXISTS trg_crm_email_activities_dedup ON public.crm_email_activities","CREATE TRIGGER trg_crm_email_activities_dedup\n  BEFORE INSERT ON public.crm_email_activities\n  FOR EACH ROW\n  EXECUTE FUNCTION public.fn_crm_email_activities_dedup()"}	add_gmail_ids_to_crm_email_activities	\N	\N	\N
20260914183000	{"-- Migration: Add 'enquiry_request' to tasks reference_type check constraint\n-- Canonical relationship: tasks.reference_type = 'enquiry_request' AND tasks.reference_id = enquiry_requests.id\n\nALTER TABLE public.tasks DROP CONSTRAINT IF EXISTS tasks_reference_type_check","ALTER TABLE public.tasks ADD CONSTRAINT tasks_reference_type_check CHECK (\n  reference_type IS NULL OR reference_type IN (\n    'sales_order',\n    'delivery_challan',\n    'import_requirement',\n    'purchase_order',\n    'product',\n    'customer',\n    'supplier',\n    'batch',\n    'other',\n    'enquiry_request'\n  )\n)","-- Ensure index exists for performant lookup of tasks by enquiry_request reference\nCREATE INDEX IF NOT EXISTS idx_tasks_enquiry_request_ref \n  ON public.tasks(reference_id) \n  WHERE reference_type = 'enquiry_request'","-- Fix legacy trigger error where create_task_status_history attempted to reference non-existent NEW.updated_by\nCREATE OR REPLACE FUNCTION public.create_task_status_history()\nRETURNS trigger\nLANGUAGE plpgsql\nSET search_path TO 'public'\nAS $$\nBEGIN\n  IF (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status) THEN\n    INSERT INTO task_status_history (\n      task_id,\n      old_status,\n      new_status,\n      changed_by,\n      notes\n    ) VALUES (\n      NEW.id,\n      OLD.status,\n      NEW.status,\n      COALESCE(auth.uid(), NEW.completed_by, NEW.created_by),\n      'Status changed from ' || OLD.status || ' to ' || NEW.status\n    );\n  END IF;\n  RETURN NEW;\nEND;\n$$"}	add_enquiry_request_to_tasks_reference_type	\N	\N	\N
20260914200000	{"-- ============================================================================\n-- Migration: 20260914200000_implement_task_notifications_and_reminders.sql\n-- Description: Phase 7.5 - Operational Notifications, Mentions, and Reminders\n-- \n-- Implements genuine notification triggers:\n--   1. notify_task_assignment() on task_assignments (replaces baseline placeholder)\n--   2. notify_mentioned_users() on task_comments (replaces baseline placeholder)\n--   3. evaluate_enquiry_task_reminders() idempotent escalation evaluator\n--\n-- Reuses existing public.notifications, public.tasks, and public.enquiry_requests.\n-- Zero new task or reminder tables.\n-- ============================================================================\n\nBEGIN","-- ============================================================================\n-- 1. Real Implementation of notify_task_assignment()\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.notify_task_assignment()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  v_task RECORD;\n  v_assigner_name TEXT;\n  v_inquiry_number TEXT;\n  v_request_code TEXT;\n  v_title TEXT;\n  v_message TEXT;\nBEGIN\n  -- 1. Fetch task details\n  SELECT \n    t.title,\n    t.priority,\n    t.deadline,\n    t.reference_type,\n    t.reference_id,\n    t.inquiry_id\n  INTO v_task\n  FROM public.tasks t\n  WHERE t.id = NEW.task_id;\n\n  IF NOT FOUND THEN\n    RETURN NEW;\n  END IF;\n\n  -- 2. Fetch assigner name (if available)\n  IF NEW.assigned_by IS NOT NULL THEN\n    SELECT COALESCE(full_name, email)\n    INTO v_assigner_name\n    FROM public.user_profiles\n    WHERE id = NEW.assigned_by;\n  END IF;\n  v_assigner_name := COALESCE(v_assigner_name, 'System / Manager');\n\n  -- 3. If task is linked to enquiry or enquiry_request, fetch contextual codes\n  IF v_task.inquiry_id IS NOT NULL THEN\n    SELECT inquiry_number INTO v_inquiry_number\n    FROM public.crm_inquiries\n    WHERE id = v_task.inquiry_id;\n  END IF;\n\n  IF v_task.reference_type = 'enquiry_request' AND v_task.reference_id IS NOT NULL THEN\n    SELECT request_code INTO v_request_code\n    FROM public.enquiry_requests\n    WHERE id = v_task.reference_id;\n  END IF;\n\n  -- 4. Construct message\n  v_title := 'New task assigned: ' || v_task.title;\n  \n  v_message := v_assigner_name || ' assigned you to task: ' || v_task.title;\n  IF v_inquiry_number IS NOT NULL THEN\n    v_message := v_message || ' [' || v_inquiry_number;\n    IF v_request_code IS NOT NULL THEN\n      v_message := v_message || ' - ' || v_request_code;\n    END IF;\n    v_message := v_message || ']';\n  END IF;\n\n  IF v_task.priority IS NOT NULL THEN\n    v_message := v_message || ' | Priority: ' || UPPER(v_task.priority::text);\n  END IF;\n\n  IF v_task.deadline IS NOT NULL THEN\n    v_message := v_message || ' | Due: ' || to_char(v_task.deadline AT TIME ZONE 'UTC', 'YYYY-MM-DD');\n  END IF;\n\n  -- 5. Insert notification for assigned user (idempotent, avoid duplicate unread)\n  INSERT INTO public.notifications (\n    user_id,\n    type,\n    title,\n    message,\n    reference_id,\n    reference_type,\n    is_read,\n    created_at\n  )\n  VALUES (\n    NEW.assigned_user_id,\n    'task_assigned',\n    v_title,\n    v_message,\n    NEW.task_id,\n    'task',\n    false,\n    now()\n  )\n  ON CONFLICT (user_id, type, message) WHERE (is_read = false)\n  DO NOTHING;\n\n  RETURN NEW;\nEND;\n$$","-- Ensure trigger exists on task_assignments\nDROP TRIGGER IF EXISTS trigger_notify_task_assignment ON public.task_assignments","CREATE TRIGGER trigger_notify_task_assignment\n  AFTER INSERT ON public.task_assignments\n  FOR EACH ROW\n  EXECUTE FUNCTION public.notify_task_assignment()","-- ============================================================================\n-- 2. Real Implementation of notify_mentioned_users()\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.notify_mentioned_users()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  v_task_title TEXT;\n  v_commenter_name TEXT;\n  v_mentioned_id UUID;\n  v_title TEXT;\n  v_message TEXT;\nBEGIN\n  -- If no mentions, nothing to do\n  IF NEW.mentions IS NULL OR array_length(NEW.mentions, 1) IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  -- 1. Fetch task title\n  SELECT title INTO v_task_title\n  FROM public.tasks\n  WHERE id = NEW.task_id;\n  v_task_title := COALESCE(v_task_title, 'Task');\n\n  -- 2. Fetch commenter name\n  SELECT COALESCE(full_name, email) INTO v_commenter_name\n  FROM public.user_profiles\n  WHERE id = NEW.user_id;\n  v_commenter_name := COALESCE(v_commenter_name, 'A team member');\n\n  v_title := 'You were mentioned in a task';\n  v_message := v_commenter_name || ' mentioned you in task: ' || v_task_title;\n\n  -- 3. Loop over mentioned users (excluding commenter themself)\n  FOREACH v_mentioned_id IN ARRAY NEW.mentions\n  LOOP\n    IF v_mentioned_id IS NOT NULL AND v_mentioned_id <> NEW.user_id THEN\n      INSERT INTO public.notifications (\n        user_id,\n        type,\n        title,\n        message,\n        reference_id,\n        reference_type,\n        is_read,\n        created_at\n      )\n      VALUES (\n        v_mentioned_id,\n        'task_mention',\n        v_title,\n        v_message,\n        NEW.task_id,\n        'task',\n        false,\n        now()\n      )\n      ON CONFLICT (user_id, type, message) WHERE (is_read = false)\n      DO NOTHING;\n    END IF;\n  END LOOP;\n\n  RETURN NEW;\nEND;\n$$","-- Ensure trigger exists on task_comments\nDROP TRIGGER IF EXISTS trigger_notify_mentioned_users ON public.task_comments","CREATE TRIGGER trigger_notify_mentioned_users\n  AFTER INSERT ON public.task_comments\n  FOR EACH ROW\n  EXECUTE FUNCTION public.notify_mentioned_users()","-- ============================================================================\n-- 3. Idempotent Reminder & Escalation Evaluator\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.evaluate_enquiry_task_reminders()\nRETURNS TABLE (\n  evaluated_requests INT,\n  evaluated_tasks INT,\n  reminders_advanced INT,\n  escalations_triggered INT\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = 'public'\nAS $$\nDECLARE\n  r RECORD;\n  t RECORD;\n  v_req_count INT := 0;\n  v_task_count INT := 0;\n  v_adv_count INT := 0;\n  v_esc_count INT := 0;\n  v_target_level INT;\n  v_now TIMESTAMPTZ := now();\n  v_hours_overdue NUMERIC;\nBEGIN\n  -- Iterate through all active requests that have a due_at set\n  FOR r IN\n    SELECT \n      req.id,\n      req.inquiry_id,\n      req.request_code,\n      req.title,\n      req.status,\n      req.due_at,\n      req.reminder_level,\n      req.last_reminded_at,\n      req.escalated_at,\n      req.assigned_to,\n      inq.inquiry_number\n    FROM public.enquiry_requests req\n    JOIN public.crm_inquiries inq ON inq.id = req.inquiry_id\n    WHERE req.status IN ('OPEN', 'IN_PROGRESS', 'BLOCKED')\n      AND req.due_at IS NOT NULL\n  LOOP\n    v_req_count := v_req_count + 1;\n    \n    -- Calculate overdue hours\n    IF r.due_at < v_now THEN\n      v_hours_overdue := EXTRACT(EPOCH FROM (v_now - r.due_at)) / 3600.0;\n      \n      -- Determine reminder level:\n      -- Level 1: Due / Overdue 0 - 24 hours\n      -- Level 2: Overdue 24 - 48 hours\n      -- Level 3: Overdue 48 - 72 hours\n      -- Level 4: Escalation (Overdue > 72 hours)\n      IF v_hours_overdue >= 72 THEN\n        v_target_level := 4;\n      ELSIF v_hours_overdue >= 48 THEN\n        v_target_level := 3;\n      ELSIF v_hours_overdue >= 24 THEN\n        v_target_level := 2;\n      ELSE\n        v_target_level := 1;\n      END IF;\n\n      -- If target level exceeds current reminder_level, advance\n      IF v_target_level > r.reminder_level THEN\n        UPDATE public.enquiry_requests\n        SET \n          reminder_level = v_target_level,\n          last_reminded_at = v_now,\n          escalated_at = CASE WHEN v_target_level = 4 AND escalated_at IS NULL THEN v_now ELSE escalated_at END,\n          updated_at = v_now\n        WHERE id = r.id;\n\n        v_adv_count := v_adv_count + 1;\n        IF v_target_level = 4 AND r.escalated_at IS NULL THEN\n          v_esc_count := v_esc_count + 1;\n        END IF;\n\n        -- Create notification for request owner if assigned\n        IF r.assigned_to IS NOT NULL THEN\n          INSERT INTO public.notifications (\n            user_id,\n            type,\n            title,\n            message,\n            reference_id,\n            reference_type,\n            is_read,\n            created_at\n          )\n          VALUES (\n            r.assigned_to,\n            CASE WHEN v_target_level = 4 THEN 'task_deadline' ELSE 'task_deadline' END,\n            CASE WHEN v_target_level = 4 THEN 'ESCALATION: Requirement overdue >72h' ELSE 'Reminder: Requirement overdue' END,\n            'Requirement ' || r.request_code || ' (' || r.inquiry_number || ' - ' || r.title || ') is ' || \n            ROUND(v_hours_overdue / 24.0, 1)::text || ' days overdue. Level ' || v_target_level::text,\n            r.id,\n            'enquiry_request',\n            false,\n            v_now\n          )\n          ON CONFLICT (user_id, type, message) WHERE (is_read = false)\n          DO NOTHING;\n        END IF;\n      END IF;\n    END IF;\n  END LOOP;\n\n  -- 2. Evaluate active incomplete tasks past deadline\n  FOR t IN\n    SELECT \n      tsk.id,\n      tsk.title,\n      tsk.deadline,\n      tsk.priority,\n      tsk.reference_type,\n      tsk.reference_id,\n      tsk.inquiry_id,\n      inq.inquiry_number,\n      ta.assigned_user_id\n    FROM public.tasks tsk\n    LEFT JOIN public.crm_inquiries inq ON inq.id = tsk.inquiry_id\n    JOIN public.task_assignments ta ON ta.task_id = tsk.id\n    WHERE tsk.is_deleted = false\n      AND tsk.status IN ('to_do', 'in_progress', 'waiting')\n      AND tsk.deadline IS NOT NULL\n      AND tsk.deadline < v_now\n  LOOP\n    v_task_count := v_task_count + 1;\n    v_hours_overdue := EXTRACT(EPOCH FROM (v_now - t.deadline)) / 3600.0;\n\n    INSERT INTO public.notifications (\n      user_id,\n      type,\n      title,\n      message,\n      reference_id,\n      reference_type,\n      is_read,\n      created_at\n    )\n    VALUES (\n      t.assigned_user_id,\n      'task_deadline',\n      CASE WHEN v_hours_overdue >= 72 THEN 'ESCALATION: Task overdue >72h' ELSE 'Task Overdue Alert' END,\n      'Task \\"' || t.title || '\\"' || \n      CASE WHEN t.inquiry_number IS NOT NULL THEN ' (' || t.inquiry_number || ')' ELSE '' END || \n      ' is ' || ROUND(v_hours_overdue / 24.0, 1)::text || ' days overdue.',\n      t.id,\n      'task',\n      false,\n      v_now\n    )\n    ON CONFLICT (user_id, type, message) WHERE (is_read = false)\n    DO NOTHING;\n  END LOOP;\n\n  RETURN QUERY SELECT v_req_count, v_task_count, v_adv_count, v_esc_count;\nEND;\n$$",COMMIT}	implement_task_notifications_and_reminders	\N	\N	\N
20260914210000	{"-- ============================================================================\n-- Migration: 20260914210000_add_ai_proposal_to_enquiry_messages.sql\n-- Description: Phase 7.6A - Add ai_proposal storage to enquiry_conversation_messages\n-- \n-- Stores structured Enquiry Brain interpretations separately from authoritative\n-- business state. Unaccepted AI proposals never mutate enquiry_requests.\n-- ============================================================================\n\nBEGIN","ALTER TABLE public.enquiry_conversation_messages\n  ADD COLUMN IF NOT EXISTS ai_proposal JSONB DEFAULT NULL","-- Optional index for finding pending or unreviewed proposals\nCREATE INDEX IF NOT EXISTS idx_enq_msg_ai_proposal_status\n  ON public.enquiry_conversation_messages((ai_proposal->>'status'))\n  WHERE ai_proposal IS NOT NULL",COMMIT}	add_ai_proposal_to_enquiry_messages	\N	\N	\N
20260914220000	{"-- ============================================================================\n-- Migration: 20260914220000_enquiry_brain_review_gate_hardening.sql\n-- Description: Phase 7.6B Hardening: Atomic Stale-Proposal Protection &\n--              Database-Level Proposal Review Concurrency Idempotency\n--\n-- Objects:\n--   1. Re-defined RPC transition_enquiry_request_atomic (with p_expected_values)\n--   2. RPC accept_enquiry_brain_proposal_atomic (transactional lock + idempotency + stale check)\n--   3. RPC edit_enquiry_brain_proposal_atomic (human-corrected values + original preservation)\n--   4. RPC dismiss_enquiry_brain_proposal_atomic (zero mutation on business state)\n--\n-- Security:\n--   - Strict actor enforcement (browser callers forced to actor_type='user', actor_id=auth.uid())\n--   - Active admin/sales users only\n--   - Revoke from public/anon, grant to authenticated and service_role\n-- ============================================================================\n\nBEGIN","-- ============================================================================\n-- 1. Enhanced transition_enquiry_request_atomic with inside-transaction stale check\n-- ============================================================================\n\n-- Drop existing signature to ensure clean signature replacement\nDROP FUNCTION IF EXISTS public.transition_enquiry_request_atomic(UUID, TEXT, TEXT, TEXT, TEXT, TEXT, JSONB, TEXT, TEXT, UUID, TEXT, TEXT, JSONB, JSONB, UUID, TEXT, UUID)","DROP FUNCTION IF EXISTS public.transition_enquiry_request_atomic(UUID, TEXT, TEXT, TEXT, TEXT, TEXT, JSONB, TEXT, TEXT, UUID, TEXT, TEXT, JSONB, JSONB, UUID, TEXT, UUID, JSONB)","CREATE OR REPLACE FUNCTION public.transition_enquiry_request_atomic(\n  p_request_id UUID,\n  p_event_type TEXT,\n  p_summary TEXT,\n  p_new_status TEXT DEFAULT NULL,\n  p_new_waiting_for TEXT DEFAULT NULL,\n  p_new_requirement TEXT DEFAULT NULL,\n  p_new_parameters JSONB DEFAULT NULL,\n  p_current_issue TEXT DEFAULT NULL,\n  p_next_action TEXT DEFAULT NULL,\n  p_new_assigned_to UUID DEFAULT NULL,\n  p_new_assigned_team TEXT DEFAULT NULL,\n  p_response_text TEXT DEFAULT NULL,\n  p_response_value JSONB DEFAULT NULL,\n  p_details JSONB DEFAULT '{}'::jsonb,\n  p_source_message_id UUID DEFAULT NULL,\n  p_actor_type TEXT DEFAULT 'user',\n  p_actor_id UUID DEFAULT NULL,\n  p_expected_values JSONB DEFAULT NULL\n)\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_caller_role TEXT;\n  v_caller_auth_uid UUID;\n  v_effective_actor_type TEXT;\n  v_effective_actor_id UUID;\n  v_user_role TEXT;\n\n  v_req public.enquiry_requests%ROWTYPE;\n  v_effective_status TEXT;\n  v_effective_waiting_for TEXT;\n  v_effective_requirement TEXT;\n  v_effective_parameters JSONB;\n  v_effective_assigned_to UUID;\n  v_effective_assigned_team TEXT;\n  v_effective_current_issue TEXT;\n  v_effective_next_action TEXT;\n  v_effective_response_text TEXT;\n  v_effective_response_value JSONB;\n  v_resolved_at TIMESTAMPTZ;\n  v_resolved_by UUID;\n  v_event_details JSONB;\nBEGIN\n  v_caller_role := auth.role();\n  v_caller_auth_uid := auth.uid();\n\n  IF v_caller_role = 'authenticated' THEN\n    SELECT role INTO v_user_role\n    FROM public.user_profiles\n    WHERE id = v_caller_auth_uid AND is_active = true;\n\n    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'sales') THEN\n      RAISE EXCEPTION 'Unauthorized: only active admin or sales users can update enquiry requests';\n    END IF;\n\n    -- Anti-spoofing guards\n    IF p_actor_type IS NOT NULL AND p_actor_type <> 'user' THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate AI or system';\n    END IF;\n\n    IF p_actor_id IS NOT NULL AND p_actor_id <> v_caller_auth_uid THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate other users';\n    END IF;\n\n    v_effective_actor_type := 'user';\n    v_effective_actor_id := v_caller_auth_uid;\n\n  ELSIF v_caller_role = 'service_role' THEN\n    IF p_actor_type NOT IN ('user', 'system', 'ai') THEN\n      RAISE EXCEPTION 'Invalid actor_type: must be user, system, or ai';\n    END IF;\n    v_effective_actor_type := p_actor_type;\n    v_effective_actor_id := p_actor_id;\n\n  ELSE\n    RAISE EXCEPTION 'Unauthorized: unauthenticated access rejected';\n  END IF;\n\n  -- Validate event_type check constraint\n  IF p_event_type NOT IN (\n    'created',\n    'requirement_changed',\n    'supplier_response',\n    'customer_decision',\n    'status_changed',\n    'waiting_for_changed',\n    'owner_reassigned',\n    'escalated',\n    'resolved',\n    'cancelled'\n  ) THEN\n    RAISE EXCEPTION 'Invalid event_type: %', p_event_type;\n  END IF;\n\n  -- Row lock target enquiry_requests record\n  SELECT * INTO v_req\n  FROM public.enquiry_requests\n  WHERE id = p_request_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Enquiry request not found: %', p_request_id;\n  END IF;\n\n  -- Stale proposal / concurrency check inside the transaction\n  IF p_expected_values IS NOT NULL AND p_expected_values <> '{}'::jsonb THEN\n    IF p_expected_values ? 'customer_requirement' THEN\n      IF trim(COALESCE(v_req.customer_requirement, '')) <> trim(COALESCE(p_expected_values->>'customer_requirement', '')) THEN\n        RAISE EXCEPTION 'STALE_PROPOSAL: customer_requirement has changed since AI suggestion was created (expected: \\"%\\", current: \\"%\\")',\n          p_expected_values->>'customer_requirement', v_req.customer_requirement\n          USING ERRCODE = 'P0001';\n      END IF;\n    END IF;\n\n    IF p_expected_values ? 'status' THEN\n      IF v_req.status <> (p_expected_values->>'status') THEN\n        RAISE EXCEPTION 'STALE_PROPOSAL: status has changed since AI suggestion was created (expected: \\"%\\", current: \\"%\\")',\n          p_expected_values->>'status', v_req.status\n          USING ERRCODE = 'P0001';\n      END IF;\n    END IF;\n\n    IF p_expected_values ? 'waiting_for' THEN\n      IF v_req.waiting_for <> (p_expected_values->>'waiting_for') THEN\n        RAISE EXCEPTION 'STALE_PROPOSAL: waiting_for has changed since AI suggestion was created (expected: \\"%\\", current: \\"%\\")',\n          p_expected_values->>'waiting_for', v_req.waiting_for\n          USING ERRCODE = 'P0001';\n      END IF;\n    END IF;\n\n    IF p_expected_values ? 'assigned_team' THEN\n      IF COALESCE(v_req.assigned_team, '') <> COALESCE(p_expected_values->>'assigned_team', '') THEN\n        RAISE EXCEPTION 'STALE_PROPOSAL: assigned_team has changed since AI suggestion was created (expected: \\"%\\", current: \\"%\\")',\n          p_expected_values->>'assigned_team', v_req.assigned_team\n          USING ERRCODE = 'P0001';\n      END IF;\n    END IF;\n  END IF;\n\n  -- Resolve effective state values\n  v_effective_status := COALESCE(p_new_status, v_req.status);\n  v_effective_waiting_for := COALESCE(p_new_waiting_for, v_req.waiting_for);\n  v_effective_requirement := COALESCE(p_new_requirement, v_req.customer_requirement);\n  v_effective_parameters := COALESCE(p_new_parameters, v_req.parameters);\n  v_effective_assigned_to := CASE WHEN p_new_assigned_to IS NOT NULL THEN p_new_assigned_to ELSE v_req.assigned_to END;\n  v_effective_assigned_team := CASE WHEN p_new_assigned_team IS NOT NULL THEN p_new_assigned_team ELSE v_req.assigned_team END;\n  v_effective_current_issue := CASE WHEN p_current_issue IS NOT NULL THEN p_current_issue ELSE v_req.current_issue END;\n  v_effective_next_action := CASE WHEN p_next_action IS NOT NULL THEN p_next_action ELSE v_req.next_action END;\n  v_effective_response_text := CASE WHEN p_response_text IS NOT NULL THEN p_response_text ELSE v_req.response_text END;\n  v_effective_response_value := CASE WHEN p_response_value IS NOT NULL THEN p_response_value ELSE v_req.response_value END;\n  v_resolved_at := v_req.resolved_at;\n  v_resolved_by := v_req.resolved_by;\n\n  -- State-specific validations\n  IF v_effective_status = 'RESOLVED' THEN\n    IF (v_effective_response_text IS NULL OR trim(v_effective_response_text) = '')\n       AND (v_effective_response_value IS NULL OR v_effective_response_value = '{}'::jsonb) THEN\n      RAISE EXCEPTION 'RESOLVED requests require response_text or response_value';\n    END IF;\n    v_effective_waiting_for := 'NONE';\n    v_resolved_at := now();\n    v_resolved_by := v_effective_actor_id;\n  END IF;\n\n  IF v_effective_status = 'BLOCKED' THEN\n    IF v_effective_waiting_for = 'NONE' THEN\n      RAISE EXCEPTION 'BLOCKED requests must specify waiting_for dependency (INTERNAL, INDIA, MANUFACTURER, CUSTOMER)';\n    END IF;\n    IF v_effective_current_issue IS NULL OR trim(v_effective_current_issue) = '' THEN\n      RAISE EXCEPTION 'BLOCKED requests must have a current_issue describing the impediment';\n    END IF;\n  END IF;\n\n  IF v_effective_status = 'CANCELLED' THEN\n    IF (v_effective_current_issue IS NULL OR trim(v_effective_current_issue) = '')\n       AND (p_details->>'cancellation_reason' IS NULL OR trim(p_details->>'cancellation_reason') = '') THEN\n      RAISE EXCEPTION 'CANCELLED requests must have a cancellation reason in current_issue or details.cancellation_reason';\n    END IF;\n  END IF;\n\n  IF v_effective_status = 'NOT_POSSIBLE' THEN\n    IF (v_effective_current_issue IS NULL OR trim(v_effective_current_issue) = '')\n       AND (p_details->>'reason' IS NULL OR trim(p_details->>'reason') = '') THEN\n      RAISE EXCEPTION 'NOT_POSSIBLE requests must have an explanation in current_issue or details.reason';\n    END IF;\n  END IF;\n\n  -- Build details diff\n  v_event_details := COALESCE(p_details, '{}'::jsonb);\n  IF p_new_requirement IS NOT NULL AND p_new_requirement <> v_req.customer_requirement THEN\n    v_event_details := v_event_details || jsonb_build_object(\n      'requirement_diff', jsonb_build_object('old', v_req.customer_requirement, 'new', p_new_requirement)\n    );\n  END IF;\n\n  -- Apply updates to enquiry_requests\n  UPDATE public.enquiry_requests\n  SET\n    status = v_effective_status,\n    waiting_for = v_effective_waiting_for,\n    customer_requirement = v_effective_requirement,\n    parameters = v_effective_parameters,\n    assigned_to = v_effective_assigned_to,\n    assigned_team = v_effective_assigned_team,\n    current_issue = v_effective_current_issue,\n    next_action = v_effective_next_action,\n    response_text = v_effective_response_text,\n    response_value = v_effective_response_value,\n    resolved_at = v_resolved_at,\n    resolved_by = v_resolved_by,\n    updated_at = now()\n  WHERE id = p_request_id;\n\n  -- Append event to enquiry_request_events\n  INSERT INTO public.enquiry_request_events (\n    request_id,\n    inquiry_id,\n    event_type,\n    summary,\n    old_status,\n    new_status,\n    old_waiting_for,\n    new_waiting_for,\n    details,\n    source_message_id,\n    actor_type,\n    actor_id\n  ) VALUES (\n    p_request_id,\n    v_req.inquiry_id,\n    p_event_type,\n    p_summary,\n    v_req.status,\n    v_effective_status,\n    v_req.waiting_for,\n    v_effective_waiting_for,\n    v_event_details,\n    p_source_message_id,\n    v_effective_actor_type,\n    v_effective_actor_id\n  );\n\n  -- Link provenance if source message provided\n  IF p_source_message_id IS NOT NULL THEN\n    INSERT INTO public.enquiry_request_messages (\n      request_id,\n      message_id,\n      relationship\n    ) VALUES (\n      p_request_id,\n      p_source_message_id,\n      CASE\n        WHEN v_effective_status = 'RESOLVED' THEN 'resolved'\n        WHEN v_effective_status = 'BLOCKED' THEN 'blocked'\n        ELSE 'clarified'\n      END\n    )\n    ON CONFLICT (request_id, message_id, relationship) DO NOTHING;\n  END IF;\n\nEND;\n$$","-- ============================================================================\n-- 2. Atomic Proposal Acceptance RPC (Locking + Concurrency + Stale Protection)\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.accept_enquiry_brain_proposal_atomic(\n  p_message_id UUID,\n  p_inquiry_id UUID,\n  p_expected_values JSONB DEFAULT NULL,\n  p_actor_type TEXT DEFAULT 'user',\n  p_actor_id UUID DEFAULT NULL\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_caller_role TEXT;\n  v_caller_auth_uid UUID;\n  v_effective_actor_type TEXT;\n  v_effective_actor_id UUID;\n  v_user_role TEXT;\n\n  v_msg public.enquiry_conversation_messages%ROWTYPE;\n  v_proposal JSONB;\n  v_proposal_status TEXT;\n  v_update JSONB;\n  v_req_id UUID;\n  v_req public.enquiry_requests%ROWTYPE;\n  v_field TEXT;\n  v_event_type TEXT;\n  v_new_req_val TEXT;\n  v_new_status_val TEXT;\n  v_new_waiting_val TEXT;\n  v_new_next_action TEXT;\n  v_new_team TEXT;\n\n  v_new_req_item JSONB;\n  v_created_req_id UUID;\n  v_req_code TEXT;\n  v_new_category TEXT;\n  v_new_title TEXT;\n  v_new_requirement_text TEXT;\n  v_new_params JSONB;\n  v_new_waiting TEXT;\n\n  v_updated_req_ids UUID[] := '{}';\n  v_created_req_ids UUID[] := '{}';\nBEGIN\n  v_caller_role := auth.role();\n  v_caller_auth_uid := auth.uid();\n\n  IF v_caller_role = 'authenticated' THEN\n    SELECT role INTO v_user_role\n    FROM public.user_profiles\n    WHERE id = v_caller_auth_uid AND is_active = true;\n\n    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'sales') THEN\n      RAISE EXCEPTION 'Unauthorized: only active admin or sales users can approve AI proposals';\n    END IF;\n\n    -- Anti-spoofing guards\n    IF p_actor_type IS NOT NULL AND p_actor_type <> 'user' THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate AI or system';\n    END IF;\n\n    IF p_actor_id IS NOT NULL AND p_actor_id <> v_caller_auth_uid THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate other users';\n    END IF;\n\n    v_effective_actor_type := 'user';\n    v_effective_actor_id := v_caller_auth_uid;\n\n  ELSIF v_caller_role = 'service_role' THEN\n    IF p_actor_type NOT IN ('user', 'system', 'ai') THEN\n      RAISE EXCEPTION 'Invalid actor_type: must be user, system, or ai';\n    END IF;\n    v_effective_actor_type := p_actor_type;\n    v_effective_actor_id := p_actor_id;\n\n  ELSE\n    RAISE EXCEPTION 'Unauthorized: unauthenticated access rejected';\n  END IF;\n\n  -- 1. Row lock the message record to serialize concurrent approvals\n  SELECT * INTO v_msg\n  FROM public.enquiry_conversation_messages\n  WHERE id = p_message_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Canonical message not found: %', p_message_id;\n  END IF;\n\n  v_proposal := v_msg.ai_proposal;\n  IF v_proposal IS NULL THEN\n    RAISE EXCEPTION 'Message % does not contain an AI proposal', p_message_id;\n  END IF;\n\n  -- 2. Concurrency / Idempotency check: strictly only 'suggested' can be accepted\n  v_proposal_status := v_proposal->>'status';\n  IF v_proposal_status IS NULL OR v_proposal_status <> 'suggested' THEN\n    RAISE EXCEPTION 'PROPOSAL_ALREADY_PROCESSED: AI proposal has already been processed (current status: %)', COALESCE(v_proposal_status, 'none')\n      USING ERRCODE = 'P0002';\n  END IF;\n\n  -- 3. Process proposed updates with inside-transaction stale checking\n  IF v_proposal ? 'proposed_updates' AND jsonb_typeof(v_proposal->'proposed_updates') = 'array' THEN\n    FOR v_update IN SELECT * FROM jsonb_array_elements(v_proposal->'proposed_updates')\n    LOOP\n      v_req_id := (v_update->>'request_id')::UUID;\n      IF v_req_id IS NULL THEN\n        RAISE EXCEPTION 'Missing request_id in proposed update';\n      END IF;\n\n      -- Lock target enquiry_requests record\n      SELECT * INTO v_req\n      FROM public.enquiry_requests\n      WHERE id = v_req_id\n      FOR UPDATE;\n\n      IF NOT FOUND THEN\n        RAISE EXCEPTION 'Target request % no longer exists', v_req_id;\n      END IF;\n\n      v_field := v_update->>'field';\n\n      -- Check stale condition against live row\n      IF v_update ? 'old_value' AND v_update->'old_value' IS NOT NULL AND v_update->>'old_value' <> 'null' THEN\n        IF v_field = 'customer_requirement' THEN\n          IF trim(COALESCE(v_req.customer_requirement, '')) <> trim(COALESCE(v_update->>'old_value', '')) THEN\n            RAISE EXCEPTION 'STALE_PROPOSAL: customer_requirement has changed since AI proposal was created (expected: \\"%\\", current: \\"%\\")',\n              v_update->>'old_value', v_req.customer_requirement\n              USING ERRCODE = 'P0001';\n          END IF;\n        ELSIF v_field = 'status' THEN\n          IF v_req.status <> (v_update->>'old_value') THEN\n            RAISE EXCEPTION 'STALE_PROPOSAL: status has changed since AI proposal was created (expected: \\"%\\", current: \\"%\\")',\n              v_update->>'old_value', v_req.status\n              USING ERRCODE = 'P0001';\n          END IF;\n        ELSIF v_field = 'waiting_for' THEN\n          IF v_req.waiting_for <> (v_update->>'old_value') THEN\n            RAISE EXCEPTION 'STALE_PROPOSAL: waiting_for has changed since AI proposal was created (expected: \\"%\\", current: \\"%\\")',\n              v_update->>'old_value', v_req.waiting_for\n              USING ERRCODE = 'P0001';\n          END IF;\n        ELSIF v_field = 'assigned_team' THEN\n          IF COALESCE(v_req.assigned_team, '') <> COALESCE(v_update->>'old_value', '') THEN\n            RAISE EXCEPTION 'STALE_PROPOSAL: assigned_team has changed since AI proposal was created (expected: \\"%\\", current: \\"%\\")',\n              v_update->>'old_value', v_req.assigned_team\n              USING ERRCODE = 'P0001';\n          END IF;\n        END IF;\n      END IF;\n\n      -- Check caller expected values if provided for this request\n      IF p_expected_values IS NOT NULL THEN\n        IF p_expected_values ? 'customer_requirement' AND trim(COALESCE(v_req.customer_requirement, '')) <> trim(COALESCE(p_expected_values->>'customer_requirement', '')) THEN\n          RAISE EXCEPTION 'STALE_PROPOSAL: customer_requirement has changed since AI proposal was created (expected: \\"%\\", current: \\"%\\")',\n            p_expected_values->>'customer_requirement', v_req.customer_requirement\n            USING ERRCODE = 'P0001';\n        END IF;\n        IF p_expected_values ? 'status' AND v_req.status <> (p_expected_values->>'status') THEN\n          RAISE EXCEPTION 'STALE_PROPOSAL: status has changed since AI proposal was created (expected: \\"%\\", current: \\"%\\")',\n            p_expected_values->>'status', v_req.status\n            USING ERRCODE = 'P0001';\n        END IF;\n        IF p_expected_values ? 'waiting_for' AND v_req.waiting_for <> (p_expected_values->>'waiting_for') THEN\n          RAISE EXCEPTION 'STALE_PROPOSAL: waiting_for has changed since AI proposal was created (expected: \\"%\\", current: \\"%\\")',\n            p_expected_values->>'waiting_for', v_req.waiting_for\n            USING ERRCODE = 'P0001';\n        END IF;\n      END IF;\n\n      -- Determine event type\n      v_event_type := CASE\n        WHEN v_proposal->>'intent' = 'customer_decision' THEN 'customer_decision'\n        WHEN v_proposal->>'intent' = 'requirement_change' OR v_field = 'customer_requirement' THEN 'requirement_changed'\n        WHEN v_proposal->>'intent' = 'supplier_response' THEN 'supplier_response'\n        ELSE 'status_changed'\n      END;\n\n      -- Compute effective new values\n      v_new_req_val := CASE WHEN v_field = 'customer_requirement' THEN v_update->>'new_value' ELSE v_req.customer_requirement END;\n      v_new_status_val := CASE WHEN v_field = 'status' THEN v_update->>'new_value' ELSE v_req.status END;\n      v_new_waiting_val := CASE\n        WHEN v_field = 'waiting_for' THEN v_update->>'new_value'\n        WHEN v_proposal->>'suggested_waiting_for' IS NOT NULL THEN v_proposal->>'suggested_waiting_for'\n        ELSE v_req.waiting_for\n      END;\n      v_new_next_action := CASE\n        WHEN v_field = 'next_action' THEN v_update->>'new_value'\n        WHEN v_proposal->>'suggested_next_action' IS NOT NULL THEN v_proposal->>'suggested_next_action'\n        ELSE v_req.next_action\n      END;\n      v_new_team := CASE\n        WHEN v_field = 'assigned_team' THEN v_update->>'new_value'\n        WHEN v_proposal->>'suggested_team' IS NOT NULL THEN v_proposal->>'suggested_team'\n        ELSE v_req.assigned_team\n      END;\n\n      -- Update enquiry_requests\n      UPDATE public.enquiry_requests\n      SET\n        customer_requirement = v_new_req_val,\n        status = v_new_status_val,\n        waiting_for = v_new_waiting_val,\n        next_action = v_new_next_action,\n        assigned_team = v_new_team,\n        ai_status = 'confirmed',\n        confirmed_by = v_effective_actor_id,\n        confirmed_at = now(),\n        updated_at = now()\n      WHERE id = v_req_id;\n\n      -- Insert immutable event\n      INSERT INTO public.enquiry_request_events (\n        request_id,\n        inquiry_id,\n        event_type,\n        summary,\n        old_status,\n        new_status,\n        old_waiting_for,\n        new_waiting_for,\n        details,\n        source_message_id,\n        actor_type,\n        actor_id\n      ) VALUES (\n        v_req_id,\n        v_req.inquiry_id,\n        v_event_type,\n        'AI Suggestion Accepted: ' || COALESCE(v_proposal->>'summary', ''),\n        v_req.status,\n        v_new_status_val,\n        v_req.waiting_for,\n        v_new_waiting_val,\n        jsonb_build_object(\n          'ai_proposal', v_proposal,\n          'decision', 'accepted',\n          'approved_field', v_field,\n          'old_value', v_update->'old_value',\n          'new_value', v_update->'new_value'\n        ),\n        p_message_id,\n        v_effective_actor_type,\n        v_effective_actor_id\n      );\n\n      -- Link provenance\n      INSERT INTO public.enquiry_request_messages (\n        request_id,\n        message_id,\n        relationship\n      ) VALUES (\n        v_req_id,\n        p_message_id,\n        'clarified'\n      )\n      ON CONFLICT (request_id, message_id, relationship) DO NOTHING;\n\n      v_updated_req_ids := array_append(v_updated_req_ids, v_req_id);\n    END LOOP;\n  END IF;\n\n  -- 4. Process proposed new requests (exactly once, atomic idempotency)\n  IF v_proposal ? 'proposed_new_requests' AND jsonb_typeof(v_proposal->'proposed_new_requests') = 'array' THEN\n    FOR v_new_req_item IN SELECT * FROM jsonb_array_elements(v_proposal->'proposed_new_requests')\n    LOOP\n      v_req_code := 'REQ-' || lpad(floor(random() * 10000)::text, 4, '0');\n      v_new_category := COALESCE(v_new_req_item->>'category', 'commercial');\n      v_new_title := COALESCE(v_new_req_item->>'title', 'New Request');\n      v_new_requirement_text := COALESCE(v_new_req_item->>'customer_requirement', '');\n      v_new_params := COALESCE(v_new_req_item->'parameters', '{}'::jsonb);\n      v_new_waiting := COALESCE(v_new_req_item->>'waiting_for', 'INTERNAL');\n      v_new_team := v_new_req_item->>'assigned_team';\n\n      INSERT INTO public.enquiry_requests (\n        inquiry_id,\n        category,\n        request_code,\n        title,\n        customer_requirement,\n        parameters,\n        assigned_to,\n        assigned_team,\n        due_at,\n        status,\n        waiting_for,\n        source_message_id,\n        ai_status,\n        ai_confidence,\n        ai_extracted_text\n      ) VALUES (\n        p_inquiry_id,\n        v_new_category,\n        v_req_code,\n        v_new_title,\n        v_new_requirement_text,\n        v_new_params,\n        NULL,\n        v_new_team,\n        NULL,\n        'OPEN',\n        v_new_waiting,\n        p_message_id,\n        'confirmed',\n        CASE WHEN v_proposal->>'confidence_tier' = 'HIGH' THEN 0.9 ELSE 0.7 END,\n        v_proposal->>'summary'\n      )\n      RETURNING id INTO v_created_req_id;\n\n      -- Append initial created event\n      INSERT INTO public.enquiry_request_events (\n        request_id,\n        inquiry_id,\n        event_type,\n        summary,\n        old_status,\n        new_status,\n        old_waiting_for,\n        new_waiting_for,\n        details,\n        source_message_id,\n        actor_type,\n        actor_id\n      ) VALUES (\n        v_created_req_id,\n        p_inquiry_id,\n        'created',\n        'Request created from AI suggestion: ' || v_new_title,\n        NULL,\n        'OPEN',\n        NULL,\n        v_new_waiting,\n        jsonb_build_object(\n          'ai_proposal', v_proposal,\n          'decision', 'accepted',\n          'initial_requirement', v_new_requirement_text,\n          'parameters', v_new_params\n        ),\n        p_message_id,\n        v_effective_actor_type,\n        v_effective_actor_id\n      );\n\n      -- Link provenance\n      INSERT INTO public.enquiry_request_messages (\n        request_id,\n        message_id,\n        relationship\n      ) VALUES (\n        v_created_req_id,\n        p_message_id,\n        'originated'\n      )\n      ON CONFLICT (request_id, message_id, relationship) DO NOTHING;\n\n      v_created_req_ids := array_append(v_created_req_ids, v_created_req_id);\n    END LOOP;\n  END IF;\n\n  -- 5. Mark proposal as accepted, preserving original proposal snapshot\n  UPDATE public.enquiry_conversation_messages\n  SET ai_proposal = v_proposal || jsonb_build_object(\n    'status', 'accepted',\n    'original_proposal', v_proposal,\n    'reviewed_by', v_effective_actor_id,\n    'reviewed_at', now()\n  )\n  WHERE id = p_message_id;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'status', 'accepted',\n    'updated_request_ids', v_updated_req_ids,\n    'created_request_ids', v_created_req_ids\n  );\nEND;\n$$","-- ============================================================================\n-- 3. Atomic Proposal Edit RPC (Human Correction + Preservation)\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.edit_enquiry_brain_proposal_atomic(\n  p_message_id UUID,\n  p_inquiry_id UUID,\n  p_edited_values JSONB,\n  p_expected_values JSONB DEFAULT NULL,\n  p_actor_type TEXT DEFAULT 'user',\n  p_actor_id UUID DEFAULT NULL\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_caller_role TEXT;\n  v_caller_auth_uid UUID;\n  v_effective_actor_type TEXT;\n  v_effective_actor_id UUID;\n  v_user_role TEXT;\n\n  v_msg public.enquiry_conversation_messages%ROWTYPE;\n  v_proposal JSONB;\n  v_proposal_status TEXT;\n  v_target_req_id UUID;\n  v_req public.enquiry_requests%ROWTYPE;\nBEGIN\n  v_caller_role := auth.role();\n  v_caller_auth_uid := auth.uid();\n\n  IF v_caller_role = 'authenticated' THEN\n    SELECT role INTO v_user_role\n    FROM public.user_profiles\n    WHERE id = v_caller_auth_uid AND is_active = true;\n\n    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'sales') THEN\n      RAISE EXCEPTION 'Unauthorized: only active admin or sales users can edit AI proposals';\n    END IF;\n\n    IF p_actor_type IS NOT NULL AND p_actor_type <> 'user' THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate AI or system';\n    END IF;\n\n    IF p_actor_id IS NOT NULL AND p_actor_id <> v_caller_auth_uid THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate other users';\n    END IF;\n\n    v_effective_actor_type := 'user';\n    v_effective_actor_id := v_caller_auth_uid;\n\n  ELSIF v_caller_role = 'service_role' THEN\n    IF p_actor_type NOT IN ('user', 'system', 'ai') THEN\n      RAISE EXCEPTION 'Invalid actor_type: must be user, system, or ai';\n    END IF;\n    v_effective_actor_type := p_actor_type;\n    v_effective_actor_id := p_actor_id;\n\n  ELSE\n    RAISE EXCEPTION 'Unauthorized: unauthenticated access rejected';\n  END IF;\n\n  -- Lock message record\n  SELECT * INTO v_msg\n  FROM public.enquiry_conversation_messages\n  WHERE id = p_message_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Canonical message not found: %', p_message_id;\n  END IF;\n\n  v_proposal := v_msg.ai_proposal;\n  IF v_proposal IS NULL THEN\n    RAISE EXCEPTION 'Message % does not contain an AI proposal', p_message_id;\n  END IF;\n\n  v_proposal_status := v_proposal->>'status';\n  IF v_proposal_status IS NULL OR v_proposal_status <> 'suggested' THEN\n    RAISE EXCEPTION 'PROPOSAL_ALREADY_PROCESSED: AI proposal has already been processed (current status: %)', COALESCE(v_proposal_status, 'none')\n      USING ERRCODE = 'P0002';\n  END IF;\n\n  -- If editing an existing request, apply changes under row lock\n  IF p_edited_values ? 'target_request_id' AND p_edited_values->>'target_request_id' IS NOT NULL THEN\n    v_target_req_id := (p_edited_values->>'target_request_id')::UUID;\n\n    SELECT * INTO v_req\n    FROM public.enquiry_requests\n    WHERE id = v_target_req_id\n    FOR UPDATE;\n\n    IF NOT FOUND THEN\n      RAISE EXCEPTION 'Target request % not found', v_target_req_id;\n    END IF;\n\n    -- Stale check if expected values passed\n    IF p_expected_values IS NOT NULL THEN\n      IF p_expected_values ? 'customer_requirement' AND trim(COALESCE(v_req.customer_requirement, '')) <> trim(COALESCE(p_expected_values->>'customer_requirement', '')) THEN\n        RAISE EXCEPTION 'STALE_PROPOSAL: customer_requirement has changed since AI suggestion was created (expected: \\"%\\", current: \\"%\\")',\n          p_expected_values->>'customer_requirement', v_req.customer_requirement\n          USING ERRCODE = 'P0001';\n      END IF;\n      IF p_expected_values ? 'status' AND v_req.status <> (p_expected_values->>'status') THEN\n        RAISE EXCEPTION 'STALE_PROPOSAL: status has changed since AI suggestion was created (expected: \\"%\\", current: \\"%\\")',\n          p_expected_values->>'status', v_req.status\n          USING ERRCODE = 'P0001';\n      END IF;\n      IF p_expected_values ? 'waiting_for' AND v_req.waiting_for <> (p_expected_values->>'waiting_for') THEN\n        RAISE EXCEPTION 'STALE_PROPOSAL: waiting_for has changed since AI suggestion was created (expected: \\"%\\", current: \\"%\\")',\n          p_expected_values->>'waiting_for', v_req.waiting_for\n          USING ERRCODE = 'P0001';\n      END IF;\n    END IF;\n\n    -- Update request with human-edited values\n    UPDATE public.enquiry_requests\n    SET\n      customer_requirement = COALESCE(p_edited_values->>'customer_requirement', v_req.customer_requirement),\n      status = COALESCE(p_edited_values->>'status', v_req.status),\n      waiting_for = COALESCE(p_edited_values->>'waiting_for', v_req.waiting_for),\n      next_action = CASE WHEN p_edited_values ? 'next_action' THEN p_edited_values->>'next_action' ELSE v_req.next_action END,\n      assigned_team = CASE WHEN p_edited_values ? 'assigned_team' THEN p_edited_values->>'assigned_team' ELSE v_req.assigned_team END,\n      ai_status = 'edited',\n      confirmed_by = v_effective_actor_id,\n      confirmed_at = now(),\n      updated_at = now()\n    WHERE id = v_target_req_id;\n\n    -- Append event\n    INSERT INTO public.enquiry_request_events (\n      request_id,\n      inquiry_id,\n      event_type,\n      summary,\n      old_status,\n      new_status,\n      old_waiting_for,\n      new_waiting_for,\n      details,\n      source_message_id,\n      actor_type,\n      actor_id\n    ) VALUES (\n      v_target_req_id,\n      v_req.inquiry_id,\n      'requirement_changed',\n      COALESCE(p_edited_values->>'summary', 'Human-Edited AI Suggestion: ' || COALESCE(v_proposal->>'summary', '')),\n      v_req.status,\n      COALESCE(p_edited_values->>'status', v_req.status),\n      v_req.waiting_for,\n      COALESCE(p_edited_values->>'waiting_for', v_req.waiting_for),\n      jsonb_build_object(\n        'ai_proposal', v_proposal,\n        'decision', 'edited',\n        'edited_values', p_edited_values,\n        'original_proposal', v_proposal\n      ),\n      p_message_id,\n      v_effective_actor_type,\n      v_effective_actor_id\n    );\n\n    -- Provenance\n    INSERT INTO public.enquiry_request_messages (\n      request_id,\n      message_id,\n      relationship\n    ) VALUES (\n      v_target_req_id,\n      p_message_id,\n      'clarified'\n    )\n    ON CONFLICT (request_id, message_id, relationship) DO NOTHING;\n  END IF;\n\n  -- Mark proposal as edited with original snapshot preserved\n  UPDATE public.enquiry_conversation_messages\n  SET ai_proposal = v_proposal || jsonb_build_object(\n    'status', 'edited',\n    'original_proposal', v_proposal,\n    'edited_values', p_edited_values,\n    'reviewed_by', v_effective_actor_id,\n    'reviewed_at', now()\n  )\n  WHERE id = p_message_id;\n\n  RETURN jsonb_build_object('success', true, 'status', 'edited');\nEND;\n$$","-- ============================================================================\n-- 4. Atomic Proposal Dismiss RPC (Zero Business Mutation)\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.dismiss_enquiry_brain_proposal_atomic(\n  p_message_id UUID,\n  p_actor_type TEXT DEFAULT 'user',\n  p_actor_id UUID DEFAULT NULL\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_caller_role TEXT;\n  v_caller_auth_uid UUID;\n  v_effective_actor_type TEXT;\n  v_effective_actor_id UUID;\n  v_user_role TEXT;\n\n  v_msg public.enquiry_conversation_messages%ROWTYPE;\n  v_proposal JSONB;\n  v_proposal_status TEXT;\nBEGIN\n  v_caller_role := auth.role();\n  v_caller_auth_uid := auth.uid();\n\n  IF v_caller_role = 'authenticated' THEN\n    SELECT role INTO v_user_role\n    FROM public.user_profiles\n    WHERE id = v_caller_auth_uid AND is_active = true;\n\n    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'sales') THEN\n      RAISE EXCEPTION 'Unauthorized: only active admin or sales users can dismiss AI proposals';\n    END IF;\n\n    IF p_actor_type IS NOT NULL AND p_actor_type <> 'user' THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate AI or system';\n    END IF;\n\n    IF p_actor_id IS NOT NULL AND p_actor_id <> v_caller_auth_uid THEN\n      RAISE EXCEPTION 'Unauthorized: authenticated users cannot impersonate other users';\n    END IF;\n\n    v_effective_actor_type := 'user';\n    v_effective_actor_id := v_caller_auth_uid;\n\n  ELSIF v_caller_role = 'service_role' THEN\n    IF p_actor_type NOT IN ('user', 'system', 'ai') THEN\n      RAISE EXCEPTION 'Invalid actor_type: must be user, system, or ai';\n    END IF;\n    v_effective_actor_type := p_actor_type;\n    v_effective_actor_id := p_actor_id;\n\n  ELSE\n    RAISE EXCEPTION 'Unauthorized: unauthenticated access rejected';\n  END IF;\n\n  -- Lock message record\n  SELECT * INTO v_msg\n  FROM public.enquiry_conversation_messages\n  WHERE id = p_message_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Canonical message not found: %', p_message_id;\n  END IF;\n\n  v_proposal := v_msg.ai_proposal;\n  IF v_proposal IS NULL THEN\n    RAISE EXCEPTION 'Message % does not contain an AI proposal', p_message_id;\n  END IF;\n\n  v_proposal_status := v_proposal->>'status';\n  IF v_proposal_status IS NULL OR v_proposal_status <> 'suggested' THEN\n    RAISE EXCEPTION 'PROPOSAL_ALREADY_PROCESSED: AI proposal has already been processed (current status: %)', COALESCE(v_proposal_status, 'none')\n      USING ERRCODE = 'P0002';\n  END IF;\n\n  -- Mark proposal as dismissed with original proposal preserved; zero mutation to enquiry_requests or crm_inquiries\n  UPDATE public.enquiry_conversation_messages\n  SET ai_proposal = v_proposal || jsonb_build_object(\n    'status', 'dismissed',\n    'original_proposal', v_proposal,\n    'dismissed_by', v_effective_actor_id,\n    'dismissed_at', now()\n  )\n  WHERE id = p_message_id;\n\n  RETURN jsonb_build_object('success', true, 'status', 'dismissed');\nEND;\n$$","-- ============================================================================\n-- 5. RPC Security Grants\n-- ============================================================================\nREVOKE ALL ON FUNCTION public.transition_enquiry_request_atomic FROM PUBLIC","REVOKE ALL ON FUNCTION public.accept_enquiry_brain_proposal_atomic FROM PUBLIC","REVOKE ALL ON FUNCTION public.edit_enquiry_brain_proposal_atomic FROM PUBLIC","REVOKE ALL ON FUNCTION public.dismiss_enquiry_brain_proposal_atomic FROM PUBLIC","REVOKE EXECUTE ON FUNCTION public.transition_enquiry_request_atomic FROM anon","REVOKE EXECUTE ON FUNCTION public.accept_enquiry_brain_proposal_atomic FROM anon","REVOKE EXECUTE ON FUNCTION public.edit_enquiry_brain_proposal_atomic FROM anon","REVOKE EXECUTE ON FUNCTION public.dismiss_enquiry_brain_proposal_atomic FROM anon","GRANT EXECUTE ON FUNCTION public.transition_enquiry_request_atomic TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.accept_enquiry_brain_proposal_atomic TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.edit_enquiry_brain_proposal_atomic TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.dismiss_enquiry_brain_proposal_atomic TO authenticated, service_role",COMMIT}	enquiry_brain_review_gate_hardening	\N	\N	\N
20260914230000	{"-- ============================================================================\n-- Migration: 20260914230000_enquiry_brain_completion_76d_76e.sql\n-- Description: Phase 7.6D (AI Reply Drafter) and Phase 7.6E (Document Intelligence)\n--\n-- 1. Adds ai_reply_draft to public.enquiry_conversation_messages\n-- 2. Adds ai_extraction to public.crm_product_documents\n-- 3. Updates fn_protect_enquiry_message_content to permit ai_reply_draft updates\n-- 4. Creates atomic document review RPCs:\n--    - accept_document_extraction_atomic\n--    - edit_document_extraction_atomic\n--    - dismiss_document_extraction_atomic\n-- ============================================================================\n\n-- 1. Add ai_reply_draft column to enquiry_conversation_messages\nALTER TABLE public.enquiry_conversation_messages\nADD COLUMN IF NOT EXISTS ai_reply_draft JSONB DEFAULT NULL","-- 2. Add ai_extraction column to crm_product_documents\nALTER TABLE public.crm_product_documents\nADD COLUMN IF NOT EXISTS ai_extraction JSONB DEFAULT NULL","-- 3. Update message content immutability trigger to permit ai_reply_draft\nCREATE OR REPLACE FUNCTION public.fn_protect_enquiry_message_content()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  -- Content fields must be immutable. Only ai_processed, ai_summary, ai_proposal, and ai_reply_draft may change.\n  IF NEW.id IS DISTINCT FROM OLD.id\n     OR NEW.channel IS DISTINCT FROM OLD.channel\n     OR NEW.direction IS DISTINCT FROM OLD.direction\n     OR NEW.external_message_id IS DISTINCT FROM OLD.external_message_id\n     OR NEW.sender_address IS DISTINCT FROM OLD.sender_address\n     OR NEW.recipient_addresses IS DISTINCT FROM OLD.recipient_addresses\n     OR NEW.subject IS DISTINCT FROM OLD.subject\n     OR NEW.body_text IS DISTINCT FROM OLD.body_text\n     OR NEW.body_html IS DISTINCT FROM OLD.body_html\n     OR NEW.attachments IS DISTINCT FROM OLD.attachments\n     OR NEW.received_or_sent_at IS DISTINCT FROM OLD.received_or_sent_at\n     OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id\n  THEN\n    RAISE EXCEPTION 'Communication content in enquiry_conversation_messages is immutable';\n  END IF;\n  RETURN NEW;\nEND;\n$$","-- 4. Atomic Document Review RPC: Accept\nCREATE OR REPLACE FUNCTION public.accept_document_extraction_atomic(\n  p_document_id UUID,\n  p_actor_id UUID,\n  p_apply_to_request_id UUID DEFAULT NULL\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_doc public.crm_product_documents%ROWTYPE;\n  v_extraction JSONB;\n  v_status TEXT;\n  v_now TIMESTAMPTZ := clock_timestamp();\nBEGIN\n  -- Lock the document row\n  SELECT * INTO v_doc\n  FROM public.crm_product_documents\n  WHERE id = p_document_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'DOCUMENT_NOT_FOUND: Document % not found', p_document_id;\n  END IF;\n\n  v_extraction := v_doc.ai_extraction;\n  IF v_extraction IS NULL THEN\n    RAISE EXCEPTION 'NO_EXTRACTION: No AI extraction exists for document %', p_document_id;\n  END IF;\n\n  v_status := v_extraction->>'status';\n  IF v_status IN ('accepted', 'dismissed') THEN\n    RAISE EXCEPTION 'DOCUMENT_ALREADY_PROCESSED: Extraction for document % has already been reviewed (status: %)', p_document_id, v_status;\n  END IF;\n\n  -- If request linking is requested, associate document with the request if not already linked\n  IF p_apply_to_request_id IS NOT NULL THEN\n    UPDATE public.crm_product_documents\n    SET enquiry_request_id = p_apply_to_request_id\n    WHERE id = p_document_id AND enquiry_request_id IS NULL;\n  END IF;\n\n  -- Update extraction status to accepted, recording human reviewer and timestamp\n  UPDATE public.crm_product_documents\n  SET ai_extraction = jsonb_set(\n    jsonb_set(\n      jsonb_set(\n        v_extraction,\n        '{status}',\n        '\\"accepted\\"'::jsonb\n      ),\n      '{reviewed_by}',\n      to_jsonb(p_actor_id::text)\n    ),\n    '{reviewed_at}',\n    to_jsonb(v_now::text)\n  )\n  WHERE id = p_document_id;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'document_id', p_document_id,\n    'status', 'accepted',\n    'reviewed_at', v_now\n  );\nEND;\n$$","-- 5. Atomic Document Review RPC: Edit\nCREATE OR REPLACE FUNCTION public.edit_document_extraction_atomic(\n  p_document_id UUID,\n  p_actor_id UUID,\n  p_edited_values JSONB\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_doc public.crm_product_documents%ROWTYPE;\n  v_extraction JSONB;\n  v_status TEXT;\n  v_original JSONB;\n  v_now TIMESTAMPTZ := clock_timestamp();\nBEGIN\n  -- Lock the document row\n  SELECT * INTO v_doc\n  FROM public.crm_product_documents\n  WHERE id = p_document_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'DOCUMENT_NOT_FOUND: Document % not found', p_document_id;\n  END IF;\n\n  v_extraction := v_doc.ai_extraction;\n  IF v_extraction IS NULL THEN\n    RAISE EXCEPTION 'NO_EXTRACTION: No AI extraction exists for document %', p_document_id;\n  END IF;\n\n  v_status := v_extraction->>'status';\n  IF v_status IN ('accepted', 'dismissed') THEN\n    RAISE EXCEPTION 'DOCUMENT_ALREADY_PROCESSED: Extraction for document % has already been reviewed (status: %)', p_document_id, v_status;\n  END IF;\n\n  -- Preserve original extraction if not already preserved\n  v_original := COALESCE(v_extraction->'original_extraction', v_extraction);\n\n  -- Update with human edits\n  UPDATE public.crm_product_documents\n  SET ai_extraction = jsonb_set(\n    jsonb_set(\n      jsonb_set(\n        jsonb_set(\n          jsonb_set(\n            v_extraction,\n            '{status}',\n            '\\"edited\\"'::jsonb\n          ),\n          '{reviewed_by}',\n          to_jsonb(p_actor_id::text)\n        ),\n        '{reviewed_at}',\n        to_jsonb(v_now::text)\n      ),\n      '{edited_values}',\n      p_edited_values\n    ),\n    '{original_extraction}',\n    v_original\n  )\n  WHERE id = p_document_id;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'document_id', p_document_id,\n    'status', 'edited',\n    'reviewed_at', v_now\n  );\nEND;\n$$","-- 6. Atomic Document Review RPC: Dismiss\nCREATE OR REPLACE FUNCTION public.dismiss_document_extraction_atomic(\n  p_document_id UUID,\n  p_actor_id UUID\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_doc public.crm_product_documents%ROWTYPE;\n  v_extraction JSONB;\n  v_status TEXT;\n  v_now TIMESTAMPTZ := clock_timestamp();\nBEGIN\n  -- Lock the document row\n  SELECT * INTO v_doc\n  FROM public.crm_product_documents\n  WHERE id = p_document_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'DOCUMENT_NOT_FOUND: Document % not found', p_document_id;\n  END IF;\n\n  v_extraction := v_doc.ai_extraction;\n  IF v_extraction IS NULL THEN\n    RAISE EXCEPTION 'NO_EXTRACTION: No AI extraction exists for document %', p_document_id;\n  END IF;\n\n  v_status := v_extraction->>'status';\n  IF v_status IN ('accepted', 'dismissed') THEN\n    RAISE EXCEPTION 'DOCUMENT_ALREADY_PROCESSED: Extraction for document % has already been reviewed (status: %)', p_document_id, v_status;\n  END IF;\n\n  UPDATE public.crm_product_documents\n  SET ai_extraction = jsonb_set(\n    jsonb_set(\n      jsonb_set(\n        v_extraction,\n        '{status}',\n        '\\"dismissed\\"'::jsonb\n      ),\n      '{dismissed_by}',\n      to_jsonb(p_actor_id::text)\n    ),\n    '{dismissed_at}',\n    to_jsonb(v_now::text)\n  )\n  WHERE id = p_document_id;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'document_id', p_document_id,\n    'status', 'dismissed',\n    'dismissed_at', v_now\n  );\nEND;\n$$","-- Grants\nGRANT EXECUTE ON FUNCTION public.accept_document_extraction_atomic(UUID, UUID, UUID) TO authenticated","GRANT EXECUTE ON FUNCTION public.edit_document_extraction_atomic(UUID, UUID, JSONB) TO authenticated","GRANT EXECUTE ON FUNCTION public.dismiss_document_extraction_atomic(UUID, UUID) TO authenticated"}	enquiry_brain_completion_76d_76e	\N	\N	\N
20260915163000	{"-- Migration: Fix Tax Compliance RLS Policies for Accounts Role\n-- Description: Grants write permissions on tax_payment_files, tax_payments, and tax_periods\n--              to 'accounts' role (and warehouse with tax-compliance permission),\n--              matching the permissions already configured on faktur_pajak and faktur_pajak_files.\n\n-- 1. tax_payment_files --------------------------------------------------------\nDROP POLICY IF EXISTS \\"tax_payment_files_write\\" ON public.tax_payment_files","CREATE POLICY \\"tax_payment_files_write\\" ON public.tax_payment_files\nFOR ALL TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.user_profiles up\n    WHERE up.id = (SELECT auth.uid())\n      AND up.is_active = true\n      AND (\n        up.role = ANY (ARRAY['admin'::text, 'manager'::text, 'accounts'::text])\n        OR (\n          up.role = 'warehouse'::text AND EXISTS (\n            SELECT 1 FROM public.user_permissions permission\n            WHERE permission.user_id = up.id\n              AND permission.module = 'tax-compliance'::text\n              AND permission.can_access = true\n          )\n        )\n      )\n  )\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.user_profiles up\n    WHERE up.id = (SELECT auth.uid())\n      AND up.is_active = true\n      AND (\n        up.role = ANY (ARRAY['admin'::text, 'manager'::text, 'accounts'::text])\n        OR (\n          up.role = 'warehouse'::text AND EXISTS (\n            SELECT 1 FROM public.user_permissions permission\n            WHERE permission.user_id = up.id\n              AND permission.module = 'tax-compliance'::text\n              AND permission.can_access = true\n          )\n        )\n      )\n  )\n)","-- 2. tax_payments -------------------------------------------------------------\nDROP POLICY IF EXISTS \\"tax_payments_write\\" ON public.tax_payments","CREATE POLICY \\"tax_payments_write\\" ON public.tax_payments\nFOR ALL TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.user_profiles up\n    WHERE up.id = (SELECT auth.uid())\n      AND up.is_active = true\n      AND (\n        up.role = ANY (ARRAY['admin'::text, 'manager'::text, 'accounts'::text])\n        OR (\n          up.role = 'warehouse'::text AND EXISTS (\n            SELECT 1 FROM public.user_permissions permission\n            WHERE permission.user_id = up.id\n              AND permission.module = 'tax-compliance'::text\n              AND permission.can_access = true\n          )\n        )\n      )\n  )\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.user_profiles up\n    WHERE up.id = (SELECT auth.uid())\n      AND up.is_active = true\n      AND (\n        up.role = ANY (ARRAY['admin'::text, 'manager'::text, 'accounts'::text])\n        OR (\n          up.role = 'warehouse'::text AND EXISTS (\n            SELECT 1 FROM public.user_permissions permission\n            WHERE permission.user_id = up.id\n              AND permission.module = 'tax-compliance'::text\n              AND permission.can_access = true\n          )\n        )\n      )\n  )\n)","-- 3. tax_periods --------------------------------------------------------------\nDROP POLICY IF EXISTS \\"tax_periods_write\\" ON public.tax_periods","CREATE POLICY \\"tax_periods_write\\" ON public.tax_periods\nFOR ALL TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.user_profiles up\n    WHERE up.id = (SELECT auth.uid())\n      AND up.is_active = true\n      AND (\n        up.role = ANY (ARRAY['admin'::text, 'manager'::text, 'accounts'::text])\n        OR (\n          up.role = 'warehouse'::text AND EXISTS (\n            SELECT 1 FROM public.user_permissions permission\n            WHERE permission.user_id = up.id\n              AND permission.module = 'tax-compliance'::text\n              AND permission.can_access = true\n          )\n        )\n      )\n  )\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.user_profiles up\n    WHERE up.id = (SELECT auth.uid())\n      AND up.is_active = true\n      AND (\n        up.role = ANY (ARRAY['admin'::text, 'manager'::text, 'accounts'::text])\n        OR (\n          up.role = 'warehouse'::text AND EXISTS (\n            SELECT 1 FROM public.user_permissions permission\n            WHERE permission.user_id = up.id\n              AND permission.module = 'tax-compliance'::text\n              AND permission.can_access = true\n          )\n        )\n      )\n  )\n)"}	fix_tax_compliance_rls_policies_for_accounts	\N	\N	\N
20260924124230	{"CREATE OR REPLACE VIEW public.dc_item_invoice_status AS\nSELECT\n  dci.id AS dc_item_id,\n  dci.challan_id,\n  dc.challan_number,\n  dc.challan_date,\n  dc.customer_id,\n  c.company_name AS customer_name,\n  dci.product_id,\n  p.product_name,\n  dci.batch_id,\n  b.batch_number,\n  dci.quantity AS original_quantity,\n  p.unit,\n  dci.pack_size,\n  dci.pack_type,\n  dci.number_of_packs,\n  COALESCE(sum(sii.quantity), 0::numeric) AS invoiced_quantity,\n  dci.quantity - COALESCE(sum(sii.quantity), 0::numeric) AS remaining_quantity,\n  CASE\n    WHEN COALESCE(sum(sii.quantity), 0::numeric) = 0::numeric THEN 'not_invoiced'::text\n    WHEN COALESCE(sum(sii.quantity), 0::numeric) >= dci.quantity THEN 'fully_invoiced'::text\n    ELSE 'partially_invoiced'::text\n  END AS status,\n  array_agg(DISTINCT si.invoice_number ORDER BY si.invoice_number) FILTER (WHERE si.invoice_number IS NOT NULL) AS invoice_numbers,\n  count(DISTINCT sii.invoice_id) AS invoice_count\nFROM delivery_challan_items dci\nJOIN delivery_challans dc ON dci.challan_id = dc.id\nLEFT JOIN customers c ON dc.customer_id = c.id\nLEFT JOIN products p ON dci.product_id = p.id\nLEFT JOIN batches b ON dci.batch_id = b.id\nLEFT JOIN sales_invoice_items sii ON dci.id = sii.delivery_challan_item_id\nLEFT JOIN sales_invoices si ON sii.invoice_id = si.id\nWHERE dc.approval_status = 'approved'::dc_approval_status\nGROUP BY dci.id, dci.challan_id, dc.challan_number, dc.challan_date, dc.customer_id, c.company_name, dci.product_id, p.product_name, p.unit, dci.batch_id, b.batch_number, dci.quantity, dci.pack_size, dci.pack_type, dci.number_of_packs;"}	fix_dc_invoice_status_exclude_nonapproved	simplykool@gmail.com	\N	\N
20261112174607	{"\nALTER TABLE public.crm_contacts\n  ADD COLUMN IF NOT EXISTS updated_by uuid\n  REFERENCES public.user_profiles(id) ON DELETE SET NULL;\n\nCREATE INDEX IF NOT EXISTS idx_crm_contacts_updated_by\n  ON public.crm_contacts(updated_by);\n\nCREATE OR REPLACE FUNCTION public.set_crm_contacts_updated_metadata()\nRETURNS trigger\nLANGUAGE plpgsql\nSET search_path = public\nAS $$\nBEGIN\n  NEW.updated_at := now();\n  IF auth.uid() IS NOT NULL THEN\n    NEW.updated_by := auth.uid();\n  END IF;\n  RETURN NEW;\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS set_crm_contacts_updated_metadata ON public.crm_contacts;\nCREATE TRIGGER set_crm_contacts_updated_metadata\nBEFORE UPDATE ON public.crm_contacts\nFOR EACH ROW\nEXECUTE FUNCTION public.set_crm_contacts_updated_metadata();\n"}	crm_contacts_updated_by_tracking	simplykool@gmail.com	\N	\N
20261114093106	{"CREATE OR REPLACE FUNCTION public.fn_pph_authoritative_source_total(p_period_id uuid)\n RETURNS numeric\n LANGUAGE sql\n STABLE\n SET search_path TO 'public'\nAS $function$\n  WITH period AS (\n    SELECT id, fiscal_year, period_month, tax_type, period_start, period_end\n      FROM public.tax_periods WHERE id = p_period_id AND tax_type <> 'PPN'\n  )\n  -- (a) Genuine withholding on expenses (where pph_amount > 0).\n  -- Import PPh 22 is an advance tax, not a monthly withholding liability.\n  SELECT COALESCE((\n    SELECT SUM(fe.pph_amount)\n      FROM period p\n      JOIN public.finance_expenses fe\n        ON (fe.pph_tax_period_id = p.id\n            OR (p.tax_type = 'PPh_Unifikasi' AND EXISTS (\n                SELECT 1 FROM public.tax_periods p_sub\n                 WHERE p_sub.id = fe.pph_tax_period_id\n                   AND p_sub.fiscal_year = p.fiscal_year\n                   AND p_sub.period_month = p.period_month\n            ))\n            OR (fe.pph_tax_period_id IS NULL\n                AND COALESCE(fe.paid_amount, 0) > 0\n                AND fe.expense_date BETWEEN p.period_start AND p.period_end))\n      JOIN public.effective_expense_posting_state eps ON eps.expense_id = fe.id\n       AND eps.effective_posting_state IN ('ACTIVE','REPLACED')\n      LEFT JOIN public.tax_codes tc ON tc.id = fe.pph_code_id\n     WHERE fe.approval_status = 'approved' AND fe.pph_amount > 0\n       AND COALESCE(fe.expense_category,'') NOT IN ('pib_import','pph_import')\n       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)\n  ),0)\n  -- (b) Genuine withholding on posted payment vouchers.\n  + COALESCE((\n    SELECT SUM(pv.pph_amount) FROM period p\n      JOIN public.payment_vouchers pv ON (pv.tax_period_id = p.id\n        OR (p.tax_type = 'PPh_Unifikasi' AND EXISTS (\n            SELECT 1 FROM public.tax_periods p_sub\n             WHERE p_sub.id = pv.tax_period_id\n               AND p_sub.fiscal_year = p.fiscal_year\n               AND p_sub.period_month = p.period_month\n        ))\n        OR (pv.tax_period_id IS NULL AND pv.voucher_date BETWEEN p.period_start AND p.period_end))\n      LEFT JOIN public.tax_codes tc ON tc.id = pv.pph_code_id\n     WHERE COALESCE(pv.is_posted,false) AND pv.pph_amount > 0\n       AND (p.tax_type = 'PPh_Unifikasi' OR tc.tax_type = p.tax_type)\n  ),0)\n  -- (c) Historical verified tax payments with missing source.\n  + COALESCE((\n    SELECT SUM(tp.amount) FROM period p\n      JOIN public.tax_payments tp ON tp.tax_period_id = p.id\n     WHERE (p.tax_type = 'PPh_Unifikasi' OR tp.tax_type = p.tax_type)\n       AND tp.historical_source_status = 'missing_source_verified'\n  ),0);\n$function$;"}	pph_null_unallocated_unpaid_exclusions	simplykool@gmail.com	\N	\N
20260915170000	{"-- ============================================================================\n-- Migration: Fix Delivery Challan Creation & Approval for Sales Orders\n-- Description:\n-- 1. Updates validate_dc_item_product_reservation_v2 to validate delivery\n--    quantity against the canonical remaining Sales Order deliverable quantity\n--    (quantity - delivered_quantity minus pending DCs) rather than requiring\n--    an existing active stock reservation, enabling delivery of orders created\n--    under shortage once physical batch stock is available.\n-- 2. Updates consume_so_product_reservation_v2 to safely consume active\n--    reservations when present, or create a consumed reservation audit record\n--    when delivering unreserved/shortage orders, ensuring 100% FK integrity,\n--    inventory deduction, and accurate SO delivered quantity tracking.\n-- ============================================================================\n\nBEGIN","-- 1. Update validate_dc_item_product_reservation_v2 trigger function\nCREATE OR REPLACE FUNCTION public.validate_dc_item_product_reservation_v2()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_dc record;\n  v_so_item record;\n  v_pending numeric;\n  v_remaining numeric;\n  v_so_make uuid;\n  v_batch_make uuid;\nBEGIN\n  SELECT dc.sales_order_id, dc.approval_status INTO v_dc\n  FROM public.delivery_challans dc\n  WHERE dc.id = NEW.challan_id;\n\n  IF NOT FOUND OR NEW.sales_order_item_id IS NULL THEN\n    RAISE EXCEPTION 'DC item requires a canonical SO item';\n  END IF;\n\n  SELECT soi.make_id, soi.quantity, soi.delivered_quantity INTO v_so_make, v_so_item.quantity, v_so_item.delivered_quantity\n  FROM public.sales_order_items soi\n  WHERE soi.id = NEW.sales_order_item_id\n    AND soi.sales_order_id = v_dc.sales_order_id\n    AND soi.product_id = NEW.product_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'DC product does not match its SO item';\n  END IF;\n\n  SELECT b.make_id INTO v_batch_make\n  FROM public.batches b\n  WHERE b.id = NEW.batch_id\n    AND b.product_id = NEW.product_id\n    AND b.is_active = true\n    AND (b.expiry_date IS NULL OR b.expiry_date > CURRENT_DATE);\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Selected DC batch is not eligible for this product';\n  END IF;\n\n  -- NULL Make preserves historical records; known Make must match exactly.\n  IF v_so_make IS NOT NULL AND v_batch_make IS DISTINCT FROM v_so_make THEN\n    RAISE EXCEPTION 'Selected DC batch Make does not match the Sales Order Make';\n  END IF;\n\n  -- Validate against remaining deliverable Sales Order quantity (including other pending draft DCs)\n  SELECT COALESCE(sum(dci.quantity), 0) INTO v_pending\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  WHERE dci.sales_order_item_id = NEW.sales_order_item_id\n    AND dc.approval_status = 'pending_approval'\n    AND dci.id IS DISTINCT FROM NEW.id;\n\n  v_remaining := v_so_item.quantity - COALESCE(v_so_item.delivered_quantity, 0);\n  IF (v_pending + NEW.quantity) > (v_remaining + 0.0001) THEN\n    RAISE EXCEPTION 'Delivery quantity (%) exceeds remaining Sales Order quantity (%)', (v_pending + NEW.quantity), v_remaining;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","-- 2. Update consume_so_product_reservation_v2 function\nCREATE OR REPLACE FUNCTION public.consume_so_product_reservation_v2(\n  p_dc_item_id uuid,\n  p_operation_id uuid,\n  p_actor uuid\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v record;\n  v_res public.so_product_reservations%ROWTYPE;\n  v_soi record;\n  v_tx uuid;\n  v_after numeric;\n  v_consume_qty numeric;\n  v_res_id uuid;\nBEGIN\n  SELECT dci.*, dc.id AS dc_id, dc.sales_order_id, dc.challan_number, dc.challan_date INTO v\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  WHERE dci.id = p_dc_item_id\n  FOR UPDATE OF dci, dc;\n\n  IF NOT FOUND OR v.sales_order_item_id IS NULL THEN\n    RAISE EXCEPTION 'DC item has no canonical SO item';\n  END IF;\n\n  SELECT * INTO v_soi\n  FROM public.sales_order_items\n  WHERE id = v.sales_order_item_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Order item not found';\n  END IF;\n\n  -- Validate remaining SO quantity\n  IF v.quantity > (v_soi.quantity - COALESCE(v_soi.delivered_quantity, 0) + 0.0001) THEN\n    RAISE EXCEPTION 'DC quantity exceeds remaining Sales Order quantity';\n  END IF;\n\n  -- Validate physical batch stock\n  IF NOT EXISTS (\n    SELECT 1 FROM public.batches b\n    WHERE b.id = v.batch_id\n      AND b.product_id = v.product_id\n      AND b.is_active = true\n      AND b.current_stock >= v.quantity\n      AND (b.expiry_date IS NULL OR b.expiry_date > CURRENT_DATE)\n  ) THEN\n    RAISE EXCEPTION 'Selected batch is invalid, expired, or has insufficient physical stock';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.dc_batch_allocations\n    WHERE delivery_challan_item_id = v.id\n      AND status = 'consumed'\n  ) THEN\n    RAISE EXCEPTION 'Delivery Challan item reservation is already consumed';\n  END IF;\n\n  -- Post inventory movement\n  v_tx := public.post_inventory_movement(\n    public.uuid_from_text('inventory-v2:dc:' || p_operation_id || ':' || v.id),\n    v.product_id,\n    v.batch_id,\n    'delivery_challan',\n    -v.quantity,\n    v.challan_date,\n    v.challan_number,\n    'delivery_challan',\n    v.dc_id,\n    'Product delivery against DC batch',\n    COALESCE(p_actor, auth.uid()),\n    NULL,\n    NULL\n  );\n\n  -- Check if there is an active reservation to consume\n  SELECT * INTO v_res\n  FROM public.so_product_reservations\n  WHERE sales_order_item_id = v.sales_order_item_id\n    AND product_id = v.product_id\n    AND status = 'active'\n  FOR UPDATE;\n\n  IF FOUND THEN\n    v_res_id := v_res.id;\n    v_consume_qty := LEAST(v_res.reserved_quantity, v.quantity);\n    v_after := v_res.reserved_quantity - v_consume_qty;\n\n    UPDATE public.so_product_reservations SET\n      reserved_quantity = v_after,\n      status = CASE WHEN v_after = 0 THEN 'consumed' ELSE 'active' END,\n      closed_at = CASE WHEN v_after = 0 THEN now() END,\n      close_reason = CASE WHEN v_after = 0 THEN 'Fully delivered' END,\n      updated_at = now()\n    WHERE id = v_res.id;\n\n    INSERT INTO public.so_product_reservation_events(\n      reservation_id, sales_order_id, sales_order_item_id, event_type,\n      quantity_delta, quantity_after, delivery_challan_item_id, reason, actor_id\n    ) VALUES (\n      v_res.id, v.sales_order_id, v.sales_order_item_id, 'consumed',\n      -v_consume_qty, v_after, v.id, 'DC approval', COALESCE(p_actor, auth.uid())\n    );\n  ELSE\n    -- If no active reservation existed prior to delivery (e.g. shortage SO fulfilled on stock arrival),\n    -- create a fulfilled/consumed reservation record for complete audit trail & FK integrity in dc_batch_allocations\n    INSERT INTO public.so_product_reservations(\n      sales_order_id, sales_order_item_id, product_id, reserved_quantity,\n      status, created_at, closed_at, close_reason, created_by\n    ) VALUES (\n      v.sales_order_id, v.sales_order_item_id, v.product_id, 0,\n      'consumed', now(), now(), 'Direct DC delivery without prior reservation', COALESCE(p_actor, auth.uid())\n    ) RETURNING id INTO v_res_id;\n\n    INSERT INTO public.so_product_reservation_events(\n      reservation_id, sales_order_id, sales_order_item_id, event_type,\n      quantity_delta, quantity_after, delivery_challan_item_id, reason, actor_id\n    ) VALUES (\n      v_res_id, v.sales_order_id, v.sales_order_item_id, 'consumed',\n      -v.quantity, 0, v.id, 'Direct DC delivery without prior reservation', COALESCE(p_actor, auth.uid())\n    );\n  END IF;\n\n  INSERT INTO public.dc_batch_allocations(\n    delivery_challan_id, delivery_challan_item_id, sales_order_item_id,\n    reservation_id, product_id, batch_id, allocated_quantity,\n    operation_id, inventory_transaction_id, created_by\n  ) VALUES (\n    v.dc_id, v.id, v.sales_order_item_id,\n    v_res_id, v.product_id, v.batch_id, v.quantity,\n    p_operation_id, v_tx, COALESCE(p_actor, auth.uid())\n  );\n\n  RETURN v_tx;\nEND;\n$$","REVOKE ALL ON FUNCTION public.consume_so_product_reservation_v2(uuid, uuid, uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.consume_so_product_reservation_v2(uuid, uuid, uuid) TO authenticated, service_role",COMMIT}	fix_dc_creation_and_approval_for_unreserved_sales_orders	\N	\N	\N
20260930065228	{"BEGIN;\n\n-- This specific invoice is already approved for inward and already has its\n-- receiving batch identity persisted. The missing state is the canonical\n-- purchase/inward inventory movement and the receiving allocation.\n-- Repair only this verified case; do not touch unrelated inventory.\n\nDO $$\nDECLARE\n  v_invoice public.purchase_invoices%ROWTYPE;\n  v_item public.purchase_invoice_items%ROWTYPE;\n  v_batch public.batches%ROWTYPE;\n  v_operation uuid := public.uuid_from_text('inventory-v1:repair:purchase-invoice-receiving:bfabbf9b-8122-4e31-9556-33dc9065924a:7358cb82-08fe-4c04-b806-fdb33411f05c');\n  v_tx_id uuid;\n  v_alloc_id uuid;\n  v_currency text;\n  v_rate numeric;\n  v_func_unit numeric;\nBEGIN\n  SELECT * INTO v_invoice\n  FROM public.purchase_invoices\n  WHERE id='bfabbf9b-8122-4e31-9556-33dc9065924a'::uuid\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Target purchase invoice not found';\n  END IF;\n\n  IF v_invoice.receiving_approval_status <> 'approved' THEN\n    RAISE EXCEPTION 'Target purchase invoice is not approved for inward';\n  END IF;\n\n  SELECT * INTO v_item\n  FROM public.purchase_invoice_items\n  WHERE id='7358cb82-08fe-4c04-b806-fdb33411f05c'::uuid\n    AND purchase_invoice_id=v_invoice.id\n  FOR UPDATE;\n\n  IF NOT FOUND OR v_item.item_type <> 'inventory' OR v_item.product_id IS NULL THEN\n    RAISE EXCEPTION 'Target purchase invoice item is invalid';\n  END IF;\n\n  SELECT * INTO v_batch\n  FROM public.batches\n  WHERE id='21e0e286-5eb6-47a1-b955-c6a1a9d7e1c2'::uuid\n    AND product_id=v_item.product_id\n    AND batch_number=v_item.receiving_batch_number\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Target Paracetamol batch not found or identity mismatch';\n  END IF;\n\n  IF COALESCE(v_batch.import_quantity,0) <> v_item.quantity THEN\n    RAISE EXCEPTION 'Target batch/import quantity mismatch: batch %, item %',\n      v_batch.import_quantity, v_item.quantity;\n  END IF;\n\n  -- Repair only if the canonical inward posting is still absent.\n  IF NOT EXISTS (\n    SELECT 1\n    FROM public.purchase_invoice_receiving_allocations\n    WHERE purchase_invoice_id=v_invoice.id\n      AND purchase_invoice_item_id=v_item.id\n      AND batch_id=v_batch.id\n      AND status='received'\n  ) THEN\n    v_currency := upper(coalesce(v_invoice.currency,'IDR'));\n    v_rate := CASE WHEN v_currency='IDR' THEN 1 ELSE coalesce(v_invoice.exchange_rate,0) END;\n\n    IF v_rate <= 0 THEN\n      RAISE EXCEPTION 'Purchase invoice exchange rate is required for repair';\n    END IF;\n\n    v_func_unit := round(coalesce(v_item.unit_price,0) * v_rate, 2);\n\n    -- If the batch has no canonical purchase movement yet, create the\n    -- authoritative inward movement as a purchase (+500 kg).\n    IF NOT EXISTS (\n      SELECT 1\n      FROM public.inventory_transactions\n      WHERE operation_id=v_operation\n         OR (\n           batch_id=v_batch.id\n           AND transaction_type='purchase'\n         )\n    ) THEN\n      v_tx_id := public.post_inventory_movement(\n        v_operation,\n        v_batch.product_id,\n        v_batch.id,\n        'purchase',\n        v_item.quantity,\n        v_invoice.invoice_date,\n        v_invoice.invoice_number,\n        'purchase_invoice_receiving',\n        v_invoice.id,\n        'Repair: approved Purchase Invoice inward posting for Paracetamol USP batch ' || v_batch.batch_number,\n        NULL,\n        v_batch.current_stock,\n        v_batch.current_stock + v_item.quantity\n      );\n    ELSE\n      SELECT id INTO v_tx_id\n      FROM public.inventory_transactions\n      WHERE batch_id=v_batch.id\n        AND transaction_type='purchase'\n      ORDER BY created_at\n      LIMIT 1;\n    END IF;\n\n    INSERT INTO public.purchase_invoice_receiving_allocations(\n      purchase_invoice_id,\n      purchase_invoice_item_id,\n      batch_id,\n      received_quantity,\n      operation_id,\n      received_by,\n      currency,\n      exchange_rate,\n      functional_unit_cost,\n      functional_total_cost,\n      import_container_id,\n      status,\n      received_at\n    )\n    VALUES(\n      v_invoice.id,\n      v_item.id,\n      v_batch.id,\n      v_item.quantity,\n      v_operation,\n      v_invoice.receiving_approved_by,\n      v_currency,\n      v_rate,\n      v_func_unit,\n      round(v_func_unit * v_item.quantity, 2),\n      v_item.receiving_import_container_id,\n      'received',\n      coalesce(v_invoice.receiving_approved_at, now())\n    )\n    RETURNING id INTO v_alloc_id;\n\n    INSERT INTO public.purchase_batch_cost_layers(\n      receiving_allocation_id,\n      purchase_invoice_id,\n      purchase_invoice_item_id,\n      batch_id,\n      import_container_id,\n      quantity,\n      currency,\n      exchange_rate,\n      transaction_unit_cost,\n      functional_unit_cost,\n      functional_total_cost,\n      final_functional_unit_cost\n    )\n    VALUES(\n      v_alloc_id,\n      v_invoice.id,\n      v_item.id,\n      v_batch.id,\n      v_item.receiving_import_container_id,\n      v_item.quantity,\n      v_currency,\n      v_rate,\n      coalesce(v_item.unit_price,0),\n      v_func_unit,\n      round(v_func_unit * v_item.quantity, 2),\n      v_func_unit\n    )\n    ON CONFLICT DO NOTHING;\n\n    UPDATE public.purchase_invoice_items\n       SET batch_id = v_batch.id,\n           receiving_batch_number = coalesce(receiving_batch_number, v_batch.batch_number)\n     WHERE id=v_item.id;\n  END IF;\nEND $$;\n\nCOMMIT;"}	repair_paracetamol_receiving_batch_2651442	simplykool@gmail.com	\N	\N
20261112175432	{"\nALTER TABLE public.crm_email_activities\n  DROP CONSTRAINT IF EXISTS crm_email_activities_contact_id_fkey;\nALTER TABLE public.crm_email_activities\n  ADD CONSTRAINT crm_email_activities_contact_id_fkey\n  FOREIGN KEY (contact_id) REFERENCES public.crm_contacts(id) ON DELETE SET NULL;\n\nALTER TABLE public.crm_company_domain_mapping\n  DROP CONSTRAINT IF EXISTS crm_company_domain_mapping_primary_contact_id_fkey;\nALTER TABLE public.crm_company_domain_mapping\n  ADD CONSTRAINT crm_company_domain_mapping_primary_contact_id_fkey\n  FOREIGN KEY (primary_contact_id) REFERENCES public.crm_contacts(id) ON DELETE SET NULL;\n\nALTER TABLE public.crm_quick_actions_log\n  DROP CONSTRAINT IF EXISTS crm_quick_actions_log_contact_id_fkey;\nALTER TABLE public.crm_quick_actions_log\n  ADD CONSTRAINT crm_quick_actions_log_contact_id_fkey\n  FOREIGN KEY (contact_id) REFERENCES public.crm_contacts(id) ON DELETE SET NULL;\n\nALTER TABLE public.crm_activity_logs\n  DROP CONSTRAINT IF EXISTS crm_activity_logs_contact_id_fkey;\nALTER TABLE public.crm_activity_logs\n  ADD CONSTRAINT crm_activity_logs_contact_id_fkey\n  FOREIGN KEY (contact_id) REFERENCES public.crm_contacts(id) ON DELETE SET NULL;\n\nUPDATE public.crm_contacts c\nSET total_inquiries = (SELECT count(*)::integer FROM public.crm_inquiries i WHERE i.crm_contact_id=c.id),\n    updated_at = now(),\n    updated_by = '1075a773-bb55-4296-bc71-af2eab9a0780'\nWHERE c.id='b668e821-d94a-4362-a7fb-c9402eb1352c';\n"}	crm_contact_delete_preserve_history	simplykool@gmail.com	\N	\N
20261114093434	{"CREATE OR REPLACE FUNCTION public.compute_period_ppn(p_period_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_period public.tax_periods%rowtype;\n  v_pph_total numeric(18,2);\nBEGIN\n  SELECT * INTO v_period\n    FROM public.tax_periods\n   WHERE id = p_period_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax period % not found', p_period_id;\n  END IF;\n\n  -- PPN calculation remains unchanged.\n  IF v_period.tax_type = 'PPN' THEN\n    PERFORM public.compute_period_ppn_pre_posted_register(p_period_id);\n    RETURN;\n  END IF;\n\n  -- Filed periods are immutable snapshots. Never overwrite a submitted\n  -- government return from live source rows during later expense edits.\n  IF v_period.filing_status = 'filed' OR v_period.status = 'closed' THEN\n    RETURN;\n  END IF;\n\n  PERFORM public.compute_period_ppn_pre_posted_register(p_period_id);\n\n  SELECT COALESCE(public.fn_pph_authoritative_source_total(p_period_id), 0)\n       + COALESCE((\n           SELECT SUM(tp.amount)\n             FROM public.tax_payments tp\n            WHERE tp.tax_period_id = p_period_id\n              AND tp.tax_type = v_period.tax_type\n              AND tp.historical_source_status = 'missing_source_verified'\n         ), 0)\n    INTO v_pph_total;\n\n  UPDATE public.tax_periods\n     SET pph_total = v_pph_total,\n         updated_at = now()\n   WHERE id = p_period_id;\nEND;\n$function$;"}	protect_filed_pph_period_totals	simplykool@gmail.com	\N	\N
20260915180000	{"-- ============================================================================\n-- Migration: Full Supabase Security Hardening (Zero ERP Regression)\n-- ============================================================================\n-- 1. Sets security_invoker = true on all 8 SECURITY DEFINER views.\n-- 2. Fixes mutable search_path on all 11 flagged functions.\n-- 3. Enables RLS and applies least-privilege policies to 6 public tables.\n-- 4. Relocates pg_net extension to the canonical extensions schema.\n-- 5. Revokes execute privileges from 'anon' across all internal and privileged\n--    SECURITY DEFINER functions, preserving genuine pre-login functions.\n-- 6. Revokes direct PostgREST execution on internal trigger-only functions.\n-- ============================================================================\n\nBEGIN","-- ----------------------------------------------------------------------------\n-- 1. SECURITY DEFINER Views -> SECURITY INVOKER\n-- ----------------------------------------------------------------------------\nALTER VIEW public.customer_receivables_view SET (security_invoker = true)","ALTER VIEW public.finance_live_verification_failures SET (security_invoker = true)","ALTER VIEW public.inventory_v1_stock_summary SET (security_invoker = true)","ALTER VIEW public.sales_invoice_item_integrity SET (security_invoker = true)","ALTER VIEW public.so_product_reservation_status SET (security_invoker = true)","ALTER VIEW public.supplier_payables_view SET (security_invoker = true)","ALTER VIEW public.vw_bank_ledger_effective SET (security_invoker = true)","ALTER VIEW public.vw_bank_ledger_monthly_reconciliation SET (security_invoker = true)","-- ----------------------------------------------------------------------------\n-- 2. Mutable Function search_path Hardening (11 Functions)\n-- ----------------------------------------------------------------------------\nALTER FUNCTION public.calculate_batch_authoritative_cost(public.batches) SET search_path = public, pg_temp","ALTER FUNCTION public.fn_crm_email_activities_dedup() SET search_path = public, pg_temp","ALTER FUNCTION public.fn_protect_enquiry_message_content() SET search_path = public, pg_temp","ALTER FUNCTION public.fn_tax_period_payment_status(text, numeric, numeric, date) SET search_path = public, pg_temp","ALTER FUNCTION public.get_batch_authoritative_unit_cost(uuid) SET search_path = public, pg_temp","ALTER FUNCTION public.is_capitalizable_landed_cost_category(text) SET search_path = public, pg_temp","ALTER FUNCTION public.normalize_customer_identity(text) SET search_path = public, pg_temp","ALTER FUNCTION public.normalize_customer_tax_id(text) SET search_path = public, pg_temp","ALTER FUNCTION public.reset_receiving_approval_on_invoice_change() SET search_path = public, pg_temp","ALTER FUNCTION public.reset_receiving_approval_on_item_change() SET search_path = public, pg_temp","ALTER FUNCTION public.sync_sales_invoice_balance_cache() SET search_path = public, pg_temp","-- ----------------------------------------------------------------------------\n-- 3. Public Tables Without RLS -> Enable RLS & Add Policies\n-- ----------------------------------------------------------------------------\n-- 3.1 audit_removed_duplicate_sale_inventory_transactions\nALTER TABLE public.audit_removed_duplicate_sale_inventory_transactions ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS \\"audit_removed_dup_sale_inv_select\\" ON public.audit_removed_duplicate_sale_inventory_transactions","CREATE POLICY \\"audit_removed_dup_sale_inv_select\\" ON public.audit_removed_duplicate_sale_inventory_transactions\n  FOR SELECT TO authenticated USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles up\n      WHERE up.id = auth.uid() AND up.is_active = true AND up.role = ANY(ARRAY['admin'::text, 'accounts'::text, 'auditor_ca'::text])\n    )\n  )","-- 3.2 purchase_batch_cost_layers\nALTER TABLE public.purchase_batch_cost_layers ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS \\"purchase_batch_cost_layers_select\\" ON public.purchase_batch_cost_layers","CREATE POLICY \\"purchase_batch_cost_layers_select\\" ON public.purchase_batch_cost_layers\n  FOR SELECT TO authenticated USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles up\n      WHERE up.id = auth.uid() AND up.is_active = true AND up.role = ANY(ARRAY['admin'::text, 'accounts'::text, 'manager'::text])\n    )\n  )","-- 3.3 temp_exec_result\nALTER TABLE public.temp_exec_result ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS \\"temp_exec_result_admin_all\\" ON public.temp_exec_result","CREATE POLICY \\"temp_exec_result_admin_all\\" ON public.temp_exec_result\n  FOR ALL TO authenticated USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles up\n      WHERE up.id = auth.uid() AND up.is_active = true AND up.role = 'admin'::text\n    )\n  )","-- 3.4 temp_exec_trace\nALTER TABLE public.temp_exec_trace ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS \\"temp_exec_trace_admin_all\\" ON public.temp_exec_trace","CREATE POLICY \\"temp_exec_trace_admin_all\\" ON public.temp_exec_trace\n  FOR ALL TO authenticated USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles up\n      WHERE up.id = auth.uid() AND up.is_active = true AND up.role = 'admin'::text\n    )\n  )","-- 3.5 temp_profile_steps\nALTER TABLE public.temp_profile_steps ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS \\"temp_profile_steps_admin_all\\" ON public.temp_profile_steps","CREATE POLICY \\"temp_profile_steps_admin_all\\" ON public.temp_profile_steps\n  FOR ALL TO authenticated USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles up\n      WHERE up.id = auth.uid() AND up.is_active = true AND up.role = 'admin'::text\n    )\n  )","-- 3.6 temp_profile_timings\nALTER TABLE public.temp_profile_timings ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS \\"temp_profile_timings_admin_all\\" ON public.temp_profile_timings","CREATE POLICY \\"temp_profile_timings_admin_all\\" ON public.temp_profile_timings\n  FOR ALL TO authenticated USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles up\n      WHERE up.id = auth.uid() AND up.is_active = true AND up.role = 'admin'::text\n    )\n  )","-- ----------------------------------------------------------------------------\n-- 4. Relocate pg_net Extension to extensions Schema\n-- ----------------------------------------------------------------------------\nDO $$\nBEGIN\n  IF EXISTS (\n    SELECT 1 FROM pg_extension e\n    JOIN pg_namespace n ON n.oid = e.extnamespace\n    WHERE e.extname = 'pg_net' AND n.nspname = 'public'\n  ) THEN\n    ALTER EXTENSION pg_net SET SCHEMA extensions;\n  END IF;\nEXCEPTION\n  WHEN OTHERS THEN\n    RAISE NOTICE 'pg_net schema alteration skipped: %', SQLERRM;\nEND $$","-- ----------------------------------------------------------------------------\n-- 5. Revoke anon Execution Across All Privileged SECURITY DEFINER Functions\n-- ----------------------------------------------------------------------------\nDO $$\nDECLARE\n  r record;\nBEGIN\n  FOR r IN\n    SELECT p.proname, pg_get_function_identity_arguments(p.oid) as args\n    FROM pg_proc p\n    JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname = 'public'\n      AND p.prosecdef = true\n      AND p.proname NOT IN ('lookup_login_email', 'is_setup_mode')\n  LOOP\n    EXECUTE format('REVOKE ALL ON FUNCTION public.%I(%s) FROM PUBLIC, anon', r.proname, r.args);\n  END LOOP;\nEND $$","-- Explicitly ensure pre-login functions remain available for initial login\nGRANT EXECUTE ON FUNCTION public.lookup_login_email(text) TO anon, authenticated, service_role","GRANT EXECUTE ON FUNCTION public.is_setup_mode() TO anon, authenticated, service_role","-- ----------------------------------------------------------------------------\n-- 6. Revoke Direct PostgREST Execution on Internal Trigger / Guard Functions\n-- ----------------------------------------------------------------------------\nDO $$\nDECLARE\n  r record;\nBEGIN\n  FOR r IN\n    SELECT p.proname, pg_get_function_identity_arguments(p.oid) as args\n    FROM pg_proc p\n    JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname = 'public'\n      AND (\n        p.prorettype = 'trigger'::regtype\n        OR p.proname LIKE 'trg_%'\n        OR p.proname LIKE 'guard_%'\n        OR p.proname LIKE 'validate_%'\n        OR p.proname LIKE 'auto_%'\n        OR p.proname LIKE 'prevent_%'\n      )\n  LOOP\n    EXECUTE format('REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM PUBLIC, anon, authenticated', r.proname, r.args);\n  END LOOP;\nEND $$",COMMIT}	full_supabase_security_hardening	\N	\N	\N
20261007111727	{"UPDATE public.import_data SET date = date + INTERVAL '27 days' WHERE created_at >= '2026-10-07 11:13:19+00' AND created_at <= '2026-10-07 11:13:41+00' AND EXTRACT(DAY FROM date) = 26;"}	repair_import_upload_dates_20261007	simplykool@gmail.com	\N	\N
20261114093607	{"CREATE OR REPLACE FUNCTION public.enforce_tax_period_lock()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_status text;\n  v_filing_status text;\nBEGIN\n  -- Explicitly authorized, narrowly scoped metadata repairs may bypass locks.\n  IF current_setting('app.finance_metadata_repair', true) = 'on' THEN\n    RETURN COALESCE(NEW, OLD);\n  END IF;\n\n  -- Preserve the existing service-role behavior.\n  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN\n    RETURN COALESCE(NEW, OLD);\n  END IF;\n\n  IF TG_OP = 'UPDATE' OR TG_OP = 'DELETE' THEN\n    IF OLD.tax_period_id IS NOT NULL THEN\n      SELECT status INTO v_status\n        FROM public.tax_periods\n       WHERE id = OLD.tax_period_id;\n\n      IF v_status = 'closed' THEN\n        RAISE EXCEPTION 'Tax period is closed; cannot modify % on %',\n          TG_OP, TG_TABLE_NAME\n          USING ERRCODE = 'check_violation';\n      END IF;\n    END IF;\n\n    -- PPh-linked source rows are immutable once their return is filed.\n    IF OLD.pph_tax_period_id IS NOT NULL THEN\n      SELECT filing_status INTO v_filing_status\n        FROM public.tax_periods\n       WHERE id = OLD.pph_tax_period_id;\n\n      IF v_filing_status IN ('filed', 'amended') THEN\n        RAISE EXCEPTION 'PPh tax period is filed; cannot modify % on %',\n          TG_OP, TG_TABLE_NAME\n          USING ERRCODE = 'check_violation';\n      END IF;\n    END IF;\n  END IF;\n\n  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN\n    IF NEW.tax_period_id IS NOT NULL THEN\n      SELECT status INTO v_status\n        FROM public.tax_periods\n       WHERE id = NEW.tax_period_id;\n\n      IF v_status = 'closed' THEN\n        RAISE EXCEPTION 'Tax period is closed; cannot assign new rows to it'\n          USING ERRCODE = 'check_violation';\n      END IF;\n    END IF;\n\n    IF NEW.pph_tax_period_id IS NOT NULL THEN\n      SELECT filing_status INTO v_filing_status\n        FROM public.tax_periods\n       WHERE id = NEW.pph_tax_period_id;\n\n      IF v_filing_status IN ('filed', 'amended') THEN\n        RAISE EXCEPTION 'PPh tax period is filed; cannot assign new rows to it'\n          USING ERRCODE = 'check_violation';\n      END IF;\n    END IF;\n  END IF;\n\n  RETURN COALESCE(NEW, OLD);\nEND;\n$function$;"}	lock_finance_expenses_in_filed_pph_periods	simplykool@gmail.com	\N	\N
20260915190000	{"-- ============================================================================\n-- FINAL SECURITY AUTHORIZATION AUDIT & ROLE HARDENING\n-- Migration: 20260915190000_final_security_authorization_audit.sql\n-- ============================================================================\n\n-- 1. Correct purchase_batch_cost_layers policy (remove non-existent 'manager' role)\nDROP POLICY IF EXISTS purchase_batch_cost_layers_select ON public.purchase_batch_cost_layers","CREATE POLICY purchase_batch_cost_layers_select ON public.purchase_batch_cost_layers\n  FOR SELECT TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles up\n      WHERE up.id = auth.uid() \n        AND up.is_active = true \n        AND up.role = ANY (ARRAY['admin'::text, 'accounts'::text])\n    )\n  )","-- repair_all_posted_fund_transfers()\nCREATE OR REPLACE FUNCTION public.repair_all_posted_fund_transfers()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  t record;\n  eligibility text;\n  result jsonb;\n  scanned integer := 0;\n  repaired integer := 0;\n  skipped integer := 0;\n  skipped_details jsonb := '[]'::jsonb;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  PERFORM public._sec_check_finance_role();\n  FOR t IN SELECT id, transfer_number FROM public.fund_transfers WHERE status='posted' ORDER BY transfer_date, transfer_number LOOP\n    scanned := scanned + 1;\n    eligibility := public.audit_fund_transfer_repair_eligibility(t.id);\n    IF eligibility IS NOT NULL THEN\n      skipped := skipped + 1;\n      skipped_details := skipped_details || jsonb_build_array(jsonb_build_object(\n        'fund_transfer_id', t.id, 'transfer_number', t.transfer_number, 'reason', eligibility));\n      CONTINUE;\n    END IF;\n    SELECT public.repair_posted_fund_transfer_from_source(t.id) INTO result;\n    IF COALESCE((result->>'repaired')::boolean, false) THEN\n      repaired := repaired + 1;\n      IF NOT EXISTS (\n        SELECT 1 FROM public.audit_logs a\n        WHERE a.table_name='fund_transfers' AND a.record_id=t.id\n          AND a.new_values->>'validation_rerun'='true'\n      ) THEN\n        INSERT INTO public.audit_logs(table_name, action_type, record_id, old_values, new_values, changed_fields)\n        VALUES ('fund_transfers', 'update', t.id,\n          jsonb_build_object('event','batch_repair','transfer_number',t.transfer_number),\n          jsonb_build_object('event','batch_repair','repair_result',result,'validation_rerun',true),\n          COALESCE(ARRAY(SELECT jsonb_array_elements_text(result->'repaired_fields')), ARRAY[]::text[]));\n      END IF;\n    ELSE\n      skipped := skipped + 1;\n      skipped_details := skipped_details || jsonb_build_array(jsonb_build_object(\n        'fund_transfer_id', t.id, 'transfer_number', t.transfer_number,\n        'reason', COALESCE(result->>'reason', 'Repair did not pass validation')));\n    END IF;\n  END LOOP;\n  RETURN jsonb_build_object('total_scanned', scanned, 'automatically_repaired', repaired,\n    'skipped', skipped, 'skipped_details', skipped_details);\nEND;\n$function$","-- repair_historical_usd_idr_transfer_fx(p_cutoff date)\nCREATE OR REPLACE FUNCTION public.repair_historical_usd_idr_transfer_fx(p_cutoff date DEFAULT '2026-08-01'::date)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE r record; l record; v_reversal uuid; v_corrected uuid; v_entry text; v_line int; v_run uuid; v_repaired int:=0; v_skipped int:=0; v_exception int:=0; BEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  PERFORM set_config('app.finance_historical_repair','on',true);\n  PERFORM set_config('app.finance_historical_repair_relink','on',true);\n  INSERT INTO public.finance_historical_repair_runs(notes) VALUES ('Controlled historical USD→IDR fund-transfer FX correction before cutoff '||p_cutoff::text) RETURNING id INTO v_run;\n  FOR r IN\n    SELECT ft.id, ft.transfer_number, ft.transfer_date, ft.from_amount, ft.to_amount, ft.exchange_rate, ft.journal_entry_id,\n           je.entry_number, je.total_debit, je.total_credit,\n           fba.coa_id from_coa, fba.currency from_currency, tba.coa_id to_coa, tba.currency to_currency,\n           fs.id from_stmt, ts.id to_stmt, fs.debit_amount from_debit, fs.credit_amount from_credit, fs.currency from_stmt_currency,\n           ts.debit_amount to_debit, ts.credit_amount to_credit, ts.currency to_stmt_currency\n    FROM public.fund_transfers ft\n    JOIN public.bank_accounts fba ON fba.id=ft.from_bank_account_id\n    JOIN public.bank_accounts tba ON tba.id=ft.to_bank_account_id\n    JOIN public.journal_entries je ON je.id=ft.journal_entry_id\n    JOIN public.bank_statement_lines fs ON fs.id=ft.from_bank_statement_line_id\n    JOIN public.bank_statement_lines ts ON ts.id=ft.to_bank_statement_line_id\n    WHERE ft.status='posted' AND ft.transfer_date < p_cutoff AND fba.currency='USD' AND tba.currency='IDR'\n      AND fs.currency='USD' AND ts.currency='IDR'\n      AND abs(fs.debit_amount-ft.from_amount)<0.01 AND abs(fs.credit_amount)<0.01\n      AND abs(ts.credit_amount-ft.to_amount)<0.01 AND abs(ts.debit_amount)<0.01\n      AND NOT COALESCE(je.is_reversed,false)\n    ORDER BY ft.transfer_date, ft.transfer_number\n    FOR UPDATE OF ft,je,fs,ts\n  LOOP\n    IF abs(r.total_debit-r.to_amount)<0.01 AND abs(r.total_credit-r.to_amount)<0.01 THEN v_skipped:=v_skipped+1; CONTINUE; END IF;\n    IF NOT (abs(r.total_debit-r.from_amount)<0.01 AND abs(r.total_credit-r.from_amount)<0.01) THEN\n      v_exception:=v_exception+1;\n      INSERT INTO public.finance_historical_repair_exceptions(run_id,document_type,document_id,document_number,inconsistent_fields,reason,manual_information_required)\n      VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal_amounts'],'Journal amount does not match either the USD source amount or evidenced IDR destination amount','Accountant review of the original journal and bank evidence');\n      CONTINUE;\n    END IF;\n    v_entry:=public.generate_journal_entry_number();\n    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n    VALUES(v_entry,r.transfer_date,'historical_repair',r.id,'HR-REV-'||r.transfer_number,'Reversal of legacy USD-source functional posting '||r.entry_number,r.total_credit,r.total_debit,true,now(),'IDR','IDR',r.exchange_rate,true)\n    RETURNING id INTO v_reversal;\n    v_line:=1;\n    FOR l IN SELECT jl.* FROM public.journal_entry_lines jl WHERE jl.journal_entry_id=r.journal_entry_id ORDER BY jl.line_number LOOP\n      INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,supplier_id,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n      VALUES(v_reversal,v_line,l.account_id,l.credit,l.debit,'Historical FX reversal: '||COALESCE(l.description,''),l.supplier_id,l.transaction_currency,l.transaction_credit,l.transaction_debit,l.functional_currency,l.exchange_rate);\n      v_line:=v_line+1;\n    END LOOP;\n    UPDATE public.journal_entries SET is_reversed=true,reversed_by_id=v_reversal WHERE id=r.journal_entry_id;\n    v_entry:=public.generate_journal_entry_number();\n    INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_at,transaction_currency,functional_currency,exchange_rate,amounts_are_functional)\n    VALUES(v_entry,r.transfer_date,'historical_repair',r.id,'HR-FX-'||r.transfer_number,'Corrected USD→IDR fund transfer '||r.transfer_number,r.to_amount,r.to_amount,true,now(),'IDR','IDR',r.exchange_rate,true)\n    RETURNING id INTO v_corrected;\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n    VALUES(v_corrected,1,r.to_coa,r.to_amount,0,'Corrected transfer into IDR bank','IDR',r.to_amount,0,'IDR',1);\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,debit,credit,description,transaction_currency,transaction_debit,transaction_credit,functional_currency,exchange_rate)\n    VALUES(v_corrected,2,r.from_coa,0,r.to_amount,'Corrected transfer out of USD bank','USD',0,r.from_amount,'IDR',r.exchange_rate);\n    UPDATE public.fund_transfers SET journal_entry_id=v_corrected WHERE id=r.id;\n    UPDATE public.bank_statement_lines SET matched_entry_id=v_corrected, reconciliation_status='matched' WHERE id IN(r.from_stmt,r.to_stmt);\n    INSERT INTO public.finance_historical_repair_items(run_id,document_type,document_id,document_number,repaired_fields,old_metadata,new_metadata,repair_reason)\n    VALUES(v_run,'fund_transfer',r.id,r.transfer_number,ARRAY['journal_entry','bank matched_entry_id'],jsonb_build_object('journal_entry_id',r.journal_entry_id,'entry_number',r.entry_number,'total',r.total_debit),jsonb_build_object('reversal_journal_id',v_reversal,'replacement_journal_id',v_corrected,'replacement_entry_number',v_entry,'functional_idr',r.to_amount,'transaction_usd',r.from_amount,'rate',r.exchange_rate),'Both bank statement sides prove the USD source amount, IDR destination amount, and historical FX rate');\n    v_repaired:=v_repaired+1;\n  END LOOP;\n  UPDATE public.finance_historical_repair_runs SET completed_at=now(),total_records_scanned=v_repaired+v_skipped+v_exception,records_repaired=v_repaired,records_manual_review=v_exception,records_skipped=v_skipped WHERE id=v_run;\n  RETURN jsonb_build_object('run_id',v_run,'repaired',v_repaired,'skipped_already_correct',v_skipped,'manual_review',v_exception,'cutoff',p_cutoff);\nEND $function$","-- repair_posted_fund_transfer_from_source(p_fund_transfer_id uuid)\nCREATE OR REPLACE FUNCTION public.repair_posted_fund_transfer_from_source(p_fund_transfer_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_transfer public.fund_transfers%ROWTYPE;\n  v_journal public.journal_entries%ROWTYPE;\n  v_from_coa uuid;\n  v_to_coa uuid;\n  v_from_currency text;\n  v_to_currency text;\n  v_journal_currency text;\n  v_expected_rate numeric;\n  v_before_lines jsonb;\n  v_after_lines jsonb;\n  v_repaired_fields text[] := ARRAY[]::text[];\n  v_possible_bank_transactions integer;\n  v_validation_failures integer;\n  v_live_validation_failures integer;\n  v_validation_passed boolean;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  PERFORM public._sec_check_finance_role();\n  PERFORM set_config('app.finance_historical_repair', 'on', true);\n  PERFORM set_config('app.finance_metadata_repair', 'on', true);\n\n  SELECT * INTO v_transfer\n  FROM public.fund_transfers\n  WHERE id = p_fund_transfer_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Fund Transfer not found';\n  END IF;\n  IF v_transfer.status <> 'posted' OR v_transfer.journal_entry_id IS NULL THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer is not posted with an existing journal');\n  END IF;\n\n  SELECT * INTO v_journal\n  FROM public.journal_entries\n  WHERE id = v_transfer.journal_entry_id\n  FOR UPDATE;\n\n  IF NOT FOUND OR NOT COALESCE(v_journal.is_posted, false) OR COALESCE(v_journal.is_reversed, false) THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer journal is not an active posted journal');\n  END IF;\n  IF v_journal.source_module NOT IN ('fund_transfer', 'fund_transfers')\n     OR v_journal.reference_id IS DISTINCT FROM v_transfer.id THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer and journal do not prove an authoritative relationship');\n  END IF;\n\n  IF v_transfer.from_account_type = 'bank' THEN\n    SELECT coa_id, upper(currency) INTO v_from_coa, v_from_currency\n    FROM public.bank_accounts WHERE id = v_transfer.from_bank_account_id AND is_active;\n  ELSIF v_transfer.from_account_type = 'petty_cash' THEN\n    SELECT id, 'IDR' INTO v_from_coa, v_from_currency FROM public.chart_of_accounts WHERE code = '1102' AND is_active LIMIT 1;\n  ELSIF v_transfer.from_account_type = 'cash_on_hand' THEN\n    SELECT id, 'IDR' INTO v_from_coa, v_from_currency FROM public.chart_of_accounts WHERE code = '1101' AND is_active LIMIT 1;\n  END IF;\n\n  IF v_transfer.to_account_type = 'bank' THEN\n    SELECT coa_id, upper(currency) INTO v_to_coa, v_to_currency\n    FROM public.bank_accounts WHERE id = v_transfer.to_bank_account_id AND is_active;\n  ELSIF v_transfer.to_account_type = 'petty_cash' THEN\n    SELECT id, 'IDR' INTO v_to_coa, v_to_currency FROM public.chart_of_accounts WHERE code = '1102' AND is_active LIMIT 1;\n  ELSIF v_transfer.to_account_type = 'cash_on_hand' THEN\n    SELECT id, 'IDR' INTO v_to_coa, v_to_currency FROM public.chart_of_accounts WHERE code = '1101' AND is_active LIMIT 1;\n  END IF;\n\n  IF v_from_coa IS NULL OR v_to_coa IS NULL OR v_from_currency IS NULL OR v_to_currency IS NULL THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer source does not contain complete active account and currency information');\n  END IF;\n  IF v_transfer.from_amount IS NULL OR v_transfer.to_amount IS NULL OR v_transfer.exchange_rate IS NULL THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer source is missing an amount or exchange rate');\n  END IF;\n\n  v_expected_rate := CASE\n    WHEN v_from_currency = v_to_currency THEN 1\n    WHEN v_from_currency = 'IDR' AND v_transfer.to_amount > 0 THEN v_transfer.from_amount / v_transfer.to_amount\n    WHEN v_to_currency = 'IDR' AND v_transfer.from_amount > 0 THEN v_transfer.to_amount / v_transfer.from_amount\n  END;\n  IF v_expected_rate IS NULL OR abs(v_transfer.exchange_rate - v_expected_rate) > 0.000001 THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Fund Transfer exchange rate is not internally consistent with its stored amounts');\n  END IF;\n  IF (SELECT count(*) FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id) <> 2\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id AND line_number = 1 AND COALESCE(debit, 0) > 0 AND COALESCE(credit, 0) = 0)\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id AND line_number = 2 AND COALESCE(credit, 0) > 0 AND COALESCE(debit, 0) = 0) THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Existing journal lines are not a safe two-line transfer journal');\n  END IF;\n  IF abs(COALESCE(v_journal.total_debit, 0) - COALESCE(v_transfer.from_amount, 0)) > 0.01\n     OR abs(COALESCE(v_journal.total_credit, 0) - COALESCE(v_transfer.from_amount, 0)) > 0.01\n     OR EXISTS (\n       SELECT 1 FROM public.journal_entry_lines l\n       WHERE l.journal_entry_id = v_journal.id\n         AND ((l.line_number = 1 AND abs(COALESCE(l.debit, 0) - v_transfer.from_amount) > 0.01)\n           OR (l.line_number = 2 AND abs(COALESCE(l.credit, 0) - v_transfer.from_amount) > 0.01))\n     ) THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Existing posted journal amounts do not match the Fund Transfer source');\n  END IF;\n\n  -- No bank transaction is inferred or relinked. If the source document does\n  -- not name a line, explicitly refuse to guess, especially when candidates\n  -- are ambiguous. The accountant can resolve the missing source information.\n  IF v_transfer.from_bank_statement_line_id IS NULL AND v_transfer.from_account_type = 'bank' THEN\n    SELECT count(*) INTO v_possible_bank_transactions\n    FROM public.bank_statement_lines b\n    WHERE b.bank_account_id = v_transfer.from_bank_account_id\n      AND abs(b.transaction_date - v_transfer.transfer_date) <= 8\n      AND (COALESCE(b.debit_amount, 0) = v_transfer.from_amount OR COALESCE(b.credit_amount, 0) = v_transfer.from_amount);\n    IF v_possible_bank_transactions > 1 THEN\n      RETURN jsonb_build_object('repaired', false, 'reason', 'Multiple possible From Bank transactions exist; no bank link was guessed');\n    END IF;\n  END IF;\n  IF v_transfer.to_bank_statement_line_id IS NULL AND v_transfer.to_account_type = 'bank' THEN\n    SELECT count(*) INTO v_possible_bank_transactions\n    FROM public.bank_statement_lines b\n    WHERE b.bank_account_id = v_transfer.to_bank_account_id\n      AND abs(b.transaction_date - v_transfer.transfer_date) <= 8\n      AND (COALESCE(b.debit_amount, 0) = v_transfer.to_amount OR COALESCE(b.credit_amount, 0) = v_transfer.to_amount);\n    IF v_possible_bank_transactions > 1 THEN\n      RETURN jsonb_build_object('repaired', false, 'reason', 'Multiple possible To Bank transactions exist; no bank link was guessed');\n    END IF;\n  END IF;\n\n  SELECT jsonb_agg(jsonb_build_object('id', id, 'debit', debit, 'credit', credit) ORDER BY id)\n  INTO v_before_lines FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id;\n\n  v_journal_currency := CASE WHEN v_from_currency = v_to_currency THEN v_from_currency ELSE 'IDR' END;\n  UPDATE public.journal_entries\n  SET source_module = 'fund_transfers', reference_id = v_transfer.id,\n      reference_number = v_transfer.transfer_number, transaction_currency = v_journal_currency,\n      functional_currency = 'IDR', exchange_rate = v_transfer.exchange_rate,\n      amounts_are_functional = true\n  WHERE id = v_journal.id\n    AND (source_module IS DISTINCT FROM 'fund_transfers' OR reference_id IS DISTINCT FROM v_transfer.id\n      OR reference_number IS DISTINCT FROM v_transfer.transfer_number OR transaction_currency IS DISTINCT FROM v_journal_currency\n      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM v_transfer.exchange_rate\n      OR amounts_are_functional IS DISTINCT FROM true);\n  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_metadata'); END IF;\n\n  UPDATE public.journal_entry_lines\n  SET account_id = v_to_coa, transaction_currency = v_to_currency,\n      functional_currency = 'IDR', exchange_rate = CASE WHEN v_to_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END\n  WHERE journal_entry_id = v_journal.id AND line_number = 1\n    AND (account_id IS DISTINCT FROM v_to_coa OR transaction_currency IS DISTINCT FROM v_to_currency\n      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM CASE WHEN v_to_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END);\n  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_debit_line_metadata'); END IF;\n\n  UPDATE public.journal_entry_lines\n  SET account_id = v_from_coa, transaction_currency = v_from_currency,\n      functional_currency = 'IDR', exchange_rate = CASE WHEN v_from_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END\n  WHERE journal_entry_id = v_journal.id AND line_number = 2\n    AND (account_id IS DISTINCT FROM v_from_coa OR transaction_currency IS DISTINCT FROM v_from_currency\n      OR functional_currency IS DISTINCT FROM 'IDR' OR exchange_rate IS DISTINCT FROM CASE WHEN v_from_currency = 'USD' THEN v_transfer.exchange_rate ELSE 1 END);\n  IF FOUND THEN v_repaired_fields := array_append(v_repaired_fields, 'journal_credit_line_metadata'); END IF;\n\n  SELECT jsonb_agg(jsonb_build_object('id', id, 'debit', debit, 'credit', credit) ORDER BY id)\n  INTO v_after_lines FROM public.journal_entry_lines WHERE journal_entry_id = v_journal.id;\n  IF v_before_lines IS DISTINCT FROM v_after_lines THEN\n    RAISE EXCEPTION 'Fund Transfer repair cancelled because a debit or credit value changed';\n  END IF;\n\n  -- The existing validation projections are live views. Read them after the\n  -- metadata updates; resolve the false-positive only when they are clean.\n  SELECT count(*) INTO v_validation_failures\n  FROM public.finance_historical_repair_verification_failures f\n  WHERE f.document_type = 'fund_transfer' AND f.database_id = v_transfer.id;\n  SELECT count(*) INTO v_live_validation_failures\n  FROM public.finance_live_verification_failures f\n  WHERE f.document_type = 'fund_transfer' AND f.document_id = v_transfer.id;\n  v_validation_failures := v_validation_failures + v_live_validation_failures;\n  v_validation_passed := v_validation_failures = 0;\n  IF v_validation_passed THEN\n    UPDATE public.finance_historical_repair_exceptions\n    SET status = 'resolved'\n    WHERE status = 'manual_review' AND document_type = 'fund_transfer' AND document_id = v_transfer.id;\n  END IF;\n\n  -- A no-op retry produces no second audit mutation. The first successful\n  -- call records the exact derived fields changed and immutable line values.\n  IF COALESCE(array_length(v_repaired_fields, 1), 0) > 0 THEN\n    INSERT INTO public.audit_logs(table_name, action_type, record_id, old_values, new_values, changed_fields)\n    VALUES ('fund_transfers', 'update', v_transfer.id,\n      jsonb_build_object('journal_entry_id', v_journal.id, 'journal_lines', v_before_lines),\n      jsonb_build_object('journal_entry_id', v_journal.id, 'journal_lines', v_after_lines,\n        'validation_rerun', true, 'validation_passed', v_validation_passed),\n      v_repaired_fields);\n  END IF;\n\n  IF NOT v_validation_passed THEN\n    RETURN jsonb_build_object('repaired', false, 'reason', 'Derived data still fails the existing Finance validation', 'validation_failures', v_validation_failures);\n  END IF;\n\n  RETURN jsonb_build_object('repaired', true, 'repaired_fields', v_repaired_fields,\n    'validation_rerun', true, 'journal_entry_id', v_journal.id);\nEND;\n$function$","-- delete_fund_transfer(p_id uuid)\nCREATE OR REPLACE FUNCTION public.delete_fund_transfer(p_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_transfer             public.fund_transfers%ROWTYPE;\n  v_je_ids               uuid[];\n  v_period               record;\n  v_dependency           record;\n  v_orphan_count         integer;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  PERFORM public._sec_check_finance_role();\n\n  IF p_id IS NULL THEN\n    RAISE EXCEPTION 'Fund transfer id is required'\n      USING ERRCODE = 'invalid_parameter_value';\n  END IF;\n\n  SELECT *\n    INTO v_transfer\n    FROM public.fund_transfers\n   WHERE id = p_id\n   FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Fund transfer % not found', p_id\n      USING ERRCODE = 'no_data_found';\n  END IF;\n\n  IF v_transfer.status = 'posted' THEN\n    RAISE EXCEPTION\n      'Posted fund transfer % cannot be deleted. Reverse it first, then delete it while the accounting period is open.',\n      v_transfer.transfer_number\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  SELECT ap.fiscal_year, ap.period_month, ap.status\n    INTO v_period\n    FROM public.accounting_periods ap\n   WHERE ap.start_date <= v_transfer.transfer_date\n     AND ap.end_date >= v_transfer.transfer_date\n   ORDER BY ap.start_date DESC\n   LIMIT 1;\n\n  IF FOUND AND v_period.status <> 'open' THEN\n    RAISE EXCEPTION\n      'Cannot delete fund transfer %: accounting period %-% is %.',\n      v_transfer.transfer_number,\n      v_period.fiscal_year,\n      lpad(v_period.period_month::text, 2, '0'),\n      v_period.status\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  SELECT COALESCE(array_agg(DISTINCT je.id), ARRAY[]::uuid[])\n    INTO v_je_ids\n    FROM public.journal_entries je\n   WHERE je.source_module = 'fund_transfers'\n     AND (\n       je.reference_id = p_id\n       OR je.reference_number IN (\n         v_transfer.transfer_number,\n         'REV-' || v_transfer.transfer_number\n       )\n     );\n\n  FOR v_period IN\n    SELECT DISTINCT\n           ap.fiscal_year,\n           ap.period_month,\n           ap.status,\n           je.entry_date\n      FROM public.journal_entries je\n      JOIN public.accounting_periods ap\n        ON ap.start_date <= je.entry_date\n       AND ap.end_date >= je.entry_date\n     WHERE je.id = ANY(v_je_ids)\n       AND ap.status <> 'open'\n  LOOP\n    RAISE EXCEPTION\n      'Cannot delete fund transfer %: journal accounting period %-% for % is %.',\n      v_transfer.transfer_number,\n      v_period.fiscal_year,\n      lpad(v_period.period_month::text, 2, '0'),\n      v_period.entry_date,\n      v_period.status\n      USING ERRCODE = 'check_violation';\n  END LOOP;\n\n  IF EXISTS (\n    SELECT 1\n      FROM public.journal_entries je\n     WHERE je.reversed_by_id = ANY(v_je_ids)\n       AND NOT (je.id = ANY(v_je_ids))\n  ) THEN\n    RAISE EXCEPTION\n      'Cannot delete fund transfer %: an unrelated journal entry depends on its reversal journal.',\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  -- Refuse to let an unexpected ON DELETE action modify another document.\n  -- Expected Contra, ledger, and reconciliation owners are cleaned below.\n  FOR v_dependency IN\n    SELECT c.conrelid::regclass AS relation_name,\n           a.attname AS column_name\n      FROM pg_catalog.pg_constraint c\n      JOIN pg_catalog.pg_attribute a\n        ON a.attrelid = c.conrelid\n       AND a.attnum = c.conkey[1]\n     WHERE c.contype = 'f'\n       AND c.confrelid = 'public.journal_entries'::regclass\n       AND array_length(c.conkey, 1) = 1\n       AND NOT (\n         (c.conrelid = 'public.journal_entry_lines'::regclass\n          AND a.attname = 'journal_entry_id')\n         OR (c.conrelid = 'public.fund_transfers'::regclass\n             AND a.attname = 'journal_entry_id')\n         OR (c.conrelid = 'public.bank_statement_lines'::regclass\n             AND a.attname = 'matched_entry_id')\n         OR (c.conrelid = 'public.bank_reconciliation_items'::regclass\n             AND a.attname = 'journal_entry_id')\n         OR (c.conrelid = 'public.journal_entries'::regclass\n             AND a.attname = 'reversed_by_id')\n       )\n  LOOP\n    EXECUTE format(\n      'SELECT count(*) FROM %s WHERE %I = ANY($1)',\n      v_dependency.relation_name,\n      v_dependency.column_name\n    )\n    INTO v_orphan_count\n    USING v_je_ids;\n\n    IF v_orphan_count <> 0 THEN\n      RAISE EXCEPTION\n        'Cannot delete fund transfer %: % dependent record(s) in % still reference its journal entry.',\n        v_transfer.transfer_number,\n        v_orphan_count,\n        v_dependency.relation_name\n        USING ERRCODE = 'foreign_key_violation';\n    END IF;\n  END LOOP;\n\n  -- Break the Fund Transfer -> Journal Entry FK cycle before deleting journals.\n  UPDATE public.fund_transfers\n     SET journal_entry_id = NULL\n   WHERE id = p_id;\n\n  -- Release only links owned by this Contra or one of its collected journals.\n  UPDATE public.bank_statement_lines\n     SET matched_fund_transfer_id = NULL,\n         matched_entry_id = NULL,\n         reconciliation_status = 'unmatched',\n         matched_at = NULL,\n         matched_by = NULL,\n         notes = NULL\n   WHERE matched_fund_transfer_id = p_id\n      OR matched_entry_id = ANY(v_je_ids);\n\n  UPDATE public.bank_reconciliation_items\n     SET journal_entry_id = NULL,\n         is_matched = false,\n         matched_at = NULL\n   WHERE journal_entry_id = ANY(v_je_ids);\n\n  -- Petty Cash displays current Fund Transfers directly. This cleanup is only\n  -- for legacy projection rows and cannot create or alter accounting.\n  DELETE FROM public.petty_cash_transactions\n   WHERE fund_transfer_id = p_id;\n\n  UPDATE public.journal_entries\n     SET is_reversed = false,\n         reversed_by_id = NULL\n   WHERE id = ANY(v_je_ids)\n     AND reversed_by_id = ANY(v_je_ids);\n\n  DELETE FROM public.journal_entry_lines\n   WHERE journal_entry_id = ANY(v_je_ids);\n\n  DELETE FROM public.journal_entries\n   WHERE id = ANY(v_je_ids);\n\n  DELETE FROM public.fund_transfers\n   WHERE id = p_id;\n\n  -- Every check runs before commit. Any failure rolls the entire deletion back.\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.fund_transfers\n   WHERE id = p_id;\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: fund transfer % still exists. No changes were committed.',\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.journal_entries\n   WHERE id = ANY(v_je_ids)\n      OR (\n        source_module = 'fund_transfers'\n        AND (\n          reference_id = p_id\n          OR reference_number IN (\n            v_transfer.transfer_number,\n            'REV-' || v_transfer.transfer_number\n          )\n        )\n      );\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: % related journal entries remain for fund transfer %. No changes were committed.',\n      v_orphan_count,\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id = ANY(v_je_ids);\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: % related ledger postings remain for fund transfer %. No changes were committed.',\n      v_orphan_count,\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.petty_cash_transactions\n   WHERE fund_transfer_id = p_id;\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: % related Petty Cash rows remain for fund transfer %. No changes were committed.',\n      v_orphan_count,\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.bank_statement_lines\n   WHERE matched_fund_transfer_id = p_id\n      OR matched_entry_id = ANY(v_je_ids);\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: % Bank Reconciliation links remain for fund transfer %. No changes were committed.',\n      v_orphan_count,\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n\n  SELECT count(*)\n    INTO v_orphan_count\n    FROM public.bank_reconciliation_items\n   WHERE journal_entry_id = ANY(v_je_ids);\n  IF v_orphan_count <> 0 THEN\n    RAISE EXCEPTION\n      'Delete failed: % Bank Reconciliation items remain for fund transfer %. No changes were committed.',\n      v_orphan_count,\n      v_transfer.transfer_number\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\nEND;\n$function$","-- delete_payment_voucher_with_allocations(p_voucher_id uuid)\nCREATE OR REPLACE FUNCTION public.delete_payment_voucher_with_allocations(p_voucher_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\nv_invoice_id uuid;\nv_affected_invoice_ids uuid[];\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\nSELECT COALESCE(array_agg(DISTINCT purchase_invoice_id), ARRAY[]::uuid[])\nINTO v_affected_invoice_ids\nFROM public.voucher_allocations\nWHERE payment_voucher_id = p_voucher_id\nAND purchase_invoice_id IS NOT NULL;\n\nDELETE FROM public.voucher_allocations\nWHERE payment_voucher_id = p_voucher_id;\n\nDELETE FROM public.payment_vouchers\nWHERE id = p_voucher_id;\n\nIF NOT FOUND THEN\nRAISE EXCEPTION 'Payment voucher % not found', p_voucher_id;\nEND IF;\n\nFOR v_invoice_id IN SELECT DISTINCT unnest(v_affected_invoice_ids) LOOP\nPERFORM public.recalculate_purchase_invoice_payment_state(v_invoice_id);\nEND LOOP;\nEND;\n$function$","-- delete_expense_safe(p_expense_id uuid)\nCREATE OR REPLACE FUNCTION public.delete_expense_safe(p_expense_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_role text;\n  v_expense public.finance_expenses%ROWTYPE;\n  v_allocation_count integer;\n  v_legacy_count integer;\nBEGIN\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot delete expenses', v_role;\n  END IF;\n\n  SELECT * INTO v_expense\n    FROM public.finance_expenses\n   WHERE id = p_expense_id\n   FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\n\n  SELECT count(*) INTO v_allocation_count\n    FROM public.bank_statement_allocations\n   WHERE document_type = 'expense'\n     AND document_id = p_expense_id;\n\n  -- Separate statement: allocation triggers may safely recalculate the still\n  -- existing expense, then the source row and its journals are deleted.\n  DELETE FROM public.bank_statement_allocations\n   WHERE document_type = 'expense'\n     AND document_id = p_expense_id;\n\n  -- Release pre-allocation legacy links to this expense. Allocation-owned\n  -- lines have already been rebuilt by sync_bank_line_from_allocation().\n  WITH released AS (\n    UPDATE public.bank_statement_lines b SET\n      matched_expense_id = NULL,\n      matched_entry_id = NULL,\n      reconciliation_status = 'unmatched',\n      matching_status = 'none',\n      matched_at = NULL,\n      matched_by = NULL,\n      manually_unlinked = true\n    WHERE b.matched_expense_id = p_expense_id\n      AND NOT EXISTS (\n        SELECT 1 FROM public.bank_statement_allocations a\n         WHERE a.bank_statement_line_id = b.id\n      )\n    RETURNING 1\n  ) SELECT count(*) INTO v_legacy_count FROM released;\n\n  DELETE FROM public.finance_expenses WHERE id = p_expense_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.bank_statement_allocations\n     WHERE document_type = 'expense' AND document_id = p_expense_id\n  ) THEN\n    RAISE EXCEPTION 'Expense delete left orphan bank allocations';\n  END IF;\n  IF EXISTS (\n    SELECT 1 FROM public.bank_statement_lines WHERE matched_expense_id = p_expense_id\n  ) THEN\n    RAISE EXCEPTION 'Expense delete left orphan bank references';\n  END IF;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'released_allocations', v_allocation_count,\n    'released_legacy_lines', v_legacy_count\n  );\nEND;\n$function$","-- delete_purchase_invoice(p_id uuid)\nCREATE OR REPLACE FUNCTION public.delete_purchase_invoice(p_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_invoice           purchase_invoices%ROWTYPE;\n  v_je_ids            UUID[];\n  v_affected_pvs      UUID[];\n  v_original_je_id    UUID;\n  v_orphan_pv_je_ids  UUID[];\n\n  -- integrity-check counters\n  v_orphan_pi         INT;\n  v_orphan_items      INT;\n  v_orphan_allocs     INT;\n  v_orphan_jes        INT;\n  v_orphan_je_lines   INT;\n  v_orphan_bsl_pi     INT;\n  v_orphan_bsl_pv     INT;\n  v_orphan_batches    INT;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'insufficient_privilege';\n  END IF;\n\n  IF p_id IS NULL THEN\n    RAISE EXCEPTION 'Purchase invoice id is required' USING ERRCODE = 'invalid_parameter_value';\n  END IF;\n\n  -- (a) Lock the invoice row.\n  SELECT * INTO v_invoice\n    FROM public.purchase_invoices\n   WHERE id = p_id\n   FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Purchase invoice % not found', p_id USING ERRCODE = 'no_data_found';\n  END IF;\n\n  v_original_je_id := v_invoice.journal_entry_id;\n\n  -- Collect every JE created by this invoice.\n  SELECT COALESCE(array_agg(id), ARRAY[]::UUID[])\n    INTO v_je_ids\n    FROM public.journal_entries\n   WHERE source_module = 'purchase_invoice'\n     AND reference_id  = p_id;\n\n  IF v_original_je_id IS NOT NULL\n     AND NOT v_original_je_id = ANY (v_je_ids) THEN\n    v_je_ids := array_append(v_je_ids, v_original_je_id);\n  END IF;\n\n  -- Payment vouchers that were paying THIS invoice.\n  SELECT COALESCE(array_agg(DISTINCT payment_voucher_id), ARRAY[]::UUID[])\n    INTO v_affected_pvs\n    FROM public.voucher_allocations\n   WHERE purchase_invoice_id = p_id\n     AND payment_voucher_id IS NOT NULL;\n\n  -- Drop the allocations pointing at this invoice.\n  DELETE FROM public.voucher_allocations\n   WHERE purchase_invoice_id = p_id;\n\n  -- Identify PVs whose allocations are now empty and release their bank matches.\n  IF array_length(v_affected_pvs, 1) IS NOT NULL THEN\n    SELECT COALESCE(array_agg(pv.journal_entry_id), ARRAY[]::UUID[])\n      INTO v_orphan_pv_je_ids\n      FROM public.payment_vouchers pv\n     WHERE pv.id = ANY (v_affected_pvs)\n       AND pv.journal_entry_id IS NOT NULL\n       AND NOT EXISTS (\n             SELECT 1\n               FROM public.voucher_allocations va\n              WHERE va.payment_voucher_id = pv.id\n           );\n\n    IF array_length(v_orphan_pv_je_ids, 1) IS NOT NULL THEN\n      UPDATE public.bank_statement_lines\n         SET matched_entry_id        = NULL,\n             matched_expense_id      = NULL,\n             matched_receipt_id      = NULL,\n             matched_petty_cash_id   = NULL,\n             matched_fund_transfer_id= NULL,\n             reconciliation_status   = 'unmatched',\n             matched_at              = NULL,\n             matched_by              = NULL\n       WHERE matched_entry_id = ANY (v_orphan_pv_je_ids);\n    END IF;\n  END IF;\n\n  -- Bank recon cleanup for the PI's OWN JEs (all typed FKs).\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    UPDATE public.bank_statement_lines\n       SET matched_entry_id        = NULL,\n           matched_expense_id      = NULL,\n           matched_receipt_id      = NULL,\n           matched_petty_cash_id   = NULL,\n           matched_fund_transfer_id= NULL,\n           reconciliation_status   = 'unmatched',\n           matched_at              = NULL,\n           matched_by              = NULL\n     WHERE matched_entry_id = ANY (v_je_ids);\n  END IF;\n\n  -- Break invoice → JE FK before deleting the JE.\n  IF v_original_je_id IS NOT NULL THEN\n    UPDATE public.purchase_invoices\n       SET journal_entry_id = NULL\n     WHERE id = p_id;\n  END IF;\n\n  -- Delete JE lines then JE headers.\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    DELETE FROM public.journal_entry_lines\n     WHERE journal_entry_id = ANY (v_je_ids);\n\n    DELETE FROM public.journal_entries\n     WHERE id = ANY (v_je_ids);\n  END IF;\n\n  -- Detach batches.\n  UPDATE public.batches\n     SET purchase_invoice_id = NULL\n   WHERE purchase_invoice_id = p_id;\n\n  -- Belt-and-braces items delete.\n  DELETE FROM public.purchase_invoice_items\n   WHERE purchase_invoice_id = p_id;\n\n  -- Delete the invoice row.\n  DELETE FROM public.purchase_invoices\n   WHERE id = p_id;\n\n  -- ═════════════════════════════════════════════════════════════════════\n  -- INTEGRITY CHECKS\n  --\n  -- Every RAISE EXCEPTION below rolls back this transaction — the invoice\n  -- stays, the JE stays, allocations stay. Better a visible failure than\n  -- silent orphan state on the bank reconciliation screen.\n  -- ═════════════════════════════════════════════════════════════════════\n\n  SELECT COUNT(*) INTO v_orphan_pi\n    FROM public.purchase_invoices\n   WHERE id = p_id;\n  IF v_orphan_pi <> 0 THEN\n    RAISE EXCEPTION\n      'delete_purchase_invoice(%): integrity check failed — purchase_invoices row still present (count=%). Rolling back.',\n      p_id, v_orphan_pi\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_items\n    FROM public.purchase_invoice_items\n   WHERE purchase_invoice_id = p_id;\n  IF v_orphan_items <> 0 THEN\n    RAISE EXCEPTION\n      'delete_purchase_invoice(%): integrity check failed — % orphan purchase_invoice_items remain. Rolling back.',\n      p_id, v_orphan_items\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_allocs\n    FROM public.voucher_allocations\n   WHERE purchase_invoice_id = p_id;\n  IF v_orphan_allocs <> 0 THEN\n    RAISE EXCEPTION\n      'delete_purchase_invoice(%): integrity check failed — % orphan voucher_allocations remain. Rolling back.',\n      p_id, v_orphan_allocs\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_jes\n    FROM public.journal_entries\n   WHERE source_module = 'purchase_invoice'\n     AND reference_id  = p_id;\n  IF v_orphan_jes <> 0 THEN\n    RAISE EXCEPTION\n      'delete_purchase_invoice(%): integrity check failed — % orphan journal_entries (source_module=purchase_invoice) remain. Rolling back.',\n      p_id, v_orphan_jes\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    SELECT COUNT(*) INTO v_orphan_je_lines\n      FROM public.journal_entry_lines\n     WHERE journal_entry_id = ANY (v_je_ids);\n    IF v_orphan_je_lines <> 0 THEN\n      RAISE EXCEPTION\n        'delete_purchase_invoice(%): integrity check failed — % orphan journal_entry_lines remain against deleted JEs. Rolling back.',\n        p_id, v_orphan_je_lines\n        USING ERRCODE = 'raise_exception';\n    END IF;\n\n    SELECT COUNT(*) INTO v_orphan_bsl_pi\n      FROM public.bank_statement_lines\n     WHERE matched_entry_id = ANY (v_je_ids);\n    IF v_orphan_bsl_pi <> 0 THEN\n      RAISE EXCEPTION\n        'delete_purchase_invoice(%): integrity check failed — % bank_statement_lines still matched to deleted PI JEs. Rolling back.',\n        p_id, v_orphan_bsl_pi\n        USING ERRCODE = 'raise_exception';\n    END IF;\n  END IF;\n\n  IF array_length(v_orphan_pv_je_ids, 1) IS NOT NULL THEN\n    SELECT COUNT(*) INTO v_orphan_bsl_pv\n      FROM public.bank_statement_lines\n     WHERE matched_entry_id = ANY (v_orphan_pv_je_ids);\n    IF v_orphan_bsl_pv <> 0 THEN\n      RAISE EXCEPTION\n        'delete_purchase_invoice(%): integrity check failed — % bank_statement_lines still matched to orphan PV JEs. Rolling back.',\n        p_id, v_orphan_bsl_pv\n        USING ERRCODE = 'raise_exception';\n    END IF;\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_batches\n    FROM public.batches\n   WHERE purchase_invoice_id = p_id;\n  IF v_orphan_batches <> 0 THEN\n    RAISE EXCEPTION\n      'delete_purchase_invoice(%): integrity check failed — % batches still tagged to deleted invoice. Rolling back.',\n      p_id, v_orphan_batches\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  -- ═════════════════════════════════════════════════════════════════════\n  -- Audit trail — only reached when every check above passed.\n  -- ═════════════════════════════════════════════════════════════════════\n  BEGIN\n    INSERT INTO public.audit_logs (\n      table_name, record_id, action_type, old_values, new_values, user_id\n    ) VALUES (\n      'purchase_invoices',\n      p_id,\n      'delete',\n      jsonb_build_object(\n        'invoice_number',           v_invoice.invoice_number,\n        'supplier_id',              v_invoice.supplier_id,\n        'invoice_date',             v_invoice.invoice_date,\n        'total_amount',             v_invoice.total_amount,\n        'paid_amount',              v_invoice.paid_amount,\n        'status',                   v_invoice.status,\n        'journal_entry_ids',        to_jsonb(v_je_ids),\n        'payment_voucher_ids',      to_jsonb(v_affected_pvs),\n        'orphan_pv_je_ids_released',to_jsonb(v_orphan_pv_je_ids),\n        'integrity_checks',         'passed'\n      ),\n      jsonb_build_object(\n        '_action',      'DELETE_PURCHASE_INVOICE',\n        'deleted_at',   NOW(),\n        'deleted_by',   auth.uid()\n      ),\n      auth.uid()\n    );\n  EXCEPTION WHEN OTHERS THEN\n    NULL;\n  END;\nEND;\n$function$","-- delete_tax_payment(p_id uuid)\nCREATE OR REPLACE FUNCTION public.delete_tax_payment(p_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_payment        tax_payments%ROWTYPE;\n  v_period_status  text;\n  v_je_ids         uuid[];\n  v_file_urls      text[];\n\n  v_orphan_pay     int;\n  v_orphan_je      int;\n  v_orphan_je_lines int;\n  v_orphan_bsl     int;\n  v_orphan_bri     int;\n  v_orphan_files   int;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'insufficient_privilege';\n  END IF;\n\n  IF p_id IS NULL THEN\n    RAISE EXCEPTION 'Tax payment id is required' USING ERRCODE = 'invalid_parameter_value';\n  END IF;\n\n  -- Lock the row\n  SELECT * INTO v_payment\n    FROM public.tax_payments\n   WHERE id = p_id\n   FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax payment % not found', p_id USING ERRCODE = 'no_data_found';\n  END IF;\n\n  -- Refuse if the period is closed (unless service_role)\n  IF current_setting('request.jwt.claim.role', true) <> 'service_role' THEN\n    SELECT status INTO v_period_status FROM tax_periods WHERE id = v_payment.tax_period_id;\n    IF v_period_status = 'closed' THEN\n      RAISE EXCEPTION 'Tax period is closed; cannot delete tax payment. Reopen the period first.'\n        USING ERRCODE = 'check_violation';\n    END IF;\n  END IF;\n\n  -- Collect JEs owned by this tax payment\n  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])\n    INTO v_je_ids\n    FROM public.journal_entries\n   WHERE source_module = 'tax_payment'\n     AND reference_id  = p_id;\n\n  IF v_payment.journal_entry_id IS NOT NULL\n     AND NOT v_payment.journal_entry_id = ANY (v_je_ids) THEN\n    v_je_ids := array_append(v_je_ids, v_payment.journal_entry_id);\n  END IF;\n\n  -- Release bank_statement_lines matched to this payment.\n  -- NOTE: bank_statement_lines has no updated_at column — do not write it.\n  UPDATE public.bank_statement_lines\n     SET matched_entry_id       = NULL,\n         matched_tax_payment_id = NULL,\n         reconciliation_status  = 'unmatched'\n   WHERE (matched_tax_payment_id = p_id)\n      OR (array_length(v_je_ids, 1) IS NOT NULL AND matched_entry_id = ANY (v_je_ids));\n\n  -- Release bank_reconciliation_items entries\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    UPDATE public.bank_reconciliation_items\n       SET is_matched = false,\n           matched_at = NULL\n     WHERE journal_entry_id = ANY (v_je_ids);\n  END IF;\n\n  -- Snapshot attachment paths BEFORE cascade-deleting the rows\n  SELECT COALESCE(array_agg(file_url), ARRAY[]::text[])\n    INTO v_file_urls\n    FROM public.tax_payment_files\n   WHERE tax_payment_id = p_id;\n\n  DELETE FROM public.tax_payment_files WHERE tax_payment_id = p_id;\n\n  -- Break FK from tax_payments → JE before deleting JE\n  UPDATE public.tax_payments\n     SET journal_entry_id = NULL\n   WHERE id = p_id;\n\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    DELETE FROM public.journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);\n    DELETE FROM public.journal_entries     WHERE id = ANY (v_je_ids);\n  END IF;\n\n  DELETE FROM public.tax_payments WHERE id = p_id;\n\n  -- ═══ INTEGRITY CHECKS ═════════════════════════════════════════════════\n  SELECT COUNT(*) INTO v_orphan_pay FROM public.tax_payments WHERE id = p_id;\n  IF v_orphan_pay <> 0 THEN\n    RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — tax_payments row still present. Rolling back.', p_id\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_je\n    FROM public.journal_entries\n   WHERE source_module = 'tax_payment' AND reference_id = p_id;\n  IF v_orphan_je <> 0 THEN\n    RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % orphan journal_entries (source=tax_payment) remain. Rolling back.', p_id, v_orphan_je\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  IF array_length(v_je_ids, 1) IS NOT NULL THEN\n    SELECT COUNT(*) INTO v_orphan_je_lines\n      FROM public.journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);\n    IF v_orphan_je_lines <> 0 THEN\n      RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % orphan journal_entry_lines remain. Rolling back.', p_id, v_orphan_je_lines\n        USING ERRCODE = 'raise_exception';\n    END IF;\n\n    SELECT COUNT(*) INTO v_orphan_bsl\n      FROM public.bank_statement_lines\n     WHERE matched_entry_id = ANY (v_je_ids);\n    IF v_orphan_bsl <> 0 THEN\n      RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % bank_statement_lines still matched to deleted JE. Rolling back.', p_id, v_orphan_bsl\n        USING ERRCODE = 'raise_exception';\n    END IF;\n\n    SELECT COUNT(*) INTO v_orphan_bri\n      FROM public.bank_reconciliation_items\n     WHERE journal_entry_id = ANY (v_je_ids) AND is_matched = true;\n    IF v_orphan_bri <> 0 THEN\n      RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % bank_reconciliation_items still matched to deleted JE. Rolling back.', p_id, v_orphan_bri\n        USING ERRCODE = 'raise_exception';\n    END IF;\n  END IF;\n\n  SELECT COUNT(*) INTO v_orphan_files FROM public.tax_payment_files WHERE tax_payment_id = p_id;\n  IF v_orphan_files <> 0 THEN\n    RAISE EXCEPTION 'delete_tax_payment(%): integrity check failed — % orphan tax_payment_files remain. Rolling back.', p_id, v_orphan_files\n      USING ERRCODE = 'raise_exception';\n  END IF;\n\n  -- Audit trail (best-effort — do not let audit failure abort the delete)\n  BEGIN\n    INSERT INTO public.audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)\n    VALUES (\n      'tax_payments', p_id, 'delete',\n      jsonb_build_object(\n        'tax_period_id',   v_payment.tax_period_id,\n        'tax_type',        v_payment.tax_type,\n        'amount',          v_payment.amount,\n        'payment_date',    v_payment.payment_date,\n        'status',          v_payment.status,\n        'file_urls',       v_file_urls\n      ),\n      NULL,\n      auth.uid()\n    );\n  EXCEPTION WHEN OTHERS THEN\n    NULL; -- audit failure must not abort the delete\n  END;\nEND $function$","-- reopen_tax_period(p_period_id uuid, p_reason text)\nCREATE OR REPLACE FUNCTION public.reopen_tax_period(p_period_id uuid, p_reason text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nBEGIN\n  IF p_reason IS NULL OR btrim(p_reason) = '' THEN\n    RAISE EXCEPTION 'Reopen reason is required';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM user_profiles\n                 WHERE id = auth.uid() AND role = 'admin' AND is_active = true) THEN\n    RAISE EXCEPTION 'Only admins may reopen a closed tax period';\n  END IF;\n\n  UPDATE tax_periods SET\n    status         = 'reopened',\n    reopen_reason  = p_reason,\n    reopened_at    = now(),\n    reopened_by    = auth.uid(),\n    updated_at     = now()\n  WHERE id = p_period_id AND status = 'closed';\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Period % is not in closed state', p_period_id;\n  END IF;\n\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)\n  VALUES (auth.uid(), 'tax_periods', 'update', p_period_id,\n          jsonb_build_object('action','reopen','reason',p_reason));\nEND $function$","-- close_tax_period(p_period_id uuid)\nCREATE OR REPLACE FUNCTION public.close_tax_period(p_period_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_period                  tax_periods%ROWTYPE;\n  v_missing_faktur          int;\n  v_draft_sales             int;\n  v_draft_purchase          int;\n  v_unposted_je             int;\n  v_unreconciled_payments   int;\n  v_outstanding             numeric(18,2);\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM user_profiles\n                 WHERE id = auth.uid() AND role IN ('admin') AND is_active = true) THEN\n    RAISE EXCEPTION 'Only admins/managers may close a tax period';\n  END IF;\n\n  SELECT * INTO v_period FROM tax_periods WHERE id = p_period_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax period % not found', p_period_id;\n  END IF;\n  IF v_period.status = 'closed' THEN\n    RAISE EXCEPTION 'Tax period already closed';\n  END IF;\n\n  -- Recompute snapshot before validating\n  PERFORM compute_period_ppn(p_period_id);\n  SELECT * INTO v_period FROM tax_periods WHERE id = p_period_id;\n\n  -- 1. Missing Faktur Pajak (PPN only)\n  IF v_period.tax_type = 'PPN' THEN\n    SELECT COUNT(*) INTO v_missing_faktur\n      FROM sales_invoices\n     WHERE tax_period_id = p_period_id\n       AND tax_amount > 0\n       AND (faktur_pajak_number IS NULL OR faktur_pajak_number = '');\n    IF v_missing_faktur > 0 THEN\n      RAISE EXCEPTION 'Cannot close period: % sales invoice(s) missing Faktur Pajak number', v_missing_faktur;\n    END IF;\n  END IF;\n\n  -- 2. No draft sales invoices attributed to this period\n  BEGIN\n    SELECT COUNT(*) INTO v_draft_sales\n      FROM sales_invoices\n     WHERE tax_period_id = p_period_id\n       AND status = 'draft';\n    IF v_draft_sales > 0 THEN\n      RAISE EXCEPTION 'Cannot close period: % draft sales invoice(s) remain', v_draft_sales;\n    END IF;\n  EXCEPTION WHEN undefined_column THEN\n    NULL;  -- sales_invoices.status may not be present in every branch\n  END;\n\n  -- 3. No draft purchase invoices attributed to this period\n  BEGIN\n    SELECT COUNT(*) INTO v_draft_purchase\n      FROM purchase_invoices\n     WHERE tax_period_id = p_period_id\n       AND status = 'draft';\n    IF v_draft_purchase > 0 THEN\n      RAISE EXCEPTION 'Cannot close period: % draft purchase invoice(s) remain', v_draft_purchase;\n    END IF;\n  EXCEPTION WHEN undefined_column THEN\n    NULL;\n  END;\n\n  -- 4. No unposted journal_entries referencing this period's source docs\n  --    (any tax_payment JE where is_posted = false is a blocker)\n  SELECT COUNT(*) INTO v_unposted_je\n    FROM journal_entries je\n    JOIN tax_payments txp ON txp.id = je.reference_id\n   WHERE je.source_module = 'tax_payment'\n     AND txp.tax_period_id = p_period_id\n     AND je.is_posted = false;\n  IF v_unposted_je > 0 THEN\n    RAISE EXCEPTION 'Cannot close period: % unposted journal entries for tax payments', v_unposted_je;\n  END IF;\n\n  -- 5. No unreconciled tax_payments (must all be in status='reconciled')\n  SELECT COUNT(*) INTO v_unreconciled_payments\n    FROM tax_payments\n   WHERE tax_period_id = p_period_id\n     AND status IN ('draft','posted');\n  IF v_unreconciled_payments > 0 THEN\n    RAISE EXCEPTION 'Cannot close period: % unreconciled tax payment(s) remain (status draft or posted)', v_unreconciled_payments;\n  END IF;\n\n  -- 6. Zero outstanding payable\n  SELECT outstanding_amount INTO v_outstanding\n    FROM vw_outstanding_tax\n   WHERE tax_period_id = p_period_id;\n  IF COALESCE(v_outstanding, 0) > 0 THEN\n    RAISE EXCEPTION 'Cannot close period: Rp % still outstanding. Record additional tax payments first.', v_outstanding;\n  END IF;\n\n  -- Flip status\n  UPDATE tax_periods SET\n    status    = 'closed',\n    closed_at = now(),\n    closed_by = auth.uid(),\n    updated_at = now()\n  WHERE id = p_period_id;\n\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)\n  VALUES (auth.uid(), 'tax_periods', 'update', p_period_id,\n          jsonb_build_object(\n            'action', 'close',\n            'status', 'closed',\n            'input_ppn_total',  v_period.input_ppn_total,\n            'output_ppn_total', v_period.output_ppn_total,\n            'net_ppn',          v_period.net_ppn,\n            'pph_total',        v_period.pph_total\n          ));\nEND $function$","-- record_tax_payment(p_tax_period_id uuid, p_tax_type text, p_payment_date date, p_amount numeric, p_bank_account_id uuid, p_billing_code text, p_ntpn text, p_government_reference text, p_notes text)\nCREATE OR REPLACE FUNCTION public.record_tax_payment(p_tax_period_id uuid, p_tax_type text, p_payment_date date, p_amount numeric, p_bank_account_id uuid, p_billing_code text DEFAULT NULL::text, p_ntpn text DEFAULT NULL::text, p_government_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_tp_id            uuid;\n  v_je_id            uuid;\n  v_je_number        text;\n  v_period           tax_periods%ROWTYPE;\n  v_payable_code     text;\n  v_payable_acct_id  uuid;\n  v_bank_acct_coa_id uuid;\n  v_ref_number       text;\nBEGIN\n  IF p_amount IS NULL OR p_amount <= 0 THEN\n    RAISE EXCEPTION 'Tax payment amount must be > 0';\n  END IF;\n\n  SELECT * INTO v_period FROM tax_periods WHERE id = p_tax_period_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax period % not found', p_tax_period_id;\n  END IF;\n  IF v_period.status = 'closed' THEN\n    RAISE EXCEPTION 'Cannot record tax payment on a closed period';\n  END IF;\n  IF v_period.tax_type <> p_tax_type THEN\n    RAISE EXCEPTION 'Tax type mismatch: period is %, payment is %',\n      v_period.tax_type, p_tax_type;\n  END IF;\n\n  -- Map tax type → payable account code\n  v_payable_code := CASE p_tax_type\n    WHEN 'PPN'      THEN '2130'\n    WHEN 'PPh21'    THEN '2131'\n    WHEN 'PPh22'    THEN '2137'\n    WHEN 'PPh23'    THEN '2132'\n    WHEN 'PPh4(2)'  THEN '2138'\n    WHEN 'PPh_Unifikasi' THEN '2131'  -- treated as PPh 21 payable by default\n    ELSE NULL\n  END;\n\n  IF v_payable_code IS NULL THEN\n    RAISE EXCEPTION 'Unknown tax_type: %', p_tax_type;\n  END IF;\n\n  SELECT id INTO v_payable_acct_id FROM chart_of_accounts WHERE code = v_payable_code;\n  IF v_payable_acct_id IS NULL THEN\n    RAISE EXCEPTION 'Payable account % missing from Chart of Accounts', v_payable_code;\n  END IF;\n\n  -- Bank account → CoA account\n  IF p_bank_account_id IS NULL THEN\n    RAISE EXCEPTION 'Bank account is required for a tax payment';\n  END IF;\n  SELECT coa_id INTO v_bank_acct_coa_id FROM bank_accounts WHERE id = p_bank_account_id;\n  IF v_bank_acct_coa_id IS NULL THEN\n    -- Fallback to generic Bank BCA (1111) when bank_accounts.coa_id not wired\n    SELECT id INTO v_bank_acct_coa_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\n  END IF;\n  IF v_bank_acct_coa_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot resolve bank CoA account for tax payment';\n  END IF;\n\n  -- 1) Create tax_payments row (draft)\n  INSERT INTO tax_payments\n    (tax_period_id, tax_type, payment_date, amount,\n     bank_account_id, billing_code, ntpn, government_reference, notes,\n     status, created_by)\n  VALUES\n    (p_tax_period_id, p_tax_type, p_payment_date, p_amount,\n     p_bank_account_id, p_billing_code, p_ntpn, p_government_reference, p_notes,\n     'draft', auth.uid())\n  RETURNING id INTO v_tp_id;\n\n  v_ref_number := COALESCE(NULLIF(p_ntpn,''), NULLIF(p_billing_code,''),\n                           'TAX-' || to_char(p_payment_date, 'YYMM') || '-' || substr(v_tp_id::text, 1, 8));\n\n  -- 2) Post journal entry: Dr Tax Payable / Cr Bank\n  v_je_number := next_journal_entry_number();\n\n  INSERT INTO journal_entries\n    (entry_number, entry_date, source_module, reference_id, reference_number,\n     description, total_debit, total_credit, is_posted, posted_by)\n  VALUES\n    (v_je_number, p_payment_date, 'tax_payment', v_tp_id, v_ref_number,\n     'Tax Payment ' || p_tax_type || ' — ' || v_ref_number,\n     p_amount, p_amount, true, auth.uid())\n  RETURNING id INTO v_je_id;\n\n  INSERT INTO journal_entry_lines\n    (journal_entry_id, line_number, account_id, description, debit, credit)\n  VALUES\n    (v_je_id, 1, v_payable_acct_id,\n     p_tax_type || ' payment — ' || v_ref_number,\n     p_amount, 0),\n    (v_je_id, 2, v_bank_acct_coa_id,\n     'Bank ' || p_tax_type || ' payment — ' || v_ref_number,\n     0, p_amount);\n\n  -- 3) Link back and mark posted\n  UPDATE tax_payments SET\n    journal_entry_id = v_je_id,\n    status           = 'posted',\n    updated_at       = now()\n  WHERE id = v_tp_id;\n\n  -- 4) Nudge the period status if it was open\n  UPDATE tax_periods SET\n    status = CASE WHEN status = 'open' THEN 'payment_pending' ELSE status END,\n    updated_at = now()\n  WHERE id = p_tax_period_id;\n\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)\n  VALUES (auth.uid(), 'tax_payments', 'insert', v_tp_id,\n          jsonb_build_object(\n            'tax_period_id', p_tax_period_id,\n            'tax_type',      p_tax_type,\n            'amount',        p_amount,\n            'journal_entry_id', v_je_id\n          ));\n\n  RETURN v_tp_id;\nEND $function$","-- record_tax_payment(p_tax_period_id uuid, p_tax_type text, p_payment_date date, p_amount numeric, p_bank_account_id uuid, p_billing_code text, p_ntpn text, p_government_reference text, p_notes text, p_payment_reference text)\nCREATE OR REPLACE FUNCTION public.record_tax_payment(p_tax_period_id uuid, p_tax_type text, p_payment_date date, p_amount numeric, p_bank_account_id uuid, p_billing_code text DEFAULT NULL::text, p_ntpn text DEFAULT NULL::text, p_government_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_payment_reference text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_tp_id            uuid;\n  v_je_id            uuid;\n  v_je_number        text;\n  v_period           tax_periods%ROWTYPE;\n  v_payable_code     text;\n  v_payable_acct_id  uuid;\n  v_bank_acct_coa_id uuid;\n  v_ref_number       text;\nBEGIN\n  IF p_amount IS NULL OR p_amount <= 0 THEN\n    RAISE EXCEPTION 'Tax payment amount must be > 0';\n  END IF;\n\n  SELECT * INTO v_period FROM tax_periods WHERE id = p_tax_period_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax period % not found', p_tax_period_id;\n  END IF;\n  IF v_period.status = 'closed' THEN\n    RAISE EXCEPTION 'Cannot record tax payment on a closed period';\n  END IF;\n  IF v_period.tax_type <> p_tax_type THEN\n    RAISE EXCEPTION 'Tax type mismatch: period is %, payment is %',\n      v_period.tax_type, p_tax_type;\n  END IF;\n\n  v_payable_code := CASE p_tax_type\n    WHEN 'PPN'      THEN '2130'\n    WHEN 'PPh21'    THEN '2131'\n    WHEN 'PPh22'    THEN '2137'\n    WHEN 'PPh23'    THEN '2132'\n    WHEN 'PPh4(2)'  THEN '2138'\n    WHEN 'PPh_Unifikasi' THEN '2131'\n    ELSE NULL\n  END;\n\n  IF v_payable_code IS NULL THEN\n    RAISE EXCEPTION 'Unknown tax_type: %', p_tax_type;\n  END IF;\n\n  SELECT id INTO v_payable_acct_id FROM chart_of_accounts WHERE code = v_payable_code;\n  IF v_payable_acct_id IS NULL THEN\n    RAISE EXCEPTION 'Payable account % missing from Chart of Accounts', v_payable_code;\n  END IF;\n\n  IF p_bank_account_id IS NULL THEN\n    RAISE EXCEPTION 'Bank account is required for a tax payment';\n  END IF;\n  SELECT coa_id INTO v_bank_acct_coa_id FROM bank_accounts WHERE id = p_bank_account_id;\n  IF v_bank_acct_coa_id IS NULL THEN\n    SELECT id INTO v_bank_acct_coa_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\n  END IF;\n  IF v_bank_acct_coa_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot resolve bank CoA account for tax payment';\n  END IF;\n\n  INSERT INTO tax_payments\n    (tax_period_id, tax_type, payment_date, amount,\n     bank_account_id, billing_code, ntpn, government_reference,\n     payment_reference, notes,\n     status, created_by)\n  VALUES\n    (p_tax_period_id, p_tax_type, p_payment_date, p_amount,\n     p_bank_account_id, p_billing_code, p_ntpn, p_government_reference,\n     p_payment_reference, p_notes,\n     'draft', auth.uid())\n  RETURNING id INTO v_tp_id;\n\n  v_ref_number := COALESCE(\n    NULLIF(p_ntpn, ''),\n    NULLIF(p_billing_code, ''),\n    NULLIF(p_payment_reference, ''),\n    'TAX-' || to_char(p_payment_date, 'YYMM') || '-' || substr(v_tp_id::text, 1, 8)\n  );\n\n  v_je_number := next_journal_entry_number();\n\n  INSERT INTO journal_entries\n    (entry_number, entry_date, source_module, reference_id, reference_number,\n     description, total_debit, total_credit, is_posted, posted_by)\n  VALUES\n    (v_je_number, p_payment_date, 'tax_payment', v_tp_id, v_ref_number,\n     'Tax Payment ' || p_tax_type || ' — ' || v_ref_number,\n     p_amount, p_amount, true, auth.uid())\n  RETURNING id INTO v_je_id;\n\n  INSERT INTO journal_entry_lines\n    (journal_entry_id, line_number, account_id, description, debit, credit)\n  VALUES\n    (v_je_id, 1, v_payable_acct_id,\n     p_tax_type || ' payment — ' || v_ref_number, p_amount, 0),\n    (v_je_id, 2, v_bank_acct_coa_id,\n     'Bank ' || p_tax_type || ' payment — ' || v_ref_number, 0, p_amount);\n\n  UPDATE tax_payments SET\n    journal_entry_id = v_je_id,\n    status = 'posted',\n    updated_at = now()\n  WHERE id = v_tp_id;\n\n  UPDATE tax_periods SET\n    status = CASE WHEN status = 'open' THEN 'payment_pending' ELSE status END,\n    updated_at = now()\n  WHERE id = p_tax_period_id;\n\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, new_values)\n  VALUES (auth.uid(), 'tax_payments', 'insert', v_tp_id,\n          jsonb_build_object(\n            'tax_period_id',     p_tax_period_id,\n            'tax_type',          p_tax_type,\n            'amount',            p_amount,\n            'journal_entry_id',  v_je_id,\n            'payment_reference', p_payment_reference,\n            'billing_code',      p_billing_code,\n            'ntpn',              p_ntpn\n          ));\n\n  RETURN v_tp_id;\nEND $function$","-- update_tax_payment(p_id uuid, p_payment_date date, p_amount numeric, p_bank_account_id uuid, p_billing_code text, p_ntpn text, p_government_reference text, p_notes text, p_payment_reference text)\nCREATE OR REPLACE FUNCTION public.update_tax_payment(p_id uuid, p_payment_date date, p_amount numeric, p_bank_account_id uuid, p_billing_code text DEFAULT NULL::text, p_ntpn text DEFAULT NULL::text, p_government_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_payment_reference text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_old              tax_payments%ROWTYPE;\n  v_period           tax_periods%ROWTYPE;\n  v_je_number        text;\n  v_je_id            uuid;\n  v_old_je_ids       uuid[];\n  v_payable_code     text;\n  v_payable_acct_id  uuid;\n  v_bank_acct_coa_id uuid;\n  v_ref_number       text;\n  v_is_admin         boolean;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'insufficient_privilege';\n  END IF;\n  IF p_amount IS NULL OR p_amount <= 0 THEN\n    RAISE EXCEPTION 'Tax payment amount must be > 0';\n  END IF;\n  IF p_bank_account_id IS NULL THEN\n    RAISE EXCEPTION 'Bank account is required';\n  END IF;\n\n  SELECT * INTO v_old FROM tax_payments WHERE id = p_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax payment % not found', p_id USING ERRCODE = 'no_data_found';\n  END IF;\n\n  SELECT * INTO v_period FROM tax_periods WHERE id = v_old.tax_period_id;\n  IF v_period.status = 'closed' AND current_setting('request.jwt.claim.role', true) <> 'service_role' THEN\n    RAISE EXCEPTION 'Tax period is closed; cannot edit tax payment. Reopen the period first.'\n      USING ERRCODE = 'check_violation';\n  END IF;\n\n  -- Reconciled payments can only be edited by admin (edit implies breaking\n  -- the current bank reconciliation match). Non-admins must first unmatch\n  -- via the Bank Reconciliation screen.\n  IF v_old.status = 'reconciled' THEN\n    SELECT (up.role = 'admin' AND up.is_active) INTO v_is_admin\n      FROM user_profiles up WHERE up.id = auth.uid();\n    IF NOT COALESCE(v_is_admin, false) THEN\n      RAISE EXCEPTION 'Tax payment is reconciled; only an admin may edit it. Unmatch it in Bank Reconciliation first.'\n        USING ERRCODE = 'insufficient_privilege';\n    END IF;\n  END IF;\n\n  -- Resolve accounts (same logic as record_tax_payment)\n  v_payable_code := CASE v_old.tax_type\n    WHEN 'PPN'      THEN '2130'\n    WHEN 'PPh21'    THEN '2131'\n    WHEN 'PPh22'    THEN '2137'\n    WHEN 'PPh23'    THEN '2132'\n    WHEN 'PPh4(2)'  THEN '2138'\n    WHEN 'PPh_Unifikasi' THEN '2131'\n    ELSE NULL\n  END;\n  IF v_payable_code IS NULL THEN\n    RAISE EXCEPTION 'Unknown tax_type: %', v_old.tax_type;\n  END IF;\n\n  SELECT id INTO v_payable_acct_id FROM chart_of_accounts WHERE code = v_payable_code;\n  IF v_payable_acct_id IS NULL THEN\n    RAISE EXCEPTION 'Payable account % missing from Chart of Accounts', v_payable_code;\n  END IF;\n\n  SELECT coa_id INTO v_bank_acct_coa_id FROM bank_accounts WHERE id = p_bank_account_id;\n  IF v_bank_acct_coa_id IS NULL THEN\n    SELECT id INTO v_bank_acct_coa_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\n  END IF;\n  IF v_bank_acct_coa_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot resolve bank CoA account';\n  END IF;\n\n  -- Reverse old JE(s)\n  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])\n    INTO v_old_je_ids\n    FROM journal_entries\n   WHERE source_module = 'tax_payment' AND reference_id = p_id;\n  IF v_old.journal_entry_id IS NOT NULL AND NOT v_old.journal_entry_id = ANY (v_old_je_ids) THEN\n    v_old_je_ids := array_append(v_old_je_ids, v_old.journal_entry_id);\n  END IF;\n\n  -- Release bank recon matches before deleting the JEs.\n  -- NOTE: bank_statement_lines has no updated_at column — do not write it.\n  UPDATE bank_statement_lines\n     SET matched_entry_id       = NULL,\n         matched_tax_payment_id = NULL,\n         reconciliation_status  = 'unmatched'\n   WHERE matched_tax_payment_id = p_id\n      OR (array_length(v_old_je_ids, 1) IS NOT NULL AND matched_entry_id = ANY (v_old_je_ids));\n\n  IF array_length(v_old_je_ids, 1) IS NOT NULL THEN\n    UPDATE bank_reconciliation_items\n       SET is_matched = false, matched_at = NULL\n     WHERE journal_entry_id = ANY (v_old_je_ids);\n    DELETE FROM journal_entry_lines WHERE journal_entry_id = ANY (v_old_je_ids);\n    DELETE FROM journal_entries     WHERE id = ANY (v_old_je_ids);\n  END IF;\n\n  -- Update the payment row (period + type unchanged; use delete+create for that)\n  UPDATE tax_payments SET\n    payment_date         = p_payment_date,\n    amount               = p_amount,\n    bank_account_id      = p_bank_account_id,\n    billing_code         = p_billing_code,\n    ntpn                 = p_ntpn,\n    government_reference = p_government_reference,\n    notes                = p_notes,\n    payment_reference    = p_payment_reference,\n    journal_entry_id     = NULL,\n    status               = 'draft',\n    updated_at           = now()\n  WHERE id = p_id;\n\n  -- Post fresh JE\n  v_ref_number := COALESCE(\n    NULLIF(p_ntpn, ''), NULLIF(p_billing_code, ''), NULLIF(p_payment_reference, ''),\n    'TAX-' || to_char(p_payment_date, 'YYMM') || '-' || substr(p_id::text, 1, 8)\n  );\n  v_je_number := next_journal_entry_number();\n\n  INSERT INTO journal_entries\n    (entry_number, entry_date, source_module, reference_id, reference_number,\n     description, total_debit, total_credit, is_posted, posted_by)\n  VALUES\n    (v_je_number, p_payment_date, 'tax_payment', p_id, v_ref_number,\n     'Tax Payment ' || v_old.tax_type || ' — ' || v_ref_number,\n     p_amount, p_amount, true, auth.uid())\n  RETURNING id INTO v_je_id;\n\n  INSERT INTO journal_entry_lines\n    (journal_entry_id, line_number, account_id, description, debit, credit)\n  VALUES\n    (v_je_id, 1, v_payable_acct_id,\n     v_old.tax_type || ' payment — ' || v_ref_number, p_amount, 0),\n    (v_je_id, 2, v_bank_acct_coa_id,\n     'Bank ' || v_old.tax_type || ' payment — ' || v_ref_number, 0, p_amount);\n\n  UPDATE tax_payments SET journal_entry_id = v_je_id, status = 'posted', updated_at = now()\n   WHERE id = p_id;\n\n  -- Refresh period snapshot (belt-and-braces; the AFTER trigger also fires)\n  PERFORM compute_period_ppn(v_old.tax_period_id);\n\n  -- Audit log — captures full before/after\n  INSERT INTO audit_logs (user_id, table_name, action_type, record_id, old_values, new_values)\n  VALUES (\n    auth.uid(), 'tax_payments', 'update', p_id,\n    jsonb_build_object(\n      'payment_date',      v_old.payment_date,\n      'amount',            v_old.amount,\n      'bank_account_id',   v_old.bank_account_id,\n      'ntpn',              v_old.ntpn,\n      'billing_code',      v_old.billing_code,\n      'payment_reference', v_old.payment_reference,\n      'notes',             v_old.notes,\n      'status',            v_old.status,\n      'old_je_ids',        to_jsonb(v_old_je_ids)\n    ),\n    jsonb_build_object(\n      'payment_date',      p_payment_date,\n      'amount',            p_amount,\n      'bank_account_id',   p_bank_account_id,\n      'ntpn',              p_ntpn,\n      'billing_code',      p_billing_code,\n      'payment_reference', p_payment_reference,\n      'notes',             p_notes,\n      'new_je_id',         v_je_id,\n      'edited_at',         now()\n    )\n  );\n\n  RETURN p_id;\nEND $function$","-- reassign_tax_document_period(p_source text, p_document_id uuid, p_tax_period_id uuid)\nCREATE OR REPLACE FUNCTION public.reassign_tax_document_period(p_source text, p_document_id uuid, p_tax_period_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_target public.tax_periods%ROWTYPE;\n  v_old_period_id uuid;\n  v_tax_type text;\n  v_tax_code_id uuid;\n  v_doc_date date;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  SELECT * INTO v_target\n    FROM public.tax_periods\n   WHERE id = p_tax_period_id\n   FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Tax period % not found', p_tax_period_id; END IF;\n  IF v_target.status IN ('closed', 'filed') OR v_target.filing_status = 'filed' THEN\n    RAISE EXCEPTION 'Tax period % is filed or closed and cannot be selected', p_tax_period_id;\n  END IF;\n\n  CASE p_source\n    WHEN 'purchase_invoice' THEN\n      SELECT tax_period_id, invoice_date INTO v_old_period_id, v_doc_date FROM public.purchase_invoices WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Purchase invoices require a PPN tax period'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    WHEN 'sales_invoice' THEN\n      SELECT tax_period_id, invoice_date INTO v_old_period_id, v_doc_date FROM public.sales_invoices WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Sales invoice % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Sales invoices require a PPN tax period'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    WHEN 'credit_note' THEN\n      SELECT tax_period_id, issue_date INTO v_old_period_id, v_doc_date FROM public.credit_notes WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Credit note % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Credit notes require a PPN tax period'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    WHEN 'finance_expense_ppn' THEN\n      SELECT tax_period_id, expense_date INTO v_old_period_id, v_doc_date FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Expense % not found', p_document_id; END IF;\n      IF v_target.tax_type <> 'PPN' THEN RAISE EXCEPTION 'Expenses require a PPN tax period for PPN reporting'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = 'PPN' AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    WHEN 'finance_expense_pph' THEN\n      SELECT pph_tax_period_id, pph_code_id, expense_date INTO v_old_period_id, v_tax_code_id, v_doc_date\n        FROM public.finance_expenses WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Expense % not found', p_document_id; END IF;\n      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id;\n      IF v_tax_type IS NULL OR v_target.tax_type <> v_tax_type THEN RAISE EXCEPTION 'Expense PPh tax type must match the selected period'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = v_tax_type AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    WHEN 'payment_voucher' THEN\n      SELECT tax_period_id, pph_code_id, voucher_date INTO v_old_period_id, v_tax_code_id, v_doc_date\n        FROM public.payment_vouchers WHERE id=p_document_id FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found', p_document_id; END IF;\n      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id;\n      IF v_tax_type IS NULL OR v_target.tax_type <> v_tax_type THEN RAISE EXCEPTION 'Payment voucher PPh tax type must match the selected period'; END IF;\n      IF v_old_period_id IS NULL AND v_doc_date IS NOT NULL THEN\n        SELECT id INTO v_old_period_id FROM public.tax_periods WHERE tax_type = v_tax_type AND v_doc_date BETWEEN period_start AND period_end;\n      END IF;\n\n    ELSE\n      RAISE EXCEPTION 'Unsupported tax document source %', p_source;\n  END CASE;\n\n  IF v_old_period_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.tax_periods\n     WHERE id=v_old_period_id AND (status IN ('closed', 'filed') OR filing_status='filed')\n  ) THEN\n    RAISE EXCEPTION 'The current tax period is filed or closed; reopen it before changing this document';\n  END IF;\n\n  CASE p_source\n    WHEN 'purchase_invoice' THEN UPDATE public.purchase_invoices SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'sales_invoice' THEN\n      UPDATE public.sales_invoices SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n      UPDATE public.faktur_pajak SET tax_period_id=p_tax_period_id WHERE sales_invoice_id=p_document_id;\n    WHEN 'credit_note' THEN UPDATE public.credit_notes SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'finance_expense_ppn' THEN UPDATE public.finance_expenses SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'finance_expense_pph' THEN UPDATE public.finance_expenses SET pph_tax_period_id=p_tax_period_id WHERE id=p_document_id;\n    WHEN 'payment_voucher' THEN UPDATE public.payment_vouchers SET tax_period_id=p_tax_period_id WHERE id=p_document_id;\n  END CASE;\n\n  IF v_old_period_id IS NOT NULL AND v_old_period_id <> p_tax_period_id THEN\n    PERFORM public.compute_period_ppn(v_old_period_id);\n  END IF;\n  PERFORM public.compute_period_ppn(p_tax_period_id);\nEND;\n$function$","-- save_finance_exception_corrections_v2(p_corrections jsonb)\nCREATE OR REPLACE FUNCTION public.save_finance_exception_corrections_v2(p_corrections jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  c jsonb;\n  v_type text;\n  v_id uuid;\n  v_exception bigint;\n  v_journal uuid;\n  v_line uuid;\n  v_supplier uuid;\n  v_customer uuid;\n  v_from_bank uuid;\n  v_to_bank uuid;\n  v_from_old uuid;\n  v_to_old uuid;\n  v_from_old_coa uuid;\n  v_to_old_coa uuid;\n  v_from_new_coa uuid;\n  v_to_new_coa uuid;\n  v_from_alias text;\n  v_to_alias text;\n  v_from_currency text;\n  v_to_currency text;\n  v_link_type text;\n  v_link_id uuid;\n  v_result jsonb;\n  v_resolved_ids jsonb := '[]'::jsonb;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  PERFORM public._sec_check_finance_role();\n  IF jsonb_typeof(p_corrections)<>'array' OR jsonb_array_length(p_corrections)=0 THEN\n    RAISE EXCEPTION 'Select at least one correction before saving';\n  END IF;\n  PERFORM set_config('app.finance_historical_repair','on',true);\n  PERFORM set_config('app.finance_metadata_repair','on',true);\n\n  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections) LOOP\n    v_type:=c->>'document_type';\n    v_id:=(c->>'document_id')::uuid;\n    v_exception:=NULLIF(c->>'exception_id','')::bigint;\n    v_journal:=NULLIF(c->>'journal_entry_id','')::uuid;\n    v_line:=NULLIF(c->>'journal_line_id','')::uuid;\n    v_supplier:=NULLIF(c->>'supplier_id','')::uuid;\n    v_customer:=NULLIF(c->>'customer_id','')::uuid;\n    v_from_bank:=NULLIF(c->>'from_bank_account_id','')::uuid;\n    v_to_bank:=NULLIF(c->>'to_bank_account_id','')::uuid;\n    v_link_type:=NULLIF(c->>'linked_document_type','');\n    v_link_id:=NULLIF(c->>'linked_document_id','')::uuid;\n\n    IF NOT EXISTS (SELECT 1 FROM public.finance_exception_correction_dashboard x WHERE x.document_type=v_type AND x.document_id=v_id) THEN\n      RAISE EXCEPTION 'This exception is no longer open';\n    END IF;\n    IF v_supplier IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.suppliers WHERE id=v_supplier AND COALESCE(is_active,true)) THEN\n      RAISE EXCEPTION 'Selected supplier is not active';\n    END IF;\n    IF v_customer IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.customers WHERE id=v_customer) THEN\n      RAISE EXCEPTION 'Selected customer does not exist';\n    END IF;\n\n    IF v_type='expense' THEN\n      UPDATE public.finance_expenses SET\n        expense_type=COALESCE(NULLIF(c->>'expense_subcategory',''),expense_type),\n        supplier_id=COALESCE(v_supplier,supplier_id),\n        payment_reference=COALESCE(NULLIF(c->>'reference',''),payment_reference)\n      WHERE id=v_id;\n    ELSIF v_type='receipt' THEN\n      UPDATE public.receipt_vouchers SET customer_id=COALESCE(v_customer,customer_id),\n        reference_number=COALESCE(NULLIF(c->>'reference',''),reference_number) WHERE id=v_id;\n    ELSIF v_type='payment' THEN\n      UPDATE public.payment_vouchers SET supplier_id=COALESCE(v_supplier,supplier_id),\n        reference_number=COALESCE(NULLIF(c->>'reference',''),reference_number) WHERE id=v_id;\n    ELSIF v_type='loan' THEN\n      UPDATE public.loans SET loan_type=COALESCE(NULLIF(c->>'finance_classification',''),loan_type) WHERE id=v_id;\n    ELSIF v_type='capital_contribution' THEN\n      UPDATE public.capital_contributions SET contribution_type=COALESCE(NULLIF(c->>'finance_classification',''),contribution_type) WHERE id=v_id;\n    END IF;\n\n    IF v_line IS NOT NULL THEN\n      UPDATE public.journal_entry_lines SET\n        supplier_id=COALESCE(v_supplier,supplier_id),customer_id=COALESCE(v_customer,customer_id)\n      WHERE id=v_line AND journal_entry_id=v_journal;\n    END IF;\n\n    IF v_type='fund_transfer' AND (v_from_bank IS NOT NULL OR v_to_bank IS NOT NULL) THEN\n      SELECT from_bank_account_id,to_bank_account_id,journal_entry_id INTO v_from_old,v_to_old,v_journal\n      FROM public.fund_transfers WHERE id=v_id FOR UPDATE;\n      v_from_bank:=COALESCE(v_from_bank,v_from_old);\n      v_to_bank:=COALESCE(v_to_bank,v_to_old);\n      IF v_from_bank=v_to_bank THEN RAISE EXCEPTION 'From Bank and To Bank must be different'; END IF;\n      SELECT coa_id,COALESCE(alias,account_name,bank_name),upper(currency) INTO v_from_new_coa,v_from_alias,v_from_currency\n        FROM public.bank_accounts WHERE id=v_from_bank AND is_active;\n      SELECT coa_id,COALESCE(alias,account_name,bank_name),upper(currency) INTO v_to_new_coa,v_to_alias,v_to_currency\n        FROM public.bank_accounts WHERE id=v_to_bank AND is_active;\n      SELECT coa_id INTO v_from_old_coa FROM public.bank_accounts WHERE id=v_from_old;\n      SELECT coa_id INTO v_to_old_coa FROM public.bank_accounts WHERE id=v_to_old;\n      IF v_from_new_coa IS NULL OR v_to_new_coa IS NULL THEN RAISE EXCEPTION 'Both transfer banks need active Bank Master posting accounts'; END IF;\n      UPDATE public.journal_entry_lines SET account_id=v_from_new_coa\n        WHERE journal_entry_id=v_journal AND account_id=v_from_old_coa AND COALESCE(credit,0)>0;\n      UPDATE public.journal_entry_lines SET account_id=v_to_new_coa\n        WHERE journal_entry_id=v_journal AND account_id=v_to_old_coa AND COALESCE(debit,0)>0;\n      UPDATE public.fund_transfers SET from_bank_account_id=v_from_bank,to_bank_account_id=v_to_bank WHERE id=v_id;\n    END IF;\n\n    IF v_type='bank_reconciliation' AND v_link_id IS NOT NULL THEN\n      IF v_link_type IS NULL THEN RAISE EXCEPTION 'Select the linked document type'; END IF;\n      PERFORM public.link_bank_statement_line(v_id,v_link_type,v_link_id,COALESCE(NULLIF(c->>'payment_type',''),'supplier'));\n    END IF;\n  END LOOP;\n\n  -- Existing RPC owns GL classification, bank master mapping, tax/currency\n  -- metadata, balance protection, audit logging and reason-specific verification.\n  v_result:=public.save_finance_exception_corrections(p_corrections);\n\n  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections) LOOP\n    v_exception:=NULLIF(c->>'exception_id','')::bigint;\n    IF v_exception IS NOT NULL AND COALESCE((c->>'confirm_resolved')::boolean,false)\n       AND EXISTS (\n         SELECT 1 FROM jsonb_each_text(c) x\n         WHERE x.key IN ('expense_category','expense_subcategory','account_id','bank_account_id','from_bank_account_id',\n           'to_bank_account_id','loan_account_id','capital_account_id','tax_code_id','payment_type','document_classification',\n           'exchange_rate','faktur_pajak_number','supplier_id','customer_id','reference','finance_classification','linked_document_id')\n           AND NULLIF(x.value,'') IS NOT NULL\n       ) THEN\n      UPDATE public.finance_historical_repair_exceptions SET status='resolved'\n      WHERE id=v_exception AND status='manual_review';\n    END IF;\n    IF NOT EXISTS (\n      SELECT 1 FROM public.finance_exception_correction_dashboard x\n      WHERE x.document_type=c->>'document_type' AND x.document_id=(c->>'document_id')::uuid\n    ) THEN v_resolved_ids:=v_resolved_ids || jsonb_build_array(c->>'row_id'); END IF;\n  END LOOP;\n\n  RETURN v_result || jsonb_build_object('resolved_row_ids',v_resolved_ids,'verification_refreshed',true);\nEND;\n$function$","-- save_finance_exception_corrections(p_corrections jsonb)\nCREATE OR REPLACE FUNCTION public.save_finance_exception_corrections(p_corrections jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  c jsonb;\n  v_document_type text;\n  v_document_id uuid;\n  v_exception_id bigint;\n  v_reason text;\n  v_journal_id uuid;\n  v_line_id uuid;\n  v_account_id uuid;\n  v_bank_id uuid;\n  v_bank_coa_id uuid;\n  v_bank_currency text;\n  v_tax_code_id uuid;\n  v_tax_type text;\n  v_exchange_rate numeric;\n  v_before_lines jsonb;\n  v_after_lines jsonb;\n  v_resolved boolean := false;\n  v_saved integer := 0;\n  v_resolved_count integer := 0;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  PERFORM public._sec_check_finance_role();\n  IF jsonb_typeof(p_corrections) <> 'array' OR jsonb_array_length(p_corrections)=0 THEN\n    RAISE EXCEPTION 'Select at least one correction before saving';\n  END IF;\n\n  -- Existing source triggers read these flags. Metadata corrections must never\n  -- regenerate journals or recalculate historical debit/credit values.\n  PERFORM set_config('app.finance_historical_repair','on',true);\n  PERFORM set_config('app.finance_metadata_repair','on',true);\n\n  FOR c IN SELECT value FROM jsonb_array_elements(p_corrections)\n  LOOP\n    v_document_type := c->>'document_type';\n    v_document_id := (c->>'document_id')::uuid;\n    v_exception_id := NULLIF(c->>'exception_id','')::bigint;\n    v_line_id := NULLIF(c->>'journal_line_id','')::uuid;\n    v_bank_id := NULLIF(c->>'bank_account_id','')::uuid;\n    v_tax_code_id := NULLIF(c->>'tax_code_id','')::uuid;\n    v_exchange_rate := NULLIF(c->>'exchange_rate','')::numeric;\n    v_resolved := false;\n\n    IF v_exception_id IS NOT NULL THEN\n      SELECT reason INTO v_reason\n      FROM public.finance_historical_repair_exceptions\n      WHERE id=v_exception_id AND document_type=v_document_type\n        AND document_id=v_document_id AND status='manual_review'\n      FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'This exception is no longer open'; END IF;\n    ELSE\n      v_reason := 'Live Finance verification failure';\n      IF NOT EXISTS (\n        SELECT 1 FROM public.finance_exception_correction_dashboard d\n        WHERE d.document_type=v_document_type AND d.document_id=v_document_id\n          AND d.status='Verification failed'\n      ) THEN RAISE EXCEPTION 'This verification failure is no longer open'; END IF;\n    END IF;\n\n    SELECT CASE v_document_type\n      WHEN 'journal' THEN v_document_id\n      WHEN 'receipt' THEN (SELECT journal_entry_id FROM public.receipt_vouchers WHERE id=v_document_id)\n      WHEN 'payment' THEN (SELECT journal_entry_id FROM public.payment_vouchers WHERE id=v_document_id)\n      WHEN 'fund_transfer' THEN (SELECT journal_entry_id FROM public.fund_transfers WHERE id=v_document_id)\n      WHEN 'loan' THEN (SELECT journal_entry_id FROM public.loans WHERE id=v_document_id)\n      WHEN 'loan_transaction' THEN (SELECT journal_entry_id FROM public.loan_transactions WHERE id=v_document_id)\n      WHEN 'loan_repayment' THEN (SELECT journal_entry_id FROM public.loan_transactions WHERE id=v_document_id)\n      WHEN 'capital_contribution' THEN (SELECT journal_entry_id FROM public.capital_contributions WHERE id=v_document_id)\n      WHEN 'tax_payment' THEN (SELECT journal_entry_id FROM public.tax_payments WHERE id=v_document_id)\n      WHEN 'sales_invoice' THEN (SELECT journal_entry_id FROM public.sales_invoices WHERE id=v_document_id)\n      WHEN 'purchase_invoice' THEN (SELECT journal_entry_id FROM public.purchase_invoices WHERE id=v_document_id)\n      WHEN 'bank_reconciliation' THEN (SELECT matched_entry_id FROM public.bank_statement_lines WHERE id=v_document_id)\n      WHEN 'expense' THEN (SELECT id FROM public.journal_entries j WHERE j.source_module IN('expense','expenses')\n        AND (j.reference_id=v_document_id OR j.reference_number='EXP-'||v_document_id::text)\n        AND COALESCE(j.is_reversed,false)=false ORDER BY j.is_posted DESC,j.created_at DESC LIMIT 1)\n      WHEN 'petty_cash' THEN (SELECT id FROM public.journal_entries j WHERE j.source_module='petty_cash'\n        AND j.reference_id=v_document_id AND COALESCE(j.is_reversed,false)=false ORDER BY j.is_posted DESC,j.created_at DESC LIMIT 1)\n    END INTO v_journal_id;\n\n    IF v_journal_id IS NOT NULL THEN\n      SELECT jsonb_agg(jsonb_build_object('id',id,'debit',debit,'credit',credit) ORDER BY id)\n      INTO v_before_lines FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;\n    END IF;\n\n    IF v_bank_id IS NOT NULL THEN\n      SELECT ba.coa_id,upper(ba.currency) INTO v_bank_coa_id,v_bank_currency\n      FROM public.bank_accounts ba JOIN public.chart_of_accounts coa ON coa.id=ba.coa_id\n      WHERE ba.id=v_bank_id AND ba.is_active=true AND coa.is_active=true AND COALESCE(coa.is_header,false)=false;\n      IF v_bank_coa_id IS NULL THEN RAISE EXCEPTION 'Selected bank has no active posting account'; END IF;\n    END IF;\n\n    v_account_id := COALESCE(NULLIF(c->>'account_id','')::uuid,\n      NULLIF(c->>'loan_account_id','')::uuid,\n      NULLIF(c->>'capital_account_id','')::uuid,\n      CASE WHEN v_bank_id IS NOT NULL THEN v_bank_coa_id END);\n    IF v_account_id IS NOT NULL AND NOT EXISTS (\n      SELECT 1 FROM public.chart_of_accounts WHERE id=v_account_id AND is_active=true AND COALESCE(is_header,false)=false\n    ) THEN RAISE EXCEPTION 'Selected account is not an active posting account'; END IF;\n\n    IF v_tax_code_id IS NOT NULL THEN\n      SELECT tax_type INTO v_tax_type FROM public.tax_codes WHERE id=v_tax_code_id AND is_active=true;\n      IF v_tax_type IS NULL THEN RAISE EXCEPTION 'Selected tax category is not active'; END IF;\n    END IF;\n\n    -- Source metadata. Every assignment is to an existing row; no insert,\n    -- delete, posting, numbering, date, narration, or amount field is allowed.\n    IF v_document_type='expense' THEN\n      UPDATE public.finance_expenses SET\n        expense_category=COALESCE(NULLIF(c->>'expense_category',''),expense_category),\n        payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),\n        bank_account_id=COALESCE(v_bank_id,bank_account_id),\n        pph_code_id=COALESCE(v_tax_code_id,pph_code_id),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),\n        currency_code=COALESCE(v_bank_currency,currency_code),\n        payment_currency=COALESCE(v_bank_currency,payment_currency),\n        bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),\n        functional_currency=COALESCE(functional_currency,'IDR')\n      WHERE id=v_document_id;\n    ELSIF v_document_type='receipt' THEN\n      UPDATE public.receipt_vouchers SET payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),\n        bank_account_id=COALESCE(v_bank_id,bank_account_id),exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency_code=COALESCE(v_bank_currency,currency_code),\n        payment_currency=COALESCE(v_bank_currency,payment_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),\n        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;\n    ELSIF v_document_type='payment' THEN\n      UPDATE public.payment_vouchers SET payment_method=COALESCE(NULLIF(c->>'payment_type',''),payment_method),\n        bank_account_id=COALESCE(v_bank_id,bank_account_id),pph_code_id=COALESCE(v_tax_code_id,pph_code_id),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency_code=COALESCE(v_bank_currency,currency_code),\n        payment_currency=COALESCE(v_bank_currency,payment_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),\n        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;\n    ELSIF v_document_type='loan' THEN\n      UPDATE public.loans SET bank_account_id=COALESCE(v_bank_id,bank_account_id),\n        coa_id=COALESCE(NULLIF(c->>'loan_account_id','')::uuid,coa_id),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),currency=COALESCE(v_bank_currency,currency),\n        bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),functional_currency=COALESCE(functional_currency,'IDR')\n      WHERE id=v_document_id;\n    ELSIF v_document_type IN ('loan_transaction','loan_repayment') THEN\n      UPDATE public.loan_transactions SET bank_account_id=COALESCE(v_bank_id,bank_account_id),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),\n        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;\n    ELSIF v_document_type='capital_contribution' THEN\n      UPDATE public.capital_contributions SET bank_account_id=COALESCE(v_bank_id,bank_account_id),\n        contribution_type=COALESCE(NULLIF(c->>'expense_category',''),contribution_type),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),bank_account_currency=COALESCE(v_bank_currency,bank_account_currency),\n        functional_currency=COALESCE(functional_currency,'IDR') WHERE id=v_document_id;\n    ELSIF v_document_type='petty_cash' THEN\n      UPDATE public.petty_cash_transactions SET expense_category=COALESCE(NULLIF(c->>'expense_category',''),expense_category),\n        bank_account_id=COALESCE(v_bank_id,bank_account_id) WHERE id=v_document_id;\n    ELSIF v_document_type='tax_payment' THEN\n      UPDATE public.tax_payments SET bank_account_id=COALESCE(v_bank_id,bank_account_id),\n        tax_type=COALESCE(v_tax_type,tax_type) WHERE id=v_document_id;\n    ELSIF v_document_type='sales_invoice' AND NULLIF(c->>'faktur_pajak_number','') IS NOT NULL THEN\n      UPDATE public.sales_invoices SET faktur_pajak_number=c->>'faktur_pajak_number' WHERE id=v_document_id;\n    ELSIF v_document_type='purchase_invoice' AND NULLIF(c->>'faktur_pajak_number','') IS NOT NULL THEN\n      UPDATE public.purchase_invoices SET faktur_pajak_number=c->>'faktur_pajak_number' WHERE id=v_document_id;\n    ELSIF v_document_type='bank_reconciliation' AND NULLIF(c->>'payment_type','') IS NOT NULL THEN\n      UPDATE public.bank_statement_lines SET payment_kind=c->>'payment_type' WHERE id=v_document_id;\n    END IF;\n\n    IF v_journal_id IS NOT NULL THEN\n      UPDATE public.journal_entries SET\n        source_module=COALESCE(NULLIF(c->>'document_classification',''),source_module),\n        transaction_currency=COALESCE(v_bank_currency,transaction_currency),\n        functional_currency=COALESCE(functional_currency,'IDR'),\n        exchange_rate=COALESCE(v_exchange_rate,CASE WHEN v_bank_currency='IDR' THEN 1 END,exchange_rate),\n        amounts_are_functional=COALESCE(amounts_are_functional,true)\n      WHERE id=v_journal_id;\n    END IF;\n\n    IF v_account_id IS NOT NULL THEN\n      IF v_line_id IS NULL OR NOT EXISTS (\n        SELECT 1 FROM public.journal_entry_lines WHERE id=v_line_id AND journal_entry_id=v_journal_id\n      ) THEN RAISE EXCEPTION 'The account line can no longer be identified safely'; END IF;\n      UPDATE public.journal_entry_lines SET account_id=v_account_id WHERE id=v_line_id;\n    END IF;\n\n    IF v_journal_id IS NOT NULL THEN\n      SELECT jsonb_agg(jsonb_build_object('id',id,'debit',debit,'credit',credit) ORDER BY id)\n      INTO v_after_lines FROM public.journal_entry_lines WHERE journal_entry_id=v_journal_id;\n      IF v_before_lines IS DISTINCT FROM v_after_lines THEN\n        RAISE EXCEPTION 'Correction cancelled because a debit or credit value changed';\n      END IF;\n    END IF;\n\n    -- Resolve only when the specific historical problem is now disproved.\n    IF v_reason ILIKE '%missing Faktur Pajak%' THEN\n      v_resolved := EXISTS(SELECT 1 FROM public.sales_invoices WHERE id=v_document_id AND NULLIF(btrim(faktur_pajak_number),'') IS NOT NULL)\n        OR EXISTS(SELECT 1 FROM public.purchase_invoices WHERE id=v_document_id AND NULLIF(btrim(faktur_pajak_number),'') IS NOT NULL);\n    ELSIF v_reason ILIKE '%no historical transaction-date rate%' OR v_reason ILIKE '%no authoritative historical rate%' THEN\n      v_resolved := v_exchange_rate IS NOT NULL AND v_exchange_rate>0;\n    ELSIF v_reason ILIKE '%does not use the Expense bank account%' OR v_reason ILIKE '%does not post to this bank account%' THEN\n      v_resolved := EXISTS(SELECT 1 FROM public.journal_entry_lines jl JOIN public.bank_accounts ba ON ba.coa_id=jl.account_id\n        WHERE jl.journal_entry_id=v_journal_id AND ba.id=COALESCE(v_bank_id,(SELECT bank_account_id FROM public.bank_statement_lines WHERE id=v_document_id)));\n    ELSIF v_reason ILIKE 'No unique authoritative relationship%' THEN\n      IF v_document_type='expense' THEN v_resolved := EXISTS(SELECT 1 FROM public.finance_expenses x WHERE x.id=v_document_id\n        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL\n        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL));\n      ELSIF v_document_type='receipt' THEN v_resolved := EXISTS(SELECT 1 FROM public.receipt_vouchers x WHERE x.id=v_document_id\n        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL\n        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL));\n      ELSIF v_document_type='payment' THEN v_resolved := EXISTS(SELECT 1 FROM public.payment_vouchers x WHERE x.id=v_document_id\n        AND x.transaction_currency IS NOT NULL AND x.functional_currency IS NOT NULL AND x.currency_code IS NOT NULL\n        AND x.exchange_rate IS NOT NULL AND x.payment_method IS NOT NULL AND (x.payment_method<>'bank_transfer' OR x.bank_account_id IS NOT NULL)); END IF;\n    ELSIF v_reason ILIKE '%metadata conflicts%' THEN\n      v_resolved := v_bank_id IS NOT NULL;\n    ELSIF v_reason ILIKE '%Journal metadata cannot be derived%' THEN\n      v_resolved := EXISTS(SELECT 1 FROM public.journal_entries WHERE id=v_journal_id AND source_module IS NOT NULL\n        AND transaction_currency IS NOT NULL AND functional_currency IS NOT NULL\n        AND (transaction_currency='IDR' OR exchange_rate IS NOT NULL));\n    END IF;\n\n    IF v_exception_id IS NOT NULL AND v_resolved THEN\n      UPDATE public.finance_historical_repair_exceptions SET status='resolved' WHERE id=v_exception_id;\n      v_resolved_count := v_resolved_count + 1;\n    END IF;\n\n    INSERT INTO public.audit_logs(table_name,action_type,record_id,old_values,new_values,changed_fields)\n    VALUES('finance_exception_correction_dashboard','update',v_document_id,\n      jsonb_build_object('exception_id',v_exception_id,'journal_lines',v_before_lines),\n      jsonb_build_object('correction',c,'journal_lines',v_after_lines,'resolved',v_resolved),\n      ARRAY['finance_metadata','account_classification','exception_status']);\n    v_saved := v_saved + 1;\n  END LOOP;\n\n  RETURN jsonb_build_object('saved',v_saved,'resolved',v_resolved_count,'refresh_required',true);\nEND;\n$function$","-- save_bank_linked_finance_journal(p_bank_line_id uuid, p_description text, p_counter_account_code text, p_bank_side text, p_transaction_currency text, p_exchange_rate numeric)\nCREATE OR REPLACE FUNCTION public.save_bank_linked_finance_journal(p_bank_line_id uuid, p_description text, p_counter_account_code text, p_bank_side text, p_transaction_currency text, p_exchange_rate numeric)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_line public.bank_statement_lines%ROWTYPE; v_bank_coa uuid; v_counter_coa uuid;\n  v_amount numeric; v_journal uuid; v_lines jsonb; v_result jsonb;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  PERFORM public._sec_check_finance_role();\n  SELECT * INTO v_line FROM public.bank_statement_lines WHERE id=p_bank_line_id FOR UPDATE;\n  IF NOT FOUND OR v_line.matched_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Bank statement line is missing or already linked'; END IF;\n  SELECT coa_id INTO v_bank_coa FROM public.bank_accounts WHERE id=v_line.bank_account_id AND is_active=true AND upper(currency)=upper(p_transaction_currency);\n  SELECT id INTO v_counter_coa FROM public.chart_of_accounts WHERE code=p_counter_account_code AND is_active=true AND COALESCE(is_header,false)=false;\n  IF v_bank_coa IS NULL OR v_counter_coa IS NULL THEN RAISE EXCEPTION 'Bank or counter account is not configured'; END IF;\n  IF p_bank_side='debit' THEN v_amount:=COALESCE(v_line.credit_amount,0);\n  ELSIF p_bank_side='credit' THEN v_amount:=COALESCE(v_line.debit_amount,0);\n  ELSE RAISE EXCEPTION 'Bank side must be debit or credit'; END IF;\n  IF v_amount<=0 THEN RAISE EXCEPTION 'Bank statement direction does not match this journal action'; END IF;\n  v_lines:=CASE WHEN p_bank_side='debit' THEN jsonb_build_array(\n      jsonb_build_object('account_id',v_bank_coa,'description',p_description,'debit',v_amount,'credit',0),\n      jsonb_build_object('account_id',v_counter_coa,'description',p_description,'debit',0,'credit',v_amount))\n    ELSE jsonb_build_array(\n      jsonb_build_object('account_id',v_counter_coa,'description',p_description,'debit',v_amount,'credit',0),\n      jsonb_build_object('account_id',v_bank_coa,'description',p_description,'debit',0,'credit',v_amount)) END;\n  v_journal:=public.save_finance_journal(NULL,v_line.transaction_date,p_description,v_lines,upper(p_transaction_currency),p_exchange_rate);\n  v_result:=public.link_bank_statement_line(p_bank_line_id,'journal',v_journal,'supplier');\n  RETURN jsonb_build_object('document_id',v_journal,'journal_entry_id',v_journal,'link',v_result);\nEND $function$","-- undo_reverse_fund_transfer(p_id uuid, p_reason text)\nCREATE OR REPLACE FUNCTION public.undo_reverse_fund_transfer(p_id uuid, p_reason text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_message  text;\n  v_conflict jsonb;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  BEGIN\n    RETURN public.undo_reverse_fund_transfer_core(p_id, p_reason);\n  EXCEPTION WHEN integrity_constraint_violation THEN\n    GET STACKED DIAGNOSTICS v_message = MESSAGE_TEXT;\n\n    IF v_message LIKE\n       'Cannot undo reversal: the % bank statement line is now linked to another transaction' THEN\n      v_conflict := public.describe_undo_reverse_bank_conflict(p_id);\n      IF v_conflict IS NOT NULL THEN\n        RAISE EXCEPTION '%', v_message\n          USING\n            ERRCODE = 'integrity_constraint_violation',\n            DETAIL = v_conflict::text;\n      END IF;\n    END IF;\n\n    RAISE;\n  END;\nEND;\n$function$","-- post_fund_transfer_journal(p_transfer_id uuid, p_user_id uuid)\nCREATE OR REPLACE FUNCTION public.post_fund_transfer_journal(p_transfer_id uuid, p_user_id uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public, pg_temp'\nAS $function$\nDECLARE\nv_transfer        RECORD;\nv_journal_id      UUID;\nv_from_account_id UUID;\nv_to_account_id   UUID;\nv_description     TEXT;\nv_role            text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot post fund transfer journals', v_role;\nEND IF;\n\nSELECT * INTO v_transfer FROM fund_transfers WHERE id = p_transfer_id;\nIF NOT FOUND THEN RAISE EXCEPTION 'Fund transfer not found'; END IF;\nIF v_transfer.journal_entry_id IS NOT NULL THEN RETURN v_transfer.journal_entry_id; END IF;\n\nSELECT id INTO v_journal_id FROM journal_entries\nWHERE reference_number = v_transfer.transfer_number AND source_module = 'fund_transfers'\nORDER BY created_at DESC LIMIT 1;\nIF v_journal_id IS NOT NULL THEN\nUPDATE fund_transfers SET journal_entry_id = v_journal_id WHERE id = p_transfer_id;\nRETURN v_journal_id;\nEND IF;\n\nIF    v_transfer.from_account_type = 'petty_cash'   THEN SELECT id INTO v_from_account_id FROM chart_of_accounts WHERE code = '1102' LIMIT 1;\nELSIF v_transfer.from_account_type = 'cash_on_hand' THEN SELECT id INTO v_from_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\nELSIF v_transfer.from_account_type = 'bank'         THEN SELECT coa_id INTO v_from_account_id FROM bank_accounts WHERE id = v_transfer.from_bank_account_id;\nEND IF;\n\nIF    v_transfer.to_account_type = 'petty_cash'   THEN SELECT id INTO v_to_account_id FROM chart_of_accounts WHERE code = '1102' LIMIT 1;\nELSIF v_transfer.to_account_type = 'cash_on_hand' THEN SELECT id INTO v_to_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\nELSIF v_transfer.to_account_type = 'bank'         THEN SELECT coa_id INTO v_to_account_id FROM bank_accounts WHERE id = v_transfer.to_bank_account_id;\nEND IF;\n\nIF v_from_account_id IS NULL OR v_to_account_id IS NULL THEN\nRAISE EXCEPTION 'Cannot determine chart of accounts for transfer';\nEND IF;\n\nv_description := 'Fund Transfer ' || v_transfer.transfer_number;\nIF v_transfer.description IS NOT NULL THEN\nv_description := v_description || ' - ' || v_transfer.description;\nEND IF;\n\nINSERT INTO journal_entries (\nentry_date, source_module, reference_id, reference_number,\ndescription, total_debit, total_credit, is_posted, created_by\n) VALUES (\nv_transfer.transfer_date, 'fund_transfers', v_transfer.id, v_transfer.transfer_number,\nv_description, 0, 0, true, p_user_id\n) RETURNING id INTO v_journal_id;\n\nINSERT INTO journal_entry_lines (journal_entry_id, account_id, debit, credit, description)\nVALUES\n(v_journal_id, v_to_account_id,   v_transfer.amount, 0,                  'Transfer In'),\n(v_journal_id, v_from_account_id, 0,                  v_transfer.amount, 'Transfer Out');\n\nUPDATE fund_transfers SET journal_entry_id = v_journal_id WHERE id = p_transfer_id;\nRETURN v_journal_id;\nEND;\n$function$","-- post_payment_voucher(p_pv_id uuid, p_posted_by uuid)\nCREATE OR REPLACE FUNCTION public.post_payment_voucher(p_pv_id uuid, p_posted_by uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_pv record; v_je uuid; v_ap uuid; v_bank uuid; v_charge uuid; v_pph uuid; v_fx uuid;\n  v_invoice_currency text; v_bank_currency text; v_rate numeric; v_gross numeric;\n  v_payment numeric; v_converted numeric; v_pph_bank numeric; v_actual numeric; v_charge_amt numeric;\n  v_expected numeric; v_fx_delta numeric; v_ap_debit numeric; v_total numeric; v_line int := 1; v_entry text;\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;\n  SELECT * INTO v_pv FROM public.payment_vouchers WHERE id=p_pv_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found',p_pv_id; END IF;\n  IF v_pv.is_posted THEN RAISE EXCEPTION 'Payment voucher % is already posted',v_pv.voucher_number; END IF;\n\n  v_invoice_currency := upper(COALESCE(v_pv.invoice_currency,v_pv.transaction_currency,v_pv.payment_currency,'IDR'));\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id=v_pv.bank_account_id;\n  v_bank_currency := COALESCE(v_bank_currency,v_pv.bank_currency,v_pv.payment_currency,'IDR');\n  v_rate := CASE WHEN v_invoice_currency=v_bank_currency THEN 1 ELSE COALESCE(v_pv.exchange_rate,0) END;\n  IF v_rate <= 0 THEN RAISE EXCEPTION 'Missing exchange rate for %',v_pv.voucher_number; END IF;\n\n  v_gross := COALESCE(v_pv.invoice_amount,v_pv.amount,0);\n  v_payment := COALESCE(v_pv.payment_amount,v_gross-COALESCE(v_pv.pph_amount,0));\n  v_converted := COALESCE(v_pv.converted_amount,v_payment*v_rate);\n  v_pph_bank := COALESCE(v_pv.pph_amount,0)*v_rate;\n  v_charge_amt := COALESCE(v_pv.bank_charge,0);\n  v_actual := COALESCE(v_pv.actual_bank_debit,v_pv.bank_amount,v_converted+v_charge_amt);\n  v_expected := v_converted+v_charge_amt;\n  v_fx_delta := v_actual-v_expected;\n  v_ap_debit := v_gross*v_rate;\n\n  IF v_pv.coa_account_id IS NOT NULL THEN\n    v_ap := v_pv.coa_account_id;\n  ELSE\n    SELECT id INTO v_ap FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n  END IF;\n  IF v_pv.payment_method = 'advance_adjustment' OR v_pv.payment_purpose = 'salary_advance' THEN\n    SELECT id INTO v_bank FROM public.chart_of_accounts WHERE code='1160' LIMIT 1;\n  ELSE\n    SELECT coa_id INTO v_bank FROM public.bank_accounts WHERE id=v_pv.bank_account_id;\n    IF v_bank IS NULL THEN SELECT id INTO v_bank FROM public.chart_of_accounts WHERE code='1101' LIMIT 1; END IF;\n  END IF;\n  SELECT id INTO v_charge FROM public.chart_of_accounts WHERE code='7100' LIMIT 1;\n  SELECT id INTO v_pph FROM public.chart_of_accounts WHERE code='2132' LIMIT 1;\n  SELECT id INTO v_fx FROM public.chart_of_accounts WHERE code='7300' LIMIT 1;\n  IF v_ap IS NULL OR v_bank IS NULL THEN RAISE EXCEPTION 'Required payment accounts are missing'; END IF;\n  IF v_pph_bank > 0 AND v_pph IS NULL THEN RAISE EXCEPTION 'PPh payable account is missing'; END IF;\n\n  v_total := v_ap_debit + v_charge_amt + GREATEST(v_fx_delta,0);\n  v_entry := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(entry_number,entry_date,source_module,reference_id,reference_number,description,total_debit,total_credit,is_posted,posted_by)\n  VALUES(v_entry,v_pv.voucher_date,'payment',v_pv.id,v_pv.voucher_number,'Payment Voucher: '||v_pv.voucher_number,v_total,v_total,true,p_posted_by)\n  RETURNING id INTO v_je;\n\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)\n  VALUES(v_je,v_line,v_ap,'Payment - '||v_pv.voucher_number,v_ap_debit,0,v_invoice_currency,v_gross,0,v_rate,v_pv.supplier_id); v_line:=v_line+1;\n  IF v_charge_amt>0 AND v_charge IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)\n    VALUES(v_je,v_line,v_charge,'Bank Charge - '||v_pv.voucher_number,v_charge_amt,0,v_bank_currency,v_charge_amt,0,1,v_pv.supplier_id); v_line:=v_line+1;\n  END IF;\n  IF v_pph_bank>0 AND v_pph IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)\n    VALUES(v_je,v_line,v_pph,'PPh Withholding - '||v_pv.voucher_number,0,v_pph_bank,v_bank_currency,0,v_pv.pph_amount,v_rate,v_pv.supplier_id); v_line:=v_line+1;\n  END IF;\n  INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_debit,transaction_credit,exchange_rate,supplier_id)\n  VALUES(v_je,v_line,v_bank,CASE WHEN v_pv.payment_method='advance_adjustment' THEN 'Advance Adjustment - ' ELSE 'Bank Payment - ' END||v_pv.voucher_number,0,v_actual,v_bank_currency,0,v_actual,1,v_pv.supplier_id); v_line:=v_line+1;\n  IF v_fx_delta>0 AND v_fx IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n    VALUES(v_je,v_line,v_fx,'FX loss - '||v_pv.voucher_number,v_fx_delta,0,v_pv.supplier_id);\n  ELSIF v_fx_delta<0 AND v_fx IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id,line_number,account_id,description,debit,credit,supplier_id)\n    VALUES(v_je,v_line,v_fx,'FX gain - '||v_pv.voucher_number,0,abs(v_fx_delta),v_pv.supplier_id);\n  END IF;\n  UPDATE public.payment_vouchers SET is_posted=true,journal_entry_id=v_je WHERE id=p_pv_id;\n  INSERT INTO public.audit_logs(table_name,record_id,action_type,old_values,new_values,user_id)\n  VALUES('payment_vouchers',p_pv_id,'update',jsonb_build_object('is_posted',false),jsonb_build_object('is_posted',true,'journal_entry_id',v_je),p_posted_by);\nEND; $function$","-- post_receipt_voucher(p_rv_id uuid, p_posted_by uuid)\nCREATE OR REPLACE FUNCTION public.post_receipt_voucher(p_rv_id uuid, p_posted_by uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\nv_rv                 RECORD;\nv_je_id              UUID;\nv_je_number          TEXT;\nv_debit_account_id   UUID;\nv_credit_account_id  UUID;\nBEGIN\nIF auth.uid() IS NULL THEN\nRAISE EXCEPTION 'Not authenticated';\nEND IF;\n\nSELECT * INTO v_rv FROM receipt_vouchers WHERE id = p_rv_id FOR UPDATE;\nIF NOT FOUND THEN RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id; END IF;\nIF v_rv.is_posted THEN RAISE EXCEPTION 'Receipt voucher % is already posted', v_rv.voucher_number; END IF;\n\nIF v_rv.bank_account_id IS NOT NULL THEN\nSELECT coa_id INTO v_debit_account_id FROM bank_accounts WHERE id = v_rv.bank_account_id;\nELSIF v_rv.payment_method = 'cash' THEN\nSELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\nEND IF;\nIF v_debit_account_id IS NULL THEN\nSELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\nEND IF;\n\nIF v_rv.coa_account_id IS NOT NULL THEN\nv_credit_account_id := v_rv.coa_account_id;\nELSE\nSELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1120' LIMIT 1;\nEND IF;\n\nIF v_debit_account_id IS NULL OR v_credit_account_id IS NULL THEN\nRAISE EXCEPTION 'Cannot post: required chart of accounts entries missing';\nEND IF;\n\nv_je_number := next_journal_entry_number();\n\nINSERT INTO journal_entries (\nentry_number, entry_date, source_module, reference_id, reference_number,\ndescription, total_debit, total_credit, is_posted, posted_by\n) VALUES (\nv_je_number, v_rv.voucher_date, 'receipt', v_rv.id, v_rv.voucher_number,\n'Receipt Voucher: ' || v_rv.voucher_number,\nv_rv.amount, v_rv.amount, TRUE, p_posted_by\n) RETURNING id INTO v_je_id;\n\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\nVALUES (v_je_id, 1, v_debit_account_id, 'Cash Receipt - ' || v_rv.voucher_number, v_rv.amount, 0, v_rv.customer_id);\nINSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\nVALUES (v_je_id, 2, v_credit_account_id, 'Receipt - ' || v_rv.voucher_number, 0, v_rv.amount, v_rv.customer_id);\n\nUPDATE receipt_vouchers\nSET is_posted = TRUE, journal_entry_id = v_je_id\nWHERE id = p_rv_id;\n\nINSERT INTO audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)\nVALUES (\n'receipt_vouchers', p_rv_id, 'update',\njsonb_build_object('is_posted', FALSE),\njsonb_build_object('is_posted', TRUE, 'journal_entry_id', v_je_id, 'journal_entry_number', v_je_number, 'posted_by', p_posted_by),\np_posted_by\n);\nEND;\n$function$","-- create_fund_transfer_with_posting(p_transfer_date date, p_from_amount numeric, p_to_amount numeric, p_from_account_type text, p_to_account_type text, p_description text, p_from_bank_account_id uuid, p_to_bank_account_id uuid, p_from_bank_statement_line_id uuid, p_to_bank_statement_line_id uuid, p_exchange_rate numeric, p_created_by uuid)\nCREATE OR REPLACE FUNCTION public.create_fund_transfer_with_posting(p_transfer_date date, p_from_amount numeric, p_to_amount numeric, p_from_account_type text, p_to_account_type text, p_description text DEFAULT NULL::text, p_from_bank_account_id uuid DEFAULT NULL::uuid, p_to_bank_account_id uuid DEFAULT NULL::uuid, p_from_bank_statement_line_id uuid DEFAULT NULL::uuid, p_to_bank_statement_line_id uuid DEFAULT NULL::uuid, p_exchange_rate numeric DEFAULT NULL::numeric, p_created_by uuid DEFAULT NULL::uuid)\n RETURNS fund_transfers\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_user_id uuid;\n  v_transfer_number text;\n  v_transfer public.fund_transfers;\n  v_source_account_name text;\nBEGIN\n  v_user_id := COALESCE(p_created_by, auth.uid());\n  IF v_user_id IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  v_transfer_number := public.generate_fund_transfer_number();\n\n  INSERT INTO public.fund_transfers (\n    transfer_number,\n    transfer_date,\n    amount,\n    from_amount,\n    to_amount,\n    exchange_rate,\n    from_account_type,\n    to_account_type,\n    from_bank_account_id,\n    to_bank_account_id,\n    from_bank_statement_line_id,\n    to_bank_statement_line_id,\n    description,\n    created_by\n  ) VALUES (\n    v_transfer_number,\n    p_transfer_date,\n    p_from_amount,\n    p_from_amount,\n    p_to_amount,\n    p_exchange_rate,\n    p_from_account_type,\n    p_to_account_type,\n    CASE WHEN p_from_account_type = 'bank' THEN p_from_bank_account_id ELSE NULL END,\n    CASE WHEN p_to_account_type = 'bank' THEN p_to_bank_account_id ELSE NULL END,\n    p_from_bank_statement_line_id,\n    p_to_bank_statement_line_id,\n    NULLIF(p_description, ''),\n    v_user_id\n  )\n  RETURNING * INTO v_transfer;\n\n  IF v_transfer.to_account_type = 'petty_cash' THEN\n    IF v_transfer.from_account_type = 'bank' THEN\n      SELECT COALESCE(ba.alias, ba.bank_name, 'Bank')\n        INTO v_source_account_name\n      FROM public.bank_accounts ba\n      WHERE ba.id = v_transfer.from_bank_account_id;\n    ELSE\n      v_source_account_name := 'Cash on Hand';\n    END IF;\n\n    INSERT INTO public.petty_cash_transactions (\n      transaction_date,\n      transaction_type,\n      amount,\n      description,\n      bank_account_id,\n      bank_statement_line_id,\n      source,\n      fund_transfer_id,\n      approval_status,\n      created_by\n    ) VALUES (\n      v_transfer.transfer_date,\n      'withdraw',\n      v_transfer.to_amount,\n      COALESCE(v_transfer.description, 'Fund transfer from ' || COALESCE(v_source_account_name, 'Bank')),\n      v_transfer.from_bank_account_id,\n      v_transfer.from_bank_statement_line_id,\n      'Fund Transfer ' || v_transfer.transfer_number,\n      v_transfer.id,\n      'approved',\n      v_user_id\n    )\n    ON CONFLICT (fund_transfer_id) WHERE fund_transfer_id IS NOT NULL DO NOTHING;\n  END IF;\n\n  RETURN v_transfer;\nEND;\n$function$","-- save_payment_voucher_with_allocations(p_voucher_id uuid, p_voucher_number text, p_voucher_date date, p_supplier_id uuid, p_payment_method text, p_bank_account_id uuid, p_reference_number text, p_amount numeric, p_pph_amount numeric, p_pph_code_id uuid, p_description text, p_payment_currency text, p_exchange_rate numeric, p_bank_amount numeric, p_bank_charge numeric, p_created_by uuid, p_allocations jsonb, p_staff_id uuid)\nCREATE OR REPLACE FUNCTION public.save_payment_voucher_with_allocations(p_voucher_id uuid DEFAULT NULL::uuid, p_voucher_number text DEFAULT NULL::text, p_voucher_date date DEFAULT NULL::date, p_supplier_id uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT NULL::text, p_bank_account_id uuid DEFAULT NULL::uuid, p_reference_number text DEFAULT NULL::text, p_amount numeric DEFAULT 0, p_pph_amount numeric DEFAULT 0, p_pph_code_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_payment_currency text DEFAULT 'IDR'::text, p_exchange_rate numeric DEFAULT 1, p_bank_amount numeric DEFAULT NULL::numeric, p_bank_charge numeric DEFAULT 0, p_created_by uuid DEFAULT NULL::uuid, p_allocations jsonb DEFAULT '[]'::jsonb, p_staff_id uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_voucher_id    UUID;\n  v_alloc         JSONB;\n  v_invoice_id    UUID;\n  v_expense_id    UUID;\n  v_alloc_amount  NUMERIC;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  IF p_supplier_id IS NULL AND p_staff_id IS NULL THEN\n    RAISE EXCEPTION 'Payment voucher needs a payee: supplier or staff';\n  END IF;\n\n  -- ── Create or update the voucher header ──\n  IF p_voucher_id IS NULL THEN\n    INSERT INTO payment_vouchers (\n      voucher_number, voucher_date, supplier_id, staff_id, payment_method,\n      bank_account_id, reference_number, amount, pph_amount, pph_code_id,\n      description, payment_currency, exchange_rate,\n      bank_amount, bank_charge, created_by\n    ) VALUES (\n      p_voucher_number, p_voucher_date, p_supplier_id, p_staff_id, p_payment_method,\n      p_bank_account_id, p_reference_number, p_amount, p_pph_amount, p_pph_code_id,\n      p_description, p_payment_currency, p_exchange_rate,\n      p_bank_amount, p_bank_charge, p_created_by\n    ) RETURNING id INTO v_voucher_id;\n  ELSE\n    v_voucher_id := p_voucher_id;\n\n    IF EXISTS (SELECT 1 FROM payment_vouchers WHERE id = v_voucher_id AND is_posted = TRUE) THEN\n      RAISE EXCEPTION 'Cannot edit: % is posted. Cancel Posting first to make changes.', p_voucher_number;\n    END IF;\n\n    UPDATE payment_vouchers SET\n      voucher_date      = p_voucher_date,\n      supplier_id       = p_supplier_id,\n      staff_id          = p_staff_id,\n      payment_method    = p_payment_method,\n      bank_account_id   = p_bank_account_id,\n      reference_number  = p_reference_number,\n      amount            = p_amount,\n      pph_amount        = p_pph_amount,\n      pph_code_id       = p_pph_code_id,\n      description       = p_description,\n      payment_currency  = p_payment_currency,\n      exchange_rate     = p_exchange_rate,\n      bank_amount       = p_bank_amount,\n      bank_charge       = p_bank_charge,\n      updated_at        = NOW()\n    WHERE id = v_voucher_id;\n  END IF;\n\n  -- ── Replace all allocations ──\n  DELETE FROM voucher_allocations WHERE payment_voucher_id = v_voucher_id;\n\n  FOR v_alloc IN SELECT value FROM jsonb_array_elements(p_allocations) AS value\n  LOOP\n    v_alloc_amount := COALESCE((v_alloc->>'amount')::NUMERIC, 0);\n    IF v_alloc_amount <= 0 THEN\n      CONTINUE;\n    END IF;\n\n    v_invoice_id := NULLIF(v_alloc->>'invoice_id', '')::UUID;\n    v_expense_id := NULLIF(v_alloc->>'finance_expense_id', '')::UUID;\n\n    IF v_invoice_id IS NOT NULL THEN\n      INSERT INTO voucher_allocations (\n        payment_voucher_id, purchase_invoice_id,\n        allocated_amount, allocated_currency, voucher_type\n      ) VALUES (\n        v_voucher_id, v_invoice_id, v_alloc_amount,\n        COALESCE(v_alloc->>'currency', 'IDR'), 'payment'\n      );\n    ELSIF v_expense_id IS NOT NULL THEN\n      INSERT INTO voucher_allocations (\n        payment_voucher_id, finance_expense_id,\n        allocated_amount, allocated_currency, voucher_type\n      ) VALUES (\n        v_voucher_id, v_expense_id, v_alloc_amount,\n        COALESCE(v_alloc->>'currency', 'IDR'), 'payment'\n      );\n      -- paid_amount on finance_expenses updated by trg_sync_expense_payment_state\n    END IF;\n  END LOOP;\n\n  RETURN v_voucher_id;\nEND;\n$function$","-- save_payment_voucher(p_voucher_date date, p_supplier_id uuid, p_payment_method text, p_bank_account_id uuid, p_reference_number text, p_amount numeric, p_pph_amount numeric, p_pph_code_id uuid, p_description text, p_created_by uuid, p_allocations jsonb)\nCREATE OR REPLACE FUNCTION public.save_payment_voucher(p_voucher_date date, p_supplier_id uuid, p_payment_method text, p_bank_account_id uuid, p_reference_number text, p_amount numeric, p_pph_amount numeric, p_pph_code_id uuid, p_description text, p_created_by uuid, p_allocations jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\nv_voucher_number text;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\nv_voucher_number := public.generate_voucher_number('PV');\n\nRETURN public.save_payment_voucher_with_allocations(\nNULL,\nv_voucher_number,\np_voucher_date,\np_supplier_id,\np_payment_method,\np_bank_account_id,\np_reference_number,\np_amount,\np_pph_amount,\np_pph_code_id,\np_description,\n'IDR',\n1,\nNULL,\n0,\np_created_by,\np_allocations\n);\nEND;\n$function$","-- save_payment_voucher_with_purpose(p_voucher_id uuid, p_payload jsonb, p_allocations jsonb, p_payment_purpose text)\nCREATE OR REPLACE FUNCTION public.save_payment_voucher_with_purpose(p_voucher_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_allocations jsonb DEFAULT '[]'::jsonb, p_payment_purpose text DEFAULT 'general'::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_result jsonb;\n  v_id uuid;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  PERFORM public._sec_check_finance_role();\n\n  IF p_payment_purpose NOT IN (\n    'general',\n    'salary_advance',\n    'salary_advance_settlement'\n  ) THEN\n    RAISE EXCEPTION 'Unsupported payment purpose %', p_payment_purpose;\n  END IF;\n\n  v_result := public.save_payment_voucher_command(\n    p_voucher_id,\n    p_payload,\n    p_allocations\n  );\n  v_id := (v_result->>'id')::uuid;\n\n  UPDATE public.payment_vouchers\n     SET payment_purpose = p_payment_purpose,\n         salary_advance_status = CASE p_payment_purpose\n           WHEN 'salary_advance' THEN 'outstanding'\n           ELSE 'not_applicable'\n         END\n   WHERE id = v_id;\n\n  RETURN v_result;\nEND;\n$function$","-- approve_finance_expense(p_expense_id uuid, p_approved_by uuid)\nCREATE OR REPLACE FUNCTION public.approve_finance_expense(p_expense_id uuid, p_approved_by uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  UPDATE public.finance_expenses SET approval_status='approved',approved_by=COALESCE(p_approved_by,auth.uid()),approved_at=now(),rejection_reason=NULL\n  WHERE id=p_expense_id AND approval_status IS DISTINCT FROM 'approved';\n  IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM public.finance_expenses WHERE id=p_expense_id AND approval_status='approved') THEN\n    RAISE EXCEPTION 'Expense not found';\n  END IF;\n  RETURN p_expense_id;\nEND $function$","-- edit_approved_finance_expense_atomic(p_expense_id uuid, p_payload jsonb, p_bank_statement_line_id uuid, p_allocation_amount numeric)\nCREATE OR REPLACE FUNCTION public.edit_approved_finance_expense_atomic(p_expense_id uuid, p_payload jsonb, p_bank_statement_line_id uuid DEFAULT NULL::uuid, p_allocation_amount numeric DEFAULT NULL::numeric)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_exp public.finance_expenses%rowtype;\n  v_journal_id uuid;\n  v_journal_count integer;\n  v_date date;\n  v_bank_id uuid;\n  v_bank_currency text;\n  v_currency text;\n  v_rate numeric;\n  v_docs text[];\n  v_same_selected_count integer;\n  v_selected_amount numeric;\n  v_period_status text;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  PERFORM public._sec_check_finance_role();\n  SELECT * INTO v_exp FROM public.finance_expenses WHERE id=p_expense_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\n  IF v_exp.approval_status<>'approved' THEN RAISE EXCEPTION 'Approved expense edit requires an approved expense'; END IF;\n\n  SELECT count(*),(array_agg(id ORDER BY created_at DESC,id DESC))[1]\n    INTO v_journal_count,v_journal_id\n    FROM public.journal_entries\n   WHERE source_module IN('expense','expenses')\n     AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n     AND is_posted=true AND NOT COALESCE(is_reversed,false);\n  IF v_journal_count<>1 THEN RAISE EXCEPTION 'Approved expense must have exactly one active effective journal'; END IF;\n  PERFORM 1 FROM public.journal_entries WHERE id=v_journal_id FOR UPDATE;\n\n  SELECT ap.status INTO v_period_status\n    FROM public.journal_entries je\n    LEFT JOIN public.accounting_periods ap\n      ON ap.start_date<=je.entry_date AND ap.end_date>=je.entry_date\n   WHERE je.id=v_journal_id\n   ORDER BY ap.start_date DESC LIMIT 1;\n  IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN\n    RAISE EXCEPTION 'Cannot edit approved expense in a closed accounting period';\n  END IF;\n\n  IF COALESCE((p_payload->>'amount')::numeric,0)<=0 THEN RAISE EXCEPTION 'Expense amount must be greater than zero'; END IF;\n  IF NULLIF(p_payload->>'expense_category','') IS NULL THEN RAISE EXCEPTION 'Expense category is required'; END IF;\n  v_date:=COALESCE((p_payload->>'expense_date')::date,current_date);\n  v_bank_id:=NULLIF(p_payload->>'bank_account_id','')::uuid;\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id=v_bank_id;\n  v_currency:=upper(COALESCE(NULLIF(p_payload->>'transaction_currency',''),v_bank_currency,'IDR'));\n  v_rate:=COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric,0),CASE WHEN v_currency='IDR' THEN 1 END);\n  IF v_currency NOT IN('IDR','USD') OR v_rate IS NULL OR v_rate<=0 THEN RAISE EXCEPTION 'Valid expense currency/rate is required'; END IF;\n  IF v_bank_currency IS NOT NULL AND v_bank_currency<>v_currency THEN RAISE EXCEPTION 'Expense currency does not match selected bank currency'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IS NOT NULL\n     AND NULLIF(p_payload->>'payment_method','') NOT IN('cash','petty_cash')\n     AND v_bank_id IS NULL THEN RAISE EXCEPTION 'Bank-paid expense requires a bank account'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IN('cash','petty_cash')\n     AND p_bank_statement_line_id IS NOT NULL THEN RAISE EXCEPTION 'Cash/petty-cash expense cannot create a bank allocation'; END IF;\n  IF NULLIF(p_payload->>'payment_method','') IS NULL AND p_bank_statement_line_id IS NOT NULL THEN RAISE EXCEPTION 'Accrued expense cannot create a bank allocation'; END IF;\n  SELECT ap.status INTO v_period_status\n    FROM public.accounting_periods ap\n   WHERE ap.start_date<=v_date AND ap.end_date>=v_date\n   ORDER BY ap.start_date DESC LIMIT 1;\n  IF v_period_status IS NOT NULL AND v_period_status<>'open' THEN\n    RAISE EXCEPTION 'Cannot move approved expense into a closed accounting period';\n  END IF;\n  SELECT COALESCE(array_agg(value),ARRAY[]::text[]) INTO v_docs\n    FROM jsonb_array_elements_text(COALESCE(p_payload->'document_urls','[]'::jsonb));\n\n  PERFORM set_config('app.expense_atomic_bank_link','on',true);\n\n  UPDATE public.finance_expenses SET\n    expense_category=p_payload->>'expense_category',expense_type=COALESCE(NULLIF(p_payload->>'expense_type',''),'admin'),\n    amount=(p_payload->>'amount')::numeric,expense_date=v_date,description=NULLIF(p_payload->>'description',''),\n    batch_id=NULLIF(p_payload->>'batch_id','')::uuid,import_container_id=NULLIF(p_payload->>'import_container_id','')::uuid,\n    delivery_challan_id=NULLIF(p_payload->>'delivery_challan_id','')::uuid,\n    payment_method=NULLIF(p_payload->>'payment_method',''),bank_account_id=v_bank_id,\n    payment_reference=NULLIF(p_payload->>'payment_reference',''),paid_by=NULLIF(p_payload->>'paid_by',''),\n    document_urls=NULLIF(v_docs,ARRAY[]::text[]),supplier_id=NULLIF(p_payload->>'supplier_id','')::uuid,\n    staff_id=NULLIF(p_payload->>'staff_id','')::uuid,invoice_number=NULLIF(p_payload->>'invoice_number',''),\n    due_date=NULLIF(p_payload->>'due_date','')::date,broker_items=NULLIF(p_payload->'broker_items','null'::jsonb),\n    pib_bm_amount=NULLIF(p_payload->>'pib_bm_amount','')::numeric,pib_ppn_amount=NULLIF(p_payload->>'pib_ppn_amount','')::numeric,\n    pib_pph_amount=NULLIF(p_payload->>'pib_pph_amount','')::numeric,ppn_amount=COALESCE(NULLIF(p_payload->>'ppn_amount','')::numeric,0),\n    ppn_manual_override=COALESCE((p_payload->>'ppn_manual_override')::boolean,false),\n    ppn_calc_mode=COALESCE(NULLIF(p_payload->>'ppn_calc_mode',''),'standard'),dpp_amount=NULLIF(p_payload->>'dpp_amount','')::numeric,\n    ppn_rate=COALESCE(NULLIF(p_payload->>'ppn_rate','')::numeric,11),pph_amount=COALESCE(NULLIF(p_payload->>'pph_amount','')::numeric,0),\n    pph_code_id=NULLIF(p_payload->>'pph_code_id','')::uuid,stamp_duty_amount=COALESCE(NULLIF(p_payload->>'stamp_duty_amount','')::numeric,0),\n    fixed_asset_account_id=NULLIF(p_payload->>'fixed_asset_account_id','')::uuid,\n    bank_charges_amount=COALESCE(NULLIF(p_payload->>'bank_charges_amount','')::numeric,0),\n    currency_code=v_currency,transaction_currency=v_currency,functional_currency='IDR',exchange_rate=v_rate,\n    bank_account_currency=COALESCE(v_bank_currency,v_currency),payment_currency=v_currency,\n    payee_id=NULLIF(p_payload->>'payee_id','')::uuid,\n    linked_sales_invoice_id=NULLIF(p_payload->>'linked_sales_invoice_id','')::uuid,\n    pph_calculation_regime=NULLIF(p_payload->>'pph_calculation_regime',''),\n    pph_dpp_ratio=NULLIF(p_payload->>'pph_dpp_ratio','')::numeric,\n    pph_dpp_amount=NULLIF(p_payload->>'pph_dpp_amount','')::numeric,\n    pph_rate=NULLIF(p_payload->>'pph_rate','')::numeric,\n    is_tax_manual_override=COALESCE((p_payload->>'is_tax_manual_override')::boolean, false)\n  WHERE id=p_expense_id;\n\n  IF NOT EXISTS(\n    SELECT 1 FROM public.journal_entries\n     WHERE id=v_journal_id\n       AND source_module IN('expense','expenses')\n       AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n       AND is_posted AND NOT COALESCE(is_reversed,false)\n  ) THEN RAISE EXCEPTION 'Expense journal identity changed during edit'; END IF;\n  IF (SELECT count(*) FROM public.journal_entries\n       WHERE source_module IN('expense','expenses')\n         AND (reference_id=p_expense_id OR reference_number='EXP-'||p_expense_id::text)\n         AND is_posted AND NOT COALESCE(is_reversed,false))<>1 THEN\n    RAISE EXCEPTION 'Expense edit did not preserve exactly one active journal';\n  END IF;\n\n  SELECT count(*),max(allocation_amount)\n    INTO v_same_selected_count,v_selected_amount\n    FROM public.bank_statement_allocations\n   WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind='supplier'\n     AND bank_statement_line_id=p_bank_statement_line_id;\n\n  IF p_bank_statement_line_id IS NOT NULL\n     AND v_same_selected_count=0 THEN\n    PERFORM public.link_bank_statement_line(\n      p_bank_statement_line_id,'expense',p_expense_id,'supplier',p_allocation_amount);\n  ELSIF p_bank_statement_line_id IS NOT NULL\n     AND p_allocation_amount IS NOT NULL\n     AND abs(COALESCE(v_selected_amount,0)-p_allocation_amount)>0.01 THEN\n    RAISE EXCEPTION 'Change an existing bank allocation through unlink/relink so other payments remain intact';\n  END IF;\n\n  PERFORM public.recalculate_expense_payment_state(p_expense_id);\n  RETURN p_expense_id;\nEND;\n$function$","-- adjust_batch_stock_atomic(p_batch_id uuid, p_quantity_change numeric, p_transaction_type text, p_reference_id uuid, p_notes text, p_created_by uuid, p_operation_id uuid)\nCREATE OR REPLACE FUNCTION public.adjust_batch_stock_atomic(p_batch_id uuid, p_quantity_change numeric, p_transaction_type text, p_reference_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid)\n RETURNS TABLE(new_stock numeric, transaction_id uuid)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_batch public.batches%ROWTYPE;\n  v_transaction_id uuid;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(\n    ARRAY['admin', 'accounts', 'warehouse']\n  ) THEN\n    RAISE EXCEPTION 'Permission denied for stock adjustment';\n  END IF;\n  IF p_transaction_type IS DISTINCT FROM 'adjustment' THEN\n    RAISE EXCEPTION 'Manual inventory entry supports Stock Adjustment only';\n  END IF;\n  IF COALESCE(p_quantity_change, 0) = 0 THEN\n    RAISE EXCEPTION 'Stock adjustment cannot be zero';\n  END IF;\n\n  SELECT *\n  INTO v_batch\n  FROM public.batches\n  WHERE id = p_batch_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Batch not found';\n  END IF;\n\n  v_transaction_id := public.post_inventory_movement(\n    p_operation_id,\n    v_batch.product_id,\n    v_batch.id,\n    'adjustment',\n    p_quantity_change,\n    CURRENT_DATE,\n    NULL,\n    'stock_adjustment',\n    p_reference_id,\n    p_notes,\n    COALESCE(p_created_by, auth.uid()),\n    NULL,\n    NULL\n  );\n\n  SELECT current_stock\n  INTO new_stock\n  FROM public.batches\n  WHERE id = p_batch_id;\n\n  transaction_id := v_transaction_id;\n  RETURN NEXT;\nEND;\n$function$","-- save_batch_inventory_v1(p_batch_id uuid, p_payload jsonb, p_operation_id uuid)\nCREATE OR REPLACE FUNCTION public.save_batch_inventory_v1(p_batch_id uuid, p_payload jsonb, p_operation_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_batch public.batches%ROWTYPE;\n  v_existing_batch_id uuid;\n  v_actor uuid := auth.uid();\n  v_delta numeric;\n  v_previous_context text;\n  v_unit_price numeric;\n  v_is_local boolean;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'warehouse']) THEN\n    RAISE EXCEPTION 'Permission denied for canonical batch save';\n  END IF;\n  IF p_operation_id IS NULL THEN\n    RAISE EXCEPTION 'operation_id is required';\n  END IF;\n  IF p_batch_id IS NULL AND NULLIF(p_payload->>'make_id', '') IS NULL THEN\n    RAISE EXCEPTION 'Make / Manufacturer is required for new inventory batches';\n  END IF;\n  IF NULLIF(p_payload->>'make_id', '') IS NOT NULL\n     AND NOT EXISTS (\n       SELECT 1 FROM public.product_sources\n        WHERE id = (p_payload->>'make_id')::uuid\n          AND product_id = (p_payload->>'product_id')::uuid\n     ) THEN\n    RAISE EXCEPTION 'Selected Make / Manufacturer does not belong to the selected product';\n  END IF;\n\n  v_unit_price := COALESCE((p_payload->>'import_price')::numeric, 0);\n  v_is_local := NULLIF(p_payload->>'import_container_id', '') IS NULL;\n\n  IF p_batch_id IS NULL THEN\n    SELECT batch_id INTO v_existing_batch_id\n      FROM public.inventory_transactions\n     WHERE operation_id = p_operation_id AND transaction_type = 'purchase';\n    IF FOUND THEN\n      RETURN jsonb_build_object('success', true, 'batch_id', v_existing_batch_id, 'idempotent_retry', true);\n    END IF;\n\n    v_previous_context := current_setting('app.canonical_stock_engine', true);\n    PERFORM set_config('app.canonical_stock_engine', 'on', true);\n    INSERT INTO public.batches (\n      batch_number, product_id, make_id, import_container_id, import_date,\n      import_quantity, current_stock, packaging_details, import_price,\n      import_price_usd, exchange_rate_usd_to_idr, duty_percent, duty_charges,\n      duty_charge_type, freight_charges, freight_charge_type, other_charges,\n      other_charge_type, expiry_date, is_active, created_by,\n      cost_per_unit, landed_cost_per_unit, final_landed_cost, import_price_per_unit\n    ) VALUES (\n      p_payload->>'batch_number', (p_payload->>'product_id')::uuid,\n      NULLIF(p_payload->>'make_id', '')::uuid,\n      NULLIF(p_payload->>'import_container_id', '')::uuid,\n      (p_payload->>'import_date')::date, (p_payload->>'import_quantity')::numeric,\n      0, NULLIF(p_payload->>'packaging_details', ''),\n      v_unit_price,\n      NULLIF(p_payload->>'import_price_usd', '')::numeric,\n      NULLIF(p_payload->>'exchange_rate_usd_to_idr', '')::numeric,\n      COALESCE(NULLIF(p_payload->>'duty_percent', '')::numeric, 0),\n      COALESCE(NULLIF(p_payload->>'duty_charges', '')::numeric, 0),\n      COALESCE(NULLIF(p_payload->>'duty_charge_type', ''), 'fixed'),\n      COALESCE(NULLIF(p_payload->>'freight_charges', '')::numeric, 0),\n      COALESCE(NULLIF(p_payload->>'freight_charge_type', ''), 'fixed'),\n      COALESCE(NULLIF(p_payload->>'other_charges', '')::numeric, 0),\n      COALESCE(NULLIF(p_payload->>'other_charge_type', ''), 'fixed'),\n      NULLIF(p_payload->>'expiry_date', '')::date, true, v_actor,\n      v_unit_price,\n      CASE WHEN v_is_local THEN v_unit_price ELSE 0 END,\n      CASE WHEN v_is_local THEN v_unit_price * (p_payload->>'import_quantity')::numeric ELSE 0 END,\n      v_unit_price\n    ) RETURNING * INTO v_batch;\n    PERFORM set_config('app.canonical_stock_engine', COALESCE(v_previous_context, ''), true);\n    PERFORM public.post_inventory_movement(\n      p_operation_id, v_batch.product_id, v_batch.id, 'purchase',\n      v_batch.import_quantity, v_batch.import_date, v_batch.batch_number,\n      'batch_creation', v_batch.id, 'Canonical Batch Creation: ' || v_batch.batch_number,\n      v_actor, 0, v_batch.import_quantity\n    );\n    RETURN jsonb_build_object('success', true, 'batch_id', v_batch.id);\n  END IF;\n\n  SELECT * INTO v_batch FROM public.batches WHERE id = p_batch_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Batch not found'; END IF;\n  IF (p_payload->>'product_id')::uuid IS DISTINCT FROM v_batch.product_id\n     AND EXISTS (SELECT 1 FROM public.inventory_transactions WHERE batch_id = p_batch_id AND transaction_type <> 'purchase') THEN\n    RAISE EXCEPTION 'Cannot change product after batch stock movement exists';\n  END IF;\n\n  v_delta := (p_payload->>'import_quantity')::numeric - v_batch.import_quantity;\n  UPDATE public.batches SET\n    batch_number = p_payload->>'batch_number', product_id = (p_payload->>'product_id')::uuid,\n    make_id = NULLIF(p_payload->>'make_id', '')::uuid,\n    import_container_id = NULLIF(p_payload->>'import_container_id', '')::uuid,\n    import_date = (p_payload->>'import_date')::date, import_quantity = (p_payload->>'import_quantity')::numeric,\n    packaging_details = NULLIF(p_payload->>'packaging_details', ''),\n    import_price = COALESCE((p_payload->>'import_price')::numeric, import_price),\n    import_price_usd = NULLIF(p_payload->>'import_price_usd', '')::numeric,\n    exchange_rate_usd_to_idr = NULLIF(p_payload->>'exchange_rate_usd_to_idr', '')::numeric,\n    duty_percent = COALESCE(NULLIF(p_payload->>'duty_percent', '')::numeric, 0),\n    duty_charges = COALESCE(NULLIF(p_payload->>'duty_charges', '')::numeric, 0),\n    duty_charge_type = COALESCE(NULLIF(p_payload->>'duty_charge_type', ''), duty_charge_type),\n    freight_charges = COALESCE(NULLIF(p_payload->>'freight_charges', '')::numeric, 0),\n    freight_charge_type = COALESCE(NULLIF(p_payload->>'freight_charge_type', ''), freight_charge_type),\n    other_charges = COALESCE(NULLIF(p_payload->>'other_charges', '')::numeric, 0),\n    other_charge_type = COALESCE(NULLIF(p_payload->>'other_charge_type', ''), other_charge_type),\n    expiry_date = NULLIF(p_payload->>'expiry_date', '')::date,\n    cost_per_unit = CASE\n      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL\n        THEN COALESCE((p_payload->>'import_price')::numeric, import_price)\n      ELSE cost_per_unit\n    END,\n    landed_cost_per_unit = CASE\n      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL\n        THEN COALESCE((p_payload->>'import_price')::numeric, import_price)\n      ELSE landed_cost_per_unit\n    END,\n    final_landed_cost = CASE\n      WHEN NULLIF(p_payload->>'import_container_id', '') IS NULL\n        THEN COALESCE((p_payload->>'import_price')::numeric, import_price) * (p_payload->>'import_quantity')::numeric\n      ELSE final_landed_cost\n    END,\n    import_price_per_unit = COALESCE((p_payload->>'import_price')::numeric, import_price),\n    updated_at = now()\n  WHERE id = p_batch_id;\n\n  IF v_delta <> 0 THEN\n    PERFORM public.post_inventory_movement(\n      p_operation_id, (p_payload->>'product_id')::uuid, p_batch_id, 'adjustment',\n      v_delta, CURRENT_DATE, p_payload->>'batch_number', 'batch_edit', p_batch_id,\n      format('Canonical Batch Edit quantity correction: %s to %s', v_batch.import_quantity, (p_payload->>'import_quantity')::numeric),\n      v_actor, v_batch.current_stock, v_batch.current_stock + v_delta\n    );\n  END IF;\n  RETURN jsonb_build_object('success', true, 'batch_id', p_batch_id);\nEND;\n$function$","-- archive_batch_inventory_v1(p_batch_id uuid)\nCREATE OR REPLACE FUNCTION public.archive_batch_inventory_v1(p_batch_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_batch public.batches%ROWTYPE;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  IF NOT public.inventory_v1_actor_allowed(\n    ARRAY['admin', 'accounts', 'warehouse']\n  ) THEN\n    RAISE EXCEPTION 'Permission denied for batch archive';\n  END IF;\n\n  SELECT *\n  INTO v_batch\n  FROM public.batches\n  WHERE id = p_batch_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object(\n      'archived', false,\n      'reason', 'Batch not found'\n    );\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM public.stock_reservations\n    WHERE batch_id = p_batch_id\n      AND status = 'active'\n  ) THEN\n    RETURN jsonb_build_object(\n      'archived', false,\n      'reason', format(\n        'Batch %s has active reservations and cannot be archived',\n        v_batch.batch_number\n      )\n    );\n  END IF;\n\n  IF v_batch.current_stock <> 0 THEN\n    RETURN jsonb_build_object(\n      'archived', false,\n      'reason', format(\n        'Batch %s still has stock %s. Post a canonical adjustment to zero before archiving',\n        v_batch.batch_number,\n        v_batch.current_stock\n      )\n    );\n  END IF;\n\n  UPDATE public.batches\n  SET is_active = false,\n      updated_at = now()\n  WHERE id = p_batch_id;\n\n  RETURN jsonb_build_object(\n    'archived', true,\n    'batch_id', p_batch_id,\n    'batch_number', v_batch.batch_number\n  );\nEND;\n$function$","-- delete_batch_safe(p_batch_id uuid)\nCREATE OR REPLACE FUNCTION public.delete_batch_safe(p_batch_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_result jsonb;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  v_result := public.archive_batch_inventory_v1(p_batch_id);\n  RETURN jsonb_build_object(\n    'deleted', false,\n    'archived', COALESCE((v_result->>'archived')::boolean, false),\n    'batch_id', v_result->>'batch_id',\n    'batch_number', v_result->>'batch_number',\n    'reason', COALESCE(\n      v_result->>'reason',\n      'Inventory V1 preserves batch and movement history; the batch was archived'\n    )\n  );\nEND;\n$function$","-- approve_purchase_invoice_for_receiving(p_purchase_invoice_id uuid)\nCREATE OR REPLACE FUNCTION public.approve_purchase_invoice_for_receiving(p_purchase_invoice_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE v_status text;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts']) THEN RAISE EXCEPTION 'Permission denied'; END IF;\n  SELECT receiving_approval_status INTO v_status FROM public.purchase_invoices WHERE id=p_purchase_invoice_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;\n  IF v_status <> 'pending_approval' THEN RAISE EXCEPTION 'Purchase Invoice must be pending approval'; END IF;\n  UPDATE public.purchase_invoices SET receiving_approval_status='approved', receiving_approved_at=now(), receiving_approved_by=auth.uid(), updated_at=now() WHERE id=p_purchase_invoice_id;\n  RETURN jsonb_build_object('success',true,'status','approved');\nEND; $function$","-- reject_purchase_invoice_inward(p_purchase_invoice_id uuid, p_purchase_invoice_item_id uuid, p_reason text)\nCREATE OR REPLACE FUNCTION public.reject_purchase_invoice_inward(p_purchase_invoice_id uuid, p_purchase_invoice_item_id uuid, p_reason text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE v_status text;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','warehouse']) THEN RAISE EXCEPTION 'Permission denied'; END IF;\n  IF p_reason IS NULL OR length(trim(p_reason))=0 THEN RAISE EXCEPTION 'Rejection reason is required'; END IF;\n  SELECT receiving_approval_status INTO v_status FROM public.purchase_invoices WHERE id=p_purchase_invoice_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;\n  IF v_status <> 'approved' THEN RAISE EXCEPTION 'Only approved Purchase Invoices can be rejected at inward'; END IF;\n  IF NOT EXISTS (SELECT 1 FROM public.purchase_invoice_items WHERE id=p_purchase_invoice_item_id AND purchase_invoice_id=p_purchase_invoice_id AND item_type='inventory') THEN\n    RAISE EXCEPTION 'Purchase Invoice item does not belong to this invoice';\n  END IF;\n  INSERT INTO public.purchase_invoice_inward_rejections(purchase_invoice_id,purchase_invoice_item_id,reason,rejected_by) VALUES (p_purchase_invoice_id,p_purchase_invoice_item_id,trim(p_reason),auth.uid());\n  UPDATE public.purchase_invoices SET receiving_approval_status='rejected', receiving_rejection_reason=trim(p_reason), updated_at=now() WHERE id=p_purchase_invoice_id;\n  RETURN jsonb_build_object('success',true,'status','rejected');\nEND; $function$","-- submit_purchase_invoice_for_receiving(p_purchase_invoice_id uuid)\nCREATE OR REPLACE FUNCTION public.submit_purchase_invoice_for_receiving(p_purchase_invoice_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE v_invoice public.purchase_invoices%ROWTYPE;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts']) THEN RAISE EXCEPTION 'Permission denied'; END IF;\n  SELECT * INTO v_invoice FROM public.purchase_invoices WHERE id = p_purchase_invoice_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase Invoice not found'; END IF;\n  IF v_invoice.status = 'cancelled' THEN RAISE EXCEPTION 'Cancelled Purchase Invoice cannot be submitted'; END IF;\n  UPDATE public.purchase_invoices SET receiving_approval_status='pending_approval', receiving_submitted_at=now(), receiving_submitted_by=auth.uid(), receiving_rejection_reason=NULL, updated_at=now() WHERE id=p_purchase_invoice_id;\n  RETURN jsonb_build_object('success',true,'status','pending_approval');\nEND; $function$","-- receive_purchase_invoice_item(p_purchase_invoice_item_id uuid, p_payload jsonb, p_received_quantity numeric, p_operation_id uuid)\nCREATE OR REPLACE FUNCTION public.receive_purchase_invoice_item(p_purchase_invoice_item_id uuid, p_payload jsonb, p_received_quantity numeric, p_operation_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_item public.purchase_invoice_items%ROWTYPE;\n  v_invoice public.purchase_invoices%ROWTYPE;\n  v_batch public.batches%ROWTYPE;\n  v_batch_id uuid;\n  v_existing numeric;\n  v_allocation_id uuid;\n  v_make_id uuid;\n  v_container_id uuid;\n  v_currency text;\n  v_rate numeric;\n  v_tx_unit numeric;\n  v_func_unit numeric;\n  v_existing_batch boolean := false;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','warehouse']) THEN\n    RAISE EXCEPTION 'Permission denied for inventory receiving';\n  END IF;\n  IF p_operation_id IS NULL OR p_received_quantity IS NULL OR p_received_quantity <= 0 THEN\n    RAISE EXCEPTION 'A positive quantity and operation_id are required';\n  END IF;\n  SELECT * INTO v_item FROM public.purchase_invoice_items WHERE id=p_purchase_invoice_item_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice item not found'; END IF;\n  SELECT * INTO v_invoice FROM public.purchase_invoices WHERE id=v_item.purchase_invoice_id;\n  IF v_item.item_type <> 'inventory' OR v_item.product_id IS NULL\n     OR NULLIF(p_payload->>'product_id','')::uuid IS DISTINCT FROM v_item.product_id THEN\n    RAISE EXCEPTION 'Receiving requires the invoice inventory product';\n  END IF;\n  SELECT batch_id,id INTO v_batch_id,v_allocation_id\n    FROM public.purchase_invoice_receiving_allocations WHERE operation_id=p_operation_id;\n  IF FOUND THEN\n    RETURN jsonb_build_object('success',true,'batch_id',v_batch_id,\n      'allocation_id',v_allocation_id,'idempotent_retry',true);\n  END IF;\n  SELECT COALESCE(sum(received_quantity),0) INTO v_existing\n    FROM public.purchase_invoice_receiving_allocations\n   WHERE purchase_invoice_item_id=v_item.id AND status='received';\n  IF v_existing+p_received_quantity > v_item.quantity THEN\n    RAISE EXCEPTION 'Received quantity exceeds invoice line quantity';\n  END IF;\n  v_make_id := NULLIF(p_payload->>'make_id','')::uuid;\n  v_container_id := NULLIF(p_payload->>'import_container_id','')::uuid;\n  IF v_make_id IS NOT NULL AND NOT EXISTS\n    (SELECT 1 FROM public.product_sources WHERE id=v_make_id AND product_id=v_item.product_id) THEN\n    RAISE EXCEPTION 'Selected Make / Manufacturer does not belong to the invoice product';\n  END IF;\n  IF NULLIF(p_payload->>'batch_id','') IS NOT NULL THEN\n    SELECT * INTO v_batch FROM public.batches WHERE id=(p_payload->>'batch_id')::uuid FOR UPDATE;\n  ELSE\n    SELECT * INTO v_batch FROM public.batches\n     WHERE product_id=v_item.product_id AND batch_number=p_payload->>'batch_number'\n       AND (make_id=v_make_id OR make_id IS NULL) AND coalesce(is_active,true)\n     ORDER BY (make_id IS NULL),created_at LIMIT 1 FOR UPDATE;\n  END IF;\n  IF FOUND THEN\n    v_existing_batch := true;\n    IF v_batch.product_id IS DISTINCT FROM v_item.product_id THEN\n      RAISE EXCEPTION 'Product does not match selected batch';\n    END IF;\n    IF v_batch.make_id IS NOT NULL AND v_batch.make_id IS DISTINCT FROM v_make_id THEN\n      RAISE EXCEPTION 'Make does not match selected batch';\n    END IF;\n    IF NULLIF(p_payload->>'expiry_date','')::date IS NOT NULL\n       AND v_batch.expiry_date IS NOT NULL\n       AND NULLIF(p_payload->>'expiry_date','')::date IS DISTINCT FROM v_batch.expiry_date THEN\n      RAISE EXCEPTION 'Expiry date conflicts with existing physical batch';\n    END IF;\n    PERFORM public.post_inventory_movement(p_operation_id,v_batch.product_id,v_batch.id,\n      'adjustment',p_received_quantity,v_invoice.invoice_date,v_invoice.invoice_number,\n      'purchase_invoice_receiving',v_invoice.id,\n      'Purchase Invoice receiving into existing batch '||v_batch.batch_number,\n      auth.uid(),v_batch.current_stock,v_batch.current_stock+p_received_quantity);\n    UPDATE public.batches SET import_quantity=import_quantity+p_received_quantity,updated_at=now()\n      WHERE id=v_batch.id;\n    v_batch_id := v_batch.id;\n  ELSE\n    p_payload := jsonb_set(p_payload,'{import_quantity}',to_jsonb(p_received_quantity),true);\n    p_payload := jsonb_set(p_payload,'{purchase_invoice_id}',to_jsonb(v_item.purchase_invoice_id),true);\n    p_payload := jsonb_set(p_payload,'{supplier_id}',to_jsonb(v_invoice.supplier_id),true);\n    SELECT (public.save_batch_inventory_v1(NULL,p_payload,p_operation_id)->>'batch_id')::uuid INTO v_batch_id;\n  END IF;\n  v_currency := upper(coalesce(v_invoice.currency,'IDR'));\n  v_rate := CASE WHEN v_currency='IDR' THEN 1 ELSE coalesce(v_invoice.exchange_rate,0) END;\n  IF v_rate<=0 THEN RAISE EXCEPTION 'Purchase invoice exchange rate is required'; END IF;\n  v_tx_unit := coalesce(v_item.unit_price,0);\n  v_func_unit := round(v_tx_unit*v_rate,2);\n  INSERT INTO public.purchase_invoice_receiving_allocations(\n    purchase_invoice_id,purchase_invoice_item_id,batch_id,received_quantity,\n    operation_id,received_by,currency,exchange_rate,functional_unit_cost,\n    functional_total_cost,import_container_id)\n  VALUES(v_item.purchase_invoice_id,v_item.id,v_batch_id,p_received_quantity,\n    p_operation_id,auth.uid(),v_currency,v_rate,v_func_unit,\n    round(v_func_unit*p_received_quantity,2),v_container_id)\n  RETURNING id INTO v_allocation_id;\n  INSERT INTO public.purchase_batch_cost_layers(\n    receiving_allocation_id,purchase_invoice_id,purchase_invoice_item_id,batch_id,\n    import_container_id,quantity,currency,exchange_rate,transaction_unit_cost,\n    functional_unit_cost,functional_total_cost,final_functional_unit_cost)\n  VALUES(v_allocation_id,v_item.purchase_invoice_id,v_item.id,v_batch_id,v_container_id,\n    p_received_quantity,v_currency,v_rate,v_tx_unit,v_func_unit,\n    round(v_func_unit*p_received_quantity,2),v_func_unit);\n  IF v_existing_batch THEN\n    PERFORM public.apply_batch_receipt_weighted_average(v_batch_id,p_received_quantity,v_func_unit);\n  END IF;\n  RETURN jsonb_build_object('success',true,'batch_id',v_batch_id,'allocation_id',v_allocation_id);\nEND; $function$","-- approve_sales_order_product_reservation_v2(p_so_id uuid, p_approved_by uuid)\nCREATE OR REPLACE FUNCTION public.approve_sales_order_product_reservation_v2(p_so_id uuid, p_approved_by uuid)\n RETURNS TABLE(success boolean, message text, shortage_items jsonb)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  r record;\n  v_delivered numeric;\n  v_item_required numeric;\n  v_reserved numeric;\n  v_shortage_qty numeric;\n  v_shortage_list jsonb := '[]'::jsonb;\n  v_has_shortage boolean := false;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'warehouse'])\n     AND current_setting('app.canonical_reservation_engine', true) IS DISTINCT FROM 'on' THEN\n    RAISE EXCEPTION 'Permission denied for SO product reservation approval';\n  END IF;\n\n  PERFORM 1 FROM public.sales_orders WHERE id = p_so_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Order not found';\n  END IF;\n\n  PERFORM set_config('app.canonical_reservation_engine', 'on', true);\n\n  UPDATE public.sales_orders\n  SET approved_by = COALESCE(p_approved_by, auth.uid()),\n      approved_at = COALESCE(approved_at, now())\n  WHERE id = p_so_id;\n\n  FOR r IN\n    SELECT id, product_id, quantity\n    FROM public.sales_order_items\n    WHERE sales_order_id = p_so_id\n    ORDER BY product_id, id\n  LOOP\n    v_reserved := public.reconcile_so_product_reservation_v2(r.id, 'SO approval/re-approval');\n\n    SELECT COALESCE(sum(dci.quantity), 0) INTO v_delivered\n    FROM public.delivery_challan_items dci\n    JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n    WHERE dci.sales_order_item_id = r.id\n      AND dc.approval_status = 'approved';\n\n    v_item_required := GREATEST(r.quantity - v_delivered, 0);\n\n    IF v_item_required > v_reserved THEN\n      v_has_shortage := true;\n      v_shortage_qty := v_item_required - v_reserved;\n      v_shortage_list := v_shortage_list || jsonb_build_object(\n        'product_id', r.product_id,\n        'required_qty', r.quantity,\n        'shortage_qty', v_shortage_qty\n      );\n    END IF;\n  END LOOP;\n\n  IF v_has_shortage THEN\n    UPDATE public.sales_orders\n    SET status = 'shortage',\n        updated_at = now()\n    WHERE id = p_so_id;\n\n    PERFORM public.fn_create_import_requirements(p_so_id, v_shortage_list);\n\n    RETURN QUERY\n    SELECT false, 'Partial stock reserved - shortage exists.'::text, v_shortage_list;\n  ELSE\n    UPDATE public.sales_orders\n    SET status = 'stock_reserved',\n        updated_at = now()\n    WHERE id = p_so_id;\n\n    -- Cancel any pending import requirements for this SO\n    UPDATE public.import_requirements\n    SET status = 'cancelled',\n        notes = COALESCE(notes || ' | ', '') ||\n          'Auto-cancelled: shortage resolved by stock reservation ' ||\n          to_char(now(), 'YYYY-MM-DD'),\n        updated_at = now()\n    WHERE sales_order_id = p_so_id\n      AND status = 'pending';\n\n    RETURN QUERY\n    SELECT true, 'Stock fully reserved'::text, '[]'::jsonb;\n  END IF;\nEND;\n$function$","-- approve_sales_order_inventory_v1(p_so_id uuid, p_approved_by uuid)\nCREATE OR REPLACE FUNCTION public.approve_sales_order_inventory_v1(p_so_id uuid, p_approved_by uuid)\n RETURNS TABLE(success boolean, message text, shortage_items jsonb)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_previous_context text;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(\n    ARRAY['admin', 'accounts', 'warehouse']\n  ) THEN\n    RAISE EXCEPTION 'Permission denied for Sales Order approval';\n  END IF;\n\n  v_previous_context := current_setting('app.canonical_reservation_engine', true);\n  PERFORM set_config('app.canonical_reservation_engine', 'on', true);\n\n  UPDATE public.sales_orders\n  SET status = 'approved',\n      approved_by = COALESCE(p_approved_by, auth.uid()),\n      approved_at = now(),\n      updated_at = now()\n  WHERE id = p_so_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Order not found';\n  END IF;\n\n  RETURN QUERY\n  SELECT *\n  FROM public.fn_reserve_stock_for_so_v2(p_so_id);\n\n  PERFORM set_config(\n    'app.canonical_reservation_engine',\n    COALESCE(v_previous_context, ''),\n    true\n  );\nEND;\n$function$","-- release_so_product_reservations_v2(p_so_id uuid, p_reason text)\nCREATE OR REPLACE FUNCTION public.release_so_product_reservations_v2(p_so_id uuid, p_reason text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE r public.so_product_reservations%ROWTYPE;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'warehouse','sales'])\n     AND current_setting('app.canonical_reservation_engine',true) IS DISTINCT FROM 'on' THEN\n    RAISE EXCEPTION 'Permission denied for reservation release';\n  END IF;\n  FOR r IN SELECT * FROM public.so_product_reservations WHERE sales_order_id=p_so_id AND status='active' ORDER BY id FOR UPDATE LOOP\n    UPDATE public.so_product_reservations SET reserved_quantity=0,status='released',closed_at=now(),updated_at=now(),close_reason=p_reason WHERE id=r.id;\n    INSERT INTO public.so_product_reservation_events(reservation_id,sales_order_id,sales_order_item_id,event_type,quantity_delta,quantity_after,reason,actor_id)\n    VALUES(r.id,r.sales_order_id,r.sales_order_item_id,'released',-r.reserved_quantity,0,p_reason,auth.uid());\n  END LOOP;\nEND; $function$","-- edit_delivery_challan(p_challan_id uuid, p_new_items jsonb)\nCREATE OR REPLACE FUNCTION public.edit_delivery_challan(p_challan_id uuid, p_new_items jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_role       text;\n  v_challan    record;\n  v_item       jsonb;\n  v_count      integer;\n  v_product_id uuid;\n  v_batch_id   uuid;\n  v_new_qty    numeric;\nBEGIN\n  SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts', 'warehouse', 'sales') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot edit delivery challans', v_role;\n  END IF;\n\n  SELECT * INTO v_challan FROM delivery_challans WHERE id = p_challan_id;\n\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Delivery challan not found');\n  END IF;\n\n  IF v_challan.approved_at IS NOT NULL THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Cannot edit approved delivery challan');\n  END IF;\n\n  SELECT count(*) INTO v_count FROM jsonb_array_elements(p_new_items);\n  IF v_count = 0 THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Cannot save DC with no items');\n  END IF;\n\n  -- Suppress the INSERT trigger on delivery_challan_items (safety: DC is pending anyway,\n  -- trigger now also guards against non-approved DCs, but be explicit)\n  PERFORM set_config('app.skip_dc_item_trigger', 'true', true);\n\n  -- Remove all existing items for this DC\n  DELETE FROM delivery_challan_items WHERE challan_id = p_challan_id;\n\n  -- Insert the new item list\n  -- No reserved_stock manipulation needed: reservations are in stock_reservations\n  -- linked to the SO, not the DC. trg_sync_batch_reserved_stock handles accuracy.\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_new_items)\n  LOOP\n    v_product_id := (v_item->>'product_id')::uuid;\n    v_batch_id   := (v_item->>'batch_id')::uuid;\n    v_new_qty    := (v_item->>'quantity')::numeric;\n\n    INSERT INTO delivery_challan_items (\n      challan_id, product_id, batch_id, quantity,\n      pack_size, pack_type, number_of_packs\n    ) VALUES (\n      p_challan_id, v_product_id, v_batch_id, v_new_qty,\n      NULLIF(v_item->>'pack_size', '')::numeric,\n      NULLIF(v_item->>'pack_type', ''),\n      NULLIF(v_item->>'number_of_packs', '')::integer\n    );\n  END LOOP;\n\n  PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n\n  RETURN jsonb_build_object('success', true, 'message', 'Delivery challan updated successfully');\n\nEXCEPTION\n  WHEN foreign_key_violation THEN\n    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n    RETURN jsonb_build_object('success', false, 'error', 'Invalid product or batch selection');\n  WHEN OTHERS THEN\n    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n    RETURN jsonb_build_object('success', false, 'error', SQLERRM);\nEND;\n$function$","-- fn_cancel_delivery_challan(p_dc_id uuid, p_user uuid, p_reason text)\nCREATE OR REPLACE FUNCTION public.fn_cancel_delivery_challan(p_dc_id uuid, p_user uuid, p_reason text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_role text;\nBEGIN\n  SELECT role INTO v_role FROM profiles WHERE id = COALESCE(auth.uid(), p_user);\n  IF v_role IS NULL OR v_role NOT IN ('admin','accounts','warehouse') THEN\n    RAISE EXCEPTION 'Not authorized to cancel delivery challans';\n  END IF;\n\n  UPDATE delivery_challans\n     SET approval_status   = 'cancelled',\n         rejection_reason  = COALESCE(p_reason, rejection_reason),\n         rejected_by       = COALESCE(p_user, auth.uid()),\n         rejected_at       = now(),\n         updated_at        = now()\n   WHERE id = p_dc_id;\nEND;\n$function$","-- fn_reject_delivery_challan(p_dc_id uuid, p_rejector_id uuid, p_reason text)\nCREATE OR REPLACE FUNCTION public.fn_reject_delivery_challan(p_dc_id uuid, p_rejector_id uuid, p_reason text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin','accounts','warehouse') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot reject delivery challans', v_role;\nEND IF;\n\nUPDATE delivery_challans\nSET approval_status = 'rejected', rejection_reason = p_reason\nWHERE id = p_dc_id;\nRETURN true;\nEND;\n$function$","-- fn_cancel_sales_order(p_so_id uuid, p_canceller_id uuid, p_reason text)\nCREATE OR REPLACE FUNCTION public.fn_cancel_sales_order(p_so_id uuid, p_canceller_id uuid, p_reason text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_role text;\n  v_status text;\nBEGIN\n  SELECT role INTO v_role\n  FROM public.user_profiles\n  WHERE id = auth.uid();\n\n  IF v_role NOT IN ('admin', 'accounts', 'sales') THEN\n    RAISE EXCEPTION\n      'Permission denied: role % cannot cancel sales orders', v_role;\n  END IF;\n\n  SELECT status::text INTO v_status\n  FROM public.sales_orders\n  WHERE id = p_so_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Order not found';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM public.delivery_challans dc\n    WHERE dc.sales_order_id = p_so_id\n      AND dc.approval_status = 'approved'\n  ) THEN\n    RAISE EXCEPTION\n      'Sales Order has an approved Delivery Challan; reverse/cancel the Delivery Challan before cancelling the order';\n  END IF;\n\n  DELETE FROM public.import_requirements\n  WHERE sales_order_id = p_so_id;\n\n  PERFORM public.fn_release_stock_reservations(\n    p_so_id,\n    'SO cancelled: ' || p_reason,\n    p_canceller_id\n  );\n\n  UPDATE public.sales_orders\n  SET status = 'cancelled',\n      updated_at = now()\n  WHERE id = p_so_id;\n\n  RETURN true;\nEND;\n$function$","-- fn_reject_sales_order(p_so_id uuid, p_rejector_id uuid, p_reason text)\nCREATE OR REPLACE FUNCTION public.fn_reject_sales_order(p_so_id uuid, p_rejector_id uuid, p_reason text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot reject sales orders', v_role;\nEND IF;\n\nPERFORM fn_release_stock_reservations(p_so_id, 'SO rejected: ' || p_reason);\nUPDATE sales_orders\nSET status = 'rejected', rejected_by = p_rejector_id, rejected_at = now(),\nrejection_reason = p_reason, updated_at = now()\nWHERE id = p_so_id;\nRETURN true;\nEND;\n$function$","-- create_sales_invoice_atomic(p_invoice jsonb, p_items jsonb)\nCREATE OR REPLACE FUNCTION public.create_sales_invoice_atomic(p_invoice jsonb, p_items jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_role text;\n  v_invoice_id uuid;\n  v_subtotal numeric := 0;\n  v_tax numeric := 0;\n  v_discount numeric := COALESCE((p_invoice->>'discount_amount')::numeric, 0);\n  v_stamp numeric := COALESCE((p_invoice->>'stamp_duty_amount')::numeric, 0);\n  v_total numeric;\n  v_count integer := 0;\n  v_item jsonb;\n  v_product uuid;\n  v_batch uuid;\n  v_dc_item uuid;\n  v_qty numeric;\n  v_price numeric;\n  v_rate numeric;\n  v_dc record;\n  v_linked_challans uuid[];\n  v_invoice_so_id uuid := NULLIF(p_invoice->>'sales_order_id','')::uuid;\nBEGIN\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role IS NULL OR v_role NOT IN ('admin', 'accounts', 'sales','warehouse') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot create sales invoices', v_role;\n  END IF;\n  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN\n    RAISE EXCEPTION 'Sales invoice requires at least one product line';\n  END IF;\n  IF NULLIF(p_invoice->>'invoice_number','') IS NULL OR NULLIF(p_invoice->>'customer_id','') IS NULL THEN\n    RAISE EXCEPTION 'Invoice number and customer are required';\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.sales_invoices WHERE invoice_number=p_invoice->>'invoice_number') THEN\n    RAISE EXCEPTION 'Invoice number already exists';\n  END IF;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)\n  LOOP\n    v_product := NULLIF(v_item->>'product_id','')::uuid;\n    v_batch := NULLIF(v_item->>'batch_id','')::uuid;\n    v_dc_item := NULLIF(v_item->>'delivery_challan_item_id','')::uuid;\n    v_qty := (v_item->>'quantity')::numeric;\n    v_price := (v_item->>'unit_price')::numeric;\n    v_rate := COALESCE((v_item->>'tax_rate')::numeric, 0);\n    IF v_product IS NULL OR v_dc_item IS NULL OR COALESCE(v_qty,0) <= 0 OR COALESCE(v_price,0) < 0 THEN\n      RAISE EXCEPTION 'Every invoice line must have a source Delivery Challan item, product, quantity, and price';\n    END IF;\n    SELECT dci.product_id,dci.batch_id,dci.quantity,dc.customer_id,dc.approval_status,dc.sales_order_id\n      INTO v_dc\n    FROM public.delivery_challan_items dci\n    JOIN public.delivery_challans dc ON dc.id=dci.challan_id\n    WHERE dci.id=v_dc_item\n    FOR SHARE;\n    IF NOT FOUND OR v_dc.product_id IS DISTINCT FROM v_product OR v_dc.batch_id IS DISTINCT FROM v_batch\n       OR v_dc.customer_id IS DISTINCT FROM (p_invoice->>'customer_id')::uuid\n       OR v_dc.approval_status <> 'approved' THEN\n      RAISE EXCEPTION 'Invoice line source Delivery Challan is invalid or not approved';\n    END IF;\n    IF v_invoice_so_id IS NOT NULL AND v_dc.sales_order_id IS DISTINCT FROM v_invoice_so_id THEN\n      RAISE EXCEPTION 'Invoice Sales Order does not match its Delivery Challan source';\n    END IF;\n    IF v_qty > v_dc.quantity - COALESCE((SELECT sum(sii.quantity) FROM public.sales_invoice_items sii\n      WHERE sii.delivery_challan_item_id=v_dc_item),0) THEN\n      RAISE EXCEPTION 'Invoice quantity exceeds remaining Delivery Challan quantity';\n    END IF;\n    v_subtotal := v_subtotal + (v_qty * v_price);\n    v_tax := v_tax + (v_qty * v_price * v_rate / 100);\n    v_count := v_count + 1;\n  END LOOP;\n  v_total := v_subtotal + v_tax - v_discount + v_stamp;\n  SELECT array_agg(DISTINCT dc.id) INTO v_linked_challans\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id=dci.challan_id\n  WHERE dci.id IN (SELECT (value->>'delivery_challan_item_id')::uuid FROM jsonb_array_elements(p_items));\n  IF p_invoice ? 'subtotal' AND abs(v_subtotal - (p_invoice->>'subtotal')::numeric) > 0.01\n     OR p_invoice ? 'tax_amount' AND abs(v_tax - (p_invoice->>'tax_amount')::numeric) > 0.01\n     OR p_invoice ? 'total_amount' AND abs(v_total - (p_invoice->>'total_amount')::numeric) > 0.01 THEN\n    RAISE EXCEPTION 'Invoice totals do not match persisted product lines';\n  END IF;\n\n  INSERT INTO public.sales_invoices (\n    invoice_number,customer_id,sales_order_id,invoice_date,due_date,discount_amount,\n    delivery_challan_number,po_number,payment_terms_days,notes,subtotal,tax_amount,\n    stamp_duty_amount,total_amount,payment_status,created_by,linked_challan_ids\n  ) VALUES (\n    p_invoice->>'invoice_number',(p_invoice->>'customer_id')::uuid,v_invoice_so_id,\n    COALESCE((p_invoice->>'invoice_date')::date,CURRENT_DATE),(p_invoice->>'due_date')::date,v_discount,\n    NULL,p_invoice->>'po_number',(p_invoice->>'payment_terms_days')::integer,p_invoice->>'notes',\n    v_subtotal,v_tax,v_stamp,v_total,'pending',COALESCE(NULLIF(p_invoice->>'created_by','')::uuid,auth.uid()),\n    COALESCE(v_linked_challans, CASE WHEN jsonb_typeof(p_invoice->'linked_challan_ids')='array' THEN\n      ARRAY(SELECT jsonb_array_elements_text(p_invoice->'linked_challan_ids')::uuid) ELSE NULL END)\n  ) RETURNING id INTO v_invoice_id;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)\n  LOOP\n    INSERT INTO public.sales_invoice_items\n      (invoice_id,product_id,batch_id,quantity,unit_price,tax_rate,delivery_challan_item_id)\n    VALUES (v_invoice_id,(v_item->>'product_id')::uuid,NULLIF(v_item->>'batch_id','')::uuid,\n      (v_item->>'quantity')::numeric,(v_item->>'unit_price')::numeric,\n      COALESCE((v_item->>'tax_rate')::numeric,0),(v_item->>'delivery_challan_item_id')::uuid);\n  END LOOP;\n\n  IF (SELECT count(*) FROM public.sales_invoice_items WHERE invoice_id=v_invoice_id) <> v_count THEN\n    RAISE EXCEPTION 'Invoice line count verification failed';\n  END IF;\n  RETURN v_invoice_id;\nEND;\n$function$","-- update_sales_invoice_atomic(p_invoice_id uuid, p_invoice_updates jsonb, p_new_items jsonb[])\nCREATE OR REPLACE FUNCTION public.update_sales_invoice_atomic(p_invoice_id uuid, p_invoice_updates jsonb, p_new_items jsonb[])\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_role text;\n  v_old_je_id uuid;\n  v_result uuid;\n  v_dc_item_ids uuid[];\n  v_linked_challan_ids text[];\n  v_sales_order_ids uuid[];\n  v_customer_ids uuid[];\nBEGIN\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts', 'sales') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot update sales invoices', v_role;\n  END IF;\n\n  SELECT array_agg(DISTINCT NULLIF(item->>'delivery_challan_item_id', '')::uuid)\n  INTO v_dc_item_ids\n  FROM unnest(p_new_items) AS item;\n\n  IF v_dc_item_ids IS NULL OR cardinality(v_dc_item_ids) = 0 THEN\n    RAISE EXCEPTION 'Sales Invoice must contain Delivery Challan-linked items';\n  END IF;\n\n  IF array_length(v_dc_item_ids, 1) <> (\n    SELECT count(*) FROM public.delivery_challan_items WHERE id = ANY(v_dc_item_ids)\n  ) THEN\n    RAISE EXCEPTION 'Sales Invoice contains a missing Delivery Challan item';\n  END IF;\n\n  SELECT\n    array_agg(DISTINCT dc.id::text ORDER BY dc.id::text),\n    array_agg(DISTINCT dc.sales_order_id),\n    array_agg(DISTINCT dc.customer_id)\n  INTO v_linked_challan_ids, v_sales_order_ids, v_customer_ids\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  WHERE dci.id = ANY(v_dc_item_ids);\n\n  IF cardinality(v_customer_ids) <> 1\n     OR (p_invoice_updates ? 'customer_id'\n         AND (p_invoice_updates->>'customer_id')::uuid IS DISTINCT FROM v_customer_ids[1]) THEN\n    RAISE EXCEPTION 'Invoice customer must match all linked Delivery Challans';\n  END IF;\n\n  SELECT journal_entry_id INTO v_old_je_id\n  FROM public.sales_invoices\n  WHERE id = p_invoice_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Invoice % not found', p_invoice_id;\n  END IF;\n\n  -- Remove old revenue journal entry\n  IF v_old_je_id IS NOT NULL THEN\n    UPDATE public.sales_invoices SET journal_entry_id = NULL WHERE id = p_invoice_id;\n    DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_old_je_id;\n    DELETE FROM public.journal_entries WHERE id = v_old_je_id;\n  END IF;\n\n  -- Remove old COGS journal entry so COGS is cleanly regenerated for updated items\n  DELETE FROM public.journal_entry_lines\n   WHERE journal_entry_id IN (\n     SELECT id FROM public.journal_entries\n      WHERE source_module = 'sales_invoice_cogs' AND reference_id = p_invoice_id\n   );\n  DELETE FROM public.journal_entries\n   WHERE source_module = 'sales_invoice_cogs' AND reference_id = p_invoice_id;\n\n  -- Delete old sales invoice items\n  DELETE FROM public.sales_invoice_items WHERE invoice_id = p_invoice_id;\n  PERFORM set_config('app.sales_invoice_rebuild', 'true', true);\n\n  UPDATE public.sales_invoices\n  SET\n    invoice_date       = COALESCE((p_invoice_updates->>'invoice_date')::date, invoice_date),\n    due_date           = COALESCE((p_invoice_updates->>'due_date')::date, due_date),\n    customer_id        = v_customer_ids[1],\n    sales_order_id     = CASE WHEN cardinality(v_sales_order_ids) = 1 THEN v_sales_order_ids[1] ELSE NULL END,\n    subtotal           = COALESCE((p_invoice_updates->>'subtotal')::numeric, subtotal),\n    tax_amount         = COALESCE((p_invoice_updates->>'tax_amount')::numeric, tax_amount),\n    total_amount       = COALESCE((p_invoice_updates->>'total_amount')::numeric, total_amount),\n    discount_amount    = COALESCE((p_invoice_updates->>'discount_amount')::numeric, discount_amount),\n    stamp_duty_amount  = COALESCE((p_invoice_updates->>'stamp_duty_amount')::numeric, stamp_duty_amount),\n    po_number          = COALESCE(p_invoice_updates->>'po_number', po_number),\n    payment_terms_days = COALESCE((p_invoice_updates->>'payment_terms_days')::integer, payment_terms_days),\n    notes              = COALESCE(p_invoice_updates->>'notes', notes),\n    linked_challan_ids = v_linked_challan_ids,\n    updated_at         = now()\n  WHERE id = p_invoice_id\n  RETURNING id INTO v_result;\n\n  INSERT INTO public.sales_invoice_items (\n    invoice_id, product_id, batch_id, quantity, unit_price, tax_rate, delivery_challan_item_id\n  )\n  SELECT\n    p_invoice_id,\n    (item->>'product_id')::uuid,\n    NULLIF(item->>'batch_id', '')::uuid,\n    (item->>'quantity')::numeric,\n    (item->>'unit_price')::numeric,\n    (item->>'tax_rate')::numeric,\n    NULLIF(item->>'delivery_challan_item_id', '')::uuid\n  FROM unnest(p_new_items) AS item;\n\n  PERFORM set_config('app.sales_invoice_rebuild', 'false', true);\n  UPDATE public.sales_invoices SET updated_at = now()\n  WHERE id = p_invoice_id AND journal_entry_id IS NULL;\n\n  RETURN v_result;\nEND;\n$function$","-- update_sales_invoice_atomic(p_invoice_id uuid, p_invoice_updates jsonb, p_items jsonb, p_user_id uuid)\nCREATE OR REPLACE FUNCTION public.update_sales_invoice_atomic(p_invoice_id uuid, p_invoice_updates jsonb, p_items jsonb, p_user_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp', 'pg_temp'\nAS $function$\nDECLARE\n  v_result uuid;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  v_result := public.update_sales_invoice_atomic(\n    p_invoice_id,\n    p_invoice_updates,\n    ARRAY(\n      SELECT value\n      FROM jsonb_array_elements(\n        CASE WHEN jsonb_typeof(p_items) = 'array' THEN p_items ELSE '[]'::jsonb END\n      )\n    )::jsonb[]\n  );\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'invoice_id', p_invoice_id,\n    'journal_entry_id', (SELECT journal_entry_id FROM sales_invoices WHERE id = p_invoice_id),\n    'result_id', v_result,\n    'user_id', p_user_id\n  );\nEND;\n$function$","-- accept_document_extraction_atomic(p_document_id uuid, p_actor_id uuid, p_apply_to_request_id uuid)\nCREATE OR REPLACE FUNCTION public.accept_document_extraction_atomic(p_document_id uuid, p_actor_id uuid, p_apply_to_request_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_doc public.crm_product_documents%ROWTYPE;\n  v_extraction JSONB;\n  v_status TEXT;\n  v_now TIMESTAMPTZ := clock_timestamp();\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  -- Lock the document row\n  SELECT * INTO v_doc\n  FROM public.crm_product_documents\n  WHERE id = p_document_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'DOCUMENT_NOT_FOUND: Document % not found', p_document_id;\n  END IF;\n\n  v_extraction := v_doc.ai_extraction;\n  IF v_extraction IS NULL THEN\n    RAISE EXCEPTION 'NO_EXTRACTION: No AI extraction exists for document %', p_document_id;\n  END IF;\n\n  v_status := v_extraction->>'status';\n  IF v_status IN ('accepted', 'dismissed') THEN\n    RAISE EXCEPTION 'DOCUMENT_ALREADY_PROCESSED: Extraction for document % has already been reviewed (status: %)', p_document_id, v_status;\n  END IF;\n\n  -- If request linking is requested, associate document with the request if not already linked\n  IF p_apply_to_request_id IS NOT NULL THEN\n    UPDATE public.crm_product_documents\n    SET enquiry_request_id = p_apply_to_request_id\n    WHERE id = p_document_id AND enquiry_request_id IS NULL;\n  END IF;\n\n  -- Update extraction status to accepted, recording human reviewer and timestamp\n  UPDATE public.crm_product_documents\n  SET ai_extraction = jsonb_set(\n    jsonb_set(\n      jsonb_set(\n        v_extraction,\n        '{status}',\n        '\\"accepted\\"'::jsonb\n      ),\n      '{reviewed_by}',\n      to_jsonb(p_actor_id::text)\n    ),\n    '{reviewed_at}',\n    to_jsonb(v_now::text)\n  )\n  WHERE id = p_document_id;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'document_id', p_document_id,\n    'status', 'accepted',\n    'reviewed_at', v_now\n  );\nEND;\n$function$","-- dismiss_document_extraction_atomic(p_document_id uuid, p_actor_id uuid)\nCREATE OR REPLACE FUNCTION public.dismiss_document_extraction_atomic(p_document_id uuid, p_actor_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_doc public.crm_product_documents%ROWTYPE;\n  v_extraction JSONB;\n  v_status TEXT;\n  v_now TIMESTAMPTZ := clock_timestamp();\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  -- Lock the document row\n  SELECT * INTO v_doc\n  FROM public.crm_product_documents\n  WHERE id = p_document_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'DOCUMENT_NOT_FOUND: Document % not found', p_document_id;\n  END IF;\n\n  v_extraction := v_doc.ai_extraction;\n  IF v_extraction IS NULL THEN\n    RAISE EXCEPTION 'NO_EXTRACTION: No AI extraction exists for document %', p_document_id;\n  END IF;\n\n  v_status := v_extraction->>'status';\n  IF v_status IN ('accepted', 'dismissed') THEN\n    RAISE EXCEPTION 'DOCUMENT_ALREADY_PROCESSED: Extraction for document % has already been reviewed (status: %)', p_document_id, v_status;\n  END IF;\n\n  UPDATE public.crm_product_documents\n  SET ai_extraction = jsonb_set(\n    jsonb_set(\n      jsonb_set(\n        v_extraction,\n        '{status}',\n        '\\"dismissed\\"'::jsonb\n      ),\n      '{dismissed_by}',\n      to_jsonb(p_actor_id::text)\n    ),\n    '{dismissed_at}',\n    to_jsonb(v_now::text)\n  )\n  WHERE id = p_document_id;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'document_id', p_document_id,\n    'status', 'dismissed',\n    'dismissed_at', v_now\n  );\nEND;\n$function$","-- edit_document_extraction_atomic(p_document_id uuid, p_actor_id uuid, p_edited_values jsonb)\nCREATE OR REPLACE FUNCTION public.edit_document_extraction_atomic(p_document_id uuid, p_actor_id uuid, p_edited_values jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_doc public.crm_product_documents%ROWTYPE;\n  v_extraction JSONB;\n  v_status TEXT;\n  v_original JSONB;\n  v_now TIMESTAMPTZ := clock_timestamp();\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  -- Lock the document row\n  SELECT * INTO v_doc\n  FROM public.crm_product_documents\n  WHERE id = p_document_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'DOCUMENT_NOT_FOUND: Document % not found', p_document_id;\n  END IF;\n\n  v_extraction := v_doc.ai_extraction;\n  IF v_extraction IS NULL THEN\n    RAISE EXCEPTION 'NO_EXTRACTION: No AI extraction exists for document %', p_document_id;\n  END IF;\n\n  v_status := v_extraction->>'status';\n  IF v_status IN ('accepted', 'dismissed') THEN\n    RAISE EXCEPTION 'DOCUMENT_ALREADY_PROCESSED: Extraction for document % has already been reviewed (status: %)', p_document_id, v_status;\n  END IF;\n\n  -- Preserve original extraction if not already preserved\n  v_original := COALESCE(v_extraction->'original_extraction', v_extraction);\n\n  -- Update with human edits\n  UPDATE public.crm_product_documents\n  SET ai_extraction = jsonb_set(\n    jsonb_set(\n      jsonb_set(\n        jsonb_set(\n          jsonb_set(\n            v_extraction,\n            '{status}',\n            '\\"edited\\"'::jsonb\n          ),\n          '{reviewed_by}',\n          to_jsonb(p_actor_id::text)\n        ),\n        '{reviewed_at}',\n        to_jsonb(v_now::text)\n      ),\n      '{edited_values}',\n      p_edited_values\n    ),\n    '{original_extraction}',\n    v_original\n  )\n  WHERE id = p_document_id;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'document_id', p_document_id,\n    'status', 'edited',\n    'reviewed_at', v_now\n  );\nEND;\n$function$","-- create_system_task(p_title text, p_description text, p_deadline timestamp with time zone, p_origin text, p_reference_type text, p_reference_id uuid, p_assigned_role text, p_priority text, p_customer_id uuid, p_product_id uuid)\nCREATE OR REPLACE FUNCTION public.create_system_task(p_title text, p_description text, p_deadline timestamp with time zone, p_origin text, p_reference_type text, p_reference_id uuid, p_assigned_role text, p_priority text DEFAULT NULL::text, p_customer_id uuid DEFAULT NULL::uuid, p_product_id uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\nv_role text;\nv_task_id uuid;\nv_assigned_users uuid[];\nv_auto_priority text;\nv_creator_id uuid;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot create system tasks', v_role;\nEND IF;\n\nv_assigned_users := get_users_by_role(p_assigned_role);\nv_auto_priority  := COALESCE(p_priority, calculate_task_priority(p_deadline));\n\nSELECT id INTO v_creator_id FROM user_profiles WHERE role = 'admin' AND is_active = true LIMIT 1;\nIF v_creator_id IS NULL THEN\nSELECT id INTO v_creator_id FROM user_profiles WHERE is_active = true LIMIT 1;\nEND IF;\n\nINSERT INTO tasks (\ntitle, description, deadline, priority, auto_priority, status,\ntask_type, task_mode, task_origin, reference_type, reference_id,\nauto_assigned_role, assigned_users, customer_id, product_id, created_by, proof_required\n) VALUES (\np_title, p_description, p_deadline, v_auto_priority::task_priority, v_auto_priority, 'to_do'::task_status,\n'system', 'advisory', p_origin, p_reference_type, p_reference_id,\np_assigned_role, v_assigned_users, p_customer_id, p_product_id, v_creator_id, false\n)\nRETURNING id INTO v_task_id;\n\nIF array_length(v_assigned_users, 1) > 0 THEN\nINSERT INTO task_assignments (task_id, assigned_user_id, assigned_by)\nSELECT v_task_id, unnest(v_assigned_users), v_creator_id;\nEND IF;\n\nRETURN v_task_id;\nEND;\n$function$","-- create_system_task(p_title text, p_description text, p_deadline timestamp with time zone, p_priority task_priority, p_assigned_users uuid[], p_task_origin task_origin_enum, p_sales_order_id uuid, p_customer_id uuid, p_product_id uuid, p_tags text[], p_metadata jsonb)\nCREATE OR REPLACE FUNCTION public.create_system_task(p_title text, p_description text, p_deadline timestamp with time zone, p_priority task_priority, p_assigned_users uuid[], p_task_origin task_origin_enum, p_sales_order_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_product_id uuid DEFAULT NULL::uuid, p_tags text[] DEFAULT ARRAY[]::text[], p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\nv_role text;\nv_task_id uuid;\nv_system_user uuid;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot create system tasks', v_role;\nEND IF;\n\nSELECT id INTO v_system_user FROM user_profiles WHERE role = 'admin' LIMIT 1;\nIF v_system_user IS NULL THEN\nv_system_user := auth.uid();\nEND IF;\n\nINSERT INTO tasks (\ntitle, description, deadline, priority, status, created_by, assigned_users,\ntask_type, task_mode, task_origin, sales_order_id, customer_id, product_id,\ntags, auto_priority, system_metadata\n) VALUES (\np_title, p_description, p_deadline, p_priority, 'to_do', v_system_user, p_assigned_users,\n'system', 'advisory', p_task_origin, p_sales_order_id, p_customer_id, p_product_id,\narray_append(p_tags, 'system-generated'), true, p_metadata\n)\nRETURNING id INTO v_task_id;\n\nRETURN v_task_id;\nEND;\n$function$","-- dismiss_system_task(p_task_id uuid, p_reason text)\nCREATE OR REPLACE FUNCTION public.dismiss_system_task(p_task_id uuid, p_reason text DEFAULT NULL::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot dismiss system tasks', v_role;\nEND IF;\n\nUPDATE tasks\nSET dismissed_at = now(), dismissed_by = auth.uid(), dismissal_reason = p_reason,\nstatus = 'completed'::task_status\nWHERE id = p_task_id AND task_type = 'system' AND task_mode = 'advisory';\nRETURN FOUND;\nEND;\n$function$","-- get_next_product_code()\nCREATE OR REPLACE FUNCTION public.get_next_product_code()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_role text;\n  v_max_code text;\n  v_next_num integer;\nBEGIN\n  SELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts', 'warehouse') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot generate product codes', v_role;\n  END IF;\n\n  SELECT MAX(product_code) INTO v_max_code\n  FROM products\n  WHERE product_code ~ '^[A-Z]{2,4}-[0-9]+$';\n\n  IF v_max_code IS NULL THEN RETURN 'PRD-001'; END IF;\n  v_next_num := (regexp_match(v_max_code, '[0-9]+$'))[1]::integer + 1;\n  RETURN regexp_replace(v_max_code, '[0-9]+$', LPAD(v_next_num::text, 3, '0'));\nEND;\n$function$","-- check_inquiry_requirements_fulfilled(inquiry_id uuid)\nCREATE OR REPLACE FUNCTION public.check_inquiry_requirements_fulfilled(inquiry_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\nv_role text;\ninquiry_record RECORD;\nall_fulfilled boolean;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'sales') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot check inquiry requirements', v_role;\nEND IF;\n\nSELECT * INTO inquiry_record FROM crm_inquiries WHERE id = inquiry_id;\n\nIF NOT FOUND THEN\nRETURN false;\nEND IF;\n\nall_fulfilled := (\n(NOT inquiry_record.price_required OR inquiry_record.price_sent_at IS NOT NULL) AND\n(NOT inquiry_record.coa_required OR inquiry_record.coa_sent_at IS NOT NULL) AND\n(NOT inquiry_record.sample_required OR inquiry_record.sample_sent_at IS NOT NULL) AND\n(NOT inquiry_record.agency_letter_required OR inquiry_record.agency_letter_sent_at IS NOT NULL)\n);\n\nRETURN all_fulfilled;\nEND;\n$function$","-- calculate_rejection_financial_loss(p_rejection_id uuid)\nCREATE OR REPLACE FUNCTION public.calculate_rejection_financial_loss(p_rejection_id uuid)\n RETURNS numeric\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\nv_role text;\nv_loss decimal;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'warehouse') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot calculate rejection financial loss', v_role;\nEND IF;\n\nSELECT sr.quantity * b.purchase_price INTO v_loss\nFROM stock_rejections sr\nJOIN batches b ON b.id = sr.batch_id\nWHERE sr.id = p_rejection_id;\n\nRETURN COALESCE(v_loss, 0);\nEND;\n$function$","-- calculate_return_financial_impact(p_return_id uuid)\nCREATE OR REPLACE FUNCTION public.calculate_return_financial_impact(p_return_id uuid)\n RETURNS TABLE(total_value numeric, total_quantity numeric, product_count integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\nv_role text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'warehouse') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot calculate return financial impact', v_role;\nEND IF;\n\nRETURN QUERY\nSELECT\nSUM(mri.quantity_returned * mri.unit_price) AS total_value,\nSUM(mri.quantity_returned) AS total_quantity,\nCOUNT(DISTINCT mri.product_id)::integer AS product_count\nFROM material_return_items mri\nWHERE mri.return_id = p_return_id;\nEND;\n$function$","-- generate_tax_notifications()\nCREATE OR REPLACE FUNCTION public.generate_tax_notifications()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_user record;\n  v_row record;\n  v_count int := 0;\n  v_today date := CURRENT_DATE;\n  v_upcoming_cutoff date := CURRENT_DATE + 7;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  FOR v_user IN\n    SELECT id FROM user_profiles\n    WHERE is_active = true AND role IN ('admin','accounts')\n  LOOP\n    -- Overdue tax payments\n    FOR v_row IN\n      SELECT tax_period_id, tax_type, payment_due_date, outstanding_amount\n      FROM vw_outstanding_tax\n      WHERE payment_due_date < v_today AND outstanding_amount > 0\n    LOOP\n      -- Insert directly: we're SECURITY DEFINER so RLS is bypassed. This\n      -- also side-steps upsert_notification's \\"only admins may notify other\n      -- users\\" rule which would fire when a manager triggers this RPC.\n      INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)\n      SELECT v_user.id, 'tax_overdue',\n             v_row.tax_type || ' payment overdue',\n             format('Rp %s outstanding, due %s',\n               to_char(v_row.outstanding_amount, 'FM999G999G999G999D00'),\n               to_char(v_row.payment_due_date, 'DD Mon YYYY')),\n             v_row.tax_period_id, 'tax_period', false\n      WHERE NOT EXISTS (\n        SELECT 1 FROM notifications\n        WHERE user_id = v_user.id\n          AND type = 'tax_overdue'\n          AND reference_id = v_row.tax_period_id\n          AND is_read = false\n      );\n      v_count := v_count + 1;\n    END LOOP;\n\n    -- Upcoming tax payments (next 7 days)\n    FOR v_row IN\n      SELECT tax_period_id, tax_type, payment_due_date, outstanding_amount\n      FROM vw_outstanding_tax\n      WHERE payment_due_date BETWEEN v_today AND v_upcoming_cutoff\n        AND outstanding_amount > 0\n    LOOP\n      INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)\n      SELECT v_user.id, 'tax_due_soon',\n             v_row.tax_type || ' payment due',\n             format('Rp %s due on %s',\n               to_char(v_row.outstanding_amount, 'FM999G999G999G999D00'),\n               to_char(v_row.payment_due_date, 'DD Mon YYYY')),\n             v_row.tax_period_id, 'tax_period', false\n      WHERE NOT EXISTS (\n        SELECT 1 FROM notifications\n        WHERE user_id = v_user.id\n          AND type = 'tax_due_soon'\n          AND reference_id = v_row.tax_period_id\n          AND is_read = false\n      );\n      v_count := v_count + 1;\n    END LOOP;\n\n    -- Missing Faktur Pajak on open PPN periods\n    FOR v_row IN\n      SELECT id AS tax_period_id, fiscal_year, period_month, missing_faktur_count\n      FROM vw_tax_period_status\n      WHERE tax_type = 'PPN' AND status <> 'closed' AND missing_faktur_count > 0\n    LOOP\n      INSERT INTO notifications (user_id, type, title, message, reference_id, reference_type, is_read)\n      SELECT v_user.id, 'faktur_missing',\n             'Waiting for Faktur',\n             format('%s sales invoice(s) in %s-%s need a Faktur Pajak number',\n               v_row.missing_faktur_count,\n               v_row.fiscal_year,\n               lpad(v_row.period_month::text, 2, '0')),\n             v_row.tax_period_id, 'tax_period', false\n      WHERE NOT EXISTS (\n        SELECT 1 FROM notifications\n        WHERE user_id = v_user.id\n          AND type = 'faktur_missing'\n          AND reference_id = v_row.tax_period_id\n          AND is_read = false\n      );\n      v_count := v_count + 1;\n    END LOOP;\n  END LOOP;\n\n  RETURN v_count;\nEND $function$","-- log_timeline_event(p_inquiry_id uuid, p_event_type text, p_event_title text, p_event_description text, p_old_value text, p_new_value text, p_performed_by uuid)\nCREATE OR REPLACE FUNCTION public.log_timeline_event(p_inquiry_id uuid, p_event_type text, p_event_title text, p_event_description text DEFAULT NULL::text, p_old_value text DEFAULT NULL::text, p_new_value text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\nv_role text;\nnew_timeline_id uuid;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts', 'sales') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot log timeline events', v_role;\nEND IF;\n\nINSERT INTO crm_inquiry_timeline (\ninquiry_id, event_type, event_title, event_description,\nold_value, new_value, performed_by\n) VALUES (\np_inquiry_id, p_event_type, p_event_title, p_event_description,\np_old_value, p_new_value,\nCOALESCE(p_performed_by, auth.uid())\n) RETURNING id INTO new_timeline_id;\n\nRETURN new_timeline_id;\nEND;\n$function$","-- fn_safe_autolink_dc_to_so()\nCREATE OR REPLACE FUNCTION public.fn_safe_autolink_dc_to_so()\n RETURNS TABLE(dc_id uuid, linked_so_id uuid, action text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\ndc_rec          RECORD;\ncandidate_so_id uuid;\nmatch_count     int;\nv_role          text;\nBEGIN\nSELECT role INTO v_role FROM user_profiles WHERE id = auth.uid();\nIF v_role NOT IN ('admin', 'accounts') THEN\nRAISE EXCEPTION 'Permission denied: role % cannot auto-link challans', v_role;\nEND IF;\n\nFOR dc_rec IN\nSELECT dc.id, dc.customer_id FROM delivery_challans dc\nWHERE dc.sales_order_id IS NULL\nAND (dc.review_status IS NULL OR dc.review_status != 'needs_review')\nLOOP\nSELECT COUNT(DISTINCT so.id) INTO match_count\nFROM sales_orders so\nWHERE so.customer_id = dc_rec.customer_id AND so.is_archived = false\nAND so.status NOT IN ('draft','cancelled','rejected')\nAND NOT EXISTS (\nSELECT 1 FROM delivery_challan_items dci\nWHERE dci.challan_id = dc_rec.id\nAND NOT EXISTS (\nSELECT 1 FROM sales_order_items soi\nWHERE soi.sales_order_id = so.id AND soi.product_id = dci.product_id\nAND soi.quantity >= dci.quantity\n)\n)\nAND EXISTS (SELECT 1 FROM delivery_challan_items dci2 WHERE dci2.challan_id = dc_rec.id);\n\nIF match_count = 1 THEN\nSELECT so.id INTO candidate_so_id\nFROM sales_orders so\nWHERE so.customer_id = dc_rec.customer_id AND so.is_archived = false\nAND so.status NOT IN ('draft','cancelled','rejected')\nAND NOT EXISTS (\nSELECT 1 FROM delivery_challan_items dci\nWHERE dci.challan_id = dc_rec.id\nAND NOT EXISTS (\nSELECT 1 FROM sales_order_items soi\nWHERE soi.sales_order_id = so.id AND soi.product_id = dci.product_id\nAND soi.quantity >= dci.quantity\n)\n)\nAND EXISTS (SELECT 1 FROM delivery_challan_items dci2 WHERE dci2.challan_id = dc_rec.id)\nLIMIT 1;\n\nUPDATE delivery_challans SET sales_order_id = candidate_so_id, updated_at = now()\nWHERE id = dc_rec.id;\ndc_id := dc_rec.id; linked_so_id := candidate_so_id; action := 'linked';\nRETURN NEXT;\nELSE\nUPDATE delivery_challans SET review_status = 'needs_review', updated_at = now()\nWHERE id = dc_rec.id AND sales_order_id IS NULL;\ndc_id := dc_rec.id; linked_so_id := NULL; action := 'needs_review';\nRETURN NEXT;\nEND IF;\nEND LOOP;\nEND;\n$function$"}	final_security_authorization_audit	\N	\N	\N
