20260916001500	{"-- ============================================================================\n-- HARDEN SENSITIVE FINANCE, INVENTORY & IDENTITY RPCs\n-- Migration: 20260916001500_harden_identity_and_finance_rpcs.sql\n-- ============================================================================\n\n-- 1. post_payment_voucher (finance role check + enforce auth.uid() as poster)\nCREATE OR REPLACE FUNCTION public.post_payment_voucher(p_pv_id uuid, p_posted_by uuid DEFAULT NULL::uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_pv RECORD;\n  v_rate numeric;\n  v_gross numeric;\n  v_payment numeric;\n  v_converted numeric;\n  v_pph_bank numeric;\n  v_charge_amt numeric;\n  v_actual numeric;\n  v_expected numeric;\n  v_fx_delta numeric;\n  v_ap_debit numeric;\n  v_total numeric;\n  v_entry text;\n  v_je uuid;\n  v_line integer := 1;\n  v_ap uuid;\n  v_bank uuid;\n  v_charge uuid;\n  v_pph uuid;\n  v_fx uuid;\n  v_invoice_currency text;\n  v_bank_currency text;\n  v_actual_poster uuid;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actual_poster := auth.uid();\n\n  SELECT * INTO v_pv FROM public.payment_vouchers WHERE id=p_pv_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found', p_pv_id; END IF;\n  IF v_pv.is_posted THEN RAISE EXCEPTION 'Payment voucher % is already posted', v_pv.voucher_number; END IF;\n\n  v_invoice_currency := upper(COALESCE(v_pv.invoice_currency, v_pv.transaction_currency, v_pv.payment_currency, 'IDR'));\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id=v_pv.bank_account_id;\n  v_bank_currency := COALESCE(v_bank_currency, v_pv.bank_currency, v_pv.payment_currency, 'IDR');\n  v_rate := CASE WHEN v_invoice_currency=v_bank_currency THEN 1 ELSE COALESCE(v_pv.exchange_rate, 0) END;\n  IF v_rate <= 0 THEN RAISE EXCEPTION 'Missing exchange rate for %', v_pv.voucher_number; END IF;\n\n  v_gross := COALESCE(v_pv.invoice_amount, v_pv.amount, 0);\n  v_payment := COALESCE(v_pv.payment_amount, v_gross - COALESCE(v_pv.pph_amount, 0));\n  v_converted := COALESCE(v_pv.converted_amount, v_payment * v_rate);\n  v_pph_bank := COALESCE(v_pv.pph_amount, 0) * v_rate;\n  v_charge_amt := COALESCE(v_pv.bank_charge, 0);\n  v_actual := COALESCE(v_pv.actual_bank_debit, v_pv.bank_amount, v_converted + v_charge_amt);\n  v_expected := v_converted + v_charge_amt;\n  v_fx_delta := v_actual - v_expected;\n  v_ap_debit := v_gross * v_rate;\n\n  IF v_pv.coa_account_id IS NOT NULL THEN\n    v_ap := v_pv.coa_account_id;\n  ELSE\n    SELECT id INTO v_ap FROM public.chart_of_accounts WHERE code='2110' LIMIT 1;\n  END IF;\n  IF v_pv.payment_method = 'advance_adjustment' OR v_pv.payment_purpose = 'salary_advance' THEN\n    SELECT id INTO v_bank FROM public.chart_of_accounts WHERE code='1160' LIMIT 1;\n  ELSE\n    SELECT coa_id INTO v_bank FROM public.bank_accounts WHERE id=v_pv.bank_account_id;\n    IF v_bank IS NULL THEN SELECT id INTO v_bank FROM public.chart_of_accounts WHERE code='1101' LIMIT 1; END IF;\n  END IF;\n  SELECT id INTO v_charge FROM public.chart_of_accounts WHERE code='7100' LIMIT 1;\n  SELECT id INTO v_pph FROM public.chart_of_accounts WHERE code='2132' LIMIT 1;\n  SELECT id INTO v_fx FROM public.chart_of_accounts WHERE code='7300' LIMIT 1;\n  IF v_ap IS NULL OR v_bank IS NULL THEN RAISE EXCEPTION 'Required payment accounts are missing'; END IF;\n  IF v_pph_bank > 0 AND v_pph IS NULL THEN RAISE EXCEPTION 'PPh payable account is missing'; END IF;\n\n  v_total := v_ap_debit + v_charge_amt + GREATEST(v_fx_delta, 0);\n  v_entry := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(entry_number, entry_date, source_module, reference_id, reference_number, description, total_debit, total_credit, is_posted, posted_by)\n  VALUES(v_entry, v_pv.voucher_date, 'payment', v_pv.id, v_pv.voucher_number, 'Payment Voucher: ' || v_pv.voucher_number, v_total, v_total, true, v_actual_poster)\n  RETURNING id INTO v_je;\n\n  INSERT INTO public.journal_entry_lines(journal_entry_id, line_number, account_id, description, debit, credit, transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id)\n  VALUES(v_je, v_line, v_ap, 'Payment - ' || v_pv.voucher_number, v_ap_debit, 0, v_invoice_currency, v_gross, 0, v_rate, v_pv.supplier_id); v_line := v_line + 1;\n  IF v_charge_amt > 0 AND v_charge IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id, line_number, account_id, description, debit, credit, transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id)\n    VALUES(v_je, v_line, v_charge, 'Bank Charge - ' || v_pv.voucher_number, v_charge_amt, 0, v_bank_currency, v_charge_amt, 0, 1, v_pv.supplier_id); v_line := v_line + 1;\n  END IF;\n  IF v_pph_bank > 0 AND v_pph IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id, line_number, account_id, description, debit, credit, transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id)\n    VALUES(v_je, v_line, v_pph, 'PPh Withholding - ' || v_pv.voucher_number, 0, v_pph_bank, v_bank_currency, 0, v_pv.pph_amount, v_rate, v_pv.supplier_id); v_line := v_line + 1;\n  END IF;\n  INSERT INTO public.journal_entry_lines(journal_entry_id, line_number, account_id, description, debit, credit, transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id)\n  VALUES(v_je, v_line, v_bank, CASE WHEN v_pv.payment_method='advance_adjustment' THEN 'Advance Adjustment - ' ELSE 'Bank Payment - ' END || v_pv.voucher_number, 0, v_actual, v_bank_currency, 0, v_actual, 1, v_pv.supplier_id); v_line := v_line + 1;\n  IF v_fx_delta > 0 AND v_fx IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)\n    VALUES(v_je, v_line, v_fx, 'FX loss - ' || v_pv.voucher_number, v_fx_delta, 0, v_pv.supplier_id);\n  ELSIF v_fx_delta < 0 AND v_fx IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)\n    VALUES(v_je, v_line, v_fx, 'FX gain - ' || v_pv.voucher_number, 0, abs(v_fx_delta), v_pv.supplier_id);\n  END IF;\n  UPDATE public.payment_vouchers SET is_posted=true, journal_entry_id=v_je WHERE id=p_pv_id;\n  INSERT INTO public.audit_logs(table_name, record_id, action_type, old_values, new_values, user_id)\n  VALUES('payment_vouchers', p_pv_id, 'update', jsonb_build_object('is_posted', false), jsonb_build_object('is_posted', true, 'journal_entry_id', v_je), v_actual_poster);\nEND;\n$$","-- 2. post_receipt_voucher (finance role check + enforce auth.uid() as poster)\nCREATE OR REPLACE FUNCTION public.post_receipt_voucher(p_rv_id uuid, p_posted_by uuid DEFAULT NULL::uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_rv                 RECORD;\n  v_je_id              UUID;\n  v_je_number          TEXT;\n  v_debit_account_id   UUID;\n  v_credit_account_id  UUID;\n  v_actual_poster      UUID;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actual_poster := auth.uid();\n\n  SELECT * INTO v_rv FROM receipt_vouchers WHERE id = p_rv_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id; END IF;\n  IF v_rv.is_posted THEN RAISE EXCEPTION 'Receipt voucher % is already posted', v_rv.voucher_number; END IF;\n\n  IF v_rv.bank_account_id IS NOT NULL THEN\n    SELECT coa_id INTO v_debit_account_id FROM bank_accounts WHERE id = v_rv.bank_account_id;\n  ELSIF v_rv.payment_method = 'cash' THEN\n    SELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\n  END IF;\n  IF v_debit_account_id IS NULL THEN\n    SELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\n  END IF;\n\n  IF v_rv.coa_account_id IS NOT NULL THEN\n    v_credit_account_id := v_rv.coa_account_id;\n  ELSE\n    SELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1120' LIMIT 1;\n  END IF;\n\n  IF v_debit_account_id IS NULL OR v_credit_account_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot post: required chart of accounts entries missing';\n  END IF;\n\n  v_je_number := next_journal_entry_number();\n\n  INSERT INTO journal_entries (\n    entry_number, entry_date, source_module, reference_id, reference_number,\n    description, total_debit, total_credit, is_posted, posted_by\n  ) VALUES (\n    v_je_number, v_rv.voucher_date, 'receipt', v_rv.id, v_rv.voucher_number,\n    'Receipt Voucher: ' || v_rv.voucher_number,\n    v_rv.amount, v_rv.amount, TRUE, v_actual_poster\n  ) RETURNING id INTO v_je_id;\n\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, 1, v_debit_account_id, 'Cash Receipt - ' || v_rv.voucher_number, v_rv.amount, 0, v_rv.customer_id);\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, 2, v_credit_account_id, 'Receipt - ' || v_rv.voucher_number, 0, v_rv.amount, v_rv.customer_id);\n\n  UPDATE receipt_vouchers\n  SET is_posted = TRUE, journal_entry_id = v_je_id\n  WHERE id = p_rv_id;\n\n  INSERT INTO audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)\n  VALUES (\n    'receipt_vouchers', p_rv_id, 'update',\n    jsonb_build_object('is_posted', FALSE),\n    jsonb_build_object('is_posted', TRUE, 'journal_entry_id', v_je_id, 'journal_entry_number', v_je_number, 'posted_by', v_actual_poster),\n    v_actual_poster\n  );\nEND;\n$$","-- 3. cancel_gl_posting (finance role check + enforce auth.uid() in audit)\nCREATE OR REPLACE FUNCTION public.cancel_gl_posting(p_je_id uuid, p_doc_id uuid, p_table_name text, p_cancelled_by uuid, p_reason text, p_extra_audit jsonb DEFAULT '{}'::jsonb)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_je            journal_entries%ROWTYPE;\n  v_period_status TEXT;\n  v_actor         UUID;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actor := auth.uid();\n\n  SELECT * INTO v_je FROM journal_entries WHERE id = p_je_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Journal entry % not found', p_je_id;\n  END IF;\n\n  SELECT ap.status INTO v_period_status\n  FROM accounting_periods ap\n  WHERE ap.start_date <= v_je.entry_date AND ap.end_date >= v_je.entry_date\n  ORDER BY ap.start_date DESC\n  LIMIT 1;\n\n  IF v_period_status IS NOT NULL AND v_period_status != 'open' THEN\n    RAISE EXCEPTION\n      'Cannot cancel posting: the accounting period for % is closed. Contact your finance manager to reopen the period.',\n      TO_CHAR(v_je.entry_date, 'FMMonth YYYY');\n  END IF;\n\n  DELETE FROM journal_entry_lines WHERE journal_entry_id = p_je_id;\n  DELETE FROM journal_entries      WHERE id              = p_je_id;\n\n  INSERT INTO audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)\n  VALUES (\n    p_table_name, p_doc_id, 'update',\n    p_extra_audit || jsonb_build_object(\n      '_action',              'CANCEL_POSTING',\n      'journal_entry_id',     p_je_id,\n      'journal_entry_number', v_je.entry_number,\n      'entry_date',           v_je.entry_date,\n      'reason',               p_reason\n    ),\n    jsonb_build_object('cancelled_by', v_actor, 'cancelled_at', NOW()),\n    v_actor\n  );\nEND;\n$$","-- 4. save_payment_voucher_with_allocations (finance role check + enforce auth.uid() as creator)\nCREATE OR REPLACE FUNCTION public.save_payment_voucher_with_allocations(\n  p_voucher_id uuid DEFAULT NULL::uuid,\n  p_voucher_number text DEFAULT NULL::text,\n  p_voucher_date date DEFAULT NULL::date,\n  p_supplier_id uuid DEFAULT NULL::uuid,\n  p_payment_method text DEFAULT NULL::text,\n  p_bank_account_id uuid DEFAULT NULL::uuid,\n  p_reference_number text DEFAULT NULL::text,\n  p_amount numeric DEFAULT 0,\n  p_pph_amount numeric DEFAULT 0,\n  p_pph_code_id uuid DEFAULT NULL::uuid,\n  p_description text DEFAULT NULL::text,\n  p_payment_currency text DEFAULT 'IDR'::text,\n  p_exchange_rate numeric DEFAULT 1,\n  p_bank_amount numeric DEFAULT NULL::numeric,\n  p_bank_charge numeric DEFAULT 0,\n  p_created_by uuid DEFAULT NULL::uuid,\n  p_allocations jsonb DEFAULT '[]'::jsonb,\n  p_staff_id uuid DEFAULT NULL::uuid\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_voucher_id    UUID;\n  v_alloc         JSONB;\n  v_invoice_id    UUID;\n  v_expense_id    UUID;\n  v_alloc_amount  NUMERIC;\n  v_creator       UUID;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_creator := auth.uid();\n\n  IF p_supplier_id IS NULL AND p_staff_id IS NULL THEN\n    RAISE EXCEPTION 'Payment voucher needs a payee: supplier or staff';\n  END IF;\n\n  IF p_voucher_id IS NULL THEN\n    INSERT INTO payment_vouchers (\n      voucher_number, voucher_date, supplier_id, staff_id, payment_method,\n      bank_account_id, reference_number, amount, pph_amount, pph_code_id,\n      description, payment_currency, exchange_rate,\n      bank_amount, bank_charge, created_by\n    ) VALUES (\n      p_voucher_number, p_voucher_date, p_supplier_id, p_staff_id, p_payment_method,\n      p_bank_account_id, p_reference_number, p_amount, p_pph_amount, p_pph_code_id,\n      p_description, p_payment_currency, p_exchange_rate,\n      p_bank_amount, p_bank_charge, v_creator\n    ) RETURNING id INTO v_voucher_id;\n  ELSE\n    v_voucher_id := p_voucher_id;\n\n    IF EXISTS (SELECT 1 FROM payment_vouchers WHERE id = v_voucher_id AND is_posted = TRUE) THEN\n      RAISE EXCEPTION 'Cannot edit: % is posted. Cancel Posting first to make changes.', p_voucher_number;\n    END IF;\n\n    UPDATE payment_vouchers SET\n      voucher_date      = p_voucher_date,\n      supplier_id       = p_supplier_id,\n      staff_id          = p_staff_id,\n      payment_method    = p_payment_method,\n      bank_account_id   = p_bank_account_id,\n      reference_number  = p_reference_number,\n      amount            = p_amount,\n      pph_amount        = p_pph_amount,\n      pph_code_id       = p_pph_code_id,\n      description       = p_description,\n      payment_currency  = p_payment_currency,\n      exchange_rate     = p_exchange_rate,\n      bank_amount       = p_bank_amount,\n      bank_charge       = p_bank_charge,\n      updated_at        = NOW()\n    WHERE id = v_voucher_id;\n  END IF;\n\n  DELETE FROM voucher_allocations WHERE payment_voucher_id = v_voucher_id;\n\n  FOR v_alloc IN SELECT value FROM jsonb_array_elements(p_allocations) AS value\n  LOOP\n    v_alloc_amount := COALESCE((v_alloc->>'amount')::NUMERIC, 0);\n    IF v_alloc_amount <= 0 THEN\n      CONTINUE;\n    END IF;\n\n    v_invoice_id := NULLIF(v_alloc->>'invoice_id', '')::UUID;\n    v_expense_id := NULLIF(v_alloc->>'finance_expense_id', '')::UUID;\n\n    IF v_invoice_id IS NOT NULL THEN\n      INSERT INTO voucher_allocations (\n        payment_voucher_id, purchase_invoice_id,\n        allocated_amount, allocated_currency, voucher_type\n      ) VALUES (\n        v_voucher_id, v_invoice_id, v_alloc_amount,\n        COALESCE(v_alloc->>'currency', 'IDR'), 'payment'\n      );\n    ELSIF v_expense_id IS NOT NULL THEN\n      INSERT INTO voucher_allocations (\n        payment_voucher_id, finance_expense_id,\n        allocated_amount, allocated_currency, voucher_type\n      ) VALUES (\n        v_voucher_id, v_expense_id, v_alloc_amount,\n        COALESCE(v_alloc->>'currency', 'IDR'), 'payment'\n      );\n    END IF;\n  END LOOP;\n\n  RETURN v_voucher_id;\nEND;\n$$","-- 5. create_fund_transfer_with_posting (finance role check + enforce auth.uid() as creator)\nCREATE OR REPLACE FUNCTION public.create_fund_transfer_with_posting(\n  p_transfer_date date,\n  p_from_amount numeric,\n  p_to_amount numeric,\n  p_from_account_type text,\n  p_to_account_type text,\n  p_description text DEFAULT NULL::text,\n  p_from_bank_account_id uuid DEFAULT NULL::uuid,\n  p_to_bank_account_id uuid DEFAULT NULL::uuid,\n  p_from_bank_statement_line_id uuid DEFAULT NULL::uuid,\n  p_to_bank_statement_line_id uuid DEFAULT NULL::uuid,\n  p_exchange_rate numeric DEFAULT NULL::numeric,\n  p_created_by uuid DEFAULT NULL::uuid\n)\nRETURNS fund_transfers\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_user_id uuid;\n  v_transfer_number text;\n  v_transfer public.fund_transfers;\n  v_source_account_name text;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_user_id := auth.uid();\n\n  v_transfer_number := public.generate_fund_transfer_number();\n\n  INSERT INTO public.fund_transfers (\n    transfer_number,\n    transfer_date,\n    amount,\n    from_amount,\n    to_amount,\n    exchange_rate,\n    from_account_type,\n    to_account_type,\n    from_bank_account_id,\n    to_bank_account_id,\n    from_bank_statement_line_id,\n    to_bank_statement_line_id,\n    description,\n    created_by\n  ) VALUES (\n    v_transfer_number,\n    p_transfer_date,\n    p_from_amount,\n    p_from_amount,\n    p_to_amount,\n    p_exchange_rate,\n    p_from_account_type,\n    p_to_account_type,\n    CASE WHEN p_from_account_type = 'bank' THEN p_from_bank_account_id ELSE NULL END,\n    CASE WHEN p_to_account_type = 'bank' THEN p_to_bank_account_id ELSE NULL END,\n    p_from_bank_statement_line_id,\n    p_to_bank_statement_line_id,\n    NULLIF(p_description, ''),\n    v_user_id\n  )\n  RETURNING * INTO v_transfer;\n\n  IF v_transfer.to_account_type = 'petty_cash' THEN\n    IF v_transfer.from_account_type = 'bank' THEN\n      SELECT COALESCE(ba.alias, ba.bank_name, 'Bank')\n        INTO v_source_account_name\n      FROM public.bank_accounts ba\n      WHERE ba.id = v_transfer.from_bank_account_id;\n    ELSE\n      v_source_account_name := 'Cash on Hand';\n    END IF;\n\n    INSERT INTO public.petty_cash_transactions (\n      transaction_date,\n      transaction_type,\n      amount,\n      description,\n      bank_account_id,\n      bank_statement_line_id,\n      source,\n      fund_transfer_id,\n      approval_status,\n      created_by\n    ) VALUES (\n      v_transfer.transfer_date,\n      'withdraw',\n      v_transfer.to_amount,\n      COALESCE(v_transfer.description, 'Fund transfer from ' || COALESCE(v_source_account_name, 'Bank')),\n      v_transfer.from_bank_account_id,\n      v_transfer.from_bank_statement_line_id,\n      'Fund Transfer ' || v_transfer.transfer_number,\n      v_transfer.id,\n      'approved',\n      v_user_id\n    )\n    ON CONFLICT (fund_transfer_id) WHERE fund_transfer_id IS NOT NULL DO NOTHING;\n  END IF;\n\n  RETURN v_transfer;\nEND;\n$$","-- 6. post_fund_transfer_journal (enforce auth.uid() as creator)\nCREATE OR REPLACE FUNCTION public.post_fund_transfer_journal(p_transfer_id uuid, p_user_id uuid DEFAULT NULL::uuid)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_transfer        RECORD;\n  v_journal_id      UUID;\n  v_from_account_id UUID;\n  v_to_account_id   UUID;\n  v_description     TEXT;\n  v_actor           UUID;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actor := auth.uid();\n\n  SELECT * INTO v_transfer FROM fund_transfers WHERE id = p_transfer_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Fund transfer not found'; END IF;\n  IF v_transfer.journal_entry_id IS NOT NULL THEN RETURN v_transfer.journal_entry_id; END IF;\n\n  SELECT id INTO v_journal_id FROM journal_entries\n  WHERE reference_number = v_transfer.transfer_number AND source_module = 'fund_transfers'\n  ORDER BY created_at DESC LIMIT 1;\n  IF v_journal_id IS NOT NULL THEN\n    UPDATE fund_transfers SET journal_entry_id = v_journal_id WHERE id = p_transfer_id;\n    RETURN v_journal_id;\n  END IF;\n\n  IF    v_transfer.from_account_type = 'petty_cash'   THEN SELECT id INTO v_from_account_id FROM chart_of_accounts WHERE code = '1102' LIMIT 1;\n  ELSIF v_transfer.from_account_type = 'cash_on_hand' THEN SELECT id INTO v_from_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\n  ELSIF v_transfer.from_account_type = 'bank'         THEN SELECT coa_id INTO v_from_account_id FROM bank_accounts WHERE id = v_transfer.from_bank_account_id;\n  END IF;\n\n  IF    v_transfer.to_account_type = 'petty_cash'   THEN SELECT id INTO v_to_account_id FROM chart_of_accounts WHERE code = '1102' LIMIT 1;\n  ELSIF v_transfer.to_account_type = 'cash_on_hand' THEN SELECT id INTO v_to_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\n  ELSIF v_transfer.to_account_type = 'bank'         THEN SELECT coa_id INTO v_to_account_id FROM bank_accounts WHERE id = v_transfer.to_bank_account_id;\n  END IF;\n\n  IF v_from_account_id IS NULL OR v_to_account_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot determine chart of accounts for transfer';\n  END IF;\n\n  v_description := 'Fund Transfer ' || v_transfer.transfer_number;\n  IF v_transfer.description IS NOT NULL THEN\n    v_description := v_description || ' - ' || v_transfer.description;\n  END IF;\n\n  INSERT INTO journal_entries (\n    entry_date, source_module, reference_id, reference_number,\n    description, total_debit, total_credit, is_posted, created_by\n  ) VALUES (\n    v_transfer.transfer_date, 'fund_transfers', v_transfer.id, v_transfer.transfer_number,\n    v_description, 0, 0, true, v_actor\n  ) RETURNING id INTO v_journal_id;\n\n  INSERT INTO journal_entry_lines (journal_entry_id, account_id, debit, credit, description)\n  VALUES\n    (v_journal_id, v_to_account_id,   v_transfer.amount, 0,                  'Transfer In'),\n    (v_journal_id, v_from_account_id, 0,                  v_transfer.amount, 'Transfer Out');\n\n  UPDATE fund_transfers SET journal_entry_id = v_journal_id WHERE id = p_transfer_id;\n  RETURN v_journal_id;\nEND;\n$$","-- 7. move_expense_to_petty_cash (enforce auth.uid() as creator)\nCREATE OR REPLACE FUNCTION public.move_expense_to_petty_cash(p_expense_id uuid, p_user_id uuid DEFAULT NULL::uuid)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_expense          RECORD;\n  v_pc_number        TEXT;\n  v_petty_cash_tx_id UUID;\n  v_actor            UUID;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actor := auth.uid();\n\n  SELECT * INTO v_expense FROM finance_expenses WHERE id = p_expense_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Expense not found'; END IF;\n  IF v_expense.petty_cash_transaction_id IS NOT NULL THEN\n    RAISE EXCEPTION 'Expense already linked to petty cash';\n  END IF;\n\n  SELECT 'PC-' || TO_CHAR(v_expense.expense_date, 'YYYYMMDD') || '-' ||\n    LPAD((COUNT(*) + 1)::TEXT, 4, '0')\n  INTO v_pc_number FROM petty_cash_transactions WHERE transaction_date = v_expense.expense_date;\n\n  INSERT INTO petty_cash_transactions (\n    transaction_number, transaction_date, transaction_type, amount, description,\n    expense_category, bank_account_id, created_by, source, paid_to, paid_by, finance_expense_id\n  ) VALUES (\n    v_pc_number, v_expense.expense_date, 'expense', v_expense.amount, v_expense.description,\n    v_expense.expense_category, v_expense.bank_account_id, v_actor,\n    'moved_from_tracker', v_expense.description, 'cash', v_expense.id\n  ) RETURNING id INTO v_petty_cash_tx_id;\n\n  UPDATE finance_expenses\n  SET petty_cash_transaction_id = v_petty_cash_tx_id, payment_method = 'cash', paid_by = 'cash'\n  WHERE id = p_expense_id;\n\n  RETURN v_petty_cash_tx_id;\nEND;\n$$","-- 8. move_expense_to_tracker (enforce auth.uid() as creator)\nCREATE OR REPLACE FUNCTION public.move_expense_to_tracker(p_petty_cash_id uuid, p_bank_account_id uuid, p_payment_method text, p_user_id uuid DEFAULT NULL::uuid)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_pc_tx            RECORD;\n  v_expense_id       UUID;\n  v_finance_category TEXT;\n  v_actor            UUID;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actor := auth.uid();\n\n  SELECT * INTO v_pc_tx FROM petty_cash_transactions\n  WHERE id = p_petty_cash_id AND transaction_type = 'expense';\n  IF NOT FOUND THEN RAISE EXCEPTION 'Petty cash expense not found'; END IF;\n\n  IF v_pc_tx.finance_expense_id IS NOT NULL THEN\n    UPDATE finance_expenses\n    SET payment_method = p_payment_method, bank_account_id = p_bank_account_id, paid_by = 'bank'\n    WHERE id = v_pc_tx.finance_expense_id RETURNING id INTO v_expense_id;\n    RETURN v_expense_id;\n  END IF;\n\n  v_finance_category := CASE\n    WHEN v_pc_tx.expense_category IN ('Office Supplies','Postage & Courier','Cleaning & Maintenance','Miscellaneous') THEN 'office_admin'\n    WHEN v_pc_tx.expense_category = 'Transportation' THEN 'delivery_sales'\n    WHEN v_pc_tx.expense_category = 'Utilities'      THEN 'utilities'\n    ELSE 'other'\n  END;\n\n  INSERT INTO finance_expenses (\n    expense_category, expense_type, amount, expense_date, description,\n    payment_method, bank_account_id, paid_by, created_by, petty_cash_transaction_id\n  ) VALUES (\n    v_finance_category, 'admin', v_pc_tx.amount, v_pc_tx.transaction_date,\n    v_pc_tx.description || ' (Moved from Petty Cash: ' || v_pc_tx.transaction_number || ')',\n    p_payment_method, p_bank_account_id, 'bank', v_actor, v_pc_tx.id\n  ) RETURNING id INTO v_expense_id;\n\n  UPDATE petty_cash_transactions\n  SET finance_expense_id = v_expense_id, source = 'moved_to_tracker'\n  WHERE id = p_petty_cash_id;\n\n  RETURN v_expense_id;\nEND;\n$$","-- 9. lock_import_container (enforce auth.uid() as locked_by)\nCREATE OR REPLACE FUNCTION public.lock_import_container(p_container_id uuid, p_user_id uuid DEFAULT NULL::uuid)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nBEGIN\n  PERFORM public._sec_check_finance_role();\n\n  UPDATE import_containers\n  SET status = 'locked', locked_at = now(), locked_by = auth.uid(), updated_at = now()\n  WHERE id = p_container_id AND status = 'allocated';\n  IF NOT FOUND THEN RAISE EXCEPTION 'Container not found or already locked'; END IF;\n\n  UPDATE batches SET cost_locked = true, cost_locked_at = now(), updated_at = now()\n  WHERE import_container_id = p_container_id AND cost_locked = false;\n\n  RETURN true;\nEND;\n$$","-- 10. post_inventory_movement (role authorization check)\nCREATE OR REPLACE FUNCTION public.post_inventory_movement(\n  p_operation_id uuid,\n  p_product_id uuid,\n  p_batch_id uuid,\n  p_transaction_type text,\n  p_quantity numeric,\n  p_transaction_date date DEFAULT CURRENT_DATE,\n  p_reference_number text DEFAULT NULL::text,\n  p_reference_type text DEFAULT NULL::text,\n  p_reference_id uuid DEFAULT NULL::uuid,\n  p_notes text DEFAULT NULL::text,\n  p_created_by uuid DEFAULT NULL::uuid,\n  p_stock_before numeric DEFAULT NULL::numeric,\n  p_stock_after numeric DEFAULT NULL::numeric\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_existing public.inventory_transactions%ROWTYPE;\n  v_batch public.batches%ROWTYPE;\n  v_transaction_id uuid;\n  v_new_stock numeric;\n  v_previous_context text;\n  v_creator uuid;\nBEGIN\n  IF auth.role() <> 'service_role' THEN\n    IF auth.uid() IS NULL THEN\n      RAISE EXCEPTION 'Not authenticated';\n    END IF;\n    IF NOT public.inventory_v1_actor_allowed(ARRAY['admin', 'accounts', 'warehouse']) THEN\n      RAISE EXCEPTION 'Permission denied for inventory movement';\n    END IF;\n  END IF;\n\n  v_creator := COALESCE(auth.uid(), p_created_by);\n\n  IF p_operation_id IS NULL THEN\n    RAISE EXCEPTION 'Canonical inventory posting requires operation_id';\n  END IF;\n  IF p_batch_id IS NULL OR p_product_id IS NULL THEN\n    RAISE EXCEPTION 'Canonical inventory posting requires product_id and batch_id';\n  END IF;\n  IF COALESCE(p_quantity, 0) = 0 THEN\n    RAISE EXCEPTION 'Canonical inventory posting quantity cannot be zero';\n  END IF;\n  IF p_transaction_type NOT IN (\n    'purchase', 'delivery_challan', 'return', 'adjustment', 'rejection'\n  ) THEN\n    RAISE EXCEPTION 'Unsupported canonical inventory transaction type: %',\n      p_transaction_type;\n  END IF;\n\n  SELECT *\n  INTO v_existing\n  FROM public.inventory_transactions\n  WHERE operation_id = p_operation_id;\n\n  IF FOUND THEN\n    IF v_existing.batch_id IS DISTINCT FROM p_batch_id\n       OR v_existing.product_id IS DISTINCT FROM p_product_id\n       OR v_existing.transaction_type IS DISTINCT FROM p_transaction_type\n       OR v_existing.quantity IS DISTINCT FROM p_quantity\n       OR v_existing.reference_type IS DISTINCT FROM p_reference_type\n       OR v_existing.reference_id IS DISTINCT FROM p_reference_id THEN\n      RAISE EXCEPTION 'operation_id % was already used with different inventory values',\n        p_operation_id;\n    END IF;\n    RETURN v_existing.id;\n  END IF;\n\n  SELECT *\n  INTO v_batch\n  FROM public.batches\n  WHERE id = p_batch_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Batch not found: %', p_batch_id;\n  END IF;\n  IF v_batch.product_id IS DISTINCT FROM p_product_id THEN\n    RAISE EXCEPTION 'Product % does not match batch % product %',\n      p_product_id, p_batch_id, v_batch.product_id;\n  END IF;\n\n  IF p_transaction_type IN ('purchase', 'return') AND p_quantity <= 0 THEN\n    RAISE EXCEPTION '% movement must be positive', p_transaction_type;\n  END IF;\n  IF p_transaction_type IN ('delivery_challan', 'rejection') AND p_quantity >= 0 THEN\n    RAISE EXCEPTION '% movement must be negative', p_transaction_type;\n  END IF;\n  IF p_transaction_type = 'delivery_challan'\n     AND v_batch.expiry_date IS NOT NULL\n     AND v_batch.expiry_date <= COALESCE(p_transaction_date, CURRENT_DATE) THEN\n    RAISE EXCEPTION 'Expired batch % cannot be delivered (expiry %)',\n      v_batch.batch_number, v_batch.expiry_date;\n  END IF;\n  IF p_transaction_type = 'purchase'\n     AND EXISTS (\n       SELECT 1\n       FROM public.inventory_transactions it\n       WHERE it.batch_id = p_batch_id\n         AND it.transaction_type = 'purchase'\n     ) THEN\n    RAISE EXCEPTION 'Batch % already has a Batch Creation movement',\n      v_batch.batch_number;\n  END IF;\n\n  v_new_stock := v_batch.current_stock + p_quantity;\n  IF v_new_stock < 0 THEN\n    RAISE EXCEPTION 'Insufficient stock in batch %: current %, movement %, result %',\n      v_batch.batch_number, v_batch.current_stock, p_quantity, v_new_stock;\n  END IF;\n\n  IF p_stock_before IS NOT NULL\n     AND p_stock_before IS DISTINCT FROM v_batch.current_stock THEN\n    RAISE EXCEPTION 'Stale stock_before for batch %: expected %, received %',\n      v_batch.batch_number, v_batch.current_stock, p_stock_before;\n  END IF;\n  IF p_stock_after IS NOT NULL\n     AND p_stock_after IS DISTINCT FROM v_new_stock THEN\n    RAISE EXCEPTION 'Invalid stock_after for batch %: expected %, received %',\n      v_batch.batch_number, v_new_stock, p_stock_after;\n  END IF;\n\n  v_previous_context := current_setting('app.canonical_stock_engine', true);\n  PERFORM set_config('app.canonical_stock_engine', 'on', true);\n\n  UPDATE public.batches\n  SET current_stock = v_new_stock,\n      updated_at = now()\n  WHERE id = p_batch_id;\n\n  INSERT INTO public.inventory_transactions (\n    operation_id,\n    product_id,\n    batch_id,\n    transaction_type,\n    quantity,\n    transaction_date,\n    reference_number,\n    reference_type,\n    reference_id,\n    notes,\n    created_by,\n    stock_before,\n    stock_after,\n    metadata\n  )\n  VALUES (\n    p_operation_id,\n    p_product_id,\n    p_batch_id,\n    p_transaction_type,\n    p_quantity,\n    COALESCE(p_transaction_date, CURRENT_DATE),\n    p_reference_number,\n    p_reference_type,\n    p_reference_id,\n    p_notes,\n    v_creator,\n    v_batch.current_stock,\n    v_new_stock,\n    jsonb_build_object(\n      'canonical_engine_version', '1.0',\n      'canonical_posted_at', clock_timestamp()\n    )\n  )\n  RETURNING id INTO v_transaction_id;\n\n  PERFORM set_config(\n    'app.canonical_stock_engine',\n    COALESCE(v_previous_context, ''),\n    true\n  );\n\n  RETURN v_transaction_id;\nEND;\n$$","-- 11. save_purchase_invoice_with_receiving_details (role authorization check)\nCREATE OR REPLACE FUNCTION public.save_purchase_invoice_with_receiving_details(p_invoice_id uuid, p_purchase_order_id uuid, p_invoice_data jsonb, p_items jsonb)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_data jsonb := coalesce(p_invoice_data, '{}'::jsonb);\n  v_items jsonb := '[]'::jsonb;\n  v_item jsonb;\n  v_old public.purchase_invoice_items%rowtype;\n  v_po uuid;\n  v_result jsonb;\n  v_id uuid;\n  v_rate numeric;\n  v_ccy text;\nBEGIN\n  IF auth.role() <> 'service_role' THEN\n    IF auth.uid() IS NULL THEN\n      RAISE EXCEPTION 'Not authenticated';\n    END IF;\n    IF NOT EXISTS (\n      SELECT 1 FROM public.user_profiles\n      WHERE id = auth.uid()\n        AND is_active = true\n        AND role IN ('admin', 'accounts', 'warehouse')\n    ) THEN\n      RAISE EXCEPTION 'Permission denied for purchase invoice receiving';\n    END IF;\n  END IF;\n\n  IF p_invoice_id IS NOT NULL AND nullif(v_data->>'purchase_order_id', '') IS NULL THEN\n    SELECT purchase_order_id INTO v_po FROM purchase_invoices WHERE id = p_invoice_id;\n    IF v_po IS NOT NULL THEN v_data := jsonb_set(v_data, '{purchase_order_id}', to_jsonb(v_po), true); END IF;\n  ELSIF p_invoice_id IS NULL AND p_purchase_order_id IS NOT NULL AND nullif(v_data->>'purchase_order_id', '') IS NULL THEN\n    v_data := jsonb_set(v_data, '{purchase_order_id}', to_jsonb(p_purchase_order_id), true);\n  END IF;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) LOOP\n    IF p_invoice_id IS NOT NULL AND nullif(v_item->>'id', '') IS NOT NULL THEN\n      SELECT * INTO v_old FROM purchase_invoice_items WHERE id = (v_item->>'id')::uuid AND purchase_invoice_id = p_invoice_id;\n      IF FOUND THEN\n        IF nullif(v_item->>'purchase_order_item_id', '') IS NULL AND v_old.purchase_order_item_id IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{purchase_order_item_id}', to_jsonb(v_old.purchase_order_item_id), true);\n        END IF;\n        IF nullif(v_item->>'receiving_make_id', '') IS NULL AND v_old.receiving_make_id IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{receiving_make_id}', to_jsonb(v_old.receiving_make_id), true);\n        END IF;\n        IF nullif(v_item->>'receiving_batch_number', '') IS NULL AND v_old.receiving_batch_number IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{receiving_batch_number}', to_jsonb(v_old.receiving_batch_number), true);\n        END IF;\n        IF nullif(v_item->>'receiving_expiry_date', '') IS NULL AND v_old.receiving_expiry_date IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{receiving_expiry_date}', to_jsonb(v_old.receiving_expiry_date), true);\n        END IF;\n        IF nullif(v_item->>'receiving_import_container_id', '') IS NULL AND v_old.receiving_import_container_id IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{receiving_import_container_id}', to_jsonb(v_old.receiving_import_container_id), true);\n        END IF;\n        IF nullif(v_item->>'receiving_notes', '') IS NULL AND v_old.receiving_notes IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{receiving_notes}', to_jsonb(v_old.receiving_notes), true);\n        END IF;\n      END IF;\n    END IF;\n    v_items := v_items || jsonb_build_array(v_item);\n  END LOOP;\n\n  v_result := CASE\n    WHEN p_invoice_id IS NOT NULL THEN save_purchase_invoice(p_invoice_id, v_data, v_items)\n    WHEN p_purchase_order_id IS NOT NULL THEN create_purchase_invoice_from_po(p_purchase_order_id, v_data, v_items)\n    ELSE save_purchase_invoice(NULL, v_data, v_items)\n  END;\n\n  v_id := (v_result->>'invoice_id')::uuid;\n  SELECT upper(currency), exchange_rate INTO v_ccy, v_rate FROM purchase_invoices WHERE id = v_id;\n  RETURN v_result;\nEND;\n$$"}	harden_identity_and_finance_rpcs	\N	\N	\N
20261007112109	{"UPDATE public.import_data SET date = make_date(2000 + EXTRACT(DAY FROM (date - INTERVAL '27 days'))::int, EXTRACT(MONTH FROM (date - INTERVAL '27 days'))::int, EXTRACT(YEAR FROM (date - INTERVAL '27 days'))::int - 2000) WHERE created_at >= '2026-10-07 11:13:19+00' AND created_at <= '2026-10-07 11:13:41+00';"}	fix_import_dates_year_day_swap_20261007	simplykool@gmail.com	\N	\N
20260918010000	{"-- ============================================================================\n-- HARDEN RECEIPT VOUCHER DATABASE SECURITY, AUTHORIZATION & IMPERSONATION CHECKS\n-- Migration: 20260918010000_harden_receipt_voucher_security.sql\n-- ============================================================================\n\n-- 1. save_receipt_voucher_with_allocations\n-- Hardened: Role check, pg_temp search path, strict auth.uid() enforcement for created_by\nCREATE OR REPLACE FUNCTION public.save_receipt_voucher_with_allocations(\n  p_receipt_id uuid DEFAULT NULL::uuid,\n  p_payload jsonb DEFAULT '{}'::jsonb,\n  p_allocations jsonb DEFAULT '[]'::jsonb\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_id uuid;\n  v_alloc jsonb;\n  v_bank_currency text;\n  v_currency text;\n  v_rate numeric;\n  v_actor uuid;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actor := auth.uid();\n\n  IF NULLIF(p_payload->>'customer_id','') IS NULL THEN\n    RAISE EXCEPTION 'Customer is required';\n  END IF;\n\n  IF COALESCE((p_payload->>'amount')::numeric, 0) <= 0 THEN\n    RAISE EXCEPTION 'Receipt amount must be greater than zero';\n  END IF;\n\n  SELECT upper(currency) INTO v_bank_currency\n  FROM public.bank_accounts\n  WHERE id = NULLIF(p_payload->>'bank_account_id','')::uuid;\n\n  v_currency := upper(COALESCE(NULLIF(p_payload->>'transaction_currency',''), v_bank_currency, 'IDR'));\n  v_rate := COALESCE(NULLIF((p_payload->>'exchange_rate')::numeric, 0), CASE WHEN v_currency='IDR' THEN 1 ELSE NULL END);\n\n  IF v_rate IS NULL OR v_rate <= 0 OR (v_currency = 'USD' AND v_rate <= 1) THEN\n    RAISE EXCEPTION 'A valid exchange rate is required for % receipts', v_currency;\n  END IF;\n\n  IF v_bank_currency IS NOT NULL AND v_bank_currency <> v_currency THEN\n    RAISE EXCEPTION 'Receipt currency % does not match selected bank currency %', v_currency, v_bank_currency;\n  END IF;\n\n  IF p_receipt_id IS NULL THEN\n    INSERT INTO public.receipt_vouchers(\n      voucher_number,\n      voucher_date,\n      customer_id,\n      payment_method,\n      bank_account_id,\n      reference_number,\n      amount,\n      description,\n      created_by,\n      currency_code,\n      transaction_currency,\n      functional_currency,\n      exchange_rate,\n      bank_account_currency,\n      payment_currency\n    ) VALUES (\n      public.next_receipt_voucher_number((p_payload->>'voucher_date')::date),\n      (p_payload->>'voucher_date')::date,\n      (p_payload->>'customer_id')::uuid,\n      p_payload->>'payment_method',\n      NULLIF(p_payload->>'bank_account_id','')::uuid,\n      NULLIF(p_payload->>'reference_number',''),\n      (p_payload->>'amount')::numeric,\n      NULLIF(p_payload->>'description',''),\n      v_actor, -- Enforce actual authenticated caller identity\n      v_currency,\n      v_currency,\n      'IDR',\n      v_rate,\n      COALESCE(v_bank_currency, v_currency),\n      v_currency\n    ) RETURNING id INTO v_id;\n  ELSE\n    IF EXISTS (SELECT 1 FROM public.receipt_vouchers WHERE id = p_receipt_id AND is_posted = true) THEN\n      RAISE EXCEPTION 'Cannot edit a posted receipt voucher. Cancel posting first.';\n    END IF;\n\n    UPDATE public.receipt_vouchers SET\n      voucher_date          = (p_payload->>'voucher_date')::date,\n      customer_id           = (p_payload->>'customer_id')::uuid,\n      payment_method        = p_payload->>'payment_method',\n      bank_account_id       = NULLIF(p_payload->>'bank_account_id','')::uuid,\n      reference_number      = NULLIF(p_payload->>'reference_number',''),\n      amount                = (p_payload->>'amount')::numeric,\n      description           = NULLIF(p_payload->>'description',''),\n      currency_code         = v_currency,\n      transaction_currency  = v_currency,\n      functional_currency   = 'IDR',\n      exchange_rate         = v_rate,\n      bank_account_currency = COALESCE(v_bank_currency, v_currency),\n      payment_currency      = v_currency,\n      updated_at            = now()\n    WHERE id = p_receipt_id\n    RETURNING id INTO v_id;\n\n    DELETE FROM public.voucher_allocations WHERE receipt_voucher_id = v_id;\n  END IF;\n\n  FOR v_alloc IN SELECT value FROM jsonb_array_elements(COALESCE(p_allocations,'[]'::jsonb)) LOOP\n    IF COALESCE((v_alloc->>'amount')::numeric, 0) > 0 THEN\n      INSERT INTO public.voucher_allocations(\n        voucher_type,\n        receipt_voucher_id,\n        sales_invoice_id,\n        sales_order_id,\n        allocated_amount\n      ) VALUES (\n        'receipt',\n        v_id,\n        NULLIF(v_alloc->>'sales_invoice_id','')::uuid,\n        NULLIF(v_alloc->>'sales_order_id','')::uuid,\n        (v_alloc->>'amount')::numeric\n      );\n    END IF;\n  END LOOP;\n\n  RETURN v_id;\nEND;\n$$","-- 2. cancel_receipt_voucher_posting\n-- Hardened: Role check, pg_temp search path, strict auth.uid() enforcement for cancelled_by\nCREATE OR REPLACE FUNCTION public.cancel_receipt_voucher_posting(\n  p_rv_id uuid,\n  p_cancelled_by uuid DEFAULT NULL::uuid,\n  p_reason text DEFAULT 'Posting cancelled by administrator'::text\n)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_rv RECORD;\n  v_je RECORD;\n  v_actor uuid;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actor := auth.uid();\n\n  SELECT * INTO v_rv FROM receipt_vouchers WHERE id = p_rv_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id;\n  END IF;\n\n  IF NOT v_rv.is_posted THEN\n    RAISE EXCEPTION 'Receipt voucher % is not posted', COALESCE(v_rv.voucher_number, p_rv_id::TEXT);\n  END IF;\n\n  SELECT * INTO v_je FROM journal_entries WHERE id = v_rv.journal_entry_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'No journal entry found for receipt voucher %', v_rv.voucher_number;\n  END IF;\n\n  -- Clear the FK reference FIRST so cancel_gl_posting can delete the JE row.\n  UPDATE receipt_vouchers\n  SET is_posted = FALSE, journal_entry_id = NULL\n  WHERE id = p_rv_id;\n\n  PERFORM cancel_gl_posting(\n    v_je.id,\n    p_rv_id,\n    'receipt_vouchers',\n    v_actor,\n    p_reason,\n    jsonb_build_object(\n      'voucher_number', v_rv.voucher_number,\n      'amount',         v_rv.amount,\n      'is_posted',      TRUE\n    )\n  );\nEND;\n$$","-- 3. next_receipt_voucher_number (Hardened search_path)\nCREATE OR REPLACE FUNCTION public.next_receipt_voucher_number(p_voucher_date date)\nRETURNS text\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_prefix text;\n  v_next int;\nBEGIN\n  IF p_voucher_date IS NULL THEN\n    RAISE EXCEPTION 'Voucher date is required';\n  END IF;\n  v_prefix := 'RV' || to_char(p_voucher_date, 'YYMM') || '-';\n  PERFORM pg_advisory_xact_lock(hashtext('receipt_voucher_' || v_prefix));\n  SELECT COALESCE(MAX((regexp_match(voucher_number, '-([0-9]+)$'))[1]::int), 0) + 1\n    INTO v_next\n    FROM public.receipt_vouchers\n   WHERE voucher_number LIKE v_prefix || '%';\n  RETURN v_prefix || lpad(v_next::text, 4, '0');\nEND;\n$$","-- 4. delete_receipt_voucher_journal trigger function (Hardened search_path)\nCREATE OR REPLACE FUNCTION public.delete_receipt_voucher_journal()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_je_ids uuid[];\nBEGIN\n  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])\n    INTO v_je_ids\n    FROM public.journal_entries\n   WHERE source_module = 'receipt'\n     AND (reference_id = OLD.id\n          OR (OLD.journal_entry_id IS NOT NULL AND id = OLD.journal_entry_id));\n\n  IF array_length(v_je_ids, 1) IS NULL THEN\n    RETURN OLD;\n  END IF;\n\n  UPDATE public.bank_statement_lines\n     SET matched_entry_id      = NULL,\n         reconciliation_status = 'unmatched',\n         matched_at            = NULL\n   WHERE matched_entry_id = ANY (v_je_ids);\n\n  DELETE FROM public.journal_entry_lines WHERE journal_entry_id = ANY (v_je_ids);\n  DELETE FROM public.journal_entries     WHERE id = ANY (v_je_ids);\n\n  RETURN OLD;\nEND;\n$$","-- 5. update_so_advance_status trigger function (Hardened search_path)\nCREATE OR REPLACE FUNCTION public.update_so_advance_status()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_sales_order_id UUID;\n  v_total_advance DECIMAL(18,2);\n  v_order_total DECIMAL(18,2);\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    v_sales_order_id := OLD.sales_order_id;\n  ELSE\n    v_sales_order_id := NEW.sales_order_id;\n  END IF;\n\n  IF v_sales_order_id IS NULL THEN\n    RETURN COALESCE(NEW, OLD);\n  END IF;\n\n  SELECT COALESCE(SUM(va.allocated_amount), 0)\n    INTO v_total_advance\n    FROM public.voucher_allocations va\n   WHERE va.sales_order_id = v_sales_order_id\n     AND va.voucher_type = 'receipt';\n\n  SELECT total_amount INTO v_order_total\n    FROM public.sales_orders\n   WHERE id = v_sales_order_id;\n\n  UPDATE public.sales_orders\n  SET \n    advance_payment_amount = v_total_advance,\n    advance_payment_status = CASE\n      WHEN v_total_advance = 0 THEN 'none'\n      WHEN v_total_advance >= v_order_total THEN 'full'\n      ELSE 'partial'\n    END,\n    updated_at = now()\n  WHERE id = v_sales_order_id;\n\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$","-- 6. get_reporting_usd_rate (Hardened search_path)\nCREATE OR REPLACE FUNCTION public.get_reporting_usd_rate()\nRETURNS numeric\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  RETURN (\n    SELECT COALESCE(\n      (SELECT exchange_rate FROM public.payment_vouchers\n       WHERE exchange_rate > 1.5\n       ORDER BY voucher_date DESC, created_at DESC LIMIT 1),\n      (SELECT exchange_rate FROM public.purchase_invoices\n       WHERE currency = 'USD' AND exchange_rate > 1.5\n       ORDER BY invoice_date DESC LIMIT 1),\n      (SELECT exchange_rate_usd_to_idr FROM public.batches\n       WHERE exchange_rate_usd_to_idr > 1.5\n       ORDER BY created_at DESC LIMIT 1),\n      16000::NUMERIC\n    )\n  );\nEND;\n$$","-- 7. Clean up overly broad legacy permissive RLS policies\nDROP POLICY IF EXISTS \\"Authenticated users can manage receipt vouchers\\" ON public.receipt_vouchers","DROP POLICY IF EXISTS \\"Authenticated users can manage voucher allocations\\" ON public.voucher_allocations","DROP POLICY IF EXISTS \\"admin_accounts_manage_receipt_vouchers\\" ON public.receipt_vouchers","DROP POLICY IF EXISTS \\"admin_accounts_manage_voucher_allocations\\" ON public.voucher_allocations","DROP POLICY IF EXISTS \\"authorized_read_receipt_vouchers\\" ON public.receipt_vouchers","DROP POLICY IF EXISTS \\"authorized_read_voucher_allocations\\" ON public.voucher_allocations","-- Recreate clean table-level RLS policies strictly guarding write operations to finance roles\nCREATE POLICY \\"admin_accounts_manage_receipt_vouchers\\" ON public.receipt_vouchers\n  FOR ALL TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles\n      WHERE id = auth.uid()\n        AND role IN ('admin', 'accounts')\n        AND is_active = true\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles\n      WHERE id = auth.uid()\n        AND role IN ('admin', 'accounts')\n        AND is_active = true\n    )\n  )","CREATE POLICY \\"admin_accounts_manage_voucher_allocations\\" ON public.voucher_allocations\n  FOR ALL TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles\n      WHERE id = auth.uid()\n        AND role IN ('admin', 'accounts')\n        AND is_active = true\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles\n      WHERE id = auth.uid()\n        AND role IN ('admin', 'accounts')\n        AND is_active = true\n    )\n  )","-- Read policy for auditor and sales reference if needed\nCREATE POLICY \\"authorized_read_receipt_vouchers\\" ON public.receipt_vouchers\n  FOR SELECT TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles\n      WHERE id = auth.uid()\n        AND is_active = true\n        AND role IN ('admin', 'accounts', 'auditor_ca', 'sales')\n    )\n  )","CREATE POLICY \\"authorized_read_voucher_allocations\\" ON public.voucher_allocations\n  FOR SELECT TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles\n      WHERE id = auth.uid()\n        AND is_active = true\n        AND role IN ('admin', 'accounts', 'auditor_ca', 'sales')\n    )\n  )","-- 8. Explicit revoke and grant controls on all Receipt Voucher functions\nREVOKE ALL ON FUNCTION public.save_receipt_voucher_with_allocations(uuid, jsonb, jsonb) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.save_receipt_voucher_with_allocations(uuid, jsonb, jsonb) TO authenticated","REVOKE ALL ON FUNCTION public.cancel_receipt_voucher_posting(uuid, uuid, text) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.cancel_receipt_voucher_posting(uuid, uuid, text) TO authenticated","REVOKE ALL ON FUNCTION public.post_receipt_voucher(uuid, uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.post_receipt_voucher(uuid, uuid) TO authenticated","REVOKE ALL ON FUNCTION public.next_receipt_voucher_number(date) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.next_receipt_voucher_number(date) TO authenticated","REVOKE ALL ON FUNCTION public.get_reporting_usd_rate() FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.get_reporting_usd_rate() TO authenticated"}	harden_receipt_voucher_security	\N	\N	\N
20260918020000	{"-- ============================================================================\n-- AUDIT AND HARDEN REMAINING ANON SECURITY DEFINER FUNCTIONS\n-- Migration: 20260918020000_harden_anon_functions.sql\n-- ============================================================================\n\n-- 1. is_setup_mode\n-- Harden search_path, keep for authenticated/service_role, REVOKE from anon.\n-- Unauthenticated users have no legitimate need to inspect database setup mode state.\nCREATE OR REPLACE FUNCTION public.is_setup_mode()\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\n  SELECT COALESCE((SELECT setup_mode FROM public.app_settings LIMIT 1), false);\n$$","REVOKE ALL ON FUNCTION public.is_setup_mode() FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.is_setup_mode() TO authenticated, service_role","-- 2. lookup_login_email\n-- Hardened: sanitized input, STABLE attribute, search_path = public, pg_temp.\n-- Genuinely required by unauthenticated (anon) callers to support username-based login\n-- before passing resolved credentials to supabase.auth.signInWithPassword.\nCREATE OR REPLACE FUNCTION public.lookup_login_email(p_username text)\nRETURNS TABLE(email text, is_active boolean)\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_clean_username text := lower(trim(COALESCE(p_username, '')));\nBEGIN\n  -- Fast return on empty input to avoid table scan\n  IF v_clean_username = '' THEN\n    RETURN;\n  END IF;\n\n  RETURN QUERY\n  SELECT up.email, up.is_active\n  FROM public.user_profiles up\n  WHERE lower(trim(up.username)) = v_clean_username\n  LIMIT 1;\nEND;\n$$","REVOKE ALL ON FUNCTION public.lookup_login_email(text) FROM PUBLIC","GRANT EXECUTE ON FUNCTION public.lookup_login_email(text) TO anon, authenticated, service_role"}	harden_anon_functions	\N	\N	\N
20260918030000	{"-- ============================================================================\n-- FINAL AUTHORIZATION, ROLE HARDENING & COST LAYER POLICY AUDIT\n-- Migration: 20260918030000_final_authorization_and_cost_layer_audit.sql\n-- ============================================================================\n\n-- 1. purchase_batch_cost_layers Final RLS Policy\n-- Strictly restricted to finance/auditing roles: admin, accounts, auditor_ca.\n-- Disallows unauthorized visibility by sales or warehouse roles.\nALTER TABLE public.purchase_batch_cost_layers ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS \\"purchase_batch_cost_layers_select\\" ON public.purchase_batch_cost_layers","DROP POLICY IF EXISTS purchase_batch_cost_layers_select ON public.purchase_batch_cost_layers","CREATE POLICY \\"purchase_batch_cost_layers_select\\" ON public.purchase_batch_cost_layers\n  FOR SELECT TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.user_profiles up\n      WHERE up.id = auth.uid()\n        AND up.is_active = true\n        AND up.role = ANY (ARRAY['admin'::text, 'accounts'::text, 'auditor_ca'::text])\n    )\n  )","-- 2. inventory_v1_actor_allowed\n-- Hardened: Checks is_active = true and uses fixed search_path = public, pg_temp.\nCREATE OR REPLACE FUNCTION public.inventory_v1_actor_allowed(p_roles text[])\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\n  SELECT\n    auth.role() = 'service_role'\n    OR EXISTS (\n      SELECT 1\n      FROM public.user_profiles up\n      WHERE up.id = auth.uid()\n        AND up.is_active = true\n        AND up.role = ANY(p_roles)\n    );\n$$","-- 3. Ensure all targeted views maintain security_invoker = true\nALTER VIEW public.customer_receivables_view SET (security_invoker = true)","ALTER VIEW public.finance_live_verification_failures SET (security_invoker = true)","ALTER VIEW public.inventory_v1_stock_summary SET (security_invoker = true)","ALTER VIEW public.sales_invoice_item_integrity SET (security_invoker = true)","ALTER VIEW public.so_product_reservation_status SET (security_invoker = true)","ALTER VIEW public.supplier_payables_view SET (security_invoker = true)","ALTER VIEW public.vw_bank_ledger_effective SET (security_invoker = true)","ALTER VIEW public.vw_bank_ledger_monthly_reconciliation SET (security_invoker = true)"}	final_authorization_and_cost_layer_audit	\N	\N	\N
20261008111122	{"-- Migration: 20261008040000_nota_retur_coretax_workflow.sql\n-- Description: Implement Indonesian Nota Retur (Tax Return Note) schema, Coretax compliance fields,\n--              linkages with Material Returns, Credit Notes, Sales Invoices, and PPN period integration.\n\nBEGIN;\n\n-- ============================================================================\n-- 1. NOTA RETUR SEQUENCE\n-- ============================================================================\nCREATE SEQUENCE IF NOT EXISTS public.nota_retur_number_seq\n  START WITH 1\n  INCREMENT BY 1\n  NO MINVALUE\n  NO MAXVALUE\n  CACHE 1;\n\n-- ============================================================================\n-- 2. CREATE NOTA_RETUR TABLE\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS public.nota_retur (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  nota_retur_number TEXT NOT NULL UNIQUE,\n  return_date DATE NOT NULL DEFAULT CURRENT_DATE,\n  material_return_id UUID REFERENCES public.material_returns(id) ON DELETE SET NULL,\n  credit_note_id UUID REFERENCES public.credit_notes(id) ON DELETE SET NULL,\n  sales_invoice_id UUID NOT NULL REFERENCES public.sales_invoices(id) ON DELETE RESTRICT,\n  original_invoice_number TEXT NOT NULL,\n  sales_invoice_number TEXT,\n  original_faktur_pajak_number TEXT,\n  original_faktur_pajak_date DATE,\n  customer_id UUID NOT NULL REFERENCES public.customers(id) ON DELETE RESTRICT,\n  customer_name TEXT NOT NULL,\n  customer_npwp TEXT,\n  customer_address TEXT,\n  seller_name TEXT NOT NULL DEFAULT 'PT. Sinar Anzen Prima Jaya',\n  seller_npwp TEXT DEFAULT '00.000.000.0-000.000',\n  seller_address TEXT,\n  currency TEXT NOT NULL DEFAULT 'IDR',\n  dpp_amount NUMERIC(15,2) NOT NULL DEFAULT 0,\n  tax_rate NUMERIC(5,4) NOT NULL DEFAULT 0.1100 CHECK (tax_rate >= 0 AND tax_rate <= 1),\n  ppn_amount NUMERIC(15,2) NOT NULL DEFAULT 0,\n  total_amount NUMERIC(15,2) NOT NULL DEFAULT 0,\n  tax_period_id UUID REFERENCES public.tax_periods(id) ON DELETE SET NULL,\n  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'ready_for_review', 'submitted', 'approved', 'rejected', 'cancelled')),\n  coretax_status TEXT NOT NULL DEFAULT 'draft' CHECK (coretax_status IN ('draft', 'ready_for_review', 'submitted', 'approved', 'rejected')),\n  coretax_reference_number TEXT,\n  coretax_submission_date TIMESTAMPTZ,\n  coretax_response_notes TEXT,\n  approved_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,\n  approved_at TIMESTAMPTZ,\n  approval_date TIMESTAMPTZ,\n  rejection_reason TEXT,\n  notes TEXT,\n  document_url TEXT,\n  company_snapshot JSONB,\n  created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Index for fast lookup by sales_invoice_id, customer_id, tax_period_id\nCREATE INDEX IF NOT EXISTS idx_nota_retur_sales_invoice_id ON public.nota_retur(sales_invoice_id);\nCREATE INDEX IF NOT EXISTS idx_nota_retur_customer_id ON public.nota_retur(customer_id);\nCREATE INDEX IF NOT EXISTS idx_nota_retur_tax_period_id ON public.nota_retur(tax_period_id);\nCREATE INDEX IF NOT EXISTS idx_nota_retur_material_return_id ON public.nota_retur(material_return_id);\nCREATE INDEX IF NOT EXISTS idx_nota_retur_credit_note_id ON public.nota_retur(credit_note_id);\nCREATE INDEX IF NOT EXISTS idx_nota_retur_status ON public.nota_retur(status);\nCREATE INDEX IF NOT EXISTS idx_nota_retur_date ON public.nota_retur(return_date);\n\n-- Enforce rule: only 1 active Nota Retur per Material Return (prevent duplicate tax claims)\nCREATE UNIQUE INDEX IF NOT EXISTS uq_nota_retur_material_return_active\nON public.nota_retur(material_return_id)\nWHERE material_return_id IS NOT NULL AND status NOT IN ('cancelled', 'rejected');\n\n-- ============================================================================\n-- 3. CREATE NOTA_RETUR_ITEMS TABLE\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS public.nota_retur_items (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  nota_retur_id UUID NOT NULL REFERENCES public.nota_retur(id) ON DELETE CASCADE,\n  product_id UUID NOT NULL REFERENCES public.products(id) ON DELETE RESTRICT,\n  batch_id UUID REFERENCES public.batches(id) ON DELETE SET NULL,\n  material_return_item_id UUID REFERENCES public.material_return_items(id) ON DELETE SET NULL,\n  item_name TEXT NOT NULL,\n  quantity NUMERIC(12,3) NOT NULL CHECK (quantity > 0),\n  unit_of_measure TEXT NOT NULL DEFAULT 'kg',\n  unit_price NUMERIC(15,2) NOT NULL CHECK (unit_price >= 0),\n  dpp_amount NUMERIC(15,2) NOT NULL DEFAULT 0,\n  tax_rate NUMERIC(5,2) NOT NULL DEFAULT 11.00,\n  ppn_amount NUMERIC(15,2) NOT NULL DEFAULT 0,\n  total_amount NUMERIC(15,2) NOT NULL DEFAULT 0,\n  notes TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_nota_retur_items_nota_retur_id ON public.nota_retur_items(nota_retur_id);\nCREATE INDEX IF NOT EXISTS idx_nota_retur_items_product_id ON public.nota_retur_items(product_id);\n\n-- ============================================================================\n-- 4. ADD LINKAGE COLUMNS TO MATERIAL_RETURNS & CREDIT_NOTES\n-- ============================================================================\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns \n    WHERE table_name = 'material_returns' AND column_name = 'nota_retur_id'\n  ) THEN\n    ALTER TABLE public.material_returns ADD COLUMN nota_retur_id UUID REFERENCES public.nota_retur(id) ON DELETE SET NULL;\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns \n    WHERE table_name = 'credit_notes' AND column_name = 'nota_retur_id'\n  ) THEN\n    ALTER TABLE public.credit_notes ADD COLUMN nota_retur_id UUID REFERENCES public.nota_retur(id) ON DELETE SET NULL;\n  END IF;\nEND $$;\n\n-- ============================================================================\n-- 5. FUNCTION: GENERATE NOTA RETUR NUMBER\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.generate_nota_retur_number(p_date DATE DEFAULT CURRENT_DATE)\nRETURNS TEXT\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_year TEXT;\n  v_month TEXT;\n  v_seq INTEGER;\n  v_number TEXT;\nBEGIN\n  v_year := to_char(p_date, 'YYYY');\n  v_month := to_char(p_date, 'MM');\n  v_seq := nextval('public.nota_retur_number_seq');\n  v_number := 'NR/' || v_year || '/' || v_month || '/' || lpad(v_seq::text, 4, '0');\n  RETURN v_number;\nEND;\n$$;\n\nALTER TABLE public.nota_retur\n  ALTER COLUMN nota_retur_number SET DEFAULT public.generate_nota_retur_number();\n\n-- ============================================================================\n-- 6. BIDIRECTIONAL SYNC TRIGGER BETWEEN NOTA_RETUR AND MATERIAL_RETURNS/CREDIT_NOTES\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.trg_sync_nota_retur_linkages()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nBEGIN\n  -- Sync link to material_returns if present\n  IF NEW.material_return_id IS NOT NULL THEN\n    UPDATE public.material_returns\n    SET nota_retur_id = NEW.id\n    WHERE id = NEW.material_return_id;\n  END IF;\n\n  -- Sync link to credit_notes if present\n  IF NEW.credit_note_id IS NOT NULL THEN\n    UPDATE public.credit_notes\n    SET nota_retur_id = NEW.id\n    WHERE id = NEW.credit_note_id;\n  END IF;\n\n  -- If status changed to cancelled or rejected, unlink from material return if appropriate\n  IF NEW.status IN ('cancelled', 'rejected') AND OLD.status NOT IN ('cancelled', 'rejected') THEN\n    IF NEW.material_return_id IS NOT NULL THEN\n      UPDATE public.material_returns\n      SET nota_retur_id = NULL\n      WHERE id = NEW.material_return_id AND nota_retur_id = NEW.id;\n    END IF;\n    IF NEW.credit_note_id IS NOT NULL THEN\n      UPDATE public.credit_notes\n      SET nota_retur_id = NULL\n      WHERE id = NEW.credit_note_id AND nota_retur_id = NEW.id;\n    END IF;\n  END IF;\n\n  -- Trigger tax period PPN recalculation if tax_period_id is set\n  IF NEW.tax_period_id IS NOT NULL THEN\n    PERFORM public.compute_period_ppn(NEW.tax_period_id);\n  END IF;\n  IF OLD.tax_period_id IS NOT NULL AND OLD.tax_period_id IS DISTINCT FROM NEW.tax_period_id THEN\n    PERFORM public.compute_period_ppn(OLD.tax_period_id);\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS trg_nota_retur_linkages ON public.nota_retur;\nCREATE TRIGGER trg_nota_retur_linkages\nAFTER INSERT OR UPDATE ON public.nota_retur\nFOR EACH ROW EXECUTE FUNCTION public.trg_sync_nota_retur_linkages();\n\n-- ============================================================================\n-- 7. REFRESH COMPUTE_PERIOD_PPN_PRE_POSTED_REGISTER TO INCLUDE NOTA RETUR\n-- ============================================================================\nCREATE OR REPLACE FUNCTION public.compute_period_ppn_pre_posted_register(p_period_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  v_period       tax_periods%ROWTYPE;\n  v_input        numeric(18,2);\n  v_output_gross numeric(18,2);\n  v_output_nr    numeric(18,2);\n  v_output_cn    numeric(18,2);\n  v_output       numeric(18,2);\n  v_prior_cf     numeric(18,2);\nBEGIN\n  SELECT * INTO v_period FROM tax_periods WHERE id = p_period_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Tax period % not found', p_period_id;\n  END IF;\n\n  IF v_period.tax_type = 'PPN' THEN\n    -- Input PPN sum\n    SELECT\n      COALESCE((\n        SELECT SUM(tax_amount) FROM purchase_invoices\n         WHERE tax_period_id = p_period_id AND tax_amount > 0\n      ), 0)\n      +\n      COALESCE((\n        SELECT SUM(fe.ppn_amount)\n          FROM finance_expenses fe\n         WHERE fe.tax_period_id = p_period_id\n           AND fe.ppn_amount > 0\n           AND NOT EXISTS (\n             SELECT 1\n               FROM jsonb_array_elements(COALESCE(fe.broker_items, '[]'::jsonb)) item\n              WHERE COALESCE((item->>'ppn_amount')::numeric, 0) > 0\n           )\n      ), 0)\n      +\n      COALESCE((\n        SELECT SUM(COALESCE((item->>'ppn_amount')::numeric, 0))\n          FROM finance_expenses fe\n          CROSS JOIN LATERAL jsonb_array_elements(COALESCE(fe.broker_items, '[]'::jsonb)) item\n         WHERE fe.tax_period_id = p_period_id\n           AND COALESCE((item->>'ppn_amount')::numeric, 0) > 0\n      ), 0)\n      +\n      COALESCE((\n        SELECT SUM(pib_ppn_amount) FROM finance_expenses\n         WHERE tax_period_id = p_period_id AND pib_ppn_amount > 0\n      ), 0)\n    INTO v_input;\n\n    -- Output PPN Gross from Sales Invoices\n    SELECT COALESCE(SUM(tax_amount), 0) INTO v_output_gross\n      FROM sales_invoices\n     WHERE tax_period_id = p_period_id AND tax_amount > 0;\n\n    -- Approved Nota Retur assigned to this tax period (tax instrument for return)\n    SELECT COALESCE(SUM(ppn_amount), 0) INTO v_output_nr\n      FROM public.nota_retur\n     WHERE tax_period_id = p_period_id\n       AND status = 'approved'\n       AND ppn_amount > 0;\n\n    -- Approved Credit Notes that are NOT already represented by an approved Nota Retur in this period\n    -- (Prevents double counting between commercial CN and tax Nota Retur)\n    SELECT COALESCE(SUM(cn.tax_amount), 0) INTO v_output_cn\n      FROM public.credit_notes cn\n     WHERE cn.tax_period_id = p_period_id\n       AND cn.status = 'approved'\n       AND cn.tax_amount > 0\n       AND NOT EXISTS (\n         SELECT 1 FROM public.nota_retur nr\n          WHERE (nr.credit_note_id = cn.id OR nr.material_return_id = cn.material_return_id)\n            AND nr.status = 'approved'\n            AND nr.tax_period_id = p_period_id\n       );\n\n    -- Net Output PPN\n    v_output := GREATEST(v_output_gross - (v_output_nr + v_output_cn), 0);\n\n    -- Prior Carry-forward\n    SELECT COALESCE(carry_forward_out, 0) INTO v_prior_cf\n      FROM tax_periods\n     WHERE tax_type = 'PPN'\n       AND (fiscal_year, period_month) < (v_period.fiscal_year, v_period.period_month)\n     ORDER BY fiscal_year DESC, period_month DESC\n     LIMIT 1;\n    v_prior_cf := COALESCE(v_prior_cf, 0);\n\n    UPDATE tax_periods SET\n      input_ppn_total   = v_input,\n      output_ppn_total  = v_output,\n      carry_forward_in  = v_prior_cf,\n      net_ppn           = GREATEST(v_output - v_input - v_prior_cf, 0),\n      carry_forward_out = GREATEST(v_input + v_prior_cf - v_output, 0),\n      updated_at        = now()\n    WHERE id = p_period_id;\n  END IF;\nEND;\n$$;\n\n-- ============================================================================\n-- 8. ROW LEVEL SECURITY & PERMISSIONS\n-- ============================================================================\nALTER TABLE public.nota_retur ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.nota_retur_items ENABLE ROW LEVEL SECURITY;\n\nDROP POLICY IF EXISTS \\"Authenticated users full access to nota_retur\\" ON public.nota_retur;\nCREATE POLICY \\"Authenticated users full access to nota_retur\\"\n  ON public.nota_retur FOR ALL\n  TO authenticated, service_role\n  USING (true)\n  WITH CHECK (true);\n\nDROP POLICY IF EXISTS \\"Authenticated users full access to nota_retur_items\\" ON public.nota_retur_items;\nCREATE POLICY \\"Authenticated users full access to nota_retur_items\\"\n  ON public.nota_retur_items FOR ALL\n  TO authenticated, service_role\n  USING (true)\n  WITH CHECK (true);\n\nGRANT ALL ON public.nota_retur TO authenticated, service_role;\nGRANT ALL ON public.nota_retur_items TO authenticated, service_role;\nGRANT USAGE, SELECT ON SEQUENCE public.nota_retur_number_seq TO authenticated, service_role;\n\nCOMMIT;\n"}	nota_retur_coretax_workflow	simplykool@gmail.com	\N	\N
20260918040000	{"-- Migration: 20260918040000_targeted_high_value_performance_optimizations.sql\n-- Description: Targeted high-value ERP performance optimizations (missing FK indexes, duplicate index cleanup, and task RLS InitPlan optimization)\n-- Security Hardening: PRESERVED (0 role changes, 0 business logic changes, 0 permission broadening)\n\n-- ============================================================================\n-- 1. HIGH-VALUE MISSING FOREIGN KEY INDEXES (CRITICAL ERP PATHS)\n-- ============================================================================\n\n-- A. dc_batch_allocations: delivery_challan_id and (batch_id, status)\nCREATE INDEX IF NOT EXISTS idx_dc_batch_allocations_dc_id \n  ON public.dc_batch_allocations (delivery_challan_id)","CREATE INDEX IF NOT EXISTS idx_dc_batch_allocations_batch_status \n  ON public.dc_batch_allocations (batch_id, status)","-- B. so_product_reservations: sales_order_id\nCREATE INDEX IF NOT EXISTS idx_so_product_reservations_so_id \n  ON public.so_product_reservations (sales_order_id)","-- C. so_product_reservation_events: sales_order_id\nCREATE INDEX IF NOT EXISTS idx_so_reservation_events_so_id \n  ON public.so_product_reservation_events (sales_order_id)","-- ============================================================================\n-- 2. REMOVE 100% IDENTICAL DUPLICATE INDEXES\n-- ============================================================================\n\n-- A. journal_entry_lines: Drop redundant duplicates, preserving idx_jel_account and idx_jel_entry\nDROP INDEX IF EXISTS public.idx_journal_entry_lines_account_id","DROP INDEX IF EXISTS public.idx_journal_entry_lines_journal_entry_id","-- B. inventory_transactions: Drop redundant duplicate, preserving idx_inventory_transactions_product\nDROP INDEX IF EXISTS public.idx_inventory_transactions_product_id","-- C. journal_entries: Drop redundant duplicate, preserving idx_je_number\nDROP INDEX IF EXISTS public.idx_journal_entries_entry_number","-- ============================================================================\n-- 3. TARGETED RLS INITPLAN OPTIMIZATION (TASKS)\n-- ============================================================================\n-- Wraps auth.uid() in (SELECT auth.uid()) so PostgreSQL evaluates the current user once per query (InitPlan)\n-- rather than per-row. Preserves 100% identical access semantics.\n\nDROP POLICY IF EXISTS \\"All authenticated users can view tasks\\" ON public.tasks","CREATE POLICY \\"All authenticated users can view tasks\\" ON public.tasks\n  FOR SELECT TO authenticated\n  USING (EXISTS (\n    SELECT 1 FROM public.user_profiles\n    WHERE user_profiles.id = (SELECT auth.uid())\n  ))"}	targeted_high_value_performance_optimizations	\N	\N	\N
20261009034934	{"-- Require explicit, reviewed advance voucher IDs before creating a salary settlement.\n-- The legacy FIFO function is retained until the new UI is deployed; new code calls this function.\nBEGIN;\n\nCREATE OR REPLACE FUNCTION public.apply_selected_salary_advances_to_expense(\n  p_salary_expense_id uuid,\n  p_advance_ids uuid[]\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_salary public.finance_expenses%ROWTYPE;\n  v_remaining numeric;\n  v_total numeric := 0;\n  v_settlement jsonb;\n  v_settlement_id uuid;\n  v_advance record;\n  v_advance_applied numeric;\n  v_available numeric;\n  v_take numeric;\n  v_currency text;\n  v_selected_ids uuid[] := ARRAY[]::uuid[];\n  v_selected_amounts numeric[] := ARRAY[]::numeric[];\n  v_selected_count integer := 0;\n  v_idx integer;\n  v_bpjs numeric := 0;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n\n  IF p_advance_ids IS NULL OR cardinality(p_advance_ids) = 0 THEN\n    RETURN jsonb_build_object('applied', false, 'total_applied', 0, 'reason', 'No advances selected');\n  END IF;\n\n  IF cardinality(p_advance_ids) <> (\n    SELECT count(DISTINCT selected_id)::integer FROM unnest(p_advance_ids) AS selected_id\n  ) THEN\n    RAISE EXCEPTION 'Duplicate advance IDs were supplied. Select each advance only once.';\n  END IF;\n\n  SELECT * INTO v_salary\n    FROM public.finance_expenses\n   WHERE id = p_salary_expense_id\n   FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Salary expense not found';\n  END IF;\n  IF v_salary.expense_category <> 'salary' OR v_salary.staff_id IS NULL THEN\n    RAISE EXCEPTION 'Salary advance settlements require a Salary expense with a selected staff member';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.salary_advance_applications\n     WHERE salary_expense_id = p_salary_expense_id\n  ) THEN\n    RAISE EXCEPTION 'This salary already has advance applications. Reverse or review the existing settlement before applying more advances.';\n  END IF;\n\n  v_currency := upper(COALESCE(v_salary.transaction_currency, v_salary.currency_code, 'IDR'));\n\n  -- Use the canonical salary calculation for the maximum deduction, but do NOT\n  -- use its auto-derived advance total: only explicitly selected IDs are eligible.\n  BEGIN\n    v_bpjs := COALESCE(\n      (public.calculate_staff_salary(v_salary.staff_id, v_salary.expense_date, v_salary.amount, v_salary.pph_amount)->>'bpjs_amount')::numeric,\n      0\n    );\n  EXCEPTION WHEN OTHERS THEN\n    v_bpjs := 0;\n  END;\n\n  v_remaining := GREATEST(v_salary.amount - COALESCE(v_salary.pph_amount, 0) - v_bpjs, 0);\n\n  FOR v_advance IN\n    SELECT pv.id, pv.voucher_number, pv.voucher_date, pv.amount\n      FROM public.payment_vouchers pv\n     WHERE pv.id = ANY(p_advance_ids)\n       AND pv.payment_purpose = 'salary_advance'\n       AND pv.is_posted = true\n       AND pv.staff_id = v_salary.staff_id\n       AND pv.voucher_date <= v_salary.expense_date\n     ORDER BY pv.voucher_date, pv.created_at, pv.id\n     FOR UPDATE OF pv\n  LOOP\n    v_selected_count := v_selected_count + 1;\n\n    IF EXISTS (\n      SELECT 1\n        FROM public.salary_advance_applications sa\n       WHERE sa.advance_payment_voucher_id = v_advance.id\n         AND sa.salary_expense_id = p_salary_expense_id\n    ) THEN\n      RAISE EXCEPTION 'Advance % is already applied to this salary', v_advance.voucher_number;\n    END IF;\n\n    SELECT COALESCE(SUM(sa.applied_amount), 0)\n      INTO v_advance_applied\n      FROM public.salary_advance_applications sa\n     WHERE sa.advance_payment_voucher_id = v_advance.id;\n\n    v_available := GREATEST(v_advance.amount - v_advance_applied, 0);\n    v_take := LEAST(v_available, GREATEST(v_remaining - v_total, 0));\n\n    IF v_take > 0 THEN\n      v_total := v_total + v_take;\n      v_selected_ids := array_append(v_selected_ids, v_advance.id);\n      v_selected_amounts := array_append(v_selected_amounts, v_take);\n    END IF;\n  END LOOP;\n\n  IF v_selected_count <> cardinality(p_advance_ids) THEN\n    RAISE EXCEPTION 'One or more selected advances are not posted, do not belong to this staff member, or are dated after the salary period. Refresh and select valid advances.';\n  END IF;\n\n  IF v_total <= 0 THEN\n    RETURN jsonb_build_object('applied', false, 'total_applied', 0, 'reason', 'Selected advances have no available balance or salary has no payable balance');\n  END IF;\n\n  v_settlement := public.save_payment_voucher_command(\n    p_voucher_id => NULL,\n    p_payload => jsonb_build_object(\n      'voucher_date', v_salary.expense_date,\n      'staff_id', v_salary.staff_id,\n      'payment_method', 'advance_adjustment',\n      'amount', v_total,\n      'payment_currency', v_currency,\n      'exchange_rate', CASE WHEN v_currency = 'IDR' THEN 1 ELSE COALESCE(v_salary.exchange_rate, 1) END,\n      'description', 'Salary Advance Recovery - ' || COALESCE(v_salary.voucher_number, v_salary.id::text),\n      'created_by', auth.uid(),\n      'document_urls', '[]'::jsonb\n    ),\n    p_allocations => jsonb_build_array(jsonb_build_object(\n      'finance_expense_id', v_salary.id,\n      'amount', v_total,\n      'currency', v_currency\n    )),\n    p_payment_purpose => 'salary_advance_settlement'\n  );\n\n  v_settlement_id := (v_settlement->>'id')::uuid;\n  PERFORM public.post_payment_voucher(v_settlement_id, auth.uid());\n\n  FOR v_idx IN 1..COALESCE(array_length(v_selected_ids, 1), 0) LOOP\n    INSERT INTO public.salary_advance_applications(\n      advance_payment_voucher_id,\n      salary_expense_id,\n      settlement_payment_voucher_id,\n      applied_amount\n    )\n    VALUES (\n      v_selected_ids[v_idx],\n      v_salary.id,\n      v_settlement_id,\n      v_selected_amounts[v_idx]\n    );\n\n    PERFORM public.refresh_salary_advance_status(v_selected_ids[v_idx]);\n  END LOOP;\n\n  RETURN jsonb_build_object(\n    'applied', true,\n    'total_applied', v_total,\n    'remaining_salary', GREATEST(v_salary.amount - COALESCE(v_salary.pph_amount, 0) - v_bpjs - v_total, 0),\n    'settlement_payment_voucher_id', v_settlement_id,\n    'settlement_payment_voucher_number', v_settlement->>'voucher_number',\n    'advance_ids_applied', to_jsonb(v_selected_ids)\n  );\nEND;\n$function$;\n\nREVOKE ALL ON FUNCTION public.apply_selected_salary_advances_to_expense(uuid, uuid[]) FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION public.apply_selected_salary_advances_to_expense(uuid, uuid[]) TO authenticated, service_role;\n\nCOMMIT;\n"}	explicit_salary_advance_selection	simplykool@gmail.com	\N	\N
20261009052255	{"-- One-time, idempotent correction for Sandi Prasetyo's July and September 2026\n-- salary advance application links. This preserves the July bank reconciliation and\n-- retains original journals as reversed with explicit replacement journals.\nCREATE OR REPLACE FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026()\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  c_staff_id CONSTANT uuid := '276dc2e0-3cb2-426f-aee7-a9991e5f4cfc';\n  c_july_expense_id CONSTANT uuid := '50da93f7-81e6-4ae7-912b-62538d97f016';\n  c_july_bank_line_id CONSTANT uuid := 'f92f9568-e361-447a-be33-a490f59e5db4';\n  c_july_bank_allocation_id CONSTANT uuid := '7f1d0ede-6e78-4cf9-be30-60c461cd6fa6';\n  c_september_expense_id CONSTANT uuid := '252040f4-bf49-463e-9af6-5bc9921a593c';\n  c_advance_012 CONSTANT uuid := '0efd7d85-6977-4bc1-b210-004e00834d88';\n  c_advance_013 CONSTANT uuid := '56acdc56-5b77-496f-a162-9f939a50aa4e';\n  c_advance_019 CONSTANT uuid := '28faa8e0-fc1c-49df-aa20-01fcec0bc62c';\n  c_settlement_021 CONSTANT uuid := 'df740056-054f-400c-8076-4fdefd6d28e0';\n  c_app_012 CONSTANT uuid := 'd125c26c-1f73-4972-a870-cd99c0c40ade';\n  c_app_013 CONSTANT uuid := '1eddf8a3-d17b-4063-b97d-f46fd9916759';\n  c_app_019 CONSTANT uuid := '00bcc331-d244-4e83-b463-5ae48ab8ca67';\n  c_idempotency CONSTANT text := 'sandi-prasetyo-salary-advance-jul-sep-2026-v1';\n\n  v_existing public.finance_historical_repair_commands%ROWTYPE;\n  v_command_id uuid;\n  v_july public.finance_expenses%ROWTYPE;\n  v_september public.finance_expenses%ROWTYPE;\n  v_settlement public.payment_vouchers%ROWTYPE;\n  v_july_source_je public.journal_entries%ROWTYPE;\n  v_september_source_je public.journal_entries%ROWTYPE;\n  v_bank_line public.bank_statement_lines%ROWTYPE;\n  v_bank_allocation public.bank_statement_allocations%ROWTYPE;\n  v_july_settlement_id uuid;\n  v_july_settlement_je_id uuid;\n  v_july_settlement_number text;\n  v_july_reversal_id uuid;\n  v_september_reversal_id uuid;\n  v_july_replacement_je_id uuid;\n  v_september_replacement_je_id uuid;\n  v_salary_coa uuid;\n  v_bank_coa uuid;\n  v_ap_coa uuid;\n  v_advance_coa uuid;\n  v_period_id uuid;\n  v_entry_number text;\n  v_line record;\n  v_line_no integer;\n  v_count integer;\n  v_debit numeric;\n  v_credit numeric;\n  v_before jsonb;\n  v_after jsonb;\nBEGIN\n  IF current_user NOT IN ('postgres', 'supabase_admin')\n     AND COALESCE(auth.role(), '') <> 'service_role'\n     AND NOT EXISTS (\n       SELECT 1 FROM public.user_profiles\n        WHERE id = auth.uid() AND is_active = true AND role = 'admin'\n     ) THEN\n    RAISE EXCEPTION 'This historical payroll repair requires a database administrator';\n  END IF;\n\n  SELECT * INTO v_existing\n    FROM public.finance_historical_repair_commands\n   WHERE idempotency_key = c_idempotency\n   FOR UPDATE;\n  IF FOUND THEN\n    RETURN jsonb_build_object(\n      'idempotent', true,\n      'command_id', v_existing.id,\n      'before', v_existing.before_state,\n      'after', v_existing.after_state\n    );\n  END IF;\n\n  SELECT * INTO v_july\n    FROM public.finance_expenses\n   WHERE id = c_july_expense_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_july.voucher_number <> 'EXP/26-26/122'\n     OR v_july.expense_category <> 'salary'\n     OR v_july.staff_id <> c_staff_id\n     OR v_july.approval_status <> 'approved'\n     OR abs(v_july.amount - 1850000) > 0.01\n     OR abs(COALESCE(v_july.paid_amount, 0) - 1850000) > 0.01 THEN\n    RAISE EXCEPTION 'July salary record no longer matches the reviewed evidence; no changes made';\n  END IF;\n\n  SELECT * INTO v_september\n    FROM public.finance_expenses\n   WHERE id = c_september_expense_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_september.voucher_number <> 'EXP/26/285'\n     OR v_september.expense_category <> 'salary'\n     OR v_september.staff_id <> c_staff_id\n     OR v_september.approval_status <> 'pending_approval'\n     OR abs(v_september.amount - 2000000) > 0.01\n     OR abs(COALESCE(v_september.paid_amount, 0) - 1150000) > 0.01 THEN\n    RAISE EXCEPTION 'September salary record no longer matches the reviewed evidence; no changes made';\n  END IF;\n\n  SELECT * INTO v_settlement\n    FROM public.payment_vouchers\n   WHERE id = c_settlement_021\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_settlement.voucher_number <> 'PV/26-26/021'\n     OR v_settlement.payment_purpose <> 'salary_advance_settlement'\n     OR v_settlement.payment_method <> 'advance_adjustment'\n     OR v_settlement.staff_id <> c_staff_id\n     OR v_settlement.is_posted IS DISTINCT FROM true\n     OR abs(v_settlement.amount - 1150000) > 0.01 THEN\n    RAISE EXCEPTION 'September settlement voucher no longer matches reviewed evidence; no changes made';\n  END IF;\n\n  SELECT * INTO v_bank_line\n    FROM public.bank_statement_lines\n   WHERE id = c_july_bank_line_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_bank_line.matched_expense_id <> c_july_expense_id\n     OR v_bank_line.transaction_date <> DATE '2026-07-31'\n     OR abs(COALESCE(v_bank_line.debit_amount, 0) - 1850000) > 0.01\n     OR v_bank_line.description NOT ILIKE '%SALARY JULI 26 SANDI PRASETYO%' THEN\n    RAISE EXCEPTION 'July bank statement evidence does not match; no changes made';\n  END IF;\n\n  SELECT * INTO v_bank_allocation\n    FROM public.bank_statement_allocations\n   WHERE id = c_july_bank_allocation_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_bank_allocation.bank_statement_line_id <> c_july_bank_line_id\n     OR v_bank_allocation.document_type <> 'expense'\n     OR v_bank_allocation.document_id <> c_july_expense_id\n     OR abs(v_bank_allocation.allocation_amount - 1850000) > 0.01 THEN\n    RAISE EXCEPTION 'July bank allocation is missing or changed; no changes made';\n  END IF;\n\n  SELECT je.* INTO v_july_source_je\n    FROM public.journal_entries je\n   WHERE je.id = v_bank_allocation.journal_entry_id\n     AND je.reference_id = c_july_expense_id\n     AND je.entry_number = 'JE2607-0083'\n     AND je.source_module IN ('expense', 'expenses')\n     AND je.is_posted = true\n     AND NOT COALESCE(je.is_reversed, false)\n   FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Expected active July salary journal JE2607-0083 is missing; no changes made';\n  END IF;\n\n  SELECT count(*) INTO v_count\n    FROM public.salary_advance_applications\n   WHERE id IN (c_app_012, c_app_013, c_app_019)\n     AND salary_expense_id = c_september_expense_id\n     AND settlement_payment_voucher_id = c_settlement_021;\n  IF v_count <> 3 THEN\n    RAISE EXCEPTION 'The three expected advance application links have changed; no changes made';\n  END IF;\n\n  SELECT COALESCE(sum(applied_amount), 0) INTO v_debit\n    FROM public.salary_advance_applications\n   WHERE settlement_payment_voucher_id = c_settlement_021\n     AND salary_expense_id = c_september_expense_id;\n  IF abs(v_debit - 1150000) > 0.01 THEN\n    RAISE EXCEPTION 'Expected September-linked advance applications totaling Rp1,150,000; no changes made';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.salary_advance_applications\n     WHERE advance_payment_voucher_id IN (c_advance_012, c_advance_013)\n       AND salary_expense_id <> c_september_expense_id\n  ) THEN\n    RAISE EXCEPTION 'One of the July advances is already applied elsewhere; no changes made';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-07-31' AND end_date >= DATE '2026-07-31'\n       AND status <> 'open'\n  ) OR NOT EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-07-31' AND end_date >= DATE '2026-07-31'\n       AND status = 'open'\n  ) OR EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-09-30' AND end_date >= DATE '2026-09-30'\n       AND status <> 'open'\n  ) OR NOT EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-09-30' AND end_date >= DATE '2026-09-30'\n       AND status = 'open'\n  ) THEN\n    RAISE EXCEPTION 'July and September accounting periods must be open; no changes made';\n  END IF;\n\n  SELECT id INTO v_salary_coa FROM public.chart_of_accounts WHERE code = '6100' LIMIT 1;\n  SELECT id INTO v_ap_coa FROM public.chart_of_accounts WHERE code = '2110' LIMIT 1;\n  SELECT id INTO v_advance_coa FROM public.chart_of_accounts WHERE code = '1160' LIMIT 1;\n  SELECT ba.coa_id INTO v_bank_coa\n    FROM public.bank_accounts ba\n   WHERE ba.id = v_bank_line.bank_account_id;\n  IF v_salary_coa IS NULL OR v_ap_coa IS NULL OR v_advance_coa IS NULL OR v_bank_coa IS NULL THEN\n    RAISE EXCEPTION 'Required salary, AP, advance, or bank COA is missing; no changes made';\n  END IF;\n\n  IF (SELECT count(*) FROM public.journal_entry_lines WHERE journal_entry_id = v_july_source_je.id) <> 2\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_july_source_je.id AND account_id = v_salary_coa AND abs(debit - 1850000) < 0.01 AND abs(COALESCE(credit,0)) < 0.01)\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_july_source_je.id AND account_id = v_bank_coa AND abs(credit - 1850000) < 0.01 AND abs(COALESCE(debit,0)) < 0.01) THEN\n    RAISE EXCEPTION 'July salary journal is not the reviewed Dr Salary / Cr Bank entry; no changes made';\n  END IF;\n\n  SELECT je.* INTO v_september_source_je\n    FROM public.journal_entries je\n   WHERE je.id = v_settlement.journal_entry_id\n     AND je.reference_id = c_settlement_021\n     AND je.is_posted = true\n     AND NOT COALESCE(je.is_reversed, false)\n   FOR UPDATE;\n  IF NOT FOUND\n     OR (SELECT count(*) FROM public.journal_entry_lines WHERE journal_entry_id = v_september_source_je.id) <> 2\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_september_source_je.id AND account_id = v_ap_coa AND abs(debit - 1150000) < 0.01 AND abs(COALESCE(credit,0)) < 0.01)\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_september_source_je.id AND account_id = v_advance_coa AND abs(credit - 1150000) < 0.01 AND abs(COALESCE(debit,0)) < 0.01) THEN\n    RAISE EXCEPTION 'September settlement journal is not the expected AP/advance entry; no changes made';\n  END IF;\n\n  IF (SELECT count(*) FROM public.voucher_allocations\n       WHERE payment_voucher_id = c_settlement_021\n         AND finance_expense_id = c_september_expense_id\n         AND abs(allocated_amount - 1150000) < 0.01) <> 1 THEN\n    RAISE EXCEPTION 'September settlement allocation is missing or changed; no changes made';\n  END IF;\n\n  v_before := jsonb_build_object(\n    'july_salary', to_jsonb(v_july),\n    'july_source_journal', to_jsonb(v_july_source_je),\n    'july_bank_statement_line', to_jsonb(v_bank_line),\n    'july_bank_allocation', to_jsonb(v_bank_allocation),\n    'september_salary', to_jsonb(v_september),\n    'september_settlement', to_jsonb(v_settlement),\n    'september_source_journal', to_jsonb(v_september_source_je),\n    'advance_applications', (\n      SELECT COALESCE(jsonb_agg(to_jsonb(sa) ORDER BY sa.id), '[]'::jsonb)\n        FROM public.salary_advance_applications sa\n       WHERE sa.id IN (c_app_012, c_app_013, c_app_019)\n    )\n  );\n\n  INSERT INTO public.finance_historical_repair_commands(\n    idempotency_key, document_type, document_id, bank_statement_line_id,\n    payment_kind, operation, requested_by, before_state, after_state, status\n  ) VALUES (\n    c_idempotency, 'expense', c_july_expense_id, c_july_bank_line_id,\n    'supplier', 'restate_salary_net_of_advance', auth.uid(), v_before, '{}'::jsonb, 'committed'\n  ) RETURNING id INTO v_command_id;\n\n  PERFORM set_config('app.finance_historical_repair_command', v_command_id::text, true);\n  PERFORM set_config('app.finance_historical_repair', 'on', true);\n  PERFORM set_config('app.finance_metadata_repair', 'on', true);\n\n  -- Restore the actual July gross salary while preserving the real Rp1.85m bank payout.\n  -- Existing bank allocation remains Rp1.85m; the extra Rp650k is settled against advances.\n  UPDATE public.finance_expenses\n     SET amount = 2500000,\n         settlement_amount = 2500000,\n         paid_amount = 2500000\n   WHERE id = c_july_expense_id;\n\n  v_july_settlement_number := public.next_payment_voucher_number(DATE '2026-07-31');\n  INSERT INTO public.payment_vouchers(\n    voucher_number, voucher_date, supplier_id, payment_method, bank_account_id,\n    reference_number, amount, pph_amount, net_amount, description, document_urls,\n    created_by, coa_account_id, payment_currency, exchange_rate, bank_amount,\n    bank_charge, is_posted, staff_id, currency_code, transaction_currency,\n    functional_currency, bank_account_currency, payment_purpose, invoice_currency,\n    invoice_amount, payment_amount, bank_currency, converted_amount, actual_bank_debit,\n    salary_advance_applied_amount, salary_advance_status, settlement_amount\n  ) VALUES (\n    v_july_settlement_number, DATE '2026-07-31', NULL, 'advance_adjustment', NULL,\n    'HIST-SALARY-EXP-26-26-122', 650000, 0, 650000,\n    'Salary Advance Recovery - EXP/26-26/122 (PV/26-26/012 + PV/26-26/013)',\n    ARRAY[]::text[], v_settlement.created_by, NULL, 'IDR', 1, 0, 0, false,\n    c_staff_id, 'IDR', 'IDR', 'IDR', 'IDR', 'salary_advance_settlement',\n    'IDR', 650000, 650000, 'IDR', 650000, 0, 0, 'not_applicable', 650000\n  ) RETURNING id INTO v_july_settlement_id;\n\n  -- Reverse the old July expense journal, preserving it for audit.\n  v_entry_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, v_july_source_je.entry_date, v_july_source_je.period_id,\n    'historical_repair', c_july_expense_id, 'HR-REV-JUL-' || v_command_id::text,\n    'Historical reversal of July net-salary-only posting ' || v_july_source_je.entry_number,\n    'salary_advance_restatement', v_july_source_je.total_credit, v_july_source_je.total_debit,\n    true, now(), auth.uid(), v_july_source_je.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_july_reversal_id;\n\n  v_line_no := 1;\n  FOR v_line IN\n    SELECT * FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_july_source_je.id ORDER BY line_number\n  LOOP\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      supplier_id, payee_id, transaction_currency, transaction_debit,\n      transaction_credit, functional_currency, exchange_rate\n    ) VALUES (\n      v_july_reversal_id, v_line_no, v_line.account_id,\n      'Historical reversal: ' || COALESCE(v_line.description, ''),\n      v_line.credit, v_line.debit, v_line.supplier_id, v_line.payee_id,\n      COALESCE(v_line.transaction_currency, 'IDR'),\n      COALESCE(v_line.transaction_credit, v_line.credit),\n      COALESCE(v_line.transaction_debit, v_line.debit),\n      'IDR', 1\n    );\n    v_line_no := v_line_no + 1;\n  END LOOP;\n  UPDATE public.journal_entries\n     SET is_reversed = true, reversed_by_id = v_july_reversal_id\n   WHERE id = v_july_source_je.id;\n\n  -- Replacement July journal: gross salary Rp2.5m = bank payout Rp1.85m + AP/advance recovery Rp650k.\n  v_entry_number := public.next_journal_entry_number();\n  SELECT id INTO v_period_id\n    FROM public.accounting_periods\n   WHERE start_date <= DATE '2026-07-31' AND end_date >= DATE '2026-07-31'\n   ORDER BY start_date DESC LIMIT 1;\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, DATE '2026-07-31', v_period_id, 'expenses', c_july_expense_id,\n    'EXP-' || c_july_expense_id::text,\n    'Salary July 2026 - gross Rp2,500,000; bank Rp1,850,000; advances Rp650,000',\n    'salary', 2500000, 2500000, true, now(), auth.uid(), v_july_source_je.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_july_replacement_je_id;\n\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate\n  ) VALUES\n    (v_july_replacement_je_id, 1, v_salary_coa, 'Gross July salary - Sandi Prasetyo', 2500000, 0, 'IDR', 2500000, 0, 'IDR', 1),\n    (v_july_replacement_je_id, 2, v_bank_coa, 'Actual salary bank payout - statement matched', 0, 1850000, 'IDR', 0, 1850000, 'IDR', 1),\n    (v_july_replacement_je_id, 3, v_ap_coa, 'July salary advance deduction clearing', 0, 650000, 'IDR', 0, 650000, 'IDR', 1);\n\n  UPDATE public.bank_statement_allocations\n     SET journal_entry_id = v_july_replacement_je_id\n   WHERE id = c_july_bank_allocation_id;\n\n  -- Post the internal July settlement journal: Dr AP, Cr Staff Advances.\n  v_entry_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, DATE '2026-07-31', v_period_id, 'payment', v_july_settlement_id,\n    v_july_settlement_number,\n    'Salary Advance Settlement - Sandi July advances PV/26-26/012 and PV/26-26/013',\n    'salary_advance_settlement', 650000, 650000, true, now(), auth.uid(),\n    v_settlement.created_by, 'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_july_settlement_je_id;\n\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate\n  ) VALUES\n    (v_july_settlement_je_id, 1, v_ap_coa, 'July salary payable cleared by advance deduction', 650000, 0, 'IDR', 650000, 0, 'IDR', 1),\n    (v_july_settlement_je_id, 2, v_advance_coa, 'Clear July staff advances PV/26-26/012 + PV/26-26/013', 0, 650000, 'IDR', 0, 650000, 'IDR', 1);\n\n  UPDATE public.payment_vouchers\n     SET journal_entry_id = v_july_settlement_je_id,\n         is_posted = true\n   WHERE id = v_july_settlement_id;\n\n  INSERT INTO public.voucher_allocations(\n    voucher_type, payment_voucher_id, finance_expense_id, allocated_amount,\n    allocated_currency, payment_kind\n  ) VALUES (\n    'payment', v_july_settlement_id, c_july_expense_id, 650000, 'IDR', 'supplier'\n  );\n\n  -- Reverse September's incorrect Rp1.15m settlement journal.\n  v_entry_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, v_september_source_je.entry_date, v_september_source_je.period_id,\n    'historical_repair', c_settlement_021, 'HR-REV-SEP-' || v_command_id::text,\n    'Historical reversal of overstated salary advance settlement PV/26-26/021',\n    'salary_advance_restatement', v_september_source_je.total_credit, v_september_source_je.total_debit,\n    true, now(), auth.uid(), v_september_source_je.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_september_reversal_id;\n\n  v_line_no := 1;\n  FOR v_line IN\n    SELECT * FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_september_source_je.id ORDER BY line_number\n  LOOP\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      supplier_id, payee_id, transaction_currency, transaction_debit,\n      transaction_credit, functional_currency, exchange_rate\n    ) VALUES (\n      v_september_reversal_id, v_line_no, v_line.account_id,\n      'Historical reversal: ' || COALESCE(v_line.description, ''),\n      v_line.credit, v_line.debit, v_line.supplier_id, v_line.payee_id,\n      COALESCE(v_line.transaction_currency, 'IDR'),\n      COALESCE(v_line.transaction_credit, v_line.credit),\n      COALESCE(v_line.transaction_debit, v_line.debit),\n      'IDR', 1\n    );\n    v_line_no := v_line_no + 1;\n  END LOOP;\n  UPDATE public.journal_entries\n     SET is_reversed = true, reversed_by_id = v_september_reversal_id\n   WHERE id = v_september_source_je.id;\n\n  -- Corrected September settlement is Rp500k for PV/26-26/019 only.\n  v_entry_number := public.next_journal_entry_number();\n  SELECT id INTO v_period_id\n    FROM public.accounting_periods\n   WHERE start_date <= DATE '2026-09-30' AND end_date >= DATE '2026-09-30'\n   ORDER BY start_date DESC LIMIT 1;\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, DATE '2026-09-30', v_period_id, 'payment', c_settlement_021,\n    'PV/26-26/021',\n    'Payment Voucher PV/26-26/021 - corrected September advance settlement Rp500,000',\n    'salary_advance_settlement', 500000, 500000, true, now(), auth.uid(), v_settlement.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_september_replacement_je_id;\n\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate\n  ) VALUES\n    (v_september_replacement_je_id, 1, v_ap_coa, 'Salary payable cleared by September advance', 500000, 0, 'IDR', 500000, 0, 'IDR', 1),\n    (v_september_replacement_je_id, 2, v_advance_coa, 'Clear September staff advance PV/26-26/019', 0, 500000, 'IDR', 0, 500000, 'IDR', 1);\n\n  -- Move the two July advance links to the July salary; keep September PV/021 linked only to PV/019.\n  UPDATE public.salary_advance_applications\n     SET salary_expense_id = c_july_expense_id,\n         settlement_payment_voucher_id = v_july_settlement_id\n   WHERE id IN (c_app_012, c_app_013)\n     AND salary_expense_id = c_september_expense_id\n     AND settlement_payment_voucher_id = c_settlement_021;\n  GET DIAGNOSTICS v_count = ROW_COUNT;\n  IF v_count <> 2 THEN\n    RAISE EXCEPTION 'Expected to move exactly two July advance links; transaction rolled back';\n  END IF;\n\n  UPDATE public.payment_vouchers\n     SET amount = 500000,\n         net_amount = 500000,\n         invoice_amount = 500000,\n         payment_amount = 500000,\n         converted_amount = 500000,\n         bank_amount = 0,\n         actual_bank_debit = 0,\n         settlement_amount = 500000,\n         journal_entry_id = v_september_replacement_je_id,\n         is_posted = true\n   WHERE id = c_settlement_021;\n\n  UPDATE public.voucher_allocations\n     SET allocated_amount = 500000,\n         allocated_currency = 'IDR'\n   WHERE payment_voucher_id = c_settlement_021\n     AND finance_expense_id = c_september_expense_id\n     AND abs(allocated_amount - 1150000) < 0.01;\n\n  -- Add explicit audit rows for the reclassified application links and corrected settlement.\n  INSERT INTO public.audit_logs(table_name, record_id, action_type, old_values, new_values, user_id)\n  VALUES\n    ('salary_advance_applications', c_app_012, 'update',\n     jsonb_build_object('salary_expense_id', c_september_expense_id, 'settlement_payment_voucher_id', c_settlement_021, 'applied_amount', 500000),\n     jsonb_build_object('salary_expense_id', c_july_expense_id, 'settlement_payment_voucher_id', v_july_settlement_id, 'applied_amount', 500000),\n     auth.uid()),\n    ('salary_advance_applications', c_app_013, 'update',\n     jsonb_build_object('salary_expense_id', c_september_expense_id, 'settlement_payment_voucher_id', c_settlement_021, 'applied_amount', 150000),\n     jsonb_build_object('salary_expense_id', c_july_expense_id, 'settlement_payment_voucher_id', v_july_settlement_id, 'applied_amount', 150000),\n     auth.uid()),\n    ('payment_vouchers', c_settlement_021, 'update',\n     jsonb_build_object('amount', 1150000, 'net_amount', 1150000, 'journal_entry_id', v_september_source_je.id, 'description', v_settlement.description),\n     jsonb_build_object('amount', 500000, 'net_amount', 500000, 'journal_entry_id', v_september_replacement_je_id, 'description', v_settlement.description),\n     auth.uid());\n\n  PERFORM public.refresh_salary_advance_status(c_advance_012);\n  PERFORM public.refresh_salary_advance_status(c_advance_013);\n  PERFORM public.refresh_salary_advance_status(c_advance_019);\n\n  -- Final exact balance/state values after allocation and advance links are moved.\n  UPDATE public.finance_expenses SET paid_amount = 2500000 WHERE id = c_july_expense_id;\n  UPDATE public.finance_expenses SET paid_amount = 500000 WHERE id = c_september_expense_id;\n\n  SELECT COALESCE(sum(debit), 0), COALESCE(sum(credit), 0)\n    INTO v_debit, v_credit\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id = v_july_replacement_je_id;\n  IF abs(v_debit - 2500000) > 0.01 OR abs(v_credit - 2500000) > 0.01 THEN\n    RAISE EXCEPTION 'Corrected July salary journal does not balance; transaction rolled back';\n  END IF;\n\n  SELECT COALESCE(sum(debit), 0), COALESCE(sum(credit), 0)\n    INTO v_debit, v_credit\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id = v_september_replacement_je_id;\n  IF abs(v_debit - 500000) > 0.01 OR abs(v_credit - 500000) > 0.01 THEN\n    RAISE EXCEPTION 'Corrected September settlement journal does not balance; transaction rolled back';\n  END IF;\n\n  IF (SELECT count(*) FROM public.salary_advance_applications\n       WHERE salary_expense_id = c_july_expense_id\n         AND advance_payment_voucher_id IN (c_advance_012, c_advance_013)\n         AND settlement_payment_voucher_id = v_july_settlement_id) <> 2\n     OR (SELECT count(*) FROM public.salary_advance_applications\n       WHERE salary_expense_id = c_september_expense_id\n         AND advance_payment_voucher_id = c_advance_019\n         AND settlement_payment_voucher_id = c_settlement_021\n         AND abs(applied_amount - 500000) < 0.01) <> 1\n     OR (SELECT count(*) FROM public.salary_advance_applications\n       WHERE salary_expense_id = c_september_expense_id\n         AND advance_payment_voucher_id IN (c_advance_012, c_advance_013)) <> 0 THEN\n    RAISE EXCEPTION 'Final advance links failed verification; transaction rolled back';\n  END IF;\n\n  v_after := jsonb_build_object(\n    'july_salary_voucher', 'EXP/26-26/122',\n    'july_gross_salary', 2500000,\n    'july_bank_payout_preserved', 1850000,\n    'july_advance_deduction', 650000,\n    'july_reversal_journal_id', v_july_reversal_id,\n    'july_replacement_journal_id', v_july_replacement_je_id,\n    'july_settlement_voucher_id', v_july_settlement_id,\n    'july_settlement_voucher_number', v_july_settlement_number,\n    'september_salary_voucher', 'EXP/26/285',\n    'september_gross_salary', 2000000,\n    'september_advance_deduction', 500000,\n    'september_net_payable', 1500000,\n    'september_reversal_journal_id', v_september_reversal_id,\n    'september_replacement_journal_id', v_september_replacement_je_id,\n    'july_bank_allocation_id_preserved', c_july_bank_allocation_id,\n    'advance_applications', (\n      SELECT COALESCE(jsonb_agg(jsonb_build_object(\n        'advance', av.voucher_number,\n        'salary', fe.voucher_number,\n        'amount', sa.applied_amount,\n        'settlement', settlement.voucher_number\n      ) ORDER BY av.voucher_number), '[]'::jsonb)\n      FROM public.salary_advance_applications sa\n      JOIN public.payment_vouchers av ON av.id = sa.advance_payment_voucher_id\n      JOIN public.finance_expenses fe ON fe.id = sa.salary_expense_id\n      JOIN public.payment_vouchers settlement ON settlement.id = sa.settlement_payment_voucher_id\n      WHERE sa.id IN (c_app_012, c_app_013, c_app_019)\n    )\n  );\n\n  UPDATE public.finance_historical_repair_commands\n     SET before_state = v_before,\n         after_state = v_after,\n         created_allocation_id = c_july_bank_allocation_id\n   WHERE id = v_command_id;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'command_id', v_command_id,\n    'before', v_before,\n    'after', v_after\n  );\nEND;\n$function$;\n\nREVOKE ALL ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() FROM anon;\nREVOKE ALL ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() FROM authenticated;\nGRANT EXECUTE ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() TO service_role;\n"}	repair_sandi_salary_advance_july_september	simplykool@gmail.com	\N	\N
20261009052319	{"-- One-time, idempotent correction for Sandi Prasetyo's July and September 2026\n-- salary advance application links. This preserves the July bank reconciliation and\n-- retains original journals as reversed with explicit replacement journals.\nCREATE OR REPLACE FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026()\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  c_staff_id CONSTANT uuid := '276dc2e0-3cb2-426f-aee7-a9991e5f4cfc';\n  c_july_expense_id CONSTANT uuid := '50da93f7-81e6-4ae7-912b-62538d97f016';\n  c_july_bank_line_id CONSTANT uuid := 'f92f9568-e361-447a-be33-a490f59e5db4';\n  c_july_bank_allocation_id CONSTANT uuid := '7f1d0ede-6e78-4cf9-be30-60c461cd6fa6';\n  c_september_expense_id CONSTANT uuid := '252040f4-bf49-463e-9af6-5bc9921a593c';\n  c_advance_012 CONSTANT uuid := '0efd7d85-6977-4bc1-b210-004e00834d88';\n  c_advance_013 CONSTANT uuid := '56acdc56-5b77-496f-a162-9f939a50aa4e';\n  c_advance_019 CONSTANT uuid := '28faa8e0-fc1c-49df-aa20-01fcec0bc62c';\n  c_settlement_021 CONSTANT uuid := 'df740056-054f-400c-8076-4fdefd6d28e0';\n  c_app_012 CONSTANT uuid := 'd125c26c-1f73-4972-a870-cd99c0c40ade';\n  c_app_013 CONSTANT uuid := '1eddf8a3-d17b-4063-b97d-f46fd9916759';\n  c_app_019 CONSTANT uuid := '00bcc331-d244-4e83-b463-5ae48ab8ca67';\n  c_idempotency CONSTANT text := 'sandi-prasetyo-salary-advance-jul-sep-2026-v1';\n\n  v_existing public.finance_historical_repair_commands%ROWTYPE;\n  v_command_id uuid;\n  v_july public.finance_expenses%ROWTYPE;\n  v_september public.finance_expenses%ROWTYPE;\n  v_settlement public.payment_vouchers%ROWTYPE;\n  v_july_source_je public.journal_entries%ROWTYPE;\n  v_september_source_je public.journal_entries%ROWTYPE;\n  v_bank_line public.bank_statement_lines%ROWTYPE;\n  v_bank_allocation public.bank_statement_allocations%ROWTYPE;\n  v_july_settlement_id uuid;\n  v_july_settlement_je_id uuid;\n  v_july_settlement_number text;\n  v_july_reversal_id uuid;\n  v_september_reversal_id uuid;\n  v_july_replacement_je_id uuid;\n  v_september_replacement_je_id uuid;\n  v_salary_coa uuid;\n  v_bank_coa uuid;\n  v_ap_coa uuid;\n  v_advance_coa uuid;\n  v_period_id uuid;\n  v_entry_number text;\n  v_line record;\n  v_line_no integer;\n  v_count integer;\n  v_debit numeric;\n  v_credit numeric;\n  v_before jsonb;\n  v_after jsonb;\nBEGIN\n  IF current_user NOT IN ('postgres', 'supabase_admin')\n     AND COALESCE(auth.role(), '') <> 'service_role'\n     AND NOT EXISTS (\n       SELECT 1 FROM public.user_profiles\n        WHERE id = auth.uid() AND is_active = true AND role = 'admin'\n     ) THEN\n    RAISE EXCEPTION 'This historical payroll repair requires a database administrator';\n  END IF;\n\n  SELECT * INTO v_existing\n    FROM public.finance_historical_repair_commands\n   WHERE idempotency_key = c_idempotency\n   FOR UPDATE;\n  IF FOUND THEN\n    RETURN jsonb_build_object(\n      'idempotent', true,\n      'command_id', v_existing.id,\n      'before', v_existing.before_state,\n      'after', v_existing.after_state\n    );\n  END IF;\n\n  SELECT * INTO v_july\n    FROM public.finance_expenses\n   WHERE id = c_july_expense_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_july.voucher_number <> 'EXP/26-26/122'\n     OR v_july.expense_category <> 'salary'\n     OR v_july.staff_id <> c_staff_id\n     OR v_july.approval_status <> 'approved'\n     OR abs(v_july.amount - 1850000) > 0.01\n     OR abs(COALESCE(v_july.paid_amount, 0) - 1850000) > 0.01 THEN\n    RAISE EXCEPTION 'July salary record no longer matches the reviewed evidence; no changes made';\n  END IF;\n\n  SELECT * INTO v_september\n    FROM public.finance_expenses\n   WHERE id = c_september_expense_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_september.voucher_number <> 'EXP/26/285'\n     OR v_september.expense_category <> 'salary'\n     OR v_september.staff_id <> c_staff_id\n     OR v_september.approval_status <> 'pending_approval'\n     OR abs(v_september.amount - 2000000) > 0.01\n     OR abs(COALESCE(v_september.paid_amount, 0) - 1150000) > 0.01 THEN\n    RAISE EXCEPTION 'September salary record no longer matches the reviewed evidence; no changes made';\n  END IF;\n\n  SELECT * INTO v_settlement\n    FROM public.payment_vouchers\n   WHERE id = c_settlement_021\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_settlement.voucher_number <> 'PV/26-26/021'\n     OR v_settlement.payment_purpose <> 'salary_advance_settlement'\n     OR v_settlement.payment_method <> 'advance_adjustment'\n     OR v_settlement.staff_id <> c_staff_id\n     OR v_settlement.is_posted IS DISTINCT FROM true\n     OR abs(v_settlement.amount - 1150000) > 0.01 THEN\n    RAISE EXCEPTION 'September settlement voucher no longer matches reviewed evidence; no changes made';\n  END IF;\n\n  SELECT * INTO v_bank_line\n    FROM public.bank_statement_lines\n   WHERE id = c_july_bank_line_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_bank_line.matched_expense_id <> c_july_expense_id\n     OR v_bank_line.transaction_date <> DATE '2026-07-31'\n     OR abs(COALESCE(v_bank_line.debit_amount, 0) - 1850000) > 0.01\n     OR v_bank_line.description NOT ILIKE '%SALARY JULI 26 SANDI PRASETYO%' THEN\n    RAISE EXCEPTION 'July bank statement evidence does not match; no changes made';\n  END IF;\n\n  SELECT * INTO v_bank_allocation\n    FROM public.bank_statement_allocations\n   WHERE id = c_july_bank_allocation_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_bank_allocation.bank_statement_line_id <> c_july_bank_line_id\n     OR v_bank_allocation.document_type <> 'expense'\n     OR v_bank_allocation.document_id <> c_july_expense_id\n     OR abs(v_bank_allocation.allocation_amount - 1850000) > 0.01 THEN\n    RAISE EXCEPTION 'July bank allocation is missing or changed; no changes made';\n  END IF;\n\n  SELECT je.* INTO v_july_source_je\n    FROM public.journal_entries je\n   WHERE je.id = v_bank_allocation.journal_entry_id\n     AND je.reference_id = c_july_expense_id\n     AND je.entry_number = 'JE2607-0083'\n     AND je.source_module IN ('expense', 'expenses')\n     AND je.is_posted = true\n     AND NOT COALESCE(je.is_reversed, false)\n   FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Expected active July salary journal JE2607-0083 is missing; no changes made';\n  END IF;\n\n  SELECT count(*) INTO v_count\n    FROM public.salary_advance_applications\n   WHERE id IN (c_app_012, c_app_013, c_app_019)\n     AND salary_expense_id = c_september_expense_id\n     AND settlement_payment_voucher_id = c_settlement_021;\n  IF v_count <> 3 THEN\n    RAISE EXCEPTION 'The three expected advance application links have changed; no changes made';\n  END IF;\n\n  SELECT COALESCE(sum(applied_amount), 0) INTO v_debit\n    FROM public.salary_advance_applications\n   WHERE settlement_payment_voucher_id = c_settlement_021\n     AND salary_expense_id = c_september_expense_id;\n  IF abs(v_debit - 1150000) > 0.01 THEN\n    RAISE EXCEPTION 'Expected September-linked advance applications totaling Rp1,150,000; no changes made';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.salary_advance_applications\n     WHERE advance_payment_voucher_id IN (c_advance_012, c_advance_013)\n       AND salary_expense_id <> c_september_expense_id\n  ) THEN\n    RAISE EXCEPTION 'One of the July advances is already applied elsewhere; no changes made';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-07-31' AND end_date >= DATE '2026-07-31'\n       AND status <> 'open'\n  ) OR NOT EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-07-31' AND end_date >= DATE '2026-07-31'\n       AND status = 'open'\n  ) OR EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-09-30' AND end_date >= DATE '2026-09-30'\n       AND status <> 'open'\n  ) OR NOT EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-09-30' AND end_date >= DATE '2026-09-30'\n       AND status = 'open'\n  ) THEN\n    RAISE EXCEPTION 'July and September accounting periods must be open; no changes made';\n  END IF;\n\n  SELECT id INTO v_salary_coa FROM public.chart_of_accounts WHERE code = '6100' LIMIT 1;\n  SELECT id INTO v_ap_coa FROM public.chart_of_accounts WHERE code = '2110' LIMIT 1;\n  SELECT id INTO v_advance_coa FROM public.chart_of_accounts WHERE code = '1160' LIMIT 1;\n  SELECT ba.coa_id INTO v_bank_coa\n    FROM public.bank_accounts ba\n   WHERE ba.id = v_bank_line.bank_account_id;\n  IF v_salary_coa IS NULL OR v_ap_coa IS NULL OR v_advance_coa IS NULL OR v_bank_coa IS NULL THEN\n    RAISE EXCEPTION 'Required salary, AP, advance, or bank COA is missing; no changes made';\n  END IF;\n\n  IF (SELECT count(*) FROM public.journal_entry_lines WHERE journal_entry_id = v_july_source_je.id) <> 2\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_july_source_je.id AND account_id = v_salary_coa AND abs(debit - 1850000) < 0.01 AND abs(COALESCE(credit,0)) < 0.01)\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_july_source_je.id AND account_id = v_bank_coa AND abs(credit - 1850000) < 0.01 AND abs(COALESCE(debit,0)) < 0.01) THEN\n    RAISE EXCEPTION 'July salary journal is not the reviewed Dr Salary / Cr Bank entry; no changes made';\n  END IF;\n\n  SELECT je.* INTO v_september_source_je\n    FROM public.journal_entries je\n   WHERE je.id = v_settlement.journal_entry_id\n     AND je.reference_id = c_settlement_021\n     AND je.is_posted = true\n     AND NOT COALESCE(je.is_reversed, false)\n   FOR UPDATE;\n  IF NOT FOUND\n     OR (SELECT count(*) FROM public.journal_entry_lines WHERE journal_entry_id = v_september_source_je.id) <> 2\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_september_source_je.id AND account_id = v_ap_coa AND abs(debit - 1150000) < 0.01 AND abs(COALESCE(credit,0)) < 0.01)\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_september_source_je.id AND account_id = v_advance_coa AND abs(credit - 1150000) < 0.01 AND abs(COALESCE(debit,0)) < 0.01) THEN\n    RAISE EXCEPTION 'September settlement journal is not the expected AP/advance entry; no changes made';\n  END IF;\n\n  IF (SELECT count(*) FROM public.voucher_allocations\n       WHERE payment_voucher_id = c_settlement_021\n         AND finance_expense_id = c_september_expense_id\n         AND abs(allocated_amount - 1150000) < 0.01) <> 1 THEN\n    RAISE EXCEPTION 'September settlement allocation is missing or changed; no changes made';\n  END IF;\n\n  v_before := jsonb_build_object(\n    'july_salary', to_jsonb(v_july),\n    'july_source_journal', to_jsonb(v_july_source_je),\n    'july_bank_statement_line', to_jsonb(v_bank_line),\n    'july_bank_allocation', to_jsonb(v_bank_allocation),\n    'september_salary', to_jsonb(v_september),\n    'september_settlement', to_jsonb(v_settlement),\n    'september_source_journal', to_jsonb(v_september_source_je),\n    'advance_applications', (\n      SELECT COALESCE(jsonb_agg(to_jsonb(sa) ORDER BY sa.id), '[]'::jsonb)\n        FROM public.salary_advance_applications sa\n       WHERE sa.id IN (c_app_012, c_app_013, c_app_019)\n    )\n  );\n\n  INSERT INTO public.finance_historical_repair_commands(\n    idempotency_key, document_type, document_id, bank_statement_line_id,\n    payment_kind, operation, requested_by, before_state, after_state, status\n  ) VALUES (\n    c_idempotency, 'expense', c_july_expense_id, c_july_bank_line_id,\n    'supplier', 'restate_salary_net_of_advance', auth.uid(), v_before, '{}'::jsonb, 'committed'\n  ) RETURNING id INTO v_command_id;\n\n  PERFORM set_config('app.finance_historical_repair_command', v_command_id::text, true);\n  PERFORM set_config('app.finance_historical_repair', 'on', true);\n  PERFORM set_config('app.finance_metadata_repair', 'on', true);\n\n  -- Restore the actual July gross salary while preserving the real Rp1.85m bank payout.\n  -- Existing bank allocation remains Rp1.85m; the extra Rp650k is settled against advances.\n  UPDATE public.finance_expenses\n     SET amount = 2500000,\n         paid_amount = 2500000\n   WHERE id = c_july_expense_id;\n\n  v_july_settlement_number := public.next_payment_voucher_number(DATE '2026-07-31');\n  INSERT INTO public.payment_vouchers(\n    voucher_number, voucher_date, supplier_id, payment_method, bank_account_id,\n    reference_number, amount, pph_amount, net_amount, description, document_urls,\n    created_by, coa_account_id, payment_currency, exchange_rate, bank_amount,\n    bank_charge, is_posted, staff_id, currency_code, transaction_currency,\n    functional_currency, bank_account_currency, payment_purpose, invoice_currency,\n    invoice_amount, payment_amount, bank_currency, converted_amount, actual_bank_debit,\n    salary_advance_applied_amount, salary_advance_status, settlement_amount\n  ) VALUES (\n    v_july_settlement_number, DATE '2026-07-31', NULL, 'advance_adjustment', NULL,\n    'HIST-SALARY-EXP-26-26-122', 650000, 0, 650000,\n    'Salary Advance Recovery - EXP/26-26/122 (PV/26-26/012 + PV/26-26/013)',\n    ARRAY[]::text[], v_settlement.created_by, NULL, 'IDR', 1, 0, 0, false,\n    c_staff_id, 'IDR', 'IDR', 'IDR', 'IDR', 'salary_advance_settlement',\n    'IDR', 650000, 650000, 'IDR', 650000, 0, 0, 'not_applicable', 650000\n  ) RETURNING id INTO v_july_settlement_id;\n\n  -- Reverse the old July expense journal, preserving it for audit.\n  v_entry_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, v_july_source_je.entry_date, v_july_source_je.period_id,\n    'historical_repair', c_july_expense_id, 'HR-REV-JUL-' || v_command_id::text,\n    'Historical reversal of July net-salary-only posting ' || v_july_source_je.entry_number,\n    'salary_advance_restatement', v_july_source_je.total_credit, v_july_source_je.total_debit,\n    true, now(), auth.uid(), v_july_source_je.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_july_reversal_id;\n\n  v_line_no := 1;\n  FOR v_line IN\n    SELECT * FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_july_source_je.id ORDER BY line_number\n  LOOP\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      supplier_id, payee_id, transaction_currency, transaction_debit,\n      transaction_credit, functional_currency, exchange_rate\n    ) VALUES (\n      v_july_reversal_id, v_line_no, v_line.account_id,\n      'Historical reversal: ' || COALESCE(v_line.description, ''),\n      v_line.credit, v_line.debit, v_line.supplier_id, v_line.payee_id,\n      COALESCE(v_line.transaction_currency, 'IDR'),\n      COALESCE(v_line.transaction_credit, v_line.credit),\n      COALESCE(v_line.transaction_debit, v_line.debit),\n      'IDR', 1\n    );\n    v_line_no := v_line_no + 1;\n  END LOOP;\n  UPDATE public.journal_entries\n     SET is_reversed = true, reversed_by_id = v_july_reversal_id\n   WHERE id = v_july_source_je.id;\n\n  -- Replacement July journal: gross salary Rp2.5m = bank payout Rp1.85m + AP/advance recovery Rp650k.\n  v_entry_number := public.next_journal_entry_number();\n  SELECT id INTO v_period_id\n    FROM public.accounting_periods\n   WHERE start_date <= DATE '2026-07-31' AND end_date >= DATE '2026-07-31'\n   ORDER BY start_date DESC LIMIT 1;\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, DATE '2026-07-31', v_period_id, 'expenses', c_july_expense_id,\n    'EXP-' || c_july_expense_id::text,\n    'Salary July 2026 - gross Rp2,500,000; bank Rp1,850,000; advances Rp650,000',\n    'salary', 2500000, 2500000, true, now(), auth.uid(), v_july_source_je.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_july_replacement_je_id;\n\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate\n  ) VALUES\n    (v_july_replacement_je_id, 1, v_salary_coa, 'Gross July salary - Sandi Prasetyo', 2500000, 0, 'IDR', 2500000, 0, 'IDR', 1),\n    (v_july_replacement_je_id, 2, v_bank_coa, 'Actual salary bank payout - statement matched', 0, 1850000, 'IDR', 0, 1850000, 'IDR', 1),\n    (v_july_replacement_je_id, 3, v_ap_coa, 'July salary advance deduction clearing', 0, 650000, 'IDR', 0, 650000, 'IDR', 1);\n\n  UPDATE public.bank_statement_allocations\n     SET journal_entry_id = v_july_replacement_je_id\n   WHERE id = c_july_bank_allocation_id;\n\n  -- Post the internal July settlement journal: Dr AP, Cr Staff Advances.\n  v_entry_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, DATE '2026-07-31', v_period_id, 'payment', v_july_settlement_id,\n    v_july_settlement_number,\n    'Salary Advance Settlement - Sandi July advances PV/26-26/012 and PV/26-26/013',\n    'salary_advance_settlement', 650000, 650000, true, now(), auth.uid(),\n    v_settlement.created_by, 'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_july_settlement_je_id;\n\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate\n  ) VALUES\n    (v_july_settlement_je_id, 1, v_ap_coa, 'July salary payable cleared by advance deduction', 650000, 0, 'IDR', 650000, 0, 'IDR', 1),\n    (v_july_settlement_je_id, 2, v_advance_coa, 'Clear July staff advances PV/26-26/012 + PV/26-26/013', 0, 650000, 'IDR', 0, 650000, 'IDR', 1);\n\n  UPDATE public.payment_vouchers\n     SET journal_entry_id = v_july_settlement_je_id,\n         is_posted = true\n   WHERE id = v_july_settlement_id;\n\n  INSERT INTO public.voucher_allocations(\n    voucher_type, payment_voucher_id, finance_expense_id, allocated_amount,\n    allocated_currency, payment_kind\n  ) VALUES (\n    'payment', v_july_settlement_id, c_july_expense_id, 650000, 'IDR', 'supplier'\n  );\n\n  -- Reverse September's incorrect Rp1.15m settlement journal.\n  v_entry_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, v_september_source_je.entry_date, v_september_source_je.period_id,\n    'historical_repair', c_settlement_021, 'HR-REV-SEP-' || v_command_id::text,\n    'Historical reversal of overstated salary advance settlement PV/26-26/021',\n    'salary_advance_restatement', v_september_source_je.total_credit, v_september_source_je.total_debit,\n    true, now(), auth.uid(), v_september_source_je.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_september_reversal_id;\n\n  v_line_no := 1;\n  FOR v_line IN\n    SELECT * FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_september_source_je.id ORDER BY line_number\n  LOOP\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      supplier_id, payee_id, transaction_currency, transaction_debit,\n      transaction_credit, functional_currency, exchange_rate\n    ) VALUES (\n      v_september_reversal_id, v_line_no, v_line.account_id,\n      'Historical reversal: ' || COALESCE(v_line.description, ''),\n      v_line.credit, v_line.debit, v_line.supplier_id, v_line.payee_id,\n      COALESCE(v_line.transaction_currency, 'IDR'),\n      COALESCE(v_line.transaction_credit, v_line.credit),\n      COALESCE(v_line.transaction_debit, v_line.debit),\n      'IDR', 1\n    );\n    v_line_no := v_line_no + 1;\n  END LOOP;\n  UPDATE public.journal_entries\n     SET is_reversed = true, reversed_by_id = v_september_reversal_id\n   WHERE id = v_september_source_je.id;\n\n  -- Corrected September settlement is Rp500k for PV/26-26/019 only.\n  v_entry_number := public.next_journal_entry_number();\n  SELECT id INTO v_period_id\n    FROM public.accounting_periods\n   WHERE start_date <= DATE '2026-09-30' AND end_date >= DATE '2026-09-30'\n   ORDER BY start_date DESC LIMIT 1;\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, DATE '2026-09-30', v_period_id, 'payment', c_settlement_021,\n    'PV/26-26/021',\n    'Payment Voucher PV/26-26/021 - corrected September advance settlement Rp500,000',\n    'salary_advance_settlement', 500000, 500000, true, now(), auth.uid(), v_settlement.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_september_replacement_je_id;\n\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate\n  ) VALUES\n    (v_september_replacement_je_id, 1, v_ap_coa, 'Salary payable cleared by September advance', 500000, 0, 'IDR', 500000, 0, 'IDR', 1),\n    (v_september_replacement_je_id, 2, v_advance_coa, 'Clear September staff advance PV/26-26/019', 0, 500000, 'IDR', 0, 500000, 'IDR', 1);\n\n  -- Move the two July advance links to the July salary; keep September PV/021 linked only to PV/019.\n  UPDATE public.salary_advance_applications\n     SET salary_expense_id = c_july_expense_id,\n         settlement_payment_voucher_id = v_july_settlement_id\n   WHERE id IN (c_app_012, c_app_013)\n     AND salary_expense_id = c_september_expense_id\n     AND settlement_payment_voucher_id = c_settlement_021;\n  GET DIAGNOSTICS v_count = ROW_COUNT;\n  IF v_count <> 2 THEN\n    RAISE EXCEPTION 'Expected to move exactly two July advance links; transaction rolled back';\n  END IF;\n\n  UPDATE public.payment_vouchers\n     SET amount = 500000,\n         net_amount = 500000,\n         invoice_amount = 500000,\n         payment_amount = 500000,\n         converted_amount = 500000,\n         bank_amount = 0,\n         actual_bank_debit = 0,\n         settlement_amount = 500000,\n         journal_entry_id = v_september_replacement_je_id,\n         is_posted = true\n   WHERE id = c_settlement_021;\n\n  UPDATE public.voucher_allocations\n     SET allocated_amount = 500000,\n         allocated_currency = 'IDR'\n   WHERE payment_voucher_id = c_settlement_021\n     AND finance_expense_id = c_september_expense_id\n     AND abs(allocated_amount - 1150000) < 0.01;\n\n  -- Add explicit audit rows for the reclassified application links and corrected settlement.\n  INSERT INTO public.audit_logs(table_name, record_id, action_type, old_values, new_values, user_id)\n  VALUES\n    ('salary_advance_applications', c_app_012, 'update',\n     jsonb_build_object('salary_expense_id', c_september_expense_id, 'settlement_payment_voucher_id', c_settlement_021, 'applied_amount', 500000),\n     jsonb_build_object('salary_expense_id', c_july_expense_id, 'settlement_payment_voucher_id', v_july_settlement_id, 'applied_amount', 500000),\n     auth.uid()),\n    ('salary_advance_applications', c_app_013, 'update',\n     jsonb_build_object('salary_expense_id', c_september_expense_id, 'settlement_payment_voucher_id', c_settlement_021, 'applied_amount', 150000),\n     jsonb_build_object('salary_expense_id', c_july_expense_id, 'settlement_payment_voucher_id', v_july_settlement_id, 'applied_amount', 150000),\n     auth.uid()),\n    ('payment_vouchers', c_settlement_021, 'update',\n     jsonb_build_object('amount', 1150000, 'net_amount', 1150000, 'journal_entry_id', v_september_source_je.id, 'description', v_settlement.description),\n     jsonb_build_object('amount', 500000, 'net_amount', 500000, 'journal_entry_id', v_september_replacement_je_id, 'description', v_settlement.description),\n     auth.uid());\n\n  PERFORM public.refresh_salary_advance_status(c_advance_012);\n  PERFORM public.refresh_salary_advance_status(c_advance_013);\n  PERFORM public.refresh_salary_advance_status(c_advance_019);\n\n  -- Final exact balance/state values after allocation and advance links are moved.\n  UPDATE public.finance_expenses SET paid_amount = 2500000 WHERE id = c_july_expense_id;\n  UPDATE public.finance_expenses SET paid_amount = 500000 WHERE id = c_september_expense_id;\n\n  SELECT COALESCE(sum(debit), 0), COALESCE(sum(credit), 0)\n    INTO v_debit, v_credit\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id = v_july_replacement_je_id;\n  IF abs(v_debit - 2500000) > 0.01 OR abs(v_credit - 2500000) > 0.01 THEN\n    RAISE EXCEPTION 'Corrected July salary journal does not balance; transaction rolled back';\n  END IF;\n\n  SELECT COALESCE(sum(debit), 0), COALESCE(sum(credit), 0)\n    INTO v_debit, v_credit\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id = v_september_replacement_je_id;\n  IF abs(v_debit - 500000) > 0.01 OR abs(v_credit - 500000) > 0.01 THEN\n    RAISE EXCEPTION 'Corrected September settlement journal does not balance; transaction rolled back';\n  END IF;\n\n  IF (SELECT count(*) FROM public.salary_advance_applications\n       WHERE salary_expense_id = c_july_expense_id\n         AND advance_payment_voucher_id IN (c_advance_012, c_advance_013)\n         AND settlement_payment_voucher_id = v_july_settlement_id) <> 2\n     OR (SELECT count(*) FROM public.salary_advance_applications\n       WHERE salary_expense_id = c_september_expense_id\n         AND advance_payment_voucher_id = c_advance_019\n         AND settlement_payment_voucher_id = c_settlement_021\n         AND abs(applied_amount - 500000) < 0.01) <> 1\n     OR (SELECT count(*) FROM public.salary_advance_applications\n       WHERE salary_expense_id = c_september_expense_id\n         AND advance_payment_voucher_id IN (c_advance_012, c_advance_013)) <> 0 THEN\n    RAISE EXCEPTION 'Final advance links failed verification; transaction rolled back';\n  END IF;\n\n  v_after := jsonb_build_object(\n    'july_salary_voucher', 'EXP/26-26/122',\n    'july_gross_salary', 2500000,\n    'july_bank_payout_preserved', 1850000,\n    'july_advance_deduction', 650000,\n    'july_reversal_journal_id', v_july_reversal_id,\n    'july_replacement_journal_id', v_july_replacement_je_id,\n    'july_settlement_voucher_id', v_july_settlement_id,\n    'july_settlement_voucher_number', v_july_settlement_number,\n    'september_salary_voucher', 'EXP/26/285',\n    'september_gross_salary', 2000000,\n    'september_advance_deduction', 500000,\n    'september_net_payable', 1500000,\n    'september_reversal_journal_id', v_september_reversal_id,\n    'september_replacement_journal_id', v_september_replacement_je_id,\n    'july_bank_allocation_id_preserved', c_july_bank_allocation_id,\n    'advance_applications', (\n      SELECT COALESCE(jsonb_agg(jsonb_build_object(\n        'advance', av.voucher_number,\n        'salary', fe.voucher_number,\n        'amount', sa.applied_amount,\n        'settlement', settlement.voucher_number\n      ) ORDER BY av.voucher_number), '[]'::jsonb)\n      FROM public.salary_advance_applications sa\n      JOIN public.payment_vouchers av ON av.id = sa.advance_payment_voucher_id\n      JOIN public.finance_expenses fe ON fe.id = sa.salary_expense_id\n      JOIN public.payment_vouchers settlement ON settlement.id = sa.settlement_payment_voucher_id\n      WHERE sa.id IN (c_app_012, c_app_013, c_app_019)\n    )\n  );\n\n  UPDATE public.finance_historical_repair_commands\n     SET before_state = v_before,\n         after_state = v_after,\n         created_allocation_id = c_july_bank_allocation_id\n   WHERE id = v_command_id;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'command_id', v_command_id,\n    'before', v_before,\n    'after', v_after\n  );\nEND;\n$function$;\n\nREVOKE ALL ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() FROM anon;\nREVOKE ALL ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() FROM authenticated;\nGRANT EXECUTE ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() TO service_role;\n"}	repair_sandi_salary_advance_july_september_fix	simplykool@gmail.com	\N	\N
20261009052404	{"-- One-time, idempotent correction for Sandi Prasetyo's July and September 2026\n-- salary advance application links. This preserves the July bank reconciliation and\n-- retains original journals as reversed with explicit replacement journals.\nCREATE OR REPLACE FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026()\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  c_staff_id CONSTANT uuid := '276dc2e0-3cb2-426f-aee7-a9991e5f4cfc';\n  c_july_expense_id CONSTANT uuid := '50da93f7-81e6-4ae7-912b-62538d97f016';\n  c_july_bank_line_id CONSTANT uuid := 'f92f9568-e361-447a-be33-a490f59e5db4';\n  c_july_bank_allocation_id CONSTANT uuid := '7f1d0ede-6e78-4cf9-be30-60c461cd6fa6';\n  c_september_expense_id CONSTANT uuid := '252040f4-bf49-463e-9af6-5bc9921a593c';\n  c_advance_012 CONSTANT uuid := '0efd7d85-6977-4bc1-b210-004e00834d88';\n  c_advance_013 CONSTANT uuid := '56acdc56-5b77-496f-a162-9f939a50aa4e';\n  c_advance_019 CONSTANT uuid := '28faa8e0-fc1c-49df-aa20-01fcec0bc62c';\n  c_settlement_021 CONSTANT uuid := 'df740056-054f-400c-8076-4fdefd6d28e0';\n  c_app_012 CONSTANT uuid := 'd125c26c-1f73-4972-a870-cd99c0c40ade';\n  c_app_013 CONSTANT uuid := '1eddf8a3-d17b-4063-b97d-f46fd9916759';\n  c_app_019 CONSTANT uuid := '00bcc331-d244-4e83-b463-5ae48ab8ca67';\n  c_idempotency CONSTANT text := 'sandi-prasetyo-salary-advance-jul-sep-2026-v1';\n\n  v_existing public.finance_historical_repair_commands%ROWTYPE;\n  v_command_id uuid;\n  v_july public.finance_expenses%ROWTYPE;\n  v_september public.finance_expenses%ROWTYPE;\n  v_settlement public.payment_vouchers%ROWTYPE;\n  v_july_source_je public.journal_entries%ROWTYPE;\n  v_september_source_je public.journal_entries%ROWTYPE;\n  v_bank_line public.bank_statement_lines%ROWTYPE;\n  v_bank_allocation public.bank_statement_allocations%ROWTYPE;\n  v_july_settlement_id uuid;\n  v_july_settlement_je_id uuid;\n  v_july_settlement_number text;\n  v_july_reversal_id uuid;\n  v_september_reversal_id uuid;\n  v_july_replacement_je_id uuid;\n  v_september_replacement_je_id uuid;\n  v_salary_coa uuid;\n  v_bank_coa uuid;\n  v_ap_coa uuid;\n  v_advance_coa uuid;\n  v_period_id uuid;\n  v_entry_number text;\n  v_line record;\n  v_line_no integer;\n  v_count integer;\n  v_debit numeric;\n  v_credit numeric;\n  v_before jsonb;\n  v_after jsonb;\nBEGIN\n  IF current_user NOT IN ('postgres', 'supabase_admin')\n     AND COALESCE(auth.role(), '') <> 'service_role'\n     AND NOT EXISTS (\n       SELECT 1 FROM public.user_profiles\n        WHERE id = auth.uid() AND is_active = true AND role = 'admin'\n     ) THEN\n    RAISE EXCEPTION 'This historical payroll repair requires a database administrator';\n  END IF;\n\n  SELECT * INTO v_existing\n    FROM public.finance_historical_repair_commands\n   WHERE idempotency_key = c_idempotency\n   FOR UPDATE;\n  IF FOUND THEN\n    RETURN jsonb_build_object(\n      'idempotent', true,\n      'command_id', v_existing.id,\n      'before', v_existing.before_state,\n      'after', v_existing.after_state\n    );\n  END IF;\n\n  SELECT * INTO v_july\n    FROM public.finance_expenses\n   WHERE id = c_july_expense_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_july.voucher_number <> 'EXP/26-26/122'\n     OR v_july.expense_category <> 'salary'\n     OR v_july.staff_id <> c_staff_id\n     OR v_july.approval_status <> 'approved'\n     OR abs(v_july.amount - 1850000) > 0.01\n     OR abs(COALESCE(v_july.paid_amount, 0) - 1850000) > 0.01 THEN\n    RAISE EXCEPTION 'July salary record no longer matches the reviewed evidence; no changes made';\n  END IF;\n\n  SELECT * INTO v_september\n    FROM public.finance_expenses\n   WHERE id = c_september_expense_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_september.voucher_number <> 'EXP/26/285'\n     OR v_september.expense_category <> 'salary'\n     OR v_september.staff_id <> c_staff_id\n     OR v_september.approval_status <> 'pending_approval'\n     OR abs(v_september.amount - 2000000) > 0.01\n     OR abs(COALESCE(v_september.paid_amount, 0) - 1150000) > 0.01 THEN\n    RAISE EXCEPTION 'September salary record no longer matches the reviewed evidence; no changes made';\n  END IF;\n\n  SELECT * INTO v_settlement\n    FROM public.payment_vouchers\n   WHERE id = c_settlement_021\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_settlement.voucher_number <> 'PV/26-26/021'\n     OR v_settlement.payment_purpose <> 'salary_advance_settlement'\n     OR v_settlement.payment_method <> 'advance_adjustment'\n     OR v_settlement.staff_id <> c_staff_id\n     OR v_settlement.is_posted IS DISTINCT FROM true\n     OR abs(v_settlement.amount - 1150000) > 0.01 THEN\n    RAISE EXCEPTION 'September settlement voucher no longer matches reviewed evidence; no changes made';\n  END IF;\n\n  SELECT * INTO v_bank_line\n    FROM public.bank_statement_lines\n   WHERE id = c_july_bank_line_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_bank_line.matched_expense_id <> c_july_expense_id\n     OR v_bank_line.transaction_date <> DATE '2026-07-31'\n     OR abs(COALESCE(v_bank_line.debit_amount, 0) - 1850000) > 0.01\n     OR v_bank_line.description NOT ILIKE '%SALARY JULI 26 SANDI PRASETYO%' THEN\n    RAISE EXCEPTION 'July bank statement evidence does not match; no changes made';\n  END IF;\n\n  SELECT * INTO v_bank_allocation\n    FROM public.bank_statement_allocations\n   WHERE id = c_july_bank_allocation_id\n   FOR UPDATE;\n  IF NOT FOUND\n     OR v_bank_allocation.bank_statement_line_id <> c_july_bank_line_id\n     OR v_bank_allocation.document_type <> 'expense'\n     OR v_bank_allocation.document_id <> c_july_expense_id\n     OR abs(v_bank_allocation.allocation_amount - 1850000) > 0.01 THEN\n    RAISE EXCEPTION 'July bank allocation is missing or changed; no changes made';\n  END IF;\n\n  SELECT je.* INTO v_july_source_je\n    FROM public.journal_entries je\n   WHERE je.id = v_bank_allocation.journal_entry_id\n     AND je.reference_id = c_july_expense_id\n     AND je.entry_number = 'JE2607-0083'\n     AND je.source_module IN ('expense', 'expenses')\n     AND je.is_posted = true\n     AND NOT COALESCE(je.is_reversed, false)\n   FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Expected active July salary journal JE2607-0083 is missing; no changes made';\n  END IF;\n\n  SELECT count(*) INTO v_count\n    FROM public.salary_advance_applications\n   WHERE id IN (c_app_012, c_app_013, c_app_019)\n     AND salary_expense_id = c_september_expense_id\n     AND settlement_payment_voucher_id = c_settlement_021;\n  IF v_count <> 3 THEN\n    RAISE EXCEPTION 'The three expected advance application links have changed; no changes made';\n  END IF;\n\n  SELECT COALESCE(sum(applied_amount), 0) INTO v_debit\n    FROM public.salary_advance_applications\n   WHERE settlement_payment_voucher_id = c_settlement_021\n     AND salary_expense_id = c_september_expense_id;\n  IF abs(v_debit - 1150000) > 0.01 THEN\n    RAISE EXCEPTION 'Expected September-linked advance applications totaling Rp1,150,000; no changes made';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.salary_advance_applications\n     WHERE advance_payment_voucher_id IN (c_advance_012, c_advance_013)\n       AND salary_expense_id <> c_september_expense_id\n  ) THEN\n    RAISE EXCEPTION 'One of the July advances is already applied elsewhere; no changes made';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-07-31' AND end_date >= DATE '2026-07-31'\n       AND status <> 'open'\n  ) OR NOT EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-07-31' AND end_date >= DATE '2026-07-31'\n       AND status = 'open'\n  ) OR EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-09-30' AND end_date >= DATE '2026-09-30'\n       AND status <> 'open'\n  ) OR NOT EXISTS (\n    SELECT 1 FROM public.accounting_periods\n     WHERE start_date <= DATE '2026-09-30' AND end_date >= DATE '2026-09-30'\n       AND status = 'open'\n  ) THEN\n    RAISE EXCEPTION 'July and September accounting periods must be open; no changes made';\n  END IF;\n\n  SELECT id INTO v_salary_coa FROM public.chart_of_accounts WHERE code = '6100' LIMIT 1;\n  SELECT id INTO v_ap_coa FROM public.chart_of_accounts WHERE code = '2110' LIMIT 1;\n  SELECT id INTO v_advance_coa FROM public.chart_of_accounts WHERE code = '1160' LIMIT 1;\n  SELECT ba.coa_id INTO v_bank_coa\n    FROM public.bank_accounts ba\n   WHERE ba.id = v_bank_line.bank_account_id;\n  IF v_salary_coa IS NULL OR v_ap_coa IS NULL OR v_advance_coa IS NULL OR v_bank_coa IS NULL THEN\n    RAISE EXCEPTION 'Required salary, AP, advance, or bank COA is missing; no changes made';\n  END IF;\n\n  IF (SELECT count(*) FROM public.journal_entry_lines WHERE journal_entry_id = v_july_source_je.id) <> 2\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_july_source_je.id AND account_id = v_salary_coa AND abs(debit - 1850000) < 0.01 AND abs(COALESCE(credit,0)) < 0.01)\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_july_source_je.id AND account_id = v_bank_coa AND abs(credit - 1850000) < 0.01 AND abs(COALESCE(debit,0)) < 0.01) THEN\n    RAISE EXCEPTION 'July salary journal is not the reviewed Dr Salary / Cr Bank entry; no changes made';\n  END IF;\n\n  SELECT je.* INTO v_september_source_je\n    FROM public.journal_entries je\n   WHERE je.id = v_settlement.journal_entry_id\n     AND je.reference_id = c_settlement_021\n     AND je.is_posted = true\n     AND NOT COALESCE(je.is_reversed, false)\n   FOR UPDATE;\n  IF NOT FOUND\n     OR (SELECT count(*) FROM public.journal_entry_lines WHERE journal_entry_id = v_september_source_je.id) <> 2\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_september_source_je.id AND account_id = v_ap_coa AND abs(debit - 1150000) < 0.01 AND abs(COALESCE(credit,0)) < 0.01)\n     OR NOT EXISTS (SELECT 1 FROM public.journal_entry_lines WHERE journal_entry_id = v_september_source_je.id AND account_id = v_advance_coa AND abs(credit - 1150000) < 0.01 AND abs(COALESCE(debit,0)) < 0.01) THEN\n    RAISE EXCEPTION 'September settlement journal is not the expected AP/advance entry; no changes made';\n  END IF;\n\n  IF (SELECT count(*) FROM public.voucher_allocations\n       WHERE payment_voucher_id = c_settlement_021\n         AND finance_expense_id = c_september_expense_id\n         AND abs(allocated_amount - 1150000) < 0.01) <> 1 THEN\n    RAISE EXCEPTION 'September settlement allocation is missing or changed; no changes made';\n  END IF;\n\n  v_before := jsonb_build_object(\n    'july_salary', to_jsonb(v_july),\n    'july_source_journal', to_jsonb(v_july_source_je),\n    'july_bank_statement_line', to_jsonb(v_bank_line),\n    'july_bank_allocation', to_jsonb(v_bank_allocation),\n    'september_salary', to_jsonb(v_september),\n    'september_settlement', to_jsonb(v_settlement),\n    'september_source_journal', to_jsonb(v_september_source_je),\n    'advance_applications', (\n      SELECT COALESCE(jsonb_agg(to_jsonb(sa) ORDER BY sa.id), '[]'::jsonb)\n        FROM public.salary_advance_applications sa\n       WHERE sa.id IN (c_app_012, c_app_013, c_app_019)\n    )\n  );\n\n  INSERT INTO public.finance_historical_repair_commands(\n    idempotency_key, document_type, document_id, bank_statement_line_id,\n    payment_kind, operation, requested_by, before_state, after_state, status\n  ) VALUES (\n    c_idempotency, 'expense', c_july_expense_id, c_july_bank_line_id,\n    'supplier', 'restate_salary_net_of_advance', auth.uid(), v_before, '{}'::jsonb, 'committed'\n  ) RETURNING id INTO v_command_id;\n\n  PERFORM set_config('app.finance_historical_repair_command', v_command_id::text, true);\n  PERFORM set_config('app.finance_historical_repair', 'on', true);\n  PERFORM set_config('app.finance_metadata_repair', 'on', true);\n\n  -- Restore the actual July gross salary while preserving the real Rp1.85m bank payout.\n  -- Existing bank allocation remains Rp1.85m; the extra Rp650k is settled against advances.\n  UPDATE public.finance_expenses\n     SET amount = 2500000,\n         paid_amount = 2500000\n   WHERE id = c_july_expense_id;\n\n  v_july_settlement_number := public.next_payment_voucher_number(DATE '2026-07-31');\n  INSERT INTO public.payment_vouchers(\n    voucher_number, voucher_date, supplier_id, payment_method, bank_account_id,\n    reference_number, amount, pph_amount, description, document_urls,\n    created_by, coa_account_id, payment_currency, exchange_rate, bank_amount,\n    bank_charge, is_posted, staff_id, currency_code, transaction_currency,\n    functional_currency, bank_account_currency, payment_purpose, invoice_currency,\n    invoice_amount, payment_amount, bank_currency, converted_amount, actual_bank_debit,\n    salary_advance_applied_amount, salary_advance_status\n  ) VALUES (\n    v_july_settlement_number, DATE '2026-07-31', NULL, 'advance_adjustment', NULL,\n    'HIST-SALARY-EXP-26-26-122', 650000, 0,\n    'Salary Advance Recovery - EXP/26-26/122 (PV/26-26/012 + PV/26-26/013)',\n    ARRAY[]::text[], v_settlement.created_by, NULL, 'IDR', 1, NULL, 0, false,\n    c_staff_id, 'IDR', 'IDR', 'IDR', 'IDR', 'salary_advance_settlement',\n    'IDR', 650000, 650000, 'IDR', 650000, NULL, 0, 'not_applicable'\n  ) RETURNING id INTO v_july_settlement_id;\n\n  -- Reverse the old July expense journal, preserving it for audit.\n  v_entry_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, v_july_source_je.entry_date, v_july_source_je.period_id,\n    'historical_repair', c_july_expense_id, 'HR-REV-JUL-' || v_command_id::text,\n    'Historical reversal of July net-salary-only posting ' || v_july_source_je.entry_number,\n    'salary_advance_restatement', v_july_source_je.total_credit, v_july_source_je.total_debit,\n    true, now(), auth.uid(), v_july_source_je.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_july_reversal_id;\n\n  v_line_no := 1;\n  FOR v_line IN\n    SELECT * FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_july_source_je.id ORDER BY line_number\n  LOOP\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      supplier_id, payee_id, transaction_currency, transaction_debit,\n      transaction_credit, functional_currency, exchange_rate\n    ) VALUES (\n      v_july_reversal_id, v_line_no, v_line.account_id,\n      'Historical reversal: ' || COALESCE(v_line.description, ''),\n      v_line.credit, v_line.debit, v_line.supplier_id, v_line.payee_id,\n      COALESCE(v_line.transaction_currency, 'IDR'),\n      COALESCE(v_line.transaction_credit, v_line.credit),\n      COALESCE(v_line.transaction_debit, v_line.debit),\n      'IDR', 1\n    );\n    v_line_no := v_line_no + 1;\n  END LOOP;\n  UPDATE public.journal_entries\n     SET is_reversed = true, reversed_by_id = v_july_reversal_id\n   WHERE id = v_july_source_je.id;\n\n  -- Replacement July journal: gross salary Rp2.5m = bank payout Rp1.85m + AP/advance recovery Rp650k.\n  v_entry_number := public.next_journal_entry_number();\n  SELECT id INTO v_period_id\n    FROM public.accounting_periods\n   WHERE start_date <= DATE '2026-07-31' AND end_date >= DATE '2026-07-31'\n   ORDER BY start_date DESC LIMIT 1;\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, DATE '2026-07-31', v_period_id, 'expenses', c_july_expense_id,\n    'EXP-' || c_july_expense_id::text,\n    'Salary July 2026 - gross Rp2,500,000; bank Rp1,850,000; advances Rp650,000',\n    'salary', 2500000, 2500000, true, now(), auth.uid(), v_july_source_je.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_july_replacement_je_id;\n\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate\n  ) VALUES\n    (v_july_replacement_je_id, 1, v_salary_coa, 'Gross July salary - Sandi Prasetyo', 2500000, 0, 'IDR', 2500000, 0, 'IDR', 1),\n    (v_july_replacement_je_id, 2, v_bank_coa, 'Actual salary bank payout - statement matched', 0, 1850000, 'IDR', 0, 1850000, 'IDR', 1),\n    (v_july_replacement_je_id, 3, v_ap_coa, 'July salary advance deduction clearing', 0, 650000, 'IDR', 0, 650000, 'IDR', 1);\n\n  UPDATE public.bank_statement_allocations\n     SET journal_entry_id = v_july_replacement_je_id\n   WHERE id = c_july_bank_allocation_id;\n\n  -- Post the internal July settlement journal: Dr AP, Cr Staff Advances.\n  v_entry_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, DATE '2026-07-31', v_period_id, 'payment', v_july_settlement_id,\n    v_july_settlement_number,\n    'Salary Advance Settlement - Sandi July advances PV/26-26/012 and PV/26-26/013',\n    'salary_advance_settlement', 650000, 650000, true, now(), auth.uid(),\n    v_settlement.created_by, 'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_july_settlement_je_id;\n\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate\n  ) VALUES\n    (v_july_settlement_je_id, 1, v_ap_coa, 'July salary payable cleared by advance deduction', 650000, 0, 'IDR', 650000, 0, 'IDR', 1),\n    (v_july_settlement_je_id, 2, v_advance_coa, 'Clear July staff advances PV/26-26/012 + PV/26-26/013', 0, 650000, 'IDR', 0, 650000, 'IDR', 1);\n\n  UPDATE public.payment_vouchers\n     SET journal_entry_id = v_july_settlement_je_id,\n         is_posted = true\n   WHERE id = v_july_settlement_id;\n\n  INSERT INTO public.voucher_allocations(\n    voucher_type, payment_voucher_id, finance_expense_id, allocated_amount,\n    allocated_currency, payment_kind\n  ) VALUES (\n    'payment', v_july_settlement_id, c_july_expense_id, 650000, 'IDR', 'supplier'\n  );\n\n  -- Reverse September's incorrect Rp1.15m settlement journal.\n  v_entry_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, v_september_source_je.entry_date, v_september_source_je.period_id,\n    'historical_repair', c_settlement_021, 'HR-REV-SEP-' || v_command_id::text,\n    'Historical reversal of overstated salary advance settlement PV/26-26/021',\n    'salary_advance_restatement', v_september_source_je.total_credit, v_september_source_je.total_debit,\n    true, now(), auth.uid(), v_september_source_je.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_september_reversal_id;\n\n  v_line_no := 1;\n  FOR v_line IN\n    SELECT * FROM public.journal_entry_lines\n     WHERE journal_entry_id = v_september_source_je.id ORDER BY line_number\n  LOOP\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      supplier_id, payee_id, transaction_currency, transaction_debit,\n      transaction_credit, functional_currency, exchange_rate\n    ) VALUES (\n      v_september_reversal_id, v_line_no, v_line.account_id,\n      'Historical reversal: ' || COALESCE(v_line.description, ''),\n      v_line.credit, v_line.debit, v_line.supplier_id, v_line.payee_id,\n      COALESCE(v_line.transaction_currency, 'IDR'),\n      COALESCE(v_line.transaction_credit, v_line.credit),\n      COALESCE(v_line.transaction_debit, v_line.debit),\n      'IDR', 1\n    );\n    v_line_no := v_line_no + 1;\n  END LOOP;\n  UPDATE public.journal_entries\n     SET is_reversed = true, reversed_by_id = v_september_reversal_id\n   WHERE id = v_september_source_je.id;\n\n  -- Corrected September settlement is Rp500k for PV/26-26/019 only.\n  v_entry_number := public.next_journal_entry_number();\n  SELECT id INTO v_period_id\n    FROM public.accounting_periods\n   WHERE start_date <= DATE '2026-09-30' AND end_date >= DATE '2026-09-30'\n   ORDER BY start_date DESC LIMIT 1;\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, transaction_category, total_debit, total_credit, is_posted, posted_at,\n    posted_by, created_by, transaction_currency, functional_currency, exchange_rate,\n    amounts_are_functional\n  ) VALUES (\n    v_entry_number, DATE '2026-09-30', v_period_id, 'payment', c_settlement_021,\n    'PV/26-26/021',\n    'Payment Voucher PV/26-26/021 - corrected September advance settlement Rp500,000',\n    'salary_advance_settlement', 500000, 500000, true, now(), auth.uid(), v_settlement.created_by,\n    'IDR', 'IDR', 1, true\n  ) RETURNING id INTO v_september_replacement_je_id;\n\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, functional_currency, exchange_rate\n  ) VALUES\n    (v_september_replacement_je_id, 1, v_ap_coa, 'Salary payable cleared by September advance', 500000, 0, 'IDR', 500000, 0, 'IDR', 1),\n    (v_september_replacement_je_id, 2, v_advance_coa, 'Clear September staff advance PV/26-26/019', 0, 500000, 'IDR', 0, 500000, 'IDR', 1);\n\n  -- Move the two July advance links to the July salary; keep September PV/021 linked only to PV/019.\n  UPDATE public.salary_advance_applications\n     SET salary_expense_id = c_july_expense_id,\n         settlement_payment_voucher_id = v_july_settlement_id\n   WHERE id IN (c_app_012, c_app_013)\n     AND salary_expense_id = c_september_expense_id\n     AND settlement_payment_voucher_id = c_settlement_021;\n  GET DIAGNOSTICS v_count = ROW_COUNT;\n  IF v_count <> 2 THEN\n    RAISE EXCEPTION 'Expected to move exactly two July advance links; transaction rolled back';\n  END IF;\n\n  UPDATE public.payment_vouchers\n     SET amount = 500000,\n         invoice_amount = 500000,\n         payment_amount = 500000,\n         converted_amount = 500000,\n         bank_amount = NULL,\n         actual_bank_debit = NULL,\n         journal_entry_id = v_september_replacement_je_id,\n         is_posted = true\n   WHERE id = c_settlement_021;\n\n  UPDATE public.voucher_allocations\n     SET allocated_amount = 500000,\n         allocated_currency = 'IDR'\n   WHERE payment_voucher_id = c_settlement_021\n     AND finance_expense_id = c_september_expense_id\n     AND abs(allocated_amount - 1150000) < 0.01;\n\n  -- Add explicit audit rows for the reclassified application links and corrected settlement.\n  INSERT INTO public.audit_logs(table_name, record_id, action_type, old_values, new_values, user_id)\n  VALUES\n    ('salary_advance_applications', c_app_012, 'update',\n     jsonb_build_object('salary_expense_id', c_september_expense_id, 'settlement_payment_voucher_id', c_settlement_021, 'applied_amount', 500000),\n     jsonb_build_object('salary_expense_id', c_july_expense_id, 'settlement_payment_voucher_id', v_july_settlement_id, 'applied_amount', 500000),\n     auth.uid()),\n    ('salary_advance_applications', c_app_013, 'update',\n     jsonb_build_object('salary_expense_id', c_september_expense_id, 'settlement_payment_voucher_id', c_settlement_021, 'applied_amount', 150000),\n     jsonb_build_object('salary_expense_id', c_july_expense_id, 'settlement_payment_voucher_id', v_july_settlement_id, 'applied_amount', 150000),\n     auth.uid()),\n    ('payment_vouchers', c_settlement_021, 'update',\n     jsonb_build_object('amount', 1150000, 'net_amount', 1150000, 'journal_entry_id', v_september_source_je.id, 'description', v_settlement.description),\n     jsonb_build_object('amount', 500000, 'net_amount', 500000, 'journal_entry_id', v_september_replacement_je_id, 'description', v_settlement.description),\n     auth.uid());\n\n  PERFORM public.refresh_salary_advance_status(c_advance_012);\n  PERFORM public.refresh_salary_advance_status(c_advance_013);\n  PERFORM public.refresh_salary_advance_status(c_advance_019);\n\n  -- Final exact balance/state values after allocation and advance links are moved.\n  UPDATE public.finance_expenses SET paid_amount = 2500000 WHERE id = c_july_expense_id;\n  UPDATE public.finance_expenses SET paid_amount = 500000 WHERE id = c_september_expense_id;\n\n  SELECT COALESCE(sum(debit), 0), COALESCE(sum(credit), 0)\n    INTO v_debit, v_credit\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id = v_july_replacement_je_id;\n  IF abs(v_debit - 2500000) > 0.01 OR abs(v_credit - 2500000) > 0.01 THEN\n    RAISE EXCEPTION 'Corrected July salary journal does not balance; transaction rolled back';\n  END IF;\n\n  SELECT COALESCE(sum(debit), 0), COALESCE(sum(credit), 0)\n    INTO v_debit, v_credit\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id = v_september_replacement_je_id;\n  IF abs(v_debit - 500000) > 0.01 OR abs(v_credit - 500000) > 0.01 THEN\n    RAISE EXCEPTION 'Corrected September settlement journal does not balance; transaction rolled back';\n  END IF;\n\n  IF (SELECT count(*) FROM public.salary_advance_applications\n       WHERE salary_expense_id = c_july_expense_id\n         AND advance_payment_voucher_id IN (c_advance_012, c_advance_013)\n         AND settlement_payment_voucher_id = v_july_settlement_id) <> 2\n     OR (SELECT count(*) FROM public.salary_advance_applications\n       WHERE salary_expense_id = c_september_expense_id\n         AND advance_payment_voucher_id = c_advance_019\n         AND settlement_payment_voucher_id = c_settlement_021\n         AND abs(applied_amount - 500000) < 0.01) <> 1\n     OR (SELECT count(*) FROM public.salary_advance_applications\n       WHERE salary_expense_id = c_september_expense_id\n         AND advance_payment_voucher_id IN (c_advance_012, c_advance_013)) <> 0 THEN\n    RAISE EXCEPTION 'Final advance links failed verification; transaction rolled back';\n  END IF;\n\n  v_after := jsonb_build_object(\n    'july_salary_voucher', 'EXP/26-26/122',\n    'july_gross_salary', 2500000,\n    'july_bank_payout_preserved', 1850000,\n    'july_advance_deduction', 650000,\n    'july_reversal_journal_id', v_july_reversal_id,\n    'july_replacement_journal_id', v_july_replacement_je_id,\n    'july_settlement_voucher_id', v_july_settlement_id,\n    'july_settlement_voucher_number', v_july_settlement_number,\n    'september_salary_voucher', 'EXP/26/285',\n    'september_gross_salary', 2000000,\n    'september_advance_deduction', 500000,\n    'september_net_payable', 1500000,\n    'september_reversal_journal_id', v_september_reversal_id,\n    'september_replacement_journal_id', v_september_replacement_je_id,\n    'july_bank_allocation_id_preserved', c_july_bank_allocation_id,\n    'advance_applications', (\n      SELECT COALESCE(jsonb_agg(jsonb_build_object(\n        'advance', av.voucher_number,\n        'salary', fe.voucher_number,\n        'amount', sa.applied_amount,\n        'settlement', settlement.voucher_number\n      ) ORDER BY av.voucher_number), '[]'::jsonb)\n      FROM public.salary_advance_applications sa\n      JOIN public.payment_vouchers av ON av.id = sa.advance_payment_voucher_id\n      JOIN public.finance_expenses fe ON fe.id = sa.salary_expense_id\n      JOIN public.payment_vouchers settlement ON settlement.id = sa.settlement_payment_voucher_id\n      WHERE sa.id IN (c_app_012, c_app_013, c_app_019)\n    )\n  );\n\n  UPDATE public.finance_historical_repair_commands\n     SET before_state = v_before,\n         after_state = v_after,\n         created_allocation_id = c_july_bank_allocation_id\n   WHERE id = v_command_id;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'command_id', v_command_id,\n    'before', v_before,\n    'after', v_after\n  );\nEND;\n$function$;\n\nREVOKE ALL ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() FROM anon;\nREVOKE ALL ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() FROM authenticated;\nGRANT EXECUTE ON FUNCTION public.repair_sandi_prasetyo_salary_advance_history_2026() TO service_role;\n"}	repair_sandi_salary_advance_july_september_fix_generated_totals	simplykool@gmail.com	\N	\N
20261009061113	{"-- Direction-aware commercial FX reference for Sales Orders.\n-- Keep commercial_usd_to_idr_rate as the normalized USD/IDR basis used by\n-- the FX Business Dashboard. IDR-denominated Sales Orders also store the\n-- reciprocal IDR/USD rate shown to the user.\nALTER TABLE public.sales_orders\n  ADD COLUMN IF NOT EXISTS commercial_idr_to_usd_rate numeric;\n\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_constraint\n    WHERE conrelid = 'public.sales_orders'::regclass\n      AND conname = 'sales_orders_commercial_idr_to_usd_rate_positive'\n  ) THEN\n    ALTER TABLE public.sales_orders\n      ADD CONSTRAINT sales_orders_commercial_idr_to_usd_rate_positive\n      CHECK (commercial_idr_to_usd_rate IS NULL OR commercial_idr_to_usd_rate > 0)\n      NOT VALID;\n  END IF;\nEND $$;\n\nALTER TABLE public.sales_orders\n  VALIDATE CONSTRAINT sales_orders_commercial_idr_to_usd_rate_positive;\n\nCREATE OR REPLACE FUNCTION public.update_sales_order_commercial_fx_rate(\n  p_so_id uuid,\n  p_new_rate numeric,\n  p_reason text DEFAULT 'Historical commercial FX rate backfill'\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_so public.sales_orders%ROWTYPE;\n  v_user_id uuid := auth.uid();\n  v_user_email text;\n  v_old_usd_to_idr numeric;\n  v_old_idr_to_usd numeric;\n  v_new_usd_to_idr numeric;\n  v_new_idr_to_usd numeric;\n  v_currency text;\n  v_direction text;\nBEGIN\n  IF v_user_id IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1 FROM public.user_profiles\n    WHERE id = v_user_id AND role IN ('admin', 'manager', 'accounts', 'sales')\n  ) THEN\n    RAISE EXCEPTION 'Unauthorized to modify commercial rates';\n  END IF;\n\n  SELECT * INTO v_so\n    FROM public.sales_orders\n   WHERE id = p_so_id\n   FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Sales order not found');\n  END IF;\n\n  IF p_new_rate IS NULL OR p_new_rate <= 0 THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Commercial exchange rate must be positive');\n  END IF;\n\n  v_currency := upper(COALESCE(v_so.currency, 'IDR'));\n  v_old_usd_to_idr := v_so.commercial_usd_to_idr_rate;\n  v_old_idr_to_usd := v_so.commercial_idr_to_usd_rate;\n\n  IF v_currency = 'IDR' THEN\n    IF p_new_rate >= 1 THEN\n      RETURN jsonb_build_object(\n        'success', false,\n        'error', 'IDR Sales Orders require an IDR→USD rate below 1, for example 0.000058'\n      );\n    END IF;\n    v_direction := 'IDR_TO_USD';\n    v_new_idr_to_usd := p_new_rate;\n    -- The normalized USD→IDR market reference remains available for downstream FX reporting.\n    v_new_usd_to_idr := round(1 / p_new_rate, 6);\n  ELSE\n    IF p_new_rate < 1 THEN\n      RETURN jsonb_build_object(\n        'success', false,\n        'error', 'USD Sales Orders require a USD→IDR rate, for example 17850'\n      );\n    END IF;\n    v_direction := 'USD_TO_IDR';\n    v_new_usd_to_idr := p_new_rate;\n    v_new_idr_to_usd := NULL;\n  END IF;\n\n  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;\n\n  UPDATE public.sales_orders\n     SET commercial_usd_to_idr_rate = v_new_usd_to_idr,\n         commercial_idr_to_usd_rate = v_new_idr_to_usd,\n         updated_at = now()\n   WHERE id = p_so_id;\n\n  INSERT INTO public.audit_logs (\n    table_name, record_id, action_type, old_values, new_values,\n    changed_fields, user_id, user_email, created_at\n  ) VALUES (\n    'sales_orders',\n    p_so_id,\n    'update',\n    jsonb_build_object(\n      'so_number', v_so.so_number,\n      'currency', v_currency,\n      'total_amount', v_so.total_amount,\n      'commercial_usd_to_idr_rate', v_old_usd_to_idr,\n      'commercial_idr_to_usd_rate', v_old_idr_to_usd\n    ),\n    jsonb_build_object(\n      'so_number', v_so.so_number,\n      'currency', v_currency,\n      'total_amount', v_so.total_amount,\n      'commercial_usd_to_idr_rate', v_new_usd_to_idr,\n      'commercial_idr_to_usd_rate', v_new_idr_to_usd,\n      'rate_direction', v_direction,\n      'reason', COALESCE(NULLIF(trim(p_reason), ''), 'Commercial FX rate update')\n    ),\n    ARRAY['commercial_usd_to_idr_rate','commercial_idr_to_usd_rate'],\n    v_user_id,\n    v_user_email,\n    now()\n  );\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'so_id', p_so_id,\n    'so_number', v_so.so_number,\n    'currency', v_currency,\n    'rate_direction', v_direction,\n    'usd_to_idr_rate', v_new_usd_to_idr,\n    'idr_to_usd_rate', v_new_idr_to_usd,\n    'reason', p_reason\n  );\nEND;\n$function$;\n\nREVOKE ALL ON FUNCTION public.update_sales_order_commercial_fx_rate(uuid, numeric, text) FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.update_sales_order_commercial_fx_rate(uuid, numeric, text) FROM anon;\nGRANT EXECUTE ON FUNCTION public.update_sales_order_commercial_fx_rate(uuid, numeric, text) TO authenticated, service_role;\n"}	add_directional_sales_order_fx	simplykool@gmail.com	\N	\N
20261009061829	{"-- Revert the unrequested schema change added for a UI redesign.\n-- No values were written to commercial_idr_to_usd_rate; the data correction\n-- should continue using the existing commercial_usd_to_idr_rate field only.\nDROP FUNCTION IF EXISTS public.update_sales_order_commercial_fx_rate(uuid, numeric, text);\nALTER TABLE public.sales_orders\n  DROP CONSTRAINT IF EXISTS sales_orders_commercial_idr_to_usd_rate_positive;\nALTER TABLE public.sales_orders\n  DROP COLUMN IF EXISTS commercial_idr_to_usd_rate;\n"}	revert_unrequested_directional_sales_order_fx	simplykool@gmail.com	\N	\N
20261012180000	{"-- Description: Allow safe salary expense amount edits for approved and unapproved expenses with applied advances\n-- Preserves accounting controls: prevents staff reassignment, category modification, and reducing gross below committed advances and bank payouts.\n\nBEGIN;\n\nCREATE OR REPLACE FUNCTION public.prevent_unsafe_settled_salary_edit()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_advance_applied numeric := 0;\n  v_bank_allocated numeric := 0;\n  v_direct_bank numeric := 0;\n  v_voucher_paid numeric := 0;\n  v_non_advance_paid numeric := 0;\n  v_committed_total numeric := 0;\nBEGIN\n  -- Only applies to salary expenses that have applied salary advances\n  IF OLD.expense_category = 'salary'\n     AND EXISTS (\n       SELECT 1\n       FROM public.salary_advance_applications sa\n       WHERE sa.salary_expense_id = OLD.id\n     ) THEN\n\n    -- 1. Staff change is NEVER allowed while advances are applied\n    IF OLD.staff_id IS DISTINCT FROM NEW.staff_id THEN\n      RAISE EXCEPTION 'Salary % has applied advance settlements for the assigned staff member and cannot be reassigned to a different employee. Reverse or remove the advance application first.',\n        COALESCE(OLD.voucher_number, OLD.id::text)\n        USING ERRCODE = 'check_violation';\n    END IF;\n\n    -- 2. Expense category change is NEVER allowed while advances are applied\n    IF NEW.expense_category <> 'salary' THEN\n      RAISE EXCEPTION 'Salary % has applied advance settlements and cannot have its category changed. Reverse or remove the advance application first.',\n        COALESCE(OLD.voucher_number, OLD.id::text)\n        USING ERRCODE = 'check_violation';\n    END IF;\n\n    -- Calculate total advance applied to this salary\n    SELECT COALESCE(sum(sa.applied_amount), 0)\n      INTO v_advance_applied\n      FROM public.salary_advance_applications sa\n     WHERE sa.salary_expense_id = OLD.id;\n\n    -- Calculate non-advance payments already committed/disbursed\n    SELECT COALESCE(sum(va.allocated_amount), 0)\n      INTO v_voucher_paid\n      FROM public.voucher_allocations va\n      JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n     WHERE va.finance_expense_id = OLD.id\n       AND COALESCE(va.payment_kind, 'supplier') = 'supplier'\n       AND COALESCE(pv.payment_purpose, 'general') NOT IN ('salary_advance', 'salary_advance_settlement')\n       AND pv.is_posted = true;\n\n    SELECT COALESCE(sum(bsa.allocation_amount), 0)\n      INTO v_bank_allocated\n      FROM public.bank_statement_allocations bsa\n     WHERE bsa.document_type = 'expense'\n       AND bsa.document_id = OLD.id\n       AND COALESCE(bsa.payment_kind, 'supplier') = 'supplier';\n\n    SELECT COALESCE(sum(COALESCE(NULLIF(bsl.debit_amount, 0), bsl.credit_amount, 0)), 0)\n      INTO v_direct_bank\n      FROM public.bank_statement_lines bsl\n     WHERE bsl.matched_expense_id = OLD.id\n       AND bsl.payment_kind = 'supplier'\n       AND NOT EXISTS (\n         SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id = bsl.id\n       );\n\n    v_non_advance_paid := v_voucher_paid + v_bank_allocated + v_direct_bank;\n    v_committed_total := v_advance_applied + v_non_advance_paid + COALESCE(NEW.pph_amount, 0);\n\n    -- 3. Gross amount cannot be reduced below the committed total (applied advances + actual disbursements + tax)\n    IF NEW.amount < v_committed_total - 0.01 THEN\n      RAISE EXCEPTION 'Cannot reduce salary % gross amount to %: % is already committed (% applied advances, % bank/payment disbursements, % withholding tax). Adjust or reverse the advance settlement or unlink bank transactions before reducing below the committed amount.',\n        COALESCE(OLD.voucher_number, OLD.id::text),\n        to_char(NEW.amount, 'FM999,999,999,999.00'),\n        to_char(v_committed_total, 'FM999,999,999,999.00'),\n        to_char(v_advance_applied, 'FM999,999,999,999.00'),\n        to_char(v_non_advance_paid, 'FM999,999,999,999.00'),\n        to_char(COALESCE(NEW.pph_amount, 0), 'FM999,999,999,999.00')\n        USING ERRCODE = 'check_violation';\n    END IF;\n\n    -- 4. If bank account is being changed while active bank statement allocations exist:\n    IF (OLD.bank_account_id IS DISTINCT FROM NEW.bank_account_id)\n       AND (v_bank_allocated > 0 OR v_direct_bank > 0) THEN\n      RAISE EXCEPTION 'Salary % has % in reconciled/linked bank statement allocations. Unlink the bank statement line before changing the bank account.',\n        COALESCE(OLD.voucher_number, OLD.id::text),\n        to_char(v_bank_allocated + v_direct_bank, 'FM999,999,999,999.00')\n        USING ERRCODE = 'check_violation';\n    END IF;\n\n  END IF;\n\n  RETURN NEW;\nEND;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.recalculate_expense_payment_state(p_expense_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_supplier_paid numeric := 0;\n  v_pph_paid numeric := 0;\n  v_payable numeric := 0;\n  v_target_paid numeric;\n  v_target_pph_paid numeric;\nBEGIN\n  IF public.historical_repair_context_active() THEN RETURN; END IF;\n\n  SELECT COALESCE(sum(va.allocated_amount),0) INTO v_supplier_paid\n    FROM public.voucher_allocations va\n    LEFT JOIN public.payment_vouchers pv ON pv.id=va.payment_voucher_id\n   WHERE va.finance_expense_id=p_expense_id\n     AND COALESCE(va.payment_kind,'supplier')='supplier'\n     AND COALESCE(pv.payment_purpose,'general') NOT IN ('salary_advance','salary_advance_settlement');\n\n  SELECT v_supplier_paid+COALESCE(sum(allocation_amount),0) INTO v_supplier_paid\n    FROM public.bank_statement_allocations\n   WHERE document_type='expense' AND document_id=p_expense_id\n     AND COALESCE(payment_kind,'supplier')='supplier';\n\n  SELECT v_supplier_paid+COALESCE(sum(COALESCE(NULLIF(b.debit_amount,0),b.credit_amount,0)),0) INTO v_supplier_paid\n    FROM public.bank_statement_lines b\n   WHERE b.matched_expense_id=p_expense_id AND b.payment_kind='supplier'\n     AND NOT EXISTS (SELECT 1 FROM public.bank_statement_allocations a WHERE a.bank_statement_line_id=b.id);\n\n  -- Include posted salary advance applications (advance recovery)\n  SELECT v_supplier_paid+COALESCE(sum(sa.applied_amount),0) INTO v_supplier_paid\n    FROM public.salary_advance_applications sa\n    JOIN public.payment_vouchers settlement ON settlement.id = sa.settlement_payment_voucher_id\n   WHERE sa.salary_expense_id = p_expense_id AND settlement.is_posted = true;\n\n  SELECT COALESCE(sum(allocated_amount),0) INTO v_pph_paid\n    FROM public.voucher_allocations va\n    LEFT JOIN public.payment_vouchers pv ON pv.id=va.payment_voucher_id\n   WHERE va.finance_expense_id=p_expense_id AND va.payment_kind='pph23'\n     AND (va.payment_voucher_id IS NULL OR pv.is_posted = true);\n\n  SELECT v_pph_paid+COALESCE(sum(allocation_amount),0) INTO v_pph_paid\n    FROM public.bank_statement_allocations\n   WHERE document_type='expense' AND document_id=p_expense_id AND payment_kind='pph23';\n\n  v_payable := COALESCE(public.calculate_finance_expense_payable(p_expense_id),0);\n  v_target_paid := LEAST(GREATEST(v_supplier_paid,0),GREATEST(v_payable,0));\n  v_target_pph_paid := GREATEST(v_pph_paid,0);\n\n  UPDATE public.finance_expenses\n     SET paid_amount=v_target_paid,\n         pph_paid_amount=v_target_pph_paid\n   WHERE id=p_expense_id\n     AND (paid_amount IS DISTINCT FROM v_target_paid OR pph_paid_amount IS DISTINCT FROM v_target_pph_paid);\nEND;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.trg_salary_advance_application_recalc()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    PERFORM public.recalculate_expense_payment_state(OLD.salary_expense_id);\n    RETURN OLD;\n  ELSE\n    PERFORM public.recalculate_expense_payment_state(NEW.salary_expense_id);\n    RETURN NEW;\n  END IF;\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS trg_salary_advance_application_recalc ON public.salary_advance_applications;\nCREATE TRIGGER trg_salary_advance_application_recalc\n  AFTER INSERT OR UPDATE OR DELETE ON public.salary_advance_applications\n  FOR EACH ROW EXECUTE FUNCTION public.trg_salary_advance_application_recalc();\n\nREVOKE ALL ON FUNCTION public.prevent_unsafe_settled_salary_edit() FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION public.prevent_unsafe_settled_salary_edit() TO authenticated, service_role;\n\nREVOKE ALL ON FUNCTION public.recalculate_expense_payment_state(uuid) FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION public.recalculate_expense_payment_state(uuid) TO authenticated, service_role;\n\nREVOKE ALL ON FUNCTION public.trg_salary_advance_application_recalc() FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION public.trg_salary_advance_application_recalc() TO authenticated, service_role;\n\nNOTIFY pgrst, 'reload schema';\n\nCOMMIT;\n"}	allow_safe_approved_salary_expense_amount_edit	admin	\N	\N
20260921130000	{"-- Migration: 20260921130000_dynamic_landed_cost_and_cogs_engine.sql\n-- Description: Dynamic landed cost and sales COGS recalculation engine for SAPJ.\n--              Automatically recalculates batch landed costs and propagates deltas to sales COGS\n--              whenever import expenses are created, edited, deleted, approved, or reclassified.\n\nBEGIN","-- 1. Helper to calculate container landed cost pool (filtering out cancelled/rejected expenses)\nCREATE OR REPLACE FUNCTION public.calculate_container_landed_cost_pool(p_container_id uuid)\nRETURNS numeric\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_expenses numeric := 0;\n  v_petty numeric := 0;\n  v_other numeric := 0;\nBEGIN\n  SELECT COALESCE(other_import_costs, 0) INTO v_other\n    FROM public.import_containers\n   WHERE id = p_container_id;\n\n  SELECT COALESCE(SUM(CASE\n    WHEN fe.expense_category = 'import_broker' THEN\n      fe.amount - COALESCE(fe.ppn_amount, 0)\n      + COALESCE((SELECT SUM(\n        CASE WHEN (x->>'invoice_amount_authoritative')::boolean = true THEN (x->>'amount')::numeric\n             ELSE COALESCE(NULLIF((x->>'amount')::numeric, 0), (x->>'dpp_amount')::numeric + COALESCE((x->>'ppn_amount')::numeric, 0)) END\n        - COALESCE((x->>'ppn_amount')::numeric, 0)) FROM jsonb_array_elements(fe.broker_items) x), 0)\n      + COALESCE(fe.stamp_duty_amount, 0)\n    ELSE fe.amount END), 0)\n    INTO v_expenses\n    FROM public.finance_expenses fe\n   WHERE fe.import_container_id = p_container_id\n     AND public.is_capitalizable_landed_cost_category(fe.expense_category)\n     AND COALESCE(fe.include_in_landed_cost, true) = true\n     AND COALESCE(fe.approval_status, 'approved') NOT IN ('cancelled', 'rejected');\n\n  SELECT COALESCE(SUM(amount), 0) INTO v_petty\n    FROM public.petty_cash_transactions\n   WHERE import_container_id = p_container_id\n     AND public.is_capitalizable_landed_cost_category(expense_category)\n     AND COALESCE(include_in_landed_cost, true) = true\n     AND COALESCE(approval_status, 'approved') NOT IN ('cancelled', 'rejected');\n\n  RETURN v_expenses + v_petty + v_other;\nEND;\n$$","-- 2. Helper to calculate direct landed cost linked to a specific batch\nCREATE OR REPLACE FUNCTION public.calculate_batch_direct_landed_cost(p_batch_id uuid)\nRETURNS numeric\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\n  SELECT COALESCE(SUM(CASE\n    WHEN fe.expense_category = 'import_broker' THEN\n      fe.amount - COALESCE(fe.ppn_amount, 0)\n      + COALESCE((SELECT SUM(\n        CASE WHEN (x->>'invoice_amount_authoritative')::boolean = true THEN (x->>'amount')::numeric\n             ELSE COALESCE(NULLIF((x->>'amount')::numeric, 0), (x->>'dpp_amount')::numeric + COALESCE((x->>'ppn_amount')::numeric, 0)) END\n        - COALESCE((x->>'ppn_amount')::numeric, 0)) FROM jsonb_array_elements(fe.broker_items) x), 0)\n      + COALESCE(fe.stamp_duty_amount, 0)\n    ELSE fe.amount END), 0)\n  FROM public.finance_expenses fe\n  WHERE fe.batch_id = p_batch_id\n    AND public.is_capitalizable_landed_cost_category(fe.expense_category)\n    AND COALESCE(fe.include_in_landed_cost, true) = true\n    AND COALESCE(fe.approval_status, 'approved') NOT IN ('cancelled', 'rejected');\n$$","-- 3. Enhanced Core procedure to revalue sales COGS when a batch cost changes\nCREATE OR REPLACE FUNCTION public.propagate_batch_cost_change(p_batch_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_batch public.batches%ROWTYPE;\n  v_new_unit_cost numeric;\n  v_inv record;\n  v_item record;\n  v_target_item_cogs numeric;\n  v_target_total numeric;\n  v_posted_gl numeric;\n  v_inv_delta numeric;\n  v_item_delta numeric;\n  v_running_delta numeric;\n  v_item_count integer;\n  v_item_idx integer;\n  v_je_id uuid;\n  v_je_number text;\n  v_entry_date date;\n  v_period_id uuid;\n  v_period_status text;\n  v_source_module text;\n  v_description text;\n  v_base_ref_num text;\n  v_ref_num text;\n  v_counter integer;\n  v_cogs_account_id uuid;\n  v_inventory_account_id uuid;\n  v_line_number integer;\n  v_adjusted_invoices_count integer := 0;\n  v_adjusted_items_count integer := 0;\n  v_total_delta_posted numeric := 0;\nBEGIN\n  -- Prevent trigger cascades while allowing normal execution\n  IF current_setting('app.in_cogs_propagation', true) = 'on' THEN\n    RETURN jsonb_build_object('success', true, 'message', 'Propagation already active in current session');\n  END IF;\n\n  PERFORM set_config('app.in_cogs_propagation', 'on', true);\n\n  SELECT * INTO v_batch FROM public.batches WHERE id = p_batch_id FOR UPDATE;\n  IF NOT FOUND THEN\n    PERFORM set_config('app.in_cogs_propagation', 'off', true);\n    RETURN jsonb_build_object('success', false, 'error', 'Batch not found');\n  END IF;\n\n  v_new_unit_cost := public.calculate_batch_authoritative_cost(v_batch);\n  IF v_new_unit_cost IS NULL OR v_new_unit_cost <= 0 THEN\n    PERFORM set_config('app.in_cogs_propagation', 'off', true);\n    RETURN jsonb_build_object('success', true, 'message', 'Batch has zero or uncosted basis; skipping propagation');\n  END IF;\n\n  SELECT id INTO v_cogs_account_id FROM public.chart_of_accounts WHERE code = '5100' LIMIT 1;\n  SELECT id INTO v_inventory_account_id FROM public.chart_of_accounts WHERE code = '1130' LIMIT 1;\n  IF v_cogs_account_id IS NULL OR v_inventory_account_id IS NULL THEN\n    PERFORM set_config('app.in_cogs_propagation', 'off', true);\n    RAISE EXCEPTION 'Missing COGS (5100) or Inventory (1130) account in chart_of_accounts';\n  END IF;\n\n  -- Iterate through each posted sales invoice containing items from this batch\n  FOR v_inv IN\n    SELECT DISTINCT si.id, si.invoice_number, si.invoice_date, si.customer_id, si.created_by\n      FROM public.sales_invoices si\n      JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id\n     WHERE sii.batch_id = p_batch_id\n       AND NOT COALESCE(si.is_draft, false)\n     ORDER BY si.invoice_date ASC, si.id ASC\n  LOOP\n    -- Calculate invoice target COGS across all lines\n    SELECT COALESCE(SUM(sii_all.quantity * public.calculate_batch_authoritative_cost(b_all)), 0),\n           COUNT(sii_all.id)\n      INTO v_target_total, v_item_count\n      FROM public.sales_invoice_items sii_all\n      JOIN public.batches b_all ON b_all.id = sii_all.batch_id\n     WHERE sii_all.invoice_id = v_inv.id;\n\n    -- Calculate total posted GL 5100 for this invoice across all active journals\n    SELECT COALESCE(SUM(jel.debit - jel.credit), 0)\n      INTO v_posted_gl\n      FROM public.journal_entries je\n      JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n      JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n     WHERE je.reference_id = v_inv.id\n       AND coa.code = '5100'\n       AND je.is_posted = true\n       AND NOT COALESCE(je.is_reversed, false);\n\n    v_inv_delta := ROUND(v_target_total - v_posted_gl, 2);\n\n    IF ABS(v_inv_delta) >= 0.01 THEN\n      SELECT ap.status INTO v_period_status\n        FROM public.accounting_periods ap\n       WHERE ap.start_date <= v_inv.invoice_date AND ap.end_date >= v_inv.invoice_date\n       ORDER BY ap.start_date DESC LIMIT 1;\n\n      IF v_period_status = 'open' THEN\n        v_entry_date := v_inv.invoice_date;\n      ELSE\n        v_entry_date := CURRENT_DATE;\n      END IF;\n\n      SELECT id INTO v_period_id\n        FROM public.accounting_periods\n       WHERE start_date <= v_entry_date AND end_date >= v_entry_date\n       ORDER BY start_date DESC LIMIT 1;\n\n      IF EXISTS (\n        SELECT 1 FROM public.journal_entries\n         WHERE source_module IN ('sales_invoice_cogs', 'historical_cogs_entry', 'sales_invoice_cogs_adjustment')\n           AND reference_id = v_inv.id\n           AND is_posted = true\n           AND NOT COALESCE(is_reversed, false)\n      ) THEN\n        v_source_module := 'sales_invoice_cogs_adjustment';\n        v_description := 'COGS True-Up: ' || v_inv.invoice_number || ' (Batch ' || v_batch.batch_number || ' cost update)';\n        v_base_ref_num := v_inv.invoice_number || '-ADJ-' || v_batch.batch_number;\n        v_ref_num := v_base_ref_num;\n        v_counter := 2;\n        WHILE EXISTS (\n          SELECT 1 FROM public.journal_entries\n           WHERE source_module = v_source_module\n             AND reference_number = v_ref_num\n             AND NOT COALESCE(is_reversed, false)\n        ) LOOP\n          v_ref_num := v_base_ref_num || '-' || v_counter;\n          v_counter := v_counter + 1;\n        END LOOP;\n      ELSE\n        v_source_module := 'sales_invoice_cogs';\n        v_description := 'COGS for Sales Invoice: ' || v_inv.invoice_number;\n        v_ref_num := v_inv.invoice_number;\n      END IF;\n\n      v_je_number := public.next_journal_entry_number();\n\n      INSERT INTO public.journal_entries (\n        entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n        description, total_debit, total_credit, is_posted, posted_by, created_by\n      ) VALUES (\n        v_je_number, v_entry_date, v_period_id, v_source_module, v_inv.id, v_ref_num,\n        v_description, ABS(v_inv_delta), ABS(v_inv_delta),\n        true, COALESCE(auth.uid(), v_inv.created_by), COALESCE(auth.uid(), v_inv.created_by)\n      ) RETURNING id INTO v_je_id;\n\n      v_line_number := 1;\n      v_running_delta := 0;\n      v_item_idx := 0;\n\n      FOR v_item IN\n        SELECT sii.id, sii.quantity, sii.batch_id,\n               ROUND(sii.quantity * public.calculate_batch_authoritative_cost(b), 2) as item_target_cogs\n          FROM public.sales_invoice_items sii\n          JOIN public.batches b ON b.id = sii.batch_id\n         WHERE sii.invoice_id = v_inv.id\n         ORDER BY sii.id\n      LOOP\n        v_item_idx := v_item_idx + 1;\n        IF v_item_idx = v_item_count THEN\n          v_item_delta := v_inv_delta - v_running_delta;\n        ELSE\n          IF v_target_total > 0 THEN\n            v_item_delta := ROUND(v_inv_delta * (v_item.item_target_cogs / v_target_total), 2);\n          ELSE\n            v_item_delta := ROUND(v_inv_delta / v_item_count, 2);\n          END IF;\n          v_running_delta := v_running_delta + v_item_delta;\n        END IF;\n\n        IF ABS(v_item_delta) >= 0.01 THEN\n          IF v_item_delta > 0 THEN\n            -- Increase COGS: Debit 5100 COGS, Credit 1130 Inventory\n            INSERT INTO public.journal_entry_lines (\n              journal_entry_id, line_number, account_id, description, debit, credit,\n              customer_id, batch_id, sales_invoice_item_id\n            ) VALUES (\n              v_je_id, v_line_number, v_cogs_account_id,\n              'COGS adjustment - ' || v_inv.invoice_number, v_item_delta, 0,\n              v_inv.customer_id, v_item.batch_id, v_item.id\n            );\n            v_line_number := v_line_number + 1;\n\n            INSERT INTO public.journal_entry_lines (\n              journal_entry_id, line_number, account_id, description, debit, credit,\n              customer_id, batch_id, sales_invoice_item_id\n            ) VALUES (\n              v_je_id, v_line_number, v_inventory_account_id,\n              'Inventory revaluation - ' || v_inv.invoice_number, 0, v_item_delta,\n              v_inv.customer_id, v_item.batch_id, v_item.id\n            );\n            v_line_number := v_line_number + 1;\n          ELSE\n            -- Downward adjustment: Debit 1130 Inventory, Credit 5100 COGS\n            INSERT INTO public.journal_entry_lines (\n              journal_entry_id, line_number, account_id, description, debit, credit,\n              customer_id, batch_id, sales_invoice_item_id\n            ) VALUES (\n              v_je_id, v_line_number, v_inventory_account_id,\n              'Inventory revaluation (downward) - ' || v_inv.invoice_number, ABS(v_item_delta), 0,\n              v_inv.customer_id, v_item.batch_id, v_item.id\n            );\n            v_line_number := v_line_number + 1;\n\n            INSERT INTO public.journal_entry_lines (\n              journal_entry_id, line_number, account_id, description, debit, credit,\n              customer_id, batch_id, sales_invoice_item_id\n            ) VALUES (\n              v_je_id, v_line_number, v_cogs_account_id,\n              'COGS adjustment (downward) - ' || v_inv.invoice_number, 0, ABS(v_item_delta),\n              v_inv.customer_id, v_item.batch_id, v_item.id\n            );\n            v_line_number := v_line_number + 1;\n          END IF;\n\n          v_adjusted_items_count := v_adjusted_items_count + 1;\n        END IF;\n      END LOOP;\n\n      v_adjusted_invoices_count := v_adjusted_invoices_count + 1;\n      v_total_delta_posted := v_total_delta_posted + v_inv_delta;\n    END IF;\n\n    -- Synchronize sales_invoice_items snapshot fields for this batch\n    FOR v_item IN\n      SELECT sii.id, sii.quantity\n        FROM public.sales_invoice_items sii\n       WHERE sii.invoice_id = v_inv.id\n         AND sii.batch_id = p_batch_id\n    LOOP\n      v_target_item_cogs := ROUND(COALESCE(v_item.quantity, 0) * v_new_unit_cost, 2);\n      UPDATE public.sales_invoice_items\n         SET cogs_unit_cost = v_new_unit_cost,\n             cogs_total_cost = v_target_item_cogs\n       WHERE id = v_item.id;\n    END LOOP;\n\n  END LOOP;\n\n  PERFORM set_config('app.in_cogs_propagation', 'off', true);\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'batch_id', p_batch_id,\n    'batch_number', v_batch.batch_number,\n    'new_unit_cost', v_new_unit_cost,\n    'adjusted_invoices_count', v_adjusted_invoices_count,\n    'adjusted_items_count', v_adjusted_items_count,\n    'total_delta_posted', v_total_delta_posted\n  );\nEND;\n$$","-- 4. Reallocate container costs and trigger propagation across all affected batches\nCREATE OR REPLACE FUNCTION public.reallocate_container_costs(p_container_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  pool numeric := public.calculate_container_landed_cost_pool(p_container_id);\n  total_qty numeric;\n  total_val numeric;\n  l record;\n  v_batch_id uuid;\n  batch_cost numeric;\n  v_affected_batches uuid[] := ARRAY[]::uuid[];\nBEGIN\n  -- Branch 1: Purchase cost layers exist for this container\n  SELECT COALESCE(SUM(quantity), 0) INTO total_qty\n    FROM public.purchase_batch_cost_layers\n   WHERE import_container_id = p_container_id;\n\n  IF total_qty > 0 THEN\n    FOR l IN SELECT * FROM public.purchase_batch_cost_layers\n      WHERE import_container_id = p_container_id ORDER BY created_at, id FOR UPDATE LOOP\n      UPDATE public.purchase_batch_cost_layers\n         SET landed_cost_amount = ROUND(pool * l.quantity / total_qty, 2),\n             final_functional_unit_cost = ROUND(l.functional_unit_cost + pool * l.quantity / total_qty / l.quantity, 2)\n       WHERE id = l.id;\n    END LOOP;\n\n    FOR v_batch_id IN SELECT DISTINCT pbl.batch_id FROM public.purchase_batch_cost_layers pbl\n      WHERE import_container_id = p_container_id LOOP\n      SELECT COALESCE(SUM(quantity * final_functional_unit_cost) / NULLIF(SUM(quantity), 0), 0)\n        INTO batch_cost\n        FROM public.purchase_batch_cost_layers pbl WHERE pbl.batch_id = v_batch_id;\n\n      UPDATE public.batches\n         SET cost_per_unit = ROUND(batch_cost, 2),\n             landed_cost_per_unit = ROUND(batch_cost, 2),\n             updated_at = now()\n       WHERE id = v_batch_id AND COALESCE(cost_locked, false) = false;\n\n      v_affected_batches := array_append(v_affected_batches, v_batch_id);\n    END LOOP;\n\n    -- Propagate cost changes to sales COGS for every affected batch\n    FOREACH v_batch_id IN ARRAY v_affected_batches LOOP\n      PERFORM public.propagate_batch_cost_change(v_batch_id);\n    END LOOP;\n\n    RETURN;\n  END IF;\n\n  -- Branch 2: Value-weighted allocation across linked batches\n  SELECT COALESCE(SUM(COALESCE(import_price, 0) * COALESCE(import_quantity, 0)), 0)\n    INTO total_val\n    FROM public.batches\n   WHERE import_container_id = p_container_id;\n\n  IF total_val <= 0 THEN RETURN; END IF;\n\n  FOR l IN SELECT id, import_price, import_quantity, duty_charges, freight_charges, other_charges\n    FROM public.batches WHERE import_container_id = p_container_id AND COALESCE(cost_locked, false) = false LOOP\n    batch_cost := pool * (COALESCE(l.import_price, 0) * COALESCE(l.import_quantity, 0)) / total_val;\n    UPDATE public.batches\n       SET import_cost_allocated = ROUND(batch_cost, 2),\n           final_landed_cost = ROUND((COALESCE(l.import_price, 0) + COALESCE(l.duty_charges, 0)) * COALESCE(l.import_quantity, 0) + COALESCE(l.freight_charges, 0) + COALESCE(l.other_charges, 0) + batch_cost, 2),\n           landed_cost_per_unit = ROUND(COALESCE(l.import_price, 0) + COALESCE(l.duty_charges, 0) + COALESCE(l.freight_charges, 0) / NULLIF(l.import_quantity, 0) + COALESCE(l.other_charges, 0) / NULLIF(l.import_quantity, 0) + batch_cost / NULLIF(l.import_quantity, 0), 2),\n           cost_per_unit = ROUND(COALESCE(l.import_price, 0) + COALESCE(l.duty_charges, 0) + COALESCE(l.freight_charges, 0) / NULLIF(l.import_quantity, 0) + COALESCE(l.other_charges, 0) / NULLIF(l.import_quantity, 0) + batch_cost / NULLIF(l.import_quantity, 0), 2),\n           updated_at = now()\n     WHERE id = l.id;\n\n    v_affected_batches := array_append(v_affected_batches, l.id);\n  END LOOP;\n\n  -- Propagate cost changes to sales COGS for every affected batch\n  FOREACH v_batch_id IN ARRAY v_affected_batches LOOP\n    PERFORM public.propagate_batch_cost_change(v_batch_id);\n  END LOOP;\nEND;\n$$","-- 5. Helper to recalculate a specific batch (with container reallocation or direct expenses)\nCREATE OR REPLACE FUNCTION public.recalculate_batch_landed_cost(p_batch_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_container_id uuid;\n  v_direct_cost numeric;\n  v_b record;\nBEGIN\n  SELECT * INTO v_b FROM public.batches WHERE id = p_batch_id;\n  IF NOT FOUND THEN RETURN; END IF;\n\n  IF v_b.import_container_id IS NOT NULL THEN\n    PERFORM public.reallocate_container_costs(v_b.import_container_id);\n  ELSE\n    -- Standalone batch with direct expense link\n    v_direct_cost := public.calculate_batch_direct_landed_cost(p_batch_id);\n    IF v_direct_cost > 0 AND COALESCE(v_b.cost_locked, false) = false THEN\n      UPDATE public.batches\n         SET import_cost_allocated = ROUND(v_direct_cost, 2),\n             final_landed_cost = ROUND((COALESCE(v_b.import_price, 0) + COALESCE(v_b.duty_charges, 0)) * COALESCE(v_b.import_quantity, 0) + COALESCE(v_b.freight_charges, 0) + COALESCE(v_b.other_charges, 0) + v_direct_cost, 2),\n             landed_cost_per_unit = ROUND(COALESCE(v_b.import_price, 0) + COALESCE(v_b.duty_charges, 0) + COALESCE(v_b.freight_charges, 0) / NULLIF(v_b.import_quantity, 0) + COALESCE(v_b.other_charges, 0) / NULLIF(v_b.import_quantity, 0) + v_direct_cost / NULLIF(v_b.import_quantity, 0), 2),\n             cost_per_unit = ROUND(COALESCE(v_b.import_price, 0) + COALESCE(v_b.duty_charges, 0) + COALESCE(v_b.freight_charges, 0) / NULLIF(v_b.import_quantity, 0) + COALESCE(v_b.other_charges, 0) / NULLIF(v_b.import_quantity, 0) + v_direct_cost / NULLIF(v_b.import_quantity, 0), 2),\n             updated_at = now()\n       WHERE id = p_batch_id;\n    END IF;\n    PERFORM public.propagate_batch_cost_change(p_batch_id);\n  END IF;\nEND;\n$$","-- 6. Trigger on public.batches to propagate changes (allowing depth up to 3)\nCREATE OR REPLACE FUNCTION public.trg_batches_propagate_cost_change()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_old_cost numeric;\n  v_new_cost numeric;\nBEGIN\n  IF pg_trigger_depth() > 3 THEN\n    RETURN NEW;\n  END IF;\n\n  IF current_setting('app.in_cogs_propagation', true) = 'on' THEN\n    RETURN NEW;\n  END IF;\n\n  IF current_setting('app.finance_metadata_repair', true) = 'on' THEN\n    RETURN NEW;\n  END IF;\n\n  v_old_cost := public.calculate_batch_authoritative_cost(OLD);\n  v_new_cost := public.calculate_batch_authoritative_cost(NEW);\n\n  IF v_old_cost IS DISTINCT FROM v_new_cost AND v_new_cost > 0 THEN\n    PERFORM public.propagate_batch_cost_change(NEW.id);\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","DROP TRIGGER IF EXISTS trg_batches_propagate_cost_change ON public.batches","CREATE TRIGGER trg_batches_propagate_cost_change\nAFTER UPDATE OF landed_cost_per_unit, cost_per_unit, import_price, final_landed_cost\nON public.batches\nFOR EACH ROW\nEXECUTE FUNCTION public.trg_batches_propagate_cost_change()","-- 7. Trigger on public.finance_expenses to react dynamically to any expense lifecycle event\nCREATE OR REPLACE FUNCTION public.trigger_recalc_batches_on_expense_change()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_container_id uuid;\n  v_batch_id uuid;\nBEGIN\n  IF current_setting('app.finance_metadata_repair', true) = 'on' THEN\n    RETURN COALESCE(NEW, OLD);\n  END IF;\n\n  v_container_id := COALESCE(NEW.import_container_id, OLD.import_container_id);\n  v_batch_id := COALESCE(NEW.batch_id, OLD.batch_id);\n\n  IF v_container_id IS NOT NULL THEN\n    PERFORM public.reallocate_container_costs(v_container_id);\n  END IF;\n\n  IF TG_OP = 'UPDATE' AND OLD.import_container_id IS NOT NULL\n     AND NEW.import_container_id IS DISTINCT FROM OLD.import_container_id THEN\n    PERFORM public.reallocate_container_costs(OLD.import_container_id);\n  END IF;\n\n  IF v_batch_id IS NOT NULL THEN\n    PERFORM public.recalculate_batch_landed_cost(v_batch_id);\n  END IF;\n\n  IF TG_OP = 'UPDATE' AND OLD.batch_id IS NOT NULL\n     AND NEW.batch_id IS DISTINCT FROM OLD.batch_id THEN\n    PERFORM public.recalculate_batch_landed_cost(OLD.batch_id);\n  END IF;\n\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$","DROP TRIGGER IF EXISTS trigger_recalc_batches_on_expense ON public.finance_expenses","CREATE TRIGGER trigger_recalc_batches_on_expense\nAFTER INSERT OR UPDATE OF import_container_id, batch_id, include_in_landed_cost, amount, ppn_amount, stamp_duty_amount, broker_items, expense_category, approval_status\nON public.finance_expenses\nFOR EACH ROW\nEXECUTE FUNCTION public.trigger_recalc_batches_on_expense_change()","DROP TRIGGER IF EXISTS trigger_recalc_batches_on_expense_del ON public.finance_expenses","CREATE TRIGGER trigger_recalc_batches_on_expense_del\nAFTER DELETE ON public.finance_expenses\nFOR EACH ROW\nEXECUTE FUNCTION public.trigger_recalc_batches_on_expense_change()","-- 8. Trigger on public.petty_cash_transactions\nCREATE OR REPLACE FUNCTION public.trigger_recalc_batches_on_petty_cash_change()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_container_id uuid;\nBEGIN\n  IF current_setting('app.finance_metadata_repair', true) = 'on' THEN\n    RETURN COALESCE(NEW, OLD);\n  END IF;\n\n  v_container_id := COALESCE(NEW.import_container_id, OLD.import_container_id);\n\n  IF v_container_id IS NOT NULL THEN\n    PERFORM public.reallocate_container_costs(v_container_id);\n  END IF;\n\n  IF TG_OP = 'UPDATE' AND OLD.import_container_id IS NOT NULL\n     AND NEW.import_container_id IS DISTINCT FROM OLD.import_container_id THEN\n    PERFORM public.reallocate_container_costs(OLD.import_container_id);\n  END IF;\n\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$","DROP TRIGGER IF EXISTS trigger_recalc_batches_on_petty_cash ON public.petty_cash_transactions","CREATE TRIGGER trigger_recalc_batches_on_petty_cash\nAFTER INSERT OR UPDATE OF import_container_id, include_in_landed_cost, amount, expense_category, approval_status\nON public.petty_cash_transactions\nFOR EACH ROW\nEXECUTE FUNCTION public.trigger_recalc_batches_on_petty_cash_change()","DROP TRIGGER IF EXISTS trigger_recalc_batches_on_petty_cash_del ON public.petty_cash_transactions","CREATE TRIGGER trigger_recalc_batches_on_petty_cash_del\nAFTER DELETE ON public.petty_cash_transactions\nFOR EACH ROW\nEXECUTE FUNCTION public.trigger_recalc_batches_on_petty_cash_change()","-- 9. Authoritative sales line COGS view resolver\nCREATE OR REPLACE FUNCTION public.get_authoritative_sales_line_cogs(\n  p_start_date date, p_end_date date\n)\nRETURNS TABLE (\n  line_id uuid, invoice_id uuid, product_id uuid, batch_id uuid, quantity numeric,\n  authoritative_cogs numeric, authoritative_unit_cogs numeric, resolution_tier text,\n  invoice_line_count bigint, invoice_product_count bigint, posted_invoice_cogs numeric,\n  base_line_cost numeric, reconciliation_difference numeric\n)\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp\nAS $$\nWITH active_cogs AS (\n  SELECT je.reference_id AS invoice_id, je.id AS journal_id,\n         SUM(jel.debit - jel.credit) AS cogs_amount\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true\n    AND NOT COALESCE(je.is_reversed, false)\n    AND coa.code = '5100'\n    AND je.reference_id IS NOT NULL\n    AND (\n      je.source_module IN ('sales_invoice_cogs', 'sales_invoice_cogs_adjustment')\n      OR je.source_module IN ('historical_cogs_correction', 'historical_cogs_final_correction')\n      OR je.source_module LIKE 'historical_cogs%'\n      OR je.source_module LIKE '%cogs%'\n    )\n  GROUP BY je.reference_id, je.id\n), posted_cogs AS (\n  SELECT invoice_id, SUM(cogs_amount) AS posted_invoice_cogs\n  FROM active_cogs GROUP BY invoice_id\n), posted_item_cogs AS (\n  SELECT jel.sales_invoice_item_id AS line_id,\n         SUM(jel.debit - jel.credit) AS posted_item_cogs\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true AND NOT COALESCE(je.is_reversed, false)\n    AND coa.code = '5100' AND jel.sales_invoice_item_id IS NOT NULL\n    AND (\n      je.source_module IN ('sales_invoice_cogs', 'sales_invoice_cogs_adjustment')\n      OR je.source_module IN ('historical_cogs_correction', 'historical_cogs_final_correction')\n      OR je.source_module LIKE 'historical_cogs%'\n      OR je.source_module LIKE '%cogs%'\n    )\n  GROUP BY jel.sales_invoice_item_id\n), line_basis AS (\n  SELECT sii.id AS line_id, sii.invoice_id, sii.product_id, sii.batch_id,\n         sii.quantity, pic.posted_item_cogs, sii.cogs_total_cost AS snapshot_cogs,\n         CASE WHEN COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0)) IS NULL\n              THEN NULL ELSE sii.quantity * COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0)) END AS base_line_cost,\n         pc.posted_invoice_cogs\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  LEFT JOIN public.batches b ON b.id = sii.batch_id\n  LEFT JOIN posted_cogs pc ON pc.invoice_id = sii.invoice_id\n  LEFT JOIN posted_item_cogs pic ON pic.line_id = sii.id\n  WHERE si.invoice_date BETWEEN p_start_date AND p_end_date\n    AND NOT COALESCE(si.is_draft, false)\n), invoice_evidence AS (\n  SELECT invoice_id, COUNT(*) AS invoice_line_count,\n         COUNT(DISTINCT product_id) AS invoice_product_count,\n         COUNT(*) FILTER (WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL) AS unresolved_line_count,\n         COUNT(*) FILTER (WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL AND base_line_cost IS NOT NULL) AS unresolved_base_line_count,\n         COALESCE(SUM(COALESCE(posted_item_cogs, snapshot_cogs)), 0) AS resolved_cogs_total,\n         SUM(base_line_cost) FILTER (WHERE posted_item_cogs IS NULL AND snapshot_cogs IS NULL) AS unresolved_base_cost_total,\n         MAX(posted_invoice_cogs) AS posted_invoice_cogs\n  FROM line_basis GROUP BY invoice_id\n), resolved AS (\n  SELECT lb.*, ie.invoice_line_count, ie.invoice_product_count,\n         ie.unresolved_line_count, ie.unresolved_base_line_count,\n         ie.resolved_cogs_total, ie.unresolved_base_cost_total,\n         ie.posted_invoice_cogs AS invoice_posted_cogs,\n         ie.posted_invoice_cogs - ie.resolved_cogs_total AS residual_posted_cogs,\n         ABS(ie.unresolved_base_cost_total - (ie.posted_invoice_cogs - ie.resolved_cogs_total)) AS reconciliation_difference\n  FROM line_basis lb JOIN invoice_evidence ie ON ie.invoice_id = lb.invoice_id\n)\nSELECT r.line_id, r.invoice_id, r.product_id, r.batch_id, r.quantity,\n  CASE\n    WHEN r.posted_item_cogs IS NOT NULL THEN r.posted_item_cogs\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN r.invoice_posted_cogs\n    WHEN r.invoice_line_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      THEN r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)\n    WHEN r.base_line_cost IS NOT NULL THEN r.base_line_cost\n    ELSE NULL END AS authoritative_cogs,\n  CASE\n    WHEN r.quantity = 0 THEN NULL\n    WHEN r.posted_item_cogs IS NOT NULL THEN r.posted_item_cogs / r.quantity\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs / r.quantity\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN r.invoice_posted_cogs / r.quantity\n    WHEN r.invoice_line_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      THEN (r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)) / r.quantity\n    WHEN r.base_line_cost IS NOT NULL THEN r.base_line_cost / r.quantity\n    ELSE NULL END AS authoritative_unit_cogs,\n  CASE\n    WHEN r.posted_item_cogs IS NOT NULL THEN 'posted_item_cogs'\n    WHEN r.snapshot_cogs IS NOT NULL THEN 'snapshot'\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL THEN 'single_line_posted_cogs'\n    WHEN r.invoice_line_count > 1 AND r.invoice_product_count = 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count AND r.unresolved_base_cost_total > 0 THEN 'single_product_proven_allocation'\n    WHEN r.invoice_line_count > 1 AND r.invoice_product_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count AND r.unresolved_base_cost_total > 0 THEN 'multi_product_proven_allocation'\n    WHEN r.base_line_cost IS NOT NULL THEN 'canonical_batch_cost'\n    ELSE 'unresolved' END AS resolution_tier,\n  r.invoice_line_count, r.invoice_product_count, r.invoice_posted_cogs,\n  r.base_line_cost, r.reconciliation_difference\nFROM resolved r;\n$$","-- 10. Canonical Safe Reconciliation Backfill Procedure\nCREATE OR REPLACE FUNCTION public.reconcile_all_sales_cogs(\n  p_start_date date DEFAULT '2025-11-29',\n  p_end_date date DEFAULT CURRENT_DATE\n)\nRETURNS TABLE (\n  total_invoices integer,\n  total_items integer,\n  snapshots_updated integer,\n  delta_journals_created integer,\n  total_delta_posted numeric\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_batch_id uuid;\n  v_res jsonb;\n  v_tot_inv integer := 0;\n  v_tot_items integer := 0;\n  v_snap_updated integer := 0;\n  v_je_created integer := 0;\n  v_delta_posted numeric := 0;\nBEGIN\n  -- Count total non-draft sales invoices and items in scope\n  SELECT COUNT(DISTINCT si.id), COUNT(sii.id)\n    INTO v_tot_inv, v_tot_items\n    FROM public.sales_invoices si\n    JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id\n   WHERE NOT COALESCE(si.is_draft, false)\n     AND si.invoice_date BETWEEN p_start_date AND p_end_date;\n\n  DECLARE\n    v_cont record;\n  BEGIN\n    -- Reallocate all import containers first to ensure canonical batch costs\n    FOR v_cont IN\n      SELECT id FROM public.import_containers\n    LOOP\n      PERFORM public.reallocate_container_costs(v_cont.id);\n    END LOOP;\n  END;\n\n  -- Propagate cost changes for every batch sold in the period\n  FOR v_batch_id IN\n    SELECT DISTINCT sii.batch_id\n      FROM public.sales_invoice_items sii\n      JOIN public.sales_invoices si ON si.id = sii.invoice_id\n     WHERE NOT COALESCE(si.is_draft, false)\n       AND si.invoice_date BETWEEN p_start_date AND p_end_date\n       AND sii.batch_id IS NOT NULL\n  LOOP\n    v_res := public.propagate_batch_cost_change(v_batch_id);\n    v_je_created := v_je_created + COALESCE((v_res->>'adjusted_invoices_count')::integer, 0);\n    v_snap_updated := v_snap_updated + COALESCE((v_res->>'adjusted_items_count')::integer, 0);\n    v_delta_posted := v_delta_posted + COALESCE((v_res->>'total_delta_posted')::numeric, 0);\n  END LOOP;\n\n  -- Return final summary\n  RETURN QUERY SELECT v_tot_inv, v_tot_items, v_snap_updated, v_je_created, v_delta_posted;\nEND;\n$$","GRANT EXECUTE ON FUNCTION public.calculate_container_landed_cost_pool(uuid) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.calculate_batch_direct_landed_cost(uuid) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.propagate_batch_cost_change(uuid) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.reallocate_container_costs(uuid) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.recalculate_batch_landed_cost(uuid) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.get_authoritative_sales_line_cogs(date, date) TO authenticated, service_role","GRANT EXECUTE ON FUNCTION public.reconcile_all_sales_cogs(date, date) TO authenticated, service_role",COMMIT}	dynamic_landed_cost_and_cogs_engine	\N	\N	\N
20260921140000	{"-- Migration: 20260921140000_bank_reconciliation_kernel_fix.sql\n-- Description: Bank Reconciliation Kernel Fix — Step 1\n--              1. Canonical Bank Book Balance (calculate_bank_account_book_balance, get_bank_account_balances)\n--              2. Database-level expense payment overpayment protection (voucher_allocations & bank_statement_allocations)\n--              3. Support for multiple bank statement lines per expense (canonical bank_statement_allocations ownership)\n--              4. Strong match validation in confirm_bank_match()\n--              5. True allocation-derived reconciliation and matching status calculations\n--              6. Expanded payment_kind check constraints\n\nBEGIN","-- ============================================================================\n-- 1. CANONICAL BANK BOOK BALANCE FUNCTIONS\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.calculate_bank_account_book_balance(\n  p_bank_account_id uuid,\n  p_as_of_date date DEFAULT CURRENT_DATE\n)\nRETURNS numeric\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_opening numeric := 0;\n  v_coa_id uuid;\n  v_currency text;\n  v_debits numeric := 0;\n  v_credits numeric := 0;\nBEGIN\n  SELECT COALESCE(opening_balance, 0), coa_id, currency\n    INTO v_opening, v_coa_id, v_currency\n    FROM public.bank_accounts\n   WHERE id = p_bank_account_id;\n\n  IF v_coa_id IS NULL THEN\n    RETURN v_opening;\n  END IF;\n\n  -- For USD accounts, use transaction debit/credit if recorded, falling back to debit/credit\n  IF v_currency = 'USD' THEN\n    SELECT \n      COALESCE(SUM(COALESCE(NULLIF(jel.transaction_debit, 0), jel.debit, 0)), 0),\n      COALESCE(SUM(COALESCE(NULLIF(jel.transaction_credit, 0), jel.credit, 0)), 0)\n      INTO v_debits, v_credits\n      FROM public.journal_entry_lines jel\n      JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n     WHERE jel.account_id = v_coa_id\n       AND je.is_posted = true\n       AND je.entry_date <= p_as_of_date;\n  ELSE\n    SELECT \n      COALESCE(SUM(jel.debit), 0),\n      COALESCE(SUM(jel.credit), 0)\n      INTO v_debits, v_credits\n      FROM public.journal_entry_lines jel\n      JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n     WHERE jel.account_id = v_coa_id\n       AND je.is_posted = true\n       AND je.entry_date <= p_as_of_date;\n  END IF;\n\n  RETURN round(v_opening + v_debits - v_credits, 2);\nEND;\n$$","COMMENT ON FUNCTION public.calculate_bank_account_book_balance(uuid, date) IS \n'Authoritative dynamic book balance for a bank account: opening_balance + posted debits - posted credits. Does not filter is_reversed.'","CREATE OR REPLACE FUNCTION public.get_bank_account_balances(\n  p_as_of_date date DEFAULT CURRENT_DATE\n)\nRETURNS TABLE (\n  bank_account_id uuid,\n  account_name text,\n  bank_name text,\n  account_number text,\n  currency text,\n  coa_id uuid,\n  coa_code text,\n  opening_balance numeric,\n  opening_balance_date date,\n  total_debits numeric,\n  total_credits numeric,\n  book_balance numeric,\n  statement_balance numeric,\n  as_of_date date\n)\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nBEGIN\n  RETURN QUERY\n  WITH latest_stmt AS (\n    SELECT DISTINCT ON (bsl.bank_account_id)\n      bsl.bank_account_id,\n      COALESCE(bsl.statement_balance, bsl.running_balance, 0) as last_stmt_bal\n    FROM public.bank_statement_lines bsl\n    WHERE bsl.transaction_date <= p_as_of_date\n    ORDER BY bsl.bank_account_id, bsl.transaction_date DESC, bsl.id DESC\n  )\n  SELECT \n    ba.id AS bank_account_id,\n    ba.account_name::text,\n    ba.bank_name::text,\n    ba.account_number::text,\n    ba.currency::text,\n    ba.coa_id,\n    coa.code::text AS coa_code,\n    COALESCE(ba.opening_balance, 0) AS opening_balance,\n    ba.opening_balance_date,\n    COALESCE(\n      CASE WHEN ba.currency = 'USD' \n        THEN (SELECT SUM(COALESCE(NULLIF(jel.transaction_debit, 0), jel.debit, 0))\n              FROM public.journal_entry_lines jel JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n              WHERE jel.account_id = ba.coa_id AND je.is_posted = true AND je.entry_date <= p_as_of_date)\n        ELSE (SELECT SUM(jel.debit)\n              FROM public.journal_entry_lines jel JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n              WHERE jel.account_id = ba.coa_id AND je.is_posted = true AND je.entry_date <= p_as_of_date)\n      END, 0) AS total_debits,\n    COALESCE(\n      CASE WHEN ba.currency = 'USD' \n        THEN (SELECT SUM(COALESCE(NULLIF(jel.transaction_credit, 0), jel.credit, 0))\n              FROM public.journal_entry_lines jel JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n              WHERE jel.account_id = ba.coa_id AND je.is_posted = true AND je.entry_date <= p_as_of_date)\n        ELSE (SELECT SUM(jel.credit)\n              FROM public.journal_entry_lines jel JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n              WHERE jel.account_id = ba.coa_id AND je.is_posted = true AND je.entry_date <= p_as_of_date)\n      END, 0) AS total_credits,\n    public.calculate_bank_account_book_balance(ba.id, p_as_of_date) AS book_balance,\n    COALESCE(ls.last_stmt_bal, COALESCE(ba.opening_balance, 0)) AS statement_balance,\n    p_as_of_date AS as_of_date\n  FROM public.bank_accounts ba\n  LEFT JOIN public.chart_of_accounts coa ON coa.id = ba.coa_id\n  LEFT JOIN latest_stmt ls ON ls.bank_account_id = ba.id\n  WHERE ba.is_active = true;\nEND;\n$$","GRANT EXECUTE ON FUNCTION public.calculate_bank_account_book_balance(uuid, date) TO authenticated, service_role, anon","GRANT EXECUTE ON FUNCTION public.get_bank_account_balances(date) TO authenticated, service_role, anon","-- ============================================================================\n-- 2. EXPAND PAYMENT_KIND CONSTRAINTS ON BANK TABLES\n-- ============================================================================\n\nALTER TABLE public.bank_statement_lines DROP CONSTRAINT IF EXISTS bank_statement_lines_payment_kind_check","ALTER TABLE public.bank_statement_lines ALTER COLUMN payment_kind DROP NOT NULL","ALTER TABLE public.bank_statement_lines ALTER COLUMN payment_kind SET DEFAULT 'unclassified'","ALTER TABLE public.bank_statement_lines ADD CONSTRAINT bank_statement_lines_payment_kind_check \n  CHECK (payment_kind IS NULL OR payment_kind = ANY (ARRAY[\n    'supplier'::text, 'pph23'::text, 'salary'::text, 'tax'::text, \n    'petty_cash'::text, 'capital'::text, 'admin_expense'::text, \n    'customer_receipt'::text, 'fund_transfer'::text, 'other'::text, 'unclassified'::text\n  ]))","ALTER TABLE public.bank_statement_allocations DROP CONSTRAINT IF EXISTS bank_statement_allocations_payment_kind_check","ALTER TABLE public.bank_statement_allocations ALTER COLUMN payment_kind DROP NOT NULL","ALTER TABLE public.bank_statement_allocations ALTER COLUMN payment_kind SET DEFAULT 'unclassified'","ALTER TABLE public.bank_statement_allocations ADD CONSTRAINT bank_statement_allocations_payment_kind_check \n  CHECK (payment_kind IS NULL OR payment_kind = ANY (ARRAY[\n    'supplier'::text, 'pph23'::text, 'salary'::text, 'tax'::text, \n    'petty_cash'::text, 'capital'::text, 'admin_expense'::text, \n    'customer_receipt'::text, 'fund_transfer'::text, 'other'::text, 'unclassified'::text\n  ]))","-- ============================================================================\n-- 3. EXPENSE OVERPAYMENT PROTECTION (VOUCHER_ALLOCATIONS)\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.prevent_expense_payment_overallocation()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_exp RECORD;\n  v_payable numeric := 0;\n  v_settled_va numeric := 0;\n  v_settled_bsa numeric := 0;\n  v_settled_bsl numeric := 0;\n  v_total_settled numeric := 0;\n  v_remaining numeric := 0;\n  v_kind text;\nBEGIN\n  IF NEW.finance_expense_id IS NULL OR NEW.voucher_type <> 'payment' THEN\n    RETURN NEW;\n  END IF;\n\n  v_kind := COALESCE(NEW.payment_kind, 'supplier');\n\n  -- Lock the finance_expense row inside the same transaction\n  SELECT * INTO v_exp \n    FROM public.finance_expenses \n   WHERE id = NEW.finance_expense_id \n     FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Referenced finance_expense % does not exist', NEW.finance_expense_id;\n  END IF;\n\n  -- Determine total payable for this payment kind\n  IF v_kind = 'pph23' THEN\n    v_payable := COALESCE(v_exp.pph_amount, 0);\n  ELSE\n    v_payable := COALESCE(public.calculate_finance_expense_payable(v_exp.id), 0);\n  END IF;\n\n  -- Existing posted settlements from voucher_allocations (excluding current row on update)\n  SELECT COALESCE(SUM(va.allocated_amount), 0) INTO v_settled_va\n    FROM public.voucher_allocations va\n    JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n   WHERE va.finance_expense_id = v_exp.id\n     AND COALESCE(va.payment_kind, 'supplier') = v_kind\n     AND COALESCE(pv.payment_purpose, 'general') NOT IN ('salary_advance', 'salary_advance_settlement')\n     AND (TG_OP <> 'UPDATE' OR va.id <> NEW.id);\n\n  -- Existing posted settlements from bank_statement_allocations\n  SELECT COALESCE(SUM(bsa.allocation_amount), 0) INTO v_settled_bsa\n    FROM public.bank_statement_allocations bsa\n   WHERE bsa.document_type = 'expense'\n     AND bsa.document_id = v_exp.id\n     AND COALESCE(bsa.payment_kind, 'supplier') = v_kind;\n\n  -- Existing legacy settlements from bank_statement_lines without allocations\n  SELECT COALESCE(SUM(COALESCE(NULLIF(bsl.debit_amount, 0), bsl.credit_amount, 0)), 0) INTO v_settled_bsl\n    FROM public.bank_statement_lines bsl\n   WHERE bsl.matched_expense_id = v_exp.id\n     AND COALESCE(bsl.payment_kind, 'supplier') = v_kind\n     AND NOT EXISTS (\n       SELECT 1 FROM public.bank_statement_allocations a \n        WHERE a.bank_statement_line_id = bsl.id\n     );\n\n  v_total_settled := v_settled_va + v_settled_bsa + v_settled_bsl;\n  v_remaining := round(v_payable - v_total_settled, 2);\n\n  IF NEW.allocated_amount > (v_remaining + 0.01) THEN\n    RAISE EXCEPTION 'Expense payment allocation (%) exceeds remaining payable (%) for expense % (Total Payable: %, Already Settled: %)',\n      NEW.allocated_amount, v_remaining, COALESCE(v_exp.voucher_number, v_exp.id::text), v_payable, v_total_settled;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","DROP TRIGGER IF EXISTS trg_prevent_expense_payment_overallocation ON public.voucher_allocations","CREATE TRIGGER trg_prevent_expense_payment_overallocation\n  BEFORE INSERT OR UPDATE OF allocated_amount, finance_expense_id, payment_kind, voucher_type\n  ON public.voucher_allocations\n  FOR EACH ROW\n  EXECUTE FUNCTION public.prevent_expense_payment_overallocation()","-- ============================================================================\n-- 4. EXPENSE OVERPAYMENT & ALLOCATION CAP (BANK_STATEMENT_ALLOCATIONS)\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.validate_expense_bank_allocation_against_journal()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_exp RECORD;\n  v_payable numeric := 0;\n  v_settled_va numeric := 0;\n  v_settled_bsa numeric := 0;\n  v_settled_bsl numeric := 0;\n  v_total_settled numeric := 0;\n  v_remaining numeric := 0;\n  v_kind text;\n  v_bank_line RECORD;\n  v_bank_amount numeric := 0;\n  v_other_allocations numeric := 0;\nBEGIN\n  -- 1. Bank Statement Line Allocation Cap Check (applies to ALL document types)\n  SELECT bsl.*, ba.coa_id AS bank_coa_id, ba.currency AS bank_currency\n    INTO v_bank_line\n    FROM public.bank_statement_lines bsl\n    JOIN public.bank_accounts ba ON ba.id = bsl.bank_account_id\n   WHERE bsl.id = NEW.bank_statement_line_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Bank statement line % does not exist', NEW.bank_statement_line_id;\n  END IF;\n\n  v_bank_amount := COALESCE(NULLIF(v_bank_line.debit_amount, 0), v_bank_line.credit_amount, 0);\n\n  SELECT COALESCE(SUM(allocation_amount), 0) INTO v_other_allocations\n    FROM public.bank_statement_allocations\n   WHERE bank_statement_line_id = NEW.bank_statement_line_id\n     AND (TG_OP <> 'UPDATE' OR id <> NEW.id);\n\n  IF (v_other_allocations + NEW.allocation_amount) > (v_bank_amount + 0.01) THEN\n    RAISE EXCEPTION 'Total bank allocations (%) exceed bank statement line amount (%) on line %',\n      (v_other_allocations + NEW.allocation_amount), v_bank_amount, NEW.bank_statement_line_id;\n  END IF;\n\n  -- 2. If document is expense, enforce aggregate expense payable limits\n  IF NEW.document_type = 'expense' THEN\n    v_kind := COALESCE(NEW.payment_kind, 'supplier');\n\n    -- Lock the finance_expenses row inside the same transaction\n    SELECT * INTO v_exp\n      FROM public.finance_expenses\n     WHERE id = NEW.document_id\n       FOR UPDATE;\n\n    IF NOT FOUND THEN\n      RAISE EXCEPTION 'Referenced finance_expense % does not exist', NEW.document_id;\n    END IF;\n\n    IF v_kind = 'pph23' THEN\n      v_payable := COALESCE(v_exp.pph_amount, 0);\n    ELSE\n      v_payable := COALESCE(public.calculate_finance_expense_payable(v_exp.id), 0);\n    END IF;\n\n    -- Settlements from voucher_allocations\n    SELECT COALESCE(SUM(va.allocated_amount), 0) INTO v_settled_va\n      FROM public.voucher_allocations va\n      JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n     WHERE va.finance_expense_id = v_exp.id\n       AND COALESCE(va.payment_kind, 'supplier') = v_kind\n       AND COALESCE(pv.payment_purpose, 'general') NOT IN ('salary_advance', 'salary_advance_settlement');\n\n    -- Settlements from other bank_statement_allocations\n    SELECT COALESCE(SUM(bsa.allocation_amount), 0) INTO v_settled_bsa\n      FROM public.bank_statement_allocations bsa\n     WHERE bsa.document_type = 'expense'\n       AND bsa.document_id = v_exp.id\n       AND COALESCE(bsa.payment_kind, 'supplier') = v_kind\n       AND (TG_OP <> 'UPDATE' OR bsa.id <> NEW.id);\n\n    -- Settlements from unallocated legacy bank lines\n    SELECT COALESCE(SUM(COALESCE(NULLIF(bsl.debit_amount, 0), bsl.credit_amount, 0)), 0) INTO v_settled_bsl\n      FROM public.bank_statement_lines bsl\n     WHERE bsl.matched_expense_id = v_exp.id\n       AND COALESCE(bsl.payment_kind, 'supplier') = v_kind\n       AND bsl.id <> NEW.bank_statement_line_id\n       AND NOT EXISTS (\n         SELECT 1 FROM public.bank_statement_allocations a \n          WHERE a.bank_statement_line_id = bsl.id\n       );\n\n    v_total_settled := v_settled_va + v_settled_bsa + v_settled_bsl;\n    v_remaining := round(v_payable - v_total_settled, 2);\n\n    IF NEW.allocation_amount > (v_remaining + 0.01) THEN\n      RAISE EXCEPTION 'Bank allocation (%) exceeds remaining payable (%) for expense % (Total Payable: %, Already Settled: %)',\n        NEW.allocation_amount, v_remaining, COALESCE(v_exp.voucher_number, v_exp.id::text), v_payable, v_total_settled;\n    END IF;\n  END IF;\n\n  -- 3. If journal entry is attached, validate journal bank lines\n  IF NEW.journal_entry_id IS NOT NULL THEN\n    PERFORM 1 FROM public.journal_entries \n     WHERE id = NEW.journal_entry_id AND is_posted = true;\n    IF NOT FOUND THEN\n      RAISE EXCEPTION 'Attached journal entry % is either missing or not posted', NEW.journal_entry_id;\n    END IF;\n\n    IF NOT EXISTS (\n      SELECT 1 FROM public.journal_entry_lines\n       WHERE journal_entry_id = NEW.journal_entry_id\n         AND account_id = v_bank_line.bank_coa_id\n    ) THEN\n      RAISE EXCEPTION 'Journal entry % does not contain the bank account COA %',\n        NEW.journal_entry_id, v_bank_line.bank_coa_id;\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","-- ============================================================================\n-- 5. CANONICAL RECONCILIATION OWNERSHIP (SYNC_BANK_LINE_ALLOCATION_OWNER)\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.sync_bank_line_allocation_owner(p_bank_line_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_count integer;\n  v_only public.bank_statement_allocations%ROWTYPE;\n  v_target_expense_id uuid;\n  v_target_receipt_id uuid;\n  v_target_payment_id uuid;\n  v_target_ft_id uuid;\n  v_target_pc_id uuid;\n  v_target_tax_id uuid;\n  v_target_entry_id uuid;\n  v_target_kind text;\nBEGIN\n  SELECT count(*) INTO v_count\n    FROM public.bank_statement_allocations\n   WHERE bank_statement_line_id = p_bank_line_id;\n\n  IF v_count = 1 THEN\n    SELECT * INTO v_only\n      FROM public.bank_statement_allocations\n     WHERE bank_statement_line_id = p_bank_line_id;\n\n    -- Multiple bank statement lines can settle the same expense; do NOT enforce artificial 1:1 exclusivity\n    v_target_expense_id := CASE WHEN v_only.document_type = 'expense' THEN v_only.document_id END;\n    v_target_receipt_id := CASE WHEN v_only.document_type = 'receipt' THEN v_only.document_id END;\n    v_target_payment_id := CASE WHEN v_only.document_type = 'payment' THEN v_only.document_id END;\n    v_target_ft_id := CASE WHEN v_only.document_type = 'fund_transfer' THEN v_only.document_id END;\n    v_target_pc_id := CASE WHEN v_only.document_type = 'petty_cash' THEN v_only.document_id END;\n    v_target_tax_id := CASE WHEN v_only.document_type = 'tax_payment' THEN v_only.document_id END;\n    v_target_entry_id := v_only.journal_entry_id;\n    v_target_kind := COALESCE(v_only.payment_kind,\n      CASE v_only.document_type\n        WHEN 'expense' THEN 'supplier'\n        WHEN 'receipt' THEN 'customer_receipt'\n        WHEN 'tax_payment' THEN 'tax'\n        WHEN 'petty_cash' THEN 'petty_cash'\n        WHEN 'fund_transfer' THEN 'fund_transfer'\n        ELSE 'other'\n      END\n    );\n\n    UPDATE public.bank_statement_lines SET\n      matched_expense_id = v_target_expense_id,\n      matched_receipt_id = v_target_receipt_id,\n      matched_payment_id = v_target_payment_id,\n      matched_fund_transfer_id = v_target_ft_id,\n      matched_petty_cash_id = v_target_pc_id,\n      matched_tax_payment_id = v_target_tax_id,\n      matched_entry_id = v_target_entry_id,\n      payment_kind = v_target_kind\n    WHERE id = p_bank_line_id\n      AND (\n        matched_expense_id IS DISTINCT FROM v_target_expense_id OR\n        matched_receipt_id IS DISTINCT FROM v_target_receipt_id OR\n        matched_payment_id IS DISTINCT FROM v_target_payment_id OR\n        matched_fund_transfer_id IS DISTINCT FROM v_target_ft_id OR\n        matched_petty_cash_id IS DISTINCT FROM v_target_pc_id OR\n        matched_tax_payment_id IS DISTINCT FROM v_target_tax_id OR\n        matched_entry_id IS DISTINCT FROM v_target_entry_id OR\n        payment_kind IS DISTINCT FROM v_target_kind\n      );\n  ELSE\n    UPDATE public.bank_statement_lines SET\n      matched_expense_id = NULL,\n      matched_receipt_id = NULL,\n      matched_payment_id = NULL,\n      matched_fund_transfer_id = NULL,\n      matched_petty_cash_id = NULL,\n      matched_tax_payment_id = NULL,\n      matched_entry_id = NULL\n    WHERE id = p_bank_line_id\n      AND (\n        matched_expense_id IS NOT NULL OR\n        matched_receipt_id IS NOT NULL OR\n        matched_payment_id IS NOT NULL OR\n        matched_fund_transfer_id IS NOT NULL OR\n        matched_petty_cash_id IS NOT NULL OR\n        matched_tax_payment_id IS NOT NULL OR\n        matched_entry_id IS NOT NULL\n      );\n  END IF;\nEND;\n$$","-- ============================================================================\n-- 6. STRONG MATCH VALIDATION IN CONFIRM_BANK_MATCH()\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.confirm_bank_match(\n  p_bank_line_id uuid,\n  p_user_id uuid\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_line RECORD;\n  v_bank_acct RECORD;\n  v_alloc RECORD;\n  v_total_alloc numeric := 0;\n  v_line_amount numeric := 0;\n  v_journal RECORD;\n  v_role text;\n  v_alloc_count integer := 0;\nBEGIN\n  -- Permission check\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role IS NOT NULL AND v_role NOT IN ('admin', 'accounts') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot confirm bank matches', v_role;\n  END IF;\n\n  SELECT * INTO v_line \n    FROM public.bank_statement_lines \n   WHERE id = p_bank_line_id \n     FOR UPDATE;\n\n  IF NOT FOUND THEN \n    RETURN jsonb_build_object('success', false, 'error', 'Bank statement line not found'); \n  END IF;\n\n  SELECT * INTO v_bank_acct \n    FROM public.bank_accounts \n   WHERE id = v_line.bank_account_id;\n\n  IF NOT FOUND THEN \n    RETURN jsonb_build_object('success', false, 'error', 'Bank account not found'); \n  END IF;\n\n  v_line_amount := COALESCE(NULLIF(v_line.debit_amount, 0), v_line.credit_amount, 0);\n\n  -- Count allocations\n  SELECT count(*), COALESCE(sum(allocation_amount), 0)\n    INTO v_alloc_count, v_total_alloc\n    FROM public.bank_statement_allocations\n   WHERE bank_statement_line_id = p_bank_line_id;\n\n  -- Case A: Line has allocations\n  IF v_alloc_count > 0 THEN\n    IF v_total_alloc > v_line_amount + 0.01 THEN\n      RETURN jsonb_build_object('success', false, 'error', 'Total allocations (' || v_total_alloc || ') exceed bank line amount (' || v_line_amount || ')');\n    END IF;\n\n    -- Validate each allocation\n    FOR v_alloc IN \n      SELECT bsa.*, je.is_posted, je.transaction_currency\n        FROM public.bank_statement_allocations bsa\n        LEFT JOIN public.journal_entries je ON je.id = bsa.journal_entry_id\n       WHERE bsa.bank_statement_line_id = p_bank_line_id\n    LOOP\n      -- 1. Must have journal entry\n      IF v_alloc.journal_entry_id IS NULL THEN\n        RETURN jsonb_build_object('success', false, 'error', 'Allocation has no journal entry attached');\n      END IF;\n\n      -- 2. Active posted journal\n      IF COALESCE(v_alloc.is_posted, false) = false THEN\n        RETURN jsonb_build_object('success', false, 'error', 'Journal entry ' || v_alloc.journal_entry_id || ' is not posted');\n      END IF;\n\n      -- 3. Journal must contain the bank account COA\n      IF NOT EXISTS (\n        SELECT 1 FROM public.journal_entry_lines \n         WHERE journal_entry_id = v_alloc.journal_entry_id \n           AND account_id = v_bank_acct.coa_id\n      ) THEN\n        RETURN jsonb_build_object('success', false, 'error', 'Journal entry does not contain bank account COA');\n      END IF;\n\n      -- 4. Direction match:\n      -- Bank statement debit (money out) -> GL bank line credit\n      -- Bank statement credit (money in) -> GL bank line debit\n      IF v_line.debit_amount > 0 THEN\n        IF NOT EXISTS (\n          SELECT 1 FROM public.journal_entry_lines\n           WHERE journal_entry_id = v_alloc.journal_entry_id \n             AND account_id = v_bank_acct.coa_id \n             AND credit > 0\n        ) THEN\n          RETURN jsonb_build_object('success', false, 'error', 'Journal direction mismatch: statement debit requires GL bank credit');\n        END IF;\n      ELSIF v_line.credit_amount > 0 THEN\n        IF NOT EXISTS (\n          SELECT 1 FROM public.journal_entry_lines\n           WHERE journal_entry_id = v_alloc.journal_entry_id \n             AND account_id = v_bank_acct.coa_id \n             AND debit > 0\n        ) THEN\n          RETURN jsonb_build_object('success', false, 'error', 'Journal direction mismatch: statement credit requires GL bank debit');\n        END IF;\n      END IF;\n\n      -- 5. Currency check\n      IF v_bank_acct.currency = 'USD' AND v_alloc.transaction_currency IS NOT NULL AND v_alloc.transaction_currency <> 'USD' THEN\n        RETURN jsonb_build_object('success', false, 'error', 'Currency mismatch between journal and bank account');\n      END IF;\n\n      -- 6. Document settlement validity if expense\n      IF v_alloc.document_type = 'expense' THEN\n        IF NOT EXISTS (\n          SELECT 1 FROM public.finance_expenses WHERE id = v_alloc.document_id\n        ) THEN\n          RETURN jsonb_build_object('success', false, 'error', 'Referenced finance expense does not exist');\n        END IF;\n      END IF;\n    END LOOP;\n\n  -- Case B: Direct matched journal without allocations\n  ELSIF v_line.matched_entry_id IS NOT NULL THEN\n    SELECT * INTO v_journal \n      FROM public.journal_entries \n     WHERE id = v_line.matched_entry_id;\n\n    IF NOT FOUND OR COALESCE(v_journal.is_posted, false) = false THEN\n      RETURN jsonb_build_object('success', false, 'error', 'Direct matched journal is missing or unposted');\n    END IF;\n\n    IF NOT EXISTS (\n      SELECT 1 FROM public.journal_entry_lines \n       WHERE journal_entry_id = v_journal.id \n         AND account_id = v_bank_acct.coa_id\n    ) THEN\n      RETURN jsonb_build_object('success', false, 'error', 'Journal does not contain bank account COA');\n    END IF;\n\n    IF v_line.debit_amount > 0 THEN\n      IF NOT EXISTS (\n        SELECT 1 FROM public.journal_entry_lines\n         WHERE journal_entry_id = v_journal.id AND account_id = v_bank_acct.coa_id AND credit > 0\n      ) THEN\n        RETURN jsonb_build_object('success', false, 'error', 'Journal direction mismatch: statement debit requires GL credit');\n      END IF;\n    ELSIF v_line.credit_amount > 0 THEN\n      IF NOT EXISTS (\n        SELECT 1 FROM public.journal_entry_lines\n         WHERE journal_entry_id = v_journal.id AND account_id = v_bank_acct.coa_id AND debit > 0\n      ) THEN\n        RETURN jsonb_build_object('success', false, 'error', 'Journal direction mismatch: statement credit requires GL debit');\n      END IF;\n    END IF;\n  ELSE\n    RETURN jsonb_build_object('success', false, 'error', 'Cannot confirm match: line has no valid allocation or posted journal entry');\n  END IF;\n\n  -- Perform the confirmation\n  UPDATE public.bank_statement_lines\n     SET matching_status = 'confirmed',\n         reconciliation_status = CASE\n           WHEN v_alloc_count > 0 AND v_total_alloc < v_line_amount - 0.01 THEN 'partially_reconciled'\n           ELSE 'matched'\n         END,\n         matched_at = now(),\n         matched_by = COALESCE(p_user_id, auth.uid()),\n         notes = COALESCE(notes, 'User confirmed match')\n   WHERE id = p_bank_line_id;\n\n  RETURN jsonb_build_object('success', true, 'message', 'Match confirmed successfully');\nEND;\n$$","-- ============================================================================\n-- 7. ALLOCATION-DERIVED STATUS SYNCHRONIZATION\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.bsl_sync_reconciliation_status()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_allocated numeric := 0;\n  v_total numeric := 0;\n  v_alloc_count integer := 0;\nBEGIN\n  v_total := COALESCE(NULLIF(NEW.debit_amount, 0), NEW.credit_amount, 0);\n\n  SELECT count(*), COALESCE(sum(allocation_amount), 0)\n    INTO v_alloc_count, v_allocated\n    FROM public.bank_statement_allocations\n   WHERE bank_statement_line_id = NEW.id;\n\n  -- 1. If line has no allocations and no matched journal entry:\n  IF v_alloc_count = 0 AND NEW.matched_entry_id IS NULL THEN\n    IF NEW.matching_status = 'confirmed' AND (TG_OP = 'INSERT' OR OLD.matching_status IS DISTINCT FROM 'confirmed') THEN\n      RAISE EXCEPTION 'Bank statement line % cannot be marked confirmed without an allocation or posted journal', NEW.id;\n    END IF;\n    NEW.reconciliation_status := 'unmatched';\n    NEW.matching_status := 'none';\n    NEW.matched_at := NULL;\n    NEW.matched_by := NULL;\n\n  -- 2. Line has allocations: derive status from allocation amounts\n  ELSIF v_alloc_count > 0 THEN\n    IF v_allocated <= 0.01 THEN\n      NEW.reconciliation_status := 'unmatched';\n    ELSIF v_allocated < v_total - 0.01 THEN\n      NEW.reconciliation_status := 'partially_reconciled';\n    ELSE\n      NEW.reconciliation_status := 'matched';\n    END IF;\n\n  -- 3. Line has direct matched_entry_id without allocations\n  ELSIF NEW.matched_entry_id IS NOT NULL THEN\n    IF NEW.reconciliation_status IS NULL OR NEW.reconciliation_status = 'unmatched' THEN\n      NEW.reconciliation_status := 'matched';\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$","DROP TRIGGER IF EXISTS trg_bsl_sync_reconciliation_status ON public.bank_statement_lines","CREATE TRIGGER trg_bsl_sync_reconciliation_status\n  BEFORE INSERT OR UPDATE OF\n    reconciliation_status,\n    matching_status,\n    matched_expense_id,\n    matched_receipt_id,\n    matched_payment_id,\n    matched_fund_transfer_id,\n    matched_petty_cash_id,\n    matched_tax_payment_id,\n    matched_entry_id\n  ON public.bank_statement_lines\n  FOR EACH ROW\n  EXECUTE FUNCTION public.bsl_sync_reconciliation_status()","CREATE OR REPLACE FUNCTION public.refresh_bank_statement_allocation_status(p_bank_line_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_total numeric;\n  v_allocated numeric;\n  v_existing_status text;\n  v_existing_matching_status text;\n  v_new_matching_status text;\n  v_new_recon_status text;\nBEGIN\n  SELECT COALESCE(NULLIF(debit_amount, 0), credit_amount, 0),\n         reconciliation_status, matching_status\n    INTO v_total, v_existing_status, v_existing_matching_status\n    FROM public.bank_statement_lines\n   WHERE id = p_bank_line_id\n   FOR UPDATE;\n\n  SELECT COALESCE(sum(allocation_amount), 0)\n    INTO v_allocated\n    FROM public.bank_statement_allocations\n   WHERE bank_statement_line_id = p_bank_line_id;\n\n  IF v_allocated <= 0.01 THEN\n    v_new_recon_status := 'unmatched';\n    v_new_matching_status := 'none';\n  ELSIF v_allocated < v_total - 0.01 THEN\n    v_new_recon_status := 'partially_reconciled';\n    v_new_matching_status := CASE WHEN v_existing_matching_status = 'confirmed' THEN 'confirmed' ELSE 'suggested' END;\n  ELSE\n    v_new_recon_status := 'matched';\n    v_new_matching_status := CASE WHEN v_existing_matching_status = 'confirmed' THEN 'confirmed' ELSE 'suggested' END;\n  END IF;\n\n  UPDATE public.bank_statement_lines\n     SET reconciliation_status = v_new_recon_status,\n         matching_status = v_new_matching_status,\n         matched_at = CASE WHEN v_allocated <= 0.01 THEN NULL ELSE COALESCE(matched_at, now()) END,\n         matched_by = CASE WHEN v_allocated <= 0.01 THEN NULL ELSE COALESCE(matched_by, auth.uid()) END\n   WHERE id = p_bank_line_id;\nEND;\n$$",COMMIT}	bank_reconciliation_kernel_fix	\N	\N	\N
20260921163000	{"-- 20260921163000_fix_product_profitability_authoritative_cogs.sql\n-- Fix get_authoritative_sales_line_cogs so canonical batch landed cost is authoritative\n-- and COGS adjustment journals (deltas) cannot overwrite the full line COGS.\n\nCREATE OR REPLACE FUNCTION public.get_authoritative_sales_line_cogs(p_start_date date, p_end_date date)\n RETURNS TABLE(\n   line_id uuid,\n   invoice_id uuid,\n   product_id uuid,\n   batch_id uuid,\n   quantity numeric,\n   authoritative_cogs numeric,\n   authoritative_unit_cogs numeric,\n   resolution_tier text,\n   invoice_line_count bigint,\n   invoice_product_count bigint,\n   posted_invoice_cogs numeric,\n   base_line_cost numeric,\n   reconciliation_difference numeric\n )\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nWITH active_cogs AS (\n  SELECT je.reference_id AS invoice_id, je.id AS journal_id,\n         SUM(jel.debit - jel.credit) AS cogs_amount\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true\n    AND NOT COALESCE(je.is_reversed, false)\n    AND coa.code = '5100'\n    AND je.reference_id IS NOT NULL\n    AND (\n      je.source_module IN ('sales_invoice_cogs', 'sales_invoice_cogs_adjustment')\n      OR je.source_module IN ('historical_cogs_correction', 'historical_cogs_final_correction')\n      OR je.source_module LIKE 'historical_cogs%'\n      OR je.source_module LIKE '%cogs%'\n    )\n  GROUP BY je.reference_id, je.id\n), posted_cogs AS (\n  SELECT invoice_id, SUM(cogs_amount) AS posted_invoice_cogs\n  FROM active_cogs GROUP BY invoice_id\n), posted_item_cogs AS (\n  SELECT jel.sales_invoice_item_id AS line_id,\n         SUM(jel.debit - jel.credit) AS posted_item_cogs\n  FROM public.journal_entries je\n  JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true AND NOT COALESCE(je.is_reversed, false)\n    AND coa.code = '5100' AND jel.sales_invoice_item_id IS NOT NULL\n    AND (\n      je.source_module IN ('sales_invoice_cogs', 'sales_invoice_cogs_adjustment')\n      OR je.source_module IN ('historical_cogs_correction', 'historical_cogs_final_correction')\n      OR je.source_module LIKE 'historical_cogs%'\n      OR je.source_module LIKE '%cogs%'\n    )\n  GROUP BY jel.sales_invoice_item_id\n), line_basis AS (\n  SELECT sii.id AS line_id, sii.invoice_id, sii.product_id, sii.batch_id,\n         sii.quantity,\n         pic.posted_item_cogs,\n         sii.cogs_total_cost AS snapshot_cogs,\n         sii.cogs_unit_cost AS snapshot_unit_cogs,\n         CASE \n           WHEN b.id IS NOT NULL \n           THEN public.calculate_batch_authoritative_cost(b)\n           ELSE NULL \n         END AS batch_authoritative_unit_cost,\n         CASE \n           WHEN b.id IS NOT NULL \n           THEN ROUND(sii.quantity * public.calculate_batch_authoritative_cost(b), 2)\n           WHEN COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0)) IS NOT NULL\n           THEN ROUND(sii.quantity * COALESCE(NULLIF(b.landed_cost_per_unit, 0), NULLIF(b.cost_per_unit, 0), NULLIF(b.import_price, 0)), 2)\n           ELSE NULL \n         END AS base_line_cost,\n         pc.posted_invoice_cogs\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  LEFT JOIN public.batches b ON b.id = sii.batch_id\n  LEFT JOIN posted_cogs pc ON pc.invoice_id = sii.invoice_id\n  LEFT JOIN posted_item_cogs pic ON pic.line_id = sii.id\n  WHERE si.invoice_date BETWEEN p_start_date AND p_end_date\n    AND NOT COALESCE(si.is_draft, false)\n), invoice_evidence AS (\n  SELECT invoice_id,\n         COUNT(*) AS invoice_line_count,\n         COUNT(DISTINCT product_id) AS invoice_product_count,\n         COUNT(*) FILTER (WHERE base_line_cost IS NULL AND snapshot_cogs IS NULL) AS unresolved_line_count,\n         COUNT(*) FILTER (WHERE base_line_cost IS NULL AND snapshot_cogs IS NULL AND base_line_cost IS NOT NULL) AS unresolved_base_line_count,\n         COALESCE(SUM(COALESCE(base_line_cost, snapshot_cogs)), 0) AS resolved_cogs_total,\n         SUM(base_line_cost) FILTER (WHERE base_line_cost IS NULL AND snapshot_cogs IS NULL) AS unresolved_base_cost_total,\n         MAX(posted_invoice_cogs) AS posted_invoice_cogs\n  FROM line_basis GROUP BY invoice_id\n), resolved AS (\n  SELECT lb.*, ie.invoice_line_count, ie.invoice_product_count,\n         ie.unresolved_line_count, ie.unresolved_base_line_count,\n         ie.resolved_cogs_total, ie.unresolved_base_cost_total,\n         ie.posted_invoice_cogs AS invoice_posted_cogs,\n         ie.posted_invoice_cogs - ie.resolved_cogs_total AS residual_posted_cogs,\n         ABS(ie.unresolved_base_cost_total - (ie.posted_invoice_cogs - ie.resolved_cogs_total)) AS reconciliation_difference\n  FROM line_basis lb JOIN invoice_evidence ie ON ie.invoice_id = lb.invoice_id\n)\nSELECT r.line_id, r.invoice_id, r.product_id, r.batch_id, r.quantity,\n  -- 1. Canonical batch cost is the primary authoritative source for sales profitability\n  -- 2. Snapshot cost is secondary (synchronized to canonical batch cost)\n  -- 3. Inferred / allocated GL COGS if batch cost is absent\n  -- 4. Under no circumstances can a standalone delta adjustment journal overwrite full line COGS\n  CASE\n    WHEN r.base_line_cost IS NOT NULL AND r.base_line_cost > 0 THEN r.base_line_cost\n    WHEN r.snapshot_cogs IS NOT NULL AND r.snapshot_cogs > 0 THEN r.snapshot_cogs\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL AND r.invoice_posted_cogs > 0 THEN r.invoice_posted_cogs\n    WHEN r.invoice_line_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      THEN r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)\n    WHEN r.posted_item_cogs IS NOT NULL AND r.posted_item_cogs > 0 THEN r.posted_item_cogs\n    WHEN r.base_line_cost IS NOT NULL THEN r.base_line_cost\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs\n    ELSE NULL \n  END AS authoritative_cogs,\n  CASE\n    WHEN r.quantity = 0 THEN NULL\n    WHEN r.base_line_cost IS NOT NULL AND r.base_line_cost > 0 THEN r.base_line_cost / r.quantity\n    WHEN r.snapshot_cogs IS NOT NULL AND r.snapshot_cogs > 0 THEN r.snapshot_cogs / r.quantity\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL AND r.invoice_posted_cogs > 0 THEN r.invoice_posted_cogs / r.quantity\n    WHEN r.invoice_line_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count\n      AND r.unresolved_base_cost_total > 0\n      THEN (r.base_line_cost * (r.residual_posted_cogs / r.unresolved_base_cost_total)) / r.quantity\n    WHEN r.posted_item_cogs IS NOT NULL AND r.posted_item_cogs > 0 THEN r.posted_item_cogs / r.quantity\n    WHEN r.base_line_cost IS NOT NULL THEN r.base_line_cost / r.quantity\n    WHEN r.snapshot_cogs IS NOT NULL THEN r.snapshot_cogs / r.quantity\n    ELSE NULL \n  END AS authoritative_unit_cogs,\n  CASE\n    WHEN r.base_line_cost IS NOT NULL AND r.base_line_cost > 0 THEN 'canonical_batch_cost'\n    WHEN r.snapshot_cogs IS NOT NULL AND r.snapshot_cogs > 0 THEN 'snapshot'\n    WHEN r.invoice_line_count = 1 AND r.invoice_posted_cogs IS NOT NULL AND r.invoice_posted_cogs > 0 THEN 'single_line_posted_cogs'\n    WHEN r.invoice_line_count > 1 AND r.invoice_product_count = 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count AND r.unresolved_base_cost_total > 0 THEN 'single_product_proven_allocation'\n    WHEN r.invoice_line_count > 1 AND r.invoice_product_count > 1 AND r.invoice_posted_cogs IS NOT NULL\n      AND r.unresolved_line_count = r.unresolved_base_line_count AND r.unresolved_base_cost_total > 0 THEN 'multi_product_proven_allocation'\n    WHEN r.posted_item_cogs IS NOT NULL AND r.posted_item_cogs > 0 THEN 'posted_item_cogs'\n    WHEN r.base_line_cost IS NOT NULL THEN 'canonical_batch_cost'\n    WHEN r.snapshot_cogs IS NOT NULL THEN 'snapshot'\n    ELSE 'unresolved' \n  END AS resolution_tier,\n  r.invoice_line_count, r.invoice_product_count, r.invoice_posted_cogs,\n  r.base_line_cost, r.reconciliation_difference\nFROM resolved r;\n$function$","COMMENT ON FUNCTION public.get_authoritative_sales_line_cogs(date, date) IS\n'Returns authoritative sales line COGS prioritizing canonical batch landed cost and snapshots over standalone delta adjustment journals.'","GRANT EXECUTE ON FUNCTION public.get_authoritative_sales_line_cogs(date, date) TO authenticated, service_role"}	fix_product_profitability_authoritative_cogs	\N	\N	\N
20260921175000	{"-- 20260921175000_complete_fx_gain_loss_engine.sql\n-- Complete FX Gain & Loss Accounting Engine\n-- 1. Ensure Account 4930 (Foreign Exchange Gain) exists in chart_of_accounts.\n-- 2. Upgrade post_payment_voucher to compute realized FX gain/loss from allocated invoices' recognition carrying rate.\n-- 3. Maintain strict separation: FX gain/loss goes to 7300/4930, Bank Charges to 7100, AP is relieved for exact carrying IDR.\n\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM public.chart_of_accounts WHERE code = '4930') THEN\n    INSERT INTO public.chart_of_accounts (\n      code, name, name_id, account_type, account_group, normal_balance, is_active, description\n    ) VALUES (\n      '4930', 'Foreign Exchange Gain', 'Keuntungan Selisih Kurs', 'revenue', 'Other Income', 'credit', true, 'Realized and unrealized foreign exchange gains'\n    );\n  END IF;\nEND $$","CREATE OR REPLACE FUNCTION public.post_payment_voucher(p_pv_id uuid, p_posted_by uuid DEFAULT NULL::uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_pv RECORD;\n  v_rate numeric;\n  v_gross numeric;\n  v_payment numeric;\n  v_converted numeric;\n  v_pph_bank numeric;\n  v_charge_amt numeric;\n  v_actual numeric;\n  v_expected numeric;\n  v_bank_spread numeric;\n  v_ap_debit numeric;\n  v_total_debit numeric;\n  v_total_credit numeric;\n  v_entry text;\n  v_je uuid;\n  v_line integer := 1;\n  v_ap uuid;\n  v_bank uuid;\n  v_charge uuid;\n  v_pph uuid;\n  v_fx_loss uuid;\n  v_fx_gain uuid;\n  v_invoice_currency text;\n  v_bank_currency text;\n  v_actual_poster uuid;\n  v_alloc_usd numeric := 0;\n  v_alloc_carrying_idr numeric := 0;\n  v_alloc_settle_idr numeric := 0;\n  v_realized_fx numeric := 0;\n  v_total_fx_loss numeric := 0;\n  v_total_fx_gain numeric := 0;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actual_poster := COALESCE(auth.uid(), p_posted_by);\n\n  SELECT * INTO v_pv FROM public.payment_vouchers WHERE id = p_pv_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found', p_pv_id; END IF;\n  IF v_pv.is_posted THEN RAISE EXCEPTION 'Payment voucher % is already posted', v_pv.voucher_number; END IF;\n\n  v_invoice_currency := upper(COALESCE(v_pv.invoice_currency, v_pv.transaction_currency, v_pv.payment_currency, 'IDR'));\n  SELECT upper(currency) INTO v_bank_currency FROM public.bank_accounts WHERE id = v_pv.bank_account_id;\n  v_bank_currency := COALESCE(v_bank_currency, v_pv.bank_currency, v_pv.payment_currency, 'IDR');\n  \n  v_rate := CASE WHEN v_invoice_currency = v_bank_currency THEN 1 ELSE COALESCE(v_pv.exchange_rate, 0) END;\n  IF v_rate <= 0 THEN RAISE EXCEPTION 'Missing exchange rate for %', v_pv.voucher_number; END IF;\n\n  v_gross := COALESCE(v_pv.invoice_amount, v_pv.amount, 0);\n  v_payment := COALESCE(v_pv.payment_amount, v_gross - COALESCE(v_pv.pph_amount, 0));\n  v_converted := COALESCE(v_pv.converted_amount, v_payment * v_rate);\n  v_pph_bank := COALESCE(v_pv.pph_amount, 0) * v_rate;\n  v_charge_amt := COALESCE(v_pv.bank_charge, 0);\n  v_actual := COALESCE(v_pv.actual_bank_debit, v_pv.bank_amount, v_converted + v_charge_amt);\n  v_expected := v_converted + v_charge_amt;\n  v_bank_spread := v_actual - v_expected;\n\n  -- Compute multi-allocation invoice carrying value vs settlement value\n  IF v_invoice_currency <> v_bank_currency THEN\n    SELECT \n      COALESCE(SUM(va.allocated_amount), 0),\n      COALESCE(SUM(va.allocated_amount * COALESCE(pi.exchange_rate, v_rate)), 0),\n      COALESCE(SUM(va.allocated_amount * v_rate), 0)\n    INTO v_alloc_usd, v_alloc_carrying_idr, v_alloc_settle_idr\n    FROM public.voucher_allocations va\n    JOIN public.purchase_invoices pi ON pi.id = va.purchase_invoice_id\n    WHERE va.payment_voucher_id = p_pv_id;\n\n    IF v_alloc_usd > 0 THEN\n      -- AP is debited for exact carrying amount of settled invoices + remaining unallocated at PV rate\n      v_ap_debit := v_alloc_carrying_idr + ((v_gross - v_alloc_usd) * v_rate);\n      v_realized_fx := v_alloc_settle_idr - v_alloc_carrying_idr;\n    ELSE\n      v_ap_debit := v_gross * v_rate;\n      v_realized_fx := 0;\n    END IF;\n  ELSE\n    v_ap_debit := v_gross * v_rate;\n    v_realized_fx := 0;\n  END IF;\n\n  IF v_realized_fx > 0 THEN\n    v_total_fx_loss := v_realized_fx;\n  ELSIF v_realized_fx < 0 THEN\n    v_total_fx_gain := abs(v_realized_fx);\n  END IF;\n\n  -- Resolve GL Accounts\n  IF v_pv.coa_account_id IS NOT NULL THEN\n    v_ap := v_pv.coa_account_id;\n  ELSE\n    SELECT id INTO v_ap FROM public.chart_of_accounts WHERE code = '2110' LIMIT 1;\n  END IF;\n\n  IF v_pv.payment_method = 'advance_adjustment' OR v_pv.payment_purpose = 'salary_advance' THEN\n    SELECT id INTO v_bank FROM public.chart_of_accounts WHERE code = '1160' LIMIT 1;\n  ELSE\n    SELECT coa_id INTO v_bank FROM public.bank_accounts WHERE id = v_pv.bank_account_id;\n    IF v_bank IS NULL THEN SELECT id INTO v_bank FROM public.chart_of_accounts WHERE code = '1101' LIMIT 1; END IF;\n  END IF;\n\n  SELECT id INTO v_charge FROM public.chart_of_accounts WHERE code = '7100' LIMIT 1;\n  SELECT id INTO v_pph FROM public.chart_of_accounts WHERE code = '2132' LIMIT 1;\n  SELECT id INTO v_fx_loss FROM public.chart_of_accounts WHERE code = '7300' LIMIT 1;\n  SELECT id INTO v_fx_gain FROM public.chart_of_accounts WHERE code = '4930' LIMIT 1;\n\n  IF v_ap IS NULL OR v_bank IS NULL THEN RAISE EXCEPTION 'Required payment accounts are missing'; END IF;\n  IF v_pph_bank > 0 AND v_pph IS NULL THEN RAISE EXCEPTION 'PPh payable account is missing'; END IF;\n\n  -- Determine balanced journal totals\n  v_total_debit := v_ap_debit + v_charge_amt + v_total_fx_loss + GREATEST(v_bank_spread, 0);\n  v_total_credit := v_actual + v_pph_bank + v_total_fx_gain + GREATEST(-v_bank_spread, 0);\n\n  v_entry := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries(\n    entry_number, entry_date, source_module, reference_id, reference_number, description,\n    total_debit, total_credit, is_posted, posted_by, transaction_currency, functional_currency, exchange_rate\n  ) VALUES (\n    v_entry, v_pv.voucher_date, 'payment', v_pv.id, v_pv.voucher_number, 'Payment Voucher: ' || v_pv.voucher_number,\n    v_total_debit, v_total_credit, true, v_actual_poster, v_invoice_currency, 'IDR', v_rate\n  ) RETURNING id INTO v_je;\n\n  -- Line: AP Debit (carrying basis)\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id\n  ) VALUES (\n    v_je, v_line, v_ap, 'Payment - ' || v_pv.voucher_number, v_ap_debit, 0,\n    v_invoice_currency, v_gross, 0, v_rate, v_pv.supplier_id\n  );\n  v_line := v_line + 1;\n\n  -- Line: Bank Charge\n  IF v_charge_amt > 0 AND v_charge IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id\n    ) VALUES (\n      v_je, v_line, v_charge, 'Bank Charge - ' || v_pv.voucher_number, v_charge_amt, 0,\n      v_bank_currency, v_charge_amt, 0, 1, v_pv.supplier_id\n    );\n    v_line := v_line + 1;\n  END IF;\n\n  -- Line: Realized FX Loss\n  IF v_total_fx_loss > 0 AND v_fx_loss IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id\n    ) VALUES (\n      v_je, v_line, v_fx_loss, 'Realized FX loss - ' || v_pv.voucher_number, v_total_fx_loss, 0,\n      'IDR', v_total_fx_loss, 0, 1, v_pv.supplier_id\n    );\n    v_line := v_line + 1;\n  END IF;\n\n  -- Line: Bank Spread (if bank charged more than expected debit)\n  IF v_bank_spread > 0 AND v_charge IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id\n    ) VALUES (\n      v_je, v_line, v_charge, 'Bank conversion spread - ' || v_pv.voucher_number, v_bank_spread, 0,\n      v_bank_currency, v_bank_spread, 0, 1, v_pv.supplier_id\n    );\n    v_line := v_line + 1;\n  END IF;\n\n  -- Line: PPh Withholding\n  IF v_pph_bank > 0 AND v_pph IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id\n    ) VALUES (\n      v_je, v_line, v_pph, 'PPh Withholding - ' || v_pv.voucher_number, 0, v_pph_bank,\n      v_bank_currency, 0, v_pv.pph_amount, v_rate, v_pv.supplier_id\n    );\n    v_line := v_line + 1;\n  END IF;\n\n  -- Line: Realized FX Gain\n  IF v_total_fx_gain > 0 AND v_fx_gain IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id\n    ) VALUES (\n      v_je, v_line, v_fx_gain, 'Realized FX gain - ' || v_pv.voucher_number, 0, v_total_fx_gain,\n      'IDR', 0, v_total_fx_gain, 1, v_pv.supplier_id\n    );\n    v_line := v_line + 1;\n  END IF;\n\n  -- Line: Bank Spread Credit (if bank charged less than expected debit)\n  IF v_bank_spread < 0 AND v_fx_gain IS NOT NULL THEN\n    INSERT INTO public.journal_entry_lines(\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id\n    ) VALUES (\n      v_je, v_line, v_fx_gain, 'Bank conversion spread - ' || v_pv.voucher_number, 0, abs(v_bank_spread),\n      v_bank_currency, 0, abs(v_bank_spread), 1, v_pv.supplier_id\n    );\n    v_line := v_line + 1;\n  END IF;\n\n  -- Line: Bank / Cash Credit\n  INSERT INTO public.journal_entry_lines(\n    journal_entry_id, line_number, account_id, description, debit, credit,\n    transaction_currency, transaction_debit, transaction_credit, exchange_rate, supplier_id\n  ) VALUES (\n    v_je, v_line, v_bank,\n    CASE WHEN v_pv.payment_method = 'advance_adjustment' THEN 'Advance Adjustment - ' ELSE 'Bank Payment - ' END || v_pv.voucher_number,\n    0, v_actual, v_bank_currency, 0, v_actual, 1, v_pv.supplier_id\n  );\n\n  UPDATE public.payment_vouchers SET is_posted = true, journal_entry_id = v_je WHERE id = p_pv_id;\n  INSERT INTO public.audit_logs(table_name, record_id, action_type, old_values, new_values, user_id)\n  VALUES('payment_vouchers', p_pv_id, 'update', jsonb_build_object('is_posted', false), jsonb_build_object('is_posted', true, 'journal_entry_id', v_je), v_actual_poster);\nEND;\n$function$","REVOKE ALL ON FUNCTION public.post_payment_voucher(uuid, uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.post_payment_voucher(uuid, uuid) TO authenticated, service_role"}	complete_fx_gain_loss_engine	\N	\N	\N
20260921175500	{"-- 20260921175500_complete_receipt_fx_engine.sql\n-- Complete Customer Receipt FX Engine\n-- Support cross-currency customer receipts with realized FX gain/loss:\n-- Dr Bank (Actual IDR received)\n-- Cr AR (Carrying value settled)\n-- Dr 7300 FX Loss (if actual IDR received < carrying value)\n-- Cr 4930 FX Gain (if actual IDR received > carrying value)\n\nCREATE OR REPLACE FUNCTION public.post_receipt_voucher(p_rv_id uuid, p_posted_by uuid DEFAULT NULL::uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_rv                 RECORD;\n  v_je_id              UUID;\n  v_je_number          TEXT;\n  v_debit_account_id   UUID;\n  v_credit_account_id  UUID;\n  v_fx_loss_id         UUID;\n  v_fx_gain_id         UUID;\n  v_actual_poster      UUID;\n  v_rate               NUMERIC := 1;\n  v_actual_received    NUMERIC;\n  v_carrying_ar        NUMERIC;\n  v_realized_fx        NUMERIC := 0;\n  v_total_debit        NUMERIC;\n  v_total_credit       NUMERIC;\n  v_line               INTEGER := 1;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actual_poster := COALESCE(auth.uid(), p_posted_by);\n\n  SELECT * INTO v_rv FROM receipt_vouchers WHERE id = p_rv_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id; END IF;\n  IF v_rv.is_posted THEN RAISE EXCEPTION 'Receipt voucher % is already posted', v_rv.voucher_number; END IF;\n\n  IF v_rv.bank_account_id IS NOT NULL THEN\n    SELECT coa_id INTO v_debit_account_id FROM bank_accounts WHERE id = v_rv.bank_account_id;\n  ELSIF v_rv.payment_method = 'cash' THEN\n    SELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\n  END IF;\n  IF v_debit_account_id IS NULL THEN\n    SELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\n  END IF;\n\n  IF v_rv.coa_account_id IS NOT NULL THEN\n    v_credit_account_id := v_rv.coa_account_id;\n  ELSE\n    SELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1120' LIMIT 1;\n  END IF;\n\n  SELECT id INTO v_fx_loss_id FROM chart_of_accounts WHERE code = '7300' LIMIT 1;\n  SELECT id INTO v_fx_gain_id FROM chart_of_accounts WHERE code = '4930' LIMIT 1;\n\n  IF v_debit_account_id IS NULL OR v_credit_account_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot post: required chart of accounts entries missing';\n  END IF;\n\n  v_rate := COALESCE(v_rv.exchange_rate, 1);\n  IF v_rate <= 0 THEN v_rate := 1; END IF;\n\n  -- If cross-currency receipt:\n  -- v_rv.amount is in receipt currency, v_rv.bank_amount or v_rv.settlement_amount is actual bank receipt in IDR\n  v_actual_received := COALESCE(v_rv.settlement_amount, v_rv.bank_amount, v_rv.amount * v_rate);\n  v_carrying_ar := v_rv.amount * v_rate; -- Default carrying if standard IDR invoice\n\n  -- If sales invoice has carrying rate:\n  IF EXISTS (SELECT 1 FROM voucher_allocations va JOIN sales_invoices si ON si.id = va.sales_invoice_id WHERE va.receipt_voucher_id = p_rv_id) THEN\n    -- In SAPJ ERP, sales_invoices are currently IDR.\n    -- If allocated amount in IDR differs from actual bank receipt, difference is bank FX / spread\n    SELECT \n      COALESCE(SUM(va.allocated_amount), v_carrying_ar)\n    INTO v_carrying_ar\n    FROM voucher_allocations va\n    WHERE va.receipt_voucher_id = p_rv_id;\n  END IF;\n\n  -- Realized FX for Customer Receipt:\n  -- Actual IDR Received - Carrying AR\n  -- If > 0: Received MORE than carrying AR -> FX GAIN (Credit 4930)\n  -- If < 0: Received LESS than carrying AR -> FX LOSS (Debit 7300)\n  v_realized_fx := v_actual_received - v_carrying_ar;\n\n  v_total_debit := v_actual_received + CASE WHEN v_realized_fx < 0 THEN abs(v_realized_fx) ELSE 0 END;\n  v_total_credit := v_carrying_ar + CASE WHEN v_realized_fx > 0 THEN v_realized_fx ELSE 0 END;\n\n  v_je_number := next_journal_entry_number();\n\n  INSERT INTO journal_entries (\n    entry_number, entry_date, source_module, reference_id, reference_number,\n    description, total_debit, total_credit, is_posted, posted_by,\n    transaction_currency, functional_currency, exchange_rate\n  ) VALUES (\n    v_je_number, v_rv.voucher_date, 'receipt', v_rv.id, v_rv.voucher_number,\n    'Receipt Voucher: ' || v_rv.voucher_number,\n    v_total_debit, v_total_credit, TRUE, v_actual_poster,\n    COALESCE(v_rv.payment_currency, 'IDR'), 'IDR', v_rate\n  ) RETURNING id INTO v_je_id;\n\n  -- Line 1: Debit Bank/Cash with Actual IDR received\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, v_line, v_debit_account_id, 'Cash Receipt - ' || v_rv.voucher_number, v_actual_received, 0, v_rv.customer_id);\n  v_line := v_line + 1;\n\n  -- Line 2: Debit FX Loss if Received Less than Carrying\n  IF v_realized_fx < 0 AND v_fx_loss_id IS NOT NULL THEN\n    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n    VALUES (v_je_id, v_line, v_fx_loss_id, 'Realized FX loss - ' || v_rv.voucher_number, abs(v_realized_fx), 0, v_rv.customer_id);\n    v_line := v_line + 1;\n  END IF;\n\n  -- Line 3: Credit AR with Carrying Value\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, v_line, v_credit_account_id, 'Receipt - ' || v_rv.voucher_number, 0, v_carrying_ar, v_rv.customer_id);\n  v_line := v_line + 1;\n\n  -- Line 4: Credit FX Gain if Received More than Carrying\n  IF v_realized_fx > 0 AND v_fx_gain_id IS NOT NULL THEN\n    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n    VALUES (v_je_id, v_line, v_fx_gain_id, 'Realized FX gain - ' || v_rv.voucher_number, 0, v_realized_fx, v_rv.customer_id);\n    v_line := v_line + 1;\n  END IF;\n\n  UPDATE receipt_vouchers\n  SET is_posted = TRUE, journal_entry_id = v_je_id\n  WHERE id = p_rv_id;\n\n  INSERT INTO audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)\n  VALUES (\n    'receipt_vouchers', p_rv_id, 'update',\n    jsonb_build_object('is_posted', FALSE),\n    jsonb_build_object('is_posted', TRUE, 'journal_entry_id', v_je_id, 'journal_entry_number', v_je_number, 'posted_by', v_actual_poster),\n    v_actual_poster\n  );\nEND;\n$$","REVOKE ALL ON FUNCTION public.post_receipt_voucher(uuid, uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.post_receipt_voucher(uuid, uuid) TO authenticated, service_role"}	complete_receipt_fx_engine	\N	\N	\N
20260921190000	{"-- Migration: 20260921190000_stage_b_fifo_cogs_engine.sql\n-- Description: Implement Stage B — Chronological FIFO COGS Engine using purchase_batch_cost_layers.\n\nBEGIN","-- 1. Add cogs_layer_allocations to sales_invoice_items to preserve layer consumption history\nALTER TABLE public.sales_invoice_items\n  ADD COLUMN IF NOT EXISTS cogs_layer_allocations jsonb","COMMENT ON COLUMN public.sales_invoice_items.cogs_layer_allocations IS\n  'Array of purchase_batch_cost_layers consumed for this sales item, including layer_id, pi_number, quantity, and unit cost.'","-- 2. Reconcile B108/2026 and B109/2026 layers to align with PO/25-26/014 and physical receipts\n-- B108/2026: 10,000 kg (functional total: 92,352,000.00, landed: 5,815,553.20, final unit: 9816.76)\nUPDATE public.purchase_batch_cost_layers pbcl\n   SET quantity = 10000.000,\n       functional_total_cost = 92352000.00,\n       landed_cost_amount = 5815553.20,\n       final_functional_unit_cost = 9816.76\n  FROM public.batches b\n WHERE b.id = pbcl.batch_id\n   AND b.batch_number = 'B108/2026'","UPDATE public.purchase_invoice_receiving_allocations pira\n   SET received_quantity = 10000.000,\n       functional_total_cost = 92352000.00\n  FROM public.batches b\n WHERE b.id = pira.batch_id\n   AND b.batch_number = 'B108/2026'","-- B109/2026: 9,000 kg (functional total: 83,116,800.00, landed: 5,233,997.88, final unit: 9816.76)\nUPDATE public.purchase_batch_cost_layers pbcl\n   SET quantity = 9000.000,\n       functional_total_cost = 83116800.00,\n       landed_cost_amount = 5233997.88,\n       final_functional_unit_cost = 9816.76\n  FROM public.batches b\n WHERE b.id = pbcl.batch_id\n   AND b.batch_number = 'B109/2026'","UPDATE public.purchase_invoice_receiving_allocations pira\n   SET received_quantity = 9000.000,\n       functional_total_cost = 83116800.00\n  FROM public.batches b\n WHERE b.id = pira.batch_id\n   AND b.batch_number = 'B109/2026'","-- 3. Function to get layer-aware batch authoritative unit cost (for display and single-layer batches)\nCREATE OR REPLACE FUNCTION public.calculate_batch_authoritative_cost(p_batch public.batches)\nRETURNS numeric\nLANGUAGE plpgsql\nSTABLE\nAS $$\nDECLARE\n  v_layer_count integer;\n  v_weighted_unit_cost numeric;\nBEGIN\n  -- If purchase_batch_cost_layers exist, return the weighted final functional unit cost\n  SELECT COUNT(*),\n         ROUND(SUM(pbcl.quantity * pbcl.final_functional_unit_cost) / NULLIF(SUM(pbcl.quantity), 0), 4)\n    INTO v_layer_count, v_weighted_unit_cost\n    FROM public.purchase_batch_cost_layers pbcl\n   WHERE pbcl.batch_id = p_batch.id;\n\n  IF v_layer_count > 0 AND v_weighted_unit_cost IS NOT NULL AND v_weighted_unit_cost > 0 THEN\n    RETURN v_weighted_unit_cost;\n  END IF;\n\n  -- Fallback to landed_cost_per_unit or cost_per_unit\n  RETURN COALESCE(\n    NULLIF(p_batch.landed_cost_per_unit, 0),\n    NULLIF(p_batch.cost_per_unit, 0),\n    NULLIF(p_batch.import_price, 0),\n    0\n  );\nEND;\n$$","-- 4. Function: effective_sales_cogs_unit_cost (layer-aware)\nCREATE OR REPLACE FUNCTION public.effective_sales_cogs_unit_cost(p_batch_id uuid)\nRETURNS numeric\nLANGUAGE plpgsql\nSTABLE\nAS $$\nDECLARE\n  v_batch public.batches%ROWTYPE;\nBEGIN\n  SELECT * INTO v_batch FROM public.batches WHERE id = p_batch_id;\n  IF NOT FOUND THEN RETURN 0; END IF;\n  RETURN public.calculate_batch_authoritative_cost(v_batch);\nEND;\n$$","-- 5. Enhanced propagate_batch_cost_change using true chronological FIFO layer consumption\nCREATE OR REPLACE FUNCTION public.propagate_batch_cost_change(p_batch_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_batch public.batches%ROWTYPE;\n  v_layer_count integer;\n  v_inv record;\n  v_item record;\n  v_layer record;\n  v_target_item_cogs numeric;\n  v_target_total numeric;\n  v_posted_gl numeric;\n  v_inv_delta numeric;\n  v_je_id uuid;\n  v_je_number text;\n  v_entry_date date;\n  v_period_id uuid;\n  v_period_status text;\n  v_source_module text;\n  v_description text;\n  v_base_ref_num text;\n  v_ref_num text;\n  v_counter integer;\n  v_cogs_account_id uuid;\n  v_inventory_account_id uuid;\n  v_line_number integer;\n  v_adjusted_invoices_count integer := 0;\n  v_adjusted_items_count integer := 0;\n  v_total_delta_posted numeric := 0;\n  \n  -- FIFO simulation variables\n  v_rem_to_consume numeric;\n  v_layer_consume numeric;\n  v_item_fifo_cogs numeric;\n  v_item_layer_alloc jsonb;\n  v_item_delta numeric;\n  v_item_old_cogs numeric;\nBEGIN\n  -- Prevent trigger cascades while allowing normal execution\n  IF current_setting('app.in_cogs_propagation', true) = 'on' THEN\n    RETURN jsonb_build_object('success', true, 'message', 'Propagation already active in current session');\n  END IF;\n\n  PERFORM set_config('app.in_cogs_propagation', 'on', true);\n\n  SELECT * INTO v_batch FROM public.batches WHERE id = p_batch_id FOR UPDATE;\n  IF NOT FOUND THEN\n    PERFORM set_config('app.in_cogs_propagation', 'off', true);\n    RETURN jsonb_build_object('success', false, 'error', 'Batch not found');\n  END IF;\n\n  SELECT id INTO v_cogs_account_id FROM public.chart_of_accounts WHERE code = '5100' LIMIT 1;\n  SELECT id INTO v_inventory_account_id FROM public.chart_of_accounts WHERE code = '1130' LIMIT 1;\n  IF v_cogs_account_id IS NULL OR v_inventory_account_id IS NULL THEN\n    PERFORM set_config('app.in_cogs_propagation', 'off', true);\n    RAISE EXCEPTION 'Missing COGS (5100) or Inventory (1130) account in chart_of_accounts';\n  END IF;\n\n  -- Build temp table for layers of this batch with running remaining quantities\n  DROP TABLE IF EXISTS tmp_batch_fifo_layers;\n  CREATE TEMP TABLE tmp_batch_fifo_layers ON COMMIT DROP AS\n    SELECT \n      pbcl.id as layer_id,\n      pbcl.quantity as original_qty,\n      pbcl.quantity as remaining_qty,\n      pbcl.final_functional_unit_cost as unit_cost,\n      pi.invoice_number as pi_number,\n      COALESCE(pira.received_at, pi.invoice_date::timestamp, pbcl.created_at) as receipt_date\n    FROM public.purchase_batch_cost_layers pbcl\n    LEFT JOIN public.purchase_invoices pi ON pi.id = pbcl.purchase_invoice_id\n    LEFT JOIN public.purchase_invoice_receiving_allocations pira ON pira.id = pbcl.receiving_allocation_id\n   WHERE pbcl.batch_id = p_batch_id\n   ORDER BY receipt_date ASC, pbcl.id ASC;\n\n  SELECT COUNT(*) INTO v_layer_count FROM tmp_batch_fifo_layers;\n\n  -- Iterate through each posted sales invoice containing items from this batch in chronological order\n  FOR v_inv IN\n    SELECT DISTINCT si.id, si.invoice_number, si.invoice_date, si.customer_id, si.created_by\n      FROM public.sales_invoices si\n      JOIN public.sales_invoice_items sii ON sii.invoice_id = si.id\n     WHERE sii.batch_id = p_batch_id\n       AND NOT COALESCE(si.is_draft, false)\n     ORDER BY si.invoice_date ASC, si.id ASC\n  LOOP\n    -- Iterate through each item in this invoice for this batch\n    FOR v_item IN\n      SELECT sii.id, sii.quantity, COALESCE(sii.cogs_total_cost, 0) as old_cogs\n        FROM public.sales_invoice_items sii\n       WHERE sii.invoice_id = v_inv.id\n         AND sii.batch_id = p_batch_id\n       ORDER BY sii.id\n    LOOP\n      v_rem_to_consume := COALESCE(v_item.quantity, 0);\n      v_item_fifo_cogs := 0;\n      v_item_layer_alloc := '[]'::jsonb;\n\n      IF v_layer_count > 0 THEN\n        FOR v_layer IN\n          SELECT * FROM tmp_batch_fifo_layers\n           WHERE remaining_qty > 0.00001\n           ORDER BY receipt_date ASC, layer_id ASC\n        LOOP\n          EXIT WHEN v_rem_to_consume <= 0.00001;\n          v_layer_consume := LEAST(v_layer.remaining_qty, v_rem_to_consume);\n          v_item_fifo_cogs := v_item_fifo_cogs + (v_layer_consume * v_layer.unit_cost);\n          \n          UPDATE tmp_batch_fifo_layers\n             SET remaining_qty = remaining_qty - v_layer_consume\n           WHERE layer_id = v_layer.layer_id;\n\n          v_item_layer_alloc := v_item_layer_alloc || jsonb_build_object(\n            'layer_id', v_layer.layer_id,\n            'pi_number', v_layer.pi_number,\n            'receipt_date', v_layer.receipt_date,\n            'consumed_qty', v_layer_consume,\n            'unit_cost', v_layer.unit_cost,\n            'cost', ROUND(v_layer_consume * v_layer.unit_cost, 2)\n          );\n\n          v_rem_to_consume := v_rem_to_consume - v_layer_consume;\n        END LOOP;\n      ELSE\n        -- Fallback to scalar batch cost if no layers exist\n        v_item_fifo_cogs := v_rem_to_consume * COALESCE(v_batch.landed_cost_per_unit, v_batch.cost_per_unit, 0);\n      END IF;\n\n      v_target_item_cogs := ROUND(v_item_fifo_cogs, 2);\n\n      -- Update snapshot on sales_invoice_items\n      UPDATE public.sales_invoice_items\n         SET cogs_unit_cost = CASE WHEN v_item.quantity > 0 THEN ROUND(v_target_item_cogs / v_item.quantity, 4) ELSE 0 END,\n             cogs_total_cost = v_target_item_cogs,\n             cogs_layer_allocations = v_item_layer_alloc\n       WHERE id = v_item.id;\n\n      v_adjusted_items_count := v_adjusted_items_count + 1;\n    END LOOP;\n\n    -- Now calculate invoice-level target total across ALL items of this invoice\n    SELECT COALESCE(SUM(sii_all.cogs_total_cost), 0)\n      INTO v_target_total\n      FROM public.sales_invoice_items sii_all\n     WHERE sii_all.invoice_id = v_inv.id;\n\n    -- Calculate total posted GL 5100 for this invoice across all active journals\n    SELECT COALESCE(SUM(jel.debit - jel.credit), 0)\n      INTO v_posted_gl\n      FROM public.journal_entries je\n      JOIN public.journal_entry_lines jel ON jel.journal_entry_id = je.id\n      JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n     WHERE je.reference_id = v_inv.id\n       AND coa.code = '5100'\n       AND je.is_posted = true\n       AND NOT COALESCE(je.is_reversed, false);\n\n    v_inv_delta := ROUND(v_target_total - v_posted_gl, 2);\n\n    IF ABS(v_inv_delta) >= 0.01 THEN\n      SELECT ap.status INTO v_period_status\n        FROM public.accounting_periods ap\n       WHERE ap.start_date <= v_inv.invoice_date AND ap.end_date >= v_inv.invoice_date\n       ORDER BY ap.start_date DESC LIMIT 1;\n\n      IF v_period_status = 'open' THEN\n        v_entry_date := v_inv.invoice_date;\n      ELSE\n        v_entry_date := CURRENT_DATE;\n      END IF;\n\n      SELECT id INTO v_period_id\n        FROM public.accounting_periods\n       WHERE start_date <= v_entry_date AND end_date >= v_entry_date\n       ORDER BY start_date DESC LIMIT 1;\n\n      v_source_module := 'sales_invoice_cogs_adjustment';\n      v_description := 'FIFO COGS True-Up: ' || v_inv.invoice_number || ' (Batch ' || v_batch.batch_number || ')';\n      v_base_ref_num := v_inv.invoice_number || '-FIFO-ADJ';\n      v_ref_num := v_base_ref_num;\n      v_counter := 2;\n      WHILE EXISTS (\n        SELECT 1 FROM public.journal_entries\n         WHERE source_module = v_source_module\n           AND reference_number = v_ref_num\n           AND NOT COALESCE(is_reversed, false)\n      ) LOOP\n        v_ref_num := v_base_ref_num || '-' || v_counter;\n        v_counter := v_counter + 1;\n      END LOOP;\n\n      v_je_number := public.next_journal_entry_number();\n\n      INSERT INTO public.journal_entries (\n        entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n        description, total_debit, total_credit, is_posted, posted_by, created_by\n      ) VALUES (\n        v_je_number, v_entry_date, v_period_id, v_source_module, v_inv.id, v_ref_num,\n        v_description, ABS(v_inv_delta), ABS(v_inv_delta),\n        true, COALESCE(auth.uid(), v_inv.created_by), COALESCE(auth.uid(), v_inv.created_by)\n      ) RETURNING id INTO v_je_id;\n\n      v_line_number := 1;\n\n      IF v_inv_delta > 0 THEN\n        -- Target > Posted: Debit 5100 COGS, Credit 1130 Inventory\n        INSERT INTO public.journal_entry_lines (\n          journal_entry_id, line_number, account_id, description, debit, credit,\n          customer_id, batch_id\n        ) VALUES (\n          v_je_id, v_line_number, v_cogs_account_id,\n          'FIFO COGS adjustment - ' || v_inv.invoice_number, v_inv_delta, 0,\n          v_inv.customer_id, p_batch_id\n        );\n        v_line_number := v_line_number + 1;\n\n        INSERT INTO public.journal_entry_lines (\n          journal_entry_id, line_number, account_id, description, debit, credit,\n          customer_id, batch_id\n        ) VALUES (\n          v_je_id, v_line_number, v_inventory_account_id,\n          'FIFO Inventory revaluation - ' || v_inv.invoice_number, 0, v_inv_delta,\n          v_inv.customer_id, p_batch_id\n        );\n      ELSE\n        -- Target < Posted: Debit 1130 Inventory, Credit 5100 COGS\n        INSERT INTO public.journal_entry_lines (\n          journal_entry_id, line_number, account_id, description, debit, credit,\n          customer_id, batch_id\n        ) VALUES (\n          v_je_id, v_line_number, v_inventory_account_id,\n          'FIFO Inventory revaluation (downward) - ' || v_inv.invoice_number, ABS(v_inv_delta), 0,\n          v_inv.customer_id, p_batch_id\n        );\n        v_line_number := v_line_number + 1;\n\n        INSERT INTO public.journal_entry_lines (\n          journal_entry_id, line_number, account_id, description, debit, credit,\n          customer_id, batch_id\n        ) VALUES (\n          v_je_id, v_line_number, v_cogs_account_id,\n          'FIFO COGS adjustment (downward) - ' || v_inv.invoice_number, 0, ABS(v_inv_delta),\n          v_inv.customer_id, p_batch_id\n        );\n      END IF;\n\n      v_adjusted_invoices_count := v_adjusted_invoices_count + 1;\n      v_total_delta_posted := v_total_delta_posted + v_inv_delta;\n    END IF;\n\n  END LOOP;\n\n  PERFORM set_config('app.in_cogs_propagation', 'off', true);\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'batch_id', p_batch_id,\n    'batch_number', v_batch.batch_number,\n    'adjusted_invoices_count', v_adjusted_invoices_count,\n    'adjusted_items_count', v_adjusted_items_count,\n    'total_delta_posted', v_total_delta_posted\n  );\nEND;\n$$","-- 6. Refactor post_sales_invoice_cogs() trigger for future sales to use FIFO cost layers\nCREATE OR REPLACE FUNCTION public.post_sales_invoice_cogs()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_existing_cogs_je_id uuid;\n  v_je_id uuid;\n  v_je_number text;\n  v_cogs_account_id uuid;\n  v_inventory_account_id uuid;\n  v_period_id uuid;\n  v_item record;\n  v_layer record;\n  v_rem_to_consume numeric;\n  v_layer_consume numeric;\n  v_item_fifo_cogs numeric;\n  v_item_alloc jsonb;\n  v_total_cogs numeric := 0;\n  v_line_number integer := 1;\n  v_snapshot_item_ids uuid[] := ARRAY[]::uuid[];\n  v_snapshot_unit_costs numeric[] := ARRAY[]::numeric[];\n  v_snapshot_total_costs numeric[] := ARRAY[]::numeric[];\n  v_snapshot_allocs jsonb[] := ARRAY[]::jsonb[];\nBEGIN\n  IF NEW.journal_entry_id IS NULL THEN RETURN NEW; END IF;\n  IF NEW.payment_status NOT IN ('pending', 'partial', 'paid') THEN RETURN NEW; END IF;\n\n  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.id::text, 0));\n\n  SELECT id INTO v_existing_cogs_je_id\n    FROM public.journal_entries\n   WHERE source_module = 'sales_invoice_cogs'\n     AND reference_id = NEW.id\n   LIMIT 1;\n  IF v_existing_cogs_je_id IS NOT NULL THEN RETURN NEW; END IF;\n\n  SELECT id INTO v_cogs_account_id FROM public.chart_of_accounts WHERE code = '5100' LIMIT 1;\n  SELECT id INTO v_inventory_account_id FROM public.chart_of_accounts WHERE code = '1130' LIMIT 1;\n  IF v_cogs_account_id IS NULL OR v_inventory_account_id IS NULL THEN\n    RAISE EXCEPTION\n      'post_sales_invoice_cogs: Missing COGS (5100) or Inventory (1130) in chart_of_accounts.';\n  END IF;\n\n  SELECT id INTO v_period_id\n    FROM public.accounting_periods\n   WHERE start_date <= NEW.invoice_date AND end_date >= NEW.invoice_date\n   ORDER BY start_date DESC LIMIT 1;\n\n  FOR v_item IN\n    SELECT sii.id, sii.quantity, sii.batch_id, b.landed_cost_per_unit, b.cost_per_unit\n      FROM public.sales_invoice_items sii\n      LEFT JOIN public.batches b ON b.id = sii.batch_id\n     WHERE sii.invoice_id = NEW.id\n       AND sii.batch_id IS NOT NULL\n     ORDER BY sii.id\n  LOOP\n    v_rem_to_consume := COALESCE(v_item.quantity, 0);\n    v_item_fifo_cogs := 0;\n    v_item_alloc := '[]'::jsonb;\n\n    -- Look up available cost layers for this batch, taking into account prior posted sales\n    FOR v_layer IN\n      WITH prior_sales AS (\n        SELECT COALESCE(SUM(sii_prior.quantity), 0) as prior_consumed\n          FROM public.sales_invoice_items sii_prior\n          JOIN public.sales_invoices si_prior ON si_prior.id = sii_prior.invoice_id\n         WHERE sii_prior.batch_id = v_item.batch_id\n           AND NOT COALESCE(si_prior.is_draft, false)\n           AND (si_prior.invoice_date < NEW.invoice_date \n                OR (si_prior.invoice_date = NEW.invoice_date AND si_prior.id < NEW.id)\n                OR (si_prior.id = NEW.id AND sii_prior.id < v_item.id))\n      ),\n      ordered_layers AS (\n        SELECT \n          pbcl.id as layer_id,\n          pbcl.quantity as layer_qty,\n          pbcl.final_functional_unit_cost as unit_cost,\n          pi.invoice_number as pi_number,\n          COALESCE(pira.received_at, pi.invoice_date::timestamp, pbcl.created_at) as receipt_date,\n          COALESCE(SUM(pbcl.quantity) OVER (\n            ORDER BY COALESCE(pira.received_at, pi.invoice_date::timestamp, pbcl.created_at) ASC, pbcl.id ASC\n            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING\n          ), 0) as prior_layer_qty_sum\n        FROM public.purchase_batch_cost_layers pbcl\n        LEFT JOIN public.purchase_invoices pi ON pi.id = pbcl.purchase_invoice_id\n        LEFT JOIN public.purchase_invoice_receiving_allocations pira ON pira.id = pbcl.receiving_allocation_id\n       WHERE pbcl.batch_id = v_item.batch_id\n      )\n      SELECT \n        ol.layer_id,\n        ol.layer_qty,\n        ol.unit_cost,\n        ol.pi_number,\n        ol.receipt_date,\n        GREATEST(0, ol.layer_qty - GREATEST(0, ps.prior_consumed - ol.prior_layer_qty_sum)) as available_qty\n      FROM ordered_layers ol\n      CROSS JOIN prior_sales ps\n      ORDER BY ol.receipt_date ASC, ol.layer_id ASC\n    LOOP\n      EXIT WHEN v_rem_to_consume <= 0.00001;\n      CONTINUE WHEN v_layer.available_qty <= 0.00001;\n\n      v_layer_consume := LEAST(v_layer.available_qty, v_rem_to_consume);\n      v_item_fifo_cogs := v_item_fifo_cogs + (v_layer_consume * v_layer.unit_cost);\n\n      v_item_alloc := v_item_alloc || jsonb_build_object(\n        'layer_id', v_layer.layer_id,\n        'pi_number', v_layer.pi_number,\n        'receipt_date', v_layer.receipt_date,\n        'consumed_qty', v_layer_consume,\n        'unit_cost', v_layer.unit_cost,\n        'cost', ROUND(v_layer_consume * v_layer.unit_cost, 2)\n      );\n\n      v_rem_to_consume := v_rem_to_consume - v_layer_consume;\n    END LOOP;\n\n    -- If remaining quantity couldn't be satisfied from layers, use batch scalar fallback\n    IF v_rem_to_consume > 0.00001 THEN\n      v_item_fifo_cogs := v_item_fifo_cogs + (v_rem_to_consume * COALESCE(v_item.landed_cost_per_unit, v_item.cost_per_unit, 0));\n    END IF;\n\n    v_item_fifo_cogs := ROUND(v_item_fifo_cogs, 2);\n\n    v_snapshot_item_ids := array_append(v_snapshot_item_ids, v_item.id);\n    v_snapshot_unit_costs := array_append(\n      v_snapshot_unit_costs, \n      CASE WHEN v_item.quantity > 0 THEN ROUND(v_item_fifo_cogs / v_item.quantity, 4) ELSE 0 END\n    );\n    v_snapshot_total_costs := array_append(v_snapshot_total_costs, v_item_fifo_cogs);\n    v_snapshot_allocs := array_append(v_snapshot_allocs, v_item_alloc);\n\n    v_total_cogs := v_total_cogs + v_item_fifo_cogs;\n  END LOOP;\n\n  IF v_total_cogs <= 0 THEN RETURN NEW; END IF;\n\n  -- Update snapshots on sales_invoice_items\n  UPDATE public.sales_invoice_items sii\n     SET cogs_unit_cost = s.unit_cost,\n         cogs_total_cost = s.total_cost,\n         cogs_layer_allocations = s.alloc\n    FROM unnest(\n      v_snapshot_item_ids,\n      v_snapshot_unit_costs,\n      v_snapshot_total_costs,\n      v_snapshot_allocs\n    ) AS s(item_id, unit_cost, total_cost, alloc)\n   WHERE sii.id = s.item_id;\n\n  v_je_number := public.next_journal_entry_number();\n  INSERT INTO public.journal_entries (\n    entry_number, entry_date, period_id, source_module, reference_id, reference_number,\n    description, total_debit, total_credit, is_posted, posted_by, created_by\n  ) VALUES (\n    v_je_number, NEW.invoice_date, v_period_id, 'sales_invoice_cogs', NEW.id, NEW.invoice_number,\n    'COGS for Sales Invoice: ' || NEW.invoice_number,\n    v_total_cogs, v_total_cogs, true, NEW.created_by, NEW.created_by\n  ) RETURNING id INTO v_je_id;\n\n  -- Debit 5100 COGS, Credit 1130 Inventory\n  FOR v_item IN\n    SELECT sii.id, sii.quantity, sii.batch_id, sii.cogs_total_cost\n      FROM public.sales_invoice_items sii\n     WHERE sii.invoice_id = NEW.id\n       AND sii.batch_id IS NOT NULL\n     ORDER BY sii.id\n  LOOP\n    IF COALESCE(v_item.cogs_total_cost, 0) > 0 THEN\n      INSERT INTO public.journal_entry_lines (\n        journal_entry_id, line_number, account_id, description, debit, credit,\n        customer_id, batch_id, sales_invoice_item_id\n      ) VALUES (\n        v_je_id, v_line_number, v_cogs_account_id,\n        'COGS - ' || NEW.invoice_number, v_item.cogs_total_cost, 0,\n        NEW.customer_id, v_item.batch_id, v_item.id\n      );\n      v_line_number := v_line_number + 1;\n\n      INSERT INTO public.journal_entry_lines (\n        journal_entry_id, line_number, account_id, description, debit, credit,\n        customer_id, batch_id, sales_invoice_item_id\n      ) VALUES (\n        v_je_id, v_line_number, v_inventory_account_id,\n        'Inventory reduction - ' || NEW.invoice_number, 0, v_item.cogs_total_cost,\n        NEW.customer_id, v_item.batch_id, v_item.id\n      );\n      v_line_number := v_line_number + 1;\n    END IF;\n  END LOOP;\n\n  RETURN NEW;\nEND;\n$$",COMMIT}	stage_b_fifo_cogs_engine	\N	\N	\N
20260921200000	{"-- Migration: 20260921200000_fix_purchase_invoice_batch_linking.sql\n-- Description: Fix Purchase Invoice batch linking in save_purchase_invoice, save_purchase_invoice_with_receiving_details, and receive_purchase_invoice_item.\n\nBEGIN","-- 1. Refactor save_purchase_invoice to resolve existing batch or create batch and persist purchase_invoice_items.batch_id\nCREATE OR REPLACE FUNCTION public.save_purchase_invoice(p_invoice_id uuid, p_invoice_data jsonb, p_items jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\n  DECLARE\n    v_invoice_id        UUID;\n    v_je_id             UUID;\n    v_je_number         TEXT;\n    v_ap_account_id     UUID;\n    v_ppn_account_id    UUID;\n    v_bm_account_id     UUID;\n    v_account_id        UUID;\n    v_item              JSONB;\n    v_line_number       INTEGER;\n    v_invoice_date      DATE;\n    v_invoice_number    TEXT;\n    v_supplier_id       UUID;\n    v_total_amount      NUMERIC(15,2);\n    v_tax_amount        NUMERIC(15,2);\n    v_stamp_duty_amount NUMERIC(15,2);\n    v_created_by        UUID;\n    v_item_type         TEXT;\n    v_line_total        NUMERIC(15,2);\n    v_item_id           UUID;\n    v_po_id             UUID;\n    v_currency          TEXT;\n    v_rate              NUMERIC;\n\n    -- Batch resolution variables\n    v_product_id        UUID;\n    v_make_id           UUID;\n    v_batch_number      TEXT;\n    v_container_id      UUID;\n    v_expiry_date       DATE;\n    v_quantity          NUMERIC;\n    v_unit_price        NUMERIC;\n    v_unit              TEXT;\n    v_batch_id          UUID;\n    v_resolved_batch_id UUID;\n  BEGIN\n    v_created_by        := auth.uid();\n    v_invoice_date      := (p_invoice_data->>'invoice_date')::DATE;\n    v_invoice_number    := p_invoice_data->>'invoice_number';\n    v_total_amount      := (p_invoice_data->>'total_amount')::NUMERIC(15,2);\n    v_tax_amount        := COALESCE((p_invoice_data->>'tax_amount')::NUMERIC(15,2), 0);\n    v_stamp_duty_amount := COALESCE((p_invoice_data->>'stamp_duty_amount')::NUMERIC(15,2), 0);\n    v_supplier_id       := (p_invoice_data->>'supplier_id')::UUID;\n    v_po_id             := NULLIF(p_invoice_data->>'purchase_order_id', '')::UUID;\n    v_currency := upper(coalesce(p_invoice_data->>'currency', 'IDR'));\n    v_rate := CASE WHEN v_currency = 'IDR' THEN 1 ELSE NULLIF((p_invoice_data->>'exchange_rate')::NUMERIC, 0) END;\n    IF v_currency <> 'IDR' AND (v_rate IS NULL OR v_rate <= 1) THEN\n      RAISE EXCEPTION 'Purchase invoice % requires a valid exchange rate greater than 1', v_invoice_number;\n    END IF;\n\n    SELECT id INTO v_ap_account_id  FROM chart_of_accounts WHERE code = '2110' LIMIT 1;\n    SELECT id INTO v_ppn_account_id FROM chart_of_accounts WHERE code = '1150' LIMIT 1;\n    SELECT id INTO v_bm_account_id  FROM chart_of_accounts WHERE code = '6950' LIMIT 1;\n\n    IF v_ap_account_id IS NULL THEN\n      RAISE EXCEPTION 'A/P account (code 2110) not found in chart of accounts';\n    END IF;\n\n    PERFORM pg_advisory_xact_lock(hashtext('je_number_' || TO_CHAR(v_invoice_date, 'YYMM')));\n\n    IF p_invoice_id IS NULL THEN\n      -- ── CREATE path ──────────────────────────────────────────────────────────\n\n      v_je_number := 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-' || LPAD((\n        SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM '(\\\\d+)$') AS INTEGER)), 0) + 1\n        FROM journal_entries\n        WHERE entry_number LIKE 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-%'\n      )::TEXT, 4, '0');\n\n      INSERT INTO journal_entries (\n        entry_number, entry_date, source_module, reference_id, reference_number,\n        description, total_debit, total_credit, is_posted, posted_by, created_by\n      ) VALUES (\n        v_je_number, v_invoice_date, 'purchase_invoice', gen_random_uuid(), v_invoice_number,\n        'Purchase Invoice: ' || v_invoice_number,\n        0, v_total_amount * v_rate, TRUE, v_created_by, v_created_by\n      ) RETURNING id INTO v_je_id;\n\n      INSERT INTO purchase_invoices (\n        invoice_number, supplier_id, invoice_date, due_date,\n        currency, exchange_rate, subtotal, tax_amount, stamp_duty_amount, total_amount,\n        paid_amount, status,\n        faktur_pajak_number, notes, document_urls,\n        requires_faktur_pajak, purchase_type,\n        purchase_order_id,\n        journal_entry_id, created_by\n      ) VALUES (\n        v_invoice_number,\n        v_supplier_id,\n        v_invoice_date,\n        NULLIF(p_invoice_data->>'due_date', '')::DATE,\n        COALESCE(p_invoice_data->>'currency', 'IDR'),\n        COALESCE((p_invoice_data->>'exchange_rate')::NUMERIC, 1),\n        COALESCE((p_invoice_data->>'subtotal')::NUMERIC, 0),\n        v_tax_amount,\n        v_stamp_duty_amount,\n        v_total_amount,\n        0,\n        'unpaid',\n        NULLIF(p_invoice_data->>'faktur_pajak_number', ''),\n        NULLIF(p_invoice_data->>'notes', ''),\n        CASE\n          WHEN p_invoice_data -> 'document_urls' IS NOT NULL\n            AND jsonb_array_length(p_invoice_data -> 'document_urls') > 0\n          THEN ARRAY(SELECT jsonb_array_elements_text(p_invoice_data -> 'document_urls'))\n          ELSE NULL\n        END,\n        COALESCE((p_invoice_data->>'requires_faktur_pajak')::BOOLEAN, FALSE),\n        COALESCE(p_invoice_data->>'purchase_type', 'inventory'),\n        v_po_id,\n        v_je_id,\n        v_created_by\n      ) RETURNING id INTO v_invoice_id;\n\n      UPDATE journal_entries SET reference_id = v_invoice_id WHERE id = v_je_id;\n\n    ELSE\n      -- ── EDIT path ──────────────────────────────────────────────────────────\n\n      v_invoice_id := p_invoice_id;\n\n      SELECT journal_entry_id INTO v_je_id\n      FROM purchase_invoices WHERE id = v_invoice_id;\n\n      UPDATE purchase_invoices SET\n        invoice_number        = v_invoice_number,\n        supplier_id           = v_supplier_id,\n        invoice_date          = v_invoice_date,\n        due_date              = NULLIF(p_invoice_data->>'due_date', '')::DATE,\n        currency              = COALESCE(p_invoice_data->>'currency', 'IDR'),\n        exchange_rate         = COALESCE((p_invoice_data->>'exchange_rate')::NUMERIC, 1),\n        subtotal              = COALESCE((p_invoice_data->>'subtotal')::NUMERIC, 0),\n        tax_amount            = v_tax_amount,\n        stamp_duty_amount     = v_stamp_duty_amount,\n        total_amount          = v_total_amount,\n        faktur_pajak_number   = NULLIF(p_invoice_data->>'faktur_pajak_number', ''),\n        notes                 = NULLIF(p_invoice_data->>'notes', ''),\n        document_urls         = CASE\n                                  WHEN p_invoice_data -> 'document_urls' IS NOT NULL\n                                    AND jsonb_array_length(p_invoice_data -> 'document_urls') > 0\n                                  THEN ARRAY(SELECT jsonb_array_elements_text(p_invoice_data -> 'document_urls'))\n                                  ELSE NULL\n                                END,\n        requires_faktur_pajak = COALESCE((p_invoice_data->>'requires_faktur_pajak')::BOOLEAN, FALSE),\n        purchase_type         = COALESCE(p_invoice_data->>'purchase_type', 'inventory'),\n        purchase_order_id     = v_po_id,\n        updated_at            = NOW()\n      WHERE id = v_invoice_id;\n\n      IF EXISTS (\n        SELECT 1 FROM purchase_invoice_items i \n        WHERE i.purchase_invoice_id = v_invoice_id \n          AND NOT EXISTS (\n            SELECT 1 FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) x \n            WHERE NULLIF(x->>'id','')::uuid = i.id\n          ) \n          AND (\n            EXISTS (SELECT 1 FROM purchase_invoice_receiving_allocations a WHERE a.purchase_invoice_item_id = i.id) \n            OR i.batch_id IS NOT NULL\n          )\n      ) THEN \n        RAISE EXCEPTION 'Cannot remove invoice line with receiving or inventory history'; \n      END IF;\n\n      DELETE FROM purchase_invoice_items i \n      WHERE i.purchase_invoice_id = v_invoice_id \n        AND NOT EXISTS (\n          SELECT 1 FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) x \n          WHERE NULLIF(x->>'id','')::uuid = i.id\n        );\n\n      IF v_je_id IS NOT NULL THEN\n        DELETE FROM journal_entry_lines WHERE journal_entry_id = v_je_id;\n        UPDATE journal_entries SET\n          entry_date       = v_invoice_date,\n          reference_number = v_invoice_number,\n          description      = 'Purchase Invoice: ' || v_invoice_number,\n          total_debit      = 0,\n          total_credit     = v_total_amount * v_rate\n        WHERE id = v_je_id;\n      ELSE\n        v_je_number := 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-' || LPAD((\n          SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM '(\\\\d+)$') AS INTEGER)), 0) + 1\n          FROM journal_entries\n          WHERE entry_number LIKE 'JE-' || TO_CHAR(v_invoice_date, 'YYMM') || '-%'\n        )::TEXT, 4, '0');\n\n        INSERT INTO journal_entries (\n          entry_number, entry_date, source_module, reference_id, reference_number,\n          description, total_debit, total_credit, is_posted, posted_by, created_by\n        ) VALUES (\n          v_je_number, v_invoice_date, 'purchase_invoice', v_invoice_id, v_invoice_number,\n          'Purchase Invoice: ' || v_invoice_number,\n          0, v_total_amount * v_rate, TRUE, v_created_by, v_created_by\n        ) RETURNING id INTO v_je_id;\n\n        UPDATE purchase_invoices SET journal_entry_id = v_je_id WHERE id = v_invoice_id;\n      END IF;\n    END IF;\n\n    -- ── Insert/Update items and build JE debit lines ───────────────────────────\n    v_line_number := 1;\n\n    FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))\n    LOOP\n      v_item_type    := v_item->>'item_type';\n      v_line_total   := COALESCE((v_item->>'line_total')::NUMERIC(15,2), 0);\n      v_item_id      := NULLIF(v_item->>'id', '')::UUID;\n      v_product_id   := NULLIF(v_item->>'product_id', '')::UUID;\n      v_make_id      := NULLIF(v_item->>'receiving_make_id', '')::UUID;\n      v_batch_number := NULLIF(TRIM(v_item->>'receiving_batch_number'), '');\n      v_container_id := NULLIF(v_item->>'receiving_import_container_id', '')::UUID;\n      v_expiry_date  := NULLIF(v_item->>'receiving_expiry_date', '')::DATE;\n      v_quantity     := COALESCE((v_item->>'quantity')::NUMERIC, 1);\n      v_unit_price   := COALESCE((v_item->>'unit_price')::NUMERIC, 0);\n      v_unit         := v_item->>'unit';\n      v_batch_id     := NULLIF(v_item->>'batch_id', '')::UUID;\n      v_resolved_batch_id := NULL;\n\n      -- ── Resolve or create batch if item has a Batch Number ────────────────\n      IF v_item_type = 'inventory' AND v_product_id IS NOT NULL AND v_batch_number IS NOT NULL THEN\n        -- 1. Check if provided batch_id matches the product and batch_number\n        IF v_batch_id IS NOT NULL THEN\n          SELECT id INTO v_resolved_batch_id\n            FROM public.batches\n           WHERE id = v_batch_id\n             AND product_id = v_product_id\n             AND (v_batch_number IS NULL OR batch_number = v_batch_number)\n             AND coalesce(is_active, true);\n        END IF;\n\n        -- 2. Resolve existing batch by product_id and batch_number (preferring matching make_id)\n        IF v_resolved_batch_id IS NULL THEN\n          SELECT id INTO v_resolved_batch_id\n            FROM public.batches\n           WHERE product_id = v_product_id\n             AND batch_number = v_batch_number\n             AND (make_id = v_make_id OR v_make_id IS NULL OR make_id IS NULL)\n             AND coalesce(is_active, true)\n           ORDER BY (make_id = v_make_id) DESC, created_at DESC\n           LIMIT 1;\n        END IF;\n\n        IF v_resolved_batch_id IS NULL THEN\n          SELECT id INTO v_resolved_batch_id\n            FROM public.batches\n           WHERE product_id = v_product_id\n             AND batch_number = v_batch_number\n             AND coalesce(is_active, true)\n           ORDER BY created_at DESC\n           LIMIT 1;\n        END IF;\n\n        -- 3. If batch does not exist, create it using the existing batch model\n        IF v_resolved_batch_id IS NULL THEN\n          PERFORM set_config('app.canonical_stock_engine', 'on', true);\n          INSERT INTO public.batches (\n            batch_number, product_id, make_id, import_container_id,\n            import_date, import_quantity, current_stock,\n            import_price, import_price_usd, exchange_rate_usd_to_idr,\n            cost_per_unit, landed_cost_per_unit, final_landed_cost, import_price_per_unit,\n            is_active, created_by, purchase_invoice_id, supplier_id, packaging_details, expiry_date\n          ) VALUES (\n            v_batch_number, v_product_id, v_make_id, v_container_id,\n            v_invoice_date, v_quantity, 0,\n            v_unit_price, CASE WHEN v_currency = 'USD' THEN v_unit_price ELSE NULL END,\n            CASE WHEN v_currency = 'USD' THEN v_rate ELSE NULL END,\n            v_unit_price * v_rate,\n            CASE WHEN v_container_id IS NULL THEN v_unit_price * v_rate ELSE 0 END,\n            CASE WHEN v_container_id IS NULL THEN v_unit_price * v_rate * v_quantity ELSE 0 END,\n            v_unit_price * v_rate,\n            true, v_created_by, v_invoice_id, v_supplier_id, v_unit, v_expiry_date\n          ) RETURNING id INTO v_resolved_batch_id;\n        END IF;\n      END IF;\n\n      IF v_item_id IS NOT NULL AND EXISTS (SELECT 1 FROM purchase_invoice_items WHERE id = v_item_id AND purchase_invoice_id = v_invoice_id) THEN\n        UPDATE purchase_invoice_items SET \n          item_type                     = v_item_type, \n          product_id                    = v_product_id, \n          batch_id                      = v_resolved_batch_id,\n          description                   = v_item->>'description', \n          quantity                      = v_quantity, \n          unit                          = v_unit, \n          unit_price                    = v_unit_price, \n          discount_percent              = (v_item->>'discount_percent')::NUMERIC, \n          line_total                    = v_line_total, \n          tax_amount                    = (v_item->>'tax_amount')::NUMERIC, \n          expense_account_id            = NULLIF(v_item->>'expense_account_id','')::UUID, \n          asset_account_id              = NULLIF(v_item->>'asset_account_id','')::UUID, \n          purchase_order_item_id        = NULLIF(v_item->>'purchase_order_item_id','')::UUID, \n          receiving_make_id             = v_make_id, \n          receiving_batch_number        = v_batch_number, \n          receiving_expiry_date         = v_expiry_date, \n          receiving_import_container_id = v_container_id, \n          receiving_notes               = NULLIF(v_item->>'receiving_notes','') \n        WHERE id = v_item_id;\n      ELSE\n        INSERT INTO purchase_invoice_items (\n          purchase_invoice_id, item_type, product_id, batch_id, description,\n          quantity, unit, unit_price, discount_percent, line_total,\n          tax_amount, expense_account_id, asset_account_id,\n          purchase_order_item_id, receiving_make_id, receiving_batch_number,\n          receiving_expiry_date, receiving_import_container_id, receiving_notes\n        ) VALUES (\n          v_invoice_id,\n          v_item_type,\n          v_product_id,\n          v_resolved_batch_id,\n          v_item->>'description',\n          v_quantity,\n          v_unit,\n          v_unit_price,\n          (v_item->>'discount_percent')::NUMERIC,\n          v_line_total,\n          (v_item->>'tax_amount')::NUMERIC,\n          NULLIF(v_item->>'expense_account_id', '')::UUID,\n          NULLIF(v_item->>'asset_account_id',   '')::UUID,\n          NULLIF(v_item->>'purchase_order_item_id', '')::UUID,\n          v_make_id,\n          v_batch_number,\n          v_expiry_date,\n          v_container_id,\n          NULLIF(v_item->>'receiving_notes', '')\n        );\n      END IF;\n\n      IF v_item_type = 'inventory' THEN\n        SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;\n      ELSIF v_item_type = 'fixed_asset' THEN\n        v_account_id := NULLIF(v_item->>'asset_account_id', '')::UUID;\n        IF v_account_id IS NULL THEN\n          SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '1200' LIMIT 1;\n        END IF;\n      ELSE\n        v_account_id := NULLIF(v_item->>'expense_account_id', '')::UUID;\n        IF v_account_id IS NULL THEN\n          SELECT id INTO v_account_id FROM chart_of_accounts WHERE code = '5100' LIMIT 1;\n        END IF;\n      END IF;\n\n      IF v_account_id IS NOT NULL AND v_line_total <> 0 THEN\n        INSERT INTO journal_entry_lines (\n          journal_entry_id, line_number, account_id, description,\n          debit, credit, supplier_id\n        ) VALUES (\n          v_je_id, v_line_number, v_account_id,\n          COALESCE(LEFT(v_item->>'description', 100), 'Purchase Item'),\n          v_line_total * v_rate, 0, v_supplier_id\n        );\n        v_line_number := v_line_number + 1;\n      END IF;\n    END LOOP;\n\n    -- PPN Input debit line (DR 1150)\n    IF v_tax_amount > 0 AND v_ppn_account_id IS NOT NULL THEN\n      INSERT INTO journal_entry_lines (\n        journal_entry_id, line_number, account_id, description,\n        debit, credit, supplier_id\n      ) VALUES (\n        v_je_id, v_line_number, v_ppn_account_id,\n        'PPN Masukan - ' || v_invoice_number,\n        v_tax_amount * v_rate, 0, v_supplier_id\n      );\n      v_line_number := v_line_number + 1;\n    END IF;\n\n    -- Stamp duty debit line (DR 6950)\n    IF v_stamp_duty_amount > 0 AND v_bm_account_id IS NOT NULL THEN\n      INSERT INTO journal_entry_lines (\n        journal_entry_id, line_number, account_id, description,\n        debit, credit, supplier_id\n      ) VALUES (\n        v_je_id, v_line_number, v_bm_account_id,\n        'Bea Meterai - ' || v_invoice_number,\n        v_stamp_duty_amount, 0, v_supplier_id\n      );\n      v_line_number := v_line_number + 1;\n    END IF;\n\n    -- A/P credit line (CR 2110)\n    INSERT INTO journal_entry_lines (\n      journal_entry_id, line_number, account_id, description,\n      debit, credit, supplier_id\n    ) VALUES (\n      v_je_id, v_line_number, v_ap_account_id,\n      'A/P - ' || v_invoice_number,\n      0, v_total_amount * v_rate, v_supplier_id\n    );\n\n    UPDATE journal_entries\n    SET total_debit = (SELECT COALESCE(SUM(debit), 0) FROM journal_entry_lines WHERE journal_entry_id = v_je_id)\n    WHERE id = v_je_id;\n\n    RETURN jsonb_build_object(\n      'success',        TRUE,\n      'invoice_id',     v_invoice_id,\n      'invoice_number', v_invoice_number,\n      'total_amount',   v_total_amount\n    );\n  END;\n$function$","-- 1b. Fix post_batch_purchase_journal to use MAX + 1 (preventing duplicate key collisions) and skip if batch is created from a purchase invoice (preventing duplicate A/P journals)\nCREATE OR REPLACE FUNCTION public.post_batch_purchase_journal()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$\nDECLARE\nv_je_id UUID;\nv_je_number TEXT;\nv_inventory_account_id UUID;\nv_ap_account_id UUID;\nv_ppn_account_id UUID;\nv_purchase_value DECIMAL(18,2);\nv_ppn_amount DECIMAL(18,2);\nv_total_amount DECIMAL(18,2);\nv_cost_per_unit DECIMAL(18,2);\nBEGIN\n-- Only post on insert for standalone batches with supplier and NOT created from a purchase invoice\nIF TG_OP = 'INSERT' AND NEW.supplier_id IS NOT NULL AND NEW.purchase_invoice_id IS NULL THEN\n\nv_cost_per_unit := COALESCE(NEW.cost_per_unit, \nCASE WHEN NEW.import_quantity > 0 \nTHEN NEW.import_price / NEW.import_quantity \nELSE 0 \nEND);\n\nv_purchase_value := NEW.import_quantity * v_cost_per_unit;\nv_ppn_amount := v_purchase_value * 0.11;\nv_total_amount := v_purchase_value + v_ppn_amount;\n\nIF v_total_amount <= 0 THEN\nRETURN NEW;\nEND IF;\n\nSELECT id INTO v_inventory_account_id FROM chart_of_accounts WHERE code = '1130' LIMIT 1;\nSELECT id INTO v_ap_account_id FROM chart_of_accounts WHERE code = '2110' LIMIT 1;\nSELECT id INTO v_ppn_account_id FROM chart_of_accounts WHERE code = '1150' LIMIT 1;\n\nIF v_inventory_account_id IS NULL OR v_ap_account_id IS NULL THEN\nRETURN NEW;\nEND IF;\n\nv_je_number := 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '-' || LPAD((\nSELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM '(\\\\d+)$') AS INTEGER)), 0) + 1 \nFROM journal_entries \nWHERE entry_number LIKE 'JE' || TO_CHAR(CURRENT_DATE, 'YYMM') || '-%'\n)::TEXT, 4, '0');\n\nINSERT INTO journal_entries (\nentry_number, \nentry_date, \nsource_module, \nreference_id, \nreference_number,\ndescription, \ntotal_debit, \ntotal_credit, \nis_posted, \nposted_by\n) VALUES (\nv_je_number, \nNEW.import_date, \n'batch_purchase', \nNEW.id, \nNEW.batch_number,\n'Goods Received - Batch: ' || NEW.batch_number,\nv_total_amount, \nv_total_amount, \ntrue, \nNEW.created_by\n) RETURNING id INTO v_je_id;\n\nINSERT INTO journal_entry_lines (\njournal_entry_id, \nline_number, \naccount_id, \ndescription, \ndebit, \ncredit, \nsupplier_id,\nbatch_id\n) VALUES (\nv_je_id, \n1, \nv_inventory_account_id, \n'Inventory - Batch ' || NEW.batch_number, \nv_purchase_value, \n0, \nNEW.supplier_id,\nNEW.id\n);\n\nIF v_ppn_amount > 0 AND v_ppn_account_id IS NOT NULL THEN\nINSERT INTO journal_entry_lines (\njournal_entry_id, \nline_number, \naccount_id, \ndescription, \ndebit, \ncredit, \nsupplier_id,\nbatch_id\n) VALUES (\nv_je_id, \n2, \nv_ppn_account_id, \n'PPN Input - Batch ' || NEW.batch_number, \nv_ppn_amount, \n0, \nNEW.supplier_id,\nNEW.id\n);\nEND IF;\n\nINSERT INTO journal_entry_lines (\njournal_entry_id, \nline_number, \naccount_id, \ndescription, \ndebit, \ncredit, \nsupplier_id,\nbatch_id\n) VALUES (\nv_je_id, \n3, \nv_ap_account_id, \n'A/P - Batch ' || NEW.batch_number, \n0, \nv_total_amount, \nNEW.supplier_id,\nNEW.id\n);\n\nEND IF;\n\nRETURN NEW;\nEND;\n$function$","-- 2. Update save_purchase_invoice_with_receiving_details to preserve batch_id\nCREATE OR REPLACE FUNCTION public.save_purchase_invoice_with_receiving_details(p_invoice_id uuid, p_purchase_order_id uuid, p_invoice_data jsonb, p_items jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_data jsonb := coalesce(p_invoice_data, '{}'::jsonb);\n  v_items jsonb := '[]'::jsonb;\n  v_item jsonb;\n  v_old public.purchase_invoice_items%rowtype;\n  v_po uuid;\n  v_result jsonb;\n  v_id uuid;\n  v_rate numeric;\n  v_ccy text;\nBEGIN\n  IF auth.role() <> 'service_role' THEN\n    IF auth.uid() IS NULL THEN\n      RAISE EXCEPTION 'Not authenticated';\n    END IF;\n    IF NOT EXISTS (\n      SELECT 1 FROM public.user_profiles\n      WHERE id = auth.uid()\n        AND is_active = true\n        AND role IN ('admin', 'accounts', 'warehouse')\n    ) THEN\n      RAISE EXCEPTION 'Permission denied for purchase invoice receiving';\n    END IF;\n  END IF;\n\n  IF p_invoice_id IS NOT NULL AND nullif(v_data->>'purchase_order_id', '') IS NULL THEN\n    SELECT purchase_order_id INTO v_po FROM purchase_invoices WHERE id = p_invoice_id;\n    IF v_po IS NOT NULL THEN v_data := jsonb_set(v_data, '{purchase_order_id}', to_jsonb(v_po), true); END IF;\n  ELSIF p_invoice_id IS NULL AND p_purchase_order_id IS NOT NULL AND nullif(v_data->>'purchase_order_id', '') IS NULL THEN\n    v_data := jsonb_set(v_data, '{purchase_order_id}', to_jsonb(p_purchase_order_id), true);\n  END IF;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) LOOP\n    IF p_invoice_id IS NOT NULL AND nullif(v_item->>'id', '') IS NOT NULL THEN\n      SELECT * INTO v_old FROM purchase_invoice_items WHERE id = (v_item->>'id')::uuid AND purchase_invoice_id = p_invoice_id;\n      IF FOUND THEN\n        IF nullif(v_item->>'batch_id', '') IS NULL \n           AND v_old.batch_id IS NOT NULL \n           AND (nullif(v_item->>'receiving_batch_number', '') IS NULL \n                OR nullif(v_item->>'receiving_batch_number', '') = v_old.receiving_batch_number) THEN\n          v_item := jsonb_set(v_item, '{batch_id}', to_jsonb(v_old.batch_id), true);\n        END IF;\n        IF nullif(v_item->>'purchase_order_item_id', '') IS NULL AND v_old.purchase_order_item_id IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{purchase_order_item_id}', to_jsonb(v_old.purchase_order_item_id), true);\n        END IF;\n        IF nullif(v_item->>'receiving_make_id', '') IS NULL AND v_old.receiving_make_id IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{receiving_make_id}', to_jsonb(v_old.receiving_make_id), true);\n        END IF;\n        IF nullif(v_item->>'receiving_batch_number', '') IS NULL AND v_old.receiving_batch_number IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{receiving_batch_number}', to_jsonb(v_old.receiving_batch_number), true);\n        END IF;\n        IF nullif(v_item->>'receiving_expiry_date', '') IS NULL AND v_old.receiving_expiry_date IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{receiving_expiry_date}', to_jsonb(v_old.receiving_expiry_date), true);\n        END IF;\n        IF nullif(v_item->>'receiving_import_container_id', '') IS NULL AND v_old.receiving_import_container_id IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{receiving_import_container_id}', to_jsonb(v_old.receiving_import_container_id), true);\n        END IF;\n        IF nullif(v_item->>'receiving_notes', '') IS NULL AND v_old.receiving_notes IS NOT NULL THEN\n          v_item := jsonb_set(v_item, '{receiving_notes}', to_jsonb(v_old.receiving_notes), true);\n        END IF;\n      END IF;\n    END IF;\n    v_items := v_items || jsonb_build_array(v_item);\n  END LOOP;\n\n  v_result := CASE\n    WHEN p_invoice_id IS NOT NULL THEN save_purchase_invoice(p_invoice_id, v_data, v_items)\n    WHEN p_purchase_order_id IS NOT NULL THEN create_purchase_invoice_from_po(p_purchase_order_id, v_data, v_items)\n    ELSE save_purchase_invoice(NULL, v_data, v_items)\n  END;\n\n  v_id := (v_result->>'invoice_id')::uuid;\n  SELECT upper(currency), exchange_rate INTO v_ccy, v_rate FROM purchase_invoices WHERE id = v_id;\n  RETURN v_result;\nEND;\n$function$","-- 3. Update receive_purchase_invoice_item to ensure purchase_invoice_items.batch_id is persisted upon receiving\nCREATE OR REPLACE FUNCTION public.receive_purchase_invoice_item(p_purchase_invoice_item_id uuid, p_payload jsonb, p_received_quantity numeric, p_operation_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_item public.purchase_invoice_items%ROWTYPE;\n  v_invoice public.purchase_invoices%ROWTYPE;\n  v_batch public.batches%ROWTYPE;\n  v_batch_id uuid;\n  v_existing numeric;\n  v_allocation_id uuid;\n  v_make_id uuid;\n  v_container_id uuid;\n  v_currency text;\n  v_rate numeric;\n  v_tx_unit numeric;\n  v_func_unit numeric;\n  v_existing_batch boolean := false;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin','accounts','warehouse']) THEN\n    RAISE EXCEPTION 'Permission denied for inventory receiving';\n  END IF;\n  IF p_operation_id IS NULL OR p_received_quantity IS NULL OR p_received_quantity <= 0 THEN\n    RAISE EXCEPTION 'A positive quantity and operation_id are required';\n  END IF;\n  SELECT * INTO v_item FROM public.purchase_invoice_items WHERE id=p_purchase_invoice_item_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase invoice item not found'; END IF;\n  SELECT * INTO v_invoice FROM public.purchase_invoices WHERE id=v_item.purchase_invoice_id;\n  IF v_item.item_type <> 'inventory' OR v_item.product_id IS NULL\n     OR NULLIF(p_payload->>'product_id','')::uuid IS DISTINCT FROM v_item.product_id THEN\n    RAISE EXCEPTION 'Receiving requires the invoice inventory product';\n  END IF;\n  SELECT batch_id,id INTO v_batch_id,v_allocation_id\n    FROM public.purchase_invoice_receiving_allocations WHERE operation_id=p_operation_id;\n  IF FOUND THEN\n    -- Ensure purchase_invoice_items.batch_id is set\n    UPDATE public.purchase_invoice_items SET batch_id = v_batch_id WHERE id = v_item.id;\n    RETURN jsonb_build_object('success',true,'batch_id',v_batch_id,\n      'allocation_id',v_allocation_id,'idempotent_retry',true);\n  END IF;\n  SELECT COALESCE(sum(received_quantity),0) INTO v_existing\n    FROM public.purchase_invoice_receiving_allocations\n   WHERE purchase_invoice_item_id=v_item.id AND status='received';\n  IF v_existing+p_received_quantity > v_item.quantity THEN\n    RAISE EXCEPTION 'Received quantity exceeds invoice line quantity';\n  END IF;\n  v_make_id := NULLIF(p_payload->>'make_id','')::uuid;\n  v_container_id := NULLIF(p_payload->>'import_container_id','')::uuid;\n  IF v_make_id IS NOT NULL AND NOT EXISTS\n    (SELECT 1 FROM public.product_sources WHERE id=v_make_id AND product_id=v_item.product_id) THEN\n    RAISE EXCEPTION 'Selected Make / Manufacturer does not belong to the invoice product';\n  END IF;\n  IF NULLIF(p_payload->>'batch_id','') IS NOT NULL THEN\n    SELECT * INTO v_batch FROM public.batches WHERE id=(p_payload->>'batch_id')::uuid FOR UPDATE;\n  ELSE\n    SELECT * INTO v_batch FROM public.batches\n     WHERE product_id=v_item.product_id AND batch_number=p_payload->>'batch_number'\n       AND (make_id=v_make_id OR make_id IS NULL) AND coalesce(is_active,true)\n     ORDER BY (make_id IS NULL),created_at LIMIT 1 FOR UPDATE;\n  END IF;\n  IF FOUND THEN\n    v_existing_batch := true;\n    IF v_batch.product_id IS DISTINCT FROM v_item.product_id THEN\n      RAISE EXCEPTION 'Product does not match selected batch';\n    END IF;\n    IF v_batch.make_id IS NOT NULL AND v_batch.make_id IS DISTINCT FROM v_make_id THEN\n      RAISE EXCEPTION 'Make does not match selected batch';\n    END IF;\n    IF NULLIF(p_payload->>'expiry_date','')::date IS NOT NULL\n       AND v_batch.expiry_date IS NOT NULL\n       AND NULLIF(p_payload->>'expiry_date','')::date IS DISTINCT FROM v_batch.expiry_date THEN\n      RAISE EXCEPTION 'Expiry date conflicts with existing physical batch';\n    END IF;\n    PERFORM public.post_inventory_movement(p_operation_id,v_batch.product_id,v_batch.id,\n      'adjustment',p_received_quantity,v_invoice.invoice_date,v_invoice.invoice_number,\n      'purchase_invoice_receiving',v_invoice.id,\n      'Purchase Invoice receiving into existing batch '||v_batch.batch_number,\n      auth.uid(),v_batch.current_stock,v_batch.current_stock+p_received_quantity);\n    UPDATE public.batches SET import_quantity=import_quantity+p_received_quantity,updated_at=now()\n      WHERE id=v_batch.id;\n    v_batch_id := v_batch.id;\n  ELSE\n    p_payload := jsonb_set(p_payload,'{import_quantity}',to_jsonb(p_received_quantity),true);\n    p_payload := jsonb_set(p_payload,'{purchase_invoice_id}',to_jsonb(v_item.purchase_invoice_id),true);\n    p_payload := jsonb_set(p_payload,'{supplier_id}',to_jsonb(v_invoice.supplier_id),true);\n    SELECT (public.save_batch_inventory_v1(NULL,p_payload,p_operation_id)->>'batch_id')::uuid INTO v_batch_id;\n  END IF;\n  v_currency := upper(coalesce(v_invoice.currency,'IDR'));\n  v_rate := CASE WHEN v_currency='IDR' THEN 1 ELSE coalesce(v_invoice.exchange_rate,0) END;\n  IF v_rate<=0 THEN RAISE EXCEPTION 'Purchase invoice exchange rate is required'; END IF;\n  v_tx_unit := coalesce(v_item.unit_price,0);\n  v_func_unit := round(v_tx_unit*v_rate,2);\n  INSERT INTO public.purchase_invoice_receiving_allocations(\n    purchase_invoice_id,purchase_invoice_item_id,batch_id,received_quantity,\n    operation_id,received_by,currency,exchange_rate,functional_unit_cost,\n    functional_total_cost,import_container_id)\n  VALUES(v_item.purchase_invoice_id,v_item.id,v_batch_id,p_received_quantity,\n    p_operation_id,auth.uid(),v_currency,v_rate,v_func_unit,\n    round(v_func_unit*p_received_quantity,2),v_container_id)\n  RETURNING id INTO v_allocation_id;\n  INSERT INTO public.purchase_batch_cost_layers(\n    receiving_allocation_id,purchase_invoice_id,purchase_invoice_item_id,batch_id,\n    import_container_id,quantity,currency,exchange_rate,transaction_unit_cost,\n    functional_unit_cost,functional_total_cost,final_functional_unit_cost)\n  VALUES(v_allocation_id,v_item.purchase_invoice_id,v_item.id,v_batch_id,v_container_id,\n    p_received_quantity,v_currency,v_rate,v_tx_unit,v_func_unit,\n    round(v_func_unit*p_received_quantity,2),v_func_unit);\n  \n  -- Apply weighted average to ensure batches record has correct unit cost\n  PERFORM public.apply_batch_receipt_weighted_average(v_batch_id,p_received_quantity,v_func_unit);\n  \n  -- Persist batch_id and receiving_batch_number back onto purchase_invoice_items\n  UPDATE public.purchase_invoice_items\n     SET batch_id = v_batch_id,\n         receiving_batch_number = COALESCE(receiving_batch_number, (SELECT batch_number FROM public.batches WHERE id = v_batch_id))\n   WHERE id = v_item.id;\n\n  RETURN jsonb_build_object('success',true,'batch_id',v_batch_id,'allocation_id',v_allocation_id);\nEND; $function$","-- 4. Idempotent Backfill: update any inventory purchase_invoice_items where batch_id IS NULL but receiving_batch_number is set\nUPDATE public.purchase_invoice_items pii\n   SET batch_id = b.id\n  FROM public.batches b\n WHERE pii.batch_id IS NULL\n   AND pii.item_type = 'inventory'\n   AND pii.product_id IS NOT NULL\n   AND NULLIF(TRIM(pii.receiving_batch_number), '') IS NOT NULL\n   AND b.product_id = pii.product_id\n   AND b.batch_number = TRIM(pii.receiving_batch_number)",COMMIT}	fix_purchase_invoice_batch_linking	\N	\N	\N
20260921210000	{"-- Migration: 20260921210000_sales_order_commercial_fx_rate_edit.sql\n-- Description: Provide isolated, audited update function for sales_orders.commercial_usd_to_idr_rate\n\nCREATE OR REPLACE FUNCTION public.update_sales_order_commercial_rate(\n  p_so_id uuid,\n  p_new_rate numeric,\n  p_reason text DEFAULT 'Commercial FX rate updated'\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_so public.sales_orders%ROWTYPE;\n  v_old_rate numeric;\n  v_user_id uuid;\n  v_user_email text;\nBEGIN\n  -- 1. Check SO exists\n  SELECT * INTO v_so FROM public.sales_orders WHERE id = p_so_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Sales order not found');\n  END IF;\n\n  v_old_rate := v_so.commercial_usd_to_idr_rate;\n  v_user_id := auth.uid();\n  IF v_user_id IS NOT NULL THEN\n    SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;\n  END IF;\n\n  -- 2. Validate rate: NULL or positive numeric\n  IF p_new_rate IS NOT NULL AND p_new_rate <= 0 THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Commercial exchange rate must be positive or null');\n  END IF;\n\n  -- 3. Update ONLY commercial_usd_to_idr_rate\n  UPDATE public.sales_orders\n     SET commercial_usd_to_idr_rate = p_new_rate,\n         updated_at = now()\n   WHERE id = p_so_id;\n\n  -- 4. Record audit entry in existing audit_logs\n  INSERT INTO public.audit_logs (\n    table_name,\n    record_id,\n    action_type,\n    old_values,\n    new_values,\n    changed_fields,\n    user_id,\n    user_email,\n    created_at\n  ) VALUES (\n    'sales_orders',\n    p_so_id,\n    'update',\n    jsonb_build_object(\n      'so_number', v_so.so_number,\n      'currency', v_so.currency,\n      'total_amount', v_so.total_amount,\n      'commercial_usd_to_idr_rate', v_old_rate\n    ),\n    jsonb_build_object(\n      'so_number', v_so.so_number,\n      'currency', v_so.currency,\n      'total_amount', v_so.total_amount,\n      'commercial_usd_to_idr_rate', p_new_rate,\n      'reason', COALESCE(NULLIF(trim(p_reason), ''), 'Commercial FX rate update')\n    ),\n    ARRAY['commercial_usd_to_idr_rate'],\n    v_user_id,\n    v_user_email,\n    now()\n  );\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'so_id', p_so_id,\n    'so_number', v_so.so_number,\n    'old_rate', v_old_rate,\n    'new_rate', p_new_rate,\n    'reason', p_reason\n  );\nEND;\n$$","GRANT EXECUTE ON FUNCTION public.update_sales_order_commercial_rate(uuid, numeric, text) TO authenticated, service_role"}	sales_order_commercial_fx_rate_edit	\N	\N	\N
