20260922082540	{"\nCREATE OR REPLACE FUNCTION public.inventory_v1_movement_report(\n  p_date_from date,\n  p_date_to date\n)\nRETURNS TABLE(\n  product_id uuid,\n  product_code text,\n  product_name text,\n  unit text,\n  opening numeric,\n  in_qty numeric,\n  out_qty numeric,\n  reserved_qty numeric,\n  closing numeric,\n  current_stock numeric\n)\nLANGUAGE sql\nSTABLE\nSET search_path TO 'public'\nAS $function$\n  WITH cfg AS (\n    SELECT enforcement_started_at\n    FROM public.inventory_engine_certification\n    WHERE singleton\n  ),\n  canonical_movements AS (\n    SELECT\n      it.product_id,\n      it.transaction_date,\n      it.quantity,\n      it.id\n    FROM public.inventory_transactions it\n    CROSS JOIN cfg\n    WHERE (\n      it.metadata->>'canonical_engine_version' = '1.0'\n      OR it.created_at >= cfg.enforcement_started_at\n    )\n      AND COALESCE((it.metadata->>'superseded')::boolean, false) = false\n  ),\n  legacy_base AS (\n    SELECT\n      it.id,\n      it.product_id,\n      it.batch_id,\n      it.transaction_date,\n      it.quantity,\n      it.transaction_type,\n      it.reference_type,\n      it.reference_id,\n      it.reference_number,\n      it.metadata,\n      COALESCE(h.classification, '') AS classification\n    FROM public.inventory_transactions it\n    CROSS JOIN cfg\n    LEFT JOIN public.inventory_historical_movement_classifications h\n      ON h.transaction_id = it.id\n    WHERE it.created_at < cfg.enforcement_started_at\n      AND it.transaction_type IN (\n        'purchase',\n        'sale',\n        'return',\n        'adjustment',\n        'delivery_challan'\n      )\n      AND COALESCE((it.metadata->>'superseded')::boolean, false) = false\n      AND COALESCE(h.classification, '') NOT IN (\n        'deterministic_duplicate_evidence',\n        'legacy_nonphysical_reservation_evidence',\n        'legacy_lifecycle_compensation_evidence'\n      )\n      AND COALESCE(it.reference_type, '') <> 'historical_stock_adjustment'\n  ),\n  legacy_physical_movements AS (\n    SELECT lb.*\n    FROM legacy_base lb\n    WHERE\n      lb.classification <> 'legacy_invoice_movement_evidence'\n      OR NOT EXISTS (\n        SELECT 1\n        FROM public.delivery_challan_items dci\n        JOIN public.delivery_challans dc\n          ON dc.id = dci.challan_id\n        WHERE dci.product_id = lb.product_id\n          AND dci.batch_id = lb.batch_id\n          AND ABS(dci.quantity) = ABS(lb.quantity)\n          AND dc.challan_date BETWEEN lb.transaction_date - 2 AND lb.transaction_date + 2\n          AND COALESCE(dc.approval_status, 'approved') <> 'rejected'\n      )\n  ),\n  derived_missing_receipts AS (\n    SELECT\n      b.product_id,\n      b.import_date AS transaction_date,\n      b.import_quantity AS quantity,\n      b.id AS batch_id\n    FROM public.batches b\n    WHERE COALESCE(b.is_active, true)\n      AND COALESCE(b.import_quantity, 0) > 0\n      AND b.import_date IS NOT NULL\n      AND NOT EXISTS (\n        SELECT 1\n        FROM public.inventory_transactions it\n        WHERE it.batch_id = b.id\n          AND it.transaction_type = 'purchase'\n      )\n  ),\n  physical_movements AS (\n    SELECT product_id, transaction_date, quantity\n    FROM canonical_movements\n\n    UNION ALL\n\n    SELECT product_id, transaction_date, quantity\n    FROM legacy_physical_movements\n\n    UNION ALL\n\n    SELECT product_id, transaction_date, quantity\n    FROM derived_missing_receipts\n  ),\n  movement_totals AS (\n    SELECT\n      pm.product_id,\n      COALESCE(\n        SUM(pm.quantity) FILTER (\n          WHERE pm.transaction_date < p_date_from\n        ),\n        0\n      ) AS opening,\n      COALESCE(\n        SUM(pm.quantity) FILTER (\n          WHERE pm.transaction_date BETWEEN p_date_from AND p_date_to\n            AND pm.quantity > 0\n        ),\n        0\n      ) AS in_qty,\n      COALESCE(\n        ABS(\n          SUM(pm.quantity) FILTER (\n            WHERE pm.transaction_date BETWEEN p_date_from AND p_date_to\n              AND pm.quantity < 0\n          )\n        ),\n        0\n      ) AS out_qty\n    FROM physical_movements pm\n    GROUP BY pm.product_id\n  ),\n  reservations AS (\n    SELECT\n      sr.product_id,\n      COALESCE(SUM(sr.reserved_quantity), 0) AS reserved_qty\n    FROM public.stock_reservations sr\n    WHERE sr.status = 'active'\n    GROUP BY sr.product_id\n  )\n  SELECT\n    p.id AS product_id,\n    p.product_code,\n    p.product_name,\n    COALESCE(p.unit, 'PCS') AS unit,\n    COALESCE(mt.opening, 0) AS opening,\n    COALESCE(mt.in_qty, 0) AS in_qty,\n    COALESCE(mt.out_qty, 0) AS out_qty,\n    COALESCE(r.reserved_qty, 0) AS reserved_qty,\n    COALESCE(mt.opening, 0)\n      + COALESCE(mt.in_qty, 0)\n      - COALESCE(mt.out_qty, 0) AS closing,\n    COALESCE(p.current_stock, 0) AS current_stock\n  FROM public.products p\n  LEFT JOIN movement_totals mt\n    ON mt.product_id = p.id\n  LEFT JOIN reservations r\n    ON r.product_id = p.id\n  WHERE COALESCE(mt.opening, 0) <> 0\n     OR COALESCE(mt.in_qty, 0) <> 0\n     OR COALESCE(mt.out_qty, 0) <> 0\n     OR COALESCE(r.reserved_qty, 0) <> 0\n  ORDER BY p.product_code, p.product_name;\n$function$;\n"}	fix_inventory_movement_report_historical_reconciliation_final	simplykool@gmail.com	\N	\N
