20260922083004	{"\nCREATE OR REPLACE FUNCTION public.inventory_v1_movement_report(\n  p_date_from date,\n  p_date_to date\n)\nRETURNS TABLE(\n  product_id uuid,\n  product_code text,\n  product_name text,\n  unit text,\n  opening numeric,\n  in_qty numeric,\n  out_qty numeric,\n  reserved_qty numeric,\n  closing numeric,\n  current_stock numeric\n)\nLANGUAGE sql\nSTABLE\nSET search_path TO 'public'\nAS $function$\n  WITH cfg AS (\n    SELECT enforcement_started_at\n    FROM public.inventory_engine_certification\n    WHERE singleton\n  ),\n  /*\n   * Historical movement reporting must use the authoritative physical\n   * documents, not the legacy inventory_transactions evidence rows.\n   *\n   * Purchases/receipts:\n   *   batches.import_date + batches.import_quantity\n   *\n   * Physical outbound:\n   *   approved delivery_challan_items + delivery_challans.challan_date\n   *\n   * Post-V1 returns/physical adjustments:\n   *   canonical inventory_transactions only.\n   *\n   * Legacy sale/adjustment/reservation evidence is intentionally not replayed\n   * because the batch-receipt vs approved-DC reconciliation is the authoritative\n   * historical physical position and those legacy rows are preserved evidence.\n   */\n  authoritative_receipts AS (\n    SELECT\n      b.product_id,\n      b.import_date AS transaction_date,\n      b.import_quantity AS quantity\n    FROM public.batches b\n    WHERE COALESCE(b.import_quantity, 0) > 0\n      AND b.import_date IS NOT NULL\n  ),\n  authoritative_deliveries AS (\n    SELECT\n      dci.product_id,\n      dc.challan_date AS transaction_date,\n      -ABS(COALESCE(dci.quantity, 0)) AS quantity\n    FROM public.delivery_challan_items dci\n    JOIN public.delivery_challans dc\n      ON dc.id = dci.challan_id\n    WHERE dc.approval_status = 'approved'\n      AND COALESCE(dci.quantity, 0) > 0\n  ),\n  canonical_non_delivery_adjustments AS (\n    SELECT\n      it.product_id,\n      it.transaction_date,\n      it.quantity\n    FROM public.inventory_transactions it\n    CROSS JOIN cfg\n    WHERE it.created_at >= cfg.enforcement_started_at\n      AND it.transaction_type IN ('return', 'adjustment')\n      AND it.metadata->>'canonical_engine_version' = '1.0'\n      AND COALESCE((it.metadata->>'superseded')::boolean, false) = false\n  ),\n  physical_movements AS (\n    SELECT product_id, transaction_date, quantity\n    FROM authoritative_receipts\n\n    UNION ALL\n\n    SELECT product_id, transaction_date, quantity\n    FROM authoritative_deliveries\n\n    UNION ALL\n\n    SELECT product_id, transaction_date, quantity\n    FROM canonical_non_delivery_adjustments\n  ),\n  movement_totals AS (\n    SELECT\n      pm.product_id,\n      COALESCE(\n        SUM(pm.quantity) FILTER (WHERE pm.transaction_date < p_date_from),\n        0\n      ) AS opening,\n      COALESCE(\n        SUM(pm.quantity) FILTER (\n          WHERE pm.transaction_date BETWEEN p_date_from AND p_date_to\n            AND pm.quantity > 0\n        ),\n        0\n      ) AS in_qty,\n      COALESCE(\n        ABS(\n          SUM(pm.quantity) FILTER (\n            WHERE pm.transaction_date BETWEEN p_date_from AND p_date_to\n              AND pm.quantity < 0\n          )\n        ),\n        0\n      ) AS out_qty\n    FROM physical_movements pm\n    GROUP BY pm.product_id\n  ),\n  reservations AS (\n    SELECT\n      sr.product_id,\n      COALESCE(SUM(sr.reserved_quantity), 0) AS reserved_qty\n    FROM public.stock_reservations sr\n    WHERE sr.status = 'active'\n    GROUP BY sr.product_id\n  )\n  SELECT\n    p.id AS product_id,\n    p.product_code,\n    p.product_name,\n    COALESCE(p.unit, 'PCS') AS unit,\n    COALESCE(mt.opening, 0) AS opening,\n    COALESCE(mt.in_qty, 0) AS in_qty,\n    COALESCE(mt.out_qty, 0) AS out_qty,\n    COALESCE(r.reserved_qty, 0) AS reserved_qty,\n    COALESCE(mt.opening, 0)\n      + COALESCE(mt.in_qty, 0)\n      - COALESCE(mt.out_qty, 0) AS closing,\n    COALESCE(p.current_stock, 0) AS current_stock\n  FROM public.products p\n  LEFT JOIN movement_totals mt\n    ON mt.product_id = p.id\n  LEFT JOIN reservations r\n    ON r.product_id = p.id\n  WHERE COALESCE(mt.opening, 0) <> 0\n     OR COALESCE(mt.in_qty, 0) <> 0\n     OR COALESCE(mt.out_qty, 0) <> 0\n     OR COALESCE(r.reserved_qty, 0) <> 0\n  ORDER BY p.product_code, p.product_name;\n$function$;\n"}	make_inventory_movement_report_authoritative_physical_ledger	simplykool@gmail.com	\N	\N
20261019151827	{"-- Migration: 20261019140000_invoice_rounding_and_discount_settlement.sql\n-- Description: End-to-end settlement round-off and commercial discount handling for AP and AR\n-- Reuses existing invoice_rounding_adjustments table with minimal schema additions\n\n-- 1. Minimal schema update on invoice_rounding_adjustments\nALTER TABLE public.invoice_rounding_adjustments\n  ALTER COLUMN sales_invoice_id DROP NOT NULL;\n\nALTER TABLE public.invoice_rounding_adjustments\n  ADD COLUMN IF NOT EXISTS purchase_invoice_id uuid REFERENCES public.purchase_invoices(id) ON DELETE CASCADE,\n  ADD COLUMN IF NOT EXISTS payment_voucher_id uuid REFERENCES public.payment_vouchers(id) ON DELETE CASCADE,\n  ADD COLUMN IF NOT EXISTS adjustment_type text NOT NULL DEFAULT 'rounding';\n\n-- Add check constraint for valid adjustment types if not present\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_constraint WHERE conname = 'chk_invoice_rounding_adjustment_type'\n  ) THEN\n    ALTER TABLE public.invoice_rounding_adjustments\n      ADD CONSTRAINT chk_invoice_rounding_adjustment_type\n      CHECK (adjustment_type IN ('rounding', 'discount', 'write_off'));\n  END IF;\nEND $$;\n\n-- Ensure an adjustment row targets either sales invoice OR purchase invoice, never both\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_constraint WHERE conname = 'chk_invoice_rounding_adjustments_target'\n  ) THEN\n    ALTER TABLE public.invoice_rounding_adjustments\n      ADD CONSTRAINT chk_invoice_rounding_adjustments_target\n      CHECK (\n        (sales_invoice_id IS NOT NULL AND purchase_invoice_id IS NULL) OR\n        (purchase_invoice_id IS NOT NULL AND sales_invoice_id IS NULL)\n      );\n  END IF;\nEND $$;\n\n-- Indexes for performance and one adjustment per purchase invoice\nCREATE UNIQUE INDEX IF NOT EXISTS invoice_rounding_adjustments_one_per_pi\n  ON public.invoice_rounding_adjustments (purchase_invoice_id)\n  WHERE purchase_invoice_id IS NOT NULL;\n\nCREATE INDEX IF NOT EXISTS idx_invoice_rounding_adjustments_pv\n  ON public.invoice_rounding_adjustments (payment_voucher_id)\n  WHERE payment_voucher_id IS NOT NULL;\n\n-- 2. Helper function to get purchase invoice adjustment amount\nCREATE OR REPLACE FUNCTION public.get_purchase_invoice_rounding_adjustment_amount(p_purchase_invoice_id uuid)\nRETURNS numeric\nLANGUAGE sql SECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\n  SELECT COALESCE(SUM(ira.adjustment_amount), 0)\n  FROM public.invoice_rounding_adjustments ira\n  WHERE ira.purchase_invoice_id = p_purchase_invoice_id;\n$$;\n\n-- 3. Update recalculate_purchase_invoice_payment_state to include rounding adjustments\nCREATE OR REPLACE FUNCTION public.recalculate_purchase_invoice_payment_state(p_purchase_invoice_id uuid)\nRETURNS void\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_invoice record;\n  v_allocated numeric(18,2);\n  v_adjustment numeric(18,2);\n  v_paid numeric(18,2);\nBEGIN\n  IF p_purchase_invoice_id IS NULL THEN\n    RETURN;\n  END IF;\n\n  SELECT id, total_amount\n  INTO v_invoice\n  FROM public.purchase_invoices\n  WHERE id = p_purchase_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  -- Only count allocations whose parent payment voucher is POSTED to GL\n  SELECT COALESCE(SUM(va.allocated_amount), 0)\n  INTO v_allocated\n  FROM public.voucher_allocations va\n  JOIN public.payment_vouchers pv\n    ON pv.id = va.payment_voucher_id\n  WHERE va.purchase_invoice_id = p_purchase_invoice_id\n    AND va.voucher_type = 'payment'\n    AND pv.is_posted = TRUE;\n\n  -- Include settlement rounding/discount adjustments\n  v_adjustment := public.get_purchase_invoice_rounding_adjustment_amount(p_purchase_invoice_id);\n  v_paid := v_allocated + v_adjustment;\n\n  UPDATE public.purchase_invoices\n  SET\n    paid_amount = v_paid,\n    status = CASE\n      WHEN v_paid <= 0 THEN 'unpaid'\n      WHEN v_paid >= COALESCE(v_invoice.total_amount, 0) THEN 'paid'\n      ELSE 'partial'\n    END\n  WHERE id = p_purchase_invoice_id;\nEND;\n$$;\n\n-- 4. Create apply_payment_allocation_rounding_adjustment\nCREATE OR REPLACE FUNCTION public.apply_payment_allocation_rounding_adjustment(\n  p_invoice_id uuid,\n  p_payment_voucher_id uuid DEFAULT NULL::uuid,\n  p_adjustment_type text DEFAULT 'rounding',\n  p_reason text DEFAULT 'invoice_rounding_tolerance',\n  p_amount numeric DEFAULT NULL::numeric\n)\nRETURNS void\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_invoice record;\n  v_allocated numeric(18,2);\n  v_residual numeric(18,2);\n  v_tolerance numeric(18,2);\n  v_existing record;\n  v_entry_id uuid;\n  v_entry_number text;\n  v_ap_account_id uuid;\n  v_adjustment_account_id uuid;\n  v_user_id uuid;\n  v_target_pv_id uuid;\n  v_has_posted_allocations boolean := false;\n  v_adj_amount numeric(18,2);\n  v_adj_type text;\n  v_adj_reason text;\nBEGIN\n  SELECT *\n  INTO v_invoice\n  FROM public.purchase_invoices\n  WHERE id = p_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  -- Verify tolerance from settings\n  SELECT COALESCE(rounding_tolerance_amount, 100)\n  INTO v_tolerance\n  FROM public.app_settings\n  LIMIT 1;\n  v_tolerance := COALESCE(v_tolerance, 100);\n\n  -- Fetch existing adjustment for this purchase invoice\n  SELECT *\n  INTO v_existing\n  FROM public.invoice_rounding_adjustments\n  WHERE purchase_invoice_id = p_invoice_id\n  LIMIT 1;\n\n  -- Only POSTED payment voucher allocations count\n  SELECT COALESCE(SUM(va.allocated_amount), 0)\n  INTO v_allocated\n  FROM public.voucher_allocations va\n  JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n  WHERE va.purchase_invoice_id = p_invoice_id\n    AND va.voucher_type = 'payment'\n    AND pv.is_posted = true;\n\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.voucher_allocations va\n    JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n    WHERE va.purchase_invoice_id = p_invoice_id\n      AND va.voucher_type = 'payment'\n      AND pv.is_posted = true\n  ) INTO v_has_posted_allocations;\n\n  -- Target PV selection\n  IF p_payment_voucher_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.payment_vouchers WHERE id = p_payment_voucher_id AND is_posted = true\n  ) THEN\n    v_target_pv_id := p_payment_voucher_id;\n  ELSIF v_has_posted_allocations THEN\n    SELECT pv.id INTO v_target_pv_id\n    FROM public.voucher_allocations va\n    JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n    WHERE va.purchase_invoice_id = p_invoice_id\n      AND va.voucher_type = 'payment'\n      AND pv.is_posted = true\n    ORDER BY pv.created_at DESC\n    LIMIT 1;\n  ELSE\n    v_target_pv_id := NULL;\n  END IF;\n\n  v_residual := ROUND(COALESCE(v_invoice.total_amount, 0) - COALESCE(v_allocated, 0), 2);\n\n  -- Determine adjustment amount and type\n  IF p_amount IS NOT NULL AND p_amount <> 0 THEN\n    v_adj_amount := ROUND(p_amount, 2);\n    v_adj_type := COALESCE(p_adjustment_type, 'rounding');\n    v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'settlement_adjustment');\n  ELSE\n    IF ABS(v_residual) > 0 AND ABS(v_residual) <= v_tolerance THEN\n      v_adj_amount := v_residual;\n      v_adj_type := COALESCE(p_adjustment_type, 'rounding');\n      v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'invoice_rounding_tolerance');\n    ELSE\n      v_adj_amount := 0;\n      v_adj_type := 'rounding';\n      v_adj_reason := 'none';\n    END IF;\n  END IF;\n\n  -- Tolerance validation for rounding\n  IF v_adj_type = 'rounding' AND ABS(v_adj_amount) > v_tolerance THEN\n    RAISE EXCEPTION 'Rounding adjustment % exceeds configured tolerance %', v_adj_amount, v_tolerance;\n  END IF;\n\n  -- Reason validation for discount or write-off\n  IF v_adj_type IN ('discount', 'write_off') AND (v_adj_reason IS NULL OR TRIM(v_adj_reason) = '' OR v_adj_reason = 'invoice_rounding_tolerance') THEN\n    RAISE EXCEPTION 'A valid reason is required for discount or write-off settlement adjustments';\n  END IF;\n\n  -- Settle with posted payment activity\n  IF ABS(v_adj_amount) > 0 AND v_has_posted_allocations THEN\n    -- If already correctly adjusted with identical amount and type, just ensure state sync and return\n    IF v_existing.id IS NOT NULL\n       AND v_existing.adjustment_amount = v_adj_amount\n       AND v_existing.adjustment_type = v_adj_type THEN\n      PERFORM public.recalculate_purchase_invoice_payment_state(p_invoice_id);\n      RETURN;\n    END IF;\n\n    -- Clean up previous adjustment journal and record before replacing\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n\n    -- AP Account 2110\n    SELECT id INTO v_ap_account_id\n    FROM public.chart_of_accounts\n    WHERE code = '2110'\n    LIMIT 1;\n\n    -- Adjustment account selection\n    IF v_adj_type = 'rounding' THEN\n      IF v_adj_amount > 0 THEN\n        SELECT COALESCE(\n          (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      ELSE\n        SELECT COALESCE(\n          (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      END IF;\n    ELSIF v_adj_type IN ('discount', 'write_off') THEN\n      IF v_adj_amount > 0 THEN\n        -- Supplier discount reduces AP, credited to Other Income / Purchase Discount (4900 / 4910)\n        SELECT COALESCE(\n          (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '4910' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      ELSE\n        SELECT id INTO v_adjustment_account_id\n        FROM public.chart_of_accounts\n        WHERE code = '6900'\n        LIMIT 1;\n      END IF;\n    END IF;\n\n    IF v_ap_account_id IS NULL OR v_adjustment_account_id IS NULL THEN\n      RAISE EXCEPTION 'Missing COA setup for purchase invoice settlement adjustment';\n    END IF;\n\n    v_user_id := COALESCE(auth.uid(), v_invoice.created_by);\n    v_entry_number := public.next_journal_entry_number();\n\n    INSERT INTO public.journal_entries (\n      entry_number, entry_date, source_module, reference_id, reference_number,\n      description, total_debit, total_credit, is_posted, posted_by, created_by\n    ) VALUES (\n      v_entry_number,\n      COALESCE(v_invoice.invoice_date, CURRENT_DATE),\n      'purchase_invoice_rounding',\n      v_invoice.id,\n      v_invoice.invoice_number,\n      'Payment settlement ' || v_adj_type || ' adjustment: ' || v_invoice.invoice_number,\n      ABS(v_adj_amount),\n      ABS(v_adj_amount),\n      true,\n      v_user_id,\n      v_user_id\n    )\n    RETURNING id INTO v_entry_id;\n\n    IF v_adj_amount > 0 THEN\n      -- Debit AP (clearing payable), Credit Rounding Gain / Purchase Discount (4900)\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)\n      VALUES\n        (v_entry_id, 1, v_ap_account_id, 'A/P settlement clearance - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.supplier_id),\n        (v_entry_id, 2, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.supplier_id);\n    ELSE\n      -- Debit Expense / Write-off (6900), Credit AP\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)\n      VALUES\n        (v_entry_id, 1, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.supplier_id),\n        (v_entry_id, 2, v_ap_account_id, 'A/P settlement clearance - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.supplier_id);\n    END IF;\n\n    INSERT INTO public.invoice_rounding_adjustments (\n      payment_voucher_id, purchase_invoice_id, adjustment_amount, adjustment_type, reason, journal_entry_id, created_by\n    ) VALUES (\n      v_target_pv_id, p_invoice_id, v_adj_amount, v_adj_type, v_adj_reason, v_entry_id, v_user_id\n    );\n  ELSE\n    -- Residual is zero or exceeds tolerance or unposted: clear existing\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n  END IF;\n\n  PERFORM public.recalculate_purchase_invoice_payment_state(p_invoice_id);\nEND;\n$$;\n\n-- 5. Create clear_payment_allocation_rounding_adjustment\nCREATE OR REPLACE FUNCTION public.clear_payment_allocation_rounding_adjustment(\n  p_invoice_id uuid DEFAULT NULL::uuid,\n  p_payment_voucher_id uuid DEFAULT NULL::uuid\n)\nRETURNS void\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_existing record;\nBEGIN\n  FOR v_existing IN\n    SELECT *\n    FROM public.invoice_rounding_adjustments\n    WHERE (p_invoice_id IS NOT NULL AND purchase_invoice_id = p_invoice_id)\n       OR (p_payment_voucher_id IS NOT NULL AND payment_voucher_id = p_payment_voucher_id)\n  LOOP\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n\n    DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    IF v_existing.purchase_invoice_id IS NOT NULL THEN\n      PERFORM public.recalculate_purchase_invoice_payment_state(v_existing.purchase_invoice_id);\n    END IF;\n  END LOOP;\n\n  IF p_invoice_id IS NOT NULL THEN\n    PERFORM public.recalculate_purchase_invoice_payment_state(p_invoice_id);\n  END IF;\nEND;\n$$;\n\n-- 6. Update sync_purchase_invoice_payment_state_from_pv_posting trigger function\nCREATE OR REPLACE FUNCTION public.sync_purchase_invoice_payment_state_from_pv_posting()\nRETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_invoice_id uuid;\nBEGIN\n  IF COALESCE(OLD.is_posted, FALSE) IS DISTINCT FROM COALESCE(NEW.is_posted, FALSE) THEN\n    FOR v_invoice_id IN\n      SELECT DISTINCT purchase_invoice_id\n      FROM public.voucher_allocations\n      WHERE payment_voucher_id = NEW.id\n        AND voucher_type = 'payment'\n        AND purchase_invoice_id IS NOT NULL\n    LOOP\n      IF NEW.is_posted = true THEN\n        PERFORM public.apply_payment_allocation_rounding_adjustment(v_invoice_id, NEW.id);\n      ELSE\n        PERFORM public.clear_payment_allocation_rounding_adjustment(v_invoice_id, NEW.id);\n      END IF;\n    END LOOP;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 7. Update cancel_payment_voucher_posting to cleanly clear adjustments\nCREATE OR REPLACE FUNCTION public.cancel_payment_voucher_posting(\n  p_pv_id uuid,\n  p_cancelled_by uuid,\n  p_reason text DEFAULT 'Posting cancelled by administrator'::text\n)\nRETURNS void\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_pv RECORD;\n  v_je RECORD;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'Not authenticated';\n  END IF;\n\n  SELECT * INTO v_pv FROM payment_vouchers WHERE id = p_pv_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Payment voucher % not found', p_pv_id; END IF;\n  IF NOT v_pv.is_posted THEN\n    RAISE EXCEPTION 'Payment voucher % is not posted', COALESCE(v_pv.voucher_number, p_pv_id::TEXT);\n  END IF;\n\n  SELECT * INTO v_je FROM journal_entries WHERE id = v_pv.journal_entry_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'No journal entry found for payment voucher %', v_pv.voucher_number;\n  END IF;\n\n  -- Clear any settlement adjustments linked to this payment voucher\n  PERFORM public.clear_payment_allocation_rounding_adjustment(NULL, p_pv_id);\n\n  -- Clear the FK reference FIRST so cancel_gl_posting can delete the JE row\n  UPDATE payment_vouchers\n  SET is_posted = FALSE, journal_entry_id = NULL\n  WHERE id = p_pv_id;\n\n  PERFORM cancel_gl_posting(\n    v_je.id, p_pv_id, 'payment_vouchers', p_cancelled_by, p_reason,\n    jsonb_build_object(\n      'voucher_number', v_pv.voucher_number,\n      'amount',         v_pv.amount,\n      'is_posted',      TRUE\n    )\n  );\nEND;\n$$;\n\n-- 8. Enhance customer receipt rounding function to support discount/write_off distinction\nCREATE OR REPLACE FUNCTION public.apply_receipt_allocation_rounding_adjustment(\n  p_invoice_id uuid,\n  p_receipt_voucher_id uuid DEFAULT NULL::uuid,\n  p_adjustment_type text DEFAULT 'rounding',\n  p_reason text DEFAULT 'invoice_rounding_tolerance',\n  p_amount numeric DEFAULT NULL::numeric\n)\nRETURNS void\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_invoice record;\n  v_allocated numeric(18,2);\n  v_residual numeric(18,2);\n  v_tolerance numeric(18,2);\n  v_existing record;\n  v_entry_id uuid;\n  v_entry_number text;\n  v_ar_account_id uuid;\n  v_adjustment_account_id uuid;\n  v_user_id uuid;\n  v_target_rv_id uuid;\n  v_has_posted_allocations boolean := false;\n  v_adj_amount numeric(18,2);\n  v_adj_type text;\n  v_adj_reason text;\nBEGIN\n  SELECT *\n  INTO v_invoice\n  FROM public.sales_invoices\n  WHERE id = p_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  SELECT COALESCE(rounding_tolerance_amount, 100)\n  INTO v_tolerance\n  FROM public.app_settings\n  LIMIT 1;\n  v_tolerance := COALESCE(v_tolerance, 100);\n\n  SELECT *\n  INTO v_existing\n  FROM public.invoice_rounding_adjustments\n  WHERE sales_invoice_id = p_invoice_id\n  LIMIT 1;\n\n  v_allocated := public.get_invoice_allocation_amount(p_invoice_id, NULL);\n\n  SELECT EXISTS (\n    SELECT 1 \n    FROM public.voucher_allocations va\n    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id\n    WHERE va.sales_invoice_id = p_invoice_id\n      AND va.voucher_type = 'receipt'\n      AND rv.is_posted = true\n  ) INTO v_has_posted_allocations;\n\n  IF p_receipt_voucher_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.receipt_vouchers WHERE id = p_receipt_voucher_id AND is_posted = true\n  ) THEN\n    v_target_rv_id := p_receipt_voucher_id;\n  ELSIF v_has_posted_allocations THEN\n    SELECT rv.id INTO v_target_rv_id\n    FROM public.voucher_allocations va\n    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id\n    WHERE va.sales_invoice_id = p_invoice_id\n      AND va.voucher_type = 'receipt'\n      AND rv.is_posted = true\n    ORDER BY rv.created_at DESC\n    LIMIT 1;\n  ELSE\n    v_target_rv_id := NULL;\n  END IF;\n\n  v_residual := ROUND(COALESCE(v_invoice.total_amount, 0) - COALESCE(v_allocated, 0), 2);\n\n  IF p_amount IS NOT NULL AND p_amount <> 0 THEN\n    v_adj_amount := ROUND(p_amount, 2);\n    v_adj_type := COALESCE(p_adjustment_type, 'rounding');\n    v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'settlement_adjustment');\n  ELSE\n    IF ABS(v_residual) > 0 AND ABS(v_residual) <= v_tolerance THEN\n      v_adj_amount := v_residual;\n      v_adj_type := COALESCE(p_adjustment_type, 'rounding');\n      v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'invoice_rounding_tolerance');\n    ELSE\n      v_adj_amount := 0;\n      v_adj_type := 'rounding';\n      v_adj_reason := 'none';\n    END IF;\n  END IF;\n\n  IF v_adj_type = 'rounding' AND ABS(v_adj_amount) > v_tolerance THEN\n    RAISE EXCEPTION 'Rounding adjustment % exceeds configured tolerance %', v_adj_amount, v_tolerance;\n  END IF;\n\n  IF v_adj_type IN ('discount', 'write_off') AND (v_adj_reason IS NULL OR TRIM(v_adj_reason) = '' OR v_adj_reason = 'invoice_rounding_tolerance') THEN\n    RAISE EXCEPTION 'A valid reason is required for discount or write-off settlement adjustments';\n  END IF;\n\n  IF ABS(v_adj_amount) > 0 AND v_has_posted_allocations THEN\n    IF v_existing.id IS NOT NULL \n       AND v_existing.adjustment_amount = v_adj_amount \n       AND v_existing.adjustment_type = v_adj_type THEN\n      PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);\n      RETURN;\n    END IF;\n\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n\n    -- AR Account 1120\n    SELECT id INTO v_ar_account_id\n    FROM public.chart_of_accounts\n    WHERE code = '1120'\n    LIMIT 1;\n\n    IF v_adj_type = 'rounding' THEN\n      IF v_adj_amount > 0 THEN\n        -- Customer short payment under tolerance: write-off expense\n        SELECT COALESCE(\n          (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      ELSE\n        -- Customer overpayment under tolerance: rounding gain\n        SELECT COALESCE(\n          (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      END IF;\n    ELSIF v_adj_type IN ('discount', 'write_off') THEN\n      IF v_adj_amount > 0 THEN\n        -- Commercial sales discount granted: debit Sales Discounts (4200)\n        SELECT COALESCE(\n          (SELECT id FROM public.chart_of_accounts WHERE code = '4200' LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      ELSE\n        SELECT id INTO v_adjustment_account_id\n        FROM public.chart_of_accounts\n        WHERE code = '4900'\n        LIMIT 1;\n      END IF;\n    END IF;\n\n    IF v_ar_account_id IS NULL OR v_adjustment_account_id IS NULL THEN\n      RAISE EXCEPTION 'Missing COA setup for sales invoice settlement adjustment';\n    END IF;\n\n    v_user_id := COALESCE(auth.uid(), v_invoice.created_by);\n    v_entry_number := public.next_journal_entry_number();\n\n    INSERT INTO public.journal_entries (\n      entry_number, entry_date, source_module, reference_id, reference_number,\n      description, total_debit, total_credit, is_posted, posted_by, created_by\n    ) VALUES (\n      v_entry_number,\n      COALESCE(v_invoice.invoice_date, CURRENT_DATE),\n      'sales_invoice_rounding',\n      v_invoice.id,\n      v_invoice.invoice_number,\n      'Receipt settlement ' || v_adj_type || ' adjustment: ' || v_invoice.invoice_number,\n      ABS(v_adj_amount),\n      ABS(v_adj_amount),\n      true,\n      v_user_id,\n      v_user_id\n    )\n    RETURNING id INTO v_entry_id;\n\n    IF v_adj_amount > 0 THEN\n      -- Customer underpaid: Debit Sales Discount/Expense, Credit AR (1120)\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES\n        (v_entry_id, 1, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.customer_id),\n        (v_entry_id, 2, v_ar_account_id, 'A/R settlement clearance - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.customer_id);\n    ELSE\n      -- Customer overpaid: Debit AR (1120), Credit Gain\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES\n        (v_entry_id, 1, v_ar_account_id, 'A/R settlement clearance - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.customer_id),\n        (v_entry_id, 2, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.customer_id);\n    END IF;\n\n    INSERT INTO public.invoice_rounding_adjustments (\n      receipt_voucher_id, sales_invoice_id, adjustment_amount, adjustment_type, reason, journal_entry_id, created_by\n    ) VALUES (\n      v_target_rv_id, p_invoice_id, v_adj_amount, v_adj_type, v_adj_reason, v_entry_id, v_user_id\n    );\n  ELSE\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n  END IF;\n\n  PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);\nEND;\n$$;\n\n-- 9. Create unified RPC for settlement adjustments\nCREATE OR REPLACE FUNCTION public.save_invoice_settlement_adjustment(\n  p_document_type text,\n  p_invoice_id uuid,\n  p_voucher_id uuid DEFAULT NULL::uuid,\n  p_adjustment_amount numeric DEFAULT NULL::numeric,\n  p_adjustment_type text DEFAULT 'rounding',\n  p_reason text DEFAULT 'invoice_rounding_tolerance'\n)\nRETURNS void\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nBEGIN\n  PERFORM public._sec_check_finance_role();\n\n  IF p_document_type = 'purchase' THEN\n    PERFORM public.apply_payment_allocation_rounding_adjustment(\n      p_invoice_id,\n      p_voucher_id,\n      p_adjustment_type,\n      p_reason,\n      p_adjustment_amount\n    );\n  ELSIF p_document_type = 'sales' THEN\n    PERFORM public.apply_receipt_allocation_rounding_adjustment(\n      p_invoice_id,\n      p_voucher_id,\n      p_adjustment_type,\n      p_reason,\n      p_adjustment_amount\n    );\n  ELSE\n    RAISE EXCEPTION 'Invalid document type % for settlement adjustment', p_document_type;\n  END IF;\nEND;\n$$;\n\n-- 10. Grant permissions to authenticated and service_role\nREVOKE ALL ON FUNCTION public.get_purchase_invoice_rounding_adjustment_amount(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.get_purchase_invoice_rounding_adjustment_amount(uuid) TO authenticated, service_role;\n\nREVOKE ALL ON FUNCTION public.apply_payment_allocation_rounding_adjustment(uuid, uuid, text, text, numeric) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.apply_payment_allocation_rounding_adjustment(uuid, uuid, text, text, numeric) TO authenticated, service_role;\n\nREVOKE ALL ON FUNCTION public.clear_payment_allocation_rounding_adjustment(uuid, uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.clear_payment_allocation_rounding_adjustment(uuid, uuid) TO authenticated, service_role;\n\nREVOKE ALL ON FUNCTION public.sync_purchase_invoice_payment_state_from_pv_posting() FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.sync_purchase_invoice_payment_state_from_pv_posting() TO authenticated, service_role;\n\nREVOKE ALL ON FUNCTION public.save_invoice_settlement_adjustment(text, uuid, uuid, numeric, text, text) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.save_invoice_settlement_adjustment(text, uuid, uuid, numeric, text, text) TO authenticated, service_role;\n"}	invoice_rounding_and_discount_settlement	simplykool@gmail.com	\N	\N
20260922083118	{"\nCREATE OR REPLACE FUNCTION public.inventory_v1_movement_report(\n  p_date_from date,\n  p_date_to date\n)\nRETURNS TABLE(\n  product_id uuid,\n  product_code text,\n  product_name text,\n  unit text,\n  opening numeric,\n  in_qty numeric,\n  out_qty numeric,\n  reserved_qty numeric,\n  closing numeric,\n  current_stock numeric\n)\nLANGUAGE sql\nSTABLE\nSET search_path TO 'public'\nAS $function$\n  WITH cfg AS (\n    SELECT enforcement_started_at\n    FROM public.inventory_engine_certification\n    WHERE singleton\n  ),\n  /*\n   * Inventory Movement is a PHYSICAL movement report.\n   *\n   * Historical / current physical sources:\n   *   1) Batch import/receipt: batches.import_date + import_quantity\n   *   2) Approved delivery: delivery_challans + delivery_challan_items\n   *   3) Post-V1 genuine return/adjustment movements\n   *\n   * Legacy inventory_transactions are preserved evidence and must not be\n   * replayed into this report because they contain duplicate invoice/DC\n   * representations, reservation artifacts, historical repairs, and other\n   * non-physical bookkeeping movements.\n   */\n  authoritative_receipts AS (\n    SELECT\n      b.product_id,\n      b.import_date AS transaction_date,\n      b.import_quantity AS quantity\n    FROM public.batches b\n    WHERE COALESCE(b.import_quantity, 0) > 0\n      AND b.import_date IS NOT NULL\n  ),\n  authoritative_deliveries AS (\n    SELECT\n      dci.product_id,\n      dc.challan_date AS transaction_date,\n      -ABS(COALESCE(dci.quantity, 0)) AS quantity\n    FROM public.delivery_challan_items dci\n    JOIN public.delivery_challans dc\n      ON dc.id = dci.challan_id\n    WHERE dc.approval_status = 'approved'\n      AND COALESCE(dci.quantity, 0) > 0\n  ),\n  canonical_physical_adjustments AS (\n    SELECT\n      it.product_id,\n      it.transaction_date,\n      it.quantity\n    FROM public.inventory_transactions it\n    CROSS JOIN cfg\n    WHERE it.created_at >= cfg.enforcement_started_at\n      AND it.transaction_type IN ('return', 'adjustment')\n      AND it.metadata->>'canonical_engine_version' = '1.0'\n      AND COALESCE((it.metadata->>'superseded')::boolean, false) = false\n      /*\n       * These are accounting/repair artifacts already represented by the\n       * authoritative batch/DC sources and MUST NOT become physical movement\n       * a second time.\n       */\n      AND COALESCE(it.reference_type, '') NOT IN (\n        'purchase_invoice_receiving',\n        'historical_stock_repair'\n      )\n  ),\n  physical_movements AS (\n    SELECT product_id, transaction_date, quantity\n    FROM authoritative_receipts\n\n    UNION ALL\n\n    SELECT product_id, transaction_date, quantity\n    FROM authoritative_deliveries\n\n    UNION ALL\n\n    SELECT product_id, transaction_date, quantity\n    FROM canonical_physical_adjustments\n  ),\n  movement_totals AS (\n    SELECT\n      pm.product_id,\n      COALESCE(\n        SUM(pm.quantity) FILTER (WHERE pm.transaction_date < p_date_from),\n        0\n      ) AS opening,\n      COALESCE(\n        SUM(pm.quantity) FILTER (\n          WHERE pm.transaction_date BETWEEN p_date_from AND p_date_to\n            AND pm.quantity > 0\n        ),\n        0\n      ) AS in_qty,\n      COALESCE(\n        ABS(\n          SUM(pm.quantity) FILTER (\n            WHERE pm.transaction_date BETWEEN p_date_from AND p_date_to\n              AND pm.quantity < 0\n          )\n        ),\n        0\n      ) AS out_qty\n    FROM physical_movements pm\n    GROUP BY pm.product_id\n  ),\n  reservations AS (\n    SELECT\n      sr.product_id,\n      COALESCE(SUM(sr.reserved_quantity), 0) AS reserved_qty\n    FROM public.stock_reservations sr\n    WHERE sr.status = 'active'\n    GROUP BY sr.product_id\n  )\n  SELECT\n    p.id AS product_id,\n    p.product_code,\n    p.product_name,\n    COALESCE(p.unit, 'PCS') AS unit,\n    COALESCE(mt.opening, 0) AS opening,\n    COALESCE(mt.in_qty, 0) AS in_qty,\n    COALESCE(mt.out_qty, 0) AS out_qty,\n    COALESCE(r.reserved_qty, 0) AS reserved_qty,\n    COALESCE(mt.opening, 0)\n      + COALESCE(mt.in_qty, 0)\n      - COALESCE(mt.out_qty, 0) AS closing,\n    COALESCE(p.current_stock, 0) AS current_stock\n  FROM public.products p\n  LEFT JOIN movement_totals mt\n    ON mt.product_id = p.id\n  LEFT JOIN reservations r\n    ON r.product_id = p.id\n  WHERE COALESCE(mt.opening, 0) <> 0\n     OR COALESCE(mt.in_qty, 0) <> 0\n     OR COALESCE(mt.out_qty, 0) <> 0\n     OR COALESCE(r.reserved_qty, 0) <> 0\n  ORDER BY p.product_code, p.product_name;\n$function$;\n"}	finalize_inventory_movement_report_physical_sources	simplykool@gmail.com	\N	\N
20261019152347	{"CREATE OR REPLACE FUNCTION public.apply_payment_allocation_rounding_adjustment(p_invoice_id uuid, p_payment_voucher_id uuid DEFAULT NULL::uuid, p_adjustment_type text DEFAULT 'rounding'::text, p_reason text DEFAULT 'invoice_rounding_tolerance'::text, p_amount numeric DEFAULT NULL::numeric)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_invoice record;\n  v_allocated numeric(18,2);\n  v_residual numeric(18,2);\n  v_tolerance numeric(18,2);\n  v_existing record;\n  v_entry_id uuid;\n  v_entry_number text;\n  v_ap_account_id uuid;\n  v_adjustment_account_id uuid;\n  v_user_id uuid;\n  v_target_pv_id uuid;\n  v_has_posted_allocations boolean := false;\n  v_adj_amount numeric(18,2);\n  v_adj_type text;\n  v_adj_reason text;\n  v_adjustment_date date;\nBEGIN\n  SELECT *\n  INTO v_invoice\n  FROM public.purchase_invoices\n  WHERE id = p_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  -- Verify tolerance from settings\n  SELECT COALESCE(rounding_tolerance_amount, 100)\n  INTO v_tolerance\n  FROM public.app_settings\n  LIMIT 1;\n  v_tolerance := COALESCE(v_tolerance, 100);\n\n  -- Fetch existing adjustment for this purchase invoice\n  SELECT *\n  INTO v_existing\n  FROM public.invoice_rounding_adjustments\n  WHERE purchase_invoice_id = p_invoice_id\n  LIMIT 1;\n\n  -- Only POSTED payment voucher allocations count\n  SELECT COALESCE(SUM(va.allocated_amount), 0)\n  INTO v_allocated\n  FROM public.voucher_allocations va\n  JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n  WHERE va.purchase_invoice_id = p_invoice_id\n    AND va.voucher_type = 'payment'\n    AND pv.is_posted = true;\n\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.voucher_allocations va\n    JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n    WHERE va.purchase_invoice_id = p_invoice_id\n      AND va.voucher_type = 'payment'\n      AND pv.is_posted = true\n  ) INTO v_has_posted_allocations;\n\n  -- Target PV selection\n  IF p_payment_voucher_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.payment_vouchers WHERE id = p_payment_voucher_id AND is_posted = true\n  ) THEN\n    v_target_pv_id := p_payment_voucher_id;\n  ELSIF v_has_posted_allocations THEN\n    SELECT pv.id INTO v_target_pv_id\n    FROM public.voucher_allocations va\n    JOIN public.payment_vouchers pv ON pv.id = va.payment_voucher_id\n    WHERE va.purchase_invoice_id = p_invoice_id\n      AND va.voucher_type = 'payment'\n      AND pv.is_posted = true\n    ORDER BY pv.created_at DESC\n    LIMIT 1;\n  ELSE\n    v_target_pv_id := NULL;\n  END IF;\n\n  -- Settlement adjustments belong to the payment voucher date, not the original invoice date.\n  SELECT pv.voucher_date INTO v_adjustment_date\n  FROM public.payment_vouchers pv\n  WHERE pv.id = v_target_pv_id;\n  v_adjustment_date := COALESCE(v_adjustment_date, CURRENT_DATE);\n\n  v_residual := ROUND(COALESCE(v_invoice.total_amount, 0) - COALESCE(v_allocated, 0), 2);\n\n  -- Determine adjustment amount and type\n  IF p_amount IS NOT NULL AND p_amount <> 0 THEN\n    v_adj_amount := ROUND(p_amount, 2);\n    v_adj_type := COALESCE(p_adjustment_type, 'rounding');\n    v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'settlement_adjustment');\n  ELSE\n    IF ABS(v_residual) > 0 AND ABS(v_residual) <= v_tolerance THEN\n      v_adj_amount := v_residual;\n      v_adj_type := COALESCE(p_adjustment_type, 'rounding');\n      v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'invoice_rounding_tolerance');\n    ELSE\n      v_adj_amount := 0;\n      v_adj_type := 'rounding';\n      v_adj_reason := 'none';\n    END IF;\n  END IF;\n\n  -- Tolerance validation for rounding\n  IF v_adj_type = 'rounding' AND ABS(v_adj_amount) > v_tolerance THEN\n    RAISE EXCEPTION 'Rounding adjustment % exceeds configured tolerance %', v_adj_amount, v_tolerance;\n  END IF;\n\n  -- Reason validation for discount or write-off\n  IF v_adj_type IN ('discount', 'write_off') AND (v_adj_reason IS NULL OR TRIM(v_adj_reason) = '' OR v_adj_reason = 'invoice_rounding_tolerance') THEN\n    RAISE EXCEPTION 'A valid reason is required for discount or write-off settlement adjustments';\n  END IF;\n\n  -- Settle with posted payment activity\n  IF ABS(v_adj_amount) > 0 AND v_has_posted_allocations THEN\n    -- If already correctly adjusted with identical amount and type, just ensure state sync and return\n    IF v_existing.id IS NOT NULL\n       AND v_existing.adjustment_amount = v_adj_amount\n       AND v_existing.adjustment_type = v_adj_type THEN\n      PERFORM public.recalculate_purchase_invoice_payment_state(p_invoice_id);\n      RETURN;\n    END IF;\n\n    -- Clean up previous adjustment journal and record before replacing\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n\n    -- AP Account 2110\n    SELECT id INTO v_ap_account_id\n    FROM public.chart_of_accounts\n    WHERE code = '2110'\n    LIMIT 1;\n\n    -- Adjustment account selection\n    IF v_adj_type = 'rounding' THEN\n      IF v_adj_amount > 0 THEN\n        SELECT COALESCE(\n          (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      ELSE\n        SELECT COALESCE(\n          (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      END IF;\n    ELSIF v_adj_type IN ('discount', 'write_off') THEN\n      IF v_adj_amount > 0 THEN\n        -- Supplier discount reduces AP, credited to Other Income / Purchase Discount (4900 / 4910)\n        SELECT COALESCE(\n          (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '4910' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      ELSE\n        SELECT id INTO v_adjustment_account_id\n        FROM public.chart_of_accounts\n        WHERE code = '6900'\n        LIMIT 1;\n      END IF;\n    END IF;\n\n    IF v_ap_account_id IS NULL OR v_adjustment_account_id IS NULL THEN\n      RAISE EXCEPTION 'Missing COA setup for purchase invoice settlement adjustment';\n    END IF;\n\n    v_user_id := COALESCE(auth.uid(), v_invoice.created_by);\n    v_entry_number := public.next_journal_entry_number();\n\n    INSERT INTO public.journal_entries (\n      entry_number, entry_date, source_module, reference_id, reference_number,\n      description, total_debit, total_credit, is_posted, posted_by, created_by\n    ) VALUES (\n      v_entry_number,\n      COALESCE(v_adjustment_date, CURRENT_DATE),\n      'purchase_invoice_rounding',\n      v_invoice.id,\n      v_invoice.invoice_number,\n      'Payment settlement ' || v_adj_type || ' adjustment: ' || v_invoice.invoice_number,\n      ABS(v_adj_amount),\n      ABS(v_adj_amount),\n      true,\n      v_user_id,\n      v_user_id\n    )\n    RETURNING id INTO v_entry_id;\n\n    IF v_adj_amount > 0 THEN\n      -- Debit AP (clearing payable), Credit Rounding Gain / Purchase Discount (4900)\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)\n      VALUES\n        (v_entry_id, 1, v_ap_account_id, 'A/P settlement clearance - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.supplier_id),\n        (v_entry_id, 2, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.supplier_id);\n    ELSE\n      -- Debit Expense / Write-off (6900), Credit AP\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, supplier_id)\n      VALUES\n        (v_entry_id, 1, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.supplier_id),\n        (v_entry_id, 2, v_ap_account_id, 'A/P settlement clearance - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.supplier_id);\n    END IF;\n\n    INSERT INTO public.invoice_rounding_adjustments (\n      payment_voucher_id, purchase_invoice_id, adjustment_amount, adjustment_type, reason, journal_entry_id, created_by\n    ) VALUES (\n      v_target_pv_id, p_invoice_id, v_adj_amount, v_adj_type, v_adj_reason, v_entry_id, v_user_id\n    );\n  ELSE\n    -- Residual is zero or exceeds tolerance or unposted: clear existing\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n  END IF;\n\n  PERFORM public.recalculate_purchase_invoice_payment_state(p_invoice_id);\nEND;\n$function$;\n\nDO $$\nDECLARE\n  v_old_date date;\n  v_new_date date;\n  v_entry_number text;\nBEGIN\n  SELECT je.entry_date, pv.voucher_date, je.entry_number\n    INTO v_old_date, v_new_date, v_entry_number\n  FROM public.journal_entries je\n  JOIN public.invoice_rounding_adjustments ira ON ira.journal_entry_id = je.id\n  JOIN public.payment_vouchers pv ON pv.id = ira.payment_voucher_id\n  WHERE je.id = '3a957746-d25c-4236-aa07-211aaf27517e'\n    AND je.reference_id = 'e053da05-cbbe-419c-ab10-7e0d96c46ddd'\n    AND je.source_module = 'purchase_invoice_rounding'\n    AND je.is_posted = TRUE;\n\n  IF v_entry_number IS NOT NULL AND v_old_date IS DISTINCT FROM v_new_date THEN\n    UPDATE public.journal_entries\n    SET entry_date = v_new_date\n    WHERE id = '3a957746-d25c-4236-aa07-211aaf27517e';\n\n    INSERT INTO public.audit_logs\n      (user_id, table_name, action_type, record_id, old_values, new_values, changed_fields)\n    VALUES\n      ('1075a773-bb55-4296-bc71-af2eab9a0780', 'journal_entries', 'update',\n       '3a957746-d25c-4236-aa07-211aaf27517e',\n       jsonb_build_object('entry_number', v_entry_number, 'entry_date', v_old_date),\n       jsonb_build_object('entry_number', v_entry_number, 'entry_date', v_new_date),\n       ARRAY['entry_date']);\n  END IF;\nEND $$;"}	correct_purchase_rounding_journal_date	simplykool@gmail.com	\N	\N
20260922084228	{"\n-- Canonical physical inventory movement source for operational reporting/AI.\n-- Legacy inventory_transactions remain preserved for audit, but are not part of\n-- this operational movement source.\n\nDROP VIEW IF EXISTS public.inventory_operational_physical_ledger;\n\nCREATE VIEW public.inventory_operational_physical_ledger AS\nWITH cfg AS (\n  SELECT enforcement_started_at\n  FROM public.inventory_engine_certification\n  WHERE singleton\n),\nbatch_receipts AS (\n  SELECT\n    b.id AS source_id,\n    b.product_id,\n    b.id AS batch_id,\n    b.import_date AS transaction_date,\n    b.import_quantity AS quantity,\n    'batch_receipt'::text AS source_type,\n    b.batch_number AS reference_number\n  FROM public.batches b\n  WHERE COALESCE(b.import_quantity, 0) > 0\n    AND b.import_date IS NOT NULL\n),\napproved_deliveries AS (\n  SELECT\n    dci.id AS source_id,\n    dci.product_id,\n    dci.batch_id,\n    dc.challan_date AS transaction_date,\n    -ABS(COALESCE(dci.quantity, 0)) AS quantity,\n    'delivery_challan'::text AS source_type,\n    dc.challan_number AS reference_number\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc\n    ON dc.id = dci.challan_id\n  WHERE dc.approval_status = 'approved'\n    AND COALESCE(dci.quantity, 0) > 0\n),\ncanonical_post_cutover_changes AS (\n  SELECT\n    it.id AS source_id,\n    it.product_id,\n    it.batch_id,\n    it.transaction_date,\n    it.quantity,\n    CASE\n      WHEN it.transaction_type = 'return' THEN 'canonical_return'\n      ELSE 'canonical_adjustment'\n    END AS source_type,\n    it.reference_number\n  FROM public.inventory_transactions it\n  CROSS JOIN cfg\n  WHERE it.created_at >= cfg.enforcement_started_at\n    AND it.transaction_type IN ('return', 'adjustment')\n    AND it.metadata->>'canonical_engine_version' = '1.0'\n    AND COALESCE((it.metadata->>'superseded')::boolean, false) = false\n    AND COALESCE(it.reference_type, '') NOT IN (\n      'purchase_invoice_receiving',\n      'historical_stock_repair'\n    )\n)\nSELECT\n  source_id,\n  product_id,\n  batch_id,\n  transaction_date,\n  quantity,\n  source_type,\n  reference_number\nFROM batch_receipts\nUNION ALL\nSELECT\n  source_id,\n  product_id,\n  batch_id,\n  transaction_date,\n  quantity,\n  source_type,\n  reference_number\nFROM approved_deliveries\nUNION ALL\nSELECT\n  source_id,\n  product_id,\n  batch_id,\n  transaction_date,\n  quantity,\n  source_type,\n  reference_number\nFROM canonical_post_cutover_changes;\n\nCOMMENT ON VIEW public.inventory_operational_physical_ledger IS\n'Canonical physical inventory movement source for operational reports and AI. Uses batch receipts, approved delivery challans, and genuine canonical post-cutover returns/adjustments. Legacy inventory_transactions evidence, reservations, repairs, and duplicate invoice movement rows are excluded. Do not independently sum legacy inventory_transactions for operational stock.';\n\nCREATE OR REPLACE FUNCTION public.inventory_v1_movement_report(\n  p_date_from date,\n  p_date_to date\n)\nRETURNS TABLE(\n  product_id uuid,\n  product_code text,\n  product_name text,\n  unit text,\n  opening numeric,\n  in_qty numeric,\n  out_qty numeric,\n  reserved_qty numeric,\n  closing numeric,\n  current_stock numeric\n)\nLANGUAGE sql\nSTABLE\nSET search_path TO 'public'\nAS $function$\n  WITH movement_totals AS (\n    SELECT\n      m.product_id,\n      COALESCE(SUM(m.quantity) FILTER (\n        WHERE m.transaction_date < p_date_from\n      ), 0) AS opening,\n      COALESCE(SUM(m.quantity) FILTER (\n        WHERE m.transaction_date BETWEEN p_date_from AND p_date_to\n          AND m.quantity > 0\n      ), 0) AS in_qty,\n      COALESCE(ABS(SUM(m.quantity) FILTER (\n        WHERE m.transaction_date BETWEEN p_date_from AND p_date_to\n          AND m.quantity < 0\n      )), 0) AS out_qty\n    FROM public.inventory_operational_physical_ledger m\n    GROUP BY m.product_id\n  ),\n  stock AS (\n    SELECT\n      s.product_id,\n      COALESCE(s.total_current_stock, 0) AS current_stock,\n      COALESCE(s.reserved_stock, 0) AS reserved_qty\n    FROM public.inventory_v1_stock_summary s\n  )\n  SELECT\n    p.id AS product_id,\n    p.product_code,\n    p.product_name,\n    COALESCE(p.unit, 'PCS') AS unit,\n    COALESCE(mt.opening, 0) AS opening,\n    COALESCE(mt.in_qty, 0) AS in_qty,\n    COALESCE(mt.out_qty, 0) AS out_qty,\n    COALESCE(st.reserved_qty, 0) AS reserved_qty,\n    COALESCE(mt.opening, 0)\n      + COALESCE(mt.in_qty, 0)\n      - COALESCE(mt.out_qty, 0) AS closing,\n    COALESCE(st.current_stock, 0) AS current_stock\n  FROM public.products p\n  LEFT JOIN movement_totals mt ON mt.product_id = p.id\n  LEFT JOIN stock st ON st.product_id = p.id\n  WHERE COALESCE(mt.opening, 0) <> 0\n     OR COALESCE(mt.in_qty, 0) <> 0\n     OR COALESCE(mt.out_qty, 0) <> 0\n     OR COALESCE(st.reserved_qty, 0) <> 0\n     OR COALESCE(st.current_stock, 0) <> 0\n  ORDER BY p.product_code, p.product_name;\n$function$;\n"}	canonical_operational_inventory_reporting_source	simplykool@gmail.com	\N	\N
20261019152825	{"CREATE OR REPLACE FUNCTION public.apply_receipt_allocation_rounding_adjustment(p_invoice_id uuid, p_receipt_voucher_id uuid DEFAULT NULL::uuid, p_adjustment_type text DEFAULT 'rounding'::text, p_reason text DEFAULT 'invoice_rounding_tolerance'::text, p_amount numeric DEFAULT NULL::numeric)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_invoice record;\n  v_allocated numeric(18,2);\n  v_residual numeric(18,2);\n  v_tolerance numeric(18,2);\n  v_existing record;\n  v_entry_id uuid;\n  v_entry_number text;\n  v_ar_account_id uuid;\n  v_adjustment_account_id uuid;\n  v_user_id uuid;\n  v_target_rv_id uuid;\n  v_adjustment_date date;\n  v_has_posted_allocations boolean := false;\n  v_adj_amount numeric(18,2);\n  v_adj_type text;\n  v_adj_reason text;\nBEGIN\n  SELECT *\n  INTO v_invoice\n  FROM public.sales_invoices\n  WHERE id = p_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  SELECT COALESCE(rounding_tolerance_amount, 100)\n  INTO v_tolerance\n  FROM public.app_settings\n  LIMIT 1;\n  v_tolerance := COALESCE(v_tolerance, 100);\n\n  SELECT *\n  INTO v_existing\n  FROM public.invoice_rounding_adjustments\n  WHERE sales_invoice_id = p_invoice_id\n  LIMIT 1;\n\n  v_allocated := public.get_invoice_allocation_amount(p_invoice_id, NULL);\n\n  SELECT EXISTS (\n    SELECT 1 \n    FROM public.voucher_allocations va\n    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id\n    WHERE va.sales_invoice_id = p_invoice_id\n      AND va.voucher_type = 'receipt'\n      AND rv.is_posted = true\n  ) INTO v_has_posted_allocations;\n\n  IF p_receipt_voucher_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.receipt_vouchers WHERE id = p_receipt_voucher_id AND is_posted = true\n  ) THEN\n    v_target_rv_id := p_receipt_voucher_id;\n  ELSIF v_has_posted_allocations THEN\n    SELECT rv.id INTO v_target_rv_id\n    FROM public.voucher_allocations va\n    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id\n    WHERE va.sales_invoice_id = p_invoice_id\n      AND va.voucher_type = 'receipt'\n      AND rv.is_posted = true\n    ORDER BY rv.created_at DESC\n    LIMIT 1;\n  ELSE\n    v_target_rv_id := NULL;\n  END IF;\n\n  -- Settlement adjustments belong to the receipt voucher date, not the original invoice date.\n  SELECT rv.voucher_date INTO v_adjustment_date\n  FROM public.receipt_vouchers rv\n  WHERE rv.id = v_target_rv_id;\n  v_adjustment_date := COALESCE(v_adjustment_date, CURRENT_DATE);\n\n  v_residual := ROUND(COALESCE(v_invoice.total_amount, 0) - COALESCE(v_allocated, 0), 2);\n\n  IF p_amount IS NOT NULL AND p_amount <> 0 THEN\n    v_adj_amount := ROUND(p_amount, 2);\n    v_adj_type := COALESCE(p_adjustment_type, 'rounding');\n    v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'settlement_adjustment');\n  ELSE\n    IF ABS(v_residual) > 0 AND ABS(v_residual) <= v_tolerance THEN\n      v_adj_amount := v_residual;\n      v_adj_type := COALESCE(p_adjustment_type, 'rounding');\n      v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'invoice_rounding_tolerance');\n    ELSE\n      v_adj_amount := 0;\n      v_adj_type := 'rounding';\n      v_adj_reason := 'none';\n    END IF;\n  END IF;\n\n  IF v_adj_type = 'rounding' AND ABS(v_adj_amount) > v_tolerance THEN\n    RAISE EXCEPTION 'Rounding adjustment % exceeds configured tolerance %', v_adj_amount, v_tolerance;\n  END IF;\n\n  IF v_adj_type IN ('discount', 'write_off') AND (v_adj_reason IS NULL OR TRIM(v_adj_reason) = '' OR v_adj_reason = 'invoice_rounding_tolerance') THEN\n    RAISE EXCEPTION 'A valid reason is required for discount or write-off settlement adjustments';\n  END IF;\n\n  IF ABS(v_adj_amount) > 0 AND v_has_posted_allocations THEN\n    IF v_existing.id IS NOT NULL \n       AND v_existing.adjustment_amount = v_adj_amount \n       AND v_existing.adjustment_type = v_adj_type THEN\n      PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);\n      RETURN;\n    END IF;\n\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n\n    -- AR Account 1120\n    SELECT id INTO v_ar_account_id\n    FROM public.chart_of_accounts\n    WHERE code = '1120'\n    LIMIT 1;\n\n    IF v_adj_type = 'rounding' THEN\n      IF v_adj_amount > 0 THEN\n        -- Customer short payment under tolerance: write-off expense\n        SELECT COALESCE(\n          (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      ELSE\n        -- Customer overpayment under tolerance: rounding gain\n        SELECT COALESCE(\n          (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      END IF;\n    ELSIF v_adj_type IN ('discount', 'write_off') THEN\n      IF v_adj_amount > 0 THEN\n        -- Commercial sales discount granted: debit Sales Discounts (4200)\n        SELECT COALESCE(\n          (SELECT id FROM public.chart_of_accounts WHERE code = '4200' LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      ELSE\n        SELECT id INTO v_adjustment_account_id\n        FROM public.chart_of_accounts\n        WHERE code = '4900'\n        LIMIT 1;\n      END IF;\n    END IF;\n\n    IF v_ar_account_id IS NULL OR v_adjustment_account_id IS NULL THEN\n      RAISE EXCEPTION 'Missing COA setup for sales invoice settlement adjustment';\n    END IF;\n\n    v_user_id := COALESCE(auth.uid(), v_invoice.created_by);\n    v_entry_number := public.next_journal_entry_number();\n\n    INSERT INTO public.journal_entries (\n      entry_number, entry_date, source_module, reference_id, reference_number,\n      description, total_debit, total_credit, is_posted, posted_by, created_by\n    ) VALUES (\n      v_entry_number,\n      COALESCE(v_adjustment_date, CURRENT_DATE),\n      'sales_invoice_rounding',\n      v_invoice.id,\n      v_invoice.invoice_number,\n      'Receipt settlement ' || v_adj_type || ' adjustment: ' || v_invoice.invoice_number,\n      ABS(v_adj_amount),\n      ABS(v_adj_amount),\n      true,\n      v_user_id,\n      v_user_id\n    )\n    RETURNING id INTO v_entry_id;\n\n    IF v_adj_amount > 0 THEN\n      -- Customer underpaid: Debit Sales Discount/Expense, Credit AR (1120)\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES\n        (v_entry_id, 1, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.customer_id),\n        (v_entry_id, 2, v_ar_account_id, 'A/R settlement clearance - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.customer_id);\n    ELSE\n      -- Customer overpaid: Debit AR (1120), Credit Gain\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES\n        (v_entry_id, 1, v_ar_account_id, 'A/R settlement clearance - ' || v_invoice.invoice_number, ABS(v_adj_amount), 0, v_invoice.customer_id),\n        (v_entry_id, 2, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_invoice.invoice_number, 0, ABS(v_adj_amount), v_invoice.customer_id);\n    END IF;\n\n    INSERT INTO public.invoice_rounding_adjustments (\n      receipt_voucher_id, sales_invoice_id, adjustment_amount, adjustment_type, reason, journal_entry_id, created_by\n    ) VALUES (\n      v_target_rv_id, p_invoice_id, v_adj_amount, v_adj_type, v_adj_reason, v_entry_id, v_user_id\n    );\n  ELSE\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n  END IF;\n\n  PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);\nEND;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.apply_receipt_allocation_rounding_adjustment(p_invoice_id uuid, p_receipt_voucher_id uuid DEFAULT NULL::uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_invoice record;\n  v_allocated numeric(18,2);\n  v_residual numeric(18,2);\n  v_tolerance numeric(18,2);\n  v_existing record;\n  v_entry_id uuid;\n  v_entry_number text;\n  v_ar_account_id uuid;\n  v_adjustment_account_id uuid;\n  v_user_id uuid;\n  v_target_rv_id uuid;\n  v_adjustment_date date;\n  v_has_posted_allocations boolean := false;\nBEGIN\n  SELECT *\n  INTO v_invoice\n  FROM public.sales_invoices\n  WHERE id = p_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  -- Verify tolerance from settings\n  SELECT COALESCE(rounding_tolerance_amount, 100)\n  INTO v_tolerance\n  FROM public.app_settings\n  LIMIT 1;\n  v_tolerance := COALESCE(v_tolerance, 100);\n\n  -- Fetch existing rounding adjustment for this invoice\n  SELECT *\n  INTO v_existing\n  FROM public.invoice_rounding_adjustments\n  WHERE sales_invoice_id = p_invoice_id\n  LIMIT 1;\n\n  -- Only POSTED receipt voucher allocations count\n  v_allocated := public.get_invoice_allocation_amount(p_invoice_id, NULL);\n\n  -- Check if any posted receipt allocation exists for this invoice\n  SELECT EXISTS (\n    SELECT 1 \n    FROM public.voucher_allocations va\n    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id\n    WHERE va.sales_invoice_id = p_invoice_id\n      AND va.voucher_type = 'receipt'\n      AND rv.is_posted = true\n  ) INTO v_has_posted_allocations;\n\n  -- If p_receipt_voucher_id is supplied, ensure it is posted; otherwise select latest posted RV\n  IF p_receipt_voucher_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.receipt_vouchers WHERE id = p_receipt_voucher_id AND is_posted = true\n  ) THEN\n    v_target_rv_id := p_receipt_voucher_id;\n  ELSIF v_has_posted_allocations THEN\n    SELECT rv.id INTO v_target_rv_id\n    FROM public.voucher_allocations va\n    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id\n    WHERE va.sales_invoice_id = p_invoice_id\n      AND va.voucher_type = 'receipt'\n      AND rv.is_posted = true\n    ORDER BY rv.created_at DESC\n    LIMIT 1;\n  ELSE\n    v_target_rv_id := NULL;\n  END IF;\n\n  -- Settlement adjustments belong to the receipt voucher date, not the original invoice date.\n  SELECT rv.voucher_date INTO v_adjustment_date\n  FROM public.receipt_vouchers rv\n  WHERE rv.id = v_target_rv_id;\n  v_adjustment_date := COALESCE(v_adjustment_date, CURRENT_DATE);\n\n  v_residual := ROUND(COALESCE(v_invoice.total_amount, 0) - COALESCE(v_allocated, 0), 2);\n\n  -- Small residual within tolerance requires posted payment activity\n  IF ABS(v_residual) > 0 AND ABS(v_residual) <= v_tolerance AND v_has_posted_allocations THEN\n    -- If already correctly adjusted, just ensure payment state is synced and return\n    IF v_existing.id IS NOT NULL AND v_existing.adjustment_amount = v_residual THEN\n      PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);\n      RETURN;\n    END IF;\n\n    -- Clean up previous adjustment journal and record before replacing\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n\n    SELECT id INTO v_ar_account_id\n    FROM public.chart_of_accounts\n    WHERE code = '1120'\n    LIMIT 1;\n\n    IF v_residual > 0 THEN\n      SELECT COALESCE(\n        (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),\n        (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)\n      )\n      INTO v_adjustment_account_id;\n    ELSE\n      SELECT COALESCE(\n        (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),\n        (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)\n      )\n      INTO v_adjustment_account_id;\n    END IF;\n\n    IF v_ar_account_id IS NULL OR v_adjustment_account_id IS NULL THEN\n      RAISE EXCEPTION 'Missing account setup for invoice rounding adjustment';\n    END IF;\n\n    v_user_id := COALESCE(auth.uid(), v_invoice.created_by);\n    v_entry_number := public.next_journal_entry_number();\n\n    INSERT INTO public.journal_entries (\n      entry_number, entry_date, source_module, reference_id, reference_number,\n      description, total_debit, total_credit, is_posted, posted_by, created_by\n    ) VALUES (\n      v_entry_number,\n      COALESCE(v_adjustment_date, CURRENT_DATE),\n      'sales_invoice_rounding',\n      v_invoice.id,\n      v_invoice.invoice_number,\n      'Receipt allocation rounding adjustment: ' || v_invoice.invoice_number,\n      ABS(v_residual),\n      ABS(v_residual),\n      true,\n      v_user_id,\n      v_user_id\n    )\n    RETURNING id INTO v_entry_id;\n\n    IF v_residual > 0 THEN\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES\n        (v_entry_id, 1, v_adjustment_account_id, 'Rounding write-off - ' || v_invoice.invoice_number, ABS(v_residual), 0, v_invoice.customer_id),\n        (v_entry_id, 2, v_ar_account_id, 'A/R rounding clearance - ' || v_invoice.invoice_number, 0, ABS(v_residual), v_invoice.customer_id);\n    ELSE\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES\n        (v_entry_id, 1, v_ar_account_id, 'A/R rounding clearance - ' || v_invoice.invoice_number, ABS(v_residual), 0, v_invoice.customer_id),\n        (v_entry_id, 2, v_adjustment_account_id, 'Rounding gain - ' || v_invoice.invoice_number, 0, ABS(v_residual), v_invoice.customer_id);\n    END IF;\n\n    INSERT INTO public.invoice_rounding_adjustments (\n      receipt_voucher_id, sales_invoice_id, adjustment_amount, journal_entry_id, created_by\n    ) VALUES (\n      v_target_rv_id, p_invoice_id, v_residual, v_entry_id, v_user_id\n    );\n  ELSE\n    -- Residual is zero or exceeds tolerance or no posted payments: clear any existing rounding\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n  END IF;\n\n  PERFORM public.recalculate_sales_invoice_payment_state(p_invoice_id);\nEND;\n$function$;\n\n-- Historical repair: only known posted settlement-rounding journals with an\n-- incorrect invoice-date journal date. Preserve the adjustment amounts and lines.\nDO $$\nDECLARE\n  r record;\nBEGIN\n  FOR r IN\n    SELECT je.id, je.entry_number, je.entry_date AS old_date, rv.voucher_date AS new_date\n    FROM public.invoice_rounding_adjustments ira\n    JOIN public.journal_entries je ON je.id = ira.journal_entry_id\n    JOIN public.receipt_vouchers rv ON rv.id = ira.receipt_voucher_id\n    WHERE ira.sales_invoice_id IS NOT NULL\n      AND je.source_module = 'sales_invoice_rounding'\n      AND je.is_posted = TRUE\n      AND je.entry_date IS DISTINCT FROM rv.voucher_date\n      AND je.id IN (\n        'eed27909-6333-47c2-9b5e-55ac68aab07d'::uuid,\n        '5fbc3d14-7194-4bef-8343-6153a72a8b1c'::uuid,\n        '452d5f54-7c8a-45a8-985f-1778f66c04ac'::uuid,\n        '09612deb-a55a-46f1-a92d-4894ed64e894'::uuid\n      )\n  LOOP\n    UPDATE public.journal_entries SET entry_date = r.new_date WHERE id = r.id;\n    INSERT INTO public.audit_logs\n      (user_id, table_name, action_type, record_id, old_values, new_values, changed_fields)\n    VALUES\n      ('1075a773-bb55-4296-bc71-af2eab9a0780', 'journal_entries', 'update', r.id,\n       jsonb_build_object('entry_number', r.entry_number, 'entry_date', r.old_date),\n       jsonb_build_object('entry_number', r.entry_number, 'entry_date', r.new_date),\n       ARRAY['entry_date']);\n  END LOOP;\nEND $$;"}	fix_receipt_rounding_journal_dates	simplykool@gmail.com	\N	\N
