20261023133847	{"ALTER TABLE public.voucher_allocations\n  DROP CONSTRAINT voucher_allocations_check;\n\nALTER TABLE public.voucher_allocations\n  ADD CONSTRAINT voucher_allocations_check\n  CHECK (\n    (\n      voucher_type = 'receipt'\n      AND receipt_voucher_id IS NOT NULL\n      AND (\n        sales_invoice_id IS NOT NULL\n        OR sales_order_id IS NOT NULL\n      )\n    )\n    OR (\n      voucher_type = 'payment'\n      AND payment_voucher_id IS NOT NULL\n      AND purchase_invoice_id IS NOT NULL\n    )\n    OR (\n      voucher_type = 'payment'\n      AND payment_voucher_id IS NOT NULL\n      AND finance_expense_id IS NOT NULL\n    )\n  );"}	allow_receipt_allocations_to_sales_orders	simplykool@gmail.com	\N	\N
