20261023134102	{"-- Migration: 20261023170000_fix_receipt_voucher_settlement_rounding.sql\n-- Description: Fix Receipt Voucher allocation and posting workflow for rounding differences\n-- Supports Sales Order advance settlements, records rounding adjustments to account 4900/6900,\n-- prevents arbitrary unallocated over/underpayment beyond tolerance, and guarantees idempotency.\n\n-- 1. Schema enhancement on invoice_rounding_adjustments to support sales orders\nALTER TABLE public.invoice_rounding_adjustments\n  ADD COLUMN IF NOT EXISTS sales_order_id uuid REFERENCES public.sales_orders(id) ON DELETE CASCADE;\n\n-- 1b. Fix voucher_allocations_check to permit Receipt -> Sales Order (Advance) allocations\nALTER TABLE public.voucher_allocations\n  DROP CONSTRAINT IF EXISTS voucher_allocations_check;\n\nALTER TABLE public.voucher_allocations\n  ADD CONSTRAINT voucher_allocations_check CHECK (\n    (voucher_type = 'receipt' AND receipt_voucher_id IS NOT NULL AND (\n      (sales_invoice_id IS NOT NULL AND sales_order_id IS NULL) OR\n      (sales_order_id IS NOT NULL AND sales_invoice_id IS NULL)\n    )) OR\n    (voucher_type = 'payment' AND payment_voucher_id IS NOT NULL AND (\n      (purchase_invoice_id IS NOT NULL AND finance_expense_id IS NULL) OR\n      (finance_expense_id IS NOT NULL AND purchase_invoice_id IS NULL)\n    ))\n  );\n\nALTER TABLE public.invoice_rounding_adjustments\n  DROP CONSTRAINT IF EXISTS chk_invoice_rounding_adjustments_target;\n\nALTER TABLE public.invoice_rounding_adjustments\n  ADD CONSTRAINT chk_invoice_rounding_adjustments_target\n  CHECK (\n    (sales_invoice_id IS NOT NULL AND purchase_invoice_id IS NULL AND sales_order_id IS NULL) OR\n    (purchase_invoice_id IS NOT NULL AND sales_invoice_id IS NULL AND sales_order_id IS NULL) OR\n    (sales_order_id IS NOT NULL AND sales_invoice_id IS NULL AND purchase_invoice_id IS NULL)\n  );\n\nCREATE UNIQUE INDEX IF NOT EXISTS invoice_rounding_adjustments_one_per_so\n  ON public.invoice_rounding_adjustments (sales_order_id)\n  WHERE sales_order_id IS NOT NULL;\n\nCREATE INDEX IF NOT EXISTS idx_invoice_rounding_adjustments_so\n  ON public.invoice_rounding_adjustments (sales_order_id)\n  WHERE sales_order_id IS NOT NULL;\n\n-- 2. Helper function to get Sales Order rounding adjustment amount\nCREATE OR REPLACE FUNCTION public.get_sales_order_rounding_adjustment_amount(p_sales_order_id uuid)\nRETURNS numeric\nLANGUAGE sql SECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\n  SELECT COALESCE(SUM(adjustment_amount), 0)\n  FROM public.invoice_rounding_adjustments\n  WHERE sales_order_id = p_sales_order_id;\n$$;\n\nREVOKE ALL ON FUNCTION public.get_sales_order_rounding_adjustment_amount(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.get_sales_order_rounding_adjustment_amount(uuid) TO authenticated, service_role;\n\n-- 3. Update update_so_advance_status trigger function to include rounding adjustments and tolerance\nCREATE OR REPLACE FUNCTION public.update_so_advance_status()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_sales_order_id UUID;\n  v_total_advance DECIMAL(18,2);\n  v_order_total DECIMAL(18,2);\n  v_total_adj DECIMAL(18,2) := 0;\n  v_tolerance DECIMAL(18,2) := 100;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    v_sales_order_id := OLD.sales_order_id;\n  ELSE\n    v_sales_order_id := NEW.sales_order_id;\n  END IF;\n\n  IF v_sales_order_id IS NULL THEN\n    RETURN COALESCE(NEW, OLD);\n  END IF;\n\n  SELECT COALESCE(SUM(va.allocated_amount), 0)\n    INTO v_total_advance\n    FROM public.voucher_allocations va\n   WHERE va.sales_order_id = v_sales_order_id\n     AND va.voucher_type = 'receipt';\n\n  SELECT total_amount INTO v_order_total\n    FROM public.sales_orders\n   WHERE id = v_sales_order_id;\n\n  SELECT COALESCE(SUM(ira.adjustment_amount), 0)\n    INTO v_total_adj\n    FROM public.invoice_rounding_adjustments ira\n   WHERE ira.sales_order_id = v_sales_order_id;\n\n  SELECT COALESCE(rounding_tolerance_amount, 100)\n    INTO v_tolerance\n    FROM public.app_settings\n   LIMIT 1;\n\n  UPDATE public.sales_orders\n  SET \n    advance_payment_amount = v_total_advance,\n    advance_payment_status = CASE\n      WHEN v_total_advance = 0 AND v_total_adj = 0 THEN 'none'\n      WHEN (v_total_advance + v_total_adj) >= v_order_total \n           OR (v_order_total - v_total_advance) <= v_tolerance THEN 'full'\n      ELSE 'partial'\n    END,\n    updated_at = now()\n  WHERE id = v_sales_order_id;\n\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$;\n\n-- 4. Function for Sales Order settlement rounding adjustments\nCREATE OR REPLACE FUNCTION public.apply_so_allocation_rounding_adjustment(\n  p_so_id uuid,\n  p_receipt_voucher_id uuid,\n  p_adjustment_type text DEFAULT 'rounding',\n  p_reason text DEFAULT 'invoice_rounding_tolerance',\n  p_amount numeric DEFAULT NULL\n)\nRETURNS void\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_so RECORD;\n  v_tolerance numeric;\n  v_existing RECORD;\n  v_allocated numeric;\n  v_residual numeric;\n  v_target_rv_id uuid;\n  v_has_posted_allocations boolean := false;\n  v_adj_amount numeric(18,2);\n  v_adj_type text;\n  v_adj_reason text;\n  v_voucher_date date;\n  v_ar_account_id uuid;\n  v_adjustment_account_id uuid;\n  v_user_id uuid;\n  v_entry_number text;\n  v_entry_id uuid;\nBEGIN\n  SELECT *\n  INTO v_so\n  FROM public.sales_orders\n  WHERE id = p_so_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  SELECT COALESCE(rounding_tolerance_amount, 100)\n  INTO v_tolerance\n  FROM public.app_settings\n  LIMIT 1;\n  v_tolerance := COALESCE(v_tolerance, 100);\n\n  SELECT *\n  INTO v_existing\n  FROM public.invoice_rounding_adjustments\n  WHERE sales_order_id = p_so_id\n  LIMIT 1;\n\n  SELECT COALESCE(SUM(allocated_amount), 0)\n  INTO v_allocated\n  FROM public.voucher_allocations\n  WHERE sales_order_id = p_so_id\n    AND voucher_type = 'receipt';\n\n  SELECT EXISTS (\n    SELECT 1 \n    FROM public.voucher_allocations va\n    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id\n    WHERE va.sales_order_id = p_so_id\n      AND va.voucher_type = 'receipt'\n      AND rv.is_posted = true\n  ) INTO v_has_posted_allocations;\n\n  IF p_receipt_voucher_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.receipt_vouchers WHERE id = p_receipt_voucher_id AND is_posted = true\n  ) THEN\n    v_target_rv_id := p_receipt_voucher_id;\n  ELSIF v_has_posted_allocations THEN\n    SELECT rv.id INTO v_target_rv_id\n    FROM public.voucher_allocations va\n    JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id\n    WHERE va.sales_order_id = p_so_id\n      AND va.voucher_type = 'receipt'\n      AND rv.is_posted = true\n    ORDER BY rv.created_at DESC\n    LIMIT 1;\n  ELSE\n    v_target_rv_id := NULL;\n  END IF;\n\n  IF v_target_rv_id IS NOT NULL THEN\n    SELECT voucher_date INTO v_voucher_date\n    FROM public.receipt_vouchers\n    WHERE id = v_target_rv_id;\n  END IF;\n\n  v_residual := ROUND(COALESCE(v_so.total_amount, 0) - COALESCE(v_allocated, 0), 2);\n\n  IF p_amount IS NOT NULL AND p_amount <> 0 THEN\n    v_adj_amount := ROUND(p_amount, 2);\n    v_adj_type := COALESCE(p_adjustment_type, 'rounding');\n    v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'settlement_adjustment');\n  ELSE\n    IF ABS(v_residual) > 0 AND ABS(v_residual) <= v_tolerance THEN\n      v_adj_amount := v_residual;\n      v_adj_type := COALESCE(p_adjustment_type, 'rounding');\n      v_adj_reason := COALESCE(NULLIF(p_reason, ''), 'invoice_rounding_tolerance');\n    ELSE\n      v_adj_amount := 0;\n      v_adj_type := 'rounding';\n      v_adj_reason := 'none';\n    END IF;\n  END IF;\n\n  IF v_adj_type = 'rounding' AND ABS(v_adj_amount) > v_tolerance THEN\n    RAISE EXCEPTION 'Rounding adjustment % exceeds configured tolerance %', v_adj_amount, v_tolerance;\n  END IF;\n\n  IF ABS(v_adj_amount) > 0 AND v_has_posted_allocations THEN\n    IF v_existing.id IS NOT NULL \n       AND v_existing.adjustment_amount = v_adj_amount \n       AND v_existing.adjustment_type = v_adj_type THEN\n      IF v_existing.journal_entry_id IS NOT NULL AND v_voucher_date IS NOT NULL THEN\n        UPDATE public.journal_entries\n        SET entry_date = v_voucher_date\n        WHERE id = v_existing.journal_entry_id AND entry_date <> v_voucher_date;\n      END IF;\n      RETURN;\n    END IF;\n\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n\n    -- AR / Advance Account 1120\n    SELECT id INTO v_ar_account_id\n    FROM public.chart_of_accounts\n    WHERE code = '1120'\n    LIMIT 1;\n\n    IF v_adj_type = 'rounding' THEN\n      IF v_adj_amount > 0 THEN\n        -- Short payment under tolerance: write-off expense\n        SELECT COALESCE(\n          (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      ELSE\n        -- Overpayment under tolerance: rounding gain\n        SELECT COALESCE(\n          (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),\n          (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)\n        ) INTO v_adjustment_account_id;\n      END IF;\n    ELSIF v_adj_type IN ('discount', 'write_off') THEN\n      SELECT COALESCE(\n        (SELECT id FROM public.chart_of_accounts WHERE code = '4200' LIMIT 1),\n        (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)\n      ) INTO v_adjustment_account_id;\n    END IF;\n\n    IF v_ar_account_id IS NULL OR v_adjustment_account_id IS NULL THEN\n      RAISE EXCEPTION 'Missing COA setup for sales order settlement adjustment';\n    END IF;\n\n    v_user_id := COALESCE(auth.uid(), v_so.created_by);\n    v_entry_number := public.next_journal_entry_number();\n\n    INSERT INTO public.journal_entries (\n      entry_number, entry_date, source_module, reference_id, reference_number,\n      description, total_debit, total_credit, is_posted, posted_by, created_by\n    ) VALUES (\n      v_entry_number,\n      COALESCE(v_voucher_date, CURRENT_DATE),\n      'sales_order_rounding',\n      v_so.id,\n      v_so.so_number,\n      'Receipt settlement ' || v_adj_type || ' adjustment: ' || v_so.so_number,\n      ABS(v_adj_amount),\n      ABS(v_adj_amount),\n      true,\n      v_user_id,\n      v_user_id\n    )\n    RETURNING id INTO v_entry_id;\n\n    IF v_adj_amount > 0 THEN\n      -- Customer underpaid: Debit Rounding Expense (6900) or Discount (4200), Credit AR (1120)\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES\n        (v_entry_id, 1, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_so.so_number, ABS(v_adj_amount), 0, v_so.customer_id),\n        (v_entry_id, 2, v_ar_account_id, 'SO advance clearance - ' || v_so.so_number, 0, ABS(v_adj_amount), v_so.customer_id);\n    ELSE\n      -- Customer overpaid: Debit AR (1120), Credit Rounding Gain (4900)\n      INSERT INTO public.journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES\n        (v_entry_id, 1, v_ar_account_id, 'SO advance clearance - ' || v_so.so_number, ABS(v_adj_amount), 0, v_so.customer_id),\n        (v_entry_id, 2, v_adjustment_account_id, INITCAP(v_adj_type) || ' - ' || v_so.so_number, 0, ABS(v_adj_amount), v_so.customer_id);\n    END IF;\n\n    INSERT INTO public.invoice_rounding_adjustments (\n      receipt_voucher_id, sales_order_id, adjustment_amount, adjustment_type, reason, journal_entry_id, created_by\n    ) VALUES (\n      v_target_rv_id, p_so_id, v_adj_amount, v_adj_type, v_adj_reason, v_entry_id, v_user_id\n    );\n  ELSE\n    IF v_existing.journal_entry_id IS NOT NULL THEN\n      DELETE FROM public.journal_entry_lines WHERE journal_entry_id = v_existing.journal_entry_id;\n      DELETE FROM public.journal_entries WHERE id = v_existing.journal_entry_id;\n    END IF;\n    IF v_existing.id IS NOT NULL THEN\n      DELETE FROM public.invoice_rounding_adjustments WHERE id = v_existing.id;\n    END IF;\n  END IF;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.apply_so_allocation_rounding_adjustment(uuid, uuid, text, text, numeric) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.apply_so_allocation_rounding_adjustment(uuid, uuid, text, text, numeric) TO authenticated, service_role;\n\n-- 5. Update save_invoice_settlement_adjustment to support sales orders and invoices\nCREATE OR REPLACE FUNCTION public.save_invoice_settlement_adjustment(\n  p_document_type text,\n  p_invoice_id uuid,\n  p_voucher_id uuid DEFAULT NULL::uuid,\n  p_adjustment_amount numeric DEFAULT NULL::numeric,\n  p_adjustment_type text DEFAULT 'rounding',\n  p_reason text DEFAULT 'invoice_rounding_tolerance'\n)\nRETURNS void\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nBEGIN\n  PERFORM public._sec_check_finance_role();\n\n  IF p_document_type = 'purchase' THEN\n    PERFORM public.apply_payment_allocation_rounding_adjustment(\n      p_invoice_id,\n      p_voucher_id,\n      p_adjustment_type,\n      p_reason,\n      p_adjustment_amount\n    );\n  ELSIF p_document_type IN ('sales', 'sales_invoice') THEN\n    IF EXISTS (SELECT 1 FROM public.sales_invoices WHERE id = p_invoice_id) THEN\n      PERFORM public.apply_receipt_allocation_rounding_adjustment(\n        p_invoice_id,\n        p_voucher_id,\n        p_adjustment_type,\n        p_reason,\n        p_adjustment_amount\n      );\n    ELSIF EXISTS (SELECT 1 FROM public.sales_orders WHERE id = p_invoice_id) THEN\n      PERFORM public.apply_so_allocation_rounding_adjustment(\n        p_invoice_id,\n        p_voucher_id,\n        p_adjustment_type,\n        p_reason,\n        p_adjustment_amount\n      );\n    ELSE\n      RAISE EXCEPTION 'Target sales document % not found', p_invoice_id;\n    END IF;\n  ELSIF p_document_type = 'sales_order' THEN\n    PERFORM public.apply_so_allocation_rounding_adjustment(\n      p_invoice_id,\n      p_voucher_id,\n      p_adjustment_type,\n      p_reason,\n      p_adjustment_amount\n    );\n  ELSE\n    RAISE EXCEPTION 'Invalid document type % for settlement adjustment', p_document_type;\n  END IF;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.save_invoice_settlement_adjustment(text, uuid, uuid, numeric, text, text) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.save_invoice_settlement_adjustment(text, uuid, uuid, numeric, text, text) TO authenticated, service_role;\n\n-- 6. Canonical post_receipt_voucher supporting sales orders, rounding tolerance, and exact accounting\nCREATE OR REPLACE FUNCTION public.post_receipt_voucher(p_rv_id uuid, p_posted_by uuid DEFAULT NULL::uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_rv                 RECORD;\n  v_je_id              UUID;\n  v_je_number          TEXT;\n  v_debit_account_id   UUID;\n  v_credit_account_id  UUID;\n  v_fx_loss_id         UUID;\n  v_fx_gain_id         UUID;\n  v_rounding_loss_id   UUID;\n  v_rounding_gain_id   UUID;\n  v_actual_poster      UUID;\n  v_rate               NUMERIC := 1;\n  v_actual_received    NUMERIC;\n  v_carrying_ar        NUMERIC;\n  v_total_allocated    NUMERIC := 0;\n  v_diff               NUMERIC := 0;\n  v_total_debit        NUMERIC;\n  v_total_credit       NUMERIC;\n  v_line               INTEGER := 1;\n  v_tolerance          NUMERIC := 100;\n  v_currency           TEXT;\n  v_target_si_id       UUID;\n  v_target_so_id       UUID;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actual_poster := COALESCE(auth.uid(), p_posted_by);\n\n  SELECT * INTO v_rv FROM receipt_vouchers WHERE id = p_rv_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id; END IF;\n  IF v_rv.is_posted THEN RAISE EXCEPTION 'Receipt voucher % is already posted', v_rv.voucher_number; END IF;\n\n  IF v_rv.bank_account_id IS NOT NULL THEN\n    SELECT coa_id INTO v_debit_account_id FROM bank_accounts WHERE id = v_rv.bank_account_id;\n  ELSIF v_rv.payment_method = 'cash' THEN\n    SELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1101' LIMIT 1;\n  END IF;\n  IF v_debit_account_id IS NULL THEN\n    SELECT id INTO v_debit_account_id FROM chart_of_accounts WHERE code = '1111' LIMIT 1;\n  END IF;\n\n  IF v_rv.coa_account_id IS NOT NULL THEN\n    v_credit_account_id := v_rv.coa_account_id;\n  ELSE\n    SELECT id INTO v_credit_account_id FROM chart_of_accounts WHERE code = '1120' LIMIT 1;\n  END IF;\n\n  SELECT id INTO v_fx_loss_id FROM chart_of_accounts WHERE code = '7300' LIMIT 1;\n  SELECT id INTO v_fx_gain_id FROM chart_of_accounts WHERE code = '4930' LIMIT 1;\n\n  SELECT COALESCE(\n    (SELECT rounding_writeoff_account_id FROM public.app_settings LIMIT 1),\n    (SELECT id FROM public.chart_of_accounts WHERE code = '6900' LIMIT 1)\n  ) INTO v_rounding_loss_id;\n\n  SELECT COALESCE(\n    (SELECT rounding_gain_account_id FROM public.app_settings LIMIT 1),\n    (SELECT id FROM public.chart_of_accounts WHERE code = '4900' LIMIT 1)\n  ) INTO v_rounding_gain_id;\n\n  IF v_debit_account_id IS NULL OR v_credit_account_id IS NULL THEN\n    RAISE EXCEPTION 'Cannot post: required chart of accounts entries missing';\n  END IF;\n\n  SELECT COALESCE(rounding_tolerance_amount, 100)\n    INTO v_tolerance\n    FROM public.app_settings\n   LIMIT 1;\n  v_tolerance := COALESCE(v_tolerance, 100);\n\n  v_currency := UPPER(COALESCE(v_rv.payment_currency, v_rv.transaction_currency, 'IDR'));\n  v_rate := COALESCE(v_rv.exchange_rate, 1);\n  IF v_rate <= 0 THEN v_rate := 1; END IF;\n\n  -- Actual received in functional currency (IDR)\n  v_actual_received := COALESCE(v_rv.settlement_amount, v_rv.amount * v_rate);\n  v_carrying_ar := v_actual_received;\n\n  -- Load total allocations across both sales invoices and sales orders\n  SELECT COALESCE(SUM(va.allocated_amount), 0)\n    INTO v_total_allocated\n    FROM public.voucher_allocations va\n   WHERE va.receipt_voucher_id = p_rv_id;\n\n  IF v_total_allocated > 0 THEN\n    v_carrying_ar := v_total_allocated;\n  END IF;\n\n  -- Difference between actual bank receipt and carrying AR allocation\n  v_diff := v_actual_received - v_carrying_ar;\n\n  -- Enforce rounding tolerance on IDR transactions\n  IF v_currency = 'IDR' AND v_total_allocated > 0 AND ABS(v_diff) > 0 THEN\n    IF ABS(v_diff) > v_tolerance THEN\n      RAISE EXCEPTION 'Receipt allocation difference % exceeds configured rounding tolerance %', ABS(v_diff), v_tolerance;\n    END IF;\n  END IF;\n\n  IF v_currency = 'IDR' THEN\n    -- In IDR: v_diff is Rounding Adjustment\n    v_total_debit := v_actual_received + CASE WHEN v_diff < 0 THEN ABS(v_diff) ELSE 0 END;\n    v_total_credit := v_carrying_ar + CASE WHEN v_diff > 0 THEN v_diff ELSE 0 END;\n  ELSE\n    -- Foreign currency: v_diff is Realized FX\n    v_total_debit := v_actual_received + CASE WHEN v_diff < 0 THEN ABS(v_diff) ELSE 0 END;\n    v_total_credit := v_carrying_ar + CASE WHEN v_diff > 0 THEN v_diff ELSE 0 END;\n  END IF;\n\n  v_je_number := next_journal_entry_number();\n\n  INSERT INTO journal_entries (\n    entry_number, entry_date, source_module, reference_id, reference_number,\n    description, total_debit, total_credit, is_posted, posted_by,\n    transaction_currency, functional_currency, exchange_rate\n  ) VALUES (\n    v_je_number, v_rv.voucher_date, 'receipt', v_rv.id, v_rv.voucher_number,\n    'Receipt Voucher: ' || v_rv.voucher_number,\n    v_total_debit, v_total_credit, TRUE, v_actual_poster,\n    COALESCE(v_rv.payment_currency, 'IDR'), 'IDR', v_rate\n  ) RETURNING id INTO v_je_id;\n\n  -- Line 1: Debit Bank/Cash with Actual IDR received\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, v_line, v_debit_account_id, 'Cash Receipt - ' || v_rv.voucher_number, v_actual_received, 0, v_rv.customer_id);\n  v_line := v_line + 1;\n\n  -- Line 2: Debit Loss/Write-off if Received Less than Carrying\n  IF v_diff < 0 THEN\n    IF v_currency = 'IDR' THEN\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES (v_je_id, v_line, v_rounding_loss_id, 'Receipt settlement rounding write-off - ' || v_rv.voucher_number, ABS(v_diff), 0, v_rv.customer_id);\n      v_line := v_line + 1;\n    ELSIF v_fx_loss_id IS NOT NULL THEN\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES (v_je_id, v_line, v_fx_loss_id, 'Realized FX loss - ' || v_rv.voucher_number, ABS(v_diff), 0, v_rv.customer_id);\n      v_line := v_line + 1;\n    END IF;\n  END IF;\n\n  -- Line 3: Credit AR with Carrying Value (the allocated document amounts)\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, v_line, v_credit_account_id, 'Receipt - ' || v_rv.voucher_number, 0, v_carrying_ar, v_rv.customer_id);\n  v_line := v_line + 1;\n\n  -- Line 4: Credit Gain if Received More than Carrying\n  IF v_diff > 0 THEN\n    IF v_currency = 'IDR' THEN\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES (v_je_id, v_line, v_rounding_gain_id, 'Receipt settlement rounding gain - ' || v_rv.voucher_number, 0, v_diff, v_rv.customer_id);\n      v_line := v_line + 1;\n    ELSIF v_fx_gain_id IS NOT NULL THEN\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES (v_je_id, v_line, v_fx_gain_id, 'Realized FX gain - ' || v_rv.voucher_number, 0, v_diff, v_rv.customer_id);\n      v_line := v_line + 1;\n    END IF;\n  END IF;\n\n  -- Audit entry in invoice_rounding_adjustments for IDR rounding differences\n  IF v_currency = 'IDR' AND v_total_allocated > 0 AND ABS(v_diff) > 0 THEN\n    SELECT va.sales_invoice_id, va.sales_order_id\n      INTO v_target_si_id, v_target_so_id\n      FROM public.voucher_allocations va\n     WHERE va.receipt_voucher_id = p_rv_id\n     ORDER BY va.allocated_amount DESC\n     LIMIT 1;\n\n    IF NOT EXISTS (SELECT 1 FROM public.invoice_rounding_adjustments WHERE receipt_voucher_id = p_rv_id) THEN\n      INSERT INTO public.invoice_rounding_adjustments (\n        receipt_voucher_id,\n        sales_invoice_id,\n        sales_order_id,\n        adjustment_amount,\n        adjustment_type,\n        reason,\n        journal_entry_id,\n        created_by\n      ) VALUES (\n        p_rv_id,\n        v_target_si_id,\n        v_target_so_id,\n        v_diff,\n        'rounding',\n        CASE WHEN v_diff > 0 THEN 'Receipt settlement rounding gain' ELSE 'Receipt settlement rounding write-off' END,\n        v_je_id,\n        v_actual_poster\n      );\n    ELSE\n      UPDATE public.invoice_rounding_adjustments\n      SET journal_entry_id = v_je_id,\n          sales_order_id = COALESCE(sales_order_id, v_target_so_id),\n          sales_invoice_id = COALESCE(sales_invoice_id, v_target_si_id),\n          adjustment_amount = v_diff\n      WHERE receipt_voucher_id = p_rv_id;\n    END IF;\n\n    -- Ensure SO advance status reflects settlement\n    IF v_target_so_id IS NOT NULL THEN\n      UPDATE public.sales_orders\n      SET advance_payment_status = 'full',\n          updated_at = now()\n      WHERE id = v_target_so_id;\n    END IF;\n  END IF;\n\n  UPDATE receipt_vouchers\n  SET is_posted = TRUE, journal_entry_id = v_je_id\n  WHERE id = p_rv_id;\n\n  INSERT INTO audit_logs (table_name, record_id, action_type, old_values, new_values, user_id)\n  VALUES (\n    'receipt_vouchers', p_rv_id, 'update',\n    jsonb_build_object('is_posted', FALSE),\n    jsonb_build_object('is_posted', TRUE, 'journal_entry_id', v_je_id, 'journal_entry_number', v_je_number, 'posted_by', v_actual_poster),\n    v_actual_poster\n  );\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.post_receipt_voucher(uuid, uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.post_receipt_voucher(uuid, uuid) TO authenticated, service_role;\n\n-- 7. Update cancel_receipt_voucher_posting to clean up rounding adjustments\nCREATE OR REPLACE FUNCTION public.cancel_receipt_voucher_posting(\n  p_rv_id uuid,\n  p_cancelled_by uuid DEFAULT NULL::uuid,\n  p_reason text DEFAULT 'Posting cancelled by administrator'::text\n)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_rv RECORD;\n  v_je RECORD;\n  v_actor uuid;\n  v_alloc RECORD;\n  v_line_ids uuid[] := ARRAY[]::uuid[];\n  v_line_id uuid;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n  v_actor := COALESCE(auth.uid(), p_cancelled_by);\n\n  SELECT * INTO v_rv FROM public.receipt_vouchers WHERE id = p_rv_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Receipt voucher % not found', p_rv_id;\n  END IF;\n\n  IF NOT v_rv.is_posted THEN\n    RAISE EXCEPTION 'Receipt voucher % is not posted', COALESCE(v_rv.voucher_number, p_rv_id::TEXT);\n  END IF;\n\n  SELECT * INTO v_je FROM public.journal_entries WHERE id = v_rv.journal_entry_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'No journal entry found for receipt voucher %', v_rv.voucher_number;\n  END IF;\n\n  -- Clean up any associated rounding adjustments\n  DELETE FROM public.invoice_rounding_adjustments WHERE receipt_voucher_id = p_rv_id;\n\n  -- Step 1: Identify all bank allocations associated with this receipt voucher or its journal entry\n  FOR v_alloc IN\n    SELECT bsa.id, bsa.bank_statement_line_id\n    FROM public.bank_statement_allocations bsa\n    WHERE (bsa.document_type = 'receipt' AND bsa.document_id = p_rv_id)\n       OR (v_rv.journal_entry_id IS NOT NULL AND bsa.journal_entry_id = v_rv.journal_entry_id)\n    FOR UPDATE\n  LOOP\n    IF NOT (v_alloc.bank_statement_line_id = ANY(v_line_ids)) THEN\n      v_line_ids := array_append(v_line_ids, v_alloc.bank_statement_line_id);\n    END IF;\n\n    UPDATE public.finance_historical_repair_commands\n    SET created_allocation_id = NULL\n    WHERE created_allocation_id = v_alloc.id;\n\n    PERFORM public.unmatch_bank_statement_allocation(v_alloc.id);\n  END LOOP;\n\n  -- Step 2: Identify any bank lines directly referencing this receipt or journal entry\n  FOR v_line_id IN\n    SELECT id FROM public.bank_statement_lines\n    WHERE matched_receipt_id = p_rv_id\n       OR (v_rv.journal_entry_id IS NOT NULL AND matched_entry_id = v_rv.journal_entry_id)\n  LOOP\n    IF NOT (v_line_id = ANY(v_line_ids)) THEN\n      v_line_ids := array_append(v_line_ids, v_line_id);\n    END IF;\n  END LOOP;\n\n  -- Step 3: Clear direct bank line references and refresh ownership and reconciliation status\n  IF array_length(v_line_ids, 1) > 0 THEN\n    UPDATE public.bank_statement_lines\n    SET matched_receipt_id = NULL\n    WHERE matched_receipt_id = p_rv_id;\n\n    IF v_rv.journal_entry_id IS NOT NULL THEN\n      UPDATE public.bank_statement_lines\n      SET matched_entry_id = NULL\n      WHERE matched_entry_id = v_rv.journal_entry_id;\n    END IF;\n\n    FOREACH v_line_id IN ARRAY v_line_ids LOOP\n      PERFORM public.sync_bank_line_allocation_owner(v_line_id);\n      PERFORM public.refresh_bank_statement_allocation_status(v_line_id);\n    END LOOP;\n  END IF;\n\n  -- Step 4: Clear the FK reference FIRST so cancel_gl_posting can delete the JE row.\n  UPDATE public.receipt_vouchers\n  SET is_posted = FALSE, journal_entry_id = NULL\n  WHERE id = p_rv_id;\n\n  -- Step 5: Delete original receipt journal entry and record audit log via cancel_gl_posting\n  PERFORM public.cancel_gl_posting(\n    v_je.id,\n    p_rv_id,\n    'receipt_vouchers',\n    v_actor,\n    p_reason,\n    jsonb_build_object(\n      'voucher_number', v_rv.voucher_number,\n      'amount',         v_rv.amount,\n      'is_posted',      TRUE\n    )\n  );\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.cancel_receipt_voucher_posting(uuid, uuid, text) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.cancel_receipt_voucher_posting(uuid, uuid, text) TO authenticated, service_role;\n"}	fix_receipt_voucher_settlement_rounding	simplykool@gmail.com	\N	\N
20260922180000	{auto_match_smart_pending_expense_review_suggestions}	auto_match_smart_pending_expense_review_suggestions	\N	\N	\N
20261023135942	{"-- The five-argument settlement function has defaults for arguments 3-5,\n-- making PostgREST's two-argument RPC call ambiguous with the legacy overload.\n-- Keep the richer canonical function; its defaults preserve two-argument callers.\nDROP FUNCTION public.apply_receipt_allocation_rounding_adjustment(uuid, uuid);"}	fix_receipt_rounding_rpc_overload_ambiguity	simplykool@gmail.com	\N	\N
20260922115603	{"\nCREATE OR REPLACE FUNCTION public.reconcile_so_product_reservation_v2(\n  p_sales_order_item_id uuid,\n  p_reason text DEFAULT 'SO state reconciliation'::text\n)\nRETURNS numeric\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_item record;\n  v_res public.so_product_reservations%ROWTYPE;\n  v_delivered numeric;\n  v_required numeric;\n  v_delta numeric;\n  v_atp numeric;\n  v_grant numeric;\n  v_has_reservation boolean := false;\nBEGIN\n  SELECT soi.*, so.status::text AS so_status\n  INTO v_item\n  FROM public.sales_order_items soi\n  JOIN public.sales_orders so ON so.id = soi.sales_order_id\n  WHERE soi.id = p_sales_order_item_id\n  FOR UPDATE OF soi, so;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Order item not found';\n  END IF;\n\n  PERFORM pg_advisory_xact_lock(hashtextextended(v_item.product_id::text, 0));\n\n  SELECT COALESCE(sum(dci.quantity), 0)\n  INTO v_delivered\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  WHERE dci.sales_order_item_id = v_item.id\n    AND dc.approval_status = 'approved';\n\n  IF v_delivered > v_item.quantity THEN\n    RAISE EXCEPTION 'Delivered quantity exceeds ordered quantity';\n  END IF;\n\n  v_required := CASE\n    WHEN v_item.so_status IN ('pending_approval', 'approved', 'stock_reserved', 'shortage', 'pending_delivery', 'partially_delivered')\n      THEN v_item.quantity - v_delivered\n    ELSE 0\n  END;\n\n  SELECT *\n  INTO v_res\n  FROM public.so_product_reservations\n  WHERE sales_order_item_id = v_item.id\n    AND status = 'active'\n  FOR UPDATE;\n\n  v_has_reservation := FOUND;\n\n  IF v_required = 0 THEN\n    IF v_has_reservation THEN\n      UPDATE public.so_product_reservations\n      SET reserved_quantity = 0,\n          status = 'released',\n          closed_at = now(),\n          updated_at = now(),\n          close_reason = p_reason\n      WHERE id = v_res.id;\n\n      INSERT INTO public.so_product_reservation_events(\n        reservation_id, sales_order_id, sales_order_item_id, event_type,\n        quantity_delta, quantity_after, reason, actor_id\n      ) VALUES (\n        v_res.id, v_item.sales_order_id, v_item.id, 'released',\n        -v_res.reserved_quantity, 0, p_reason, auth.uid()\n      );\n    END IF;\n    RETURN 0;\n  END IF;\n\n  v_atp := public.product_available_to_promise(\n    v_item.product_id,\n    CASE WHEN v_has_reservation THEN v_item.id ELSE NULL END\n  );\n\n  v_grant := LEAST(v_required, GREATEST(COALESCE(v_atp, 0), 0));\n\n  IF NOT v_has_reservation THEN\n    IF v_grant > 0 THEN\n      INSERT INTO public.so_product_reservations(\n        sales_order_id, sales_order_item_id, product_id, reserved_quantity, created_by\n      ) VALUES (\n        v_item.sales_order_id, v_item.id, v_item.product_id, v_grant, auth.uid()\n      ) RETURNING * INTO v_res;\n\n      INSERT INTO public.so_product_reservation_events(\n        reservation_id, sales_order_id, sales_order_item_id, event_type,\n        quantity_delta, quantity_after, reason, actor_id\n      ) VALUES (\n        v_res.id, v_item.sales_order_id, v_item.id, 'created',\n        v_grant, v_grant, p_reason, auth.uid()\n      );\n    END IF;\n  ELSE\n    IF v_res.product_id <> v_item.product_id THEN\n      RAISE EXCEPTION 'Cannot change product on an actively reserved SO item';\n    END IF;\n\n    IF v_grant = 0 THEN\n      UPDATE public.so_product_reservations\n      SET reserved_quantity = 0,\n          status = 'released',\n          closed_at = now(),\n          updated_at = now(),\n          close_reason = p_reason\n      WHERE id = v_res.id;\n\n      INSERT INTO public.so_product_reservation_events(\n        reservation_id, sales_order_id, sales_order_item_id, event_type,\n        quantity_delta, quantity_after, reason, actor_id\n      ) VALUES (\n        v_res.id, v_item.sales_order_id, v_item.id, 'released',\n        -v_res.reserved_quantity, 0, p_reason, auth.uid()\n      );\n    ELSE\n      v_delta := v_grant - v_res.reserved_quantity;\n      IF v_delta <> 0 THEN\n        UPDATE public.so_product_reservations\n        SET reserved_quantity = v_grant,\n            updated_at = now()\n        WHERE id = v_res.id;\n\n        INSERT INTO public.so_product_reservation_events(\n          reservation_id, sales_order_id, sales_order_item_id, event_type,\n          quantity_delta, quantity_after, reason, actor_id\n        ) VALUES (\n          v_res.id, v_item.sales_order_id, v_item.id,\n          CASE WHEN v_delta > 0 THEN 'increased' ELSE 'decreased' END,\n          v_delta, v_grant, p_reason, auth.uid()\n        );\n      END IF;\n    END IF;\n  END IF;\n\n  RETURN v_grant;\nEND;\n$function$;\n\nSET LOCAL app.canonical_reservation_engine = 'on';\n\nDO $$\nDECLARE\n  v_so_id uuid;\n  v_item_id uuid;\n  v_result record;\nBEGIN\n  SELECT so.id, soi.id\n  INTO v_so_id, v_item_id\n  FROM public.sales_orders so\n  JOIN public.sales_order_items soi ON soi.sales_order_id = so.id\n  JOIN public.products p ON p.id = soi.product_id\n  WHERE so.so_number = 'SO-2026-0027'\n    AND p.product_name = 'Ferrous Fumarate USP'\n  LIMIT 1;\n\n  IF v_so_id IS NULL OR v_item_id IS NULL THEN\n    RAISE EXCEPTION 'Ferrous Fumarate SO-2026-0027 item not found';\n  END IF;\n\n  SELECT *\n  INTO v_result\n  FROM public.approve_sales_order_product_reservation_v2(v_so_id, NULL);\n\n  IF COALESCE(v_result.success, true) THEN\n    RAISE EXCEPTION 'Expected SO-2026-0027 reservation to become shortage, but result was success';\n  END IF;\nEND\n$$;\n\nDO $$\nDECLARE\n  v_current numeric;\n  v_reserved numeric;\n  v_available numeric;\n  v_so26 numeric;\n  v_so27 numeric;\n  v_so27_status text;\nBEGIN\n  SELECT COALESCE(sum(b.current_stock) FILTER (\n    WHERE b.is_active\n      AND (b.expiry_date IS NULL OR b.expiry_date > CURRENT_DATE)\n  ),0)\n  INTO v_current\n  FROM public.batches b\n  WHERE b.product_id = (SELECT id FROM public.products WHERE product_name='Ferrous Fumarate USP' LIMIT 1);\n\n  SELECT COALESCE(sum(r.reserved_quantity),0)\n  INTO v_reserved\n  FROM public.so_product_reservations r\n  WHERE r.product_id = (SELECT id FROM public.products WHERE product_name='Ferrous Fumarate USP' LIMIT 1)\n    AND r.status='active';\n\n  SELECT COALESCE(sum(r.reserved_quantity),0)\n  INTO v_so26\n  FROM public.so_product_reservations r\n  WHERE r.product_id = (SELECT id FROM public.products WHERE product_name='Ferrous Fumarate USP' LIMIT 1)\n    AND r.status='active'\n    AND r.sales_order_id = (SELECT id FROM public.sales_orders WHERE so_number='SO-2026-0026');\n\n  SELECT COALESCE(sum(r.reserved_quantity),0)\n  INTO v_so27\n  FROM public.so_product_reservations r\n  WHERE r.product_id = (SELECT id FROM public.products WHERE product_name='Ferrous Fumarate USP' LIMIT 1)\n    AND r.status='active'\n    AND r.sales_order_id = (SELECT id FROM public.sales_orders WHERE so_number='SO-2026-0027');\n\n  SELECT status::text INTO v_so27_status\n  FROM public.sales_orders\n  WHERE so_number='SO-2026-0027';\n\n  v_available := GREATEST(v_current - v_reserved, 0);\n\n  IF v_current <> 5000 OR v_reserved <> 5000 OR v_so26 <> 5000 OR v_so27 <> 0\n     OR v_available <> 0 OR v_so27_status <> 'shortage' THEN\n    RAISE EXCEPTION\n      'Ferrous Fumarate reservation repair failed: current %, reserved %, SO26 %, SO27 %, available %, SO27 status %',\n      v_current, v_reserved, v_so26, v_so27, v_available, v_so27_status;\n  END IF;\nEND\n$$;\n"}	repair_ferrous_fumarate_overreservation	simplykool@gmail.com	\N	\N
20261023140318	{"CREATE OR REPLACE FUNCTION public.sync_si_state_on_rv_posting_change()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_invoice_id uuid;\nBEGIN\n  IF COALESCE(OLD.is_posted, FALSE) IS DISTINCT FROM COALESCE(NEW.is_posted, FALSE) THEN\n    FOR v_invoice_id IN\n      SELECT DISTINCT sales_invoice_id\n      FROM public.voucher_allocations\n      WHERE receipt_voucher_id = NEW.id\n        AND voucher_type = 'receipt'\n        AND sales_invoice_id IS NOT NULL\n    LOOP\n      -- post_receipt_voucher writes the rounding line directly into the\n      -- receipt's own journal entry and records that same JE in\n      -- invoice_rounding_adjustments. Do not let the follow-up invoice\n      -- rounding routine delete/replace that journal entry while the\n      -- receipt_vouchers FK still points at it.\n      IF EXISTS (\n        SELECT 1\n        FROM public.invoice_rounding_adjustments ira\n        WHERE ira.receipt_voucher_id = NEW.id\n          AND ira.sales_invoice_id = v_invoice_id\n          AND ira.journal_entry_id = NEW.journal_entry_id\n          AND NEW.journal_entry_id IS NOT NULL\n      ) THEN\n        PERFORM public.recalculate_sales_invoice_payment_state(v_invoice_id);\n      ELSE\n        PERFORM public.apply_receipt_allocation_rounding_adjustment(v_invoice_id, NEW.id);\n      END IF;\n    END LOOP;\n  END IF;\n  RETURN NEW;\nEND;\n$function$;"}	fix_receipt_posting_rounding_journal_fk	simplykool@gmail.com	\N	\N
20261023153932	{"-- ============================================================================\n-- Migration: 20261023210000_fix_sales_invoice_paid_amount_calculation.sql\n-- Fix: Prevent \\"Invoice paid amount cannot exceed total amount (P0001)\\"\n--\n-- 1. get_invoice_allocation_amount: Count ONLY allocations from POSTED receipt vouchers\n--    (rv.is_posted = true), fulfilling the authoritative contract in\n--    docs/AUTHORITATIVE_DERIVED_FIELDS.md and mirroring purchase invoices.\n-- 2. recalculate_sales_invoice_payment_state: Bound paid_amount with LEAST/GREATEST\n--    so that settlement adjustments (e.g. Rounding Gain / Rp 0.25 residual) or\n--    overpayments never push sales_invoices.paid_amount above total_amount.\n-- 3. get_invoice_paid_amount & balance RPCs: Reflect the same bounded calculation.\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION public.get_invoice_allocation_amount(\n  p_invoice_id uuid,\n  p_exclude_voucher_id uuid DEFAULT NULL::uuid\n) RETURNS numeric\nLANGUAGE sql SECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\n  SELECT COALESCE(SUM(va.allocated_amount), 0)\n  FROM public.voucher_allocations va\n  JOIN public.receipt_vouchers rv ON rv.id = va.receipt_voucher_id\n  WHERE va.sales_invoice_id = p_invoice_id\n    AND va.voucher_type = 'receipt'\n    AND rv.is_posted = true\n    AND (p_exclude_voucher_id IS NULL OR va.receipt_voucher_id <> p_exclude_voucher_id);\n$$;\n\nREVOKE ALL ON FUNCTION public.get_invoice_allocation_amount(uuid, uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.get_invoice_allocation_amount(uuid, uuid) TO authenticated, service_role;\n\nCREATE OR REPLACE FUNCTION public.recalculate_sales_invoice_payment_state(p_invoice_id uuid)\nRETURNS void\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_invoice record;\n  v_allocated numeric(18,2);\n  v_adjustment numeric(18,2);\n  v_paid numeric(18,2);\nBEGIN\n  SELECT id, total_amount\n  INTO v_invoice\n  FROM public.sales_invoices\n  WHERE id = p_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  v_allocated := public.get_invoice_allocation_amount(p_invoice_id, NULL);\n  v_adjustment := public.get_invoice_rounding_adjustment_amount(p_invoice_id);\n\n  v_paid := LEAST(\n    GREATEST(COALESCE(v_allocated, 0) + COALESCE(v_adjustment, 0), 0),\n    COALESCE(v_invoice.total_amount, 0)\n  );\n\n  UPDATE public.sales_invoices\n  SET\n    paid_amount = v_paid,\n    payment_status = CASE\n      WHEN v_paid <= 0 THEN 'pending'\n      WHEN v_paid >= v_invoice.total_amount THEN 'paid'\n      ELSE 'partial'\n    END\n  WHERE id = p_invoice_id;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.recalculate_sales_invoice_payment_state(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.recalculate_sales_invoice_payment_state(uuid) TO authenticated, service_role;\n\nCREATE OR REPLACE FUNCTION public.get_invoice_paid_amount(p_invoice_id uuid)\nRETURNS numeric\nLANGUAGE sql SECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\n  SELECT LEAST(\n    GREATEST(\n      public.get_invoice_allocation_amount(p_invoice_id, NULL)\n      + public.get_invoice_rounding_adjustment_amount(p_invoice_id),\n      0\n    ),\n    COALESCE((SELECT total_amount FROM public.sales_invoices WHERE id = p_invoice_id), 0)\n  );\n$$;\n\nREVOKE ALL ON FUNCTION public.get_invoice_paid_amount(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.get_invoice_paid_amount(uuid) TO authenticated, service_role;\n\nCREATE OR REPLACE FUNCTION public.get_invoice_with_balance(\n  invoice_uuid uuid,\n  exclude_voucher_uuid uuid DEFAULT NULL::uuid\n) RETURNS TABLE(\n  id uuid,\n  invoice_number text,\n  invoice_date date,\n  customer_id uuid,\n  total_amount numeric,\n  paid_amount numeric,\n  balance_amount numeric\n)\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nBEGIN\n  RETURN QUERY\n  SELECT\n    si.id,\n    si.invoice_number,\n    si.invoice_date,\n    si.customer_id,\n    si.total_amount,\n    LEAST(\n      GREATEST(\n        public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)\n        + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END,\n        0\n      ),\n      COALESCE(si.total_amount, 0)\n    ) AS paid_amount,\n    GREATEST(\n      si.total_amount - (\n        public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)\n        + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END\n      ),\n      0\n    ) AS balance_amount\n  FROM public.sales_invoices si\n  WHERE si.id = invoice_uuid;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.get_invoice_with_balance(uuid, uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.get_invoice_with_balance(uuid, uuid) TO authenticated, service_role;\n\nCREATE OR REPLACE FUNCTION public.get_invoices_with_balance(\n  customer_uuid uuid,\n  exclude_voucher_uuid uuid DEFAULT NULL::uuid\n) RETURNS TABLE(\n  id uuid,\n  invoice_number text,\n  invoice_date date,\n  total_amount numeric,\n  paid_amount numeric,\n  balance_amount numeric\n)\nLANGUAGE plpgsql SECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nBEGIN\n  RETURN QUERY\n  SELECT\n    si.id,\n    si.invoice_number,\n    si.invoice_date,\n    si.total_amount,\n    LEAST(\n      GREATEST(\n        public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)\n        + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END,\n        0\n      ),\n      COALESCE(si.total_amount, 0)\n    ) AS paid_amount,\n    GREATEST(\n      si.total_amount - (\n        public.get_invoice_allocation_amount(si.id, exclude_voucher_uuid)\n        + CASE WHEN exclude_voucher_uuid IS NULL THEN public.get_invoice_rounding_adjustment_amount(si.id) ELSE 0 END\n      ),\n      0\n    ) AS balance_amount\n  FROM public.sales_invoices si\n  WHERE si.customer_id = customer_uuid\n    AND COALESCE(si.is_draft, false) = false\n  ORDER BY si.invoice_date;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.get_invoices_with_balance(uuid, uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.get_invoices_with_balance(uuid, uuid) TO authenticated, service_role;"}	fix_sales_invoice_paid_amount_calculation	simplykool@gmail.com	\N	\N
20261024043020	{"-- Correct bank book-balance calculations without modifying accounting records.\n-- Exclude reversed journals and honor the configured opening-balance date.\n-- USD bank balances use only native USD amounts with valid USD/IDR metadata.\n\nCREATE OR REPLACE FUNCTION public.calculate_bank_account_book_balance(\n  p_bank_account_id uuid,\n  p_as_of_date date DEFAULT CURRENT_DATE\n)\nRETURNS numeric\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_opening numeric := 0;\n  v_coa_id uuid;\n  v_currency text;\n  v_opening_date date;\n  v_debits numeric := 0;\n  v_credits numeric := 0;\nBEGIN\n  SELECT COALESCE(opening_balance, 0),\n         coa_id,\n         upper(COALESCE(currency, 'IDR')),\n         COALESCE(opening_balance_date, DATE '1900-01-01')\n    INTO v_opening, v_coa_id, v_currency, v_opening_date\n    FROM public.bank_accounts\n   WHERE id = p_bank_account_id;\n\n  IF NOT FOUND THEN\n    RETURN NULL;\n  END IF;\n\n  IF p_as_of_date < v_opening_date THEN\n    RETURN 0;\n  END IF;\n\n  IF v_coa_id IS NULL THEN\n    RETURN v_opening;\n  END IF;\n\n  IF v_currency = 'USD' THEN\n    SELECT COALESCE(SUM(jel.transaction_debit), 0),\n           COALESCE(SUM(jel.transaction_credit), 0)\n      INTO v_debits, v_credits\n      FROM public.journal_entry_lines jel\n      JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n     WHERE jel.account_id = v_coa_id\n       AND je.is_posted = true\n       AND NOT COALESCE(je.is_reversed, false)\n       AND je.entry_date >= v_opening_date\n       AND je.entry_date <= p_as_of_date\n       AND jel.transaction_currency = 'USD'\n       AND jel.functional_currency = 'IDR'\n       AND COALESCE(jel.exchange_rate, 0) > 0;\n  ELSE\n    SELECT COALESCE(SUM(jel.debit), 0),\n           COALESCE(SUM(jel.credit), 0)\n      INTO v_debits, v_credits\n      FROM public.journal_entry_lines jel\n      JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n     WHERE jel.account_id = v_coa_id\n       AND je.is_posted = true\n       AND NOT COALESCE(je.is_reversed, false)\n       AND je.entry_date >= v_opening_date\n       AND je.entry_date <= p_as_of_date;\n  END IF;\n\n  RETURN ROUND(v_opening + v_debits - v_credits, 2);\nEND;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.get_bank_account_balances(\n  p_as_of_date date DEFAULT CURRENT_DATE\n)\nRETURNS TABLE (\n  bank_account_id uuid,\n  account_name text,\n  bank_name text,\n  account_number text,\n  currency text,\n  coa_id uuid,\n  coa_code text,\n  opening_balance numeric,\n  opening_balance_date date,\n  total_debits numeric,\n  total_credits numeric,\n  book_balance numeric,\n  statement_balance numeric,\n  as_of_date date\n)\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nBEGIN\n  RETURN QUERY\n  WITH stmt_aggregates AS (\n    SELECT bsl.bank_account_id,\n           COALESCE(SUM(bsl.debit_amount), 0) AS stmt_debits,\n           COALESCE(SUM(bsl.credit_amount), 0) AS stmt_credits\n      FROM public.bank_statement_lines bsl\n      JOIN public.bank_accounts ba ON ba.id = bsl.bank_account_id\n     WHERE bsl.transaction_date <= p_as_of_date\n       AND bsl.transaction_date >= COALESCE(ba.opening_balance_date, DATE '1900-01-01')\n     GROUP BY bsl.bank_account_id\n  ),\n  latest_stmt AS (\n    SELECT DISTINCT ON (bsl.bank_account_id)\n           bsl.bank_account_id,\n           COALESCE(NULLIF(bsl.statement_balance, 0), NULLIF(bsl.running_balance, 0)) AS last_stmt_bal\n      FROM public.bank_statement_lines bsl\n      JOIN public.bank_accounts ba ON ba.id = bsl.bank_account_id\n     WHERE bsl.transaction_date <= p_as_of_date\n       AND bsl.transaction_date >= COALESCE(ba.opening_balance_date, DATE '1900-01-01')\n       AND (COALESCE(bsl.statement_balance, 0) <> 0 OR COALESCE(bsl.running_balance, 0) <> 0)\n     ORDER BY bsl.bank_account_id, bsl.transaction_date DESC, bsl.id DESC\n  )\n  SELECT ba.id AS bank_account_id,\n         ba.account_name::text,\n         ba.bank_name::text,\n         ba.account_number::text,\n         ba.currency::text,\n         ba.coa_id,\n         coa.code::text AS coa_code,\n         COALESCE(ba.opening_balance, 0) AS opening_balance,\n         ba.opening_balance_date,\n         COALESCE((\n           SELECT SUM(CASE WHEN upper(ba.currency) = 'USD' THEN jel.transaction_debit ELSE jel.debit END)\n             FROM public.journal_entry_lines jel\n             JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n            WHERE jel.account_id = ba.coa_id\n              AND je.is_posted = true\n              AND NOT COALESCE(je.is_reversed, false)\n              AND je.entry_date >= COALESCE(ba.opening_balance_date, DATE '1900-01-01')\n              AND je.entry_date <= p_as_of_date\n              AND (upper(ba.currency) <> 'USD' OR (\n                jel.transaction_currency = 'USD'\n                AND jel.functional_currency = 'IDR'\n                AND COALESCE(jel.exchange_rate, 0) > 0\n              ))\n         ), 0) AS total_debits,\n         COALESCE((\n           SELECT SUM(CASE WHEN upper(ba.currency) = 'USD' THEN jel.transaction_credit ELSE jel.credit END)\n             FROM public.journal_entry_lines jel\n             JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n            WHERE jel.account_id = ba.coa_id\n              AND je.is_posted = true\n              AND NOT COALESCE(je.is_reversed, false)\n              AND je.entry_date >= COALESCE(ba.opening_balance_date, DATE '1900-01-01')\n              AND je.entry_date <= p_as_of_date\n              AND (upper(ba.currency) <> 'USD' OR (\n                jel.transaction_currency = 'USD'\n                AND jel.functional_currency = 'IDR'\n                AND COALESCE(jel.exchange_rate, 0) > 0\n              ))\n         ), 0) AS total_credits,\n         public.calculate_bank_account_book_balance(ba.id, p_as_of_date) AS book_balance,\n         COALESCE(\n           ls.last_stmt_bal,\n           ROUND(COALESCE(ba.opening_balance, 0) + COALESCE(sa.stmt_credits, 0) - COALESCE(sa.stmt_debits, 0), 2)\n         ) AS statement_balance,\n         p_as_of_date AS as_of_date\n    FROM public.bank_accounts ba\n    LEFT JOIN public.chart_of_accounts coa ON coa.id = ba.coa_id\n    LEFT JOIN stmt_aggregates sa ON sa.bank_account_id = ba.id\n    LEFT JOIN latest_stmt ls ON ls.bank_account_id = ba.id\n   WHERE ba.is_active = true;\nEND;\n$function$;"}	fix_bank_account_book_balance_reversed_entries	simplykool@gmail.com	\N	\N
20261024104751	{"-- Hotfix: remove the legacy 4-argument wrapper that makes PostgREST RPC resolution\n-- ambiguous with the 5-argument overload whose final two parameters have defaults.\nDROP FUNCTION IF EXISTS public.link_bank_statement_line(uuid, text, uuid, text);\nNOTIFY pgrst, 'reload schema';"}	fix_bank_statement_link_rpc_ambiguity	simplykool@gmail.com	\N	\N
20261027171021	{"-- ==============================================================================\n-- Sales Order -> Delivery Challan -> Sales Invoice Lifecycle Rectification\n-- ==============================================================================\n-- 1. Updates DC reversal triggers (trg_dc_reverse_product_reservation_v2 and\n--    trg_dc_reverse_inventory_v1) to allow reversing an approved Delivery Challan\n--    when its linked invoice has been cancelled.\n-- 2. Updates admin_edit_approved_delivery_challan to ignore cancelled invoices.\n-- 3. Updates dc_item_invoice_status view to ignore cancelled invoices.\n-- 4. Updates dc_invoicing_summary view to ignore cancelled invoices and provide\n--    both linked_invoices and linked_invoice_numbers aliases.\n-- 5. Updates so_delivery_invoice_status view to ignore cancelled invoices in\n--    invoiced_qty and invoice_count.\n-- 6. Updates fn_recompute_so_status to ignore cancelled invoices.\n-- ==============================================================================\n\n-- 1. Update trg_dc_reverse_product_reservation_v2\nCREATE OR REPLACE FUNCTION public.trg_dc_reverse_product_reservation_v2()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  r record;\nBEGIN\n  IF OLD.approval_status = 'approved' AND NEW.approval_status IN ('rejected', 'cancelled') THEN\n    -- Only block DC reversal if there is an active (uncancelled) invoice item referencing it\n    IF EXISTS (\n      SELECT 1\n      FROM public.sales_invoice_items sii\n      JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n      JOIN public.sales_invoices si ON si.id = sii.invoice_id\n      WHERE dci.challan_id = NEW.id\n        AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n    ) THEN\n      RAISE EXCEPTION 'Approved Delivery Challan already invoiced; reverse invoice first';\n    END IF;\n\n    -- Reverse consumed allocations and restore inventory\n    FOR r IN\n      SELECT dci.*, a.id AS allocation_id\n      FROM public.delivery_challan_items dci\n      JOIN public.dc_batch_allocations a ON a.delivery_challan_item_id = dci.id AND a.status = 'consumed'\n      WHERE dci.challan_id = NEW.id\n      ORDER BY dci.id\n      FOR UPDATE OF a\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text('inventory-v2:dc-reversal:' || NEW.id || ':' || r.id),\n        r.product_id,\n        r.batch_id,\n        'adjustment',\n        r.quantity,\n        CURRENT_DATE,\n        NEW.challan_number,\n        'delivery_challan_reversal',\n        NEW.id,\n        'Reversal of product-reservation DC batch allocation',\n        COALESCE(NEW.rejected_by, auth.uid()),\n        NULL,\n        NULL\n      );\n      UPDATE public.dc_batch_allocations\n      SET status = 'reversed',\n          reversed_at = now(),\n          reversal_reason = NEW.approval_status\n      WHERE id = r.allocation_id;\n    END LOOP;\n\n    -- Fallback for legacy DC items without dc_batch_allocations\n    FOR r IN\n      SELECT dci.*\n      FROM public.delivery_challan_items dci\n      WHERE dci.challan_id = NEW.id\n        AND NOT EXISTS (\n          SELECT 1 FROM public.dc_batch_allocations a\n          WHERE a.delivery_challan_item_id = dci.id\n        )\n      ORDER BY dci.id\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text('inventory-v1:dc-reversal:' || NEW.id || ':' || r.id || ':' || NEW.approval_status),\n        r.product_id,\n        r.batch_id,\n        'adjustment',\n        r.quantity,\n        CURRENT_DATE,\n        NEW.challan_number,\n        'delivery_challan_reversal',\n        NEW.id,\n        'Canonical reversal of DC ' || NEW.challan_number || ' (' || NEW.approval_status || ')',\n        COALESCE(NEW.rejected_by, auth.uid()),\n        NULL,\n        NULL\n      );\n    END LOOP;\n\n    IF NEW.sales_order_id IS NOT NULL THEN\n      PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);\n      FOR r IN\n        SELECT DISTINCT sales_order_item_id\n        FROM public.delivery_challan_items\n        WHERE challan_id = NEW.id\n          AND sales_order_item_id IS NOT NULL\n      LOOP\n        PERFORM public.reconcile_so_product_reservation_v2(r.sales_order_item_id, 'DC reversal');\n      END LOOP;\n      PERFORM public.fn_recompute_so_status(NEW.sales_order_id);\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 2. Update trg_dc_reverse_inventory_v1\nCREATE OR REPLACE FUNCTION public.trg_dc_reverse_inventory_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_item record;\nBEGIN\n  IF OLD.approval_status = 'approved'\n     AND NEW.approval_status IN ('rejected', 'cancelled') THEN\n    IF EXISTS (\n      SELECT 1\n      FROM public.sales_invoice_items sii\n      JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n      JOIN public.sales_invoices si ON si.id = sii.invoice_id\n      WHERE dci.challan_id = NEW.id\n        AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n    ) THEN\n      RAISE EXCEPTION 'Approved Delivery Challan already invoiced; reverse the invoice before cancelling';\n    END IF;\n\n    FOR v_item IN\n      SELECT *\n      FROM public.delivery_challan_items\n      WHERE challan_id = NEW.id\n      ORDER BY id\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text(\n          'inventory-v1:dc-reversal:' || NEW.id || ':' || v_item.id || ':' ||\n          NEW.approval_status\n        ),\n        v_item.product_id,\n        v_item.batch_id,\n        'adjustment',\n        v_item.quantity,\n        CURRENT_DATE,\n        NEW.challan_number,\n        'delivery_challan_reversal',\n        NEW.id,\n        'Canonical reversal of DC ' || NEW.challan_number || ' (' || NEW.approval_status || ')',\n        COALESCE(NEW.rejected_by, NEW.approved_by, auth.uid()),\n        NULL,\n        NULL\n      );\n    END LOOP;\n\n    IF NEW.sales_order_id IS NOT NULL THEN\n      PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);\n      PERFORM public.fn_reserve_stock_for_so_v2(NEW.sales_order_id);\n      PERFORM public.fn_recompute_so_status(NEW.sales_order_id);\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 3. Update admin_edit_approved_delivery_challan\nCREATE OR REPLACE FUNCTION public.admin_edit_approved_delivery_challan(\n  p_challan_id uuid,\n  p_new_items jsonb,\n  p_operation_id uuid DEFAULT gen_random_uuid()\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_challan public.delivery_challans%ROWTYPE;\n  v_old_item record;\n  v_item jsonb;\n  v_item_id uuid;\n  v_product_id uuid;\n  v_batch_id uuid;\n  v_quantity numeric;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin']) THEN\n    RAISE EXCEPTION 'Only admin can edit an approved Delivery Challan';\n  END IF;\n  IF p_operation_id IS NULL THEN\n    RAISE EXCEPTION 'operation_id is required';\n  END IF;\n\n  SELECT *\n  INTO v_challan\n  FROM public.delivery_challans\n  WHERE id = p_challan_id\n  FOR UPDATE;\n\n  IF NOT FOUND OR v_challan.approval_status <> 'approved' THEN\n    RAISE EXCEPTION 'Approved Delivery Challan not found';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM public.inventory_transactions\n    WHERE reference_type = 'delivery_challan'\n      AND reference_id = p_challan_id\n      AND COALESCE(metadata->>'canonical_engine_version', '') <> '1.0'\n  ) THEN\n    RAISE EXCEPTION 'Historical DC movement is ambiguous; manual review is required';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM public.sales_invoice_items sii\n    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    WHERE dci.challan_id = p_challan_id\n      AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n  ) THEN\n    RAISE EXCEPTION 'Approved Delivery Challan already invoiced; reverse the invoice before editing';\n  END IF;\n\n  FOR v_old_item IN\n    SELECT *\n    FROM public.delivery_challan_items\n    WHERE challan_id = p_challan_id\n    ORDER BY id\n  LOOP\n    PERFORM public.post_inventory_movement(\n      public.uuid_from_text(\n        'inventory-v1:dc-edit-reverse:' || p_operation_id || ':' ||\n        v_old_item.id\n      ),\n      v_old_item.product_id,\n      v_old_item.batch_id,\n      'adjustment',\n      v_old_item.quantity,\n      CURRENT_DATE,\n      v_challan.challan_number,\n      'delivery_challan_edit_reversal',\n      p_challan_id,\n      'Canonical reversal before approved DC edit',\n      auth.uid(),\n      NULL,\n      NULL\n    );\n  END LOOP;\n\n  DELETE FROM public.delivery_challan_items\n  WHERE challan_id = p_challan_id;\n\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_new_items)\n  LOOP\n    v_item_id := COALESCE(\n      NULLIF(v_item->>'id', '')::uuid,\n      gen_random_uuid()\n    );\n    v_product_id := (v_item->>'product_id')::uuid;\n    v_batch_id := (v_item->>'batch_id')::uuid;\n    v_quantity := (v_item->>'quantity')::numeric;\n\n    IF v_quantity <= 0 THEN\n      RAISE EXCEPTION 'Delivery Challan item quantity must be greater than zero';\n    END IF;\n\n    INSERT INTO public.delivery_challan_items (\n      id,\n      challan_id,\n      product_id,\n      batch_id,\n      sales_order_item_id,\n      quantity,\n      pack_size,\n      pack_type,\n      number_of_packs\n    ) VALUES (\n      v_item_id,\n      p_challan_id,\n      v_product_id,\n      v_batch_id,\n      NULLIF(v_item->>'sales_order_item_id', '')::uuid,\n      v_quantity,\n      NULLIF(v_item->>'pack_size', ''),\n      NULLIF(v_item->>'pack_type', ''),\n      NULLIF(v_item->>'number_of_packs', '')::integer\n    );\n\n    PERFORM public.post_inventory_movement(\n      public.uuid_from_text(\n        'inventory-v1:dc-edit-apply:' || p_operation_id || ':' || v_item_id\n      ),\n      v_product_id,\n      v_batch_id,\n      'sale',\n      v_quantity,\n      CURRENT_DATE,\n      v_challan.challan_number,\n      'delivery_challan',\n      p_challan_id,\n      'Canonical delivery challan edit application',\n      auth.uid(),\n      NULL,\n      NULL\n    );\n  END LOOP;\n\n  IF v_challan.sales_order_id IS NOT NULL THEN\n    PERFORM public.fn_recompute_so_delivered(v_challan.sales_order_id);\n    PERFORM public.fn_reserve_stock_for_so_v2(v_challan.sales_order_id);\n    PERFORM public.fn_recompute_so_status(v_challan.sales_order_id);\n  END IF;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'challan_id', p_challan_id,\n    'operation_id', p_operation_id\n  );\nEND;\n$$;\n\n-- 4. Update dc_item_invoice_status view\nCREATE OR REPLACE VIEW public.dc_item_invoice_status WITH (security_invoker = true) AS\n SELECT dci.id AS dc_item_id,\n    dci.challan_id,\n    dc.challan_number,\n    dc.challan_date,\n    dc.customer_id,\n    c.company_name AS customer_name,\n    dci.product_id,\n    p.product_name,\n    dci.batch_id,\n    b.batch_number,\n    dci.quantity AS original_quantity,\n    p.unit,\n    dci.pack_size,\n    dci.pack_type,\n    dci.number_of_packs,\n    COALESCE(sum(sii.quantity), 0::numeric) AS invoiced_quantity,\n    (dci.quantity - COALESCE(sum(sii.quantity), 0::numeric)) AS remaining_quantity,\n    CASE\n        WHEN (COALESCE(sum(sii.quantity), 0::numeric) = 0::numeric) THEN 'not_invoiced'::text\n        WHEN (COALESCE(sum(sii.quantity), 0::numeric) >= dci.quantity) THEN 'fully_invoiced'::text\n        ELSE 'partially_invoiced'::text\n    END AS status,\n    array_agg(DISTINCT si.invoice_number ORDER BY si.invoice_number) FILTER (WHERE si.invoice_number IS NOT NULL) AS invoice_numbers,\n    count(DISTINCT sii.invoice_id) AS invoice_count\n   FROM public.delivery_challan_items dci\n     JOIN public.delivery_challans dc ON dci.challan_id = dc.id\n     LEFT JOIN public.customers c ON dc.customer_id = c.id\n     LEFT JOIN public.products p ON dci.product_id = p.id\n     LEFT JOIN public.batches b ON dci.batch_id = b.id\n     LEFT JOIN (\n       public.sales_invoice_items sii\n       JOIN public.sales_invoices si ON si.id = sii.invoice_id\n         AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n     ) ON dci.id = sii.delivery_challan_item_id\n  GROUP BY dci.id, dci.challan_id, dc.challan_number, dc.challan_date, dc.customer_id, c.company_name, dci.product_id, p.product_name, p.unit, dci.batch_id, b.batch_number, dci.quantity, dci.pack_size, dci.pack_type, dci.number_of_packs;\n\nGRANT SELECT ON public.dc_item_invoice_status TO authenticated;\n\n-- 5. Update dc_invoicing_summary view\nCREATE OR REPLACE VIEW public.dc_invoicing_summary WITH (security_invoker = true) AS\n SELECT dc.id AS challan_id,\n    dc.challan_number,\n    dc.customer_id,\n    dc.challan_date,\n    dc.approval_status,\n    count(DISTINCT dci.id) AS total_items,\n    count(DISTINCT\n        CASE\n            WHEN sii.id IS NULL THEN dci.id\n            ELSE NULL::uuid\n        END) AS not_invoiced_items,\n    count(DISTINCT\n        CASE\n            WHEN sii.id IS NOT NULL THEN dci.id\n            ELSE NULL::uuid\n        END) AS invoiced_items,\n    COALESCE(sum(dci.quantity), 0::numeric) AS total_quantity,\n    COALESCE(sum(\n        CASE\n            WHEN sii.id IS NULL THEN dci.quantity\n            ELSE 0::numeric\n        END), 0::numeric) AS total_remaining_quantity,\n    CASE\n        WHEN count(DISTINCT sii.id) = 0 THEN 'not_invoiced'::text\n        WHEN count(DISTINCT sii.id) < count(DISTINCT dci.id) THEN 'partially_invoiced'::text\n        ELSE 'fully_invoiced'::text\n    END AS dc_status,\n    COALESCE(array_agg(DISTINCT si.invoice_number) FILTER (WHERE si.invoice_number IS NOT NULL), ARRAY[]::text[]) AS linked_invoices,\n    COALESCE(array_agg(DISTINCT si.invoice_number) FILTER (WHERE si.invoice_number IS NOT NULL), ARRAY[]::text[]) AS linked_invoice_numbers\n   FROM public.delivery_challans dc\n     LEFT JOIN public.delivery_challan_items dci ON dc.id = dci.challan_id\n     LEFT JOIN (\n       public.sales_invoice_items sii\n       JOIN public.sales_invoices si ON si.id = sii.invoice_id\n         AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n     ) ON sii.delivery_challan_item_id = dci.id\n  WHERE dc.approval_status = 'approved'::public.dc_approval_status\n  GROUP BY dc.id, dc.challan_number, dc.customer_id, dc.challan_date, dc.approval_status;\n\nGRANT SELECT ON public.dc_invoicing_summary TO authenticated;\n\n-- 6. Update so_delivery_invoice_status view\nCREATE OR REPLACE VIEW public.so_delivery_invoice_status WITH (security_invoker = true) AS\n WITH ordered AS (\n   SELECT soi.sales_order_id AS so_id,\n          COALESCE(sum(soi.quantity), 0::numeric) AS ordered_qty\n   FROM public.sales_order_items soi\n   GROUP BY soi.sales_order_id\n ),\n approved_delivery AS (\n   SELECT dc.sales_order_id AS so_id,\n          COALESCE(sum(dci.quantity), 0::numeric) AS approved_delivered_qty,\n          count(DISTINCT dc.id) AS approved_dc_count\n   FROM public.delivery_challans dc\n     JOIN public.delivery_challan_items dci ON dci.challan_id = dc.id\n   WHERE dc.approval_status = 'approved'::public.dc_approval_status\n     AND dc.sales_order_id IS NOT NULL\n   GROUP BY dc.sales_order_id\n ),\n invoice_items_by_so AS (\n   SELECT DISTINCT sii.id AS invoice_item_id,\n          COALESCE(si.sales_order_id, dc.sales_order_id) AS so_id,\n          sii.quantity\n   FROM public.sales_invoice_items sii\n     JOIN public.sales_invoices si ON si.id = sii.invoice_id\n     LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n     LEFT JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n   WHERE COALESCE(si.is_draft, false) = false\n     AND si.invoice_number !~~* 'TEST-COGS-%'::text\n     AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n     AND COALESCE(si.sales_order_id, dc.sales_order_id) IS NOT NULL\n ),\n invoiced AS (\n   SELECT i_1.so_id,\n          COALESCE(sum(i_1.quantity), 0::numeric) AS invoiced_qty,\n          count(DISTINCT i_1.invoice_item_id) AS invoice_count\n   FROM invoice_items_by_so i_1\n   GROUP BY i_1.so_id\n )\n SELECT so.id AS so_id,\n    so.so_number,\n    so.customer_id,\n    so.status AS so_status,\n    CASE\n        WHEN (COALESCE(ad.approved_delivered_qty, 0::numeric) = 0::numeric) THEN 'pending'::text\n        WHEN (COALESCE(ad.approved_delivered_qty, 0::numeric) >= COALESCE(o.ordered_qty, 0::numeric) AND COALESCE(o.ordered_qty, 0::numeric) > 0::numeric) THEN 'completed'::text\n        ELSE 'partial'::text\n    END AS delivery_status,\n    CASE\n        WHEN (COALESCE(i.invoiced_qty, 0::numeric) = 0::numeric) THEN 'pending'::text\n        WHEN (COALESCE(i.invoiced_qty, 0::numeric) >= COALESCE(o.ordered_qty, 0::numeric) AND COALESCE(o.ordered_qty, 0::numeric) > 0::numeric) THEN 'completed'::text\n        ELSE 'partial'::text\n    END AS invoice_status,\n    CASE\n        WHEN (COALESCE(i.invoiced_qty, 0::numeric) > 0::numeric AND COALESCE(ad.approved_delivered_qty, 0::numeric) = 0::numeric) THEN 'invoice_done_delivery_pending'::text\n        ELSE NULL::text\n    END AS special_status,\n    COALESCE(ad.approved_dc_count, 0::bigint) AS approved_dc_count,\n    COALESCE(i.invoice_count, 0::bigint) AS invoice_count,\n    COALESCE(o.ordered_qty, 0::numeric) AS ordered_qty,\n    COALESCE(ad.approved_delivered_qty, 0::numeric) AS approved_delivered_qty,\n    COALESCE(i.invoiced_qty, 0::numeric) AS invoiced_qty\n   FROM public.sales_orders so\n     LEFT JOIN ordered o ON o.so_id = so.id\n     LEFT JOIN approved_delivery ad ON ad.so_id = so.id\n     LEFT JOIN invoiced i ON i.so_id = so.id;\n\nGRANT SELECT ON public.so_delivery_invoice_status TO authenticated;\n\n-- 7. Update fn_recompute_so_status\nCREATE OR REPLACE FUNCTION public.fn_recompute_so_status(p_so_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  v_ordered numeric := 0;\n  v_delivered numeric := 0;\n  v_invoiced numeric := 0;\nBEGIN\n  IF p_so_id IS NULL THEN\n    RETURN;\n  END IF;\n\n  WITH approved_by_product AS (\n    SELECT\n      dci.product_id,\n      COALESCE(SUM(dci.quantity), 0)::numeric AS delivered_qty\n    FROM public.delivery_challans dc\n    JOIN public.delivery_challan_items dci ON dci.challan_id = dc.id\n    WHERE dc.sales_order_id = p_so_id\n      AND dc.approval_status = 'approved'\n    GROUP BY dci.product_id\n  ),\n  ordered_items AS (\n    SELECT\n      soi.id,\n      soi.product_id,\n      soi.quantity,\n      COALESCE(abp.delivered_qty, 0) AS delivered_qty,\n      COALESCE(\n        SUM(soi.quantity) OVER (\n          PARTITION BY soi.product_id\n          ORDER BY soi.created_at, soi.id\n          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING\n        ),\n        0\n      ) AS prior_qty\n    FROM public.sales_order_items soi\n    LEFT JOIN approved_by_product abp ON abp.product_id = soi.product_id\n    WHERE soi.sales_order_id = p_so_id\n  ),\n  allocated AS (\n    SELECT\n      id,\n      CASE\n        WHEN delivered_qty - prior_qty <= 0 THEN 0\n        WHEN delivered_qty - prior_qty >= quantity THEN quantity\n        ELSE delivered_qty - prior_qty\n      END AS delivered_quantity\n    FROM ordered_items\n  )\n  UPDATE public.sales_order_items soi\n     SET delivered_quantity = allocated.delivered_quantity\n    FROM allocated\n   WHERE soi.id = allocated.id;\n\n  SELECT COALESCE(SUM(quantity), 0)\n    INTO v_ordered\n    FROM public.sales_order_items\n   WHERE sales_order_id = p_so_id;\n\n  SELECT COALESCE(SUM(dci.quantity), 0)\n    INTO v_delivered\n    FROM public.delivery_challans dc\n    JOIN public.delivery_challan_items dci ON dci.challan_id = dc.id\n   WHERE dc.sales_order_id = p_so_id\n     AND dc.approval_status = 'approved';\n\n  SELECT COALESCE(SUM(x.quantity), 0)\n    INTO v_invoiced\n    FROM (\n      SELECT DISTINCT\n        sii.id,\n        sii.quantity\n      FROM public.sales_invoice_items sii\n      JOIN public.sales_invoices si ON si.id = sii.invoice_id\n      LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n      LEFT JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n      WHERE COALESCE(si.is_draft, false) = false\n        AND si.invoice_number NOT ILIKE 'TEST-COGS-%'\n        AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n        AND COALESCE(si.sales_order_id, dc.sales_order_id) = p_so_id\n    ) x;\n\n  UPDATE public.sales_orders\n     SET status = CASE\n                    WHEN v_ordered > 0 AND v_delivered >= v_ordered AND v_invoiced >= v_ordered\n                      THEN 'closed'::public.sales_order_status\n                    WHEN v_ordered > 0 AND v_delivered >= v_ordered\n                      THEN 'delivered'::public.sales_order_status\n                    WHEN v_delivered > 0\n                      THEN 'partially_delivered'::public.sales_order_status\n                    ELSE status\n                  END,\n         updated_at = now()\n   WHERE id = p_so_id\n     AND status NOT IN ('closed', 'cancelled', 'rejected');\nEND;\n$$;\n"}	sales_dc_invoice_lifecycle_rectification	simplykool@gmail.com	\N	\N
20261027220000	{"-- ==============================================================================\n-- Atomic Sales Invoice Cancellation and GL Reversal Architecture\n-- ==============================================================================\n-- Ensures that when a sales invoice is cancelled:\n-- 1. General Ledger postings (commercial revenue, AR, tax, and COGS) are reversed\n--    using the established is_reversed = true double-entry pattern.\n-- 2. reversed_by_id is kept NULL (foreign key points to journal_entries.id).\n-- 3. The Delivery Challan and its physical inventory deduction remain intact\n--    (single-owner invariant: DC owns physical stock movements).\n-- 4. Delivery Challan items are released so the DC is unbilled for re-invoicing.\n-- 5. Cancellation is idempotent and protected against partial failure.\n-- ==============================================================================\n\n-- 1. Update trg_sales_invoice_item_inventory to support invoice cancellation unlinking\nCREATE OR REPLACE FUNCTION public.trg_sales_invoice_item_inventory()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_dc_item public.delivery_challan_items%ROWTYPE;\n  v_dc_status text;\n  v_invoiced_quantity numeric;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n\n  -- Allow unlinking delivery_challan_item_id during controlled invoice cancellation\n  IF current_setting('app.sales_invoice_cancel', true) = 'true' THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.delivery_challan_item_id IS NULL THEN\n    -- If invoice has been cancelled or is being cancelled, allow null link\n    IF EXISTS (\n      SELECT 1 FROM public.sales_invoices si\n      WHERE si.id = NEW.invoice_id\n        AND (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n    ) THEN\n      RETURN NEW;\n    END IF;\n\n    RAISE EXCEPTION 'Sales Invoice item must reference an approved Delivery Challan item';\n  END IF;\n\n  SELECT dci.*\n  INTO v_dc_item\n  FROM public.delivery_challan_items dci\n  WHERE dci.id = NEW.delivery_challan_item_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Invoice item references a missing Delivery Challan item';\n  END IF;\n\n  SELECT dc.approval_status::text\n  INTO v_dc_status\n  FROM public.delivery_challans dc\n  WHERE dc.id = v_dc_item.challan_id;\n\n  IF NOT FOUND OR v_dc_status <> 'approved' THEN\n    RAISE EXCEPTION 'Sales Invoice item references a non-approved Delivery Challan item';\n  END IF;\n\n  IF NEW.product_id IS DISTINCT FROM v_dc_item.product_id\n     OR NEW.batch_id IS DISTINCT FROM v_dc_item.batch_id THEN\n    RAISE EXCEPTION 'Sales Invoice product/batch must match its Delivery Challan item';\n  END IF;\n\n  SELECT COALESCE(SUM(sii.quantity), 0)\n  INTO v_invoiced_quantity\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  WHERE sii.delivery_challan_item_id = NEW.delivery_challan_item_id\n    AND sii.id IS DISTINCT FROM NEW.id\n    AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%');\n\n  IF v_invoiced_quantity + NEW.quantity > v_dc_item.quantity THEN\n    RAISE EXCEPTION 'Sales Invoice quantity exceeds approved Delivery Challan quantity';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 2. Update dc_invoicing_summary to exclude cancelled invoices\nDROP VIEW IF EXISTS public.dc_invoicing_summary CASCADE;\nCREATE OR REPLACE VIEW public.dc_invoicing_summary WITH (security_invoker = true) AS\n SELECT dc.id AS challan_id,\n    dc.challan_number,\n    dc.customer_id,\n    dc.challan_date,\n    dc.approval_status,\n    count(DISTINCT dci.id) AS total_items,\n    count(DISTINCT\n        CASE\n            WHEN sii.id IS NULL THEN dci.id\n            ELSE NULL::uuid\n        END) AS not_invoiced_items,\n    count(DISTINCT\n        CASE\n            WHEN sii.id IS NOT NULL THEN dci.id\n            ELSE NULL::uuid\n        END) AS invoiced_items,\n    COALESCE(sum(dci.quantity), 0::numeric) AS total_quantity,\n    COALESCE(sum(\n        CASE\n            WHEN sii.id IS NULL THEN dci.quantity\n            ELSE 0::numeric\n        END), 0::numeric) AS total_remaining_quantity,\n    CASE\n        WHEN count(DISTINCT sii.id) = 0 THEN 'not_invoiced'::text\n        WHEN count(DISTINCT sii.id) < count(DISTINCT dci.id) THEN 'partially_invoiced'::text\n        ELSE 'fully_invoiced'::text\n    END AS dc_status,\n    COALESCE(array_agg(DISTINCT si.invoice_number) FILTER (WHERE si.invoice_number IS NOT NULL), ARRAY[]::text[]) AS linked_invoices\n   FROM public.delivery_challans dc\n     LEFT JOIN public.delivery_challan_items dci ON dc.id = dci.challan_id\n     LEFT JOIN (\n       public.sales_invoice_items sii\n       JOIN public.sales_invoices si ON si.id = sii.invoice_id\n         AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n     ) ON sii.delivery_challan_item_id = dci.id\n  WHERE dc.approval_status = 'approved'::public.dc_approval_status\n  GROUP BY dc.id, dc.challan_number, dc.customer_id, dc.challan_date, dc.approval_status;\n\nCOMMENT ON VIEW public.dc_invoicing_summary IS 'Summary of delivery challans with invoicing status and remaining quantities for approved DCs only, excluding cancelled invoices';\n\n-- 3. Transactional cancellation RPC\nCREATE OR REPLACE FUNCTION public.cancel_sales_invoice(\n  p_invoice_id uuid,\n  p_reason text DEFAULT NULL,\n  p_actor uuid DEFAULT NULL\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_caller uuid := COALESCE(auth.uid(), p_actor);\n  v_role text;\n  v_inv record;\n  v_alloc_paid numeric := 0;\n  v_adj_paid numeric := 0;\n  v_reason text;\n  v_rev_count int := 0;\n  v_cogs_count int := 0;\n  v_updated_notes text;\n  v_je record;\n  v_period_id uuid;\n  v_rev_entry text;\n  v_reversal_id uuid;\nBEGIN\n  -- Permission check: only admin and accounts can cancel financially posted invoices\n  IF v_caller IS NOT NULL THEN\n    SELECT role INTO v_role FROM public.user_profiles WHERE id = v_caller;\n    IF v_role NOT IN ('admin', 'accounts') THEN\n      RAISE EXCEPTION 'Permission denied: role % cannot cancel sales invoices', v_role;\n    END IF;\n  END IF;\n\n  -- Lock invoice row\n  SELECT * INTO v_inv\n  FROM public.sales_invoices\n  WHERE id = p_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales invoice % not found', p_invoice_id;\n  END IF;\n\n  -- Payment guard: check allocated receipts and adjustments\n  SELECT COALESCE(SUM(allocated_amount), 0) INTO v_alloc_paid\n  FROM public.voucher_allocations\n  WHERE sales_invoice_id = p_invoice_id AND voucher_type = 'receipt';\n\n  SELECT COALESCE(SUM(adjustment_amount), 0) INTO v_adj_paid\n  FROM public.invoice_rounding_adjustments\n  WHERE sales_invoice_id = p_invoice_id;\n\n  IF (COALESCE(v_inv.paid_amount, 0) > 0.01 OR v_alloc_paid > 0.01 OR v_adj_paid > 0.01) THEN\n    RAISE EXCEPTION 'Cannot cancel invoice %: payments of Rp % are allocated. Unallocate payments first.',\n      v_inv.invoice_number, (COALESCE(v_inv.paid_amount, 0) + v_alloc_paid + v_adj_paid);\n  END IF;\n\n  v_reason := COALESCE(p_reason, '[CANCELLED on ' || CURRENT_DATE::text || ' by ' || COALESCE(v_role, 'Admin') || ']');\n\n  -- 1. Reverse Revenue Journal Entries (Commercial AR, Sales, VAT Output, Stamp Duty)\n  FOR v_je IN\n    SELECT *\n    FROM public.journal_entries\n    WHERE is_posted = true\n      AND COALESCE(is_reversed, false) = false\n      AND (\n        id = v_inv.journal_entry_id\n        OR (reference_id = p_invoice_id AND source_module IN ('sales_invoice', 'sales', 'sales_invoices'))\n        OR (reference_number = v_inv.invoice_number AND source_module IN ('sales_invoice', 'sales', 'sales_invoices'))\n      )\n    FOR UPDATE\n  LOOP\n    SELECT id INTO v_period_id\n    FROM public.accounting_periods\n    WHERE CURRENT_DATE BETWEEN start_date AND end_date\n      AND status = 'open'\n    LIMIT 1;\n    IF v_period_id IS NULL THEN v_period_id := v_je.period_id; END IF;\n\n    v_rev_entry := public.next_journal_entry_number();\n\n    INSERT INTO public.journal_entries (\n      entry_number, entry_date, period_id, source_module, reference_id,\n      reference_number, description, total_debit, total_credit,\n      is_posted, is_reversed, posted_by, posted_at, created_by, created_at,\n      transaction_category, transaction_currency, functional_currency, exchange_rate, amounts_are_functional\n    ) VALUES (\n      v_rev_entry, CURRENT_DATE, v_period_id, v_je.source_module || '_cancellation', p_invoice_id,\n      'CANCEL-' || v_inv.invoice_number,\n      'Cancellation reversal of ' || v_je.entry_number || ': ' || v_reason,\n      v_je.total_credit, v_je.total_debit,\n      true, true, v_caller, now(), v_caller, now(),\n      v_je.transaction_category, v_je.transaction_currency, v_je.functional_currency, v_je.exchange_rate, v_je.amounts_are_functional\n    ) RETURNING id INTO v_reversal_id;\n\n    INSERT INTO public.journal_entry_lines (\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      tax_code_id, customer_id, supplier_id, batch_id, transaction_currency,\n      transaction_debit, transaction_credit, functional_currency, exchange_rate, sales_invoice_item_id\n    )\n    SELECT\n      v_reversal_id, line_number, account_id, 'CANCEL: ' || COALESCE(description, ''),\n      credit, debit, tax_code_id, customer_id, supplier_id, batch_id, transaction_currency,\n      transaction_credit, transaction_debit, functional_currency, exchange_rate, sales_invoice_item_id\n    FROM public.journal_entry_lines\n    WHERE journal_entry_id = v_je.id\n    ORDER BY line_number;\n\n    UPDATE public.journal_entries\n    SET is_reversed = true,\n        reversed_by_id = v_reversal_id,\n        description = v_reason || ' ' || COALESCE(description, '')\n    WHERE id = v_je.id;\n\n    v_rev_count := v_rev_count + 1;\n  END LOOP;\n\n  -- 2. Reverse COGS Journal Entries (COGS Dr 5100, Inventory Cr 1130)\n  FOR v_je IN\n    SELECT *\n    FROM public.journal_entries\n    WHERE is_posted = true\n      AND COALESCE(is_reversed, false) = false\n      AND source_module = 'sales_invoice_cogs'\n      AND (reference_id = p_invoice_id OR reference_number = v_inv.invoice_number)\n    FOR UPDATE\n  LOOP\n    SELECT id INTO v_period_id\n    FROM public.accounting_periods\n    WHERE CURRENT_DATE BETWEEN start_date AND end_date\n      AND status = 'open'\n    LIMIT 1;\n    IF v_period_id IS NULL THEN v_period_id := v_je.period_id; END IF;\n\n    v_rev_entry := public.next_journal_entry_number();\n\n    INSERT INTO public.journal_entries (\n      entry_number, entry_date, period_id, source_module, reference_id,\n      reference_number, description, total_debit, total_credit,\n      is_posted, is_reversed, posted_by, posted_at, created_by, created_at,\n      transaction_category, transaction_currency, functional_currency, exchange_rate, amounts_are_functional\n    ) VALUES (\n      v_rev_entry, CURRENT_DATE, v_period_id, 'sales_invoice_cogs_cancellation', p_invoice_id,\n      'CANCEL-' || v_inv.invoice_number || '-COGS',\n      'Cancellation reversal of COGS ' || v_je.entry_number || ': ' || v_reason,\n      v_je.total_credit, v_je.total_debit,\n      true, true, v_caller, now(), v_caller, now(),\n      v_je.transaction_category, v_je.transaction_currency, v_je.functional_currency, v_je.exchange_rate, v_je.amounts_are_functional\n    ) RETURNING id INTO v_reversal_id;\n\n    INSERT INTO public.journal_entry_lines (\n      journal_entry_id, line_number, account_id, description, debit, credit,\n      tax_code_id, customer_id, supplier_id, batch_id, transaction_currency,\n      transaction_debit, transaction_credit, functional_currency, exchange_rate, sales_invoice_item_id\n    )\n    SELECT\n      v_reversal_id, line_number, account_id, 'CANCEL: ' || COALESCE(description, ''),\n      credit, debit, tax_code_id, customer_id, supplier_id, batch_id, transaction_currency,\n      transaction_credit, transaction_debit, functional_currency, exchange_rate, sales_invoice_item_id\n    FROM public.journal_entry_lines\n    WHERE journal_entry_id = v_je.id\n    ORDER BY line_number;\n\n    UPDATE public.journal_entries\n    SET is_reversed = true,\n        reversed_by_id = v_reversal_id,\n        description = v_reason || ' ' || COALESCE(description, '') || ' COGS'\n    WHERE id = v_je.id;\n\n    v_cogs_count := v_cogs_count + 1;\n  END LOOP;\n\n  -- 3. Release Delivery Challan link while preserving invoice line items for viewing\n  PERFORM set_config('app.sales_invoice_cancel', 'true', true);\n  UPDATE public.sales_invoice_items\n  SET delivery_challan_item_id = NULL\n  WHERE invoice_id = p_invoice_id;\n  PERFORM set_config('app.sales_invoice_cancel', 'false', true);\n\n  -- 4. Update sales invoice header\n  v_updated_notes := CASE\n    WHEN v_inv.notes IS NULL OR v_inv.notes = '' THEN v_reason\n    WHEN v_inv.notes LIKE '[CANCELLED%' THEN v_inv.notes\n    ELSE v_reason || E'\\\\n' || v_inv.notes\n  END;\n\n  UPDATE public.sales_invoices\n  SET notes = v_updated_notes,\n      balance_amount = 0,\n      updated_at = now()\n  WHERE id = p_invoice_id;\n\n  -- 5. Cancel Faktur Pajak if exists\n  UPDATE public.faktur_pajak\n  SET status = 'cancelled',\n      notes = v_reason || ' Sales Invoice cancelled',\n      updated_at = now()\n  WHERE sales_invoice_id = p_invoice_id\n    AND status <> 'cancelled';\n\n  -- 6. Record audit log\n  INSERT INTO public.audit_logs (table_name, record_id, action_type, user_id, new_values)\n  VALUES (\n    'sales_invoices',\n    p_invoice_id,\n    'update',\n    v_caller,\n    jsonb_build_object(\n      '_action', 'INVOICE_CANCELLED',\n      'invoice_number', v_inv.invoice_number,\n      'reason', v_reason,\n      'revenue_journals_reversed', v_rev_count,\n      'cogs_journals_reversed', v_cogs_count\n    )\n  );\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'invoice_number', v_inv.invoice_number,\n    'revenue_journals_reversed', v_rev_count,\n    'cogs_journals_reversed', v_cogs_count\n  );\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.cancel_sales_invoice(uuid, text, uuid) TO authenticated;\n\n"}	atomic_sales_invoice_cancellation	\N	\N	\N
20261028000000	{"-- ==============================================================================\n-- Sales Order -> Delivery Challan -> Sales Invoice Lifecycle Rectification\n-- ==============================================================================\n-- 1. Updates DC reversal triggers (trg_dc_reverse_product_reservation_v2 and\n--    trg_dc_reverse_inventory_v1) to allow reversing an approved Delivery Challan\n--    when its linked invoice has been cancelled.\n-- 2. Updates admin_edit_approved_delivery_challan to ignore cancelled invoices.\n-- 3. Updates dc_item_invoice_status view to ignore cancelled invoices.\n-- 4. Updates dc_invoicing_summary view to ignore cancelled invoices and provide\n--    both linked_invoices and linked_invoice_numbers aliases.\n-- 5. Updates so_delivery_invoice_status view to ignore cancelled invoices in\n--    invoiced_qty and invoice_count.\n-- 6. Updates fn_recompute_so_status to ignore cancelled invoices.\n-- ==============================================================================\n\n-- 1. Update trg_dc_reverse_product_reservation_v2\nCREATE OR REPLACE FUNCTION public.trg_dc_reverse_product_reservation_v2()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  r record;\n  v_blocking_invoices text;\nBEGIN\n  IF OLD.approval_status = 'approved' AND NEW.approval_status IN ('rejected', 'cancelled') THEN\n    -- Only block DC reversal if there is an active (uncancelled) invoice item referencing it\n    SELECT string_agg(DISTINCT si.invoice_number, ', ')\n    INTO v_blocking_invoices\n    FROM public.sales_invoice_items sii\n    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    WHERE dci.challan_id = NEW.id\n      AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%');\n\n    IF v_blocking_invoices IS NOT NULL AND v_blocking_invoices <> '' THEN\n      RAISE EXCEPTION 'Approved Delivery Challan % already invoiced by active invoice(s) %; reverse or cancel the invoice(s) first',\n        COALESCE(NEW.challan_number, NEW.id::text), v_blocking_invoices;\n    END IF;\n\n    -- Reverse consumed allocations and restore inventory\n    FOR r IN\n      SELECT dci.*, a.id AS allocation_id\n      FROM public.delivery_challan_items dci\n      JOIN public.dc_batch_allocations a ON a.delivery_challan_item_id = dci.id AND a.status = 'consumed'\n      WHERE dci.challan_id = NEW.id\n      ORDER BY dci.id\n      FOR UPDATE OF a\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text('inventory-v2:dc-reversal:' || NEW.id || ':' || r.id),\n        r.product_id,\n        r.batch_id,\n        'adjustment',\n        r.quantity,\n        CURRENT_DATE,\n        NEW.challan_number,\n        'delivery_challan_reversal',\n        NEW.id,\n        'Reversal of product-reservation DC batch allocation',\n        COALESCE(NEW.rejected_by, auth.uid()),\n        NULL,\n        NULL\n      );\n      UPDATE public.dc_batch_allocations\n      SET status = 'reversed',\n          reversed_at = now(),\n          reversal_reason = NEW.approval_status\n      WHERE id = r.allocation_id;\n    END LOOP;\n\n    -- Fallback for legacy DC items without dc_batch_allocations\n    FOR r IN\n      SELECT dci.*\n      FROM public.delivery_challan_items dci\n      WHERE dci.challan_id = NEW.id\n        AND NOT EXISTS (\n          SELECT 1 FROM public.dc_batch_allocations a\n          WHERE a.delivery_challan_item_id = dci.id\n        )\n      ORDER BY dci.id\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text('inventory-v1:dc-reversal:' || NEW.id || ':' || r.id || ':' || NEW.approval_status),\n        r.product_id,\n        r.batch_id,\n        'adjustment',\n        r.quantity,\n        CURRENT_DATE,\n        NEW.challan_number,\n        'delivery_challan_reversal',\n        NEW.id,\n        'Canonical reversal of DC ' || NEW.challan_number || ' (' || NEW.approval_status || ')',\n        COALESCE(NEW.rejected_by, auth.uid()),\n        NULL,\n        NULL\n      );\n    END LOOP;\n\n    IF NEW.sales_order_id IS NOT NULL THEN\n      PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);\n      FOR r IN\n        SELECT DISTINCT sales_order_item_id\n        FROM public.delivery_challan_items\n        WHERE challan_id = NEW.id\n          AND sales_order_item_id IS NOT NULL\n      LOOP\n        PERFORM public.reconcile_so_product_reservation_v2(r.sales_order_item_id, 'DC reversal');\n      END LOOP;\n      PERFORM public.fn_recompute_so_status(NEW.sales_order_id);\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 2. Update trg_dc_reverse_inventory_v1\nCREATE OR REPLACE FUNCTION public.trg_dc_reverse_inventory_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_item record;\n  v_blocking_invoices text;\nBEGIN\n  IF OLD.approval_status = 'approved'\n     AND NEW.approval_status IN ('rejected', 'cancelled') THEN\n    SELECT string_agg(DISTINCT si.invoice_number, ', ')\n    INTO v_blocking_invoices\n    FROM public.sales_invoice_items sii\n    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    WHERE dci.challan_id = NEW.id\n      AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%');\n\n    IF v_blocking_invoices IS NOT NULL AND v_blocking_invoices <> '' THEN\n      RAISE EXCEPTION 'Approved Delivery Challan % already invoiced by active invoice(s) %; reverse or cancel the invoice(s) before cancelling',\n        COALESCE(NEW.challan_number, NEW.id::text), v_blocking_invoices;\n    END IF;\n\n    FOR v_item IN\n      SELECT *\n      FROM public.delivery_challan_items\n      WHERE challan_id = NEW.id\n      ORDER BY id\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text(\n          'inventory-v1:dc-reversal:' || NEW.id || ':' || v_item.id || ':' ||\n          NEW.approval_status\n        ),\n        v_item.product_id,\n        v_item.batch_id,\n        'adjustment',\n        v_item.quantity,\n        CURRENT_DATE,\n        NEW.challan_number,\n        'delivery_challan_reversal',\n        NEW.id,\n        'Canonical reversal of DC ' || NEW.challan_number || ' (' || NEW.approval_status || ')',\n        COALESCE(NEW.rejected_by, NEW.approved_by, auth.uid()),\n        NULL,\n        NULL\n      );\n    END LOOP;\n\n    IF NEW.sales_order_id IS NOT NULL THEN\n      PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);\n      PERFORM public.fn_reserve_stock_for_so_v2(NEW.sales_order_id);\n      PERFORM public.fn_recompute_so_status(NEW.sales_order_id);\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 3. Update admin_edit_approved_delivery_challan\nCREATE OR REPLACE FUNCTION public.admin_edit_approved_delivery_challan(\n  p_challan_id uuid,\n  p_new_items jsonb,\n  p_operation_id uuid DEFAULT gen_random_uuid()\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_challan public.delivery_challans%ROWTYPE;\n  v_old_item record;\n  v_item jsonb;\n  v_item_id uuid;\n  v_product_id uuid;\n  v_batch_id uuid;\n  v_quantity numeric;\n  v_blocking_invoices text;\nBEGIN\n  IF NOT public.inventory_v1_actor_allowed(ARRAY['admin']) THEN\n    RAISE EXCEPTION 'Only admin can edit an approved Delivery Challan';\n  END IF;\n  IF p_operation_id IS NULL THEN\n    RAISE EXCEPTION 'operation_id is required';\n  END IF;\n\n  SELECT *\n  INTO v_challan\n  FROM public.delivery_challans\n  WHERE id = p_challan_id\n  FOR UPDATE;\n\n  IF NOT FOUND OR v_challan.approval_status <> 'approved' THEN\n    RAISE EXCEPTION 'Approved Delivery Challan not found';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM public.inventory_transactions\n    WHERE reference_type = 'delivery_challan'\n      AND reference_id = p_challan_id\n      AND COALESCE(metadata->>'canonical_engine_version', '') <> '1.0'\n  ) THEN\n    RAISE EXCEPTION 'Historical DC movement is ambiguous; manual review is required';\n  END IF;\n\n  SELECT string_agg(DISTINCT si.invoice_number, ', ')\n  INTO v_blocking_invoices\n  FROM public.sales_invoice_items sii\n  JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  WHERE dci.challan_id = p_challan_id\n    AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%');\n\n  IF v_blocking_invoices IS NOT NULL AND v_blocking_invoices <> '' THEN\n    RAISE EXCEPTION 'Approved Delivery Challan % already invoiced by active invoice(s) %; reverse or cancel the invoice(s) before editing',\n      v_challan.challan_number, v_blocking_invoices;\n  END IF;\n\n  FOR v_old_item IN\n    SELECT *\n    FROM public.delivery_challan_items\n    WHERE challan_id = p_challan_id\n    ORDER BY id\n  LOOP\n    PERFORM public.post_inventory_movement(\n      public.uuid_from_text(\n        'inventory-v1:dc-edit-reverse:' || p_operation_id || ':' ||\n        v_old_item.id\n      ),\n      v_old_item.product_id,\n      v_old_item.batch_id,\n      'adjustment',\n      v_old_item.quantity,\n      CURRENT_DATE,\n      v_challan.challan_number,\n      'delivery_challan_edit_reversal',\n      p_challan_id,\n      'Canonical reversal before approved DC edit',\n      auth.uid(),\n      NULL,\n      NULL\n    );\n  END LOOP;\n\n  DELETE FROM public.delivery_challan_items\n  WHERE challan_id = p_challan_id;\n\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_new_items)\n  LOOP\n    v_item_id := COALESCE(\n      NULLIF(v_item->>'id', '')::uuid,\n      gen_random_uuid()\n    );\n    v_product_id := (v_item->>'product_id')::uuid;\n    v_batch_id := (v_item->>'batch_id')::uuid;\n    v_quantity := (v_item->>'quantity')::numeric;\n\n    IF v_quantity <= 0 THEN\n      RAISE EXCEPTION 'Delivery Challan item quantity must be greater than zero';\n    END IF;\n\n    INSERT INTO public.delivery_challan_items (\n      id,\n      challan_id,\n      product_id,\n      batch_id,\n      sales_order_item_id,\n      quantity,\n      pack_size,\n      pack_type,\n      number_of_packs\n    ) VALUES (\n      v_item_id,\n      p_challan_id,\n      v_product_id,\n      v_batch_id,\n      NULLIF(v_item->>'sales_order_item_id', '')::uuid,\n      v_quantity,\n      NULLIF(v_item->>'pack_size', ''),\n      NULLIF(v_item->>'pack_type', ''),\n      NULLIF(v_item->>'number_of_packs', '')::integer\n    );\n\n    PERFORM public.post_inventory_movement(\n      public.uuid_from_text(\n        'inventory-v1:dc-edit-apply:' || p_operation_id || ':' || v_item_id\n      ),\n      v_product_id,\n      v_batch_id,\n      'sale',\n      v_quantity,\n      CURRENT_DATE,\n      v_challan.challan_number,\n      'delivery_challan',\n      p_challan_id,\n      'Canonical delivery challan edit application',\n      auth.uid(),\n      NULL,\n      NULL\n    );\n  END LOOP;\n\n  IF v_challan.sales_order_id IS NOT NULL THEN\n    PERFORM public.fn_recompute_so_delivered(v_challan.sales_order_id);\n    PERFORM public.fn_reserve_stock_for_so_v2(v_challan.sales_order_id);\n    PERFORM public.fn_recompute_so_status(v_challan.sales_order_id);\n  END IF;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'challan_id', p_challan_id,\n    'operation_id', p_operation_id\n  );\nEND;\n$$;\n\n-- 4. Update dc_item_invoice_status view\nCREATE OR REPLACE VIEW public.dc_item_invoice_status WITH (security_invoker = true) AS\n SELECT dci.id AS dc_item_id,\n    dci.challan_id,\n    dc.challan_number,\n    dc.challan_date,\n    dc.customer_id,\n    c.company_name AS customer_name,\n    dci.product_id,\n    p.product_name,\n    dci.batch_id,\n    b.batch_number,\n    dci.quantity AS original_quantity,\n    p.unit,\n    dci.pack_size,\n    dci.pack_type,\n    dci.number_of_packs,\n    COALESCE(sum(sii.quantity), 0::numeric) AS invoiced_quantity,\n    (dci.quantity - COALESCE(sum(sii.quantity), 0::numeric)) AS remaining_quantity,\n    CASE\n        WHEN (COALESCE(sum(sii.quantity), 0::numeric) = 0::numeric) THEN 'not_invoiced'::text\n        WHEN (COALESCE(sum(sii.quantity), 0::numeric) >= dci.quantity) THEN 'fully_invoiced'::text\n        ELSE 'partially_invoiced'::text\n    END AS status,\n    array_agg(DISTINCT si.invoice_number ORDER BY si.invoice_number) FILTER (WHERE si.invoice_number IS NOT NULL) AS invoice_numbers,\n    count(DISTINCT sii.invoice_id) AS invoice_count\n   FROM public.delivery_challan_items dci\n     JOIN public.delivery_challans dc ON dci.challan_id = dc.id\n     LEFT JOIN public.customers c ON dc.customer_id = c.id\n     LEFT JOIN public.products p ON dci.product_id = p.id\n     LEFT JOIN public.batches b ON dci.batch_id = b.id\n     LEFT JOIN (\n       public.sales_invoice_items sii\n       JOIN public.sales_invoices si ON si.id = sii.invoice_id\n         AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n     ) ON dci.id = sii.delivery_challan_item_id\n  GROUP BY dci.id, dci.challan_id, dc.challan_number, dc.challan_date, dc.customer_id, c.company_name, dci.product_id, p.product_name, p.unit, dci.batch_id, b.batch_number, dci.quantity, dci.pack_size, dci.pack_type, dci.number_of_packs;\n\nGRANT SELECT ON public.dc_item_invoice_status TO authenticated;\n\n-- 5. Update dc_invoicing_summary view\nCREATE OR REPLACE VIEW public.dc_invoicing_summary WITH (security_invoker = true) AS\n SELECT dc.id AS challan_id,\n    dc.challan_number,\n    dc.customer_id,\n    dc.challan_date,\n    dc.approval_status,\n    count(DISTINCT dci.id) AS total_items,\n    count(DISTINCT\n        CASE\n            WHEN sii.id IS NULL THEN dci.id\n            ELSE NULL::uuid\n        END) AS not_invoiced_items,\n    count(DISTINCT\n        CASE\n            WHEN sii.id IS NOT NULL THEN dci.id\n            ELSE NULL::uuid\n        END) AS invoiced_items,\n    COALESCE(sum(dci.quantity), 0::numeric) AS total_quantity,\n    COALESCE(sum(\n        CASE\n            WHEN sii.id IS NULL THEN dci.quantity\n            ELSE 0::numeric\n        END), 0::numeric) AS total_remaining_quantity,\n    CASE\n        WHEN count(DISTINCT sii.id) = 0 THEN 'not_invoiced'::text\n        WHEN count(DISTINCT sii.id) < count(DISTINCT dci.id) THEN 'partially_invoiced'::text\n        ELSE 'fully_invoiced'::text\n    END AS dc_status,\n    COALESCE(array_agg(DISTINCT si.invoice_number) FILTER (WHERE si.invoice_number IS NOT NULL), ARRAY[]::text[]) AS linked_invoices,\n    COALESCE(array_agg(DISTINCT si.invoice_number) FILTER (WHERE si.invoice_number IS NOT NULL), ARRAY[]::text[]) AS linked_invoice_numbers\n   FROM public.delivery_challans dc\n     LEFT JOIN public.delivery_challan_items dci ON dc.id = dci.challan_id\n     LEFT JOIN (\n       public.sales_invoice_items sii\n       JOIN public.sales_invoices si ON si.id = sii.invoice_id\n         AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n     ) ON sii.delivery_challan_item_id = dci.id\n  WHERE dc.approval_status = 'approved'::public.dc_approval_status\n  GROUP BY dc.id, dc.challan_number, dc.customer_id, dc.challan_date, dc.approval_status;\n\nGRANT SELECT ON public.dc_invoicing_summary TO authenticated;\n\n-- 6. Update so_delivery_invoice_status view\nCREATE OR REPLACE VIEW public.so_delivery_invoice_status WITH (security_invoker = true) AS\n WITH ordered AS (\n   SELECT soi.sales_order_id AS so_id,\n          COALESCE(sum(soi.quantity), 0::numeric) AS ordered_qty\n   FROM public.sales_order_items soi\n   GROUP BY soi.sales_order_id\n ),\n approved_delivery AS (\n   SELECT dc.sales_order_id AS so_id,\n          COALESCE(sum(dci.quantity), 0::numeric) AS approved_delivered_qty,\n          count(DISTINCT dc.id) AS approved_dc_count\n   FROM public.delivery_challans dc\n     JOIN public.delivery_challan_items dci ON dci.challan_id = dc.id\n   WHERE dc.approval_status = 'approved'::public.dc_approval_status\n     AND dc.sales_order_id IS NOT NULL\n   GROUP BY dc.sales_order_id\n ),\n invoice_items_by_so AS (\n   SELECT DISTINCT sii.id AS invoice_item_id,\n          COALESCE(si.sales_order_id, dc.sales_order_id) AS so_id,\n          sii.quantity\n   FROM public.sales_invoice_items sii\n     JOIN public.sales_invoices si ON si.id = sii.invoice_id\n     LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n     LEFT JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n   WHERE COALESCE(si.is_draft, false) = false\n     AND si.invoice_number !~~* 'TEST-COGS-%'::text\n     AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n     AND COALESCE(si.sales_order_id, dc.sales_order_id) IS NOT NULL\n ),\n invoiced AS (\n   SELECT i_1.so_id,\n          COALESCE(sum(i_1.quantity), 0::numeric) AS invoiced_qty,\n          count(DISTINCT i_1.invoice_item_id) AS invoice_count\n   FROM invoice_items_by_so i_1\n   GROUP BY i_1.so_id\n )\n SELECT so.id AS so_id,\n    so.so_number,\n    so.customer_id,\n    so.status AS so_status,\n    CASE\n        WHEN (COALESCE(ad.approved_delivered_qty, 0::numeric) = 0::numeric) THEN 'pending'::text\n        WHEN (COALESCE(ad.approved_delivered_qty, 0::numeric) >= COALESCE(o.ordered_qty, 0::numeric) AND COALESCE(o.ordered_qty, 0::numeric) > 0::numeric) THEN 'completed'::text\n        ELSE 'partial'::text\n    END AS delivery_status,\n    CASE\n        WHEN (COALESCE(i.invoiced_qty, 0::numeric) = 0::numeric) THEN 'pending'::text\n        WHEN (COALESCE(i.invoiced_qty, 0::numeric) >= COALESCE(o.ordered_qty, 0::numeric) AND COALESCE(o.ordered_qty, 0::numeric) > 0::numeric) THEN 'completed'::text\n        ELSE 'partial'::text\n    END AS invoice_status,\n    CASE\n        WHEN (COALESCE(i.invoiced_qty, 0::numeric) > 0::numeric AND COALESCE(ad.approved_delivered_qty, 0::numeric) = 0::numeric) THEN 'invoice_done_delivery_pending'::text\n        ELSE NULL::text\n    END AS special_status,\n    COALESCE(ad.approved_dc_count, 0::bigint) AS approved_dc_count,\n    COALESCE(i.invoice_count, 0::bigint) AS invoice_count,\n    COALESCE(o.ordered_qty, 0::numeric) AS ordered_qty,\n    COALESCE(ad.approved_delivered_qty, 0::numeric) AS approved_delivered_qty,\n    COALESCE(i.invoiced_qty, 0::numeric) AS invoiced_qty\n   FROM public.sales_orders so\n     LEFT JOIN ordered o ON o.so_id = so.id\n     LEFT JOIN approved_delivery ad ON ad.so_id = so.id\n     LEFT JOIN invoiced i ON i.so_id = so.id;\n\nGRANT SELECT ON public.so_delivery_invoice_status TO authenticated;\n\n-- 7. Update fn_recompute_so_status\nCREATE OR REPLACE FUNCTION public.fn_recompute_so_status(p_so_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $$\nDECLARE\n  v_ordered numeric := 0;\n  v_delivered numeric := 0;\n  v_invoiced numeric := 0;\nBEGIN\n  IF p_so_id IS NULL THEN\n    RETURN;\n  END IF;\n\n  WITH approved_by_product AS (\n    SELECT\n      dci.product_id,\n      COALESCE(SUM(dci.quantity), 0)::numeric AS delivered_qty\n    FROM public.delivery_challans dc\n    JOIN public.delivery_challan_items dci ON dci.challan_id = dc.id\n    WHERE dc.sales_order_id = p_so_id\n      AND dc.approval_status = 'approved'\n    GROUP BY dci.product_id\n  ),\n  ordered_items AS (\n    SELECT\n      soi.id,\n      soi.product_id,\n      soi.quantity,\n      COALESCE(abp.delivered_qty, 0) AS delivered_qty,\n      COALESCE(\n        SUM(soi.quantity) OVER (\n          PARTITION BY soi.product_id\n          ORDER BY soi.created_at, soi.id\n          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING\n        ),\n        0\n      ) AS prior_qty\n    FROM public.sales_order_items soi\n    LEFT JOIN approved_by_product abp ON abp.product_id = soi.product_id\n    WHERE soi.sales_order_id = p_so_id\n  ),\n  allocated AS (\n    SELECT\n      id,\n      CASE\n        WHEN delivered_qty - prior_qty <= 0 THEN 0\n        WHEN delivered_qty - prior_qty >= quantity THEN quantity\n        ELSE delivered_qty - prior_qty\n      END AS delivered_quantity\n    FROM ordered_items\n  )\n  UPDATE public.sales_order_items soi\n     SET delivered_quantity = allocated.delivered_quantity\n    FROM allocated\n   WHERE soi.id = allocated.id;\n\n  SELECT COALESCE(SUM(quantity), 0)\n    INTO v_ordered\n    FROM public.sales_order_items\n   WHERE sales_order_id = p_so_id;\n\n  SELECT COALESCE(SUM(dci.quantity), 0)\n    INTO v_delivered\n    FROM public.delivery_challans dc\n    JOIN public.delivery_challan_items dci ON dci.challan_id = dc.id\n   WHERE dc.sales_order_id = p_so_id\n     AND dc.approval_status = 'approved';\n\n  SELECT COALESCE(SUM(x.quantity), 0)\n    INTO v_invoiced\n    FROM (\n      SELECT DISTINCT\n        sii.id,\n        sii.quantity\n      FROM public.sales_invoice_items sii\n      JOIN public.sales_invoices si ON si.id = sii.invoice_id\n      LEFT JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n      LEFT JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n      WHERE COALESCE(si.is_draft, false) = false\n        AND si.invoice_number NOT ILIKE 'TEST-COGS-%'\n        AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n        AND COALESCE(si.sales_order_id, dc.sales_order_id) = p_so_id\n    ) x;\n\n  UPDATE public.sales_orders\n     SET status = CASE\n                    WHEN v_ordered > 0 AND v_delivered >= v_ordered AND v_invoiced >= v_ordered\n                      THEN 'closed'::public.sales_order_status\n                    WHEN v_ordered > 0 AND v_delivered >= v_ordered\n                      THEN 'delivered'::public.sales_order_status\n                    WHEN v_delivered > 0\n                      THEN 'partially_delivered'::public.sales_order_status\n                    ELSE status\n                  END,\n         updated_at = now()\n   WHERE id = p_so_id\n     AND status NOT IN ('closed', 'cancelled', 'rejected');\nEND;\n$$;\n\n"}	sales_dc_invoice_lifecycle_rectification	\N	\N	\N
20261028010000	{"-- ==============================================================================\n-- Delivery Challan Recovery, Editing, Source Relinking, and Re-Approval Fix\n-- Migration: 20261028010000_delivery_challan_recovery_and_source_relinking.sql\n-- ==============================================================================\n\n-- 1. Allow nullable delivery_challan_item_id on sales_invoice_items and set ON DELETE SET NULL\nALTER TABLE public.sales_invoice_items\n  ALTER COLUMN delivery_challan_item_id DROP NOT NULL;\n\nALTER TABLE public.sales_invoice_items\n  DROP CONSTRAINT IF EXISTS sales_invoice_items_delivery_challan_item_id_fkey,\n  ADD CONSTRAINT sales_invoice_items_delivery_challan_item_id_fkey\n    FOREIGN KEY (delivery_challan_item_id)\n    REFERENCES public.delivery_challan_items(id)\n    ON DELETE SET NULL;\n\n-- 2. Update foreign key constraints referencing delivery_challan_items\nALTER TABLE public.so_product_reservation_events\n  DROP CONSTRAINT IF EXISTS so_product_reservation_events_delivery_challan_item_id_fkey,\n  ADD CONSTRAINT so_product_reservation_events_delivery_challan_item_id_fkey\n    FOREIGN KEY (delivery_challan_item_id)\n    REFERENCES public.delivery_challan_items(id)\n    ON DELETE SET NULL;\n\nALTER TABLE public.dc_batch_allocations\n  DROP CONSTRAINT IF EXISTS dc_batch_allocations_delivery_challan_item_id_fkey,\n  ADD CONSTRAINT dc_batch_allocations_delivery_challan_item_id_fkey\n    FOREIGN KEY (delivery_challan_item_id)\n    REFERENCES public.delivery_challan_items(id)\n    ON DELETE CASCADE;\n\n-- 3. Update trg_sales_invoice_item_inventory trigger function\nCREATE OR REPLACE FUNCTION public.trg_sales_invoice_item_inventory()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_dc_item public.delivery_challan_items%ROWTYPE;\n  v_dc_status text;\n  v_invoiced_quantity numeric;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    RETURN OLD;\n  END IF;\n\n  IF current_setting('app.sales_invoice_cancel', true) = 'true'\n     OR current_setting('app.skip_dc_item_trigger', true) = 'true' THEN\n    RETURN NEW;\n  END IF;\n\n  IF NEW.delivery_challan_item_id IS NULL THEN\n    IF EXISTS (\n      SELECT 1 FROM public.sales_invoices si\n      WHERE si.id = NEW.invoice_id\n        AND (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n    ) THEN\n      RETURN NEW;\n    END IF;\n\n    RAISE EXCEPTION 'Sales Invoice item must reference an approved Delivery Challan item';\n  END IF;\n\n  SELECT dci.*\n  INTO v_dc_item\n  FROM public.delivery_challan_items dci\n  WHERE dci.id = NEW.delivery_challan_item_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Sales Invoice item references a missing Delivery Challan item';\n  END IF;\n\n  SELECT dc.approval_status::text\n  INTO v_dc_status\n  FROM public.delivery_challans dc\n  WHERE dc.id = v_dc_item.challan_id;\n\n  IF NOT FOUND OR v_dc_status <> 'approved' THEN\n    RAISE EXCEPTION 'Sales Invoice item references a non-approved Delivery Challan item';\n  END IF;\n\n  IF NEW.product_id IS DISTINCT FROM v_dc_item.product_id\n     OR NEW.batch_id IS DISTINCT FROM v_dc_item.batch_id THEN\n    RAISE EXCEPTION 'Sales Invoice product/batch must match its Delivery Challan item';\n  END IF;\n\n  SELECT COALESCE(SUM(sii.quantity), 0)\n  INTO v_invoiced_quantity\n  FROM public.sales_invoice_items sii\n  JOIN public.sales_invoices si ON si.id = sii.invoice_id\n  WHERE sii.delivery_challan_item_id = NEW.delivery_challan_item_id\n    AND sii.id IS DISTINCT FROM NEW.id\n    AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%');\n\n  IF v_invoiced_quantity + NEW.quantity > v_dc_item.quantity THEN\n    RAISE EXCEPTION 'Sales Invoice quantity exceeds approved Delivery Challan quantity';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 4. Update guard_delivery_challan_source_link trigger function\n-- Only block detachment / reassignment of sales_order_id if the DC is CURRENTLY APPROVED.\n-- Allows rejected, cancelled, draft, or pending DCs to be relinked to an eligible Sales Order.\nCREATE OR REPLACE FUNCTION public.guard_delivery_challan_source_link()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_so_customer uuid;\nBEGIN\n  IF OLD.approval_status = 'approved'\n     AND OLD.sales_order_id IS NOT NULL\n     AND NEW.sales_order_id IS DISTINCT FROM OLD.sales_order_id THEN\n    RAISE EXCEPTION 'An approved Delivery Challan linked to a Sales Order cannot be detached or reassigned; cancel or reverse it first';\n  END IF;\n\n  IF NEW.sales_order_id IS NOT NULL THEN\n    SELECT customer_id INTO v_so_customer\n    FROM public.sales_orders\n    WHERE id = NEW.sales_order_id;\n\n    IF NOT FOUND THEN\n      RAISE EXCEPTION 'Linked Sales Order % does not exist', NEW.sales_order_id;\n    END IF;\n    IF NEW.customer_id IS DISTINCT FROM v_so_customer THEN\n      RAISE EXCEPTION 'Delivery Challan customer must match its linked Sales Order customer';\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 5. Update edit_delivery_challan RPC to allow editing rejected/cancelled DCs and save sales_order_item_id\nCREATE OR REPLACE FUNCTION public.edit_delivery_challan(p_challan_id uuid, p_new_items jsonb)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_role               text;\n  v_challan            record;\n  v_item               jsonb;\n  v_count              integer;\n  v_product_id         uuid;\n  v_batch_id           uuid;\n  v_new_qty            numeric;\n  v_item_id            uuid;\n  v_so_item_id         uuid;\n  v_blocking_invoices  text;\n  v_kept_ids           uuid[] := ARRAY[]::uuid[];\nBEGIN\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts', 'warehouse', 'sales') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot edit delivery challans', v_role;\n  END IF;\n\n  SELECT * INTO v_challan FROM public.delivery_challans WHERE id = p_challan_id FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Delivery challan not found');\n  END IF;\n\n  IF v_challan.approval_status = 'approved' THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Cannot edit approved delivery challan directly; reverse it or use approved DC edit');\n  END IF;\n\n  -- Check if any active (uncancelled) invoice items reference this DC\n  IF EXISTS (\n    SELECT 1\n    FROM public.sales_invoice_items sii\n    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    WHERE dci.challan_id = p_challan_id\n      AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n  ) THEN\n    SELECT string_agg(DISTINCT si.invoice_number, ', ')\n    INTO v_blocking_invoices\n    FROM public.sales_invoice_items sii\n    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    WHERE dci.challan_id = p_challan_id\n      AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%');\n\n    RETURN jsonb_build_object(\n      'success', false,\n      'error', 'Delivery Challan already invoiced by active invoice(s) ' || v_blocking_invoices || '; cancel or reverse the invoice(s) first'\n    );\n  END IF;\n\n  SELECT count(*) INTO v_count FROM jsonb_array_elements(p_new_items);\n  IF v_count = 0 THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Cannot save DC with no items');\n  END IF;\n\n  PERFORM set_config('app.skip_dc_item_trigger', 'true', true);\n  PERFORM set_config('app.sales_invoice_cancel', 'true', true);\n\n  -- Upsert / replace items\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_new_items)\n  LOOP\n    v_item_id    := NULLIF(v_item->>'id', '')::uuid;\n    v_product_id := (v_item->>'product_id')::uuid;\n    v_batch_id   := (v_item->>'batch_id')::uuid;\n    v_new_qty    := (v_item->>'quantity')::numeric;\n    v_so_item_id := NULLIF(v_item->>'sales_order_item_id', '')::uuid;\n\n    IF v_new_qty <= 0 THEN\n      RAISE EXCEPTION 'Item quantity must be greater than zero';\n    END IF;\n\n    IF v_item_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.delivery_challan_items WHERE id = v_item_id AND challan_id = p_challan_id) THEN\n      UPDATE public.delivery_challan_items SET\n        product_id = v_product_id,\n        batch_id = v_batch_id,\n        sales_order_item_id = v_so_item_id,\n        quantity = v_new_qty,\n        pack_size = NULLIF(v_item->>'pack_size', '')::numeric,\n        pack_type = NULLIF(v_item->>'pack_type', ''),\n        number_of_packs = NULLIF(v_item->>'number_of_packs', '')::integer\n      WHERE id = v_item_id;\n\n      v_kept_ids := array_append(v_kept_ids, v_item_id);\n    ELSE\n      v_item_id := COALESCE(v_item_id, gen_random_uuid());\n      INSERT INTO public.delivery_challan_items (\n        id, challan_id, product_id, batch_id, sales_order_item_id, quantity,\n        pack_size, pack_type, number_of_packs\n      ) VALUES (\n        v_item_id, p_challan_id, v_product_id, v_batch_id, v_so_item_id, v_new_qty,\n        NULLIF(v_item->>'pack_size', '')::numeric,\n        NULLIF(v_item->>'pack_type', ''),\n        NULLIF(v_item->>'number_of_packs', '')::integer\n      );\n      v_kept_ids := array_append(v_kept_ids, v_item_id);\n    END IF;\n  END LOOP;\n\n  -- Remove any DC items that were not in the updated item list\n  DELETE FROM public.delivery_challan_items\n  WHERE challan_id = p_challan_id\n    AND id <> ALL(v_kept_ids);\n\n  PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n  PERFORM set_config('app.sales_invoice_cancel', 'false', true);\n\n  RETURN jsonb_build_object('success', true, 'message', 'Delivery challan updated successfully');\n\nEXCEPTION\n  WHEN foreign_key_violation THEN\n    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n    PERFORM set_config('app.sales_invoice_cancel', 'false', true);\n    RETURN jsonb_build_object('success', false, 'error', 'Invalid product or batch selection: ' || SQLERRM);\n  WHEN OTHERS THEN\n    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n    PERFORM set_config('app.sales_invoice_cancel', 'false', true);\n    RETURN jsonb_build_object('success', false, 'error', SQLERRM);\nEND;\n$$;\n\n-- 6. Update trg_dc_approval_product_reservation_v2 trigger function\nCREATE OR REPLACE FUNCTION public.trg_dc_approval_product_reservation_v2()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  r record;\nBEGIN\n  IF NEW.approval_status = 'approved'\n     AND OLD.approval_status IS DISTINCT FROM 'approved' THEN\n    IF NEW.approval_operation_id IS NULL THEN\n      RAISE EXCEPTION 'approval_operation_id is required';\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM public.delivery_challan_items WHERE challan_id = NEW.id) THEN\n      RAISE EXCEPTION 'Cannot approve Delivery Challan % without items', NEW.challan_number;\n    END IF;\n\n    FOR r IN\n      SELECT id FROM public.delivery_challan_items WHERE challan_id = NEW.id ORDER BY id\n    LOOP\n      PERFORM public.consume_so_product_reservation_v2(\n        r.id,\n        NEW.approval_operation_id,\n        COALESCE(NEW.approved_by, auth.uid())\n      );\n    END LOOP;\n\n    IF NEW.sales_order_id IS NOT NULL THEN\n      PERFORM public.fn_recompute_so_delivered(NEW.sales_order_id);\n      PERFORM public.fn_recompute_so_status(NEW.sales_order_id);\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 7. Add RLS DELETE policy for delivery_challans\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_policies\n    WHERE tablename = 'delivery_challans'\n      AND policyname = 'Admin, sales, and warehouse can delete unposted delivery_challans'\n  ) THEN\n    CREATE POLICY \\"Admin, sales, and warehouse can delete unposted delivery_challans\\"\n      ON public.delivery_challans\n      FOR DELETE\n      TO authenticated\n      USING (\n        EXISTS (\n          SELECT 1 FROM public.user_profiles\n          WHERE user_profiles.id = auth.uid()\n            AND user_profiles.role = ANY (ARRAY['admin', 'sales', 'warehouse'])\n            AND user_profiles.is_active = true\n        )\n        AND approval_status <> 'approved'\n      );\n  END IF;\nEND $$;\n"}	delivery_challan_recovery_and_source_relinking	\N	\N	\N
20261028015459	{"-- ============================================================================\n-- Migration: 20261028040000_fix_delivery_challan_edit_type_mismatch.sql\n-- Description:\n-- 1. Fixes the PostgreSQL type error: \\"COALESCE types text and dc_approval_status cannot be matched\\"\n--    in edit_delivery_challan RPC by validating and casting approval_status to public.dc_approval_status.\n-- 2. Eliminates signature ambiguity between 2-arg and 3-arg overloads by defining a single canonical\n--    edit_delivery_challan function with DEFAULT NULL for p_header.\n-- 3. Enforces Sales Order quantity constraints, batch validity, and parent SO status checks atomically.\n-- ============================================================================\n\nBEGIN;\n\n-- Drop existing overloads to avoid signature collision\nDROP FUNCTION IF EXISTS public.edit_delivery_challan(uuid, jsonb);\nDROP FUNCTION IF EXISTS public.edit_delivery_challan(uuid, jsonb, jsonb);\n\nCREATE OR REPLACE FUNCTION public.edit_delivery_challan(\n  p_challan_id uuid,\n  p_new_items jsonb,\n  p_header jsonb DEFAULT NULL::jsonb\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $$\nDECLARE\n  v_role               text;\n  v_challan            record;\n  v_item               jsonb;\n  v_count              integer;\n  v_product_id         uuid;\n  v_batch_id           uuid;\n  v_new_qty            numeric;\n  v_item_id            uuid;\n  v_so_item_id         uuid;\n  v_so_id              uuid;\n  v_blocking_invoices  text;\n  v_kept_ids           uuid[] := ARRAY[]::uuid[];\n  v_new_status         text;\n  v_parsed_status      public.dc_approval_status := NULL;\n  v_so_status          text;\n  v_soi_qty            numeric;\n  v_soi_del_qty        numeric;\n  v_other_pending      numeric;\n  v_remaining_qty      numeric;\n  v_batch_active       boolean;\n  v_batch_not_expired  boolean;\nBEGIN\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts', 'warehouse', 'sales') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot edit delivery challans', v_role;\n  END IF;\n\n  SELECT * INTO v_challan FROM public.delivery_challans WHERE id = p_challan_id FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Delivery challan not found');\n  END IF;\n\n  IF v_challan.approval_status = 'approved' THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Cannot edit approved delivery challan directly; reverse it or use approved DC edit');\n  END IF;\n\n  -- Check if any active (uncancelled) invoice items reference this DC\n  IF EXISTS (\n    SELECT 1\n    FROM public.sales_invoice_items sii\n    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    WHERE dci.challan_id = p_challan_id\n      AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n  ) THEN\n    SELECT string_agg(DISTINCT si.invoice_number, ', ')\n    INTO v_blocking_invoices\n    FROM public.sales_invoice_items sii\n    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    WHERE dci.challan_id = p_challan_id\n      AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%');\n\n    RETURN jsonb_build_object(\n      'success', false,\n      'error', 'Delivery Challan already invoiced by active invoice(s) ' || v_blocking_invoices || '; cancel or reverse the invoice(s) first'\n    );\n  END IF;\n\n  -- Validate and apply header if provided\n  IF p_header IS NOT NULL THEN\n    IF p_header ? 'approval_status' THEN\n      v_new_status := NULLIF(TRIM(p_header->>'approval_status'), '');\n      IF v_new_status IS NOT NULL THEN\n        IF v_new_status NOT IN ('pending_approval', 'rejected', 'cancelled') THEN\n          RAISE EXCEPTION '%', 'Invalid approval_status: ' || v_new_status || '. Allowed values are pending_approval, rejected, cancelled.';\n        END IF;\n        v_parsed_status := v_new_status::public.dc_approval_status;\n      END IF;\n    END IF;\n\n    v_so_id := CASE \n      WHEN p_header ? 'sales_order_id' THEN NULLIF(p_header->>'sales_order_id', '')::uuid \n      ELSE v_challan.sales_order_id \n    END;\n\n    -- Verify parent Sales Order status if linked\n    IF v_so_id IS NOT NULL THEN\n      SELECT status::text INTO v_so_status FROM public.sales_orders WHERE id = v_so_id;\n      IF v_so_status IN ('cancelled', 'rejected') THEN\n        RAISE EXCEPTION '%', 'Cannot save Delivery Challan: linked Sales Order is ' || v_so_status;\n      END IF;\n    END IF;\n\n    UPDATE public.delivery_challans SET\n      customer_id = CASE WHEN p_header ? 'customer_id' THEN COALESCE(NULLIF(p_header->>'customer_id', '')::uuid, customer_id) ELSE customer_id END,\n      sales_order_id = v_so_id,\n      challan_date = CASE WHEN p_header ? 'challan_date' THEN COALESCE(NULLIF(p_header->>'challan_date', '')::date, challan_date) ELSE challan_date END,\n      delivery_address = CASE WHEN p_header ? 'delivery_address' THEN COALESCE(p_header->>'delivery_address', delivery_address) ELSE delivery_address END,\n      vehicle_number = CASE WHEN p_header ? 'vehicle_number' THEN NULLIF(p_header->>'vehicle_number', '') ELSE vehicle_number END,\n      driver_name = CASE WHEN p_header ? 'driver_name' THEN NULLIF(p_header->>'driver_name', '') ELSE driver_name END,\n      notes = CASE WHEN p_header ? 'notes' THEN NULLIF(p_header->>'notes', '') ELSE notes END,\n      approval_status = COALESCE(v_parsed_status, approval_status),\n      rejection_reason = CASE WHEN v_parsed_status = 'pending_approval'::public.dc_approval_status THEN NULL WHEN p_header ? 'rejection_reason' THEN NULLIF(p_header->>'rejection_reason', '') ELSE rejection_reason END,\n      rejected_by = CASE WHEN v_parsed_status = 'pending_approval'::public.dc_approval_status THEN NULL ELSE rejected_by END,\n      rejected_at = CASE WHEN v_parsed_status = 'pending_approval'::public.dc_approval_status THEN NULL ELSE rejected_at END,\n      approved_at = CASE WHEN v_parsed_status = 'pending_approval'::public.dc_approval_status THEN NULL ELSE approved_at END,\n      approved_by = CASE WHEN v_parsed_status = 'pending_approval'::public.dc_approval_status THEN NULL ELSE approved_by END,\n      updated_at = NOW()\n    WHERE id = p_challan_id;\n  ELSE\n    v_so_id := v_challan.sales_order_id;\n    IF v_so_id IS NOT NULL THEN\n      SELECT status::text INTO v_so_status FROM public.sales_orders WHERE id = v_so_id;\n      IF v_so_status IN ('cancelled', 'rejected') THEN\n        RAISE EXCEPTION '%', 'Cannot save Delivery Challan: linked Sales Order is ' || v_so_status;\n      END IF;\n    END IF;\n  END IF;\n\n  SELECT count(*) INTO v_count FROM jsonb_array_elements(p_new_items);\n  IF v_count = 0 THEN\n    RAISE EXCEPTION '%', 'Cannot save DC with no items';\n  END IF;\n\n  PERFORM set_config('app.skip_dc_item_trigger', 'true', true);\n  PERFORM set_config('app.sales_invoice_cancel', 'true', true);\n\n  -- Upsert / replace items\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_new_items)\n  LOOP\n    v_item_id    := NULLIF(v_item->>'id', '')::uuid;\n    v_product_id := NULLIF(v_item->>'product_id', '')::uuid;\n    v_batch_id   := NULLIF(v_item->>'batch_id', '')::uuid;\n    v_new_qty    := NULLIF(v_item->>'quantity', '')::numeric;\n    v_so_item_id := NULLIF(v_item->>'sales_order_item_id', '')::uuid;\n\n    IF v_product_id IS NULL OR v_batch_id IS NULL THEN\n      RAISE EXCEPTION '%', 'Each delivery item must have a valid product and batch';\n    END IF;\n\n    IF v_new_qty IS NULL OR v_new_qty <= 0 THEN\n      RAISE EXCEPTION '%', 'Item quantity must be greater than zero';\n    END IF;\n\n    -- Batch validity check\n    SELECT is_active, (expiry_date IS NULL OR expiry_date > CURRENT_DATE)\n    INTO v_batch_active, v_batch_not_expired\n    FROM public.batches\n    WHERE id = v_batch_id AND product_id = v_product_id;\n\n    IF NOT FOUND OR NOT COALESCE(v_batch_active, false) OR NOT COALESCE(v_batch_not_expired, false) THEN\n      RAISE EXCEPTION '%', 'Selected batch is invalid, inactive, or expired';\n    END IF;\n\n    -- SO Item quantity constraint\n    IF v_so_id IS NOT NULL AND v_so_item_id IS NOT NULL THEN\n      SELECT quantity, COALESCE(delivered_quantity, 0)\n      INTO v_soi_qty, v_soi_del_qty\n      FROM public.sales_order_items\n      WHERE id = v_so_item_id AND sales_order_id = v_so_id AND product_id = v_product_id;\n\n      IF NOT FOUND THEN\n        RAISE EXCEPTION '%', 'DC item does not match the linked Sales Order item';\n      END IF;\n\n      SELECT COALESCE(sum(dci.quantity), 0) INTO v_other_pending\n      FROM public.delivery_challan_items dci\n      JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n      WHERE dci.sales_order_item_id = v_so_item_id\n        AND dc.approval_status = 'pending_approval'\n        AND dc.id <> p_challan_id;\n\n      v_remaining_qty := v_soi_qty - v_soi_del_qty;\n      IF (v_other_pending + v_new_qty) > (v_remaining_qty + 0.0001) THEN\n        RAISE EXCEPTION '%', 'Delivery quantity (' || v_new_qty || ') exceeds remaining Sales Order quantity (' || (v_remaining_qty - v_other_pending) || ')';\n      END IF;\n    END IF;\n\n    IF v_item_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.delivery_challan_items WHERE id = v_item_id AND challan_id = p_challan_id) THEN\n      UPDATE public.delivery_challan_items SET\n        product_id = v_product_id,\n        batch_id = v_batch_id,\n        sales_order_item_id = v_so_item_id,\n        quantity = v_new_qty,\n        pack_size = NULLIF(v_item->>'pack_size', '')::numeric,\n        pack_type = NULLIF(v_item->>'pack_type', ''),\n        number_of_packs = NULLIF(v_item->>'number_of_packs', '')::integer\n      WHERE id = v_item_id;\n\n      v_kept_ids := array_append(v_kept_ids, v_item_id);\n    ELSE\n      v_item_id := COALESCE(v_item_id, gen_random_uuid());\n      INSERT INTO public.delivery_challan_items (\n        id, challan_id, product_id, batch_id, sales_order_item_id, quantity,\n        pack_size, pack_type, number_of_packs\n      ) VALUES (\n        v_item_id, p_challan_id, v_product_id, v_batch_id, v_so_item_id, v_new_qty,\n        NULLIF(v_item->>'pack_size', '')::numeric,\n        NULLIF(v_item->>'pack_type', ''),\n        NULLIF(v_item->>'number_of_packs', '')::integer\n      );\n      v_kept_ids := array_append(v_kept_ids, v_item_id);\n    END IF;\n  END LOOP;\n\n  -- Remove any DC items that were not in the updated item list\n  DELETE FROM public.delivery_challan_items\n  WHERE challan_id = p_challan_id\n    AND id <> ALL(v_kept_ids);\n\n  PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n  PERFORM set_config('app.sales_invoice_cancel', 'false', true);\n\n  RETURN jsonb_build_object('success', true, 'message', 'Delivery challan updated successfully');\n\nEXCEPTION\n  WHEN foreign_key_violation THEN\n    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n    PERFORM set_config('app.sales_invoice_cancel', 'false', true);\n    RAISE EXCEPTION '%', 'Invalid product or batch selection: ' || SQLERRM;\n  WHEN OTHERS THEN\n    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n    PERFORM set_config('app.sales_invoice_cancel', 'false', true);\n    RAISE EXCEPTION '%', SQLERRM;\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.edit_delivery_challan(uuid, jsonb, jsonb) TO authenticated;\n\nCOMMIT;\n"}	fix_delivery_challan_edit_type_mismatch	simplykool@gmail.com	\N	\N
20261028024712	{"-- Migration: 20261028050000_fix_dc_quantity_validation_and_trigger_exclusion.sql\n-- Description:\n-- 1. Updates validate_dc_item_product_reservation_v2 to:\n--    a) Respect app.skip_dc_item_trigger during atomic RPC bulk updates.\n--    b) Exclude the current Delivery Challan (NEW.challan_id) when calculating pending deliverable quantity from other challans.\n--    c) Accurately sum other items on the same challan excluding the row being updated (NEW.id).\n-- 2. Updates validate_delivery_challan_source_item to respect app.skip_dc_item_trigger.\n-- 3. Updates edit_delivery_challan to:\n--    a) Sum total requested quantity per Sales Order item across p_new_items before comparing against deliverable remaining.\n--    b) Calculate other pending delivery quantities strictly excluding p_challan_id.\n--    c) Reuse / match existing delivery challan item IDs when updating items so items are updated in-place rather than generating duplicate conflicting rows.\n--    d) Ensure strict atomicity and complete rollback on any validation failure.\n\nBEGIN;\n\n-- 1. Update validate_dc_item_product_reservation_v2 trigger function\nCREATE OR REPLACE FUNCTION public.validate_dc_item_product_reservation_v2()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_dc record;\n  v_so_item public.sales_order_items%ROWTYPE;\n  v_pending numeric;\n  v_remaining numeric;\n  v_so_make uuid;\n  v_batch_make uuid;\n  v_so_status text;\nBEGIN\n  -- Honor trigger bypass during atomic RPC bulk operations\n  IF current_setting('app.skip_dc_item_trigger', true) = 'true' THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT dc.sales_order_id, dc.approval_status INTO v_dc\n  FROM public.delivery_challans dc\n  WHERE dc.id = NEW.challan_id;\n\n  IF NOT FOUND OR NEW.sales_order_item_id IS NULL THEN\n    RAISE EXCEPTION 'DC item requires a canonical SO item';\n  END IF;\n\n  -- Verify parent Sales Order status\n  IF v_dc.sales_order_id IS NOT NULL THEN\n    SELECT status::text INTO v_so_status\n    FROM public.sales_orders\n    WHERE id = v_dc.sales_order_id;\n\n    IF v_so_status IN ('cancelled', 'rejected') THEN\n      RAISE EXCEPTION 'Cannot add or modify Delivery Challan items: linked Sales Order is %', v_so_status;\n    END IF;\n  END IF;\n\n  SELECT * INTO v_so_item\n  FROM public.sales_order_items soi\n  WHERE soi.id = NEW.sales_order_item_id\n    AND soi.sales_order_id = v_dc.sales_order_id\n    AND soi.product_id = NEW.product_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'DC product does not match its SO item';\n  END IF;\n\n  v_so_make := v_so_item.make_id;\n\n  SELECT b.make_id INTO v_batch_make\n  FROM public.batches b\n  WHERE b.id = NEW.batch_id\n    AND b.product_id = NEW.product_id\n    AND b.is_active = true\n    AND (b.expiry_date IS NULL OR b.expiry_date > CURRENT_DATE);\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Selected DC batch is not eligible for this product';\n  END IF;\n\n  -- NULL Make preserves historical records; known Make must match exactly.\n  IF v_so_make IS NOT NULL AND v_batch_make IS DISTINCT FROM v_so_make THEN\n    RAISE EXCEPTION 'Selected DC batch Make does not match the Sales Order Make';\n  END IF;\n\n  -- Validate against remaining deliverable Sales Order quantity\n  -- Sum pending items from OTHER pending delivery challans\n  SELECT COALESCE(sum(dci.quantity), 0) INTO v_pending\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n  WHERE dci.sales_order_item_id = NEW.sales_order_item_id\n    AND dc.approval_status = 'pending_approval'\n    AND dc.id IS DISTINCT FROM NEW.challan_id;\n\n  -- Sum other items on the SAME challan excluding the row being inserted/updated\n  SELECT v_pending + COALESCE(sum(dci.quantity), 0) INTO v_pending\n  FROM public.delivery_challan_items dci\n  WHERE dci.challan_id = NEW.challan_id\n    AND dci.sales_order_item_id = NEW.sales_order_item_id\n    AND dci.id IS DISTINCT FROM NEW.id;\n\n  v_remaining := v_so_item.quantity - COALESCE(v_so_item.delivered_quantity, 0);\n  IF (v_pending + NEW.quantity) > (v_remaining + 0.0001) THEN\n    RAISE EXCEPTION 'Delivery quantity (%) exceeds remaining Sales Order quantity (%)', (v_pending + NEW.quantity), v_remaining;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 2. Update validate_delivery_challan_source_item trigger function\nCREATE OR REPLACE FUNCTION public.validate_delivery_challan_source_item()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_dc public.delivery_challans%rowtype;\n  v_soi public.sales_order_items%rowtype;\n  v_remaining numeric;\nBEGIN\n  -- Honor trigger bypass during atomic RPC bulk operations\n  IF current_setting('app.skip_dc_item_trigger', true) = 'true' THEN\n    RETURN NEW;\n  END IF;\n\n  SELECT * INTO v_dc FROM public.delivery_challans WHERE id = NEW.challan_id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Delivery Challan does not exist';\n  END IF;\n\n  IF v_dc.sales_order_id IS NULL THEN\n    IF NEW.sales_order_item_id IS NOT NULL THEN\n      RAISE EXCEPTION 'Unlinked Delivery Challan cannot reference a Sales Order item';\n    END IF;\n    RETURN NEW;\n  END IF;\n\n  IF NEW.sales_order_item_id IS NULL THEN\n    SELECT soi.id INTO NEW.sales_order_item_id\n    FROM public.sales_order_items soi\n    WHERE soi.sales_order_id = v_dc.sales_order_id AND soi.product_id = NEW.product_id;\n\n    IF NEW.sales_order_item_id IS NULL THEN\n      RAISE EXCEPTION 'Delivery Challan product is not present on the selected Sales Order';\n    END IF;\n\n    IF (SELECT count(*) FROM public.sales_order_items soi WHERE soi.sales_order_id = v_dc.sales_order_id AND soi.product_id = NEW.product_id) > 1 THEN\n      RAISE EXCEPTION 'Delivery Challan item source is ambiguous; select the exact Sales Order item';\n    END IF;\n  END IF;\n\n  IF NEW.sales_order_item_id IS NULL THEN\n    RAISE EXCEPTION 'Sales Order-linked Delivery Challan item requires sales_order_item_id';\n  END IF;\n\n  SELECT * INTO v_soi FROM public.sales_order_items WHERE id = NEW.sales_order_item_id AND sales_order_id = v_dc.sales_order_id FOR SHARE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Delivery Challan item is not from the selected Sales Order';\n  END IF;\n\n  IF NEW.product_id IS DISTINCT FROM v_soi.product_id THEN\n    RAISE EXCEPTION 'Delivery Challan product must match the Sales Order item';\n  END IF;\n\n  v_remaining := v_soi.quantity - COALESCE(v_soi.delivered_quantity, 0);\n  IF TG_OP = 'UPDATE' THEN\n    v_remaining := v_remaining + COALESCE(OLD.quantity, 0);\n  END IF;\n\n  IF NEW.quantity <= 0 OR NEW.quantity > (v_remaining + 0.0001) THEN\n    RAISE EXCEPTION 'Delivery quantity exceeds remaining Sales Order quantity';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 3. Update edit_delivery_challan RPC\nCREATE OR REPLACE FUNCTION public.edit_delivery_challan(\n  p_challan_id uuid,\n  p_new_items jsonb,\n  p_header jsonb DEFAULT NULL::jsonb\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_role               text;\n  v_challan            record;\n  v_item               jsonb;\n  v_count              integer;\n  v_product_id         uuid;\n  v_batch_id           uuid;\n  v_new_qty            numeric;\n  v_item_id            uuid;\n  v_matched_id         uuid;\n  v_so_item_id         uuid;\n  v_so_id              uuid;\n  v_blocking_invoices  text;\n  v_kept_ids           uuid[] := ARRAY[]::uuid[];\n  v_new_status         text;\n  v_parsed_status      public.dc_approval_status := NULL;\n  v_so_status          text;\n  v_soi_qty            numeric;\n  v_soi_del_qty        numeric;\n  v_other_pending      numeric;\n  v_total_new_so_qty   numeric;\n  v_remaining_qty      numeric;\n  v_batch_active       boolean;\n  v_batch_not_expired  boolean;\nBEGIN\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role NOT IN ('admin', 'accounts', 'warehouse', 'sales') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot edit delivery challans', v_role;\n  END IF;\n\n  SELECT * INTO v_challan FROM public.delivery_challans WHERE id = p_challan_id FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Delivery challan not found');\n  END IF;\n\n  IF v_challan.approval_status = 'approved' THEN\n    RETURN jsonb_build_object('success', false, 'error', 'Cannot edit approved delivery challan directly; reverse it or use approved DC edit');\n  END IF;\n\n  -- Check if any active (uncancelled) invoice items reference this DC\n  IF EXISTS (\n    SELECT 1\n    FROM public.sales_invoice_items sii\n    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    WHERE dci.challan_id = p_challan_id\n      AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%')\n  ) THEN\n    SELECT string_agg(DISTINCT si.invoice_number, ', ')\n    INTO v_blocking_invoices\n    FROM public.sales_invoice_items sii\n    JOIN public.delivery_challan_items dci ON dci.id = sii.delivery_challan_item_id\n    JOIN public.sales_invoices si ON si.id = sii.invoice_id\n    WHERE dci.challan_id = p_challan_id\n      AND NOT (si.notes LIKE '[CANCELLED%' OR LOWER(si.notes) LIKE 'cancelled%');\n\n    RETURN jsonb_build_object(\n      'success', false,\n      'error', 'Delivery Challan already invoiced by active invoice(s) ' || v_blocking_invoices || '; cancel or reverse the invoice(s) first'\n    );\n  END IF;\n\n  -- Validate and apply header if provided\n  IF p_header IS NOT NULL THEN\n    IF p_header ? 'approval_status' THEN\n      v_new_status := NULLIF(TRIM(p_header->>'approval_status'), '');\n      IF v_new_status IS NOT NULL THEN\n        IF v_new_status NOT IN ('pending_approval', 'rejected', 'cancelled') THEN\n          RAISE EXCEPTION 'Invalid approval_status: %. Allowed values are pending_approval, rejected, cancelled.', v_new_status;\n        END IF;\n        v_parsed_status := v_new_status::public.dc_approval_status;\n      END IF;\n    END IF;\n\n    v_so_id := CASE \n      WHEN p_header ? 'sales_order_id' THEN NULLIF(p_header->>'sales_order_id', '')::uuid \n      ELSE v_challan.sales_order_id \n    END;\n\n    -- Verify parent Sales Order status if linked\n    IF v_so_id IS NOT NULL THEN\n      SELECT status::text INTO v_so_status FROM public.sales_orders WHERE id = v_so_id;\n      IF v_so_status IN ('cancelled', 'rejected') THEN\n        RAISE EXCEPTION 'Cannot save Delivery Challan: linked Sales Order is %', v_so_status;\n      END IF;\n    END IF;\n\n    UPDATE public.delivery_challans SET\n      customer_id = CASE WHEN p_header ? 'customer_id' THEN COALESCE(NULLIF(p_header->>'customer_id', '')::uuid, customer_id) ELSE customer_id END,\n      sales_order_id = v_so_id,\n      challan_date = CASE WHEN p_header ? 'challan_date' THEN COALESCE(NULLIF(p_header->>'challan_date', '')::date, challan_date) ELSE challan_date END,\n      delivery_address = CASE WHEN p_header ? 'delivery_address' THEN COALESCE(p_header->>'delivery_address', delivery_address) ELSE delivery_address END,\n      vehicle_number = CASE WHEN p_header ? 'vehicle_number' THEN NULLIF(p_header->>'vehicle_number', '') ELSE vehicle_number END,\n      driver_name = CASE WHEN p_header ? 'driver_name' THEN NULLIF(p_header->>'driver_name', '') ELSE driver_name END,\n      notes = CASE WHEN p_header ? 'notes' THEN NULLIF(p_header->>'notes', '') ELSE notes END,\n      approval_status = COALESCE(v_parsed_status, approval_status),\n      rejection_reason = CASE WHEN v_parsed_status = 'pending_approval'::public.dc_approval_status THEN NULL WHEN p_header ? 'rejection_reason' THEN NULLIF(p_header->>'rejection_reason', '') ELSE rejection_reason END,\n      rejected_by = CASE WHEN v_parsed_status = 'pending_approval'::public.dc_approval_status THEN NULL ELSE rejected_by END,\n      rejected_at = CASE WHEN v_parsed_status = 'pending_approval'::public.dc_approval_status THEN NULL ELSE rejected_at END,\n      approved_at = CASE WHEN v_parsed_status = 'pending_approval'::public.dc_approval_status THEN NULL ELSE approved_at END,\n      approved_by = CASE WHEN v_parsed_status = 'pending_approval'::public.dc_approval_status THEN NULL ELSE approved_by END,\n      updated_at = NOW()\n    WHERE id = p_challan_id;\n  ELSE\n    v_so_id := v_challan.sales_order_id;\n    IF v_so_id IS NOT NULL THEN\n      SELECT status::text INTO v_so_status FROM public.sales_orders WHERE id = v_so_id;\n      IF v_so_status IN ('cancelled', 'rejected') THEN\n        RAISE EXCEPTION 'Cannot save Delivery Challan: linked Sales Order is %', v_so_status;\n      END IF;\n    END IF;\n  END IF;\n\n  SELECT count(*) INTO v_count FROM jsonb_array_elements(p_new_items);\n  IF v_count = 0 THEN\n    RAISE EXCEPTION 'Cannot save DC with no items';\n  END IF;\n\n  PERFORM set_config('app.skip_dc_item_trigger', 'true', true);\n  PERFORM set_config('app.sales_invoice_cancel', 'true', true);\n\n  -- Upsert / replace items\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_new_items)\n  LOOP\n    v_item_id    := NULLIF(v_item->>'id', '')::uuid;\n    v_product_id := NULLIF(v_item->>'product_id', '')::uuid;\n    v_batch_id   := NULLIF(v_item->>'batch_id', '')::uuid;\n    v_new_qty    := NULLIF(v_item->>'quantity', '')::numeric;\n    v_so_item_id := NULLIF(v_item->>'sales_order_item_id', '')::uuid;\n\n    IF v_product_id IS NULL OR v_batch_id IS NULL THEN\n      RAISE EXCEPTION 'Each delivery item must have a valid product and batch';\n    END IF;\n\n    IF v_new_qty IS NULL OR v_new_qty <= 0 THEN\n      RAISE EXCEPTION 'Item quantity must be greater than zero';\n    END IF;\n\n    -- Batch validity check\n    SELECT is_active, (expiry_date IS NULL OR expiry_date > CURRENT_DATE)\n    INTO v_batch_active, v_batch_not_expired\n    FROM public.batches\n    WHERE id = v_batch_id AND product_id = v_product_id;\n\n    IF NOT FOUND OR NOT COALESCE(v_batch_active, false) OR NOT COALESCE(v_batch_not_expired, false) THEN\n      RAISE EXCEPTION 'Selected batch is invalid, inactive, or expired';\n    END IF;\n\n    -- SO Item quantity constraint\n    IF v_so_id IS NOT NULL AND v_so_item_id IS NOT NULL THEN\n      SELECT quantity, COALESCE(delivered_quantity, 0)\n      INTO v_soi_qty, v_soi_del_qty\n      FROM public.sales_order_items\n      WHERE id = v_so_item_id AND sales_order_id = v_so_id AND product_id = v_product_id;\n\n      IF NOT FOUND THEN\n        RAISE EXCEPTION 'DC item does not match the linked Sales Order item';\n      END IF;\n\n      -- Other pending DCs (strictly excluding the current DC being edited)\n      SELECT COALESCE(sum(dci.quantity), 0) INTO v_other_pending\n      FROM public.delivery_challan_items dci\n      JOIN public.delivery_challans dc ON dc.id = dci.challan_id\n      WHERE dci.sales_order_item_id = v_so_item_id\n        AND dc.approval_status = 'pending_approval'\n        AND dc.id <> p_challan_id;\n\n      -- Total requested quantity across p_new_items for this SO item\n      SELECT COALESCE(sum((elem->>'quantity')::numeric), 0) INTO v_total_new_so_qty\n      FROM jsonb_array_elements(p_new_items) elem\n      WHERE NULLIF(elem->>'sales_order_item_id', '')::uuid = v_so_item_id;\n\n      v_remaining_qty := v_soi_qty - v_soi_del_qty;\n      IF (v_other_pending + v_total_new_so_qty) > (v_remaining_qty + 0.0001) THEN\n        RAISE EXCEPTION 'Delivery quantity (%) exceeds remaining Sales Order quantity (%)', v_total_new_so_qty, (v_remaining_qty - v_other_pending);\n      END IF;\n    END IF;\n\n    -- If no item ID supplied, attempt to match an existing unclaimed item on this DC\n    IF v_item_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.delivery_challan_items WHERE id = v_item_id AND challan_id = p_challan_id) THEN\n      v_matched_id := NULL;\n      SELECT id INTO v_matched_id\n      FROM public.delivery_challan_items\n      WHERE challan_id = p_challan_id\n        AND id <> ALL(v_kept_ids)\n        AND (\n          (v_so_item_id IS NOT NULL AND sales_order_item_id = v_so_item_id)\n          OR (product_id = v_product_id)\n        )\n      ORDER BY (sales_order_item_id = v_so_item_id) DESC, (product_id = v_product_id) DESC\n      LIMIT 1;\n\n      IF v_matched_id IS NOT NULL THEN\n        v_item_id := v_matched_id;\n      END IF;\n    END IF;\n\n    IF v_item_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.delivery_challan_items WHERE id = v_item_id AND challan_id = p_challan_id) THEN\n      UPDATE public.delivery_challan_items SET\n        product_id = v_product_id,\n        batch_id = v_batch_id,\n        sales_order_item_id = v_so_item_id,\n        quantity = v_new_qty,\n        pack_size = NULLIF(v_item->>'pack_size', '')::numeric,\n        pack_type = NULLIF(v_item->>'pack_type', ''),\n        number_of_packs = NULLIF(v_item->>'number_of_packs', '')::integer\n      WHERE id = v_item_id;\n\n      v_kept_ids := array_append(v_kept_ids, v_item_id);\n    ELSE\n      v_item_id := COALESCE(v_item_id, gen_random_uuid());\n      INSERT INTO public.delivery_challan_items (\n        id, challan_id, product_id, batch_id, sales_order_item_id, quantity,\n        pack_size, pack_type, number_of_packs\n      ) VALUES (\n        v_item_id, p_challan_id, v_product_id, v_batch_id, v_so_item_id, v_new_qty,\n        NULLIF(v_item->>'pack_size', '')::numeric,\n        NULLIF(v_item->>'pack_type', ''),\n        NULLIF(v_item->>'number_of_packs', '')::integer\n      );\n      v_kept_ids := array_append(v_kept_ids, v_item_id);\n    END IF;\n  END LOOP;\n\n  -- Remove any DC items that were not in the updated item list\n  DELETE FROM public.delivery_challan_items\n  WHERE challan_id = p_challan_id\n    AND id <> ALL(v_kept_ids);\n\n  PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n  PERFORM set_config('app.sales_invoice_cancel', 'false', true);\n\n  RETURN jsonb_build_object('success', true, 'message', 'Delivery challan updated successfully');\n\nEXCEPTION\n  WHEN foreign_key_violation THEN\n    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n    PERFORM set_config('app.sales_invoice_cancel', 'false', true);\n    RAISE EXCEPTION 'Invalid product or batch selection: %', SQLERRM;\n  WHEN OTHERS THEN\n    PERFORM set_config('app.skip_dc_item_trigger', 'false', true);\n    PERFORM set_config('app.sales_invoice_cancel', 'false', true);\n    RAISE EXCEPTION '%', SQLERRM;\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.edit_delivery_challan(uuid, jsonb, jsonb) TO authenticated;\n\nCOMMIT;\n"}	fix_dc_quantity_validation_and_trigger_exclusion	simplykool@gmail.com	\N	\N
20261028051130	{"-- Exclude cancelled invoices when calculating remaining Delivery Challan quantity.\n-- Keeps the invoice creation RPC consistent with dc_item_invoice_status and the UI.\nBEGIN;\nCREATE OR REPLACE FUNCTION public.create_sales_invoice_atomic(p_invoice jsonb, p_items jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_role text;\n  v_invoice_id uuid;\n  v_subtotal numeric := 0;\n  v_tax numeric := 0;\n  v_discount numeric := COALESCE((p_invoice->>'discount_amount')::numeric, 0);\n  v_stamp numeric := COALESCE((p_invoice->>'stamp_duty_amount')::numeric, 0);\n  v_total numeric;\n  v_count integer := 0;\n  v_item jsonb;\n  v_product uuid;\n  v_batch uuid;\n  v_dc_item uuid;\n  v_qty numeric;\n  v_price numeric;\n  v_rate numeric;\n  v_dc record;\n  v_linked_challans uuid[];\n  v_invoice_so_id uuid := NULLIF(p_invoice->>'sales_order_id','')::uuid;\nBEGIN\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n  IF v_role IS NULL OR v_role NOT IN ('admin', 'accounts', 'sales','warehouse') THEN\n    RAISE EXCEPTION 'Permission denied: role % cannot create sales invoices', v_role;\n  END IF;\n  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN\n    RAISE EXCEPTION 'Sales invoice requires at least one product line';\n  END IF;\n  IF NULLIF(p_invoice->>'invoice_number','') IS NULL OR NULLIF(p_invoice->>'customer_id','') IS NULL THEN\n    RAISE EXCEPTION 'Invoice number and customer are required';\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.sales_invoices WHERE invoice_number=p_invoice->>'invoice_number') THEN\n    RAISE EXCEPTION 'Invoice number already exists';\n  END IF;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)\n  LOOP\n    v_product := NULLIF(v_item->>'product_id','')::uuid;\n    v_batch := NULLIF(v_item->>'batch_id','')::uuid;\n    v_dc_item := NULLIF(v_item->>'delivery_challan_item_id','')::uuid;\n    v_qty := (v_item->>'quantity')::numeric;\n    v_price := (v_item->>'unit_price')::numeric;\n    v_rate := COALESCE((v_item->>'tax_rate')::numeric, 0);\n    IF v_product IS NULL OR v_dc_item IS NULL OR COALESCE(v_qty,0) <= 0 OR COALESCE(v_price,0) < 0 THEN\n      RAISE EXCEPTION 'Every invoice line must have a source Delivery Challan item, product, quantity, and price';\n    END IF;\n    SELECT dci.product_id,dci.batch_id,dci.quantity,dc.customer_id,dc.approval_status,dc.sales_order_id\n      INTO v_dc\n    FROM public.delivery_challan_items dci\n    JOIN public.delivery_challans dc ON dc.id=dci.challan_id\n    WHERE dci.id=v_dc_item\n    FOR SHARE;\n    IF NOT FOUND OR v_dc.product_id IS DISTINCT FROM v_product OR v_dc.batch_id IS DISTINCT FROM v_batch\n       OR v_dc.customer_id IS DISTINCT FROM (p_invoice->>'customer_id')::uuid\n       OR v_dc.approval_status <> 'approved' THEN\n      RAISE EXCEPTION 'Invoice line source Delivery Challan is invalid or not approved';\n    END IF;\n    IF v_invoice_so_id IS NOT NULL AND v_dc.sales_order_id IS DISTINCT FROM v_invoice_so_id THEN\n      RAISE EXCEPTION 'Invoice Sales Order does not match its Delivery Challan source';\n    END IF;\n    IF v_qty > v_dc.quantity - COALESCE((SELECT sum(sii.quantity)\n      FROM public.sales_invoice_items sii\n      JOIN public.sales_invoices si ON si.id = sii.invoice_id\n      WHERE sii.delivery_challan_item_id = v_dc_item\n        AND NOT (COALESCE(si.notes, '') LIKE '[CANCELLED%'\n                 OR LOWER(COALESCE(si.notes, '')) LIKE 'cancelled%')), 0) THEN\n      RAISE EXCEPTION 'Invoice quantity exceeds remaining Delivery Challan quantity';\n    END IF;\n    v_subtotal := v_subtotal + (v_qty * v_price);\n    v_tax := v_tax + (v_qty * v_price * v_rate / 100);\n    v_count := v_count + 1;\n  END LOOP;\n  v_total := v_subtotal + v_tax - v_discount + v_stamp;\n  SELECT array_agg(DISTINCT dc.id) INTO v_linked_challans\n  FROM public.delivery_challan_items dci\n  JOIN public.delivery_challans dc ON dc.id=dci.challan_id\n  WHERE dci.id IN (SELECT (value->>'delivery_challan_item_id')::uuid FROM jsonb_array_elements(p_items));\n  IF p_invoice ? 'subtotal' AND abs(v_subtotal - (p_invoice->>'subtotal')::numeric) > 0.01\n     OR p_invoice ? 'tax_amount' AND abs(v_tax - (p_invoice->>'tax_amount')::numeric) > 0.01\n     OR p_invoice ? 'total_amount' AND abs(v_total - (p_invoice->>'total_amount')::numeric) > 0.01 THEN\n    RAISE EXCEPTION 'Invoice totals do not match persisted product lines';\n  END IF;\n\n  INSERT INTO public.sales_invoices (\n    invoice_number,customer_id,sales_order_id,invoice_date,due_date,discount_amount,\n    delivery_challan_number,po_number,payment_terms_days,notes,subtotal,tax_amount,\n    stamp_duty_amount,total_amount,payment_status,created_by,linked_challan_ids\n  ) VALUES (\n    p_invoice->>'invoice_number',(p_invoice->>'customer_id')::uuid,v_invoice_so_id,\n    COALESCE((p_invoice->>'invoice_date')::date,CURRENT_DATE),(p_invoice->>'due_date')::date,v_discount,\n    NULL,p_invoice->>'po_number',(p_invoice->>'payment_terms_days')::integer,p_invoice->>'notes',\n    v_subtotal,v_tax,v_stamp,v_total,'pending',COALESCE(NULLIF(p_invoice->>'created_by','')::uuid,auth.uid()),\n    COALESCE(v_linked_challans, CASE WHEN jsonb_typeof(p_invoice->'linked_challan_ids')='array' THEN\n      ARRAY(SELECT jsonb_array_elements_text(p_invoice->'linked_challan_ids')::uuid) ELSE NULL END)\n  ) RETURNING id INTO v_invoice_id;\n\n  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)\n  LOOP\n    INSERT INTO public.sales_invoice_items\n      (invoice_id,product_id,batch_id,quantity,unit_price,tax_rate,delivery_challan_item_id)\n    VALUES (v_invoice_id,(v_item->>'product_id')::uuid,NULLIF(v_item->>'batch_id','')::uuid,\n      (v_item->>'quantity')::numeric,(v_item->>'unit_price')::numeric,\n      COALESCE((v_item->>'tax_rate')::numeric,0),(v_item->>'delivery_challan_item_id')::uuid);\n  END LOOP;\n\n  IF (SELECT count(*) FROM public.sales_invoice_items WHERE invoice_id=v_invoice_id) <> v_count THEN\n    RAISE EXCEPTION 'Invoice line count verification failed';\n  END IF;\n  RETURN v_invoice_id;\nEND;\n$function$;\nGRANT EXECUTE ON FUNCTION public.create_sales_invoice_atomic(jsonb, jsonb) TO authenticated;\nCOMMIT;\n"}	fix_cancelled_invoice_dc_quantity_validation	simplykool@gmail.com	\N	\N
20261028115203	{"-- Migration: 20261028190000_fix_receivables_rounding_and_write_scope.sql\n-- Description: Unblock sales invoice settlement rounding adjustments in enforce_sales_invoice_write_scope\n-- and ensure recalculate_sales_invoice_payment_state synchronizes balance_amount alongside paid_amount and payment_status.\n\n-- 1. Update enforce_sales_invoice_write_scope to include invoice rounding adjustments when validating paid status\nCREATE OR REPLACE FUNCTION public.enforce_sales_invoice_write_scope()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_role text;\n  v_paid_actual numeric;\nBEGIN\n  -- Cascading updates from other triggers (e.g. recalculate_invoice_payment_status) are trusted\n  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;\n  IF auth.role() = 'service_role' THEN RETURN NEW; END IF;\n\n  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid();\n\n  IF v_role NOT IN ('admin','accounts') THEN\n    IF NEW.payment_status IS DISTINCT FROM OLD.payment_status\n       OR NEW.paid_amount    IS DISTINCT FROM OLD.paid_amount\n       OR NEW.total_amount   IS DISTINCT FROM OLD.total_amount\n       OR NEW.customer_id    IS DISTINCT FROM OLD.customer_id THEN\n      RAISE EXCEPTION 'Sales/warehouse cannot modify invoice financial fields (payment_status, paid_amount, total_amount, customer_id)';\n    END IF;\n  END IF;\n\n  IF NEW.payment_status = 'paid' AND NEW.payment_status IS DISTINCT FROM OLD.payment_status THEN\n    SELECT COALESCE(SUM(allocated_amount), 0) + COALESCE(public.get_invoice_rounding_adjustment_amount(NEW.id), 0)\n    INTO v_paid_actual\n    FROM public.voucher_allocations\n    WHERE sales_invoice_id = NEW.id;\n\n    IF v_paid_actual < COALESCE(NEW.total_amount, 0) THEN\n      RAISE EXCEPTION 'Cannot mark invoice paid: allocated payments (%) < total (%)', v_paid_actual, NEW.total_amount;\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$function$;\n\n-- 2. Update recalculate_sales_invoice_payment_state to synchronize balance_amount alongside paid_amount and payment_status\nCREATE OR REPLACE FUNCTION public.recalculate_sales_invoice_payment_state(p_invoice_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_invoice record;\n  v_allocated numeric(18,2);\n  v_adjustment numeric(18,2);\n  v_paid numeric(18,2);\nBEGIN\n  SELECT id, total_amount\n  INTO v_invoice\n  FROM public.sales_invoices\n  WHERE id = p_invoice_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN;\n  END IF;\n\n  v_allocated := public.get_invoice_allocation_amount(p_invoice_id, NULL);\n  v_adjustment := public.get_invoice_rounding_adjustment_amount(p_invoice_id);\n\n  v_paid := LEAST(\n    GREATEST(COALESCE(v_allocated, 0) + COALESCE(v_adjustment, 0), 0),\n    COALESCE(v_invoice.total_amount, 0)\n  );\n\n  UPDATE public.sales_invoices\n  SET\n    paid_amount = v_paid,\n    balance_amount = GREATEST(COALESCE(v_invoice.total_amount, 0) - v_paid, 0),\n    payment_status = CASE\n      WHEN v_paid <= 0 THEN 'pending'\n      WHEN v_paid >= v_invoice.total_amount THEN 'paid'\n      ELSE 'partial'\n    END\n  WHERE id = p_invoice_id;\nEND;\n$function$;\n\n-- 3. Grants\nREVOKE ALL ON FUNCTION public.enforce_sales_invoice_write_scope() FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.enforce_sales_invoice_write_scope() TO authenticated, service_role;\n\nREVOKE ALL ON FUNCTION public.recalculate_sales_invoice_payment_state(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.recalculate_sales_invoice_payment_state(uuid) TO authenticated, service_role;\n\n"}	fix_receivables_rounding_and_write_scope	simplykool@gmail.com	\N	\N
20261028171454	{"-- Migration: 20261028233000_credit_note_type_classification.sql\n-- Purpose: Add explicit credit_note_type ('physical_return' vs 'commercial_credit')\n-- Ensures physical returns update inventory and reverse COGS, while commercial credits\n-- only generate AR/Revenue/PPN adjustments without moving physical stock or touching COGS.\n-- Preserves existing CN-26-0001 records and valid historical postings without duplication.\n-- Protects approved/posted physical returns from unauthorized transitions to commercial credits.\n-- ─────────────────────────────────────────────────────────────────────────────\n-- STEP 1: PRECONDITION INTEGRITY CHECKS (ABORT SAFELY ON ANY MISMATCH)\n-- ─────────────────────────────────────────────────────────────────────────────\nDO $$\nDECLARE\n  v_inv_count      integer;\n  v_inv            record;\n  v_cn_count       integer;\n  v_cn             record;\n  v_items_count    integer;\n  v_items_qty      numeric;\n  v_b108_qty       numeric;\n  v_b109_qty       numeric;\n  v_it_count       integer;\n  v_it_b108_qty    numeric;\n  v_it_b109_qty    numeric;\n  v_je_ar          record;\n  v_je_ar_lines    integer;\n  v_je_cogs        record;\n  v_je_cogs_lines  integer;\n  v_line_4300      record;\n  v_line_2130      record;\n  v_line_1120      record;\n  v_line_1130      record;\n  v_line_5100      record;\nBEGIN\n  -- 1. Check required Chart of Accounts codes\n  IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE code = '1120') THEN\n    RAISE EXCEPTION 'Precondition failed: Account 1120 (A/R) missing from Chart of Accounts';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE code = '4300') THEN\n    RAISE EXCEPTION 'Precondition failed: Account 4300 (Sales Returns) missing from Chart of Accounts';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE code = '1130') THEN\n    RAISE EXCEPTION 'Precondition failed: Account 1130 (Inventory) missing from Chart of Accounts';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE code = '5100') THEN\n    RAISE EXCEPTION 'Precondition failed: Account 5100 (COGS - Materials) missing from Chart of Accounts';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE code = '2130') THEN\n    RAISE EXCEPTION 'Precondition failed: Account 2130 (Output PPN) missing from Chart of Accounts';\n  END IF;\n  -- 2. Check existing function and trigger definitions\n  IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = '_post_credit_note_je') THEN\n    RAISE EXCEPTION 'Precondition failed: Function _post_credit_note_je does not exist';\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'trg_credit_note_inventory_v1') THEN\n    RAISE EXCEPTION 'Precondition failed: Function trg_credit_note_inventory_v1 does not exist';\n  END IF;\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_trigger\n     WHERE tgrelid = 'public.credit_notes'::regclass\n       AND tgname = 'trigger_credit_note_inventory_v1'\n       AND tgenabled = 'O'\n  ) THEN\n    RAISE EXCEPTION 'Precondition failed: Trigger trigger_credit_note_inventory_v1 missing or disabled on public.credit_notes';\n  END IF;\n  -- 3. Check invoice SAPJ-26-013 invariants (exact identity, single occurrence, settled state, zero balance)\n  SELECT count(*) INTO v_inv_count FROM public.sales_invoices WHERE invoice_number = 'SAPJ-26-013';\n  IF v_inv_count != 1 THEN\n    RAISE EXCEPTION 'Precondition failed: SAPJ-26-013 count is %, expected exactly 1', v_inv_count;\n  END IF;\n  SELECT id, payment_status, total_amount, balance_amount\n    INTO v_inv\n    FROM public.sales_invoices\n   WHERE invoice_number = 'SAPJ-26-013';\n  IF v_inv.id != '03162b99-b06b-475b-b00c-e14cb9dd6123'::uuid THEN\n    RAISE EXCEPTION 'Precondition failed: SAPJ-26-013 ID is %, expected 03162b99-b06b-475b-b00c-e14cb9dd6123', v_inv.id;\n  END IF;\n  IF v_inv.payment_status != 'paid' THEN\n    RAISE EXCEPTION 'Precondition failed: SAPJ-26-013 payment_status is %, expected paid', v_inv.payment_status;\n  END IF;\n  IF v_inv.balance_amount != 0.00 THEN\n    RAISE EXCEPTION 'Precondition failed: SAPJ-26-013 balance_amount is %, expected 0.00', v_inv.balance_amount;\n  END IF;\n  IF v_inv.total_amount != 251328420.00 THEN\n    RAISE EXCEPTION 'Precondition failed: SAPJ-26-013 total_amount is %, expected 251328420.00', v_inv.total_amount;\n  END IF;\n  -- 4. Check CN-26-0001 invariants (exact identity, single occurrence, approved status, amounts, journal link)\n  SELECT count(*) INTO v_cn_count FROM public.credit_notes WHERE credit_note_number = 'CN-26-0001';\n  IF v_cn_count != 1 THEN\n    RAISE EXCEPTION 'Precondition failed: CN-26-0001 count is %, expected exactly 1', v_cn_count;\n  END IF;\n  SELECT id, status, total_amount, subtotal, tax_amount, material_return_id, journal_entry_id\n    INTO v_cn\n    FROM public.credit_notes\n   WHERE credit_note_number = 'CN-26-0001';\n  IF v_cn.id != '83953d95-7baf-4a07-b7c5-b63d6f08945c'::uuid THEN\n    RAISE EXCEPTION 'Precondition failed: CN-26-0001 ID is %, expected 83953d95-7baf-4a07-b7c5-b63d6f08945c', v_cn.id;\n  END IF;\n  IF v_cn.status != 'approved' THEN\n    RAISE EXCEPTION 'Precondition failed: CN-26-0001 status is %, expected approved', v_cn.status;\n  END IF;\n  IF v_cn.journal_entry_id != 'e5485488-ad57-442c-8e02-c98619cbc240'::uuid THEN\n    RAISE EXCEPTION 'Precondition failed: CN-26-0001 journal_entry_id mismatch';\n  END IF;\n  IF v_cn.total_amount != 1745336.25 OR v_cn.subtotal != 1572375.00 OR v_cn.tax_amount != 172961.25 THEN\n    RAISE EXCEPTION 'Precondition failed: CN-26-0001 financial amounts mismatch';\n  END IF;\n  -- 5. Check CN-26-0001 line items (exactly 2 items, 125 kg total: B108/2026 100 kg, B109/2026 25 kg)\n  SELECT count(*), COALESCE(SUM(quantity), 0)\n    INTO v_items_count, v_items_qty\n    FROM public.credit_note_items\n   WHERE credit_note_id = v_cn.id;\n  IF v_items_count != 2 OR v_items_qty != 125.000 THEN\n    RAISE EXCEPTION 'Precondition failed: CN-26-0001 items count %, qty %, expected 2 items totaling 125.000 kg', v_items_count, v_items_qty;\n  END IF;\n  SELECT COALESCE(SUM(cni.quantity), 0) INTO v_b108_qty\n    FROM public.credit_note_items cni\n    JOIN public.batches b ON b.id = cni.batch_id\n   WHERE cni.credit_note_id = v_cn.id AND b.batch_number = 'B108/2026';\n  IF v_b108_qty != 100.000 THEN\n    RAISE EXCEPTION 'Precondition failed: B108/2026 qty is %, expected 100.000 kg', v_b108_qty;\n  END IF;\n  SELECT COALESCE(SUM(cni.quantity), 0) INTO v_b109_qty\n    FROM public.credit_note_items cni\n    JOIN public.batches b ON b.id = cni.batch_id\n   WHERE cni.credit_note_id = v_cn.id AND b.batch_number = 'B109/2026';\n  IF v_b109_qty != 25.000 THEN\n    RAISE EXCEPTION 'Precondition failed: B109/2026 qty is %, expected 25.000 kg', v_b109_qty;\n  END IF;\n  -- 6. Check inventory return transactions for CN-26-0001\n  SELECT count(*) INTO v_it_count\n    FROM public.inventory_transactions\n   WHERE reference_id = v_cn.id AND transaction_type = 'return';\n  IF v_it_count != 2 THEN\n    RAISE EXCEPTION 'Precondition failed: CN-26-0001 inventory return movements count is %, expected 2', v_it_count;\n  END IF;\n  SELECT COALESCE(SUM(it.quantity), 0) INTO v_it_b108_qty\n    FROM public.inventory_transactions it\n    JOIN public.batches b ON b.id = it.batch_id\n   WHERE it.reference_id = v_cn.id AND it.transaction_type = 'return' AND b.batch_number = 'B108/2026';\n  IF v_it_b108_qty != 100.000 THEN\n    RAISE EXCEPTION 'Precondition failed: Inventory return B108/2026 qty is %, expected 100.000 kg', v_it_b108_qty;\n  END IF;\n  SELECT COALESCE(SUM(it.quantity), 0) INTO v_it_b109_qty\n    FROM public.inventory_transactions it\n    JOIN public.batches b ON b.id = it.batch_id\n   WHERE it.reference_id = v_cn.id AND it.transaction_type = 'return' AND b.batch_number = 'B109/2026';\n  IF v_it_b109_qty != 25.000 THEN\n    RAISE EXCEPTION 'Precondition failed: Inventory return B109/2026 qty is %, expected 25.000 kg', v_it_b109_qty;\n  END IF;\n  -- 7. Check AR Journal JE2610-0219 (header, lines, accounts, posting status)\n  SELECT id, entry_number, total_debit, total_credit, is_posted\n    INTO v_je_ar\n    FROM public.journal_entries\n   WHERE entry_number = 'JE2610-0219';\n  IF v_je_ar.id IS NULL OR NOT v_je_ar.is_posted OR v_je_ar.total_debit != 1745336.25 OR v_je_ar.total_credit != 1745336.25 THEN\n    RAISE EXCEPTION 'Precondition failed: JE2610-0219 header is invalid or unposted';\n  END IF;\n  SELECT count(*) INTO v_je_ar_lines\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id = v_je_ar.id;\n  IF v_je_ar_lines != 3 THEN\n    RAISE EXCEPTION 'Precondition failed: JE2610-0219 lines count is %, expected 3', v_je_ar_lines;\n  END IF;\n  SELECT debit, credit INTO v_line_4300\n    FROM public.journal_entry_lines jel\n    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n   WHERE jel.journal_entry_id = v_je_ar.id AND coa.code = '4300';\n  IF v_line_4300.debit != 1572375.00 OR v_line_4300.credit != 0.00 THEN\n    RAISE EXCEPTION 'Precondition failed: JE2610-0219 Line 4300 (Sales Returns) mismatch';\n  END IF;\n  SELECT debit, credit INTO v_line_2130\n    FROM public.journal_entry_lines jel\n    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n   WHERE jel.journal_entry_id = v_je_ar.id AND coa.code = '2130';\n  IF v_line_2130.debit != 172961.25 OR v_line_2130.credit != 0.00 THEN\n    RAISE EXCEPTION 'Precondition failed: JE2610-0219 Line 2130 (Output PPN) mismatch';\n  END IF;\n  SELECT debit, credit INTO v_line_1120\n    FROM public.journal_entry_lines jel\n    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n   WHERE jel.journal_entry_id = v_je_ar.id AND coa.code = '1120';\n  IF v_line_1120.debit != 0.00 OR v_line_1120.credit != 1745336.25 THEN\n    RAISE EXCEPTION 'Precondition failed: JE2610-0219 Line 1120 (A/R) mismatch';\n  END IF;\n  -- 8. Check COGS Journal JE2610-0220 (header, lines, accounts, posting status)\n  SELECT id, entry_number, total_debit, total_credit, is_posted\n    INTO v_je_cogs\n    FROM public.journal_entries\n   WHERE entry_number = 'JE2610-0220';\n  IF v_je_cogs.id IS NULL OR NOT v_je_cogs.is_posted OR v_je_cogs.total_debit != 1227102.50 OR v_je_cogs.total_credit != 1227102.50 THEN\n    RAISE EXCEPTION 'Precondition failed: JE2610-0220 header is invalid or unposted';\n  END IF;\n  SELECT count(*) INTO v_je_cogs_lines\n    FROM public.journal_entry_lines\n   WHERE journal_entry_id = v_je_cogs.id;\n  IF v_je_cogs_lines != 2 THEN\n    RAISE EXCEPTION 'Precondition failed: JE2610-0220 lines count is %, expected 2', v_je_cogs_lines;\n  END IF;\n  SELECT debit, credit INTO v_line_1130\n    FROM public.journal_entry_lines jel\n    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n   WHERE jel.journal_entry_id = v_je_cogs.id AND coa.code = '1130';\n  IF v_line_1130.debit != 1227102.50 OR v_line_1130.credit != 0.00 THEN\n    RAISE EXCEPTION 'Precondition failed: JE2610-0220 Line 1130 (Inventory) mismatch';\n  END IF;\n  SELECT debit, credit INTO v_line_5100\n    FROM public.journal_entry_lines jel\n    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n   WHERE jel.journal_entry_id = v_je_cogs.id AND coa.code = '5100';\n  IF v_line_5100.debit != 0.00 OR v_line_5100.credit != 1227102.50 THEN\n    RAISE EXCEPTION 'Precondition failed: JE2610-0220 Line 5100 (COGS - Materials) mismatch';\n  END IF;\n  RAISE NOTICE 'Comprehensive Preconditions PASSED: SAPJ-26-013, CN-26-0001, batches, stock movements, journal entries and schema definitions all verified.';\nEND $$;\n-- ─────────────────────────────────────────────────────────────────────────────\n-- STEP 2: ADD COLUMN credit_note_type (IF NOT EXISTS)\n-- ─────────────────────────────────────────────────────────────────────────────\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns \n    WHERE table_name = 'credit_notes' AND column_name = 'credit_note_type'\n  ) THEN\n    ALTER TABLE public.credit_notes \n      ADD COLUMN credit_note_type text\n      CONSTRAINT chk_credit_note_type CHECK (credit_note_type IN ('physical_return', 'commercial_credit'));\n  END IF;\nEND $$;\n-- ─────────────────────────────────────────────────────────────────────────────\n-- STEP 3: PRESERVE KNOWN CLASSIFICATIONS & CONSERVATIVE HISTORICAL BACKFILL\n-- ─────────────────────────────────────────────────────────────────────────────\n-- 1. CN-26-0001: Verified physical return of 125 kg Corn Starch BP with restocked batches\nUPDATE public.credit_notes\n   SET credit_note_type = 'physical_return'\n WHERE credit_note_number = 'CN-26-0001'\n   AND (credit_note_type IS NULL OR credit_note_type = 'physical_return');\n-- 2. Multi-dimensional positive classification for unclassified records (credit_note_type IS NULL)\n-- A record is classified as 'physical_return' ONLY when positive physical return evidence exists:\n--   - Linked to a material return\n--   - OR has physical inventory_transactions (return movement)\n--   - OR has a COGS reversal journal (source_module = 'credit_note_cogs')\n-- A record is classified as 'commercial_credit' ONLY when positive commercial evidence exists\n--   AND NO physical return or COGS evidence exists:\n--   - Approved status, commercial reason text (discount, price concession, rebate, rounding, etc.)\n--   - AND zero inventory transactions AND zero COGS journal entries.\n-- All other records remain NULL (unclassified) for manual audit and explicit user review.\nUPDATE public.credit_notes cn\n   SET credit_note_type = CASE\n     -- Positive physical return evidence\n     WHEN cn.material_return_id IS NOT NULL THEN 'physical_return'\n     WHEN EXISTS (\n       SELECT 1 FROM public.inventory_transactions it \n       WHERE it.reference_id = cn.id AND it.transaction_type = 'return'\n     ) THEN 'physical_return'\n     WHEN EXISTS (\n       SELECT 1 FROM public.journal_entries je \n       WHERE je.reference_id = cn.id AND je.source_module = 'credit_note_cogs'\n     ) THEN 'physical_return'\n     -- Positive commercial concession evidence (explicit commercial text + no stock/COGS movement)\n     WHEN cn.status = 'approved'\n       AND (\n         LOWER(cn.reason) ~* '(discount|price concession|commercial|rebate|rounding|allowance)'\n         OR LOWER(COALESCE(cn.notes, '')) ~* '(discount|price concession|commercial|rebate|rounding|allowance)'\n       )\n       AND NOT EXISTS (\n         SELECT 1 FROM public.inventory_transactions it \n         WHERE it.reference_id = cn.id\n       )\n       AND NOT EXISTS (\n         SELECT 1 FROM public.journal_entries je \n         WHERE je.reference_id = cn.id AND je.source_module = 'credit_note_cogs'\n       ) THEN 'commercial_credit'\n     -- Otherwise: leave unclassified (NULL) for manual review\n     ELSE NULL\n   END\n WHERE cn.credit_note_type IS NULL;\n-- Log audit notice for any remaining unclassified historical records\nDO $$\nDECLARE\n  v_unclassified_count integer;\nBEGIN\n  SELECT COUNT(*) INTO v_unclassified_count\n    FROM public.credit_notes\n   WHERE credit_note_type IS NULL;\n  IF v_unclassified_count > 0 THEN\n    RAISE NOTICE 'Audit Notice: % credit note(s) remain unclassified (NULL) pending manual review.', v_unclassified_count;\n  ELSE\n    RAISE NOTICE 'Audit Notice: All existing credit notes successfully classified with verified positive evidence.';\n  END IF;\nEND $$;\n-- Set default for future rows now that historical data is safely backfilled\nALTER TABLE public.credit_notes \n  ALTER COLUMN credit_note_type SET DEFAULT 'physical_return';\n-- ─────────────────────────────────────────────────────────────────────────────\n-- STEP 4: TRANSITION GUARD TRIGGER (PREVENTS UNAUTHORIZED TYPE MUTATIONS)\n-- ─────────────────────────────────────────────────────────────────────────────\nCREATE OR REPLACE FUNCTION public.trg_guard_credit_note_type_transition()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nBEGIN\n  IF (OLD.status = 'approved' OR OLD.journal_entry_id IS NOT NULL) \n     AND OLD.credit_note_type IS NOT NULL\n     AND OLD.credit_note_type IS DISTINCT FROM NEW.credit_note_type THEN\n    RAISE EXCEPTION 'Cannot modify credit_note_type on an approved or posted Credit Note (ID: %, Number: %) without a controlled reversal workflow.', \n      OLD.id, OLD.credit_note_number;\n  END IF;\n  RETURN NEW;\nEND;\n$$;\nDROP TRIGGER IF EXISTS trg_guard_credit_note_type_transition ON public.credit_notes;\nCREATE TRIGGER trg_guard_credit_note_type_transition\n  BEFORE UPDATE OF credit_note_type ON public.credit_notes\n  FOR EACH ROW\n  EXECUTE FUNCTION public.trg_guard_credit_note_type_transition();\n-- ─────────────────────────────────────────────────────────────────────────────\n-- STEP 5: UPDATE INVENTORY TRIGGER FUNCTION\n-- ─────────────────────────────────────────────────────────────────────────────\nCREATE OR REPLACE FUNCTION public.trg_credit_note_inventory_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_item record;\nBEGIN\n  -- Commercial credit notes NEVER move physical inventory\n  IF NEW.credit_note_type = 'commercial_credit' THEN\n    RETURN NEW;\n  END IF;\n  -- For Credit Notes linked to a Material Return, the Material Return owns inventory\n  IF COALESCE(NEW.material_return_id, OLD.material_return_id) IS NOT NULL THEN\n    RETURN NEW;\n  END IF;\n  -- Standalone physical return credit notes (credit_note_type = 'physical_return')\n  IF NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved' THEN\n    IF EXISTS (\n      SELECT 1\n      FROM public.inventory_transactions\n      WHERE reference_type = 'credit_note_reversal'\n        AND reference_id = NEW.id\n        AND metadata->>'canonical_engine_version' = '1.0'\n    ) THEN\n      RAISE EXCEPTION 'Reversed Credit Note cannot be re-approved; create a new Credit Note';\n    END IF;\n    FOR v_item IN\n      SELECT *\n      FROM public.credit_note_items\n      WHERE credit_note_id = NEW.id\n      ORDER BY id\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text('inventory-v1:credit-note:' || NEW.id || ':' || v_item.id),\n        v_item.product_id,\n        v_item.batch_id,\n        'return',\n        v_item.quantity,\n        NEW.credit_note_date,\n        NEW.credit_note_number,\n        'credit_note',\n        NEW.id,\n        'Canonical Credit Note return: ' || NEW.credit_note_number,\n        NEW.approved_by,\n        NULL,\n        NULL\n      );\n    END LOOP;\n  ELSIF OLD.status = 'approved' AND NEW.status IS DISTINCT FROM 'approved' THEN\n    FOR v_item IN\n      SELECT *\n      FROM public.credit_note_items\n      WHERE credit_note_id = NEW.id\n      ORDER BY id\n    LOOP\n      PERFORM public.post_inventory_movement(\n        public.uuid_from_text(\n          'inventory-v1:credit-note-reversal:' || NEW.id || ':' || v_item.id\n        ),\n        v_item.product_id,\n        v_item.batch_id,\n        'adjustment',\n        -v_item.quantity,\n        CURRENT_DATE,\n        NEW.credit_note_number,\n        'credit_note_reversal',\n        NEW.id,\n        'Canonical Credit Note reversal: ' || NEW.credit_note_number,\n        COALESCE(NEW.approved_by, auth.uid()),\n        NULL,\n        NULL\n      );\n    END LOOP;\n  END IF;\n  RETURN NEW;\nEND;\n$function$;\n-- ─────────────────────────────────────────────────────────────────────────────\n-- STEP 6: UPDATE COGS AND REVENUE POSTING FUNCTION\n-- ─────────────────────────────────────────────────────────────────────────────\nCREATE OR REPLACE FUNCTION public._post_credit_note_je(p_cn public.credit_notes)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_je_id         uuid;\n  v_je_cogs_id    uuid;\n  v_je_number     text;\n  v_ar_id         uuid;\n  v_return_id     uuid;\n  v_ppn_id        uuid;\n  v_cogs_id       uuid;\n  v_inv_id        uuid;\n  v_total_cogs    numeric(18,2) := 0;\n  v_item          record;\n  v_actor         uuid := COALESCE(p_cn.approved_by, p_cn.created_by);\n  v_unit_cogs     numeric(18,4);\n  v_orig_inv_id   uuid;\nBEGIN\n  SELECT id INTO v_ar_id     FROM chart_of_accounts WHERE code = '1120';\n  SELECT id INTO v_return_id FROM chart_of_accounts WHERE code = '4300';\n  SELECT id INTO v_ppn_id    FROM chart_of_accounts WHERE code = '2130';\n  SELECT id INTO v_cogs_id   FROM chart_of_accounts WHERE code = '5100';\n  SELECT id INTO v_inv_id    FROM chart_of_accounts WHERE code = '1130';\n  IF v_ar_id IS NULL OR v_return_id IS NULL THEN\n    RAISE EXCEPTION 'Credit Note JE: missing required accounts (1120 A/R or 4300 Sales Returns) in Chart of Accounts';\n  END IF;\n  -- ── 1. Revenue & Receivables Reversal JE (posted for BOTH types) ──\n  v_je_number := public.next_journal_entry_number();\n  INSERT INTO journal_entries\n    (entry_number, entry_date, source_module, reference_id, reference_number,\n     description, total_debit, total_credit, is_posted, posted_by, created_by)\n  VALUES\n    (v_je_number, p_cn.credit_note_date, 'credit_note', p_cn.id, p_cn.credit_note_number,\n     'Credit Note reversal — ' || p_cn.credit_note_number,\n     p_cn.total_amount, p_cn.total_amount, true, v_actor, v_actor)\n  RETURNING id INTO v_je_id;\n  -- Dr Sales Return (subtotal — contra revenue)\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, 1, v_return_id,\n          'Sales Return - ' || p_cn.credit_note_number,\n          p_cn.subtotal, 0, p_cn.customer_id);\n  -- Dr Output PPN (reduces tax liability)\n  IF COALESCE(p_cn.tax_amount, 0) > 0 AND v_ppn_id IS NOT NULL THEN\n    INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n    VALUES (v_je_id, 2, v_ppn_id,\n            'Output PPN reversal - ' || p_cn.credit_note_number,\n            p_cn.tax_amount, 0, p_cn.customer_id);\n  END IF;\n  -- Cr A/R (reduces customer receivable)\n  INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n  VALUES (v_je_id, 3, v_ar_id,\n          'A/R reversal - ' || p_cn.credit_note_number,\n          0, p_cn.total_amount, p_cn.customer_id);\n  -- ── 2. COGS-reversal JE (Dr Inventory, Cr COGS) ──\n  -- ONLY posted for physical goods returns; commercial credits do not affect inventory or COGS\n  IF p_cn.credit_note_type = 'physical_return' AND v_cogs_id IS NOT NULL AND v_inv_id IS NOT NULL THEN\n    v_orig_inv_id := p_cn.original_invoice_id;\n    IF v_orig_inv_id IS NULL AND p_cn.material_return_id IS NOT NULL THEN\n      SELECT mr.original_invoice_id INTO v_orig_inv_id\n        FROM public.material_returns mr\n       WHERE mr.id = p_cn.material_return_id;\n      IF v_orig_inv_id IS NULL THEN\n        SELECT si.id INTO v_orig_inv_id\n          FROM public.material_returns mr\n          JOIN public.sales_invoices si ON mr.original_dc_id::text = ANY(si.linked_challan_ids)\n         WHERE mr.id = p_cn.material_return_id\n         LIMIT 1;\n      END IF;\n    END IF;\n    FOR v_item IN\n      SELECT cni.quantity, cni.batch_id, cni.product_id\n        FROM credit_note_items cni\n       WHERE cni.credit_note_id = p_cn.id\n    LOOP\n      v_unit_cogs := NULL;\n      -- 1. Exact historical FIFO cost from original sales invoice line\n      IF v_orig_inv_id IS NOT NULL THEN\n        SELECT COALESCE(sii.cogs_unit_cost, CASE WHEN sii.quantity > 0 THEN ROUND(sii.cogs_total_cost / sii.quantity, 4) ELSE NULL END)\n          INTO v_unit_cogs\n          FROM public.sales_invoice_items sii\n         WHERE sii.invoice_id = v_orig_inv_id\n           AND (\n             (v_item.batch_id IS NOT NULL AND sii.batch_id = v_item.batch_id)\n             OR (v_item.batch_id IS NULL AND sii.product_id = v_item.product_id)\n           )\n           AND ((sii.cogs_unit_cost IS NOT NULL AND sii.cogs_unit_cost > 0) OR (sii.cogs_total_cost IS NOT NULL AND sii.cogs_total_cost > 0))\n         ORDER BY sii.created_at\n         LIMIT 1;\n      END IF;\n      -- 1b. Fallback to delivery challan items if linked via material return\n      IF (v_unit_cogs IS NULL OR v_unit_cogs <= 0) AND p_cn.material_return_id IS NOT NULL THEN\n        SELECT COALESCE(b.landed_cost_per_unit, b.cost_per_unit, 0) INTO v_unit_cogs\n          FROM public.material_returns mr\n          JOIN public.delivery_challan_items dci ON dci.challan_id = mr.original_dc_id\n          JOIN public.batches b ON b.id = dci.batch_id\n         WHERE mr.id = p_cn.material_return_id\n           AND (\n             (v_item.batch_id IS NOT NULL AND dci.batch_id = v_item.batch_id)\n             OR (v_item.batch_id IS NULL AND dci.product_id = v_item.product_id)\n           )\n         LIMIT 1;\n      END IF;\n      -- 1c. Fallback to batch landed cost\n      IF v_unit_cogs IS NULL OR v_unit_cogs <= 0 THEN\n        SELECT COALESCE(b.landed_cost_per_unit, b.cost_per_unit, 0) INTO v_unit_cogs\n          FROM public.batches b\n         WHERE b.id = v_item.batch_id;\n      END IF;\n      v_total_cogs := v_total_cogs + ROUND(v_item.quantity * COALESCE(v_unit_cogs, 0), 2);\n    END LOOP;\n    IF v_total_cogs > 0 THEN\n      v_je_number := public.next_journal_entry_number();\n      INSERT INTO journal_entries\n        (entry_number, entry_date, source_module, reference_id, reference_number,\n         description, total_debit, total_credit, is_posted, posted_by, created_by)\n      VALUES\n        (v_je_number, p_cn.credit_note_date, 'credit_note_cogs', p_cn.id, p_cn.credit_note_number,\n         'Historical FIFO COGS reversal for Credit Note ' || p_cn.credit_note_number,\n         v_total_cogs, v_total_cogs, true, v_actor, v_actor)\n      RETURNING id INTO v_je_cogs_id;\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit)\n      VALUES (v_je_cogs_id, 1, v_inv_id,\n              'Inventory restock - ' || p_cn.credit_note_number,\n              v_total_cogs, 0);\n      INSERT INTO journal_entry_lines (journal_entry_id, line_number, account_id, description, debit, credit, customer_id)\n      VALUES (v_je_cogs_id, 2, v_cogs_id,\n              'COGS reversal - ' || p_cn.credit_note_number,\n              0, v_total_cogs, p_cn.customer_id);\n    END IF;\n  END IF;\n  RETURN v_je_id;\nEND;\n$$;"}	credit_note_type_classification	simplykool@gmail.com	\N	\N
