20261103183311	{"\nCREATE OR REPLACE FUNCTION public.get_pnl_summary(\n  p_start_date date,\n  p_end_date date,\n  p_usd_rate numeric\n)\nRETURNS TABLE(total_revenue numeric, total_expenses numeric, net_income numeric)\nLANGUAGE sql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\n  SELECT\n    COALESCE(SUM(\n      CASE\n        WHEN coa.account_type = 'revenue'\n          THEN (jel.credit - jel.debit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)\n        WHEN coa.account_type = 'contra' AND coa.account_group = 'Revenue'\n          THEN (jel.credit - jel.debit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)\n        ELSE 0\n      END\n    ), 0)::numeric AS total_revenue,\n    COALESCE(SUM(\n      CASE WHEN coa.account_type = 'expense'\n        THEN (jel.debit - jel.credit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)\n        ELSE 0\n      END\n    ), 0)::numeric AS total_expenses,\n    (\n      COALESCE(SUM(\n        CASE\n          WHEN coa.account_type = 'revenue'\n            THEN (jel.credit - jel.debit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)\n          WHEN coa.account_type = 'contra' AND coa.account_group = 'Revenue'\n            THEN (jel.credit - jel.debit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)\n          ELSE 0\n        END\n      ), 0)\n      -\n      COALESCE(SUM(\n        CASE WHEN coa.account_type = 'expense'\n          THEN (jel.debit - jel.credit) * public.get_journal_reporting_multiplier(je.id, p_usd_rate)\n          ELSE 0\n        END\n      ), 0)\n    )::numeric AS net_income\n  FROM public.journal_entry_lines jel\n  JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n  JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n  WHERE je.is_posted = true\n    AND NOT COALESCE(je.is_reversed, false)\n    AND je.entry_date BETWEEN p_start_date AND p_end_date;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.get_pnl_summary_detailed(\n  p_start_date date,\n  p_end_date date,\n  p_usd_rate numeric\n)\nRETURNS TABLE(\n  gross_commercial_sales numeric,\n  sales_discounts numeric,\n  sales_returns numeric,\n  net_commercial_sales numeric,\n  other_income numeric,\n  fx_gain numeric,\n  cogs numeric,\n  operating_expenses numeric,\n  other_expenses numeric,\n  bank_charges numeric,\n  fx_loss numeric,\n  total_expenses numeric,\n  total_income numeric,\n  net_income numeric\n)\nLANGUAGE sql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\n  WITH ledger AS (\n    SELECT\n      coa.code,\n      coa.account_type,\n      coa.account_group,\n      (jel.credit - jel.debit)\n        * public.get_journal_reporting_multiplier(je.id, p_usd_rate) AS revenue_amount,\n      (jel.debit - jel.credit)\n        * public.get_journal_reporting_multiplier(je.id, p_usd_rate) AS expense_amount\n    FROM public.journal_entry_lines jel\n    JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n    WHERE je.is_posted = true\n      AND NOT COALESCE(je.is_reversed, false)\n      AND je.entry_date BETWEEN p_start_date AND p_end_date\n      AND COALESCE(coa.is_header, false) = false\n  ),\n  totals AS (\n    SELECT\n      COALESCE(SUM(revenue_amount) FILTER (\n        WHERE account_type = 'revenue' AND code IN ('4100','4110','4120')\n      ), 0)::numeric AS gross_commercial_sales,\n      COALESCE(SUM(expense_amount) FILTER (WHERE code = '4200'), 0)::numeric AS sales_discounts,\n      COALESCE(SUM(expense_amount) FILTER (WHERE code = '4300'), 0)::numeric AS sales_returns,\n      COALESCE(SUM(revenue_amount) FILTER (\n        WHERE account_type = 'revenue'\n          AND code NOT IN ('4100','4110','4120')\n      ), 0)::numeric AS other_income,\n      COALESCE(SUM(revenue_amount) FILTER (WHERE code = '4930'), 0)::numeric AS fx_gain,\n      COALESCE(SUM(expense_amount) FILTER (\n        WHERE account_type = 'expense' AND account_group = 'COGS'\n      ), 0)::numeric AS cogs,\n      COALESCE(SUM(expense_amount) FILTER (\n        WHERE account_type = 'expense'\n          AND COALESCE(account_group, '') NOT IN ('COGS','Other Expenses')\n      ), 0)::numeric AS operating_expenses,\n      COALESCE(SUM(expense_amount) FILTER (\n        WHERE account_type = 'expense'\n          AND account_group = 'Other Expenses'\n          AND code NOT IN ('7100','7300')\n      ), 0)::numeric AS other_expenses,\n      COALESCE(SUM(expense_amount) FILTER (WHERE code = '7100'), 0)::numeric AS bank_charges,\n      COALESCE(SUM(expense_amount) FILTER (WHERE code = '7300'), 0)::numeric AS fx_loss,\n      COALESCE(SUM(expense_amount) FILTER (WHERE account_type = 'expense'), 0)::numeric AS total_expenses\n    FROM ledger\n  )\n  SELECT\n    gross_commercial_sales,\n    sales_discounts,\n    sales_returns,\n    (gross_commercial_sales - sales_discounts - sales_returns)::numeric AS net_commercial_sales,\n    other_income,\n    fx_gain,\n    cogs,\n    operating_expenses,\n    other_expenses,\n    bank_charges,\n    fx_loss,\n    total_expenses,\n    (gross_commercial_sales - sales_discounts - sales_returns + other_income)::numeric AS total_income,\n    (gross_commercial_sales - sales_discounts - sales_returns + other_income - total_expenses)::numeric AS net_income\n  FROM totals;\n$function$;\n\nREVOKE ALL ON FUNCTION public.get_pnl_summary_detailed(date, date, numeric) FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.get_pnl_summary_detailed(date, date, numeric) FROM anon;\nGRANT EXECUTE ON FUNCTION public.get_pnl_summary_detailed(date, date, numeric) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.get_pnl_summary_detailed(date, date, numeric) TO service_role;\n"}	fix_pnl_contra_revenue_and_add_detailed_summary_v2	simplykool@gmail.com	\N	\N
20261103183504	{"\nCREATE OR REPLACE FUNCTION public.get_pnl_summary_detailed(\n  p_start_date date,\n  p_end_date date,\n  p_usd_rate numeric\n)\nRETURNS TABLE(\n  gross_commercial_sales numeric,\n  sales_discounts numeric,\n  sales_returns numeric,\n  net_commercial_sales numeric,\n  other_income numeric,\n  fx_gain numeric,\n  cogs numeric,\n  operating_expenses numeric,\n  other_expenses numeric,\n  bank_charges numeric,\n  fx_loss numeric,\n  total_expenses numeric,\n  total_income numeric,\n  net_income numeric\n)\nLANGUAGE sql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\n  WITH ledger AS (\n    SELECT\n      coa.code,\n      coa.account_type,\n      coa.account_group,\n      (jel.credit - jel.debit)\n        * public.get_journal_reporting_multiplier(je.id, p_usd_rate) AS revenue_amount,\n      (jel.debit - jel.credit)\n        * public.get_journal_reporting_multiplier(je.id, p_usd_rate) AS expense_amount\n    FROM public.journal_entry_lines jel\n    JOIN public.journal_entries je ON je.id = jel.journal_entry_id\n    JOIN public.chart_of_accounts coa ON coa.id = jel.account_id\n    WHERE je.is_posted = true\n      AND NOT COALESCE(je.is_reversed, false)\n      AND je.entry_date BETWEEN p_start_date AND p_end_date\n      AND COALESCE(coa.is_header, false) = false\n  ),\n  totals AS (\n    SELECT\n      COALESCE(SUM(revenue_amount) FILTER (\n        WHERE account_type = 'revenue' AND code IN ('4100','4110','4120')\n      ), 0)::numeric AS gross_commercial_sales,\n      COALESCE(SUM(expense_amount) FILTER (WHERE code = '4200'), 0)::numeric AS sales_discounts,\n      COALESCE(SUM(expense_amount) FILTER (WHERE code = '4300'), 0)::numeric AS sales_returns,\n      COALESCE(SUM(revenue_amount) FILTER (\n        WHERE account_type = 'revenue'\n          AND code NOT IN ('4100','4110','4120','4930')\n      ), 0)::numeric AS other_income,\n      COALESCE(SUM(revenue_amount) FILTER (WHERE code = '4930'), 0)::numeric AS fx_gain,\n      COALESCE(SUM(expense_amount) FILTER (\n        WHERE account_type = 'expense' AND account_group = 'COGS'\n      ), 0)::numeric AS cogs,\n      COALESCE(SUM(expense_amount) FILTER (\n        WHERE account_type = 'expense'\n          AND COALESCE(account_group, '') NOT IN ('COGS','Other Expenses')\n      ), 0)::numeric AS operating_expenses,\n      COALESCE(SUM(expense_amount) FILTER (\n        WHERE account_type = 'expense'\n          AND account_group = 'Other Expenses'\n          AND code NOT IN ('7100','7300')\n      ), 0)::numeric AS other_expenses,\n      COALESCE(SUM(expense_amount) FILTER (WHERE code = '7100'), 0)::numeric AS bank_charges,\n      COALESCE(SUM(expense_amount) FILTER (WHERE code = '7300'), 0)::numeric AS fx_loss,\n      COALESCE(SUM(expense_amount) FILTER (WHERE account_type = 'expense'), 0)::numeric AS total_expenses\n    FROM ledger\n  )\n  SELECT\n    gross_commercial_sales,\n    sales_discounts,\n    sales_returns,\n    (gross_commercial_sales - sales_discounts - sales_returns)::numeric AS net_commercial_sales,\n    other_income,\n    fx_gain,\n    cogs,\n    operating_expenses,\n    other_expenses,\n    bank_charges,\n    fx_loss,\n    total_expenses,\n    (gross_commercial_sales - sales_discounts - sales_returns + other_income + fx_gain)::numeric AS total_income,\n    (gross_commercial_sales - sales_discounts - sales_returns + other_income + fx_gain - total_expenses)::numeric AS net_income\n  FROM totals;\n$function$;\n"}	separate_fx_gain_from_other_income_in_detailed_pnl	simplykool@gmail.com	\N	\N
20261103235405	{"\nCREATE OR REPLACE FUNCTION public.auto_reconcile_bank_statement(p_upload_id uuid DEFAULT NULL::uuid)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_line RECORD;\n  v_pv RECORD;\n  v_rv RECORD;\n  v_exp RECORD;\n  v_ft RECORD;\n  v_tax RECORD;\n  v_matched_count INTEGER := 0;\n  v_conflict_count INTEGER := 0;\n  v_candidate_count INTEGER := 0;\n  v_matched_id UUID;\n  v_matched_type TEXT;\nBEGIN\n  PERFORM public._sec_check_finance_role();\n\n  FOR v_line IN\n    SELECT bsl.*\n    FROM public.bank_statement_lines bsl\n    WHERE (p_upload_id IS NULL OR bsl.upload_id = p_upload_id)\n      AND bsl.reconciliation_status IN ('unmatched', 'suggested', 'conflict')\n      AND NOT COALESCE(bsl.manually_unlinked, false)\n    ORDER BY bsl.transaction_date ASC\n  LOOP\n    v_candidate_count := 0;\n    v_matched_id := NULL;\n    v_matched_type := NULL;\n\n    IF v_line.debit_amount > 0 THEN\n      SELECT pv.id, 'payment_voucher' INTO v_pv\n      FROM public.payment_vouchers pv\n      WHERE pv.bank_account_id = v_line.bank_account_id\n        AND pv.is_posted = true\n        AND abs(COALESCE(pv.actual_bank_debit, pv.bank_amount, pv.amount + COALESCE(pv.bank_charge, 0)) - v_line.debit_amount) < 0.01\n        AND abs(pv.voucher_date - v_line.transaction_date) <= 5\n        AND pv.id NOT IN (\n          SELECT matched_payment_id FROM public.bank_statement_lines\n          WHERE matched_payment_id IS NOT NULL AND id <> v_line.id\n        )\n      ORDER BY abs(pv.voucher_date - v_line.transaction_date) ASC\n      LIMIT 2;\n\n      IF FOUND THEN\n        v_candidate_count := v_candidate_count + 1;\n        v_matched_id := v_pv.id;\n        v_matched_type := 'payment';\n      END IF;\n\n      SELECT fe.id, 'expense' INTO v_exp\n      FROM public.finance_expenses fe\n      WHERE fe.bank_account_id = v_line.bank_account_id\n        AND fe.status = 'approved'\n        AND abs(fe.amount - v_line.debit_amount) < 0.01\n        AND abs(fe.expense_date - v_line.transaction_date) <= 5\n        AND fe.id NOT IN (\n          SELECT matched_expense_id FROM public.bank_statement_lines\n          WHERE matched_expense_id IS NOT NULL AND id <> v_line.id\n        )\n      ORDER BY abs(fe.expense_date - v_line.transaction_date) ASC\n      LIMIT 2;\n\n      IF FOUND THEN\n        v_candidate_count := v_candidate_count + 1;\n        IF v_matched_id IS NULL THEN\n          v_matched_id := v_exp.id;\n          v_matched_type := 'expense';\n        END IF;\n      END IF;\n\n      SELECT ft.id, 'fund_transfer' INTO v_ft\n      FROM public.fund_transfers ft\n      WHERE ft.from_bank_account_id = v_line.bank_account_id\n        AND ft.status = 'posted'\n        AND abs(COALESCE(ft.from_amount, ft.amount) - v_line.debit_amount) < 0.01\n        AND abs(ft.transfer_date - v_line.transaction_date) <= 5\n        AND ft.id NOT IN (\n          SELECT matched_fund_transfer_id FROM public.bank_statement_lines\n          WHERE matched_fund_transfer_id IS NOT NULL AND id <> v_line.id\n        )\n      ORDER BY abs(ft.transfer_date - v_line.transaction_date) ASC\n      LIMIT 2;\n\n      IF FOUND THEN\n        v_candidate_count := v_candidate_count + 1;\n        IF v_matched_id IS NULL THEN\n          v_matched_id := v_ft.id;\n          v_matched_type := 'fund_transfer';\n        END IF;\n      END IF;\n\n      SELECT tp.id, 'tax_payment' INTO v_tax\n      FROM public.tax_payments tp\n      WHERE tp.bank_account_id = v_line.bank_account_id\n        AND abs(tp.amount - v_line.debit_amount) < 0.01\n        AND abs(tp.payment_date - v_line.transaction_date) <= 5\n        AND tp.id NOT IN (\n          SELECT matched_tax_payment_id FROM public.bank_statement_lines\n          WHERE matched_tax_payment_id IS NOT NULL AND id <> v_line.id\n        )\n      ORDER BY abs(tp.payment_date - v_line.transaction_date) ASC\n      LIMIT 2;\n\n      IF FOUND THEN\n        v_candidate_count := v_candidate_count + 1;\n        IF v_matched_id IS NULL THEN\n          v_matched_id := v_tax.id;\n          v_matched_type := 'tax_payment';\n        END IF;\n      END IF;\n\n    ELSIF v_line.credit_amount > 0 THEN\n      SELECT rv.id, 'receipt_voucher' INTO v_rv\n      FROM public.receipt_vouchers rv\n      WHERE rv.bank_account_id = v_line.bank_account_id\n        AND rv.is_posted = true\n        AND abs(rv.amount - v_line.credit_amount) < 0.01\n        AND abs(rv.receipt_date - v_line.transaction_date) <= 5\n        AND rv.id NOT IN (\n          SELECT matched_receipt_id FROM public.bank_statement_lines\n          WHERE matched_receipt_id IS NOT NULL AND id <> v_line.id\n        )\n      ORDER BY abs(rv.receipt_date - v_line.transaction_date) ASC\n      LIMIT 2;\n\n      IF FOUND THEN\n        v_candidate_count := v_candidate_count + 1;\n        v_matched_id := v_rv.id;\n        v_matched_type := 'receipt';\n      END IF;\n\n      SELECT ft.id, 'fund_transfer' INTO v_ft\n      FROM public.fund_transfers ft\n      WHERE ft.to_bank_account_id = v_line.bank_account_id\n        AND ft.status = 'posted'\n        AND abs(COALESCE(ft.to_amount, ft.amount) - v_line.credit_amount) < 0.01\n        AND abs(ft.transfer_date - v_line.transaction_date) <= 5\n        AND ft.id NOT IN (\n          SELECT matched_fund_transfer_id FROM public.bank_statement_lines\n          WHERE matched_fund_transfer_id IS NOT NULL AND id <> v_line.id\n        )\n      ORDER BY abs(ft.transfer_date - v_line.transaction_date) ASC\n      LIMIT 2;\n\n      IF FOUND THEN\n        v_candidate_count := v_candidate_count + 1;\n        IF v_matched_id IS NULL THEN\n          v_matched_id := v_ft.id;\n          v_matched_type := 'fund_transfer';\n        END IF;\n      END IF;\n    END IF;\n\n    IF v_candidate_count = 1 AND v_matched_id IS NOT NULL THEN\n      UPDATE public.bank_statement_lines\n      SET matching_status = 'confirmed',\n          reconciliation_status = 'reconciled',\n          matched_payment_id = CASE WHEN v_matched_type = 'payment' THEN v_matched_id ELSE matched_payment_id END,\n          matched_receipt_id = CASE WHEN v_matched_type = 'receipt' THEN v_matched_id ELSE matched_receipt_id END,\n          matched_expense_id = CASE WHEN v_matched_type = 'expense' THEN v_matched_id ELSE matched_expense_id END,\n          matched_fund_transfer_id = CASE WHEN v_matched_type = 'fund_transfer' THEN v_matched_id ELSE matched_fund_transfer_id END,\n          matched_tax_payment_id = CASE WHEN v_matched_type = 'tax_payment' THEN v_matched_id ELSE matched_tax_payment_id END,\n          matched_at = now(),\n          notes = 'Auto-reconciled against posted ' || v_matched_type\n      WHERE id = v_line.id;\n      v_matched_count := v_matched_count + 1;\n\n    ELSIF v_candidate_count > 1 THEN\n      UPDATE public.bank_statement_lines\n      SET matching_status = 'suggested',\n          reconciliation_status = 'conflict',\n          notes = 'Multiple potential accounting documents match this transaction (' || v_candidate_count || ' candidates) - manual review required'\n      WHERE id = v_line.id;\n      v_conflict_count := v_conflict_count + 1;\n    END IF;\n  END LOOP;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'auto_matched_count', v_matched_count,\n    'conflict_review_count', v_conflict_count\n  );\nEND;\n$function$;\n\nREVOKE ALL ON FUNCTION public.run_fx_month_end_revaluation(date, numeric, text, uuid) FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.run_fx_month_end_revaluation(date, numeric, text, uuid) FROM anon;\nGRANT EXECUTE ON FUNCTION public.run_fx_month_end_revaluation(date, numeric, text, uuid) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.run_fx_month_end_revaluation(date, numeric, text, uuid) TO service_role;\n\nREVOKE ALL ON FUNCTION public.auto_reconcile_bank_statement(uuid) FROM PUBLIC;\nREVOKE ALL ON FUNCTION public.auto_reconcile_bank_statement(uuid) FROM anon;\nGRANT EXECUTE ON FUNCTION public.auto_reconcile_bank_statement(uuid) TO authenticated;\nGRANT EXECUTE ON FUNCTION public.auto_reconcile_bank_statement(uuid) TO service_role;\n"}	secure_dynamic_fx_and_bank_reconciliation_rpcs	simplykool@gmail.com	\N	\N
