20261105031234	{"\nDO $repair$\nDECLARE\n  v_definition text;\n  v_column_occurrences integer;\n  v_value_occurrences integer;\nBEGIN\n  SELECT pg_get_functiondef('public.post_payment_voucher(uuid,uuid)'::regprocedure)\n    INTO v_definition;\n\n  v_column_occurrences :=\n    (length(v_definition) - length(replace(v_definition,\n      'supplier_id, customer_id, payee_id', '')))\n    / length('supplier_id, customer_id, payee_id');\n\n  v_value_occurrences :=\n    (length(v_definition) - length(replace(v_definition,\n      'v_pv.supplier_id, v_pv.customer_id, v_pv.staff_id', '')))\n    / length('v_pv.supplier_id, v_pv.customer_id, v_pv.staff_id');\n\n  IF v_column_occurrences <> 6 OR v_value_occurrences <> 6 THEN\n    RAISE EXCEPTION\n      'Safety stop: expected 6 payment voucher payee mappings, found columns %, values %',\n      v_column_occurrences, v_value_occurrences;\n  END IF;\n\n  v_definition := replace(\n    v_definition,\n    'supplier_id, customer_id, payee_id',\n    'supplier_id, customer_id'\n  );\n\n  v_definition := replace(\n    v_definition,\n    'v_pv.supplier_id, v_pv.customer_id, v_pv.staff_id',\n    'v_pv.supplier_id, v_pv.customer_id'\n  );\n\n  EXECUTE v_definition;\nEND\n$repair$;\n"}	fix_payment_voucher_staff_id_payee_fk	simplykool@gmail.com	\N	\N
